package com.gachaman.overlay;

import com.gachaman.*;
import org.junit.*;

/**
 * The chest intro's three-stage strain schedule — pure timing math, no client,
 * no Graphics2D. Every case loops {@link Tuning.Chest#values()} rather than
 * naming tiers, so a fifth tier added later is held to the same invariants.
 */
public class ChestStrainTest
{
	/** Mirrors ChestStrain's private KICK_MS; kept private there because only the curve is public. */
	private static final long KICK_MS = 180;

	/**
	 * Closest two groans may ever land. Comfortably wider than both the 180ms
	 * kick and the 420ms groan clip, so neither the shudder nor the audio can
	 * stack on itself.
	 */
	private static final long MIN_BEAT_GAP_MS = 500;

	@Test
	public void totalsAreUnchanged()
	{
		// The pitch for this feature asked for a 2800ms top-tier intro. Applying
		// it would end Gilded's intro 400ms BEFORE its lid opens at el=3200, so
		// the ceremony would cut to the deal over a still-shut chest. These four
		// numbers are the ones the ceremony is tuned against; they do not move.
		Assert.assertEquals(1400, ChestStrain.totalMs(Tuning.Chest.RUSTY));
		Assert.assertEquals(2000, ChestStrain.totalMs(Tuning.Chest.BATTERED));
		Assert.assertEquals(4000, ChestStrain.totalMs(Tuning.Chest.GILDED));
		Assert.assertEquals(7000, ChestStrain.totalMs(Tuning.Chest.ORNATE));
	}

	@Test
	public void giveAlwaysLandsInsideTheIntro()
	{
		for (Tuning.Chest tier : Tuning.Chest.values())
		{
			long shudder = ChestStrain.shudderMs(tier);
			long give = ChestStrain.giveMs(tier);
			Assert.assertTrue(tier + " shudders before it gives", shudder < give);
			Assert.assertTrue(tier + " gives before the intro ends", give < ChestStrain.totalMs(tier));
			Assert.assertTrue(tier + " leaves room for the stillness",
				give - shudder > ChestStrain.HELD_STILL_MS);
		}
	}

	@Test
	public void loadIsMonotoneAndClamped()
	{
		for (Tuning.Chest tier : Tuning.Chest.values())
		{
			double previous = -1;
			for (long el = -500; el <= ChestStrain.totalMs(tier) + 500; el += 10)
			{
				double load = ChestStrain.load(el, tier);
				Assert.assertTrue(tier + " load in range at " + el, load >= 0 && load <= 1);
				Assert.assertTrue(tier + " load never falls back at " + el, load >= previous);
				previous = load;
			}
			Assert.assertEquals(tier + " starts unloaded",
				0.0, ChestStrain.load(ChestStrain.shudderMs(tier), tier), 1e-9);
			Assert.assertEquals(tier + " is fully loaded when it gives",
				1.0, ChestStrain.load(ChestStrain.giveMs(tier), tier), 1e-9);
		}
	}

	@Test
	public void strainingBracketsExactly()
	{
		for (Tuning.Chest tier : Tuning.Chest.values())
		{
			long shudder = ChestStrain.shudderMs(tier);
			long still = ChestStrain.giveMs(tier) - ChestStrain.HELD_STILL_MS;
			// Boundary exactness at shudderMs is why the draw code gates on
			// straining() and not on load() > 0: the load is exactly 0 here, so
			// a > 0 gate would silently drop the first frame of movement.
			Assert.assertFalse(tier + " is calm before the shudder", ChestStrain.straining(shudder - 1, tier));
			Assert.assertTrue(tier + " moves on the shudder", ChestStrain.straining(shudder, tier));
			Assert.assertTrue(tier + " still moves a frame before the hush",
				ChestStrain.straining(still - 1, tier));
			Assert.assertFalse(tier + " is hushed on the mark", ChestStrain.straining(still, tier));
			Assert.assertFalse(tier + " is hushed when it gives",
				ChestStrain.straining(ChestStrain.giveMs(tier), tier));
		}
	}

	@Test
	public void theLockGoesStillBeforeItGives()
	{
		// The payoff beat. Motion that merely continues reads as noise; motion
		// that stops dead reads as a lock about to lose.
		for (Tuning.Chest tier : Tuning.Chest.values())
		{
			long give = ChestStrain.giveMs(tier);
			for (long el = give - ChestStrain.HELD_STILL_MS; el <= give; el++)
			{
				Assert.assertFalse(tier + " must not twitch at " + el, ChestStrain.straining(el, tier));
			}
		}
	}

	@Test
	public void rustyStaysMuted()
	{
		// The starter box's ceremony is deliberately cheap and undramatic. The
		// tell only works if the bottom of the ladder stays conspicuously quiet,
		// so Rusty gets no groans at all — its lack of a fight IS its tell.
		Assert.assertEquals(0, ChestStrain.beats(Tuning.Chest.RUSTY).length);
		Assert.assertEquals(300, ChestStrain.shudderMs(Tuning.Chest.RUSTY));
		Assert.assertEquals(900, ChestStrain.giveMs(Tuning.Chest.RUSTY));
		Assert.assertEquals(1400, ChestStrain.totalMs(Tuning.Chest.RUSTY));
	}

	@Test
	public void beatsAreOrderedAndInsideTheStrain()
	{
		for (Tuning.Chest tier : Tuning.Chest.values())
		{
			long[] beats = ChestStrain.beats(tier);
			// The schedule was authored against a four-step pitch ladder — one
			// whole tone of metal-under-load per beat — and a fifth beat has no
			// step of its own: it clamps to the top of the ladder and repeats
			// the fourth. Four ASCENDING groans are the tell; a fifth that
			// merely repeats the last one is noise that says nothing new.
			Assert.assertTrue(tier + " has at most four beats", beats.length <= 4);
			for (int k = 0; k < beats.length; k++)
			{
				if (k > 0)
				{
					Assert.assertTrue(tier + " beats ascend", beats[k] > beats[k - 1]);
					Assert.assertTrue(tier + " beat " + k + " must not crowd its predecessor",
						beats[k] - beats[k - 1] >= MIN_BEAT_GAP_MS);
				}
				Assert.assertTrue(tier + " beat " + k + " waits for the shudder",
					beats[k] >= ChestStrain.shudderMs(tier));
				// A groan struck during the hush would be audio with no motion.
				Assert.assertTrue(tier + " beat " + k + " lands before the hush",
					beats[k] <= ChestStrain.giveMs(tier) - ChestStrain.HELD_STILL_MS);
			}
		}
	}

	@Test
	public void kickDecaysAndNeverExceedsOne()
	{
		for (Tuning.Chest tier : Tuning.Chest.values())
		{
			long[] beats = ChestStrain.beats(tier);
			if (beats.length > 0)
			{
				Assert.assertEquals(tier + " is unkicked before its first beat",
					0.0, ChestStrain.kick(beats[0] - 1, tier), 1e-9);
			}
			for (long beat : beats)
			{
				Assert.assertEquals(tier + " kicks hardest on the beat",
					1.0, ChestStrain.kick(beat, tier), 1e-9);
				double previous = Double.MAX_VALUE;
				for (long d = 0; d < KICK_MS; d++)
				{
					double kick = ChestStrain.kick(beat + d, tier);
					Assert.assertTrue(tier + " kick decays at +" + d, kick < previous);
					previous = kick;
				}
				Assert.assertEquals(tier + " kick is spent at +" + KICK_MS,
					0.0, ChestStrain.kick(beat + KICK_MS, tier), 1e-9);
			}
			// The amplitude formulas add 3-4px per unit of kick, so an
			// out-of-range value would fling the chest off screen — and a kick
			// with no groan under it is a jolt from nowhere, so any nonzero
			// value has to sit inside some beat's window.
			for (long el = 0; el <= ChestStrain.totalMs(tier); el++)
			{
				double kick = ChestStrain.kick(el, tier);
				Assert.assertTrue(tier + " kick in range at " + el, kick >= 0 && kick <= 1);
				Assert.assertEquals(tier + " kick at " + el + " must follow a beat",
					inBeatWindow(beats, el), kick > 0);
			}
		}
	}

	private static boolean inBeatWindow(long[] beats, long el)
	{
		for (long beat : beats)
		{
			if (el >= beat && el < beat + KICK_MS)
			{
				return true;
			}
		}
		return false;
	}
}

package com.gachaman.overlay;

import com.gachaman.*;
import java.awt.*;
import java.awt.image.*;
import java.io.*;
import javax.imageio.*;

/**
 * Pre-renders the WHOLE chest-opening ceremony to a frame sequence per tier:
 * body, lid, chains, padlock, strain, seam leak, glow, motes and all.
 *
 * <p>It can be one sequence because the ceremony is a pure function of
 * (tier, elapsed): the chest shake and the camera shake are applied by the
 * caller as translations, innerGlow is 0 throughout the intro, and both lidOpen
 * and leak are derived from el. Every frame is cropped to its own alpha bounds
 * and its offset recorded, so the empty space around a whipping chain or a
 * blasted lid costs nothing.
 *
 * <p>Test scope: never shipped, never counted. This is the authoring source.
 */
public final class CeremonyArt {
	private static final int W = 300;
	private static final int H = 225;
	/**
	 * Decoded-size ceiling per frame, in bytes.
	 *
	 * <p>The Plugin Hub rejects any image whose DECODED size — width * height * 4,
	 * not the compressed file — passes 1 MiB. On disk these frames are 60-70 KB,
	 * so nothing about the file sizes hints at the problem. Four ORNATE frames
	 * were over the line and a fifth sat 3% under it, which is why the cap is set
	 * below the limit rather than at it.
	 *
	 * <p>What makes those frames large is not detail but REACH: the chain and the
	 * broken padlock fall away from the chest, so the alpha bounding box stretches
	 * to cover a thin diagonal of chain and one small padlock across a mostly
	 * empty rectangle. The cheap-looking alternative — clamping how far the debris
	 * may travel — would visibly cut the fall short, and packing the pieces into
	 * separate sub-images would cost player code the token budget cannot spare.
	 *
	 * <p>So resolution is what gets traded, worst case 0.82 linear on ORNATE 38.
	 * That frame's chain links and padlock were compared against the procedural
	 * source at 1:1 (CeremonyFitCmp) and are indistinguishable; the measurable
	 * delta sits on 1px trim edges and reaches the eye as nothing.
	 */
	private static final long MAX_DECODED = 900_000L;

	/** Generous working canvas; every frame is cropped out of it. */
	private static final int CW = 1100;
	private static final int CH = 1000;
	static final int FPS = 20;

	private static double clamp01(double v) {
		return v <= 0 ? 0 : (v >= 1 ? 1 : v);
	}

	private static double smoothstep(double t) {
		t = clamp01(t);
		return t * t * (3 - 2 * t);
	}

	/** Last millisecond worth rendering for a tier. */
	static int durationMs(Tuning.Chest tier) {
		switch (tier) {
			case RUSTY: return 1600;
			case BATTERED: return 2150;
			case GILDED: return 4050;
			default: return 7100;
		}
	}

	static double lidOpen(Tuning.Chest tier, long el) {
		switch (tier) {
			case RUSTY: return el >= 900 ? smoothstep(clamp01((el - 900) / 350.0)) : 0;
			case BATTERED: return el >= 1400 ? smoothstep(clamp01((el - 1400) / 400.0)) : 0;
			case GILDED: return el >= 3200 ? smoothstep(clamp01((el - 3200) / 500.0)) : 0;
			default: return el >= 6400 ? smoothstep(clamp01((el - 6400) / 350.0)) * 1.35 : 0;
		}
	}

	static float leak(Tuning.Chest tier, long el) {
		if (tier != Tuning.Chest.ORNATE) {
			return 0f;
		}
		return el >= 4000 && el < 6400 ? (float) clamp01((el - 4000) / 2400.0) : 0f;
	}

	static Color trim(Tuning.Chest tier) {
		switch (tier) {
			case RUSTY: return new Color(122, 82, 46);
			case BATTERED: return new Color(139, 98, 46);
			case GILDED: return new Color(198, 202, 212);
			default: return new Color(230, 190, 80);
		}
	}

	public static void main(String[] a) throws Exception {
		File dir = new File(a[0]);
		dir.mkdirs();
		StringBuilder idx = new StringBuilder("{\n  \"fps\": ").append(FPS).append(",\n  \"tiers\": {\n");
		long totalBytes = 0;
		long peakPixels = 0;
		long peakDecoded = 0;
		int shrunk = 0;
		for (Tuning.Chest tier : Tuning.Chest.values()) {
			String name = tier.name().toLowerCase();
			int step = 1000 / FPS;
			int n = 0;
			StringBuilder frames = new StringBuilder();
			long tierPixels = 0;
			for (long el = 0; el <= durationMs(tier); el += step) {
				BufferedImage img = new BufferedImage(CW, CH, BufferedImage.TYPE_INT_ARGB);
				Graphics2D g = img.createGraphics();
				g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
				int cx = CW / 2;
				int cy = CH / 2;
				ChestPainter.draw(g, cx, cy, W, H, lidOpen(tier, el), tier, trim(tier), 0f,
					leak(tier, el), el);
				if (tier == Tuning.Chest.GILDED) {
					ChestPainter.drawPadlock(g, cx, cy + H / 8, W, el, ChestStrain.giveMs(tier));
				}
				else if (tier == Tuning.Chest.ORNATE) {
					ChestPainter.drawChains(g, cx, cy, W, H, el, 1200, 1400);
				}
				g.dispose();

				int[] bb = bounds(img);
				BufferedImage crop = img.getSubimage(bb[0], bb[1], bb[2] - bb[0], bb[3] - bb[1]);
				// authored size: what the frame is DRAWN at, whatever it is stored at
				int aw = crop.getWidth();
				int ah = crop.getHeight();
				BufferedImage out = crop;
				if ((long) aw * ah * 4 > MAX_DECODED) {
					double k = Math.sqrt(MAX_DECODED / (double) ((long) aw * ah * 4));
					int sw = Math.max(1, (int) Math.floor(aw * k));
					int sh = Math.max(1, (int) Math.floor(ah * k));
					out = new BufferedImage(sw, sh, BufferedImage.TYPE_INT_ARGB);
					Graphics2D sg = out.createGraphics();
					sg.setRenderingHint(RenderingHints.KEY_INTERPOLATION,
						RenderingHints.VALUE_INTERPOLATION_BILINEAR);
					sg.setRenderingHint(RenderingHints.KEY_RENDERING,
						RenderingHints.VALUE_RENDER_QUALITY);
					sg.drawImage(crop, 0, 0, sw, sh, null);
					sg.dispose();
					shrunk++;
				}
				File f = new File(dir, String.format("chest-%s-%03d.png", name, n));
				ImageIO.write(out, "png", f);
				totalBytes += f.length();
				tierPixels += (long) out.getWidth() * out.getHeight();
				peakDecoded = Math.max(peakDecoded, (long) out.getWidth() * out.getHeight() * 4);
				frames.append(n == 0 ? "" : ", ")
					.append("[").append(bb[0] - cx).append(",").append(bb[1] - cy)
					.append(",").append(aw).append(",").append(ah).append("]");
				n++;
			}
			peakPixels = Math.max(peakPixels, tierPixels);
			idx.append("    \"").append(name).append("\": [").append(frames).append("]")
				.append(tier == Tuning.Chest.ORNATE ? "\n" : ",\n");
			System.out.printf("%-9s %3d frames%n", name, n);
		}
		idx.append("  }\n}\n");
		try (FileWriter w = new FileWriter(new File(dir, "chest-ceremony.json"))) {
			w.write(idx.toString());
		}
		System.out.printf("on disk: %.2f MB%n", totalBytes / 1048576.0);
		System.out.printf("largest tier decoded (ARGB): %.1f MB%n", peakPixels * 4 / 1048576.0);
		System.out.printf("largest SINGLE frame decoded: %,d bytes (Plugin Hub limit 1,048,576)%n",
			peakDecoded);
		System.out.printf("frames downscaled to fit: %d%n", shrunk);
		if (peakDecoded > 1048576L) {
			throw new IllegalStateException("a frame is still over the Plugin Hub image limit");
		}
	}

	/** Tight alpha bounds, or the whole canvas if the frame is empty. */
	private static int[] bounds(BufferedImage img) {
		int minX = img.getWidth();
		int minY = img.getHeight();
		int maxX = 0;
		int maxY = 0;
		for (int y = 0; y < img.getHeight(); y++) {
			for (int x = 0; x < img.getWidth(); x++) {
				if ((img.getRGB(x, y) >>> 24) != 0) {
					if (x < minX) { minX = x; }
					if (y < minY) { minY = y; }
					if (x > maxX) { maxX = x; }
					if (y > maxY) { maxY = y; }
				}
			}
		}
		if (minX > maxX) {
			return new int[]{0, 0, 1, 1};
		}
		return new int[]{minX, minY, maxX + 1, maxY + 1};
	}

	private CeremonyArt() {
	}
}

package com.gachaman.overlay;

import java.awt.*;
import org.junit.*;

/**
 * The ornate chest's chains are clipped to the chest's own silhouette - that
 * clip is what makes their ends pass BEHIND the box instead of hanging in the
 * air beside it. Which means the silhouette and the chain path are now two
 * readers of the same layout fractions, and nothing in the painter would notice
 * if they drifted apart: a run that leaves the silhouette is not a bug you see
 * as a misplaced chain, it is a bug you see as no chain at all.
 *
 * <p>Swept over every chest size that ships. chestW is min(300, cw/3) and
 * chestH is three quarters of that, so the range below covers a very narrow
 * client through to the clamp.
 */
public class ChestPainterChainTest
{
	private static final int[] DIRS = {1, -1};

	/** Chain position at t along the straight run, before bow and sway. */
	private static double[] at(double[] ends, double t)
	{
		return new double[]{ends[0] + (ends[2] - ends[0]) * t, ends[1] + (ends[3] - ends[1]) * t};
	}

	/**
	 * Every part of the run the player is meant to see lands on the chest. The
	 * ends are sampled just inside t=0 and t=1 rather than exactly on them,
	 * because those points sit on the silhouette's own boundary where
	 * {@code contains} is entitled to answer either way.
	 */
	@Test
	public void theWholeVisibleRunOfEveryChainLandsOnTheChest()
	{
		for (int w = 60; w <= 300; w += 4)
		{
			int h = w * 3 / 4;
			Shape box = ChestPainter.closedSilhouette(0, 0, w, h);
			for (int dir : DIRS)
			{
				double[] ends = ChestPainter.chainEnds(0, 0, w, h, dir);
				for (double t = 0.02; t <= 0.98; t += 0.02)
				{
					double[] p = at(ends, t);
					Assert.assertTrue("chain " + dir + " leaves the chest at t=" + t
						+ " on a " + w + "x" + h + " chest", box.contains(p[0], p[1]));
				}
			}
		}
	}

	/**
	 * And the length past those ends does NOT, or the chain would simply stop at
	 * the edge with a visible last link - which is the thing that reads as an X
	 * painted on the picture rather than as a band going around a box. The
	 * painter runs 15% past each end and leans on the clip to cut it.
	 */
	@Test
	public void theLengthPastEachEndIsHiddenBehindTheChest()
	{
		for (int w = 60; w <= 300; w += 4)
		{
			int h = w * 3 / 4;
			Shape box = ChestPainter.closedSilhouette(0, 0, w, h);
			for (int dir : DIRS)
			{
				double[] ends = ChestPainter.chainEnds(0, 0, w, h, dir);
				for (double t : new double[]{-0.15, -0.08, 1.08, 1.15})
				{
					double[] p = at(ends, t);
					Assert.assertFalse("the run past t=" + t + " is still on the chest at "
						+ w + "x" + h, box.contains(p[0], p[1]));
				}
			}
		}
	}

	/**
	 * A chain that never reaches the lid is not holding anything shut. Both
	 * chains have to start inside the lid skirt and finish on the body, so the
	 * lid seam is crossed on the way and the whip-away has something to release.
	 */
	@Test
	public void everyChainCrossesTheLidSeam()
	{
		for (int w = 60; w <= 300; w += 4)
		{
			int h = w * 3 / 4;
			double skirtTop = -h / 2.0 + h * 0.16;
			double seam = skirtTop + h * 0.30;
			double bottom = h / 2.0;
			for (int dir : DIRS)
			{
				double[] ends = ChestPainter.chainEnds(0, 0, w, h, dir);
				Assert.assertTrue("chain " + dir + " starts above the lid at " + w,
					ends[1] > skirtTop);
				Assert.assertTrue("chain " + dir + " starts below the lid seam at " + w,
					ends[1] < seam);
				Assert.assertTrue("chain " + dir + " ends above the lid seam at " + w,
					ends[3] > seam);
				Assert.assertTrue("chain " + dir + " ends below the chest at " + w,
					ends[3] < bottom);
			}
		}
	}

	/**
	 * The OUTER chain comes off first. Chain 1 is painted second, so it lies
	 * over chain 0 where they cross, so it is the outer one and the only one
	 * whose padlock can actually be reached. Releasing the inner chain first
	 * has it slide out from under a chain still pinning it down - wrong in a way
	 * everybody sees and nobody can name, which is exactly the kind of thing
	 * that gets quietly reintroduced by a loop that runs k = 0 then 1.
	 */
	@Test
	public void theOuterChainIsUnlockedFirst()
	{
		long outer = ChestPainter.lockBreakMs(1, 1200, 1400);
		long inner = ChestPainter.lockBreakMs(0, 1200, 1400);
		Assert.assertEquals("the first lock should break at firstBreakMs", 1200, outer);
		Assert.assertEquals("the second should follow one gap later", 2600, inner);
		Assert.assertTrue("the inner chain came off before the outer one", outer < inner);
	}

	/** The two chains cross, or there is no X and nothing to whip off in turn. */
	@Test
	public void theTwoChainsCross()
	{
		for (int w = 60; w <= 300; w += 4)
		{
			int h = w * 3 / 4;
			double[] a = ChestPainter.chainEnds(0, 0, w, h, 1);
			double[] b = ChestPainter.chainEnds(0, 0, w, h, -1);
			Assert.assertTrue("the chains run parallel at " + w,
				java.awt.geom.Line2D.linesIntersect(a[0], a[1], a[2], a[3],
					b[0], b[1], b[2], b[3]));
		}
	}
}

package com.gachaman.overlay;

import java.awt.*;
import java.awt.geom.*;
import java.awt.image.*;
import java.io.*;
import javax.imageio.*;

/** Procedural roller vs the 9-sliced one, across tints and scroll widths. */
public final class RollerCmp {
	private static final Color WOOD_LIGHT = new Color(168, 128, 76);
	private static final Color WOOD_DARK = new Color(70, 48, 24);
	private static final Color CAP_EDGE = new Color(34, 24, 12, 200);
	private static final Color GRAIN = new Color(52, 34, 14, 55);

	private static Color mix(Color a, Color b, float t) {
		return new Color((int) (a.getRed() + (b.getRed() - a.getRed()) * t),
			(int) (a.getGreen() + (b.getGreen() - a.getGreen()) * t),
			(int) (a.getBlue() + (b.getBlue() - a.getBlue()) * t));
	}

	public static void main(String[] a) throws Exception {
		File dir = new File(a[0]);
		dir.mkdirs();
		int n = 0;
		for (Color tier : RollerArt.TINTS) {
			for (int width : new int[]{200, 260, 320}) {
				Rectangle r = new Rectangle(20, 20, width, 120);
				int cy = 40;
				BufferedImage proc = new BufferedImage(width + 60, 90, BufferedImage.TYPE_INT_ARGB);
				Graphics2D g = proc.createGraphics();
				g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
				old(g, r, cy, mix(WOOD_LIGHT, tier, 0.45f), mix(WOOD_DARK, tier, 0.30f), 0.3);
				g.dispose();
				ImageIO.write(proc, "png", new File(dir, RollerArt.key(tier) + "_" + width + "_proc.png"));

				BufferedImage spr = new BufferedImage(width + 60, 90, BufferedImage.TYPE_INT_ARGB);
				g = spr.createGraphics();
				g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
				ScrollPainter.drawRoller(g, r, cy, tier, 0.3);
				g.dispose();
				ImageIO.write(spr, "png", new File(dir, RollerArt.key(tier) + "_" + width + "_spr.png"));
				n++;
			}
		}
		System.out.println("compared " + n + " rollers");
	}

	/** The roller exactly as ScrollPainter drew it before the 9-slice. */
	private static void old(Graphics2D g, Rectangle r, int cy, Color hi, Color lo, double spin) {
		int H = 18;
		int CAP_W = 7;
		int y = cy - H / 2;
		int bodyX = r.x + CAP_W - 2;
		int bodyW = r.width - (CAP_W - 2) * 2;
		java.awt.Shape clip = g.getClip();
		RoundRectangle2D body = new RoundRectangle2D.Float(bodyX, y, bodyW, H, H, H);
		g.setPaint(new LinearGradientPaint(new Point2D.Float(0, y), new Point2D.Float(0, y + H),
			new float[]{0f, 0.28f, 0.5f, 0.82f, 1f},
			new Color[]{mix(lo, Color.BLACK, 0.35f), mix(hi, Color.WHITE, 0.55f), hi,
				mix(lo, Color.BLACK, 0.15f), mix(lo, hi, 0.45f)}));
		g.fill(body);
		g.clip(body);
		g.setColor(GRAIN);
		for (int k = 0; k < 3; k++) {
			double phase = (((spin + k / 3.0) % 1.0) + 1.0) % 1.0;
			int gy = y + 2 + (int) Math.round(phase * (H - 4));
			g.drawLine(bodyX + 3, gy, bodyX + bodyW - 3, gy);
		}
		g.setClip(clip);
		cap(g, r.x, y - 2, hi, lo);
		cap(g, r.x + r.width - CAP_W, y - 2, hi, lo);
	}

	private static void cap(Graphics2D g, int x, int y, Color hi, Color lo) {
		int h = 22;
		g.setPaint(new java.awt.RadialGradientPaint(new Point2D.Float(x + 7 * 0.35f, y + h * 0.32f),
			Math.max(1f, h * 0.75f), new float[]{0f, 1f},
			new Color[]{mix(hi, Color.WHITE, 0.35f), mix(lo, Color.BLACK, 0.25f)}));
		g.fillOval(x, y, 7, h);
		g.setColor(CAP_EDGE);
		g.drawOval(x, y, 6, h - 1);
	}

	private RollerCmp() {
	}
}

package com.gachaman.overlay;

import java.awt.Point;
import com.gachaman.*;
import com.gachaman.model.*;
import com.gachaman.service.*;
import com.google.gson.*;
import java.awt.*;
import java.awt.image.*;
import java.lang.reflect.*;
import java.util.*;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.callback.*;
import org.junit.*;

/**
 * The Consignment's offer ceremony, end to end through the real overlay.
 *
 * <p>Everything here exists because the offer is the one request on the
 * CeremonyBus that TAKES something. Every other ceremony is a reward already
 * banked: drop a fanfare and a banner is missed, abort a chest reveal and the
 * cards are still committed. Drop THIS one and the player is left with a style
 * roll owed, a day key in an ambiguous state, and no question on screen to
 * answer — so the four ways it can leave the screen (a click, Escape, an abort,
 * a teardown) each have to reach ConsignmentService, and each has to reach it
 * with the RIGHT one of accept / decline / abandon. Those three are not
 * interchangeable: two of them spend the day and one deliberately does not.
 *
 * <p>The overlay is driven exactly as the client drives it — a Client proxy
 * answering the four calls it makes, the real {@link CeremonyBus}, and a
 * ConsignmentService subclass that records which answer arrived. Nothing is
 * stubbed between the click and the service.
 *
 * <p>Explicit {@code java.awt.Point} import: {@code handleClick} takes the AWT
 * one, and {@code net.runelite.api} exports a Point of its own — the same
 * collision RevealOverlay itself resolves at the top of the file.
 */
public class ConsignmentCeremonyTest
{
	/** The fixed-mode canvas, which is the smallest one a real client ever has. */
	private static final int W = 765;
	private static final int H = 503;
	/** Any tick; the assertion is that this exact number reaches the service. */
	private static final int TICK = 4271;

	/**
	 * Records which answer arrived, and nothing else.
	 *
	 * <p>A subclass rather than an interface stub because {@code Presenter} is the
	 * seam pointing the other way — the overlay holds the concrete service, so the
	 * only way to watch what it says to it is to be that service.
	 */
	private static class Spy extends ConsignmentService
	{
		int accepts;
		int declines;
		int abandons;
		int lastTick = -1;

		Spy()
		{
			super(null, null, null, null, null);
		}

		@Override
		public boolean accept(int currentTick)
		{
			accepts++;
			lastTick = currentTick;
			return true;
		}

		@Override
		public boolean decline(int currentTick)
		{
			declines++;
			lastTick = currentTick;
			return true;
		}

		@Override
		public void abandon()
		{
			abandons++;
		}

		int answered()
		{
			return accepts + declines;
		}
	}

	/**
	 * A ClientThread that runs the job INLINE, on the caller's thread.
	 *
	 * <p>Every assertion below reads the spy on the line after the click, so a
	 * stub that queued the job would turn each of them green by never running the
	 * code under test. Inline keeps the real path — click, hop, service — intact
	 * and merely collapses the hop to a call.
	 *
	 * <p>{@code invoke(Runnable)} is the overload to override, not
	 * {@code invokeLater}: the overlay calls invoke(), and the real one asks its
	 * injected {@code client} field whether we are already on the client thread —
	 * a field no hand-built ClientThread has, so falling through to super would
	 * NPE rather than defer. (ShopOddsRequestTest's stub next door overrides
	 * invokeLater for the same reason in reverse: that is what ShopTab calls.)
	 */
	private static final class InlineClientThread extends ClientThread
	{
		@Override
		public void invoke(Runnable job)
		{
			job.run();
		}
	}

	/**
	 * A ClientThread that QUEUES instead of running, the way the real one does
	 * when the caller is not already on the client thread.
	 *
	 * <p>This is the stub that can tell a hop from a direct call. An inline stub
	 * cannot: the service is reached either way, so an overlay that dropped the
	 * hop entirely would keep every other test in this file green.
	 */
	private static final class QueueingClientThread extends ClientThread
	{
		private final Deque<Runnable> jobs = new ArrayDeque<>();

		@Override
		public void invoke(Runnable job)
		{
			jobs.add(job);
		}

		int run()
		{
			int ran = 0;
			// drained by index rather than by iterator: a job may post another
			// one (applyDeedClaim's dismissal does exactly that), and the real
			// queue would run those too
			while (!jobs.isEmpty())
			{
				jobs.poll().run();
				ran++;
			}
			return ran;
		}
	}

	/**
	 * A Client that answers the four things the ceremony asks it and nothing
	 * else: the game state it claims ceremonies on, the canvas it lays out
	 * against, and the tick it stamps an answer with.
	 *
	 * <p>The game state is read out of the caller's own one-element array so a
	 * test can log in and out under a live overlay, which is the only way to
	 * exercise the parking rule.
	 */
	private static Client client(GameState[] state)
	{
		return (Client) Proxy.newProxyInstance(Client.class.getClassLoader(),
			new Class<?>[]{Client.class}, (proxy, method, args) ->
			{
				switch (method.getName())
				{
					case "getGameState":
						return state[0];
					case "getCanvasWidth":
						return W;
					case "getCanvasHeight":
						return H;
					case "getTickCount":
						return TICK;
					default:
						return blank(method.getReturnType());
				}
			});
	}

	/** Type-correct nothing, so an unexpected call cannot blow up the proxy. */
	private static Object blank(Class<?> type)
	{
		if (!type.isPrimitive() || type == void.class)
		{
			return null;
		}
		if (type == boolean.class)
		{
			return false;
		}
		if (type == long.class)
		{
			return 0L;
		}
		if (type == double.class)
		{
			return 0d;
		}
		if (type == float.class)
		{
			return 0f;
		}
		if (type == char.class)
		{
			return (char) 0;
		}
		if (type == byte.class)
		{
			return (byte) 0;
		}
		if (type == short.class)
		{
			return (short) 0;
		}
		return 0;
	}

	private static RevealOverlay overlay(CeremonyBus bus, ConsignmentService consignment)
	{
		return overlay(bus, consignment, new GameState[]{GameState.LOGGED_IN});
	}

	private static RevealOverlay overlay(CeremonyBus bus, ConsignmentService consignment,
		GameState[] state)
	{
		return overlay(bus, consignment, state, new InlineClientThread());
	}

	private static RevealOverlay overlay(CeremonyBus bus, ConsignmentService consignment,
		GameState[] state, ClientThread clientThread)
	{
		// ChestService is real but starved: handleClick and render both snapshot
		// the reroll tokens before touching the lock, and a null `pending` is the
		// state every non-chest ceremony is in anyway.
		ChestService chests = new ChestService(null, null, null, null, null, null, null, null, null);
		return new RevealOverlay(client(state), clientThread, bus, chests,
			null, null, null, null, null,
			new CeremonyPlayer(new Gson()), consignment);
	}

	private static ConsignmentService.Offer offer()
	{
		return new ConsignmentService.Offer(AttackStyle.MAGIC, 0, Tuning.Chest.GILDED);
	}

	/** Click the middle of answer {@code i}, exactly where the plate is drawn. */
	private static void clickAnswer(RevealOverlay overlay, int i)
	{
		Rectangle r = new Rectangle();
		RevealOverlay.consignRect(i, W, H, r);
		overlay.handleClick(new Point(r.x + r.width / 2, r.y + r.height / 2));
	}

	/** An overlay with the offer already on screen. */
	private static RevealOverlay showing(CeremonyBus bus, ConsignmentService consignment)
	{
		RevealOverlay overlay = overlay(bus, consignment);
		bus.addRenderer(overlay);
		Assert.assertTrue("the presenter must claim the offer", overlay.present(offer()));
		Assert.assertTrue("an unobstructed offer should be on screen", overlay.isModalActive());
		return overlay;
	}

	/**
	 * The presenter claims by ENQUEUEING, not by asking whether it is free.
	 *
	 * <p>This is the whole feature, and the way to lose it is to write the
	 * obvious presenter. {@code offerOrRoll} is called from a completed contract,
	 * by which point TASK_COMPLETE is already queued — and on every 10th, 25th,
	 * 45th... contract a DEED_CHOICE is too, because every deed milestone is a
	 * multiple of the style cycle. A presenter that answered "not now, a modal is
	 * up" would answer that essentially every time, the service would quietly take
	 * the ordinary roll, and the Consignment would never appear once. Nothing
	 * would log; the feature would simply not exist.
	 */
	@Test
	public void theOfferParksBehindTheDeedScreenAndPresentsWhenItClears()
	{
		CeremonyBus bus = new CeremonyBus();
		Spy consignment = new Spy();
		RevealOverlay overlay = overlay(bus, consignment);
		bus.addRenderer(overlay);

		bus.submit(CeremonyBus.Type.DEED_CHOICE, 0);
		Assert.assertTrue("the deed screen should have claimed the modal",
			overlay.isModalActive());

		Assert.assertTrue("an offer must be claimed even while a ceremony is up",
			overlay.present(offer()));
		Assert.assertEquals("claiming is not answering", 0, consignment.answered());

		// dismissing the deed drains the bus, which is where the parked offer
		// comes back — the same path every declined request takes
		overlay.handleEscape();
		Assert.assertTrue("the parked offer should be on screen now",
			overlay.isModalActive());

		// and it really is the offer, not a leftover deed screen: only the
		// Consignment answers a click on this rectangle
		clickAnswer(overlay, 0);
		Assert.assertEquals("the presented ceremony was not the offer", 1, consignment.accepts);
	}

	/**
	 * An offer raised while logged out waits for the login rather than being
	 * eaten by it.
	 *
	 * <p>Ceremonies are only ever drawn in game — one claimed at the login screen
	 * would sit invisible over "Click here to play" while its input listener ate
	 * every click — so the renderer refuses everything until LOGGED_IN. For most
	 * requests a refusal that went wrong would cost a banner. For this one it
	 * would cost the answer to a question, and the CeremonyBus has exactly two
	 * behaviours available to it: park the request, or hand it to a
	 * FallbackHandler that would have to answer a binding choice in chat. Nothing
	 * anywhere registers a fallback, so it parks — and that is the property this
	 * pins, because it is one {@code setFallback} call away from changing.
	 */
	@Test
	public void anOfferRaisedAtTheLoginScreenParksUntilTheGameIsIn()
	{
		CeremonyBus bus = new CeremonyBus();
		Spy consignment = new Spy();
		GameState[] state = {GameState.LOGIN_SCREEN};
		RevealOverlay overlay = overlay(bus, consignment, state);
		bus.addRenderer(overlay);

		Assert.assertTrue("the offer is claimed whatever the game state is",
			overlay.present(offer()));
		Assert.assertFalse("nothing may be drawn over the login screen",
			overlay.isModalActive());
		Assert.assertEquals("a parked offer must not answer itself", 0, consignment.answered());
		Assert.assertEquals(0, consignment.abandons);

		state[0] = GameState.LOGGED_IN;
		bus.drain(); // the plugin's own post-login drain
		Assert.assertTrue("the parked offer must present after login",
			overlay.isModalActive());
		clickAnswer(overlay, 0);
		Assert.assertEquals("the offer survived the logout intact", 1, consignment.accepts);
	}

	@Test
	public void takingTheDealAcceptsOnceAndReleasesTheScreen()
	{
		CeremonyBus bus = new CeremonyBus();
		Spy consignment = new Spy();
		RevealOverlay overlay = showing(bus, consignment);

		clickAnswer(overlay, 0);
		Assert.assertEquals(1, consignment.accepts);
		Assert.assertEquals(0, consignment.declines);
		Assert.assertEquals(0, consignment.abandons);
		// released before the answer is sent, so the roulette the answer causes
		// can claim the screen immediately and the crate can park behind it
		Assert.assertFalse("the modal must be released by the answer",
			overlay.isModalActive());
		Assert.assertEquals("the answer is stamped with the CURRENT tick",
			TICK, consignment.lastTick);
	}

	@Test
	public void spinningTheWheelDeclines()
	{
		CeremonyBus bus = new CeremonyBus();
		Spy consignment = new Spy();
		RevealOverlay overlay = showing(bus, consignment);

		clickAnswer(overlay, 1);
		Assert.assertEquals(1, consignment.declines);
		Assert.assertEquals(0, consignment.accepts);
		Assert.assertFalse(overlay.isModalActive());
	}

	/**
	 * Escape REFUSES; it does not dismiss.
	 *
	 * <p>The deed choice next door treats Escape as "not now" and re-queues,
	 * which costs nothing because the deed is still owed either way. An offer
	 * that behaved like that would be re-offerable at will — Escape, finish
	 * another contract, be asked again — and the once-per-day gate would be worth
	 * nothing. Refusing is an answer, and an answer spends the day.
	 */
	@Test
	public void escapeRefusesTheDealRatherThanDismissingIt()
	{
		CeremonyBus bus = new CeremonyBus();
		Spy consignment = new Spy();
		RevealOverlay overlay = showing(bus, consignment);

		overlay.handleEscape();
		Assert.assertEquals("Escape must decline, not abandon", 1, consignment.declines);
		Assert.assertEquals(0, consignment.abandons);
		Assert.assertFalse(overlay.isModalActive());
	}

	/**
	 * Space is not an answer. It skips a beat in four other ceremonies, where it
	 * costs nothing; here the muscle memory would sign a deal.
	 */
	@Test
	public void spaceCannotAnswerABindingChoice()
	{
		CeremonyBus bus = new CeremonyBus();
		Spy consignment = new Spy();
		RevealOverlay overlay = showing(bus, consignment);

		overlay.handleAdvance();
		Assert.assertEquals("space must answer nothing", 0, consignment.answered());
		Assert.assertEquals(0, consignment.abandons);
		Assert.assertTrue("the offer must still be waiting", overlay.isModalActive());
	}

	/**
	 * An abort ABANDONS — it never silently becomes a refusal.
	 *
	 * <p>Safe mode fires this on incoming damage, and the plugin fires it on a
	 * logout or a world hop. The player did not answer, so the day key must stay
	 * unspent and the roll must stay owed; turning it into a decline would charge
	 * them a day for a question they were never given the chance to hear.
	 */
	@Test
	public void anAbortAbandonsWithoutAnsweringForThePlayer()
	{
		CeremonyBus bus = new CeremonyBus();
		Spy consignment = new Spy();
		RevealOverlay overlay = showing(bus, consignment);

		overlay.abortActiveCeremony();
		Assert.assertEquals(1, consignment.abandons);
		Assert.assertEquals("an abort is not an answer", 0, consignment.answered());
		Assert.assertFalse(overlay.isModalActive());
	}

	/** A type-scoped abort aimed at another ceremony must leave the offer alone. */
	@Test
	public void anAbortScopedToTheOfferScrollsLeavesTheOfferStanding()
	{
		CeremonyBus bus = new CeremonyBus();
		Spy consignment = new Spy();
		RevealOverlay overlay = showing(bus, consignment);

		overlay.abortActiveCeremony(CeremonyBus.Type.TASK_OFFERS);
		Assert.assertEquals(0, consignment.abandons);
		Assert.assertTrue(overlay.isModalActive());
	}

	/**
	 * Teardown abandons an offer that was never even shown.
	 *
	 * <p>{@code reset()} runs in shutDown immediately before {@code bus.clear()},
	 * which drops whatever is still queued. An offer parked behind another
	 * ceremony at that moment is invisible to every other teardown path — the
	 * overlay never claimed it, so aborting the active ceremony cannot reach it —
	 * and it would leave ConsignmentService holding a live offer nobody can ever
	 * answer. Abandoning unconditionally is what closes that.
	 */
	@Test
	public void tearingDownAbandonsAnOfferStillParkedInTheQueue()
	{
		CeremonyBus bus = new CeremonyBus();
		Spy consignment = new Spy();
		RevealOverlay overlay = overlay(bus, consignment);
		bus.addRenderer(overlay);

		bus.submit(CeremonyBus.Type.DEED_CHOICE, 0);
		Assert.assertTrue(overlay.present(offer()));
		Assert.assertFalse("the offer is parked, not shown",
			consignment.answered() > 0);

		overlay.reset();
		Assert.assertEquals("a parked offer must be abandoned on teardown",
			1, consignment.abandons);
		Assert.assertEquals(0, consignment.answered());
	}

	/**
	 * The answer travels to the service ON THE CLIENT THREAD, never straight off
	 * the AWT thread the click arrived on.
	 *
	 * <p>{@code handleClick} is called by RuneLite's MouseManager, which is AWT;
	 * the answer it raises reads live game state on the way down —
	 * {@code client.getTickCount()} stamps it, accepting opens a chest whose pool
	 * asks for the player's real skill levels, and every answer ends in a bus
	 * drain that reads the game state. Reading any of that from AWT races the game
	 * thread writing it.
	 *
	 * <p>The proof is the gap: with a ClientThread that queues rather than runs,
	 * the click must reach the service NOT AT ALL until the queue is drained. An
	 * overlay that called the service directly would answer on the first line and
	 * fail here, while still passing every other test in this file — which is
	 * exactly why the inline stub cannot be the only one.
	 */
	@Test
	public void theAnswerIsOnlyEverGivenFromTheClientThread()
	{
		CeremonyBus bus = new CeremonyBus();
		Spy consignment = new Spy();
		QueueingClientThread clientThread = new QueueingClientThread();
		RevealOverlay overlay = overlay(bus, consignment,
			new GameState[]{GameState.LOGGED_IN}, clientThread);
		bus.addRenderer(overlay);
		Assert.assertTrue(overlay.present(offer()));

		clickAnswer(overlay, 0);
		Assert.assertEquals("the answer was sent straight from the AWT thread",
			0, consignment.answered());
		// the screen is still released synchronously, and must be: releasing is
		// pure bookkeeping under this overlay's own lock, and it is what lets the
		// ceremonies the answer causes claim the screen the moment they arrive
		Assert.assertFalse("releasing the modal does not need the client thread",
			overlay.isModalActive());

		Assert.assertTrue("nothing was handed to the client thread at all",
			clientThread.run() > 0);
		Assert.assertEquals(1, consignment.accepts);
		Assert.assertEquals("the answer is stamped with the CURRENT tick",
			TICK, consignment.lastTick);
	}

	/**
	 * Teardown is the ONE service call this overlay makes without hopping, and
	 * that is deliberate rather than an oversight.
	 *
	 * <p>{@code abandon()} clears the service's own live offer and logs. It reads
	 * no game state, submits nothing to the bus and therefore drains nothing, so
	 * there is no Client anywhere beneath it. Hopping it would buy nothing and
	 * cost something real: {@code reset()} runs in shutDown, immediately before
	 * the bus is cleared, and a deferred abandon is a job queued against a plugin
	 * already being taken apart — the offer would stay live for good.
	 */
	@Test
	public void teardownAbandonsWithoutWaitingForTheClientThread()
	{
		CeremonyBus bus = new CeremonyBus();
		Spy consignment = new Spy();
		QueueingClientThread clientThread = new QueueingClientThread();
		RevealOverlay overlay = overlay(bus, consignment,
			new GameState[]{GameState.LOGGED_IN}, clientThread);
		bus.addRenderer(overlay);
		Assert.assertTrue(overlay.present(offer()));

		overlay.reset();
		Assert.assertEquals("teardown must not leave the offer live behind a hop",
			1, consignment.abandons);
		Assert.assertEquals("and it must not answer for the player either",
			0, consignment.answered());
	}

	/** A double click cannot answer twice: the modal is gone after the first. */
	@Test
	public void aSecondClickAfterTheAnswerChangesNothing()
	{
		CeremonyBus bus = new CeremonyBus();
		Spy consignment = new Spy();
		RevealOverlay overlay = showing(bus, consignment);

		clickAnswer(overlay, 0);
		clickAnswer(overlay, 1);
		Assert.assertEquals(1, consignment.accepts);
		Assert.assertEquals(0, consignment.declines);
	}

	/** A click on neither plate answers nothing and leaves the question up. */
	@Test
	public void clickingBesideBothAnswersDecidesNothing()
	{
		CeremonyBus bus = new CeremonyBus();
		Spy consignment = new Spy();
		RevealOverlay overlay = showing(bus, consignment);

		overlay.handleClick(new Point(4, 4));
		Assert.assertEquals(0, consignment.answered());
		Assert.assertTrue(overlay.isModalActive());
	}

	/**
	 * The two plates never overlap and never leave the canvas.
	 *
	 * <p>A binding choice whose targets touched would take an answer the player
	 * did not give, and the pair is laid out by arithmetic rather than by a fixed
	 * table, so the sweep is the only thing that proves it at every size a
	 * resizable client can be dragged to.
	 */
	@Test
	public void theTwoAnswersNeverOverlapAtAnyCanvasSize()
	{
		Rectangle a = new Rectangle();
		Rectangle b = new Rectangle();
		int checked = 0;
		// from well below the client's own smallest canvas (765x503 fixed) up past
		// a maximised 4K window
		for (int cw = 320; cw <= 2600; cw += 7)
		{
			for (int ch = 300; ch <= 1600; ch += 11)
			{
				RevealOverlay.consignRect(0, cw, ch, a);
				RevealOverlay.consignRect(1, cw, ch, b);
				checked++;
				Assert.assertFalse(cw + "x" + ch + ": the two answers overlap",
					a.intersects(b));
				Assert.assertTrue(cw + "x" + ch + ": an answer ran off the left edge",
					a.x >= 0);
				Assert.assertTrue(cw + "x" + ch + ": an answer ran off the right edge",
					b.x + b.width <= cw);
				Assert.assertTrue(cw + "x" + ch + ": an answer ran off the bottom",
					a.y + a.height <= ch);
				Assert.assertEquals(cw + "x" + ch + ": the answers are different sizes",
					a.width, b.width);
			}
		}
		Assert.assertTrue("the sweep checked nothing", checked > 1000);
	}

	/**
	 * What is drawn is where the hit test looks.
	 *
	 * <p>The plates are painted from {@code consignRect} and clicked through
	 * {@code consignRect}, but nothing enforces that they stay the same call —
	 * a plate drawn at an offset would leave the player clicking a picture and
	 * getting nothing, or worse, clicking empty canvas and striking a deal. Both
	 * rectangles must therefore hold ink, and the gap between them must hold none:
	 * a full-canvas fill would satisfy the first half on its own.
	 */
	@Test
	public void bothAnswersArePaintedExactlyWhereTheyAreClicked()
	{
		CeremonyBus bus = new CeremonyBus();
		RevealOverlay overlay = showing(bus, new Spy());

		BufferedImage img = new BufferedImage(W, H, BufferedImage.TYPE_INT_RGB);
		Graphics2D g = img.createGraphics();
		try
		{
			g.setColor(Color.WHITE);
			g.fillRect(0, 0, W, H);
			overlay.render(g);
		}
		finally
		{
			g.dispose();
		}

		// the dimmed backdrop, sampled where the ceremony draws nothing at all
		int backdrop = img.getRGB(4, 4);
		Assert.assertNotEquals("the modal did not dim the canvas", Color.WHITE.getRGB(), backdrop);

		Rectangle a = new Rectangle();
		Rectangle b = new Rectangle();
		RevealOverlay.consignRect(0, W, H, a);
		RevealOverlay.consignRect(1, W, H, b);
		Assert.assertNotEquals("nothing is drawn where TAKE THE DEAL is clicked",
			backdrop, img.getRGB(a.x + a.width / 2, a.y + a.height / 2));
		Assert.assertNotEquals("nothing is drawn where SPIN THE WHEEL is clicked",
			backdrop, img.getRGB(b.x + b.width / 2, b.y + b.height / 2));
		Assert.assertEquals("the gap between the two answers is not empty",
			backdrop, img.getRGB((a.x + a.width + b.x) / 2, a.y + a.height / 2));
	}
}

package com.gachaman.overlay;

import java.awt.*;
import org.junit.*;

/**
 * The "one left" signal: at exactly one kill remaining, the contract's targets
 * and its progress bar turn a pulsing gold.
 *
 * <p>The overlays themselves need a live Client, so what is pinned here is the
 * pure piece — the pulse — plus the arithmetic both halves share. The two halves
 * MUST agree: {@code TaskNpcHighlightOverlay} is behind a config toggle, so if
 * they ever disagreed a player with highlighting off would get no warning while
 * a player with it on got two.
 */
public class OneLeftTest
{
	/** The same expression both overlays use, kept here as the spec. */
	private static int remaining(int required, int done, int partyOther, boolean party)
	{
		return required - (done + (party ? partyOther : 0));
	}

	@Test
	public void theSignalIsExactlyOneKillOut()
	{
		Assert.assertEquals(1, remaining(20, 19, 0, false));
		Assert.assertEquals(2, remaining(20, 18, 0, false));
		// and it is == 1, never <= 1: a completion landing mid-frame, or pooled
		// party kills overshooting the quota, must not re-arm it at zero or below
		Assert.assertEquals(0, remaining(20, 20, 0, false));
		Assert.assertEquals(-1, remaining(20, 21, 0, false));
	}

	@Test
	public void aSharedContractCountsTheWholeParty()
	{
		// 12 of mine + 7 of theirs against 20 is one out, even though my own
		// kill count alone is nowhere near it
		Assert.assertEquals(1, remaining(20, 12, 7, true));
		// the same numbers on a SOLO contract are not one out
		Assert.assertEquals(8, remaining(20, 12, 7, false));
	}

	@Test
	public void thePulseStaysInsideAVisibleAlphaBand()
	{
		// it breathes rather than blinks: never invisible, never flat
		int min = 255;
		int max = 0;
		for (int i = 0; i < 400; i++)
		{
			Color c = TaskNpcHighlightOverlay.finalTargetGold();
			Assert.assertEquals(255, c.getRed());
			Assert.assertEquals(205, c.getGreen());
			Assert.assertEquals(70, c.getBlue());
			min = Math.min(min, c.getAlpha());
			max = Math.max(max, c.getAlpha());
			try
			{
				Thread.sleep(1);
			}
			catch (InterruptedException e)
			{
				Thread.currentThread().interrupt();
				break;
			}
		}
		Assert.assertTrue("never fades out of sight: " + min, min >= 165);
		Assert.assertTrue("never exceeds opaque: " + max, max <= 255);
		Assert.assertTrue("it actually moves", max > min);
	}
}

package com.gachaman.overlay;

import com.gachaman.*;
import java.awt.*;
import java.awt.image.*;
import java.io.*;
import javax.imageio.*;

/**
 * Checks the frames that had to be stored below their authored size to fit the
 * Plugin Hub's 1 MiB decoded-image limit.
 *
 * <p>Two different questions, and only one of them is about fidelity:
 *
 * <ol>
 *   <li><b>Geometry.</b> A downscaled frame is stretched back to its authored
 *       size at draw time. If the index's authored width/height were wrong the
 *       glow would land shifted or shrunk — a visible break, not a soft one.
 *       The painted bounding box must match the procedural one.
 *   <li><b>Fidelity.</b> Resolution really was traded away here, so the delta
 *       is NOT expected to be zero. What matters is that it stays low and sits
 *       in the soft halo rather than on the chest itself.
 * </ol>
 */
public final class CeremonyFitCmp {
	private static final CeremonyPlayer PLAYER = new CeremonyPlayer(new com.google.gson.Gson());

	/** The frames the generator reported as downscaled. */
	private static final Object[][] CASES = {
		{Tuning.Chest.GILDED, 72}, {Tuning.Chest.ORNATE, 36}, {Tuning.Chest.ORNATE, 37},
		{Tuning.Chest.ORNATE, 38}, {Tuning.Chest.ORNATE, 40}, {Tuning.Chest.ORNATE, 64},
		{Tuning.Chest.ORNATE, 65}, {Tuning.Chest.ORNATE, 66}, {Tuning.Chest.ORNATE, 68},
	};

	private static final int W = 300;
	private static final int H = 225;
	private static final int CW = 1100;
	private static final int CH = 1000;

	public static void main(String[] a) throws Exception {
		File dir = new File(a[0]);
		dir.mkdirs();
		System.out.printf("%-8s %5s  %-22s %-22s %7s %7s %7s%n",
			"tier", "frame", "procedural bounds", "sprite bounds", "meanD", "maxD", ">8/255");
		for (Object[] c : CASES) {
			Tuning.Chest tier = (Tuning.Chest) c[0];
			int f = (Integer) c[1];
			long el = f * 1000L / 20L;

			BufferedImage proc = canvas();
			Graphics2D g = proc.createGraphics();
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			ChestPainter.draw(g, CW / 2, CH / 2, W, H, CeremonyArt.lidOpen(tier, el), tier,
				CeremonyArt.trim(tier), 0f, CeremonyArt.leak(tier, el), el);
			if (tier == Tuning.Chest.GILDED) {
				ChestPainter.drawPadlock(g, CW / 2, CH / 2 + H / 8, W, el, ChestStrain.giveMs(tier));
			}
			else if (tier == Tuning.Chest.ORNATE) {
				ChestPainter.drawChains(g, CW / 2, CH / 2, W, H, el, 1200, 1400);
			}
			g.dispose();

			BufferedImage spr = canvas();
			g = spr.createGraphics();
			PLAYER.draw(g, CW / 2, CH / 2, W, H, tier, f, 1f);
			g.dispose();

			int[] pb = bounds(proc);
			int[] sb = bounds(spr);
			long sum = 0;
			long n = 0;
			int max = 0;
			long loud = 0;
			for (int y = 0; y < CH; y++) {
				for (int x = 0; x < CW; x++) {
					int p = proc.getRGB(x, y);
					int s = spr.getRGB(x, y);
					if (p == 0 && s == 0) {
						continue;
					}
					int d = 0;
					for (int sh = 0; sh <= 24; sh += 8) {
						d = Math.max(d, Math.abs(((p >> sh) & 0xFF) - ((s >> sh) & 0xFF)));
					}
					sum += d;
					n++;
					max = Math.max(max, d);
					if (d > 8) {
						loud++;
					}
				}
			}
			System.out.printf("%-8s %5d  %-22s %-22s %7.2f %7d %6.2f%%%n",
				tier, f, box(pb), box(sb), n == 0 ? 0 : sum / (double) n, max,
				n == 0 ? 0 : 100.0 * loud / n);
			ImageIO.write(proc, "png", new File(dir, tier + "_" + f + "_proc.png"));
			ImageIO.write(spr, "png", new File(dir, tier + "_" + f + "_spr.png"));
		}
	}

	private static BufferedImage canvas() {
		return new BufferedImage(CW, CH, BufferedImage.TYPE_INT_ARGB);
	}

	private static String box(int[] b) {
		return b == null ? "(empty)"
			: String.format("%d,%d %dx%d", b[0], b[1], b[2] - b[0], b[3] - b[1]);
	}

	private static int[] bounds(BufferedImage img) {
		int minX = img.getWidth();
		int minY = img.getHeight();
		int maxX = -1;
		int maxY = -1;
		for (int y = 0; y < img.getHeight(); y++) {
			for (int x = 0; x < img.getWidth(); x++) {
				if ((img.getRGB(x, y) >>> 24) > 2) {
					minX = Math.min(minX, x);
					minY = Math.min(minY, y);
					maxX = Math.max(maxX, x);
					maxY = Math.max(maxY, y);
				}
			}
		}
		return maxX < 0 ? null : new int[]{minX, minY, maxX + 1, maxY + 1};
	}

	private CeremonyFitCmp() {
	}
}

package com.gachaman.overlay;

import java.util.List;
import com.gachaman.party.*;
import java.awt.*;
import java.awt.image.*;
import java.util.*;
import org.junit.*;

/**
 * Two defects in {@link RevealOverlay} that a live client would only ever show
 * you as a smear of overlapping text, or as a frame-rate mystery on a broken
 * jar. Both are pinned here because both are cheap to reproduce off-client:
 * {@code drawVoters} is a static function of a Graphics2D and a name list, and
 * the sprite cache is a plain static map.
 *
 * <p>Explicit {@code java.util.List} import on purpose — {@code java.awt.*} is
 * wildcarded below for Graphics2D and Color, and it exports a List of its own.
 */
public class RevealOverlayTest
{
	private static final int W = 400;
	private static final int H = 200;
	/** Left margin the voter block is drawn from, i.e. drawVoters' own {@code x}. */
	private static final int MARGIN = 12;
	/** Top the block starts at; the "Backed by" rule lands here. */
	private static final int TOP = 20;
	/**
	 * Column width. Narrow enough that the five names below need three rows,
	 * which is what gives the sweep a wrap to refuse in the first place.
	 */
	private static final int COLUMN = 150;
	/** Paper white. Every ink the block uses is dark, so "not this" means "inked". */
	private static final int BG = 0xFFFFFFFF;

	/**
	 * Five backers with no avatars. Dropping the faces is deliberate: it makes
	 * every chip's width a pure function of its name, so the layout the sweep
	 * reasons about has one input instead of two, and drawVoterFace's scratch
	 * image never enters the picture.
	 */
	private static List<PartyRollService.Voter> voters()
	{
		List<PartyRollService.Voter> out = new ArrayList<>();
		for (String name : new String[]{
			"Zezimaaaa", "Wooooox", "Framedddd", "Torvestaa", "Odablock"})
		{
			out.add(new PartyRollService.Voter(name, null, false));
		}
		return out;
	}

	/**
	 * The voter block rendered against {@code parchBot}, as a flat ARGB raster.
	 *
	 * <p>No rendering hints are set, by both renders equally — the comparison
	 * below only holds if the two rasters differ for exactly one reason.
	 */
	private static int[] render(int parchBot)
	{
		BufferedImage img = new BufferedImage(W, H, BufferedImage.TYPE_INT_RGB);
		Graphics2D g = img.createGraphics();
		try
		{
			g.setColor(Color.WHITE);
			g.fillRect(0, 0, W, H);
			RevealOverlay.drawVoters(g, voters(), MARGIN, TOP, COLUMN, parchBot);
		}
		finally
		{
			g.dispose();
		}
		return img.getRGB(0, 0, W, H, null, 0, W);
	}

	/**
	 * The "+N more" overflow label is appended AFTER the names on its row, never
	 * stamped on top of them.
	 *
	 * <p>Method: render the block once with the whole canvas to play with, then
	 * again at every parchment bottom from the very cramped to the roomy. A tight
	 * render draws a strict PREFIX of the roomy layout at identical coordinates —
	 * the wrap arithmetic depends only on the names, the font and the column, none
	 * of which parchBot touches, and the voter whose chip triggered the refused
	 * wrap is on the NEXT row in the roomy render. So every pixel the tight render
	 * inks and the roomy one does not is label ink, and nothing else.
	 *
	 * <p>The invariant is then one number against another: the label's leftmost
	 * pixel must sit clear of the rightmost pixel already on the label's own
	 * scanlines. The original code reset cx to the left margin at the wrap and
	 * then drew the label with it against the previous row's baseline, so the
	 * label started at the margin and the first name on that row disappeared
	 * underneath it — leftmost label pixel far to the LEFT of the row's ink.
	 */
	@Test
	public void theOverflowLabelNeverOverprintsTheNamesOnItsRow()
	{
		int[] roomy = render(H);
		int overflows = 0;
		for (int parchBot = TOP; parchBot <= H; parchBot++)
		{
			int[] tight = render(parchBot);
			int labelLeft = Integer.MAX_VALUE;
			int labelTop = Integer.MAX_VALUE;
			int labelBottom = Integer.MIN_VALUE;
			for (int py = 0; py < H; py++)
			{
				for (int px = 0; px < W; px++)
				{
					int at = py * W + px;
					if (tight[at] != BG && roomy[at] == BG)
					{
						labelLeft = Math.min(labelLeft, px);
						labelTop = Math.min(labelTop, py);
						labelBottom = Math.max(labelBottom, py);
					}
				}
			}
			if (labelLeft == Integer.MAX_VALUE)
			{
				// this height either fitted every name or refused the whole
				// block at the heading guard; either way there is no label
				continue;
			}
			overflows++;

			// the widest ink already on the label's scanlines, which on those
			// rows is exactly the chips that did fit
			int rowInkRight = -1;
			for (int py = labelTop; py <= labelBottom; py++)
			{
				for (int px = 0; px < W; px++)
				{
					if (roomy[py * W + px] != BG)
					{
						rowInkRight = Math.max(rowInkRight, px);
					}
				}
			}
			Assert.assertTrue(
				"parchBot=" + parchBot + ": '+N more' starts at x=" + labelLeft
					+ " but the names on that row run out to x=" + rowInkRight,
				labelLeft > rowInkRight);
		}
		// without this the sweep could pass by never producing a label at all
		Assert.assertTrue("the sweep never forced an overflow", overflows > 0);
	}

	/**
	 * A sprite that is not in the jar is looked up ONCE, not once per frame.
	 *
	 * <p>{@code computeIfAbsent} used to do the loading, and a HashMap does not
	 * record a null mapping — so a missing PNG stayed "not cached yet" forever and
	 * the roulette re-walked the classloader for it on every frame of the spin.
	 * The cached miss is the whole fix, so the assertion is on the map, not on
	 * anything drawn.
	 *
	 * <p>The map now lives in {@link ArtCache}, which the scroll rollers and the
	 * parchment texture load through as well — so this one assertion covers every
	 * sprite the ceremonies draw, including the copy of the bug ScrollPainter was
	 * still carrying in its own {@code computeIfAbsent}.
	 */
	@Test
	public void aMissingSpriteIsResolvedOnlyOnce()
	{
		String missing = "no-such-wheel-part";
		ArtCache.ART.remove(missing);
		blit(missing);
		Assert.assertTrue("a miss must be remembered, not retried every frame",
			ArtCache.ART.containsKey(missing));
		Assert.assertNull("a miss caches as an explicit null",
			ArtCache.ART.get(missing));
	}

	/**
	 * The sprite that ships still loads and still caches. Guards the other half
	 * of the same rewrite: a cache that remembers misses but has stopped
	 * remembering hits would pass the test above and blank the wheel.
	 */
	@Test
	public void aShippedSpriteStillLoadsAndCaches()
	{
		ArtCache.ART.remove("wheel-hub");
		blit("wheel-hub");
		Assert.assertNotNull("wheel-hub.png ships and must decode",
			ArtCache.ART.get("wheel-hub"));
	}

	/**
	 * The scroll chrome loads through the SAME cache, so its misses are cached too.
	 *
	 * <p>ScrollPainter used to carry its own {@code computeIfAbsent} copy of the
	 * loader — the very bug the test above pins for the wheel, sitting on a path
	 * that blits five slices per roller and two rollers per scroll, four scrolls
	 * at a time. Drawing a roller in a tier colour nothing was authored for is the
	 * cheapest way to reach a miss: the draw must survive it, and the cache must
	 * come out of it holding an explicit null rather than nothing at all.
	 */
	@Test
	public void theScrollRollerCachesItsMissesToo()
	{
		String slice = "roller-123456-m";
		ArtCache.ART.remove(slice);
		BufferedImage img = new BufferedImage(64, 32, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		try
		{
			ScrollPainter.drawRoller(g, new Rectangle(0, 0, 64, 32), 16, new Color(0x123456), 0.0);
		}
		finally
		{
			g.dispose();
		}
		Assert.assertTrue("a missing roller slice must be remembered",
			ArtCache.ART.containsKey(slice));
		Assert.assertNull("a miss caches as an explicit null",
			ArtCache.ART.get(slice));
	}

	/** One blitArt call against a throwaway surface; only the cache is of interest. */
	private static void blit(String name)
	{
		BufferedImage img = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		try
		{
			RevealOverlay.blitArt(g, name, 8, 8, 1.0, 0, 0);
		}
		finally
		{
			g.dispose();
		}
	}
}

package com.gachaman.overlay;

