		System.out.println("compared " + n + " frame pairs");
	}

	private CeremonyCmp() {
	}
}

package com.gachaman.overlay;

import com.gachaman.*;
import java.awt.*;
import java.awt.geom.*;
import java.io.*;
import java.util.*;
import javax.imageio.*;

/**
 * Procedural pseudo-3D treasure chest for the reveal ceremony. The chest is
 * drawn with fake perspective: a trapezoid front face with wood-plank strips,
 * side hints, a back rim, and a lid quad that rotates open around its back
 * hinge (vertical scale/shear approximates the 3D rotation; the inner face
 * fades in past ~60 degrees). Warm light spills from the opening, dust and
 * spark particles drift up. Pure function of its arguments - no state, no
 * timers; all animation comes in via {@code openT}, {@code leak} and
 * {@code timeMs} so callers control time. Single-threaded render use only
 * (shared scratch path).
 */
final class ChestPainter {
	private static final double OPEN_ANGLE_MAX = 1.95; // ~112 degrees

	// Body layout, as fractions of the chest box. Named because the chains have
	// to wrap the SILHOUETTE these produce, so the numbers now have two readers.
	private static final double LID_TOP_FRAC = 0.16;   // empty air above the lid
	private static final double LID_FRONT_FRAC = 0.30; // lid skirt height
	private static final double SLANT_FRAC = 0.045;    // front face taper
	private static final double SKIRT_WIDEN = 1.02;    // lid overhangs the body

	private static final Color WOOD_LIGHT = new Color(126, 84, 48);
	private static final Color WOOD_DARK = new Color(72, 46, 22);
	private static final Color WOOD_SEAM = new Color(46, 28, 12);
	private static final Color WOOD_SIDE = new Color(56, 35, 16);
	private static final Color INTERIOR = new Color(24, 14, 6);
	private static final Color INNER_LID = new Color(58, 36, 16);
	private static final Color GLOW_WARM = new Color(255, 214, 120);
	private static final Color GLOW_HOT = new Color(255, 240, 200);
	private static final Color METAL_SILVER_HI = new Color(212, 216, 226);
	private static final Color METAL_SILVER_LO = new Color(120, 124, 136);
	private static final Color METAL_GOLD_HI = new Color(244, 208, 96);
	private static final Color METAL_GOLD_LO = new Color(148, 108, 28);
	private static final Color METAL_WORN_HI = new Color(96, 92, 86);
	private static final Color METAL_WORN_LO = new Color(52, 48, 44);
	private static final Color METAL_RUST_HI = new Color(124, 78, 48);
	private static final Color METAL_RUST_LO = new Color(62, 40, 26);
	// Wide range on purpose: the chain sits on gold bands over lit wood, and a
	// mid-grey barstock with a mild highlight merges into all of it as one flat
	// mass. Dark body, hot specular, and the specular carries the scene's warmth.
	private static final Color CHAIN_LIGHT = new Color(136, 139, 150);
	private static final Color CHAIN_SHADE = new Color(20, 21, 27);
	private static final Color CHAIN_SPEC = new Color(246, 242, 228);
	private static final Color LOCK_GOLD = new Color(230, 190, 80);
	private static final Color LOCK_BODY_HI = new Color(112, 116, 130);
	private static final Color LOCK_BODY_LO = new Color(28, 30, 38);

	/** Key light for the chain barstock: up and to the left, screen space. */
	private static final double LIGHT_X = -0.52;
	private static final double LIGHT_Y = -0.85;

	private static final int LINK_FULL = 0;
	private static final int LINK_NEAR = 1;

	/** Where along its chain each padlock hangs; 0.30 puts the pair either side
	 * of the chest's own keyplate. */
	private static final double LOCK_T = 0.30;
	/** A lock gives, and only then does the chain it was holding let go. */
	private static final long LOCK_TO_WHIP_MS = 160;
	private static final long LOCK_BREAK_MS = 750;

	/** Shared scratch path; render happens on a single thread. */
	private static final Path2D.Double PATH = new Path2D.Double();

	private ChestPainter() {
	}

	/**
	 * Draw the chest centered at (cx, cy) inside a w-by-h box.
	 *
	 * @param openT     0 = closed, 1 = fully open; values above 1 add blast
	 *                  lift (the lid keeps rising off the hinge). The lid ANGLE
	 *                  clamps at 1, so above-1 values only detach the lid from
	 *                  the hinge - reserve them for the stationary lid-blast
	 *                  beat and pass at most 1.0 while translating the chest,
	 *                  or the lid will visibly float off the moving body.
	 * @param tier      structural styling (band metal, trim richness)
	 * @param trim      trim color override (jackpot crossfades pass a mix)
	 * @param innerGlow extra interior glow 0..1 independent of the lid angle
	 * @param leak      seam light-leak intensity 0..1 (pre-blast tension)
	 */
	static void draw(Graphics2D g, int cx, int cy, int w, int h, double openT,
		Tuning.Chest tier, Color trim, float innerGlow, float leak, long timeMs) {
		Graphics2D g2 = (Graphics2D) g.create();
		g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

		int x = cx - w / 2;
		int top = cy - h / 2;
		int bottom = cy + h / 2;
		double a = clamp01(openT) * OPEN_ANGLE_MAX;
		int lift = (int) (Math.max(0, openT - 1.0) * h * 0.55);

		int lidFrontH = (int) (h * LID_FRONT_FRAC);
		int dTop = (int) (h * LID_TOP_FRAC);
		int frontTopY = top + lidFrontH + dTop;
		int inset = (int) (w * 0.07);
		int slant = (int) (w * SLANT_FRAC);
		int hingeY = top;

		float openGlow = (float) smoothstep(Math.min(1.0, a / 1.5));
		float glow = Math.max(openGlow, clamp01f(innerGlow));

		drawStatic(g2, cx, cy, w, h, tier, "back");
		if (a > 0.10) {
			drawInterior(g2, x, w, inset, hingeY, frontTopY, glow);
		}
		drawStatic(g2, cx, cy, w, h, tier, "body");
		if (glow > 0.04f) {
			drawSpillGlow(g2, cx, frontTopY, w, h, glow);
			drawMotes(g2, cx, frontTopY, w, h, glow, timeMs);
		}
		drawLid(g2, x, w, inset, hingeY, dTop, lidFrontH, frontTopY, a, lift, tier, trim, glow);
		if (leak > 0.03f && a < 0.15) {
			// seam between the closed lid skirt and the body top edge
			drawSeamLeak(g2, x, w, frontTopY, leak, timeMs);
		}
		g2.dispose();
	}

	// --- pieces ---

	private static final Map<String, Image> STATIC_ART = new HashMap<>();
	private static final int ART_W = 300;
	private static final int ART_H = 225;
	private static final int ART_PAD_X = 34;
	private static final int ART_PAD_Y = 26;

	private static void drawStatic(Graphics2D g2, int cx, int cy, int w, int h, Tuning.Chest tier,
		String part) {
		Image art = STATIC_ART.computeIfAbsent(part + tier.name(), k -> {
			try (InputStream in = ChestPainter.class.getResourceAsStream("/com/gachaman/art/chest-"
				+ part + "-" + tier.name().toLowerCase(Locale.ROOT) + ".png")) {
				return in == null ? null : ImageIO.read(in);
			}
			catch (Exception e) {
				return null;
			}
		});
		if (art == null) {
			return;
		}
		double sx = w / (double) ART_W;
		double sy = h / (double) ART_H;
		int dw = (int) Math.round(art.getWidth(null) * sx);
		int dh = (int) Math.round(art.getHeight(null) * sy);
		int dx = cx - (int) Math.round((ART_PAD_X + ART_W / 2.0) * sx);
		int dy = cy - (int) Math.round((ART_PAD_Y + ART_H / 2.0) * sy);
		g2.drawImage(art, dx, dy, dw, dh, null);
	}



	private static void drawInterior(Graphics2D g2, int x, int w, int inset, int hingeY,
		int frontTopY, float glow) {
		PATH.reset();
		PATH.moveTo(x + 2, frontTopY);
		PATH.lineTo(x + w - 2, frontTopY);
		PATH.lineTo(x + w - inset, hingeY + 4);
		PATH.lineTo(x + inset, hingeY + 4);
		PATH.closePath();
		g2.setColor(INTERIOR);
		g2.fill(PATH);
		// warm pool inside, layered for a radial falloff
		int cxm = x + w / 2;
		int span = w - inset * 2;
		for (int i = 6; i >= 1; i--) {
			float t = i / 6f;
			int ew = (int) (span * (0.35 + 0.65 * (1 - t)));
			int eh = Math.max(4, (int) ((frontTopY - hingeY) * (1 - t) * 0.9));
			g2.setColor(withAlpha(GLOW_WARM, glow * 0.16f * (1 - t) + glow * 0.06f));
			g2.fillOval(cxm - ew / 2, frontTopY - eh - 2, ew, eh + 4);
		}
	}





	private static void drawLid(Graphics2D g2, int x, int w, int inset, int hingeY, int dTop,
		int lidFrontH, int frontTopY, double a, int lift, Tuning.Chest tier, Color trim, float glow) {
		double cosA = Math.cos(a);
		double sinA = Math.sin(a);
		double rise = (frontTopY - hingeY) * 1.6;

		int hy = hingeY - lift;
		double lipY = hy + dTop * cosA - rise * sinA;
		double lipHalf = (w * (1.0 - 0.10 * sinA)) / 2.0;
		double cxm = x + w / 2.0;

		// inner face: visible once past ~60 degrees, lit from the chest below
		float innerA = clamp01f((float) ((a - 1.0) / 0.5));
		if (innerA > 0.02f) {
			PATH.reset();
			PATH.moveTo(x + inset, hy);
			PATH.lineTo(x + w - inset, hy);
			PATH.lineTo(cxm + lipHalf, lipY);
			PATH.lineTo(cxm - lipHalf, lipY);
			PATH.closePath();
			Graphics2D gi = (Graphics2D) g2.create();
			gi.setClip(PATH);
			gi.setPaint(new GradientPaint((float) cxm, (float) lipY, dim(INNER_LID, 0.8f),
				(float) cxm, hy, mix(INNER_LID, GLOW_WARM, glow * 0.55f)));
			gi.fill(PATH);
			gi.setColor(withAlpha(GLOW_WARM, glow * 0.30f * innerA));
			gi.fillRect(x + inset, hy - 6, w - inset * 2, 12);
			gi.dispose();
			g2.setColor(withAlpha(trim, innerA));
			g2.setStroke(new BasicStroke(2.2f));
			g2.draw(PATH);
		}

		// outer skirt face: squashes vertically as the lid tips back
		if (cosA > 0.06) {
			double skirtTopY = hy + dTop * cosA;
			double skirtBotY = skirtTopY + lidFrontH * cosA;
			double topHalf = lipHalf;
			double botHalf = (w * SKIRT_WIDEN) / 2.0;
			PATH.reset();
			PATH.moveTo(cxm - topHalf, skirtTopY);
			PATH.lineTo(cxm + topHalf, skirtTopY);
			PATH.lineTo(cxm + botHalf, skirtBotY);
			PATH.lineTo(cxm - botHalf, skirtBotY);
			PATH.closePath();
			boolean battered = worn(tier);
			float hiDim = tier == Tuning.Chest.RUSTY ? 0.80f : 0.9f;
			float loDim = tier == Tuning.Chest.RUSTY ? 0.65f : 0.75f;
			Color hi = battered ? dim(WOOD_LIGHT, hiDim) : brighten(WOOD_LIGHT, 1.15f);
			Color lo = battered ? dim(WOOD_LIGHT, loDim) : WOOD_LIGHT;
			g2.setPaint(new GradientPaint((float) cxm, (float) skirtTopY, hi,
				(float) cxm, (float) skirtBotY, lo));
			g2.fill(PATH);

			Graphics2D gs = (Graphics2D) g2.create();
			gs.setClip(PATH);
			// plank seam across the skirt
			gs.setColor(WOOD_SEAM);
			int seamY = (int) lerp(skirtTopY, skirtBotY, 0.5);
			gs.drawLine((int) (cxm - botHalf), seamY, (int) (cxm + botHalf), seamY);
			// lid bands aligned with the body bands
			int bandW = Math.max(6, w / 16);
			gs.setPaint(new GradientPaint(0, (float) skirtTopY, bandHi(tier),
				0, (float) skirtBotY, bandLo(tier)));
			gs.fillRect((int) (cxm - w * 0.30) - bandW / 2, (int) skirtTopY - 2,
				bandW, (int) (skirtBotY - skirtTopY) + 4);
			gs.fillRect((int) (cxm + w * 0.30) - bandW / 2, (int) skirtTopY - 2,
				bandW, (int) (skirtBotY - skirtTopY) + 4);
			gs.dispose();

			g2.setColor(trim);
			g2.setStroke(new BasicStroke(tier == Tuning.Chest.ORNATE ? 3.0f : 2.2f));
			g2.draw(PATH);
			// arched top hint on the closed lid
			if (a < 0.35) {
				g2.setColor(withAlpha(brighten(WOOD_LIGHT, 1.25f), (float) (1.0 - a / 0.35) * 0.5f));
				g2.setStroke(new BasicStroke(1.4f));
				g2.drawLine((int) (cxm - topHalf + 6), (int) skirtTopY + 2,
					(int) (cxm + topHalf - 6), (int) skirtTopY + 2);
			}
		}
	}

	private static void drawSpillGlow(Graphics2D g2, int cx, int frontTopY, int w, int h, float glow) {
		// column of warm light rising out of the opening
		for (int i = 5; i >= 1; i--) {
			float t = i / 5f;
			int gw = (int) (w * (0.36 + 0.5 * (1 - t)));
			int gh = (int) (h * 0.7 * (1 - t * 0.35));
			g2.setColor(withAlpha(GLOW_WARM, glow * 0.10f * (1 - t) + glow * 0.03f));
			g2.fillOval(cx - gw / 2, frontTopY - gh, gw, gh + 8);
		}
		g2.setColor(withAlpha(GLOW_HOT, glow * 0.25f));
		g2.fillOval(cx - w / 4, frontTopY - 8, w / 2, 14);
	}

	private static void drawMotes(Graphics2D g2, int cx, int frontTopY, int w, int h,
		float glow, long timeMs) {
		for (int p = 0; p < 14; p++) {
			float h1 = hash01(p * 197 + 11);
			float h2 = hash01(p * 197 + 12);
			float h3 = hash01(p * 197 + 13);
			int cycle = 1500 + (int) (h1 * 1300);
			float ph = ((timeMs + (long) (h2 * 99991)) % cycle) / (float) cycle;
			int px = cx + (int) ((h3 - 0.5f) * w * 0.62) + (int) (Math.sin(timeMs * 0.0012 + p) * 5);
			int py = frontTopY - 4 - (int) (ph * h * 0.85);
			float alpha = (1 - ph) * glow * (0.35f + 0.5f * h2);
			if (alpha < 0.03f) {
				continue;
			}
			if ((p & 1) == 0) {
				g2.setColor(withAlpha(METAL_GOLD_HI, alpha));
				g2.fillRect(px, py, 2, 2);
			}
			else {
				g2.setColor(withAlpha(GLOW_HOT, alpha * 0.6f));
				g2.fillRect(px, py, 1, 2);
			}
		}
	}

	private static void drawSeamLeak(Graphics2D g2, int x, int w, int seamY, float leak, long timeMs) {
		float flicker = 0.85f + 0.15f * (float) Math.sin(timeMs * 0.02);
		float a = clamp01f(leak) * flicker;
		for (int i = 3; i >= 1; i--) {
			g2.setColor(withAlpha(GLOW_WARM, a * 0.14f * (4 - i)));
			g2.setStroke(new BasicStroke(2f + i * 3f));
			g2.drawLine(x + 6, seamY, x + w - 6, seamY);
		}
		g2.setColor(withAlpha(GLOW_HOT, a));
		g2.setStroke(new BasicStroke(2f));
		g2.drawLine(x + 6, seamY, x + w - 6, seamY);
		// stray rays escaping the seam
		g2.setStroke(new BasicStroke(1.4f));
		for (int r = 0; r < 5; r++) {
			float hr = hash01(r * 379 + 5);
			int rx = x + 10 + (int) (hr * (w - 20));
			int len = 6 + (int) (a * 22 * hash01(r * 379 + 6));
			g2.setColor(withAlpha(GLOW_HOT, a * 0.55f));
			g2.drawLine(rx, seamY - 2, rx + (int) ((hr - 0.5f) * 8), seamY - 2 - len);
		}
	}

	// --- ceremony props ---

	/**
	 * Gilded padlock hanging over the lock plate; pulses, then shatters into
	 * fragments at {@code shatterAtMs} (pure function of elapsed time).
	 */
	static void drawPadlock(Graphics2D g2, int cx, int cy, int chestW, long el, long shatterAtMs) {
		int size = chestW / 5;
		if (el >= shatterAtMs) {
			long t = el - shatterAtMs;
			if (t > 850) {
				return;
			}
			float u = t / 850f;
			// flash ring
			g2.setColor(withAlpha(GLOW_HOT, (1 - u) * 0.8f));
			g2.setStroke(new BasicStroke(2f + (1 - u) * 6f));
			int rr = (int) (size * (0.5 + u * 2.2));
			g2.drawOval(cx - rr, cy - rr, rr * 2, rr * 2);
			// fragments with fake gravity
			double ts = t / 1000.0;
			for (int p = 0; p < 14; p++) {
				float a1 = hash01(p * 131 + 7);
				float a2 = hash01(p * 131 + 8);
				double ang = a1 * Math.PI * 2;
				double speed = 70 + a2 * 190;
				int px = cx + (int) (Math.cos(ang) * speed * ts);
				int py = cy + (int) (Math.sin(ang) * speed * ts + 320 * ts * ts);
				int fs = 2 + (p % 3);
				g2.setColor(withAlpha((p & 1) == 0 ? METAL_GOLD_HI : METAL_SILVER_HI, 1 - u));
				Graphics2D gf = (Graphics2D) g2.create();
				gf.rotate(a1 * 6 + ts * 8, px, py);
				gf.fillRect(px - fs / 2, py - fs / 2, fs + 2, fs);
				gf.dispose();
			}
			return;
		}
		float pulse = 0.5f + 0.5f * (float) Math.sin(el * 0.008);
		// glow behind the lock
		for (int i = 4; i >= 1; i--) {
			g2.setColor(withAlpha(LOCK_GOLD, (0.10f + 0.10f * pulse) * (5 - i) / 5f));
			int pad = i * 5;
			g2.fillOval(cx - size / 2 - pad, cy - size / 2 - pad, size + pad * 2, size + pad * 2);
		}
		// shackle
		g2.setColor(METAL_SILVER_HI);
		g2.setStroke(new BasicStroke(5f));
		g2.drawArc(cx - size / 3, cy - size, size * 2 / 3, size * 2 / 3, 0, 180);
		g2.setColor(METAL_SILVER_LO);
		g2.setStroke(new BasicStroke(2f));
		g2.drawArc(cx - size / 3 + 2, cy - size + 2, size * 2 / 3 - 4, size * 2 / 3 - 4, 0, 180);
		// body
		g2.setPaint(new GradientPaint(cx - size / 2f, cy - size / 2f, METAL_GOLD_HI,
			cx + size / 2f, cy + size / 2f, METAL_GOLD_LO));
		g2.fillRoundRect(cx - size / 2, cy - size / 2, size, size, 8, 8);
		g2.setColor(withAlpha(Color.BLACK, 0.4f));
		g2.setStroke(new BasicStroke(1.4f));
		g2.drawRoundRect(cx - size / 2, cy - size / 2, size, size, 8, 8);
		g2.setColor(new Color(70, 52, 14));
		g2.fillOval(cx - 4, cy - 6, 8, 8);
		g2.fillRect(cx - 2, cy, 4, 8);
	}

	/**
	 * Two chains wrapped around the closed ornate chest, each held shut by its
	 * own padlock on the front. A lock bursts; the chain it was holding hangs
	 * slack for a beat and only then whips away (rotate + fling with gravity).
	 *
	 * <p>The OUTER chain goes first. Chain 1 is drawn second, so it lies over
	 * chain 0 where they cross, so it is the outer one, so its lock is the one
	 * that can be reached and the one that breaks first - you cannot unwrap the
	 * inner chain while the outer is still pinning it down. That is the kind of
	 * wrong that reads instantly even when nobody can say why.
	 *
	 * @param firstBreakMs when the outer chain's lock bursts
	 * @param breakGapMs   how long after that the inner one follows
	 */
	static void drawChains(Graphics2D g2, int cx, int cy, int w, int h, long el,
		long firstBreakMs, long breakGapMs) {
		int lockSize = Math.max(15, w / 9);
		long[] since = new long[2];
		double[][] at = new double[2][];
		for (int k = 0; k < 2; k++) {
			long breakAt = lockBreakMs(k, firstBreakMs, breakGapMs);
			since[k] = el - breakAt;
			// frozen at the break: the wreckage falls from where the lock WAS,
			// and does not keep riding a chain it is no longer attached to
			at[k] = chainPointAt(cx, cy, w, h, k == 0 ? 1 : -1, LOCK_T,
				Math.min(el, breakAt), k);
		}

		// the bow of each shackle, so the chain can run in FRONT of it
		for (int k = 0; k < 2; k++) {
			if (since[k] < 0) {
				drawLockBow(g2, at[k][0], at[k][1], lockSize, k == 0 ? 1 : -1, el, k);
			}
		}
		for (int k = 0; k < 2; k++) {
			int dir = k == 0 ? 1 : -1;
			long t = since[k] - LOCK_TO_WHIP_MS;
			if (t < 0) {
				// between the lock giving and the chain letting go, the tension
				// it was under comes out as slack - the chain sags and swings
				// wider for a beat before it goes
				drawChainDiagonal(g2, cx, cy, w, h, dir, 1f, 0, k, el,
					clamp01f(since[k] / (float) LOCK_TO_WHIP_MS) * 0.30f, true);
				continue;
			}
			if (t > 650) {
				continue;
			}
			float u = t / 650f;
			double ts = t / 1000.0;
			int off = (int) (ts * 320) * dir;
			int drop = (int) (460 * ts * ts);
			// a chain coming loose goes slack before it is clear of the box, so
			// the whip is a rigid throw plus a much larger travelling wave
			drawChainDiagonal(g2, cx + off, cy + drop, w, h, dir, 1f - u,
				(float) (u * 1.4 * dir), k, el, u, false);
		}
		// and the near leg and body back over the chain, closing the U on it
		for (int k = 0; k < 2; k++) {
			if (since[k] < 0) {
				drawLockFront(g2, at[k][0], at[k][1], lockSize, k == 0 ? 1 : -1, el, k);
			}
			else if (since[k] < LOCK_BREAK_MS) {
				drawLockBreak(g2, at[k][0], at[k][1], lockSize, since[k]);
			}
		}
	}

	/**
	 * When chain {@code k}'s padlock bursts. Chain 1 is drawn second, so it lies
	 * over chain 0 where they cross, so it is the OUTER one - and the outer lock
	 * is the one you can get at. Freeing the inner chain first would have it
	 * slide out from under a chain still pinning it down.
	 */
	static long lockBreakMs(int k, long firstBreakMs, long breakGapMs) {
		return firstBreakMs + (k == 1 ? 0 : breakGapMs);
	}

	/**
	 * The closed chest's outer silhouette - lid skirt plus body - as one shape.
	 * Used to clip the resting chains so their ends pass behind the box instead
	 * of hanging in the air beside it. Package-private so the test can pin it
	 * against {@link #chainEnds}: the layout fractions now have two readers, and
	 * a chain whose run leaves the silhouette is a chain the clip deletes.
	 */
	static Shape closedSilhouette(int cx, int cy, int w, int h) {
		double x = cx - w / 2.0;
		double top = cy - h / 2.0;
		double bottom = cy + h / 2.0;
		double skirtTop = top + h * LID_TOP_FRAC;
		double frontTop = skirtTop + h * LID_FRONT_FRAC;
		double slant = w * SLANT_FRAC;
		double botHalf = w * SKIRT_WIDEN / 2.0;
		Path2D.Double p = new Path2D.Double();
		p.moveTo(x, skirtTop);
		p.lineTo(x + w, skirtTop);
		p.lineTo(cx + botHalf, frontTop);
		p.lineTo(cx - botHalf, frontTop);
		p.closePath();
		p.moveTo(x, frontTop);
		p.lineTo(x + w, frontTop);
		p.lineTo(x + w - slant, bottom);
		p.lineTo(x + slant, bottom);
		p.closePath();
		return p;
	}

	/**
	 * Where chain {@code dir} enters and leaves the chest, before bow and sway.
	 *
	 * <p>Side to side, NOT corner to corner. A chain that ends on a corner could
	 * just as well be lying flat on the picture; one that runs off the left edge
	 * and off the right edge can only be continuing around the back. It still
	 * crosses the lid seam on the way, so it is still what holds the lid shut.
	 */
	static double[] chainEnds(int cx, int cy, int w, int h, int dir) {
		return new double[]{
			cx - dir * (w / 2.0),
			cy - h / 2.0 + h * (LID_TOP_FRAC + LID_FRONT_FRAC * 0.55),
			cx + dir * (w / 2.0),
			cy + h / 2.0 - h * 0.10};
	}

	/**
	 * How far the chain sits off its straight run at {@code c}, measured along
	 * the path normal. Three terms: the bow out over the front face, a slow
	 * swing, and a fast rattle at the ORNATE strain frequency so the chain
	 * visibly LAGS the box it is tied to instead of moving with it. All three
	 * are pinned to zero where the chain bites the corners.
	 *
	 * <p>Shared with the padlocks, which hang off the chain and so have to ride
	 * exactly this curve - a lock floating beside its own chain is the tell that
	 * gives the whole thing away.
	 */
	private static double chainNormal(double c, int w, int h, long el, int seed, float slack) {
		double env = Math.sin(c * Math.PI);
		double swing = (2.2 + 7.0 * slack) * Math.min(1.0, w / 300.0 + 0.4);
		return h * 0.055 * env
			+ swing * env * Math.sin(el * 0.0055 + c * 6.0 + seed * 2.0)
			+ 1.0 * env * Math.sin(el * 0.05 + c * 3.0 + seed);
	}

	/** Where chain {@code dir} actually is at {@code t}, sway and all. */
	private static double[] chainPointAt(int cx, int cy, int w, int h, int dir, double t,
		long el, int seed) {
		double[] e = chainEnds(cx, cy, w, h, dir);
		double dx = e[2] - e[0];
		double dy = e[3] - e[1];
		double len = Math.hypot(dx, dy);
		double n = chainNormal(clamp01(t), w, h, el, seed, 0f) * dir;
		return new double[]{e[0] + dx * t - dy / len * n, e[1] + dy * t + dx / len * n};
	}

	/**
	 * One chain wrapped diagonally around the chest, side to side.
	 *
	 * <p>What makes it read as a chain rather than a dotted line of beads: the
	 * link count comes from the path length divided by a 0.62 pitch, so every
	 * link's end bar lands INSIDE its neighbour's hole. A fixed count breaks
	 * that at every chest size but one. Then the flat links are drawn, the
	 * edge-on ones over them, and the flat links' NEAR arcs back over those - so
	 * each link genuinely threads behind one neighbour and in front of the next.
	 *
	 * <p>What makes it read as going AROUND the box rather than lying on top of
	 * the picture: the path runs past both sides of the silhouette and is
	 * clipped to it, so the ends disappear behind the chest; the last links
	 * before that edge foreshorten and drop into shadow as the band turns the
	 * corner; the run bows out over the front face and the whole chain twists
	 * along its length, so no two links present the same face.
	 *
	 * <p>And what makes it read as loose: it never sits still. A slow swing and
	 * a fast rattle ride the path normal, anchored to zero at both ends, and
	 * {@code slack} opens the swing right up while the chain is being flung.
	 */
	private static void drawChainDiagonal(Graphics2D g2, int cx, int cy, int w, int h,
		int dir, float alpha, float rot, int seed, long el, float slack, boolean wrapped) {
		float a = clamp01f(alpha);
		if (a <= 0.01f) {
			return;
		}
		Graphics2D gc = (Graphics2D) g2.create();
		gc.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		if (wrapped) {
			gc.clip(closedSilhouette(cx, cy, w, h));
		}
		if (rot != 0) {
			gc.rotate(rot * (0.4 + 0.15 * seed), cx, cy);
		}

		double[] ends = chainEnds(cx, cy, w, h, dir);
		double x0 = ends[0];
		double y0 = ends[1];
		double x1 = ends[2];
		double y1 = ends[3];
		double dx = x1 - x0;
		double dy = y1 - y0;
		double len = Math.hypot(dx, dy);
		// times dir, or the two chains bow in OPPOSITE directions - the left-hand
		// one sagging and the right-hand one arching - and their padlocks end up
		// hanging at visibly different heights
		double nx = -dy / len * dir;
		double ny = dx / len * dir;
		// run past both edges so the clip - not the last link - is what ends the
		// chain. A chain that stops exactly at the edge reads as painted on.
		// Constant in both states on purpose: the chain really is longer than
		// the face it crosses, so the flung one is the same length as the
		// wrapped one and the whip does not re-tessellate it on its first frame.
		double ext = 0.15;
		// floors matter: chestW is min(300, cw/3), so a narrow client asks for a
		// much smaller chain and an unfloored ring degenerates into a smear
		double linkLen = Math.max(11, w / 10.0);
		double bar = Math.max(2.2, w / 62.0);
		int links = Math.max(4,
			(int) Math.round(len * (1 + 2 * ext) / (linkLen * 0.62)));

		double[] px = new double[links + 1];
		double[] py = new double[links + 1];
		double[] ang = new double[links + 1];
		double[] halfLen = new double[links + 1];
		double[] halfWid = new double[links + 1];
		float[] shade = new float[links + 1];
		float[] linkA = new float[links + 1];
		// the length hidden behind the box has to come INTO view rather than
		// appear the instant the clip drops, so it fades up over the first
		// ~150ms of the whip - by which point the chain is already moving fast
		float freed = wrapped ? 0f : Math.min(1f, slack / 0.23f);

		for (int i = 0; i <= links; i++) {
			double t = -ext + (1 + 2 * ext) * i / links;
			double c = clamp01(t);
			double env = Math.sin(c * Math.PI);
			double n = chainNormal(c, w, h, el, seed, slack);
			px[i] = x0 + dx * t + nx * n;
			py[i] = y0 + dy * t + ny * n;
			// tangent of the OFFSET path, so links lie along the curve they sit
			// on rather than along the straight run underneath it. Differenced
			// rather than differentiated by hand: chainNormal has three terms and
			// two readers, and a stale derivative would tilt every link silently.
			double dn = (chainNormal(clamp01(t + 0.004), w, h, el, seed, slack)
				- chainNormal(clamp01(t - 0.004), w, h, el, seed, slack)) / 0.008;
			ang[i] = Math.atan2(dy + ny * dn, dx + nx * dn)
				+ (hash01(seed * 37 + i) - 0.5) * 0.10;

			// turning the corner: the band rolls away from the eye, so the last
			// links compress along their own axis and fall into shadow. Gentle
			// on both counts - crush the length and they stop being rings, crush
			// the light and the corner is a black lump instead of dark metal.
			// ...and released along with the rest of it: a chain in mid-air has
			// no corner left to turn, so the squash and the shadow let go as the
			// hidden length fades in
			double turn = (1 - smoothstep(Math.min(c, 1 - c) / 0.10)) * (1 - freed);
			// nearer the bottom is nearer the eye; the front face bows out too
			double s = (0.86 + 0.28 * c) * (1 + 0.10 * env);
			// the chain twists as it runs, so no two links show the same face
			double roll = c * 1.35 + seed * 0.9 + el * 0.0006;
			double open = Math.abs((i & 1) == 0 ? Math.cos(roll) : Math.sin(roll));
			halfLen[i] = (linkLen * s * (1 - 0.34 * turn) - bar) / 2;
			halfWid[i] = Math.max(bar * 0.85, linkLen * s * 0.30 * open - bar / 2);
			shade[i] = (float) (0.58 + 0.42 * (1 - turn));
			linkA[i] = t < 0 || t > 1 ? a * (wrapped ? 1f : freed) : a;
		}

		drawChainShadow(gc, px, py, bar, a);
		for (int pass = 0; pass < 3; pass++) {
			for (int i = 0; i <= links; i++) {
				boolean flat = (i & 1) == 0;
				// flat links, then the edge-on ones on top, then the flat links'
				// near arcs back over the top: that ordering IS the interlock
				if (pass == 0 ? !flat : (pass == 1) == flat) {
					continue;
				}
				if (linkA[i] <= 0.01f) {
					continue;
				}
				chainLink(gc, px[i], py[i], ang[i], halfLen[i], halfWid[i], bar, linkA[i],
					shade[i], pass == 2 ? LINK_NEAR : LINK_FULL);
			}
		}
		gc.dispose();
	}

	/**
	 * Diffuse shadow the chain throws onto the chest face. One soft stroke along
	 * the whole path rather than per-link, which is both cheaper and closer to
	 * how a shadow that far from its caster actually looks.
	 */
	private static void drawChainShadow(Graphics2D gc, double[] px, double[] py,
		double bar, float a) {
		PATH.reset();
		for (int i = 0; i < px.length; i++) {
			if (i == 0) {
				PATH.moveTo(px[i] + bar * 0.55, py[i] + bar * 0.8);
			}
			else {
				PATH.lineTo(px[i] + bar * 0.55, py[i] + bar * 0.8);
			}
		}
		for (int i = 2; i >= 1; i--) {
			gc.setColor(withAlpha(Color.BLACK, a * 0.24f));
			gc.setStroke(new BasicStroke((float) (bar * (1.1 + i * 0.8)),
				BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			gc.draw(PATH);
		}
	}

	/**
	 * One link, drawn in its own rotated frame. {@code halfLen}/{@code halfWid}
	 * are the ellipse the barstock centre follows, so the silhouette runs half a
	 * bar wider than that in every direction and the hole is what is left inside.
	 */
	private static void chainLink(Graphics2D gc, double lx, double ly, double ang,
		double halfLen, double halfWid, double bar, float a, float shade, int mode) {
		AffineTransform old = gc.getTransform();
		gc.translate(lx, ly);
		gc.rotate(ang);
		// the key light is fixed in screen space, so it has to be carried into
		// the link's frame - otherwise every link is lit from its own direction
		double llx = LIGHT_X * Math.cos(ang) + LIGHT_Y * Math.sin(ang);
		double lly = -LIGHT_X * Math.sin(ang) + LIGHT_Y * Math.cos(ang);
		double r = Math.max(halfLen, halfWid) * 0.95;
		Ellipse2D.Double ring = new Ellipse2D.Double(-halfLen, -halfWid,
			halfLen * 2, halfWid * 2);
		Shape body = mode == LINK_NEAR
			? new Arc2D.Double(-halfLen, -halfWid, halfLen * 2, halfWid * 2, 188, 164,
				Arc2D.OPEN)
			: ring;

		if (mode == LINK_FULL) {
			double hw = halfWid * 2 - bar;
			if (hw > 1) {
				// the hole is a window onto the planks, in the link's own shadow
				gc.setColor(withAlpha(Color.BLACK, a * 0.42f));
				gc.fill(new Ellipse2D.Double(-halfLen + bar * 0.5, -halfWid + bar * 0.5,
					halfLen * 2 - bar, hw));
			}
			// contour, so the metal sits ON the wood instead of floating over it.
			// Eased off with the light: a full-strength outline on an already
			// dark link at the far edge just paints a black lump.
			gc.setColor(withAlpha(Color.BLACK, a * 0.5f * (0.55f + 0.45f * shade)));
			gc.setStroke(new BasicStroke((float) bar + 1.1f, BasicStroke.CAP_ROUND,
				BasicStroke.JOIN_ROUND));
			gc.draw(ring);
		}

		barMetal(gc, body, llx, lly, r, bar, a, shade);
		gc.setTransform(old);
	}

	/**
	 * Round barstock, stroked along {@code body}: a gradient around the form
	 * from the key light, then a specular that dies before it reaches the shaded
	 * side. {@code llx,lly} is the light in the shape's own frame and {@code r}
	 * the radius the gradient spans. Shared by the chain links and the padlock
	 * shackles so both are visibly the same steel.
	 */
	private static void barMetal(Graphics2D gc, Shape body, double llx, double lly,
		double r, double bar, float a, float shade) {
		gc.setPaint(new GradientPaint(
			(float) (llx * r), (float) (lly * r), withAlpha(dim(CHAIN_LIGHT, shade), a),
			(float) (-llx * r), (float) (-lly * r), withAlpha(dim(CHAIN_SHADE, shade), a)));
		gc.setStroke(new BasicStroke((float) bar, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		gc.draw(body);

		AffineTransform old = gc.getTransform();
		gc.translate(llx * bar * 0.26, lly * bar * 0.26);
		gc.setPaint(new GradientPaint(
			(float) (llx * r), (float) (lly * r), withAlpha(dim(CHAIN_SPEC, shade), a * 0.85f),
			(float) (llx * r * 0.15), (float) (lly * r * 0.15), withAlpha(CHAIN_SPEC, 0f)));
		gc.setStroke(new BasicStroke((float) (bar * 0.40), BasicStroke.CAP_ROUND,
			BasicStroke.JOIN_ROUND));
		gc.draw(body);
		gc.setTransform(old);
	}

	// --- the padlock on each chain ---
	//
	// Geometry is in units of `size`, in a frame whose origin is the point on
	// the chain the lock hangs from - which is also the middle of the shackle's
	// opening, so the chain runs THROUGH the U rather than past it. The bow and
	// the far leg are painted before the chain and the near leg and body after,
	// so the chain is genuinely inside the shackle and not merely behind a lock
	// parked on top of it.

	private static final double SHACKLE_BAR = 0.15;
	private static final double SHACKLE_R = 0.44;
	// The bow has to clear the chain running through it, and a chain link is
	// half as tall as this whole lock - so the U is deliberately tall. Sized
	// tight and the shackle vanishes behind the very chain it is holding.
	private static final double SHACKLE_TOP = -0.22;  // centre of the bow
	private static final double LOCK_BODY_TOP = 0.34;
	private static final double LOCK_BODY_H = 0.92;

	/** How far the lock has swung on its chain, in radians. */
	private static double lockTilt(long el, int seed) {
		return 0.07 * Math.sin(el * 0.0055 + seed * 2.0 + 0.9);
	}

	/** The bow of the shackle and its far leg: everything the chain runs over. */
	private static void drawLockBow(Graphics2D g2, double lx, double ly, int size,
		int dir, long el, int seed) {
		Graphics2D gl = (Graphics2D) g2.create();
		gl.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		gl.translate(lx, ly);
		gl.rotate(lockTilt(el, seed));
		double bar = size * SHACKLE_BAR;
		double r = size * SHACKLE_R;
		double top = size * SHACKLE_TOP;
		// the far leg is the one on the side the chain climbs towards, because
		// higher on this chest means further away
		double legX = -dir * r;
		Path2D.Double bow = new Path2D.Double();
		bow.moveTo(legX, size * LOCK_BODY_TOP);
		bow.lineTo(legX, top);
		bow.append(new Arc2D.Double(-r, top - r, r * 2, r * 2, dir > 0 ? 180 : 0, dir > 0 ? -180 : 180,
			Arc2D.OPEN), true);
		gl.setColor(withAlpha(Color.BLACK, 0.5f));
		gl.setStroke(new BasicStroke((float) bar + 1.2f, BasicStroke.CAP_ROUND,
			BasicStroke.JOIN_ROUND));
		gl.draw(bow);
		barMetal(gl, bow, LIGHT_X, LIGHT_Y, r, bar, 1f, 0.92f);
		gl.dispose();
	}

	/** The near leg and the body: everything that closes back over the chain. */
	private static void drawLockFront(Graphics2D g2, double lx, double ly, int size,
		int dir, long el, int seed) {
		Graphics2D gl = (Graphics2D) g2.create();
		gl.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		gl.translate(lx, ly);
		gl.rotate(lockTilt(el, seed));
		lockNearLeg(gl, size, dir);
		lockBody(gl, size, 1f);
		gl.dispose();
	}

	private static void lockNearLeg(Graphics2D gl, int size, int dir) {
		double bar = size * SHACKLE_BAR;
		double legX = dir * size * SHACKLE_R;
		Path2D.Double leg = new Path2D.Double();
		leg.moveTo(legX, size * SHACKLE_TOP);
		leg.lineTo(legX, size * (LOCK_BODY_TOP + 0.1));
		gl.setColor(withAlpha(Color.BLACK, 0.5f));
		gl.setStroke(new BasicStroke((float) bar + 1.2f, BasicStroke.CAP_ROUND,
			BasicStroke.JOIN_ROUND));
		gl.draw(leg);
		barMetal(gl, leg, LIGHT_X, LIGHT_Y, bar * 1.6, bar, 1f, 1f);
	}

	/**
	 * The lock body: an extruded side face behind a bevelled front plate, with a
	 * brass escutcheon around the keyhole. The extrusion is what stops it from
	 * reading as a rounded rectangle stuck to the wood.
	 */
	private static void lockBody(Graphics2D gl, int size, float a) {
		double bw = size;
		double bh = size * LOCK_BODY_H;
		double bx = -bw / 2;
		double by = size * LOCK_BODY_TOP;
		int arc = (int) (size * 0.34);
		double dz = size * 0.10;

		// contact shadow on the chest, then the extruded right/bottom faces
		gl.setColor(withAlpha(Color.BLACK, a * 0.42f));
		gl.fillRoundRect((int) (bx + dz * 1.5), (int) (by + dz * 1.7), (int) bw, (int) bh,
			arc, arc);
		gl.setPaint(new GradientPaint((float) bx, (float) by, brighten(LOCK_BODY_LO, 1.6f),
			(float) (bx + bw + dz), (float) (by + bh + dz), dim(LOCK_BODY_LO, 0.7f)));
		gl.fillRoundRect((int) (bx + dz), (int) (by + dz), (int) bw, (int) bh, arc, arc);

		// front plate
		gl.setPaint(new GradientPaint((float) bx, (float) by, LOCK_BODY_HI,
			(float) (bx + bw), (float) (by + bh), LOCK_BODY_LO));
		gl.fillRoundRect((int) bx, (int) by, (int) bw, (int) bh, arc, arc);
		// bevel: a lit band across the top and a bright edge on the top-left
		gl.setPaint(new GradientPaint(0f, (float) by, withAlpha(CHAIN_SPEC, a * 0.30f),
			0f, (float) (by + bh * 0.42), withAlpha(CHAIN_SPEC, 0f)));
		gl.fillRoundRect((int) bx + 1, (int) by + 1, (int) bw - 2, (int) (bh * 0.45), arc, arc);
		gl.setColor(withAlpha(CHAIN_SPEC, a * 0.55f));
		gl.setStroke(new BasicStroke(1.3f));
		gl.drawArc((int) bx + 1, (int) by + 1, arc, arc, 95, 80);
		gl.setColor(withAlpha(Color.BLACK, a * 0.55f));
		gl.drawRoundRect((int) bx, (int) by, (int) bw, (int) bh, arc, arc);

		// scuffs, so the face is a used object and not a swatch
		gl.setColor(withAlpha(CHAIN_SPEC, a * 0.10f));
		gl.setStroke(new BasicStroke(1f));
		gl.drawLine((int) (bx + bw * 0.18), (int) (by + bh * 0.30),
			(int) (bx + bw * 0.44), (int) (by + bh * 0.26));
		gl.drawLine((int) (bx + bw * 0.55), (int) (by + bh * 0.78),
			(int) (bx + bw * 0.84), (int) (by + bh * 0.72));

		// the two holes the shackle enters. Without them the legs simply stop at
		// the body edge and the whole lock reads as a sticker on the chest.
		double hx = size * SHACKLE_R;
		double hr2 = size * SHACKLE_BAR * 0.68;
		for (int s = -1; s <= 1; s += 2) {
			gl.setColor(withAlpha(new Color(9, 9, 12), a * 0.92f));
			gl.fillOval((int) (s * hx - hr2), (int) (by - hr2 * 0.6), (int) (hr2 * 2),
				(int) (hr2 * 1.5));
			gl.setColor(withAlpha(CHAIN_SPEC, a * 0.28f));
			gl.drawArc((int) (s * hx - hr2), (int) (by - hr2 * 0.6), (int) (hr2 * 2),
				(int) (hr2 * 1.5), 195, 150);
		}

		// brass escutcheon, recessed into the face, and the keyhole through it
		double kx = 0;
		double ky = by + bh * 0.54;
		double kr = size * 0.185;
		gl.setColor(withAlpha(Color.BLACK, a * 0.55f));
		gl.fillOval((int) (kx - kr - 1), (int) (ky - kr), (int) (kr * 2 + 2), (int) (kr * 2 + 2));
		gl.setPaint(new GradientPaint((float) (kx - kr), (float) (ky - kr), LOCK_GOLD,
			(float) (kx + kr), (float) (ky + kr), METAL_GOLD_LO));
		gl.fillOval((int) (kx - kr), (int) (ky - kr), (int) (kr * 2), (int) (kr * 2));
		gl.setColor(withAlpha(METAL_GOLD_HI, a * 0.5f));
		gl.setStroke(new BasicStroke(1f));
		gl.drawArc((int) (kx - kr), (int) (ky - kr), (int) (kr * 2), (int) (kr * 2), 70, 130);
		gl.setColor(withAlpha(new Color(12, 9, 5), a));
		double hr = kr * 0.44;
		gl.fillOval((int) (kx - hr), (int) (ky - hr * 1.3), (int) (hr * 2), (int) (hr * 2));
		Path2D.Double slot = new Path2D.Double();
		slot.moveTo(kx - hr * 0.75, ky);
		slot.lineTo(kx + hr * 0.75, ky);
		slot.lineTo(kx + hr * 0.35, ky + kr * 0.95);
		slot.lineTo(kx - hr * 0.35, ky + kr * 0.95);
		slot.closePath();
		gl.fill(slot);
	}

	/**
	 * The lock giving way: a flash, the shackle springing open at the bow and
	 * both halves tumbling off, the body dropping under it, and shrapnel. Pure
	 * function of {@code since} - the ms elapsed since it broke.
	 */
	private static void drawLockBreak(Graphics2D g2, double lx, double ly, int size, long since) {
		float u = clamp01f(since / (float) LOCK_BREAK_MS);
		double ts = since / 1000.0;
		float vis = (float) (1 - smoothstep(Math.max(0, (u - 0.6) / 0.4)));
		Graphics2D gl = (Graphics2D) g2.create();
		gl.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		gl.translate(lx, ly);

		// a bloom, not a ring: struck steel throws light and grit, and a clean
		// expanding outline reads as a vector effect laid over the scene
		if (u < 0.30f) {
			float f = 1 - u / 0.30f;
			for (int i = 3; i >= 1; i--) {
				int rr = (int) (size * (0.30 + i * 0.42) * (1 + (1 - f) * 0.7));
				gl.setColor(withAlpha(i == 1 ? GLOW_HOT : GLOW_WARM, f * f * 0.30f));
				gl.fillOval(-rr, -rr, rr * 2, rr * 2);
			}
		}

		double bar = size * SHACKLE_BAR;
		double r = size * SHACKLE_R;
		double top = size * SHACKLE_TOP;
		for (int s = 0; s < 2; s++) {
			int sgn = s == 0 ? -1 : 1;
			AffineTransform old = gl.getTransform();
			gl.translate(sgn * 230 * ts, -150 * ts + 820 * ts * ts);
			gl.rotate(sgn * ts * 8.5);
			Path2D.Double half = new Path2D.Double();
			half.moveTo(sgn * r, size * LOCK_BODY_TOP);
			half.lineTo(sgn * r, top);
			half.append(new Arc2D.Double(-r, top - r, r * 2, r * 2, sgn > 0 ? 0 : 180,
				sgn > 0 ? 88 : -88, Arc2D.OPEN), true);
			barMetal(gl, half, LIGHT_X, LIGHT_Y, r, bar, vis, 1f);
			gl.setTransform(old);
		}

		AffineTransform old = gl.getTransform();
		gl.translate(28 * ts, 60 * ts + 900 * ts * ts);
		gl.rotate(ts * 2.4);
		lockBody(gl, size, vis);
		gl.setTransform(old);

		// grit, drawn as short trails along its own velocity rather than as dots
		gl.setStroke(new BasicStroke(1.4f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		for (int p = 0; p < 14; p++) {
			float a1 = hash01(p * 151 + 3);
			float a2 = hash01(p * 151 + 4);
			double ang = a1 * Math.PI * 2;
			double sp = 90 + a2 * 260;
			double vx = Math.cos(ang) * sp;
			double vy = Math.sin(ang) * sp + 760 * ts;
			double fx = vx * ts;
			double fy = Math.sin(ang) * sp * ts + 380 * ts * ts;
			double trail = Math.min(7, Math.hypot(vx, vy) * 0.016);
			double m = Math.max(1e-3, Math.hypot(vx, vy));
			gl.setColor(withAlpha((p & 1) == 0 ? CHAIN_SPEC : METAL_GOLD_HI,
				vis * (0.55f + 0.45f * a2)));
			gl.draw(new Line2D.Double(fx, fy,
				fx - vx / m * trail, fy - vy / m * trail));
		}
		gl.dispose();
	}

	// --- palette helpers ---

	private static Color bandHi(Tuning.Chest tier) {
		switch (tier) {
			case RUSTY:
				return METAL_RUST_HI;
			case BATTERED:
				return METAL_WORN_HI;
			case GILDED:
				return METAL_SILVER_HI;
			default:
				return METAL_GOLD_HI;
		}
	}

	private static Color bandLo(Tuning.Chest tier) {
		switch (tier) {
			case RUSTY:
				return METAL_RUST_LO;
			case BATTERED:
				return METAL_WORN_LO;
			case GILDED:
				return METAL_SILVER_LO;
			default:
				return METAL_GOLD_LO;
		}
	}

	/** Tiers with worn (dimmed) wood; Rusty is one visible step shabbier. */
	private static boolean worn(Tuning.Chest tier) {
		return tier == Tuning.Chest.BATTERED || tier == Tuning.Chest.RUSTY;
	}

	// --- math/color utilities (mirrors RevealOverlay's, kept private) ---

	private static double clamp01(double v) {
		return v <= 0 ? 0 : (v >= 1 ? 1 : v);
	}

	private static float clamp01f(float v) {
		return v <= 0 ? 0 : (v >= 1 ? 1 : v);
	}

	private static double smoothstep(double t) {
		t = clamp01(t);
		return t * t * (3 - 2 * t);
	}

	private static double lerp(double a, double b, double t) {
		return a + (b - a) * t;
	}

	private static float hash01(int n) {
		int h = n * 0x9E3779B9;
		h ^= h >>> 16;
		h *= 0x85EBCA6B;
		h ^= h >>> 13;
		return (h & 0x7FFFFFFF) / (float) 0x7FFFFFFF;
	}

	private static Color withAlpha(Color c, float alpha) {
		int a = Math.max(0, Math.min(255, Math.round(alpha * 255f)));
		return new Color(c.getRed(), c.getGreen(), c.getBlue(), a);
	}

	private static Color dim(Color c, float f) {
		return new Color((int) (c.getRed() * f), (int) (c.getGreen() * f), (int) (c.getBlue() * f));
	}

	private static Color brighten(Color c, float f) {
		return new Color(Math.min(255, (int) (c.getRed() * f)),
			Math.min(255, (int) (c.getGreen() * f)),
			Math.min(255, (int) (c.getBlue() * f)));
	}

	private static Color mix(Color a, Color b, float t) {
		float u = clamp01f(t);
		return new Color(
			(int) (a.getRed() + (b.getRed() - a.getRed()) * u),
			(int) (a.getGreen() + (b.getGreen() - a.getGreen()) * u),
			(int) (a.getBlue() + (b.getBlue() - a.getBlue()) * u));
	}
}

package com.gachaman.overlay;

import java.awt.*;
import java.awt.geom.*;
import java.awt.image.*;
import java.io.*;
import javax.imageio.*;

/**
 * Authors the scroll rollers as 9-slice pieces, one set per difficulty tint.
 *
 * <p>Exact rather than approximate: the roller body's gradient runs purely
 * vertically, so its middle is uniform along x and a narrow strip stretches to
 * any scroll width with no distortion. Only the two rounded ends and the end
 * caps are fixed-width, and those are blitted unscaled.
 *
 * <p>The three grain fibres are NOT baked - they are driven by spin, and that
 * is what makes the rods look like they are turning.
 */
public final class RollerArt {
	static final int H = 18;
	static final int CAP_W = 7;
	static final int END = H / 2;
	static final int MID = 8;
	private static final Color WOOD_LIGHT = new Color(168, 128, 76);
	private static final Color WOOD_DARK = new Color(70, 48, 24);
	private static final Color CAP_EDGE = new Color(34, 24, 12, 200);

	static final Color[] TINTS = {
		new Color(120, 200, 120), new Color(240, 200, 80), new Color(240, 130, 60),
		new Color(230, 60, 60), new Color(120, 20, 20),
	};

	static String key(Color tier) {
		return String.format("%06x", tier.getRGB() & 0xFFFFFF);
	}

	private static Color mix(Color a, Color b, float t) {
		return new Color(
			(int) (a.getRed() + (b.getRed() - a.getRed()) * t),
			(int) (a.getGreen() + (b.getGreen() - a.getGreen()) * t),
			(int) (a.getBlue() + (b.getBlue() - a.getBlue()) * t));
	}

	public static void main(String[] a) throws Exception {
		File dir = new File(a[0]);
		dir.mkdirs();
		int w = 120;
		for (Color tier : TINTS) {
			Color hi = mix(WOOD_LIGHT, tier, 0.45f);
			Color lo = mix(WOOD_DARK, tier, 0.30f);
			BufferedImage body = new BufferedImage(w, H, BufferedImage.TYPE_INT_ARGB);
			Graphics2D g = body.createGraphics();
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g.setPaint(new LinearGradientPaint(
				new Point2D.Float(0, 0), new Point2D.Float(0, H),
				new float[]{0f, 0.28f, 0.5f, 0.82f, 1f},
				new Color[]{mix(lo, Color.BLACK, 0.35f), mix(hi, Color.WHITE, 0.55f), hi,
					mix(lo, Color.BLACK, 0.15f), mix(lo, hi, 0.45f)}));
			g.fill(new RoundRectangle2D.Float(0, 0, w, H, H, H));
			g.dispose();
			String k = key(tier);
			ImageIO.write(body.getSubimage(0, 0, END, H), "png", new File(dir, "roller-" + k + "-l.png"));
			ImageIO.write(body.getSubimage(w / 2, 0, MID, H), "png", new File(dir, "roller-" + k + "-m.png"));
			ImageIO.write(body.getSubimage(w - END, 0, END, H), "png", new File(dir, "roller-" + k + "-r.png"));

			int ch = H + 4;
			BufferedImage cap = new BufferedImage(CAP_W, ch, BufferedImage.TYPE_INT_ARGB);
			g = cap.createGraphics();
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g.setPaint(new RadialGradientPaint(
				new Point2D.Float(CAP_W * 0.35f, ch * 0.32f), Math.max(1f, ch * 0.75f),
				new float[]{0f, 1f},
				new Color[]{mix(hi, Color.WHITE, 0.35f), mix(lo, Color.BLACK, 0.25f)}));
			g.fillOval(0, 0, CAP_W, ch);
			g.setColor(CAP_EDGE);
			g.drawOval(0, 0, CAP_W - 1, ch - 1);
			g.dispose();
			ImageIO.write(cap, "png", new File(dir, "roller-" + k + "-cap.png"));
		}
		System.out.println("roller slices written for " + TINTS.length + " tints");
	}

	private RollerArt() {
	}
}

package com.gachaman.overlay;

import java.util.List;
import com.gachaman.*;
import com.gachaman.model.*;
import com.gachaman.service.*;
import com.google.gson.*;
import java.awt.*;
import java.awt.image.*;
import java.io.*;
import java.nio.charset.*;
import java.util.*;
import org.junit.*;

/**
 * The roulette's preferred-weapon caption: the two lines that say what the wheel
 * named and what it is worth.
 *
 * <p>Both lines are load-bearing rather than decorative, and they fail
 * differently. The NAME can leak an internal key that lies about the game state
 * — the key for category 0 is "unarmed", which the game also reports for a
 * lantern, a bucket and a pet rock, so a player holding a fishing rod would be
 * told they are unarmed. The WORTH can quietly go stale: the bonus multiplies
 * the per-kill trickle only, so what it is actually worth depends on the ratio
 * between the kill rate and the completion bonus, and a printed number would go
 * wrong the first time either is retuned with nobody the wiser.
 *
 * <p>Everything here is a pure function of the shipped resource and
 * {@link Tuning}, so none of it needs a client.
 *
 * <p>Explicit {@code java.util.List} import: {@code java.awt.*} is wildcarded
 * below for the font metrics and exports a List of its own.
 */
public class WeaponCaptionTest
{
	/** The shape of the shipped resource, as far as this test cares. */
	private static class ShippedFile
	{
		List<WeaponTypeService.WeaponType> types;
	}

	/**
	 * The taxonomy as SHIPPED, read straight off the classpath.
	 *
	 * <p>Deliberately not via WeaponTypeService: the service's constructor is
	 * package-private to its own package, and going around it also means this
	 * test keeps working if the loading ever changes. What is being pinned is the
	 * file's contents against the caption, and nothing in between.
	 */
	private static List<WeaponTypeService.WeaponType> taxonomy() throws Exception
	{
		try (InputStream in = WeaponCaptionTest.class.getResourceAsStream(
			"/com/gachaman/data/weapon-types.json"))
		{
			Assert.assertNotNull("weapon-types.json is not on the classpath", in);
			ShippedFile file = new Gson().fromJson(
				new InputStreamReader(in, StandardCharsets.UTF_8), ShippedFile.class);
			Assert.assertNotNull("weapon-types.json carries no types", file.types);
			Assert.assertFalse("weapon-types.json is empty", file.types.isEmpty());
			return file.types;
		}
	}

	/**
	 * Every category the wheel can name renders its display name, and NOT its key.
	 *
	 * <p>The taxonomy has a resource test of its own asserting that no display
	 * name contains "unarmed". This is the other end of the same rule: it does not
	 * matter what the resource says if the caption reaches past it for the key,
	 * and this method is the only place in the plugin where a weapon category
	 * becomes words on a player's screen. Walking the whole file rather than the
	 * one interesting entry is what makes it hold for entries added later.
	 */
	@Test
	public void everyShippedCategoryIsNamedByItsDisplayNameNeverItsKey() throws Exception
	{
		int checked = 0;
		for (WeaponTypeService.WeaponType type : taxonomy())
		{
			String line = RevealOverlay.weaponLine(type);
			checked++;
			Assert.assertTrue(type.getKey() + ": the caption must carry the display name '"
				+ type.getDisplayName() + "' — it says: " + line,
				line.contains(type.getDisplayName()));
			Assert.assertFalse(type.getKey() + ": the caption leaked the internal key —"
				+ " the game reports that category for every non-weapon held item, so it"
				+ " must read 'No weapon equipped'. It says: " + line,
				line.toLowerCase(Locale.ROOT).contains("narmed"));
		}
		Assert.assertTrue("walked no categories", checked > 20);
	}

	/** The category-0 entry specifically, since it is the one the rule exists for. */
	@Test
	public void categoryZeroReadsAsNoWeaponEquipped() throws Exception
	{
		WeaponTypeService.WeaponType unarmed = null;
		for (WeaponTypeService.WeaponType type : taxonomy())
		{
			if ("unarmed".equals(type.getKey()))
			{
				unarmed = type;
			}
		}
		Assert.assertNotNull("the taxonomy no longer carries the 'unarmed' key", unarmed);
		Assert.assertEquals("Preferred weapon: No weapon equipped",
			RevealOverlay.weaponLine(unarmed));
	}

	/**
	 * A cycle the wheel named nothing for reads as an absent bonus, never as a
	 * bonus the player let slip.
	 *
	 * <p>Null means the taxonomy resource failed to load — this build's
	 * shortcoming, not the player's — and the preference only ever adds to what
	 * they earn, so nothing was taken from them. Wording it as a loss would invent
	 * a punishment out of a missing file.
	 */
	@Test
	public void noNamedCategoryReadsAsNoBonusAvailable()
	{
		String worth = RevealOverlay.worthLine(null);
		Assert.assertTrue("it must say the bonus is unavailable, and say it plainly: " + worth,
			worth.contains("no bonus available"));
		String both = (RevealOverlay.weaponLine(null) + " " + worth).toLowerCase(Locale.ROOT);
		for (String blame : new String[]{"miss", "fail", "lost", "wasted", "unlucky", "should"})
		{
			Assert.assertFalse("the caption blames the player with '" + blame + "': " + both,
				both.contains(blame));
		}
		Assert.assertFalse("even with nothing named, the caption must not say 'unarmed'",
			both.contains("narmed"));
	}

	/**
	 * The worth is DERIVED from the constants that decide it.
	 *
	 * <p>Computed here the long way round — the whole contract's pay with the
	 * bonus against the whole contract's pay without it — so it agrees with the
	 * implementation only if both are reading the same three tuning values. A
	 * printed literal, or a formula that quietly dropped the completion bonus out
	 * of the denominator, fails this.
	 */
	@Test
	public void theWorthIsDerivedFromTuningRatherThanWrittenDown()
	{
		for (TaskDifficulty difficulty : TaskDifficulty.values())
		{
			double kills = (difficulty.getMinKills() + difficulty.getMaxKills()) / 2.0;
			double perKill = Tuning.PER_KILL_GC.get(difficulty);
			double completion = Tuning.COMPLETION_GC.get(difficulty);
			double plain = kills * perKill + completion;
			double bonused = kills * perKill * Tuning.WEAPON_BONUS_MULT + completion;
			Assert.assertEquals(difficulty.getDisplayName(),
				(int) Math.round(100 * (bonused - plain) / plain),
				RevealOverlay.weaponWorthPct(difficulty));
		}
	}

	/**
	 * The claim the caption is actually making: this is worth little on the bottom
	 * rung and a lot on the top one.
	 *
	 * <p>If that ever stops being true the caption stops being honest, and the
	 * player who chose a slower weapon on the strength of it has been misled. The
	 * ladder is monotone because kill count and per-kill rate both climb faster
	 * than the completion bonus does; pinning it means a retune that flattens the
	 * curve has to come back here and rewrite the sentence.
	 */
	@Test
	public void theBonusIsWorthLeastOnEasyAndMostOnInsane()
	{
		TaskDifficulty[] ladder = TaskDifficulty.values();
		for (int i = 1; i < ladder.length; i++)
		{
			Assert.assertTrue(ladder[i].getDisplayName() + " is not worth more than "
					+ ladder[i - 1].getDisplayName(),
				RevealOverlay.weaponWorthPct(ladder[i])
					> RevealOverlay.weaponWorthPct(ladder[i - 1]));
		}
		Assert.assertTrue("Easy is no longer a thin margin, so the caveat line lies",
			RevealOverlay.weaponWorthPct(TaskDifficulty.EASY) <= 10);
		Assert.assertTrue("Insane is no longer a large gain, so the caption oversells it",
			RevealOverlay.weaponWorthPct(TaskDifficulty.INSANE) >= 20);
	}

	/**
	 * The worth line names both ends of the ladder and says which half of the pay
	 * the multiplier touches.
	 *
	 * <p>"x1.5" on its own reads as half again as much money. It is half again as
	 * much of the per-kill trickle, and the completion bonus — the larger half of
	 * every contract — is untouched. The sentence has to carry that or the number
	 * is worse than no number.
	 */
	@Test
	public void theWorthLineNamesTheKillHalfAndBothEndsOfTheLadder()
	{
		String worth = RevealOverlay.worthLine(
			new WeaponTypeService.WeaponType("scimitar", "Scimitar", 3901,
				Collections.singleton(AttackStyle.MELEE), true, null));
		Assert.assertTrue("it must say the bonus is on kill GC: " + worth,
			worth.contains("kill GC"));
		Assert.assertTrue("it must name the multiplier: " + worth,
			worth.contains(String.valueOf(Tuning.WEAPON_BONUS_MULT)));
		for (TaskDifficulty end : new TaskDifficulty[]{TaskDifficulty.EASY, TaskDifficulty.INSANE})
		{
			Assert.assertTrue("it must name " + end.getDisplayName() + ": " + worth,
				worth.contains(end.getDisplayName()));
			Assert.assertTrue("it must carry " + end.getDisplayName() + "'s figure: " + worth,
				worth.contains("+" + RevealOverlay.weaponWorthPct(end) + "%"));
		}
	}

	/**
	 * No caption line is wider than the canvas it is centred on.
	 *
	 * <p>Centred text is not clipped anywhere in this ceremony, so a line too wide
	 * for the canvas runs off BOTH edges and loses its beginning and its end at
	 * once. The bound is the fixed-mode client's 765px canvas less a margin, which
	 * is the smallest screen any of this is drawn on.
	 */
	@Test
	public void everyCaptionLineFitsTheNarrowestClient() throws Exception
	{
		BufferedImage img = new BufferedImage(8, 8, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		try
		{
			int budget = 765 - 40;
			FontMetrics body = g.getFontMetrics(new Font(Font.SANS_SERIF, Font.BOLD, 14));
			FontMetrics small = g.getFontMetrics(new Font(Font.SANS_SERIF, Font.PLAIN, 11));
			for (WeaponTypeService.WeaponType type : taxonomy())
			{
				String name = RevealOverlay.weaponLine(type);
				Assert.assertTrue("too wide for a 765px canvas: " + name,
					body.stringWidth(name) <= budget);
			}
			for (String line : new String[]{
				RevealOverlay.worthLine(null),
				RevealOverlay.worthLine(taxonomy().get(0))})
			{
				Assert.assertTrue("too wide for a 765px canvas: " + line,
					small.stringWidth(line) <= budget);
			}
		}
		finally
		{
			g.dispose();
		}
	}
}

package com.gachaman.overlay;

import com.gachaman.*;
import java.io.*;
import java.nio.charset.*;
import java.nio.file.*;
import java.util.*;
import org.junit.*;

/**
 * Every side effect RevealOverlay raises is raised from the client thread.
 *
 * <p>A source scan, on the {@link com.gachaman.ui.panel.PanelWordingScanTest}
 * precedent, and for the same reason: the sibling behavioural test
 * ({@code ConsignmentCeremonyTest.theAnswerIsOnlyEverGivenFromTheClientThread})
 * can only prove the hop for the one path it can drive. Driving a REROLL needs a
 * funded state, a live card database, a pending chest and a token to spend,
 * while the invariant is one line at each call site. Delete the hop from
 * {@code applyReroll} and every behavioural test in this package still passes —
 * which is precisely the gap this closes.
 *
 * <p>The reroll is the headline. {@code chestService.rerollSlot} rebuilds the
 * slot's pool through {@code poolFor} -> {@code isReachable}, which asks the
 * client for four real skill levels; raised from the AWT thread that delivered
 * the click, that is a read of game state racing the game thread writing it.
 *
 * <p>Scans also catch code that does not exist yet, which is the point: the next
 * person to add a service call to this overlay is who this is written for. Tests
 * cost no token budget.
 */
public class RevealHopScanTest
{
	/**
	 * Calls that must open a hop of their own, named in full rather than as a
	 * bare {@code .rerollSlot(} — a guard that fires on somebody else's correct
	 * code is a guard that gets deleted.
	 *
	 * <p>{@code runAction} is in this list because it IS the rest of them: the
	 * switch it carries commits chests, accepts contracts and answers
	 * Consignments, and it is private precisely so that the hop in
	 * {@code executeAction} is the only door into it. Pinning the door is
	 * stronger than pinning each arm, and it cannot drift as arms are added.
	 */
	private static final String[] MUST_HOP = {
		"chestService.rerollSlot(",
		"chestService.claimDeed(",
		"runAction(",
	};

	/**
	 * How far above the call the hop may open. Every one of them sits on the
	 * first line of its own lambda, so this is slack, not licence — a call that
	 * needed a wider window would be a call with logic ahead of it inside the
	 * lambda, and that logic is what the window is meant to make visible.
	 */
	private static final int WINDOW = 3;

	private static boolean isComment(String line)
	{
		String trimmed = line.trim();
		return trimmed.startsWith("//") || trimmed.startsWith("*") || trimmed.startsWith("/*");
	}

	private static List<String> overlaySource() throws IOException
	{
		Path root = SourceHygieneTest.sourceRoot();
		Assert.assertNotNull("could not locate src/main/java from "
			+ Paths.get("").toAbsolutePath(), root);
		Path file = root.resolve("com").resolve("gachaman").resolve("overlay")
			.resolve("RevealOverlay.java");
		Assert.assertTrue("RevealOverlay.java is not at " + file, Files.isRegularFile(file));
		return Files.readAllLines(file, StandardCharsets.UTF_8);
	}

	@Test
	public void everyCallThatReachesTheClientIsMadeFromTheClientThread() throws IOException
	{
		List<String> lines = overlaySource();
		List<String> offenders = new ArrayList<>();
		int calls = 0;
		for (int i = 0; i < lines.size(); i++)
		{
			String line = lines.get(i);
			// the declaration of runAction is not a call to it
			if (isComment(line) || line.contains("private void runAction("))
			{
				continue;
			}
			boolean guarded = false;
			for (String call : MUST_HOP)
			{
				guarded |= line.contains(call);
			}
			if (!guarded)
			{
				continue;
			}
			calls++;
			boolean hopped = false;
			for (int back = i; back >= Math.max(0, i - WINDOW); back--)
			{
				hopped |= lines.get(back).contains("clientThread.invoke");
			}
			if (!hopped)
			{
				offenders.add("RevealOverlay.java:" + (i + 1) + "  " + line.trim());
			}
		}
		Assert.assertEquals("a ceremony side effect reaches live game state from the"
			+ " AWT thread the click arrived on", Collections.emptyList(), offenders);
		Assert.assertTrue("the guard is only real while these calls exist",
			calls >= MUST_HOP.length);
	}

	/**
	 * The teardown abandon is the deliberate exception, pinned so that
	 * "everything hops" cannot be tidied into being true.
	 *
	 * <p>{@code consignmentService.abandon()} clears the service's own live offer
	 * and logs. No game state, nothing submitted to the bus and so nothing
	 * drained — there is no Client beneath it. It runs in {@code reset()}, which
	 * shutDown calls on the AWT thread immediately before the bus is cleared, so
	 * hopping it would leave the last chance to release an unanswered offer
	 * queued against a plugin already being taken apart.
	 */
	@Test
	public void theTeardownAbandonIsDeliberatelyNotHopped() throws IOException
	{
		List<String> lines = overlaySource();
		int start = -1;
		for (int i = 0; i < lines.size(); i++)
		{
			if (lines.get(i).contains("public void reset()"))
			{
				start = i;
				break;
			}
		}
		Assert.assertTrue("reset() is gone from RevealOverlay", start >= 0);

		boolean abandoned = false;
		for (int i = start; i < lines.size(); i++)
		{
			// one tab and a brace: the end of the method, not of a block inside it
			if (i > start && lines.get(i).equals("\t}"))
			{
				break;
			}
			if (isComment(lines.get(i)))
			{
				continue;
			}
			Assert.assertFalse("RevealOverlay.java:" + (i + 1) + " the teardown abandon must"
					+ " stay synchronous; a deferred one never runs, see reset()",
				lines.get(i).contains("clientThread.invoke"));
			abandoned |= lines.get(i).contains("consignmentService.abandon()");
		}
		Assert.assertTrue("reset() no longer abandons the parked offer", abandoned);
	}
}

package com.gachaman;

import java.nio.charset.*;
import java.nio.file.*;
import org.junit.*;

/**
 * The three commissioned features each need a hook set from
 * {@link GachamanPlugin}, and every one of them fails SILENTLY when it is
 * missing. That is what makes them worth a test rather than a code review.
 *
 * <ul>
 *   <li>No {@code setPresenter} and {@code ConsignmentService.offerOrRoll} takes
 *       the ordinary roll every single time. No error, no log line, no chat
 *       notice — the Consignment simply never appears, and the only way to
 *       notice is to know it should have.</li>
 *   <li>No {@code setDealer} and {@code TollService.purchase} log-warns and
 *       returns null, which the shop panel renders as "a reveal may already be
 *       in progress" — a message that names the wrong cause forever.</li>
 *   <li>No {@code drainOwedRoll} and a style roll owed by a Consignment offer
 *       that died with the client is never taken. The cycle self-heals on the
 *       next contract, so even this one is invisible rather than broken.</li>
 *   <li>No {@code abandon} on the profile switch and a live offer leaks across
 *       accounts.</li>
 * </ul>
 *
 * <p>A source scan, following {@code UnassignCallSiteTest}'s precedent and for
 * the same reason: standing the real plugin up needs a Client, a ConfigManager,
 * an OverlayManager and the whole injector, while the invariant here is simply
 * "these four calls exist in this file". Scans cost nothing — the Hub bot counts
 * only src/main/java.
 */
public class FeatureWiringTest
{
	private static String plugin() throws Exception
	{
		return new String(Files.readAllBytes(
			Paths.get("src/main/java/com/gachaman/GachamanPlugin.java")), StandardCharsets.UTF_8);
	}

	/**
	 * Strips comments before matching, so that a call which exists only inside a
	 * javadoc block explaining that it OUGHT to exist cannot satisfy the test.
	 * That is a real failure mode here: every one of these hooks was described in
	 * prose in a handover note before it was written.
	 */
	private static String code() throws Exception
	{
		return plugin()
			.replaceAll("(?s)/\\*.*?\\*/", "")
			.replaceAll("//[^\n]*", "");
	}

	@Test
	public void theConsignmentHasAPresenter() throws Exception
	{
		Assert.assertTrue("GachamanPlugin must call consignmentService.setPresenter(revealOverlay) —"
				+ " without it the Consignment silently never appears",
			code().contains("consignmentService.setPresenter("));
	}

	@Test
	public void theTollHasAPullDealer() throws Exception
	{
		Assert.assertTrue("GachamanPlugin must call tollService.setDealer(...) —"
				+ " without it every Toll purchase refuses and blames a pending reveal",
			code().contains("tollService.setDealer("));
	}

	@Test
	public void theOwedStyleRollIsDrainedAtLogin() throws Exception
	{
		String code = code();
		Assert.assertTrue("GachamanPlugin must call consignmentService.drainOwedRoll(...)",
			code.contains("consignmentService.drainOwedRoll("));

		// It must sit in the state-load block, not the LOGGED_IN branch: state is
		// still null at LOGGED_IN, so a drain fired there no-ops forever. The
		// recoverPending() call is the anchor for that block.
		int drain = code.indexOf("consignmentService.drainOwedRoll(");
		int recover = code.indexOf("chestService.recoverPending()");
		Assert.assertTrue("recoverPending() should be present as the state-load anchor", recover > 0);
		Assert.assertTrue("drainOwedRoll must sit in the state-load block beside recoverPending(),"
				+ " where state actually exists — not in the LOGGED_IN branch",
			drain > recover && drain - recover < 900);
	}

	@Test
	public void aProfileSwitchAbandonsALiveConsignment() throws Exception
	{
		Assert.assertTrue("GachamanPlugin must call consignmentService.abandon() when the RS profile"
				+ " changes — ceremonyBus.clear() cannot reach the service's own live offer",
			code().contains("consignmentService.abandon()"));
	}

	/**
	 * The Toll's dealer must be ChestService's tier-scoped opener specifically.
	 * Routing it at {@code openThemedChest} would compile and would silently deal
	 * an ordinary chest, because {@code setMembers()} returns empty for a tier key
	 * and the pool falls back to every card in the game.
	 */
	@Test
	public void theTollDealerIsTheTierScopedOpener() throws Exception
	{
		Assert.assertTrue("the Toll must be dealt by ChestService.openTollChest",
			code().contains("openTollChest"));
		Assert.assertFalse("openThemedChest must never be the Toll's dealer — a tier key is not a"
				+ " set tag, so it would fall back to the all-cards pool",
			code().contains("tollService.setDealer(chestService::openThemedChest"));
	}
}

package com.gachaman;

import java.util.*;
import org.junit.*;

/**
 * ::gachachest's tier argument must fold case the same way on every client.
 *
 * <p>Turkish and Azeri fold "i" to the DOTTED capital "İ", so under those
 * locales "gilded".toUpperCase() is "GİLDED" — a string no Tuning.Chest
 * constant matches. valueOf threw IllegalArgumentException and the command
 * died for those players. Locale.ROOT is the fix; this pins it by forcing the
 * hostile locale rather than trusting the machine the suite happens to run on.
 */
public class DebugCommandLocaleTest
{
	private Locale previous;

	@Before
	public void forceTurkishDefault()
	{
		previous = Locale.getDefault();
		Locale.setDefault(Locale.forLanguageTag("tr"));
	}

	@After
	public void restoreDefault()
	{
		// JUnit 4 runs the whole suite in one JVM and other code folds case
		// with the default locale (CardDatabase's name index, for one), so
		// leaving Turkish installed would break tests unrelated to this file
		Locale.setDefault(previous);
	}

	@Test
	public void everyChestTierParsesUnderAHostileLocale()
	{
		for (Tuning.Chest tier : Tuning.Chest.values())
		{
			String typed = tier.name().toLowerCase(Locale.ROOT);
			Assert.assertEquals("::gachachest " + typed,
				tier, GachamanPlugin.chestArg(new String[]{typed}));
		}
	}

	@Test
	public void mixedCaseStillParses()
	{
		Assert.assertEquals(Tuning.Chest.GILDED,
			GachamanPlugin.chestArg(new String[]{"GiLdEd"}));
	}

	@Test
	public void noArgumentMeansBattered()
	{
		Assert.assertEquals(Tuning.Chest.BATTERED, GachamanPlugin.chestArg(new String[0]));
	}

	@Test
	public void theDefaultLocaleFoldIsWhatWasBroken()
	{
		// the shape of the defect itself, so nobody "tidies" the explicit
		// Locale.ROOT back out of chestArg on the grounds that it looks noisy
		Assert.assertNotEquals("GILDED", "gilded".toUpperCase());
		Assert.assertEquals("GILDED", "gilded".toUpperCase(Locale.ROOT));
	}
}

package com.gachaman.tools;

import com.gachaman.model.*;
import com.gachaman.service.*;
import com.gachaman.service.WeaponTypeService.WeaponType;
import com.google.gson.*;
import java.io.*;
import java.nio.charset.*;
import java.nio.file.*;
import java.util.*;
import net.runelite.api.gameval.*;

/**
 * Authors {@code weapon-types.json}: the weapon CATEGORY taxonomy the Preferred
 * Weapon bonus is named from.
 *
 * <p>The dbrow ids are pure data and belong in a resource, but writing them
 * there by hand would mean three dozen four-digit magic numbers with nothing
 * checking them — and a mistyped one does not fail loudly. It resolves to no
 * type, so that category simply never pays the bonus, for everyone, forever,
 * with no error anywhere. So they are spelled here as
 * {@link DBTableID.CombatInterfaceWeaponCategory.Row} constants — where the
 * compiler still verifies every name against the live API — and this tool
 * projects them into the resource the plugin actually reads. Exactly the
 * arrangement {@link AttackAnims} uses for the animation ids.
 *
 * <p>{@code WeaponTypeResourceTest} asserts the shipped resource still matches
 * this declaration, and additionally that the declaration still covers EVERY
 * {@code Row} constant the API defines — so a RuneLite update that adds a
 * category fails the build with its name rather than quietly shipping a
 * category the wheel can never name.
 *
 * <p>Regenerate by running this class's {@code main} on the test classpath.
 * There is no {@code ./gradlew weaponTypes} task yet; see the note in
 * build.gradle's sibling tasks (attackAnims, iconArt, ceremonyArt).
 */
public final class WeaponTypes {
	private static final Set<AttackStyle> MELEE = EnumSet.of(AttackStyle.MELEE);
	private static final Set<AttackStyle> RANGED = EnumSet.of(AttackStyle.RANGED);
	private static final Set<AttackStyle> MAGIC = EnumSet.of(AttackStyle.MAGIC);
	/**
	 * The hybrid staves: named by the MELEE wheel and the MAGIC wheel both.
	 *
	 * <p>Deliberate, and it is what rescues magic from a two-item pool — without
	 * them magic could name only the powered staves and casting itself. Which
	 * mode such a staff is in is never resolved, and never has to be: the bonus
	 * pays only on a compliant kill, and a kill in the wrong style is tainted
	 * and pays zero before any multiplier is reached. So a magic player who bash
	 * their way through a kill with a bladed staff has already lost the whole
	 * award, not merely the 1.5x.
	 */
	private static final Set<AttackStyle> HYBRID_STAFF = EnumSet.of(AttackStyle.MELEE, AttackStyle.MAGIC);
	/** Never named by any wheel. */
	private static final Set<AttackStyle> NONE = EnumSet.noneOf(AttackStyle.class);

	private static final String NOTE = "Authored by com.gachaman.tools.WeaponTypes from"
		+ " DBTableID.CombatInterfaceWeaponCategory.Row constants. Do not hand-edit:"
		+ " WeaponTypeResourceTest pins this file to those constants, and the keys are"
		+ " persisted in player saves. dbrow -1 is the SPELL_CAST pseudo-type, which is"
		+ " com mode 4 (the autocast slot) and has no row of its own.";

	private WeaponTypes() {
	}

	private static WeaponType offerable(String key, String displayName, int dbrow,
		Set<AttackStyle> offerIn) {
		return new WeaponType(key, displayName, dbrow, offerIn, true, null);
	}

	private static WeaponType excluded(String key, String displayName, int dbrow, String reason) {
		return new WeaponType(key, displayName, dbrow, NONE, false, reason);
	}

	/**
	 * The taxonomy, in dbrow order.
	 *
	 * <p>Listed in dbrow order rather than grouped by pool so that this file
	 * lines up one-to-one with the {@code Row} class itself: when the API adds a
	 * category, a {@code javap} of {@code Row} diffs straight against this list
	 * and the newcomer is obvious. The pool each entry belongs to is the trailing
	 * argument, so nothing is lost by not grouping — the styles interleave.
	 *
	 * <p>The order is also the order the wheel's pools are built in, so a seeded
	 * roll is reproducible from the shipped file alone.
	 *
	 * <p>Every {@code Row} constant appears exactly once, offerable or not.
	 * Silence is not an option here: a category left out of the file is
	 * indistinguishable at runtime from one nobody has heard of, and the whole
	 * value of the exclusions is that somebody looked at each one and wrote down
	 * why.
	 */
	public static List<WeaponType> types() {
		List<WeaponType> types = new ArrayList<>();

		// "unarmed" is the key; the NAME is "No weapon equipped" and must stay
		// that way. The game reports this same category for every non-weapon
		// held item — a bucket of water, a lantern, a clue scroll — so telling
		// the player they are "unarmed" while they hold something would be a lie
		// about what is in their hands. It is a real, nameable category all the
		// same: fists are a legitimate way to fight, and the wheel may say so.
		types.add(offerable("unarmed", "No weapon equipped",
			DBTableID.CombatInterfaceWeaponCategory.Row.COMBAT_INTERFACE_UNARMED, MELEE));
		types.add(offerable("axe", "Axes",
			DBTableID.CombatInterfaceWeaponCategory.Row.COMBAT_INTERFACE_AXE, MELEE));
		types.add(offerable("blunt", "Blunt weapons",
			DBTableID.CombatInterfaceWeaponCategory.Row.COMBAT_INTERFACE_BLUNT, MELEE));
		types.add(offerable("blunt_bludgeon", "Bludgeons",
			DBTableID.CombatInterfaceWeaponCategory.Row.COMBAT_INTERFACE_BLUNT_BLUDGEON, MELEE));

		types.add(offerable("bow", "Bows",
			DBTableID.CombatInterfaceWeaponCategory.Row.COMBAT_INTERFACE_BOW, RANGED));

		types.add(offerable("claw", "Claws",
			DBTableID.CombatInterfaceWeaponCategory.Row.COMBAT_INTERFACE_CLAW, MELEE));

		types.add(offerable("crossbow", "Crossbows",
			DBTableID.CombatInterfaceWeaponCategory.Row.COMBAT_INTERFACE_CROSSBOW, RANGED));

		// tri-style: the same weapon fights with melee, ranged and magic, and the
		// varbit reports only the category — never which of the three stances is
		// live. Naming it would mean paying 1.5x on kills the preference cannot
		// actually verify
		types.add(excluded("flamer", "Salamanders",
			DBTableID.CombatInterfaceWeaponCategory.Row.COMBAT_INTERFACE_FLAMER,
			"tri-style: the varbit reports the category, never which of the three"
				+ " stances is in use"));

		types.add(offerable("grenade", "Chinchompas",
			DBTableID.CombatInterfaceWeaponCategory.Row.COMBAT_INTERFACE_GRENADE, RANGED));

		// the trap in the whole taxonomy: it reads as a ranged category and is
		// actually swung. A ranged week that named it would be paying a melee
		// bonus, and a player fighting to the letter of the offer would be
		// tainting every kill
		types.add(excluded("gun", "Guns",
			DBTableID.CombatInterfaceWeaponCategory.Row.COMBAT_INTERFACE_GUN,
			"reads as ranged but is fought as melee — a ranged wheel naming it would"
				+ " ask the player to break their own style lock"));

		types.add(offerable("hacksword", "Slash swords",
			DBTableID.CombatInterfaceWeaponCategory.Row.COMBAT_INTERFACE_HACKSWORD, MELEE));
		types.add(offerable("heavysword", "Two-handed swords",
			DBTableID.CombatInterfaceWeaponCategory.Row.COMBAT_INTERFACE_HEAVYSWORD, MELEE));
		types.add(excluded("heavysword_large", "Colossal blades",
			DBTableID.CombatInterfaceWeaponCategory.Row.COMBAT_INTERFACE_HEAVYSWORD_LARGE,
			"too narrow a category to hand a player for a whole style cycle"));
		types.add(offerable("pickaxe", "Pickaxes",
			DBTableID.CombatInterfaceWeaponCategory.Row.COMBAT_INTERFACE_PICKAXE, MELEE));
		types.add(offerable("polearm", "Polearms",
			DBTableID.CombatInterfaceWeaponCategory.Row.COMBAT_INTERFACE_POLEARM, MELEE));
		types.add(excluded("chargespear", "Charged spears",
			DBTableID.CombatInterfaceWeaponCategory.Row.COMBAT_INTERFACE_CHARGESPEAR,
			"the client special-cases this category's styles (see StyleTracker), and it"
				+ " is too narrow to hand a player for a whole style cycle"));
		types.add(offerable("polestaff", "Polestaves",
			DBTableID.CombatInterfaceWeaponCategory.Row.COMBAT_INTERFACE_POLESTAFF, MELEE));
		types.add(offerable("scythe", "Scythes",
			DBTableID.CombatInterfaceWeaponCategory.Row.COMBAT_INTERFACE_SCYTHE, MELEE));
		types.add(offerable("spear", "Spears",
			DBTableID.CombatInterfaceWeaponCategory.Row.COMBAT_INTERFACE_SPEAR, MELEE));
		types.add(excluded("banner", "Banners",
			DBTableID.CombatInterfaceWeaponCategory.Row.COMBAT_INTERFACE_BANNER,
			"a carried banner, not a category anyone trains a style in"));
		types.add(offerable("spiked", "Spiked weapons",
			DBTableID.CombatInterfaceWeaponCategory.Row.COMBAT_INTERFACE_SPIKED, MELEE));
		types.add(offerable("stabsword", "Stab swords",
			DBTableID.CombatInterfaceWeaponCategory.Row.COMBAT_INTERFACE_STABSWORD, MELEE));

		// --- The hybrid staves: melee AND magic ---
		types.add(offerable("staff", "Staves",
			DBTableID.CombatInterfaceWeaponCategory.Row.COMBAT_INTERFACE_STAFF, HYBRID_STAFF));
		types.add(offerable("staff_bladed", "Bladed staves",
			DBTableID.CombatInterfaceWeaponCategory.Row.COMBAT_INTERFACE_STAFF_BLADED, HYBRID_STAFF));
		types.add(offerable("staff_spellblade", "Spellblade staves",
			DBTableID.CombatInterfaceWeaponCategory.Row.COMBAT_INTERFACE_STAFF_SPELLBLADE, HYBRID_STAFF));

		types.add(offerable("thrown", "Thrown weapons",
			DBTableID.CombatInterfaceWeaponCategory.Row.COMBAT_INTERFACE_THROWN, RANGED));
		types.add(offerable("whip", "Whips",
			DBTableID.CombatInterfaceWeaponCategory.Row.COMBAT_INTERFACE_WHIP, MELEE));

		types.add(offerable("staff_selfpowering", "Powered staves",
			DBTableID.CombatInterfaceWeaponCategory.Row.COMBAT_INTERFACE_STAFF_SELFPOWERING, MAGIC));
		types.add(excluded("wand_selfpowering", "Powered wands",
			DBTableID.CombatInterfaceWeaponCategory.Row.COMBAT_INTERFACE_WAND_SELFPOWERING,
			"no live items in this category, so the preference could never be met"));

		// block mode deals no damage at all, so a cycle spent under this
		// preference is not merely weak, it is unplayable: the player would have
		// to choose between the bonus and killing anything
		types.add(excluded("bulwark", "Bulwarks",
			DBTableID.CombatInterfaceWeaponCategory.Row.COMBAT_INTERFACE_BULWARK,
			"block mode does no damage — a bulwark cycle is unplayable"));

		types.add(offerable("partisan", "Partisans",
			DBTableID.CombatInterfaceWeaponCategory.Row.COMBAT_INTERFACE_PARTISAN, MELEE));

		types.add(excluded("tribrid", "Tribrid weapons",
			DBTableID.CombatInterfaceWeaponCategory.Row.COMBAT_INTERFACE_TRIBRID,
			"covers all three styles at once — naming it would hollow out the style lock"));
		types.add(excluded("egg", "Eggs",
			DBTableID.CombatInterfaceWeaponCategory.Row.COMBAT_INTERFACE_EGG,
			"not a category anyone fights a contract with"));
		types.add(excluded("sailing_cannon", "Sailing cannons",
			DBTableID.CombatInterfaceWeaponCategory.Row.COMBAT_INTERFACE_SAILING_CANNON,
			"a mounted cannon, not a wielded weapon"));
		types.add(excluded("multi_melee", "Multi-style melee",
			DBTableID.CombatInterfaceWeaponCategory.Row.COMBAT_INTERFACE_MULTI_MELEE,
			"no stable pool of items to name"));
		types.add(excluded("slashflail", "Slash flails",
			DBTableID.CombatInterfaceWeaponCategory.Row.COMBAT_INTERFACE_SLASHFLAIL,
			"one item, and quest locked"));

		// --- The pseudo-type ---
		// Not a weapon category and not a dbrow: com mode 4, the autocast slot,
		// which StyleTracker.resolve already reads. It is here so that MAGIC's
		// pool is not just the powered staves and the hybrids, and so that "does
		// this kill satisfy the preference" has exactly one answer from exactly
		// one place.
		types.add(offerable(WeaponTypeService.SPELL_CAST_KEY, "Cast spells",
			WeaponTypeService.NO_DBROW, MAGIC));

		return types;
	}

	public static void main(String[] args) throws IOException {
		Map<String, Object> file = new LinkedHashMap<>();
		file.put("note", NOTE);
		file.put("types", types());

		File out = new File("src/main/resources/com/gachaman/data/weapon-types.json");
		try (Writer w = Files.newBufferedWriter(out.toPath(), StandardCharsets.UTF_8)) {
			new GsonBuilder().setPrettyPrinting().create().toJson(file, w);
		}

		int offerable = 0;
		for (WeaponType type : types()) {
			if (type.isOfferable()) {
				offerable++;
			}
		}
		System.out.println("wrote " + out + " (" + types().size() + " categories, "
			+ offerable + " offerable)");
	}
}

package com.gachaman.tools;

import com.gachaman.*;
import java.awt.*;
import java.awt.geom.*;

/**
 * Procedural pseudo-3D treasure chest for the reveal ceremony. The chest is
 * drawn with fake perspective: a trapezoid front face with wood-plank strips,
 * side hints, a back rim, and a lid quad that rotates open around its back
 * hinge (vertical scale/shear approximates the 3D rotation; the inner face
 * fades in past ~60 degrees). Warm light spills from the opening, dust and
 * spark particles drift up. Pure function of its arguments - no state, no
 * timers; all animation comes in via {@code openT}, {@code leak} and
 * {@code timeMs} so callers control time. Single-threaded render use only
 * (shared scratch path).
 */
public final class ChestArt {
	private static final double OPEN_ANGLE_MAX = 1.95; // ~112 degrees

	// Body layout, as fractions of the chest box. Named because the chains have
	// to wrap the SILHOUETTE these produce, so the numbers now have two readers.
	private static final double LID_TOP_FRAC = 0.16;   // empty air above the lid
	private static final double LID_FRONT_FRAC = 0.30; // lid skirt height
	private static final double SLANT_FRAC = 0.045;    // front face taper
	private static final double SKIRT_WIDEN = 1.02;    // lid overhangs the body

	private static final Color WOOD_LIGHT = new Color(126, 84, 48);
	private static final Color WOOD_DARK = new Color(72, 46, 22);
	private static final Color WOOD_SEAM = new Color(46, 28, 12);
	private static final Color WOOD_SIDE = new Color(56, 35, 16);
	private static final Color INTERIOR = new Color(24, 14, 6);
	private static final Color INNER_LID = new Color(58, 36, 16);
	private static final Color GLOW_WARM = new Color(255, 214, 120);
	private static final Color GLOW_HOT = new Color(255, 240, 200);
	private static final Color METAL_SILVER_HI = new Color(212, 216, 226);
	private static final Color METAL_SILVER_LO = new Color(120, 124, 136);
	private static final Color METAL_GOLD_HI = new Color(244, 208, 96);
	private static final Color METAL_GOLD_LO = new Color(148, 108, 28);
	private static final Color METAL_WORN_HI = new Color(96, 92, 86);
	private static final Color METAL_WORN_LO = new Color(52, 48, 44);
	private static final Color METAL_RUST_HI = new Color(124, 78, 48);
	private static final Color METAL_RUST_LO = new Color(62, 40, 26);
	// Wide range on purpose: the chain sits on gold bands over lit wood, and a
	// mid-grey barstock with a mild highlight merges into all of it as one flat
	// mass. Dark body, hot specular, and the specular carries the scene's warmth.
	private static final Color CHAIN_LIGHT = new Color(136, 139, 150);
	private static final Color CHAIN_SHADE = new Color(20, 21, 27);
	private static final Color CHAIN_SPEC = new Color(246, 242, 228);
	private static final Color LOCK_GOLD = new Color(230, 190, 80);
	private static final Color LOCK_BODY_HI = new Color(112, 116, 130);
	private static final Color LOCK_BODY_LO = new Color(28, 30, 38);

	/** Key light for the chain barstock: up and to the left, screen space. */
	private static final double LIGHT_X = -0.52;
	private static final double LIGHT_Y = -0.85;

	private static final int LINK_FULL = 0;
	private static final int LINK_NEAR = 1;

	/** Where along its chain each padlock hangs; 0.30 puts the pair either side
	 * of the chest's own keyplate. */
	private static final double LOCK_T = 0.30;
	/** A lock gives, and only then does the chain it was holding let go. */
	private static final long LOCK_TO_WHIP_MS = 160;
	private static final long LOCK_BREAK_MS = 750;

	/** Shared scratch path; render happens on a single thread. */
	private static final Path2D.Double PATH = new Path2D.Double();

	private ChestArt() {
	}

	/**
	 * Draw the chest centered at (cx, cy) inside a w-by-h box.
	 *
	 * @param openT     0 = closed, 1 = fully open; values above 1 add blast
	 *                  lift (the lid keeps rising off the hinge). The lid ANGLE
	 *                  clamps at 1, so above-1 values only detach the lid from
	 *                  the hinge - reserve them for the stationary lid-blast
	 *                  beat and pass at most 1.0 while translating the chest,
	 *                  or the lid will visibly float off the moving body.
	 * @param tier      structural styling (band metal, trim richness)
	 * @param trim      trim color override (jackpot crossfades pass a mix)
	 * @param innerGlow extra interior glow 0..1 independent of the lid angle
	 * @param leak      seam light-leak intensity 0..1 (pre-blast tension)
	 */
	static void draw(Graphics2D g, int cx, int cy, int w, int h, double openT,
		Tuning.Chest tier, Color trim, float innerGlow, float leak, long timeMs) {
		Graphics2D g2 = (Graphics2D) g.create();
		g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

		int x = cx - w / 2;
		int top = cy - h / 2;
		int bottom = cy + h / 2;
		double a = clamp01(openT) * OPEN_ANGLE_MAX;
		int lift = (int) (Math.max(0, openT - 1.0) * h * 0.55);

		int lidFrontH = (int) (h * LID_FRONT_FRAC);
		int dTop = (int) (h * LID_TOP_FRAC);
		int frontTopY = top + lidFrontH + dTop;
		int inset = (int) (w * 0.07);
		int slant = (int) (w * SLANT_FRAC);
		int hingeY = top;

		float openGlow = (float) smoothstep(Math.min(1.0, a / 1.5));
		float glow = Math.max(openGlow, clamp01f(innerGlow));

		drawDropShadow(g2, cx, bottom, w, h);
		drawBackRim(g2, x, w, inset, hingeY, frontTopY);
		if (a > 0.10) {
			drawInterior(g2, x, w, inset, hingeY, frontTopY, glow);
		}
		drawBody(g2, x, frontTopY, bottom, w, slant, tier, trim);
		if (glow > 0.04f) {
			drawSpillGlow(g2, cx, frontTopY, w, h, glow);
			drawMotes(g2, cx, frontTopY, w, h, glow, timeMs);
		}
		drawLid(g2, x, w, inset, hingeY, dTop, lidFrontH, frontTopY, a, lift, tier, trim, glow);
		if (leak > 0.03f && a < 0.15) {
			// seam between the closed lid skirt and the body top edge
			drawSeamLeak(g2, x, w, frontTopY, leak, timeMs);
		}
		g2.dispose();
	}

	// --- pieces ---

	private static void drawDropShadow(Graphics2D g2, int cx, int bottom, int w, int h) {
		int sw = (int) (w * 1.20);
		int sh = Math.max(10, h / 6);
		g2.setColor(new Color(0, 0, 0, 60));
		g2.fillOval(cx - sw / 2, bottom - sh / 2, sw, sh);
		int sw2 = (int) (w * 1.02);
		int sh2 = Math.max(8, h / 8);
		g2.setColor(new Color(0, 0, 0, 90));
		g2.fillOval(cx - sw2 / 2, bottom - sh2 / 2, sw2, sh2);
	}

	private static void drawBackRim(Graphics2D g2, int x, int w, int inset, int hingeY, int frontTopY) {
		// thin dark silhouette of the box's back wall rising behind the opening
		int backH = (frontTopY - hingeY) / 2;
		g2.setColor(new Color(38, 24, 10));
		g2.fillRect(x + inset, frontTopY - backH - 2, w - inset * 2, backH + 2);
		g2.setColor(new Color(20, 12, 5));
		g2.drawLine(x + inset, frontTopY - backH - 2, x + w - inset, frontTopY - backH - 2);
	}

	private static void drawInterior(Graphics2D g2, int x, int w, int inset, int hingeY,
		int frontTopY, float glow) {
		PATH.reset();
		PATH.moveTo(x + 2, frontTopY);
		PATH.lineTo(x + w - 2, frontTopY);
		PATH.lineTo(x + w - inset, hingeY + 4);
		PATH.lineTo(x + inset, hingeY + 4);
		PATH.closePath();
		g2.setColor(INTERIOR);
		g2.fill(PATH);
		// warm pool inside, layered for a radial falloff
		int cxm = x + w / 2;
		int span = w - inset * 2;
		for (int i = 6; i >= 1; i--) {
			float t = i / 6f;
			int ew = (int) (span * (0.35 + 0.65 * (1 - t)));
			int eh = Math.max(4, (int) ((frontTopY - hingeY) * (1 - t) * 0.9));
			g2.setColor(withAlpha(GLOW_WARM, glow * 0.16f * (1 - t) + glow * 0.06f));
			g2.fillOval(cxm - ew / 2, frontTopY - eh - 2, ew, eh + 4);
		}
	}

	private static void drawBody(Graphics2D g2, int x, int frontTopY, int bottom, int w,
		int slant, Tuning.Chest tier, Color trim) {
		// side hints: dark slivers where the slanted front edges expose the sides
		PATH.reset();
		PATH.moveTo(x, frontTopY);
		PATH.lineTo(x + slant, bottom);
		PATH.lineTo(x, bottom);
		PATH.closePath();
		g2.setColor(WOOD_SIDE);
		g2.fill(PATH);
		PATH.reset();
		PATH.moveTo(x + w, frontTopY);
		PATH.lineTo(x + w - slant, bottom);
		PATH.lineTo(x + w, bottom);
		PATH.closePath();
		g2.fill(PATH);

		// front face trapezoid, clipped so plank strips stay inside
		PATH.reset();
		PATH.moveTo(x, frontTopY);
		PATH.lineTo(x + w, frontTopY);
		PATH.lineTo(x + w - slant, bottom);
		PATH.lineTo(x + slant, bottom);
		PATH.closePath();

		Graphics2D gp = (Graphics2D) g2.create();
		gp.setClip(PATH);
		boolean battered = worn(tier);
		float dimBody = tier == Tuning.Chest.RUSTY ? 0.70f : 0.82f;
		Color lightWood = battered ? dim(WOOD_LIGHT, dimBody) : WOOD_LIGHT;
		Color darkWood = battered ? dim(WOOD_DARK, dimBody) : WOOD_DARK;
		int planks = 4;
		int faceH = bottom - frontTopY;
		for (int p = 0; p < planks; p++) {
			int py = frontTopY + faceH * p / planks;
			int ph = faceH * (p + 1) / planks - faceH * p / planks;
			gp.setPaint(new GradientPaint(x, py, lightWood, x, py + ph, darkWood));
			gp.fillRect(x, py, w, ph + 1);
			// grain streaks (deterministic, subtle)
			gp.setColor(new Color(255, 235, 200, 16));
			int gy = py + ph / 3 + (p * 7) % Math.max(1, ph / 2);
			gp.drawLine(x + 6 + p * 11, gy, x + w / 2 + p * 9, gy);
			if (p > 0) {
				gp.setColor(WOOD_SEAM);
				gp.drawLine(x, py, x + w, py);
				gp.setColor(new Color(255, 220, 170, 24));
				gp.drawLine(x, py + 1, x + w, py + 1);
			}
		}
		// vertical metal bands following the trapezoid slant
		drawBand(gp, x, frontTopY, bottom, w, slant, 0.20f, tier);
		drawBand(gp, x, frontTopY, bottom, w, slant, 0.80f, tier);
		gp.dispose();

		// outline + tier trim
		g2.setColor(trim);
		g2.setStroke(new BasicStroke(tier == Tuning.Chest.ORNATE ? 3.2f : 2.4f));
		g2.draw(PATH);
		if (tier == Tuning.Chest.ORNATE) {
			g2.setColor(withAlpha(METAL_GOLD_HI, 0.55f));
			g2.setStroke(new BasicStroke(1.2f));
			g2.drawLine(x + 4, frontTopY + 3, x + w - 4, frontTopY + 3);
		}

		drawCornerCaps(g2, x, frontTopY, bottom, w, slant, tier);
		drawLockPlate(g2, x + w / 2, frontTopY, w, tier);
	}

	private static void drawBand(Graphics2D gp, int x, int frontTopY, int bottom, int w,
		int slant, float frac, Tuning.Chest tier) {
		int bandW = Math.max(6, w / 16);
		int xt = x + (int) (w * frac);
		int xb = x + slant + (int) ((w - slant * 2) * frac);
		PATH.reset();
		PATH.moveTo(xt - bandW / 2.0, frontTopY);
		PATH.lineTo(xt + bandW / 2.0, frontTopY);
		PATH.lineTo(xb + bandW / 2.0, bottom);
		PATH.lineTo(xb - bandW / 2.0, bottom);
		PATH.closePath();
		gp.setPaint(new GradientPaint(xt - bandW / 2f, frontTopY, bandHi(tier),
			xt + bandW / 2f, frontTopY, bandLo(tier)));
		gp.fill(PATH);
		gp.setColor(withAlpha(Color.BLACK, 0.35f));
		gp.setStroke(new BasicStroke(1f));
		gp.draw(PATH);
		// rivets
		gp.setColor(bandHi(tier));
		int faceH = bottom - frontTopY;
		for (int r = 0; r < 3; r++) {
			int ry = frontTopY + faceH * (r * 2 + 1) / 6;
			int rx = (int) lerp(xt, xb, (ry - frontTopY) / (double) faceH);
			gp.fillOval(rx - 2, ry - 2, 4, 4);
		}
		if (worn(tier)) {
			// worn notches chipped out of the band edge
			gp.setColor(WOOD_DARK);
			gp.fillRect(xt - bandW / 2 - 1, frontTopY + faceH / 4, 3, 5);
			gp.fillRect(xb + bandW / 2 - 2, bottom - faceH / 3, 3, 6);
		}
	}

	private static void drawCornerCaps(Graphics2D g2, int x, int frontTopY, int bottom, int w,
		int slant, Tuning.Chest tier) {
		int cap = Math.max(7, w / 14);
		g2.setPaint(new GradientPaint(x, frontTopY, bandHi(tier), x + cap, frontTopY + cap, bandLo(tier)));
		g2.fillRoundRect(x - 1, frontTopY - 1, cap, cap, 4, 4);
		g2.fillRoundRect(x + w - cap + 1, frontTopY - 1, cap, cap, 4, 4);
		g2.fillRoundRect(x + slant - 2, bottom - cap + 1, cap, cap, 4, 4);
		g2.fillRoundRect(x + w - slant - cap + 2, bottom - cap + 1, cap, cap, 4, 4);
		g2.setColor(withAlpha(Color.BLACK, 0.4f));
		g2.setStroke(new BasicStroke(1f));
		g2.drawRoundRect(x - 1, frontTopY - 1, cap, cap, 4, 4);
		g2.drawRoundRect(x + w - cap + 1, frontTopY - 1, cap, cap, 4, 4);
	}

	private static void drawLockPlate(Graphics2D g2, int cx, int frontTopY, int w, Tuning.Chest tier) {
		int pw = Math.max(14, w / 7);
		int ph = (int) (pw * 1.15);
		int px = cx - pw / 2;
		int py = frontTopY + 3;
		g2.setPaint(new GradientPaint(px, py, bandHi(tier), px, py + ph, bandLo(tier)));
		g2.fillRoundRect(px, py, pw, ph, 6, 6);
		g2.setColor(withAlpha(Color.BLACK, 0.45f));
		g2.setStroke(new BasicStroke(1.2f));
		g2.drawRoundRect(px, py, pw, ph, 6, 6);
		// keyhole
		g2.setColor(new Color(24, 16, 8));
		g2.fillOval(cx - 3, py + ph / 3 - 3, 6, 6);
		g2.fillRect(cx - 1, py + ph / 3, 3, ph / 3);
	}

	private static void drawLid(Graphics2D g2, int x, int w, int inset, int hingeY, int dTop,
		int lidFrontH, int frontTopY, double a, int lift, Tuning.Chest tier, Color trim, float glow) {
		double cosA = Math.cos(a);
		double sinA = Math.sin(a);
		double rise = (frontTopY - hingeY) * 1.6;

		int hy = hingeY - lift;
		double lipY = hy + dTop * cosA - rise * sinA;
		double lipHalf = (w * (1.0 - 0.10 * sinA)) / 2.0;
		double cxm = x + w / 2.0;

		// inner face: visible once past ~60 degrees, lit from the chest below
		float innerA = clamp01f((float) ((a - 1.0) / 0.5));
		if (innerA > 0.02f) {
			PATH.reset();
			PATH.moveTo(x + inset, hy);
			PATH.lineTo(x + w - inset, hy);
			PATH.lineTo(cxm + lipHalf, lipY);
			PATH.lineTo(cxm - lipHalf, lipY);
			PATH.closePath();
			Graphics2D gi = (Graphics2D) g2.create();
			gi.setClip(PATH);
			gi.setPaint(new GradientPaint((float) cxm, (float) lipY, dim(INNER_LID, 0.8f),
				(float) cxm, hy, mix(INNER_LID, GLOW_WARM, glow * 0.55f)));
			gi.fill(PATH);
			gi.setColor(withAlpha(GLOW_WARM, glow * 0.30f * innerA));
			gi.fillRect(x + inset, hy - 6, w - inset * 2, 12);
			gi.dispose();
			g2.setColor(withAlpha(trim, innerA));
			g2.setStroke(new BasicStroke(2.2f));
			g2.draw(PATH);
		}

		// outer skirt face: squashes vertically as the lid tips back
		if (cosA > 0.06) {
			double skirtTopY = hy + dTop * cosA;
			double skirtBotY = skirtTopY + lidFrontH * cosA;
			double topHalf = lipHalf;
			double botHalf = (w * SKIRT_WIDEN) / 2.0;
			PATH.reset();
			PATH.moveTo(cxm - topHalf, skirtTopY);
			PATH.lineTo(cxm + topHalf, skirtTopY);
			PATH.lineTo(cxm + botHalf, skirtBotY);
			PATH.lineTo(cxm - botHalf, skirtBotY);
			PATH.closePath();
			boolean battered = worn(tier);
			float hiDim = tier == Tuning.Chest.RUSTY ? 0.80f : 0.9f;
			float loDim = tier == Tuning.Chest.RUSTY ? 0.65f : 0.75f;
			Color hi = battered ? dim(WOOD_LIGHT, hiDim) : brighten(WOOD_LIGHT, 1.15f);
			Color lo = battered ? dim(WOOD_LIGHT, loDim) : WOOD_LIGHT;
			g2.setPaint(new GradientPaint((float) cxm, (float) skirtTopY, hi,
				(float) cxm, (float) skirtBotY, lo));
			g2.fill(PATH);

			Graphics2D gs = (Graphics2D) g2.create();
			gs.setClip(PATH);
			// plank seam across the skirt
			gs.setColor(WOOD_SEAM);
			int seamY = (int) lerp(skirtTopY, skirtBotY, 0.5);
			gs.drawLine((int) (cxm - botHalf), seamY, (int) (cxm + botHalf), seamY);
			// lid bands aligned with the body bands
			int bandW = Math.max(6, w / 16);
			gs.setPaint(new GradientPaint(0, (float) skirtTopY, bandHi(tier),
				0, (float) skirtBotY, bandLo(tier)));
			gs.fillRect((int) (cxm - w * 0.30) - bandW / 2, (int) skirtTopY - 2,
				bandW, (int) (skirtBotY - skirtTopY) + 4);
			gs.fillRect((int) (cxm + w * 0.30) - bandW / 2, (int) skirtTopY - 2,
				bandW, (int) (skirtBotY - skirtTopY) + 4);
			gs.dispose();

			g2.setColor(trim);
			g2.setStroke(new BasicStroke(tier == Tuning.Chest.ORNATE ? 3.0f : 2.2f));
			g2.draw(PATH);
			// arched top hint on the closed lid
			if (a < 0.35) {
				g2.setColor(withAlpha(brighten(WOOD_LIGHT, 1.25f), (float) (1.0 - a / 0.35) * 0.5f));
				g2.setStroke(new BasicStroke(1.4f));
				g2.drawLine((int) (cxm - topHalf + 6), (int) skirtTopY + 2,
					(int) (cxm + topHalf - 6), (int) skirtTopY + 2);
			}
		}
	}

	private static void drawSpillGlow(Graphics2D g2, int cx, int frontTopY, int w, int h, float glow) {
		// column of warm light rising out of the opening
		for (int i = 5; i >= 1; i--) {
			float t = i / 5f;
			int gw = (int) (w * (0.36 + 0.5 * (1 - t)));
			int gh = (int) (h * 0.7 * (1 - t * 0.35));
			g2.setColor(withAlpha(GLOW_WARM, glow * 0.10f * (1 - t) + glow * 0.03f));
			g2.fillOval(cx - gw / 2, frontTopY - gh, gw, gh + 8);
		}
		g2.setColor(withAlpha(GLOW_HOT, glow * 0.25f));
		g2.fillOval(cx - w / 4, frontTopY - 8, w / 2, 14);
	}

	private static void drawMotes(Graphics2D g2, int cx, int frontTopY, int w, int h,
		float glow, long timeMs) {
		for (int p = 0; p < 14; p++) {
			float h1 = hash01(p * 197 + 11);
			float h2 = hash01(p * 197 + 12);
			float h3 = hash01(p * 197 + 13);
			int cycle = 1500 + (int) (h1 * 1300);
			float ph = ((timeMs + (long) (h2 * 99991)) % cycle) / (float) cycle;
			int px = cx + (int) ((h3 - 0.5f) * w * 0.62) + (int) (Math.sin(timeMs * 0.0012 + p) * 5);
			int py = frontTopY - 4 - (int) (ph * h * 0.85);
			float alpha = (1 - ph) * glow * (0.35f + 0.5f * h2);
			if (alpha < 0.03f) {
				continue;
			}
			if ((p & 1) == 0) {
				g2.setColor(withAlpha(METAL_GOLD_HI, alpha));
				g2.fillRect(px, py, 2, 2);
			}
			else {
				g2.setColor(withAlpha(GLOW_HOT, alpha * 0.6f));
				g2.fillRect(px, py, 1, 2);
			}
		}
	}

	private static void drawSeamLeak(Graphics2D g2, int x, int w, int seamY, float leak, long timeMs) {
		float flicker = 0.85f + 0.15f * (float) Math.sin(timeMs * 0.02);
		float a = clamp01f(leak) * flicker;
		for (int i = 3; i >= 1; i--) {
			g2.setColor(withAlpha(GLOW_WARM, a * 0.14f * (4 - i)));
			g2.setStroke(new BasicStroke(2f + i * 3f));
			g2.drawLine(x + 6, seamY, x + w - 6, seamY);
		}
		g2.setColor(withAlpha(GLOW_HOT, a));
		g2.setStroke(new BasicStroke(2f));
		g2.drawLine(x + 6, seamY, x + w - 6, seamY);
		// stray rays escaping the seam
		g2.setStroke(new BasicStroke(1.4f));
		for (int r = 0; r < 5; r++) {
			float hr = hash01(r * 379 + 5);
			int rx = x + 10 + (int) (hr * (w - 20));
			int len = 6 + (int) (a * 22 * hash01(r * 379 + 6));
			g2.setColor(withAlpha(GLOW_HOT, a * 0.55f));
			g2.drawLine(rx, seamY - 2, rx + (int) ((hr - 0.5f) * 8), seamY - 2 - len);
		}
	}

	// --- ceremony props ---

	/**
	 * Gilded padlock hanging over the lock plate; pulses, then shatters into
	 * fragments at {@code shatterAtMs} (pure function of elapsed time).
	 */
	static void drawPadlock(Graphics2D g2, int cx, int cy, int chestW, long el, long shatterAtMs) {
		int size = chestW / 5;
		if (el >= shatterAtMs) {
			long t = el - shatterAtMs;
			if (t > 850) {
				return;
			}
			float u = t / 850f;
			// flash ring
			g2.setColor(withAlpha(GLOW_HOT, (1 - u) * 0.8f));
			g2.setStroke(new BasicStroke(2f + (1 - u) * 6f));
			int rr = (int) (size * (0.5 + u * 2.2));
			g2.drawOval(cx - rr, cy - rr, rr * 2, rr * 2);
			// fragments with fake gravity
			double ts = t / 1000.0;
			for (int p = 0; p < 14; p++) {
				float a1 = hash01(p * 131 + 7);
				float a2 = hash01(p * 131 + 8);
				double ang = a1 * Math.PI * 2;
				double speed = 70 + a2 * 190;
				int px = cx + (int) (Math.cos(ang) * speed * ts);
				int py = cy + (int) (Math.sin(ang) * speed * ts + 320 * ts * ts);
				int fs = 2 + (p % 3);
				g2.setColor(withAlpha((p & 1) == 0 ? METAL_GOLD_HI : METAL_SILVER_HI, 1 - u));
				Graphics2D gf = (Graphics2D) g2.create();
				gf.rotate(a1 * 6 + ts * 8, px, py);
				gf.fillRect(px - fs / 2, py - fs / 2, fs + 2, fs);
				gf.dispose();
			}
			return;
		}
		float pulse = 0.5f + 0.5f * (float) Math.sin(el * 0.008);
		// glow behind the lock
		for (int i = 4; i >= 1; i--) {
			g2.setColor(withAlpha(LOCK_GOLD, (0.10f + 0.10f * pulse) * (5 - i) / 5f));
			int pad = i * 5;
			g2.fillOval(cx - size / 2 - pad, cy - size / 2 - pad, size + pad * 2, size + pad * 2);
		}
		// shackle
		g2.setColor(METAL_SILVER_HI);
		g2.setStroke(new BasicStroke(5f));
		g2.drawArc(cx - size / 3, cy - size, size * 2 / 3, size * 2 / 3, 0, 180);
		g2.setColor(METAL_SILVER_LO);
		g2.setStroke(new BasicStroke(2f));
		g2.drawArc(cx - size / 3 + 2, cy - size + 2, size * 2 / 3 - 4, size * 2 / 3 - 4, 0, 180);
		// body
		g2.setPaint(new GradientPaint(cx - size / 2f, cy - size / 2f, METAL_GOLD_HI,
			cx + size / 2f, cy + size / 2f, METAL_GOLD_LO));
		g2.fillRoundRect(cx - size / 2, cy - size / 2, size, size, 8, 8);
		g2.setColor(withAlpha(Color.BLACK, 0.4f));
		g2.setStroke(new BasicStroke(1.4f));
		g2.drawRoundRect(cx - size / 2, cy - size / 2, size, size, 8, 8);
		g2.setColor(new Color(70, 52, 14));
		g2.fillOval(cx - 4, cy - 6, 8, 8);
		g2.fillRect(cx - 2, cy, 4, 8);
	}

	/**
	 * Two chains wrapped around the closed ornate chest, each held shut by its
	 * own padlock on the front. A lock bursts; the chain it was holding hangs
	 * slack for a beat and only then whips away (rotate + fling with gravity).
	 *
	 * <p>The OUTER chain goes first. Chain 1 is drawn second, so it lies over
	 * chain 0 where they cross, so it is the outer one, so its lock is the one
	 * that can be reached and the one that breaks first - you cannot unwrap the
	 * inner chain while the outer is still pinning it down. That is the kind of
	 * wrong that reads instantly even when nobody can say why.
	 *
	 * @param firstBreakMs when the outer chain's lock bursts
	 * @param breakGapMs   how long after that the inner one follows
	 */
	static void drawChains(Graphics2D g2, int cx, int cy, int w, int h, long el,
		long firstBreakMs, long breakGapMs) {
		int lockSize = Math.max(15, w / 9);
		long[] since = new long[2];
		double[][] at = new double[2][];
		for (int k = 0; k < 2; k++) {
			long breakAt = lockBreakMs(k, firstBreakMs, breakGapMs);
			since[k] = el - breakAt;
			// frozen at the break: the wreckage falls from where the lock WAS,
			// and does not keep riding a chain it is no longer attached to
			at[k] = chainPointAt(cx, cy, w, h, k == 0 ? 1 : -1, LOCK_T,
				Math.min(el, breakAt), k);
		}

		// the bow of each shackle, so the chain can run in FRONT of it
		for (int k = 0; k < 2; k++) {
			if (since[k] < 0) {
				drawLockBow(g2, at[k][0], at[k][1], lockSize, k == 0 ? 1 : -1, el, k);
			}
		}
		for (int k = 0; k < 2; k++) {
			int dir = k == 0 ? 1 : -1;
			long t = since[k] - LOCK_TO_WHIP_MS;
			if (t < 0) {
				// between the lock giving and the chain letting go, the tension
				// it was under comes out as slack - the chain sags and swings
				// wider for a beat before it goes
				drawChainDiagonal(g2, cx, cy, w, h, dir, 1f, 0, k, el,
					clamp01f(since[k] / (float) LOCK_TO_WHIP_MS) * 0.30f, true);
				continue;
			}
			if (t > 650) {
				continue;
			}
			float u = t / 650f;
			double ts = t / 1000.0;
			int off = (int) (ts * 320) * dir;
			int drop = (int) (460 * ts * ts);
			// a chain coming loose goes slack before it is clear of the box, so
			// the whip is a rigid throw plus a much larger travelling wave
			drawChainDiagonal(g2, cx + off, cy + drop, w, h, dir, 1f - u,
				(float) (u * 1.4 * dir), k, el, u, false);
		}
		// and the near leg and body back over the chain, closing the U on it
		for (int k = 0; k < 2; k++) {
			if (since[k] < 0) {
				drawLockFront(g2, at[k][0], at[k][1], lockSize, k == 0 ? 1 : -1, el, k);
			}
			else if (since[k] < LOCK_BREAK_MS) {
				drawLockBreak(g2, at[k][0], at[k][1], lockSize, since[k]);
			}
		}
	}

	/**
	 * When chain {@code k}'s padlock bursts. Chain 1 is drawn second, so it lies
	 * over chain 0 where they cross, so it is the OUTER one - and the outer lock
	 * is the one you can get at. Freeing the inner chain first would have it
	 * slide out from under a chain still pinning it down.
	 */
	static long lockBreakMs(int k, long firstBreakMs, long breakGapMs) {
		return firstBreakMs + (k == 1 ? 0 : breakGapMs);
	}

	/**
	 * The closed chest's outer silhouette - lid skirt plus body - as one shape.
	 * Used to clip the resting chains so their ends pass behind the box instead
	 * of hanging in the air beside it. Package-private so the test can pin it
	 * against {@link #chainEnds}: the layout fractions now have two readers, and
	 * a chain whose run leaves the silhouette is a chain the clip deletes.
	 */
	static Shape closedSilhouette(int cx, int cy, int w, int h) {
		double x = cx - w / 2.0;
		double top = cy - h / 2.0;
		double bottom = cy + h / 2.0;
		double skirtTop = top + h * LID_TOP_FRAC;
		double frontTop = skirtTop + h * LID_FRONT_FRAC;
		double slant = w * SLANT_FRAC;
		double botHalf = w * SKIRT_WIDEN / 2.0;
		Path2D.Double p = new Path2D.Double();
		p.moveTo(x, skirtTop);
		p.lineTo(x + w, skirtTop);
		p.lineTo(cx + botHalf, frontTop);
		p.lineTo(cx - botHalf, frontTop);
		p.closePath();
		p.moveTo(x, frontTop);
		p.lineTo(x + w, frontTop);
		p.lineTo(x + w - slant, bottom);
		p.lineTo(x + slant, bottom);
		p.closePath();
		return p;
	}

	/**
	 * Where chain {@code dir} enters and leaves the chest, before bow and sway.
	 *
	 * <p>Side to side, NOT corner to corner. A chain that ends on a corner could
	 * just as well be lying flat on the picture; one that runs off the left edge
	 * and off the right edge can only be continuing around the back. It still
	 * crosses the lid seam on the way, so it is still what holds the lid shut.
	 */
	static double[] chainEnds(int cx, int cy, int w, int h, int dir) {
		return new double[]{
			cx - dir * (w / 2.0),
			cy - h / 2.0 + h * (LID_TOP_FRAC + LID_FRONT_FRAC * 0.55),
			cx + dir * (w / 2.0),
			cy + h / 2.0 - h * 0.10};
	}

	/**
	 * How far the chain sits off its straight run at {@code c}, measured along
	 * the path normal. Three terms: the bow out over the front face, a slow
	 * swing, and a fast rattle at the ORNATE strain frequency so the chain
	 * visibly LAGS the box it is tied to instead of moving with it. All three
	 * are pinned to zero where the chain bites the corners.
	 *
	 * <p>Shared with the padlocks, which hang off the chain and so have to ride
	 * exactly this curve - a lock floating beside its own chain is the tell that
	 * gives the whole thing away.
	 */
	private static double chainNormal(double c, int w, int h, long el, int seed, float slack) {
		double env = Math.sin(c * Math.PI);
		double swing = (2.2 + 7.0 * slack) * Math.min(1.0, w / 300.0 + 0.4);
		return h * 0.055 * env
			+ swing * env * Math.sin(el * 0.0055 + c * 6.0 + seed * 2.0)
			+ 1.0 * env * Math.sin(el * 0.05 + c * 3.0 + seed);
	}

	/** Where chain {@code dir} actually is at {@code t}, sway and all. */
	private static double[] chainPointAt(int cx, int cy, int w, int h, int dir, double t,
		long el, int seed) {
		double[] e = chainEnds(cx, cy, w, h, dir);
		double dx = e[2] - e[0];
		double dy = e[3] - e[1];
		double len = Math.hypot(dx, dy);
		double n = chainNormal(clamp01(t), w, h, el, seed, 0f) * dir;
		return new double[]{e[0] + dx * t - dy / len * n, e[1] + dy * t + dx / len * n};
	}

	/**
	 * One chain wrapped diagonally around the chest, side to side.
	 *
	 * <p>What makes it read as a chain rather than a dotted line of beads: the
	 * link count comes from the path length divided by a 0.62 pitch, so every
	 * link's end bar lands INSIDE its neighbour's hole. A fixed count breaks
	 * that at every chest size but one. Then the flat links are drawn, the
	 * edge-on ones over them, and the flat links' NEAR arcs back over those - so
	 * each link genuinely threads behind one neighbour and in front of the next.
	 *
	 * <p>What makes it read as going AROUND the box rather than lying on top of
	 * the picture: the path runs past both sides of the silhouette and is
	 * clipped to it, so the ends disappear behind the chest; the last links
	 * before that edge foreshorten and drop into shadow as the band turns the
	 * corner; the run bows out over the front face and the whole chain twists
	 * along its length, so no two links present the same face.
	 *
	 * <p>And what makes it read as loose: it never sits still. A slow swing and
	 * a fast rattle ride the path normal, anchored to zero at both ends, and
	 * {@code slack} opens the swing right up while the chain is being flung.
	 */
	private static void drawChainDiagonal(Graphics2D g2, int cx, int cy, int w, int h,
		int dir, float alpha, float rot, int seed, long el, float slack, boolean wrapped) {
		float a = clamp01f(alpha);
		if (a <= 0.01f) {
			return;
		}
		Graphics2D gc = (Graphics2D) g2.create();
		gc.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		if (wrapped) {
			gc.clip(closedSilhouette(cx, cy, w, h));
		}
		if (rot != 0) {
			gc.rotate(rot * (0.4 + 0.15 * seed), cx, cy);
		}

		double[] ends = chainEnds(cx, cy, w, h, dir);
		double x0 = ends[0];
		double y0 = ends[1];
		double x1 = ends[2];
		double y1 = ends[3];
		double dx = x1 - x0;
		double dy = y1 - y0;
		double len = Math.hypot(dx, dy);
		// times dir, or the two chains bow in OPPOSITE directions - the left-hand
		// one sagging and the right-hand one arching - and their padlocks end up
		// hanging at visibly different heights
		double nx = -dy / len * dir;
		double ny = dx / len * dir;
		// run past both edges so the clip - not the last link - is what ends the
		// chain. A chain that stops exactly at the edge reads as painted on.
		// Constant in both states on purpose: the chain really is longer than
		// the face it crosses, so the flung one is the same length as the
		// wrapped one and the whip does not re-tessellate it on its first frame.
		double ext = 0.15;
		// floors matter: chestW is min(300, cw/3), so a narrow client asks for a
		// much smaller chain and an unfloored ring degenerates into a smear
		double linkLen = Math.max(11, w / 10.0);
		double bar = Math.max(2.2, w / 62.0);
		int links = Math.max(4,
			(int) Math.round(len * (1 + 2 * ext) / (linkLen * 0.62)));

		double[] px = new double[links + 1];
		double[] py = new double[links + 1];
		double[] ang = new double[links + 1];
		double[] halfLen = new double[links + 1];
		double[] halfWid = new double[links + 1];
		float[] shade = new float[links + 1];
		float[] linkA = new float[links + 1];
		// the length hidden behind the box has to come INTO view rather than
		// appear the instant the clip drops, so it fades up over the first
		// ~150ms of the whip - by which point the chain is already moving fast
		float freed = wrapped ? 0f : Math.min(1f, slack / 0.23f);

		for (int i = 0; i <= links; i++) {
			double t = -ext + (1 + 2 * ext) * i / links;
			double c = clamp01(t);
			double env = Math.sin(c * Math.PI);
			double n = chainNormal(c, w, h, el, seed, slack);
			px[i] = x0 + dx * t + nx * n;
			py[i] = y0 + dy * t + ny * n;
			// tangent of the OFFSET path, so links lie along the curve they sit
			// on rather than along the straight run underneath it. Differenced
			// rather than differentiated by hand: chainNormal has three terms and
			// two readers, and a stale derivative would tilt every link silently.
			double dn = (chainNormal(clamp01(t + 0.004), w, h, el, seed, slack)
				- chainNormal(clamp01(t - 0.004), w, h, el, seed, slack)) / 0.008;
			ang[i] = Math.atan2(dy + ny * dn, dx + nx * dn)
				+ (hash01(seed * 37 + i) - 0.5) * 0.10;

			// turning the corner: the band rolls away from the eye, so the last
			// links compress along their own axis and fall into shadow. Gentle
			// on both counts - crush the length and they stop being rings, crush
			// the light and the corner is a black lump instead of dark metal.
			// ...and released along with the rest of it: a chain in mid-air has
			// no corner left to turn, so the squash and the shadow let go as the
			// hidden length fades in
			double turn = (1 - smoothstep(Math.min(c, 1 - c) / 0.10)) * (1 - freed);
			// nearer the bottom is nearer the eye; the front face bows out too
			double s = (0.86 + 0.28 * c) * (1 + 0.10 * env);
			// the chain twists as it runs, so no two links show the same face
			double roll = c * 1.35 + seed * 0.9 + el * 0.0006;
			double open = Math.abs((i & 1) == 0 ? Math.cos(roll) : Math.sin(roll));
			halfLen[i] = (linkLen * s * (1 - 0.34 * turn) - bar) / 2;
			halfWid[i] = Math.max(bar * 0.85, linkLen * s * 0.30 * open - bar / 2);
			shade[i] = (float) (0.58 + 0.42 * (1 - turn));
			linkA[i] = t < 0 || t > 1 ? a * (wrapped ? 1f : freed) : a;
		}

		drawChainShadow(gc, px, py, bar, a);
		for (int pass = 0; pass < 3; pass++) {
			for (int i = 0; i <= links; i++) {
				boolean flat = (i & 1) == 0;
				// flat links, then the edge-on ones on top, then the flat links'
				// near arcs back over the top: that ordering IS the interlock
				if (pass == 0 ? !flat : (pass == 1) == flat) {
					continue;
				}
				if (linkA[i] <= 0.01f) {
					continue;
				}
				chainLink(gc, px[i], py[i], ang[i], halfLen[i], halfWid[i], bar, linkA[i],
					shade[i], pass == 2 ? LINK_NEAR : LINK_FULL);
			}
		}
		gc.dispose();
	}

	/**
	 * Diffuse shadow the chain throws onto the chest face. One soft stroke along
	 * the whole path rather than per-link, which is both cheaper and closer to
	 * how a shadow that far from its caster actually looks.
	 */
	private static void drawChainShadow(Graphics2D gc, double[] px, double[] py,
		double bar, float a) {
		PATH.reset();
		for (int i = 0; i < px.length; i++) {
			if (i == 0) {
				PATH.moveTo(px[i] + bar * 0.55, py[i] + bar * 0.8);
			}
			else {
				PATH.lineTo(px[i] + bar * 0.55, py[i] + bar * 0.8);
			}
		}
		for (int i = 2; i >= 1; i--) {
			gc.setColor(withAlpha(Color.BLACK, a * 0.24f));
			gc.setStroke(new BasicStroke((float) (bar * (1.1 + i * 0.8)),
				BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			gc.draw(PATH);
		}
	}

	/**
	 * One link, drawn in its own rotated frame. {@code halfLen}/{@code halfWid}
	 * are the ellipse the barstock centre follows, so the silhouette runs half a
	 * bar wider than that in every direction and the hole is what is left inside.
	 */
	private static void chainLink(Graphics2D gc, double lx, double ly, double ang,
		double halfLen, double halfWid, double bar, float a, float shade, int mode) {
		AffineTransform old = gc.getTransform();
		gc.translate(lx, ly);
		gc.rotate(ang);
		// the key light is fixed in screen space, so it has to be carried into
		// the link's frame - otherwise every link is lit from its own direction
		double llx = LIGHT_X * Math.cos(ang) + LIGHT_Y * Math.sin(ang);
		double lly = -LIGHT_X * Math.sin(ang) + LIGHT_Y * Math.cos(ang);
		double r = Math.max(halfLen, halfWid) * 0.95;
		Ellipse2D.Double ring = new Ellipse2D.Double(-halfLen, -halfWid,
			halfLen * 2, halfWid * 2);
		Shape body = mode == LINK_NEAR
			? new Arc2D.Double(-halfLen, -halfWid, halfLen * 2, halfWid * 2, 188, 164,
				Arc2D.OPEN)
			: ring;

		if (mode == LINK_FULL) {
			double hw = halfWid * 2 - bar;
			if (hw > 1) {
				// the hole is a window onto the planks, in the link's own shadow
				gc.setColor(withAlpha(Color.BLACK, a * 0.42f));
				gc.fill(new Ellipse2D.Double(-halfLen + bar * 0.5, -halfWid + bar * 0.5,
					halfLen * 2 - bar, hw));
			}
			// contour, so the metal sits ON the wood instead of floating over it.
			// Eased off with the light: a full-strength outline on an already
			// dark link at the far edge just paints a black lump.
			gc.setColor(withAlpha(Color.BLACK, a * 0.5f * (0.55f + 0.45f * shade)));
			gc.setStroke(new BasicStroke((float) bar + 1.1f, BasicStroke.CAP_ROUND,
				BasicStroke.JOIN_ROUND));
			gc.draw(ring);
		}

		barMetal(gc, body, llx, lly, r, bar, a, shade);
		gc.setTransform(old);
	}

	/**
	 * Round barstock, stroked along {@code body}: a gradient around the form
	 * from the key light, then a specular that dies before it reaches the shaded
	 * side. {@code llx,lly} is the light in the shape's own frame and {@code r}
	 * the radius the gradient spans. Shared by the chain links and the padlock
	 * shackles so both are visibly the same steel.
	 */
	private static void barMetal(Graphics2D gc, Shape body, double llx, double lly,
		double r, double bar, float a, float shade) {
		gc.setPaint(new GradientPaint(
			(float) (llx * r), (float) (lly * r), withAlpha(dim(CHAIN_LIGHT, shade), a),
			(float) (-llx * r), (float) (-lly * r), withAlpha(dim(CHAIN_SHADE, shade), a)));
		gc.setStroke(new BasicStroke((float) bar, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		gc.draw(body);

		AffineTransform old = gc.getTransform();
		gc.translate(llx * bar * 0.26, lly * bar * 0.26);
		gc.setPaint(new GradientPaint(
			(float) (llx * r), (float) (lly * r), withAlpha(dim(CHAIN_SPEC, shade), a * 0.85f),
			(float) (llx * r * 0.15), (float) (lly * r * 0.15), withAlpha(CHAIN_SPEC, 0f)));
		gc.setStroke(new BasicStroke((float) (bar * 0.40), BasicStroke.CAP_ROUND,
			BasicStroke.JOIN_ROUND));
		gc.draw(body);
		gc.setTransform(old);
	}

	// --- the padlock on each chain ---
	//
	// Geometry is in units of `size`, in a frame whose origin is the point on
	// the chain the lock hangs from - which is also the middle of the shackle's
	// opening, so the chain runs THROUGH the U rather than past it. The bow and
	// the far leg are painted before the chain and the near leg and body after,
	// so the chain is genuinely inside the shackle and not merely behind a lock
	// parked on top of it.

	private static final double SHACKLE_BAR = 0.15;
	private static final double SHACKLE_R = 0.44;
	// The bow has to clear the chain running through it, and a chain link is
	// half as tall as this whole lock - so the U is deliberately tall. Sized
	// tight and the shackle vanishes behind the very chain it is holding.
	private static final double SHACKLE_TOP = -0.22;  // centre of the bow
	private static final double LOCK_BODY_TOP = 0.34;
	private static final double LOCK_BODY_H = 0.92;

	/** How far the lock has swung on its chain, in radians. */
	private static double lockTilt(long el, int seed) {
		return 0.07 * Math.sin(el * 0.0055 + seed * 2.0 + 0.9);
	}

	/** The bow of the shackle and its far leg: everything the chain runs over. */
	private static void drawLockBow(Graphics2D g2, double lx, double ly, int size,
		int dir, long el, int seed) {
		Graphics2D gl = (Graphics2D) g2.create();
		gl.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		gl.translate(lx, ly);
		gl.rotate(lockTilt(el, seed));
		double bar = size * SHACKLE_BAR;
		double r = size * SHACKLE_R;
		double top = size * SHACKLE_TOP;
		// the far leg is the one on the side the chain climbs towards, because
		// higher on this chest means further away
		double legX = -dir * r;
		Path2D.Double bow = new Path2D.Double();
		bow.moveTo(legX, size * LOCK_BODY_TOP);
		bow.lineTo(legX, top);
		bow.append(new Arc2D.Double(-r, top - r, r * 2, r * 2, dir > 0 ? 180 : 0, dir > 0 ? -180 : 180,
			Arc2D.OPEN), true);
		gl.setColor(withAlpha(Color.BLACK, 0.5f));
		gl.setStroke(new BasicStroke((float) bar + 1.2f, BasicStroke.CAP_ROUND,
			BasicStroke.JOIN_ROUND));
		gl.draw(bow);
		barMetal(gl, bow, LIGHT_X, LIGHT_Y, r, bar, 1f, 0.92f);
		gl.dispose();
	}

	/** The near leg and the body: everything that closes back over the chain. */
	private static void drawLockFront(Graphics2D g2, double lx, double ly, int size,
		int dir, long el, int seed) {
		Graphics2D gl = (Graphics2D) g2.create();
		gl.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		gl.translate(lx, ly);
		gl.rotate(lockTilt(el, seed));
		lockNearLeg(gl, size, dir);
		lockBody(gl, size, 1f);
		gl.dispose();
	}

	private static void lockNearLeg(Graphics2D gl, int size, int dir) {
		double bar = size * SHACKLE_BAR;
		double legX = dir * size * SHACKLE_R;
		Path2D.Double leg = new Path2D.Double();
		leg.moveTo(legX, size * SHACKLE_TOP);
		leg.lineTo(legX, size * (LOCK_BODY_TOP + 0.1));
		gl.setColor(withAlpha(Color.BLACK, 0.5f));
		gl.setStroke(new BasicStroke((float) bar + 1.2f, BasicStroke.CAP_ROUND,
			BasicStroke.JOIN_ROUND));
		gl.draw(leg);
		barMetal(gl, leg, LIGHT_X, LIGHT_Y, bar * 1.6, bar, 1f, 1f);
	}

	/**
	 * The lock body: an extruded side face behind a bevelled front plate, with a
	 * brass escutcheon around the keyhole. The extrusion is what stops it from
	 * reading as a rounded rectangle stuck to the wood.
	 */
	private static void lockBody(Graphics2D gl, int size, float a) {
		double bw = size;
		double bh = size * LOCK_BODY_H;
		double bx = -bw / 2;
		double by = size * LOCK_BODY_TOP;
		int arc = (int) (size * 0.34);
		double dz = size * 0.10;

		// contact shadow on the chest, then the extruded right/bottom faces
		gl.setColor(withAlpha(Color.BLACK, a * 0.42f));
		gl.fillRoundRect((int) (bx + dz * 1.5), (int) (by + dz * 1.7), (int) bw, (int) bh,
			arc, arc);
		gl.setPaint(new GradientPaint((float) bx, (float) by, brighten(LOCK_BODY_LO, 1.6f),
			(float) (bx + bw + dz), (float) (by + bh + dz), dim(LOCK_BODY_LO, 0.7f)));
		gl.fillRoundRect((int) (bx + dz), (int) (by + dz), (int) bw, (int) bh, arc, arc);

		// front plate
		gl.setPaint(new GradientPaint((float) bx, (float) by, LOCK_BODY_HI,
			(float) (bx + bw), (float) (by + bh), LOCK_BODY_LO));
		gl.fillRoundRect((int) bx, (int) by, (int) bw, (int) bh, arc, arc);
		// bevel: a lit band across the top and a bright edge on the top-left
		gl.setPaint(new GradientPaint(0f, (float) by, withAlpha(CHAIN_SPEC, a * 0.30f),
			0f, (float) (by + bh * 0.42), withAlpha(CHAIN_SPEC, 0f)));
		gl.fillRoundRect((int) bx + 1, (int) by + 1, (int) bw - 2, (int) (bh * 0.45), arc, arc);
		gl.setColor(withAlpha(CHAIN_SPEC, a * 0.55f));
		gl.setStroke(new BasicStroke(1.3f));
		gl.drawArc((int) bx + 1, (int) by + 1, arc, arc, 95, 80);
		gl.setColor(withAlpha(Color.BLACK, a * 0.55f));
		gl.drawRoundRect((int) bx, (int) by, (int) bw, (int) bh, arc, arc);

		// scuffs, so the face is a used object and not a swatch
		gl.setColor(withAlpha(CHAIN_SPEC, a * 0.10f));
		gl.setStroke(new BasicStroke(1f));
		gl.drawLine((int) (bx + bw * 0.18), (int) (by + bh * 0.30),
			(int) (bx + bw * 0.44), (int) (by + bh * 0.26));
		gl.drawLine((int) (bx + bw * 0.55), (int) (by + bh * 0.78),
			(int) (bx + bw * 0.84), (int) (by + bh * 0.72));

		// the two holes the shackle enters. Without them the legs simply stop at
		// the body edge and the whole lock reads as a sticker on the chest.
		double hx = size * SHACKLE_R;
		double hr2 = size * SHACKLE_BAR * 0.68;
		for (int s = -1; s <= 1; s += 2) {
			gl.setColor(withAlpha(new Color(9, 9, 12), a * 0.92f));
			gl.fillOval((int) (s * hx - hr2), (int) (by - hr2 * 0.6), (int) (hr2 * 2),
				(int) (hr2 * 1.5));
			gl.setColor(withAlpha(CHAIN_SPEC, a * 0.28f));
			gl.drawArc((int) (s * hx - hr2), (int) (by - hr2 * 0.6), (int) (hr2 * 2),
				(int) (hr2 * 1.5), 195, 150);
		}

		// brass escutcheon, recessed into the face, and the keyhole through it
		double kx = 0;
		double ky = by + bh * 0.54;
		double kr = size * 0.185;
		gl.setColor(withAlpha(Color.BLACK, a * 0.55f));
		gl.fillOval((int) (kx - kr - 1), (int) (ky - kr), (int) (kr * 2 + 2), (int) (kr * 2 + 2));
		gl.setPaint(new GradientPaint((float) (kx - kr), (float) (ky - kr), LOCK_GOLD,
			(float) (kx + kr), (float) (ky + kr), METAL_GOLD_LO));
		gl.fillOval((int) (kx - kr), (int) (ky - kr), (int) (kr * 2), (int) (kr * 2));
		gl.setColor(withAlpha(METAL_GOLD_HI, a * 0.5f));
		gl.setStroke(new BasicStroke(1f));
		gl.drawArc((int) (kx - kr), (int) (ky - kr), (int) (kr * 2), (int) (kr * 2), 70, 130);
		gl.setColor(withAlpha(new Color(12, 9, 5), a));
		double hr = kr * 0.44;
		gl.fillOval((int) (kx - hr), (int) (ky - hr * 1.3), (int) (hr * 2), (int) (hr * 2));
		Path2D.Double slot = new Path2D.Double();
		slot.moveTo(kx - hr * 0.75, ky);
		slot.lineTo(kx + hr * 0.75, ky);
		slot.lineTo(kx + hr * 0.35, ky + kr * 0.95);
		slot.lineTo(kx - hr * 0.35, ky + kr * 0.95);
		slot.closePath();
		gl.fill(slot);
	}

	/**
	 * The lock giving way: a flash, the shackle springing open at the bow and
	 * both halves tumbling off, the body dropping under it, and shrapnel. Pure
	 * function of {@code since} - the ms elapsed since it broke.
	 */
	private static void drawLockBreak(Graphics2D g2, double lx, double ly, int size, long since) {
		float u = clamp01f(since / (float) LOCK_BREAK_MS);
		double ts = since / 1000.0;
		float vis = (float) (1 - smoothstep(Math.max(0, (u - 0.6) / 0.4)));
		Graphics2D gl = (Graphics2D) g2.create();
		gl.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		gl.translate(lx, ly);

		// a bloom, not a ring: struck steel throws light and grit, and a clean
		// expanding outline reads as a vector effect laid over the scene
		if (u < 0.30f) {
			float f = 1 - u / 0.30f;
			for (int i = 3; i >= 1; i--) {
				int rr = (int) (size * (0.30 + i * 0.42) * (1 + (1 - f) * 0.7));
				gl.setColor(withAlpha(i == 1 ? GLOW_HOT : GLOW_WARM, f * f * 0.30f));
				gl.fillOval(-rr, -rr, rr * 2, rr * 2);
			}
		}

		double bar = size * SHACKLE_BAR;
		double r = size * SHACKLE_R;
		double top = size * SHACKLE_TOP;
		for (int s = 0; s < 2; s++) {
			int sgn = s == 0 ? -1 : 1;
			AffineTransform old = gl.getTransform();
			gl.translate(sgn * 230 * ts, -150 * ts + 820 * ts * ts);
			gl.rotate(sgn * ts * 8.5);
			Path2D.Double half = new Path2D.Double();
			half.moveTo(sgn * r, size * LOCK_BODY_TOP);
			half.lineTo(sgn * r, top);
			half.append(new Arc2D.Double(-r, top - r, r * 2, r * 2, sgn > 0 ? 0 : 180,
				sgn > 0 ? 88 : -88, Arc2D.OPEN), true);
			barMetal(gl, half, LIGHT_X, LIGHT_Y, r, bar, vis, 1f);
			gl.setTransform(old);
		}

		AffineTransform old = gl.getTransform();
		gl.translate(28 * ts, 60 * ts + 900 * ts * ts);
		gl.rotate(ts * 2.4);
		lockBody(gl, size, vis);
		gl.setTransform(old);

		// grit, drawn as short trails along its own velocity rather than as dots
		gl.setStroke(new BasicStroke(1.4f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		for (int p = 0; p < 14; p++) {
			float a1 = hash01(p * 151 + 3);
			float a2 = hash01(p * 151 + 4);
			double ang = a1 * Math.PI * 2;
			double sp = 90 + a2 * 260;
			double vx = Math.cos(ang) * sp;
			double vy = Math.sin(ang) * sp + 760 * ts;
			double fx = vx * ts;
			double fy = Math.sin(ang) * sp * ts + 380 * ts * ts;
			double trail = Math.min(7, Math.hypot(vx, vy) * 0.016);
			double m = Math.max(1e-3, Math.hypot(vx, vy));
			gl.setColor(withAlpha((p & 1) == 0 ? CHAIN_SPEC : METAL_GOLD_HI,
				vis * (0.55f + 0.45f * a2)));
			gl.draw(new Line2D.Double(fx, fy,
				fx - vx / m * trail, fy - vy / m * trail));
		}
		gl.dispose();
	}

	// --- palette helpers ---

	private static Color bandHi(Tuning.Chest tier) {
		switch (tier) {
			case RUSTY:
				return METAL_RUST_HI;
			case BATTERED:
				return METAL_WORN_HI;
			case GILDED:
				return METAL_SILVER_HI;
			default:
				return METAL_GOLD_HI;
		}
	}

	private static Color bandLo(Tuning.Chest tier) {
		switch (tier) {
			case RUSTY:
				return METAL_RUST_LO;
			case BATTERED:
				return METAL_WORN_LO;
			case GILDED:
				return METAL_SILVER_LO;
			default:
				return METAL_GOLD_LO;
		}
	}

	/** Tiers with worn (dimmed) wood; Rusty is one visible step shabbier. */
	private static boolean worn(Tuning.Chest tier) {
		return tier == Tuning.Chest.BATTERED || tier == Tuning.Chest.RUSTY;
	}

	// --- math/color utilities (mirrors RevealOverlay's, kept private) ---

	private static double clamp01(double v) {
		return v <= 0 ? 0 : (v >= 1 ? 1 : v);
	}

	private static float clamp01f(float v) {
		return v <= 0 ? 0 : (v >= 1 ? 1 : v);
	}

	private static double smoothstep(double t) {
		t = clamp01(t);
		return t * t * (3 - 2 * t);
	}

	private static double lerp(double a, double b, double t) {
		return a + (b - a) * t;
	}

	private static float hash01(int n) {
		int h = n * 0x9E3779B9;
		h ^= h >>> 16;
		h *= 0x85EBCA6B;
		h ^= h >>> 13;
		return (h & 0x7FFFFFFF) / (float) 0x7FFFFFFF;
	}

	private static Color withAlpha(Color c, float alpha) {
		int a = Math.max(0, Math.min(255, Math.round(alpha * 255f)));
		return new Color(c.getRed(), c.getGreen(), c.getBlue(), a);
	}

	private static Color dim(Color c, float f) {
		return new Color((int) (c.getRed() * f), (int) (c.getGreen() * f), (int) (c.getBlue() * f));
	}

	private static Color brighten(Color c, float f) {
		return new Color(Math.min(255, (int) (c.getRed() * f)),
			Math.min(255, (int) (c.getGreen() * f)),
			Math.min(255, (int) (c.getBlue() * f)));
	}

	private static Color mix(Color a, Color b, float t) {
		float u = clamp01f(t);
		return new Color(
			(int) (a.getRed() + (b.getRed() - a.getRed()) * u),
			(int) (a.getGreen() + (b.getGreen() - a.getGreen()) * u),
			(int) (a.getBlue() + (b.getBlue() - a.getBlue()) * u));
	}

	public static final int ART_W = 300;
	public static final int ART_H = 225;
	public static final int PAD_X = 34;
	public static final int PAD_Y = 26;

	public static void drawStatic(Graphics2D g, int cx, int cy, int w, int h, Tuning.Chest tier,
		Color trim, boolean back) {
		Graphics2D g2 = (Graphics2D) g.create();
		g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		int x = cx - w / 2;
		int top = cy - h / 2;
		int bottom = cy + h / 2;
		int frontTopY = top + (int) (h * LID_FRONT_FRAC) + (int) (h * LID_TOP_FRAC);
		int inset = (int) (w * 0.07);
		int slant = (int) (w * SLANT_FRAC);
		if (back) {
			drawDropShadow(g2, cx, bottom, w, h);
			drawBackRim(g2, x, w, inset, top, frontTopY);
		}
		else {
			drawBody(g2, x, frontTopY, bottom, w, slant, tier, trim);
		}
		g2.dispose();
	}

	public static void main(String[] args) throws Exception {
		java.io.File dir = new java.io.File(args[0]);
		dir.mkdirs();
		Color[] trims = {new Color(122, 82, 46), new Color(139, 98, 46),
			new Color(198, 202, 212), new Color(230, 190, 80)};
		for (int part = 0; part < 2; part++) {
			for (Tuning.Chest t : Tuning.Chest.values()) {
				java.awt.image.BufferedImage img = new java.awt.image.BufferedImage(
					ART_W + PAD_X * 2, ART_H + PAD_Y * 2,
					java.awt.image.BufferedImage.TYPE_INT_ARGB);
				Graphics2D g = img.createGraphics();
				drawStatic(g, ART_W / 2 + PAD_X, ART_H / 2 + PAD_Y, ART_W, ART_H, t,
					trims[t.ordinal()], part == 0);
				g.dispose();
				javax.imageio.ImageIO.write(img, "png", new java.io.File(dir,
					(part == 0 ? "chest-back-" : "chest-body-") + t.name().toLowerCase() + ".png"));
			}
		}
		System.out.println("sprites written");
	}
}

package com.gachaman.tools;

import com.gachaman.model.*;
import com.google.gson.*;
import java.io.*;
import java.nio.charset.*;
import java.nio.file.*;
import java.util.*;
import net.runelite.api.SpriteID;

/**
 * Authors {@code loadout-board.json}: where each of the eleven GearSlot sockets
 * sits on the in-game loadout board, and which native equipment silhouette fills
 * it while it is empty.
 *
 * <p>Both tables are pure data — a column, a y offset and a sprite id per slot —
 * and the overlay that reads them used to spell all three out in code: eleven
 * {@code socketRects.put(...)} calls and an eleven-arm switch returning
 * {@code SpriteID.EQUIPMENT_SLOT_*}. That is 415 tokens of the Plugin Hub's
 * budget spent on a lookup table, and {@code src/main/resources} is not counted
 * at all, so the table belongs here.
 *
 * <p>The sprite ids stay spelled as {@link SpriteID} constants for exactly the
 * reason {@link WeaponTypes} keeps its dbrows as {@code DBTableID} constants:
 * the compiler checks a name and nothing checks a number, and a mistyped sprite
 * id does not fail loudly — it draws the wrong silhouette, or none, forever.
 * {@code LoadoutBoardResourceTest} pins the shipped resource back to this
 * declaration so the two cannot drift.
 *
 * <p><b>The column is an index, not an x.</b> The three columns are derived from
 * {@code BOARD_W} and {@code SOCKET} in the overlay, so writing absolute x
 * values here would silently desynchronise the board the day either constant
 * moved. The y offsets are absolute because nothing derives them.
 *
 * <p>Regenerate by running this class's {@code main} on the test classpath, or
 * {@code ./gradlew loadoutBoard}.
 */
public final class LoadoutBoard {
	private LoadoutBoard() {
	}

	private static final String NOTE = "Authored by com.gachaman.tools.LoadoutBoard from"
		+ " SpriteID.EQUIPMENT_SLOT_* constants. Do not hand-edit:"
		+ " LoadoutBoardResourceTest pins this file to those constants. 'col' is an"
		+ " index into the overlay's three-column layout (0 left, 1 middle, 2 right),"
		+ " not an absolute x — the columns are derived from BOARD_W and SOCKET.";

	/**
	 * One socket: its grid cell, its pixel y on the overlay, and its silhouette.
	 *
	 * <p>{@code row} and {@code y} are the SAME position measured for the two
	 * views of this board — the sidebar's GridBagLayout wants a row index, the
	 * in-game overlay wants pixels. Today {@code y == 28 + 44 * row} exactly, and
	 * both are written out rather than one derived from the other: the resource
	 * costs nothing (src/main/resources is not counted against the Hub's budget)
	 * and a formula in the overlay would be a second place for the layout to live.
	 * {@code LoadoutBoardResourceTest} pins the relationship so the two views
	 * cannot silently disagree about where a socket is.
	 */
	private static Map<String, Object> socket(int col, int row, int y, int sprite) {
		Map<String, Object> entry = new LinkedHashMap<>();
		entry.put("col", col);
		entry.put("row", row);
		entry.put("y", y);
		entry.put("sprite", sprite);
		return entry;
	}

	/** The overlay's y for the top row, and the gap between rows. */
	public static final int TOP = 28;
	public static final int PITCH = 44;

	private static Map<String, Object> socket(int col, int row, int sprite) {
		return socket(col, row, TOP + PITCH * row, sprite);
	}

	/**
	 * The classic equipment-tab arrangement, in the reading order the eye takes
	 * down the board rather than GearSlot's declaration order — both readers key
	 * by slot name, so the order here is documentation only.
	 *
	 * <p>One table, two views. The sidebar's LoadoutTab and the in-game
	 * LoadoutOverlay drew the same eleven sockets in the same arrangement from two
	 * separate hand-written tables, which is one edit away from a board that
	 * disagrees with itself about where the ring goes.
	 */
	public static Map<String, Object> sockets() {
		Map<String, Object> sockets = new LinkedHashMap<>();
		sockets.put(GearSlot.HEAD.name(), socket(1, 0, SpriteID.EQUIPMENT_SLOT_HEAD));
		sockets.put(GearSlot.CAPE.name(), socket(0, 1, SpriteID.EQUIPMENT_SLOT_CAPE));
		sockets.put(GearSlot.AMULET.name(), socket(1, 1, SpriteID.EQUIPMENT_SLOT_NECK));
		sockets.put(GearSlot.AMMO.name(), socket(2, 1, SpriteID.EQUIPMENT_SLOT_AMMUNITION));
		sockets.put(GearSlot.WEAPON.name(), socket(0, 2, SpriteID.EQUIPMENT_SLOT_WEAPON));
		sockets.put(GearSlot.BODY.name(), socket(1, 2, SpriteID.EQUIPMENT_SLOT_TORSO));
		sockets.put(GearSlot.SHIELD.name(), socket(2, 2, SpriteID.EQUIPMENT_SLOT_SHIELD));
		sockets.put(GearSlot.LEGS.name(), socket(1, 3, SpriteID.EQUIPMENT_SLOT_LEGS));
		sockets.put(GearSlot.HANDS.name(), socket(0, 4, SpriteID.EQUIPMENT_SLOT_HANDS));
		sockets.put(GearSlot.FEET.name(), socket(1, 4, SpriteID.EQUIPMENT_SLOT_FEET));
		sockets.put(GearSlot.RING.name(), socket(2, 4, SpriteID.EQUIPMENT_SLOT_RING));
		return sockets;
	}

	public static void main(String[] args) throws IOException {
		Map<String, Object> file = new LinkedHashMap<>();
		file.put("note", NOTE);
		file.put("sockets", sockets());

		File out = new File("src/main/resources/com/gachaman/data/loadout-board.json");
		try (Writer w = Files.newBufferedWriter(out.toPath(), StandardCharsets.UTF_8)) {
			new GsonBuilder().setPrettyPrinting().create().toJson(file, w);
		}
		System.out.println("wrote " + out + " (" + sockets().size() + " sockets)");
	}
}

package com.gachaman.tools;

import java.awt.*;
import java.awt.geom.*;
import java.awt.image.*;
import java.io.*;
import javax.imageio.*;

/**
 * Authors the tier-INDEPENDENT parchment texture: the cylinder bow across the
 * sheet and the laid-paper fibre. Both are pure fractions of the sheet's width
 * and height, so one image stretches to any scroll size exactly.
 *
 * <p>The base gradient and the hairline border stay procedural in ScrollPainter
 * because they carry the difficulty's colour, and the aged edges and vignette
 * stay because they clamp to a pixel count rather than a fraction.
 */
public final class ScrollArt {
	public static final int W = 240;
	public static final int H = 360;
	private static final Color BOW_SHADE = new Color(92, 68, 36, 70);
	private static final Color BOW_MID = new Color(120, 96, 60, 22);
	private static final Color BOW_LIGHT = new Color(255, 248, 226, 34);
	private static final Color FIBRE = new Color(120, 96, 60, 11);
	private static final float[][] FIBRE_AT = {
		{0.11f, 0.06f, 0.62f}, {0.26f, 0.31f, 0.55f}, {0.38f, 0.04f, 0.34f},
		{0.57f, 0.22f, 0.71f}, {0.69f, 0.09f, 0.41f}, {0.84f, 0.36f, 0.52f},
	};

	public static void main(String[] a) throws Exception {
		new File(a[0]).mkdirs();
		BufferedImage img = new BufferedImage(W, H, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setPaint(new LinearGradientPaint(new Point2D.Float(0, 0), new Point2D.Float(W, 0),
			new float[]{0f, 0.18f, 0.5f, 0.82f, 1f},
			new Color[]{BOW_SHADE, BOW_MID, BOW_LIGHT, BOW_MID, BOW_SHADE}));
		g.fillRect(0, 0, W, H);
		g.setColor(FIBRE);
		for (float[] f : FIBRE_AT) {
			int fy = (int) (H * f[0]);
			int fx = (int) (W * f[1]);
			int fw = (int) (W * f[2]);
			g.drawLine(fx, fy, Math.min(W - 3, fx + fw), fy);
		}
		g.dispose();
		ImageIO.write(img, "png", new File(a[0] + "/parchment-texture.png"));
		System.out.println("parchment texture written " + W + "x" + H);
	}

	private ScrollArt() {
	}
}

package com.gachaman.tools;

import java.awt.*;
import java.awt.geom.*;
import java.awt.image.*;
import java.io.*;
import javax.imageio.*;
import net.runelite.client.ui.*;

/**
 * Authors the plugin's flat icons as PNGs: the sidebar mark, the Plugin Hub
 * listing art, and the GitHub / Ko-fi link icons in both their rest and hover
 * colours.
 *
 * <p>These were painted at runtime by PanelIcon and by two GachamanPanel
 * methods. Every one of them is a FIXED drawing — no animation, no tint that
 * varies with state, nothing a player action changes — so painting them on
 * every panel build was re-deriving a constant. The drawing code lives here
 * now, in test scope, which keeps the art reviewable and regenerable while
 * costing the shipped plugin nothing but six small PNGs.
 *
 * <p>Run with {@code ./gradlew iconArt}. The output is committed; this is an
 * authoring tool, not a build step.
 */
public final class IconArt {
	private static final int GRID = 16;
	private static final Color CARD_FILL = new Color(88, 52, 140);
	private static final Color CARD_TRIM = new Color(212, 175, 55);
	private static final Color CHEST_FILL = new Color(112, 82, 46);
	private static final Color CHEST_TRIM = new Color(230, 190, 80);
	private static final int LINK_ICON_SIZE = 18;
	/** The album header's stardust sparkle and "Owned only" checkbox. */
	private static final int ALBUM_ICON_SIZE = 13;
	private static final Color STARDUST = new Color(190, 170, 255);

	private static final String RES = "src/main/resources/com/gachaman/ui/";

	private IconArt() {
	}

	public static void main(String[] args) throws Exception {
		new File(RES).mkdirs();
		ImageIO.write(panelIcon(GRID), "png", new File(RES + "panel-icon.png"));
		// the Plugin Hub listing art is 48x72; same drawing, fitted and centred
		ImageIO.write(hubIcon(48, 72), "png", new File("icon.png"));
		ImageIO.write(githubIcon(false), "png", new File(RES + "link-github.png"));
		ImageIO.write(githubIcon(true), "png", new File(RES + "link-github-hover.png"));
		ImageIO.write(kofiIcon(false), "png", new File(RES + "link-kofi.png"));
		ImageIO.write(kofiIcon(true), "png", new File(RES + "link-kofi-hover.png"));
		ImageIO.write(stardustIcon(), "png", new File(RES + "stardust.png"));
		ImageIO.write(checkboxIcon(false), "png", new File(RES + "checkbox-off.png"));
		ImageIO.write(checkboxIcon(true), "png", new File(RES + "checkbox-on.png"));
		System.out.println("wrote 8 icons to " + RES + " and icon.png");
	}

	/**
	 * A 13x13 canvas with antialiasing on — the surface both album icons below
	 * were painting onto, once per repaint, straight into the panel's Graphics.
	 *
	 * <p>Compositing an antialiased shape into a transparent ARGB buffer and then
	 * drawing that buffer SRC_OVER gives cov*src + (1-cov)*dst, which is what
	 * drawing the shape straight onto the destination gives — the identity
	 * ChestArt and CeremonyArt already rely on. It was measured for these two
	 * rather than assumed, and it is not quite bit-exact: no pixel moved, and on
	 * a white or transparent destination the two routes agreed exactly, but over
	 * the dark panel eight pixels per icon came out ±1 on one channel, because
	 * ARGB is stored non-premultiplied and a layer rounds once more than a direct
	 * draw. AlbumIconBakeTest holds the old drawing code and pins that band.
	 */
	private static Graphics2D iconCanvas(BufferedImage img) {
		Graphics2D g = img.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		return g;
	}

	/**
	 * The stardust counter's icon: a static 4-point sparkle in pale violet. No
	 * animation and no state — the "Blessed!" case recolours the LABEL, never
	 * this glyph — so the album was re-deriving a constant on every panel build.
	 */
	static BufferedImage stardustIcon() {
		int size = ALBUM_ICON_SIZE;
		BufferedImage img = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = iconCanvas(img);
		int cx = size / 2;
		int cy = size / 2;
		g.setColor(STARDUST);
		g.setStroke(new BasicStroke(1.4f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.drawLine(cx, 2, cx, size - 2);
		g.drawLine(2, cy, size - 2, cy);
		g.setStroke(new BasicStroke(1f));
		g.drawLine(cx - 2, cy - 2, cx + 2, cy + 2);
		g.drawLine(cx - 2, cy + 2, cx + 2, cy - 2);
		g.setColor(Color.WHITE);
		g.fillOval(cx - 1, cy - 1, 2, 2);
		g.dispose();
		return img;
	}

	/**
	 * The album's "Owned only" checkbox in both states: a dark rounded square
	 * with a light border, plus a crisp white 2px check mark when selected. The
	 * stock look-and-feel's check mark was nearly invisible on the dark panel,
	 * which is why the plugin draws its own.
	 *
	 * <p>The border is drawn at SIZE-1 so the 1px stroke lands inside the icon's
	 * own 13x13 box; the default STROKE_NORMALIZE then snaps it to the pixel
	 * grid, so nothing bleeds outside the raster this bakes into.
	 */
	static BufferedImage checkboxIcon(boolean selected) {
		int size = ALBUM_ICON_SIZE;
		BufferedImage img = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = iconCanvas(img);
		g.setColor(ColorScheme.DARKER_GRAY_COLOR);
		g.fillRoundRect(0, 0, size, size, 4, 4);
		g.setColor(ColorScheme.LIGHT_GRAY_COLOR);
		g.drawRoundRect(0, 0, size - 1, size - 1, 4, 4);
		if (selected) {
			g.setColor(Color.WHITE);
			g.setStroke(new BasicStroke(2f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			g.drawLine(3, 7, 5, 9);
			g.drawLine(5, 9, 10, 3);
		}
		g.dispose();
		return img;
	}

	/** The artwork centred on a non-square canvas, aspect preserved. */
	private static BufferedImage hubIcon(int width, int height) {
		int edge = Math.min(width, height);
		BufferedImage art = panelIcon(edge);
		BufferedImage canvas = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = canvas.createGraphics();
		g.drawImage(art, (width - edge) / 2, (height - edge) / 2, null);
		g.dispose();
		return canvas;
	}

	/** A gacha card peeking out behind a chest, authored on a 16x16 grid. */
	private static BufferedImage panelIcon(int size) {
		BufferedImage img = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		if (size != GRID) {
			// geometric accuracy, which is what an upscale wants. Deliberately NOT
			// set at 16x16: there the default (normalize) snaps the 1px outlines to
			// the pixel grid, and that crispness is the sidebar button as it ships.
			g.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);
		}
		double scale = size / (double) GRID;
		g.scale(scale, scale);
		g.setStroke(new BasicStroke(1f));

		g.setColor(CARD_FILL);
		g.fillRoundRect(1, 0, 8, 11, 3, 3);
		g.setColor(CARD_TRIM);
		g.drawRoundRect(1, 0, 8, 11, 3, 3);
		g.drawOval(3, 3, 4, 4);

		g.setColor(CHEST_FILL);
		g.fillRoundRect(4, 6, 11, 9, 3, 3);
		g.setColor(CHEST_TRIM);
		g.drawRoundRect(4, 6, 11, 9, 3, 3);
		g.drawLine(4, 9, 15, 9);
		g.fillRect(9, 8, 2, 3);
		g.dispose();
		return img;
	}

	/**
	 * The GitHub mark, drawn as a UNION of primitives rather than a traced bezier
	 * so the shape stays reviewable: ears, body, legs and tail as named parts.
	 */
	private static BufferedImage githubIcon(boolean hover) {
		BufferedImage image = new BufferedImage(LINK_ICON_SIZE, LINK_ICON_SIZE,
			BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		double s = LINK_ICON_SIZE / 18.0;
		g.scale(s, s);

		Area mark = new Area(new Ellipse2D.Float(1.7f, 4.2f, 14.6f, 10.2f));
		mark.add(new Area(triangle(3.1f, 6.8f, 3.5f, 1.6f, 7.6f, 4.6f)));
		mark.add(new Area(triangle(14.9f, 6.8f, 14.5f, 1.6f, 10.4f, 4.6f)));
		mark.add(new Area(new RoundRectangle2D.Float(5.5f, 11.6f, 2.4f, 5.6f, 1.8f, 1.8f)));
		mark.add(new Area(new RoundRectangle2D.Float(10.1f, 11.6f, 2.4f, 5.6f, 1.8f, 1.8f)));

		g.setColor(hover ? Color.WHITE : ColorScheme.LIGHT_GRAY_COLOR);
		g.fill(mark);
		g.setStroke(new BasicStroke(2.4f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.draw(new QuadCurve2D.Float(4.0f, 10.8f, 0.6f, 13.2f, 2.2f, 16.4f));
		g.dispose();
		return image;
	}

	/** The Ko-fi cup: a white mug and two steam wisps on the brand's coral plate. */
	private static BufferedImage kofiIcon(boolean hover) {
		BufferedImage image = new BufferedImage(LINK_ICON_SIZE, LINK_ICON_SIZE,
			BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		double s = LINK_ICON_SIZE / 18.0;
		g.scale(s, s);

		g.setColor(hover ? new Color(255, 110, 107) : new Color(214, 78, 75));
		g.fillRoundRect(0, 0, 18, 18, 6, 6);

		g.setColor(Color.WHITE);
		g.fillRoundRect(3, 8, 8, 7, 2, 2);
		g.setStroke(new BasicStroke(1.5f));
		g.drawArc(9, 8, 5, 5, 90, -180);
		g.fillRoundRect(2, 15, 11, 2, 1, 1);
		g.setStroke(new BasicStroke(1.4f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.draw(new QuadCurve2D.Float(5.2f, 6.6f, 6.8f, 4.8f, 5.2f, 2.8f));
		g.draw(new QuadCurve2D.Float(8.6f, 6.6f, 10.2f, 4.8f, 8.6f, 2.8f));
		g.dispose();
		return image;
	}

	private static Path2D.Float triangle(float x1, float y1, float x2, float y2,
		float x3, float y3) {
		Path2D.Float path = new Path2D.Float();
		path.moveTo(x1, y1);
		path.lineTo(x2, y2);
		path.lineTo(x3, y3);
		path.closePath();
		return path;
	}
}

package com.gachaman.tools;

import java.awt.*;
import java.awt.image.*;
import java.io.*;
import javax.imageio.*;

/**
 * Authors the Shop tab's chest-tile icons as PNGs — one per chest tier, in a
 * lit and a dimmed pass.
 *
 * <p>ShopTab.ChestTile used to paint this icon from scratch on every repaint.
 * It is a pure function of two things, the tier and whether the tile is
 * affordable, and neither of them is continuous: there are exactly eight
 * pictures it can ever produce. Re-deriving one of eight constants on every
 * paint cost the shipped plugin the drawing code, the two colour tables it read
 * and the desaturation helper it called — so the drawing moved here, into test
 * scope, where it stays reviewable and regenerable while the plugin ships eight
 * small PNGs instead. This is the same trade IconArt, ChestPainter, RollerArt
 * and CeremonyArt already make.
 *
 * <p><b>The drawing below is byte-for-byte the calls ShopTab made</b>, in the
 * same order, on a Graphics2D with the same antialiasing hint and the same
 * 1.5f stroke. That is what makes the swap invisible: antialiased shapes
 * composited SRC_OVER out of a transparent buffer land on the tile background
 * as {@code cov * src + (1 - cov) * dst}, which is what drawing them straight
 * onto that background already did — Porter-Duff OVER is associative, so
 * layering the icon's own overlaps first changes nothing. ShopIconBakeTest
 * pins that empirically rather than on my word for it.
 *
 * <p><b>One honest caveat, at UI scales above 1.</b> Everything above is about
 * an unscaled panel, where the measured difference is at most 2/255 on the
 * antialiased edges. On a scaled client the side panel hands ShopTab a
 * transformed Graphics2D, and a 44x42 raster is RESAMPLED there where vector
 * strokes would have been re-rendered at the higher resolution — so the chest
 * softens slightly while the tile's text, which still goes through drawString,
 * does not. That is a genuine change, not a rounding one. It is also the trade
 * this repo already ships for panel-icon.png, the link icons, the wheel chrome
 * and every ceremony frame, which is why it is taken here too rather than
 * quietly assumed away.
 *
 * <p>Deliberately depends on NOTHING but the JDK — not even Tuning, whose enum
 * order {@link #TIERS} mirrors (ShopIconBakeTest pins the two against each
 * other, so drift fails the build rather than mislabelling a chest). That keeps
 * this runnable straight from a JDK with no classpath at all:
 *
 * <pre>
 * javac -d /tmp/shopart src/test/java/com/gachaman/tools/ShopArt.java
 * java -cp /tmp/shopart com.gachaman.tools.ShopArt
 * </pre>
 *
 * <p>The output is committed; this is an authoring tool, not a build step.
 */
public final class ShopArt {
	private static final String RES = "src/main/resources/com/gachaman/ui/";

	/**
	 * Tier keys in Tuning.Chest declaration order. Lower case because they are
	 * also the file names, and because {@code name().toLowerCase()} is what
	 * ShopTab does to find them again.
	 */
	public static final String[] TIERS = {"rusty", "battered", "gilded", "ornate"};

	/** Chest body fill per tier. Was ShopTab.bodyColor(), which is now gone. */
	public static final Color[] BODY = {
		new Color(88, 60, 42),
		new Color(101, 84, 63),
		new Color(133, 105, 41),
		new Color(90, 56, 128)};

	/**
	 * Chest trim per tier. ShopTab keeps its own copy of this table because the
	 * tile BORDER still needs the lit trim colour at paint time; only the icon's
	 * use of it moved here.
	 */
	public static final Color[] TRIM = {
		new Color(154, 96, 52),
		new Color(146, 126, 96),
		new Color(230, 190, 80),
		new Color(255, 196, 60)};

	// The icon's box inside the tile, straight out of the old paintComponent.
	public static final int IX = 8;
	public static final int IY = 12;
	public static final int IW = 40;
	public static final int IH = 38;

	/**
	 * Where the sprite's top-left sits in tile coordinates, and how big it is.
	 *
	 * <p>Two pixels of margin on every side of the drawn extent: the 1.5f stroke
	 * hangs 0.75px outside the geometry and the antialiaser feathers about a
	 * pixel past that, so a canvas cropped to the nominal 40x38 box would shave
	 * the outline. The offsets are whole pixels on purpose — an integer
	 * translation reproduces the antialiasing coverage exactly, where a
	 * fractional one would resample it.
	 */
	public static final int ORIGIN_X = IX - 2;
	public static final int ORIGIN_Y = IY - 2;
	public static final int WIDTH = IW + 4;
	public static final int HEIGHT = IH + 4;

	private ShopArt() {
	}

	public static void main(String[] args) throws Exception {
		File dir = new File(args.length > 0 ? args[0] : RES);
		dir.mkdirs();
		for (int tier = 0; tier < TIERS.length; tier++) {
			for (int lit = 0; lit < 2; lit++) {
				ImageIO.write(chestIcon(tier, lit == 1), "png", new File(dir, name(tier, lit == 1)));
			}
		}
		System.out.println("wrote " + TIERS.length * 2 + " chest tile icons to " + dir);
	}

	/** The resource name ShopTab.chestIcon() rebuilds at load time. */
	public static String name(int tier, boolean lit) {
		return "chest-tile-" + TIERS[tier] + (lit ? "-lit" : "-dim") + ".png";
	}

	/** One baked icon, transparent everywhere the chest is not. */
	public static BufferedImage chestIcon(int tier, boolean lit) {
		BufferedImage img = new BufferedImage(WIDTH, HEIGHT, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g2 = img.createGraphics();
		g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		paint(g2, tier, lit, IX - ORIGIN_X, IY - ORIGIN_Y);
		g2.dispose();
		return img;
	}

	/**
	 * The chest itself, at (ix, iy) in whatever space the caller set up. Shared
	 * with the comparison test, which draws it at the tile coordinates the old
	 * ShopTab used so the two renderings can be diffed pixel for pixel.
	 *
	 * <p>A dimmed tile desaturates BOTH colours before drawing, which is exactly
	 * what ShopTab did — its dimming ran on {@code !affordable || remaining == 0},
	 * and a retired tile is never affordable (ChestTile's constructor ands the
	 * two together), so the second half of that test could never decide it.
	 */
	public static void paint(Graphics2D g2, int tier, boolean lit, int ix, int iy) {
		Color body = lit ? BODY[tier] : desaturate(BODY[tier]);
		Color trim = lit ? TRIM[tier] : desaturate(TRIM[tier]);
		int iw = IW;
		int ih = IH;
		g2.setColor(body);
		g2.fillRoundRect(ix, iy + ih / 3, iw, ih * 2 / 3, 6, 6);
		g2.fillArc(ix, iy, iw, ih * 2 / 3, 0, 180);
		g2.setColor(trim);
		g2.setStroke(new BasicStroke(1.5f));
		g2.drawRoundRect(ix, iy + ih / 3, iw, ih * 2 / 3, 6, 6);
		g2.drawArc(ix, iy, iw, ih * 2 / 3, 0, 180);
		g2.drawLine(ix, iy + ih / 3, ix + iw, iy + ih / 3);
		// clasp + keyhole
		g2.fillRect(ix + iw / 2 - 3, iy + ih / 3 - 3, 6, 9);
		g2.setColor(body.darker());
		g2.fillOval(ix + iw / 2 - 1, iy + ih / 3, 3, 4);
	}

	/** Was ShopTab.desaturate(): a luma-weighted pull toward grey, then darker(). */
	public static Color desaturate(Color color) {
		int gray = (int) (color.getRed() * 0.3 + color.getGreen() * 0.59 + color.getBlue() * 0.11);
		return new Color(
			(color.getRed() + gray * 2) / 3,
			(color.getGreen() + gray * 2) / 3,
			(color.getBlue() + gray * 2) / 3).darker();
	}
}

package com.gachaman.tools;

import java.awt.*;
import java.awt.geom.*;
import java.awt.image.*;
import java.io.*;
import javax.imageio.*;

/** Procedural bow+fibre vs the stretched sprite, at several sheet sizes. */
public final class ScrollCmp {
	private static final Color BOW_SHADE = new Color(92, 68, 36, 70);
	private static final Color BOW_MID = new Color(120, 96, 60, 22);
	private static final Color BOW_LIGHT = new Color(255, 248, 226, 34);
	private static final Color FIBRE = new Color(120, 96, 60, 11);
	private static final float[][] FIBRE_AT = {
		{0.11f, 0.06f, 0.62f}, {0.26f, 0.31f, 0.55f}, {0.38f, 0.04f, 0.34f},
		{0.57f, 0.22f, 0.71f}, {0.69f, 0.09f, 0.41f}, {0.84f, 0.36f, 0.52f},
	};

	public static void main(String[] a) throws Exception {
		int[][] sizes = {{240, 360}, {180, 300}, {300, 420}};
		for (int[] s : sizes) {
			int w = s[0];
			int h = s[1];
			BufferedImage p = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
			Graphics2D g = p.createGraphics();
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g.setPaint(new LinearGradientPaint(new Point2D.Float(0, 0), new Point2D.Float(w, 0),
				new float[]{0f, 0.18f, 0.5f, 0.82f, 1f},
				new Color[]{BOW_SHADE, BOW_MID, BOW_LIGHT, BOW_MID, BOW_SHADE}));
			g.fillRect(0, 0, w, h);
			g.setColor(FIBRE);
			for (float[] f : FIBRE_AT) {
				int fy = (int) (h * f[0]);
				int fx = (int) (w * f[1]);
				int fw = (int) (w * f[2]);
				g.drawLine(fx, fy, Math.min(w - 3, fx + fw), fy);
			}
			g.dispose();
			ImageIO.write(p, "png", new File(a[0] + "/parch_proc_" + w + ".png"));

			BufferedImage q = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
			g = q.createGraphics();
			g.setRenderingHint(RenderingHints.KEY_INTERPOLATION,
				RenderingHints.VALUE_INTERPOLATION_BILINEAR);
			try (InputStream in = ScrollCmp.class.getResourceAsStream(
				"/com/gachaman/art/parchment-texture.png")) {
				Image tex = ImageIO.read(in);
				g.drawImage(tex, 0, 0, w, h, null);
			}
			g.dispose();
			ImageIO.write(q, "png", new File(a[0] + "/parch_spr_" + w + ".png"));
		}
		System.out.println("rendered 3 sizes");
	}

	private ScrollCmp() {
	}
}

package com.gachaman.tools;

import java.awt.*;
import java.awt.geom.*;
import java.awt.image.*;
import java.io.*;
import javax.imageio.*;

/**
 * Authors the static chrome of the style roulette. Test scope: never shipped,
 * never counted, and it keeps the procedural source so the art can be redrawn.
 *
 * <p>Only the pieces that do NOT rotate with the wheel and do NOT depend on the
 * result live here. The wedges, separators, labels, pulse and glow stay in
 * RevealOverlay because they turn, tint or animate.
 */
public final class WheelArt {
	public static final int R = 190;
	public static final int FACE = 440;
	public static final int FACE_C = 220;
	private static final Color GOLD = new Color(230, 190, 80);
	private static final Color RIM_HI = new Color(214, 218, 228);
	private static final Color RIM_LO = new Color(96, 100, 112);

	private static Graphics2D aa(BufferedImage img) {
		Graphics2D g = img.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		return g;
	}

	public static void main(String[] a) throws Exception {
		File dir = new File(a[0]);
		dir.mkdirs();
		int cx = FACE_C;
		int cy = FACE_C;

		// 1. drop shadow under the whole wheel (drawn BEFORE the wedges)
		BufferedImage shadow = new BufferedImage(FACE, FACE, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = aa(shadow);
		g.setColor(new Color(0, 0, 0, 80));
		g.fillOval(cx - R - 10, cy - R - 2, (R + 10) * 2, (R + 10) * 2);
		g.dispose();
		ImageIO.write(shadow, "png", new File(dir, "wheel-shadow.png"));

		// 2. sheen + metallic rim + bolts (drawn AFTER the separators)
		BufferedImage rim = new BufferedImage(FACE, FACE, BufferedImage.TYPE_INT_ARGB);
		g = aa(rim);
		Graphics2D gs = (Graphics2D) g.create();
		gs.setClip(new Ellipse2D.Float(cx - R, cy - R, R * 2, R * 2));
		for (int i = 4; i >= 1; i--) {
			float al = 0.030f * (5 - i);
			gs.setColor(new Color(255, 255, 255, (int) (al * 255)));
			int sw = (int) (R * (0.6 + i * 0.22));
			gs.fillOval(cx - (int) (R * 0.75), cy - (int) (R * 0.85), sw, (int) (sw * 0.8));
		}
		gs.dispose();
		g.setPaint(new GradientPaint(cx - R, cy - R, RIM_HI, cx + R, cy + R, RIM_LO));
		g.setStroke(new BasicStroke(11f));
		g.drawOval(cx - R - 5, cy - R - 5, (R + 5) * 2, (R + 5) * 2);
		g.setColor(GOLD);
		g.setStroke(new BasicStroke(2f));
		g.drawOval(cx - R - 11, cy - R - 11, (R + 11) * 2, (R + 11) * 2);
		g.drawOval(cx - R + 1, cy - R + 1, (R - 1) * 2, (R - 1) * 2);
		for (int b = 0; b < 12; b++) {
			double ba = Math.toRadians(b * 30 + 15);
			int bx = cx + (int) (Math.cos(ba) * (R + 5));
			int by = cy - (int) (Math.sin(ba) * (R + 5));
			g.setColor(RIM_LO);
			g.fillOval(bx - 3, by - 3, 6, 6);
			g.setColor(RIM_HI);
			g.fillOval(bx - 2, by - 3, 3, 3);
		}
		g.dispose();
		ImageIO.write(rim, "png", new File(dir, "wheel-rim.png"));

		// 3. hub sigil - fixed 44px, independent of the wheel radius
		BufferedImage hub = new BufferedImage(64, 64, BufferedImage.TYPE_INT_ARGB);
		g = aa(hub);
		int hx = 32;
		int hy = 30;
		g.setColor(new Color(0, 0, 0, 90));
		g.fillOval(hx - 24, hy - 21, 48, 48);
		g.setPaint(new GradientPaint(hx - 22, hy - 22, new Color(52, 42, 22),
			hx + 22, hy + 22, new Color(24, 18, 8)));
		g.fillOval(hx - 22, hy - 22, 44, 44);
		g.setColor(GOLD);
		g.setStroke(new BasicStroke(2.2f));
		g.drawOval(hx - 22, hy - 22, 44, 44);
		g.setColor(new Color(230, 190, 80, 204));
		g.setStroke(new BasicStroke(1.6f));
		int r9 = 9;
		g.drawOval(hx - r9, hy - r9, r9 * 2, r9 * 2);
		int d = r9 + r9 / 2;
		g.drawLine(hx, hy - d, hx + d, hy);
		g.drawLine(hx + d, hy, hx, hy + d);
		g.drawLine(hx, hy + d, hx - d, hy);
		g.drawLine(hx - d, hy, hx, hy - d);
		g.dispose();
		ImageIO.write(hub, "png", new File(dir, "wheel-hub.png"));

		// 4. pointer flap + pivot cap - a fixed 30px shape whatever the radius
		BufferedImage ptr = new BufferedImage(40, 48, BufferedImage.TYPE_INT_ARGB);
		g = aa(ptr);
		int px = 20;
		int py = 12;
		Path2D.Double flap = new Path2D.Double();
		flap.moveTo(px - 11, py - 4);
		flap.lineTo(px + 11, py - 4);
		flap.lineTo(px + 3, py + 18);
		flap.lineTo(px, py + 26);
		flap.lineTo(px - 3, py + 18);
		flap.closePath();
		g.setPaint(new GradientPaint(px - 10, py, new Color(250, 216, 110),
			px + 10, py + 26, new Color(150, 110, 30)));
		g.fill(flap);
		g.setColor(new Color(60, 44, 10));
		g.setStroke(new BasicStroke(1.6f));
		g.draw(flap);
		g.dispose();
		ImageIO.write(ptr, "png", new File(dir, "wheel-pointer.png"));
		System.out.println("wheel sprites written");
	}

	private WheelArt() {
	}

	/** The chrome as RevealOverlay drew it, for the comparison harness. */
	public static void drawChrome(Graphics2D g, int cx, int cy, int radius) {
		g.setColor(new Color(0, 0, 0, 80));
		g.fillOval(cx - radius - 10, cy - radius - 2, (radius + 10) * 2, (radius + 10) * 2);
		Graphics2D gs = (Graphics2D) g.create();
		gs.setClip(new Ellipse2D.Float(cx - radius, cy - radius, radius * 2, radius * 2));
		for (int i = 4; i >= 1; i--) {
			float al = 0.030f * (5 - i);
			gs.setColor(new Color(255, 255, 255, (int) (al * 255)));
			int sw = (int) (radius * (0.6 + i * 0.22));
			gs.fillOval(cx - (int) (radius * 0.75), cy - (int) (radius * 0.85), sw, (int) (sw * 0.8));
		}
		gs.dispose();
		g.setPaint(new GradientPaint(cx - radius, cy - radius, RIM_HI, cx + radius, cy + radius, RIM_LO));
		g.setStroke(new BasicStroke(11f));
		g.drawOval(cx - radius - 5, cy - radius - 5, (radius + 5) * 2, (radius + 5) * 2);
		g.setColor(GOLD);
		g.setStroke(new BasicStroke(2f));
		g.drawOval(cx - radius - 11, cy - radius - 11, (radius + 11) * 2, (radius + 11) * 2);
		g.drawOval(cx - radius + 1, cy - radius + 1, (radius - 1) * 2, (radius - 1) * 2);
		for (int b = 0; b < 12; b++) {
			double ba = Math.toRadians(b * 30 + 15);
			int bx = cx + (int) (Math.cos(ba) * (radius + 5));
			int by = cy - (int) (Math.sin(ba) * (radius + 5));
			g.setColor(RIM_LO);
			g.fillOval(bx - 3, by - 3, 6, 6);
			g.setColor(RIM_HI);
			g.fillOval(bx - 2, by - 3, 3, 3);
		}
		int hx = cx;
		int hy = cy;
		g.setColor(new Color(0, 0, 0, 90));
		g.fillOval(hx - 24, hy - 21, 48, 48);
		g.setPaint(new GradientPaint(hx - 22, hy - 22, new Color(52, 42, 22),
			hx + 22, hy + 22, new Color(24, 18, 8)));
		g.fillOval(hx - 22, hy - 22, 44, 44);
		g.setColor(GOLD);
		g.setStroke(new BasicStroke(2.2f));
		g.drawOval(hx - 22, hy - 22, 44, 44);
		g.setColor(new Color(230, 190, 80, 204));
		g.setStroke(new BasicStroke(1.6f));
		int r9 = 9;
		g.drawOval(hx - r9, hy - r9, r9 * 2, r9 * 2);
		int d = r9 + r9 / 2;
		g.drawLine(hx, hy - d, hx + d, hy);
		g.drawLine(hx + d, hy, hx, hy + d);
		g.drawLine(hx, hy + d, hx - d, hy);
		g.drawLine(hx - d, hy, hx, hy - d);
		int px = cx;
		int py = cy - radius - 16;
		Path2D.Double flap = new Path2D.Double();
		flap.moveTo(px - 11, py - 4);
		flap.lineTo(px + 11, py - 4);
		flap.lineTo(px + 3, py + 18);
		flap.lineTo(px, py + 26);
		flap.lineTo(px - 3, py + 18);
		flap.closePath();
		g.setPaint(new GradientPaint(px - 10, py, new Color(250, 216, 110),
			px + 10, py + 26, new Color(150, 110, 30)));
		g.fill(flap);
		g.setColor(new Color(60, 44, 10));
		g.setStroke(new BasicStroke(1.6f));
		g.draw(flap);
	}
}

package com.gachaman.tools;

import java.awt.*;
import java.awt.image.*;
import java.io.*;
import javax.imageio.*;

/** Renders the wheel chrome procedurally and from sprites, to prove the anchors. */
public final class WheelCmp {
	public static void main(String[] a) throws Exception {
		int radius = Integer.parseInt(a[1]);
		int cw = 560;
		int ch = 620;
		int cx = cw / 2;
		int cy = ch / 2 + 10;

		BufferedImage proc = new BufferedImage(cw, ch, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = proc.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		WheelArt.drawChrome(g, cx, cy, radius);
		g.dispose();
		ImageIO.write(proc, "png", new File(a[0] + "/wheel_proc.png"));

		BufferedImage spr = new BufferedImage(cw, ch, BufferedImage.TYPE_INT_ARGB);
		g = spr.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		double s = radius / (double) WheelArt.R;
		blit(g, "wheel-shadow", cx, cy, s, 220, 220);
		blit(g, "wheel-rim", cx, cy, s, 220, 220);
		blit(g, "wheel-hub", cx, cy, 1.0, 32, 30);
		int pivotY = cy - radius - 16;
		blit(g, "wheel-pointer", cx, pivotY, 1.0, 20, 12);
		g.dispose();
		ImageIO.write(spr, "png", new File(a[0] + "/wheel_spr.png"));
		System.out.println("rendered at radius " + radius);
	}

	private static void blit(Graphics2D g, String n, int cx, int cy, double s, int ax, int ay)
		throws Exception {
		try (InputStream in = WheelCmp.class.getResourceAsStream("/com/gachaman/art/" + n + ".png")) {
			Image im = ImageIO.read(in);
			g.drawImage(im, cx - (int) Math.round(ax * s), cy - (int) Math.round(ay * s),
				(int) Math.round(im.getWidth(null) * s), (int) Math.round(im.getHeight(null) * s), null);
		}
	}

	private WheelCmp() {
	}
}

package com.gachaman.tools;

import java.awt.*;
import java.awt.image.*;
import net.runelite.client.ui.*;
import net.runelite.client.util.*;
import org.junit.*;

/**
 * Pins the album's two baked icons against the drawing they replaced.
 *
 * <p>AlbumTab used to carry a StardustIcon and a CheckboxIcon: two Icon classes
 * whose paintIcon bodies drew a fixed 13x13 picture from hardcoded colours on
 * every repaint. They are PNGs now, authored by {@link IconArt}, because the
 * Plugin Hub counts only src/main/java and a constant drawing is the cheapest
 * thing in the plugin to move out of it. The originals are copied verbatim into
 * this test — the old code is the specification, and keeping it here is free.
 *
 * <p>What the test asserts is the claim the swap rests on: rendering the shape
 * into a transparent layer and compositing that layer SRC_OVER produces the
 * same picture as drawing the shape straight onto the destination. It is not
 * bit-exact — ARGB is stored non-premultiplied, so an intermediate layer rounds
 * once more than a direct draw — hence the ±TOLERANCE band. When this was
 * written the worst case was 1, on eight pixels of a dark background.
 *
 * <p>Both sides render live, on whatever JDK runs the test, so the assertion is
 * about the two compositing routes rather than about one committed raster: a
 * different rasterizer moves both sides together. The committed PNGs get their
 * own, deliberately coarse check — that they exist, load, and are 13x13 — since
 * a missing or mis-sized resource is the failure a player would actually see.
 */
public class AlbumIconBakeTest
{
	private static final int SIZE = 13;
	private static final int PAD = 6;
	private static final int CANVAS = SIZE + 2 * PAD;
	/** Slack for the one extra rounding step a composited layer costs. */
	private static final int TOLERANCE = 2;

	private static final Color SPARKLE = new Color(190, 170, 255);
	private static final BasicStroke CHECK_STROKE =
		new BasicStroke(2f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND);

	// --- the AlbumTab paintIcon bodies, verbatim as they stood before the bake ---

	private static void paintStardust(Graphics g, int x, int y)
	{
		Graphics2D g2 = (Graphics2D) g.create();
		try
		{
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			int cx = x + SIZE / 2;
			int cy = y + SIZE / 2;
			g2.setColor(SPARKLE);
			g2.setStroke(new BasicStroke(1.4f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			g2.drawLine(cx, y + 2, cx, y + SIZE - 2);
			g2.drawLine(x + 2, cy, x + SIZE - 2, cy);
			g2.setStroke(new BasicStroke(1f));
			g2.drawLine(cx - 2, cy - 2, cx + 2, cy + 2);
			g2.drawLine(cx - 2, cy + 2, cx + 2, cy - 2);
			g2.setColor(Color.WHITE);
			g2.fillOval(cx - 1, cy - 1, 2, 2);
		}
		finally
		{
			g2.dispose();
		}
	}

	private static void paintCheckbox(boolean selected, Graphics g, int x, int y)
	{
		Graphics2D g2 = (Graphics2D) g.create();
		try
		{
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g2.setColor(ColorScheme.DARKER_GRAY_COLOR);
			g2.fillRoundRect(x, y, SIZE, SIZE, 4, 4);
			g2.setColor(ColorScheme.LIGHT_GRAY_COLOR);
			g2.drawRoundRect(x, y, SIZE - 1, SIZE - 1, 4, 4);
			if (selected)
			{
				g2.setColor(Color.WHITE);
				g2.setStroke(CHECK_STROKE);
				g2.drawLine(x + 3, y + 7, x + 5, y + 9);
				g2.drawLine(x + 5, y + 9, x + 10, y + 3);
			}
		}
		finally
		{
			g2.dispose();
		}
	}

	/**
	 * A canvas bigger than the icon on every side, so a stroke that bled outside
	 * the 13x13 box the baked PNG can hold would show up as a difference rather
	 * than being silently cropped by the comparison itself.
	 */
	private static BufferedImage canvas(Color background)
	{
		BufferedImage img = new BufferedImage(CANVAS, CANVAS, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		if (background != null)
		{
			g.setColor(background);
			g.fillRect(0, 0, CANVAS, CANVAS);
		}
		g.dispose();
		return img;
	}

	private static BufferedImage baked(BufferedImage icon, Color background)
	{
		BufferedImage img = canvas(background);
		Graphics2D g = img.createGraphics();
		g.drawImage(icon, PAD, PAD, null);
		g.dispose();
		return img;
	}

	private static void assertWithinTolerance(String what, BufferedImage a, BufferedImage b)
	{
		for (int y = 0; y < CANVAS; y++)
		{
			for (int x = 0; x < CANVAS; x++)
			{
				int pa = a.getRGB(x, y);
				int pb = b.getRGB(x, y);
				for (int shift = 0; shift < 32; shift += 8)
				{
					int delta = Math.abs(((pa >> shift) & 255) - ((pb >> shift) & 255));
					Assert.assertTrue(what + ": pixel (" + (x - PAD) + "," + (y - PAD)
							+ ") drifted from " + Integer.toHexString(pa) + " to "
							+ Integer.toHexString(pb),
						delta <= TOLERANCE);
				}
			}
		}
	}

	/**
	 * The three surfaces an icon can land on: the plugin panel it actually sits
	 * on, a bright one, and no background at all. A transparent destination is
	 * the case where a layered composite is exactly equal, so it also proves the
	 * geometry is identical and the tolerance is only absorbing rounding.
	 */
	private static Color[] backgrounds()
	{
		return new Color[]{ColorScheme.DARK_GRAY_COLOR, Color.WHITE, null};
	}

	@Test
	public void bakedStardustMatchesThePaintedSparkle()
	{
		for (Color background : backgrounds())
		{
			BufferedImage painted = canvas(background);
			Graphics2D g = painted.createGraphics();
			paintStardust(g, PAD, PAD);
			g.dispose();
			assertWithinTolerance("stardust on " + background, painted,
				baked(IconArt.stardustIcon(), background));
		}
	}

	@Test
	public void bakedCheckboxMatchesThePaintedBoxInBothStates()
	{
		for (boolean selected : new boolean[]{false, true})
		{
			for (Color background : backgrounds())
			{
				BufferedImage painted = canvas(background);
				Graphics2D g = painted.createGraphics();
				paintCheckbox(selected, g, PAD, PAD);
				g.dispose();
				assertWithinTolerance("checkbox[" + selected + "] on " + background, painted,
					baked(IconArt.checkboxIcon(selected), background));
			}
		}
	}

	/**
	 * The committed rasters themselves. AlbumTab loads these by name at
	 * construction, so a rename, a missing file or a resource excluded from the
	 * jar is a blank icon in the player's panel — and nothing else in the build
	 * would notice.
	 */
	@Test
	public void committedIconResourcesLoadAtTheExpectedSize()
	{
		for (String name : new String[]{"stardust", "checkbox-off", "checkbox-on"})
		{
			BufferedImage img = ImageUtil.loadImageResource(AlbumIconBakeTest.class,
				"/com/gachaman/ui/" + name + ".png");
			Assert.assertNotNull(name + ".png did not load", img);
			Assert.assertEquals(name + ".png width", SIZE, img.getWidth());
			Assert.assertEquals(name + ".png height", SIZE, img.getHeight());

			boolean anyVisible = false;
			for (int y = 0; y < img.getHeight() && !anyVisible; y++)
			{
				for (int x = 0; x < img.getWidth(); x++)
				{
					if ((img.getRGB(x, y) >>> 24) != 0)
					{
						anyVisible = true;
						break;
					}
				}
			}
			Assert.assertTrue(name + ".png is fully transparent", anyVisible);
		}
	}
}

