package com.gachaman.model;

import java.util.*;
import org.junit.*;

/** The totals header: a pure fold over the contract log. */
public class DossierSummaryTest
{
	private static ContractRecord record(long gc, int kills, long durationMs, int taintedKills,
		String party)
	{
		return new ContractRecord(1L, "Goblin", "EASY", kills, gc, durationMs, "MELEE",
			taintedKills, party, false, false);
	}

	@Test
	public void anEmptyLogTotalsToZeroWithoutDividingByZero()
	{
		for (List<ContractRecord> log : Arrays.asList(null, new ArrayList<ContractRecord>()))
		{
			DossierSummary summary = DossierSummary.of(log);
			Assert.assertEquals(0, summary.getContracts());
			Assert.assertEquals(0, summary.getTotalGc());
			Assert.assertEquals(0, summary.getBestGc());
			Assert.assertEquals(0, summary.averageGc());
			Assert.assertEquals(0, summary.averageDurationMs());
			Assert.assertEquals(0, summary.cleanPercent());
			Assert.assertEquals(0d, summary.cleanFraction(), 0.0001);
		}
	}

	@Test
	public void foldsEveryColumnInOnePass()
	{
		DossierSummary summary = DossierSummary.of(Arrays.asList(
			record(400, 15, 60_000, 0, null),
			record(1600, 30, 120_000, 2, "Party of 2"),
			record(1000, 25, 30_000, 0, "Party of 3")));
		Assert.assertEquals(3, summary.getContracts());
		Assert.assertEquals(2, summary.getCleanContracts());
		Assert.assertEquals(2, summary.getPartyContracts());
		Assert.assertEquals(70, summary.getTotalKills());
		Assert.assertEquals(3000, summary.getTotalGc());
		Assert.assertEquals(210_000, summary.getTotalDurationMs());
		Assert.assertEquals(1600, summary.getBestGc());
		Assert.assertEquals(1000, summary.averageGc());
		Assert.assertEquals(70_000, summary.averageDurationMs());
	}

	@Test
	public void aNullElementIsSkippedRatherThanThrowing()
	{
		// Gson writes null ARRAY elements regardless of serializeNulls, so a hole
		// genuinely survives the codec — the same skip partyStyles needs
		DossierSummary summary = DossierSummary.of(
			Arrays.asList(record(400, 15, 60_000, 0, null), null, record(600, 5, 0, 0, null)));
		Assert.assertEquals("the hole must not be counted as a contract", 2, summary.getContracts());
		Assert.assertEquals(1000, summary.getTotalGc());
	}

	@Test
	public void cleanPercentFloorsSoOneBlemishNeverReadsAsPerfect()
	{
		List<ContractRecord> log = new ArrayList<>();
		for (int i = 0; i < 199; i++)
		{
			log.add(record(1, 1, 0, 0, null));
		}
		log.add(record(1, 1, 0, 1, null));
		DossierSummary summary = DossierSummary.of(log);
		Assert.assertEquals(199, summary.getCleanContracts());
		Assert.assertEquals("199/200 rounds to 100 — it must floor to 99", 99, summary.cleanPercent());
	}

	@Test
	public void aFlawlessLogReadsAsOneHundred()
	{
		DossierSummary summary = DossierSummary.of(
			Arrays.asList(record(1, 1, 0, 0, null), record(1, 1, 0, 0, null)));
		Assert.assertEquals(100, summary.cleanPercent());
		Assert.assertEquals(1d, summary.cleanFraction(), 0.0001);
	}

	@Test
	public void aNegativeDurationCannotDragTheTotalBackwards()
	{
		// a save moved across a clock change can produce a negative elapsed time;
		// the header must not report less total time than a single contract took
		DossierSummary summary = DossierSummary.of(
			Arrays.asList(record(1, 1, 60_000, 0, null), record(1, 1, -5_000, 0, null)));
		Assert.assertEquals(60_000, summary.getTotalDurationMs());
	}

	@Test
	public void aSingleContractIsItsOwnBestAndAverage()
	{
		DossierSummary summary = DossierSummary.of(
			Collections.singletonList(record(1234, 15, 45_000, 0, null)));
		Assert.assertEquals(1234, summary.getBestGc());
		Assert.assertEquals(1234, summary.averageGc());
		Assert.assertEquals(45_000, summary.averageDurationMs());
	}
}

package com.gachaman.model;

import com.gachaman.*;
import java.util.*;
import org.junit.*;

/**
 * The Dossier's capped-append rule and its clean verdict. Pure — no client, no
 * state service, no Swing.
 */
public class ContractRecordTest
{
	private static ContractRecord record(long at, int taintedKills)
	{
		return new ContractRecord(at, "Goblin", "EASY", 15, 400, 60_000, "MELEE",
			taintedKills, null, false, false);
	}

	// --- A. the cap ---

	@Test
	public void appendingToNullStartsTheLog()
	{
		// a save written before the Dossier existed reaches this with a null list
		// (normalized() only runs at LOAD, and a mutate lambda can see a state
		// object that never went through it)
		List<ContractRecord> log = ContractRecord.appendCapped(null, record(1L, 0), 200);
		Assert.assertEquals(1, log.size());
		Assert.assertEquals(1L, log.get(0).getAt());
	}

	@Test
	public void appendsInCompletionOrder()
	{
		List<ContractRecord> log = null;
		for (int i = 1; i <= 3; i++)
		{
			log = ContractRecord.appendCapped(log, record(i, 0), 200);
		}
		Assert.assertEquals(Arrays.asList(1L, 2L, 3L),
			Arrays.asList(log.get(0).getAt(), log.get(1).getAt(), log.get(2).getAt()));
	}

	@Test
	public void oldestDropsPastTheCap()
	{
		List<ContractRecord> log = null;
		for (int i = 1; i <= Tuning.DOSSIER_MAX_RECORDS + 25; i++)
		{
			log = ContractRecord.appendCapped(log, record(i, 0), Tuning.DOSSIER_MAX_RECORDS);
		}
		Assert.assertEquals(Tuning.DOSSIER_MAX_RECORDS, log.size());
		Assert.assertEquals("the 25 oldest are gone, not the 25 newest",
			26L, log.get(0).getAt());
		Assert.assertEquals(Tuning.DOSSIER_MAX_RECORDS + 25L, log.get(log.size() - 1).getAt());
	}

	@Test
	public void anOversizeLogConvergesRatherThanSittingOverTheCap()
	{
		// a save written while the cap was higher: trimming exactly one per append
		// would leave it permanently over, so the trim loops
		List<ContractRecord> oversize = new ArrayList<>();
		for (int i = 1; i <= 500; i++)
		{
			oversize.add(record(i, 0));
		}
		List<ContractRecord> log = ContractRecord.appendCapped(oversize, record(501, 0), 200);
		Assert.assertEquals(200, log.size());
		Assert.assertEquals(501L, log.get(log.size() - 1).getAt());
	}

	@Test
	public void theInputListIsNeverMutated()
	{
		// GachaState is immutable and the decoded list may be shared or read-only
		List<ContractRecord> original = Collections.singletonList(record(1L, 0));
		List<ContractRecord> log = ContractRecord.appendCapped(original, record(2L, 0), 200);
		Assert.assertEquals(1, original.size());
		Assert.assertEquals(2, log.size());
	}

	@Test
	public void aCapOfOneKeepsOnlyTheNewest()
	{
		List<ContractRecord> log = ContractRecord.appendCapped(
			Arrays.asList(record(1L, 0), record(2L, 0)), record(3L, 0), 1);
		Assert.assertEquals(1, log.size());
		Assert.assertEquals(3L, log.get(0).getAt());
	}

	@Test
	public void aNonsenseCapYieldsAnEmptyLogRatherThanAnUnboundedOne()
	{
		// nothing in the plugin passes 0, but an unbounded log is the one outcome
		// that must be impossible — it grows the gzip+SHA256 done on every mutate
		Assert.assertTrue(ContractRecord.appendCapped(null, record(1L, 0), 0).isEmpty());
		Assert.assertTrue(ContractRecord.appendCapped(null, record(1L, 0), -5).isEmpty());
	}

	// --- B. the verdict ---

	@Test
	public void zeroViolationsReadsClean()
	{
		Assert.assertTrue(record(1L, 0).isClean());
	}

	@Test
	public void anyViolationReadsDirty()
	{
		Assert.assertFalse(record(1L, 1).isClean());
		Assert.assertFalse(record(1L, 9).isClean());
	}

	@Test
	public void aNegativeCountStillReadsClean()
	{
		// nothing writes a negative, but "clean" must be the tolerant side: a
		// corrupt count must not brand a contract the plugin never convicted
		Assert.assertTrue(record(1L, -1).isClean());
	}

	@Test
	public void soloAndPartyAreDistinguishedByTheLabel()
	{
		Assert.assertFalse(record(1L, 0).isParty());
		Assert.assertTrue(new ContractRecord(1L, "Goblin", "EASY", 15, 400, 60_000, "MELEE",
			0, "Party of 3", false, false).isParty());
	}
}

package com.gachaman.ui.loadout;

import com.gachaman.model.*;
import com.gachaman.tools.*;
import com.google.gson.*;
import java.io.*;
import java.lang.reflect.*;
import java.nio.charset.*;
import java.nio.file.*;
import java.util.*;
import org.junit.*;

/**
 * The shipped loadout-board.json must still be exactly what {@link LoadoutBoard}
 * declares, and it must still name every {@link GearSlot}.
 *
 * <p>This is the seam that makes moving the board's layout and its silhouette
 * sprite ids into a resource safe. In code the sprites are
 * {@code SpriteID.EQUIPMENT_SLOT_*} constants and the compiler catches a rename;
 * as raw numbers in JSON nothing would — and a wrong sprite id does not fail
 * loudly, it draws the wrong silhouette in an empty socket, or none at all, with
 * no error anywhere. A missing SLOT is worse still: that socket vanishes from
 * the board entirely, so the player cannot assign, unassign or claim a deed in
 * it, and nothing says why.
 *
 * <p>If the first test fails, run {@code ./gradlew loadoutBoard} and commit the
 * result.
 */
public class LoadoutBoardResourceTest
{
	private static class Socket
	{
		int col;
		int row;
		int y;
		int sprite;
	}

	private static class ShippedFile
	{
		String note;
		Map<String, Socket> sockets;
	}

	private static ShippedFile shipped() throws IOException
	{
		try (InputStream in = LoadoutBoardResourceTest.class.getResourceAsStream(
			"/com/gachaman/data/loadout-board.json"))
		{
			Assert.assertNotNull("loadout-board.json is not on the classpath", in);
			return new Gson().fromJson(
				new InputStreamReader(in, StandardCharsets.UTF_8), ShippedFile.class);
		}
	}

	@Test
	public void theShippedFileMatchesTheDeclaration() throws IOException
	{
		ShippedFile file = shipped();
		Assert.assertNotNull("the resource carries no sockets object", file.sockets);

		Map<String, Object> declared = LoadoutBoard.sockets();
		Assert.assertEquals("socket count drifted from com.gachaman.tools.LoadoutBoard",
			declared.size(), file.sockets.size());

		for (Map.Entry<String, Object> entry : declared.entrySet())
		{
			String slot = entry.getKey();
			@SuppressWarnings("unchecked")
			Map<String, Object> want = (Map<String, Object>) entry.getValue();
			Socket got = file.sockets.get(slot);
			Assert.assertNotNull(slot + " is missing from the shipped resource", got);
			Assert.assertEquals(slot + " column drifted",
				((Number) want.get("col")).intValue(), got.col);
			Assert.assertEquals(slot + " row drifted",
				((Number) want.get("row")).intValue(), got.row);
			Assert.assertEquals(slot + " y drifted",
				((Number) want.get("y")).intValue(), got.y);
			Assert.assertEquals(slot + " silhouette sprite drifted — run ./gradlew loadoutBoard",
				((Number) want.get("sprite")).intValue(), got.sprite);
		}
	}

	/**
	 * The two units the same position is written in must agree.
	 *
	 * <p>{@code row} drives the sidebar's GridBagLayout and {@code y} drives the
	 * in-game overlay's pixels, and they describe ONE board. Writing both out (a
	 * resource is free; the Hub counts only src/main/java) keeps the layout in one
	 * place instead of splitting it between a table and a formula — but only while
	 * something checks they still line up, which is this.
	 */
	@Test
	public void theRowAndPixelViewsOfEachSocketAgree() throws IOException
	{
		for (Map.Entry<String, Socket> entry : shipped().sockets.entrySet())
		{
			Socket socket = entry.getValue();
			Assert.assertEquals(entry.getKey() + ": row " + socket.row + " and y " + socket.y
					+ " place the socket in two different rows",
				LoadoutBoard.TOP + LoadoutBoard.PITCH * socket.row, socket.y);
		}
	}

	/**
	 * The exact pixel rows the overlay drew before the layout moved into a
	 * resource, spelled out rather than derived. The formula above and this list
	 * are checked against each other on purpose: a formula alone would happily
	 * validate a board that had been slid ten pixels down as a whole.
	 */
	@Test
	public void theBoardStillSitsWhereItAlwaysDid() throws IOException
	{
		Map<String, Socket> sockets = shipped().sockets;
		Assert.assertEquals(28, sockets.get("HEAD").y);
		Assert.assertEquals(72, sockets.get("CAPE").y);
		Assert.assertEquals(116, sockets.get("WEAPON").y);
		Assert.assertEquals(160, sockets.get("LEGS").y);
		Assert.assertEquals(204, sockets.get("RING").y);
		// and the three columns, at the corners of the arrangement
		Assert.assertEquals(1, sockets.get("HEAD").col);
		Assert.assertEquals(0, sockets.get("CAPE").col);
		Assert.assertEquals(2, sockets.get("AMMO").col);
	}

	/**
	 * Every GearSlot has a socket. The overlay skips a slot the resource does not
	 * name, so a slot added to the enum without a matching entry here would
	 * silently disappear from the board rather than fail.
	 */
	@Test
	public void everyGearSlotHasASocket() throws IOException
	{
		ShippedFile file = shipped();
		List<String> missing = new ArrayList<>();
		for (GearSlot slot : GearSlot.values())
		{
			if (file.sockets == null || !file.sockets.containsKey(slot.name()))
			{
				missing.add(slot.name());
			}
		}
		Assert.assertEquals("a GearSlot with no socket vanishes from the loadout board",
			Collections.emptyList(), missing);
	}

	/**
	 * The columns are an index into the overlay's three-column layout, and the y
	 * offsets have to land inside the board. Both are pinned because the overlay
	 * reads them straight into a Rectangle: an out-of-range column is skipped
	 * (invisible socket) and an out-of-range y draws off the panel.
	 */
	@Test
	public void everySocketLandsOnTheBoard() throws IOException
	{
		ShippedFile file = shipped();
		for (Map.Entry<String, Socket> entry : file.sockets.entrySet())
		{
			Socket socket = entry.getValue();
			Assert.assertTrue(entry.getKey() + " column " + socket.col + " is not 0, 1 or 2",
				socket.col >= 0 && socket.col <= 2);
			Assert.assertTrue(entry.getKey() + " y " + socket.y + " falls off the board",
				socket.y >= 0 && socket.y + 36 <= LoadoutOverlay.BOARD_H);
		}
	}

	/** A resource nobody can leave a comment in should at least carry a note. */
	@Test
	public void theFileExplainsItself() throws IOException
	{
		Assert.assertNotNull("loadout-board.json lost its note", shipped().note);
	}

	/**
	 * The shared binding must still carry every field the resource does. Gson
	 * binds by field NAME and silently leaves an unmatched one at its default, so
	 * a rename in BoardLayout.Socket would zero every column, row, y or sprite on
	 * both views of the board with nothing failing anywhere — reflection is
	 * forbidden in src/main/java, not here, and this is exactly the silent drift
	 * it is good at catching.
	 */
	@Test
	public void theSharedBindingStillMatchesTheResource() throws Exception
	{
		Set<String> fields = new TreeSet<>();
		for (Field field : com.gachaman.data.BoardLayout.Socket.class.getDeclaredFields())
		{
			fields.add(field.getName());
		}
		Assert.assertEquals("BoardLayout.Socket no longer matches loadout-board.json",
			new TreeSet<>(Arrays.asList("col", "row", "sprite", "y")), fields);
	}

	/**
	 * Both views of the board read the one table. A reader that quietly went back
	 * to a private hand-written copy would pass every test above while drifting
	 * from the other view, which is the failure this consolidation removed.
	 */
	@Test
	public void bothViewsReadTheSharedTable() throws IOException
	{
		Path root = com.gachaman.SourceHygieneTest.sourceRoot();
		Assert.assertNotNull(root);
		for (String file : Arrays.asList("com/gachaman/ui/loadout/LoadoutOverlay.java",
			"com/gachaman/ui/panel/LoadoutTab.java"))
		{
			String source = new String(Files.readAllBytes(root.resolve(file)),
				StandardCharsets.UTF_8);
			Assert.assertTrue(file + " must lay its sockets out from BoardLayout.load(gson)",
				source.contains("BoardLayout.load(gson)"));
		}
	}
}

package com.gachaman.ui.panel;

import com.gachaman.*;
import com.gachaman.service.*;
import java.awt.*;
import javax.swing.*;
import org.junit.*;

/**
 * Facts the Overview panel used to state in code and now relies on silently.
 *
 * <p>Compressing that panel replaced two explicit structures with implicit
 * ones. A materialised {@code int[]} of Ante percentages became a bare
 * arithmetic progression, and a hand-built header row became a call to the
 * shared {@link GachamanPanel#row} helper. Both are exactly equivalent today.
 * Both would stop being equivalent if something OUTSIDE this file moved — a
 * Tuning constant in the first case, a helper in another class in the second —
 * and in neither case would the compiler notice.
 *
 * <p>So the equivalences are asserted rather than assumed. Nothing here tests
 * the compression itself; each test pins the external fact that makes the
 * compressed form correct.
 */
public class OverviewTabCompressionTest
{
	/**
	 * The Ante combo box lists ten-point stakes and the Arm listener turns the
	 * selected INDEX back into a percentage with {@code ANTE_MIN_PERCENT + 10 *
	 * index}. That inverse is only right while the band starts on the minimum,
	 * ends on the maximum, and divides evenly by ten — which the deleted
	 * {@code antePercentChoices()} array used to guarantee by construction.
	 *
	 * <p>A Tuning edit to an odd band (say 10..55) would leave the top stake
	 * unofferable, and a click would still arm a legal-looking wager, so this
	 * fails loudly instead.
	 */
	@Test
	public void everyAnteStopIsRecoverableFromItsComboIndexAlone()
	{
		Assert.assertTrue("the Ante band has to run upwards",
			Tuning.ANTE_MIN_PERCENT <= Tuning.ANTE_MAX_PERCENT);
		Assert.assertEquals("the band must divide evenly into ten-point stops, or the"
				+ " maximum stake is never offered",
			0, (Tuning.ANTE_MAX_PERCENT - Tuning.ANTE_MIN_PERCENT) % 10);

		// the same loop addAnteControls uses to fill the combo box
		int index = 0;
		int last = -1;
		for (int percent = Tuning.ANTE_MIN_PERCENT; percent <= Tuning.ANTE_MAX_PERCENT;
			percent += 10)
		{
			Assert.assertEquals("combo index " + index + " must map back to its own stop",
				percent, Tuning.ANTE_MIN_PERCENT + 10 * index);
			last = percent;
			index++;
		}
		Assert.assertEquals("the first item is the floor of the band",
			Tuning.ANTE_MIN_PERCENT, Tuning.ANTE_MIN_PERCENT + 10 * 0);
		Assert.assertEquals("the last item is the ceiling of the band",
			Tuning.ANTE_MAX_PERCENT, last);
		Assert.assertEquals("the item count is what the old int[] length was",
			(Tuning.ANTE_MAX_PERCENT - Tuning.ANTE_MIN_PERCENT) / 10 + 1, index);
		Assert.assertEquals("nothing selected (-1) has to clamp to the floor, not"
				+ " underflow below it",
			Tuning.ANTE_MIN_PERCENT, Tuning.ANTE_MIN_PERCENT + 10 * Math.max(0, -1));
	}

	/**
	 * The Contract header hands its name label and Wiki button to
	 * {@link GachamanPanel#row}. That is only safe while row() keeps building the
	 * panel the header used to build by hand: BorderLayout with a 6px horizontal
	 * gap (the header's width arithmetic subtracts exactly that), transparent so
	 * the section's own background shows through, left-aligned for the enclosing
	 * BoxLayout, and left-in-CENTER / right-in-EAST.
	 */
	@Test
	public void theSharedRowHelperStillBuildsWhatTheContractHeaderNeeds()
	{
		JLabel left = new JLabel("monster");
		JButton right = new JButton("Wiki");
		JPanel row = GachamanPanel.row(left, right);

		Assert.assertFalse("an opaque row would paint over the section background",
			row.isOpaque());
		Assert.assertEquals("BoxLayout centres anything that is not left-aligned",
			Component.LEFT_ALIGNMENT, row.getAlignmentX(), 0f);
		Assert.assertTrue("BorderLayout is what puts the button hard against the"
			+ " right edge", row.getLayout() instanceof BorderLayout);

		BorderLayout layout = (BorderLayout) row.getLayout();
		Assert.assertEquals("the header sizes its name cell as the column width less"
			+ " the button and THIS gap", 6, layout.getHgap());
		Assert.assertSame("the name takes the elastic cell",
			left, layout.getLayoutComponent(BorderLayout.CENTER));
		Assert.assertSame("the Wiki button keeps its natural width on the right",
			right, layout.getLayoutComponent(BorderLayout.EAST));
	}

	/**
	 * row() pins a maximum height of its own, which the Contract header overwrites
	 * on the very next line so the row ends up only as tall as its tallest child.
	 * This asserts the overwrite actually takes — if a future row() ever pinned
	 * the height some other way (a layout manager minimum, an overridden
	 * getMaximumSize) the later setMaximumSize would quietly stop winning and the
	 * header would gain empty space under it.
	 *
	 * <p>Deliberately says nothing about WHICH value row() pins. Asserting that
	 * would couple this test to a constant in another class that the header does
	 * not depend on and in fact discards, so an edit there would fail here as
	 * though OverviewTab had regressed.
	 */
	@Test
	public void anExplicitMaximumSizeStillOverridesTheOneRowPins()
	{
		JPanel row = GachamanPanel.row(new JLabel("monster"), new JButton("Wiki"));
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 17));
		Assert.assertEquals("the header's ceiling has to be the one that sticks",
			17, row.getMaximumSize().height);
		Assert.assertEquals(Integer.MAX_VALUE, row.getMaximumSize().width);
	}

	/**
	 * The Quest-unlocked rows deliberately do NOT use row(): they put the NPC
	 * name in WEST so it holds its width and the quest name gives way first.
	 * Now that the Contract header DOES use row(), that difference is one edit
	 * away from being "tidied" into consistency — which would elide the NPC name
	 * the player is trying to match against the monster in front of them.
	 */
	@Test
	public void theQuestUnlockRowKeepsTheNpcNameOnTheInelasticSide()
	{
		QuestExemptionService.Unlock unlock =
			new QuestExemptionService.Unlock("Kurask", "Fremennik Trials");
		JPanel row = OverviewTab.unlockRow(unlock);

		BorderLayout layout = (BorderLayout) row.getLayout();
		JLabel npc = (JLabel) layout.getLayoutComponent(BorderLayout.WEST);
		JLabel quest = (JLabel) layout.getLayoutComponent(BorderLayout.CENTER);
		Assert.assertEquals("Kurask", npc.getText());
		Assert.assertEquals("Fremennik Trials", quest.getText());
		Assert.assertEquals("the quest name is the half that may be elided",
			SwingConstants.RIGHT, quest.getHorizontalAlignment());
		Assert.assertNull("nothing belongs in EAST here — that is row()'s shape",
			layout.getLayoutComponent(BorderLayout.EAST));
	}
}

package com.gachaman.ui.panel;

import java.text.*;
import java.util.*;
import org.junit.*;

/**
 * The caption under the Timeline's scrub slider.
 *
 * It updates on every drag tick, so it is read more than any other line on the
 * page, and the count it carries walks down through one on the way to zero —
 * which is exactly where "(1 events)" used to appear.
 *
 * The date half is deliberately compared against a locally built formatter
 * rather than a hardcoded string: the pattern pins the locale but not the
 * timezone, so a literal expectation would pass only on this machine.
 */
public class TimelineTabScrubCaptionTest
{
	/** Same pattern and locale TimelineTab uses; default zone, as it does. */
	private static final SimpleDateFormat RANGE =
		new SimpleDateFormat("d MMM yy HH:mm", Locale.ENGLISH);

	private static final long WHEN = 1_700_000_000_000L;

	private static String stamp(long millis)
	{
		return RANGE.format(new Date(millis));
	}

	@Test
	public void oneEventIsSingular()
	{
		Assert.assertEquals("Up to " + stamp(WHEN) + "  (1 event)",
			TimelineTab.scrubCaption(WHEN, 1));
	}

	@Test
	public void everyOtherCountIsPlural()
	{
		// zero included: an empty window is "0 events", never "0 event"
		Assert.assertEquals("Up to " + stamp(WHEN) + "  (0 events)",
			TimelineTab.scrubCaption(WHEN, 0));
		Assert.assertEquals("Up to " + stamp(WHEN) + "  (2 events)",
			TimelineTab.scrubCaption(WHEN, 2));
		Assert.assertEquals("Up to " + stamp(WHEN) + "  (500 events)",
			TimelineTab.scrubCaption(WHEN, 500));
	}

	@Test
	public void theCaptionTracksTheScrubPosition()
	{
		// the slider is the only thing that moves this value, so two positions
		// an hour apart must not render the same caption
		String early = TimelineTab.scrubCaption(WHEN, 3);
		String later = TimelineTab.scrubCaption(WHEN + 3_600_000L, 3);
		Assert.assertNotEquals(early, later);
		Assert.assertTrue(early.startsWith("Up to "));
		Assert.assertTrue(later.startsWith("Up to "));
	}

	@Test
	public void theCaptionFitsTheColumn()
	{
		// a non-scrolling tab: 230px at ~4.6px/char for the small font is about
		// 50 characters, and this label does not wrap
		for (int shown : new int[]{0, 1, 9, 10, 99, 100, 999, 9999})
		{
			String text = TimelineTab.scrubCaption(WHEN, shown);
			Assert.assertTrue("too long at " + shown + ": " + text, text.length() <= 44);
		}
	}
}

package com.gachaman.ui.panel;

import com.gachaman.*;
import org.junit.*;

/**
 * The Rusty tile's lifetime counter, and the sentinel it must never collide with.
 *
 * <p>ChestTile packs three meanings into one int: -1 means "this tier has no
 * lifetime cap", 0 means "retired", and a positive value prints as "N left". The
 * shop derives that number for Rusty by subtracting the persisted open count from
 * {@link Tuning#RUSTY_LIFETIME_CAP}, and the subtraction alone is not safe — a save
 * carrying more opens than the cap (an older build, a migration, a hand edit) lands
 * on exactly -1 and the retired chest comes back to life: ungreyed, unlabelled, and
 * clickable straight into a refusal that blames a busy reveal or a GC shortage.
 *
 * <p>So the invariant pinned here is not the arithmetic, it is the floor: this
 * method may never return a negative number, whatever the save says.
 */
public class ShopRustyCapTest
{
	@Test
	public void aFreshAccountHasTheWholeCapLeft()
	{
		Assert.assertEquals(Tuning.RUSTY_LIFETIME_CAP, ShopTab.rustyRemaining(0));
	}

	@Test
	public void eachOpenTakesOneOff()
	{
		Assert.assertEquals(Tuning.RUSTY_LIFETIME_CAP - 1, ShopTab.rustyRemaining(1));
		Assert.assertEquals(Tuning.RUSTY_LIFETIME_CAP - 2, ShopTab.rustyRemaining(2));
	}

	@Test
	public void spendingTheCapExactlyRetiresTheTile()
	{
		// 0 is "retired", which is what greys the tile and prints "Rusted away"
		Assert.assertEquals(0, ShopTab.rustyRemaining(Tuning.RUSTY_LIFETIME_CAP));
	}

	@Test
	public void aCountPastTheCapStaysRetiredInsteadOfReadingAsUncapped()
	{
		// the bug: CAP - (CAP + 1) is -1, which ChestTile reads as "no cap at all"
		Assert.assertEquals(0, ShopTab.rustyRemaining(Tuning.RUSTY_LIFETIME_CAP + 1));
		Assert.assertEquals(0, ShopTab.rustyRemaining(Tuning.RUSTY_LIFETIME_CAP + 2));
		Assert.assertEquals(0, ShopTab.rustyRemaining(99));
	}

	@Test
	public void theUncappedSentinelIsNeverReachableFromACount()
	{
		// -1 is reserved for the tiers that genuinely have no cap; the Rusty count
		// must never produce it, or the retired tile renders as an ordinary chest
		for (int opened = 0; opened < 500; opened++)
		{
			int remaining = ShopTab.rustyRemaining(opened);
			Assert.assertTrue("opened " + opened + " gave " + remaining, remaining >= 0);
			Assert.assertNotEquals("opened " + opened + " hit the uncapped sentinel",
				-1, remaining);
		}
	}
}

