package com.gachaman.ui.panel;

import com.gachaman.service.*;
import java.util.*;
import org.junit.*;

/**
 * The tooltip on a tier row in the Chest Odds bands.
 *
 * A tier ladder legitimately lands in BOTH bands at once — the Defence gate is
 * applied to the body only, and metal-prefixed ranged gear is measured against
 * Ranged rather than the melee rank table — so "Hardleather" appears under
 * Wieldable now AND under Headroom. That reads as double-counting until the
 * tooltip names the pieces that are actually the ones out of reach, which is
 * what these tests pin.
 */
public class ShopBandTooltipTest
{
	private static ChestService.TierOdds row(String name, boolean wieldable, double probability,
		String... cards)
	{
		return new ChestService.TierOdds(name.toLowerCase(java.util.Locale.ROOT), name, wieldable,
			probability, Arrays.asList(cards));
	}

	@Test
	public void aWieldableRowJustStatesItsOdds()
	{
		// the cards behind a reachable row are not news — the player can wear them
		String tip = ShopTab.rowTooltip(row("Bronze", true, 0.039, "Bronze med helm"), false);
		Assert.assertEquals("<html>Bronze - 3.9% per card</html>", tip);
	}

	@Test
	public void aWieldableRowStaysQuietEvenWhenTheLadderIsSplit()
	{
		String tip = ShopTab.rowTooltip(row("Hardleather", true, 0.001, "Hard leather chaps"), true);
		Assert.assertFalse(tip.contains("Hard leather chaps"));
		Assert.assertFalse(tip.contains("out of reach"));
	}

	@Test
	public void aHeadroomRowNamesTheCardsBehindIt()
	{
		String tip = ShopTab.rowTooltip(
			row("Black", false, 0.01, "Black platebody", "Black kiteshield"), false);
		Assert.assertTrue(tip, tip.contains("Out of reach:"));
		Assert.assertTrue(tip, tip.contains("Black platebody"));
		Assert.assertTrue(tip, tip.contains("Black kiteshield"));
	}

	@Test
	public void aSplitLadderExplainsWhyItAppearsTwice()
	{
		String tip = ShopTab.rowTooltip(
			row("Hardleather", false, 0.0004, "Hard leather body"), true);
		Assert.assertTrue(tip, tip.contains("Some Hardleather gear is already within reach."));
		Assert.assertTrue(tip, tip.contains("Still out of reach:"));
		Assert.assertTrue(tip, tip.contains("Hard leather body"));
		// the unsplit wording must not also appear, or the sentence reads twice
		Assert.assertFalse(tip, tip.contains(">Out of reach:"));
	}

	@Test
	public void theFlooredPercentageCannotCloseTheTooltip()
	{
		// pct() answers "<0.1%" here, and Swing's HTML 3.2 parser would read a raw
		// "<0" as the start of a tag and swallow every card name after it
		String tip = ShopTab.rowTooltip(row("Hardleather", false, 0.0000001, "Hard leather body"),
			true);
		Assert.assertTrue(tip, tip.contains("&lt;0.1% per card"));
		Assert.assertTrue(tip, tip.contains("Hard leather body"));
		// only the wrapper and the line breaks are real markup
		Assert.assertEquals(0, countOutsideMarkup(tip));
	}

	@Test
	public void cardNamesFromTheItemCacheAreEscaped()
	{
		String tip = ShopTab.rowTooltip(row("Black", false, 0.01, "Bow & <arrow>"), false);
		Assert.assertTrue(tip, tip.contains("Bow &amp; &lt;arrow&gt;"));
		Assert.assertFalse(tip, tip.contains("<arrow>"));
	}

	@Test
	public void anOverlongListCountsTheRemainderRatherThanDroppingIt()
	{
		List<String> many = new ArrayList<>();
		for (int i = 0; i < 30; i++)
		{
			many.add("Card " + i);
		}
		String tip = ShopTab.rowTooltip(new ChestService.TierOdds("k", "Big", false, 0.5, many),
			false);
		Assert.assertTrue(tip, tip.contains("Card 0"));
		Assert.assertTrue(tip, tip.contains("Card 23"));
		Assert.assertFalse(tip, tip.contains("Card 24"));
		// the tail is disclosed as a count, never silently trimmed
		Assert.assertTrue(tip, tip.contains("+6 more"));
	}

	@Test
	public void aHeadroomRowWithNoNamesDegradesQuietly()
	{
		String empty = ShopTab.rowTooltip(
			new ChestService.TierOdds("k", "Mithril", false, 0.008, Collections.emptyList()), false);
		Assert.assertEquals("<html>Mithril - 0.8% per card</html>", empty);

		String missing = ShopTab.rowTooltip(
			new ChestService.TierOdds("k", "Mithril", false, 0.008, null), true);
		Assert.assertEquals("<html>Mithril - 0.8% per card</html>", missing);
	}

	/** Counts angle brackets that are not one of the tags this tooltip may emit. */
	private static int countOutsideMarkup(String html)
	{
		String stripped = html
			.replace("<html>", "")
			.replace("</html>", "")
			.replace("<br>", "");
		int count = 0;
		for (int i = 0; i < stripped.length(); i++)
		{
			char c = stripped.charAt(i);
			if (c == '<' || c == '>')
			{
				count++;
			}
		}
		return count;
	}
}

package com.gachaman.ui.panel;

import org.junit.*;

/**
 * The percentage the Chest Odds rows print, and the one place it is handed to a
 * Swing HTML parser.
 *
 * A tier whose chance rounds to 0.0% would read as impossible — the one claim
 * the headroom band must never make — so {@link ShopTab#pct} floors it at
 * "&lt;0.1%" instead. That answer opens with a literal {@code <}, and the folded
 * "+N more tiers" tooltip is built as {@code <html>}: Swing's parser is HTML 3.2
 * and reads {@code <0.1%} as the start of a tag, swallowing every row after it.
 * Escaping is what keeps the two compatible, so both halves are pinned here.
 */
public class ShopOddsTooltipTest
{
	@Test
	public void aVanishinglySmallChanceIsFlooredNotRoundedAway()
	{
		// 0.04% — non-zero, but below the 0.05 that "%.1f" would round up
		Assert.assertEquals("<0.1%", ShopTab.pct(0.0004));
		Assert.assertEquals("<0.1%", ShopTab.pct(0.0000001));
	}

	@Test
	public void anImpossibleRowIsStillPrintedAsZero()
	{
		// exactly zero is a real answer, not a rounding artefact, so it does not
		// get the "<" treatment — a locked tier should read 0.0%
		Assert.assertEquals("0.0%", ShopTab.pct(0));
	}

	@Test
	public void ordinaryChancesKeepOneDecimal()
	{
		Assert.assertEquals("3.3%", ShopTab.pct(0.033));
		Assert.assertEquals("100.0%", ShopTab.pct(1));
		// at and above the floor boundary the normal format takes over again
		Assert.assertEquals("0.1%", ShopTab.pct(0.0005));
	}

	@Test
	public void theFlooredAnswerSurvivesTheHtmlTooltip()
	{
		// what addBand actually appends; unescaped, the parser eats from here on
		Assert.assertEquals("&lt;0.1%", GachamanPanel.escape(ShopTab.pct(0.0004)));
		Assert.assertFalse(GachamanPanel.escape(ShopTab.pct(0.0004)).contains("<"));
	}

	@Test
	public void everyPercentageIsSafeToInterpolate()
	{
		for (double fraction : new double[]{0, 0.0000001, 0.0004, 0.0005, 0.033, 0.5, 1})
		{
			String escaped = GachamanPanel.escape(ShopTab.pct(fraction));
			Assert.assertFalse("raw < from " + fraction, escaped.contains("<"));
			Assert.assertFalse("raw > from " + fraction, escaped.contains(">"));
		}
	}

	@Test
	public void escapingHandlesTheAmpersandFirst()
	{
		// order matters: replacing "<" before "&" would turn a tier name's own
		// ampersand into "&amp;lt;" and print the entity as visible text
		Assert.assertEquals("&amp;lt;", GachamanPanel.escape("&lt;"));
		Assert.assertEquals("Saradomin &amp; Zamorak", GachamanPanel.escape("Saradomin & Zamorak"));
		Assert.assertEquals("", GachamanPanel.escape(null));
	}
}

package com.gachaman.ui.panel;

import com.gachaman.model.*;
import java.util.*;
import org.junit.*;

/**
 * The indefinite article the Shop's confirm dialogs put in front of a noun.
 *
 * These dialogs are the last thing a player reads before spending GC, and the
 * two nouns feeding them are both live tables — {@code GearSlot} and the chest
 * ladder. A slot or a chest tier added later with a vowel on the front would
 * silently start printing "a Amulet chest" with nothing to catch it, so the
 * expectations below are spelled out per entry rather than derived.
 */
public class GachamanPanelArticleTest
{
	@Test
	public void aMissingNounStillGetsAnArticle()
	{
		// getDisplayName() is non-null for every enum constant today, but the
		// caller passes "" for a null slot rather than branching — so the
		// degenerate case has to produce a word, not an NPE or an empty gap
		Assert.assertEquals("a", GachamanPanel.article(null));
		Assert.assertEquals("a", GachamanPanel.article(""));
	}

	@Test
	public void everyGearSlotReadsCorrectly()
	{
		Map<GearSlot, String> expected = new LinkedHashMap<>();
		expected.put(GearSlot.HEAD, "a");
		expected.put(GearSlot.CAPE, "a");
		expected.put(GearSlot.AMULET, "an");
		expected.put(GearSlot.WEAPON, "a");
		expected.put(GearSlot.BODY, "a");
		expected.put(GearSlot.SHIELD, "a");
		expected.put(GearSlot.LEGS, "a");
		expected.put(GearSlot.HANDS, "a");
		expected.put(GearSlot.FEET, "a");
		expected.put(GearSlot.RING, "a");
		expected.put(GearSlot.AMMO, "an");

		// a new slot must be given an answer here, not inherit one by accident
		Assert.assertEquals("every gear slot needs an expected article",
			GearSlot.values().length, expected.size());

		for (Map.Entry<GearSlot, String> entry : expected.entrySet())
		{
			String name = entry.getKey().getDisplayName();
			Assert.assertEquals(name, entry.getValue(), GachamanPanel.article(name));
		}
	}

	@Test
	public void everyChestNameReadsCorrectly()
	{
		// ShopTab.chestName is private; these are its four returns verbatim
		Assert.assertEquals("a", GachamanPanel.article("Rusty Chest"));
		Assert.assertEquals("a", GachamanPanel.article("Battered Chest"));
		Assert.assertEquals("a", GachamanPanel.article("Gilded Chest"));
		Assert.assertEquals("an", GachamanPanel.article("Ornate Chest"));
	}

	@Test
	public void caseDoesNotChangeTheAnswer()
	{
		// the nouns arrive title-cased from a display name today, but the shop
		// also interpolates raw card and charge names, which are not
		Assert.assertEquals("an", GachamanPanel.article("epic"));
		Assert.assertEquals("an", GachamanPanel.article("Epic"));
		Assert.assertEquals("a", GachamanPanel.article("compactor"));
		Assert.assertEquals("a", GachamanPanel.article("Compactor"));
	}
}

package com.gachaman.ui.panel;

import com.gachaman.*;
import com.gachaman.service.*;
import javax.swing.*;
import org.junit.*;

/**
 * The two style-charge buttons are built by one shared helper now, and these
 * are the strings a player reads on them.
 *
 * <p>Collapsing the Compactor and Extender blocks into {@code chargeButton}
 * moved four player-visible pieces — the price label, the FREE-voucher label,
 * the explanation and the voucher sentence bolted onto its end — across a
 * method boundary, and re-split the long tooltip prose at a different point in
 * its concatenation. All of that is supposed to produce byte-identical text.
 * "Supposed to" is exactly the kind of claim worth a test, especially when the
 * only cost is a test file, which the token budget does not count.
 *
 * <p>The literals below are copied from the code as it stood BEFORE the helper
 * existed, not from the helper, or this would assert that the code equals
 * itself.
 */
public class ShopChargeButtonTest
{
	/**
	 * chargeButton touches no collaborator — it formats text, reads the two
	 * numbers it was handed and hangs a listener that only runs on a click — so
	 * an instance with nothing injected is enough to exercise it.
	 */
	private static ShopTab tab()
	{
		return new ShopTab(new GachaStateService(null), null, null, null, null, null,
			null, null, null, null);
	}

	@Test
	public void theCompactorButtonReadsAsItAlwaysHas()
	{
		// no voucher, enough GC: the priced label
		JButton priced = tab().chargeButton(true, "Compactor", Tuning.COMPACTOR_PRICE_GC, 0,
			Tuning.COMPACTOR_PRICE_GC, "This contract counts double toward the style cycle,"
				+ " and each kill counts double toward the contract itself (the skipped count"
				+ " pays no GC).");
		Assert.assertEquals("Compactor — 400 GC", priced.getText());
		Assert.assertEquals("This contract counts double toward the style cycle, and each"
			+ " kill counts double toward the contract itself (the skipped count pays no GC).",
			priced.getToolTipText());
		Assert.assertTrue("affordable at exactly the price", priced.isEnabled());
	}

	@Test
	public void aVoucherChangesTheLabelAndAppendsTheVoucherSentence()
	{
		// one voucher, no GC at all: still enabled, and the voucher sentence lands
		JButton free = tab().chargeButton(false, "Extender", Tuning.EXTENDER_PRICE_GC, 1, 0,
			"This contract counts only half toward the style cycle.");
		Assert.assertEquals("Extender — FREE voucher", free.getText());
		Assert.assertEquals("This contract counts only half toward the style cycle."
			+ " Uses your free voucher — no GC.", free.getToolTipText());
		Assert.assertTrue("a voucher pays for it whatever the balance", free.isEnabled());
	}

	@Test
	public void tooLittleGcAndNoVoucherDisablesIt()
	{
		JButton broke = tab().chargeButton(true, "Compactor", Tuning.COMPACTOR_PRICE_GC, 0,
			Tuning.COMPACTOR_PRICE_GC - 1, "irrelevant");
		Assert.assertFalse(broke.isEnabled());
	}
}

package com.gachaman.ui.panel;

import com.gachaman.*;
import com.gachaman.model.*;
import org.junit.*;

/**
 * The honesty claim the Overview's Preferred Weapon block makes, pinned against
 * the real Tuning tables.
 *
 * <p>The claim is that the x1.5 is worth a very different amount on an EASY
 * contract than on an INSANE one, because it multiplies kill GC and kill GC is
 * a small slice of one and a large slice of the other. That is the whole reason
 * the panel prints a break-even instead of the multiplier alone — so if the
 * tables ever move far enough to make the two ends comparable, the prose has
 * stopped being true and this test is the thing that says so.
 *
 * <p>Both ends are computed from {@link Tuning#PER_KILL_GC},
 * {@link Tuning#COMPLETION_GC} and {@link TaskDifficulty}'s own kill band rather
 * than from copied literals: a test that hard-codes 4 and 400 would go on
 * passing after a rebalance that had already made the panel lie.
 */
public class OverviewWeaponWorthTest
{
	private static double slackPercent(TaskDifficulty difficulty, int kills)
	{
		return OverviewTab.killShareFraction(Tuning.PER_KILL_GC.get(difficulty), kills,
			Tuning.COMPLETION_GC.get(difficulty)) * (Tuning.WEAPON_BONUS_MULT - 1.0) * 100;
	}

	/** The middle of a difficulty's own kill band — the contract a player usually gets. */
	private static int typicalKills(TaskDifficulty difficulty)
	{
		return (difficulty.getMinKills() + difficulty.getMaxKills()) / 2;
	}

	/** The load-bearing comparison, on the contract each difficulty usually deals. */
	@Test
	public void theBonusIsWorthFarLessOnEasyThanOnInsane()
	{
		double easy = slackPercent(TaskDifficulty.EASY, typicalKills(TaskDifficulty.EASY));
		double insane = slackPercent(TaskDifficulty.INSANE, typicalKills(TaskDifficulty.INSANE));
		Assert.assertTrue("an easy contract's break-even should be single digits, was " + easy,
			easy < 10);
		Assert.assertTrue("an insane contract's break-even should be far larger, was " + insane,
			insane > 20);
		Assert.assertTrue("the two ends must stay far enough apart for the panel's prose"
			+ " to be worth printing: easy " + easy + " vs insane " + insane,
			insane > 2 * easy);
	}

	/**
	 * And the claim must not merely hold on average — it must not INVERT at the
	 * extremes, which is the pairing that would make the prose wrong for a real
	 * player: the longest easy contract (most kill GC, so the biggest share it
	 * can have) against the shortest insane one (the least).
	 */
	@Test
	public void theClaimSurvivesTheWorstPairingOfContractLengths()
	{
		double easy = slackPercent(TaskDifficulty.EASY, TaskDifficulty.EASY.getMaxKills());
		double insane = slackPercent(TaskDifficulty.INSANE, TaskDifficulty.INSANE.getMinKills());
		Assert.assertTrue("even the longest easy against the shortest insane must keep the"
			+ " difficulties in the same order: easy " + easy + " vs insane " + insane,
			insane > 1.5 * easy);
	}

	/**
	 * The break-even the panel prints, checked against its own derivation rather
	 * than against itself: running a contract entirely with the named category
	 * pays 1.5K + C where it would have paid K + C, so GC per hour breaks even
	 * exactly when the weapon is (1.5K + C) / (K + C) - 1 slower per kill.
	 */
	@Test
	public void theBreakEvenMatchesTheIncomeItIsDerivedFrom()
	{
		int perKill = 16;
		int kills = 60;
		int completion = 1900;
		double k = (double) perKill * kills;
		double expected = ((Tuning.WEAPON_BONUS_MULT * k + completion) / (k + completion)) - 1;
		double printed = OverviewTab.killShareFraction(perKill, kills, completion)
			* (Tuning.WEAPON_BONUS_MULT - 1.0);
		Assert.assertEquals(expected, printed, 1e-12);
	}

	@Test
	public void aContractWithNoKillIncomeIsAllCompletionAndNoShare()
	{
		// a Redemption contract: perKillGc 0, so the weapon multiplies nothing
		Assert.assertEquals(0, OverviewTab.killShareFraction(0, 40, 900), 0);
		// and no contract at all divides by nothing rather than by zero
		Assert.assertEquals(0, OverviewTab.killShareFraction(0, 0, 0), 0);
	}

	@Test
	public void everyReasonToShowNothingSaysNoBonusAvailable()
	{
		String noContract = OverviewTab.noBonusReason(null);
		String redemption = OverviewTab.noBonusReason(ActiveTask.builder()
			.difficulty(TaskDifficulty.HARD).monsterName("Anything")
			.killsRequired(20).perKillGc(0).completionGc(1900).redemption(true).build());
		Assert.assertNotNull(noContract);
		Assert.assertNotNull(redemption);
		// the owner's wording, and never anything that reads as the player's fault
		Assert.assertTrue(noContract, noContract.contains("no bonus available"));
		Assert.assertTrue(redemption, redemption.contains("no bonus available"));
		Assert.assertNotEquals("the two cases have different fixes and must be told apart",
			noContract, redemption);
	}

	@Test
	public void aPayingContractHasNoReasonToShowNothing()
	{
		Assert.assertNull(OverviewTab.noBonusReason(ActiveTask.builder()
			.difficulty(TaskDifficulty.EASY).monsterName("Anything")
			.killsRequired(20).perKillGc(4).completionGc(400).build()));
	}
}

package com.gachaman.ui.panel;

import com.gachaman.data.*;
import com.gachaman.service.*;
import com.google.gson.*;
import org.junit.*;

/**
 * The Toll's purchase row, in the two places where a wrong word would be a
 * wrong claim rather than a typo.
 *
 * <p>The row itself cannot be driven headlessly — it needs a live album, a
 * loadout map, a card database and a week key — so what is pinned here is every
 * decision the row makes that is NOT a Swing call: which sentence each of the
 * three Toll states gets, and how a tier ladder is named. Both have a failure
 * mode that ships silently: an untiered card printing "null" on the shop page,
 * or the two no-offer states collapsing into one sentence that tells a player
 * to wait a week for something that is actually arriving on its own.
 */
public class ShopTollTest
{
	/**
	 * tierLabel and tollPull read the tier table and nothing else — no state, no
	 * client, no chest service — so an instance with only that injected is
	 * enough. Same arrangement ShopChargeButtonTest already uses.
	 */
	private static ShopTab tab()
	{
		return new ShopTab(new GachaStateService(null), null, null, null, null, null,
			null, null, null, TierTable.load(new Gson()));
	}

	@Test
	public void anUntieredCardNeverPrintsARawNullOrAKey()
	{
		ShopTab tab = tab();
		// the untiered band is a real offer: the owner settled Toll eligibility as
		// "not a hologram and served at least one kill", which admits cards with no
		// tier ladder at all, and TierTable.displayNameOf would throw on the null
		Assert.assertEquals("No tier gate", tab.tierLabel(null));
		String pull = tab.tollPull(null);
		Assert.assertTrue("the untiered pull must say so: " + pull,
			pull.contains("untiered"));
		Assert.assertFalse("a null tier must never reach the player: " + pull,
			pull.toLowerCase(java.util.Locale.ROOT).contains("null"));
	}

	@Test
	public void aTieredCardNamesItsLadderInWords()
	{
		ShopTab tab = tab();
		String label = tab.tierLabel("rune");
		Assert.assertFalse("the raw key must never be shown: " + label, label.contains("_"));
		Assert.assertTrue("the ladder's own name belongs in the pull: " + tab.tollPull("rune"),
			tab.tollPull("rune").contains(label));
		Assert.assertTrue("the pull is one card and says so: " + tab.tollPull("rune"),
			tab.tollPull("rune").contains("one blind"));
	}

	/**
	 * The two no-offer states mean opposite things. "Paid" is a wait for the week
	 * to turn; "nothing eligible" ends the moment any assigned card is present for
	 * a kill, which can be this afternoon. One sentence for both would send half
	 * the players who read it away for six days.
	 */
	@Test
	public void theTwoNoOfferStatesDoNotShareASentence()
	{
		String paid = ShopTab.tollNoOffer(true);
		String nothing = ShopTab.tollNoOffer(false);
		Assert.assertNotEquals(paid, nothing);
		Assert.assertTrue("paid points at next week: " + paid, paid.contains("next week"));
		Assert.assertFalse("nothing-eligible must NOT point at next week: " + nothing,
			nothing.contains("next week"));
		Assert.assertTrue("it must name what actually ends the wait: " + nothing,
			nothing.contains("first kill"));
	}

	@Test
	public void aServiceRecordOfOneIsNotPluralised()
	{
		Assert.assertEquals("1 kill", ShopTab.killsServed(1));
		Assert.assertEquals("0 kills", ShopTab.killsServed(0));
		Assert.assertEquals("342 kills", ShopTab.killsServed(342));
	}
}

package com.gachaman.ui.panel;

import java.awt.image.*;
import java.io.*;
import javax.imageio.*;
import org.junit.*;

/**
 * The header's Ko-fi and GitHub icons ship as PNGs authored by
 * {@code com.gachaman.tools.IconArt}. Shipping them rather than painting them
 * moves the failure mode: the glyph can no longer come out empty because of a
 * geometry edit, but it CAN be missing from the jar, regenerated at the wrong
 * size, or accidentally overwritten with a blank tile — and Swing renders a
 * missing or empty icon perfectly happily while nothing fails.
 *
 * <p>These assertions are the smoke alarm for that: the resource must resolve
 * off the classpath, coverage proves the tile actually carries a mark, and the
 * hover difference proves the two variants are not the same file twice.
 *
 * <p>Deliberately NOT pixel-exact. Pinning the artwork would make every nudge
 * to the tail or the ears a test edit, which trains the habit of updating the
 * expectation instead of looking at the icon.
 */
public class HeaderLinkIconTest
{
	private static BufferedImage icon(String name) throws IOException
	{
		try (InputStream in = HeaderLinkIconTest.class.getResourceAsStream(
			"/com/gachaman/ui/" + name + ".png"))
		{
			Assert.assertNotNull("icon missing from the classpath: " + name, in);
			return ImageIO.read(in);
		}
	}

	/** Fraction of pixels that are not fully transparent. */
	private static double coverage(BufferedImage image)
	{
		int painted = 0;
		for (int y = 0; y < image.getHeight(); y++)
		{
			for (int x = 0; x < image.getWidth(); x++)
			{
				if ((image.getRGB(x, y) >>> 24) > 8)
				{
					painted++;
				}
			}
		}
		return painted / (double) (image.getWidth() * image.getHeight());
	}

	private static int differingPixels(BufferedImage a, BufferedImage b)
	{
		int differing = 0;
		for (int y = 0; y < a.getHeight(); y++)
		{
			for (int x = 0; x < a.getWidth(); x++)
			{
				if (a.getRGB(x, y) != b.getRGB(x, y))
				{
					differing++;
				}
			}
		}
		return differing;
	}

	@Test
	public void bothIconsAreSquareAndTheSameSize() throws IOException
	{
		// they sit side by side in the title row: a mismatch reads as misalignment
		BufferedImage github = icon("link-github");
		BufferedImage kofi = icon("link-kofi");
		Assert.assertEquals(github.getWidth(), github.getHeight());
		Assert.assertEquals(kofi.getWidth(), kofi.getHeight());
		Assert.assertEquals(github.getWidth(), kofi.getWidth());
		Assert.assertTrue("too small to be legible in the sidebar", github.getWidth() >= 12);
	}

	@Test
	public void theGithubMarkIsActuallyDrawn() throws IOException
	{
		double covered = coverage(icon("link-github"));
		Assert.assertTrue("the mark rendered as (nearly) nothing: " + covered, covered > 0.3);
		Assert.assertTrue("the mark filled the whole tile, so no silhouette is readable: "
			+ covered, covered < 0.9);
	}

	@Test
	public void theKofiPlateIsOpaqueEdgeToEdge() throws IOException
	{
		// a rounded plate, so the corners are the only transparent pixels
		double covered = coverage(icon("link-kofi"));
		Assert.assertTrue("the plate did not render: " + covered, covered > 0.85);
	}

	@Test
	public void hoverVariantsDifferFromTheirRestingState() throws IOException
	{
		// hover is the ONLY affordance these labels have — no border, no fill, no
		// focus ring — so an identical hover icon makes them look unclickable
		Assert.assertTrue(differingPixels(icon("link-github"), icon("link-github-hover")) > 20);
		Assert.assertTrue(differingPixels(icon("link-kofi"), icon("link-kofi-hover")) > 20);
	}

	@Test
	public void theSidebarIconShipsAndCarriesAMark() throws IOException
	{
		// the one icon a player sees before opening anything; a missing resource
		// here is a blank button in the RuneLite sidebar
		BufferedImage sidebar = icon("panel-icon");
		Assert.assertEquals(sidebar.getWidth(), sidebar.getHeight());
		double covered = coverage(sidebar);
		Assert.assertTrue("the sidebar icon is blank: " + covered, covered > 0.3);
	}
}

package com.gachaman.ui.panel;

import com.gachaman.*;
import com.gachaman.tools.*;
import java.awt.*;
import java.awt.image.*;
import org.junit.*;

/**
 * The Shop tab's chest icon is a baked PNG now, not a drawing. This is the test
 * that keeps it honest.
 *
 * <p>ChestTile used to paint the chest from scratch on every repaint even
 * though the picture only ever depended on the tier and on whether the tile was
 * affordable — eight possible outputs, re-derived forever. The drawing moved to
 * {@link ShopArt} in test scope, which authors the eight PNGs the plugin now
 * ships, and ShopTab blits one. Three things have to hold for a player not to
 * be able to tell, and each is checked below:
 *
 * <ol>
 * <li>every sprite is actually IN the jar under the name ShopTab rebuilds — a
 * missing or misnamed resource is the one failure mode of this refactor that
 * would reach a player, as a chestless tile, so the test loads them through
 * ShopTab's own accessor rather than by a path of its own;
 * <li>the sprite lands where the drawing used to, which is the blit origin
 * agreeing with the margin ShopArt padded the canvas with;
 * <li>the pixels match what the old code drew.
 * </ol>
 *
 * <p>On that last point the tolerance is honest rather than zero. Compositing
 * the chest into a transparent buffer, encoding it as 8-bit PNG and blending the
 * decoded result over the tile is Porter-Duff OVER either way — the operator is
 * associative, so layering the icon's own overlaps first is mathematically the
 * same answer — but the intermediate buffer quantises to 8 bits per channel
 * where the direct drawing kept going. Measured across four backgrounds and all
 * eight sprites, that costs at most 2/255 on at most ~40 of a tile's 7,440
 * pixels, every one of them on an antialiased edge. The bound is set at 2 so
 * that ordinary rounding passes while anything structural — a wrong colour, a
 * stale palette, an offset that slipped — fails loudly.
 */
public class ShopIconBakeTest
{
	/** The tile the icon is drawn into; RuneLite's DARKER_GRAY under it. */
	private static final int TILE_W = 120;
	private static final int TILE_H = 62;

	/** Per-channel slack, in 8-bit levels. See the class comment. */
	private static final int TOLERANCE = 2;

	@Test
	public void everySpriteIsPresentAndMatchesTheDrawingItReplaced()
	{
		for (Tuning.Chest tier : Tuning.Chest.values())
		{
			for (boolean lit : new boolean[]{true, false})
			{
				// through ShopTab's own loader: if the PNG is missing from
				// src/main/resources, or named differently from what the loader
				// builds, this is where it fails instead of on a player's screen
				Image sprite = ShopTab.chestIcon(tier, lit);
				Assert.assertNotNull(tier + " lit=" + lit + " has no baked sprite", sprite);

				BufferedImage drawn = tile();
				Graphics2D g = drawn.createGraphics();
				g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,
					RenderingHints.VALUE_ANTIALIAS_ON);
				// exactly what ChestTile.paintComponent used to do, at the
				// coordinates it used to do it at
				ShopArt.paint(g, tier.ordinal(), lit, ShopArt.IX, ShopArt.IY);
				g.dispose();

				BufferedImage blitted = tile();
				Graphics2D g2 = blitted.createGraphics();
				g2.drawImage(sprite, ShopTab.ICON_X, ShopTab.ICON_Y, null);
				g2.dispose();

				int worst = maxChannelDelta(drawn, blitted);
				Assert.assertTrue(tier + " lit=" + lit + " differs from the drawing by "
					+ worst + " levels", worst <= TOLERANCE);
			}
		}
	}

	/**
	 * The blit origin and the canvas margin are two halves of one number. If
	 * ShopArt ever pads differently, ShopTab has to move by the same amount or
	 * the chest slides across the tile — a couple of pixels, which is exactly
	 * the size of mistake nobody catches by eye.
	 */
	@Test
	public void theBlitOriginMatchesTheCanvasTheSpritesWereAuthoredOn()
	{
		Assert.assertEquals(ShopArt.ORIGIN_X, ShopTab.ICON_X);
		Assert.assertEquals(ShopArt.ORIGIN_Y, ShopTab.ICON_Y);
	}

	/**
	 * ShopArt deliberately does not import Tuning — it is meant to run from a
	 * bare JDK with no classpath — so its tier order is a copy, and a copy needs
	 * pinning. Both the file names and the palettes are indexed by ordinal.
	 */
	@Test
	public void theAuthoringToolAgreesWithTheChestEnum()
	{
		Tuning.Chest[] tiers = Tuning.Chest.values();
		Assert.assertEquals(tiers.length, ShopArt.TIERS.length);
		Assert.assertEquals(tiers.length, ShopArt.BODY.length);
		Assert.assertEquals(tiers.length, ShopArt.TRIM.length);
		for (Tuning.Chest tier : tiers)
		{
			Assert.assertEquals(tier.name().toLowerCase(java.util.Locale.ROOT),
				ShopArt.TIERS[tier.ordinal()]);
			// the trim table is the one palette that lives in BOTH places: ShopArt
			// paints the icon with it, ShopTab still draws the tile border with it
			Assert.assertEquals("trim drifted for " + tier,
				ShopTab.trimColor(tier), ShopArt.TRIM[tier.ordinal()]);
		}
	}

	private static BufferedImage tile()
	{
		BufferedImage img = new BufferedImage(TILE_W, TILE_H, BufferedImage.TYPE_INT_RGB);
		Graphics2D g = img.createGraphics();
		g.setColor(new Color(30, 30, 30));
		g.fillRect(0, 0, TILE_W, TILE_H);
		g.dispose();
		return img;
	}

	/** Largest per-channel difference anywhere in the two tiles. */
	private static int maxChannelDelta(BufferedImage a, BufferedImage b)
	{
		int worst = 0;
		for (int y = 0; y < TILE_H; y++)
		{
			for (int x = 0; x < TILE_W; x++)
			{
				int p = a.getRGB(x, y);
				int q = b.getRGB(x, y);
				for (int shift = 0; shift < 24; shift += 8)
				{
					worst = Math.max(worst, Math.abs(((p >> shift) & 255) - ((q >> shift) & 255)));
				}
			}
		}
		return worst;
	}
}

package com.gachaman.ui.panel;

import com.gachaman.*;
import java.io.*;
import java.nio.charset.*;
import java.nio.file.*;
import java.util.*;
import java.util.stream.*;
import org.junit.*;

/**
 * Three rules about the sidebar's new text that no behavioural test can reach,
 * because each of them is about a mistake that compiles, runs, and looks right
 * until a player reads it.
 *
 * <p>A source scan rather than a rendering test, on the
 * {@link UnassignCallSiteTest} precedent: driving these lines means a live
 * album, a card database, a week key and a Swing hierarchy, while the invariant
 * itself is one line of text each. Scans also catch code that does not exist
 * yet, which is the point — the next person to add a weapon line to this
 * package is the one these are written for. Tests cost no token budget.
 */
public class PanelWordingScanTest
{
	private static List<Path> panelSources() throws IOException
	{
		Path root = SourceHygieneTest.sourceRoot();
		Assert.assertNotNull("could not locate src/main/java from "
			+ Paths.get("").toAbsolutePath(), root);
		Path panel = root.resolve("com").resolve("gachaman").resolve("ui");
		Assert.assertTrue("no ui package under " + root, Files.isDirectory(panel));
		try (Stream<Path> tree = Files.walk(panel))
		{
			List<Path> files = tree.filter(p -> p.toString().endsWith(".java"))
				.collect(Collectors.toList());
			// an empty walk is the classic silent green
			Assert.assertFalse("scanned no sources under " + panel, files.isEmpty());
			return files;
		}
	}

	/**
	 * Comments are exempt and MUST be, because the reason "unarmed" is banned
	 * from player-facing text can only be written down using the word: the key
	 * for category 0 really is "unarmed", and the javadoc that warns the next
	 * reader off it would otherwise fail this very test.
	 */
	private static boolean isComment(String line)
	{
		String trimmed = line.trim();
		return trimmed.startsWith("//") || trimmed.startsWith("*") || trimmed.startsWith("/*");
	}

	/**
	 * The owner's rule: category 0 is reported for every non-weapon item a player
	 * might be holding, so calling it "unarmed" would be a claim about their
	 * hands the varbit cannot support. Its display name is "No weapon equipped",
	 * and a resource test already stops the JSON from saying otherwise — this is
	 * the same guard on the side that renders it.
	 */
	@Test
	public void noPanelStringEverSaysUnarmed() throws IOException
	{
		List<String> offenders = new ArrayList<>();
		for (Path file : panelSources())
		{
			List<String> lines = Files.readAllLines(file, StandardCharsets.UTF_8);
			for (int i = 0; i < lines.size(); i++)
			{
				String line = lines.get(i);
				if (!isComment(line)
					&& line.toLowerCase(Locale.ROOT).contains("narmed"))
				{
					offenders.add(file.getFileName() + ":" + (i + 1) + "  " + line.trim());
				}
			}
		}
		Assert.assertEquals("player-facing text must say \"no weapon equipped\","
			+ " never \"unarmed\"", Collections.emptyList(), offenders);
	}

	/**
	 * The preferred weapon is persisted as a KEY and rendered as a NAME, and the
	 * two are deliberately different strings. Every read of the raw field must go
	 * straight into {@code WeaponTypeService.displayName}, which is also what
	 * makes a key this build no longer knows render as nothing rather than as
	 * itself.
	 */
	@Test
	public void thePersistedWeaponKeyIsOnlyEverResolvedToAName() throws IOException
	{
		List<String> offenders = new ArrayList<>();
		int reads = 0;
		for (Path file : panelSources())
		{
			List<String> lines = Files.readAllLines(file, StandardCharsets.UTF_8);
			for (int i = 0; i < lines.size(); i++)
			{
				String line = lines.get(i);
				if (isComment(line) || !line.contains("getPreferredWeaponType()"))
				{
					continue;
				}
				reads++;
				if (!line.contains("displayName("))
				{
					offenders.add(file.getFileName() + ":" + (i + 1) + "  " + line.trim());
				}
			}
		}
		Assert.assertEquals("a raw weapon-type key must never reach the screen",
			Collections.emptyList(), offenders);
		Assert.assertTrue("the guard is only real while somebody reads the field", reads > 0);
	}

	/**
	 * Paying the Toll rolls a chest, and rolling a chest reads live skill levels
	 * — client thread only. A Swing listener calling it directly would work on
	 * every machine right up until it did not, which is the failure this package
	 * already routes every other purchase around.
	 */
	@Test
	public void theTollIsOnlyEverPaidFromTheClientThread() throws IOException
	{
		List<String> offenders = new ArrayList<>();
		int calls = 0;
		for (Path file : panelSources())
		{
			List<String> lines = Files.readAllLines(file, StandardCharsets.UTF_8);
			for (int i = 0; i < lines.size(); i++)
			{
				// tollService.purchase() by name, not a bare ".purchase()": the
				// weekly shop's purchase(index) is called straight from the EDT on
				// purpose, and the next zero-arg purchase somebody adds under ui/
				// might legitimately be too. A guard that fails on somebody else's
				// correct code is a guard that gets deleted.
				if (isComment(lines.get(i)) || !lines.get(i).contains("tollService.purchase()"))
				{
					continue;
				}
				calls++;
				boolean hopped = false;
				// the hop opens the lambda a line or two above the call
				for (int back = i; back >= Math.max(0, i - 4); back--)
				{
					hopped |= lines.get(back).contains("clientThread.invokeLater");
				}
				if (!hopped)
				{
					offenders.add(file.getFileName() + ":" + (i + 1) + "  " + lines.get(i).trim());
				}
			}
		}
		Assert.assertEquals("a chest roll off the client thread reads game state from the EDT",
			Collections.emptyList(), offenders);
		Assert.assertTrue("the guard is only real while somebody pays the Toll", calls > 0);
	}
}

package com.gachaman.ui.panel;

import com.gachaman.*;
import com.gachaman.service.*;
import java.io.*;
import java.lang.reflect.*;
import java.nio.charset.*;
import java.nio.file.*;
import java.util.*;
import java.util.function.*;
import net.runelite.client.callback.*;
import org.junit.*;

/**
 * Two defects in the Overview panel that a compiler cannot see.
 *
 * <p>The first is a number that changes shape with the player's locale; the
 * second is an overload the compiler picks silently and wrongly. Neither shows
 * up on a UK/US developer machine, and neither needs a live client to pin.
 */
public class OverviewTabTest
{
	private Locale savedDisplay;
	private Locale savedFormat;

	/**
	 * {@code Locale.setDefault} is process-global and JUnit 4 shares one JVM
	 * across every test class, so a leaked German default would surface as a
	 * failure in somebody ELSE'S test, order-dependently. Both categories are
	 * saved because setDefault(Locale) overwrites both.
	 */
	@Before
	public void rememberLocale()
	{
		savedDisplay = Locale.getDefault(Locale.Category.DISPLAY);
		savedFormat = Locale.getDefault(Locale.Category.FORMAT);
	}

	@After
	public void restoreLocale()
	{
		Locale.setDefault(Locale.Category.DISPLAY, savedDisplay);
		Locale.setDefault(Locale.Category.FORMAT, savedFormat);
	}

	@Test
	public void aFractionKeepsItsDecimalPointOnACommaDecimalClient()
	{
		// de, fr, es, pt-BR and much of the EU: default-locale String.format
		// rendered these as "2,5" and "x1,5" while QuantityFormatter alongside
		// them was printing "1,250 GC" — two commas, opposite meanings
		Locale.setDefault(Locale.GERMANY);
		Assert.assertEquals("2.5", OverviewTab.trimDouble(2.5));
		Assert.assertEquals("0.5", OverviewTab.trimDouble(0.5));
		Locale.setDefault(Locale.FRANCE);
		Assert.assertEquals("2.5", OverviewTab.trimDouble(2.5));
	}

	@Test
	public void theDoubleDocketMultiplierIsAReachableFractionalCase()
	{
		// not a hypothetical path: the tuning value really is fractional, so the
		// Double Docket label and its tooltip both hit the format branch
		Assert.assertNotEquals(Tuning.DOUBLE_DOCKET_MULT,
			Math.floor(Tuning.DOUBLE_DOCKET_MULT), 0.0);
		Locale.setDefault(Locale.GERMANY);
		Assert.assertEquals("1.2", OverviewTab.trimDouble(Tuning.DOUBLE_DOCKET_MULT));
	}

	@Test
	public void wholeNumbersStayWholeInEveryLocale()
	{
		Locale.setDefault(Locale.GERMANY);
		Assert.assertEquals("3", OverviewTab.trimDouble(3));
		Assert.assertEquals("0", OverviewTab.trimDouble(0));
		Locale.setDefault(Locale.UK);
		Assert.assertEquals("3", OverviewTab.trimDouble(3));
	}

	@Test
	public void theCommonLocalesSeeExactlyWhatTheyAlreadySaw()
	{
		Locale.setDefault(Locale.UK);
		Assert.assertEquals("2.5", OverviewTab.trimDouble(2.5));
		Locale.setDefault(Locale.US);
		Assert.assertEquals("2.5", OverviewTab.trimDouble(2.5));
	}

	/**
	 * The three facts that together make {@code invokeLater(taskService::presentOffers)}
	 * a permanent per-tick leak, asserted separately so a failure says WHICH one
	 * moved.
	 *
	 * <p>ClientThread declares both overloads; presentOffers returns boolean; and
	 * for an exact method reference JLS 15.12.2.5 prefers the non-void functional
	 * interface. RuneLite re-queues a BooleanSupplier that returns false, which
	 * presentOffers does whenever the board is empty. If any of these three ever
	 * stops holding, the guard below is no longer needed and this test says so.
	 */
	@Test
	public void theOverloadTrapStillExists() throws NoSuchMethodException
	{
		Assert.assertNotNull(ClientThread.class.getMethod("invokeLater", Runnable.class));
		try
		{
			ClientThread.class.getMethod("invokeLater", BooleanSupplier.class);
		}
		catch (NoSuchMethodException e)
		{
			Assert.fail("ClientThread no longer declares invokeLater(BooleanSupplier);"
				+ " the ambiguity this guards against is gone and viewRolledContracts"
				+ " can be inlined again");
		}
		Assert.assertEquals("presentOffers must keep returning boolean for this trap"
			+ " to apply — if it went void the guard is moot",
			boolean.class, TaskService.class.getMethod("presentOffers").getReturnType());
	}

	@Test
	public void theViewButtonHopsThroughAVoidTarget()
	{
		// void is the whole point: it is the only return type that makes
		// invokeLater(Runnable) the more specific overload
		Method target;
		try
		{
			target = OverviewTab.class.getDeclaredMethod("viewRolledContracts");
		}
		catch (NoSuchMethodException e)
		{
			throw new AssertionError("viewRolledContracts is gone — the View Rolled"
				+ " Contracts button has probably been pointed straight at"
				+ " taskService::presentOffers again", e);
		}
		Assert.assertEquals(void.class, target.getReturnType());
		Assert.assertEquals(0, target.getParameterCount());
	}

	/**
	 * Reflection can prove the hop target is void but cannot see which target the
	 * button's lambda actually names, so the call site itself is pinned as text.
	 * Ugly, and worth it: reverting to the direct method reference is the exact
	 * edit that reintroduces the bug, and it compiles clean and runs fine until a
	 * click happens to land on an empty board.
	 */
	@Test
	public void theCallSiteNeverNamesTheBooleanReturningMethodDirectly() throws IOException
	{
		String code = codeOnly(overviewSource());

		Assert.assertFalse("invokeLater(taskService::presentOffers) binds to the"
			+ " BooleanSupplier overload and re-queues every tick forever",
			code.contains("invokeLater(taskService::presentOffers)"));
		Assert.assertTrue("the View Rolled Contracts button should hop through the"
			+ " void viewRolledContracts()",
			code.contains("invokeLater(this::viewRolledContracts)"));
		// The sibling call, invokeLater(taskService::rollOffers), is deliberately
		// NOT pinned here. It is safe because rollOffers returns List<TaskOffer>,
		// which is not assignable to boolean, so BooleanSupplier is not applicable
		// — safe by RETURN TYPE, not by spelling. Asserting on its text would turn
		// this test red if someone rewrote it as an equally-correct block lambda,
		// and this file still carries unapplied terser/dedupe findings in exactly
		// that block.
	}

	private static String overviewSource() throws IOException
	{
		Path root = SourceHygieneTest.sourceRoot();
		Assert.assertNotNull("could not locate src/main/java", root);
		Path file = root.resolve("com/gachaman/ui/panel/OverviewTab.java");
		Assert.assertTrue("missing " + file, Files.isRegularFile(file));
		return new String(Files.readAllBytes(file), StandardCharsets.UTF_8);
	}

	/**
	 * The source with comments stripped, so a prose mention of a call cannot
	 * stand in for the call itself. This matters here specifically:
	 * {@code viewRolledContracts}' own javadoc QUOTES the bad spelling in order
	 * to explain it, so an unstripped search would match the warning rather than
	 * the code and the test would fail while the code was correct.
	 *
	 * <p>Tracks string and char literals, including backslash escapes, so that a
	 * {@code "https://..."} URL is not mistaken for the start of a line comment
	 * — OverviewTab builds exactly such a literal for the wiki button. Nothing
	 * here needs to handle text blocks: the build targets Java 11.
	 */
	private static String codeOnly(String source)
	{
		final int code = 0;
		final int string = 1;
		final int character = 2;
		final int lineComment = 3;
		final int blockComment = 4;

		StringBuilder out = new StringBuilder(source.length());
		int mode = code;
		for (int i = 0; i < source.length(); i++)
		{
			char c = source.charAt(i);
			char next = i + 1 < source.length() ? source.charAt(i + 1) : '\n';
			if (mode == code)
			{
				if (c == '/' && next == '/')
				{
					mode = lineComment;
					i++;
				}
				else if (c == '/' && next == '*')
				{
					mode = blockComment;
					i++;
				}
				else
				{
					if (c == '"')
					{
						mode = string;
					}
					else if (c == '\'')
					{
						mode = character;
					}
					out.append(c);
				}
			}
			else if (mode == string || mode == character)
			{
				out.append(c);
				if (c == '\\')
				{
					// an escaped quote does not close the literal, and an escaped
					// backslash must not swallow the quote that follows it
					out.append(next);
					i++;
				}
				else if (c == (mode == string ? '"' : '\''))
				{
					mode = code;
				}
			}
			else if (mode == lineComment)
			{
				if (c == '\n')
				{
					// keep the newline so nothing on the next line joins this one
					out.append(c);
					mode = code;
				}
			}
			else if (c == '*' && next == '/')
			{
				mode = code;
				i++;
			}
		}
		return out.toString();
	}

	@Test
	public void theCommentStripperItselfBehaves()
	{
		// the four shapes the assertion above depends on getting right
		Assert.assertEquals("a  b", codeOnly("a /* x */ b"));
		Assert.assertEquals("a \n", codeOnly("a // x\n"));
		Assert.assertEquals("\"http://x\"", codeOnly("\"http://x\""));
		Assert.assertEquals("\"a\\\"//b\"", codeOnly("\"a\\\"//b\""));
	}
}

package com.gachaman.ui.panel;

import com.gachaman.model.*;
import com.gachaman.service.*;
import java.util.*;
import javax.swing.*;
import javax.swing.text.*;
import org.junit.*;

/**
 * The Preferred Weapon block as a player actually reads it, built against the
 * REAL shipped taxonomy and the real Tuning tables.
 *
 * <p>Every other test of this block checks a number in isolation. This one
 * assembles the lines, which is the only way to catch the two mistakes that
 * would survive all of them: the persisted key reaching the screen instead of
 * the display name, and the honesty sentence quietly losing its figures.
 *
 * <p>Headless-safe — nothing here realises a window, and the panel's own
 * helpers only measure text, which AWT does without a display.
 */
public class OverviewWeaponRenderTest
{
	/**
	 * Only the taxonomy is wired: addWeaponLines reads that and the state it is
	 * handed, and touches no other collaborator. The same all-nulls arrangement
	 * ShopChargeButtonTest uses on the other tab.
	 */
	private static OverviewTab tab()
	{
		return new OverviewTab(null, null, null, null, null, null,
			WeaponTypeFixture.taxonomy(), null);
	}

	private static GachaState state(String weaponKey, ActiveTask task)
	{
		return GachaState.fresh(50).withAllowedStyle(AttackStyle.MELEE.name())
			.withPreferredWeaponType(weaponKey).withActiveTask(task);
	}

	/** An ordinary Easy contract: 20 kills at 4 GC, 400 GC to finish. */
	private static ActiveTask easyContract()
	{
		return ActiveTask.builder().difficulty(TaskDifficulty.EASY).monsterName("Goblin")
			.killsRequired(20).perKillGc(4).completionGc(400).build();
	}

	/** Every word the block put on screen, labels and wrapped paragraphs alike. */
	private static String rendered(GachaState state)
	{
		JPanel section = new JPanel();
		section.setLayout(new BoxLayout(section, BoxLayout.Y_AXIS));
		tab().addWeaponLines(section, state, AttackStyle.MELEE);
		StringBuilder text = new StringBuilder();
		for (java.awt.Component child : section.getComponents())
		{
			if (child instanceof JLabel)
			{
				text.append(((JLabel) child).getText()).append('\n');
			}
			else if (child instanceof JEditorPane)
			{
				Document doc = ((JEditorPane) child).getDocument();
				try
				{
					text.append(doc.getText(0, doc.getLength())).append('\n');
				}
				catch (BadLocationException e)
				{
					throw new AssertionError(e);
				}
			}
		}
		return text.toString();
	}

	/**
	 * The owner's rule, end to end. Category 0 is reported for every non-weapon
	 * item a player might be holding, so its name is "No weapon equipped" — while
	 * the key it is persisted under, and the word this line must never contain,
	 * is "unarmed".
	 */
	@Test
	public void categoryZeroReadsAsNoWeaponEquippedAndNeverAsItsKey()
	{
		String shown = rendered(state("unarmed", easyContract()));
		Assert.assertTrue("the display name must be on screen: " + shown,
			shown.contains("No weapon equipped"));
		Assert.assertFalse("the persisted key must never reach the player: " + shown,
			shown.toLowerCase(Locale.ROOT).contains("narmed"));
	}

	/**
	 * The honesty sentence, with the numbers a player can check by hand: 20 kills
	 * at 4 GC is 80 GC of kill income against 400 GC of completion, so kill GC is
	 * a sixth of the 480 GC contract and the x1.5 buys about 8% of slack.
	 */
	@Test
	public void anEasyContractPrintsItsRealShareAndBreakEven()
	{
		String shown = rendered(state("axe", easyContract()));
		Assert.assertTrue("the category is named: " + shown, shown.contains("Axes"));
		Assert.assertTrue("the share of the contract is stated: " + shown,
			shown.contains("17%"));
		Assert.assertTrue("the contract's own total is stated: " + shown,
			shown.contains("480 GC"));
		Assert.assertTrue("the break-even is stated: " + shown, shown.contains("8% slower"));
		Assert.assertTrue("and what it means is stated: " + shown,
			shown.contains("pay cut"));
	}

	/**
	 * The same weapon on an Insane contract is worth nearly three times as much
	 * slack, which is the entire reason the panel prints a number instead of the
	 * multiplier. 100 kills at 28 GC against 3,600 GC to finish.
	 */
	@Test
	public void anInsaneContractPrintsAFarLargerBreakEven()
	{
		String shown = rendered(state("axe", ActiveTask.builder()
			.difficulty(TaskDifficulty.INSANE).monsterName("Abyssal demon")
			.killsRequired(100).perKillGc(28).completionGc(3600).build()));
		Assert.assertTrue("the share of the contract is stated: " + shown,
			shown.contains("44%"));
		Assert.assertTrue("the break-even is stated: " + shown, shown.contains("22% slower"));
	}

	/**
	 * A preference saved under a key this build no longer carries resolves to
	 * nothing, and nothing is what must be shown — not the key, and not an error.
	 */
	@Test
	public void aKeyThisBuildNoLongerKnowsReadsAsNoBonusRatherThanAsItself()
	{
		String shown = rendered(state("halberd_of_a_later_patch", easyContract()));
		Assert.assertTrue("no bonus, said plainly: " + shown,
			shown.contains("no bonus available"));
		Assert.assertFalse("the unknown key must not be echoed: " + shown,
			shown.contains("halberd_of_a_later_patch"));
	}

	@Test
	public void aRedemptionContractSaysWhyTheBonusIsWorthNothing()
	{
		String shown = rendered(state("axe", ActiveTask.builder()
			.difficulty(TaskDifficulty.HARD).monsterName("Anything").killsRequired(20)
			.perKillGc(0).completionGc(1900).redemption(true).build()));
		Assert.assertTrue("the category is still named: " + shown, shown.contains("Axes"));
		Assert.assertTrue("and the reason it pays nothing: " + shown,
			shown.contains("no bonus available"));
		Assert.assertFalse("a break-even here would be a division by an income of zero: "
			+ shown, shown.contains("slower"));
	}

	@Test
	public void noPreferenceAtAllIsNotDressedAsAFailure()
	{
		String shown = rendered(state(null, easyContract()));
		Assert.assertTrue(shown, shown.contains("no bonus available"));
		Assert.assertFalse("nothing here is the player's fault: " + shown,
			shown.toLowerCase(Locale.ROOT).contains("error"));
	}
}

package com.gachaman.ui.panel;

import org.junit.*;

/**
 * The Patrons page's "last shared" stamp.
 *
 * Every boundary here is a real one a player hits — a partner from last night,
 * from last month, from last year — and the whole reason the age is rendered
 * relatively is that an absolute "MMM d" with no year reads as THIS year for a
 * patron you last rolled with fourteen months ago.
 */
public class PatronsTabAgoTest
{
	private static final long DAY = 86_400_000L;

	/** An arbitrary fixed "now". Wall-clock time would make this unassertable. */
	private static final long NOW = 1_700_000_000_000L;

	@Test
	public void anUnrecordedStampPrintsNothing()
	{
		// a record written before lastSharedAt existed carries 0, and rendering
		// that would date the partnership to 1970 — the caller drops the whole
		// segment on an empty string rather than printing a wrong age
		Assert.assertEquals("", PatronsTab.ago(0, NOW));
		Assert.assertEquals("", PatronsTab.ago(-1, NOW));
	}

	@Test
	public void theFirstTwoDaysReadAsWords()
	{
		Assert.assertEquals("today", PatronsTab.ago(NOW, NOW));
		Assert.assertEquals("today", PatronsTab.ago(NOW - DAY + 1, NOW));
		Assert.assertEquals("yesterday", PatronsTab.ago(NOW - DAY, NOW));
		Assert.assertEquals("yesterday", PatronsTab.ago(NOW - 2 * DAY + 1, NOW));
	}

	@Test
	public void eachUnitTakesOverAtItsBoundary()
	{
		Assert.assertEquals("2d ago", PatronsTab.ago(NOW - 2 * DAY, NOW));
		Assert.assertEquals("6d ago", PatronsTab.ago(NOW - 6 * DAY, NOW));
		Assert.assertEquals("1w ago", PatronsTab.ago(NOW - 7 * DAY, NOW));
		Assert.assertEquals("4w ago", PatronsTab.ago(NOW - 29 * DAY, NOW));
		Assert.assertEquals("1mo ago", PatronsTab.ago(NOW - 30 * DAY, NOW));
		Assert.assertEquals("12mo ago", PatronsTab.ago(NOW - 364 * DAY, NOW));
		Assert.assertEquals("1y ago", PatronsTab.ago(NOW - 365 * DAY, NOW));
		Assert.assertEquals("3y ago", PatronsTab.ago(NOW - 1200 * DAY, NOW));
	}

	@Test
	public void aBackwardsClockReadsAsToday()
	{
		// a resync, a save copied from another machine, or a hand-edited stamp
		// can all put the last contract in the future. "shared -3 days ago" is
		// the one answer here that is certainly wrong.
		Assert.assertEquals("today", PatronsTab.ago(NOW + DAY, NOW));
		Assert.assertEquals("today", PatronsTab.ago(NOW + 500 * DAY, NOW));
	}

	@Test
	public void everyAgeFitsTheColumn()
	{
		// the sidebar is ~200px and this shares a line with the tier label, so a
		// long form would wrap the row and push the next patron off-screen
		for (long days = 0; days <= 4000; days++)
		{
			String text = PatronsTab.ago(NOW - days * DAY, NOW);
			Assert.assertNotNull(text);
			Assert.assertFalse("no age may be blank at " + days + " days", text.isEmpty());
			Assert.assertTrue("too long at " + days + " days: " + text, text.length() <= 9);
		}
	}
}

package com.gachaman.ui.panel;

import com.gachaman.service.*;
import java.util.concurrent.atomic.*;
import javax.swing.*;
import net.runelite.client.callback.ClientThread;
import org.junit.*;

/**
 * The Chest Odds in-flight latch, against a client-thread body that throws.
 *
 * <p>ShopTab computes odds on the client thread because they read live skill
 * levels, and allows one flight at a time so a rebuild storm cannot queue a job per
 * rebuild. That flag is raised on the EDT before the job is posted and lowered by
 * the continuation the job posts back. If the job dies before it gets to post
 * anything, the flag is never lowered: every later request returns at the guard,
 * the panel is stuck on "Reading your levels…" for the rest of the session, and
 * nothing in the UI says why. The fix posts the continuation from a finally, so the
 * flag comes down whether the body returned or threw.
 *
 * <p>The scenario is reproduced honestly rather than simulated: chestService is
 * null, so the real {@code chestService.oddsFor(wanted)} call inside the real
 * client-thread body throws, exactly as a failure inside oddsFor would. Every other
 * collaborator is untouched on this path — the constructor only assigns fields, and
 * a throwing body never reaches the code that would use them.
 */
public class ShopOddsRequestTest
{
	/**
	 * Runs the job inline on the calling thread and counts the jobs handed over.
	 *
	 * <p>Overrides the Runnable overload deliberately: ClientThread also declares
	 * invokeLater(BooleanSupplier), and ShopTab's lambda has a void body, so it binds
	 * to this one. Overriding the other would silently observe nothing.
	 */
	private static final class InlineClientThread extends ClientThread
	{
		final AtomicInteger jobs = new AtomicInteger();

		@Override
		public void invokeLater(Runnable job)
		{
			jobs.incrementAndGet();
			job.run();
		}
	}

	@Test
	public void aThrowingOddsCallDoesNotLatchTheRequestFlagForever() throws Exception
	{
		InlineClientThread clientThread = new InlineClientThread();
		// a state service over a null store answers null from get(), which is the
		// logged-out case requestOdds already handles (it stamps -1). Every other
		// collaborator is null, chestService (the second argument) included — that
		// null IS the failure this test reproduces.
		ShopTab tab = new ShopTab(new GachaStateService(null), null, null, null, null, null,
			clientThread, null, null, null);

		Assert.assertTrue("the null chestService should have thrown inside the job",
			fireAndCatch(tab));
		drainEdt();
		Assert.assertEquals("the first request should have reached the client thread",
			1, clientThread.jobs.get());

		fireAndCatch(tab);
		drainEdt();
		// before the fix the continuation was posted only on success, so the flag was
		// still up here and this second request was swallowed at the guard
		Assert.assertEquals("a second request after a failed one must still be posted",
			2, clientThread.jobs.get());
	}

	@Test
	public void aFailedRequestDoesNotRebuildIntoAnotherRequest() throws Exception
	{
		InlineClientThread clientThread = new InlineClientThread();
		ShopTab tab = new ShopTab(new GachaStateService(null), null, null, null, null, null,
			clientThread, null, null, null);

		fireAndCatch(tab);
		drainEdt();

		// the failure path must clear the flag and stop. Rebuilding there would ask
		// buildOddsSection for a section with no snapshot, which requests again — a
		// tight loop between the client thread and the EDT. One job, not many, and the
		// panel is left exactly as it was rather than re-laid-out from a failure.
		Assert.assertEquals(1, clientThread.jobs.get());
		Assert.assertEquals("the failure path should not have rebuilt the panel",
			0, tab.getComponentCount());
	}

	/** Fires one request inline; returns whether the client-thread body threw. */
	private static boolean fireAndCatch(ShopTab tab)
	{
		try
		{
			tab.requestOdds();
			return false;
		}
		catch (NullPointerException expected)
		{
			// the throw is meant to keep travelling: RuneLite's own ClientThread logs
			// it, so the failure is recoverable without being silent
			return true;
		}
	}

	/** Blocks until everything already queued on the EDT has run. */
	private static void drainEdt() throws Exception
	{
		SwingUtilities.invokeAndWait(() ->
		{
		});
	}
}

package com.gachaman.ui.panel;

import java.nio.charset.*;
import java.nio.file.*;
import java.util.*;
import com.gachaman.*;
import org.junit.*;

/**
 * Every {@code GachamanPanel.Tab} must have a rebuilder registered for it.
 *
 * <p>{@code rebuildIfDirty} used to be an eleven-arm switch, one arm per tab,
 * each arm the same statement with a different receiver. That shape is now an
 * {@code EnumMap<Tab, Runnable>} filled by {@code addCard} beside the card it
 * belongs to — smaller, and it cannot get a tab's rebuild call attached to the
 * wrong constant. What it does NOT do by itself is notice a tab nobody
 * registered: the old switch would silently fall through such a case and draw
 * nothing, and the map would hand back null, NPE inside the existing try, and
 * log a warning. Neither is a crash and neither is visible in review, so the
 * guarantee is pinned here instead.
 *
 * <p>Asserted against the SOURCE rather than a live panel because constructing
 * a GachamanPanel needs the whole Guice graph, a card database and an EDT —
 * none of which this invariant depends on. The registration is a lexical fact
 * about the constructor, so a lexical check is the honest one. Tests cost
 * nothing here: the Plugin Hub bot counts only {@code src/main/java}.
 */
public class TabRebuilderRegistrationTest
{
	@Test
	public void everyTabRegistersARebuilder() throws Exception
	{
		Path root = SourceHygieneTest.sourceRoot();
		Assert.assertNotNull("could not locate src/main/java from "
			+ Paths.get("").toAbsolutePath(), root);
		Path source = root.resolve("com/gachaman/ui/panel/GachamanPanel.java");
		Assert.assertTrue("missing " + source, Files.isRegularFile(source));
		String text = new String(Files.readAllBytes(source), StandardCharsets.UTF_8);

		// Tab is a private nested enum, so it cannot be named from here even in
		// the same package; reflection reads the constants without taking any
		// position on how the enum is written.
		Object[] tabs = Class.forName("com.gachaman.ui.panel.GachamanPanel$Tab")
			.getEnumConstants();
		Assert.assertNotNull("GachamanPanel.Tab is no longer an enum, or could not"
			+ " be loaded — this test cannot silently pass on that", tabs);
		Assert.assertTrue("GachamanPanel.Tab has no constants", tabs.length > 0);

		List<String> unregistered = new ArrayList<>();
		for (Object tab : tabs)
		{
			if (!text.contains("addCard(Tab." + tab + ","))
			{
				unregistered.add(tab.toString());
			}
		}
		Assert.assertEquals("every Tab needs an addCard(Tab.X, card, x::rebuild)"
			+ " call in the GachamanPanel constructor — without one the tab shows"
			+ " a card that never redraws and logs a warning instead",
			Collections.emptyList(), unregistered);

		// and no more registrations than there are tabs, so a stray or duplicated
		// addCard cannot hide here either
		int calls = 0;
		for (int at = text.indexOf("addCard(Tab."); at >= 0;
			at = text.indexOf("addCard(Tab.", at + 1))
		{
			calls++;
		}
		Assert.assertEquals("one addCard per Tab, no duplicates", tabs.length, calls);
	}
}

package com.gachaman.ui;

import java.util.List;
import com.gachaman.model.*;
import java.awt.*;
import java.util.*;
import org.junit.*;

public class CardRendererTest
{
	/** The album thumbnail, which is the tightest surface the wear art has to fit. */
	private static final int THUMB_W = 90;
	private static final int THUMB_H = 120;
	/**
	 * The card corner has room for four characters, not six. Integer math only,
	 * so this cannot flake on a machine with a different default Locale.
	 */
	@Test
	public void serviceTextBoundaries()
	{
		Assert.assertEquals("0", CardRenderer.serviceText(0));
		Assert.assertEquals("1", CardRenderer.serviceText(1));
		Assert.assertEquals("999", CardRenderer.serviceText(999));
		Assert.assertEquals("1.0k", CardRenderer.serviceText(1000));
		Assert.assertEquals("1.2k", CardRenderer.serviceText(1234));
		Assert.assertEquals("9.9k", CardRenderer.serviceText(9999));
		Assert.assertEquals("10k", CardRenderer.serviceText(10000));
		Assert.assertEquals("999k", CardRenderer.serviceText(999999));
		Assert.assertEquals("1m", CardRenderer.serviceText(1000000));
	}

	/**
	 * Four characters is the whole reachable domain. A kill costs at least one
	 * game tick, so 999,999,999 kills is roughly nineteen thousand years of
	 * uninterrupted combat — the badge is not sized for anything past it.
	 */
	@Test
	public void serviceTextNeverExceedsFourCharacters()
	{
		int[] samples = {0, 9, 99, 999, 1000, 5555, 9999, 10000, 87654, 999999, 1000000,
			12345678, 999999999};
		for (int n : samples)
		{
			Assert.assertTrue("too wide for the corner pill at " + n,
				CardRenderer.serviceText(n).length() <= 4);
		}
	}

	/**
	 * A card with no service record must render pixel-identically to the way it
	 * did before this feature existed, so the label span has to collapse back to
	 * the plain 4px inset.
	 */
	@Test
	public void noBadgeLeavesTheRarityLabelSpanUntouched()
	{
		Assert.assertEquals(4, CardRenderer.rarityLabelLeft(0, 90, -1));
		Assert.assertEquals(104, CardRenderer.rarityLabelLeft(100, 150, -1));
	}

	/**
	 * The badge and the centred rarity label share the top band. The label span
	 * must start clear of the pill at every size the card is ever drawn at —
	 * album thumbnails (90px) through reveal cards (150px) — and the clearance
	 * has to come from the shared geometry, not from a lucky font measurement.
	 */
	@Test
	public void theRarityLabelNeverStartsUnderTheServiceBadge()
	{
		for (int w = 40; w <= 400; w++)
		{
			for (int textW = 0; textW <= 60; textW++)
			{
				int badgeRight = CardRenderer.serviceBadgeX(0, w)
					+ CardRenderer.serviceBadgeWidth(w, textW);
				int labelLeft = CardRenderer.rarityLabelLeft(0, w, textW);
				Assert.assertTrue("label overlaps the badge at w=" + w + " textW=" + textW,
					labelLeft > badgeRight);
			}
		}
	}

	/**
	 * Reserving on the left only (rather than mirroring the margin to keep the
	 * label centred on the card) is what keeps "LEGENDARY" whole on the album
	 * thumbnail. Pin the span so a later "let's re-centre it" edit has to face
	 * the number it would cost.
	 */
	@Test
	public void theAlbumThumbnailKeepsRoomForTheLongestRarityWord()
	{
		// 90px thumbnail, a four-character record measuring ~18px at 8pt bold
		int span = (0 + 90 - 4) - CardRenderer.rarityLabelLeft(0, 90, 18);
		Assert.assertTrue("only " + span + "px left for LEGENDARY", span >= 50);
	}

	/** Only ASCII digits, '.', 'k' and 'm' — the badge font has no exotic glyphs. */
	@Test
	public void serviceTextIsPlainAscii()
	{
		int[] samples = {0, 7, 999, 1000, 4321, 9999, 10000, 250000, 1000000, 999999999};
		for (int n : samples)
		{
			Assert.assertTrue("unexpected characters at " + n,
				CardRenderer.serviceText(n).matches("[0-9.km]+"));
		}
	}

	// --- cosmetic wear (Cracked Cards) ---
	//
	// Creases and scratches cross the whole card face, ART INCLUDED — that is the
	// design, and the reason these tests no longer model a sprite rect at all. A
	// card creases through the picture. What wear may never sit on is TEXT.
	//
	// The other half of the design, and the harder one to keep by accident: every
	// card wears DIFFERENTLY and every card in a bracket wears the same AMOUNT.
	// Pattern is seeded, weight is not.

	private static final int[] SEEDS = {0, 1, -1, 7, 42, -913, 100003, Integer.MIN_VALUE,
		Integer.MAX_VALUE, "Abyssal whip".hashCode(), "Bandos chestplate".hashCode(),
		"Twisted bow".hashCode()};

	private static final CardWear[] WORN = {CardWear.HAIRLINE, CardWear.CRACKED,
		CardWear.SHATTERED};

	/** The band edges drawFace hands the wear pass, re-derived from its own arithmetic. */
	private static int topBandBottom(int y, int w, int h)
	{
		return y + h / 14 + 4 + Math.max(8, w / 11);
	}

	private static int nameBandTop(int y, int h)
	{
		return y + h - Math.max(16, h / 6) - h / 8;
	}

	private static List<int[]> ofKind(List<int[]> segments, int kind)
	{
		List<int[]> out = new ArrayList<>();
		for (int[] s : segments)
		{
			if (s[4] == kind)
			{
				out.add(s);
			}
		}
		return out;
	}

	/**
	 * The painted footprint of one round-capped segment, tested against the
	 * protected rects with arithmetic of its own. Deliberately NOT a call to
	 * CardRenderer.blocked() — wearSegments already filters with that, so reusing
	 * it would assert only that the filter agrees with itself.
	 */
	private static void assertInkIsClear(String where, int[] seg, Rectangle[] protect, float reach)
	{
		double x0 = Math.min(seg[0], seg[2]) - reach;
		double y0 = Math.min(seg[1], seg[3]) - reach;
		double x1 = Math.max(seg[0], seg[2]) + reach;
		double y1 = Math.max(seg[1], seg[3]) + reach;
		String[] names = {"the rarity label / service pill", "the card name"};
		for (int i = 0; i < protect.length; i++)
		{
			Rectangle r = protect[i];
			if (r == null)
			{
				continue;
			}
			boolean overlaps = x1 > r.getMinX() && x0 < r.getMaxX()
				&& y1 > r.getMinY() && y0 < r.getMaxY();
			Assert.assertFalse(where + ": wear covers " + names[i] + " " + r, overlaps);
		}
	}

	/**
	 * The promise this feature still makes: wear is art added to a card you
	 * already own, so it may never sit on top of the words you read the card BY.
	 * Swept across every size the plugin draws, both origins, all stages and a
	 * spread of name hashes, because a guarantee that holds only for the sizes
	 * someone happened to look at is not a guarantee.
	 *
	 * <p>Note what is NOT in the protected set any more: the item sprite. Keeping
	 * the damage out of the picture is exactly what forced the old renderer to
	 * route its cracks down the eight-pixel gutters beside the art, and that is
	 * what made them read as margin scribble instead of as wear.
	 */
	@Test
	public void wearNeverCoversTheNameOrTheRarityLabel()
	{
		for (int w = 40; w <= 260; w += 2)
		{
			int h = w * 29 / 20;
			int x = (w % 7) * 13;
			int y = (w % 5) * 9;
			Rectangle[] protect = CardRenderer.wearProtect(x, y, w, h,
				topBandBottom(y, w, h), nameBandTop(y, h));
			for (CardWear wear : CardWear.values())
			{
				for (int seed : SEEDS)
				{
					String where = "w=" + w + " " + wear + " seed=" + seed;
					for (int[] seg : CardRenderer.wearSegments(x, y, w, h, wear, seed, protect))
					{
						assertInkIsClear(where, seg, protect, CardRenderer.wearInkReach(w));
					}
				}
			}
		}
	}

	/**
	 * A crease is supposed to cross the sprite. This is the assertion that keeps
	 * the old design from creeping back in: measure the box the art actually
	 * occupies and require the fold to enter it. Without this, a well-meaning
	 * "let's keep the icon clean" edit would pass every other test in this file
	 * while undoing the entire point of the rewrite.
	 */
	@Test
	public void creasesRunStraightAcrossTheItemSprite()
	{
		int[][] sizes = {{THUMB_W, THUMB_H}, {150, 200}, {195, 338}};
		for (int[] size : sizes)
		{
			int w = size[0];
			int h = size[1];
			// the rect drawFace gives a typical wide sprite
			Rectangle art = new Rectangle(w * 13 / 100, h * 12 / 100, w * 74 / 100, h * 52 / 100);
			Rectangle[] protect = CardRenderer.wearProtect(0, 0, w, h,
				topBandBottom(0, w, h), nameBandTop(0, h));
			for (int seed : SEEDS)
			{
				boolean touched = false;
				for (int[] s : ofKind(CardRenderer.wearSegments(0, 0, w, h, CardWear.CRACKED,
					seed, protect), CardRenderer.KIND_CREASE))
				{
					touched |= art.intersectsLine(s[0], s[1], s[2], s[3]);
				}
				Assert.assertTrue("no crease reaches the art at " + w + "x" + h + " seed=" + seed,
					touched);
			}
		}
	}

	/**
	 * Safe in the sense of "draws nothing" is not good enough — this is a reward,
	 * and it has to be visible on the surfaces it actually ships on: the 90px
	 * album thumbnail and the reveal card at its smallest and largest. Swept over
	 * a range of band edges so a font-metric difference on someone else's machine
	 * cannot silently empty the card.
	 */
	@Test
	public void everyStageIsVisibleOnTheSurfacesThatShipIt()
	{
		int[][] sizes = {{THUMB_W, THUMB_H}, {70, 101}, {150, 217}, {195, 338}};
		for (int[] size : sizes)
		{
			int w = size[0];
			int h = size[1];
			for (int top = h / 14 + 4 + Math.max(8, w / 11) - 4; top <= h / 5; top++)
			{
				for (int bottom = nameBandTop(0, h) - 3; bottom <= nameBandTop(0, h) + 3; bottom++)
				{
					Rectangle[] protect = CardRenderer.wearProtect(0, 0, w, h, top, bottom);
					for (CardWear wear : WORN)
					{
						String where = w + "x" + h + " top=" + top + " bottom=" + bottom
							+ " " + wear;
						Assert.assertFalse("no wear drawn at all on " + where,
							CardRenderer.wearSegments(0, 0, w, h, wear, 12345, protect).isEmpty());
					}
				}
			}
		}
	}

	/**
	 * The rule that is easy to break without noticing: two cards at the same stage
	 * carry the same WEIGHT of damage, in different places. Scratches are pinned
	 * exactly — every scratch a bracket promises lands whole, which is why
	 * wearSegments confines them to the clear band rather than letting the name
	 * label quietly eat a card's third scratch.
	 *
	 * <p>Creases are pinned to a floor instead of an equality, because a crease
	 * entering through the top edge genuinely does run under the rarity label and
	 * lose its first step or two. That is the intended look; what is not
	 * acceptable is a crease losing most of itself, so two thirds is the bar.
	 */
	@Test
	public void everyCardInABracketCarriesTheSameAmountOfWear()
	{
		int steps = CardRenderer.WEAR_STEPS;
		for (int w = 60; w <= 220; w += 5)
		{
			int h = w * 29 / 20;
			Rectangle[] protect = CardRenderer.wearProtect(0, 0, w, h,
				topBandBottom(0, w, h), nameBandTop(0, h));
			for (CardWear wear : CardWear.values())
			{
				int scratchesDue = CardRenderer.scratchCount(wear) * steps;
				int creaseFloor = CardRenderer.creaseCount(wear) * steps * 2 / 3;
				for (int seed : SEEDS)
				{
					List<int[]> segs = CardRenderer.wearSegments(0, 0, w, h, wear, seed, protect);
					String where = "w=" + w + " " + wear + " seed=" + seed;
					Assert.assertEquals("this card got a different amount of scuffing, " + where,
						scratchesDue, ofKind(segs, CardRenderer.KIND_SCRATCH).size());
					Assert.assertTrue("this card lost most of a crease, " + where,
						ofKind(segs, CardRenderer.KIND_CREASE).size() >= creaseFloor);
				}
			}
		}
	}

	/**
	 * The other half of that rule: same amount, never the same picture. Every pair
	 * of seeds has to differ somewhere, or the album is a wall of stamped copies.
	 */
	@Test
	public void noTwoCardsWearInTheSamePlaces()
	{
		Rectangle[] protect = CardRenderer.wearProtect(0, 0, THUMB_W, THUMB_H,
			topBandBottom(0, THUMB_W, THUMB_H), nameBandTop(0, THUMB_H));
		for (CardWear wear : WORN)
		{
			for (int i = 0; i < SEEDS.length; i++)
			{
				List<int[]> a = CardRenderer.wearSegments(0, 0, THUMB_W, THUMB_H, wear,
					SEEDS[i], protect);
				for (int j = i + 1; j < SEEDS.length; j++)
				{
					List<int[]> b = CardRenderer.wearSegments(0, 0, THUMB_W, THUMB_H, wear,
						SEEDS[j], protect);
					boolean differs = a.size() != b.size();
					for (int k = 0; !differs && k < a.size(); k++)
					{
						differs = !Arrays.equals(a.get(k), b.get(k));
					}
					Assert.assertTrue("seeds " + SEEDS[i] + " and " + SEEDS[j]
						+ " wear identically at " + wear, differs);
				}
			}
		}
	}

	/**
	 * The first crease of every card is forced left-to-right through the clear
	 * band between the two text strips, which is what makes the visibility test
	 * hold for EVERY seed rather than for the lucky ones. Pin it: a crease
	 * entering at the same height as the name band would be dropped whole, and a
	 * one-crease card would then show nothing folded at all.
	 */
	@Test
	public void theFirstCreaseAlwaysCrossesTheOpenMiddle()
	{
		for (int w = 40; w <= 260; w += 2)
		{
			int h = w * 29 / 20;
			Rectangle[] protect = CardRenderer.wearProtect(0, 0, w, h,
				topBandBottom(0, w, h), nameBandTop(0, h));
			int[] band = CardRenderer.wearOpenBand(protect, 0, h);
			Assert.assertTrue("the open band collapsed at w=" + w, band[1] - band[0] >= 4);
			for (int seed : SEEDS)
			{
				int left = Integer.MAX_VALUE;
				int right = Integer.MIN_VALUE;
				for (int[] s : ofKind(CardRenderer.wearSegments(0, 0, w, h, CardWear.CRACKED,
					seed, protect), CardRenderer.KIND_CREASE))
				{
					left = Math.min(left, Math.min(s[0], s[2]));
					right = Math.max(right, Math.max(s[0], s[2]));
				}
				Assert.assertTrue("the forced crease vanished at w=" + w + " seed=" + seed,
					right > left);
				Assert.assertTrue("the forced crease does not span the card at w=" + w
					+ " seed=" + seed + " (" + left + ".." + right + ")",
					right - left >= w * 3 / 4);
			}
		}
	}

	/**
	 * The open band is derived from the protected rects rather than from a second
	 * copy of drawFace's arithmetic, so it has to survive whatever shape those
	 * rects take — including the degenerate ones a hostile size could produce.
	 */
	@Test
	public void theOpenBandFallsBackRatherThanInverting()
	{
		Assert.assertArrayEquals(new int[]{0, 100}, CardRenderer.wearOpenBand(null, 0, 100));
		Assert.assertArrayEquals(new int[]{0, 100},
			CardRenderer.wearOpenBand(new Rectangle[]{null, null}, 0, 100));
		// bands that meet in the middle leave nothing: fall back to the whole card
		// and let the per-segment text check do the work
		Assert.assertArrayEquals(new int[]{0, 100}, CardRenderer.wearOpenBand(
			new Rectangle[]{new Rectangle(0, 0, 80, 50), new Rectangle(0, 50, 80, 50)}, 0, 100));
		// the normal case, and it must not care which order they arrive in
		Rectangle topBand = new Rectangle(0, 0, 80, 20);
		Rectangle nameBand = new Rectangle(0, 85, 80, 15);
		Assert.assertArrayEquals(new int[]{20, 85},
			CardRenderer.wearOpenBand(new Rectangle[]{topBand, nameBand}, 0, 100));
		Assert.assertArrayEquals(new int[]{20, 85},
			CardRenderer.wearOpenBand(new Rectangle[]{nameBand, topBand}, 0, 100));
	}

	/**
	 * Pin the actual density on the album thumbnail. "Non-empty" would still pass
	 * if a refactor thinned three creases down to one stub, and the difference
	 * between a badge you notice and one you do not is exactly this number.
	 *
	 * <p>A ceiling, not an equality: segments crossing the two text bands are
	 * dropped, and how many that is depends on which edges the seed picked.
	 */
	@Test
	public void theThumbnailDrawsMostOfEveryLineItPromises()
	{
		Rectangle[] protect = CardRenderer.wearProtect(0, 0, THUMB_W, THUMB_H,
			topBandBottom(0, THUMB_W, THUMB_H), nameBandTop(0, THUMB_H));
		for (CardWear wear : CardWear.values())
		{
			int lines = CardRenderer.creaseCount(wear) + CardRenderer.scratchCount(wear);
			int ceiling = lines * CardRenderer.WEAR_STEPS;
			for (int seed : SEEDS)
			{
				int drawn = CardRenderer.wearSegments(0, 0, THUMB_W, THUMB_H, wear, seed,
					protect).size();
				Assert.assertTrue("more segments than there are steps at " + wear,
					drawn <= ceiling);
				// over half of every promised polyline actually lands: the bands
				// clip the ends of a crease, never the bulk of it
				Assert.assertTrue("only " + drawn + " of " + ceiling + " segments at "
					+ wear + " seed=" + seed, drawn >= ceiling / 2);
			}
		}
	}

	/**
	 * A card under the first threshold must render exactly as it did before this
	 * feature existed. Not "almost nothing" — nothing, across all four passes.
	 */
	@Test
	public void aPristineCardDrawsNoWearAtAll()
	{
		Rectangle[] protect = CardRenderer.wearProtect(0, 0, THUMB_W, THUMB_H,
			topBandBottom(0, THUMB_W, THUMB_H), nameBandTop(0, THUMB_H));
		Assert.assertEquals(0, CardRenderer.creaseCount(CardWear.NONE));
		Assert.assertEquals(0, CardRenderer.scratchCount(CardWear.NONE));
		Assert.assertEquals(0, CardRenderer.wearAlpha(CardWear.NONE));
		Assert.assertEquals(0, CardRenderer.grimeAlpha(CardWear.NONE));
		Assert.assertEquals(0, CardRenderer.edgeNicks(CardWear.NONE));
		for (int seed : SEEDS)
		{
			Assert.assertTrue("a pristine card drew wear", CardRenderer.wearSegments(
				0, 0, THUMB_W, THUMB_H, CardWear.NONE, seed, protect).isEmpty());
		}
		Assert.assertTrue("a null stage drew wear", CardRenderer.wearSegments(
			0, 0, THUMB_W, THUMB_H, null, 7, protect).isEmpty());
	}

	/**
	 * The pattern is seeded from the card NAME, never from the clock, so a worn
	 * card is one physical object: it does not shimmer frame to frame, it looks
	 * the same after a restart, and the album thumbnail matches the reveal card.
	 */
	@Test
	public void theSameCardWearsTheSameWayEveryTime()
	{
		Rectangle[] protect = CardRenderer.wearProtect(0, 0, THUMB_W, THUMB_H,
			topBandBottom(0, THUMB_W, THUMB_H), nameBandTop(0, THUMB_H));
		int seed = "Abyssal whip".hashCode();
		List<int[]> first = CardRenderer.wearSegments(0, 0, THUMB_W, THUMB_H,
			CardWear.CRACKED, seed, protect);
		List<int[]> again = CardRenderer.wearSegments(0, 0, THUMB_W, THUMB_H,
			CardWear.CRACKED, seed, protect);
		Assert.assertEquals(first.size(), again.size());
		for (int i = 0; i < first.size(); i++)
		{
			Assert.assertArrayEquals("segment " + i + " moved between draws",
				first.get(i), again.get(i));
		}
	}

	/**
	 * Wear only ever accumulates, so a card that reaches a heavier stage must
	 * never show LESS than it did before. True by construction — line k's geometry
	 * depends on the seed and on k, never on the stage — and this is what pins
	 * that construction down.
	 *
	 * <p>Containment, not index equality: a heavier stage inserts its extra crease
	 * ahead of the scratches, so the shared lines sit at different offsets in the
	 * list even though every one of them is unmoved on the card.
	 */
	@Test
	public void aHeavierStageNeverShowsLessThanALighterOne()
	{
		for (int w = 60; w <= 200; w += 5)
		{
			int h = w * 29 / 20;
			Rectangle[] protect = CardRenderer.wearProtect(0, 0, w, h,
				topBandBottom(0, w, h), nameBandTop(0, h));
			for (int seed : SEEDS)
			{
				for (int i = 1; i < WORN.length; i++)
				{
					List<int[]> lighter = CardRenderer.wearSegments(0, 0, w, h, WORN[i - 1],
						seed, protect);
					List<int[]> heavier = CardRenderer.wearSegments(0, 0, w, h, WORN[i],
						seed, protect);
					String where = "w=" + w + " seed=" + seed + " " + WORN[i - 1]
						+ " -> " + WORN[i];
					Assert.assertTrue("wear went backwards at " + where,
						heavier.size() >= lighter.size());
					Set<String> after = new HashSet<>();
					for (int[] s : heavier)
					{
						after.add(Arrays.toString(s));
					}
					for (int[] s : lighter)
					{
						Assert.assertTrue("a line moved when the card aged, " + where + " "
							+ Arrays.toString(s), after.contains(Arrays.toString(s)));
					}
				}
			}
		}
	}

	/**
	 * A badge, not damage. Every layer gets denser as the record grows, but the
	 * lines never turn opaque, the grime never drowns the art, and the face never
	 * folds into origami — the card has to keep reading as a thing you earned, not
	 * a thing about to fall apart.
	 */
	@Test
	public void wearReadsAsABadgeAndNotAsDamage()
	{
		Assert.assertTrue("the top stage folds the card to pieces",
			CardRenderer.creaseCount(CardWear.SHATTERED) <= 3);
		Assert.assertTrue("scuffing should show before a fold does",
			CardRenderer.scratchCount(CardWear.HAIRLINE)
				> CardRenderer.creaseCount(CardWear.HAIRLINE));

		for (CardWear wear : CardWear.values())
		{
			Assert.assertTrue("wear paints opaque at " + wear, CardRenderer.wearAlpha(wear) < 255);
			Assert.assertTrue("negative alpha at " + wear, CardRenderer.wearAlpha(wear) >= 0);
			// grime is the layer you notice second: it must never out-shout the
			// line work. NONE is both-zero and so is skipped rather than
			// special-cased into a <=, which would let a future stage tie.
			Assert.assertTrue("grime drowns the art at " + wear,
				wear == CardWear.NONE
					|| CardRenderer.grimeAlpha(wear) < CardRenderer.wearAlpha(wear));
		}

		CardWear[] ladder = {CardWear.NONE, CardWear.HAIRLINE, CardWear.CRACKED,
			CardWear.SHATTERED};
		for (int i = 1; i < ladder.length; i++)
		{
			String step = ladder[i - 1] + " -> " + ladder[i];
			Assert.assertTrue("the lines faded at " + step,
				CardRenderer.wearAlpha(ladder[i]) > CardRenderer.wearAlpha(ladder[i - 1]));
			Assert.assertTrue("grime lifted at " + step,
				CardRenderer.grimeAlpha(ladder[i]) > CardRenderer.grimeAlpha(ladder[i - 1]));
			Assert.assertTrue("the edge healed at " + step,
				CardRenderer.edgeNicks(ladder[i]) > CardRenderer.edgeNicks(ladder[i - 1]));
			Assert.assertTrue("scratches buffed out at " + step,
				CardRenderer.scratchCount(ladder[i]) > CardRenderer.scratchCount(ladder[i - 1]));
			Assert.assertTrue("a crease unfolded at " + step,
				CardRenderer.creaseCount(ladder[i]) >= CardRenderer.creaseCount(ladder[i - 1]));
		}
	}

	/**
	 * A crease is one continuous line, not a scatter of marks. Consecutive
	 * segments must share an endpoint, because that is the difference between a
	 * fold and the hatching the old renderer drew. Gaps are legal only where the
	 * text check removed a segment.
	 */
	@Test
	public void aCreaseIsAContinuousLine()
	{
		// no protected rects, so nothing is dropped and the polyline is whole
		for (int w = 60; w <= 200; w += 5)
		{
			int h = w * 29 / 20;
			for (int seed : SEEDS)
			{
				List<int[]> creases = ofKind(CardRenderer.wearSegments(0, 0, w, h,
					CardWear.CRACKED, seed, null), CardRenderer.KIND_CREASE);
				Assert.assertEquals("a crease should be exactly one polyline",
					CardRenderer.WEAR_STEPS, creases.size());
				for (int i = 1; i < creases.size(); i++)
				{
					Assert.assertEquals("the crease broke between step " + (i - 1) + " and " + i,
						creases.get(i - 1)[2], creases.get(i)[0]);
					Assert.assertEquals("the crease broke between step " + (i - 1) + " and " + i,
						creases.get(i - 1)[3], creases.get(i)[1]);
				}
			}
		}
	}

	/**
	 * The jitter is tapered to zero at both ends, so a line arrives exactly where
	 * it was aimed and meets the frame cleanly. An untapered walk is what the old
	 * renderer drew and what read as scribble — this is the assertion that stops
	 * anyone quietly deleting the sin() term.
	 */
	@Test
	public void aLineMeetsBothEndsWhereItWasAimed()
	{
		for (int seed : SEEDS)
		{
			double[][] path = CardRenderer.wearSeamPath(10, 50, 190, 70, seed, 40);
			Assert.assertEquals(10, path[0][0], 1e-9);
			Assert.assertEquals(50, path[0][1], 1e-9);
			Assert.assertEquals(190, path[path.length - 1][0], 1e-9);
			Assert.assertEquals(70, path[path.length - 1][1], 1e-9);
			// and it genuinely wanders in between, or it is just a straight line
			double maxOff = 0;
			for (int s = 1; s < path.length - 1; s++)
			{
				double t = s / (double) (path.length - 1);
				maxOff = Math.max(maxOff, Math.abs(path[s][1] - (50 + 20 * t)));
			}
			Assert.assertTrue("the line is dead straight at seed=" + seed, maxOff > 1);
		}
	}

	/** Nothing paints outside the card, so the rounded-corner clip is a safety net, not the plan. */
	@Test
	public void wearStaysInsideTheCard()
	{
		for (int w = 40; w <= 260; w += 2)
		{
			int h = w * 29 / 20;
			int x = 17;
			int y = 23;
			Rectangle[] protect = CardRenderer.wearProtect(x, y, w, h,
				topBandBottom(y, w, h), nameBandTop(y, h));
			float reach = CardRenderer.wearInkReach(w);
			for (CardWear wear : CardWear.values())
			{
				for (int seed : SEEDS)
				{
					for (int[] s : CardRenderer.wearSegments(x, y, w, h, wear, seed, protect))
					{
						Assert.assertTrue("wear escaped the card at w=" + w,
							Math.min(s[0], s[2]) - reach >= x
								&& Math.max(s[0], s[2]) + reach <= x + w
								&& Math.min(s[1], s[3]) - reach >= y
								&& Math.max(s[1], s[3]) + reach <= y + h);
					}
				}
			}
		}
	}

	/**
	 * wearInkReach is the budget every clearance test above measures against, so
	 * it has to cover the widest thing drawWearLines actually paints. Two passes
	 * compete for it: the crease's soft valley, stroked at exactly twice the reach
	 * and centred, and the lit ridge, offset a full stroke to one side and then
	 * half of its own width beyond that. Both land on the reach exactly — there is
	 * no slack here, which is why the ridge is drawn through Line2D rather than
	 * being rounded to whole pixels first.
	 */
	@Test
	public void theInkReachCoversEveryPassThatLands()
	{
		for (int w = 1; w <= 2000; w++)
		{
			float line = CardRenderer.wearStroke(w);
			float reach = CardRenderer.wearInkReach(w);
			Assert.assertTrue("the valley is wider than the reach at w=" + w, reach * 2f >= line);
			Assert.assertTrue("the ridge sits outside the reach at w=" + w,
				reach + 1e-4f >= line + line * 0.7f / 2f);
			Assert.assertTrue("the crease vanished at w=" + w, line >= 1.6f);
		}
	}
}

package com.gachaman.ui;

import com.gachaman.model.*;
import org.junit.*;

/**
 * Pins CardRenderer's WEAR_TUNING table against the five switch statements it
 * replaced.
 *
 * <p>Every number here is a literal copied from the switches as they stood, not
 * a re-derivation of the table: the whole value of this test is that it fails if
 * a row is ever reordered or a column shifted, and a test that computed its
 * expectations from the same table would pass through exactly that mistake.
 *
 * <p>Two things the switches gave for free and the table does not, both covered
 * below. A switch fell through to {@code default: return 0} for any constant it
 * did not name, so a CardWear added later simply behaved like NONE; an
 * ordinal-indexed table throws instead. {@link #everyStageHasARow} is what turns
 * that from a crash mid-reveal into a red build, and it needs no maintenance —
 * it walks {@code values()}, so a new constant fails it the day it is added.
 */
public class WearTuningTest
{
	/**
	 * NONE is the row that used to be the {@code default:} arm of all five
	 * switches, so it is the one that proves the table did not shift by a row.
	 */
	@Test
	public void pristineDrawsNothing()
	{
		Assert.assertEquals(0, CardRenderer.creaseCount(CardWear.NONE));
		Assert.assertEquals(0, CardRenderer.scratchCount(CardWear.NONE));
		Assert.assertEquals(0, CardRenderer.wearAlpha(CardWear.NONE));
		Assert.assertEquals(0, CardRenderer.grimeAlpha(CardWear.NONE));
		Assert.assertEquals(0, CardRenderer.edgeNicks(CardWear.NONE));
	}

	/** HAIRLINE: scuffing has started, nothing has folded yet. */
	@Test
	public void hairlineNumbers()
	{
		Assert.assertEquals(0, CardRenderer.creaseCount(CardWear.HAIRLINE));
		Assert.assertEquals(6, CardRenderer.scratchCount(CardWear.HAIRLINE));
		Assert.assertEquals(96, CardRenderer.wearAlpha(CardWear.HAIRLINE));
		Assert.assertEquals(34, CardRenderer.grimeAlpha(CardWear.HAIRLINE));
		Assert.assertEquals(20, CardRenderer.edgeNicks(CardWear.HAIRLINE));
	}

	/** CRACKED: one fold. */
	@Test
	public void crackedNumbers()
	{
		Assert.assertEquals(1, CardRenderer.creaseCount(CardWear.CRACKED));
		Assert.assertEquals(10, CardRenderer.scratchCount(CardWear.CRACKED));
		Assert.assertEquals(150, CardRenderer.wearAlpha(CardWear.CRACKED));
		Assert.assertEquals(62, CardRenderer.grimeAlpha(CardWear.CRACKED));
		Assert.assertEquals(38, CardRenderer.edgeNicks(CardWear.CRACKED));
	}

	/** SHATTERED: two folds, and the heaviest of everything else. */
	@Test
	public void shatteredNumbers()
	{
		Assert.assertEquals(2, CardRenderer.creaseCount(CardWear.SHATTERED));
		Assert.assertEquals(16, CardRenderer.scratchCount(CardWear.SHATTERED));
		Assert.assertEquals(200, CardRenderer.wearAlpha(CardWear.SHATTERED));
		Assert.assertEquals(92, CardRenderer.grimeAlpha(CardWear.SHATTERED));
		Assert.assertEquals(60, CardRenderer.edgeNicks(CardWear.SHATTERED));
	}

	/**
	 * The invariant the table costs and the switches did not: one row per
	 * constant. A new CardWear with no row would throw
	 * ArrayIndexOutOfBoundsException out of every accessor, which is a crash in
	 * the middle of drawing a card rather than a wrong-looking card.
	 */
	@Test
	public void everyStageHasARow()
	{
		for (CardWear wear : CardWear.values())
		{
			String where = "no WEAR_TUNING row for " + wear;
			try
			{
				CardRenderer.creaseCount(wear);
				CardRenderer.scratchCount(wear);
				CardRenderer.wearAlpha(wear);
				CardRenderer.grimeAlpha(wear);
				CardRenderer.edgeNicks(wear);
			}
			catch (ArrayIndexOutOfBoundsException e)
			{
				Assert.fail(where);
			}
		}
	}

	/**
	 * The stage has to be legible at a glance, which means the damage can only
	 * ever get heavier as the Service Record grows. Creases are the one column
	 * allowed to sit still (HAIRLINE has none, by design — a scuffed card has not
	 * been folded), so it is tested non-decreasing while the rest are strictly
	 * increasing from HAIRLINE on.
	 */
	@Test
	public void everyColumnClimbsWithTheStage()
	{
		CardWear[] stages = CardWear.values();
		for (int i = 1; i < stages.length; i++)
		{
			CardWear prev = stages[i - 1];
			CardWear next = stages[i];
			String where = prev + " -> " + next;
			Assert.assertTrue("creases went backwards at " + where,
				CardRenderer.creaseCount(next) >= CardRenderer.creaseCount(prev));
			Assert.assertTrue("scratches went backwards at " + where,
				CardRenderer.scratchCount(next) > CardRenderer.scratchCount(prev));
			Assert.assertTrue("line alpha went backwards at " + where,
				CardRenderer.wearAlpha(next) > CardRenderer.wearAlpha(prev));
			Assert.assertTrue("grime went backwards at " + where,
				CardRenderer.grimeAlpha(next) > CardRenderer.grimeAlpha(prev));
			Assert.assertTrue("edge nicks went backwards at " + where,
				CardRenderer.edgeNicks(next) > CardRenderer.edgeNicks(prev));
		}
	}

	/** Never opaque: wear is a layer over the print, not a replacement for it. */
	@Test
	public void opacitiesStayUnderFull()
	{
		for (CardWear wear : CardWear.values())
		{
			Assert.assertTrue("line alpha is opaque at " + wear,
				CardRenderer.wearAlpha(wear) < 255);
			Assert.assertTrue("grime is opaque at " + wear,
				CardRenderer.grimeAlpha(wear) < 255);
			Assert.assertTrue("grime outweighs the line work at " + wear,
				CardRenderer.grimeAlpha(wear) <= CardRenderer.wearAlpha(wear));
		}
	}
}

package com.gachaman;

import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.stream.*;
import org.junit.*;

/**
 * Byte-level guards on the main source tree itself.
 *
 * <p>The one this exists for: a raw NUL (0x00) written directly into a string
 * literal instead of the {@code \0} escape. Both compile to the identical
 * character, so nothing at runtime can tell them apart — but the raw byte makes
 * {@code file} classify the source as "data", and makes grep and ripgrep treat
 * it as BINARY and skip it entirely unless invoked with {@code -a}. One such
 * byte in {@code OverviewTab.java} silently hid ~900 lines of live UI from every
 * repo-wide search, which very nearly got the party-roll proposal cards
 * (proposalGroups, PendingProposal, joinProposal, declineProposal) recommended
 * for deletion as dead code.
 *
 * <p>That failure mode is invisible to the compiler, invisible to the Plugin Hub
 * bot, and invisible in a diff. A test is the only thing that can see it, and
 * tests cost nothing here — the bot counts only src/main/java.
 */
public class SourceHygieneTest
{
	/**
	 * The main source root, found by walking up from the test working directory.
	 *
	 * <p>Gradle runs tests with the project directory as CWD, but a run launched
	 * from elsewhere (an IDE pointed at a module, a nested invocation) can start
	 * a level or two down, so this climbs rather than assuming. Returns null when
	 * it cannot be found, which callers MUST treat as a failure and never as a
	 * pass — a source scan that walks nothing is the classic silent green.
	 */
	public static Path sourceRoot()
	{
		Path dir = Paths.get("").toAbsolutePath();
		for (int up = 0; dir != null && up < 5; up++)
		{
			Path candidate = dir.resolve("src").resolve("main").resolve("java");
			if (Files.isDirectory(candidate))
			{
				return candidate;
			}
			dir = dir.getParent();
		}
		return null;
	}

	@Test
	public void noSourceFileCarriesARawNulByte() throws IOException
	{
		Path root = sourceRoot();
		Assert.assertNotNull("could not locate src/main/java from "
			+ Paths.get("").toAbsolutePath(), root);

		List<String> offenders = new ArrayList<>();
		int scanned = 0;
		try (Stream<Path> tree = Files.walk(root))
		{
			for (Path file : tree.filter(p -> p.toString().endsWith(".java"))
				.collect(Collectors.toList()))
			{
				scanned++;
				for (byte b : Files.readAllBytes(file))
				{
					if (b == 0)
					{
						offenders.add(root.relativize(file).toString());
						break;
					}
				}
			}
		}

		// the scan finding nothing is only good news if it actually looked at
		// something — an empty walk would otherwise pass forever
		Assert.assertTrue("scanned no .java files under " + root, scanned > 0);
		Assert.assertEquals("raw NUL byte in source — write it as the escape \\0"
			+ " instead, or grep/ripgrep will skip these files as binary",
			Collections.emptyList(), offenders);
	}
}

package com.gachaman.party;

import org.junit.*;

/**
 * The display name the Party page and its chat lines put on a remote member.
 *
 * Every value here is self-reported over the party channel, so the name is the
 * one field a hostile or merely broken client can point anywhere: absent, blank,
 * the literal "&lt;unknown&gt;" RuneLite hands out before a member's name has
 * arrived, or long enough to widen the whole tab. The tab has no horizontal
 * scrollbar, so an over-long name does not ellipsise — it clips every row's
 * right edge instead.
 */
public class PartyPresenceNameTest
{
	@Test
	public void anAbsentNameFallsBackToAPhrase()
	{
		// null and blank both mean "the name has not arrived yet", and both get
		// a phrase that reads correctly in the chat lines that interpolate it
		// ("A party member accepted the contract")
		Assert.assertEquals("A party member", PartyPresenceService.memberName(null));
		Assert.assertEquals("A party member", PartyPresenceService.memberName(""));
		Assert.assertEquals("A party member", PartyPresenceService.memberName("   "));
		Assert.assertEquals("A party member", PartyPresenceService.memberName("\t\n "));
	}

	@Test
	public void runelitesPlaceholderIsNotPrintedRaw()
	{
		// the party plugin uses this literal before a member's name resolves;
		// printing it would also hand angle brackets to the chat tag parser,
		// which eats everything between them
		Assert.assertEquals("A party member", PartyPresenceService.memberName("<unknown>"));
		Assert.assertEquals("A party member", PartyPresenceService.memberName("  <unknown>  "));
	}

	@Test
	public void anOrdinaryNameSurvivesIntact()
	{
		Assert.assertEquals("Zezima", PartyPresenceService.memberName("Zezima"));
		// RSN space, and the surrounding whitespace the wire may carry
		Assert.assertEquals("Iron Talka", PartyPresenceService.memberName("  Iron Talka  "));
	}

	@Test
	public void anOverlongNameIsCutToTheColumnBudget()
	{
		// a real RSN is at most 12 characters; anything past the cap is a
		// malformed or hostile broadcast, and the cap is what keeps it from
		// widening a tab that cannot scroll sideways
		String flood = repeat("x", 400);
		String clipped = PartyPresenceService.memberName(flood);
		Assert.assertEquals(40, clipped.length());
		Assert.assertEquals(repeat("x", 40), clipped);
	}

	@Test
	public void aNameExactlyAtTheCapIsNotTouched()
	{
		String exact = repeat("y", 40);
		Assert.assertEquals(exact, PartyPresenceService.memberName(exact));
		Assert.assertEquals(repeat("y", 40), PartyPresenceService.memberName(repeat("y", 41)));
	}

	@Test
	public void everyResultIsUsableAsASentenceSubject()
	{
		for (String candidate : new String[]{null, "", "   ", "<unknown>", "Zezima",
			repeat("z", 400)})
		{
			String name = PartyPresenceService.memberName(candidate);
			Assert.assertNotNull(name);
			Assert.assertFalse("blank name from " + candidate, name.trim().isEmpty());
			Assert.assertTrue("too long from " + candidate, name.length() <= 40);
		}
	}

	/** Java 8 has no String.repeat. */
	private static String repeat(String unit, int times)
	{
		StringBuilder builder = new StringBuilder(unit.length() * times);
		for (int i = 0; i < times; i++)
		{
			builder.append(unit);
		}
		return builder.toString();
	}
}

package com.gachaman.party;

import com.gachaman.*;
import org.junit.*;

/**
 * The presence broadcast's pure rules: when we speak, when we stop believing
 * someone else, and what counts as a change worth speaking about. Every
 * assertion pins a BOUNDARY rather than a constant's value, so retuning the
 * heartbeat does not rewrite the suite.
 */
public class PartyPresenceClockTest
{
	@Test
	public void firstBroadcastAlwaysSends()
	{
		Assert.assertTrue("a client that has never announced must not wait out a heartbeat",
			PartyPresenceService.shouldBroadcast(0, 0, "x", null));
	}

	@Test
	public void anyChangeBroadcastsImmediately()
	{
		Assert.assertTrue(PartyPresenceService.shouldBroadcast(101, 100, "a", "b"));
	}

	@Test
	public void unchangedPresenceWaitsForTheExactHeartbeat()
	{
		int last = 100;
		Assert.assertFalse(PartyPresenceService.shouldBroadcast(
			last + Tuning.PARTY_PRESENCE_HEARTBEAT_TICKS - 1, last, "a", "a"));
		Assert.assertTrue(PartyPresenceService.shouldBroadcast(
			last + Tuning.PARTY_PRESENCE_HEARTBEAT_TICKS, last, "a", "a"));
	}

	@Test
	public void aBackwardsTickCounterReAnnounces()
	{
		// a relog or world hop restarts getTickCount(): without this we would
		// look silent to the whole party for as long as the old count was high
		Assert.assertTrue(PartyPresenceService.shouldBroadcast(5, 4000, "a", "a"));
	}

	@Test
	public void signatureSeparatorPreventsAdjacentFieldCollision()
	{
		// the exact bug plain concatenation causes: a real change swallowed by
		// the heartbeat because two different lines flatten to one string
		Assert.assertNotEquals(
			PartyPresenceService.signature("MELEE", 70, "Goblin", 1, 12, false, null, false, null),
			PartyPresenceService.signature("MELEE", 70, "Goblin1", 1, 2, false, null, false, null));
	}

	@Test
	public void nullStyleAndNullTaskAreStableAndDistinct()
	{
		String none = PartyPresenceService.signature(null, 3, null, 0, 0, false, null, false, null);
		Assert.assertEquals(none,
			PartyPresenceService.signature(null, 3, null, 0, 0, false, null, false, null));
		Assert.assertNotEquals(none,
			PartyPresenceService.signature("MELEE", 3, null, 0, 0, false, null, false, null));
		Assert.assertNotEquals(none,
			PartyPresenceService.signature(null, 3, "Goblin", 0, 0, false, null, false, null));
		Assert.assertNotEquals(none,
			PartyPresenceService.signature(null, 3, null, 0, 0, true, null, false, null));
	}

	@Test
	public void identityEligibilityAndContractAllMoveTheSignature()
	{
		// every one of these is DRAWN, so a change in any of them has to reach
		// the party: an unsent key loses a patron pip, an unsent flag leaves a
		// member looking eligible when they are not, and an unsent contract id
		// silently merges two members into one block
		String none = PartyPresenceService.signature(null, 3, null, 0, 0, false, null, false, null);
		Assert.assertNotEquals(none, PartyPresenceService.signature(
			null, 3, null, 0, 0, false, "00112233445566aa", false, null));
		Assert.assertNotEquals(none,
			PartyPresenceService.signature(null, 3, null, 0, 0, false, null, true, null));
		Assert.assertNotEquals(none,
			PartyPresenceService.signature(null, 3, null, 0, 0, false, null, false, 0L));
		// and a claimed id of ZERO is a real claim, not the same as no claim:
		// proposal ids come from nextLong(), so zero is a legal one
		Assert.assertNotEquals(
			PartyPresenceService.signature(null, 3, null, 0, 0, false, null, false, 0L),
			PartyPresenceService.signature(null, 3, null, 0, 0, false, null, false, null));
	}

	@Test
	public void stalenessBoundary()
	{
		int heard = 100;
		Assert.assertFalse(PartyPresenceService.isStale(
			heard + Tuning.PARTY_PRESENCE_STALE_TICKS - 1, heard));
		Assert.assertTrue(PartyPresenceService.isStale(
			heard + Tuning.PARTY_PRESENCE_STALE_TICKS, heard));
	}

	@Test
	public void aBackwardsClockForgivesTheSender()
	{
		// deliberate asymmetry with shouldBroadcast: OUR clock restarting is our
		// problem to re-announce, not grounds to grey out every other member
		Assert.assertFalse(PartyPresenceService.isStale(5, 4000));
	}

	@Test
	public void progressFractionNeverDividesByZeroAndClamps()
	{
		Assert.assertEquals(0, PartyPresenceService.progressFraction(3, 0), 0.0);
		Assert.assertEquals(0, PartyPresenceService.progressFraction(0, 10), 0.0);
		Assert.assertEquals(1, PartyPresenceService.progressFraction(20, 10), 0.0);
		Assert.assertEquals(0, PartyPresenceService.progressFraction(-4, 10), 0.0);
		Assert.assertEquals(0.5, PartyPresenceService.progressFraction(5, 10), 1e-9);
	}

	@Test
	public void clipBoundsARemoteName()
	{
		Assert.assertNull(PartyPresenceService.clip(null, 40));
		Assert.assertNull("whitespace is not a name", PartyPresenceService.clip("   ", 40));
		Assert.assertEquals("Goblin", PartyPresenceService.clip("Goblin", 40));
		Assert.assertEquals("Goblin", PartyPresenceService.clip("  Goblin  ", 40));

		StringBuilder huge = new StringBuilder();
		for (int i = 0; i < 500; i++)
		{
			huge.append('x');
		}
		String clipped = PartyPresenceService.clip(huge.toString(), 40);
		Assert.assertNotNull(clipped);
		Assert.assertEquals("a hostile client must not be able to blow up the row layout",
			40, clipped.length());
	}
}

package com.gachaman.party;

import org.junit.*;

/**
 * The tick-to-seconds conversion behind every countdown the party UI shows.
 *
 * One function feeds the proposal cards, the "party roll pending" line and the
 * vote clock, so a wrong constant here is wrong on every screen at once. Game
 * ticks are 0.6s: 5 ticks make 3 seconds.
 */
public class PartyCountdownTest
{
	@Test
	public void ticksConvertAtSixHundredMilliseconds()
	{
		Assert.assertEquals(0, PartyRollService.ticksToSeconds(0));
		Assert.assertEquals(3, PartyRollService.ticksToSeconds(5));
		Assert.assertEquals(6, PartyRollService.ticksToSeconds(10));
		Assert.assertEquals(60, PartyRollService.ticksToSeconds(100));
	}

	@Test
	public void aPartTickRoundsDownRatherThanUp()
	{
		// a countdown that rounds up says "1s left" when there is none, and the
		// deadline is real: the vote stops counting
		Assert.assertEquals(0, PartyRollService.ticksToSeconds(1));
		Assert.assertEquals(1, PartyRollService.ticksToSeconds(2));
		Assert.assertEquals(2, PartyRollService.ticksToSeconds(4));
	}

	@Test
	public void anExpiredClockNeverReadsNegative()
	{
		// the caller subtracts a tick count that can overshoot the deadline
		// between the sweep and the repaint; "-2s left" is not a countdown
		Assert.assertEquals(0, PartyRollService.ticksToSeconds(-1));
		Assert.assertEquals(0, PartyRollService.ticksToSeconds(-100));
	}

	@Test
	public void theCountdownNeverRunsBackwards()
	{
		int previous = Integer.MAX_VALUE;
		for (int ticks = 200; ticks >= 0; ticks--)
		{
			int seconds = PartyRollService.ticksToSeconds(ticks);
			Assert.assertTrue("rose at " + ticks, seconds <= previous);
			previous = seconds;
		}
		Assert.assertEquals(0, previous);
	}
}

package com.gachaman.party;

import org.junit.*;

/**
 * The one-party-at-a-time rule.
 *
 * A player can be offered several party rolls at once — several members of one
 * RuneLite party can each propose — but can only ever be in one. The moment
 * they join one, or host one, or sign a contract, the rest stop being offers
 * and start being noise they could accidentally click.
 *
 * This is the whole of that rule, isolated from the Client so it can be stated
 * as a table rather than reasoned about through a running party.
 */
public class PartyProposalVisibilityTest
{
	@Test
	public void anUncommittedPlayerIsShownOffers()
	{
		Assert.assertFalse(PartyRollService.spokenFor(false, false, false));
	}

	@Test
	public void joiningAProposalHidesTheRest()
	{
		// proposalLive is set by joining OR by proposing, so this one flag covers
		// both "I answered someone" and "I am the host" — a host must not be
		// shopping through other people's rolls while their own collects answers
		Assert.assertTrue(PartyRollService.spokenFor(true, false, false));
	}

	@Test
	public void aRunningVoteHidesTheRest()
	{
		// between the roll and the contract there is no proposal live, but the
		// player is very much committed — offers must not reappear in the gap
		Assert.assertTrue(PartyRollService.spokenFor(false, true, false));
	}

	@Test
	public void anActiveContractHidesTheRest()
	{
		Assert.assertTrue(PartyRollService.spokenFor(false, false, true));
	}

	@Test
	public void anyCommitmentIsEnoughOnItsOwn()
	{
		// no combination un-commits a player: the rule is an OR, and a test that
		// only ever sets one flag would pass just as well against an AND
		for (int mask = 1; mask < 8; mask++)
		{
			boolean proposal = (mask & 1) != 0;
			boolean voting = (mask & 2) != 0;
			boolean task = (mask & 4) != 0;
			Assert.assertTrue("mask " + mask,
				PartyRollService.spokenFor(proposal, voting, task));
		}
	}
}

package com.gachaman.party;

import org.junit.*;

/**
 * The vote shot clock's deadline test, in isolation. Statics only —
 * constructing PartyRollService would need a Client and a PartyService, and
 * everything around this predicate (voteLocal, evaluateVotes, cancelVoting,
 * onGameTick) reads client.getTickCount() or the party roster.
 *
 * Note what this does NOT prove: convergence. Two clients agreeing on when a
 * tick counts as expired says nothing about them agreeing on the DEADLINE —
 * that comes from the host owning the clock and broadcasting the cancel, and
 * only a two-client run can check it.
 */
public class PartyRollVoteClockTest
{
	@Test
	public void voteExpiryBoundary()
	{
		Assert.assertFalse("one tick short is still live",
			PartyRollService.voteExpired(199, 200));
		Assert.assertTrue("the deadline tick itself expires",
			PartyRollService.voteExpired(200, 200));
		Assert.assertTrue("and every tick after it",
			PartyRollService.voteExpired(201, 200));
	}

	@Test
	public void aMissedDeadlineNeverReadsAsLive()
	{
