	}
}

package com.gachaman.party;

import java.util.*;
import org.junit.*;

/**
 * Who is actually IN a party roll — and therefore who may be dealt a board,
 * who counts toward the start rule, and who is remembered as a partner.
 *
 * Three defects came out of that one question being answered three different
 * ways in three different places, so all three answers are pinned here:
 *
 * <ul>
 * <li><b>partOfRoll</b> — the start MESSAGE path turned away a client the
 * participant list omitted, but the host's own path did not, so a host who
 * declined its own proposal was dealt the full board it had just refused.</li>
 * <li><b>agreedAmong</b> — the Start Roll Now button counted every AGREE it
 * had ever heard while the rule behind the button counted only members still
 * on the party roster, so the button could promise a roll the rule refused and
 * then do nothing at all, with no chat line to say why.</li>
 * <li><b>rememberPartners</b> — joining a proposal resets the key cache, and
 * the host's account key rides on their propose message alone (a host never
 * answers its own proposal), so the Patron's Mark silently skipped the one
 * partner every joiner is guaranteed to have.</li>
 * </ul>
 *
 * All three are statics for the usual reason: the paths around them need a
 * Client, a ClientThread and a PartyService, and the rules themselves need
 * nothing.
 */
public class PartyRollRosterTest
{
	/** A valid 16-hex-character account key, as AccountKey.normalize demands. */
	private static final String KEY_HOST = "0123456789abcdef";
	private static final String KEY_MEMBER = "fedcba9876543210";

	private static PartyRollService.Stance stance(int response, String accountKey)
	{
		return new PartyRollService.Stance(response, 1L, true, 70, 55, "MELEE",
			PartyRollService.ROLL_PROTOCOL, Collections.emptyList(), accountKey);
	}

	private static Map<Long, PartyRollService.Stance> answers(long id,
		PartyRollService.Stance stance)
	{
		Map<Long, PartyRollService.Stance> map = new HashMap<>();
		map.put(id, stance);
		return map;
	}

	private static Set<Long> roster(long... ids)
	{
		Set<Long> set = new HashSet<>();
		for (long id : ids)
		{
			set.add(id);
		}
		return set;
	}

	// =====================================================================
	// partOfRoll — may this client deal itself the board?
	// =====================================================================

	@Test
	public void aListedMemberIsOnTheRoll()
	{
		Assert.assertTrue(PartyRollService.partOfRoll(Arrays.asList(1L, 2L, 3L), 2L));
	}

	@Test
	public void aHostWhoDeclinedItsOwnProposalIsNotOnTheRoll()
	{
		// evaluateProposal drops a DECLINE stance from the agreed list but still
		// recognises the client as the proposer, so it broadcast the start and
		// rolled locally — a full board, ceremony and all, for the one member who
		// had just said no, and four personal offers they then had to decide
		// because a roll cannot be handed back
		Assert.assertFalse(PartyRollService.partOfRoll(Arrays.asList(2L, 3L), 1L));
	}

	@Test
	public void anAbsentListAndAnAbsentMemberBothMeanNo()
	{
		Assert.assertFalse(PartyRollService.partOfRoll(null, 1L));
		Assert.assertFalse(PartyRollService.partOfRoll(Collections.emptyList(), 1L));
		// 0 is what safeMemberIdOrZero() returns when there is no local member;
		// it must never be read as membership of somebody else's roll
		Assert.assertFalse(PartyRollService.partOfRoll(Arrays.asList(1L, 2L), 0L));
	}

	@Test
	public void realSizedMemberIdsStillMatch()
	{
		// member ids come from nextLong(), far outside Long's boxing cache, so
		// this pins that membership is equals() and never reference identity —
		// the failure mode would be a party that silently deals nobody a board
		long id = 7_403_912_884_512_003_991L;
		Assert.assertTrue(PartyRollService.partOfRoll(Arrays.asList(id, 5L), id));
		Assert.assertFalse(PartyRollService.partOfRoll(Arrays.asList(id, 5L), id + 1));
	}

	// =====================================================================
	// agreedAmong — what the host's start button is allowed to promise
	// =====================================================================

	@Test
	public void onlyAgreementsAreCounted()
	{
		Map<Long, PartyRollService.Stance> stances = new HashMap<>();
		stances.put(1L, stance(PartyRollResponseMessage.AGREE, null));
		stances.put(2L, stance(PartyRollResponseMessage.DECLINE, null));
		stances.put(3L, stance(PartyRollResponseMessage.BUSY, null));

		Assert.assertEquals(1, PartyRollService.agreedAmong(stances, roster(1L, 2L, 3L)));
	}

	@Test
	public void anAgreeingMemberWhoLeftThePartyStopsCounting()
	{
		// the exact shape of the silent button: two agreements heard, one of them
		// from a partner who has since disconnected. evaluateProposal walks the
		// ROSTER, so it saw one; the button walked the stances, so it said two,
		// and pressing it hit neither the deadline nor the all-answered branch
		// and returned with no message and no state change
		Map<Long, PartyRollService.Stance> stances = new HashMap<>();
		stances.put(1L, stance(PartyRollResponseMessage.AGREE, null));
		stances.put(2L, stance(PartyRollResponseMessage.AGREE, null));

		Assert.assertEquals(2, PartyRollService.agreedAmong(stances, roster(1L, 2L)));
		Assert.assertEquals("the departed member's agreement cannot start a roll", 1,
			PartyRollService.agreedAmong(stances, roster(1L)));
		// and the number the button prints is now the number the rule tests
		Assert.assertTrue(PartyRollService.agreedAmong(stances, roster(1L)) < 2);
	}

	@Test
	public void anUnreadableRosterCountsNobody()
	{
		// rosterIds() answers with an empty set when PartyService throws, which is
		// also when evaluateProposal bails out entirely — so the button must not
		// keep offering a start that cannot happen
		Map<Long, PartyRollService.Stance> stances =
			answers(1L, stance(PartyRollResponseMessage.AGREE, null));
		Assert.assertEquals(0, PartyRollService.agreedAmong(stances, roster()));
	}

	@Test
	public void nothingHeardIsNobodyAgreed()
	{
		Assert.assertEquals(0, PartyRollService.agreedAmong(
			new HashMap<>(), roster(1L, 2L)));
	}

	// =====================================================================
	// rememberPartners — the key that survives into the Patron's Mark
	// =====================================================================

	@Test
	public void aJoinedProposalInheritsTheHostsKey()
	{
		// joinProposal resets the session, which wipes the key cache the propose
		// message had just filled. Nothing later re-sends it — Start carries
		// participant ids, Vote an offer index, Resolve a roster, and a host
		// never sends a Response to its own proposal — so without this the host
		// was dropped at creditPatrons' "no identity, no mark" guard, every time
		Map<Long, String> cache = new HashMap<>();
		PartyRollService.rememberPartners(cache,
			answers(9L, stance(PartyRollResponseMessage.AGREE, KEY_HOST)));

		Assert.assertEquals(KEY_HOST, cache.get(9L));
	}

	@Test
	public void everyHeardAnswerIsSeededNotJustTheHosts()
	{
		// answers that arrived while the card was still only an offer are wiped
		// by the same reset, and a member who has already answered will not
		// answer again either
		Map<Long, PartyRollService.Stance> heard = new HashMap<>();
		heard.put(9L, stance(PartyRollResponseMessage.AGREE, KEY_HOST));
		heard.put(4L, stance(PartyRollResponseMessage.AGREE, KEY_MEMBER));

		Map<Long, String> cache = new HashMap<>();
		PartyRollService.rememberPartners(cache, heard);

		Assert.assertEquals(2, cache.size());
		Assert.assertEquals(KEY_MEMBER, cache.get(4L));
	}

	@Test
	public void aClaimThatIsNotAKeyLeavesNoEntryAtAll()
	{
		// the value becomes a KEY in a persisted ledger, so a malformed claim
		// must leave the member unknown rather than store the claim
		Map<Long, String> cache = new HashMap<>();
		PartyRollService.rememberPartners(cache,
			answers(1L, stance(PartyRollResponseMessage.AGREE, null)));
		PartyRollService.rememberPartners(cache,
			answers(2L, stance(PartyRollResponseMessage.AGREE, "")));
		PartyRollService.rememberPartners(cache,
			answers(3L, stance(PartyRollResponseMessage.AGREE, "not-a-key")));
		PartyRollService.rememberPartners(cache,
			answers(4L, stance(PartyRollResponseMessage.AGREE, KEY_HOST + KEY_MEMBER)));

		Assert.assertTrue(cache.toString(), cache.isEmpty());
	}

	@Test
	public void anInheritedKeyIsStoredNormalised()
	{
		// the ledger keys on this string, so one account arriving in two cases
		// would otherwise earn two rows and never reach a tier
		Map<Long, String> cache = new HashMap<>();
		PartyRollService.rememberPartners(cache, answers(9L,
			stance(PartyRollResponseMessage.AGREE, "  " + KEY_HOST.toUpperCase(Locale.ROOT) + " ")));

		Assert.assertEquals(KEY_HOST, cache.get(9L));
	}

	@Test
	public void aLaterAnswerReplacesAnEarlierKeyForTheSameMember()
	{
		// the same shape rememberPartner has always had for single answers: the
		// most recent claim wins, so a member who logged in between messages is
		// not stuck as unknown
		Map<Long, String> cache = new HashMap<>();
		cache.put(9L, KEY_MEMBER);
		PartyRollService.rememberPartners(cache,
			answers(9L, stance(PartyRollResponseMessage.AGREE, KEY_HOST)));

		Assert.assertEquals(KEY_HOST, cache.get(9L));
	}
}

package com.gachaman.party;

import com.gachaman.model.*;
import com.google.gson.*;
import org.junit.*;

/**
 * The presence broadcast is the ONE channel every later party feature extends,
 * so both directions of version skew have to be safe: an older client's omitted
 * field must read as "not claimed" rather than fabricate a value, and a newer
 * client's extra field must not break the message for anyone.
 */
public class PartyPresenceWireTest
{
	private final Gson gson = new Gson();

	@Test
	public void olderClientPresenceFabricatesNothing()
	{
		GachaPresenceMessage msg = gson.fromJson("{\"combatLevel\":70}",
			GachaPresenceMessage.class);
		Assert.assertNull("an omitted style must not become MELEE", msg.getAllowedStyle());
		Assert.assertNull("no contract, not a phantom one", msg.getActiveTaskName());
		Assert.assertEquals(0, msg.getKillsRequired());
		Assert.assertEquals(0, msg.getKillsDone());
		Assert.assertFalse(msg.isTainted());
		Assert.assertEquals(70, msg.getCombatLevel());
		Assert.assertNull("an omitted key is an unknown account, not a blank one",
			msg.getAccountKey());
		Assert.assertFalse("an omitted flag reads as 'nothing pending', which is what"
			+ " a client that never had a board is", msg.isUndecidedOffers());
		Assert.assertNull("a BOXED id, so an omission cannot read as a real claim of 0",
			msg.getPartyContractId());
	}

	@Test
	public void styleTravelsAsANameNotAnOrdinal()
	{
		GachaPresenceMessage magic = gson.fromJson(gson.toJson(
			new GachaPresenceMessage("MAGIC", 82, "Zulrah", 3, 25, false, null, false, null)),
			GachaPresenceMessage.class);
		Assert.assertEquals("MAGIC", magic.getAllowedStyle());
		Assert.assertEquals(AttackStyle.MAGIC, PartyRollService.parseStyle(magic.getAllowedStyle()));
		Assert.assertEquals("Zulrah", magic.getActiveTaskName());
		Assert.assertEquals(3, magic.getKillsDone());
		Assert.assertEquals(25, magic.getKillsRequired());

		GachaPresenceMessage future = gson.fromJson("{\"allowedStyle\":\"SHADOW\"}",
			GachaPresenceMessage.class);
		Assert.assertNull("a fourth style must not crash an old client",
			PartyRollService.parseStyle(future.getAllowedStyle()));
	}

	@Test
	public void aNewerClientsExtraFieldIsIgnored()
	{
		// proves the documented badge seam (add a FIELD here, never a second
		// message class) is safe in both directions
		GachaPresenceMessage msg = gson.fromJson("{\"combatLevel\":3,\"patronMark\":true}",
			GachaPresenceMessage.class);
		Assert.assertEquals(3, msg.getCombatLevel());
	}

	@Test
	public void memberIdIsNotOnTheWire()
	{
		String json = gson.toJson(
			new GachaPresenceMessage("RANGED", 60, null, 0, 0, true, null, false, null));
		Assert.assertFalse("PartyMemberMessage.memberId is transient and stamped on receipt,"
			+ " so a sender-supplied id could never be trusted", json.contains("memberId"));
		Assert.assertTrue(json.contains("RANGED"));
	}

	@Test
	public void taintTravelsAsAFlag()
	{
		GachaPresenceMessage clean = gson.fromJson(gson.toJson(
			new GachaPresenceMessage(null, 3, null, 0, 0, false, null, false, null)),
			GachaPresenceMessage.class);
		Assert.assertFalse(clean.isTainted());
		GachaPresenceMessage dirty = gson.fromJson(gson.toJson(
			new GachaPresenceMessage(null, 3, null, 0, 0, true, null, false, null)),
			GachaPresenceMessage.class);
		Assert.assertTrue(dirty.isTainted());
	}

	@Test
	public void identityEligibilityAndContractRoundTripWithoutMovingTheOlderFields()
	{
		// @AllArgsConstructor is positional, so a field inserted rather than
		// APPENDED silently re-points every existing call site: the assertions
		// on the older fields are the only thing that would catch it
		GachaPresenceMessage msg = gson.fromJson(gson.toJson(
			new GachaPresenceMessage("MELEE", 99, "Goblin", 4, 12, true,
				"00112233445566aa", true, 0L)), GachaPresenceMessage.class);
		Assert.assertEquals("MELEE", msg.getAllowedStyle());
		Assert.assertEquals(99, msg.getCombatLevel());
		Assert.assertEquals("Goblin", msg.getActiveTaskName());
		Assert.assertEquals(4, msg.getKillsDone());
		Assert.assertEquals(12, msg.getKillsRequired());
		Assert.assertTrue(msg.isTainted());
		Assert.assertEquals("00112233445566aa", msg.getAccountKey());
		Assert.assertTrue(msg.isUndecidedOffers());
		Assert.assertEquals(Long.valueOf(0L), msg.getPartyContractId());
	}

	@Test
	public void aClaimedContractIdOfZeroSurvivesTheWireAsAClaim()
	{
		// the whole reason partyContractId is boxed: proposal ids come from
		// nextLong(), so 0 is as legal as any other, and a primitive would make
		// that member indistinguishable from one who claims nothing
		GachaPresenceMessage zero = gson.fromJson(gson.toJson(
			new GachaPresenceMessage(null, 3, "Goblin", 0, 12, false, null, false, 0L)),
			GachaPresenceMessage.class);
		Assert.assertNotNull(zero.getPartyContractId());
		Assert.assertEquals(0L, zero.getPartyContractId().longValue());

		GachaPresenceMessage silent = gson.fromJson(gson.toJson(
			new GachaPresenceMessage(null, 3, "Goblin", 0, 12, false, null, false, null)),
			GachaPresenceMessage.class);
		Assert.assertNull(silent.getPartyContractId());
	}
}

package com.gachaman.party;

import org.junit.*;

/**
 * Host and member must count down the SAME deadline.
 *
 * A non-host stores its deadline with a grace margin so it does not give up on
 * a start or cancel message that is merely late. That margin is enforcement
 * slack, not thinking time — the host stops collecting answers at its own
 * deadline regardless. Displaying the padded figure had the host's screen
 * reading 60s while everyone else read 75s for one and the same moment, which
 * would invite a member to sit on a decision the host had already timed out.
 *
 * The service applies the correction against a live tick counter, so what is
 * checked here is the arithmetic that correction has to satisfy.
 */
public class PartyDeadlineAgreementTest
{
	/** Mirrors PartyRollService: 100 ticks to answer, 25 more before self-cancel. */
	private static final int PROPOSAL_TTL_TICKS = 100;
	private static final int NON_HOST_GRACE_TICKS = 25;

	/** The service's display rule, stated independently of the Client. */
	private static int displayTicks(int expiresAtTick, boolean hosting, int now)
	{
		int deadline = hosting ? expiresAtTick : expiresAtTick - NON_HOST_GRACE_TICKS;
		return Math.max(0, deadline - now);
	}

	@Test
	public void bothSidesShowTheSameSecondsAtTheStartOfAProposal()
	{
		int now = 5_000;
		int hostExpiry = now + PROPOSAL_TTL_TICKS;
		int memberExpiry = now + PROPOSAL_TTL_TICKS + NON_HOST_GRACE_TICKS;

		int host = displayTicks(hostExpiry, true, now);
		int member = displayTicks(memberExpiry, false, now);

		Assert.assertEquals(host, member);
		// and it is the real window, not the padded one: 100 ticks is 60s
		Assert.assertEquals(60, PartyRollService.ticksToSeconds(host));
		Assert.assertEquals(60, PartyRollService.ticksToSeconds(member));
	}

	@Test
	public void theyStayInStepAsTheClockRuns()
	{
		int start = 5_000;
		int hostExpiry = start + PROPOSAL_TTL_TICKS;
		int memberExpiry = start + PROPOSAL_TTL_TICKS + NON_HOST_GRACE_TICKS;
		for (int now = start; now <= start + PROPOSAL_TTL_TICKS + 40; now++)
		{
			Assert.assertEquals("tick " + now,
				displayTicks(hostExpiry, true, now),
				displayTicks(memberExpiry, false, now));
		}
	}

	@Test
	public void theMemberHitsZeroWhenTheHostDoes()
	{
		int start = 5_000;
		int deadline = start + PROPOSAL_TTL_TICKS;
		int memberExpiry = deadline + NON_HOST_GRACE_TICKS;
		// one tick before: still time on both
		Assert.assertTrue(displayTicks(deadline, true, deadline - 1) > 0);
		Assert.assertTrue(displayTicks(memberExpiry, false, deadline - 1) > 0);
		// at the host's deadline: both read zero, and the member does NOT keep
		// counting through the grace it is silently still honouring internally
		Assert.assertEquals(0, displayTicks(deadline, true, deadline));
		Assert.assertEquals(0, displayTicks(memberExpiry, false, deadline));
	}

	@Test
	public void theGraceIsStillThereForTheTimeoutItself()
	{
		// the point of the fix is that the margin stops being VISIBLE, not that
		// it stops existing — the member's stored expiry must still be later
		int start = 5_000;
		int hostExpiry = start + PROPOSAL_TTL_TICKS;
		int memberExpiry = start + PROPOSAL_TTL_TICKS + NON_HOST_GRACE_TICKS;
		Assert.assertTrue(memberExpiry > hostExpiry);
		Assert.assertEquals(15, PartyRollService.ticksToSeconds(memberExpiry - hostExpiry));
	}
}

package com.gachaman.party;

import com.gachaman.*;
import com.google.gson.*;
import java.util.*;
import org.junit.*;

/**
 * The host picks the party's sizing rule — Fighting Weight (average) or
 * Weakest Man (lowest) — and every client in the roll obeys THAT choice, not
 * its own setting.
 *
 * Statics only, like {@link PartyFightingWeightTest}: executeRoll needs a
 * Client, a PartyService and a live proposal. What is pinned here is the
 * property the cross-client claim rests on — the sizing level is a pure
 * function of the TRANSMITTED protocols, the TRANSMITTED levels and the ONE
 * transmitted host choice. Nothing local feeds it, so two clients holding the
 * same stances compute the same number.
 */
public class PartySizingChoiceTest
{
	private final Gson gson = new Gson();

	// --- A. Weakest Man itself ---

	@Test
	public void weakestManIsTheLowestLevel()
	{
		Assert.assertEquals("a level 40 in a party of 90s sizes the board at 40", 40,
			PartyRollService.weakestMan(Arrays.asList(40, 90, 90, 90)));
		Assert.assertEquals(50, PartyRollService.weakestMan(Arrays.asList(50, 50)));
		Assert.assertEquals(40, PartyRollService.weakestMan(Arrays.asList(40, 90)));
	}

	@Test
	public void orderDoesNotChangeTheWeakestMan()
	{
		// the roster is host-sorted, but the rule must not DEPEND on that —
		// order-independence is the whole cross-client-identity claim
		int expected = PartyRollService.weakestMan(Arrays.asList(40, 90, 90, 90));
		Assert.assertEquals(expected, PartyRollService.weakestMan(Arrays.asList(90, 90, 40, 90)));
		Assert.assertEquals(expected, PartyRollService.weakestMan(Arrays.asList(90, 90, 90, 40)));
	}

	@Test
	public void aSoloLevelIsItsOwnWeakestMan()
	{
		Assert.assertEquals(70, PartyRollService.weakestMan(Collections.singletonList(70)));
	}

	@Test
	public void aBrokenLevelIsClampedBeforeItSizesTheBoard()
	{
		// NOT 0: a 0 collapses TaskGenerator's cap to max(2, 0) and rolls a
		// degenerate board of the two lowest monsters in the table. Lowering the
		// board is harmless under Fighting Weight (it averages away) but this
		// rule takes the minimum DIRECTLY, so one bad value is the whole answer
		Assert.assertEquals(Tuning.COMBAT_LEVEL_MIN,
			PartyRollService.weakestMan(Arrays.asList(0, 90)));
		Assert.assertEquals(Tuning.COMBAT_LEVEL_MIN,
			PartyRollService.weakestMan(Arrays.asList(-5, 90)));
		Assert.assertEquals(Tuning.COMBAT_LEVEL_MIN,
			PartyRollService.weakestMan(Arrays.asList(Integer.MIN_VALUE, 90)));
		Assert.assertEquals(Tuning.COMBAT_LEVEL_MAX,
			PartyRollService.weakestMan(Arrays.asList(Integer.MAX_VALUE, Integer.MAX_VALUE)));
	}

	@Test
	public void anEmptyOrMissingRosterFallsToTheFloor()
	{
		Assert.assertEquals(Tuning.COMBAT_LEVEL_MIN, PartyRollService.weakestMan(null));
		Assert.assertEquals(Tuning.COMBAT_LEVEL_MIN,
			PartyRollService.weakestMan(Collections.emptyList()));
	}

	// --- B. the legacy rule stays bug-for-bug ---

	@Test
	public void theLegacyRuleIsStillUnclamped()
	{
		// a party that falls back to this contains a client running that exact
		// code, and "nearly the same level" deals a different board. Weakest Man
		// and the legacy rule agree on every sane input and MUST diverge on a
		// broken one — that divergence is the clamp, and it is deliberate
		Assert.assertEquals(40, PartyRollService.legacyLowest(Arrays.asList(40, 90)));
		Assert.assertEquals(0, PartyRollService.legacyLowest(Arrays.asList(0, 90)));
		Assert.assertEquals(Integer.MIN_VALUE,
			PartyRollService.legacyLowest(Arrays.asList(Integer.MIN_VALUE, 90)));
		Assert.assertNotEquals(PartyRollService.weakestMan(Arrays.asList(0, 90)),
			PartyRollService.legacyLowest(Arrays.asList(0, 90)));
	}

	// --- C. the mixed-version gate, one rung up ---

	@Test
	public void weakestManNeedsEveryClientToUnderstandTheChoice()
	{
		// a protocol-1 client never reads the host's choice and sizes to the
		// average regardless, so one of them is enough to override the host
		Assert.assertTrue(PartyRollService.sizingChoiceAgreed(Arrays.asList(2, 2, 2)));
		Assert.assertFalse("one Fighting-Weight-only member is enough to fall back",
			PartyRollService.sizingChoiceAgreed(Arrays.asList(2, 2, 1)));
		Assert.assertFalse(PartyRollService.sizingChoiceAgreed(Arrays.asList(2, 0)));
		Assert.assertFalse(PartyRollService.sizingChoiceAgreed(null));
		Assert.assertFalse(PartyRollService.sizingChoiceAgreed(Collections.emptyList()));
	}

	@Test
	public void aFutureProtocolStillUnderstandsTheChoice()
	{
		Assert.assertTrue(PartyRollService.sizingChoiceAgreed(Arrays.asList(3, 2)));
		Assert.assertTrue(PartyRollService.sizingChoiceAgreed(
			Collections.singletonList(Integer.MAX_VALUE)));
	}

	@Test
	public void thisBuildAnnouncesTheSizingChoiceProtocol()
	{
		Assert.assertTrue("this build must claim a protocol its own gate accepts",
			PartyRollService.sizingChoiceAgreed(
				Collections.singletonList(PartyRollService.ROLL_PROTOCOL)));
		// the gates are nested, so understanding the choice implies understanding
		// Fighting Weight — a build that answered yes to one and no to the other
		// would make sizingLevel's branch order meaningless
		Assert.assertTrue(PartyRollService.meanSizingAgreed(
			Collections.singletonList(PartyRollService.ROLL_PROTOCOL)));
		Assert.assertTrue(PartyRollService.ROLL_PROTOCOL_SIZING_CHOICE
			> PartyRollService.ROLL_PROTOCOL_FIGHTING_WEIGHT);
	}

	// --- D. parsing the host's choice ---

	@Test
	public void everyUnrecognisedChoiceLandsOnTheDefault()
	{
		// what matters is not WHICH value garbage maps to, but that it maps to
		// the same one on every client — a roll that cannot agree on its rule is
		// worse than a roll on the wrong rule
		Assert.assertEquals(PartySizing.FIGHTING_WEIGHT, PartySizing.fromWire(null));
		Assert.assertEquals(PartySizing.FIGHTING_WEIGHT, PartySizing.fromWire(""));
		Assert.assertEquals(PartySizing.FIGHTING_WEIGHT, PartySizing.fromWire("STRONGEST_MAN"));
		Assert.assertEquals(PartySizing.FIGHTING_WEIGHT, PartySizing.fromWire("weakest_man"));
		Assert.assertEquals(PartySizing.WEAKEST_MAN, PartySizing.fromWire("WEAKEST_MAN"));
		Assert.assertEquals(PartySizing.FIGHTING_WEIGHT, PartySizing.fromWire("FIGHTING_WEIGHT"));
	}

	@Test
	public void everyConstantSurvivesItsOwnRoundTrip()
	{
		// the wire carries name(), not toString() — a display label that drifted
		// into the transmitted value would read as garbage on the far side
		for (PartySizing sizing : PartySizing.values())
		{
			Assert.assertEquals(sizing, PartySizing.fromWire(sizing.name()));
		}
	}

	// --- E. the whole decision ---

	@Test
	public void theHostsChoiceDecidesWhenEveryoneCanObeyIt()
	{
		Assert.assertEquals("Weakest Man sizes to the lowest", 40,
			PartyRollService.sizingLevel(Arrays.asList(40, 90), Arrays.asList(2, 2),
				"WEAKEST_MAN"));
		Assert.assertEquals("Fighting Weight sizes to the average", 65,
			PartyRollService.sizingLevel(Arrays.asList(40, 90), Arrays.asList(2, 2),
				"FIGHTING_WEIGHT"));
		Assert.assertEquals("an unset choice is Fighting Weight", 65,
			PartyRollService.sizingLevel(Arrays.asList(40, 90), Arrays.asList(2, 2), null));
	}

	@Test
	public void oneOlderClientOverridesAWeakestManHost()
	{
		// NOT 40: the fallback has to be the value the unaware client would have
		// picked, which is the average — falling back to the host's preference
		// would split the board it was meant to keep identical
		Assert.assertEquals(65,
			PartyRollService.sizingLevel(Arrays.asList(40, 90), Arrays.asList(2, 1),
				"WEAKEST_MAN"));
	}

	@Test
	public void aPreFightingWeightClientOverridesEveryoneIncludingTheHost()
	{
		// the legacy branch is checked FIRST and ignores the choice entirely
		Assert.assertEquals(40,
			PartyRollService.sizingLevel(Arrays.asList(40, 90), Arrays.asList(2, 0),
				"FIGHTING_WEIGHT"));
		Assert.assertEquals(40,
			PartyRollService.sizingLevel(Arrays.asList(40, 90), Arrays.asList(2, 0),
				"WEAKEST_MAN"));
	}

	@Test
	public void theLegacyBranchKeepsItsMissingClampEvenNowThatWeakestManHasOne()
	{
		// the same party, the same broken level, two rules: legacy passes the 0
		// straight through because the old client will, and Weakest Man clamps
		// because nothing on the wire has to match it
		Assert.assertEquals(0,
			PartyRollService.sizingLevel(Arrays.asList(0, 90), Arrays.asList(0, 2),
				"WEAKEST_MAN"));
		Assert.assertEquals(Tuning.COMBAT_LEVEL_MIN,
			PartyRollService.sizingLevel(Arrays.asList(0, 90), Arrays.asList(2, 2),
				"WEAKEST_MAN"));
	}

	@Test
	public void theResolvedRuleIsNamedRatherThanAppliedSilently()
	{
		Assert.assertEquals(PartySizing.WEAKEST_MAN,
			PartyRollService.resolvedSizing(Arrays.asList(2, 2), "WEAKEST_MAN"));
		Assert.assertEquals(PartySizing.FIGHTING_WEIGHT,
			PartyRollService.resolvedSizing(Arrays.asList(2, 1), "WEAKEST_MAN"));

		// the pre-vote disclosure has to print what actually happened, because
		// the member it protects is voting on a binding contract
		Assert.assertEquals("Weakest Man",
			PartyRollService.sizingRuleLabel(Arrays.asList(2, 2), "WEAKEST_MAN"));
		Assert.assertEquals("a silently overridden host is the one case that must not read"
				+ " like the host got their way", "Fighting Weight",
			PartyRollService.sizingRuleLabel(Arrays.asList(2, 1), "WEAKEST_MAN"));
		Assert.assertTrue(PartyRollService.sizingRuleLabel(Arrays.asList(2, 0), "WEAKEST_MAN")
			.contains("pre-Fighting Weight"));
	}

	// --- E2. the label on the CARD, which both cards now ask for ---

	/** One heard answer, carrying nothing but the protocol the label reads. */
	private static PartyRollService.Stance heard(int protocol)
	{
		return new PartyRollService.Stance(PartyRollResponseMessage.AGREE, 1L, true, 70, 55,
			"MELEE", protocol, Collections.emptyList(), null);
	}

	@Test
	public void theCardNamesTheHostsRuleWhenEveryBuildCanRunIt()
	{
		Assert.assertEquals("Weakest Man", PartyRollService.effectiveSizingLabel(
			Arrays.asList(heard(PartyRollService.ROLL_PROTOCOL),
				heard(PartyRollService.ROLL_PROTOCOL)),
			"WEAKEST_MAN"));
		Assert.assertEquals("Fighting Weight", PartyRollService.effectiveSizingLabel(
			Collections.singletonList(heard(PartyRollService.ROLL_PROTOCOL)),
			"FIGHTING_WEIGHT"));
	}

	@Test
	public void aJoinedMemberIsNotShownARuleTheRollWillNotUse()
	{
		// The committed card used to print PartySizing.fromWire(hostSizingMode)
		// — the host's DECLARED choice — so a member who had JOINED read
		// "Sizing: Weakest Man" for a roll that a protocol-1 member had already
		// forced down to Fighting Weight, while the member who had NOT joined
		// read the truth off the identical answers. One function answers both
		// now, so the two cards cannot disagree about one roll.
		List<PartyRollService.Stance> mixed = Arrays.asList(
			heard(PartyRollService.ROLL_PROTOCOL_FIGHTING_WEIGHT),
			heard(PartyRollService.ROLL_PROTOCOL));

		String label = PartyRollService.effectiveSizingLabel(mixed, "WEAKEST_MAN");
		Assert.assertNotEquals("the declared rule is exactly what must not be shown",
			PartySizing.fromWire("WEAKEST_MAN").toString(), label);
		Assert.assertTrue(label, label.startsWith("Fighting Weight"));
		Assert.assertTrue("the card has to say WHY, or it reads as the host's own choice",
			label.contains("cannot read the host's rule"));
	}

	@Test
	public void aPreFightingWeightBuildDragsTheCardAllTheWayDown()
	{
		String label = PartyRollService.effectiveSizingLabel(
			Arrays.asList(heard(0), heard(PartyRollService.ROLL_PROTOCOL)), "FIGHTING_WEIGHT");
		// the legacy rule IS the lowest level, so the honest name for it is
		// Weakest Man — even against a host who asked for the average
		Assert.assertTrue(label, label.startsWith("Weakest Man"));
		Assert.assertTrue(label.contains("too old to average"));
	}

	@Test
	public void theLocalBuildIsAlwaysCountedInTheCardsAnswer()
	{
		// an empty answer set is still this client's roll to join, and
		// everyoneAtLeast reads an empty list as "no", so the label would fall
		// to the legacy wording for a party of nobody without that term
		Assert.assertEquals("Weakest Man",
			PartyRollService.effectiveSizingLabel(Collections.emptyList(), "WEAKEST_MAN"));
	}

	@Test
	public void anUnreadableHostChoiceLandsOnTheDefaultOnTheCardToo()
	{
		// same rule as the wire parser: garbage is Fighting Weight everywhere,
		// never a fabricated third answer
		Assert.assertEquals("Fighting Weight", PartyRollService.effectiveSizingLabel(
			Collections.singletonList(heard(PartyRollService.ROLL_PROTOCOL)), null));
		Assert.assertEquals("Fighting Weight", PartyRollService.effectiveSizingLabel(
			Collections.singletonList(heard(PartyRollService.ROLL_PROTOCOL)), "NONSENSE"));
	}

	// --- F. the wire ---

	@Test
	public void sizingModeIsAbsentFromAnOlderClientsWire()
	{
		// a String and not an ordinal: Gson leaves null here, whereas an int
		// would deserialize to 0 and fabricate a real choice
		PartyRollProposeMessage propose = gson.fromJson(
			"{\"proposalId\":7,\"seedCandidate\":3,\"members\":true,"
				+ "\"combatLevel\":50,\"slayerLevel\":12,\"rollProtocol\":1}",
			PartyRollProposeMessage.class);
		Assert.assertNull(propose.getSizingMode());
		Assert.assertEquals(PartySizing.FIGHTING_WEIGHT,
			PartySizing.fromWire(propose.getSizingMode()));
	}

	@Test
	public void sizingModeRoundTripsAndDidNotDisturbTheOlderFields()
	{
		PartyRollProposeMessage propose = gson.fromJson(gson.toJson(
			new PartyRollProposeMessage(7L, 3L, true, 50, 12, "MAGIC",
				PartyRollService.ROLL_PROTOCOL, PartySizing.WEAKEST_MAN.name(),
				java.util.List.of(), null)),
			PartyRollProposeMessage.class);
		Assert.assertEquals("WEAKEST_MAN", propose.getSizingMode());
		// appended LAST, so every older field must still land where it did — a
		// positional @AllArgsConstructor gives no other warning
		Assert.assertEquals(7L, propose.getProposalId());
		Assert.assertEquals(3L, propose.getSeedCandidate());
		Assert.assertTrue(propose.isMembers());
		Assert.assertEquals(50, propose.getCombatLevel());
		Assert.assertEquals(12, propose.getSlayerLevel());
		Assert.assertEquals("MAGIC", propose.getAllowedStyle());
		Assert.assertEquals(PartyRollService.ROLL_PROTOCOL, propose.getRollProtocol());
	}

	private static PartyRollService.Stance answered(int response, int protocol)
	{
		return new PartyRollService.Stance(response, 1L, true, 70, 55,
			"MELEE", protocol, Collections.emptyList(), null);
	}

	/**
	 * Regression: the card and the chat line must name ONE rule.
	 *
	 * <p>executeRoll builds its protocol list from `agreed` and nothing else, so
	 * a member who says no cannot change the rule the roll uses. The label used
	 * to count every answer it had heard, which let one declining old build print
	 * "Fighting Weight (a member's build cannot read the host's rule)" on the
	 * card while the roll beside it really did use Weakest Man.
	 */
	@Test
	public void aMemberWhoDeclinedCannotDragTheLabelDown()
	{
		java.util.List<PartyRollService.Stance> mixed = Arrays.asList(
			answered(PartyRollResponseMessage.AGREE, PartyRollService.ROLL_PROTOCOL),
			answered(PartyRollResponseMessage.DECLINE, 0));
		Assert.assertEquals("Weakest Man",
			PartyRollService.effectiveSizingLabel(mixed, "WEAKEST_MAN"));
	}

	@Test
	public void aBusyMemberIsIgnoredTheSameWay()
	{
		java.util.List<PartyRollService.Stance> mixed = Arrays.asList(
			answered(PartyRollResponseMessage.AGREE, PartyRollService.ROLL_PROTOCOL),
			answered(PartyRollResponseMessage.BUSY, 0));
		Assert.assertEquals("Weakest Man",
			PartyRollService.effectiveSizingLabel(mixed, "WEAKEST_MAN"));
	}

	/** But an old build that AGREES still binds the whole party, as before. */
	@Test
	public void anOldBuildThatAgreesStillBindsEveryone()
	{
		java.util.List<PartyRollService.Stance> mixed = Arrays.asList(
			answered(PartyRollResponseMessage.AGREE, PartyRollService.ROLL_PROTOCOL),
			answered(PartyRollResponseMessage.AGREE, 0));
		Assert.assertNotEquals("Weakest Man",
			PartyRollService.effectiveSizingLabel(mixed, "WEAKEST_MAN"));
	}
}

package com.gachaman.party;

import com.gachaman.model.*;
import com.google.gson.*;
import org.junit.*;

/**
 * The allowed style rides the party handshake so the clash bonus can be
 * priced at accept. Mixed-version parties are the whole reason the field is a
 * nullable NAME: an older client omits it and Gson leaves null, where an int
 * ordinal would deserialize to 0 and silently fabricate MELEE.
 */
public class PartyRollStyleWireTest
{
	private final Gson gson = new Gson();

	@Test
	public void proposeFromAnOlderClientCarriesNoStyle()
	{
		PartyRollProposeMessage msg = gson.fromJson(
			"{\"proposalId\":7,\"seedCandidate\":3,\"members\":true,"
				+ "\"combatLevel\":50,\"slayerLevel\":12}", PartyRollProposeMessage.class);
		Assert.assertNull("an omitted style must not become MELEE", msg.getAllowedStyle());
		Assert.assertEquals(50, msg.getCombatLevel());
	}

	@Test
	public void responseFromAnOlderClientCarriesNoStyle()
	{
		PartyRollResponseMessage msg = gson.fromJson(
			"{\"proposalId\":7,\"response\":0,\"seedCandidate\":3,\"members\":false,"
				+ "\"combatLevel\":50,\"slayerLevel\":12}", PartyRollResponseMessage.class);
		Assert.assertNull(msg.getAllowedStyle());
		Assert.assertEquals(PartyRollResponseMessage.AGREE, msg.getResponse());
	}

	@Test
	public void styleRoundTripsOnBothMessages()
	{
		PartyRollProposeMessage propose = gson.fromJson(gson.toJson(
			new PartyRollProposeMessage(7L, 3L, true, 50, 12, "MAGIC",
				PartyRollService.ROLL_PROTOCOL, PartySizing.FIGHTING_WEIGHT.name(),
				java.util.List.of(), null)),
			PartyRollProposeMessage.class);
		Assert.assertEquals("MAGIC", propose.getAllowedStyle());

		PartyRollResponseMessage response = gson.fromJson(gson.toJson(
			new PartyRollResponseMessage(7L, PartyRollResponseMessage.AGREE, 3L, true, 50, 12,
				"RANGED", PartyRollService.ROLL_PROTOCOL, java.util.List.of(), null)),
			PartyRollResponseMessage.class);
		Assert.assertEquals("RANGED", response.getAllowedStyle());
	}

	@Test
	public void parseStyleRejectsGarbageInsteadOfThrowing()
	{
		Assert.assertEquals(AttackStyle.MAGIC, PartyRollService.parseStyle("MAGIC"));
		Assert.assertNull("a member who has not rolled yet", PartyRollService.parseStyle(null));
		Assert.assertNull("a style name this build does not know",
			PartyRollService.parseStyle("DRAGONFIRE"));
		Assert.assertNull(PartyRollService.parseStyle(""));
	}
}

package com.gachaman.party;

import java.util.*;
import org.junit.*;

/**
 * The majority rule and its tiebreak, in isolation. Statics only —
 * constructing PartyRollService would need a Client and a PartyService, and
 * evaluateVotes/hostResolve read the tick counter and the party roster.
 *
 * What this does NOT prove: that two clients settle on the same contract.
 * They don't have to — only the HOST resolves, and it broadcasts the result
 * (PartyRollResolveMessage). Convergence is a property of that message, and
 * only a two-client run can check it.
 */
public class PartyRollMajorityTest
{
	// --- A. the threshold ---

	@Test
	public void thresholdIsAStrictMajorityOfTheParty()
	{
		Assert.assertEquals("a pair must agree — there is no majority of two", 2,
			PartyRollService.majorityThreshold(2));
		Assert.assertEquals(2, PartyRollService.majorityThreshold(3));
		Assert.assertEquals("half of four is a TIE, not a majority", 3,
			PartyRollService.majorityThreshold(4));
		Assert.assertEquals(3, PartyRollService.majorityThreshold(5));
		Assert.assertEquals(4, PartyRollService.majorityThreshold(6));
	}

	@Test
	public void onlyOneContractCanEverHoldTheThreshold()
	{
		// the property the local-vote display leans on: with a STRICT majority,
		// two offers reaching it at once is arithmetically impossible, so the
		// count shown next to a vote can never promise a contract that loses
		for (int party = 2; party <= 12; party++)
		{
			int threshold = PartyRollService.majorityThreshold(party);
			Assert.assertTrue("two contracts could both reach " + threshold + " of " + party,
				2 * threshold > party);
		}
	}

	// --- B. reading the tally ---

	@Test
	public void topTalliesFindsTheLead()
	{
		Assert.assertEquals(Arrays.asList(1),
			PartyRollService.topTallies(new int[]{1, 3, 2, 0}));
		Assert.assertEquals("a lead at the last index still wins", Arrays.asList(3),
			PartyRollService.topTallies(new int[]{1, 1, 1, 2}));
	}

	@Test
	public void topTalliesReportsEveryTiedLeader()
	{
		Assert.assertEquals(Arrays.asList(0, 2),
			PartyRollService.topTallies(new int[]{2, 1, 2, 0}));
		Assert.assertEquals("a four-way tie is still a tie", Arrays.asList(0, 1, 2, 3),
			PartyRollService.topTallies(new int[]{1, 1, 1, 1}));
	}

	@Test
	public void anUnvotedContractIsNeverALeader()
	{
		// zero votes is not a lead to be tied with — otherwise a vote nobody
		// cast could be drawn out of an all-zero board
		Assert.assertTrue(PartyRollService.topTallies(new int[]{0, 0, 0, 0}).isEmpty());
		Assert.assertTrue(PartyRollService.topTallies(new int[0]).isEmpty());
		Assert.assertEquals(Arrays.asList(2), PartyRollService.topTallies(new int[]{0, 0, 1, 0}));
	}

	// --- C. the draw ---

	@Test
	public void tiebreakPicksFromTheTiedContractsOnly()
	{
		List<Integer> tied = Arrays.asList(1, 3);
		for (long seed = 0; seed < 200; seed++)
		{
			int drawn = PartyRollService.tiebreakIndex(seed, seed * 7 + 1, tied);
			Assert.assertTrue("drew " + drawn + ", which nobody voted for", tied.contains(drawn));
		}
	}

	@Test
	public void tiebreakIsReproducibleForTheSameRoll()
	{
		// the draw is seeded from the roll's anchor seed and proposal id, never
		// from an ambient random: the same vote must always draw the same
		// contract, or a bug report can never be replayed
		List<Integer> tied = Arrays.asList(0, 1, 2, 3);
		int first = PartyRollService.tiebreakIndex(12345L, 6789L, tied);
		Assert.assertEquals(first, PartyRollService.tiebreakIndex(12345L, 6789L, tied));
		Assert.assertEquals(first, PartyRollService.tiebreakIndex(12345L, 6789L, tied));
	}

	@Test
	public void tiebreakIsNotConstantAcrossRolls()
	{
		// a fixed seed is not the same as a fixed OUTCOME — if every party's
		// tie drew index 0, the "random" tiebreak would just be "first offer"
		List<Integer> tied = Arrays.asList(0, 1, 2, 3);
		boolean varies = false;
		int baseline = PartyRollService.tiebreakIndex(1L, 1L, tied);
		for (long seed = 2; seed < 60 && !varies; seed++)
		{
			varies = PartyRollService.tiebreakIndex(seed, seed, tied) != baseline;
		}
		Assert.assertTrue("every roll drew the same contract", varies);
	}

	@Test
	public void tiebreakSurvivesAnEmptyLead()
	{
		// hostResolve guards this, but a helper that throws on an empty list is
		// a landmine for the next caller: -1 is the "nothing to sign" answer
		Assert.assertEquals(-1, PartyRollService.tiebreakIndex(1L, 2L, null));
		Assert.assertEquals(-1, PartyRollService.tiebreakIndex(1L, 2L, Arrays.asList()));
	}

	@Test
	public void aSingleTiedContractDrawsItself()
	{
		Assert.assertEquals(2, PartyRollService.tiebreakIndex(99L, 44L, Arrays.asList(2)));
	}
}

package com.gachaman.party;

import com.gachaman.*;
import com.google.gson.*;
import java.util.*;
import org.junit.*;

/**
 * Party contracts are sized to the party's AVERAGE combat level (its fighting
 * weight) rather than its lowest. Statics only — executeRoll needs a Client, a
 * PartyService and a live proposal, so the rule is extracted and tested here.
 *
 * What this does NOT prove: that two clients roll the same board. Only a
 * two-client run can check that, as PartyRollMajorityTest already says. What
 * it DOES pin is the property the cross-client claim rests on — the sizing
 * input is a pure, order-independent function of the TRANSMITTED stances, so
 * two clients feeding generateOffers the same stances feed it the same cb. It
 * is never recomputed from local party membership.
 */
public class PartyFightingWeightTest
{
	private final Gson gson = new Gson();

	// --- A. the weight itself ---

	@Test
	public void fightingWeightIsTheFloorOfTheMean()
	{
		Assert.assertEquals("a level 40 in a party of 90s sizes the board at 77", 77,
			PartyRollService.fightingWeight(Arrays.asList(40, 90, 90, 90)));
		Assert.assertEquals(50, PartyRollService.fightingWeight(Arrays.asList(50, 50)));
		Assert.assertEquals(65, PartyRollService.fightingWeight(Arrays.asList(40, 90)));
	}

	@Test
	public void fightingWeightFloorsAndNeverRounds()
	{
		// pins integer division. A later "tidy-up" to Math.round would size a
		// pair ABOVE its own average, which is the one direction the weakest
		// member can never absorb
		Assert.assertEquals(3, PartyRollService.fightingWeight(Arrays.asList(3, 4)));
		Assert.assertEquals(10, PartyRollService.fightingWeight(Arrays.asList(10, 11)));
	}

	@Test
	public void aSoloLevelIsItsOwnWeight()
	{
		// a one-member roster must be byte-identical to the old lowest-level
		// rule, so an executeRoll that ever runs with one agreed member is
		// unchanged by this feature
		Assert.assertEquals(70, PartyRollService.fightingWeight(Collections.singletonList(70)));
	}

	@Test
	public void orderDoesNotChangeTheWeight()
	{
		// the roster is host-sorted, but the mean must not DEPEND on that —
		// order-independence is the whole cross-client-identity claim
		int expected = PartyRollService.fightingWeight(Arrays.asList(40, 90, 90, 90));
		Assert.assertEquals(expected, PartyRollService.fightingWeight(Arrays.asList(90, 90, 40, 90)));
		Assert.assertEquals(expected, PartyRollService.fightingWeight(Arrays.asList(90, 40, 90, 90)));
		Assert.assertEquals(expected, PartyRollService.fightingWeight(Arrays.asList(90, 90, 90, 40)));
	}

	// --- B. hostile or broken transmitted levels ---

	@Test
	public void anAbsurdLevelIsClampedBeforeAveraging()
	{
		// under the old lowest-level rule a bad combatLevel could only make
		// contracts EASIER, so it was self-limiting. An average is not: one
		// inflated value would drag the whole party onto an unkillable monster,
		// and a party contract cannot be abandoned. (126 + 90) / 2 = 108, and
		// an unclamped int sum would have wrapped negative here
		Assert.assertEquals(108,
			PartyRollService.fightingWeight(Arrays.asList(90, Integer.MAX_VALUE)));
		Assert.assertEquals(Tuning.COMBAT_LEVEL_MAX,
			PartyRollService.fightingWeight(Arrays.asList(Integer.MAX_VALUE, Integer.MAX_VALUE)));
	}

	@Test
	public void aNonsenseLowLevelIsClampedToTheCombatFloor()
	{
		Assert.assertEquals(Tuning.COMBAT_LEVEL_MIN,
			PartyRollService.fightingWeight(Arrays.asList(0, 0)));
		Assert.assertEquals(Tuning.COMBAT_LEVEL_MIN,
			PartyRollService.fightingWeight(Arrays.asList(-5, -5)));
		Assert.assertEquals(Tuning.COMBAT_LEVEL_MIN,
			PartyRollService.fightingWeight(Arrays.asList(Integer.MIN_VALUE, Integer.MIN_VALUE)));
	}

	@Test
	public void anEmptyOrMissingRosterFallsToTheFloor()
	{
		// NOT 0. A 0 collapses TaskGenerator's cap to max(2, 0) = 2 and rolls a
		// degenerate board of the two lowest monsters in the table
		Assert.assertEquals(Tuning.COMBAT_LEVEL_MIN, PartyRollService.fightingWeight(null));
		Assert.assertEquals(Tuning.COMBAT_LEVEL_MIN,
			PartyRollService.fightingWeight(Collections.emptyList()));
	}

	// --- C. the mixed-version gate ---

	@Test
	public void oneOldClientPutsTheWholePartyBackOnTheOldRule()
	{
		// all-or-nothing: sizing changes the eligible pool, the pool changes the
		// bound rng.pick draws against, and a different bound consumes a
		// different number of Random.next() calls. Two clients on two rules
		// would vote by INDEX on boards they never saw
		Assert.assertTrue(PartyRollService.meanSizingAgreed(Arrays.asList(1, 1, 1)));
		Assert.assertFalse("one legacy member is enough to fall back",
			PartyRollService.meanSizingAgreed(Arrays.asList(1, 1, 0)));
		Assert.assertFalse(PartyRollService.meanSizingAgreed(Arrays.asList(0, 0)));
	}

	@Test
	public void aFutureProtocolIsNotMistakenForALegacyOne()
	{
		// the gate is >= and not ==, so a client from a LATER round that still
		// implements Fighting Weight is not shoved back onto the old rule
		Assert.assertTrue(PartyRollService.meanSizingAgreed(Arrays.asList(2, 1)));
		Assert.assertTrue(PartyRollService.meanSizingAgreed(
			Collections.singletonList(Integer.MAX_VALUE)));
	}

	@Test
	public void anUnknownRosterNeverAssumesTheNewRule()
	{
		// no answer is not a yes: the safe default is the rule every build in
		// existence already agrees on
		Assert.assertFalse(PartyRollService.meanSizingAgreed(null));
		Assert.assertFalse(PartyRollService.meanSizingAgreed(Collections.emptyList()));
	}

	@Test
	public void thisBuildAnnouncesTheFightingWeightProtocol()
	{
		Assert.assertTrue("this build must claim a protocol its own gate accepts",
			PartyRollService.meanSizingAgreed(
				Collections.singletonList(PartyRollService.ROLL_PROTOCOL)));
	}

	// --- D. the wire ---

	@Test
	public void rollProtocolIsAbsentFromAnOlderClientsWire()
	{
		// exactly the value meanSizingAgreed treats as legacy — the fallback is
		// driven by Gson's int default, not by a version string anyone sends
		PartyRollProposeMessage propose = gson.fromJson(
			"{\"proposalId\":7,\"seedCandidate\":3,\"members\":true,"
				+ "\"combatLevel\":50,\"slayerLevel\":12}", PartyRollProposeMessage.class);
		Assert.assertEquals(0, propose.getRollProtocol());

		PartyRollResponseMessage response = gson.fromJson(
			"{\"proposalId\":7,\"response\":0,\"seedCandidate\":3,\"members\":false,"
				+ "\"combatLevel\":50,\"slayerLevel\":12}", PartyRollResponseMessage.class);
		Assert.assertEquals(0, response.getRollProtocol());
		Assert.assertFalse(PartyRollService.meanSizingAgreed(
			Arrays.asList(PartyRollService.ROLL_PROTOCOL, propose.getRollProtocol())));
	}

	@Test
	public void rollProtocolRoundTripsOnBothMessages()
	{
		PartyRollProposeMessage propose = gson.fromJson(gson.toJson(
			new PartyRollProposeMessage(7L, 3L, true, 50, 12, "MAGIC",
				PartyRollService.ROLL_PROTOCOL, PartySizing.FIGHTING_WEIGHT.name(),
				java.util.List.of(), null)),
			PartyRollProposeMessage.class);
		Assert.assertEquals(PartyRollService.ROLL_PROTOCOL, propose.getRollProtocol());
		// the field was appended LAST, so the older fields must still land where
		// they did — a positional @AllArgsConstructor gives no other warning
		Assert.assertEquals(50, propose.getCombatLevel());
		Assert.assertEquals(12, propose.getSlayerLevel());
		Assert.assertEquals("MAGIC", propose.getAllowedStyle());

		PartyRollResponseMessage response = gson.fromJson(gson.toJson(
			new PartyRollResponseMessage(7L, PartyRollResponseMessage.AGREE, 3L, true, 50, 12,
				"RANGED", PartyRollService.ROLL_PROTOCOL, java.util.List.of(), null)),
			PartyRollResponseMessage.class);
		Assert.assertEquals(PartyRollService.ROLL_PROTOCOL, response.getRollProtocol());
		Assert.assertEquals(50, response.getCombatLevel());
		Assert.assertEquals(12, response.getSlayerLevel());
		Assert.assertEquals("RANGED", response.getAllowedStyle());
	}
}

package com.gachaman.party;

import com.gachaman.*;
import java.util.*;
import org.junit.*;

/**
 * The rules that let a shared contract survive a client restart.
 *
 * A restart destroys the whole party session — member ids are drawn fresh every
 * time RuneLite starts — while the contract itself comes back off disk still
 * flagged as shared. The contract is resurrected from its persisted proposal id
 * and its participant set is rebuilt by whoever calls in quoting that id, which
 * leaves the carry-clause watchdog reading an EMPTY participant set for a party
 * that may be perfectly alive. These are the two pure decisions in that path.
 */
public class PartyResumeTest
{
	private static Set<Long> roster(long... ids)
	{
		Set<Long> set = new LinkedHashSet<>();
		for (long id : ids)
		{
			set.add(id);
		}
		return set;
	}

	// =====================================================================
	// everyoneGone
	// =====================================================================

	private static final int GONE = Tuning.PARTY_DEPART_GRACE_TICKS + 1;

	@Test
	public void aPartyStillTogetherIsNotGone()
	{
		Assert.assertFalse(PartyRollService.everyoneGone(true, true, 0, false, 0, 3));
	}

	@Test
	public void knownPartnersWhoStayGoneFire()
	{
		Assert.assertTrue(PartyRollService.everyoneGone(true, false, GONE, false, 0, 1));
	}

	@Test
	public void aPartnerRestartingTheirClientIsNotWrittenOffAtOnce()
	{
		// the other half of the resume defect. Closing a client removes you from the
		// roster IMMEDIATELY, so with no grace a party of two converts about fifteen
		// seconds into a partner's restart — and the resurrection on their side then
		// comes back to a contract that was already settled without them. The feature
		// would be inert for the commonest party size.
		Assert.assertFalse(PartyRollService.everyoneGone(true, false, 0, false, 0, 1));
		Assert.assertFalse("still within the relaunch window",
			PartyRollService.everyoneGone(true, false,
				Tuning.PARTY_DEPART_GRACE_TICKS, false, 0, 1));
	}

	@Test
	public void aPartnerWhoComesBackInsideTheGraceCancelsIt()
	{
		// what the caller's latch buys: presence outranks any elapsed time
		Assert.assertFalse(PartyRollService.everyoneGone(true, true, GONE, false, 0, 2));
	}

	@Test
	public void theDepartureGraceIsShorterThanTheIdleTimer()
	{
		// a departed party must settle on the "your party has left" branch, not sit
		// out the full idle timer and settle on the "gone quiet" one
		Assert.assertTrue(Tuning.PARTY_DEPART_GRACE_TICKS < Tuning.PARTY_IDLE_TICKS);
	}

	@Test
	public void aResumedContractDoesNotConvertOnItsFirstSweep()
	{
		// the defect this rule exists to prevent. A resurrected contract knows
		// nobody, because ids do not survive a restart — reading that as "everyone
		// left" would drop a live party to the carry multiplier within 25 ticks of
		// logging back in, with nobody having gone anywhere.
		Assert.assertFalse("a populated party we simply have not heard from yet",
			PartyRollService.everyoneGone(false, false, 0, true, 0, 3));
		Assert.assertFalse("and it must not start converting once the grace lapses either",
			PartyRollService.everyoneGone(false, false, 0, true,
				Tuning.PARTY_RESYNC_TICKS * 100, 3));
	}

	@Test
	public void aResumedContractAloneInAnEmptyPartyWaitsOutTheResyncGrace()
	{
		// RuneLite rejoins the previous party ASYNCHRONOUSLY, so the roster is
		// usually still empty at the moment the save loads. Converting there would
		// punish every relog for the client's own startup ordering.
		Assert.assertFalse(PartyRollService.everyoneGone(false, false, 0, true, 0, 0));
		Assert.assertFalse(PartyRollService.everyoneGone(false, false, 0, true,
			Tuning.PARTY_RESYNC_TICKS, 1));
	}

	@Test
	public void aResumedContractStillAloneAfterTheGraceConverts()
	{
		// closes the relog exploit: without this branch nobody can ever call in from
		// an empty roster, so parking on the idle timer would hand a dead party's
		// contract a fresh ten-minute window on every restart, indefinitely
		Assert.assertTrue(PartyRollService.everyoneGone(false, false, 0, true,
			Tuning.PARTY_RESYNC_TICKS + 1, 1));
		Assert.assertTrue("no party at all is the same case",
			PartyRollService.everyoneGone(false, false, 0, true,
				Tuning.PARTY_RESYNC_TICKS + 1, 0));
	}

	@Test
	public void theResyncGraceIsShorterThanTheIdleTimer()
	{
		// otherwise the branch it guards is unreachable — the idle clause would
		// always settle a silent contract first and the party-of-one case would
		// never be distinguished from any other quiet one
		Assert.assertTrue(Tuning.PARTY_RESYNC_TICKS < Tuning.PARTY_IDLE_TICKS);
	}

	@Test
	public void aSessionThatKnowsItsOwnRosterIgnoresTheResumeGraceEntirely()
	{
		// once anyone has called in, knewOthers is true and the resume arguments
		// stop being consulted: a party that reassembles and THEN disbands settles
		// on the ordinary rule, with no second grace period bought by the restart
		Assert.assertTrue(PartyRollService.everyoneGone(true, false, GONE, true, 0, 1));
		Assert.assertFalse(PartyRollService.everyoneGone(true, true, GONE, true, 0, 3));
	}

	@Test
	public void aSessionThatNeverResumedAndKnowsNobodyParksOnTheIdleTimer()
	{
		// not a state the roll can produce — a signed contract always records its
		// own participants — but the fallback must be the forgiving one, since an
		// unexpected empty set is a bug in US and should not cost the player GC
		Assert.assertFalse(PartyRollService.everyoneGone(false, false, 0, false, 0, 0));
		Assert.assertFalse(PartyRollService.everyoneGone(false, false, GONE, false, 99999, 1));
	}

	@Test
	public void aRewoundClockNeverConvertsEarly()
	{
		// a relog restarts getTickCount(), so the caller re-anchors its stamps and
		// feeds 0 rather than a negative elapsed. Pin that a negative would be safe
		// anyway — the failure direction has to be "waits too long", never "converts
		// a contract the player still has a party for".
		Assert.assertFalse(PartyRollService.everyoneGone(true, false, -5000, false, 0, 1));
		Assert.assertFalse(PartyRollService.everyoneGone(false, false, 0, true, -5000, 0));
	}

	// =====================================================================
	// dropDepartedKills
	// =====================================================================

	@Test
	public void aReturningMemberIsNotCountedTwice()
	{
		// the exact double-count: 12 kills banked under the id they held before
		// their client restarted, then the same 12 re-reported under the new one.
		// Summed blind that is 24 kills of shared quota for 12 kills of work.
		Map<Long, Integer> partyKills = new HashMap<>();
		partyKills.put(111L, 12); // pre-restart id, no longer in the party
		partyKills.put(333L, 5);  // a partner who never left

		PartyRollService.dropDepartedKills(partyKills, roster(999L, 222L, 333L));
		partyKills.merge(222L, 12, Math::max); // the same player, new id

		Assert.assertFalse(partyKills.containsKey(111L));
		int othersTotal = 0;
		for (int kills : partyKills.values())
		{
			othersTotal += kills;
		}
		Assert.assertEquals("12 kills of work must buy 12 kills of shared quota",
			17, othersTotal);
	}

	@Test
	public void pruningIsANoOpWhenNobodyHasLeft()
	{
		Map<Long, Integer> partyKills = new HashMap<>();
		partyKills.put(111L, 12);
		partyKills.put(222L, 3);
		PartyRollService.dropDepartedKills(partyKills, roster(999L, 111L, 222L));
		Assert.assertEquals(2, partyKills.size());
		Assert.assertEquals(Integer.valueOf(12), partyKills.get(111L));
	}

	@Test
	public void pruningToleratesEmptyInputs()
	{
		Map<Long, Integer> empty = new HashMap<>();
		PartyRollService.dropDepartedKills(empty, new HashSet<>());
		Assert.assertTrue(empty.isEmpty());

		Map<Long, Integer> all = new HashMap<>();
		all.put(111L, 12);
		// only ever called with a roster containing the member being admitted, so
		// this cannot happen in practice — pin that it degrades to "trust nobody"
		// rather than throwing, since the total can only fall and syncPartyKills
		// refuses to move its high-water mark down
		PartyRollService.dropDepartedKills(all, new HashSet<>());
		Assert.assertTrue(all.isEmpty());
	}

	@Test
	public void pruningSurvivesAnImmutableRoster()
	{
		// rosterIds() hands back a set we do not own; the prune must not write to it
		Map<Long, Integer> partyKills = new HashMap<>();
		partyKills.put(111L, 12);
		partyKills.put(222L, 3);
		Set<Long> immutable = java.util.Collections.unmodifiableSet(
			new HashSet<>(Arrays.asList(222L)));
		PartyRollService.dropDepartedKills(partyKills, immutable);
		Assert.assertEquals(1, partyKills.size());
		Assert.assertEquals(Integer.valueOf(3), partyKills.get(222L));
	}
}

package com.gachaman.party;

import java.util.*;
import org.junit.*;

/**
 * The Ante's party rule, in isolation: UNANIMOUS consent of the FINAL roster.
 * Deliberately a stricter bar than the contract's own majority — a contract is
 * an activity the party does together, a stake is each member's own GC.
 *
 * Statics only; the surrounding vote plumbing needs a Client and a PartyService.
 * What this does NOT prove is convergence between clients: the host alone
 * evaluates this and broadcasts the verdict, and each client then re-checks its
 * own recorded consent before any GC moves.
 */
public class AnteUnanimityTest
{
	private static Map<Long, Boolean> consent(Object... pairs)
	{
		Map<Long, Boolean> map = new HashMap<>();
		for (int i = 0; i < pairs.length; i += 2)
		{
			map.put(((Number) pairs[i]).longValue(), (Boolean) pairs[i + 1]);
		}
		return map;
	}

	private static final List<Long> TRIO = Arrays.asList(1L, 2L, 3L);

	// --- A. unanimity ---

	@Test
	public void everyMemberSayingYesCarriesTheAnte()
	{
		Assert.assertTrue(PartyRollService.anteUnanimous(TRIO,
			consent(1L, true, 2L, true, 3L, true)));
	}

	@Test
	public void oneRefusalSinksItForEveryone()
	{
		Assert.assertFalse(PartyRollService.anteUnanimous(TRIO,
			consent(1L, true, 2L, false, 3L, true)));
		Assert.assertFalse("the last member counts as much as the first",
			PartyRollService.anteUnanimous(TRIO, consent(1L, true, 2L, true, 3L, false)));
	}

	@Test
	public void silenceIsARefusal()
	{
		// a member bound by a MAJORITY may never have clicked at all, and a
		// client too old to know the field sends nothing — neither consented to
		// stake anything, so neither can be counted as a yes
		Assert.assertFalse(PartyRollService.anteUnanimous(TRIO, consent(1L, true, 2L, true)));
		Assert.assertFalse(PartyRollService.anteUnanimous(TRIO, consent()));
	}

	@Test
	public void aSoloRosterStillNeedsItsOwnConsent()
	{
		Assert.assertTrue(PartyRollService.anteUnanimous(Arrays.asList(7L), consent(7L, true)));
		Assert.assertFalse(PartyRollService.anteUnanimous(Arrays.asList(7L), consent(7L, false)));
		Assert.assertFalse(PartyRollService.anteUnanimous(Arrays.asList(7L), consent(8L, true)));
	}

	// --- B. the roster is what counts, not the ballot box ---

	@Test
	public void consentFromSomeoneOffTheContractDoesNotCount()
	{
		// a plurality narrows the roster to the voters; a member who agreed to
		// the wager but is NOT on the resulting contract must neither carry it
		// nor block it
		Assert.assertTrue("an outsider's yes must not be needed",
			PartyRollService.anteUnanimous(Arrays.asList(1L, 2L),
				consent(1L, true, 2L, true, 9L, false)));
		Assert.assertFalse("an outsider's yes must not substitute for a member's",
			PartyRollService.anteUnanimous(Arrays.asList(1L, 2L),
				consent(1L, true, 9L, true)));
	}

	// --- C. degenerate input never stakes anything ---

	@Test
	public void anEmptyOrAbsentRosterCarriesNothing()
	{
		// the safe direction is always "no wager": broadcastResolve calls this
		// with whatever roster it just fixed, and a true here moves real GC
		Assert.assertFalse(PartyRollService.anteUnanimous(null, consent(1L, true)));
		Assert.assertFalse(PartyRollService.anteUnanimous(Arrays.asList(), consent(1L, true)));
		Assert.assertFalse(PartyRollService.anteUnanimous(TRIO, null));
	}
}

package com.gachaman.party;

import com.gachaman.model.*;
import java.util.*;
import org.junit.*;

/**
 * How the party page decides what is one block and what is several.
 *
 * A party is routinely not one thing: two members can be working one shared
 * contract while two more work another and a fifth is still mid-roll. The
 * grouping rules are pure statics precisely so this — the part a player
 * actually reads — can be pinned without a Client or a PartyService.
 *
 * Every input is SELF-REPORTED. So the recurring question in this file is not
 * "is the claim true" but "does a false claim stay contained", and the answer
 * has to be yes for every case here.
 */
public class PartyPresenceGroupTest
{
	private static PartyPresenceService.Row row(long memberId, String name,
		String taskName, int killsDone, int killsRequired, Long contractId)
	{
		return new PartyPresenceService.Row(memberId, name, true, false, true,
			AttackStyle.MELEE, 99, taskName, killsDone, killsRequired, false,
			null, false, contractId, null);
	}

	/** A member with nothing signed: no quarry, no quota, no contract id. */
	private static PartyPresenceService.Row idle(long memberId, String name)
	{
		return row(memberId, name, null, 0, 0, null);
	}

	private static List<String> names(PartyPresenceService.Group group)
	{
		List<String> out = new ArrayList<>();
		for (PartyPresenceService.Row member : group.getMembers())
		{
			out.add(member.getName());
		}
		return out;
	}

	@Test
	public void nothingToGroupIsNoBlocks()
	{
		Assert.assertTrue(PartyPresenceService.group(null).isEmpty());
		Assert.assertTrue(PartyPresenceService.group(Collections.emptyList()).isEmpty());
	}

	@Test
	public void membersOnOneContractAreOneBlock()
	{
		List<PartyPresenceService.Group> groups = PartyPresenceService.group(Arrays.asList(
			row(1, "Alpha", "Goblin", 4, 20, 77L),
			row(2, "Bravo", "Goblin", 6, 20, 77L)));

		Assert.assertEquals("one contract draws one meter, not two", 1, groups.size());
		PartyPresenceService.Group only = groups.get(0);
		Assert.assertTrue(only.isShared());
		Assert.assertTrue(only.isOnContract());
		Assert.assertEquals(Arrays.asList("Alpha", "Bravo"), names(only));
		Assert.assertEquals("Goblin", only.getTaskName());
		Assert.assertEquals(20, only.getKillsRequired());
	}

	@Test
	public void pooledProgressIsTheMaxNotTheSum()
	{
		// a shared contract has ONE quota that every member's kills fill, so
		// every client should report the same number — but a client that has
		// gone quiet reports a stale LOWER one. Summing would multiply the quota
		// by the party size and show 18/20 for a job that is 6/20 done.
		PartyPresenceService.Group group = PartyPresenceService.group(Arrays.asList(
			row(1, "Alpha", "Goblin", 6, 20, 77L),
			row(2, "Bravo", "Goblin", 6, 20, 77L),
			row(3, "Charlie", "Goblin", 6, 20, 77L))).get(0);

		Assert.assertEquals(6, group.getKillsDone());
		Assert.assertEquals(20, group.getKillsRequired());
	}

	@Test
	public void theFreshestClientSetsThePooledProgress()
	{
		// and it is order-independent: the stale row first, then the stale row
		// last. A "first row wins" reading would draw a different number for the
		// same party depending on who happened to sort to the top.
		Assert.assertEquals(9, PartyPresenceService.group(Arrays.asList(
			row(1, "Stale", "Goblin", 2, 20, 77L),
			row(2, "Fresh", "Goblin", 9, 20, 77L))).get(0).getKillsDone());
		Assert.assertEquals(9, PartyPresenceService.group(Arrays.asList(
			row(1, "Fresh", "Goblin", 9, 20, 77L),
			row(2, "Stale", "Goblin", 2, 20, 77L))).get(0).getKillsDone());
	}

	@Test
	public void twoContractsInOnePartyAreTwoBlocks()
	{
		List<PartyPresenceService.Group> groups = PartyPresenceService.group(Arrays.asList(
			row(1, "Alpha", "Goblin", 4, 20, 77L),
			row(2, "Bravo", "Goblin", 4, 20, 77L),
			row(3, "Charlie", "Zulrah", 1, 5, 88L),
			row(4, "Delta", "Zulrah", 1, 5, 88L)));

		Assert.assertEquals(2, groups.size());
		Assert.assertEquals(Arrays.asList("Alpha", "Bravo"), names(groups.get(0)));
		Assert.assertEquals(Arrays.asList("Charlie", "Delta"), names(groups.get(1)));
		Assert.assertEquals("Goblin", groups.get(0).getTaskName());
		Assert.assertEquals("Zulrah", groups.get(1).getTaskName());
	}

	@Test
	public void everyoneElseIsTheirOwnBlock()
	{
		// a solo contract, an idle member and a member mid-roll each stand alone
		// — and two idle members must not merge into one "nobody" block
		List<PartyPresenceService.Group> groups = PartyPresenceService.group(Arrays.asList(
			row(1, "Solo", "Goblin", 4, 20, null),
			idle(2, "Idle"),
			idle(3, "AlsoIdle")));

		Assert.assertEquals(3, groups.size());
		Assert.assertFalse("no contract id is no shared contract", groups.get(0).isShared());
		Assert.assertTrue(groups.get(0).isOnContract());
		Assert.assertEquals("Goblin", groups.get(0).getTaskName());

		for (int i = 1; i < groups.size(); i++)
		{
			Assert.assertFalse(groups.get(i).isShared());
			Assert.assertFalse(groups.get(i).isOnContract());
			Assert.assertNull(groups.get(i).getTaskName());
			Assert.assertEquals(0, groups.get(i).getKillsRequired());
		}
	}

	@Test
	public void anIdClaimedByOneMemberIsStillAGroupOfOne()
	{
		// their partner may have left the party or gone quiet and the carry
		// clause has not fired yet. Calling this "solo" would be a guess about
		// somebody else's state, and the page would flip the label back the
		// moment they reconnect.
		PartyPresenceService.Group group = PartyPresenceService.group(
			Collections.singletonList(row(1, "Alpha", "Goblin", 4, 20, 77L))).get(0);
		Assert.assertTrue(group.isShared());
		Assert.assertEquals(1, group.getMembers().size());
	}

	@Test
	public void agreeingOnTheIdButNotTheQuarryDoesNotMerge()
	{
		// the reason the bucket key is id AND task, never the id alone. Two
		// clients that disagree about the monster are not on the same contract
		// by any reading, and merging them would draw one pooled meter over two
		// different jobs. Splitting renders the disagreement, which is honest
		// and also self-limiting: a hostile client that guesses an id can at
		// worst appear beside the party under the party's own monster name.
		List<PartyPresenceService.Group> groups = PartyPresenceService.group(Arrays.asList(
			row(1, "Honest", "Goblin", 4, 20, 77L),
			row(2, "Liar", "Zulrah", 19, 20, 77L)));

		Assert.assertEquals(2, groups.size());
		Assert.assertEquals("Goblin", groups.get(0).getTaskName());
		Assert.assertEquals("the forged progress stays in the forger's own block",
			4, groups.get(0).getKillsDone());
		Assert.assertEquals("Zulrah", groups.get(1).getTaskName());
	}

	@Test
	public void theBucketKeyIsSeparated()
	{
		// plain concatenation collides: id 7 on "0Goblin" and id 70 on "Goblin"
		// flatten to the same string and two unrelated contracts become one
		// block with one meter
		List<PartyPresenceService.Group> groups = PartyPresenceService.group(Arrays.asList(
			row(1, "Alpha", "0Goblin", 4, 20, 7L),
			row(2, "Bravo", "Goblin", 4, 20, 70L)));
		Assert.assertEquals(2, groups.size());
	}

	@Test
	public void aClaimedIdOfZeroIsARealClaim()
	{
		// proposal ids come from nextLong(), so 0 is as legal as any other and
		// must not read as "claims nothing"
		List<PartyPresenceService.Group> groups = PartyPresenceService.group(Arrays.asList(
			row(1, "Alpha", "Goblin", 4, 20, 0L),
			row(2, "Bravo", "Goblin", 4, 20, 0L)));
		Assert.assertEquals(1, groups.size());
		Assert.assertTrue(groups.get(0).isShared());
		Assert.assertEquals(Long.valueOf(0L), groups.get(0).getContractId());
	}

	@Test
	public void anIdWithoutAQuotaIsNotAContract()
	{
		// a stale id left behind after a contract finished would otherwise pull
		// an idle member into a block whose own line says they have no work
		List<PartyPresenceService.Group> groups = PartyPresenceService.group(Arrays.asList(
			row(1, "Working", "Goblin", 4, 20, 77L),
			row(2, "Finished", null, 0, 0, 77L)));

		Assert.assertEquals(2, groups.size());
		Assert.assertTrue(groups.get(0).isShared());
		Assert.assertFalse(groups.get(1).isShared());
		Assert.assertFalse(groups.get(1).isOnContract());
	}

	@Test
	public void groupOrderFollowsRowOrderSoSelfStaysOnTop()
	{
		// the row list is already the display order (self first), and the page
		// draws groups in the order it gets them — so a party where your own
		// contract is not first would bury your own meter below strangers'
		PartyPresenceService.Row self = new PartyPresenceService.Row(9, "You", true, true, true,
			AttackStyle.MAGIC, 99, "Zulrah", 2, 5, false, null, false, 88L, null);
		List<PartyPresenceService.Group> groups = PartyPresenceService.group(Arrays.asList(
			self,
			row(1, "Alpha", "Goblin", 4, 20, 77L),
			row(2, "Bravo", "Goblin", 4, 20, 77L)));

		Assert.assertEquals(2, groups.size());
		Assert.assertEquals(Collections.singletonList("You"), names(groups.get(0)));
		Assert.assertTrue(groups.get(0).getMembers().get(0).isSelf());
	}

	@Test
	public void eligibilityNeedsSilenceOnBothSides()
	{
		// what the page prints under a member who cannot join a shared roll.
		// A dealt-but-unsigned board is the non-obvious half: they look idle in
		// every other respect, and the party would sit waiting on someone who
		// cannot answer until they sign or clear it.
		Assert.assertTrue(idle(1, "Ready").isEligibleToRoll());
		Assert.assertFalse("a signed contract is not eligible",
			row(1, "Working", "Goblin", 0, 20, null).isEligibleToRoll());
		Assert.assertFalse("a dealt board with nothing signed is not eligible",
			new PartyPresenceService.Row(1, "Choosing", true, false, true,
				null, 99, null, 0, 0, false, null, true, null, null).isEligibleToRoll());
		Assert.assertFalse("no signal is not a yes",
			new PartyPresenceService.Row(1, "Silent", true, false, false,
				null, 99, null, 0, 0, false, null, false, null, null).isEligibleToRoll());
		Assert.assertFalse("logged out is not a yes",
			new PartyPresenceService.Row(1, "Offline", false, false, true,
				null, 99, null, 0, 0, false, null, false, null, null).isEligibleToRoll());
	}

	@Test
	public void aGroupsMemberListIsNotTheCallersToEdit()
	{
		// it is handed straight to a panel loop, where an accidental sort would
		// silently disagree with the row order the meter was computed from
		try
		{
			PartyPresenceService.group(Collections.singletonList(idle(1, "Alpha")))
				.get(0).getMembers().clear();
			Assert.fail("the member list must be unmodifiable");
		}
		catch (UnsupportedOperationException expected)
		{
			// intended
		}
	}
}

package com.gachaman.party;

import com.gachaman.data.*;
import com.gachaman.model.*;
import com.gachaman.service.*;
import com.google.gson.*;
import java.io.*;
import java.nio.charset.*;
import java.util.*;
import org.junit.*;

/**
 * A quest lock cuts monsters out of the pool, and the pool decides how many
 * values {@code rng.pick} draws against — so two clients rolling one seed
 * against two different quest sets diverge from the first pick, then vote by
 * INDEX on boards they never saw. Party contracts are binding.
 *
 * That is why quest state is TRANSMITTED and intersected rather than read
 * locally, and why everything below is pinned: the agreed set must be a pure
 * function of the transmitted lists and the transmitted protocols, order must
 * not matter, and every unclear answer must withhold monsters rather than
 * offer them.
 *
 * Statics only, like {@link PartySizingChoiceTest}: executeRoll needs a Client,
 * a PartyService and a live proposal.
 */
public class PartyQuestGateTest
{
	private static final int OLD = PartyRollService.ROLL_PROTOCOL_SIZING_CHOICE;
	private static final int NOW = PartyRollService.ROLL_PROTOCOL_QUEST_GATE;

	private static List<MonsterTable.Monster> monsters;

	private final Gson gson = new Gson();

	@BeforeClass
	public static void load() throws Exception
	{
		try (InputStreamReader reader = new InputStreamReader(
			PartyQuestGateTest.class.getResourceAsStream("/com/gachaman/data/monsters.json"),
			StandardCharsets.UTF_8))
		{
			monsters = new Gson().fromJson(reader, MonstersShape.class).monsters;
		}
	}

	private static class MonstersShape
	{
		List<MonsterTable.Monster> monsters;
	}

	private static List<Integer> protocols(int... values)
	{
		List<Integer> list = new ArrayList<>(values.length);
		for (int value : values)
		{
			list.add(value);
		}
		return list;
	}

	// --- A. the intersection ------------------------------------------------

	@Test
	public void onlyQuestsTheWholePartyHasFinishedSurvive()
	{
		List<List<String>> perMember = Arrays.asList(
			Arrays.asList("PRIEST_IN_PERIL", "LOST_CITY", "DRAGON_SLAYER_I"),
			Arrays.asList("PRIEST_IN_PERIL", "LOST_CITY"),
			Arrays.asList("PRIEST_IN_PERIL", "REGICIDE"));
		Assert.assertEquals(Set.of("PRIEST_IN_PERIL"),
			PartyRollService.agreedQuests(perMember, protocols(NOW, NOW, NOW)));
	}

	@Test
	public void oneMemberWhoHasDoneNothingGatesTheWholeParty()
	{
		// the point of the feature: three maxed accounts do not get to sign a
		// contract on a monster the fourth cannot walk up to
		List<List<String>> perMember = Arrays.asList(
			Arrays.asList("PRIEST_IN_PERIL", "LOST_CITY"),
			Arrays.asList("PRIEST_IN_PERIL", "LOST_CITY"),
			Collections.emptyList());
		Assert.assertEquals(Collections.emptySet(),
			PartyRollService.agreedQuests(perMember, protocols(NOW, NOW, NOW)));
	}

	@Test
	public void aPartyThatAllFinishedTheSameQuestsKeepsThemAll()
	{
		List<List<String>> perMember = Arrays.asList(
			Arrays.asList("PRIEST_IN_PERIL", "LOST_CITY"),
			Arrays.asList("LOST_CITY", "PRIEST_IN_PERIL"));
		Assert.assertEquals(Set.of("PRIEST_IN_PERIL", "LOST_CITY"),
			PartyRollService.agreedQuests(perMember, protocols(NOW, NOW)));
	}

	@Test
	public void orderDoesNotChangeTheAgreedSet()
	{
		// the roster iterates in whatever order each client's map happens to
		// hold, and each member's own list is sorted by its own TreeSet — so
		// neither order may reach the pool filter
		List<List<String>> ab = Arrays.asList(
			Arrays.asList("LOST_CITY", "PRIEST_IN_PERIL", "REGICIDE"),
			Arrays.asList("REGICIDE", "LOST_CITY"));
		List<List<String>> ba = Arrays.asList(
			Arrays.asList("LOST_CITY", "REGICIDE"),
			Arrays.asList("REGICIDE", "PRIEST_IN_PERIL", "LOST_CITY"));
		Assert.assertEquals(PartyRollService.agreedQuests(ab, protocols(NOW, NOW)),
			PartyRollService.agreedQuests(ba, protocols(NOW, NOW)));
		Assert.assertEquals(Set.of("LOST_CITY", "REGICIDE"),
			PartyRollService.agreedQuests(ab, protocols(NOW, NOW)));
	}

	@Test
	public void aSoloMemberIsItsOwnAgreedSet()
	{
		Assert.assertEquals(Set.of("PRIEST_IN_PERIL"), PartyRollService.agreedQuests(
			Collections.singletonList(Arrays.asList("PRIEST_IN_PERIL")), protocols(NOW)));
	}

	@Test
	public void aDuplicateNameIsNotAnExtraVote()
	{
		// a member listing the same quest twice must not survive an intersection
		// with a member who never did it
		List<List<String>> perMember = Arrays.asList(
			Arrays.asList("LOST_CITY", "LOST_CITY"),
			Arrays.asList("PRIEST_IN_PERIL"));
		Assert.assertEquals(Collections.emptySet(),
			PartyRollService.agreedQuests(perMember, protocols(NOW, NOW)));
	}

	// --- B. every unclear answer withholds ----------------------------------

	@Test
	public void aMemberWhoSentNoListCountsAsHavingFinishedNothing()
	{
		// on the current protocol a null is a bug, not a legacy client — and the
		// safe reading of a bug is "offer less", never "offer on the strength of
		// a value nobody sent"
		List<List<String>> perMember = Arrays.asList(
			Arrays.asList("PRIEST_IN_PERIL", "LOST_CITY"),
			null);
		Assert.assertEquals(Collections.emptySet(),
			PartyRollService.agreedQuests(perMember, protocols(NOW, NOW)));
	}

	@Test
	public void anEmptyRosterGatesNothingRatherThanEverything()
	{
		// null means "no gating" (roll the whole table), which is only correct
		// because there is no member to gate on — a roll with no stances never
		// reaches the pool filter anyway
		Assert.assertNull(PartyRollService.agreedQuests(null, protocols(NOW)));
		Assert.assertNull(PartyRollService.agreedQuests(
			Collections.emptyList(), protocols(NOW)));
	}

	@Test
	public void theAgreedSetCannotBeMutatedByItsCaller()
	{
		Set<String> agreed = PartyRollService.agreedQuests(
			Arrays.asList(Arrays.asList("LOST_CITY"), Arrays.asList("LOST_CITY")),
			protocols(NOW, NOW));
		Assert.assertNotNull(agreed);
		try
		{
			agreed.add("PRIEST_IN_PERIL");
			Assert.fail("the agreed set is read by the pool filter and must not be writable");
		}
		catch (UnsupportedOperationException expected)
		{
			// the board would change under one client and not the others
		}
	}

	// --- C. the protocol gate is all-or-nothing -----------------------------

	@Test
	public void oneOlderClientPutsTheWholePartyOnTheUnfilteredTable()
	{
		List<List<String>> perMember = Arrays.asList(
			Arrays.asList("PRIEST_IN_PERIL"),
			Arrays.asList("PRIEST_IN_PERIL"),
			null); // an older build sends no field at all
		Assert.assertFalse(PartyRollService.questGateAgreed(protocols(NOW, NOW, OLD)));
		// null, NOT the empty set: an unaware client filters on nothing, and the
		// fallback has to be what THAT client computes or the boards diverge
		Assert.assertNull(PartyRollService.agreedQuests(perMember, protocols(NOW, NOW, OLD)));
	}

	@Test
	public void theGateNeedsEveryoneAndAnUnknownRosterIsNotEveryone()
	{
		Assert.assertTrue(PartyRollService.questGateAgreed(protocols(NOW, NOW)));
		Assert.assertFalse(PartyRollService.questGateAgreed(protocols(NOW, 0)));
		Assert.assertFalse(PartyRollService.questGateAgreed(protocols(OLD)));
		Assert.assertFalse(PartyRollService.questGateAgreed(null));
		Assert.assertFalse(PartyRollService.questGateAgreed(Collections.emptyList()));
		// a FUTURE build still filters quests, so it must not be read as legacy
		Assert.assertTrue(PartyRollService.questGateAgreed(protocols(NOW, NOW + 7)));
	}

	@Test
	public void theOlderGatesStillHoldOnAQuestGatingParty()
	{
		// the protocol is one ladder, so shipping rung 3 must not quietly drop
		// rungs 1 and 2 for a party that is entirely on the current build
		Assert.assertTrue(PartyRollService.meanSizingAgreed(protocols(NOW, NOW)));
		Assert.assertTrue(PartyRollService.sizingChoiceAgreed(protocols(NOW, NOW)));
	}

	// --- D. the reason all of the above matters -----------------------------

	@Test
	public void twoClientsAgreeingOnQuestsDealTheSameBoardAndOtherwiseDoNot()
	{
		List<List<String>> perMember = Arrays.asList(
			Arrays.asList("PRIEST_IN_PERIL", "LOST_CITY"),
			Arrays.asList("LOST_CITY", "PRIEST_IN_PERIL"));
		Set<String> host = PartyRollService.agreedQuests(perMember, protocols(NOW, NOW));
		Set<String> guest = PartyRollService.agreedQuests(
			Arrays.asList(perMember.get(1), perMember.get(0)), protocols(NOW, NOW));
		Assert.assertEquals(board(host), board(guest));
		// and the gate really is what moves the board — otherwise this test
		// would pass just as well with the filter deleted
		Assert.assertNotEquals(board(host), board(Collections.emptySet()));
		Assert.assertNotEquals(board(host), board(null));
	}

	private static List<String> board(Set<String> completedQuests)
	{
		List<String> names = new ArrayList<>();
		for (TaskOffer offer : TaskGenerator.generateOffers(monsters, 100, 99, true,
			completedQuests, false, new GachaRng(31337L)))
		{
			names.add(offer.getMonsterName());
		}
		return names;
	}

	// --- E. the wire --------------------------------------------------------

	@Test
	public void questsRoundTripOnBothMessagesWithoutMovingTheOlderFields()
	{
		PartyRollProposeMessage propose = gson.fromJson(gson.toJson(
			new PartyRollProposeMessage(7L, 3L, true, 50, 12, "MAGIC", NOW,
				PartySizing.WEAKEST_MAN.name(), Arrays.asList("LOST_CITY", "PRIEST_IN_PERIL"), null)),
			PartyRollProposeMessage.class);
		Assert.assertEquals(Arrays.asList("LOST_CITY", "PRIEST_IN_PERIL"),
			propose.getCompletedQuests());
		// appending a field is only safe if it appended — @AllArgsConstructor is
		// positional, so a field inserted above shifts every existing call site
		Assert.assertEquals(7L, propose.getProposalId());
		Assert.assertEquals(3L, propose.getSeedCandidate());
		Assert.assertTrue(propose.isMembers());
		Assert.assertEquals(50, propose.getCombatLevel());
		Assert.assertEquals(12, propose.getSlayerLevel());
		Assert.assertEquals("MAGIC", propose.getAllowedStyle());
		Assert.assertEquals(NOW, propose.getRollProtocol());
		Assert.assertEquals(PartySizing.WEAKEST_MAN.name(), propose.getSizingMode());

		PartyRollResponseMessage response = gson.fromJson(gson.toJson(
			new PartyRollResponseMessage(7L, PartyRollResponseMessage.AGREE, 3L, true, 50, 12,
				"RANGED", NOW, Arrays.asList("REGICIDE"), null)), PartyRollResponseMessage.class);
		Assert.assertEquals(Arrays.asList("REGICIDE"), response.getCompletedQuests());
		Assert.assertEquals(PartyRollResponseMessage.AGREE, response.getResponse());
		Assert.assertEquals("RANGED", response.getAllowedStyle());
		Assert.assertEquals(NOW, response.getRollProtocol());
	}

	@Test
	public void anOlderClientsMessageLeavesTheQuestListNullNotEmpty()
	{
		// null and empty are NOT interchangeable here: null rides through to the
		// protocol check and falls the party back to the unfiltered table, while
		// empty would claim a member who has genuinely finished nothing
		PartyRollProposeMessage propose = gson.fromJson(
			"{\"proposalId\":7,\"seedCandidate\":3,\"members\":true,\"combatLevel\":50,"
				+ "\"slayerLevel\":12,\"allowedStyle\":\"MAGIC\",\"rollProtocol\":2,"
				+ "\"sizingMode\":\"WEAKEST_MAN\"}", PartyRollProposeMessage.class);
		Assert.assertNull(propose.getCompletedQuests());
		Assert.assertEquals(OLD, propose.getRollProtocol());

		PartyRollResponseMessage response = gson.fromJson(
			"{\"proposalId\":7,\"response\":0,\"seedCandidate\":3,\"members\":true,"
				+ "\"combatLevel\":50,\"slayerLevel\":12,\"rollProtocol\":2}",
			PartyRollResponseMessage.class);
		Assert.assertNull(response.getCompletedQuests());
	}

	@Test
	public void anEmptyListSurvivesTheWireAsAnEmptyList()
	{
		// the questless account's answer must not be flattened into "no answer"
		// by a round trip, or it would read as a legacy client and unlock the
		// very monsters it cannot reach
		PartyRollResponseMessage response = gson.fromJson(gson.toJson(
			new PartyRollResponseMessage(7L, PartyRollResponseMessage.AGREE, 3L, true, 50, 12,
				null, NOW, Collections.emptyList(), null)), PartyRollResponseMessage.class);
		Assert.assertNotNull(response.getCompletedQuests());
		Assert.assertTrue(response.getCompletedQuests().isEmpty());
	}
}

package com.gachaman.data;

import com.gachaman.*;
import com.google.gson.*;
import org.junit.*;

/**
 * Tier reach: the dhide and robes ladders rank by power, not by level, so they
 * carry real requirements in tiers.json instead of borrowing metal's rank table.
 * ChestService.isReachable cannot be tested directly — it returns true whenever
 * Client is null, which is every headless test — so the comparison lives in
 * Tuning.withinReach and is pinned here.
 */
public class TierRequirementTest
{
	private static final String[] LADDER_TIERS = {
		"bronze", "iron", "steel", "black", "white", "mithril", "adamant", "rune", "granite", "dragon",
		"leather", "hardleather", "studded", "snakeskin", "frog_leather",
		"green_dhide", "blue_dhide", "red_dhide", "black_dhide",
		"wizard", "xerician", "mystic", "enchanted", "splitbark", "infinity", "ancestral"};

	private TierTable table()
	{
		return TierTable.load(new Gson());
	}

	/**
	 * The load-bearing guard. A tier that loses its requirements falls back to the
	 * fail-closed sentinel and drops out of every gated roll — and pickCardOfRarity's
	 * unfiltered fallback would then mask that as "the gate quietly stopped working".
	 */
	@Test
	public void everyTierLoadsWithRequirements()
	{
		TierTable tiers = table();
		for (String tierKey : LADDER_TIERS)
		{
			Assert.assertNotEquals(tierKey + " has no reqLevel in tiers.json",
				99, tiers.reqLevelOf(tierKey));
			Assert.assertNotEquals(tierKey + " has no reqDefence in tiers.json",
				99, tiers.reqDefenceOf(tierKey));
			Assert.assertTrue(tierKey + " reqLevel must be >= 1", tiers.reqLevelOf(tierKey) >= 1);
			Assert.assertTrue(tierKey + " reqDefence must be >= 1", tiers.reqDefenceOf(tierKey) >= 1);
		}
	}

	/** An unannotated tier must fail closed (out of reach), never open at level 1. */
	@Test
	public void unknownTierFailsClosed()
	{
		Assert.assertEquals(99, table().reqLevelOf("no-such-tier"));
		Assert.assertEquals(99, table().reqDefenceOf("no-such-tier"));
	}

	/** Pinned against the wiki, so a data typo cannot silently reopen the gate. */
	@Test
	public void requirementsMatchRealOsrs()
	{
		TierTable t = table();
		Assert.assertEquals(1, t.reqLevelOf("iron"));
		Assert.assertEquals(5, t.reqLevelOf("steel"));
		Assert.assertEquals(10, t.reqLevelOf("black"));
		Assert.assertEquals(20, t.reqLevelOf("mithril"));
		Assert.assertEquals(40, t.reqLevelOf("rune"));
		Assert.assertEquals(50, t.reqLevelOf("granite"));
		Assert.assertEquals(60, t.reqLevelOf("dragon"));

		Assert.assertEquals(1, t.reqLevelOf("leather"));
		Assert.assertEquals(1, t.reqLevelOf("hardleather"));
		Assert.assertEquals(10, t.reqDefenceOf("hardleather"));
		Assert.assertEquals(20, t.reqLevelOf("studded"));
		Assert.assertEquals(30, t.reqLevelOf("snakeskin"));
		Assert.assertEquals(40, t.reqLevelOf("green_dhide"));
		Assert.assertEquals(70, t.reqLevelOf("black_dhide"));

		Assert.assertEquals(1, t.reqLevelOf("wizard"));
		Assert.assertEquals(20, t.reqLevelOf("xerician"));
		Assert.assertEquals(10, t.reqDefenceOf("xerician"));
		Assert.assertEquals(40, t.reqLevelOf("mystic"));
		Assert.assertEquals(20, t.reqDefenceOf("mystic"));
		Assert.assertEquals(40, t.reqDefenceOf("splitbark"));
		Assert.assertEquals(50, t.reqLevelOf("infinity"));
		Assert.assertEquals(25, t.reqDefenceOf("infinity"));
		Assert.assertEquals(75, t.reqLevelOf("ancestral"));
		Assert.assertEquals(65, t.reqDefenceOf("ancestral"));
	}

	/**
	 * A higher rank must never be cheaper than a lower one on the same ladder.
	 * Compared pairwise rather than as a sorted run because ranks are not unique —
	 * black/white share 4, rune/granite share 7, snakeskin/frog_leather share 4.
	 */
	@Test
	public void requirementsRiseWithRankWithinEachLadder()
	{
		TierTable t = table();
		for (String a : LADDER_TIERS)
		{
			for (String b : LADDER_TIERS)
			{
				if (!java.util.Objects.equals(t.ladderOf(a), t.ladderOf(b))
					|| t.rankOf(a) >= t.rankOf(b))
				{
					continue;
				}
				Assert.assertTrue(a + " (rank " + t.rankOf(a) + ") requires more than "
						+ b + " (rank " + t.rankOf(b) + ")",
					t.reqLevelOf(a) <= t.reqLevelOf(b));
			}
		}
	}

	/**
	 * Regression pin for B2-tier-clamp. Under the old rank table these three resolved
	 * to 1, 10 and 1 respectively, which is what let a level-1 account roll them.
	 */
	@Test
	public void regressionB2TierClamp()
	{
		TierTable t = table();
		Assert.assertTrue("xerician must not read as a level-1 tier", t.reqLevelOf("xerician") >= 20);
		Assert.assertTrue("mystic must not read as a level-10 tier", t.reqLevelOf("mystic") >= 40);
		Assert.assertTrue("hardleather body needs 10 Defence", t.reqDefenceOf("hardleather") >= 10);
	}

	// --- display names, as printed by the Chest Odds disclosure ---

	/**
	 * The odds panel prints one row per tier, so a tier with no label would show up as
	 * a raw key with an underscore in it. Names are harvested from the hologram entries
	 * rather than authored twice, which is what this guards.
	 */
	@Test
	public void everyLadderTierHasADisplayName()
	{
		TierTable t = table();
		for (String tierKey : LADDER_TIERS)
		{
			String name = t.displayNameOf(tierKey);
			Assert.assertNotNull(tierKey + " has no display name", name);
			Assert.assertFalse(tierKey + " has an empty display name", name.isEmpty());
			Assert.assertFalse(tierKey + " leaks its raw key into the UI", name.contains("_"));
			Assert.assertFalse(tierKey + " kept the \" Hologram\" suffix", name.endsWith("Hologram"));
		}
	}

	/** A tier authored without a hologram must still read as words, not as a key. */
	@Test
	public void unknownTierFallsBackToWords()
	{
		Assert.assertEquals("No Such Tier", table().displayNameOf("no_such_tier"));
	}

	// --- the reach comparison itself ---

	/**
	 * The headline symptom: a fresh account must stop rolling Mystic (40 Magic) and
	 * Xerician (20 Magic), and Snakeskin/Studded on the dhide side.
	 */
	@Test
	public void freshAccountCannotReachMidLadderRobesOrDhide()
	{
		int h = Tuning.ROLL_LEVEL_HEADROOM;
		Assert.assertFalse("mystic at Magic 1", Tuning.withinReach(1, 1, 40, 20, h));
		Assert.assertFalse("xerician at Magic 1", Tuning.withinReach(1, 1, 20, 10, h));
		Assert.assertFalse("splitbark at Magic 1", Tuning.withinReach(1, 1, 40, 40, h));
		Assert.assertFalse("studded at Ranged 1", Tuning.withinReach(1, 1, 20, 20, h));
		Assert.assertFalse("snakeskin at Ranged 1", Tuning.withinReach(1, 1, 30, 30, h));
	}

	/**
	 * Headroom still has to feel aspirational, not dead: hardleather (10 Defence) stays
	 * rollable on a fresh account, the dhide analogue of black metal at level 1.
	 */
	@Test
	public void headroomStillReachesTheNextStepUp()
	{
		int h = Tuning.ROLL_LEVEL_HEADROOM;
		Assert.assertTrue("leather", Tuning.withinReach(1, 1, 1, 1, h));
		Assert.assertTrue("hardleather body", Tuning.withinReach(1, 1, 1, 10, h));
	}

	/**
	 * The Rusty pool calls isReachable with no headroom, so at level 1 only genuinely
	 * level-1 tiers may survive. Xerician top and Hardleather body both passed before.
	 */
	@Test
	public void rustyPoolAdmitsOnlyLevelOneGear()
	{
		Assert.assertTrue("leather / wizard", Tuning.withinReach(1, 1, 1, 1, 0));
		Assert.assertFalse("xerician top", Tuning.withinReach(1, 1, 20, 10, 0));
		Assert.assertFalse("hardleather body", Tuning.withinReach(1, 1, 1, 10, 0));
	}

	/** A maxed Ranged, level-1 Defence account is still blocked from splitbark-style gear. */
	@Test
	public void defenceIsEnforcedIndependentlyOfThePrimarySkill()
	{
		Assert.assertFalse(Tuning.withinReach(99, 1, 1, 40, 0));
	}

	/**
	 * D'hide chaps and vambraces carry no Defence requirement while the body needs 40.
	 * ChestService applies reqDefence to BODY only; this pins the resulting arithmetic
	 * (the slot branch itself needs a Client and cannot be tested).
	 */
	@Test
	public void dhideAccessoriesIgnoreTheBodyDefenceRequirement()
	{
		// Ranged 50 / Defence 1: blue d'hide chaps yes, blue d'hide body no
		Assert.assertTrue("blue d'hide chaps", Tuning.withinReach(50, 1, 50, 1, 0));
		Assert.assertFalse("blue d'hide body", Tuning.withinReach(50, 1, 50, 40, 0));
	}

	/**
	 * Metal is deliberately NOT retuned by this fix — TIER_RANK_LEVELS transcribes the
	 * melee ladder exactly, so metal was already correct. Pin the whole reach curve so
	 * a later change to the reach model cannot quietly move it. Values are the highest
	 * metal rank a gated roll may land on at each level.
	 */
	@Test
	public void metalReachCurveIsUnchanged()
	{
		int[][] levelToMaxRank = {{1, 4}, {5, 5}, {10, 6}, {20, 7}, {30, 8}, {40, 9}, {50, 9}, {60, 10}};
		for (int[] row : levelToMaxRank)
		{
			Assert.assertEquals("metal reach moved at level " + row[0], row[1],
				Tuning.maxRankForLevel(row[0]) + Tuning.ROLL_TIER_HEADROOM);
		}
	}

	/**
	 * Regression pin for the fix that was rejected: metal resolves on
	 * max(ATTACK, DEFENCE) because metal weapons gate on Attack and metal armour on
	 * Defence, never both. A 60 Attack / 1 Defence pure must still reach rune (rank 7)
	 * and dragon (rank 8) weapons, with and without headroom.
	 */
	@Test
	public void attackPureStillReachesHighMetal()
	{
		int metalLevel = Math.max(60, 1);
		Assert.assertTrue("rune, no headroom", 7 <= Tuning.maxRankForLevel(metalLevel));
		Assert.assertTrue("dragon, with headroom",
			8 <= Tuning.maxRankForLevel(metalLevel) + Tuning.ROLL_TIER_HEADROOM);
		// and the ordinary mid-game case the rejected fix also broke
		Assert.assertTrue("rune at 40 Attack / 20 Defence",
			7 <= Tuning.maxRankForLevel(Math.max(40, 20)) + Tuning.ROLL_TIER_HEADROOM);
	}
}

package com.gachaman.data;

import com.gachaman.*;
import com.google.gson.*;
import org.junit.*;

/**
 * Metal-prefixed ranged gear: classified onto the metal ladder by name prefix, but
 * gated on Ranged and — for crossbows, bolts, javelins and the dragon thrownaxe — on
 * numbers the metal ladder does not carry.
 *
 * <p>ChestService.isReachable and LoadoutService.styleOf both dereference Client, which
 * is null in every headless test, so the decision itself lives in this pure enum and is
 * pinned here. Requirements are the LAUNCHER's: ammunition has no equip requirement at
 * all, so the number a player actually feels for rune arrows is the yew bow's 40.
 */
public class RangedMetalTest
{
	/**
	 * The table is injected in the plugin (the Plugin Hub forbids a fresh Gson
	 * in shipped code); a test builds its own because there is no injector here.
	 */
	private static final RangedMetal.Lookup METAL = new RangedMetal.Lookup(new Gson());

	private TierTable table()
	{
		return TierTable.load(new Gson());
	}

	/** The reported symptom: these four all wear a metal prefix and are Ranged gear. */
	@Test
	public void metalPrefixedRangedGearIsRecognised()
	{
		Assert.assertEquals(RangedMetal.ARROW, METAL.of("Rune arrow"));
		Assert.assertEquals(RangedMetal.DART, METAL.of("Adamant dart"));
		Assert.assertEquals(RangedMetal.KNIFE, METAL.of("Mithril knife"));
		Assert.assertEquals(RangedMetal.BOLTS, METAL.of("Bronze bolts"));
		Assert.assertEquals(RangedMetal.CROSSBOW, METAL.of("Rune crossbow"));
		Assert.assertEquals(RangedMetal.JAVELIN, METAL.of("Adamant javelin"));
		Assert.assertEquals(RangedMetal.THROWNAXE, METAL.of("Iron thrownaxe"));
	}

	/** Both spellings ship in-game — "Rune arrow" is singular, "Bronze bolts" is plural. */
	@Test
	public void bothSingularAndPluralHeadNounsMatch()
	{
		Assert.assertEquals(RangedMetal.ARROW, METAL.of("Rune arrows"));
		Assert.assertEquals(RangedMetal.BOLTS, METAL.of("Runite bolt"));
		Assert.assertEquals(RangedMetal.KNIFE, METAL.of("Rune knives"));
		Assert.assertEquals(RangedMetal.DART, METAL.of("Rune darts"));
		Assert.assertEquals(RangedMetal.JAVELIN, METAL.of("Rune javelins"));
		Assert.assertEquals(RangedMetal.THROWNAXE, METAL.of("Rune thrownaxes"));
		Assert.assertEquals(RangedMetal.CROSSBOW, METAL.of("Rune crossbows"));
	}

	/**
	 * The load-bearing negative. Melee metal must stay melee — misfiring here would
	 * gate every platebody in the game on Ranged, which is far worse than the bug.
	 */
	@Test
	public void ordinaryMetalGearIsNotRanged()
	{
		String[] melee = {"Rune platebody", "Rune scimitar", "Dragon dagger", "Adamant full helm",
			"Bronze med helm", "Mithril kiteshield", "Rune 2h sword", "Black chainbody",
			"Steel battleaxe", "Granite maul", "Iron boots", "White platelegs"};
		for (String name : melee)
		{
			Assert.assertNull(name + " must not read as ranged gear", METAL.of(name));
		}
	}

	/** Nulls, single words and empty strings reach here from card names — none may throw. */
	@Test
	public void degenerateNamesAreSafe()
	{
		Assert.assertNull(METAL.of(null));
		Assert.assertNull(METAL.of(""));
		Assert.assertNull(METAL.of("Arrow"));   // no prefix at all
		Assert.assertNull(METAL.of("Seercull"));
	}

	/**
	 * CardDatabase.cleanName strips every trailing parenthetical before a name reaches
	 * here, so the poisoned and enchanted variants arrive already normalised.
	 */
	@Test
	public void poisonedAndEnchantedVariantsAreAlreadyCleaned()
	{
		Assert.assertEquals(RangedMetal.DART, METAL.of(CardDatabase.cleanName("Rune dart(p++)")));
		Assert.assertEquals(RangedMetal.KNIFE, METAL.of(CardDatabase.cleanName("Adamant knife(p+)")));
		Assert.assertEquals(RangedMetal.BOLTS, METAL.of(CardDatabase.cleanName("Runite bolts (e)")));
	}

	// --- the numbers, pinned against the wiki ---

	/** Darts and knives are the only families that ride the metal ladder exactly. */
	@Test
	public void dartsAndKnivesFollowTheMetalLadder()
	{
		TierTable t = table();
		String[] tiers = {"bronze", "iron", "steel", "black", "mithril", "adamant", "rune", "dragon"};
		for (String tier : tiers)
		{
			Assert.assertEquals(tier + " dart", t.reqLevelOf(tier),
				METAL.reqRangedLevel(RangedMetal.DART, tier, 99));
			Assert.assertEquals(tier + " knife", t.reqLevelOf(tier),
				METAL.reqRangedLevel(RangedMetal.KNIFE, tier, 99));
		}
	}

	/**
	 * Crossbows barely touch the ladder — only bronze matches. A rune crossbow is 61,
	 * not 40, and bolts inherit the number from the crossbow that fires them.
	 */
	@Test
	public void crossbowsAndBoltsDivergeFromTheLadder()
	{
		Assert.assertEquals(1, METAL.reqRangedLevel(RangedMetal.CROSSBOW, "bronze", 99));
		Assert.assertEquals(26, METAL.reqRangedLevel(RangedMetal.CROSSBOW, "iron", 99));
		Assert.assertEquals(31, METAL.reqRangedLevel(RangedMetal.CROSSBOW, "steel", 99));
		Assert.assertEquals(36, METAL.reqRangedLevel(RangedMetal.CROSSBOW, "mithril", 99));
		Assert.assertEquals(46, METAL.reqRangedLevel(RangedMetal.CROSSBOW, "adamant", 99));
		Assert.assertEquals(61, METAL.reqRangedLevel(RangedMetal.CROSSBOW, "rune", 99));
		Assert.assertEquals(64, METAL.reqRangedLevel(RangedMetal.CROSSBOW, "dragon", 99));
		// bolts are gated by their launcher, so the two families read identically
		for (String tier : new String[]{"bronze", "iron", "steel", "mithril", "adamant", "rune", "dragon"})
		{
			Assert.assertEquals(tier + " bolts track the crossbow",
				METAL.reqRangedLevel(RangedMetal.CROSSBOW, tier, 99),
				METAL.reqRangedLevel(RangedMetal.BOLTS, tier, 99));
		}
	}

	/** Every javelin is ballista-exclusive at 65, whatever the metal says. */
	@Test
	public void everyJavelinIsBallistaGated()
	{
		for (String tier : new String[]{"bronze", "iron", "steel", "mithril", "adamant", "rune", "dragon"})
		{
			Assert.assertEquals(tier + " javelin", 65, METAL.reqRangedLevel(RangedMetal.JAVELIN, tier, 99));
		}
	}

	/** The one off-by-one in an otherwise exact family. */
	@Test
	public void dragonThrownaxeIsSixtyOne()
	{
		Assert.assertEquals(61, METAL.reqRangedLevel(RangedMetal.THROWNAXE, "dragon", 99));
		Assert.assertEquals(60, METAL.reqRangedLevel(RangedMetal.DART, "dragon", 99));
	}

	/**
	 * Black exists only as a dart and a knife; there is no black arrow, bolt, javelin or
	 * thrownaxe, and no white ranged item at all. A metal with no item in the family must
	 * fall back to the caller's number rather than silently opening at level 1.
	 */
	@Test
	public void absentMetalsFallBackInsteadOfOpeningUp()
	{
		Assert.assertEquals(10, METAL.reqRangedLevel(RangedMetal.DART, "black", 99));
		Assert.assertEquals(10, METAL.reqRangedLevel(RangedMetal.KNIFE, "black", 99));
		Assert.assertEquals(99, METAL.reqRangedLevel(RangedMetal.ARROW, "black", 99));
		Assert.assertEquals(99, METAL.reqRangedLevel(RangedMetal.BOLTS, "black", 99));
		Assert.assertEquals(99, METAL.reqRangedLevel(RangedMetal.THROWNAXE, "black", 99));
		// white and granite are melee-only tiers, and an unknown/null tier must not open either
		Assert.assertEquals(99, METAL.reqRangedLevel(RangedMetal.ARROW, "white", 99));
		Assert.assertEquals(99, METAL.reqRangedLevel(RangedMetal.ARROW, "granite", 99));
		Assert.assertEquals(99, METAL.reqRangedLevel(RangedMetal.ARROW, "no-such-tier", 99));
		Assert.assertEquals(99, METAL.reqRangedLevel(RangedMetal.ARROW, null, 99));
	}

	/** No ranged item may read as harder than the hardest thing in the game. */
	@Test
	public void everyRequirementIsALegalLevel()
	{
		for (RangedMetal family : RangedMetal.values())
		{
			for (String tier : new String[]{"bronze", "iron", "steel", "black", "mithril",
				"adamant", "rune", "dragon"})
			{
				int req = METAL.reqRangedLevel(family, tier, 1);
				Assert.assertTrue(family + "/" + tier + " = " + req, req >= 1 && req <= 99);
			}
		}
	}

	/** Within a family, a higher metal never costs less than a lower one. */
	@Test
	public void requirementsRiseWithTheMetal()
	{
		String[] ladder = {"bronze", "iron", "steel", "mithril", "adamant", "rune", "dragon"};
		for (RangedMetal family : RangedMetal.values())
		{
			for (int i = 1; i < ladder.length; i++)
			{
				Assert.assertTrue(family + ": " + ladder[i] + " must not be cheaper than " + ladder[i - 1],
					METAL.reqRangedLevel(family, ladder[i], 1) >= METAL.reqRangedLevel(family, ladder[i - 1], 1));
			}
		}
	}

	// --- the reach decision ChestService makes with these numbers ---

	/**
	 * The headline case. A 40 Ranged / 1 Attack / 1 Defence archer must reach adamant
	 * arrows (30) and rune arrows (40) — under the old max(Attack, Defence) read it
	 * reached neither, because its melee levels were 1.
	 */
	@Test
	public void archerReachesTheAmmoItActuallyShoots()
	{
		int h = Tuning.ROLL_LEVEL_HEADROOM;
		Assert.assertTrue("adamant arrows at 40 Ranged", Tuning.withinReach(40, 1,
			METAL.reqRangedLevel(RangedMetal.ARROW, "adamant", 99), 1, h));
		Assert.assertTrue("rune arrows at 40 Ranged", Tuning.withinReach(40, 1,
			METAL.reqRangedLevel(RangedMetal.ARROW, "rune", 99), 1, h));
		Assert.assertTrue("mithril knives at 40 Ranged", Tuning.withinReach(40, 1,
			METAL.reqRangedLevel(RangedMetal.KNIFE, "mithril", 99), 1, h));
	}

	/** And the mirror: a 40 Attack meleer must stop rolling ammunition it owns no bow for. */
	@Test
	public void meleerNoLongerRollsAmmoItCannotFire()
	{
		int h = Tuning.ROLL_LEVEL_HEADROOM;
		Assert.assertFalse("rune arrows at Ranged 1", Tuning.withinReach(1, 40,
			METAL.reqRangedLevel(RangedMetal.ARROW, "rune", 99), 1, h));
		Assert.assertFalse("rune crossbow at Ranged 1", Tuning.withinReach(1, 99,
			METAL.reqRangedLevel(RangedMetal.CROSSBOW, "rune", 99), 1, h));
	}

	/**
	 * No ranged weapon or ammunition carries a Defence gate, so a 1 Defence pure must
	 * reach everything its Ranged level allows.
	 */
	@Test
	public void rangedGearNeverGatesOnDefence()
	{
		Assert.assertTrue("dragon crossbow at 64 Ranged / 1 Defence",
			Tuning.withinReach(64, 1, METAL.reqRangedLevel(RangedMetal.CROSSBOW, "dragon", 99), 1, 0));
		Assert.assertTrue("rune javelin at 65 Ranged / 1 Defence",
			Tuning.withinReach(65, 1, METAL.reqRangedLevel(RangedMetal.JAVELIN, "rune", 99), 1, 0));
	}

	/**
	 * The divergence that motivated encoding real numbers instead of re-reading the
	 * ladder as Ranged: at 45 Ranged the ladder would have handed over a rune crossbow.
	 */
	@Test
	public void ladderAsRangedWouldStillHaveBeenWrongForCrossbows()
	{
		TierTable t = table();
		Assert.assertTrue("the ladder says rune is 40", Tuning.withinReach(45, 1,
			t.reqLevelOf("rune"), 1, 0));
		Assert.assertFalse("but a rune crossbow is 61", Tuning.withinReach(45, 1,
			METAL.reqRangedLevel(RangedMetal.CROSSBOW, "rune", 99), 1, 0));
	}

	/**
	 * "Runite bolts" is the one equipable item spelt the long way. "Runite" does not
	 * prefix-match "Rune" (4th char 'i' vs 'e'), so before it was added to the tier's
	 * prefixes the card landed untiered — no tier, no ladder, gated by nothing.
	 */
	@Test
	public void runiteBoltsAreTiered()
	{
		TierTable.Match match = table().match("Runite bolts");
		Assert.assertNotNull("Runite bolts must not be untiered", match);
		Assert.assertEquals("rune", match.getTierKey());
		Assert.assertEquals("bolts", match.getFamilyKey());
		Assert.assertEquals(61, METAL.reqRangedLevel(RangedMetal.BOLTS, match.getTierKey(), 99));
	}

	// --- the colour-prefixed impostors ---

	/**
	 * "Black chinchompa" and "Black salamander" are not black METAL — the prefix is a
	 * colour that happens to spell one. Both prefix-match the black tier exactly as a
	 * platebody does, so both were classified rank 4 and gated on max(Attack, Defence).
	 */
	@Test
	public void colourPrefixedImpostorsAreRecognisedAsRanged()
	{
		Assert.assertEquals(RangedMetal.CHINCHOMPA, METAL.of("Black chinchompa"));
		Assert.assertEquals(RangedMetal.SALAMANDER, METAL.of("Black salamander"));
	}

	/** The real wiki numbers: a chinchompa is 65 Ranged, a salamander 70. */
	@Test
	public void theImpostorsCarryTheirRealRequirement()
	{
		Assert.assertEquals(65, METAL.reqRangedLevel(RangedMetal.CHINCHOMPA, "black", 99));
		Assert.assertEquals(70, METAL.reqRangedLevel(RangedMetal.SALAMANDER, "black", 99));
	}

	/**
	 * They exist at black and nowhere else, so every other metal must fall back to the
	 * caller's number rather than inventing a mithril chinchompa at level 1.
	 */
	@Test
	public void theImpostorsExistAtBlackOnly()
	{
		for (String tier : new String[]{"bronze", "iron", "steel", "mithril", "adamant",
			"rune", "dragon", "white", "granite", "no-such-tier"})
		{
			Assert.assertEquals(tier + " chinchompa does not exist", 99,
				METAL.reqRangedLevel(RangedMetal.CHINCHOMPA, tier, 99));
			Assert.assertEquals(tier + " salamander does not exist", 99,
				METAL.reqRangedLevel(RangedMetal.SALAMANDER, tier, 99));
		}
		Assert.assertEquals(99, METAL.reqRangedLevel(RangedMetal.CHINCHOMPA, null, 99));
	}

	/**
	 * The defect itself, both halves. The black tier is rank 4 and reqLevel 10, so under
	 * the melee read a brand-new account cleared it outright — rank 4 &lt;= rank-for-level-1
	 * (2) + ROLL_TIER_HEADROOM (2) — and even with no headroom at all 10 Attack bought a
	 * weapon needing 65 Ranged. Read as Ranged, both refuse.
	 */
	@Test
	public void aFreshAccountNoLongerReachesABlackChinchompa()
	{
		TierTable.Match match = table().match("Black chinchompa");
		Assert.assertNotNull(match);
		Assert.assertEquals(4, match.getRank());
		// what the melee branch of ChestService.isReachable would have said
		Assert.assertTrue("the defect: rank 4 was inside a level-1 account's reach",
			match.getRank() <= Tuning.maxRankForLevel(1) + Tuning.ROLL_TIER_HEADROOM);
		Assert.assertTrue("and 10 Attack cleared it even with no headroom",
			match.getRank() <= Tuning.maxRankForLevel(10));

		int h = Tuning.ROLL_LEVEL_HEADROOM;
		int chin = METAL.reqRangedLevel(RangedMetal.CHINCHOMPA, match.getTierKey(), 99);
		Assert.assertFalse("1 Ranged must not reach a 65 Ranged weapon",
			Tuning.withinReach(1, 1, chin, 1, h));
		Assert.assertFalse("nor 99 Attack with no Ranged to speak of",
			Tuning.withinReach(1, 99, chin, 1, h));
		Assert.assertTrue("a 65 Ranged archer reaches it",
			Tuning.withinReach(65, 1, chin, 1, 0));
		Assert.assertTrue("and it stays aspirational inside the headroom band",
			Tuning.withinReach(56, 1, chin, 1, h));
	}

	/** Same story one tier of severity up: the salamander was 70, and was charging 10. */
	@Test
	public void aFreshAccountNoLongerReachesABlackSalamander()
	{
		int h = Tuning.ROLL_LEVEL_HEADROOM;
		int sala = METAL.reqRangedLevel(RangedMetal.SALAMANDER, 
			table().match("Black salamander").getTierKey(), 99);
		Assert.assertEquals(70, sala);
		Assert.assertFalse(Tuning.withinReach(1, 1, sala, 1, h));
		Assert.assertTrue(Tuning.withinReach(70, 1, sala, 1, 0));
	}

	/**
	 * Deliberately still tiered. Excluding the family in tiers.json would have worked too,
	 * but tierKey is written into the card cache — flipping it to null would change every
	 * user's stored classification and force a rescan, where fixing the READ costs nothing.
	 */
	@Test
	public void theImpostorsStayOnTheBlackTierSoTheCacheIsUntouched()
	{
		TierTable t = table();
		Assert.assertEquals("black", t.match("Black chinchompa").getTierKey());
		Assert.assertEquals("chinchompa", t.match("Black chinchompa").getFamilyKey());
		Assert.assertEquals("black", t.match("Black salamander").getTierKey());
		Assert.assertEquals("salamander", t.match("Black salamander").getFamilyKey());
		// and being tiered is what routes them to the metal ladder in the first place,
		// which is the only branch that consults RangedMetal at all
		Assert.assertEquals("metal", t.ladderOf("black"));
	}

	/**
	 * The siblings are untiered and therefore ungated, like every other exotic weapon.
	 * "Chinchompa" has no prefix; "Red chinchompa" matches no metal, because "Red d'hide"
	 * is the only Red prefix and it needs the whole "Red d'hide " to match.
	 */
	@Test
	public void theUntieredSiblingsAreLeftAlone()
	{
		TierTable t = table();
		Assert.assertNull("Chinchompa carries no prefix", t.match("Chinchompa"));
		Assert.assertNull("Red is not a metal", t.match("Red chinchompa"));
		Assert.assertNull("nor for the salamanders", t.match("Red salamander"));
		Assert.assertNull(t.match("Orange salamander"));
		Assert.assertNull(t.match("Swamp lizard"));
	}

	/** And the load-bearing negative: real black metal must not follow them across. */
	@Test
	public void blackMetalGearIsUndisturbed()
	{
		Assert.assertNull(METAL.of("Black platebody"));
		Assert.assertNull(METAL.of("Black scimitar"));
		Assert.assertNull(METAL.of("Black full helm"));
		Assert.assertEquals(RangedMetal.DART, METAL.of("Black dart"));
		Assert.assertEquals(RangedMetal.KNIFE, METAL.of("Black knife"));
		Assert.assertEquals(10, METAL.reqRangedLevel(RangedMetal.DART, "black", 99));
	}

	/** Adding that prefix must not disturb anything the short spelling already claimed. */
	@Test
	public void theShortSpellingStillMatches()
	{
		TierTable t = table();
		Assert.assertEquals("rune", t.match("Rune platebody").getTierKey());
		Assert.assertEquals("rune", t.match("Rune arrow").getTierKey());
		Assert.assertEquals("rune", t.match("Rune crossbow").getTierKey());
		Assert.assertEquals(7, t.match("Rune platebody").getRank());
		Assert.assertEquals(7, t.match("Runite bolts").getRank());
	}
}

package com.gachaman.data;

import com.gachaman.model.*;
import org.junit.*;

/**
 * Which style a weapon actually swings with, read off its offensive bonuses.
 * The First Colours gift promises the player something they can use in the
 * style they just rolled, so a wrong answer here is a broken promise.
 */
public class DominantStyleTest
{
	@Test
	public void meleeWinsOnAnyOfItsThreeAttackTypes()
	{
		// stab, slash and crush are three faces of one style — a weapon that
		// leads on any of them is a melee weapon
		Assert.assertEquals(AttackStyle.MELEE, CardDatabase.dominantStyle(40, 0, 0, 0, 0));
		Assert.assertEquals(AttackStyle.MELEE, CardDatabase.dominantStyle(0, 45, 0, 0, 0));
		Assert.assertEquals(AttackStyle.MELEE, CardDatabase.dominantStyle(0, 0, 55, 0, 0));
		// a warhammer's spread across all three still reads as one style
		Assert.assertEquals(AttackStyle.MELEE, CardDatabase.dominantStyle(10, 20, 65, 5, -4));
	}

	@Test
	public void rangedAndMagicWinOnTheirOwnBonus()
	{
		Assert.assertEquals(AttackStyle.RANGED, CardDatabase.dominantStyle(0, 0, 0, 30, 0));
		Assert.assertEquals(AttackStyle.MAGIC, CardDatabase.dominantStyle(0, 0, 0, 0, 25));
		// a shortbow's small melee stats must not outvote its actual purpose
		Assert.assertEquals(AttackStyle.RANGED, CardDatabase.dominantStyle(2, 3, 1, 30, 0));
		// a staff that can also bash still leads with magic
		Assert.assertEquals(AttackStyle.MAGIC, CardDatabase.dominantStyle(0, 5, 8, 0, 12));
	}

	@Test
	public void tiesAreRefusedRatherThanGuessed()
	{
		// gear that is not unambiguously one style's weapon is not a promise
		// worth making — better no steer at all than the wrong one
		Assert.assertNull(CardDatabase.dominantStyle(20, 0, 0, 20, 0));
		Assert.assertNull(CardDatabase.dominantStyle(0, 0, 0, 15, 15));
		Assert.assertNull(CardDatabase.dominantStyle(0, 9, 0, 0, 9));
		Assert.assertNull(CardDatabase.dominantStyle(7, 7, 7, 7, 7));
	}

	@Test
	public void noOffenceAtAllIsNotAWeapon()
	{
		// pure armour, and the shields/robes that carry a magic PENALTY: a
		// negative or zero best must never be dressed up as a style
		Assert.assertNull(CardDatabase.dominantStyle(0, 0, 0, 0, 0));
		Assert.assertNull(CardDatabase.dominantStyle(-1, -1, -1, -5, -20));
		Assert.assertNull(CardDatabase.dominantStyle(0, 0, 0, 0, -30));
	}

	@Test
	public void aNegativeBonusNeverWins()
	{
		// a melee weapon with the usual magic penalty is still melee, and a
		// staff with a melee penalty is still magic
		Assert.assertEquals(AttackStyle.MELEE, CardDatabase.dominantStyle(0, 32, 0, -2, -12));
		Assert.assertEquals(AttackStyle.MAGIC, CardDatabase.dominantStyle(-5, -5, -5, -5, 3));
		Assert.assertEquals(AttackStyle.RANGED, CardDatabase.dominantStyle(-8, -8, -8, 1, -8));
	}
}

