package com.gachaman.data;

import com.google.gson.*;
import java.io.*;
import java.nio.charset.*;
import java.util.*;
import org.junit.*;

/** The four bundled datasets must parse and cross-reference cleanly. */
public class DatasetIntegrityTest
{
	private static final Set<String> MONSTER_TAGS = Set.of(
		"starter", "giant", "demon", "dragon", "undead", "slayer", "wilderness", "tzhaar",
		"kalphite", "spider", "reptile", "avian", "fremennik", "desert", "morytania",
		"kourend", "varlamore", "elemental", "fairy", "goblinoid", "boss", "sailing");

	private JsonObject load(String name)
	{
		try (InputStreamReader reader = new InputStreamReader(
			getClass().getResourceAsStream("/com/gachaman/data/" + name), StandardCharsets.UTF_8))
		{
			return new Gson().fromJson(reader, JsonObject.class);
		}
		catch (Exception e)
		{
			throw new AssertionError("failed to load " + name, e);
		}
	}

	@Test
	public void tiersParseWithLaddersAndHolograms()
	{
		JsonObject tiers = load("tiers.json");
		JsonArray ladders = tiers.getAsJsonArray("ladders");
		Assert.assertTrue(ladders.size() >= 3);
		Set<String> tierKeys = new HashSet<>();
		for (JsonElement ladderEl : ladders)
		{
			JsonObject ladder = ladderEl.getAsJsonObject();
			for (JsonElement tierEl : ladder.getAsJsonArray("tiers"))
			{
				JsonObject tier = tierEl.getAsJsonObject();
				Assert.assertTrue(tier.get("rank").getAsInt() >= 1);
				Assert.assertTrue(tier.getAsJsonArray("prefixes").size() >= 1);
				// a tier with no requirements fails closed and vanishes from gated rolls
				String key = tier.get("tierKey").getAsString();
				Assert.assertTrue(key + " needs reqLevel", tier.has("reqLevel"));
				Assert.assertTrue(key + " needs reqDefence", tier.has("reqDefence"));
				Assert.assertTrue(key + " reqLevel >= 1", tier.get("reqLevel").getAsInt() >= 1);
				Assert.assertTrue(key + " reqDefence >= 1", tier.get("reqDefence").getAsInt() >= 1);
				tierKeys.add(key);
			}
		}
		JsonArray holograms = tiers.getAsJsonArray("hologramTiers");
		Assert.assertTrue(holograms.size() >= 10);
		for (JsonElement holoEl : holograms)
		{
			JsonObject holo = holoEl.getAsJsonObject();
			Assert.assertTrue("holo tier unknown: " + holo.get("tierKey"),
				tierKeys.contains(holo.get("tierKey").getAsString()));
			com.gachaman.model.Rarity.valueOf(holo.get("rarity").getAsString()); // must parse
		}
	}

	@Test
	public void monstersParseWithLegalTagsAndLevels()
	{
		JsonArray monsters = load("monsters.json").getAsJsonArray("monsters");
		Assert.assertTrue(monsters.size() >= 200);
		Set<String> names = new HashSet<>();
		for (JsonElement monsterEl : monsters)
		{
			JsonObject monster = monsterEl.getAsJsonObject();
			String name = monster.get("name").getAsString();
			Assert.assertTrue("duplicate monster " + name, names.add(name));
			int level = monster.get("combatLevel").getAsInt();
			Assert.assertTrue("bad level " + name, level >= 1 && level <= 1600);
			for (JsonElement tag : monster.getAsJsonArray("tags"))
			{
				Assert.assertTrue("illegal tag " + tag + " on " + name,
					MONSTER_TAGS.contains(tag.getAsString()));
			}
		}
	}

	/**
	 * Every quest gate must name a real {@link net.runelite.api.Quest} constant.
	 *
	 * A typo here does not throw at runtime — it produces a requirement no
	 * account can ever satisfy, so the monster silently vanishes from the pool
	 * for everyone and nothing in the logs says why. The build is the only place
	 * that can catch it, so it catches it here.
	 */
	@Test
	public void everyMonsterQuestGateNamesARealQuest()
	{
		JsonArray monsters = load("monsters.json").getAsJsonArray("monsters");
		Set<String> gatingQuests = new HashSet<>();
		int gated = 0;
		for (JsonElement monsterEl : monsters)
		{
			JsonObject monster = monsterEl.getAsJsonObject();
			JsonElement quests = monster.get("quests");
			if (quests == null)
			{
				continue;
			}
			String name = monster.get("name").getAsString();
			JsonArray required = quests.getAsJsonArray();
			Assert.assertTrue("empty quests array on " + name + " — omit the key instead",
				required.size() > 0);
			gated++;
			for (JsonElement questEl : required)
			{
				String quest = questEl.getAsString();
				gatingQuests.add(quest);
				try
				{
					net.runelite.api.Quest.valueOf(quest);
				}
				catch (IllegalArgumentException e)
				{
					Assert.fail("monster " + name + " is gated on " + quest
						+ ", which is not a Quest constant");
				}
			}
		}
		// a merge that dropped the key would leave a table that still parses and
		// still passes every other check, so the count is asserted too
		Assert.assertTrue("no monster carries a quest gate", gated >= 100);
		Assert.assertTrue("suspiciously few distinct gating quests", gatingQuests.size() >= 20);
	}

	@Test
	public void bossesParseWithMilestones()
	{
		JsonArray bosses = load("bosses.json").getAsJsonArray("bosses");
		Assert.assertTrue(bosses.size() >= 15);
		for (JsonElement bossEl : bosses)
		{
			JsonObject boss = bossEl.getAsJsonObject();
			Assert.assertFalse(boss.get("chatName").getAsString().isEmpty());
			Assert.assertFalse(boss.get("setTag").getAsString().isEmpty());
			JsonArray milestones = boss.getAsJsonArray("kcMilestones");
			Assert.assertTrue(milestones.size() >= 2);
			int prev = 0;
			for (JsonElement milestone : milestones)
			{
				int m = milestone.getAsInt();
				Assert.assertTrue("milestones not ascending", m > prev);
				prev = m;
			}
		}
	}

	@Test
	public void setsParseWithLegalPerks()
	{
		JsonArray sets = load("sets.json").getAsJsonArray("sets");
		Assert.assertTrue(sets.size() >= 15);
		Set<String> keys = new HashSet<>();
		for (JsonElement setEl : sets)
		{
			JsonObject set = setEl.getAsJsonObject();
			Assert.assertTrue("dup set key", keys.add(set.get("setKey").getAsString()));
			Assert.assertTrue(set.getAsJsonArray("cardNames").size() >= 2);
			JsonObject perk = set.getAsJsonObject("perk");
			SetTable.PerkType.valueOf(perk.get("type").getAsString());
			SetTable.PerkScope scope = SetTable.PerkScope.valueOf(perk.get("scope").getAsString());
			int magnitude = perk.get("magnitudePercent").getAsInt();
			Assert.assertTrue(magnitude >= 1 && magnitude <= 10);
			if (scope != SetTable.PerkScope.GLOBAL)
			{
				Assert.assertTrue(perk.getAsJsonArray("scopeValues").size() >= 1);
			}
		}
	}

	/**
	 * Every boss setTag must resolve to a real set. A dangling tag makes
	 * ChestService.roll() fall through to the whole card pool, so the "themed"
	 * milestone chest silently rolls random gear.
	 */
	@Test
	public void everyBossSetTagResolvesToASet()
	{
		Set<String> setKeys = new HashSet<>();
		for (JsonElement setEl : load("sets.json").getAsJsonArray("sets"))
		{
			setKeys.add(setEl.getAsJsonObject().get("setKey").getAsString());
		}
		for (JsonElement bossEl : load("bosses.json").getAsJsonArray("bosses"))
		{
			JsonObject boss = bossEl.getAsJsonObject();
			String tag = boss.get("setTag").getAsString();
			Assert.assertTrue(
				boss.get("bossName").getAsString() + " has setTag '" + tag + "' with no set in sets.json",
				setKeys.contains(tag));
		}
	}

	/**
	 * Milestone claims are keyed by bossName and BossKcService stops at the first
	 * chatName match, so a repeat of either silently swallows another boss's chests.
	 * Set tags are deliberately shared (the three Dagannoth Kings, the Wilderness
	 * singles pairs) and are not checked here.
	 */
	@Test
	public void bossNamesAndChatNamesAreUnique()
	{
		Set<String> bossNames = new HashSet<>();
		Set<String> chatNames = new HashSet<>();
		for (JsonElement bossEl : load("bosses.json").getAsJsonArray("bosses"))
		{
			JsonObject boss = bossEl.getAsJsonObject();
			String bossName = boss.get("bossName").getAsString();
			Assert.assertTrue("duplicate bossName " + bossName, bossNames.add(bossName));
			String chatName = boss.get("chatName").getAsString().toLowerCase();
			Assert.assertTrue("duplicate chatName " + chatName + " on " + bossName,
				chatNames.add(chatName));
		}
	}

	/**
	 * BossKcService captures the name lazily, up to the counter noun, so a chatName
	 * that swallows the noun ("Barrows chest") can never match.
	 */
	@Test
	public void bossChatNamesExcludeTheCounterNoun()
	{
		for (JsonElement bossEl : load("bosses.json").getAsJsonArray("bosses"))
		{
			JsonObject boss = bossEl.getAsJsonObject();
			String chatName = boss.get("chatName").getAsString();
			for (String noun : new String[]{"kill", "chest", "harvest", "completion"})
			{
				Assert.assertFalse(chatName + " ends with the counter noun '" + noun + "'",
					chatName.toLowerCase().endsWith(" " + noun));
			}
		}
	}

	/**
	 * Every quest combat exemption must name a real {@link net.runelite.api.Quest}.
	 *
	 * <p>The loader only logs a warning and skips, so a typo is a monster the
	 * player is quietly blocked from attacking during the one quest that needs
	 * it — with nothing on screen to explain why. The build is the only place
	 * that can catch it.
	 */
	@Test
	public void everyQuestExemptionNamesARealQuest()
	{
		JsonArray quests = load("quest-monsters.json").getAsJsonArray("quests");
		Assert.assertTrue(quests.size() >= 100);
		for (JsonElement entryEl : quests)
		{
			JsonObject entry = entryEl.getAsJsonObject();
			String quest = entry.get("quest").getAsString();
			try
			{
				net.runelite.api.Quest.valueOf(quest);
			}
			catch (IllegalArgumentException e)
			{
				Assert.fail("quest-monsters.json names " + quest + ", not a Quest constant");
			}
			Assert.assertTrue(quest + " has no NPCs — drop the entry instead",
				entry.getAsJsonArray("npcNames").size() > 0);
		}
	}

	/**
	 * Varplayers and varbits are SEPARATE id spaces read by different client
	 * methods, and {@code getVarpValue} on a varbit id returns a plausible
	 * integer rather than an error. An entry that names the wrong one produces a
	 * window that is silently wrong — no exception, no log line, just a player
	 * who cannot attack the monster their quest told them to. So: exactly one id
	 * kind, and never half a window.
	 */
	@Test
	public void everyQuestWindowIsWellFormed()
	{
		JsonArray quests = load("quest-monsters.json").getAsJsonArray("quests");
		int windowed = 0;
		for (JsonElement entryEl : quests)
		{
			JsonObject entry = entryEl.getAsJsonObject();
			String quest = entry.get("quest").getAsString();
			boolean hasVarp = entry.has("varp");
			boolean hasVarbit = entry.has("varbit");
			boolean hasRange = entry.has("min") || entry.has("max");
			Assert.assertFalse(quest + " names both a varp and a varbit",
				hasVarp && hasVarbit);
			if (!hasVarp && !hasVarbit && !hasRange)
			{
				continue;
			}
			windowed++;
			Assert.assertTrue(quest + " has a range but no varp/varbit to read",
				hasVarp || hasVarbit);
			Assert.assertTrue(quest + " has a varp/varbit but no min/max, so it gates nothing",
				hasRange);
			int id = (hasVarp ? entry.get("varp") : entry.get("varbit")).getAsInt();
			Assert.assertTrue(quest + " has a non-positive var id " + id, id > 0);
			int min = entry.has("min") ? entry.get("min").getAsInt() : Integer.MIN_VALUE;
			int max = entry.has("max") ? entry.get("max").getAsInt() : Integer.MAX_VALUE;
			Assert.assertTrue(quest + " has min " + min + " above max " + max, min <= max);
		}
		// windows are opt-in and most entries have none, but if this hits zero
		// someone has deleted the only thing the feature exists for
		Assert.assertTrue("no quest carries a progress window any more", windowed >= 1);
	}

	/**
	 * Quest progress variables count up from 0 = not started, so a window has to
	 * sit inside [1, ..]: {@code max} below 1 admits nothing a started quest can
	 * hold and locks the player out, and {@code min} of 0 admits a state the
	 * outer IN_PROGRESS check has already excluded, which means someone wrote a
	 * bound against the wrong variable.
	 */
	@Test
	public void everyQuestWindowSitsInsideTheStartedRange()
	{
		for (JsonElement entryEl : load("quest-monsters.json").getAsJsonArray("quests"))
		{
			JsonObject entry = entryEl.getAsJsonObject();
			if (!entry.has("varp") && !entry.has("varbit"))
			{
				continue;
			}
			String quest = entry.get("quest").getAsString();
			int min = entry.has("min") ? entry.get("min").getAsInt() : Integer.MIN_VALUE;
			int max = entry.has("max") ? entry.get("max").getAsInt() : Integer.MAX_VALUE;
			Assert.assertTrue(quest + " has max " + max + ", which no started quest can be",
				max >= 1);
			Assert.assertTrue(quest + " has min " + min + ", but 0 means NOT_STARTED",
				min >= 1);
		}
	}

	/**
	 * Windows are per NPC, not per quest.
	 *
	 * <p>They are SPELLED as one entry per window — {@code npcNames} groups the
	 * NPCs that happen to share one, it is not the unit the window applies to —
	 * and the loader flattens that to npc name -&gt; every gate on it. So one
	 * quest can gate one monster to a stretch of itself and leave another open
	 * for its whole run, and a single monster can carry several windows in the
	 * same quest by appearing on several entries.
	 *
	 * <p>This is easy to misread as quest-level, so it is pinned: Dragon Slayer
	 * I holds Melzar's Maze open only up to the Crandor landing, while Elvarg —
	 * who cannot be reached outside the quest anyway — stays open throughout.
	 */
	@Test
	public void oneQuestCanGateDifferentNpcsDifferently()
	{
		QuestMonsterTable table = QuestMonsterTable.load(new Gson());
		QuestMonsterTable.Gate maze = table.gatesFor("Skeleton").stream()
			.filter(g -> g.getQuest() == net.runelite.api.Quest.DRAGON_SLAYER_I)
			.findFirst().orElse(null);
		QuestMonsterTable.Gate elvarg = table.gatesFor("Elvarg").stream()
			.filter(g -> g.getQuest() == net.runelite.api.Quest.DRAGON_SLAYER_I)
			.findFirst().orElse(null);
		Assert.assertNotNull(maze);
		Assert.assertNotNull(elvarg);
		Assert.assertTrue("two NPCs of one quest must be able to differ",
			maze.hasWindow() != elvarg.hasWindow());
		// and the grouped NPCs really do each carry it, rather than the first one
		for (String npc : new String[]{"Zombie rat", "Ghost", "Skeleton", "Zombie",
			"Melzar the Mad", "Lesser demon", "Wormbrain"})
		{
			Assert.assertTrue(npc + " lost the window its entry carries",
				table.gatesFor(npc).stream()
					.filter(g -> g.getQuest() == net.runelite.api.Quest.DRAGON_SLAYER_I)
					.anyMatch(QuestMonsterTable.Gate::hasWindow));
		}
	}

	/**
	 * The window arithmetic itself, with no Client in sight.
	 *
	 * <p>Provenance of the one window that ships, because JSON cannot carry it:
	 * varplayer 176 is Dragon Slayer I, and the wiki documents 1 started, 2
	 * Oziach, 3 boat bought, 6 boat repaired, 7 map given to Ned, 8 landed on
	 * Crandor, 9 Elvarg slain, 10 complete. It documents NO value for Melzar's
	 * Maze. The upper bound of 8 is therefore INFERRED from step ordering — the
	 * maze yields a map piece, so it precedes the handover — and deliberately
	 * carries a step of slack past that, because being too tight is what locks a
	 * player out of their own quest. Do not tighten it without a real source.
	 */
	@Test
	public void gatesAdmitExactlyTheirWindow()
	{
		QuestMonsterTable table = QuestMonsterTable.load(new Gson());
		QuestMonsterTable.Gate maze = null;
		QuestMonsterTable.Gate elvarg = null;
		for (QuestMonsterTable.Gate gate : table.gatesFor("Ghost"))
		{
			if (gate.getQuest() == net.runelite.api.Quest.DRAGON_SLAYER_I)
			{
				maze = gate;
			}
		}
		for (QuestMonsterTable.Gate gate : table.gatesFor("Elvarg"))
		{
			elvarg = gate;
		}
		Assert.assertNotNull("Melzar's Maze mobs lost their Dragon Slayer gate", maze);
		Assert.assertNotNull("Elvarg lost her Dragon Slayer gate", elvarg);
		Assert.assertTrue("the maze gate lost its window", maze.hasWindow());
		Assert.assertFalse("the maze window must be a varplayer, not a varbit", maze.isVarbit());
		Assert.assertFalse("0 is NOT_STARTED", maze.contains(0));
		Assert.assertTrue(maze.contains(1));
		Assert.assertTrue(maze.contains(7));
		Assert.assertTrue("a step of slack past the map handover, on purpose", maze.contains(8));
		Assert.assertFalse("the exemption must close once Elvarg is dead", maze.contains(9));
		// no window means whole-quest, exactly as before windows existed
		Assert.assertFalse(elvarg.hasWindow());
	}

	@Test
	public void loadersLoadTheRealFiles()
	{
		Gson gson = new Gson();
		Assert.assertFalse(MonsterTable.load(gson).getMonsters().isEmpty());
		Assert.assertFalse(BossTable.load(gson).getBosses().isEmpty());
		Assert.assertFalse(SetTable.load(gson).getSets().isEmpty());
		TierTable tiers = TierTable.load(gson);
		Assert.assertFalse(tiers.getHolograms().isEmpty());
		TierTable.Match match = tiers.match("Rune scimitar");
		Assert.assertNotNull(match);
		Assert.assertEquals("rune", match.getTierKey());
		Assert.assertEquals("scimitar", match.getFamilyKey());
		TierTable.Match dhide = tiers.match("Black d'hide body");
		Assert.assertNotNull(dhide);
		Assert.assertEquals("body", dhide.getFamilyKey());
		// black metal is rank 4, but non-metal "Black ..." items must stay untiered
		TierTable.Match blackMetal = tiers.match("Black platebody");
		Assert.assertNotNull(blackMetal);
		Assert.assertEquals(4, blackMetal.getRank());
		Assert.assertNull("Black mask is slayer gear, not metal", tiers.match("Black mask"));
		Assert.assertNull("Black wizard hat is robes, not metal", tiers.match("Black wizard hat"));
		Assert.assertNull("White apron is cosmetic, not metal", tiers.match("White apron"));
	}
}

package com.gachaman;

import com.gachaman.model.*;
import org.junit.*;

/**
 * Guards the positional enum tables in {@link Tuning}.
 *
 * <p>Those tables no longer name their keys — the Nth value belongs to the Nth
 * enum constant — which trades a compile-time safety net for token budget. This
 * test IS the replacement net, and it costs nothing: the Plugin Hub bot counts
 * only src/main/java.
 *
 * <p>What it catches: a value list shorter or longer than its enum, an enum
 * gaining a constant without its tables gaining a row, and the deliberate gap
 * (a Rusty chest rolls no deeds) being closed by accident.
 */
public class TuningTableTest
{
	@Test
	public void everyTableCoversItsWholeEnum()
	{
		Assert.assertEquals(TaskDifficulty.values().length, Tuning.PER_KILL_GC.size());
		Assert.assertEquals(TaskDifficulty.values().length, Tuning.COMPLETION_GC.size());
		Assert.assertEquals(Tuning.Chest.values().length, Tuning.CHEST_PRICE_GC.size());
		Assert.assertEquals(Tuning.Chest.values().length, Tuning.CHEST_CARDS.size());
		Assert.assertEquals(Tuning.Chest.values().length, Tuning.CHEST_ODDS.size());
		Assert.assertEquals(Rarity.values().length, Tuning.DUPLICATE_GC.size());
		Assert.assertEquals(Rarity.values().length, Tuning.SHOP_PRICE_GC.size());
	}

	@Test
	public void positionalRowsLandOnTheRightConstants()
	{
		// spelled out against the enum BY NAME, which is exactly what the table
		// literals stopped doing — so a reordered enum fails here loudly
		Assert.assertEquals(4, (int) Tuning.PER_KILL_GC.get(TaskDifficulty.EASY));
		Assert.assertEquals(28, (int) Tuning.PER_KILL_GC.get(TaskDifficulty.INSANE));
		Assert.assertEquals(400, (int) Tuning.COMPLETION_GC.get(TaskDifficulty.EASY));
		Assert.assertEquals(3600, (int) Tuning.COMPLETION_GC.get(TaskDifficulty.INSANE));
		Assert.assertEquals(150, (int) Tuning.CHEST_PRICE_GC.get(Tuning.Chest.RUSTY));
		Assert.assertEquals(1000, (int) Tuning.CHEST_PRICE_GC.get(Tuning.Chest.ORNATE));
		Assert.assertEquals(3, (int) Tuning.CHEST_CARDS.get(Tuning.Chest.ORNATE));
		Assert.assertEquals(25, (int) Tuning.DUPLICATE_GC.get(Rarity.COMMON));
		Assert.assertEquals(1000, (int) Tuning.DUPLICATE_GC.get(Rarity.LEGENDARY));
		Assert.assertEquals(800, (int) Tuning.SHOP_PRICE_GC.get(Rarity.COMMON));
		Assert.assertEquals(20000, (int) Tuning.SHOP_PRICE_GC.get(Rarity.LEGENDARY));
		// Rusty rolls COMMON only; Ornate carries the whole spread
		Assert.assertEquals(100.0, Tuning.CHEST_ODDS.get(Tuning.Chest.RUSTY)[0], 1e-9);
		Assert.assertEquals(3.5, Tuning.CHEST_ODDS.get(Tuning.Chest.ORNATE)[4], 1e-9);
	}

	@Test
	public void theOneDeliberateGapStaysAGap()
	{
		// a null row means "absent", not "zero" — Rusty must roll no deeds at all
		Assert.assertFalse(Tuning.DEED_CHANCE.containsKey(Tuning.Chest.RUSTY));
		Assert.assertEquals(Tuning.Chest.values().length - 1, Tuning.DEED_CHANCE.size());
		Assert.assertTrue(Tuning.DEED_CHANCE.get(Tuning.Chest.ORNATE)
			> Tuning.DEED_CHANCE.get(Tuning.Chest.BATTERED));
	}
}

package com.gachaman;

import java.io.*;
import java.nio.charset.*;
import java.nio.file.*;
import java.util.*;
import java.util.stream.*;
import org.junit.*;

/**
 * Every caller of {@code LoadoutService.unassign} must read its answer.
 *
 * <p>The guard's failure mode is not a crash, it is a DEAD CLICK: unassign
 * refuses, the caller drops the boolean on the floor, and the card sits there
 * with the player none the wiser. The in-game board is the one that would hurt
 * — before this change it discarded the result and had no feedback path at all
 * — so the regression worth pinning is "somebody added a call site and forgot".
 *
 * <p>A source scan rather than a behavioural test, deliberately. Driving the
 * real call sites means constructing a JPanel with six injected collaborators
 * and an Overlay that needs a Client, a SpriteManager and a ClientThread; a
 * scan states the invariant directly, catches call sites that do not exist
 * yet, and costs nothing — the Hub bot counts only src/main/java.
 */
public class UnassignCallSiteTest
{
	/**
	 * How a call site is allowed to consume the boolean: branch on the
	 * refusal, hand it upward, or capture it in a named local.
	 *
	 * <p>Deliberately narrow. A bare {@code if (} would match any call that
	 * merely SITS inside an unrelated conditional — which is exactly the shape
	 * the old overlay code had — and a bare {@code =} would match assignments
	 * that never look at what they stored. Both would pass the three real call
	 * sites and catch nothing, which is the worst thing a guard test can be.
	 */
	private static boolean readsTheResult(String line)
	{
		String trimmed = line.trim();
		String before = trimmed.substring(0, trimmed.indexOf(".unassign("));
		return before.contains("if (!") || before.contains("return ")
			|| before.contains("boolean ");
	}

	@Test
	public void everyUnassignCallSiteReadsTheRefusal() throws IOException
	{
		Path root = SourceHygieneTest.sourceRoot();
		Assert.assertNotNull("could not locate src/main/java from "
			+ Paths.get("").toAbsolutePath(), root);

		List<String> offenders = new ArrayList<>();
		Set<String> callers = new TreeSet<>();
		try (Stream<Path> tree = Files.walk(root))
		{
			for (Path file : tree.filter(p -> p.toString().endsWith(".java"))
				.collect(Collectors.toList()))
			{
				List<String> lines = Files.readAllLines(file, StandardCharsets.UTF_8);
				for (int i = 0; i < lines.size(); i++)
				{
					if (!lines.get(i).contains(".unassign("))
					{
						continue;
					}
					callers.add(root.relativize(file).toString());
					if (!readsTheResult(lines.get(i)))
					{
						offenders.add(root.relativize(file) + ":" + (i + 1)
							+ "  " + lines.get(i).trim());
					}
				}
			}
		}

		Assert.assertEquals("a call site that ignores unassign()'s boolean is a click that"
			+ " refuses silently — branch on it and tell the player why",
			Collections.emptyList(), offenders);
		// a scan that found nothing would pass forever; the guard is only real
		// while somebody is actually calling the guarded method
		Assert.assertFalse("found no unassign() call sites at all under " + root,
			callers.isEmpty());
	}

	/**
	 * Both of the sidebar's unassign routes — the right-click menu item and
	 * the picker's "Unassign" row — go through the one helper that raises the
	 * dialog, so neither can be the one that swallows a refusal.
	 */
	@Test
	public void theSidebarRoutesBothOfItsUnassignsThroughTheExplainingHelper() throws IOException
	{
		Path root = SourceHygieneTest.sourceRoot();
		Assert.assertNotNull(root);
		String source = new String(Files.readAllBytes(
			root.resolve("com/gachaman/ui/panel/LoadoutTab.java")), StandardCharsets.UTF_8);

		int routed = 0;
		for (int at = source.indexOf("unassignOrExplain("); at >= 0;
			at = source.indexOf("unassignOrExplain(", at + 1))
		{
			routed++;
		}
		// two call sites plus the declaration
		Assert.assertEquals("LoadoutTab must route both unassign routes through the helper",
			3, routed);
		Assert.assertTrue("the helper is what puts the refusal in front of the player",
			source.contains("GachamanPanel.info(this, \"That card is still unlocking"));
	}

	/** The board has no text of its own, so its refusal has to show on the board. */
	@Test
	public void theInGameBoardShowsSomethingWhenItIsRefused() throws IOException
	{
		Path root = SourceHygieneTest.sourceRoot();
		Assert.assertNotNull(root);
		String source = new String(Files.readAllBytes(
			root.resolve("com/gachaman/ui/loadout/LoadoutOverlay.java")), StandardCharsets.UTF_8);

		Assert.assertTrue("the overlay must branch on the refusal",
			source.contains("if (!loadoutService.unassign("));
		Assert.assertTrue("...and mark the socket, or the click looks like a miss",
			source.contains("refusedSlot = slot;"));
	}
}

package com.gachaman.service;

import com.gachaman.*;
import com.gachaman.data.*;
import com.gachaman.model.*;
import com.gachaman.persist.*;
import com.google.gson.*;
import java.lang.reflect.*;
import java.util.*;
import net.runelite.api.Client;
import net.runelite.api.gameval.VarbitID;
import org.junit.*;

/**
 * What a kill actually PAYS once the wheel names a preferred weapon category:
 * where the 1.5x sits in the multiplier chain, which kills may claim it, and
 * which may not.
 *
 * <p>Headless, on real in-memory state, a real StyleTracker (so the sampling
 * rule is genuinely exercised rather than stubbed out) and the real shipped
 * taxonomy. Two things are faked and only two: the player's combat level, by
 * overriding the one method that reads it, and a Client that answers the ironman
 * varbit — the award branch is the only place onKill touches a client, and the
 * nine older TaskService suites dodge it entirely by paying 0 per kill, which is
 * exactly the branch this file has to run.
 *
 * <p><b>Why every preference here is the spell-cast pseudo-type.</b> A real
 * weapon category resolves through the client's own DB table, which a headless
 * test has no way to answer, so {@code satisfies} would be false for every
 * category and every assertion below would pass for the wrong reason. The
 * autocast pseudo-type is decided by com mode alone and is therefore the one
 * preference that can be genuinely satisfied here. Nothing in the award path
 * cares which category it was — WeaponTypeServiceTest owns the resolution chain,
 * this file owns the arithmetic and the window.
 */
public class WeaponBonusTest
{
	/** EASY's base per-kill GC. The owner's pinned ladder is quoted in these. */
	private static final int BASE = Tuning.PER_KILL_GC.get(TaskDifficulty.EASY);
	private static final int PLAYER_CB = 50;
	/**
	 * One level BELOW the player, which is inside KILL_DIFF_GRACE and so pays the
	 * flat 1.0. Not an equal match: {@code killCbMultiplier} pays 1.1x at diff 0,
	 * and the ladder the owner chose is quoted against a level term of exactly 1.
	 */
	private static final int NPC_CB = PLAYER_CB - 1;
	/** The autocast slot; see the class comment for why the preference is this one. */
	private static final int AUTOCAST = 4;
	/** Any other com mode: a weapon being swung, which never satisfies spell-cast. */
	private static final int SWINGING = 0;

	private GachaStateService stateService;
	private ComplianceService complianceService;
	private StyleTracker styleTracker;
	private TaskService taskService;
	private RecordingConsignment consignment;
	private final List<TaskService.TaskCompletionSummary> completions = new ArrayList<>();
	/** Per-kill GC in the order it was credited, straight off the kill feedback. */
	private final List<Long> awards = new ArrayList<>();

	// --- Harness --------------------------------------------------------------

	private static GachaStateService inMemoryStateService()
	{
		StateStore store = new StateStore(null, null, null)
		{
			@Override
			public void save(GachaState state)
			{
			}

			@Override
			public void save(GachaState state, boolean flushDiskNow)
			{
			}

			@Override
			public GachaState load()
			{
				return null; // forces a fresh in-memory state
			}
		};
		GachaStateService service = new GachaStateService(store);
		service.load(3);
		return service;
	}

	/**
	 * The smallest Client {@link TaskService#onKill} can run against: it answers
	 * the ironman varbit and a type-appropriate zero for everything else.
	 *
	 * <p>A proxy rather than a hand-written stub because {@code Client} is
	 * hundreds of methods wide and this path needs exactly one of them. It is
	 * test-only: the plugin ships no reflection anywhere, which is a Plugin Hub
	 * rule about what is DISTRIBUTED, not about what verifies it.
	 */
	private static Client client(boolean ironman)
	{
		return (Client) Proxy.newProxyInstance(Client.class.getClassLoader(),
			new Class<?>[]{Client.class}, (proxy, method, args) ->
			{
				if ("getVarbitValue".equals(method.getName())
					&& args != null && Integer.valueOf(VarbitID.IRONMAN).equals(args[0]))
				{
					return ironman ? 1 : 0;
				}
				Class<?> type = method.getReturnType();
				// yields false / 0 / 0.0 / null for whatever the signature
				// promised, with no table of primitives to keep in sync
				return type == void.class ? null : Array.get(Array.newInstance(type, 1), 0);
			});
	}

	/**
	 * Stands in for the Consignment so the completion path can be asked WHO it
	 * handed a due roll to. It deliberately rolls nothing: a wheel that never
	 * turns is what tells "TaskService delegated" apart from "TaskService rolled
	 * the wheel itself", which is otherwise invisible.
	 */
	private static class RecordingConsignment extends ConsignmentService
	{
		private int calls;
		private int lastTick = -1;

		RecordingConsignment()
		{
			super(null, null, null, null, null);
		}

		@Override
		public boolean offerOrRoll(int currentTick)
		{
			calls++;
			lastTick = currentTick;
			return false;
		}
	}

	@Before
	public void setUp()
	{
		build(false);
	}

	private void build(boolean ironman)
	{
		awards.clear();
		completions.clear();
		stateService = inMemoryStateService();
		CreditSink creditSink = new CreditSink(stateService);
		complianceService = new ComplianceService(stateService, creditSink, null, null);
		CeremonyBus ceremonyBus = new CeremonyBus();
		StyleService styleService = StyleFixture.styleService(stateService, complianceService,
			ceremonyBus, new GachaRng(1L));
		styleTracker = new StyleTracker(null, null);
		consignment = new RecordingConsignment();
		taskService = new TaskService(client(ironman), stateService, creditSink, complianceService,
			styleService, ceremonyBus, new GachaRng(1L), MonsterTable.load(new Gson()),
			// quest unlocks and max hit are offer-roll collaborators; no offer is rolled here
			null, null,
			styleTracker, new WeaponTypeService(null, new Gson(), new GachaRng(1L)), consignment)
		{
			@Override
			public int playerCombatLevel()
			{
				return PLAYER_CB;
			}
		};
		taskService.addListener(new TaskService.Listener()
		{
			@Override
			public void onKillFeedback(TaskService.KillFeedback feedback)
			{
				awards.add(feedback.getGcAwarded());
			}

			@Override
			public void onTaskCompleted(TaskService.TaskCompletionSummary summary)
			{
				completions.add(summary);
			}
		});
		Assert.assertEquals("the harness must carry no taint", 0, stateService.get().getTaint());
	}

	/** The wheel named the autocast slot; the state carries the key, as it does in play. */
	private void preferSpellCast()
	{
		stateService.mutate(s -> s.withPreferredWeaponType(WeaponTypeService.SPELL_CAST_KEY));
	}

	private void clearPreference()
	{
		stateService.mutate(s -> s.withPreferredWeaponType(null));
	}

	private void seedContract(int killsRequired, int perKillGc)
	{
		stateService.mutate(s -> s.withActiveTask(ActiveTask.builder()
			.difficulty(TaskDifficulty.EASY)
			.monsterName("Goblin")
			.monsterCombatLevel(NPC_CB)
			.killsRequired(killsRequired)
			.killsDone(0)
			.perKillGc(perKillGc)
			.completionGc(100)
			.acceptedAtMs(1L)
			.build()));
	}

	private KillTracker.Kill kill(int tick, boolean assisted)
	{
		// engagement spans [tick - 3, tick], the same shape the other suites use
		return new KillTracker.Kill("Goblin", NPC_CB, 1, tick, tick - 3, false, 3, assisted, null);
	}

	/** One on-task kill at `tick`, with an attack sampled inside its own window. */
	private long killWith(int tick, int comMode)
	{
		styleTracker.recordWeapon(tick, 0, comMode);
		taskService.onKill(kill(tick, false));
		return awards.get(awards.size() - 1);
	}

	// --- A. the ladder the owner pinned ---------------------------------------

	@Test
	public void theLevelTermIsExactlyOneForThisPairing()
	{
		// guards every figure below: if this pairing ever stopped paying a flat
		// 1.0 the ladder would drift and the failure would look like a bonus bug
		Assert.assertEquals(1.0, Tuning.killCbMultiplier(PLAYER_CB, NPC_CB), 1e-9);
		Assert.assertEquals(4, BASE);
	}

	@Test
	public void theEasyComboLadderUnderTheWeaponBonus()
	{
		// 6, 8, 9, 11, 12, 14, 15 — LUMPY ON PURPOSE, and recorded here so it stays
		// a decision rather than becoming a bug report. Every base in PER_KILL_GC is
		// a multiple of 4 so the combo's quarter-steps land whole; 1.5 breaks that,
		// and only whole multipliers would not. The owner chose 1.5 knowing it.
		seedContract(200, BASE);
		preferSpellCast();
		List<Long> ladder = new ArrayList<>();
		for (int i = 1; i <= 30; i++)
		{
			long paid = killWith(i * 2, AUTOCAST);
			if (i == 1 || i % 5 == 0)
			{
				ladder.add(paid);
			}
		}
		Assert.assertEquals(Arrays.asList(6L, 8L, 9L, 11L, 12L, 14L, 15L), ladder);
	}

	@Test
	public void theSameLadderWithoutTheBonusIsEven()
	{
		// the control that makes the lumpiness above legible: unpreferred, the same
		// thirty kills step 4, 5, 6, 7, 8, 9, 10 — whole GC all the way up
		seedContract(200, BASE);
		preferSpellCast();
		List<Long> ladder = new ArrayList<>();
		for (int i = 1; i <= 30; i++)
		{
			long paid = killWith(i * 2, SWINGING);
			if (i == 1 || i % 5 == 0)
			{
				ladder.add(paid);
			}
		}
		Assert.assertEquals(Arrays.asList(4L, 5L, 6L, 7L, 8L, 9L, 10L), ladder);
	}

	// --- B. which kills may claim it ------------------------------------------

	@Test
	public void aWeaponSwappedInAfterTheDeathEarnsNothing()
	{
		// THE regression this feature was designed around. onKill runs several
		// ticks after the killing blow, so a varbit read there would report the
		// weapon the player swapped to during the loot-oracle window. The sample
		// that proves the preference was in hand lands at tick 11; the kill died at
		// 10 and spans [7, 10], so it is not this kill's evidence.
		seedContract(200, BASE);
		preferSpellCast();
		styleTracker.recordWeapon(11, 0, AUTOCAST);
		taskService.onKill(kill(10, false));
		Assert.assertEquals(BASE, awards.get(0).longValue());
	}

	@Test
	public void theBonusSurvivesFightingStraightOnToTheNextMonster()
	{
		// The other half of the same rule, and the one a single cached slot would
		// break: the player kills at tick 10 with the preferred weapon and is
		// already hitting the next monster at 11, 12, 13... while the kill sits in
		// KillTracker's loot-oracle queue. Those later attacks must not evict the
		// evidence for a kill that is still waiting to be credited.
		seedContract(200, BASE);
		preferSpellCast();
		styleTracker.recordWeapon(10, 0, AUTOCAST);
		for (int tick = 11; tick <= 25; tick++)
		{
			styleTracker.recordWeapon(tick, 0, SWINGING);
		}
		taskService.onKill(kill(10, false));
		Assert.assertEquals(6, awards.get(0).longValue());
	}

	@Test
	public void aKillWithNoJudgedAttackInsideItsWindowEarnsNothing()
	{
		// thralls, off-screen damage, a monster something else finished: nothing
		// was judged inside this engagement, so there is no evidence to pay on and
		// the last fight's weapon is not inherited
		seedContract(200, BASE);
		preferSpellCast();
		taskService.onKill(kill(10, false));
		Assert.assertEquals(BASE, awards.get(0).longValue());
	}

	@Test
	public void noPreferenceMeansNoBonusEvenHoldingTheRightThing()
	{
		// a fresh save, or a cycle the taxonomy could not name a category for:
		// null is simply no bonus, never an error and never a penalty
		seedContract(200, BASE);
		clearPreference();
		Assert.assertEquals(BASE, killWith(10, AUTOCAST));
	}

	@Test
	public void anUnrecognisedCategoryPaysTheORDINARYAwardRatherThanNothing()
	{
		// The owner's rule, stated as the number it has to be: a category the
		// taxonomy has never heard of pays 1x — the plain award, exactly as if the
		// feature were not installed. NOT zero, and NOT an exception on the kill
		// path, which is the way this would actually break a player's session.
		//
		// Garbage is fed deliberately: the varbit is six bits, so 0..63 is the
		// legal range and everything here is outside it or at the extremes. A
		// future Jagex category the JSON has not caught up with arrives looking
		// exactly like this, so it is the real case, not a synthetic one.
		// Asserted against a CONTROL run rather than against the flat base, because
		// the combo earns its first stack on the fifth kill and a flat expectation
		// would fail there for a reason that has nothing to do with weapons. What
		// has to hold is that the two runs are indistinguishable.
		int[] garbage = {64, 255, -1, Integer.MIN_VALUE, Integer.MAX_VALUE};

		// SWINGING, not AUTOCAST: spell_cast is satisfied by the com mode alone and
		// would pay the bonus whatever the category is, hiding the thing under test.
		build(false);
		seedContract(200, BASE);
		preferSpellCast();
		List<Long> withGarbage = new ArrayList<>();
		for (int i = 0; i < garbage.length; i++)
		{
			styleTracker.recordWeapon((i + 1) * 2, garbage[i], SWINGING);
			taskService.onKill(kill((i + 1) * 2, false));
			withGarbage.add(awards.get(awards.size() - 1));
		}

		build(false);
		seedContract(200, BASE);
		clearPreference();
		List<Long> control = new ArrayList<>();
		for (int i = 0; i < garbage.length; i++)
		{
			styleTracker.recordWeapon((i + 1) * 2, garbage[i], SWINGING);
			taskService.onKill(kill((i + 1) * 2, false));
			control.add(awards.get(awards.size() - 1));
		}

		Assert.assertEquals("an unrecognised category must pay exactly what no"
			+ " preference at all pays", control, withGarbage);
		// and it is a real award, not a run of zeroes agreeing with itself
		Assert.assertEquals(Arrays.asList(4L, 4L, 4L, 4L, 5L), control);
	}

	// --- C. composition with the rest of the chain ----------------------------

	@Test
	public void aTaintedKillPaysNoWeaponBonus()
	{
		// Structural, not a rule anybody has to remember: the factor is applied
		// inside the non-tainted branch, and a tainted kill never reaches an award
		// at all. Pinned so a later refactor of that branch cannot quietly change
		// it — and pinned WITH the positive control below, because "tainted pays
		// nothing" would pass just as well if the bonus never worked at all.
		stateService.mutate(s -> s.withAllowedStyle(AttackStyle.MELEE.name()));
		seedContract(200, BASE);
		preferSpellCast();
		complianceService.onAttack(AttackStyle.MAGIC, 8); // convicts the kill at 10
		Assert.assertEquals(0, killWith(10, AUTOCAST));
		Assert.assertTrue("the kill must really have been tainted", stateService.get().getTaint() > 0);

		// the identical kill, uncontested: the bonus is alive and paying
		complianceService.resetTransient();
		stateService.mutate(s -> s.withTaint(0));
		Assert.assertEquals(6, killWith(20, AUTOCAST));
	}

	@Test
	public void theAssistHalvingLandsOnTopOfTheWeaponBonus()
	{
		// Both are multiplicative on the whole award, so the four combinations are
		// exactly base x 1 or 1.5, x 1 or 0.5. Asserting all four is what proves
		// they compose rather than one swallowing the other.
		build(true); // an ironman, so an assisted kill is only half theirs
		seedContract(200, BASE);
		clearPreference();
		Assert.assertEquals("plain", 4, killWith(2, AUTOCAST));
		preferSpellCast();
		Assert.assertEquals("preferred weapon", 6, killWith(4, AUTOCAST));
		clearPreference();
		styleTracker.recordWeapon(6, 0, AUTOCAST);
		taskService.onKill(kill(6, true));
		Assert.assertEquals("assisted", 2, awards.get(awards.size() - 1).longValue());
		preferSpellCast();
		styleTracker.recordWeapon(8, 0, AUTOCAST);
		taskService.onKill(kill(8, true));
		Assert.assertEquals("assisted, preferred weapon", 3,
			awards.get(awards.size() - 1).longValue());
	}

	@Test
	public void theBonusNeverTouchesTheCompletionReward()
	{
		// per-kill only. A completion bonus would be decided by whatever happened
		// to be equipped at the end, and could be had by swapping the preferred
		// weapon in for the final kill alone.
		seedContract(1, BASE);
		preferSpellCast();
		Assert.assertEquals(6, killWith(10, AUTOCAST));
		Assert.assertEquals(1, completions.size());
		Assert.assertEquals(100, completions.get(0).getCompletionGcAwarded());
	}

	// --- D. the Consignment owns a due roll -----------------------------------

	@Test
	public void aDueStyleRollGoesThroughTheConsignmentNotAroundIt()
	{
		// The Consignment may only be offered in the moment a roll comes due, so
		// this call site is the whole of its trigger. Routing it back through
		// styleService.roll would still change the style — nothing player-visible
		// would look broken — while quietly deleting the feature.
		stateService.mutate(s -> s.withAllowedStyle(AttackStyle.MELEE.name())
			.withCycleTarget(1)
			.withCycleProgress(0)
			.withStyleRolledAtMs(1L));
		seedContract(1, 0);
		taskService.onKill(kill(10, false));

		Assert.assertEquals("the cycle must really have tipped for this to mean anything",
			1, completions.size());
		Assert.assertTrue(completions.get(0).isCycleTriggered());
		Assert.assertEquals(1, consignment.calls);
		Assert.assertEquals("offered for the tick of the kill that finished the contract",
			10, consignment.lastTick);
		// this stand-in rolls nothing, so a style that moved could only have been
		// rolled by TaskService going around it
		Assert.assertEquals(AttackStyle.MELEE.name(), stateService.get().getAllowedStyle());
		Assert.assertEquals(1L, stateService.get().getStyleRolledAtMs());
	}

	@Test
	public void aContractThatDoesNotTipTheCycleOffersNothing()
	{
		// the once-a-day gate is not the only thing rationing the offer: it is only
		// ever put up when the wheel is actually due
		stateService.mutate(s -> s.withAllowedStyle(AttackStyle.MELEE.name())
			.withCycleTarget(5)
			.withCycleProgress(0));
		seedContract(1, 0);
		taskService.onKill(kill(10, false));
		Assert.assertFalse(completions.get(0).isCycleTriggered());
		Assert.assertEquals(0, consignment.calls);
	}
}

package com.gachaman.service;

import com.gachaman.data.*;
import com.gachaman.model.*;
import com.gachaman.persist.*;
import com.google.gson.*;
import java.util.*;
import java.util.concurrent.atomic.*;
import org.junit.*;

/**
 * Pins the invariants behind TaskService's shared board accessors — pending(),
 * offerAt(), installOffers() — and behind the removal of acceptInternal's
 * partyAnchorId parameter.
 *
 * These all began life as copy-pasted blocks inside the individual methods. The
 * folding is only safe while the answers below stay identical, and each of them
 * is the kind of thing a later "simplification" would quietly change:
 *
 * <ul>
 * <li>a null pendingOffers list is an EMPTY BOARD, never an NPE and never a
 *     throw out of a bounds test — a save written before the field existed
 *     deserialises exactly that way;</li>
 * <li>every signed contract carries partyAnchorId 0, because nothing writes it
 *     any more and the persisted field must keep encoding the same value;</li>
 * <li>installing a board always disarms the Ante and always tells the
 *     listeners, on the party path as much as on the personal one.</li>
 * </ul>
 *
 * Headless with a null Client: nothing exercised here reads the client (only
 * rollOffers does), so the offers are seeded through the state service.
 */
public class TaskServiceOfferAccessorTest
{
	private GachaStateService stateService;
	private CeremonyBus ceremonyBus;
	private TaskService taskService;

	private static GachaStateService inMemoryStateService()
	{
		StateStore store = new StateStore(null, null, null)
		{
			@Override
			public void save(GachaState state)
			{
			}

			@Override
			public void save(GachaState state, boolean flushDiskNow)
			{
			}

			@Override
			public GachaState load()
			{
				return null; // forces a fresh in-memory state
			}
		};
		GachaStateService service = new GachaStateService(store);
		service.load(3);
		return service;
	}

	@Before
	public void setUp()
	{
		stateService = inMemoryStateService();
		CreditSink creditSink = new CreditSink(stateService);
		ComplianceService complianceService = new ComplianceService(stateService, creditSink, null, null);
		ceremonyBus = new CeremonyBus();
		StyleService styleService = StyleFixture.styleService(stateService, complianceService, ceremonyBus,
			new GachaRng(1L));
		MonsterTable monsterTable = MonsterTable.load(new Gson());
		taskService = new TaskService(null, stateService, creditSink, complianceService,
			styleService, ceremonyBus, new GachaRng(1L), monsterTable, null, null,
			// The three collaborators added with the Preferred Weapon and the
			// Consignment are unwired here: no contract in this file pays per kill,
			// so the award branch (the only reader of the weapon pair) is never
			// reached, and no completion here tips the style cycle.
			null, null, null);
	}

	private static List<TaskOffer> twoOffers(boolean partyRoll)
	{
		List<TaskOffer> offers = new ArrayList<>(2);
		offers.add(new TaskOffer(TaskDifficulty.EASY, "Goblin", 2, 15, 7, 400,
			new ArrayList<>(), false, partyRoll));
		offers.add(new TaskOffer(TaskDifficulty.MEDIUM, "Hill Giant", 28, 40, 12, 1100,
			new ArrayList<>(), false, partyRoll));
		return offers;
	}

	private List<TaskOffer> seedOffers(boolean partyRoll)
	{
		List<TaskOffer> offers = twoOffers(partyRoll);
		stateService.mutate(s -> s.withPendingOffers(offers));
		return offers;
	}

	/**
	 * A save from before pendingOffers existed loads the field as null. Every
	 * board query has to read that as "nothing on the board" — the old code said
	 * so with a hand-written null test at each site, the accessor says it once.
	 */
	@Test
	public void aNullPendingListIsAnEmptyBoard()
	{
		stateService.mutate(s -> s.withPendingOffers(null));

		Assert.assertFalse(taskService.hasPendingOffers());
		Assert.assertFalse(taskService.hasPendingPartyOffers());
		Assert.assertFalse("nothing to re-present", taskService.presentOffers());
		Assert.assertFalse("nothing to accept", taskService.acceptOffer(0));
		Assert.assertFalse("and a bogus index must not escape as a throw",
			taskService.acceptOffer(-1));
		Assert.assertNull(stateService.get().getActiveTask());
	}

	/** The accessor hands back the state's OWN list, so re-presenting is free. */
	@Test
	public void presentOffersSubmitsTheBoardItself()
	{
		List<TaskOffer> seeded = seedOffers(false);
		AtomicReference<Object> presented = new AtomicReference<>();
		ceremonyBus.addTap(request ->
		{
			if (request.getType() == CeremonyBus.Type.TASK_OFFERS)
			{
				presented.set(request.getPayload());
			}
		});

		Assert.assertTrue(taskService.presentOffers());

		Assert.assertSame("the ceremony must receive the live board, not a copy",
			seeded, presented.get());
	}

	/** Both accept paths refuse the same four ways, in the same order. */
	@Test
	public void acceptRefusesEveryOffBoardIndex()
	{
		Assert.assertFalse("empty board", taskService.acceptOffer(0));

		seedOffers(false);
		Assert.assertFalse("past the end", taskService.acceptOffer(2));
		Assert.assertFalse("past the end, party path",
			taskService.acceptPartyOffer(2, "Party of 2", null));

		Assert.assertTrue(taskService.acceptOffer(0));
		Assert.assertNotNull(stateService.get().getActiveTask());

		// a contract in force closes the board to both paths
		stateService.mutate(s -> s.withPendingOffers(twoOffers(false)));
		Assert.assertFalse("a contract is a contract", taskService.acceptOffer(1));
		Assert.assertFalse(taskService.acceptPartyOffer(1, "Party of 2", null));
		Assert.assertEquals("Goblin", stateService.get().getActiveTask().getMonsterName());
	}

	/**
	 * partyAnchorId is no longer a parameter of acceptInternal. It stays a
	 * persisted field (dropping it would change the save format), so what must
	 * hold is that the builder still writes the 0 every accept has always
	 * written — on the solo path and on the shared one alike.
	 */
	@Test
	public void everySignedContractCarriesAnchorIdZero()
	{
		seedOffers(false);
		Assert.assertTrue(taskService.acceptOffer(0));
		Assert.assertEquals("solo contract", 0L,
			stateService.get().getActiveTask().getPartyAnchorId());

		setUp(); // fresh state: a contract in force would block the second accept
		seedOffers(false);
		Assert.assertTrue(taskService.acceptPartyOffer(1, "Party of 3",
			Arrays.asList(AttackStyle.MELEE, AttackStyle.RANGED), false, 4242L));
		ActiveTask shared = stateService.get().getActiveTask();
		Assert.assertEquals("shared contract", 0L, shared.getPartyAnchorId());
		Assert.assertEquals("the id that actually survives a restart is untouched",
			Long.valueOf(4242L), shared.getPartyProposalId());
		Assert.assertEquals("Party of 3", shared.getPartyLabel());
		Assert.assertTrue(shared.isParty());
	}

	/**
	 * The personal roll and the party installer share one installer, so the
	 * party path must disarm the Ante and notify the listeners exactly as the
	 * personal path does. Arming survives neither: a stake is a decision about
	 * one specific board.
	 */
	@Test
	public void installingAPartyBoardDisarmsTheAnteAndNotifiesListeners()
	{
		AtomicReference<List<TaskOffer>> announced = new AtomicReference<>();
		taskService.addListener(new TaskService.Listener()
		{
			@Override
			public void onTaskCompleted(TaskService.TaskCompletionSummary summary)
			{
			}

			@Override
			public void onOffersRolled(List<TaskOffer> offers)
			{
				announced.set(offers);
			}
		});
		AtomicInteger ceremonies = new AtomicInteger();
		ceremonyBus.addTap(request ->
		{
			if (request.getType() == CeremonyBus.Type.TASK_OFFERS)
			{
				ceremonies.incrementAndGet();
			}
		});
		taskService.armAnte(20);
		Assert.assertTrue(taskService.anteArmed());

		List<TaskOffer> offers = twoOffers(true);
		Assert.assertTrue(taskService.presentPartyOffers(offers));

		Assert.assertEquals("a new board is a new decision", 0,
			taskService.getArmedAntePercent());
		Assert.assertSame(offers, announced.get());
		Assert.assertEquals(1, ceremonies.get());
		Assert.assertEquals(offers, stateService.get().getPendingOffers());
		Assert.assertTrue(taskService.hasPendingPartyOffers());
	}
}

package com.gachaman.service;

import com.gachaman.model.*;
import com.gachaman.service.WeaponTypeService.WeaponType;
import com.google.gson.*;
import java.util.*;
import org.junit.*;

/**
 * The Preferred Weapon lookup, and above all the property the whole design rests
 * on: an unrecognised category earns NOTHING.
 *
 * <p>There is no default arm anywhere in the chain, no array index, no clamp
 * into range and no remap of an unknown id onto a similar one — so a player
 * holding a category this build has never heard of simply does not get the
 * multiplier that kill. Every path that could turn a miss into a payout is
 * pinned here.
 *
 * <p>{@code WeaponTypeService} dereferences Client to read the category table,
 * and Client is null in every headless test, so the decisions themselves live in
 * pure package-private overloads that take the table as an argument — the same
 * seam {@code StyleTracker.resolve} uses, for the same reason.
 */
public class WeaponTypeServiceTest
{
	/**
	 * The table is injected in the plugin (the Plugin Hub forbids a fresh Gson
	 * in shipped code); a test builds its own because there is no injector here.
	 */
	private static WeaponTypeService service(long seed)
	{
		return new WeaponTypeService(null, new Gson(), new GachaRng(seed));
	}

	private static final WeaponTypeService SERVICE = service(0xC0FFEEL);

	/**
	 * A SYNTHETIC category-int to dbrow table. Deliberately scrambled — it maps
	 * category 0 to the LAST of the original block of rows and counts backwards.
	 *
	 * <p>It is scrambled on purpose so that nothing in this file can be mistaken
	 * for a table the plugin could hardcode. The live mapping is the client's own
	 * (DB table 78) and must always be read from it: the legacy WeaponType int
	 * table that other plugins copy around is stale from 22 onward, and building
	 * anything on a fixed int-to-category assumption is the exact bug the dbrow
	 * indirection exists to avoid.
	 *
	 * <p>What matters here is only its SHAPE: exactly the ints 0..30 are mapped,
	 * so 31..63 and everything negative are genuinely unknown to it.
	 */
	private static final Map<Integer, Integer> FIXTURE = fixture();

	private static Map<Integer, Integer> fixture()
	{
		List<WeaponType> withRows = new ArrayList<>();
		for (WeaponType type : SERVICE.all())
		{
			if (type.getDbrow() != WeaponTypeService.NO_DBROW)
			{
				withRows.add(type);
			}
		}
		Map<Integer, Integer> map = new HashMap<>();
		for (int category = 0; category <= 30; category++)
		{
			map.put(category, withRows.get(30 - category).getDbrow());
		}
		return Collections.unmodifiableMap(map);
	}

	/** The fixture's category int for a key, or -1 when it maps to none. */
	private static int categoryOf(String key)
	{
		WeaponType type = SERVICE.byKey(key);
		Assert.assertNotNull("no such weapon type: " + key, type);
		for (Map.Entry<Integer, Integer> entry : FIXTURE.entrySet())
		{
			if (entry.getValue() == type.getDbrow())
			{
				return entry.getKey();
			}
		}
		return -1;
	}

	@Test
	public void theResourceLoads()
	{
		// every other test in this file would pass vacuously against an empty
		// taxonomy, so prove there is one before asserting anything about it
		Assert.assertFalse("weapon-types.json did not load", SERVICE.all().isEmpty());
		Assert.assertNotNull(SERVICE.byKey("whip"));
		Assert.assertNotNull(SERVICE.byKey(WeaponTypeService.SPELL_CAST_KEY));
	}

	@Test
	public void aKnownCategoryInHandDoesPay()
	{
		// the positive control: without it, a service that answered "no" to
		// everything would pass every other test in this class
		int whip = categoryOf("whip");
		Assert.assertNotEquals(-1, whip);
		Assert.assertEquals("whip", SERVICE.byCategory(FIXTURE, whip).getKey());
		Assert.assertTrue(SERVICE.satisfies(FIXTURE, "whip", whip, 0));
	}

	@Test
	public void anUnknownCategoryPaysNothing()
	{
		// the varbit is 6 bits, so 0..63 is the whole legal range; the live table
		// fills only the low end of it and everything above is a category this
		// build has never heard of
		for (int category = 31; category <= 63; category++)
		{
			assertNothingPaid(category);
		}
	}

	@Test
	public void anImpossibleCategoryPaysNothing()
	{
		// negatives cannot come out of a varbit at all, so reaching one means the
		// read itself failed — which must still be worth nothing rather than
		// indexing off the front of something
		for (int category = -1; category >= -8; category--)
		{
			assertNothingPaid(category);
		}
		assertNothingPaid(Integer.MIN_VALUE);
		assertNothingPaid(Integer.MAX_VALUE);
		assertNothingPaid(64);
		assertNothingPaid(255);
	}

	private void assertNothingPaid(int category)
	{
		Assert.assertNull("category " + category + " resolved to a type",
			SERVICE.byCategory(FIXTURE, category));
		for (String key : new String[] {"whip", "unarmed", "bow", "staff_selfpowering"})
		{
			Assert.assertFalse("category " + category + " paid the " + key + " bonus",
				SERVICE.satisfies(FIXTURE, key, category, 0));
			// and not through the autocast door either: only SPELL_CAST may pass
			// on com mode alone
			Assert.assertFalse("category " + category + " paid the " + key
				+ " bonus while autocasting", SERVICE.satisfies(FIXTURE, key, category, 4));
		}
	}

	@Test
	public void anUnreadableCategoryTablePaysNothing()
	{
		// the client has not loaded the table yet (or the read failed and was not
		// cached): every weapon is unknown, and unknown is worth nothing. Never a
		// free bonus, never a penalty
		Map<Integer, Integer> empty = Collections.emptyMap();
		for (int category = 0; category <= 63; category++)
		{
			Assert.assertNull(SERVICE.byCategory(empty, category));
			Assert.assertFalse(SERVICE.satisfies(empty, "whip", category, 0));
		}
		// ...except the pseudo-type, which needs no table at all
		Assert.assertTrue(SERVICE.satisfies(empty, WeaponTypeService.SPELL_CAST_KEY, 0, 4));
	}

	@Test
	public void aPartialCategoryTableStillPaysForWhatItDoesResolve()
	{
		// the read came back with only some of the rows readable. Everything the
		// partial table DOES name still pays — refusing the lot would turn a
		// partial outage into a total one, and a total one is silent (the service
		// never caches a partial map, so this heals by itself if it was transient)
		Map<Integer, Integer> partial = new HashMap<>();
		int whip = categoryOf("whip");
		partial.put(whip, SERVICE.byKey("whip").getDbrow());

		Assert.assertTrue(SERVICE.satisfies(partial, "whip", whip, 0));
		Assert.assertFalse("a category missing from the partial table must pay nothing",
			SERVICE.satisfies(partial, "bow", categoryOf("bow"), 0));
		Assert.assertNull(SERVICE.byCategory(partial, categoryOf("bow")));
	}

	@Test
	public void aCategoryMappedToADbrowThisBuildDoesNotKnowPaysNothing()
	{
		// the table resolved the varbit to a row the taxonomy has no entry for —
		// a category the API gained and weapon-types.json has not caught up with.
		// The chain must break here rather than fall through to a neighbour
		Map<Integer, Integer> future = new HashMap<>(FIXTURE);
		future.put(31, 999_999);
		Assert.assertNull(SERVICE.byCategory(future, 31));
		for (String key : new String[] {"whip", "unarmed", "bow"})
		{
			Assert.assertFalse(SERVICE.satisfies(future, key, 31, 0));
		}
	}

	@Test
	public void noPreferenceIsNoBonusAndNeverAnError()
	{
		int whip = categoryOf("whip");
		Assert.assertFalse("a null preference must be worth nothing",
			SERVICE.satisfies(FIXTURE, null, whip, 0));
		Assert.assertNull(SERVICE.byKey(null));
		Assert.assertNull(SERVICE.displayName(null));
	}

	@Test
	public void aPreferenceThisBuildNoLongerKnowsPaysNothing()
	{
		// preferredWeaponType is a String in a save file and the taxonomy is
		// regenerated from a moving API. A save carrying a key that no longer
		// resolves must land on "no bonus" — not on an exception, and not on some
		// neighbouring category
		// "blaster" is in this list on purpose: the owner's exclusion list named
		// it, and runelite-api 1.12.35 has no COMBAT_INTERFACE_BLASTER constant to
		// spell it with, so it was left out rather than invented. If the API ever
		// adds one, everyApiCategoryIsAccountedFor will demand an entry for it and
		// this assertion will fail — that is the pair working, not a broken test.
		// Move "blaster" out of this list then; do not delete the assertion.
		int whip = categoryOf("whip");
		for (String stale : new String[] {"moon_hammer", "", "WHIP", "whip ", "blaster"})
		{
			Assert.assertNull("unexpectedly resolvable: " + stale, SERVICE.byKey(stale));
			Assert.assertNull(SERVICE.displayName(stale));
			Assert.assertFalse(stale + " paid a bonus", SERVICE.satisfies(FIXTURE, stale, whip, 0));
			Assert.assertFalse(stale + " paid a bonus while autocasting",
				SERVICE.satisfies(FIXTURE, stale, whip, 4));
		}
	}

	@Test
	public void spellCastMatchesTheAutocastSlotAndNothingElse()
	{
		// com mode 4 is the autocast slot, the same signal StyleTracker.resolve
		// judges MAGIC on. It is the whole definition of the pseudo-type: what is
		// in hand is irrelevant, which is why it can be named at all
		for (int category : new int[] {0, 1, categoryOf("whip"), categoryOf("staff_selfpowering"), 31, 63, -1})
		{
			Assert.assertTrue("spell_cast must match com mode 4 (category " + category + ")",
				SERVICE.satisfies(FIXTURE, WeaponTypeService.SPELL_CAST_KEY, category, 4));
			for (int comMode = -1; comMode <= 10; comMode++)
			{
				if (comMode == 4)
				{
					continue;
				}
				Assert.assertFalse("spell_cast matched com mode " + comMode,
					SERVICE.satisfies(FIXTURE, WeaponTypeService.SPELL_CAST_KEY, category, comMode));
			}
		}
	}

	@Test
	public void aPoweredStaffIsNotSpellCastAndSpellCastIsNotAPoweredStaff()
	{
		// powered staves fight from com mode 0/1/3, never the autocast slot, which
		// is exactly why they are their own category. The two must not stand in
		// for each other in either direction, or naming one would silently pay for
		// the other
		int powered = categoryOf("staff_selfpowering");
		Assert.assertFalse(SERVICE.satisfies(FIXTURE, WeaponTypeService.SPELL_CAST_KEY, powered, 0));
		Assert.assertTrue(SERVICE.satisfies(FIXTURE, "staff_selfpowering", powered, 0));
		Assert.assertFalse(SERVICE.satisfies(FIXTURE, "staff_selfpowering", categoryOf("whip"), 4));
	}

	@Test
	public void aNamedStaffStillPaysWhileAutocasting()
	{
		// deliberate: the category in hand is what the preference names, and a
		// hybrid staff reads as its category whether it is being swung or cast
		// with. The style lock is what makes this safe — a magic player who swings
		// it has tainted the kill and lost the whole award, not merely the 1.5x
		for (String key : new String[] {"staff", "staff_bladed", "staff_spellblade"})
		{
			int category = categoryOf(key);
			Assert.assertTrue(key + " should pay while autocasting",
				SERVICE.satisfies(FIXTURE, key, category, 4));
			Assert.assertTrue(key + " should pay while swinging",
				SERVICE.satisfies(FIXTURE, key, category, 0));
		}
	}

	@Test
	public void hybridStavesAreMeleeAndMagicButNeverRanged()
	{
		// this is what rescues magic from a two-item pool, so it is worth pinning
		// rather than leaving to the resource
		for (String key : new String[] {"staff", "staff_bladed", "staff_spellblade"})
		{
			WeaponType type = SERVICE.byKey(key);
			Assert.assertNotNull(key + " is missing from the taxonomy", type);
			Assert.assertTrue(key + " must be offerable", type.isOfferable());
			Assert.assertTrue(key + " must be in the melee pool",
				SERVICE.pool(AttackStyle.MELEE).contains(type));
			Assert.assertTrue(key + " must be in the magic pool",
				SERVICE.pool(AttackStyle.MAGIC).contains(type));
			Assert.assertFalse(key + " must never be in the ranged pool",
				SERVICE.pool(AttackStyle.RANGED).contains(type));
		}
	}

	@Test
	public void excludedCategoriesNeverComeOutOfTheWheel()
	{
		// 10,000 rolls per style. An excluded category reaching a player is not a
		// cosmetic bug: bulwark cannot deal damage, gun reads ranged and is fought
		// as melee, and a salamander cannot be verified at all — each one is a
		// whole style cycle the player cannot honour
		Set<String> excluded = new HashSet<>();
		for (WeaponType type : SERVICE.all())
		{
			if (!type.isOfferable())
			{
				excluded.add(type.getKey());
			}
		}
		Assert.assertFalse("no categories are excluded — the taxonomy is not loaded",
			excluded.isEmpty());

		for (AttackStyle style : AttackStyle.values())
		{
			WeaponTypeService rolling = service(20260815L + style.ordinal());
			Set<String> seen = new HashSet<>();
			for (int i = 0; i < 10_000; i++)
			{
				WeaponType rolled = rolling.roll(style);
				Assert.assertNotNull(style + " rolled nothing", rolled);
				Assert.assertFalse(style + " rolled the excluded category " + rolled.getKey(),
					excluded.contains(rolled.getKey()));
				Assert.assertTrue(style + " rolled " + rolled.getKey() + ", which it may not name",
					rolled.getOfferIn().contains(style));
				seen.add(rolled.getKey());
			}
			// and the pool is genuinely drawn from: a roll that always returned the
			// same entry would satisfy everything above
			Set<String> pool = new HashSet<>();
			for (WeaponType type : SERVICE.pool(style))
			{
				pool.add(type.getKey());
			}
			Assert.assertEquals(style + " never rolled part of its own pool", pool, seen);
		}
	}

	@Test
	public void theRollIsDrivenOnlyByTheInjectedRng()
	{
		// the wheel's weapon roll must not draw from the party's seeded RNG — an
		// extra draw taken from that stream by one client and not another deals
		// two different boards. The RNG is constructor-injected precisely so the
		// seeded instance has no route in; this pins that the roll consumes that
		// instance and nothing else, so the same seed replays exactly
		WeaponTypeService a = service(4242L);
		WeaponTypeService b = service(4242L);
		for (int i = 0; i < 200; i++)
		{
			AttackStyle style = AttackStyle.values()[i % AttackStyle.values().length];
			Assert.assertEquals(a.roll(style).getKey(), b.roll(style).getKey());
		}
	}

	@Test
	public void unarmedIsNamedForWhatThePlayerCanSee()
	{
		// category 0 is reported for every non-weapon held item, not just for bare
		// fists, so the player-facing name may never say "unarmed" — see
		// WeaponTypeResourceTest for the guard across the whole file
		Assert.assertEquals("No weapon equipped", SERVICE.displayName("unarmed"));
		Assert.assertTrue("unarmed belongs to the melee pool",
			SERVICE.pool(AttackStyle.MELEE).contains(SERVICE.byKey("unarmed")));
	}
}

package com.gachaman.service;

import java.time.*;
import java.util.*;
import org.junit.*;

/**
 * The once-per-day gate's clock, tested as a pure function.
 *
 * <p>The day key is the whole of the gate — there is no server and nothing
 * stored but the last key used — so the only two ways it can be wrong are
 * turning over at the wrong instant, or turning over at a different instant for
 * different players. One test each.
 */
public class ConsignmentDayKeyTest
{
	private TimeZone originalZone;

	@Before
	public void rememberZone()
	{
		originalZone = TimeZone.getDefault();
	}

	@After
	public void restoreZone()
	{
		TimeZone.setDefault(originalZone);
	}

	private static long at(String isoInstant)
	{
		return Instant.parse(isoInstant).toEpochMilli();
	}

	@Test
	public void theKeyTurnsOverAtUtcMidnightAndNotBefore()
	{
		String lateOnTheFifteenth = ConsignmentService.dayKeyAt(at("2026-08-15T23:59:59Z"));
		String earlyOnTheSixteenth = ConsignmentService.dayKeyAt(at("2026-08-16T00:00:01Z"));

		Assert.assertNotEquals("two seconds apart across UTC midnight is two different days",
			lateOnTheFifteenth, earlyOnTheSixteenth);
		Assert.assertEquals("the whole of one UTC day is one key",
			lateOnTheFifteenth, ConsignmentService.dayKeyAt(at("2026-08-15T00:00:00Z")));
		Assert.assertEquals(earlyOnTheSixteenth,
			ConsignmentService.dayKeyAt(at("2026-08-16T23:59:59Z")));
	}

	/**
	 * The guard against the obvious "simplification" — {@code LocalDate.now()}
	 * without a zone, which reads the JVM default. Two players hitting the same
	 * instant from Tokyo and Los Angeles are on opposite sides of their own local
	 * midnights here, and must still be on the same Consignment day.
	 */
	@Test
	public void oneInstantIsOneDayNoMatterWhatTheClientsClockIsSetTo()
	{
		// 05:00 the next morning in Tokyo, 13:00 the same afternoon in Los Angeles
		long instant = at("2026-08-15T20:00:00Z");

		TimeZone.setDefault(TimeZone.getTimeZone("Asia/Tokyo"));
		String tokyo = ConsignmentService.dayKeyAt(instant);

		TimeZone.setDefault(TimeZone.getTimeZone("America/Los_Angeles"));
		String losAngeles = ConsignmentService.dayKeyAt(instant);

		Assert.assertEquals("the gate must not depend on the player's own clock",
			tokyo, losAngeles);
		Assert.assertEquals("...and both must be the UTC day", tokyo,
			ConsignmentService.dayKey(LocalDate.of(2026, 8, 15)));
	}

	/**
	 * Day-of-year rather than month/day, lifted verbatim from the Charter Office
	 * so two daily gates in one plugin cannot disagree about when a day turns
	 * over. Pinned because the shape is compared as a plain string against a
	 * persisted value — changing it would silently hand every existing save a
	 * free Consignment on the day of the change.
	 */
	@Test
	public void theKeyIsYearAndDayOfYear()
	{
		Assert.assertEquals("2026-D1", ConsignmentService.dayKey(LocalDate.of(2026, 1, 1)));
		Assert.assertEquals("2026-D227", ConsignmentService.dayKey(LocalDate.of(2026, 8, 15)));
		// leap years push the tail of the year along by one; nothing depends on
		// the number itself, only on two derived strings comparing equal
		Assert.assertEquals("2024-D366", ConsignmentService.dayKey(LocalDate.of(2024, 12, 31)));
		Assert.assertEquals("2025-D365", ConsignmentService.dayKey(LocalDate.of(2025, 12, 31)));
	}

	@Test
	public void anUnusedKeyIsNeverUsedToday()
	{
		String today = ConsignmentService.dayKey(LocalDate.of(2026, 8, 15));
		String yesterday = ConsignmentService.dayKey(LocalDate.of(2026, 8, 14));

		Assert.assertFalse("a save written before the feature existed has no key at all",
			ConsignmentService.usedOn(null, today));
		Assert.assertFalse(ConsignmentService.usedOn(yesterday, today));
		Assert.assertTrue(ConsignmentService.usedOn(today, today));
	}
}

package com.gachaman.service;

import com.gachaman.*;
import com.gachaman.model.*;
import com.gachaman.persist.*;
import java.util.*;
import org.junit.*;

/**
 * The Ante end to end: escrow at accept, doubled return at completion, total
 * loss on death, and the guarantee that none of it can interfere with the
 * contract itself.
 *
 * Headless, real in-memory state; the null client is never touched because
 * every contract here uses perKillGc 0 (the award branch is the only client
 * read in onKill). The exact GC figures assume the harness registers NO
 * CreditSink modifiers and carries no taint — both asserted in setUp.
 */
public class TaskServiceAnteTest
{
	private static final int PURSE = 2000;
	/**
	 * Everything the ONE kill in these tests pays that is not the Ante and not
	 * the completion award. A fresh harness has an empty bestiary, so that kill
	 * is a first-of-species discovery. Named rather than folded into the
	 * numbers so an Ante regression cannot hide behind an unexplained constant.
	 */
	private static final int KILL_EXTRAS = Tuning.DISCOVERY_GC;

	private GachaStateService stateService;
	private TaskService taskService;
	private final List<TaskService.TaskCompletionSummary> completions = new ArrayList<>();

	private static GachaStateService inMemoryStateService()
	{
		StateStore store = new StateStore(null, null, null)
		{
			@Override
			public void save(GachaState state)
			{
			}

			@Override
			public void save(GachaState state, boolean flushDiskNow)
			{
			}

			@Override
			public GachaState load()
			{
				return null; // forces a fresh in-memory state
			}
		};
		GachaStateService service = new GachaStateService(store);
		service.load(3);
		return service;
	}

	@Before
	public void setUp()
	{
		stateService = inMemoryStateService();
		CreditSink creditSink = new CreditSink(stateService);
		ComplianceService complianceService = new ComplianceService(stateService, creditSink, null, null);
		CeremonyBus ceremonyBus = new CeremonyBus();
		StyleService styleService = StyleFixture.styleService(stateService, complianceService, ceremonyBus,
			new GachaRng(1L));
		com.gachaman.data.MonsterTable monsterTable =
			com.gachaman.data.MonsterTable.load(new com.google.gson.Gson());
		taskService = new TaskService(null, stateService, creditSink, complianceService,
			styleService, ceremonyBus, new GachaRng(1L), monsterTable,
			// null Client already means these tests never reach rollOffers()
			null, null,
			// The three collaborators added with the Preferred Weapon and the
			// Consignment are unwired here: no contract in this file pays per kill,
			// so the award branch (the only reader of the weapon pair) is never
			// reached, and no completion here tips the style cycle.
			null, null, null);
		taskService.addListener(new TaskService.Listener()
		{
			@Override
			public void onKillFeedback(TaskService.KillFeedback feedback)
			{
			}

			@Override
			public void onSideBetHit(SideBet bet, String monsterName)
			{
			}

			@Override
			public void onTaskCompleted(TaskService.TaskCompletionSummary summary)
			{
				completions.add(summary);
			}

			@Override
			public void onOffersRolled(List<TaskOffer> offers)
			{
			}

			@Override
			public void onPartyProgress(ActiveTask task)
			{
			}
		});
		// the exact payout figures below only hold with an unmodified sink
		Assert.assertEquals("harness must carry no taint", 0, stateService.get().getTaint());
		setPurse(PURSE);
	}

	private void setPurse(long gc)
	{
		stateService.mutate(s -> s.withGc(gc));
	}

	private long gc()
	{
		return stateService.get().getGc();
	}

	private ActiveTask task()
	{
		return stateService.get().getActiveTask();
	}

	/** One kill short of done, perKillGc 0, so one onKill reaches completeTask. */
	private void board(TaskDifficulty difficulty)
	{
		TaskOffer offer = new TaskOffer(difficulty, "Goblin", 2, 1, 0, 1000, null, false, false);
		stateService.mutate(s -> s.withPendingOffers(Arrays.asList(offer)));
	}

	private KillTracker.Kill goblinKill()
	{
		return new KillTracker.Kill("Goblin", 2, 1, 10, 7, false, 3, false, null);
	}

	// --- A. the escrow ---

	@Test
	public void armingAloneStakesNothing()
	{
		board(TaskDifficulty.INSANE);
		taskService.armAnte(50);
		Assert.assertEquals("GC must not move until a contract is signed", PURSE, gc());
		Assert.assertTrue(taskService.anteArmed());
		Assert.assertEquals(1000, taskService.previewAnteStake());
	}

	@Test
	public void acceptingAnInsaneContractEscrowsTheStake()
	{
		board(TaskDifficulty.INSANE);
		taskService.armAnte(50);
		Assert.assertTrue(taskService.acceptOffer(0));
		Assert.assertEquals("the stake left the purse at signing", PURSE - 1000, gc());
		Assert.assertEquals(1000, task().getAnteStake());
		Assert.assertEquals(1000, taskService.getActiveAnteStake());
	}

	@Test
	public void theArmingIsSpentByTheContractItArmed()
	{
		board(TaskDifficulty.INSANE);
		taskService.armAnte(50);
		taskService.acceptOffer(0);
		Assert.assertFalse("a stake must never carry silently to the next contract",
			taskService.anteArmed());
		Assert.assertEquals(0, taskService.getArmedAntePercent());
	}

	@Test
	public void anUnarmedPlayerStakesNothing()
	{
		board(TaskDifficulty.INSANE);
		Assert.assertTrue(taskService.acceptOffer(0));
		Assert.assertEquals(PURSE, gc());
		Assert.assertEquals(0, task().getAnteStake());
	}

	@Test
	public void onlyInsaneContractsTakeTheStake()
	{
		board(TaskDifficulty.HARD);
		taskService.armAnte(50);
		Assert.assertTrue("the contract is signed regardless", taskService.acceptOffer(0));
		Assert.assertEquals("an armed player must not be charged on an ineligible contract",
			PURSE, gc());
		Assert.assertEquals(0, task().getAnteStake());
	}

	@Test
	public void aPurseUnderTheFloorSignsTheContractWithoutAWager()
	{
		setPurse(Tuning.ANTE_MIN_PURSE_GC - 1);
		board(TaskDifficulty.INSANE);
		taskService.armAnte(50);
		Assert.assertTrue("the Ante must never block or cancel a contract",
			taskService.acceptOffer(0));
		Assert.assertNotNull(task());
		Assert.assertEquals(Tuning.ANTE_MIN_PURSE_GC - 1, gc());
		Assert.assertEquals(0, task().getAnteStake());
	}

	@Test
	public void aFreshBoardDisarmsAnyStandingArming()
	{
		taskService.armAnte(30);
		// the party layer installing a new offer set is the same decision point
		// as a personal re-roll: a new board, so a new answer
		Assert.assertTrue(taskService.presentPartyOffers(Arrays.asList(
			new TaskOffer(TaskDifficulty.INSANE, "Goblin", 2, 1, 0, 1000, null, false, true))));
		Assert.assertFalse(taskService.anteArmed());
	}

	// --- B. winning ---

	@Test
	public void completingReturnsTheStakeDoubled()
	{
		board(TaskDifficulty.INSANE);
		taskService.armAnte(50);
		taskService.acceptOffer(0);
		long afterAccept = gc();
		taskService.onKill(goblinKill());

		Assert.assertEquals("exactly one completion must fire", 1, completions.size());
		long completion = completions.get(0).getCompletionGcAwarded();
		Assert.assertEquals("principal out of escrow plus an equal profit",
			afterAccept + completion + 2L * 1000 + KILL_EXTRAS, gc());
		Assert.assertNull(stateService.get().getActiveTask());
	}

	@Test
	public void aWonAnteIsNetNeutralOnTheStakeItself()
	{
		// the whole promise, stated as a balance: stake 1000, finish, be 1000 up
		board(TaskDifficulty.INSANE);
		taskService.armAnte(50);
		taskService.acceptOffer(0);
		taskService.onKill(goblinKill());
		long completion = completions.get(0).getCompletionGcAwarded();
		Assert.assertEquals(PURSE + completion + 1000 + KILL_EXTRAS, gc());
	}

	@Test
	public void theStakePrincipalIsNotCountedAsEarnings()
	{
		// it is the player's own GC coming back out of escrow, not income; only
		// the profit is (and lifetime earnings drives prestige progress)
		board(TaskDifficulty.INSANE);
		taskService.armAnte(50);
		taskService.acceptOffer(0);
		long earnedBefore = stateService.get().getLifetimeGcEarned();
		taskService.onKill(goblinKill());
		long completion = completions.get(0).getCompletionGcAwarded();
		Assert.assertEquals(earnedBefore + completion + 1000 + KILL_EXTRAS,
			stateService.get().getLifetimeGcEarned());
	}

	@Test
	public void anUnstakedContractPaysExactlyWhatItAlwaysDid()
	{
		board(TaskDifficulty.INSANE);
		taskService.acceptOffer(0);
		taskService.onKill(goblinKill());
		long completion = completions.get(0).getCompletionGcAwarded();
		Assert.assertEquals(1000, completion);
		Assert.assertEquals(PURSE + completion + KILL_EXTRAS, gc());
	}

	// --- C. losing ---

	@Test
	public void dyingForfeitsTheStake()
	{
		board(TaskDifficulty.INSANE);
		taskService.armAnte(50);
		taskService.acceptOffer(0);
		long afterAccept = gc();

		taskService.onLocalPlayerDeath();
		Assert.assertEquals("the GC already left the purse; death only stops the return",
			afterAccept, gc());
		Assert.assertEquals(0, task().getAnteStake());
		Assert.assertNotNull("the contract itself survives the player", task());
	}

	@Test
	public void aForfeitedStakeIsNotReturnedOnCompletion()
	{
		board(TaskDifficulty.INSANE);
		taskService.armAnte(50);
		taskService.acceptOffer(0);
		long afterAccept = gc();
		taskService.onLocalPlayerDeath();
		taskService.onKill(goblinKill());

		long completion = completions.get(0).getCompletionGcAwarded();
		Assert.assertEquals("finishing after a death pays the contract and nothing more",
			afterAccept + completion + KILL_EXTRAS, gc());
	}

	@Test
	public void dyingTwiceCannotChargeTheStakeTwice()
	{
		board(TaskDifficulty.INSANE);
		taskService.armAnte(50);
		taskService.acceptOffer(0);
		long afterAccept = gc();
		taskService.onLocalPlayerDeath();
		taskService.onLocalPlayerDeath();
		taskService.onLocalPlayerDeath();
		Assert.assertEquals(afterAccept, gc());
		Assert.assertEquals(0, task().getAnteStake());
	}

	@Test
	public void dyingWithNothingStakedChangesNothing()
	{
		board(TaskDifficulty.INSANE);
		taskService.acceptOffer(0);
		taskService.onLocalPlayerDeath();
		Assert.assertEquals(PURSE, gc());
		Assert.assertNotNull(task());
	}

	@Test
	public void dyingWithNoContractAtAllIsHarmless()
	{
		// the death hook fires on every death, contract or not
		taskService.onLocalPlayerDeath();
		Assert.assertEquals(PURSE, gc());
		Assert.assertNull(task());
	}

	// --- D. the party path: personal stakes, personal loss ---

	@Test
	public void aPartyContractStakesOnlyWithThisClientsConsent()
	{
		board(TaskDifficulty.INSANE);
		taskService.armAnte(50);
		// the three-arg form is the no-verdict path: the party did not agree
		Assert.assertTrue(taskService.acceptPartyOffer(0, "Party of 3", null));
		Assert.assertEquals("no unanimity means no wager, but the contract stands",
			PURSE, gc());
		Assert.assertEquals(0, task().getAnteStake());
		Assert.assertTrue(task().isParty());
	}

	@Test
	public void aConsentedPartyContractEscrowsThisPlayersOwnStake()
	{
		board(TaskDifficulty.INSANE);
		taskService.armAnte(50);
		Assert.assertTrue(taskService.acceptPartyOffer(0, "Party of 3", null, true));
		Assert.assertEquals(PURSE - 1000, gc());
		Assert.assertEquals("the stake is priced off THIS purse, not the party's",
			1000, task().getAnteStake());
	}

	@Test
	public void aPartyVerdictCannotStakeAnUnarmedPlayer()
	{
		// belt and braces: the host's verdict says the party agreed, but a client
		// that armed nothing has consented to nothing
		board(TaskDifficulty.INSANE);
		Assert.assertTrue(taskService.acceptPartyOffer(0, "Party of 3", null, true));
		Assert.assertEquals(PURSE, gc());
		Assert.assertEquals(0, task().getAnteStake());
	}

	@Test
	public void theCarryClauseDoesNotReleaseTheStake()
	{
		// the partner leaves; the contract converts to solo and still pays out.
		// Refunding here would make "partner logs out" the cheap way out of a bet.
		board(TaskDifficulty.INSANE);
		taskService.armAnte(50);
		taskService.acceptPartyOffer(0, "Party of 2", null, true);
		taskService.convertPartyToSolo();
		Assert.assertEquals(1000, task().getAnteStake());

		taskService.onKill(goblinKill());
		long completion = completions.get(0).getCompletionGcAwarded();
		Assert.assertEquals(PURSE - 1000 + completion + 2000 + KILL_EXTRAS, gc());
	}
}

package com.gachaman.service;

import com.gachaman.model.*;
import java.util.*;
import org.junit.*;

/**
 * The Service Record's pure rules. "Present for" means the owned card's uuid
 * was assigned to a loadout slot when the kill was credited — these tests pin
 * that reading, not any particular contract state.
 */
public class ServiceRecordServiceTest
{
	private static OwnedCard card(String uuid, int cardId, int killsServed)
	{
		return new OwnedCard(uuid, cardId, null, Variant.NORMAL, 100L, "chest:GILDED", killsServed);
	}

	// --- creditKill ---

	@Test
	public void creditKillCountsEachAssignedCardOnce()
	{
		Map<String, String> loadout = new LinkedHashMap<>();
		loadout.put("WEAPON", "u1");
		loadout.put("BODY", "u2");
		Map<String, Integer> tally = new HashMap<>();

		ServiceRecordService.creditKill(tally, loadout);
		ServiceRecordService.creditKill(tally, loadout);

		Assert.assertEquals(2, tally.size());
		Assert.assertEquals(Integer.valueOf(2), tally.get("u1"));
		Assert.assertEquals(Integer.valueOf(2), tally.get("u2"));
	}

	@Test
	public void creditKillCountsADuplicatedUuidOnce()
	{
		// a card that somehow occupied two slots still served ONE kill
		Map<String, String> loadout = new LinkedHashMap<>();
		loadout.put("WEAPON", "u1");
		loadout.put("SHIELD", "u1");
		Map<String, Integer> tally = new HashMap<>();

		ServiceRecordService.creditKill(tally, loadout);

		Assert.assertEquals(1, tally.size());
		Assert.assertEquals(Integer.valueOf(1), tally.get("u1"));
	}

	@Test
	public void creditKillIgnoresNullAndEmptyLoadout()
	{
		Map<String, Integer> tally = new HashMap<>();
		ServiceRecordService.creditKill(tally, null);
		ServiceRecordService.creditKill(tally, Collections.emptyMap());
		Assert.assertTrue(tally.isEmpty());
	}

	@Test
	public void creditKillSkipsNullSlotValues()
	{
		Map<String, String> loadout = new HashMap<>();
		loadout.put("WEAPON", null);
		loadout.put("BODY", "u2");
		Map<String, Integer> tally = new HashMap<>();

		ServiceRecordService.creditKill(tally, loadout);

		Assert.assertEquals(1, tally.size());
		Assert.assertEquals(Integer.valueOf(1), tally.get("u2"));
	}

	// --- applyTally ---

	@Test
	public void applyTallyCreditsOnlyMatchingCardsAndPreservesOrder()
	{
		List<OwnedCard> cards = Arrays.asList(card("u1", 11, 0), card("u2", 22, 0), card("u3", 33, 0));
		Map<String, Integer> tally = new HashMap<>();
		tally.put("u2", 5);

		List<OwnedCard> out = ServiceRecordService.applyTally(cards, tally);

		Assert.assertNotNull(out);
		Assert.assertEquals(3, out.size());
		Assert.assertEquals("u1", out.get(0).getUuid());
		Assert.assertEquals("u2", out.get(1).getUuid());
		Assert.assertEquals("u3", out.get(2).getUuid());
		Assert.assertEquals(0, out.get(0).getKillsServed());
		Assert.assertEquals(5, out.get(1).getKillsServed());
		Assert.assertEquals(0, out.get(2).getKillsServed());
		// every other field of the rewritten card survives untouched
		OwnedCard credited = out.get(1);
		Assert.assertEquals(22, credited.getCardId());
		Assert.assertNull(credited.getTierKey());
		Assert.assertEquals(Variant.NORMAL, credited.getVariant());
		Assert.assertEquals(100L, credited.getAcquiredAtMs());
		Assert.assertEquals("chest:GILDED", credited.getProvenance());
		// untouched cards are the very same instances, not equal copies
		Assert.assertSame(cards.get(0), out.get(0));
		Assert.assertSame(cards.get(2), out.get(2));
	}

	@Test
	public void applyTallyAccumulatesOnTopOfAnExistingRecord()
	{
		// the counter is monotonic — a flush ADDS, it never replaces
		List<OwnedCard> cards = Collections.singletonList(card("u1", 11, 400));
		Map<String, Integer> tally = new HashMap<>();
		tally.put("u1", 3);

		List<OwnedCard> out = ServiceRecordService.applyTally(cards, tally);

		Assert.assertNotNull(out);
		Assert.assertEquals(403, out.get(0).getKillsServed());
	}

	@Test
	public void applyTallyReturnsNullWhenNothingMatched()
	{
		// null hands mutate() an unchanged state, so a no-op flush costs no
		// gzip + SHA-256 encode at all
		List<OwnedCard> cards = Collections.singletonList(card("u1", 11, 0));
		Map<String, Integer> unowned = new HashMap<>();
		unowned.put("gone", 4);

		Assert.assertNull(ServiceRecordService.applyTally(cards, unowned));
		Assert.assertNull(ServiceRecordService.applyTally(cards, new HashMap<>()));
		Assert.assertNull(ServiceRecordService.applyTally(null, unowned));
		Assert.assertNull(ServiceRecordService.applyTally(Collections.emptyList(), unowned));
	}

	@Test
	public void applyTallyDropsUuidsNoLongerOwned()
	{
		// a card burned by prestige between the kill and the flush: its service
		// died with it, and the survivor still gets its own credit
		List<OwnedCard> cards = Collections.singletonList(card("alive", 11, 2));
		Map<String, Integer> tally = new HashMap<>();
		tally.put("alive", 1);
		tally.put("burned", 9);

		List<OwnedCard> out = ServiceRecordService.applyTally(cards, tally);

		Assert.assertNotNull(out);
		Assert.assertEquals(1, out.size());
		Assert.assertEquals(3, out.get(0).getKillsServed());
	}

	// --- setServed (::gachawear only) ---

	@Test
	public void setServedOverwritesOnlyTheNamedCopiesAndPreservesOrder()
	{
		List<OwnedCard> cards = Arrays.asList(card("u1", 11, 7), card("u2", 22, 7), card("u3", 33, 7));

		List<OwnedCard> out = ServiceRecordService.setServed(
			cards, Collections.singleton("u2"), 400);

		Assert.assertNotNull(out);
		Assert.assertEquals(3, out.size());
		Assert.assertEquals("u1", out.get(0).getUuid());
		Assert.assertEquals("u2", out.get(1).getUuid());
		Assert.assertEquals("u3", out.get(2).getUuid());
		Assert.assertEquals(7, out.get(0).getKillsServed());
		Assert.assertEquals(400, out.get(1).getKillsServed());
		Assert.assertEquals(7, out.get(2).getKillsServed());
		Assert.assertSame(cards.get(0), out.get(0));
		Assert.assertSame(cards.get(2), out.get(2));
		// the rest of the card is not collateral damage
		Assert.assertEquals(22, out.get(1).getCardId());
		Assert.assertEquals(Variant.NORMAL, out.get(1).getVariant());
		Assert.assertEquals(100L, out.get(1).getAcquiredAtMs());
		Assert.assertEquals("chest:GILDED", out.get(1).getProvenance());
	}

	@Test
	public void setServedReplacesRatherThanAdds()
	{
		// the one place in the plugin where a record may go DOWN. applyTally
		// would have made this 1400; a debug SET means what it says
		List<OwnedCard> cards = Collections.singletonList(card("u1", 11, 1000));

		List<OwnedCard> out = ServiceRecordService.setServed(
			cards, Collections.singleton("u1"), 400);

		Assert.assertNotNull(out);
		Assert.assertEquals(400, out.get(0).getKillsServed());
	}

	@Test
	public void setServedCanClearARecordCompletely()
	{
		// ::gachawear none, for retaking a pristine screenshot after a worn one
		List<OwnedCard> cards = Collections.singletonList(card("u1", 11, 1000));

		List<OwnedCard> out = ServiceRecordService.setServed(
			cards, Collections.singleton("u1"), 0);

		Assert.assertNotNull(out);
		Assert.assertEquals(0, out.get(0).getKillsServed());
	}

	@Test
	public void setServedMovesEveryNamedCopyTogether()
	{
		// "Dragon scimitar" is one album cell but can be several owned copies,
		// and the cell shows the best of them — moving one would look like a
		// no-op on screen
		List<OwnedCard> cards = Arrays.asList(card("u1", 11, 0), card("u2", 11, 0));
		Set<String> both = new LinkedHashSet<>(Arrays.asList("u1", "u2"));

		List<OwnedCard> out = ServiceRecordService.setServed(cards, both, 100);

		Assert.assertNotNull(out);
		Assert.assertEquals(100, out.get(0).getKillsServed());
		Assert.assertEquals(100, out.get(1).getKillsServed());
	}

	@Test
	public void setServedReturnsNullWhenNothingWouldChange()
	{
		// same null contract as applyTally: mutate() gets an unchanged state and
		// skips the gzip + SHA-256 encode entirely
		List<OwnedCard> cards = Collections.singletonList(card("u1", 11, 400));

		Assert.assertNull("already at the asked-for number",
			ServiceRecordService.setServed(cards, Collections.singleton("u1"), 400));
		Assert.assertNull("uuid not owned",
			ServiceRecordService.setServed(cards, Collections.singleton("gone"), 9));
		Assert.assertNull(ServiceRecordService.setServed(cards, Collections.emptySet(), 9));
		Assert.assertNull(ServiceRecordService.setServed(null, Collections.singleton("u1"), 9));
		Assert.assertNull(ServiceRecordService.setServed(
			Collections.emptyList(), Collections.singleton("u1"), 9));
	}

	// --- bestByCardId ---

	@Test
	public void bestByCardIdTakesTheMaxAcrossCopies()
	{
		// the album cell is per card DEFINITION while the record is per copy:
		// the veteran copy is the one the player means
		List<OwnedCard> cards = Arrays.asList(
			new OwnedCard("u1", 1333, null, Variant.NORMAL, 1L, "chest:GILDED", 400),
			new OwnedCard("u2", 1333, null, Variant.SHINY, 2L, "chest:ORNATE", 0));

		Map<Integer, Integer> best = ServiceRecordService.bestByCardId(cards);

		Assert.assertEquals(1, best.size());
		Assert.assertEquals(Integer.valueOf(400), best.get(1333));
	}

	@Test
	public void bestByCardIdSkipsHologramsAndHandlesNull()
	{
		List<OwnedCard> cards = Arrays.asList(
			new OwnedCard("u1", 1333, null, Variant.NORMAL, 1L, "chest:GILDED", 7),
			new OwnedCard("u2", -1, "dragon", Variant.HOLOGRAM, 2L, "chest:ORNATE", 99));

		Map<Integer, Integer> best = ServiceRecordService.bestByCardId(cards);

		Assert.assertEquals(1, best.size());
		Assert.assertEquals(Integer.valueOf(7), best.get(1333));
		Assert.assertFalse("hologram cardId -1 must never enter the grid map", best.containsKey(-1));

		Assert.assertTrue(ServiceRecordService.bestByCardId(null).isEmpty());
		Assert.assertTrue(ServiceRecordService.bestByCardId(Collections.emptyList()).isEmpty());
	}
}

package com.gachaman.service;

import java.lang.reflect.*;
import org.junit.*;

/**
 * Thread-visibility pins for ChestService's mutable reveal state.
 *
 * <p>These assert on modifiers rather than on behaviour, which is unusual for
 * this suite and needs justifying: a missing happens-before edge cannot be
 * pinned by running code. A test that spun up two threads and waited for a
 * stale read would pass on x86 whether or not the field is volatile (the
 * hardware rarely reorders these accesses) and would be flaky everywhere else.
 * The modifier IS the invariant, so the modifier is what gets asserted.
 *
 * <p>This is also the only reflection in the repository. It is confined to
 * src/test on purpose — CLAUDE.md forbids reflection in the plugin itself, and
 * src/test is neither shipped nor counted against the Plugin Hub token budget.
 */
public class ChestPendingVisibilityTest
{
	@Test
	public void pendingIsVolatileBecauseTheEdtReadsItWithoutTheLock() throws Exception
	{
		// ChestService writes `pending` only from synchronized methods, but it is
		// exposed through a plain Lombok @Getter and read off the Swing EDT by
		// ShopTab (lines 205 and 652) while the client thread writes it. Drop the
		// volatile and the EDT has no happens-before edge to those writes, so it
		// may cache a stale reference for the rest of the session — the shop tile
		// keeps insisting a reveal is in progress after the reveal has closed.
		Field pending = ChestService.class.getDeclaredField("pending");
		Assert.assertTrue(
			"ChestService.pending is read off the EDT through its @Getter while the "
				+ "client thread writes it under the lock; it must stay volatile or "
				+ "the EDT has no happens-before edge to those writes",
			Modifier.isVolatile(pending.getModifiers()));
	}

	@Test
	public void canRerollStaysSynchronisedSoTheRerollFlagNeedsNoVolatile()
		throws Exception
	{
		// The other half of the reasoning above, pinned so it cannot rot silently.
		// rerollUsedThisReveal is written under the lock and read ONLY here, so it
		// needs no volatile of its own — but that is true only while canReroll
		// keeps taking the lock. If someone drops `synchronized` from canReroll to
		// spare the render thread a monitor, the flag quietly acquires the exact
		// visibility hole this file exists to close, and this test says so.
		Method canReroll = ChestService.class.getDeclaredMethod("canReroll", int.class);
		Assert.assertTrue(
			"canReroll() must stay synchronized: it is the only reader of the "
				+ "non-volatile rerollUsedThisReveal field, so the lock is what "
				+ "makes that field's writes visible to it",
			Modifier.isSynchronized(canReroll.getModifiers()));
	}
}

package com.gachaman.service;

import com.gachaman.model.*;
import java.util.*;
import org.junit.*;

/**
 * Who the house names: the style with the fewest owned weapon cards.
 *
 * <p>The tie-break gets first-class treatment here rather than a footnote,
 * because it is the common path and not the corner case. The pools come from
 * {@code CardDatabase.weaponCardIdsForStyle}, which returns COMMON weapons only,
 * so a young album sits at 0/0/0 and the earliest Consignments a player ever
 * sees are decided by the break alone.
 */
public class ConsignmentWorstDressedTest
{
	private static OwnedCard card(int cardId)
	{
		return new OwnedCard("u" + cardId + "-" + UUID.randomUUID(), cardId, null,
			Variant.NORMAL, 0L, "test", 0);
	}

	private static Map<AttackStyle, Set<Integer>> pools(int[] melee, int[] ranged, int[] magic)
	{
		Map<AttackStyle, Set<Integer>> out = new EnumMap<>(AttackStyle.class);
		out.put(AttackStyle.MELEE, ids(melee));
		out.put(AttackStyle.RANGED, ids(ranged));
		out.put(AttackStyle.MAGIC, ids(magic));
		return out;
	}

	private static Set<Integer> ids(int[] raw)
	{
		Set<Integer> out = new HashSet<>();
		for (int id : raw)
		{
			out.add(id);
		}
		return out;
	}

	@Test
	public void theFewestOwnedWeaponCardsWins()
	{
		Map<AttackStyle, Set<Integer>> pools = pools(
			new int[]{1, 2, 3}, new int[]{10, 11, 12}, new int[]{20, 21, 22});
		List<OwnedCard> album = Arrays.asList(
			card(1), card(2), card(3),   // melee: 3
			card(10),                    // ranged: 1
			card(20), card(21));         // magic: 2

		Assert.assertEquals(AttackStyle.RANGED,
			ConsignmentService.worstDressed(pools, album));
	}

	/**
	 * Ties go to the earliest declared style. Not a coin flip and not a seeded
	 * draw: the offer is recomputed for the panel as well as for the ceremony,
	 * and anything random would have to persist a seed to stop the two disagreeing
	 * — where a rule the player can learn costs nothing and never drifts.
	 */
	@Test
	public void anEmptyAlbumIsWorstDressedForMeleeByDeclarationOrder()
	{
		Map<AttackStyle, Set<Integer>> pools = pools(
			new int[]{1, 2}, new int[]{10, 11}, new int[]{20, 21});

		Assert.assertEquals("0/0/0 is the normal early-game state, not an edge case",
			AttackStyle.MELEE, ConsignmentService.worstDressed(pools, Collections.emptyList()));
	}

	@Test
	public void aTieBetweenTheLaterTwoGoesToRanged()
	{
		Map<AttackStyle, Set<Integer>> pools = pools(
			new int[]{1, 2}, new int[]{10, 11}, new int[]{20, 21});
		List<OwnedCard> album = Arrays.asList(card(1), card(10), card(20));

		// melee 1, ranged 1, magic 1 — a three-way tie
		Assert.assertEquals(AttackStyle.MELEE, ConsignmentService.worstDressed(pools, album));

		// give melee one more: ranged and magic tie at 1, ranged is declared first
		List<OwnedCard> richerMelee = new ArrayList<>(album);
		richerMelee.add(card(2));
		Assert.assertEquals(AttackStyle.RANGED,
			ConsignmentService.worstDressed(pools, richerMelee));
	}

	/**
	 * Copies of one card do not dress anybody twice. Counting copies would let a
	 * run of duplicate pulls quietly move a style out of last place without the
	 * player having gained a single new weapon.
	 */
	@Test
	public void duplicateCopiesOfOneCardCountOnce()
	{
		Map<AttackStyle, Set<Integer>> pools = pools(
			new int[]{1, 2, 3}, new int[]{10, 11, 12}, new int[]{20, 21, 22});
		List<OwnedCard> album = Arrays.asList(
			card(1), card(2),               // melee: 2 distinct
			card(10), card(10), card(10),   // ranged: 3 copies of ONE card
			card(20), card(21));            // magic: 2 distinct

		// counting copies would make ranged the best dressed at 3 and hand the
		// offer to melee; counting distinct cards puts ranged last at 1
		Assert.assertEquals(AttackStyle.RANGED,
			ConsignmentService.worstDressed(pools, album));
		Assert.assertEquals(1, ConsignmentService.ownedFrom(
			pools.get(AttackStyle.RANGED), album));
	}

	/**
	 * A hologram names a whole tier rather than a weapon. It genuinely does dress
	 * a slot, but this measure is "how many weapons has this style been given",
	 * and a tier card answers a different question — so it is skipped even when
	 * its card id would match.
	 */
	@Test
	public void hologramsAreNotWeaponCards()
	{
		Map<AttackStyle, Set<Integer>> pools = pools(
			new int[]{1, 2}, new int[]{10, 11}, new int[]{20, 21});
		List<OwnedCard> album = Arrays.asList(
			card(1),
			new OwnedCard("holo", 10, "rune", Variant.HOLOGRAM, 0L, "test", 0),
			card(20));

		Assert.assertEquals("the hologram must not count as ranged's weapon card",
			AttackStyle.RANGED, ConsignmentService.worstDressed(pools, album));
		Assert.assertEquals(0, ConsignmentService.ownedFrom(
			pools.get(AttackStyle.RANGED), album));
	}

	@Test
	public void theAnswerDoesNotDependOnTheOrderTheAlbumHappensToBeIn()
	{
		Map<AttackStyle, Set<Integer>> pools = pools(
			new int[]{1, 2, 3}, new int[]{10, 11, 12}, new int[]{20, 21, 22});
		List<OwnedCard> album = new ArrayList<>(Arrays.asList(
			card(1), card(2), card(10), card(20), card(21), card(22)));

		AttackStyle first = ConsignmentService.worstDressed(pools, album);
		Assert.assertEquals(AttackStyle.RANGED, first);
		for (int i = 0; i < 25; i++)
		{
			Collections.shuffle(album, new Random(i));
			Assert.assertEquals("the house must name the same style every time it is asked",
				first, ConsignmentService.worstDressed(pools, album));
		}
	}

	/**
	 * Never null, whatever it is handed. A null answer would send offerOrRoll
	 * down the "cannot offer" path, which is a safe outcome — but it would be
	 * silently safe, and a style is always nameable.
	 */
	@Test
	public void degenerateInputStillNamesAStyle()
	{
		Assert.assertEquals(AttackStyle.MELEE,
			ConsignmentService.worstDressed(new EnumMap<>(AttackStyle.class), null));
		Assert.assertEquals(AttackStyle.MELEE,
			ConsignmentService.worstDressed(null, Collections.emptyList()));
		Assert.assertEquals(0, ConsignmentService.ownedFrom(null, null));
		Assert.assertEquals(0, ConsignmentService.ownedFrom(Collections.emptySet(),
			Collections.singletonList(card(1))));
	}
}

package com.gachaman.service;

import com.gachaman.data.MonsterTable;
import com.gachaman.model.*;
import com.gachaman.persist.*;
import java.util.*;
import org.junit.*;

/**
 * The party-progress fan-out at the tail of {@link TaskService#onKill}.
 *
 * <p>The loop used to read the volatile state snapshot FOUR separate times per
 * listener — once for the state null test, once for the active-task null test,
 * once for isParty() and once more to build the argument. Three of those reads
 * guarded a fourth read that nothing tied to them, so the value the listener
 * actually received was never the value the guards had approved. It also meant
 * five registered listeners cost twenty state reads on the single hottest path
 * in the plugin.
 *
 * <p>These tests pin both halves of the fix: the fan-out makes exactly ONE
 * observation per listener (so the guard and the argument are the same object
 * by construction), and that observation still happens per ITERATION rather
 * than once for the whole loop — a listener that ends the contract must still
 * silence the listeners queued behind it.
 *
 * <p>Headless, real in-memory state. The client is null throughout, which is
 * safe only because every contract here uses perKillGc 0 — the award branch is
 * the only client read onKill can reach.
 */
public class TaskServicePartyProgressTest
{
	/**
	 * Counts the state reads made through the PUBLIC accessor. Mutations inside
	 * GachaStateService touch the field directly, so this counts callers only —
	 * which is exactly the quantity under test.
	 */
	private static final class CountingStateService extends GachaStateService
	{
		private int gets;

		CountingStateService()
		{
			super(silentStore());
		}

		@Override
		public GachaState get()
		{
			gets++;
			return super.get();
		}
	}

	/** A store that persists nothing and always loads fresh. */
	private static StateStore silentStore()
	{
		return new StateStore(null, null, null)
		{
			@Override
			public void save(GachaState state)
			{
			}

			@Override
			public void save(GachaState state, boolean flushDiskNow)
			{
			}

			@Override
			public GachaState load()
			{
				return null; // forces a fresh in-memory state
			}
		};
	}

	/** Records every party-progress callback, including a null one if it ever comes. */
	private static class Recorder implements TaskService.Listener
	{
		final List<ActiveTask> progress = new ArrayList<>();

		@Override
		public void onTaskCompleted(TaskService.TaskCompletionSummary summary)
		{
		}

		@Override
		public void onPartyProgress(ActiveTask task)
		{
			progress.add(task);
		}
	}

	private CountingStateService stateService;
	private TaskService taskService;

	@Before
	public void setUp()
	{
		stateService = new CountingStateService();
		stateService.load(3);
		CreditSink creditSink = new CreditSink(stateService);
		ComplianceService complianceService =
			new ComplianceService(stateService, creditSink, null, null);
		CeremonyBus ceremonyBus = new CeremonyBus();
		StyleService styleService =
			StyleFixture.styleService(stateService, complianceService, ceremonyBus, new GachaRng(1L));
		taskService = new TaskService(null, stateService, creditSink, complianceService,
			styleService, ceremonyBus, new GachaRng(1L),
			MonsterTable.load(new com.google.gson.Gson()),
			// null Client already means these tests never reach rollOffers()
			null, null,
			// The three collaborators added with the Preferred Weapon and the
			// Consignment are unwired here: no contract in this file pays per kill,
			// so the award branch (the only reader of the weapon pair) is never
			// reached, and no completion here tips the style cycle.
			null, null, null);
	}

	/**
	 * Five kills short of the quota, so a single onKill reaches the fan-out
	 * without falling through into completeTask().
	 */
	private void seedContract(String partyLabel)
	{
		stateService.mutate(s -> s.withActiveTask(ActiveTask.builder()
			.difficulty(TaskDifficulty.EASY)
			.monsterName("Goblin")
			.killsRequired(5)
			.killsDone(0)
			.perKillGc(0) // keeps the null client out of onKill
			.completionGc(1000)
			.acceptedAtMs(1L)
			.partyLabel(partyLabel)
			.build()));
	}

	private KillTracker.Kill goblinKill(int tick)
	{
		return new KillTracker.Kill("Goblin", 2, 1, tick, tick - 3, false, 3, false, null);
	}

	// --- A. what the listener receives ---

	@Test
	public void partyKillNotifiesWithTheFreshlyCreditedTask()
	{
		seedContract("Party of 2");
		Recorder recorder = new Recorder();
		taskService.addListener(recorder);

		taskService.onKill(goblinKill(10));

		Assert.assertEquals("exactly one party-progress callback per credited kill",
			1, recorder.progress.size());
		ActiveTask seen = recorder.progress.get(0);
		Assert.assertNotNull("the guard approved a task, so a task must arrive", seen);
		Assert.assertTrue("only party contracts fan out", seen.isParty());
		// the fan-out sits AFTER the kill-count mutate on purpose: the partner
		// clients are told the new total, never the pre-kill one
		Assert.assertEquals("the task must carry the kill just credited", 1, seen.getKillsDone());
	}

	@Test
	public void soloContractNeverFansOut()
	{
		seedContract(null);
		Recorder recorder = new Recorder();
		taskService.addListener(recorder);

		taskService.onKill(goblinKill(10));

		Assert.assertTrue("a solo contract has nobody to tell", recorder.progress.isEmpty());
	}

	@Test
	public void offTaskKillNeverFansOut()
	{
		seedContract("Party of 2");
		Recorder recorder = new Recorder();
		taskService.addListener(recorder);

		taskService.onKill(new KillTracker.Kill("Cow", 2, 1, 10, 7, false, 3, false, null));

		Assert.assertTrue("an off-contract kill credits nothing to share",
			recorder.progress.isEmpty());
	}

	// --- B. the re-read stays per-iteration ---

	@Test
	public void listenerThatEndsTheContractSilencesTheOnesBehindIt()
	{
		seedContract("Party of 2");
		Recorder first = new Recorder()
		{
			@Override
			public void onPartyProgress(ActiveTask task)
			{
				super.onPartyProgress(task);
				// there is no abandonTask() in the plugin, but a listener CAN end
				// the contract (completion clears it the same way), and the check
				// lives inside the loop precisely so the rest of the fan-out sees it
				stateService.mutate(s -> s.withActiveTask(null));
			}
		};
		Recorder second = new Recorder();
		taskService.addListener(first);
		taskService.addListener(second);

		taskService.onKill(goblinKill(10));

		Assert.assertEquals("the listener that ran first still gets told",
			1, first.progress.size());
		Assert.assertNotNull(first.progress.get(0));
		Assert.assertTrue("the contract was gone before the second listener's turn",
			second.progress.isEmpty());
	}

	@Test
	public void listenerThatConvertsTheContractToSoloSilencesTheOnesBehindIt()
	{
		seedContract("Party of 2");
		Recorder first = new Recorder()
		{
			@Override
			public void onPartyProgress(ActiveTask task)
			{
				super.onPartyProgress(task);
				// isParty() goes false without the task going null: the guard has to
				// re-test the flag, not merely the presence of a contract
				stateService.mutate(s -> s.withActiveTask(
					s.getActiveTask().withPartyConvertedToSolo(true)));
			}
		};
		Recorder second = new Recorder();
		taskService.addListener(first);
		taskService.addListener(second);

		taskService.onKill(goblinKill(10));

		Assert.assertEquals(1, first.progress.size());
		Assert.assertTrue("a carried contract is nobody else's business",
			second.progress.isEmpty());
	}

	// --- C. one observation per listener, not four ---

	@Test
	public void fanOutCostsExactlyOneStateReadPerListener()
	{
		// Measured as a DELTA between two otherwise identical kills, so the test
		// pins the per-listener cost of the fan-out without hardcoding the total
		// number of reads onKill makes — that total is free to move.
		int withOne = readsForOneKillWith(1);
		int withFour = readsForOneKillWith(4);

		Assert.assertEquals("three extra listeners may cost three extra state reads,"
			+ " not twelve", 3, withFour - withOne);
	}

	/** Fresh harness, n party-progress listeners, one credited kill; returns get() calls. */
	private int readsForOneKillWith(int listenerCount)
	{
		setUp(); // rebuild against a fresh counter so the delta is clean
		seedContract("Party of 2");
		for (int i = 0; i < listenerCount; i++)
		{
			// deliberately NOT a listener that reads state itself: the only reads
			// this test may attribute to the fan-out are the fan-out's own
			taskService.addListener(new Recorder());
		}
		int before = stateService.gets;
		taskService.onKill(goblinKill(10));
		return stateService.gets - before;
	}
}

package com.gachaman.service;

import com.google.gson.*;

/**
 * One way to build a {@link StyleService} for a headless test, so that the
 * wheel's two collaborators are wired the way Guice wires them in production.
 *
 * <p>It exists because of the RNG. The wheel draws the style and then the weapon
 * category from the SAME injected singleton, and a test that handed each service
 * its own {@code new GachaRng(seed)} would give both the identical stream —
 * every style would arrive paired with the category at the same index of its
 * pool, forever, and a test asserting the pairing looked random would be
 * asserting nothing. Passing one instance through here is what keeps a seeded
 * harness honest.
 *
 * <p>The {@code null} Client is safe and deliberate: {@link WeaponTypeService}
 * dereferences the client only to read the category DB table, which is the
 * kill-time lookup, and never to roll — the taxonomy it rolls from is the shipped
 * JSON resource. See that class's "which thread" note.
 */
final class StyleFixture
{
	private StyleFixture()
	{
	}

	/** A StyleService over the real shipped taxonomy, sharing {@code rng} with it. */
	static StyleService styleService(GachaStateService stateService,
		ComplianceService complianceService, CeremonyBus ceremonyBus, GachaRng rng)
	{
		return styleService(stateService, complianceService, ceremonyBus, rng,
			new WeaponTypeService(null, new Gson(), rng));
	}

	/**
	 * The same, with the taxonomy supplied — for a test that needs to hold the
	 * service it is asserting against, or to substitute one that names nothing.
	 */
	static StyleService styleService(GachaStateService stateService,
		ComplianceService complianceService, CeremonyBus ceremonyBus, GachaRng rng,
		WeaponTypeService weaponTypeService)
	{
		return new StyleService(stateService, complianceService, ceremonyBus, rng,
			weaponTypeService);
	}
}

package com.gachaman.service;

import com.gachaman.*;
import com.gachaman.data.*;
import com.gachaman.model.*;
import java.util.*;
import org.junit.*;

/** Pure math for the early-game round: combo, fragments, bestiary, stardust bands. */
public class EarlyGameMathTest
{
	@Test
	public void comboLadderIsFlatQuarterSteps()
	{
		// the whole ladder, spelled out rather than derived — the point of the
		// rewrite was that a player can read it, so a typo in the step must fail
		double[] expected = {1.0, 1.25, 1.5, 1.75, 2.0, 2.25, 2.5};
		Assert.assertEquals(expected.length, Tuning.COMBO_MAX_STACKS + 1);
		for (int stacks = 0; stacks < expected.length; stacks++)
		{
			Assert.assertEquals("stack " + stacks, expected[stacks],
				Tuning.comboMultiplier(stacks), 1e-9);
		}
		// above the cap clamps, below zero clamps
		Assert.assertEquals(2.5, Tuning.comboMultiplier(99), 1e-9);
		Assert.assertEquals(1.0, Tuning.comboMultiplier(-5), 1e-9);
	}

	@Test
	public void comboStacksAreEarnedEveryFiveKills()
	{
		Assert.assertEquals(0, Tuning.comboStacks(0));
		// four kills is still nothing — the stack lands on the fifth
		Assert.assertEquals(0, Tuning.comboStacks(Tuning.COMBO_KILLS_PER_STACK - 1));
		Assert.assertEquals(1, Tuning.comboStacks(Tuning.COMBO_KILLS_PER_STACK));
		Assert.assertEquals(2, Tuning.comboStacks(2 * Tuning.COMBO_KILLS_PER_STACK));
		// a maxed chain is MAX_STACKS * KILLS_PER_STACK kills deep, and holds there
		Assert.assertEquals(Tuning.COMBO_MAX_STACKS, Tuning.comboStacks(Tuning.COMBO_MAX_KILLS));
		Assert.assertEquals(Tuning.COMBO_MAX_STACKS, Tuning.comboStacks(Tuning.COMBO_MAX_KILLS * 9));
		Assert.assertEquals(0, Tuning.comboStacks(-3));
	}

	@Test
	public void everyPerKillBaseStaysWholeAcrossTheLadder()
	{
		// the ladder is only readable because a quarter step never produces a
		// fraction of a GC; a base that is not a multiple of 4 would break that
		for (int gc : Tuning.PER_KILL_GC.values())
		{
			Assert.assertEquals("base " + gc + " must be a multiple of 4", 0, gc % 4);
			for (int stacks = 0; stacks <= Tuning.COMBO_MAX_STACKS; stacks++)
			{
				double paid = gc * Tuning.comboMultiplier(stacks);
				Assert.assertEquals("base " + gc + " at stack " + stacks,
					Math.rint(paid), paid, 1e-9);
			}
		}
	}

	@Test
	public void milestoneLadderTakesTheHighestTierOnly()
	{
		// ordinary contracts pay flat
		Assert.assertEquals(1.0, Tuning.completionMilestoneMult(1), 1e-9);
		Assert.assertEquals(1.0, Tuning.completionMilestoneMult(4), 1e-9);
		Assert.assertEquals(1.0, Tuning.completionMilestoneMult(99), 1e-9);
		// each tier, and crucially the overlaps: 10 is also a multiple of 5,
		// 100 is a multiple of all of them. Highest wins, they never stack.
		Assert.assertEquals(1.5, Tuning.completionMilestoneMult(5), 1e-9);
		Assert.assertEquals(2.5, Tuning.completionMilestoneMult(10), 1e-9);
		Assert.assertEquals(5.0, Tuning.completionMilestoneMult(50), 1e-9);
		Assert.assertEquals(10.0, Tuning.completionMilestoneMult(100), 1e-9);
		Assert.assertEquals(15.0, Tuning.completionMilestoneMult(250), 1e-9);
		// and it repeats rather than firing once
		Assert.assertEquals(10.0, Tuning.completionMilestoneMult(200), 1e-9);
		Assert.assertEquals(2.5, Tuning.completionMilestoneMult(110), 1e-9);
		// zero is "no contracts finished", not "a multiple of everything" —
		// without the guard the modulo would call it a x15 milestone
		Assert.assertEquals(1.0, Tuning.completionMilestoneMult(0), 1e-9);
		Assert.assertEquals(1.0, Tuning.completionMilestoneMult(-5), 1e-9);
	}

	@Test
	public void milestoneLadderKeepsTheAverageModest()
	{
		// the property that stops the ladder quietly becoming the economy: the
		// peaks are dramatic but the mean lift over a long run stays near +30%.
		double sum = 0;
		for (int n = 1; n <= 1000; n++)
		{
			sum += Tuning.completionMilestoneMult(n);
		}
		double mean = sum / 1000.0;
		Assert.assertTrue("average lift was " + mean, mean > 1.2 && mean < 1.45);
	}

	@Test
	public void fragmentMapping()
	{
		Assert.assertEquals(0, Tuning.fragmentsFor(TaskDifficulty.EASY));
		Assert.assertEquals(1, Tuning.fragmentsFor(TaskDifficulty.MEDIUM));
		Assert.assertEquals(2, Tuning.fragmentsFor(TaskDifficulty.HARD));
		Assert.assertEquals(3, Tuning.fragmentsFor(TaskDifficulty.INSANE));
		// all-hard across the whole window exactly forges; mediums-only misses
		Assert.assertEquals(Tuning.FRAGMENTS_REQUIRED,
			Tuning.FRAGMENT_WINDOW_TASKS * Tuning.fragmentsFor(TaskDifficulty.HARD));
		Assert.assertTrue(Tuning.FRAGMENT_WINDOW_TASKS * Tuning.fragmentsFor(TaskDifficulty.MEDIUM)
			< Tuning.FRAGMENTS_REQUIRED);
	}

	@Test
	public void bestiaryMilestonesAreConsistent()
	{
		Assert.assertEquals(Tuning.BESTIARY_MILESTONES.length, Tuning.BESTIARY_MILESTONE_GC.length);
		int prev = 0;
		for (int milestone : Tuning.BESTIARY_MILESTONES)
		{
			Assert.assertTrue(milestone > prev);
			prev = milestone;
		}
	}

	@Test
	public void rustyRollsCommonOnly()
	{
		double[] odds = Tuning.CHEST_ODDS.get(Tuning.Chest.RUSTY);
		Assert.assertEquals(0, odds[Rarity.UNCOMMON.ordinal()], 1e-9);
		Assert.assertEquals(0, odds[Rarity.RARE.ordinal()], 1e-9);
		Assert.assertEquals(0, odds[Rarity.EPIC.ordinal()], 1e-9);
		Assert.assertEquals(0, odds[Rarity.LEGENDARY.ordinal()], 1e-9);
		// structural guarantee: rollRarity can only ever land COMMON
		ChestService service = new ChestService(null, null, null, null,
			new GachaRng(42L), new com.google.gson.Gson(), null, null, null);
		for (int i = 0; i < 50_000; i++)
		{
			Assert.assertEquals(Rarity.COMMON, service.rollRarity(odds, 0));
		}
		// Rusty is priced, deals one card, and rolls no deeds
		Assert.assertEquals(150, (int) Tuning.CHEST_PRICE_GC.get(Tuning.Chest.RUSTY));
		Assert.assertEquals(1, (int) Tuning.CHEST_CARDS.get(Tuning.Chest.RUSTY));
		Assert.assertFalse(Tuning.DEED_CHANCE.containsKey(Tuning.Chest.RUSTY));
	}

	@Test
	public void shinyNearMissBandsBehave()
	{
		ChestService service = new ChestService(null, null, null, null,
			new GachaRng(1234L), new com.google.gson.Gson(), null, null, null);
		List<CardDefinition> pool = new ArrayList<>();
		pool.add(new CardDefinition(1, "Bronze scimitar", GearSlot.WEAPON, "bronze", 1,
			"scimitar", Rarity.COMMON, Set.of(1), true));

		int n = 200_000;
		int shiny = 0;
		int nearMiss = 0;
		for (int i = 0; i < n; i++)
		{
			ChestService.RolledSlot slot = service.rollSlot(pool, Rarity.COMMON, false,
				Tuning.SHINY_CHANCE, 1, Set.of());
			if (slot.getVariant() == Variant.SHINY)
			{
				shiny++;
				Assert.assertFalse("a shiny can never also be a near-miss", slot.isNearMiss());
			}
			else if (slot.isNearMiss())
			{
				nearMiss++;
			}
		}
		double shinyRate = shiny / (double) n;
		double nearMissRate = nearMiss / (double) n;
		Assert.assertEquals(Tuning.SHINY_CHANCE, shinyRate, Tuning.SHINY_CHANCE * 0.2);
		// near-miss band is (mult - 1) times the shiny mass
		double expectedNearMiss = Tuning.SHINY_CHANCE * (Tuning.STARDUST_NEAR_MISS_MULT - 1);
		Assert.assertEquals(expectedNearMiss, nearMissRate, expectedNearMiss * 0.2);
	}

	@Test
	public void blessedDoubleAttemptRoughlyDoublesShiny()
	{
		List<CardDefinition> pool = new ArrayList<>();
		pool.add(new CardDefinition(1, "Bronze scimitar", GearSlot.WEAPON, "bronze", 1,
			"scimitar", Rarity.COMMON, Set.of(1), true));
		int n = 150_000;

		ChestService single = new ChestService(null, null, null, null,
			new GachaRng(9L), new com.google.gson.Gson(), null, null, null);
		int shinySingle = 0;
		for (int i = 0; i < n; i++)
		{
			if (single.rollSlot(pool, Rarity.COMMON, false, Tuning.SHINY_CHANCE, 1, Set.of())
				.getVariant() == Variant.SHINY)
			{
				shinySingle++;
			}
		}
		ChestService blessed = new ChestService(null, null, null, null,
			new GachaRng(9L), new com.google.gson.Gson(), null, null, null);
		int shinyBlessed = 0;
		for (int i = 0; i < n; i++)
		{
			if (blessed.rollSlot(pool, Rarity.COMMON, false, Tuning.SHINY_CHANCE, 2, Set.of())
				.getVariant() == Variant.SHINY)
			{
				shinyBlessed++;
			}
		}
		Assert.assertTrue("blessed (" + shinyBlessed + ") must clearly beat single (" + shinySingle + ")",
			shinyBlessed > shinySingle * 1.6);
	}

	@Test
	public void unshinyEligibleCardsNeverSparkle()
	{
		ChestService service = new ChestService(null, null, null, null,
			new GachaRng(5L), new com.google.gson.Gson(), null, null, null);
		List<CardDefinition> pool = new ArrayList<>();
		pool.add(new CardDefinition(2, "Training sword", GearSlot.WEAPON, null, 0,
			null, Rarity.COMMON, Set.of(2), false));
		for (int i = 0; i < 10_000; i++)
		{
			ChestService.RolledSlot slot = service.rollSlot(pool, Rarity.COMMON, false,
				Tuning.RUSTY_SHINY_CHANCE, 2, Set.of());
			Assert.assertEquals(Variant.NORMAL, slot.getVariant());
			Assert.assertFalse(slot.isNearMiss());
		}
	}
}

package com.gachaman.service;

