	}

	/**
	 * Defaults first, caller's tweaks last — a plain builder argument would let
	 * the shared defaults silently overwrite whatever the test asked for.
	 */
	private void seedContract(Consumer<ActiveTask.ActiveTaskBuilder> tweaks)
	{
		ActiveTask.ActiveTaskBuilder builder = ActiveTask.builder()
			.difficulty(TaskDifficulty.EASY)
			.monsterName("Goblin")
			.killsRequired(1) // one kill away, so a single onKill reaches completeTask()
			.killsDone(0)
			.perKillGc(0) // keeps the null client out of onKill
			.completionGc(1000)
			.acceptedAtMs(System.currentTimeMillis() - RUN_MS);
		tweaks.accept(builder);
		ActiveTask task = builder.build();
		stateService.mutate(s -> s.withActiveTask(task));
	}

	private void seedSoloContract()
	{
		seedContract(b ->
		{
		});
	}

	private List<ContractRecord> log()
	{
		return stateService.get().getContractLog();
	}

	private ContractRecord onlyRecord()
	{
		Assert.assertEquals("exactly one completion must fire", 1, completions.size());
		Assert.assertEquals("exactly one record must be filed", 1, log().size());
		return log().get(0);
	}

	// --- A. the record a completion files ---

	@Test
	public void completingAContractFilesOneRecord()
	{
		long before = System.currentTimeMillis();
		seedSoloContract();
		taskService.onKill(goblinKill(10));

		ContractRecord record = onlyRecord();
		Assert.assertEquals("Goblin", record.getMonsterName());
		Assert.assertEquals("EASY", record.getDifficulty());
		Assert.assertEquals(1, record.getKills());
		Assert.assertEquals("solo contracts carry no party label", null, record.getParty());
		Assert.assertFalse(record.isParty());
		Assert.assertFalse(record.isCarried());
		Assert.assertFalse(record.isRedemption());
		Assert.assertTrue("no forbidden attack was ever made", record.isClean());
		Assert.assertEquals(0, record.getTaintedKills());
		Assert.assertTrue("the filed timestamp is the completion, not the accept",
			record.getAt() >= before);
		Assert.assertTrue("duration must be measured from acceptedAtMs",
			record.getDurationMs() >= RUN_MS && record.getDurationMs() < RUN_MS + 60_000L);
	}

	@Test
	public void filedGcIsTheWholeHaulTheSummaryReports()
	{
		seedSoloContract();
		taskService.onKill(goblinKill(10));
		// no side bets and perKillGc 0, so the haul IS the completion award — the
		// Dossier and the PersonalBest must never disagree about what a job paid
		Assert.assertEquals(1000, completions.get(0).getCompletionGcAwarded());
		Assert.assertEquals(1000, onlyRecord().getGc());
	}

	@Test
	public void aPartyContractFilesItsLabelAndItsBoostedPay()
	{
		seedContract(b -> b
			.partyLabel("Party of 2")
			.partyStyles(Arrays.asList(AttackStyle.MELEE, AttackStyle.MELEE)));
		taskService.onKill(goblinKill(10));

		ContractRecord record = onlyRecord();
		Assert.assertEquals("Party of 2", record.getParty());
		Assert.assertTrue(record.isParty());
		Assert.assertFalse(record.isCarried());
		Assert.assertEquals("the co-op multiplier must reach the filed pay", 1600, record.getGc());
	}

	@Test
	public void aCarriedContractFilesTheCarryFlagAndNotTheParty()
	{
		// the party dissolved mid-contract: isParty() goes false but the label is
		// still the truth about who it was signed with
		seedContract(b -> b
			.partyLabel("Party of 2")
			.partyStyles(Arrays.asList(AttackStyle.MELEE, AttackStyle.MAGIC))
			.partyConvertedToSolo(true));
		taskService.onKill(goblinKill(10));

		ContractRecord record = onlyRecord();
		Assert.assertTrue(record.isCarried());
		Assert.assertEquals("Party of 2", record.getParty());
		Assert.assertEquals("the carry multiplier, not the clash bonus", 800, record.getGc());
	}

	@Test
	public void aRedemptionContractIsFiledAsOne()
	{
		seedContract(b -> b.redemption(true));
		taskService.onKill(goblinKill(10));
		Assert.assertTrue(onlyRecord().isRedemption());
	}

	@Test
	public void contractsAccumulateNewestLast()
	{
		seedSoloContract();
		taskService.onKill(goblinKill(10));
		seedContract(b -> b.completionGc(2000));
		taskService.onKill(goblinKill(40));

		List<ContractRecord> log = log();
		Assert.assertEquals(2, log.size());
		Assert.assertEquals(1000, log.get(0).getGc());
		Assert.assertEquals("appended, so the newest is last in storage order",
			2000, log.get(1).getGc());
		Assert.assertTrue(log.get(1).getAt() >= log.get(0).getAt());
	}

	// --- B. the style is the one the contract was RUN under ---

	@Test
	public void theFiledStyleIsThePreRollStyle()
	{
		// cycleTarget 1 with progress 0 means this completion tips the style cycle
		// over: the reward re-roll is due. The record must still read MELEE — it
		// is filed inside the completion mutate, BEFORE advanceCycle runs.
		stateService.mutate(s -> s.withAllowedStyle("MELEE").withCycleTarget(1).withCycleProgress(0));
		seedSoloContract();
		taskService.onKill(goblinKill(10));

		Assert.assertTrue("the cycle must actually have tipped for this test to mean anything",
			completions.get(0).isCycleTriggered());
		Assert.assertEquals("MELEE", onlyRecord().getStyle());
	}

	@Test
	public void aContractFinishedBeforeTheFirstStyleRollFilesANullStyle()
	{
		// a fresh account has no allowed style yet; null is honest, and the tab
		// simply omits the segment rather than inventing one
		Assert.assertNull(stateService.get().getAllowedStyle());
		seedSoloContract();
		taskService.onKill(goblinKill(10));
		Assert.assertNull(onlyRecord().getStyle());
	}

	@Test
	public void filedStyleIsASnapshotNotALiveView()
	{
		stateService.mutate(s -> s.withAllowedStyle("MELEE").withCycleTarget(5).withCycleProgress(0));
		seedSoloContract();
		taskService.onKill(goblinKill(10));
		stateService.mutate(s -> s.withAllowedStyle("MAGIC"));
		Assert.assertEquals("a later re-roll must not rewrite history", "MELEE",
			log().get(0).getStyle());
	}

	// --- C. the clean verdict ---

	@Test
	public void anOutOfStyleKillFilesTheContractDirty()
	{
		stateService.mutate(s -> s.withAllowedStyle("MELEE").withCycleTarget(5).withCycleProgress(0));
		seedSoloContract();
		// the kill at tick 10 spans [7, 10], so this attack convicts it
		complianceService.onAttack(AttackStyle.MAGIC, 8);
		taskService.onKill(goblinKill(10));

		ContractRecord record = onlyRecord();
		Assert.assertEquals(1, record.getTaintedKills());
		Assert.assertFalse(record.isClean());
	}

	@Test
	public void oneDirtyKillTaintsTheWholeContractEvenIfTheLastIsClean()
	{
		// the counter LATCHES: "was the contract clean" is not "was the final kill
		// clean". This is the whole point of counting rather than flagging.
		stateService.mutate(s -> s.withAllowedStyle("MELEE").withCycleTarget(5).withCycleProgress(0));
		seedContract(b -> b.killsRequired(2));
		complianceService.onAttack(AttackStyle.MAGIC, 8);
		taskService.onKill(goblinKill(10)); // convicted by the tick-8 attack
		taskService.onKill(goblinKill(30)); // spans [27, 30] — nothing to convict it

		ContractRecord record = onlyRecord();
		Assert.assertEquals(1, record.getTaintedKills());
		Assert.assertFalse(record.isClean());
	}

	@Test
	public void aForbiddenAttackOutsideTheKillWindowDoesNotDirtyTheContract()
	{
		// the same death-tick bound the GC penalty already respects: an attack
		// before the engagement started never belonged to this kill
		stateService.mutate(s -> s.withAllowedStyle("MELEE").withCycleTarget(5).withCycleProgress(0));
		seedSoloContract();
		complianceService.onAttack(AttackStyle.MAGIC, 2); // kill 10 spans [7, 10]
		taskService.onKill(goblinKill(10));
		Assert.assertTrue(onlyRecord().isClean());
	}

	@Test
	public void theViolationCounterDoesNotLeakIntoTheNextContract()
	{
		stateService.mutate(s -> s.withAllowedStyle("MELEE").withCycleTarget(9).withCycleProgress(0));
		seedSoloContract();
		complianceService.onAttack(AttackStyle.MAGIC, 8);
		taskService.onKill(goblinKill(10));
		Assert.assertFalse(log().get(0).isClean());

		// a brand new contract starts its own count at zero — the counter lives on
		// the ActiveTask, which the completion mutate cleared
		seedSoloContract();
		taskService.onKill(goblinKill(60));
		Assert.assertEquals(2, log().size());
		Assert.assertTrue("a fresh contract is presumed clean", log().get(1).isClean());
	}
}

package com.gachaman.service;

import java.util.*;
import org.junit.*;

/**
 * A renderer that declines a request must not lose it.
 *
 * <p>This is the contract the TASK_COMPLETE presentation depends on. That
 * ceremony no longer has a screen of its own — it is claimed as the generic
 * fanfare banner, and the renderer therefore DECLINES it whenever a banner is
 * already on screen rather than overwriting whichever celebration was
 * mid-flight.
 *
 * <p>That is only safe if a declined request stays queued and is re-presented
 * when the renderer next frees up. Nothing calls {@code setFallback}, so if the
 * queue instead dropped it — or stalled on it — a contract completion would
 * either vanish or block every ceremony behind it forever. Neither failure
 * raises anything; the player just stops seeing chests open.
 */
public class CeremonyBusDeclineTest
{
	/** Claims nothing while busy, everything otherwise — the overlay's shape. */
	private static class BusyRenderer implements CeremonyBus.Renderer
	{
		private final List<CeremonyBus.Type> presented = new ArrayList<>();
		private boolean busy;

		@Override
		public boolean present(CeremonyBus.Request request)
		{
			if (busy)
			{
				return false;
			}
			presented.add(request.getType());
			return true;
		}
	}

	@Test
	public void aDeclinedRequestIsRepresentedWhenTheRendererFreesUp()
	{
		CeremonyBus bus = new CeremonyBus();
		BusyRenderer renderer = new BusyRenderer();
		bus.addRenderer(renderer);

		renderer.busy = true;
		bus.submit(CeremonyBus.Type.TASK_COMPLETE, "summary");
		Assert.assertTrue("a busy renderer must not present", renderer.presented.isEmpty());

		renderer.busy = false;
		bus.drain();
		Assert.assertEquals("the declined request was dropped instead of re-presented",
			List.of(CeremonyBus.Type.TASK_COMPLETE), renderer.presented);
	}

	@Test
	public void aDeclinedRequestDoesNotBlockTheOnesBehindIt()
	{
		// the queue is FIFO and only drains while the head is claimable, so a
		// permanently-declined head would starve everything after it. Proven by
		// draining once free: both arrive, in order.
		CeremonyBus bus = new CeremonyBus();
		BusyRenderer renderer = new BusyRenderer();
		bus.addRenderer(renderer);

		renderer.busy = true;
		bus.submit(CeremonyBus.Type.TASK_COMPLETE, "summary");
		bus.submit(CeremonyBus.Type.STYLE_ROLL, "roll");

		renderer.busy = false;
		bus.drain(); // presents the head
		bus.drain(); // the overlay's own "I am free again" call
		Assert.assertEquals(List.of(CeremonyBus.Type.TASK_COMPLETE, CeremonyBus.Type.STYLE_ROLL),
			renderer.presented);
	}

	@Test
	public void tapsSeeEveryRequestEvenOneNobodyPresents()
	{
		// TimelineService records contract completions off a tap. If a tap only
		// fired for CLAIMED requests, declining while busy would silently drop
		// the completion out of the player's timeline.
		CeremonyBus bus = new CeremonyBus();
		BusyRenderer renderer = new BusyRenderer();
		bus.addRenderer(renderer);
		List<CeremonyBus.Type> tapped = new ArrayList<>();
		bus.addTap(request -> tapped.add(request.getType()));

		renderer.busy = true;
		bus.submit(CeremonyBus.Type.TASK_COMPLETE, "summary");

		Assert.assertEquals(List.of(CeremonyBus.Type.TASK_COMPLETE), tapped);
		Assert.assertTrue(renderer.presented.isEmpty());
	}
}

package com.gachaman.service;

import java.util.*;
import org.junit.*;

/**
 * The party layer's identity, and the trust boundary around it.
 *
 * The key is the one thing in the party protocol that is claimed rather than
 * observed, so the tests that matter most here are the negative ones: what a
 * hostile or broken client can put on the wire must come back as "unknown",
 * never as a group, and never as an unbounded string headed for a save key.
 */
public class AccountKeyTest
{
	@Test
	public void aKeyIsSixteenLowercaseHexCharacters()
	{
		String key = AccountKey.of(123456789L);
		Assert.assertNotNull(key);
		Assert.assertEquals(AccountKey.KEY_LENGTH, key.length());
		Assert.assertTrue("the wire format is exactly what normalize accepts",
			key.matches("[0-9a-f]{16}"));
		Assert.assertEquals("already canonical, so normalizing is a no-op",
			key, AccountKey.normalize(key));
	}

	@Test
	public void theKeyIsNotTheAccountHash()
	{
		// the whole reason this hashes rather than forwarding: the account hash
		// is a permanent cross-session correlator AND the input RuneLite derives
		// the RS profile key from. Handing it to every member of every party is
		// strictly more than "this is the same person I rolled with last week".
		long hash = 4611686018427387904L;
		String key = AccountKey.of(hash);
		Assert.assertNotNull(key);
		Assert.assertNotEquals(Long.toString(hash), key);
		Assert.assertNotEquals(Long.toHexString(hash), key);
		Assert.assertFalse("no substring of the raw value may survive",
			Long.toString(hash).contains(key) || key.contains(Long.toHexString(hash)));
	}

	@Test
	public void theSameAccountAlwaysProducesTheSameKey()
	{
		// a mark that reset every login would put tier II out of reach entirely,
		// which is the exact failure the member id had
		Assert.assertEquals(AccountKey.of(777L), AccountKey.of(777L));
		Assert.assertNotEquals(AccountKey.of(777L), AccountKey.of(778L));
		Assert.assertNotEquals(AccountKey.of(Long.MIN_VALUE), AccountKey.of(Long.MAX_VALUE));
	}

	@Test
	public void distinctAccountsDoNotCollideAtPartySize()
	{
		// 16 hex characters is 64 bits. This does not prove the bound, it pins
		// the property the bound exists for: a party is single digits, and even
		// a few thousand consecutive accounts must all read as different people.
		Set<String> keys = new HashSet<>();
		for (long hash = 1; hash <= 5000; hash++)
		{
			Assert.assertTrue("collision at " + hash, keys.add(AccountKey.of(hash)));
		}
	}

	@Test
	public void loggedOutIsNoIdentityRatherThanASharedOne()
	{
		// getAccountHash() returns -1 with nobody logged in. A constant "logged
		// out" key would make every logged-out client in the party the same
		// person, merge their rows into one group and credit them one mark.
		Assert.assertNull(AccountKey.of(AccountKey.NO_ACCOUNT));
		Assert.assertNull("0 is the other not-an-account value", AccountKey.of(0L));
		Assert.assertFalse("two unknowns are not each other",
			AccountKey.same(AccountKey.of(-1L), AccountKey.of(-1L)));
	}

	@Test
	public void normalizeIsTheWireTrustBoundary()
	{
		String key = AccountKey.of(42L);
		Assert.assertEquals("casing is folded, so one account cannot key twice",
			key, AccountKey.normalize(key.toUpperCase(java.util.Locale.ROOT)));
		Assert.assertEquals(key, AccountKey.normalize("  " + key + "  "));

		Assert.assertNull(AccountKey.normalize(null));
		Assert.assertNull(AccountKey.normalize(""));
		Assert.assertNull("15 characters is not a key", AccountKey.normalize("00112233445566a"));
		Assert.assertNull("17 characters is not a key", AccountKey.normalize("00112233445566aaa"));
		Assert.assertNull("g is not hex", AccountKey.normalize("00112233445566ag"));
		Assert.assertNull(AccountKey.normalize("0011223344 5566a"));
		Assert.assertNull("a display name is not a key", AccountKey.normalize("Zezima"));
	}

	@Test
	public void aHostileKeyCannotGrowTheSaveFile()
	{
		// this string becomes a KEY in the persisted patron ledger, so an
		// unbounded remote value keyed into it is a way to grow somebody else's
		// save file one party message at a time
		StringBuilder huge = new StringBuilder();
		for (int i = 0; i < 100_000; i++)
		{
			huge.append('a');
		}
		Assert.assertNull(AccountKey.normalize(huge.toString()));
		// and the length check runs before the alphabet scan, so the rejection
		// does not depend on finding a bad character
		Assert.assertNull(AccountKey.normalize(huge.toString().replace('a', 'z')));
	}

	@Test
	public void sameIsNotObjectsEquals()
	{
		String key = AccountKey.of(9L);
		Assert.assertTrue(AccountKey.same(key, key));
		Assert.assertTrue("both sides are normalized before comparing",
			AccountKey.same(key, "  " + key.toUpperCase(java.util.Locale.ROOT) + "  "));
		Assert.assertFalse(AccountKey.same(key, AccountKey.of(10L)));

		// the reason this method exists at all: a null is "I do not know who
		// this is", and two of them are not a match. Objects.equals says true.
		Assert.assertFalse(AccountKey.same(null, null));
		Assert.assertFalse(AccountKey.same(key, null));
		Assert.assertFalse(AccountKey.same(null, key));
		Assert.assertFalse("junk is unknown, not a group",
			AccountKey.same("not-a-key", "not-a-key"));
	}
}

package com.gachaman.service;

import com.gachaman.*;
import com.gachaman.data.*;
import com.gachaman.model.*;
import java.util.*;
import org.junit.*;

import static com.gachaman.service.LoadoutFixture.*;

/**
 * PermissionService.itemIdsFor is the per-loadout-entry branch of rebuild,
 * lifted out so the unassign guard can ask rebuild's own question. The lift
 * has to be behaviour-preserving, and "I moved it carefully" is not evidence.
 *
 * <p>{@link #oracle} is the loop exactly as it read before the extraction,
 * kept verbatim on purpose: it is the only copy of the old behaviour that
 * still exists, and comparing rebuild against it over a generated album is
 * what makes the refactor checkable rather than merely plausible.
 */
public class PermissionItemIdsForTest
{
	private GachaStateService stateService;
	private LoadoutFixture.Cards cards;
	private GachamanConfig config;
	private PermissionService permissions;

	@Before
	public void setUp()
	{
		stateService = inMemoryStateService();
		cards = new LoadoutFixture.Cards();
		config = config(true);
		permissions = new PermissionService(stateService, cards, null, config);
		deedEverySlot(stateService);
	}

	/**
	 * The rebuild loop's per-entry branch, verbatim as it stood before
	 * itemIdsFor existed. Do not "tidy" this — its whole value is being an
	 * independent copy of the old code.
	 */
	private static Set<Integer> oracle(GachaState state, CardDatabase db)
	{
		Set<Integer> allowed = new HashSet<>();
		Map<String, OwnedCard> byUuid = new HashMap<>();
		for (OwnedCard card : state.getOwnedCards())
		{
			byUuid.put(card.getUuid(), card);
		}
		for (Map.Entry<String, String> entry : state.getLoadout().entrySet())
		{
			GearSlot slot;
			try
			{
				slot = GearSlot.valueOf(entry.getKey());
			}
			catch (IllegalArgumentException e)
			{
				continue;
			}
			OwnedCard owned = byUuid.get(entry.getValue());
			if (owned == null)
			{
				continue;
			}
			if (owned.isHologram())
			{
				for (CardDefinition card : db.all().values())
				{
					if (owned.getTierKey().equals(card.getTierKey()) && card.getSlot() == slot)
					{
						allowed.addAll(card.getItemIds());
					}
				}
				continue;
			}
			CardDefinition card = db.card(owned.getCardId());
			if (card == null || card.getSlot() != slot)
			{
				continue;
			}
			allowed.addAll(card.getItemIds());
			if (owned.getVariant() == Variant.SHINY && card.getFamilyKey() != null)
			{
				for (CardDefinition member : db.family(card.getFamilyKey()))
				{
					if (member.getTierRank() <= card.getTierRank())
					{
						allowed.addAll(member.getItemIds());
					}
				}
			}
		}
		return allowed;
	}

	/** Union of the extracted branch over every loadout entry. */
	private Set<Integer> viaExtraction(GachaState state)
	{
		Map<String, OwnedCard> byUuid = new HashMap<>();
		for (OwnedCard card : state.getOwnedCards())
		{
			byUuid.put(card.getUuid(), card);
		}
		Set<Integer> allowed = new HashSet<>();
		for (Map.Entry<String, String> entry : state.getLoadout().entrySet())
		{
			allowed.addAll(permissions.itemIdsFor(byUuid.get(entry.getValue()),
				GearSlot.valueOf(entry.getKey())));
		}
		return allowed;
	}

	/**
	 * Album generator: every slot holds a card, and which KIND of card rotates
	 * with the permutation index so that across the runs each slot has been
	 * plain, shiny and hologram, at several tiers.
	 */
	private List<OwnedCard> deal(int permutation)
	{
		List<OwnedCard> album = new ArrayList<>();
		GearSlot[] slots = GearSlot.values();
		for (int i = 0; i < slots.length; i++)
		{
			GearSlot slot = slots[i];
			String tierKey = TIERS.get((permutation + i) % TIERS.size());
			switch ((permutation + i) % 3)
			{
				case 0:
					album.add(plain(slot, tierKey));
					break;
				case 1:
					album.add(shiny(slot, tierKey));
					break;
				default:
					album.add(hologram(slot, tierKey));
					break;
			}
		}
		return album;
	}

	@Test
	public void theExtractedBranchReproducesTheOldRebuildLoopExactly()
	{
		// 33 permutations: 3 card kinds x 11 slot offsets, so every slot has
		// been every kind, and the tier walked past every rung of the ladder
		for (int permutation = 0; permutation < 33; permutation++)
		{
			List<OwnedCard> album = deal(permutation);
			stateService.mutate(s -> s.withOwnedCards(album));
			Map<String, String> loadout = new HashMap<>();
			for (int i = 0; i < GearSlot.values().length; i++)
			{
				loadout.put(GearSlot.values()[i].name(), album.get(i).getUuid());
			}
			stateService.mutate(s -> s.withLoadout(loadout));

			GachaState state = stateService.get();
			Set<Integer> expected = oracle(state, cards);
			Assert.assertFalse("permutation " + permutation + " permitted nothing, so it"
				+ " would have agreed with a broken extraction too", expected.isEmpty());
			Assert.assertEquals("permutation " + permutation,
				expected, viaExtraction(state));

			// ...and through the only door the rest of the plugin uses. Every
			// slot is deeded and TutorialGate reads false with a null Client,
			// so isForbidden here is exactly "not in the allowed set".
			permissions.refresh();
			for (int itemId : cards.everyItemId())
			{
				Assert.assertEquals("permutation " + permutation + ", item " + itemId,
					!expected.contains(itemId), permissions.isForbidden(itemId));
			}
		}
	}

	@Test
	public void aHologramGrantsItsTierOnlyInTheSlotItSitsIn()
	{
		OwnedCard holo = hologram(GearSlot.WEAPON, "dragon");
		Set<Integer> weapon = permissions.itemIdsFor(holo, GearSlot.WEAPON);
		Assert.assertTrue(weapon.contains(itemId(GearSlot.WEAPON, "dragon")));
		Assert.assertTrue(weapon.contains(variantItemId(GearSlot.WEAPON, "dragon")));
		Assert.assertFalse("a weapon hologram permits no body armour",
			weapon.contains(itemId(GearSlot.BODY, "dragon")));
		Assert.assertFalse("nor a lower tier of its own slot",
			weapon.contains(itemId(GearSlot.WEAPON, "rune")));

		Assert.assertTrue("the same instance in BODY grants dragon body armour",
			permissions.itemIdsFor(holo, GearSlot.BODY)
				.contains(itemId(GearSlot.BODY, "dragon")));
	}

	@Test
	public void aShinyReachesDownItsFamilyAndNoFurther()
	{
		Set<Integer> ids = permissions.itemIdsFor(shiny(GearSlot.WEAPON, "rune"), GearSlot.WEAPON);
		for (String tierKey : TIERS)
		{
			boolean lowerOrEqual = TIERS.indexOf(tierKey) <= TIERS.indexOf("rune");
			Assert.assertEquals(tierKey, lowerOrEqual,
				ids.contains(itemId(GearSlot.WEAPON, tierKey)));
		}
		Assert.assertFalse("and never leaves the slot",
			ids.contains(itemId(GearSlot.BODY, "bronze")));
	}

	@Test
	public void aPlainCardGrantsOnlyItsOwnItemIds()
	{
		Set<Integer> ids = permissions.itemIdsFor(plain(GearSlot.WEAPON, "rune"), GearSlot.WEAPON);
		Assert.assertEquals(new HashSet<>(Arrays.asList(
			itemId(GearSlot.WEAPON, "rune"), variantItemId(GearSlot.WEAPON, "rune"))), ids);
	}

	/** A card in the wrong slot grants nothing, which is what makes the guard a set test. */
	@Test
	public void aCardInTheWrongSlotGrantsNothing()
	{
		Assert.assertTrue(permissions.itemIdsFor(plain(GearSlot.WEAPON, "rune"), GearSlot.BODY)
			.isEmpty());
		Assert.assertTrue(permissions.itemIdsFor(null, GearSlot.WEAPON).isEmpty());
		Assert.assertTrue(permissions.itemIdsFor(plain(GearSlot.WEAPON, "rune"), null).isEmpty());
	}

	/** Fail-open: an unbuilt card database must permit nothing rather than throw. */
	@Test
	public void anUnreadyDatabaseGrantsNothingAndDoesNotThrow()
	{
		CardDatabase notReady = new CardDatabase(null, null, null, null, null);
		PermissionService cold = new PermissionService(stateService, notReady, null, config);
		Assert.assertTrue(cold.itemIdsFor(plain(GearSlot.WEAPON, "rune"), GearSlot.WEAPON)
			.isEmpty());
	}
}

package com.gachaman.service;

import com.gachaman.data.*;
import com.gachaman.model.*;
import com.google.gson.*;
import java.util.*;
import java.util.function.*;
import org.junit.*;

/**
 * First Colours: the steered pick, and the flag that makes the gift happen
 * exactly once per account no matter where the client dies.
 */
public class FirstColoursConstraintTest
{
	private static CardDefinition card(int id, String name)
	{
		return new CardDefinition(id, name, GearSlot.WEAPON, null, 0, null,
			Rarity.COMMON, Set.of(id), true);
	}

	private static List<CardDefinition> pool()
	{
		return new ArrayList<>(Arrays.asList(
			card(1, "Bronze scimitar"),
			card(2, "Shortbow"),
			card(3, "Staff"),
			card(4, "Iron mace")));
	}

	@Test
	public void nullConstraintHandsBackTheVerySameList()
	{
		// THE determinism guarantee. rng.pick is nextInt(list.size()), so an
		// unconstrained draw must see a list built exactly as it was before this
		// feature existed — same instance, therefore same size, therefore the
		// same number of Random.next() calls consumed. Every fixed-seed test in
		// the suite depends on this identity.
		List<CardDefinition> candidates = pool();
		Assert.assertSame(candidates, ChestService.constrained(candidates, null));
	}

	@Test
	public void aConstraintThatMatchesNothingHandsBackTheFullList()
	{
		// the steer is a preference, never a filter: a chest must always deal
		List<CardDefinition> candidates = pool();
		Predicate<CardDefinition> impossible = c -> c.getCardId() == 999;
		Assert.assertSame(candidates, ChestService.constrained(candidates, impossible));
	}

	@Test
	public void aMatchingConstraintNarrowsToExactlyThoseCardsInOrder()
	{
		List<CardDefinition> candidates = pool();
		Set<Integer> preferred = Set.of(3, 1);
		List<CardDefinition> narrowed = ChestService.constrained(candidates,
			c -> preferred.contains(c.getCardId()));

		Assert.assertEquals(2, narrowed.size());
		// relative order is preserved, so a fixed seed picks predictably
		Assert.assertEquals(1, narrowed.get(0).getCardId());
		Assert.assertEquals(3, narrowed.get(1).getCardId());
		// and the caller's list was not mutated out from under it
		Assert.assertEquals(4, candidates.size());
	}

	@Test
	public void aConstraintMatchingEverythingStillNarrowsToEverything()
	{
		List<CardDefinition> candidates = pool();
		List<CardDefinition> narrowed = ChestService.constrained(candidates, c -> true);
		Assert.assertEquals(candidates, narrowed);
	}

	@Test
	public void anEmptyListSurvivesAnyConstraint()
	{
		List<CardDefinition> empty = new ArrayList<>();
		Assert.assertSame(empty, ChestService.constrained(empty, null));
		Assert.assertSame(empty, ChestService.constrained(empty, c -> true));
		Assert.assertSame(empty, ChestService.constrained(empty, c -> false));
	}

	@Test
	public void theGiftIsDueOnlyWhenEverySafetyTermAgrees()
	{
		GachaState owed = GachaState.fresh(3).withFirstColoursChestOwed(true);
		Assert.assertTrue(ChestService.firstColoursDue(owed, false, true));

		// nothing owed: the overwhelmingly common case, every login forever
		Assert.assertFalse(ChestService.firstColoursDue(GachaState.fresh(3), false, true));
		// no state loaded yet
		Assert.assertFalse(ChestService.firstColoursDue(null, false, true));
		// a reveal is already on screen — the modal queue owns the player
		Assert.assertFalse(ChestService.firstColoursDue(owed, true, true));
		// the card database cannot yet say what anything is; rolling now would
		// draw from an empty pool
		Assert.assertFalse(ChestService.firstColoursDue(owed, false, false));
	}

	@Test
	public void theGiftNeverOverwritesAChestThePlayerPaidFor()
	{
		// a client that died mid-reveal left its outcome serialized in state.
		// Dealing the gift before recoverPending commits that blob would
		// silently destroy a bought chest, so the flag waits its turn.
		GachaState interrupted = GachaState.fresh(3)
			.withFirstColoursChestOwed(true)
			.withPendingChestBlob("{\"purchasedTier\":\"ORNATE\"}");
		Assert.assertFalse(ChestService.firstColoursDue(interrupted, false, true));

		// once that blob is committed and cleared, the gift is still owed
		Assert.assertTrue(ChestService.firstColoursDue(
			interrupted.withPendingChestBlob(null), false, true));
	}

	@Test
	public void anEstablishedSaveIsNeverRetroGiftedAChest()
	{
		// The flag is phrased as OWED, not DONE, precisely for this: a save
		// written before the field existed has no key for it, and Gson leaves a
		// missing primitive at false. False must therefore mean "nothing owed" —
		// a "firstColoursDone" flag would read as "not done" and hand every
		// established account a free chest on its next login.
		Gson gson = new Gson();
		String legacy = "{\"gc\":5000,\"allowedStyle\":\"MELEE\",\"totalTasksCompleted\":140}";
		GachaState old = gson.fromJson(legacy, GachaState.class).normalized();

		Assert.assertFalse("a missing key must never owe a gift", old.isFirstColoursChestOwed());
		Assert.assertFalse(ChestService.firstColoursDue(old, false, true));
		// and a brand-new account is not owed one either until the style rolls
		Assert.assertFalse(GachaState.fresh(3).isFirstColoursChestOwed());
	}
}

package com.gachaman.service;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.*;

/**
 * The Double Docket matching rule. Everything here is pure static — the
 * Client/ConfigManager half of {@link SlayerAlignment} is deliberately a single
 * thin method so that this suite can cover the whole decision.
 */
public class SlayerAlignmentTest
{
	@Test
	public void normalizeStripsCaseAndPunctuationAndCollapsesSpaces()
	{
		assertEquals("fire giant", SlayerAlignment.normalize("Fire Giant"));
		assertEquals("kalphite worker", SlayerAlignment.normalize("  Kalphite   Worker  "));
		assertEquals("mounted terrorbird gnome", SlayerAlignment.normalize("Mounted terrorbird-gnome"));
		assertEquals("", SlayerAlignment.normalize(null));
		assertEquals("", SlayerAlignment.normalize("   "));
	}

	@Test
	public void noSlayerTaskMeansNoBonus()
	{
		// The whole feature must fail CLOSED: absent or blank inputs never pay.
		assertFalse(SlayerAlignment.matches("Fire giant", null));
		assertFalse(SlayerAlignment.matches("Fire giant", ""));
		assertFalse(SlayerAlignment.matches("Fire giant", "   "));
		assertFalse(SlayerAlignment.matches(null, "Fire giants"));
		assertFalse(SlayerAlignment.matches("", "Fire giants"));
		assertFalse(SlayerAlignment.matches(null, null));
	}

	@Test
	public void plainPluralAssignmentMatchesSingularContract()
	{
		assertTrue(SlayerAlignment.matches("Fire giant", "Fire giants"));
		assertTrue(SlayerAlignment.matches("Hill giant", "Hill giants"));
		assertTrue(SlayerAlignment.matches("Goblin", "Goblins"));
		assertTrue(SlayerAlignment.matches("Blue dragon", "Blue dragons"));
	}

	@Test
	public void irregularPluralAssignmentsMatch()
	{
		assertTrue(SlayerAlignment.matches("Jelly", "Jellies"));
		assertTrue(SlayerAlignment.matches("Elf warrior", "Elves"));
		assertTrue(SlayerAlignment.matches("Zombie", "Zombies"));
	}

	@Test
	public void alreadySingularAssignmentStillMatches()
	{
		// "Nechryael" has no distinct plural, so the untouched name must remain a
		// candidate or the whole assignment silently stops paying.
		assertTrue(SlayerAlignment.matches("Nechryael", "Nechryael"));
		assertTrue(SlayerAlignment.matches("Aberrant spectre", "Aberrant spectre"));
	}

	@Test
	public void broaderAssignmentCoversSpecificContract()
	{
		assertTrue(SlayerAlignment.matches("Kalphite Worker", "Kalphites"));
		assertTrue(SlayerAlignment.matches("Dust devil", "Dust devils"));
		assertTrue(SlayerAlignment.matches("Greater demon", "Greater demons"));
	}

	@Test
	public void prefixMatchRequiresAWordBoundary()
	{
		// The trailing space in the prefix test is load-bearing: without it these
		// would all pay a bonus for an unrelated monster.
		assertFalse(SlayerAlignment.matches("Ratcatcher", "Rats"));
		assertFalse(SlayerAlignment.matches("Hobgoblin", "Goblins"));
		assertFalse(SlayerAlignment.matches("Bandit", "Bandos"));
	}

	@Test
	public void prefixMatchIsOneDirectionalOnly()
	{
		// A NARROWER assignment does not cover a broader contract: being sent to
		// kill steel dragons is not being sent to kill every dragon.
		assertFalse(SlayerAlignment.matches("Dragon", "Steel dragons"));
		assertFalse(SlayerAlignment.matches("Demon", "Greater demons"));
	}

	@Test
	public void differentSpeciesNeverMatch()
	{
		assertFalse(SlayerAlignment.matches("Fire giant", "Blue dragons"));
		assertFalse(SlayerAlignment.matches("Goblin", "Abyssal demons"));
		assertFalse(SlayerAlignment.matches("Cow", "Chickens"));
	}

	@Test
	public void setValuedAssignmentsAreAKnownWithheldBonus()
	{
		// Documented gap, asserted so it is a CHOICE and not an accident: these
		// category names map to their members through the Slayer plugin's
		// package-private Task enum, which is unreachable from here. Failing
		// closed (no bonus) is the correct direction.
		assertFalse(SlayerAlignment.matches("Steel dragon", "Metal dragons"));
		assertFalse(SlayerAlignment.matches("Guard", "Bandits"));
	}

	@Test
	public void singularCandidatesAlwaysIncludeTheOriginal()
	{
		assertTrue(SlayerAlignment.singularCandidates("nechryael").contains("nechryael"));
		assertTrue(SlayerAlignment.singularCandidates("fire giants").contains("fire giant"));
		assertTrue(SlayerAlignment.singularCandidates("jellies").contains("jelly"));
		assertTrue(SlayerAlignment.singularCandidates("elves").contains("elf"));
		// Only the LAST word is singularised, so a plural head word survives.
		assertTrue(SlayerAlignment.singularCandidates("black demons").contains("black demon"));
		assertFalse(SlayerAlignment.singularCandidates("black demons").contains("black demons "));
	}
}

package com.gachaman.service;

import com.gachaman.data.*;
import com.gachaman.model.*;
import com.google.gson.*;
import java.io.*;
import java.nio.charset.*;
import java.util.*;
import org.junit.*;

public class TaskGeneratorTest
{
	private static List<MonsterTable.Monster> monsters;

	@BeforeClass
	public static void load() throws Exception
	{
		// parse the real bundled dataset via the loader's own Gson shape
		try (InputStreamReader reader = new InputStreamReader(
			TaskGeneratorTest.class.getResourceAsStream("/com/gachaman/data/monsters.json"),
			StandardCharsets.UTF_8))
		{
			MonstersShape shape = new Gson().fromJson(reader, MonstersShape.class);
			monsters = shape.monsters;
		}
		Assert.assertTrue("dataset should have 200+ monsters", monsters.size() >= 200);
	}

	private static class MonstersShape
	{
		List<MonsterTable.Monster> monsters;
	}

	@Test
	public void everyCombatLevelGetsValidOffers()
	{
		GachaRng rng = new GachaRng(1234L);
		for (int cb = 3; cb <= 126; cb++)
		{
			List<TaskOffer> offers = TaskGenerator.generateOffers(monsters, cb, true, false, rng);
			Assert.assertEquals(4, offers.size());
			for (TaskOffer offer : offers)
			{
				Assert.assertNotNull(offer.getMonsterName());
				Assert.assertTrue("kills in range", offer.getKillsRequired() >= offer.getDifficulty().getMinKills());
				// the cap only applies when the pool allows it; sanity: never a boss 3x the player
				if (cb >= 40)
				{
					Assert.assertTrue("cb " + cb + " got monster lvl " + offer.getMonsterCombatLevel(),
						offer.getMonsterCombatLevel() <= cb * offer.getDifficulty().getCbCapFraction() + 1);
				}
			}
		}
	}

	@Test
	public void f2pWorldsNeverGetMembersMonsters()
	{
		GachaRng rng = new GachaRng(99L);
		for (int i = 0; i < 200; i++)
		{
			List<TaskOffer> offers = TaskGenerator.generateOffers(monsters, 80, false, false, rng);
			for (TaskOffer offer : offers)
			{
				MonsterTable.Monster monster = monsters.stream()
					.filter(m -> m.getName().equals(offer.getMonsterName()))
					.findFirst().orElseThrow(AssertionError::new);
				Assert.assertFalse("members monster on f2p: " + monster.getName(), monster.isMembers());
			}
		}
	}

	@Test
	public void taintAddsRedemptionOffer()
	{
		GachaRng rng = new GachaRng(7L);
		List<TaskOffer> offers = TaskGenerator.generateOffers(monsters, 90, true, true, rng);
		Assert.assertEquals(5, offers.size());
		TaskOffer redemption = offers.get(4);
		Assert.assertTrue(redemption.isRedemption());
		Assert.assertEquals(0, redemption.getPerKillGc());
		Assert.assertTrue(redemption.getSideBets().isEmpty());
	}

	@Test
	public void sameSeedProducesIdenticalOffers()
	{
		// party rolls rely on this: every participant rolls with the anchor's
		// seed and must see byte-identical offers
		List<TaskOffer> first = TaskGenerator.generateOffers(monsters, 55, 40, true, false,
			new GachaRng(31337L));
		List<TaskOffer> second = TaskGenerator.generateOffers(monsters, 55, 40, true, false,
			new GachaRng(31337L));
		Assert.assertEquals(first.size(), second.size());
		for (int i = 0; i < first.size(); i++)
		{
			TaskOffer a = first.get(i);
			TaskOffer b = second.get(i);
			Assert.assertEquals(a.getMonsterName(), b.getMonsterName());
			Assert.assertEquals(a.getKillsRequired(), b.getKillsRequired());
			Assert.assertEquals(a.getDifficulty(), b.getDifficulty());
			Assert.assertEquals(a.getSideBets().size(), b.getSideBets().size());
		}
	}

	@Test
	public void slayerGatingFiltersUnreachableMonsters()
	{
		GachaRng rng = new GachaRng(77L);
		List<MonsterTable.Monster> pool = new java.util.ArrayList<>(monsters);
		pool.add(new MonsterTable.Monster("Taskonly Boss", 90, List.of("boss"), true, 0, true,
			false, false, List.of()));
		pool.add(new MonsterTable.Monster("Highslayer Fiend", 90, List.of("slayer"), true, 85,
			false, false, false, List.of()));
		for (int i = 0; i < 300; i++)
		{
			// slayer level 1: neither may ever appear
			for (TaskOffer offer : TaskGenerator.generateOffers(pool, 100, 1, true, false, rng))
			{
				Assert.assertNotEquals("Taskonly Boss", offer.getMonsterName());
				Assert.assertNotEquals("Highslayer Fiend", offer.getMonsterName());
			}
		}
		boolean fiendSeen = false;
		for (int i = 0; i < 500 && !fiendSeen; i++)
		{
			// slayer level 90: the level-gated one becomes rollable, task-only never
			for (TaskOffer offer : TaskGenerator.generateOffers(pool, 100, 90, true, false, rng))
			{
				Assert.assertNotEquals("Taskonly Boss", offer.getMonsterName());
				fiendSeen |= "Highslayer Fiend".equals(offer.getMonsterName());
			}
		}
		Assert.assertTrue("level-gated monster should roll once the level is met", fiendSeen);
	}

	@Test
	public void noMonsterAppearsTwiceInOneRoll()
	{
		GachaRng rng = new GachaRng(4242L);
		for (int trial = 0; trial < 500; trial++)
		{
			for (int cb = 20; cb <= 126; cb += 10)
			{
				List<TaskOffer> offers = TaskGenerator.generateOffers(monsters, cb, true, true, rng);
				long distinct = offers.stream().map(TaskOffer::getMonsterName).distinct().count();
				Assert.assertEquals("duplicate monster at cb " + cb, offers.size(), distinct);
			}
		}
	}

	@Test
	public void insanePaysMoreThanEasy()
	{
		GachaRng rng = new GachaRng(11L);
		List<TaskOffer> offers = TaskGenerator.generateOffers(monsters, 110, true, false, rng);
		TaskOffer easy = offers.get(0);
		TaskOffer insane = offers.get(3);
		Assert.assertTrue(insane.getCompletionGc() > easy.getCompletionGc() * 4);
		Assert.assertTrue(insane.getPerKillGc() > easy.getPerKillGc() * 2);
	}

	@Test
	public void bigHitBetIsAlwaysWinnableByThePlayerItIsDealtTo()
	{
		// the bug this replaced: the threshold came off combat level and was
		// floored at 5, so a combat-12 account whose calculated max is 3 was
		// dealt "land a hit of 6+" and could not win it at all
		Assert.assertTrue("a player who maxes 3 must be dealt 3 or less",
			TaskGenerator.bigHitThreshold(3) <= 3);
		Assert.assertTrue("a player who maxes 6 must be dealt 6 or less",
			TaskGenerator.bigHitThreshold(6) <= 6);
		// winnable for EVERY observed ceiling, which is the whole property
		for (int best = 1; best <= 120; best++)
		{
			Assert.assertTrue("unwinnable at best hit " + best,
				TaskGenerator.bigHitThreshold(best) <= best);
		}
	}

	@Test
	public void bigHitBetFloorsAndClimbsAndCaps()
	{
		// ceiling unreadable (logged out, no style rolled): a low guess, never 0
		Assert.assertEquals(2, TaskGenerator.bigHitThreshold(0));
		// but once a real ceiling is known the guess never overrides it
		Assert.assertEquals(1, TaskGenerator.bigHitThreshold(1));
		// and it tracks the player upward rather than sitting at the floor
		Assert.assertTrue(TaskGenerator.bigHitThreshold(40) > TaskGenerator.bigHitThreshold(10));
		Assert.assertEquals(40, TaskGenerator.bigHitThreshold(999));
	}
}

package com.gachaman.service;

import com.gachaman.*;
import com.gachaman.model.*;
import com.gachaman.persist.*;
import java.util.*;
import org.junit.*;

/**
 * Conviction + pardon round-trip (headless, real in-memory state; the null
 * client skips the tutorial gate and quest-exemption branches).
 */
public class ComplianceServiceTest
{
	private GachaStateService stateService;
	private ComplianceService complianceService;
	private final List<Long> pardonRefunds = new ArrayList<>();
	/** (cleared, remaining) pairs — a pardon must NEVER land in here. */
	private final List<int[]> taintCleared = new ArrayList<>();
	/** (lifted, remaining) pairs from the pardon rollback. */
	private final List<int[]> taintRolledBack = new ArrayList<>();

	private int taint()
	{
		return stateService.get().getTaint();
	}

	private static GachaStateService inMemoryStateService()
	{
		StateStore store = new StateStore(null, null, null)
		{
			@Override
			public void save(GachaState state)
			{
			}

			@Override
			public void save(GachaState state, boolean flushDiskNow)
			{
			}

			@Override
			public GachaState load()
			{
				return null; // forces a fresh in-memory state
			}
		};
		GachaStateService service = new GachaStateService(store);
		service.load(3);
		return service;
	}

	@Before
	public void setUp()
	{
		stateService = inMemoryStateService();
		CreditSink creditSink = new CreditSink(stateService);
		complianceService = new ComplianceService(stateService, creditSink, null, null);
		complianceService.addListener(new ComplianceService.Listener()
		{
			@Override
			public void onForbiddenAttack(AttackStyle used, AttackStyle allowed, long penaltyGc)
			{
			}

			@Override
			public void onTaintAdded(int newTaint)
			{
			}

			@Override
			public void onTaintCleared(int cleared, int remaining)
			{
				taintCleared.add(new int[]{cleared, remaining});
			}

			@Override
			public void onForbiddenPardoned(int tick, long refundedGc)
			{
				pardonRefunds.add(refundedGc);
			}

			@Override
			public void onTaintRolledBack(int lifted, int remaining)
			{
				taintRolledBack.add(new int[]{lifted, remaining});
			}
		});
		stateService.mutate(s -> s.withGc(1000).withAllowedStyle(AttackStyle.MAGIC.name()));
	}

	@Test
	public void pardonRefundsPenaltyAndClearsTaintWindow()
	{
		complianceService.onAttack(AttackStyle.MELEE, 100);
		Assert.assertEquals(1000 - Tuning.VIOLATION_ATTACK_PENALTY_NO_TASK,
			stateService.get().getGc());
		Assert.assertTrue(complianceService.forbiddenAttackBetween(95, 105));
		Assert.assertEquals(100, complianceService.getLastForbiddenAttackTick());

		complianceService.onAttackPardoned(100);
		Assert.assertEquals(1000, stateService.get().getGc());
		Assert.assertFalse(complianceService.forbiddenAttackBetween(95, 105));
		Assert.assertEquals(-1, complianceService.getLastForbiddenAttackTick());
		Assert.assertEquals(100, complianceService.getLastCompliantAttackTick());
		Assert.assertEquals(List.of((long) Tuning.VIOLATION_ATTACK_PENALTY_NO_TASK), pardonRefunds);
	}

	@Test
	public void pardonOnlyLiftsTheMatchingConviction()
	{
		complianceService.onAttack(AttackStyle.MELEE, 100);
		complianceService.onAttack(AttackStyle.MELEE, 104);
		complianceService.onAttackPardoned(100);
		Assert.assertFalse(complianceService.forbiddenAttackBetween(100, 103));
		Assert.assertTrue(complianceService.forbiddenAttackBetween(104, 104));
		Assert.assertEquals(104, complianceService.getLastForbiddenAttackTick());
	}

	@Test
	public void pardonOfACompliantOrUnknownTickIsANoOp()
	{
		complianceService.onAttack(AttackStyle.MAGIC, 100); // compliant
		long gcBefore = stateService.get().getGc();
		complianceService.onAttackPardoned(100);
		complianceService.onAttackPardoned(999);
		Assert.assertEquals(gcBefore, stateService.get().getGc());
		Assert.assertTrue(pardonRefunds.isEmpty());
	}

	/**
	 * The defect: the pardon refunded the GC but left the taint standing, so the
	 * player kept paying the halved-income tax for an attack the plugin had just
	 * declared legal.
	 */
	@Test
	public void pardonRollsBackTheTaintItCaused()
	{
		complianceService.onAttack(AttackStyle.MELEE, 100);
		Assert.assertEquals(100, complianceService.convictingAttackTick(95, 100));
		complianceService.addTaint(100);
		Assert.assertEquals(1, taint());

		complianceService.onAttackPardoned(100);
		Assert.assertEquals(0, taint());
		Assert.assertEquals(1, taintRolledBack.size());
		Assert.assertArrayEquals(new int[]{1, 0}, taintRolledBack.get(0));
		Assert.assertEquals(1000, stateService.get().getGc());
	}

	/**
	 * A pardon must not masquerade as a cleanse: onTaintCleared is what claims
	 * the once-ever FIRST_TAINT_CLEARED stamp and pays its bounty, and nothing
	 * here was worked off.
	 */
	@Test
	public void pardonNeverFiresTaintCleared()
	{
		complianceService.onAttack(AttackStyle.MELEE, 100);
		complianceService.addTaint(100);
		complianceService.onAttackPardoned(100);
		Assert.assertTrue(taintCleared.isEmpty());
		Assert.assertEquals(1, taintRolledBack.size());
	}

	@Test
	public void pardonDoesNotClearUnrelatedTaint()
	{
		complianceService.onAttack(AttackStyle.MELEE, 100);
		complianceService.addTaint(100);
		complianceService.onAttack(AttackStyle.MELEE, 200);
		complianceService.addTaint(200);
		Assert.assertEquals(2, taint());

		complianceService.onAttackPardoned(100);
		Assert.assertEquals(1, taint());
		Assert.assertEquals(200, complianceService.convictingAttackTick(200, 200));
	}

	/** Ledger drift: the point is already gone, so the pardon must lift nothing. */
	@Test
	public void pardonAfterTheTaintWasAlreadyWorkedOff()
	{
		complianceService.onAttack(AttackStyle.MELEE, 100);
		complianceService.addTaint(100);
		complianceService.workOffTaint();
		Assert.assertEquals(0, taint());
		Assert.assertEquals(1, taintCleared.size());

		complianceService.onAttackPardoned(100);
		Assert.assertEquals(0, taint());
		Assert.assertTrue(taintRolledBack.isEmpty());
		Assert.assertEquals(1, taintCleared.size());
	}

	@Test
	public void workOffTaintConsumesOldestConvictionFirst()
	{
		complianceService.onAttack(AttackStyle.MELEE, 100);
		complianceService.addTaint(100);
		complianceService.onAttack(AttackStyle.MELEE, 200);
		complianceService.addTaint(200);
		complianceService.workOffTaint();
		Assert.assertEquals(1, taint());

		complianceService.onAttackPardoned(100); // its point was already worked off
		Assert.assertEquals(1, taint());
		complianceService.onAttackPardoned(200);
		Assert.assertEquals(0, taint());
		complianceService.onAttackPardoned(200); // gone from the deque — no-op
		Assert.assertEquals(0, taint());
	}

	@Test
	public void clearAllTaintZeroesTheLedger()
	{
		complianceService.onAttack(AttackStyle.MELEE, 100);
		complianceService.addTaint(100);
		complianceService.clearAllTaint();
		Assert.assertEquals(0, taint());

		complianceService.onAttackPardoned(100);
		Assert.assertEquals(0, taint());
		Assert.assertTrue(taintRolledBack.isEmpty());
	}

	/**
	 * The winning ordering, which already worked: the pardon beats the deferred
	 * kill, so the kill is judged compliant and no taint is ever added.
	 */
	@Test
	public void pardonBeforeCreditStillPreventsTaintEntirely()
	{
		complianceService.onAttack(AttackStyle.MELEE, 100);
		complianceService.onAttackPardoned(100);
		Assert.assertEquals(-1, complianceService.convictingAttackTick(90, 105));
		Assert.assertFalse(complianceService.forbiddenAttackBetween(95, 105));
		Assert.assertEquals(0, taint());
	}

	/**
	 * Two convictions inside ONE kill window: the taint is pinned to the oldest,
	 * but StyleTracker can only ever pardon the newest verdict. Lifting nothing
	 * is the correct conservative answer — the surviving conviction still earns
	 * the taint.
	 */
	@Test
	public void pardoningTheNewerOfTwoConvictionsInOneWindowLiftsNothing()
	{
		complianceService.onAttack(AttackStyle.MELEE, 100);
		complianceService.onAttack(AttackStyle.MELEE, 103);
		complianceService.addTaint(complianceService.convictingAttackTick(95, 105));
		Assert.assertEquals(1, taint());

		complianceService.onAttackPardoned(103);
		Assert.assertEquals(1, taint());
		Assert.assertTrue(taintRolledBack.isEmpty());
		Assert.assertEquals(100, complianceService.convictingAttackTick(95, 105));
	}

	/**
	 * The ledger is in-memory while taint is persisted, so a reload can leave a
	 * conviction scored against a counter that no longer holds its point. The
	 * rollback is clamped to what is actually standing, never to the ledger.
	 */
	@Test
	public void staleLedgerAgainstAReloadedCounterIsANoOp()
	{
		complianceService.onAttack(AttackStyle.MELEE, 100);
		complianceService.addTaint(100);
		stateService.mutate(s -> s.withTaint(0)); // counter reloaded out from under it

		complianceService.onAttackPardoned(100);
		Assert.assertEquals(0, taint());
		Assert.assertTrue(taintRolledBack.isEmpty());
	}

	@Test
	public void convictingAttackTickAgreesWithForbiddenAttackBetween()
	{
		complianceService.onAttack(AttackStyle.MELEE, 100);
		complianceService.onAttack(AttackStyle.MELEE, 107);
		int[][] windows = {{95, 105}, {100, 100}, {101, 106}, {107, 110}, {0, 99}, {108, 200}};
		for (int[] window : windows)
		{
			Assert.assertEquals("window " + window[0] + ".." + window[1],
				complianceService.forbiddenAttackBetween(window[0], window[1]),
				complianceService.convictingAttackTick(window[0], window[1]) >= 0);
		}
	}

	@Test
	public void resetTransientDropsConvictionsWithTheProfile()
	{
		complianceService.onAttack(AttackStyle.MELEE, 100);
		complianceService.resetTransient();
		Assert.assertEquals(-1, complianceService.convictingAttackTick(95, 105));
		Assert.assertEquals(-1, complianceService.getLastForbiddenAttackTick());
		Assert.assertEquals(-1, complianceService.getLastCompliantAttackTick());
	}
}

package com.gachaman.service;

import java.lang.reflect.*;
import java.util.*;
import org.junit.*;

/**
 * Why {@code MAX_WEAPON_SAMPLES} and {@code MAX_RECENT_VERDICTS} are
 * belt-and-braces rather than working code — and why they are kept anyway.
 *
 * <p>A compression pass proposed deleting the weapon-sample cap as dead code, on
 * the argument that at most one judgement lands per tick (the animation path
 * refuses a second, and the XP fallback waits out XP_FALLBACK_QUIET_TICKS), so
 * the 40-tick TTL already bounds the deque to 41 entries and the 41-entry cap can
 * never bite. That argument is CORRECT, and this test pins the half of it that a
 * headless harness can actually reach: the age-based prune alone holds the deque
 * at TTL + 1 when samples arrive one per tick.
 *
 * <p>It is pinned rather than acted on. The cap's own comment says it exists for
 * the day that one-judgement-per-tick invariant breaks, which makes it a designed
 * backstop and not vestigial code — and the invariant it guards lives in two
 * other methods that a future edit could change without ever looking at this one.
 * Removing it would buy 46 tokens and cost the only thing standing between a
 * broken invariant and an unbounded deque on the kill path.
 *
 * <p>The sibling {@code MAX_RECENT_VERDICTS} is unreachable by exactly the same
 * reasoning over the 5-tick pardon window, and stays for exactly the same reason;
 * the two comments cross-reference each other, so they live or die together.
 */
public class WeaponSampleBoundTest
{
	/** The deque, read straight off the tracker — nothing exposes its size. */
	@SuppressWarnings("unchecked")
	private static Deque<StyleTracker.WeaponSample> samples(StyleTracker tracker) throws Exception
	{
		Field field = StyleTracker.class.getDeclaredField("weaponSamples");
		field.setAccessible(true);
		return (Deque<StyleTracker.WeaponSample>) field.get(tracker);
	}

	private static int constant(String name) throws Exception
	{
		Field field = StyleTracker.class.getDeclaredField(name);
		field.setAccessible(true);
		return field.getInt(null);
	}

	/**
	 * One sample per tick for far longer than the TTL: the age prune alone never
	 * lets the deque past TTL + 1, so the hard cap is never the thing that
	 * discards an entry.
	 */
	@Test
	public void theAgePruneAloneBoundsTheDeque() throws Exception
	{
		StyleTracker tracker = new StyleTracker(null, null);
		int ttl = constant("WEAPON_SAMPLE_TTL_TICKS");
		int cap = constant("MAX_WEAPON_SAMPLES");
		Assert.assertEquals("the cap is sized as TTL + 1; if that changed, re-derive"
			+ " the unreachability argument before trusting it", ttl + 1, cap);

		int highWater = 0;
		for (int tick = 0; tick < ttl * 5; tick++)
		{
			tracker.recordWeapon(tick, 6, 0);
			highWater = Math.max(highWater, samples(tracker).size());
		}
		Assert.assertEquals("one judgement per tick can never reach the hard cap —"
			+ " the TTL prune gets there first", ttl + 1, highWater);
		Assert.assertTrue("so the cap never bites", highWater <= cap);
	}

	/**
	 * The clear on LOGGED_IN is NOT hygiene-only, which is the other thing the
	 * compression pass proposed removing.
	 *
	 * <p>The argument for removing it was that the tick counter never resets, so
	 * stale samples fall out of every future window anyway. That holds for a kill
	 * fought after the hop — but a kill whose engagement window sits BEFORE it is
	 * exactly the case the clear changes: with the samples cleared such a kill
	 * finds nothing and pays no weapon bonus, and without the clear it can still
	 * match a sample from a session that has ended. So the clear has observable
	 * behaviour, and this pins the direction it picks.
	 */
	@Test
	public void aClearedCacheStrandsAPreLogoutKillRatherThanPayingIt() throws Exception
	{
		StyleTracker tracker = new StyleTracker(null, null);
		tracker.recordWeapon(10, 6, 0);
		Assert.assertNotNull("precondition: the sample is claimable before the hop",
			tracker.weaponAt(7, 10));

		samples(tracker).clear(); // what onGameStateChanged(LOGGED_IN) does
		Assert.assertNull("a kill carried across the hop must pay no weapon bonus rather"
			+ " than claim a sample from the session that ended", tracker.weaponAt(7, 10));
	}
}

package com.gachaman.service;

import com.gachaman.*;
import org.junit.*;

/**
 * The jackpot upgrade in ChestService.roll() promotes a chest with
 * {@code Tuning.Chest.values()[tier.ordinal() + 1]} instead of an explicit
 * if/else chain, which makes the ENUM'S DECLARATION ORDER load-bearing: it is
 * the only thing that still says BATTERED promotes to GILDED and GILDED to
 * ORNATE. Reorder or insert a tier without reading roll() and the shop starts
 * handing out the wrong box — silently, because nothing else would fail.
 *
 * <p>These are deliberately enum-only assertions with no service, no RNG and no
 * card database, so a red result here means exactly one thing: the ladder moved.
 * (Tuning's own tables — CHEST_PRICE_GC, CHEST_CARDS, CHEST_ODDS — are built
 * positionally from Chest.values() too, so the coupling this pins was already
 * real before roll() leaned on it.)
 */
public class ChestJackpotLadderTest
{
	@Test
	public void theChestLadderIsRustyBatteredGildedOrnateInThatOrder()
	{
		Assert.assertArrayEquals(
			new Tuning.Chest[]{
				Tuning.Chest.RUSTY,
				Tuning.Chest.BATTERED,
				Tuning.Chest.GILDED,
				Tuning.Chest.ORNATE,
			},
			Tuning.Chest.values());
	}

	@Test
	public void oneStepUpFromBatteredIsGildedAndFromGildedIsOrnate()
	{
		// the two promotions roll() actually performs, written the way roll()
		// writes them
		Assert.assertEquals(Tuning.Chest.GILDED,
			Tuning.Chest.values()[Tuning.Chest.BATTERED.ordinal() + 1]);
		Assert.assertEquals(Tuning.Chest.ORNATE,
			Tuning.Chest.values()[Tuning.Chest.GILDED.ordinal() + 1]);
	}

	@Test
	public void ornateIsTheTopOfTheLadderSoPromotingItWouldRunOffTheEnd()
	{
		// why roll() excludes ORNATE from the promotion rather than relying on the
		// array bound: its jackpot pays a fourth card instead of a better box, and
		// an unguarded ordinal + 1 here would be an AIOOBE on every ornate jackpot
		Assert.assertEquals(Tuning.Chest.values().length - 1, Tuning.Chest.ORNATE.ordinal());
	}

	@Test
	public void rustyIsBelowEveryOtherTierSoItCanNeverBeAPromotionTarget()
	{
		// roll() gates the jackpot on !rusty; this pins the other half of that
		// reasoning — nothing sits below RUSTY that could promote INTO it
		Assert.assertEquals(0, Tuning.Chest.RUSTY.ordinal());
	}
}

package com.gachaman.service;

import com.gachaman.tools.*;
import com.google.gson.*;
import com.google.gson.reflect.*;
import java.io.*;
import java.nio.charset.*;
import java.util.*;
import org.junit.*;

/**
 * The shipped attack-anims.json must still be exactly what {@link AttackAnims}
 * declares.
 *
 * <p>This is the seam that makes moving the ids into a resource safe. In code
 * they were {@code AnimationID} constants and the compiler caught a rename; as
 * raw numbers in JSON nothing would. So the names stay in AttackAnims, where
 * they are still compiled against the live API, and this test pins the resource
 * to them.
 *
 * <p>What it prevents: a RuneLite rename silently dropping a teleport from
 * neverJudge, so teleporting mid-fight scores as a melee attack against a magic
 * contract and taints the kill. That failure is invisible until a player loses
 * a reward to it.
 *
 * <p>If this fails, run {@code ./gradlew attackAnims} and commit the result.
 */
public class AttackAnimResourceTest
{
	private static Map<String, Set<Integer>> shipped() throws Exception
	{
		try (InputStream in = AttackAnimResourceTest.class.getResourceAsStream(
			"/com/gachaman/data/attack-anims.json"))
		{
			Assert.assertNotNull("attack-anims.json is not on the classpath", in);
			return new Gson().fromJson(new InputStreamReader(in, StandardCharsets.UTF_8),
				new TypeToken<Map<String, Set<Integer>>>()
				{
				}.getType());
		}
	}

	@Test
	public void theResourceMatchesTheCompiledAnimationIds() throws Exception
	{
		Map<String, Set<Integer>> shipped = shipped();
		Map<String, Set<Integer>> declared = AttackAnims.groups();
		Assert.assertEquals("group names drifted", declared.keySet(), shipped.keySet());
		for (Map.Entry<String, Set<Integer>> entry : declared.entrySet())
		{
			Assert.assertEquals("stale attack-anims.json — run ./gradlew attackAnims ("
				+ entry.getKey() + ")", entry.getValue(), shipped.get(entry.getKey()));
		}
	}

	@Test
	public void everyMagicUtilityAnimationIsAlsoUnjudgeable() throws Exception
	{
		// a spell that pays Magic XP but is still judged as an attack would let an
		// alch mid-fight score against a melee contract
		Map<String, Set<Integer>> shipped = shipped();
		Assert.assertTrue("magicUtility must be a subset of neverJudge",
			shipped.get("neverJudge").containsAll(shipped.get("magicUtility")));
	}

	@Test
	public void noAnimationIsBothAnAttackAndNotAnAttack() throws Exception
	{
		Map<String, Set<Integer>> shipped = shipped();
		for (Integer id : shipped.get("offensiveMagic"))
		{
			Assert.assertFalse("animation " + id + " is classified both ways",
				shipped.get("neverJudge").contains(id));
		}
	}

	@Test
	public void noGroupIsEmpty() throws Exception
	{
		// the whole point of the fallback is that a missing resource degrades
		// rather than crashes — but an EMPTY shipped group is a silent regression
		for (Map.Entry<String, Set<Integer>> entry : shipped().entrySet())
		{
			Assert.assertFalse(entry.getKey() + " is empty", entry.getValue().isEmpty());
		}
	}
}

package com.gachaman.service;

import com.gachaman.*;
import java.io.*;
import java.nio.charset.*;
import java.nio.file.*;
import java.util.*;
import java.util.function.*;
import java.util.stream.*;
import org.junit.*;

/**
 * The three invariants sixteen hand-written fan-out loops used to each carry
 * their own copy of, now pinned in one place.
 *
 * <p>They matter because of WHERE a fan-out sits: by the time one runs, the
 * state write and the GC award have already happened. A listener that throws
 * must not be able to swallow the notifications queued behind it, and a
 * listener that registers or drops another one mid-callback (the panel does
 * exactly this when a tab is rebuilt) must not blow up the caller.
 */
public class ListenersTest
{
	@Test
	public void oneThrowingListenerDoesNotStopTheOthers()
	{
		List<String> seen = new ArrayList<>();
		List<Consumer<String>> listeners = new ArrayList<>();
		listeners.add(seen::add);
		listeners.add(name ->
		{
			seen.add("boom");
			throw new IllegalStateException("deliberate");
		});
		listeners.add(seen::add);

		Listeners.fire(listeners, l -> l.accept("event"), "test listener failed");

		Assert.assertEquals(Arrays.asList("event", "boom", "event"), seen);
	}

	/**
	 * A listener that throws on EVERY call still leaves the loop running to the
	 * end — the catch is per listener, not once around the whole fan-out.
	 */
	@Test
	public void everyListenerThrowingStillVisitsThemAll()
	{
		int[] visits = {0};
		List<Runnable> listeners = new ArrayList<>();
		for (int i = 0; i < 4; i++)
		{
			listeners.add(() ->
			{
				visits[0]++;
				throw new RuntimeException("deliberate");
			});
		}

		Listeners.fire(listeners, Runnable::run, "test listener failed");

		Assert.assertEquals(4, visits[0]);
	}

	/**
	 * The defensive copy: registering and unregistering from inside a callback
	 * is legal and must not throw ConcurrentModificationException. The snapshot
	 * is taken up front, so the listener added during the fan-out is NOT called
	 * by it (it will be by the next one) and the one removed still is.
	 */
	@Test
	public void aListenerMayAddAndRemoveListenersFromInsideItsOwnCallback()
	{
		List<String> seen = new ArrayList<>();
		List<Runnable> listeners = new ArrayList<>();
		Runnable late = () -> seen.add("late");
		Runnable doomed = () -> seen.add("doomed");
		listeners.add(() ->
		{
			seen.add("first");
			listeners.add(late);
			listeners.remove(doomed);
		});
		listeners.add(doomed);

		Listeners.fire(listeners, Runnable::run, "test listener failed");

		Assert.assertEquals(Arrays.asList("first", "doomed"), seen);
		Assert.assertEquals(Arrays.asList(listeners.get(0), late), listeners);
	}

	/** Listeners are visited in registration order, like every loop this replaced. */
	@Test
	public void listenersAreVisitedInOrder()
	{
		List<Integer> seen = new ArrayList<>();
		List<Integer> listeners = Arrays.asList(1, 2, 3, 4, 5);

		Listeners.fire(listeners, seen::add, "test listener failed");

		Assert.assertEquals(listeners, seen);
	}

	/**
	 * Exception is caught; Error is not. A StackOverflowError or an OOM means
	 * the client is already in trouble and must not be quietly logged as "a
	 * listener failed" while the fan-out carries on.
	 */
	@Test
	public void errorsPropagateInsteadOfBeingLogged()
	{
		List<Runnable> listeners = new ArrayList<>();
		listeners.add(() ->
		{
			throw new StackOverflowError("deliberate");
		});
		listeners.add(() -> Assert.fail("fan-out continued past an Error"));

		try
		{
			Listeners.fire(listeners, Runnable::run, "test listener failed");
			Assert.fail("Error should have escaped the fan-out");
		}
		catch (StackOverflowError expected)
		{
			Assert.assertEquals("deliberate", expected.getMessage());
		}
	}

	/** An empty collection is a no-op, not an NPE. */
	@Test
	public void emptyCollectionIsANoOp()
	{
		Listeners.fire(Collections.<Runnable>emptyList(),
			l -> Assert.fail("nothing to notify"), "test listener failed");
	}

	private static final String CALL = "Listeners.fire(";

	/**
	 * A failure mode the shared helper introduced that the sixteen hand-written
	 * loops could not have: the label IS the SLF4J message pattern, and the
	 * exception binds to {@code warn(String, Throwable)} rather than filling a
	 * placeholder. A label written as {@code "x failed for {}"} would therefore
	 * print a literal {@code {}} in the client log with nothing substituted.
	 *
	 * <p>Scans the real main-source tree rather than testing a behaviour, because
	 * the mistake is one a future call site makes, not one this class can catch.
	 */
	@Test
	public void noFanOutLabelCarriesAnSlf4jPlaceholder() throws IOException
	{
		Path root = SourceHygieneTest.sourceRoot();
		Assert.assertNotNull("could not locate src/main/java from "
			+ Paths.get("").toAbsolutePath(), root);

		List<String> offenders = new ArrayList<>();
		int checked = 0;
		try (Stream<Path> tree = Files.walk(root))
		{
			for (Path file : tree.filter(p -> p.toString().endsWith(".java"))
				.collect(Collectors.toList()))
			{
				String src = new String(Files.readAllBytes(file), StandardCharsets.UTF_8);
				for (int at = src.indexOf(CALL); at >= 0; at = src.indexOf(CALL, at + 1))
				{
					String args = balanced(src, at + CALL.length() - 1);
					String label = args == null ? null : lastArgument(args);
					// a label built at runtime cannot be read here; only literals
					// are checkable, and every site today passes one
					if (label == null || !label.startsWith("\"") || !label.endsWith("\""))
					{
						continue;
					}
					checked++;
					if (label.contains("{}"))
					{
						offenders.add(root.relativize(file) + ": " + label);
					}
				}
			}
		}

		// a scan that matched nothing would pass forever, exactly as it would in
		// SourceHygieneTest — the call sites are what this test is about
		Assert.assertTrue("found no " + CALL + " call sites under " + root, checked > 0);
		Assert.assertEquals("SLF4J placeholder in a listener fan-out label — the label is"
			+ " the message pattern and nothing fills it, so {} would be printed literally",
			Collections.emptyList(), offenders);
	}

	/** Text between {@code src[openParen]} and its matching close, or null. */
	private static String balanced(String src, int openParen)
	{
		int depth = 0;
		for (int i = openParen; i < src.length(); i++)
		{
			char c = src.charAt(i);
			if (c == '"' || c == '\'')
			{
				i = endOfLiteral(src, i);
			}
			else if (c == '(')
			{
				depth++;
			}
			else if (c == ')' && --depth == 0)
			{
				return src.substring(openParen + 1, i);
			}
		}
		return null;
	}

	/** Index of the closing quote of the literal starting at {@code start}. */
	private static int endOfLiteral(String src, int start)
	{
		char quote = src.charAt(start);
		for (int i = start + 1; i < src.length(); i++)
		{
			if (src.charAt(i) == '\\')
			{
				i++;
			}
			else if (src.charAt(i) == quote)
			{
				return i;
			}
		}
		return src.length() - 1;
	}

	/**
	 * The last argument of an argument list — split on the last TOP-LEVEL comma,
	 * so the commas inside the action lambda's own call do not count.
	 */
	private static String lastArgument(String args)
	{
		int depth = 0;
		int lastComma = -1;
		for (int i = 0; i < args.length(); i++)
		{
			char c = args.charAt(i);
			if (c == '"' || c == '\'')
			{
				i = endOfLiteral(args, i);
			}
			else if (c == '(' || c == '[' || c == '{')
			{
				depth++;
			}
			else if (c == ')' || c == ']' || c == '}')
			{
				depth--;
			}
			else if (c == ',' && depth == 0)
			{
				lastComma = i;
			}
		}
		return lastComma < 0 ? null : args.substring(lastComma + 1).trim();
	}
}

package com.gachaman.service;

import com.gachaman.*;
import com.gachaman.model.*;
import org.junit.*;

/**
 * Tick behaviour of the Rhythm Combo. The pure ladder maths lives in
 * {@link EarlyGameMathTest}; what is pinned here is when a kill banks and when
 * the chain dies, because that is where the chain used to freeze: growth was
 * gated on a 25s window measured from the previous KILL, so anything slower
 * than that sat on one stack forever while the meter still showed an active
 * chain. Only idling breaks a chain now.
 *
 * <p>The combo path touches no collaborator, so nulls are enough to build one.
 */
public class ComboChainTest
{
	private static final int IDLE = Tuning.COMBO_IDLE_RESET_TICKS;
	private static final int PER_STACK = Tuning.COMBO_KILLS_PER_STACK;

	private TaskService service()
	{
		// every collaborator unwired: the combo rules under test are pure
		// bookkeeping over ticks and touch none of them
		return new TaskService(null, null, null, null, null, null, null, null, null, null,
			null, null, null);
	}

	/** Fight from `from` until `until`, landing an attack every other tick. */
	private void fight(TaskService s, int from, int until)
	{
		for (int t = from; t < until; t += 2)
		{
			s.onAttack(AttackStyle.MELEE, t);
		}
	}

	/** Land `kills` kills `gapTicks` apart, attacking throughout; returns the last tick. */
	private int grind(TaskService s, int kills, int gapTicks, int startTick)
	{
		int tick = startTick;
		for (int i = 0; i < kills; i++)
		{
			fight(s, tick + 1, tick + gapTicks);
			tick += gapTicks;
			s.advanceCombo(tick);
		}
		return tick;
	}

	@Test
	public void aStackCostsFiveKills()
	{
		TaskService s = service();
		int tick = 0;
		// four kills buy nothing at all
		for (int kill = 1; kill < PER_STACK; kill++)
		{
			tick += 10;
			Assert.assertEquals("kill " + kill, 0, s.advanceCombo(tick));
		}
		// the fifth lands the first stack; the four after it do not add another
		for (int kill = PER_STACK; kill < 2 * PER_STACK; kill++)
		{
			tick += 10;
			Assert.assertEquals("kill " + kill, 1, s.advanceCombo(tick));
		}
		// the tenth lands the second
		tick += 10;
		Assert.assertEquals(2, s.advanceCombo(tick));
	}

	@Test
	public void aKillSlowerThanTheOldWindowStillBanks()
	{
		TaskService s = service();
		// 45 ticks (27s) per kill — past the retired 42-tick growth window, so
		// this is exactly the case that used to be stuck forever
		int last = grind(s, PER_STACK, 45, 0);
		Assert.assertEquals(1, s.comboStacksAt(last));
	}

	@Test
	public void aTankyTargetReachesAFullChain()
	{
		TaskService s = service();
		// 90 ticks/kill — nearly a minute each, and still a full chain
		int last = grind(s, Tuning.COMBO_MAX_KILLS, 90, 0);
		Assert.assertEquals(Tuning.COMBO_MAX_STACKS, s.comboStacksAt(last));
		// and it holds there rather than banking credit it cannot spend
		last = grind(s, 20, 90, last);
		Assert.assertEquals(Tuning.COMBO_MAX_STACKS, s.comboStacksAt(last));
		Assert.assertEquals(0, s.comboProgressAt(last), 1e-9);
	}

	@Test
	public void idlingPastTheCutoffStartsTheChainOver()
	{
		TaskService s = service();
		int last = grind(s, 2 * PER_STACK, 10, 0);
		Assert.assertEquals(2, s.comboStacksAt(last));
		// no attacks at all across the cutoff
		Assert.assertEquals(0, s.advanceCombo(last + IDLE + 1));
	}

	@Test
	public void oneTickInsideTheCutoffKeepsTheChain()
	{
		TaskService s = service();
		grind(s, PER_STACK, 1, 0);
		// the next kill lands exactly on the cutoff, so the chain survives and
		// the banked kills carry — a sixth kill, not a new chain's first
		Assert.assertEquals(1, s.advanceCombo(PER_STACK + IDLE));
	}

	@Test
	public void attacksAfterTheCutoffCannotReviveADeadChain()
	{
		TaskService s = service();
		int last = grind(s, PER_STACK, 5, 0);
		Assert.assertEquals(1, s.comboStacksAt(last));
		// the chain is already dead by the time these land, so they must not
		// re-anchor it — the next kill starts a new chain rather than resuming
		fight(s, last + IDLE + 1, last + IDLE + 40);
		Assert.assertEquals(0, s.advanceCombo(last + IDLE + 41));
	}

	@Test
	public void anIdleChainReadsAsZeroBeforeTheNextKill()
	{
		TaskService s = service();
		int last = grind(s, PER_STACK, 1, 0);
		Assert.assertEquals(1, s.comboStacksAt(last + IDLE));
		Assert.assertEquals(0, s.comboStacksAt(last + IDLE + 1));
		Assert.assertEquals(0, s.comboProgressAt(last + IDLE + 1), 1e-9);
		// and the countdown drains to nothing rather than going negative
		Assert.assertEquals(0, s.comboIdleTicksRemaining(last + IDLE + 99));
	}

	@Test
	public void attackingHoldsTheCountdownOpen()
	{
		TaskService s = service();
		s.advanceCombo(0);
		fight(s, 1, IDLE);
		// last attack landed just under the cutoff, so the chain is still live
		// well past the point an unattended one would have expired
		Assert.assertEquals(0, s.comboStacksAt(IDLE + 10));
		Assert.assertTrue(s.comboIdleTicksRemaining(IDLE + 10) > 0);
	}

	@Test
	public void progressTracksTheClimbToTheNextStack()
	{
		TaskService s = service();
		Assert.assertEquals(0, s.comboProgressAt(0), 1e-9);
		int tick = 0;
		for (int banked = 1; banked < PER_STACK; banked++)
		{
			tick = banked * 10;
			s.advanceCombo(tick);
			Assert.assertEquals(banked / (double) PER_STACK, s.comboProgressAt(tick), 1e-9);
		}
		// the stack lands and the climb restarts from nothing
		tick = PER_STACK * 10;
		Assert.assertEquals(1, s.advanceCombo(tick));
		Assert.assertEquals(0, s.comboProgressAt(tick), 1e-9);
	}

	@Test
	public void noChainReadsZeroThroughout()
	{
		TaskService s = service();
		Assert.assertEquals(0, s.comboStacksAt(0));
		Assert.assertEquals(0, s.comboIdleTicksRemaining(0));
		Assert.assertEquals(0, s.comboProgressAt(0), 1e-9);
	}
}

package com.gachaman.service;

import com.gachaman.model.*;
import com.gachaman.persist.*;
import java.util.*;
import org.junit.*;

/**
 * Double Docket: what a contract actually PAYS when its target is also the
 * player's live Slayer assignment, and how that composes with the rest of the
 * completion multiplier chain.
 *
 * Headless, real in-memory state. The Slayer read is a hook rather than an
 * injected ConfigManager precisely so it can be driven from here; the null
 * client is never touched because every contract uses perKillGc 0 (the award
 * branch is the only client read in onKill). The exact GC figures assume the
 * harness registers NO CreditSink modifiers and carries no taint unless a test
 * seeds some — both asserted in setUp.
 */
public class TaskServiceDoubleDocketTest
{
	private GachaStateService stateService;
	private TaskService taskService;
	private final List<TaskService.TaskCompletionSummary> completions = new ArrayList<>();
	/** What the Slayer layer would report; mutable so a test can end the task. */
	private String slayerTarget;
	private int latchAnnouncements;

	private static GachaStateService inMemoryStateService()
	{
		StateStore store = new StateStore(null, null, null)
		{
			@Override
			public void save(GachaState state)
			{
			}

			@Override
			public void save(GachaState state, boolean flushDiskNow)
			{
			}

			@Override
			public GachaState load()
			{
				return null; // forces a fresh in-memory state
			}
		};
		GachaStateService service = new GachaStateService(store);
		service.load(3);
		return service;
	}

	@Before
	public void setUp()
	{
		stateService = inMemoryStateService();
		CreditSink creditSink = new CreditSink(stateService);
		ComplianceService complianceService = new ComplianceService(stateService, creditSink, null, null);
		CeremonyBus ceremonyBus = new CeremonyBus();
		StyleService styleService = StyleFixture.styleService(stateService, complianceService, ceremonyBus,
			new GachaRng(1L));
		com.gachaman.data.MonsterTable monsterTable =
			com.gachaman.data.MonsterTable.load(new com.google.gson.Gson());
		taskService = new TaskService(null, stateService, creditSink, complianceService,
			styleService, ceremonyBus, new GachaRng(1L), monsterTable,
			// null Client already means these tests never reach rollOffers()
			null, null,
			// The three collaborators added with the Preferred Weapon and the
			// Consignment are unwired here: no contract in this file pays per kill,
			// so the award branch (the only reader of the weapon pair) is never
			// reached, and no completion here tips the style cycle.
			null, null, null);
		taskService.addListener(new TaskService.Listener()
		{
			@Override
			public void onKillFeedback(TaskService.KillFeedback feedback)
			{
			}

			@Override
			public void onSideBetHit(SideBet bet, String monsterName)
			{
			}

			@Override
			public void onTaskCompleted(TaskService.TaskCompletionSummary summary)
			{
				completions.add(summary);
			}

			@Override
			public void onOffersRolled(List<TaskOffer> offers)
			{
			}

			@Override
			public void onPartyProgress(ActiveTask task)
			{
			}
		});
		// the exact payout figures below only hold with an unmodified sink
		Assert.assertEquals("harness must carry no taint", 0, stateService.get().getTaint());
	}

	/** Wire the Slayer layer in, reading whatever {@link #slayerTarget} holds now. */
	private void wireSlayer(String target)
	{
		slayerTarget = target;
		taskService.setSlayerTargetHook(() -> slayerTarget);
		taskService.setSlayerLatchHook(() -> latchAnnouncements++);
	}

	private KillTracker.Kill goblinKill(int tick)
	{
		return new KillTracker.Kill("Goblin", 2, 1, tick, tick - 3, false, 3, false, null);
	}

	private void seedContract(String partyLabel, List<AttackStyle> styles, boolean convertedToSolo,
		boolean slayerAligned, int killsRequired)
	{
		stateService.mutate(s -> s.withActiveTask(ActiveTask.builder()
			.difficulty(TaskDifficulty.EASY)
			.monsterName("Goblin")
			.killsRequired(killsRequired)
			.killsDone(0)
			.perKillGc(0) // keeps the null client out of onKill
			.completionGc(1000)
			.acceptedAtMs(1L)
			.partyLabel(partyLabel)
			.partyStyles(styles)
			.partyConvertedToSolo(convertedToSolo)
			.slayerAligned(slayerAligned)
			.build()));
	}

	/** One kill away from done, so a single onKill reaches completeTask(). */
	private void seedSolo(boolean slayerAligned)
	{
		seedContract(null, null, false, slayerAligned, 1);
	}

	private long completionAward()
	{
		taskService.onKill(goblinKill(10));
		Assert.assertEquals("exactly one completion must fire", 1, completions.size());
		return completions.get(0).getCompletionGcAwarded();
	}

	// --- A. no Slayer layer at all ---

	@Test
	public void unwiredHookPaysBase()
	{
		// every other test suite in this project leaves the hook null; none of
		// them may start paying a bonus because this feature exists
		seedSolo(false);
		Assert.assertEquals(1000, completionAward());
	}

	@Test
	public void throwingHookPaysBaseAndDoesNotEscape()
	{
		// a broken Slayer read must cost the player a bonus, never a completion
		taskService.setSlayerTargetHook(() ->
		{
			throw new IllegalStateException("no rs profile");
		});
		seedSolo(false);
		Assert.assertEquals(1000, completionAward());
	}

	// --- B. what it pays ---

	@Test
	public void alignedSoloContractPaysTwentyPercentMore()
	{
		wireSlayer("Goblins");
		seedSolo(false);
		Assert.assertEquals(1200, completionAward());
		Assert.assertEquals("the player is told once, on the kill that latches",
			1, latchAnnouncements);
	}

	@Test
	public void unalignedContractNeverLatches()
	{
		wireSlayer("Fire giants");
		seedContract(null, null, false, false, 2); // 2 kills: survives to be inspected
		taskService.onKill(goblinKill(10));
		Assert.assertFalse("a different assignment must not latch",
			stateService.get().getActiveTask().isSlayerAligned());
		Assert.assertEquals(0, latchAnnouncements);
		taskService.onKill(goblinKill(20));
		Assert.assertEquals(1000, completions.get(0).getCompletionGcAwarded());
	}

	// --- C. the latch ---

	@Test
	public void latchTurnsOnMidContract()
	{
		// signed with no assignment, then the player goes and gets the matching
		// one: the bonus applies, because the roll is never biased toward Slayer
		// and this is the only way alignment can be sought out deliberately
		wireSlayer(null);
		seedContract(null, null, false, false, 2);
		taskService.onKill(goblinKill(10));
		Assert.assertFalse(stateService.get().getActiveTask().isSlayerAligned());
		slayerTarget = "Goblins";
		Assert.assertEquals(1200, completionAward());
		Assert.assertEquals(1, latchAnnouncements);
	}

	@Test
	public void latchStaysOnAfterTheSlayerTaskEnds()
	{
		// finishing the Slayer assignment mid-contract must not retract a bonus
		// the sidebar has already promised
		wireSlayer("Goblins");
		seedContract(null, null, false, false, 2);
		taskService.onKill(goblinKill(10));
		Assert.assertTrue(stateService.get().getActiveTask().isSlayerAligned());
		slayerTarget = null; // assignment handed in
		Assert.assertEquals(1200, completionAward());
		Assert.assertEquals("no second announcement once latched", 1, latchAnnouncements);
	}

	@Test
	public void legacyInFlightContractDefaultsToNoBonus()
	{
		// a contract signed before this field existed deserializes slayerAligned
		// false; with no matching assignment it simply pays base
		wireSlayer("Fire giants");
		seedSolo(false);
		Assert.assertEquals(1000, completionAward());
	}

	@Test
	public void acceptingAnOfferLatchesImmediately()
	{
		// the accept-time check, so the sidebar can promise the bonus from the
		// first kill rather than only after one has landed
		wireSlayer("Goblins");
		stateService.mutate(s -> s.withPendingOffers(Collections.singletonList(
			new TaskOffer(TaskDifficulty.EASY, "Goblin", 2, 1, 0, 1000, null, false, false))));
		Assert.assertTrue(taskService.acceptOffer(0));
		Assert.assertTrue(stateService.get().getActiveTask().isSlayerAligned());
		Assert.assertEquals("accepting is not a kill, so nothing is announced yet",
			0, latchAnnouncements);
		Assert.assertEquals(1200, completionAward());
	}

	// --- D. composition with the rest of the chain ---

	@Test
	public void partyAndDocketComposeMultiplicatively()
	{
		// 1.6 co-op + 0.25 flat clash = 1.85, then x1.2
		wireSlayer("Goblins");
		seedContract("Party of 2", Arrays.asList(AttackStyle.MELEE, AttackStyle.MAGIC), false, false, 1);
		Assert.assertEquals(2220, completionAward());
	}

	@Test
	public void monoStylePartyAndDocketCompose()
	{
		wireSlayer("Goblins");
		seedContract("Party of 2", Arrays.asList(AttackStyle.MELEE, AttackStyle.MELEE), false, false, 1);
		Assert.assertEquals(1920, completionAward());
	}

	@Test
	public void carryClauseAndDocketCompose()
	{
		// the carry clause replaces the party bonus but not the docket
		wireSlayer("Goblins");
		seedContract("Party of 2", Arrays.asList(AttackStyle.MELEE, AttackStyle.MAGIC), true, false, 1);
		Assert.assertEquals(960, completionAward());
	}

	@Test
	public void taintStillHalvesADocketedAward()
	{
		// the docket is a completion MULTIPLIER, so it is priced before the sink
		// halves a tainted player's income: 1000 x1.2 = 1200, halved = 600. A
		// docket must never be a way to shrug off a debt.
		wireSlayer("Goblins");
		stateService.mutate(s -> s.withTaint(5));
		seedSolo(false);
		Assert.assertEquals(600, completionAward());
		Assert.assertTrue("the kill works one taint off, so the debt must still stand",
			stateService.get().getTaint() > 0);
	}
}

package com.gachaman.service;

import com.gachaman.model.*;
import java.util.*;
import org.junit.*;

public class StyleTrackerTest
{
	@Test
	public void styleNamesMapCorrectly()
	{
		Assert.assertEquals(AttackStyle.MELEE, StyleTracker.mapStyleName("Accurate"));
		Assert.assertEquals(AttackStyle.MELEE, StyleTracker.mapStyleName("Aggressive"));
		Assert.assertEquals(AttackStyle.MELEE, StyleTracker.mapStyleName("Defensive"));
		Assert.assertEquals(AttackStyle.MELEE, StyleTracker.mapStyleName("Controlled"));
		Assert.assertEquals(AttackStyle.RANGED, StyleTracker.mapStyleName("Ranging"));
		Assert.assertEquals(AttackStyle.RANGED, StyleTracker.mapStyleName("Longrange"));
		Assert.assertEquals(AttackStyle.MAGIC, StyleTracker.mapStyleName("Casting"));
		Assert.assertEquals(AttackStyle.MAGIC, StyleTracker.mapStyleName("Defensive Casting"));
		Assert.assertNull(StyleTracker.mapStyleName("Unknown"));
	}

	@Test
	public void autocastModeIsAlwaysMagic()
	{
		// com mode 4 = autocast slot regardless of weapon category
		Assert.assertEquals(AttackStyle.MAGIC,
			StyleTracker.resolve(1, 4, false, (c, s) -> "Accurate"));
		Assert.assertEquals(AttackStyle.MAGIC,
			StyleTracker.resolve(24, 4, true, (c, s) -> null));
	}

	@Test
	public void specialCasedCategoriesFallBackToMelee()
	{
		Assert.assertEquals(AttackStyle.MELEE,
			StyleTracker.resolve(22, 0, false, (c, s) -> null));
		Assert.assertEquals(AttackStyle.MELEE,
			StyleTracker.resolve(30, 1, false, (c, s) -> null));
	}

	@Test
	public void unresolvableIsNullNeverGuessed()
	{
		Assert.assertNull(StyleTracker.resolve(5, 1, false, (c, s) -> null));
		Assert.assertNull(StyleTracker.resolve(5, 1, false, (c, s) -> "Garbage"));
	}

	@Test
	public void normalResolutionUsesLookup()
	{
		Assert.assertEquals(AttackStyle.RANGED,
			StyleTracker.resolve(3, 1, false, (c, s) -> "Ranging"));
		Assert.assertEquals(AttackStyle.MAGIC,
			StyleTracker.resolve(18, 3, false, (c, s) -> "Defensive Casting"));
	}

	@Test
	public void poweredStavesResolveMagicInEveryComMode()
	{
		// powered staves (trident, sanguinesti...) fight from comMode 0/1/3,
		// never the autocast slot; style 0 of such a category is "Casting".
		// Without the style-0 probe, comMode 3 here would resolve MELEE.
		StyleTracker.StyleNameLookup poweredStave = (c, s) -> s == 0 ? "Casting" : "Defensive";
		Assert.assertEquals(AttackStyle.MAGIC, StyleTracker.resolve(24, 0, false, poweredStave));
		Assert.assertEquals(AttackStyle.MAGIC, StyleTracker.resolve(24, 1, false, poweredStave));
		Assert.assertEquals(AttackStyle.MAGIC, StyleTracker.resolve(24, 3, false, poweredStave));
		// a melee weapon's style 0 is not "Casting" — probe must not touch it
		Assert.assertEquals(AttackStyle.MELEE,
			StyleTracker.resolve(6, 1, false, (c, s) -> "Aggressive"));
	}

	@Test
	public void onlyUnconfirmedStanceVerdictsArePardonable()
	{
		// the happy path: stance said melee, magic xp landed 3 ticks later,
		// nothing confirmed the melee verdict
		Assert.assertTrue(StyleTracker.shouldPardon(StyleTracker.JudgementSource.STANCE,
			AttackStyle.MELEE, false, 100, 103, -1, -100));
		Assert.assertTrue(StyleTracker.shouldPardon(StyleTracker.JudgementSource.STANCE,
			AttackStyle.RANGED, false, 100, 103, -1, -100));
		// MARK/ANIM verdicts are already magic; XP verdicts are ground truth
		Assert.assertFalse(StyleTracker.shouldPardon(StyleTracker.JudgementSource.MARK,
			AttackStyle.MELEE, false, 100, 103, -1, -100));
		Assert.assertFalse(StyleTracker.shouldPardon(StyleTracker.JudgementSource.ANIM,
			AttackStyle.MELEE, false, 100, 103, -1, -100));
		Assert.assertFalse(StyleTracker.shouldPardon(StyleTracker.JudgementSource.XP,
			AttackStyle.MELEE, false, 100, 103, -1, -100));
		// a magic verdict needs no pardon
		Assert.assertFalse(StyleTracker.shouldPardon(StyleTracker.JudgementSource.STANCE,
			AttackStyle.MAGIC, false, 100, 103, -1, -100));
	}

	@Test
	public void pardonBlockedByWindowConfirmationAndUtilityCasts()
	{
		// outside the pardon window
		Assert.assertFalse(StyleTracker.shouldPardon(StyleTracker.JudgementSource.STANCE,
			AttackStyle.MELEE, false, 100, 106, -1, -100));
		// already pardoned once
		Assert.assertFalse(StyleTracker.shouldPardon(StyleTracker.JudgementSource.STANCE,
			AttackStyle.MELEE, true, 100, 103, -1, -100));
		// same-tick melee xp confirms a genuine melee hit (auto-retaliate
		// staff bash that landed) — never pardoned
		Assert.assertFalse(StyleTracker.shouldPardon(StyleTracker.JudgementSource.STANCE,
			AttackStyle.MELEE, false, 100, 103, 100, -100));
		// magic xp right after an alch/teleport proves nothing about combat
		Assert.assertFalse(StyleTracker.shouldPardon(StyleTracker.JudgementSource.STANCE,
			AttackStyle.MELEE, false, 100, 103, -1, 103));
		Assert.assertFalse(StyleTracker.shouldPardon(StyleTracker.JudgementSource.STANCE,
			AttackStyle.MELEE, false, 100, 103, -1, 102));
		// melee xp from BEFORE the verdict does not confirm it
		Assert.assertTrue(StyleTracker.shouldPardon(StyleTracker.JudgementSource.STANCE,
			AttackStyle.MELEE, false, 100, 103, 99, -100));
	}

	// --- pardoning ACROSS verdicts, not just the newest one ---

	private static StyleTracker.Verdict verdict(int tick, AttackStyle style,
		StyleTracker.JudgementSource source)
	{
		return new StyleTracker.Verdict(tick, style, source);
	}

	@Test
	public void aLaterCastNoLongerShieldsTheStaleMeleeVerdict()
	{
		// The reported symptom, exactly: swap to a staff, cast twice. The first
		// cast is judged MELEE because COMBAT_WEAPON_CATEGORY still describes the
		// weapon just put away; the second animates a spell and is judged MAGIC.
		// The first cast's Magic XP lands at tick 104 — and when only the NEWEST
		// verdict could be pardoned it found the ANIM MAGIC one, declined, and
		// left the melee verdict standing to taint the kill.
		StyleTracker.Verdict stale = verdict(100, AttackStyle.MELEE,
			StyleTracker.JudgementSource.STANCE);
		List<StyleTracker.Verdict> recent = Arrays.asList(stale,
			verdict(102, AttackStyle.MAGIC, StyleTracker.JudgementSource.ANIM));
		Assert.assertSame(stale, StyleTracker.pardonTarget(recent, 104, -1, -100));
	}

	@Test
	public void theOldestPardonableVerdictGoesFirst()
	{
		// magic xp is the DELAYED signal, so the earliest candidate is the cast
		// that produced it; two drops then clear two verdicts in order
		StyleTracker.Verdict first = verdict(100, AttackStyle.MELEE,
			StyleTracker.JudgementSource.STANCE);
		StyleTracker.Verdict second = verdict(102, AttackStyle.MELEE,
			StyleTracker.JudgementSource.STANCE);
		List<StyleTracker.Verdict> recent = Arrays.asList(first, second);
		Assert.assertSame(first, StyleTracker.pardonTarget(recent, 104, -1, -100));
		first.pardoned = true;
		Assert.assertSame(second, StyleTracker.pardonTarget(recent, 104, -1, -100));
		second.pardoned = true;
		// and one XP drop is never worth a third pardon
		Assert.assertNull(StyleTracker.pardonTarget(recent, 104, -1, -100));
	}

	@Test
	public void scanningManyVerdictsNeverRelaxesTheRules()
	{
		// every entry here is unpardonable for a DIFFERENT reason, and having
		// several to choose from must not let any of them through
		List<StyleTracker.Verdict> recent = Arrays.asList(
			verdict(90, AttackStyle.MELEE, StyleTracker.JudgementSource.STANCE),  // stale
			verdict(101, AttackStyle.MAGIC, StyleTracker.JudgementSource.STANCE), // already magic
			verdict(102, AttackStyle.MELEE, StyleTracker.JudgementSource.MARK),   // not stance
			verdict(103, AttackStyle.RANGED, StyleTracker.JudgementSource.XP));   // ground truth
		Assert.assertNull(StyleTracker.pardonTarget(recent, 104, -1, -100));
		// an empty history is not a special case
		Assert.assertNull(StyleTracker.pardonTarget(
			Collections.emptyList(), 104, -1, -100));
	}

	@Test
	public void aConfirmedMeleeSwingIsStillConvictedWithACastBesideIt()
	{
		// auto-retaliate lands a real sword hit at 100 (same-tick Attack XP), then
		// the player casts at 102. The delayed magic xp must clear the CAST, not
		// buy the swing an alibi it did not earn.
		StyleTracker.Verdict swing = verdict(100, AttackStyle.MELEE,
			StyleTracker.JudgementSource.STANCE);
		StyleTracker.Verdict cast = verdict(102, AttackStyle.MELEE,
			StyleTracker.JudgementSource.STANCE);
		List<StyleTracker.Verdict> recent = Arrays.asList(swing, cast);
		Assert.assertSame(cast, StyleTracker.pardonTarget(recent, 105, 100, -100));
		Assert.assertFalse(swing.pardoned);
	}
}

package com.gachaman.service;

import com.gachaman.*;
import com.gachaman.data.*;
import com.gachaman.model.*;
import com.gachaman.persist.*;
import java.util.*;
import org.junit.*;

/**
 * {@code ChestService.openTollChest} — the tier-scoped opener the Toll pays for.
 *
 * <p>Two of these pin traps that would otherwise ship silently. A pull that
 * escaped its ladder still deals a card, and a pull that counted the surrendered
 * card as owned still deals a card; neither throws, neither logs, and both only
 * ever hurt the player who has just destroyed a veteran card to get here.
 */
public class TollChestPullTest
{
	private static GachaStateService inMemoryStateService()
	{
		StateStore store = new StateStore(null, null, null)
		{
			@Override
			public void save(GachaState state)
			{
			}

			@Override
			public void save(GachaState state, boolean flushDiskNow)
			{
			}

			@Override
			public GachaState load()
			{
				return null;
			}
		};
		GachaStateService service = new GachaStateService(store);
		service.load(3);
		return service;
	}

	private GachaStateService stateService;
	private ChestService chestService;
	private LoadoutFixture.Cards cards;

	@Before
	public void setUp()
	{
		stateService = inMemoryStateService();
		cards = new LoadoutFixture.Cards();
		chestService = new ChestService(stateService, new CreditSink(stateService), cards,
			new CeremonyBus(), new GachaRng(20260815L), new com.google.gson.Gson(),
			null, null, null);
		// funds only the ordinary-chest control below; every Toll pull is free
		stateService.mutate(s -> s.withGc(10_000));
	}

	/** Every card the fixture defines for one tier ladder. */
	private Set<Integer> cardIdsOfTier(String tierKey)
	{
		Set<Integer> ids = new HashSet<>();
		for (CardDefinition def : cards.all().values())
		{
			if (tierKey.equals(def.getTierKey()))
			{
				ids.add(def.getCardId());
			}
		}
		return ids;
	}

	private ChestService.RolledSlot onlySlotOf(ChestService.ChestOpenResult result)
	{
		Assert.assertNotNull("the Toll must deal something", result);
		Assert.assertEquals("a Toll pull is exactly one card", 1, result.getSlots().size());
		return result.getSlots().get(0);
	}

	// --- the ladder ----------------------------------------------------------

	/**
	 * The whole promise of the Toll: "a blind pull of its tier". Repeated, because
	 * a pool bug that leaked one tier in ten would pass a single draw.
	 */
	@Test
	public void everyPullComesFromTheNamedLadder()
	{
		Set<Integer> rune = cardIdsOfTier("rune");
		Assert.assertFalse("the fixture must define a rune ladder", rune.isEmpty());

		for (int i = 0; i < 200; i++)
		{
			ChestService.ChestOpenResult result = chestService.openTollChest("rune", "spent-uuid");
			ChestService.RolledSlot slot = onlySlotOf(result);
			if (slot.getVariant() == Variant.HOLOGRAM)
			{
				// a hologram represents a tier rather than a card; it must still be
				// this tier
				Assert.assertEquals("a hologram pull must name the paid-for tier",
					"rune", slot.getHologramTier());
			}
			else
			{
				Assert.assertTrue("pull #" + i + " escaped the rune ladder: card "
					+ slot.getCardId(), rune.contains(slot.getCardId()));
			}
			chestService.commitPending();
		}
	}

	/**
	 * The trap group 3 named: {@code openThemedChest(tierKey)} looks like the
	 * obvious route and silently is not, because a tier key is not a set tag. If
	 * openTollChest were ever re-implemented that way the pool would fall back to
	 * every card in the game — which this test detects as pulls from other tiers.
	 */
	@Test
	public void theUntieredBandIsItsOwnLadderRatherThanEverything()
	{
		// The fixture gives every card a tier, so the untiered band is EMPTY and
		// the pool guard falls back to all cards. That is the documented
		// behaviour of an empty pool, and pinning it here records that "untiered"
		// is a real branch rather than a synonym for null.
		ChestService.ChestOpenResult result = chestService.openTollChest(null, "spent-uuid");
		ChestService.RolledSlot slot = onlySlotOf(result);
		Assert.assertNotNull("an untiered Toll must still deal a card", slot);
		Assert.assertEquals("the result must record the untiered band, not a null tier",
			RollOdds.UNTIERED, result.getTollTierKey());
	}

	// --- the duplicate test --------------------------------------------------

	/**
	 * The surrendered card is still in the album when the pull is rolled — that
	 * ordering is deliberate, so a crash cannot take the card and hand back
	 * nothing. It must therefore be invisible to the duplicate test, or the
	 * player who pays a 300-kill veteran and pulls its own card back gets a
	 * handful of dupe GC for it.
	 */
	@Test
	public void theSurrenderedCardIsNotItsOwnDuplicate()
	{
		int paidCardId = cardIdsOfTier("rune").iterator().next();
		OwnedCard paid = new OwnedCard("spent-uuid", paidCardId, null, Variant.NORMAL,
			100L, "chest:GILDED", 300);
		stateService.mutate(s -> s.withOwnedCards(Collections.singletonList(paid)));

		boolean sawItsOwnCard = false;
		for (int i = 0; i < 400 && !sawItsOwnCard; i++)
		{
			ChestService.ChestOpenResult result = chestService.openTollChest("rune", "spent-uuid");
			ChestService.RolledSlot slot = onlySlotOf(result);
			if (slot.getVariant() == Variant.NORMAL && slot.getCardId() == paidCardId)
			{
				sawItsOwnCard = true;
				Assert.assertFalse("the card being surrendered must not count as a duplicate"
					+ " of itself — it is only still owned because the pull is dealt first",
					slot.isDuplicate());
			}
			chestService.commitPending();
		}
		Assert.assertTrue("the paid card's own id must come up in its own small ladder —"
			+ " if it never does, this test is proving nothing", sawItsOwnCard);
	}

	/**
	 * The other half of that rule, and the reason the exclusion is by UUID rather
	 * than by key: a player holding TWO copies who pays one still owns the other,
	 * so the pull genuinely is a duplicate. Excluding the key instead would hand
	 * them a free non-dupe.
	 */
	@Test
	public void aSecondCopyStillCountsAsADuplicate()
	{
		int paidCardId = cardIdsOfTier("rune").iterator().next();
		OwnedCard paid = new OwnedCard("spent-uuid", paidCardId, null, Variant.NORMAL,
			100L, "chest:GILDED", 300);
		OwnedCard kept = new OwnedCard("kept-uuid", paidCardId, null, Variant.NORMAL,
			100L, "chest:GILDED", 5);
		stateService.mutate(s -> s.withOwnedCards(Arrays.asList(paid, kept)));

		boolean sawIt = false;
		for (int i = 0; i < 400 && !sawIt; i++)
		{
			ChestService.ChestOpenResult result = chestService.openTollChest("rune", "spent-uuid");
			ChestService.RolledSlot slot = onlySlotOf(result);
			if (slot.getVariant() == Variant.NORMAL && slot.getCardId() == paidCardId)
			{
				sawIt = true;
				Assert.assertTrue("the KEPT copy still makes this a duplicate", slot.isDuplicate());
			}
			chestService.commitPending();
		}
		Assert.assertTrue("the card id must come up for this test to mean anything", sawIt);
	}

	// --- the contract with TollService ---------------------------------------

	/**
	 * TollService reads a null return as "nothing happened" and leaves the week
	 * unspent, so this must never return null after changing anything.
	 */
	@Test
	public void aPullRefusesWhileAnotherRevealIsPending()
	{
		Assert.assertNotNull(chestService.openTollChest("rune", "spent-uuid"));
		Assert.assertNull("a second pull must refuse while the first is unrevealed",
			chestService.openTollChest("rune", "spent-uuid"));
	}

	@Test
	public void aPullRefusesWhenTheCardDatabaseIsNotReady()
	{
		ChestService notReady = new ChestService(stateService, new CreditSink(stateService),
			new CardDatabase(null, null, null, null, null), new CeremonyBus(),
			new GachaRng(1L), new com.google.gson.Gson(), null, null, null);
		Assert.assertNull("no pool means no pull, and nothing taken",
			notReady.openTollChest("rune", "spent-uuid"));
	}

	/** Free at the till — the price was a card, and it was taken elsewhere. */
	@Test
	public void thePullCostsNoGachaCoins()
	{
		ChestService.ChestOpenResult result = chestService.openTollChest("rune", "spent-uuid");
		Assert.assertEquals("the Toll is paid in a card, never in GC", 0, result.getPricePaid());
	}

	/**
	 * A one-ladder pool has nothing to upgrade INTO, so the jackpot is excluded —
	 * and, more importantly, the exclusion is what keeps the ladder promise true
	 * for the rerolled card as well.
	 */
	@Test
	public void aPullNeverJackpotUpgrades()
	{
		for (int i = 0; i < 300; i++)
		{
			ChestService.ChestOpenResult result = chestService.openTollChest("rune", "spent-uuid");
			Assert.assertFalse("a Toll pull has one ladder and nothing to upgrade into",
				result.isJackpotUpgraded());
			chestService.commitPending();
		}
	}

	/**
	 * The tier must survive onto the RESULT, because the in-reveal reroll rebuilds
	 * its pool from that object rather than from the call. Drop the field and a
	 * rerolled Toll pull escapes to the all-cards pool — the player spends a token
	 * and leaves the ladder they paid for.
	 */
	@Test
	public void theLadderIsCarriedOnTheResultSoARerollCannotEscapeIt()
	{
		ChestService.ChestOpenResult result = chestService.openTollChest("rune", "spent-uuid");
		Assert.assertEquals("rune", result.getTollTierKey());

		stateService.mutate(s -> s.withRerollTokens(5));
		Set<Integer> rune = cardIdsOfTier("rune");
		ChestService.RolledSlot fresh = chestService.rerollSlot(0);
		Assert.assertNotNull("a Toll pull must be rerollable like any other reveal", fresh);
		if (fresh.getVariant() == Variant.HOLOGRAM)
		{
			Assert.assertEquals("rune", fresh.getHologramTier());
		}
		else
		{
			Assert.assertTrue("a rerolled Toll pull must stay inside the paid-for ladder",
				rune.contains(fresh.getCardId()));
		}
	}

	/** An ordinary chest must carry no tier, or every reroll would be confined. */
	@Test
	public void anOrdinaryChestCarriesNoLadder()
	{
		ChestService.ChestOpenResult ordinary = chestService.openChest(Tuning.Chest.BATTERED);
		Assert.assertNotNull(ordinary);
		Assert.assertNull("only a Toll pull is confined to a ladder",
			ordinary.getTollTierKey());
	}
}

package com.gachaman.service;

import com.gachaman.*;
import com.gachaman.model.*;
import com.gachaman.persist.*;
import org.junit.*;

/**
 * Voucher-first purchaseCharge spend path and Compactor kill-count doubling
 * (headless, real in-memory state; the null client is never touched because
 * kill tests use perKillGc 0 contracts — the award branch is the only client
 * read in onKill).
 */
public class TaskServiceChargeTest
{
	private GachaStateService stateService;
	private CreditSink creditSink;
	private TaskService taskService;

	private static GachaStateService inMemoryStateService()
	{
		StateStore store = new StateStore(null, null, null)
		{
			@Override
			public void save(GachaState state)
			{
			}

			@Override
			public void save(GachaState state, boolean flushDiskNow)
			{
			}

			@Override
			public GachaState load()
			{
				return null; // forces a fresh in-memory state
			}
		};
		GachaStateService service = new GachaStateService(store);
		service.load(3);
		return service;
	}

	@Before
	public void setUp()
	{
		stateService = inMemoryStateService();
		creditSink = new CreditSink(stateService);
		ComplianceService complianceService = new ComplianceService(stateService, creditSink, null, null);
		CeremonyBus ceremonyBus = new CeremonyBus();
		StyleService styleService = StyleFixture.styleService(stateService, complianceService, ceremonyBus,
			new GachaRng(1L));
		com.gachaman.data.MonsterTable monsterTable =
			com.gachaman.data.MonsterTable.load(new com.google.gson.Gson());
		taskService = new TaskService(null, stateService, creditSink, complianceService,
			styleService, ceremonyBus, new GachaRng(1L), monsterTable,
			// null Client already means these tests never reach rollOffers()
			null, null,
			// The three collaborators added with the Preferred Weapon and the
			// Consignment are unwired here: no contract in this file pays per kill,
			// so the award branch (the only reader of the weapon pair) is never
			// reached, and no completion here tips the style cycle.
			null, null, null);
	}

	private void seed(long gc, int compactors, int extenders, boolean withTask)
	{
		seed(gc, compactors, extenders, withTask, 8);
	}

	private void seed(long gc, int compactors, int extenders, boolean withTask, int perKillGc)
	{
		stateService.mutate(s -> {
			GachaState next = s.withGc(gc)
				.withFreeCompactors(compactors)
				.withFreeExtenders(extenders);
			if (withTask)
			{
				next = next.withActiveTask(ActiveTask.builder()
					.difficulty(TaskDifficulty.EASY)
					.monsterName("Goblin")
					.killsRequired(10)
					.killsDone(0)
					.perKillGc(perKillGc)
					.completionGc(250)
					.acceptedAtMs(1L)
					.build());
			}
			return next;
		});
	}

	private KillTracker.Kill goblinKill(int tick)
	{
		return new KillTracker.Kill("Goblin", 2, 1, tick, tick - 3, false, 3, false, null);
	}

	@Test
	public void assistedPenaltyStandsDownOnSharedPartyContracts()
	{
		ActiveTask solo = ActiveTask.builder()
			.difficulty(TaskDifficulty.EASY)
			.monsterName("Goblin")
			.killsRequired(10)
			.perKillGc(8)
			.completionGc(250)
			.acceptedAtMs(1L)
			.build();
		ActiveTask party = solo.toBuilder().partyLabel("Party of 3").build();
		Assert.assertTrue(TaskService.assistedPenaltyApplies(true, true, solo));
		Assert.assertFalse(TaskService.assistedPenaltyApplies(true, true, party));
		// carry clause converts the contract back to solo — the rule re-arms
		Assert.assertTrue(TaskService.assistedPenaltyApplies(true, true,
			party.withPartyConvertedToSolo(true)));
		Assert.assertFalse(TaskService.assistedPenaltyApplies(false, true, solo));
		Assert.assertFalse(TaskService.assistedPenaltyApplies(true, false, solo));
	}

	@Test
	public void voucherConsumedInsteadOfGc()
	{
		seed(1000, 1, 1, true);
		Assert.assertTrue(taskService.purchaseCharge(true));
		GachaState state = stateService.get();
		Assert.assertEquals(0, state.getFreeCompactors());
		Assert.assertEquals(1, state.getFreeExtenders());
		Assert.assertEquals("GC untouched when a voucher pays", 1000, state.getGc());
		Assert.assertEquals("COMPACTOR", state.getActiveTask().getAppliedCharge());
	}

	@Test
	public void secondChargeSameTaskBlocked()
	{
		seed(1000, 1, 1, true);
		Assert.assertTrue(taskService.purchaseCharge(true));
		Assert.assertFalse(taskService.purchaseCharge(true));
		Assert.assertFalse(taskService.purchaseCharge(false));
		GachaState state = stateService.get();
		Assert.assertEquals(0, state.getFreeCompactors());
		Assert.assertEquals(1, state.getFreeExtenders());
		Assert.assertEquals(1000, state.getGc());
	}

	@Test
	public void gcSpentWhenNoVoucher()
	{
		seed(1000, 0, 0, true);
		Assert.assertTrue(taskService.purchaseCharge(true));
		GachaState state = stateService.get();
		Assert.assertEquals(1000 - Tuning.COMPACTOR_PRICE_GC, state.getGc());
		Assert.assertEquals("COMPACTOR", state.getActiveTask().getAppliedCharge());
	}

	@Test
	public void voucherWorksAtZeroGc()
	{
		seed(0, 0, 1, true);
		Assert.assertTrue(taskService.purchaseCharge(false));
		GachaState state = stateService.get();
		Assert.assertEquals(0, state.getFreeExtenders());
		Assert.assertEquals(0, state.getGc());
		Assert.assertEquals("EXTENDER", state.getActiveTask().getAppliedCharge());
	}

	@Test
	public void wrongTypeVoucherNotUsed()
	{
		seed(0, 1, 0, true);
		Assert.assertFalse("extender unaffordable, compactor voucher must not cross over",
			taskService.purchaseCharge(false));
		GachaState state = stateService.get();
		Assert.assertEquals(1, state.getFreeCompactors());
		Assert.assertNull(state.getActiveTask().getAppliedCharge());
	}

	@Test
	public void noActiveTaskDoesNotConsumeVoucher()
	{
		seed(1000, 1, 1, false);
		Assert.assertFalse(taskService.purchaseCharge(true));
		GachaState state = stateService.get();
		Assert.assertEquals(1, state.getFreeCompactors());
		Assert.assertEquals(1, state.getFreeExtenders());
		Assert.assertEquals(1000, state.getGc());
	}

	@Test
	public void compactorDoublesKillCount()
	{
		seed(1000, 1, 0, true, 0);
		Assert.assertTrue(taskService.purchaseCharge(true));
		taskService.onKill(goblinKill(10));
		Assert.assertEquals("one kill must count as two", 2,
			stateService.get().getActiveTask().getKillsDone());
		taskService.onKill(goblinKill(20));
		Assert.assertEquals(4, stateService.get().getActiveTask().getKillsDone());
	}

	@Test
	public void plainKillCountsOne()
	{
		seed(1000, 0, 0, true, 0);
		taskService.onKill(goblinKill(10));
		Assert.assertEquals(1, stateService.get().getActiveTask().getKillsDone());
	}

	@Test
	public void compactorFinalKillClampsAndCompletes()
	{
		seed(1000, 1, 0, true, 0);
		Assert.assertTrue(taskService.purchaseCharge(true));
		// 9/10 done: the doubled kill must clamp to 10 (not 11) and complete
		stateService.mutate(s -> s.withActiveTask(s.getActiveTask().withKillsDone(9)));
		taskService.onKill(goblinKill(10));
		GachaState state = stateService.get();
		Assert.assertNull("task must complete", state.getActiveTask());
		Assert.assertEquals(1, state.getTotalTasksCompleted());
	}

	@Test
	public void lootOracleVerdict()
	{
		// loot received = server proof of full credit, overrides any suspicion
		Assert.assertFalse(KillTracker.finalAssisted(true, true, true, true));
		Assert.assertFalse(KillTracker.finalAssisted(true, false, true, true));
		// suspicion convicts regardless of the loot pipeline
		Assert.assertTrue(KillTracker.finalAssisted(false, true, false, true));
		Assert.assertTrue(KillTracker.finalAssisted(false, true, true, false));
		// absence convicts only when the pipeline is live AND a drop was guaranteed
		Assert.assertTrue(KillTracker.finalAssisted(false, false, true, true));
		Assert.assertFalse("dead pipeline must never convict",
			KillTracker.finalAssisted(false, false, false, true));
		Assert.assertFalse("no guaranteed drop proves nothing",
			KillTracker.finalAssisted(false, false, true, false));
	}

	@Test
	public void kcAdvanceRules()
	{
		// plain kill
		Assert.assertEquals(1, TaskService.kcAdvance(false, false, false).getIncrement());
		// compactor doubles
		Assert.assertEquals(2, TaskService.kcAdvance(true, false, false).getIncrement());
		// assisted normal kill: first banks a half, second redeems it
		TaskService.KcAdvance first = TaskService.kcAdvance(false, true, false);
		Assert.assertEquals(0, first.getIncrement());
		Assert.assertTrue(first.isHalfPending());
		TaskService.KcAdvance second = TaskService.kcAdvance(false, true, true);
		Assert.assertEquals(1, second.getIncrement());
		Assert.assertFalse(second.isHalfPending());
		// assisted compactor kill lands back on exactly 1, half untouched
		Assert.assertEquals(1, TaskService.kcAdvance(true, true, false).getIncrement());
		Assert.assertFalse(TaskService.kcAdvance(true, true, false).isHalfPending());
		Assert.assertEquals(1, TaskService.kcAdvance(true, true, true).getIncrement());
		Assert.assertTrue("pending half survives a compactor-assisted kill",
			TaskService.kcAdvance(true, true, true).isHalfPending());
		// unassisted kills never touch a banked half
		Assert.assertTrue(TaskService.kcAdvance(false, false, true).isHalfPending());
	}

	@Test
	public void compactorSkippedCountPaysNothing()
	{
		// perKillGc 0 keeps the client untouched; discovery pays a flat +25 on
		// the first-ever goblin, so any GC delta beyond that would mean the
		// skipped count was paid
		seed(0, 1, 0, true, 0);
		Assert.assertTrue(taskService.purchaseCharge(true));
		taskService.onKill(goblinKill(10));
		long afterFirst = stateService.get().getGc();
		taskService.onKill(goblinKill(20));
		Assert.assertEquals("second kill of a known species with perKill 0 must pay 0",
			afterFirst, stateService.get().getGc());
	}
}

package com.gachaman.service;

import com.gachaman.*;
import com.gachaman.model.*;
import java.util.*;
import org.junit.*;

/**
 * The Patron's Mark rules, in isolation. Every decision the feature makes
 * lives in these statics — PartyRollService.creditPatrons is reduced to
 * reading a roster and calling them, and PartyTab and PatronsTab only draw the
 * answer.
 *
 * The ledger is keyed on the ACCOUNT KEY with the display name demoted to a
 * label, so the theme running through this file is that identity and label are
 * separable: a rename must not fork a history, and a shared name must not merge
 * two strangers.
 *
 * What this does NOT prove: that two clients agree on a count. They never have
 * to. Each client keeps a private ledger of its own partners; there is no wire
 * message, no host authority and nothing to desync.
 */
public class PatronMarkTest
{
	/** A fixed clock. Real time in a test would make lastSharedAt unassertable. */
	private static final long NOW = 1_700_000_000_000L;

	private static final long DAY = 24L * 60 * 60 * 1000;

	/**
	 * A distinct, well-formed account key. Canonical casing, exactly 16 hex.
	 *
	 * Padded with 'a' rather than '0' so every key CONTAINS a letter: the
	 * case-folding assertions below upper-case a key and expect a different
	 * string back, and an all-digit key would make toUpperCase a no-op and
	 * those tests vacuously green. Only the suffix varies, so keys still sort
	 * by n and the tiebreak assertions stay readable.
	 */
	private static String key(int n)
	{
		String hex = Integer.toHexString(n);
		StringBuilder out = new StringBuilder(AccountKey.KEY_LENGTH);
		for (int i = hex.length(); i < AccountKey.KEY_LENGTH; i++)
		{
			out.append('a');
		}
		return out.append(hex).toString();
	}

	@Test
	public void theTestKeyHelperProducesRealKeys()
	{
		// this file's whole premise. A helper that quietly emitted something
		// normalize() rejects would make every assertion below test the junk
		// path instead of the one it names.
		for (int n : new int[]{0, 1, 9, 50, 255})
		{
			Assert.assertEquals("key(" + n + ") must be canonical",
				key(n), AccountKey.normalize(key(n)));
			Assert.assertNotEquals("key(" + n + ") must contain a hex letter, or the"
				+ " case-folding tests below prove nothing",
				key(n), key(n).toUpperCase(Locale.ROOT));
		}
		Assert.assertNotEquals(key(1), key(2));
	}

	/** One partner, so the common single-credit case reads as one line. */
	private static Map<String, String> one(String accountKey, String name)
	{
		Map<String, String> partners = new LinkedHashMap<>();
		partners.put(accountKey, name);
		return partners;
	}

	// --- A. identity is the key; the name is only a label ---

	@Test
	public void normalizeNameRejectsThePartyPlaceholder()
	{
		// PartyMember's CONSTRUCTOR DEFAULT, verified in the shipped client jar:
		// the literal "<unknown>" sits in its constant pool, and the only caller
		// of setDisplayName in the whole jar is the built-in Party plugin. With
		// that plugin off, EVERY member reads as this — storing it would put a
		// placeholder on the Patrons page as though it were somebody's name.
		Assert.assertNull("the placeholder must never be stored as a name",
			PatronMark.normalizeName("<unknown>"));
		Assert.assertNull(PatronMark.normalizeName(null));
		Assert.assertNull(PatronMark.normalizeName(""));
		Assert.assertNull(PatronMark.normalizeName("   "));
		// angle brackets would also be eaten by the sidebar's HTML renderer
		Assert.assertNull(PatronMark.normalizeName("<col=ff0000>Zezima"));
		Assert.assertNull(PatronMark.normalizeName("Zezima>"));
	}

	@Test
	public void normalizeNameTrimsAndBoundsTheName()
	{
		Assert.assertEquals("Zezima", PatronMark.normalizeName("  Zezima  "));
		// U+00A0 is Jagex's word separator. It reads as a space but is a
		// different character, so it is folded here rather than drawn raw.
		// Built by code point because in source the two characters are
		// indistinguishable and one editor pass would make this vacuous.
		Assert.assertEquals("Zezima Pk",
			PatronMark.normalizeName("Zezima" + (char) 0xA0 + "Pk"));
		Assert.assertEquals("a 12-character name is legal", "123456789012",
			PatronMark.normalizeName("123456789012"));
		Assert.assertNull("13 characters cannot be a real OSRS name",
			PatronMark.normalizeName("1234567890123"));
	}

	@Test
	public void aNameIsALabelNotAnIdentity()
	{
		// the whole reason the ledger moved off names: a partner who renames must
		// keep one history, and two partners who happen to share a name must keep
		// two. A name-keyed map got both of these backwards.
		Map<String, PatronRecord> ledger = PatronMark.credit(null,
			one(key(1), "Alpha"), 100, NOW);
		ledger = PatronMark.credit(ledger, one(key(1), "Renamed"), 100, NOW);

		Assert.assertEquals("a rename is one partner, not two", 1, ledger.size());
		Assert.assertEquals(2, PatronMark.countFor(ledger, key(1)));
		Assert.assertEquals("the label follows the latest completion",
			"Renamed", PatronMark.recordFor(ledger, key(1)).getName());

		// a completion credited while their name was unreadable keeps the label
		ledger = PatronMark.credit(ledger, one(key(1), "<unknown>"), 100, NOW);
		Assert.assertEquals(3, PatronMark.countFor(ledger, key(1)));
		Assert.assertEquals("an unreadable name must not blank a drawn row",
			"Renamed", PatronMark.recordFor(ledger, key(1)).getName());

		// and the converse: one name, two accounts, two rows
		Map<String, String> namesakes = new LinkedHashMap<>();
		namesakes.put(key(7), "Zezima");
		namesakes.put(key(8), "Zezima");
		Map<String, PatronRecord> two = PatronMark.credit(null, namesakes, 100, NOW);
		Assert.assertEquals("a shared name is not a shared identity", 2, two.size());
		Assert.assertEquals(1, PatronMark.countFor(two, key(7)));
		Assert.assertEquals(1, PatronMark.countFor(two, key(8)));
	}

	// --- B. crediting a finished contract ---

	@Test
	public void creditReturnsTheSameInstanceWhenNothingIsCreditable()
	{
		// this exact identity is what GachaStateService.mutate short-circuits on
		// (`next == state`), so a completion with no creditable partner pays for
		// no gzip + SHA-256 of the whole save at all
		Map<String, PatronRecord> current = new LinkedHashMap<>();
		current.put(key(1), new PatronRecord("Zezima", 4, NOW));
		Assert.assertSame(current, PatronMark.credit(current, null, 100, NOW));
		Assert.assertSame(current,
			PatronMark.credit(current, Collections.emptyMap(), 100, NOW));

		Map<String, String> junk = new LinkedHashMap<>();
		junk.put("not-a-key", "Zezima");
		junk.put("00112233445566", "Short");
		junk.put("00112233445566gg", "NotHex");
		Assert.assertSame("no usable key is the same as no partners",
			current, PatronMark.credit(current, junk, 100, NOW));
	}

	@Test
	public void creditReturnsTheSameInstanceWhenTheCapTurnsEveryoneAway()
	{
		// the subtle half of the identity contract: a full ledger whose partners
		// all have real histories accepts nobody, so NOTHING changed — handing
		// back an equal-but-distinct map would slip past mutate's `next ==
		// state` check and buy a gzip + SHA-256 of the whole save for no edit
		int cap = 3;
		Map<String, PatronRecord> full = new LinkedHashMap<>();
		for (int i = 0; i < cap; i++)
		{
			full.put(key(i), new PatronRecord("Partner" + i, 2, NOW));
		}
		Map<String, String> strangers = new LinkedHashMap<>();
		strangers.put(key(50), "Stranger");
		strangers.put(key(51), "Drifter");
		Assert.assertSame(full, PatronMark.credit(full, strangers, cap, NOW));
	}

	@Test
	public void oneAccountIsOneMarkHoweverManyClients()
	{
		// the same account dual-logged into the party arrives under two member
		// ids. The caller collapses them into one map entry, but two entries
		// differing only in case would still normalize to one partner and credit
		// them twice off a single contract — one mark per partner is the rule the
		// whole feature rests on, so it is enforced here too.
		Map<String, String> doubled = new LinkedHashMap<>();
		doubled.put(key(1), "Zezima");
		doubled.put(key(1).toUpperCase(Locale.ROOT), "Zezima");
		doubled.put("  " + key(1) + "  ", "Zezima");

		Map<String, PatronRecord> ledger = PatronMark.credit(null, doubled, 100, NOW);
		Assert.assertEquals(1, ledger.size());
		Assert.assertEquals("one contract is one mark", 1, PatronMark.countFor(ledger, key(1)));
		Assert.assertEquals("the stored key is canonical, whatever casing arrived",
			key(1), ledger.keySet().iterator().next());
	}

	@Test
	public void creditNeverMutatesTheMapItWasGiven()
	{
		// the map comes off the shared, immutable state object, and
		// creditPatrons compares the pre-mutate snapshot against the result —
		// an in-place write would corrupt both
		Map<String, PatronRecord> original = new LinkedHashMap<>();
		original.put(key(1), new PatronRecord("Zezima", 4, NOW));
		Map<String, PatronRecord> guarded = Collections.unmodifiableMap(original);

		Map<String, String> partners = new LinkedHashMap<>();
		partners.put(key(1), "Zezima");
		partners.put(key(2), "B0aty");
		Map<String, PatronRecord> next = PatronMark.credit(guarded, partners, 100, NOW);

		Assert.assertEquals("the caller's map is untouched", 1, guarded.size());
		Assert.assertEquals(4, PatronMark.countFor(guarded, key(1)));
		Assert.assertEquals(5, PatronMark.countFor(next, key(1)));
		Assert.assertEquals(1, PatronMark.countFor(next, key(2)));
	}

	@Test
	public void lastSharedAtIsStampedOnEveryCredit()
	{
		// the Patrons page draws "last <relative>", so a stamp written only on
		// the FIRST contract would show a years-old date for a daily partner
		Map<String, PatronRecord> ledger = PatronMark.credit(null,
			one(key(1), "Zezima"), 100, NOW);
		Assert.assertEquals(NOW, PatronMark.recordFor(ledger, key(1)).getLastSharedAt());

		ledger = PatronMark.credit(ledger, one(key(1), "Zezima"), 100, NOW + 5 * DAY);
		Assert.assertEquals("the stamp moves with the partnership",
			NOW + 5 * DAY, PatronMark.recordFor(ledger, key(1)).getLastSharedAt());
		Assert.assertEquals(2, PatronMark.countFor(ledger, key(1)));
	}

	@Test
	public void countForToleratesJunkAndNulls()
	{
		Assert.assertEquals(0, PatronMark.countFor(null, key(1)));
		Assert.assertEquals(0, PatronMark.countFor(Collections.emptyMap(), key(1)));
		Assert.assertEquals(0, PatronMark.countFor(
			Collections.singletonMap(key(1), new PatronRecord("Zezima", 3, NOW)), key(2)));
		Assert.assertEquals("an unknown account is not a lookup",
			0, PatronMark.countFor(
				Collections.singletonMap(key(1), new PatronRecord("Zezima", 3, NOW)), null));
		Assert.assertEquals(0, PatronMark.countFor(
			Collections.singletonMap(key(1), new PatronRecord("Zezima", 3, NOW)), "not-a-key"));

		// Gson can deserialize {"0000…01":null} out of a hand-edited save
		Map<String, PatronRecord> nulled = new HashMap<>();
		nulled.put(key(1), null);
		Assert.assertEquals(0, PatronMark.countFor(nulled, key(1)));
		Assert.assertNull(PatronMark.recordFor(nulled, key(1)));

		// as can a zero count, which is a row nobody has a history with
		Assert.assertEquals(0, PatronMark.countFor(
			Collections.singletonMap(key(1), new PatronRecord("Ghost", 0, NOW)), key(1)));
	}

	@Test
	public void aNonCanonicalStoredKeyDrawsNowhere()
	{
		// recordFor looks up with the NORMALIZED key, so an upper-cased key in a
		// hand-edited save would be listed by ranked() and found by nothing: the
		// Patrons page would name a top patron the party page could draw no pip
		// for. Both sides must agree, so it is junk to both.
		Map<String, PatronRecord> hand = new LinkedHashMap<>();
		hand.put(key(1).toUpperCase(Locale.ROOT), new PatronRecord("Forged", 99, NOW));
		hand.put(key(2), new PatronRecord("Real", 1, NOW));

		Assert.assertEquals(0, PatronMark.countFor(hand, key(1)));
		Assert.assertEquals(1, PatronMark.partnerCount(hand));
		Assert.assertEquals(key(2), PatronMark.topKey(hand));
		Assert.assertEquals(1, PatronMark.ranked(hand).size());
		Assert.assertEquals("Real", PatronMark.ranked(hand).get(0).getName());
	}

	// --- C. the bound, and who it may displace ---

	@Test
	public void aStrangerCannotDisplaceARealHistory()
	{
		int cap = 5;
		Map<String, PatronRecord> full = new LinkedHashMap<>();
		for (int i = 0; i < cap; i++)
		{
			full.put(key(i), new PatronRecord("Partner" + i, 2, NOW));
		}

		Map<String, PatronRecord> next = PatronMark.credit(full,
			one(key(50), "Stranger"), cap, NOW);
		Assert.assertEquals("the map stays bounded", cap, next.size());
		Assert.assertEquals("a two-contract history is never evicted",
			0, PatronMark.countFor(next, key(50)));
		Assert.assertEquals(2, PatronMark.countFor(next, key(0)));

		// with one genuine one-off present, that one — and only that one — goes
		Map<String, PatronRecord> withOneOff = new LinkedHashMap<>(full);
		withOneOff.remove(key(4));
		withOneOff.put(key(9), new PatronRecord("OneOff", 1, NOW));
		Map<String, PatronRecord> after = PatronMark.credit(withOneOff,
			one(key(50), "Stranger"), cap, NOW);
		Assert.assertEquals(cap, after.size());
		Assert.assertEquals(0, PatronMark.countFor(after, key(9)));
		Assert.assertEquals(1, PatronMark.countFor(after, key(50)));
		Assert.assertEquals(2, PatronMark.countFor(after, key(0)));
	}

	@Test
	public void amongOneOffsTheColdestGoesFirst()
	{
		// a bound has to drop SOMETHING; dropping the partner you shared with
		// longest ago is the only choice that does not throw away the newest
		// relationship the moment it starts
		int cap = 3;
		Map<String, PatronRecord> full = new LinkedHashMap<>();
		full.put(key(1), new PatronRecord("Recent", 1, NOW));
		full.put(key(2), new PatronRecord("Ancient", 1, NOW - 400 * DAY));
		full.put(key(3), new PatronRecord("Middling", 1, NOW - 30 * DAY));

		Map<String, PatronRecord> after = PatronMark.credit(full,
			one(key(50), "Newcomer"), cap, NOW);
		Assert.assertEquals(cap, after.size());
		Assert.assertEquals("the coldest one-off is the victim",
			0, PatronMark.countFor(after, key(2)));
		Assert.assertEquals(1, PatronMark.countFor(after, key(1)));
		Assert.assertEquals(1, PatronMark.countFor(after, key(3)));
		Assert.assertEquals(1, PatronMark.countFor(after, key(50)));
	}

	@Test
	public void evictionIsDeterministic()
	{
		// Gson hands the map back as a LinkedTreeMap in JSON order, so an
		// order-sensitive victim would differ between a fresh map and a reloaded
		// one and a partner would vanish on some logins but not others. Every
		// count and every stamp is identical here, so ONLY the tiebreak decides.
		int[] forward = {1, 2, 3};
		int[] backward = {3, 2, 1};

		Map<String, PatronRecord> a = new LinkedHashMap<>();
		for (int n : forward)
		{
			a.put(key(n), new PatronRecord("Partner" + n, 1, NOW));
		}
		Map<String, PatronRecord> b = new LinkedHashMap<>();
		for (int n : backward)
		{
			b.put(key(n), new PatronRecord("Partner" + n, 1, NOW));
		}

		Map<String, PatronRecord> afterA = PatronMark.credit(a,
			one(key(50), "Newcomer"), forward.length, NOW);
		Map<String, PatronRecord> afterB = PatronMark.credit(b,
			one(key(50), "Newcomer"), backward.length, NOW);

		for (int n : forward)
		{
			Assert.assertEquals("victim must not depend on insertion order: " + key(n),
				PatronMark.countFor(afterA, key(n)), PatronMark.countFor(afterB, key(n)));
		}
		Assert.assertEquals(forward.length, afterA.size());
	}

	@Test
	public void aCapOfZeroOrLessIsNoCapAtAll()
	{
		// defensive: a mis-tuned constant must not silently stop counting
		Map<String, String> partners = new LinkedHashMap<>();
		partners.put(key(1), "Alpha");
		partners.put(key(2), "Bravo");
		partners.put(key(3), "Charlie");
		Assert.assertEquals(3, PatronMark.credit(null, partners, 0, NOW).size());
		Assert.assertEquals(3, PatronMark.credit(null, partners, -1, NOW).size());
	}

	// --- D. who wears the mark ---

	@Test
	public void topKeyIsIndependentOfMapOrder()
	{
		Map<String, PatronRecord> seed = new LinkedHashMap<>();
		seed.put(key(1), new PatronRecord("Alpha", 3, NOW));
		seed.put(key(2), new PatronRecord("Bravo", 9, NOW));
		seed.put(key(3), new PatronRecord("Charlie", 4, NOW));

		Assert.assertEquals(key(2), PatronMark.topKey(new HashMap<>(seed)));
		Assert.assertEquals(key(2), PatronMark.topKey(new LinkedHashMap<>(seed)));
		Assert.assertEquals(key(2), PatronMark.topKey(new TreeMap<>(seed)));

		// a tie must resolve the same way from either insertion order
		Map<String, PatronRecord> tieForward = new LinkedHashMap<>();
		tieForward.put(key(1), new PatronRecord("Alpha", 7, NOW));
		tieForward.put(key(2), new PatronRecord("Bravo", 7, NOW));
		Map<String, PatronRecord> tieBackward = new LinkedHashMap<>();
		tieBackward.put(key(2), new PatronRecord("Bravo", 7, NOW));
		tieBackward.put(key(1), new PatronRecord("Alpha", 7, NOW));
		Assert.assertEquals(PatronMark.topKey(tieForward), PatronMark.topKey(tieBackward));

		// and two NAMELESS ties still resolve, because the key is the last word
		Map<String, PatronRecord> nameless = new LinkedHashMap<>();
		nameless.put(key(5), new PatronRecord(null, 2, NOW));
		nameless.put(key(4), new PatronRecord(null, 2, NOW));
		Assert.assertEquals(key(4), PatronMark.topKey(nameless));
	}

	@Test
	public void topKeyIgnoresJunkKeysAndZeroCounts()
	{
		Map<String, PatronRecord> ledger = new LinkedHashMap<>();
		ledger.put("<unknown>", new PatronRecord("Placeholder", 999, NOW));
		ledger.put("", new PatronRecord("Blank", 5, NOW));
		ledger.put(key(1), new PatronRecord("Ghost", 0, NOW));
		ledger.put(key(2), null);
		ledger.put(key(3), new PatronRecord("Zezima", 1, NOW));

		Assert.assertEquals("a key that is not a key must never become the mark,"
			+ " however high its count", key(3), PatronMark.topKey(ledger));
		Assert.assertEquals(1, PatronMark.partnerCount(ledger));
		Assert.assertEquals(1, PatronMark.totalMarks(ledger));
	}

	@Test
	public void topKeyOfNothingIsNothing()
	{
		// the day-one path: render no mark, not a blank row
		Assert.assertNull(PatronMark.topKey(null));
		Assert.assertNull(PatronMark.topKey(Collections.emptyMap()));
		Assert.assertNull(PatronMark.topKey(
			Collections.singletonMap(key(1), new PatronRecord("Ghost", 0, NOW))));
		Assert.assertEquals(0, PatronMark.partnerCount(null));
		Assert.assertEquals(0, PatronMark.totalMarks(null));
		Assert.assertTrue(PatronMark.ranked(null).isEmpty());
	}

	@Test
	public void rankedIsDescendingAndAgreesWithTopKey()
	{
		// the Patrons page draws ranked() in order and must NOT re-sort: its
		// first row and the outlined pip on the party page are the same claim
		// about the same person, and two sorts would eventually disagree
		Map<String, PatronRecord> ledger = new LinkedHashMap<>();
		ledger.put(key(1), new PatronRecord("Alpha", 3, NOW));
		ledger.put(key(2), new PatronRecord("Bravo", 9, NOW));
		ledger.put(key(3), new PatronRecord("Charlie", 4, NOW));
		ledger.put(key(4), new PatronRecord("Ghost", 0, NOW));

		List<PatronRecord> ranked = PatronMark.ranked(ledger);
		Assert.assertEquals("uncounted rows are not partners", 3, ranked.size());
		for (int i = 1; i < ranked.size(); i++)
		{
			Assert.assertTrue("descending at " + i,
				ranked.get(i - 1).getCount() >= ranked.get(i).getCount());
		}
		Assert.assertSame("row 0 IS the mark's owner",
			PatronMark.recordFor(ledger, PatronMark.topKey(ledger)), ranked.get(0));
		Assert.assertEquals(3, PatronMark.partnerCount(ledger));
		Assert.assertEquals("marks, not contracts: one shared contract with three"
			+ " partners is three", 16, PatronMark.totalMarks(ledger));
	}

	@Test
	public void rankedIsNotTheCallersToEdit()
	{
		// it is handed straight to a panel loop; an accidental sort there would
		// silently disagree with topKey rather than fail
		try
		{
			PatronMark.ranked(Collections.singletonMap(key(1),
				new PatronRecord("Zezima", 1, NOW))).clear();
			Assert.fail("ranked() must be unmodifiable");
		}
		catch (UnsupportedOperationException expected)
		{
			// intended
		}
	}

	@Test
	public void displayNameFallsBackForAnUnnamedPartner()
	{
		// a partner credited while their client could not read their name is
		// still a real partner with a real count — the row draws either way
		Assert.assertEquals("An unnamed patron", PatronMark.displayName(null));
		Assert.assertEquals("An unnamed patron",
			PatronMark.displayName(new PatronRecord(null, 4, NOW)));
		Assert.assertEquals("a stored name that is not a name is not drawn raw",
			"An unnamed patron",
			PatronMark.displayName(new PatronRecord("<unknown>", 4, NOW)));
		Assert.assertEquals("Zezima",
			PatronMark.displayName(new PatronRecord("  Zezima  ", 4, NOW)));
	}

	// --- E. the tier ladder ---

	@Test
	public void tierLadderMatchesTheThresholds()
	{
		// driven off Tuning rather than hardcoded numbers, so retuning the
		// thresholds cannot silently invalidate this
		int[] tiers = Tuning.PATRON_TIERS;
		Assert.assertEquals("the ladder is ascending and has three rungs", 3, tiers.length);
		Assert.assertEquals(0, PatronMark.tierFor(0));
		for (int i = 0; i < tiers.length; i++)
		{
			Assert.assertEquals("one below threshold " + i, i, PatronMark.tierFor(tiers[i] - 1));
			Assert.assertEquals("at threshold " + i, i + 1, PatronMark.tierFor(tiers[i]));
		}
		Assert.assertEquals(tiers.length, PatronMark.tierFor(Integer.MAX_VALUE));
		for (int i = 1; i < tiers.length; i++)
		{
			Assert.assertTrue("thresholds must ascend", tiers[i] > tiers[i - 1]);
		}
	}

	@Test
	public void crossedTierFiresOnceAtEachThreshold()
	{
		// the chat line is the only feedback when the top patron is offline, so
		// a double-fire or a miss is directly user-visible
		for (int threshold : Tuning.PATRON_TIERS)
		{
			Assert.assertTrue("crossing " + threshold,
				PatronMark.crossedTier(threshold - 1, threshold));
			Assert.assertFalse("already past " + threshold,
				PatronMark.crossedTier(threshold, threshold + 1));
		}
		Assert.assertFalse(PatronMark.crossedTier(5, 9));
		Assert.assertFalse("standing still is not a crossing", PatronMark.crossedTier(10, 10));
	}

	@Test
	public void everyTierHasALabelAndTheLabelNeverThrows()
	{
		Assert.assertEquals("the label array must stay exactly one longer than"
			+ " PATRON_TIERS — index 0 is the untiered mark",
			Tuning.PATRON_TIERS.length + 1, PatronMark.labelCount());
		String previous = null;
		for (int count = 0; count <= 200; count++)
		{
			String label = PatronMark.tierLabel(count);
			Assert.assertNotNull("no label at " + count, label);
			Assert.assertFalse(label.isEmpty());
			if (previous != null && PatronMark.tierFor(count) == PatronMark.tierFor(count - 1))
			{
				Assert.assertEquals("the label may only change at a threshold",
					previous, label);
			}
			previous = label;
		}
	}

	// --- F. the whole path, end to end ---

	@Test
	public void aLongPartnershipClimbsTheLadderExactlyOnce()
	{
		// the property the feature exists for, and the one an id-keyed map could
		// never satisfy: a memberId is re-drawn from a fresh Random every login,
		// so tier II and III would be unreachable by construction
		Map<String, PatronRecord> ledger = null;
		int crossings = 0;
		for (int contract = 1; contract <= 100; contract++)
		{
			int before = PatronMark.countFor(ledger, key(1));
			// they rename halfway through: a name-keyed ledger forked here and
			// each half stalled below the next threshold
			String name = contract < 50 ? "Zezima" : "Zezima Pk";
			ledger = PatronMark.credit(ledger, one(key(1), name),
				Tuning.PATRON_MAX_PARTNERS, NOW + contract * DAY);
			int after = PatronMark.countFor(ledger, key(1));
			Assert.assertEquals(before + 1, after);
			if (PatronMark.crossedTier(before, after))
			{
				crossings++;
			}
		}
		Assert.assertEquals("one announcement per threshold, no more",
			Tuning.PATRON_TIERS.length, crossings);
		Assert.assertEquals("a rename must not fork the history", 1, ledger.size());
		Assert.assertEquals(key(1), PatronMark.topKey(ledger));
		Assert.assertEquals("Zezima Pk", PatronMark.displayName(PatronMark.recordFor(ledger, key(1))));
		Assert.assertEquals("Patron III",
			PatronMark.tierLabel(PatronMark.countFor(ledger, key(1))));
		Assert.assertEquals(NOW + 100 * DAY,
			PatronMark.recordFor(ledger, key(1)).getLastSharedAt());
	}
}

package com.gachaman.service;

import com.gachaman.data.*;
import com.google.gson.*;
import java.util.regex.*;
import org.junit.*;

/**
 * The KC line and the curated chatName have to agree. They did not for Barrows:
 * the in-game line is "Your Barrows chest count is: 5", and because the name is
 * captured lazily up to the counter noun it yields "Barrows" — which never
 * matched the old chatName of "Barrows chest", so the milestone never fired.
 */
public class BossKcParseTest
{
	private static String capturedName(String message)
	{
		Matcher matcher = BossKcService.KC_PATTERN.matcher(message);
		return matcher.find() ? matcher.group(1) : null;
	}

	private static int capturedCount(String message)
	{
		Matcher matcher = BossKcService.KC_PATTERN.matcher(message);
		return matcher.find() ? Integer.parseInt(matcher.group(2).replace(",", "")) : -1;
	}

	@Test
	public void barrowsChestLineCapturesTheConfiguredName()
	{
		Assert.assertEquals("Barrows", capturedName("Your Barrows chest count is: 5."));
	}

	@Test
	public void killLinesCaptureNamesWithPunctuationAndSpaces()
	{
		Assert.assertEquals("Zulrah", capturedName("Your Zulrah kill count is: 1."));
		Assert.assertEquals("K'ril Tsutsaroth", capturedName("Your K'ril Tsutsaroth kill count is: 42."));
		Assert.assertEquals("Thermonuclear smoke devil",
			capturedName("Your Thermonuclear smoke devil kill count is: 300."));
	}

	@Test
	public void thousandsSeparatorIsParsed()
	{
		Assert.assertEquals(1234, capturedCount("Your Kraken kill count is: 1,234."));
	}

	@Test
	public void nonKcChatIsIgnored()
	{
		Assert.assertNull(capturedName("Your Slayer task is complete."));
		Assert.assertNull(capturedName("Congratulations, you just advanced an Attack level."));
	}

	/**
	 * Every curated boss must be reachable: build the line the game would send
	 * and assert it captures back to exactly that boss's chatName.
	 */
	@Test
	public void everyCuratedBossChatNameRoundTrips()
	{
		BossTable table = BossTable.load(new Gson());
		Assert.assertFalse(table.getBosses().isEmpty());
		for (BossTable.Boss boss : table.getBosses())
		{
			String noun = "Barrows".equals(boss.getChatName()) ? "chest" : "kill";
			String line = "Your " + boss.getChatName() + " " + noun + " count is: 10.";
			Assert.assertEquals("KC line unparseable for " + boss.getBossName(),
				boss.getChatName(), capturedName(line));
		}
	}
}

package com.gachaman.service;

import com.gachaman.*;
import com.gachaman.data.*;
import com.gachaman.model.*;
import java.util.*;
import org.junit.*;

/**
 * The house lean and the odds disclosure share this arithmetic on purpose, so these
 * assertions pin BOTH at once: if a number here moves, the roll and the panel move
 * together or the build goes red. ChestService itself cannot be tested here — the
 * lean's reach test dereferences Client — which is exactly why the arithmetic was
 * lifted out into RollOdds.
 */
public class RollOddsTest
{
	private static final double EPS = 1e-9;

	private static CardDefinition card(int id, String tierKey, Rarity rarity)
	{
		return new CardDefinition(id, "card" + id, GearSlot.WEAPON, tierKey,
			tierKey == null ? 0 : 1, tierKey == null ? null : "scimitar", rarity, Set.of(id), true);
	}

	private static double shareOf(Map<RollOdds.TierBand, Double> shares, String tierKey,
		boolean wieldableNow)
	{
		Double value = shares.get(new RollOdds.TierBand(tierKey, wieldableNow));
		return value == null ? 0 : value;
	}

	// --- pity arithmetic, lifted verbatim out of rollRarity ---

	/**
	 * The regression that matters most: this is the block that used to sit inline in
	 * ChestService.rollRarity, so these five numbers are the old behaviour transcribed.
	 * Gilded is {55, 26, 12, 5, 2}; a 6% pity bonus moves 6 out of Common, 70% of it to
	 * Epic and 30% to Legendary.
	 */
	@Test
	public void adjustOddsMatchesTheOldInlineArithmetic()
	{
		double[] out = RollOdds.adjustOdds(Tuning.CHEST_ODDS.get(Tuning.Chest.GILDED), 6.0);
		Assert.assertArrayEquals(new double[]{49.0, 26.0, 12.0, 9.2, 3.8}, out, 1e-9);
	}

	/** Tuning.CHEST_ODDS hands out a shared array; a caller must never see it move. */
	@Test
	public void adjustOddsClonesAndNeverMutatesTheCallerArray()
	{
		double[] odds = Tuning.CHEST_ODDS.get(Tuning.Chest.GILDED);
		double[] before = odds.clone();
		double[] out = RollOdds.adjustOdds(odds, 25.0);
		Assert.assertArrayEquals("adjustOdds mutated Tuning.CHEST_ODDS", before, odds, 0);
		Assert.assertNotSame(odds, out);
	}

	/**
	 * A Common share of 0 would make the rarity walk's index-0 fallback unreachable and
	 * the shift is clamped for exactly that reason. Pinned at an absurd bonus so the
	 * clamp is what is being measured, not the tuning.
	 */
	@Test
	public void adjustOddsNeverDrivesCommonBelowOne()
	{
		double[] out = RollOdds.adjustOdds(Tuning.CHEST_ODDS.get(Tuning.Chest.ORNATE), 500.0);
		Assert.assertEquals(1.0, out[0], EPS);
		double total = 0;
		for (double v : out)
		{
			total += v;
		}
		double before = 0;
		for (double v : Tuning.CHEST_ODDS.get(Tuning.Chest.ORNATE))
		{
			before += v;
		}
		Assert.assertEquals("pity redistributes mass, it never creates it", before, total, EPS);
	}

	@Test
	public void adjustOddsIsANoOpWithoutPity()
	{
		double[] odds = Tuning.CHEST_ODDS.get(Tuning.Chest.RUSTY);
		Assert.assertArrayEquals(odds, RollOdds.adjustOdds(odds, 0), 0);
	}

	// --- the lean itself ---

	/**
	 * The whole contract of the feature in one assertion: strictly less than wieldable
	 * gear (or there is no lean) and strictly more than zero (or the headroom band is
	 * dead, and it is deliberate aspirational slack — see Tuning.ROLL_TIER_HEADROOM).
	 */
	@Test
	public void leanWeightIsAStrictLeanThatNeverClosesTheHeadroom()
	{
		Assert.assertEquals(1.0, RollOdds.leanWeight(true), 0);
		Assert.assertTrue("headroom gear must stay possible", RollOdds.leanWeight(false) > 0);
		Assert.assertTrue("headroom gear must be rarer than wieldable gear",
			RollOdds.leanWeight(false) < RollOdds.leanWeight(true));
		Assert.assertTrue("HOUSE_LEAN_HEADROOM_WEIGHT must stay in (0,1)",
			Tuning.HOUSE_LEAN_HEADROOM_WEIGHT > 0 && Tuning.HOUSE_LEAN_HEADROOM_WEIGHT < 1);
	}

	@Test
	public void normalizeSumsToOneAndSurvivesAnAllZeroVector()
	{
		double[] out = RollOdds.normalize(new double[]{55, 26, 12, 5, 2});
		double total = 0;
		for (double v : out)
		{
			total += v;
		}
		Assert.assertEquals(1.0, total, EPS);
		Assert.assertEquals(0.55, out[0], EPS);
		// an empty candidate list must read as "no odds", not as a divide by zero
		Assert.assertArrayEquals(new double[]{0, 0, 0}, RollOdds.normalize(new double[]{0, 0, 0}), 0);
		Assert.assertEquals(0, RollOdds.normalize(new double[0]).length);
	}

	/**
	 * The draw pickLeaned actually performs. Boundaries are half-open on the low side
	 * (roll == a boundary lands on the NEXT bucket), which is what makes the widths add
	 * up to the total exactly once.
	 */
	@Test
	public void weightedIndexWalksTheCumulativeWeights()
	{
		double w = Tuning.HOUSE_LEAN_HEADROOM_WEIGHT;
		double[] weights = {1.0, 1.0, w};
		Assert.assertEquals(0, RollOdds.weightedIndex(0.0, weights));
		Assert.assertEquals(0, RollOdds.weightedIndex(0.999, weights));
		Assert.assertEquals(1, RollOdds.weightedIndex(1.0, weights));
		Assert.assertEquals(1, RollOdds.weightedIndex(1.999, weights));
		Assert.assertEquals(2, RollOdds.weightedIndex(2.0, weights));
		Assert.assertEquals(2, RollOdds.weightedIndex(2 + w - 1e-9, weights));
	}

	/**
	 * A roll of exactly the total (or a rounding crumb past it) must land on the last
	 * bucket rather than fall off the end — the headroom card is usually last, so the
	 * fallback has to be the generous one, not an exception.
	 */
	@Test
	public void weightedIndexClampsInsteadOfFallingOffTheEnd()
	{
		double[] weights = {1.0, 1.0, Tuning.HOUSE_LEAN_HEADROOM_WEIGHT};
		Assert.assertEquals(2, RollOdds.weightedIndex(2 + Tuning.HOUSE_LEAN_HEADROOM_WEIGHT, weights));
		Assert.assertEquals(2, RollOdds.weightedIndex(Double.MAX_VALUE, weights));
	}

	/**
	 * Every index must stay drawable, headroom included. Sweeping the roll space is the
	 * strongest form of "never impossible" available without an RNG.
	 */
	@Test
	public void everyBucketIncludingTheHeadroomIsReachableAcrossTheRollSpace()
	{
		double w = Tuning.HOUSE_LEAN_HEADROOM_WEIGHT;
		double[] weights = {1.0, 1.0, w};
		double total = 2 + w;
		int[] hits = new int[3];
		int samples = 10_000;
		for (int i = 0; i < samples; i++)
		{
			hits[RollOdds.weightedIndex((i + 0.5) / samples * total, weights)]++;
		}
		Assert.assertTrue("the headroom bucket was never drawn", hits[2] > 0);
		// the sweep is uniform, so hit counts are the probabilities back again
		Assert.assertEquals(1 / total, (double) hits[0] / samples, 1e-3);
		Assert.assertEquals(w / total, (double) hits[2] / samples, 1e-3);
		Assert.assertTrue("headroom must be drawn less often than wieldable gear",
			hits[2] < hits[0]);
	}

	// --- tier shares ---

	/**
	 * Hand-computed: two wieldable rune cards at weight 1 each and one dragon card in
	 * the headroom at weight w, over a total of 2 + w.
	 */
	@Test
	public void tierSharesReproduceAHandComputedDistribution()
	{
		List<CardDefinition> candidates = Arrays.asList(
			card(1, "rune", Rarity.COMMON),
			card(2, "rune", Rarity.COMMON),
			card(3, "dragon", Rarity.COMMON));
		double w = Tuning.HOUSE_LEAN_HEADROOM_WEIGHT;
		double total = 2 + w;
		Map<RollOdds.TierBand, Double> shares =
			RollOdds.tierShares(candidates, new boolean[]{true, true, false}, true);
		Assert.assertEquals(2, shares.size());
		Assert.assertEquals(2 / total, shareOf(shares, "rune", true), EPS);
		Assert.assertEquals(w / total, shareOf(shares, "dragon", false), EPS);
	}

	/**
	 * The headline claim the disclosure makes: dragon gets rarer than a uniform draw
	 * would give it, but never reaches zero.
	 */
	@Test
	public void theHeadroomTierGetsRarerButNeverImpossible()
	{
		List<CardDefinition> candidates = Arrays.asList(
			card(1, "rune", Rarity.COMMON),
			card(2, "rune", Rarity.COMMON),
			card(3, "dragon", Rarity.COMMON));
		boolean[] flags = {true, true, false};
		double leaned = shareOf(RollOdds.tierShares(candidates, flags, true), "dragon", false);
		double uniform = shareOf(RollOdds.tierShares(candidates, flags, false), "dragon", false);
		Assert.assertEquals("uniform draw is 1 in 3", 1.0 / 3, uniform, EPS);
		Assert.assertTrue("the lean must actually lean", leaned < uniform);
		Assert.assertTrue("the lean must never close the band", leaned > 0);
	}

	/**
	 * Why pickLeaned may short-circuit to rng.pick when every candidate sits in one
	 * band: a flat weight vector normalizes to the uniform draw exactly, so skipping
	 * the weighted walk is a substitution, not an approximation — which is what keeps
	 * the fixed-seed roll tests from moving.
	 */
	@Test
	public void aFlatBandNormalizesExactlyLikeAUniformDraw()
	{
		List<CardDefinition> candidates = Arrays.asList(
			card(1, "rune", Rarity.COMMON),
			card(2, "dragon", Rarity.COMMON),
			card(3, "adamant", Rarity.COMMON));
		boolean[] allOut = {false, false, false};
		Map<RollOdds.TierBand, Double> leaned = RollOdds.tierShares(candidates, allOut, true);
		Map<RollOdds.TierBand, Double> uniform = RollOdds.tierShares(candidates, allOut, false);
		Assert.assertEquals(uniform.keySet(), leaned.keySet());
		for (RollOdds.TierBand band : uniform.keySet())
		{
			Assert.assertEquals(band.getTierKey(), uniform.get(band), leaned.get(band), EPS);
			Assert.assertEquals(1.0 / 3, leaned.get(band), EPS);
		}
	}

	/**
	 * Untiered gear is gate-EXEMPT, not gate-passing: ChestService.isReachable returns
	 * true for a null tierKey, so it always carries full weight and must never be
	 * folded into the "wieldable" ladder rows.
	 */
	@Test
	public void untieredCardsGroupUnderTheUntieredKeyAtFullWeight()
	{
		List<CardDefinition> candidates = Arrays.asList(
			card(1, null, Rarity.COMMON),
			card(2, null, Rarity.COMMON),
			card(3, "dragon", Rarity.COMMON));
		double w = Tuning.HOUSE_LEAN_HEADROOM_WEIGHT;
		Map<RollOdds.TierBand, Double> shares =
			RollOdds.tierShares(candidates, new boolean[]{true, true, false}, true);
		Assert.assertEquals(2 / (2 + w), shareOf(shares, RollOdds.UNTIERED, true), EPS);
		Assert.assertEquals(0, shareOf(shares, RollOdds.UNTIERED, false), EPS);
	}

	/**
	 * One tier legitimately straddles both bands: ChestService applies reqDefence to
	 * BODY only, so hardleather chaps can be wieldable while the body is not. The
	 * disclosure has to be able to say that rather than pick a side.
	 */
	@Test
	public void oneTierCanAppearInBothBands()
	{
		List<CardDefinition> candidates = Arrays.asList(
			card(1, "hardleather", Rarity.COMMON),
			card(2, "hardleather", Rarity.COMMON));
		double w = Tuning.HOUSE_LEAN_HEADROOM_WEIGHT;
		Map<RollOdds.TierBand, Double> shares =
			RollOdds.tierShares(candidates, new boolean[]{true, false}, true);
		Assert.assertEquals(2, shares.size());
		Assert.assertEquals(1 / (1 + w), shareOf(shares, "hardleather", true), EPS);
		Assert.assertEquals(w / (1 + w), shareOf(shares, "hardleather", false), EPS);
	}

	/** Whatever the mix, the panel's rows must add up to one card. */
	@Test
	public void tierSharesAlwaysTotalOne()
	{
		List<CardDefinition> candidates = new ArrayList<>();
		String[] tiers = {"bronze", "iron", null, "rune", "dragon", "mystic", null, "black_dhide"};
		boolean[] flags = new boolean[tiers.length];
		for (int i = 0; i < tiers.length; i++)
		{
			candidates.add(card(i + 1, tiers[i], Rarity.COMMON));
			flags[i] = i % 3 != 0;
		}
		for (boolean leaned : new boolean[]{true, false})
		{
			double total = 0;
			for (double share : RollOdds.tierShares(candidates, flags, leaned).values())
			{
				total += share;
			}
			Assert.assertEquals("leaned=" + leaned, 1.0, total, EPS);
		}
	}

	/** An empty bucket must read as "no rows", not throw — oddsFor walks every rarity. */
	@Test
	public void anEmptyCandidateListYieldsNoRows()
	{
		Assert.assertTrue(RollOdds.tierShares(new ArrayList<>(), new boolean[0], true).isEmpty());
	}
}

package com.gachaman.service;

import com.gachaman.*;
import com.gachaman.model.*;
import java.util.*;
import org.junit.*;

import static com.gachaman.service.LoadoutFixture.*;

/**
 * The unassign guard: a card cannot leave a loadout slot while the item it
 * unlocks is still on the player's back.
 *
 * <p>The hole it closes exists with or without the Toll. Unassigning is the
 * only way to lose a permission you are in the middle of exercising, and
 * nothing re-reads equipment when the loadout changes — so before the guard a
 * player could clear a slot, keep wearing the item, and only be caught out
 * whenever some unrelated container change forced a permission rebuild.
 *
 * <p>The plugin may not take the gear off for them, ever, so every test here
 * asserts a REFUSAL and an unchanged loadout, never an unequip.
 */
public class UnassignGuardTest
{
	private GachaStateService stateService;
	private LoadoutFixture.Cards cards;

	@Before
	public void setUp()
	{
		stateService = inMemoryStateService();
		cards = new LoadoutFixture.Cards();
		deedEverySlot(stateService);
	}

	private LoadoutService serviceWearing(boolean oneCardPerSlot, int... wornItemIds)
	{
		GachamanConfig config = config(oneCardPerSlot);
		PermissionService permissions =
			new PermissionService(stateService, cards, null, config);
		Set<Integer> worn = new HashSet<>();
		for (int id : wornItemIds)
		{
			worn.add(id);
		}
		return service(stateService, cards, permissions, config, worn);
	}

	private String inLoadout(GearSlot slot)
	{
		return stateService.get().getLoadout().get(slot.name());
	}

	/**
	 * THE case that proves isForbidden would have been the wrong call.
	 *
	 * <p>A dragon hologram in the weapon slot is what permits the dragon
	 * scimitar, and isForbidden(dragon scimitar) answers FALSE right now —
	 * precisely because the hologram is still assigned. A guard built on it
	 * would wave this through and look like it worked.
	 */
	@Test
	public void aHologramRefusesWhileAnythingOfItsTierIsWorn()
	{
		OwnedCard holo = hologram(GearSlot.WEAPON, "dragon");
		giveCards(stateService, holo);
		putInLoadout(stateService, GearSlot.WEAPON, holo);

		LoadoutService loadout = serviceWearing(true, itemId(GearSlot.WEAPON, "dragon"));
		PermissionService permissions =
			new PermissionService(stateService, cards, null, config(true));
		permissions.refresh();
		Assert.assertFalse("isForbidden answers false here, which is the whole point",
			permissions.isForbidden(itemId(GearSlot.WEAPON, "dragon")));

		Assert.assertFalse("wearing a dragon weapon must block the hologram leaving",
			loadout.unassign(GearSlot.WEAPON));
		Assert.assertEquals("a refusal changes nothing", holo.getUuid(),
			inLoadout(GearSlot.WEAPON));
	}

	/** A hologram grants its tier only in the slot it sits in, so it may leave others. */
	@Test
	public void aHologramInAnotherSlotIsNotBlockedByWeaponryOfItsTier()
	{
		OwnedCard holo = hologram(GearSlot.BODY, "dragon");
		giveCards(stateService, holo);
		putInLoadout(stateService, GearSlot.BODY, holo);

		LoadoutService loadout = serviceWearing(true, itemId(GearSlot.WEAPON, "dragon"));
		Assert.assertTrue("a dragon weapon is not what the BODY hologram is permitting",
			loadout.unassign(GearSlot.BODY));
		Assert.assertNull(inLoadout(GearSlot.BODY));
	}

	/**
	 * A shiny unlocks its whole family DOWN the ladder, so the worn item that
	 * blocks it need not be the one the card is named for.
	 */
	@Test
	public void aShinyRefusesWhileALowerTierItUnlocksIsWorn()
	{
		OwnedCard shiny = shiny(GearSlot.WEAPON, "rune");
		giveCards(stateService, shiny);
		putInLoadout(stateService, GearSlot.WEAPON, shiny);

		LoadoutService loadout = serviceWearing(true, itemId(GearSlot.WEAPON, "adamant"));
		Assert.assertFalse("a shiny rune card is what permits the adamant scimitar",
			loadout.unassign(GearSlot.WEAPON));
		Assert.assertEquals(shiny.getUuid(), inLoadout(GearSlot.WEAPON));
	}

	/** The same card unshiny permits only its own tier, so adamant does not hold it. */
	@Test
	public void aPlainCardIsHeldOnlyByItsOwnTier()
	{
		OwnedCard plain = plain(GearSlot.WEAPON, "rune");
		giveCards(stateService, plain);
		putInLoadout(stateService, GearSlot.WEAPON, plain);

		Assert.assertTrue("a plain rune card never permitted the adamant scimitar",
			serviceWearing(true, itemId(GearSlot.WEAPON, "adamant"))
				.unassign(GearSlot.WEAPON));

		putInLoadout(stateService, GearSlot.WEAPON, plain);
		Assert.assertFalse("its own tier does hold it",
			serviceWearing(true, itemId(GearSlot.WEAPON, "rune"))
				.unassign(GearSlot.WEAPON));
	}

	/**
	 * Cards merge item variants — kitted, ornamented, charged — and the guard
	 * has to see all of them. A canonical-id-only comparison would let an
	 * ornament kit stay on the player's back.
	 */
	@Test
	public void aMergedVariantOfTheSameCardHoldsItToo()
	{
		OwnedCard plain = plain(GearSlot.WEAPON, "rune");
		giveCards(stateService, plain);
		putInLoadout(stateService, GearSlot.WEAPON, plain);

		Assert.assertFalse("the ornamented variant is the same card's permission",
			serviceWearing(true, variantItemId(GearSlot.WEAPON, "rune"))
				.unassign(GearSlot.WEAPON));
	}

	/**
	 * With one-card-per-slot OFF, PermissionService.rebuildOwnershipOnly grants
	 * from OWNERSHIP alone: the loadout permits nothing, so clearing a slot
	 * takes nothing away and a refusal would be pure obstruction.
	 */
	@Test
	public void oneCardPerSlotOffNeverRefusesWhateverIsWorn()
	{
		OwnedCard holo = hologram(GearSlot.WEAPON, "dragon");
		OwnedCard shiny = shiny(GearSlot.BODY, "rune");
		giveCards(stateService, holo, shiny);
		putInLoadout(stateService, GearSlot.WEAPON, holo);
		putInLoadout(stateService, GearSlot.BODY, shiny);

		LoadoutService loadout = serviceWearing(false,
			itemId(GearSlot.WEAPON, "dragon"), itemId(GearSlot.BODY, "adamant"));
		Assert.assertTrue(loadout.unassign(GearSlot.WEAPON));
		Assert.assertTrue(loadout.unassign(GearSlot.BODY));
		Assert.assertTrue(stateService.get().getLoadout().isEmpty());
	}

	/** Nothing on the player at all: every slot clears. */
	@Test
	public void anEmptyEquipmentContainerNeverRefuses()
	{
		OwnedCard holo = hologram(GearSlot.WEAPON, "dragon");
		giveCards(stateService, holo);
		putInLoadout(stateService, GearSlot.WEAPON, holo);

		Assert.assertTrue(serviceWearing(true).unassign(GearSlot.WEAPON));
		Assert.assertNull(inLoadout(GearSlot.WEAPON));
	}

	/** Gear in OTHER slots is somebody else's permission and holds nothing here. */
	@Test
	public void unrelatedWornGearNeverRefuses()
	{
		OwnedCard weapon = plain(GearSlot.WEAPON, "rune");
		giveCards(stateService, weapon);
		putInLoadout(stateService, GearSlot.WEAPON, weapon);

		Assert.assertTrue(serviceWearing(true,
			itemId(GearSlot.BODY, "rune"), itemId(GearSlot.LEGS, "dragon"),
			itemId(GearSlot.AMMO, "adamant")).unassign(GearSlot.WEAPON));
		Assert.assertNull(inLoadout(GearSlot.WEAPON));
	}

	/** An already-empty slot is not a refusal — there is nothing to explain. */
	@Test
	public void anEmptySlotReportsSuccess()
	{
		Assert.assertTrue(serviceWearing(true, itemId(GearSlot.WEAPON, "dragon"))
			.unassign(GearSlot.WEAPON));
	}

	/** A null slot is a caller bug, not a guard refusal: no message is owed. */
	@Test
	public void aNullSlotReportsSuccess()
	{
		Assert.assertTrue(serviceWearing(true).unassign(null));
	}

	/** Take the item off and the same call goes through — the guard is a gate, not a lock. */
	@Test
	public void takingTheItemOffLetsTheCardLeave()
	{
		OwnedCard holo = hologram(GearSlot.WEAPON, "dragon");
		giveCards(stateService, holo);
		putInLoadout(stateService, GearSlot.WEAPON, holo);

		Assert.assertFalse(serviceWearing(true, itemId(GearSlot.WEAPON, "dragon"))
			.unassign(GearSlot.WEAPON));
		Assert.assertTrue(serviceWearing(true).unassign(GearSlot.WEAPON));
		Assert.assertNull(inLoadout(GearSlot.WEAPON));
	}

	/** Every slot behaves the same way — the rule is general, not weapon-shaped. */
	@Test
	public void theGuardHoldsInEverySlot()
	{
		for (GearSlot slot : GearSlot.values())
		{
			GachaStateService state = inMemoryStateService();
			deedEverySlot(state);
			OwnedCard card = plain(slot, "rune");
			giveCards(state, card);
			putInLoadout(state, slot, card);

			GachamanConfig config = config(true);
			PermissionService permissions = new PermissionService(state, cards, null, config);
			LoadoutService loadout = service(state, cards, permissions, config,
				Collections.singleton(itemId(slot, "rune")));
			Assert.assertFalse(slot + " must refuse while its own gear is worn",
				loadout.unassign(slot));
			Assert.assertEquals(slot + " must keep its card", card.getUuid(),
				state.get().getLoadout().get(slot.name()));
		}
	}

	/**
	 * A KNOWN GAP, pinned so it cannot be mistaken for closed.
	 *
	 * <p>The guard covers {@link LoadoutService#unassign} because that is what
	 * was commissioned. Two other paths vacate a slot without going through
	 * it, and both leave the same worn item unpermitted:
	 *
	 * <ul>
	 * <li>MOVING a hologram — assign() clears its previous slot first, since a
	 * hologram may occupy only one.
	 * <li>OVERWRITING a slot — assign() replaces whatever was there, and the
	 * replacement may not permit what the old card did.
	 * </ul>
	 *
	 * <p>Closing them means guarding assign() as well, which changes the
	 * contract of a method whose other caller (the chatbox card search)
	 * discards its result and lives outside this change's file group. That is
	 * an owner's call, not this test's — so the current behaviour is asserted
	 * exactly, and this test flips the day it is made.
	 */
	@Test
	public void knownGap_movingOrOverwritingStillVacatesASlotUnguarded()
	{
		OwnedCard holo = hologram(GearSlot.WEAPON, "dragon");
		OwnedCard body = plain(GearSlot.BODY, "rune");
		giveCards(stateService, holo, body);
		putInLoadout(stateService, GearSlot.WEAPON, holo);

		LoadoutService loadout = serviceWearing(true, itemId(GearSlot.WEAPON, "dragon"));
		Assert.assertFalse("unassign is guarded", loadout.unassign(GearSlot.WEAPON));
		Assert.assertTrue("but moving the same hologram elsewhere is not",
			loadout.assign(GearSlot.BODY, holo.getUuid()));
		Assert.assertNull("...and the weapon slot is empty with the item still worn",
			inLoadout(GearSlot.WEAPON));
	}
}

package com.gachaman.service;

import com.gachaman.*;
import com.gachaman.model.*;
import com.gachaman.persist.*;
import com.google.gson.*;
import org.junit.*;

/**
 * The wheel naming a weapon category alongside the style: that it happens in the
 * SAME write as the style, that it is drawn from the per-player RNG and never a
 * seeded one, and that the forced-style overload the Consignment needs commits
 * the same kind of roll the ordinary wheel does.
 *
 * <p>Real state, a real {@link WeaponTypeService} over the shipped taxonomy, and
 * a real {@link StyleService}. The only stub is the one collaborator that would
 * need a live client (the compliance service's chat/quest arms, which a null
 * client skips), because the thing under test is a persistence ordering and a
 * stubbed roll could not observe it.
 */
public class StyleWeaponRollTest
{
	/**
	 * Fixed so the ordinary wheel is predictable from a bare
	 * {@code new GachaRng(SEED)} — which is itself an invariant one of these tests
	 * pins, since ConsignmentServiceTest predicts the wheel exactly that way.
	 */
	private static final long SEED = 7L;

	private GachaStateService stateService;
	private GachaRng rng;
	private WeaponTypeService weaponTypes;
	private StyleService styleService;

	// --- Harness --------------------------------------------------------------

	private static GachaStateService inMemoryStateService()
	{
		StateStore store = new StateStore(null, null, null)
		{
			@Override
			public void save(GachaState state)
			{
			}

			@Override
			public void save(GachaState state, boolean flushDiskNow)
			{
			}

			@Override
			public GachaState load()
			{
				return null; // forces a fresh in-memory state
			}
		};
		GachaStateService service = new GachaStateService(store);
		service.load(3);
		return service;
	}

	/**
	 * A taxonomy that can name nothing, standing in for the one failure the
	 * resource can actually have: the JSON missing or unparseable, which leaves
	 * every pool empty and {@code roll} returning null for every style.
	 */
	private static class NamesNothing extends WeaponTypeService
	{
		NamesNothing(GachaRng rng)
		{
			super(null, new Gson(), rng);
		}

		@Override
		public WeaponTypeService.WeaponType roll(AttackStyle style)
		{
			return null;
		}
	}

	/** Counts state writes; every real mutate notifies exactly once. */
	private static class WriteCounter implements GachaStateService.Listener
	{
		private int writes;

		@Override
		public void onStateChanged(GachaState newState)
		{
			writes++;
		}
	}

	/**
	 * Everything goes through {@link StyleFixture}, which is the harness every
	 * other StyleService test builds on — so a change that breaks the shared
	 * fixture fails here first, where the wheel itself is what is being asserted.
	 * One rng is shared with the taxonomy exactly as Guice shares the singleton.
	 */
	private StyleService serviceOver(WeaponTypeService types)
	{
		CreditSink creditSink = new CreditSink(stateService);
		ComplianceService compliance = new ComplianceService(stateService, creditSink, null, null);
		return StyleFixture.styleService(stateService, compliance, new CeremonyBus(), rng, types);
	}

	/** The fixture's own four-argument form: it builds the taxonomy itself. */
	private StyleService serviceOverTheShippedTaxonomy()
	{
		CreditSink creditSink = new CreditSink(stateService);
		ComplianceService compliance = new ComplianceService(stateService, creditSink, null, null);
		return StyleFixture.styleService(stateService, compliance, new CeremonyBus(), rng);
	}

	@Before
	public void setUp()
	{
		stateService = inMemoryStateService();
		rng = new GachaRng(SEED);
		weaponTypes = new WeaponTypeService(null, new Gson(), rng);
		styleService = serviceOver(weaponTypes);
	}

	private GachaState state()
	{
		return stateService.get();
	}

	/** An account past its first roll, so nothing under test is the firstEver path. */
	private void established()
	{
		stateService.mutate(s -> s.withAllowedStyle(AttackStyle.MELEE.name())
			.withPreferredWeaponType(null)
			.withFirstColoursChestOwed(false));
	}

	// --- The same-write requirement -------------------------------------------

	/**
	 * The requirement that a second write would break, and the only one that can
	 * be pinned at all: everything else about "the same mutate" is prose. A style
	 * committed in one write and a preference in another leaves a window where the
	 * new style is live under the previous cycle's category, and a crash there
	 * ships a preference the player can never satisfy.
	 */
	@Test
	public void aRollIsExactlyOneWriteToState()
	{
		established();
		WriteCounter counter = new WriteCounter();
		stateService.addListener(counter);

		StyleService.StyleRollResult result = styleService.roll(1);

		Assert.assertNotNull(result);
		Assert.assertEquals("the style and everything the wheel names beside it must land"
			+ " in ONE mutate — a second write is a window a crash can land in",
			1, counter.writes);
		Assert.assertNotNull("the shipped taxonomy must name something", result.getWeaponType());
		Assert.assertEquals("the result must announce what was persisted",
			result.getWeaponType().getKey(), state().getPreferredWeaponType());
	}

	/**
	 * The write is unconditional, null included. A guard that only wrote a
	 * category when it had one would leave the LAST cycle's preference live
	 * against a style it was never rolled for — the bonus would then pay on a
	 * weapon this cycle's wheel never named.
	 */
	@Test
	public void aRollThatNamesNothingCLEARSTheStaleCategory()
	{
		established();
		styleService.roll(1);
		String stale = state().getPreferredWeaponType();
		Assert.assertNotNull("precondition: a preference is live", stale);

		StyleService.StyleRollResult result = serviceOver(new NamesNothing(rng)).roll(2);

		Assert.assertNull("a roll that names no category must clear the previous one,"
			+ " never inherit it", state().getPreferredWeaponType());
		Assert.assertNull("and must say so in the result", result.getWeaponType());
	}

	// --- What gets named ------------------------------------------------------

	/**
	 * Over many rolls: the category is always one the rolled style's own wheel is
	 * allowed to name, and it always resolves back out of a save. The persisted
	 * form is a String, so a key that no longer resolves is indistinguishable from
	 * no preference at all — silently, and for the whole cycle.
	 */
	@Test
	public void theNamedCategoryAlwaysBelongsToTheRolledStyleAndSurvivesPersistence()
	{
		for (int seed = 0; seed < 300; seed++)
		{
			stateService = inMemoryStateService();
			rng = new GachaRng(seed);
			weaponTypes = new WeaponTypeService(null, new Gson(), rng);
			established();

			StyleService.StyleRollResult result = serviceOver(weaponTypes).roll(1);
			WeaponTypeService.WeaponType named = result.getWeaponType();

			Assert.assertNotNull("seed " + seed, named);
			Assert.assertTrue("the wheel may only name a category it is allowed to offer"
				+ " for the style it rolled (seed " + seed + ")",
				weaponTypes.pool(result.getRolled()).contains(named));
			Assert.assertTrue(named.isOfferable());

			// the round trip a save actually makes: key out, type back in
			String persisted = state().getPreferredWeaponType();
			Assert.assertEquals(named.getKey(), persisted);
			Assert.assertSame("a persisted key must resolve back through the taxonomy,"
				+ " or the whole cycle silently has no preference",
				named, weaponTypes.byKey(persisted));
			Assert.assertNotNull("and must be renderable without showing the key",
				weaponTypes.displayName(persisted));
		}
	}

	/**
	 * The style is still the FIRST number off the stream. Drawing the category
	 * first would shift it, and ConsignmentServiceTest predicts the ordinary wheel
	 * with a bare {@code new GachaRng(SEED).nextInt(3)} on an untouched copy of the
	 * seed — a prediction that would silently start naming the wrong style.
	 */
	@Test
	public void theStyleIsDrawnBeforeTheCategory()
	{
		established();
		AttackStyle predicted =
			AttackStyle.values()[new GachaRng(SEED).nextInt(AttackStyle.values().length)];

		Assert.assertEquals(predicted, styleService.roll(1).getRolled());
	}

	/** The bare overload is the forced one with nothing forced, and nothing else. */
	@Test
	public void rollWithoutAStyleIsRollWithANullStyle()
	{
		established();
		StyleService.StyleRollResult bare = styleService.roll(1);

		stateService = inMemoryStateService();
		rng = new GachaRng(SEED);
		established();
		StyleService.StyleRollResult explicit = serviceOverTheShippedTaxonomy().roll(1, null);

		Assert.assertEquals(bare.getRolled(), explicit.getRolled());
		Assert.assertEquals(bare.getWeaponType().getKey(), explicit.getWeaponType().getKey());
	}

	// --- The Consignment's deferred path --------------------------------------

	/**
	 * A forced roll is a whole roll: the house's style, a category rolled FOR that
	 * style, the cycle restarted and the clock stamped. This is the property that
	 * makes routing the Consignment through here worth the overload — a
	 * hand-written commit over there would set the first three and drop the fourth.
	 */
	@Test
	public void aForcedRollCommitsTheHousesStyleAndNamesACategoryForIt()
	{
		for (AttackStyle forced : AttackStyle.values())
		{
			stateService = inMemoryStateService();
			rng = new GachaRng(SEED);
			weaponTypes = new WeaponTypeService(null, new Gson(), rng);
			established();
			stateService.mutate(s -> s.withCycleProgress(4));

			StyleService.StyleRollResult result = serviceOver(weaponTypes).roll(1, forced);

			Assert.assertEquals(forced, result.getRolled());
			Assert.assertEquals(forced.name(), state().getAllowedStyle());
			Assert.assertTrue("the category must be rolled for the style the HOUSE named,"
				+ " not for the one the wheel would have",
				weaponTypes.pool(forced).contains(result.getWeaponType()));
			Assert.assertEquals(forced.name(), state().getAllowedStyle());
			Assert.assertEquals("a forced roll restarts the cycle like any other",
				0.0, state().getCycleProgress(), 0.0001);
			Assert.assertEquals(Tuning.CYCLE_TASKS, state().getCycleTarget());
			Assert.assertNotEquals(0L, state().getStyleRolledAtMs());
		}
	}

	/**
	 * The forced style is taken even when the wheel disagreed — the house names
	 * it, so a forced roll that quietly spun anyway would be selling the player a
	 * deal it does not honour.
	 */
	@Test
	public void aForcedRollDoesNotSpinTheWheel()
	{
		established();
		AttackStyle wheelWould =
			AttackStyle.values()[new GachaRng(SEED).nextInt(AttackStyle.values().length)];
		AttackStyle other = AttackStyle.values()[(wheelWould.ordinal() + 1) % 3];

		Assert.assertEquals(other, styleService.roll(1, other).getRolled());
		Assert.assertEquals(other.name(), state().getAllowedStyle());
	}

	// --- firstEver ------------------------------------------------------------

	/**
	 * The free First Colours chest is armed off the absent PREVIOUS style, not off
	 * the presence of a draw, so it survives the forced overload. It cannot happen
	 * in practice — ConsignmentService refuses to offer at all while
	 * {@code allowedStyle} is null, since an account with no album cannot be worst
	 * dressed — but the discriminator is what that exclusion is built on, and it is
	 * cheaper to pin it here than to discover it moved.
	 */
	@Test
	public void theFirstEverRollArmsTheFreeChestThroughEitherOverload()
	{
		Assert.assertNull("precondition: a fresh profile", state().getAllowedStyle());
		StyleService.StyleRollResult first = styleService.roll(1);
		Assert.assertNull("nothing preceded it", first.getPrevious());
		Assert.assertTrue(state().isFirstColoursChestOwed());

		stateService = inMemoryStateService();
		rng = new GachaRng(SEED);
		StyleService.StyleRollResult forced =
			serviceOverTheShippedTaxonomy().roll(1, AttackStyle.MAGIC);
		Assert.assertNull(forced.getPrevious());
		Assert.assertTrue("firstEver is the absent previous style, not the absent draw",
			state().isFirstColoursChestOwed());

		// and a SECOND roll never re-arms it, forced or not
		stateService.mutate(s -> s.withFirstColoursChestOwed(false));
		serviceOver(weaponTypes).roll(2);
		Assert.assertFalse(state().isFirstColoursChestOwed());
	}

	/** A roll on unloaded state is a no-op that returns null, both overloads. */
	@Test
	public void anUnloadedProfileRollsNothing()
	{
		stateService.unload();
		Assert.assertNull(styleService.roll(1));
		Assert.assertNull(styleService.roll(1, AttackStyle.RANGED));
	}
}

package com.gachaman.service;

import com.gachaman.*;
import com.gachaman.model.*;
import java.util.*;
import org.junit.*;

public class FirstsServiceTest
{
	@Test
	public void payoutsCoverEveryStampAndSumJustUnder500()
	{
		int sum = 0;
		for (FirstStamp stamp : FirstStamp.values())
		{
			Integer gc = Tuning.FIRSTS_GC.get(stamp);
			Assert.assertNotNull("missing payout for " + stamp, gc);
			Assert.assertTrue(stamp + " must pay something", gc > 0);
			sum += gc;
		}
		Assert.assertEquals(495, sum);
		Assert.assertTrue("total must stay under one Battered chest",
			sum < Tuning.CHEST_PRICE_GC.get(Tuning.Chest.BATTERED));
	}

	@Test
	public void everyStampHasNameAndExplainer()
	{
		for (FirstStamp stamp : FirstStamp.values())
		{
			Assert.assertFalse(stamp + " display name blank", stamp.getDisplayName().isBlank());
			Assert.assertFalse(stamp + " explainer blank", stamp.getExplainer().isBlank());
		}
	}

	@Test
	public void alreadyClaimedNullSetMeansUnclaimed()
	{
		Assert.assertFalse(FirstsService.alreadyClaimed(null, FirstStamp.FIRST_KILL));
		Assert.assertFalse(FirstsService.alreadyClaimed(Set.of(), FirstStamp.FIRST_KILL));
		Assert.assertTrue(FirstsService.alreadyClaimed(Set.of("FIRST_KILL"), FirstStamp.FIRST_KILL));
		Assert.assertFalse(FirstsService.alreadyClaimed(Set.of("FIRST_KILL"), FirstStamp.FIRST_TASK));
	}

	@Test
	public void stampsForSlotsDetectsRarityVariantAndDupes()
	{
		List<ChestService.RolledSlot> slots = new ArrayList<>();
		// plain common non-dupe: nothing
		slots.add(new ChestService.RolledSlot(Rarity.COMMON, 1, null, Variant.NORMAL, false, false, false));
		Assert.assertTrue(FirstsService.stampsForSlots(slots).isEmpty());

		slots.clear();
		slots.add(new ChestService.RolledSlot(Rarity.UNCOMMON, 2, null, Variant.NORMAL, false, false, false));
		slots.add(new ChestService.RolledSlot(Rarity.RARE, 3, null, Variant.NORMAL, true, false, false));
		slots.add(new ChestService.RolledSlot(Rarity.LEGENDARY, 4, null, Variant.SHINY, false, false, false));
		List<FirstStamp> stamps = FirstsService.stampsForSlots(slots);
		Assert.assertTrue(stamps.contains(FirstStamp.FIRST_UNCOMMON));
		Assert.assertTrue(stamps.contains(FirstStamp.FIRST_RARE));
		Assert.assertTrue("LEGENDARY counts as Epic-or-better", stamps.contains(FirstStamp.FIRST_EPIC));
		Assert.assertTrue(stamps.contains(FirstStamp.FIRST_SHINY));
		Assert.assertTrue(stamps.contains(FirstStamp.FIRST_DUPE));

		// hologram slot (cardId -1) counts for rarity and dupes
		slots.clear();
		slots.add(new ChestService.RolledSlot(Rarity.EPIC, -1, "dragon", Variant.HOLOGRAM, true, false, false));
		stamps = FirstsService.stampsForSlots(slots);
		Assert.assertTrue(stamps.contains(FirstStamp.FIRST_EPIC));
		Assert.assertTrue(stamps.contains(FirstStamp.FIRST_DUPE));
		Assert.assertFalse(stamps.contains(FirstStamp.FIRST_SHINY));

		// no duplicates in the returned list
		slots.clear();
		slots.add(new ChestService.RolledSlot(Rarity.UNCOMMON, 5, null, Variant.NORMAL, false, false, false));
		slots.add(new ChestService.RolledSlot(Rarity.UNCOMMON, 6, null, Variant.NORMAL, false, false, false));
		stamps = FirstsService.stampsForSlots(slots);
		Assert.assertEquals(1, stamps.size());
	}
}

package com.gachaman.service;

import com.gachaman.*;
import com.gachaman.model.*;
import org.junit.*;

/**
 * Pins the claim {@link Tuning#KILL_DIFF_CAP}'s own javadoc makes: that dropping
 * the punching-up ceiling from 2.5 to 1.75 is "a literal no-op for every SOLO
 * kill".
 *
 * <p>This class is named in that javadoc and did not exist until the weapon-type
 * commission landed, so the constant carried a citation to nothing. It is written
 * now because the claim is load-bearing in two directions: it is the reason the
 * owner judged the drop safe for solo play, and it is the reason the drop bites
 * exactly where it was aimed — the party carry.
 *
 * <p><b>Why the cap cannot bind solo.</b> The contract generator never deals a
 * monster above {@code floor(playerCb * difficulty.getCbCapFraction())}, and the
 * largest fraction is INSANE's 1.35. Feed ratio 1.35 through the curve:
 *
 * <pre>
 *   1 + 0.1 + 0.35 * 1.5 + 0.35^2 * 0.75  =  1.716875
 * </pre>
 *
 * which is under 1.75 with 0.033 to spare. The floor in the cap expression only
 * ever pushes the real ratio further below 1.35, so the headroom is a minimum
 * rather than a typical case.
 *
 * <p><b>Why this is a range test and not one arithmetic check.</b> The margin is
 * only 0.033. A retune of KILL_RATIO_LINEAR, KILL_RATIO_QUAD or
 * KILL_DIFF_EQUAL_BONUS could close it without anybody touching KILL_DIFF_CAP
 * itself, and the failure would be silent — solo players would quietly start
 * clamping. Walking every combat level the game has against every difficulty
 * catches that whoever causes it.
 */
public class KillDiffCapTest
{
	/**
	 * The highest monster combat level the generator can deal to this player at
	 * this difficulty, mirroring {@code TaskGenerator.eligibleMonsters}' cap
	 * expression exactly. Duplicated rather than called because that method needs
	 * a monster pool and this test is about the arithmetic, not the table.
	 */
	private static int hardestMonsterFor(int playerCb, TaskDifficulty difficulty)
	{
		return (int) Math.max(2, Math.floor(playerCb * difficulty.getCbCapFraction()));
	}

	@Test
	public void theCapIsANoOpForEverySoloContractTheGeneratorCanDeal()
	{
		// Combat 3 is a fresh account off Tutorial Island; 126 is the maximum.
		for (int playerCb = 3; playerCb <= 126; playerCb++)
		{
			for (TaskDifficulty difficulty : TaskDifficulty.values())
			{
				int npcCb = hardestMonsterFor(playerCb, difficulty);
				double mult = Tuning.killCbMultiplier(playerCb, npcCb);
				Assert.assertTrue(
					"the cap must not bind solo: cb " + playerCb + " vs " + difficulty
						+ " monster cb " + npcCb + " paid " + mult,
					mult < Tuning.KILL_DIFF_CAP);
			}
		}
	}

	/**
	 * The no-op claim is only interesting if the OLD cap was also a no-op over the
	 * same range — otherwise the drop would have changed solo payouts and the
	 * javadoc would be wrong. Pins that nothing solo reaches even 1.75, which is
	 * what makes "2.5 -> 1.75 changed nothing" true rather than merely untested.
	 */
	@Test
	public void theWorstSoloPairingLandsJustUnderTheCapWithKnownHeadroom()
	{
		// INSANE at a high level is the tightest the ratio ever gets: floor()
		// rounding matters least when playerCb is large.
		int playerCb = 100;
		int npcCb = hardestMonsterFor(playerCb, TaskDifficulty.INSANE);
		Assert.assertEquals("INSANE caps at 1.35x the player's level", 135, npcCb);

		double mult = Tuning.killCbMultiplier(playerCb, npcCb);
		Assert.assertEquals("the curve's value at ratio 1.35, as quoted in Tuning's javadoc",
			1.716875, mult, 1e-9);
		Assert.assertTrue("and it must sit under the cap", mult < Tuning.KILL_DIFF_CAP);
	}

	/**
	 * The other half of the owner's reasoning: the drop is NOT a no-op for the
	 * path it was aimed at. A cb-30 member carried in a cb-90 party fights a
	 * monster sized to the party average, so the award — which reads the LOCAL
	 * player's level — sees a ratio the solo generator could never produce.
	 *
	 * <p>Without this the test class would prove only that the cap is harmless,
	 * and a future edit could raise it back to 2.5 with every assertion above
	 * still green.
	 */
	@Test
	public void theCapDoesBindOnAPartyCarry()
	{
		// Party average cb 90, INSANE: monsters up to cb 121. The carried
		// member is cb 30, so the ratio the award sees is ~4.0.
		int carriedCb = 30;
		int partySizedNpcCb = hardestMonsterFor(90, TaskDifficulty.INSANE);

		Assert.assertTrue("the carry must exceed any solo ratio",
			(double) partySizedNpcCb / carriedCb > TaskDifficulty.INSANE.getCbCapFraction());
		Assert.assertEquals("and it must clamp to the cap",
			Tuning.KILL_DIFF_CAP, Tuning.killCbMultiplier(carriedCb, partySizedNpcCb), 1e-9);
	}

	/**
	 * The weapon bonus multiplies the whole award, so it compounds with whatever
	 * the level term paid. This pins the true worst case a single kill can reach,
	 * which is the number {@link Tuning#WEAPON_BONUS_MULT}'s neighbours in
	 * TaskService now quote: the cap, times the bonus.
	 */
	@Test
	public void theWeaponBonusCompoundsOnTopOfTheCapRatherThanBeingSwallowedByIt()
	{
		double clamped = Tuning.killCbMultiplier(30, hardestMonsterFor(90, TaskDifficulty.INSANE));
		Assert.assertEquals(Tuning.KILL_DIFF_CAP, clamped, 1e-9);
		Assert.assertEquals("1.75 x 1.5 — the ceiling the level term and the weapon can reach together",
			2.625, clamped * Tuning.WEAPON_BONUS_MULT, 1e-9);
	}
}

package com.gachaman.service;

import com.gachaman.*;
import com.gachaman.data.*;
import com.gachaman.model.*;
import com.gachaman.persist.*;
import java.util.*;

/**
 * Everything the loadout tests need to run headless: a synthetic card
 * database, an in-memory state service, and a config whose only interesting
 * answer is {@code oneCardPerSlot}.
 *
 * <p>It exists because the guard under test spans three collaborators. The
 * real CardDatabase is built by a chunked scan of the live item cache, so a
 * test cannot have one; RuneLite's Client is an interface far too wide to
 * implement for a single container read, and this repo's suite carries no
 * mocking framework by design. What is left is a small honest fake plus one
 * overridable seam in LoadoutService, which is enough to state every rule.
 */
final class LoadoutFixture
{
	/** Ranks 1..6, low to high — the shiny rule reads "<= my rank". */
	static final List<String> TIERS =
		Arrays.asList("bronze", "iron", "steel", "adamant", "rune", "dragon");

	private LoadoutFixture()
	{
	}

	/**
	 * A card database of eleven slots x six tiers, one family per slot.
	 *
	 * <p>One family per slot mirrors the real builder, which keys families as
	 * "scimitar/WEAPON" — a shiny can only ever reach down its own slot's
	 * ladder, and the guard depends on that: an id match is a slot match.
	 *
	 * <p>Every card carries TWO item ids (its canonical id and that id plus
	 * {@link #VARIANT_STEP}) because real cards merge item variants — kitted,
	 * charged, ornamented. A guard that only ever compared canonical ids would
	 * pass a one-id-per-card fake and still let a player keep an ornament kit
	 * on their back.
	 */
	static final class Cards extends CardDatabase
	{
		/** Distance from a card's canonical item id to its second variant id. */
		static final int VARIANT_STEP = 10000;

		private static final Map<GearSlot, String> WORD = new EnumMap<>(GearSlot.class);

		static
		{
			WORD.put(GearSlot.HEAD, "full helm");
			WORD.put(GearSlot.CAPE, "cape");
			WORD.put(GearSlot.AMULET, "amulet");
			WORD.put(GearSlot.WEAPON, "scimitar");
			WORD.put(GearSlot.BODY, "platebody");
			WORD.put(GearSlot.SHIELD, "kiteshield");
			WORD.put(GearSlot.LEGS, "platelegs");
			WORD.put(GearSlot.HANDS, "gauntlets");
			WORD.put(GearSlot.FEET, "boots");
			WORD.put(GearSlot.RING, "ring");
			WORD.put(GearSlot.AMMO, "arrows");
		}

		private final Map<Integer, CardDefinition> cards = new LinkedHashMap<>();
		private final Map<Integer, CardDefinition> cardByItem = new HashMap<>();
		private final Map<String, List<CardDefinition>> families = new HashMap<>();

		Cards()
		{
			super(null, null, null, null, null);
			for (GearSlot slot : GearSlot.values())
			{
				for (int rank = 1; rank <= TIERS.size(); rank++)
				{
					String tierKey = TIERS.get(rank - 1);
					int cardId = cardId(slot, tierKey);
					Set<Integer> itemIds = new LinkedHashSet<>(
						Arrays.asList(cardId, cardId + VARIANT_STEP));
					CardDefinition def = new CardDefinition(cardId,
						name(tierKey, slot), slot, tierKey, rank, familyKey(slot),
						Rarity.values()[Math.min(rank - 1, Rarity.values().length - 1)],
						itemIds, rank > 1);
					cards.put(cardId, def);
					for (int itemId : itemIds)
					{
						cardByItem.put(itemId, def);
					}
					families.computeIfAbsent(familyKey(slot), k -> new ArrayList<>()).add(def);
				}
			}
		}

		@Override
		public boolean isReady()
		{
			return true;
		}

		@Override
		public CardDefinition card(int cardId)
		{
			return cards.get(cardId);
		}

		@Override
		public CardDefinition cardForItem(int itemId)
		{
			return cardByItem.get(itemId);
		}

		@Override
		public Map<Integer, CardDefinition> all()
		{
			return cards;
		}

		@Override
		public List<CardDefinition> family(String familyKey)
		{
			return families.getOrDefault(familyKey, Collections.emptyList());
		}

		/** Every item id in the database, canonical and variant alike. */
		Set<Integer> everyItemId()
		{
			return cardByItem.keySet();
		}

		static String familyKey(GearSlot slot)
		{
			return WORD.get(slot) + "/" + slot.name();
		}

		static String name(String tierKey, GearSlot slot)
		{
			return Character.toUpperCase(tierKey.charAt(0)) + tierKey.substring(1)
				+ " " + WORD.get(slot);
		}
	}

	/**
	 * Card id for a slot/tier pair. Also its canonical ITEM id: the real
	 * builder uses the lowest merged item id as the card id, so a card's own
	 * number being wearable is true there too.
	 */
	static int cardId(GearSlot slot, String tierKey)
	{
		return (slot.ordinal() + 1) * 100 + TIERS.indexOf(tierKey) + 1;
	}

	/** The canonical worn item id of a slot/tier pair. Reads better at call sites. */
	static int itemId(GearSlot slot, String tierKey)
	{
		return cardId(slot, tierKey);
	}

	/** The second, merged-variant item id of a slot/tier pair. */
	static int variantItemId(GearSlot slot, String tierKey)
	{
		return cardId(slot, tierKey) + Cards.VARIANT_STEP;
	}

	static OwnedCard plain(GearSlot slot, String tierKey)
	{
		return owned("plain:" + slot + ":" + tierKey, cardId(slot, tierKey), null, Variant.NORMAL);
	}

	static OwnedCard shiny(GearSlot slot, String tierKey)
	{
		return owned("shiny:" + slot + ":" + tierKey, cardId(slot, tierKey), null, Variant.SHINY);
	}

	/**
	 * A hologram instance. The slot is only part of the uuid — a hologram
	 * carries no card id and grants by TIER — but distinct uuids let a
	 * generated album park one in every slot at once without two entries
	 * silently being the same physical card.
	 */
	static OwnedCard hologram(GearSlot slot, String tierKey)
	{
		return owned("holo:" + slot + ":" + tierKey, -1, tierKey, Variant.HOLOGRAM);
	}

	private static OwnedCard owned(String uuid, int cardId, String tierKey, Variant variant)
	{
		return new OwnedCard(uuid, cardId, tierKey, variant, 0L, "test", 0);
	}

	/**
	 * State backed by a store that never touches disk and never returns a save,
	 * so every test starts from a fresh profile. Same shape the task-service
	 * tests use.
	 */
	static GachaStateService inMemoryStateService()
	{
		StateStore store = new StateStore(null, null, null)
		{
			@Override
			public void save(GachaState state)
			{
			}

			@Override
			public void save(GachaState state, boolean flushDiskNow)
			{
			}

			@Override
			public GachaState load()
			{
				return null;
			}
		};
		GachaStateService service = new GachaStateService(store);
		service.load(3);
		return service;
	}

	/** Every slot deeded, so deed gating can never be what a test is measuring. */
	static void deedEverySlot(GachaStateService stateService)
	{
		Set<String> all = new HashSet<>();
		for (GearSlot slot : GearSlot.values())
		{
			all.add(slot.name());
		}
		stateService.mutate(s -> s.withDeededSlots(all));
	}

	static void giveCards(GachaStateService stateService, OwnedCard... cards)
	{
		List<OwnedCard> owned = new ArrayList<>(Arrays.asList(cards));
		stateService.mutate(s -> s.withOwnedCards(owned));
	}

	static void putInLoadout(GachaStateService stateService, GearSlot slot, OwnedCard card)
	{
		stateService.mutate(s ->
		{
			Map<String, String> loadout = new HashMap<>(s.getLoadout());
			loadout.put(slot.name(), card.getUuid());
			return s.withLoadout(loadout);
		});
	}

	static GachamanConfig config(boolean oneCardPerSlot)
	{
		return new GachamanConfig()
		{
			@Override
			public boolean oneCardPerSlot()
			{
				return oneCardPerSlot;
			}
		};
	}

	/**
	 * A LoadoutService wired for a headless test: a null Client and a null
	 * ChatMessageManager (so the refusal line is skipped and the boolean
	 * return is the whole contract), with the worn-equipment read replaced by
	 * a fixed set.
	 */
	static LoadoutService service(GachaStateService stateService, CardDatabase cards,
		PermissionService permissions, GachamanConfig config, Set<Integer> worn)
	{
		return new LoadoutService(stateService, cards, null, null, null, config, permissions, null)
		{
			@Override
			Set<Integer> wornItemIds()
			{
				return worn;
			}
		};
	}
}

package com.gachaman.service;

import com.gachaman.data.*;
import com.google.gson.*;
import org.junit.*;

/**
 * The manual unlock escape hatch, which exists for exactly one situation: a
 * quest needs a monster the bundled table does not list, and the player cannot
 * proceed until someone ships a fix.
 *
 * <p>Its argument is free text a stuck player types into the chatbox while
 * annoyed, so the matching has to be forgiving about case — "::gachaunlock rat"
 * has to work, or the escape hatch fails the one person it was built for.
 *
 * <p>Constructed with a null Client on purpose: overriding is pure bookkeeping
 * and must never need the game to answer. If a change makes these calls touch
 * the client, this test NPEs, and that is the correct alarm — a bypass that
 * only works when the client is in a good mood is not a bypass.
 */
public class QuestUnlockOverrideTest
{
	private static QuestExemptionService service()
	{
		return new QuestExemptionService(null, QuestMonsterTable.load(new Gson()));
	}

	@Test
	public void unlockingIsCaseInsensitiveAndIdempotent()
	{
		QuestExemptionService service = service();
		Assert.assertTrue("first unlock should report as new", service.unlock("Rat"));
		Assert.assertFalse("the same NPC in another case is the same NPC",
			service.unlock("rat"));
		Assert.assertFalse(service.unlock("  RAT  ".trim()));
		Assert.assertEquals("relock must find it whatever case was typed",
			1, service.relock("rAt"));
		Assert.assertEquals("and it is gone", 0, service.relock("Rat"));
	}

	/** With no name, the command clears everything and reports how many. */
	@Test
	public void relockWithoutANameClearsEveryOverrideAndCountsThem()
	{
		QuestExemptionService service = service();
		Assert.assertEquals("nothing to clear yet", 0, service.relock(null));
		service.unlock("Rat");
		service.unlock("Imp");
		service.unlock("Giant rat");
		Assert.assertEquals(3, service.relock(null));
		Assert.assertEquals("clearing twice must not double-count", 0, service.relock(null));
	}

	/** Re-blocking something that was never unlocked is a no-op, not an error. */
	@Test
	public void relockingAnUntouchedNpcReportsNothing()
	{
		Assert.assertEquals(0, service().relock("Elvarg"));
	}
}

package com.gachaman.service;

import com.gachaman.*;
import com.gachaman.model.*;
import org.junit.*;

/** Fixed-seed distribution and math checks — no live client needed. */
public class RollMathTest
{
	private ChestService serviceWithSeed(long seed)
	{
		// only rollRarity is exercised; collaborators may be null
		return new ChestService(null, null, null, null, new GachaRng(seed), new com.google.gson.Gson(), null, null, null);
	}

	@Test
	public void rarityDistributionMatchesOddsWithinTolerance()
	{
		ChestService service = serviceWithSeed(42L);
		double[] odds = Tuning.CHEST_ODDS.get(Tuning.Chest.BATTERED);
		int n = 200_000;
		int[] counts = new int[Rarity.values().length];
		for (int i = 0; i < n; i++)
		{
			counts[service.rollRarity(odds, 0).ordinal()]++;
		}
		double total = 0;
		for (double o : odds)
		{
			total += o;
		}
		for (int i = 0; i < odds.length; i++)
		{
			double expected = odds[i] / total;
			double actual = counts[i] / (double) n;
			Assert.assertEquals("rarity " + Rarity.values()[i], expected, actual, expected * 0.15 + 0.002);
		}
	}

	@Test
	public void pityBonusShiftsMassUpward()
	{
		ChestService service = serviceWithSeed(7L);
		double[] odds = Tuning.CHEST_ODDS.get(Tuning.Chest.BATTERED);
		int n = 100_000;
		int epicPlusBase = 0;
		int epicPlusPity = 0;
		for (int i = 0; i < n; i++)
		{
			if (service.rollRarity(odds, 0).atLeast(Rarity.EPIC))
			{
				epicPlusBase++;
			}
			if (service.rollRarity(odds, 20).atLeast(Rarity.EPIC))
			{
				epicPlusPity++;
			}
		}
		Assert.assertTrue("pity should raise Epic+ rate: " + epicPlusBase + " vs " + epicPlusPity,
			epicPlusPity > epicPlusBase * 3);
	}

	@Test
	public void splitmixIsDeterministic()
	{
		Assert.assertEquals(WeeklyShopService.splitmix64(123L), WeeklyShopService.splitmix64(123L));
		Assert.assertNotEquals(WeeklyShopService.splitmix64(123L), WeeklyShopService.splitmix64(124L));
	}

	@Test
	public void killCbMultiplierCurve()
	{
		// within 5 levels below: flat base
		Assert.assertEquals(1.0, Tuning.killCbMultiplier(100, 95), 1e-9);
		Assert.assertEquals(1.0, Tuning.killCbMultiplier(100, 99), 1e-9);
		// matching your level pays a bonus
		Assert.assertEquals(1.1, Tuning.killCbMultiplier(100, 100), 1e-9);
		// stronger pays progressively more
		double plus10 = Tuning.killCbMultiplier(100, 110);
		double plus30 = Tuning.killCbMultiplier(100, 130);
		Assert.assertTrue(plus10 > 1.1 && plus30 > plus10);
		// The same absolute gap means far more at low levels (ratio scaling).
		//
		// This assertion used to read "> 2 *", and that was correct while
		// KILL_DIFF_CAP was 2.5: +5 at cb 3 is a ratio of 2.67 and scored 5.68
		// before the clamp, which really did dwarf the near-peer. The owner's
		// drop to 1.75 clamps the low-level side to the cap itself, so the
		// factor-of-two claim is now arithmetically unreachable — not because
		// the ratio scaling stopped working, but because the ceiling landed
		// below where the comparison was being made.
		//
		// What is pinned instead is the property the cap did NOT change, in the
		// strongest form still observable through this function: the low-level
		// pair is pushed all the way to the ceiling while the near-peer sits
		// far under it. That keeps the test honest about the direction AND
		// records that the clamp binds at cb 3, which is the actual new
		// behaviour worth catching if the cap ever moves again.
		double lowLevelGap = Tuning.killCbMultiplier(3, 8);
		double nearPeerGap = Tuning.killCbMultiplier(70, 75);
		Assert.assertEquals("+5 at cb 3 is a ratio of 2.67 and must reach the cap",
			Tuning.KILL_DIFF_CAP, lowLevelGap, 1e-9);
		Assert.assertTrue("+5 at cb 70 is a near-peer and must stay well under the cap",
			nearPeerGap < Tuning.KILL_DIFF_CAP - 0.4);
		Assert.assertTrue("+5 at cb 3 must still pay more than +5 at cb 70",
			lowLevelGap > nearPeerGap);
		// far above caps
		Assert.assertEquals(Tuning.KILL_DIFF_CAP, Tuning.killCbMultiplier(50, 700), 1e-9);
		// trivial mobs decay toward the floor
		Assert.assertTrue(Tuning.killCbMultiplier(100, 80) < 1.0);
		Assert.assertEquals(Tuning.KILL_DIFF_FLOOR, Tuning.killCbMultiplier(126, 2), 1e-9);
		// monotonic: never pays more for an easier monster
		double prev = -1;
		for (int npc = 2; npc <= 300; npc++)
		{
			double mult = Tuning.killCbMultiplier(100, npc);
			Assert.assertTrue("non-monotonic at npc " + npc, mult >= prev);
			prev = mult;
		}
	}

	/**
	 * The low-level compensation multiplier is gone on purpose (see Tuning).
	 * What replaces its test is the property it was violating: a kill must not
	 * pay more just because the player is low level. Combat level now reaches
	 * the payout ONLY through the npc-vs-player ratio, so a player and a
	 * monster in the same relative position pay the same at every level.
	 */
	@Test
	public void payoutDependsOnTheGapNotOnBeingLowLevel()
	{
		// same ratio (npc = 1.35x player) at four very different levels
		double at12 = Tuning.killCbMultiplier(12, 16);
		double at30 = Tuning.killCbMultiplier(30, 40);
		double at70 = Tuning.killCbMultiplier(70, 94);
		double at100 = Tuning.killCbMultiplier(100, 135);
		Assert.assertEquals(at12, at30, 0.05);
		Assert.assertEquals(at12, at70, 0.05);
		Assert.assertEquals(at12, at100, 0.05);
	}

	@Test
	public void combinedKillBonusIsBoundedAndAdditive()
	{
		// the runaway this replaced: killCb x combo compounded. Added, the pair
		// cannot exceed the sum of their two ceilings.
		double maxKillCb = Tuning.KILL_DIFF_CAP - 1.0;
		double maxCombo = Tuning.comboMultiplier(Tuning.COMBO_MAX_STACKS) - 1.0;
		double ceiling = 1.0 + maxKillCb + maxCombo;
		Assert.assertTrue("combined ceiling should stay under 5x", ceiling < 5.0);
		for (int cb = 3; cb <= 126; cb++)
		{
			for (int npc = 1; npc <= 200; npc += 7)
			{
				double bonus = (Tuning.killCbMultiplier(cb, npc) - 1.0)
					+ (Tuning.comboMultiplier(Tuning.COMBO_MAX_STACKS) - 1.0);
				Assert.assertTrue("cb " + cb + " vs npc " + npc, 1.0 + bonus <= ceiling + 1e-9);
			}
		}
	}

	@Test
	public void violationPenaltyRules()
	{
		Assert.assertEquals(Tuning.VIOLATION_ATTACK_PENALTY_NO_TASK, ComplianceService.penaltyFor(null));
		com.gachaman.model.ActiveTask task = com.gachaman.model.ActiveTask.builder()
			.difficulty(com.gachaman.model.TaskDifficulty.HARD)
			.monsterName("Fire giant")
			.killsRequired(50)
			.perKillGc(16)
			.completionGc(950)
			.acceptedAtMs(1L)
			.build();
		Assert.assertEquals(32, ComplianceService.penaltyFor(task));
	}

}

