/**
 * The starter grant used to hand every profile all six ironman sets and park a
 * Hardcore ironman platebody in the body slot. Only the set matching the
 * account type varbit is wearable, so only that set may be granted.
 */
public class IronmanGearTest
{
	/**
	 * Injected in the plugin — the Plugin Hub forbids a fresh Gson in shipped
	 * code — but a test has no injector, so it builds its own.
	 */
	private static final IronmanGear GEAR = new IronmanGear(new Gson());

	@Test
	public void normalAccountsGetNoIdentityArmour()
	{
		Assert.assertTrue(GEAR.cardNames(IronmanGear.NORMAL).isEmpty());
		Assert.assertNull(GEAR.bodyCardName(IronmanGear.NORMAL));
	}

	@Test
	public void eachAccountTypeMapsToItsOwnSet()
	{
		Assert.assertEquals("Ironman platebody", GEAR.bodyCardName(1));
		Assert.assertEquals("Ultimate ironman platebody", GEAR.bodyCardName(2));
		Assert.assertEquals("Hardcore ironman platebody", GEAR.bodyCardName(3));
		Assert.assertEquals("Group ironman platebody", GEAR.bodyCardName(4));
		Assert.assertEquals("Hardcore group ironman platebody", GEAR.bodyCardName(5));
		Assert.assertEquals("Unranked group ironman platebody", GEAR.bodyCardName(6));
	}

	@Test
	public void everySetIsAHelmABodyAndLegsAndSetsNeverOverlap()
	{
		int total = 0;
		for (int type = 1; type <= 6; type++)
		{
			List<String> set = GEAR.cardNames(type);
			Assert.assertEquals("account type " + type, 3, set.size());
			Assert.assertTrue(set.get(0).endsWith(" helm"));
			Assert.assertTrue(set.get(1).endsWith(" platebody"));
			Assert.assertTrue(set.get(2).endsWith(" platelegs"));
			total += set.size();
		}
		// allCardNames is the revoke denylist — a name shared between two sets
		// would silently exempt itself, so the union must lose nothing
		Assert.assertEquals(total, GEAR.allCardNames().size());
	}

	@Test
	public void anUnknownAccountTypeGrantsNothingRatherThanTheWrongSet()
	{
		Assert.assertTrue(GEAR.cardNames(7).isEmpty());
		Assert.assertTrue(GEAR.cardNames(-1).isEmpty());
		Assert.assertNull(GEAR.bodyCardName(99));
	}

	@Test
	public void theDenylistCoversEverySetSoForeignCopiesCanBeRevoked()
	{
		Set<String> all = GEAR.allCardNames();
		for (int type = 1; type <= 6; type++)
		{
			Assert.assertTrue("set " + type + " missing from the denylist",
				all.containsAll(GEAR.cardNames(type)));
		}
	}

	/** A null client (headless, or logged out) must read as normal, not crash. */
	@Test
	public void aMissingClientReadsAsNormal()
	{
		Assert.assertEquals(IronmanGear.NORMAL, IronmanGear.accountType(null));
	}
}

package com.gachaman.service;

import com.gachaman.model.*;
import java.util.*;
import java.util.function.*;
import org.junit.*;

/**
 * The Toll's pure rules.
 *
 * <p>The headline invariant is stability: the pick is PERSISTED, not recomputed
 * from a seed, because the pool is the player's album and an album grows during
 * the week. {@link #pickIsStableAsTheAlbumGrows} is the test a naive port of
 * WeeklyShopService's zero-stored-state trick fails, and it is first on purpose.
 */
public class TollServiceTest
{
	private static final String WEEK = "2026-W33";
	private static final String NEXT_WEEK = "2026-W34";
	private static final ToIntFunction<String> NO_PENDING = uuid -> 0;

	/** Fixed seed: these tests pin behaviour, never a particular draw. */
	private static final long SEED = TollService.seedFor("profile-a", WEEK);

	private static OwnedCard card(String uuid, int cardId, int killsServed)
	{
		return new OwnedCard(uuid, cardId, null, Variant.NORMAL, 100L, "chest:GILDED", killsServed);
	}

	private static OwnedCard hologram(String uuid, String tierKey, int killsServed)
	{
		return new OwnedCard(uuid, -1, tierKey, Variant.HOLOGRAM, 100L, "chest:ORNATE", killsServed);
	}

	/** An album of six veteran cards — every one of them a legal Toll. */
	private static List<OwnedCard> veterans()
	{
		List<OwnedCard> cards = new ArrayList<>();
		for (int i = 0; i < 6; i++)
		{
			cards.add(card("vet-" + i, 1000 + i, 40 + i));
		}
		return cards;
	}

	private static ToIntFunction<String> pending(Map<String, Integer> banked)
	{
		return uuid -> banked.getOrDefault(uuid, 0);
	}

	// --- stability across a week (the reason this class stores its pick) ---

	@Test
	public void pickIsStableAsTheAlbumGrows()
	{
		List<OwnedCard> album = veterans();
		TollService.Pick first = TollService.resolve(WEEK, null, null, album, NO_PENDING, SEED);
		Assert.assertNotNull("a six-veteran album must offer a Toll", first.getUuid());
		Assert.assertTrue("the first pick of a week must be persisted", first.isRewrite());
		final String named = first.getUuid();

		// the week goes on: ten chests open, and three of those cards cross their
		// first kill of service. Both kinds of growth move the seeded index.
		for (int i = 0; i < 10; i++)
		{
			album.add(card("new-" + i, 2000 + i, 0));
		}
		Map<String, Integer> banked = new HashMap<>();
		for (int i = 0; i < 3; i++)
		{
			banked.put("new-" + i, 1);
		}

		TollService.Pick later = TollService.resolve(WEEK, WEEK, named, album, pending(banked), SEED);

		Assert.assertEquals("the named card must not change mid-week", named, later.getUuid());
		Assert.assertFalse("a pick that still stands must not be rewritten", later.isRewrite());
	}

	@Test
	public void aRecomputedPickWouldHaveDriftedOnTheGrownAlbum()
	{
		// The other half of the test above: it only proves something because the
		// grown album really does index differently under the very same seed. If
		// this ever stops holding, the stability test has quietly become vacuous.
		List<OwnedCard> album = veterans();
		String before = TollService.resolve(WEEK, null, null, album, NO_PENDING, SEED).getUuid();

		for (int i = 0; i < 10; i++)
		{
			album.add(card("new-" + i, 2000 + i, 1));
		}
		String recomputed = TollService.resolve(WEEK, null, null, album, NO_PENDING, SEED).getUuid();

		Assert.assertNotEquals("same seed, grown pool: the naive port re-picks", before, recomputed);
	}

	// --- the three re-pick triggers, and nothing else ---

	@Test
	public void rePicksWhenTheWeekTurns()
	{
		List<OwnedCard> album = veterans();
		TollService.Pick next = TollService.resolve(
			NEXT_WEEK, WEEK, "vet-0", album, NO_PENDING, TollService.seedFor("profile-a", NEXT_WEEK));

		Assert.assertNotNull(next.getUuid());
		Assert.assertTrue("a new week's pick must be persisted", next.isRewrite());
	}

	@Test
	public void rePicksWhenTheNamedCardIsNoLongerOwned()
	{
		List<OwnedCard> album = veterans();
		album.removeIf(c -> "vet-0".equals(c.getUuid()));

		TollService.Pick fresh = TollService.resolve(WEEK, WEEK, "vet-0", album, NO_PENDING, SEED);

		Assert.assertNotNull(fresh.getUuid());
		Assert.assertNotEquals("vet-0", fresh.getUuid());
		Assert.assertTrue(fresh.isRewrite());
	}

	@Test
	public void doesNotRePickOnceThisWeeksTollIsPaid()
	{
		// THE anti-re-arm rule. purchase() consumes the card and stores a null uuid
		// under the current week key. Check the null uuid AFTER the ownership test
		// instead of before and the spent card reads as "no longer owned", the Toll
		// re-picks, and the player pays it again and again inside one week.
		List<OwnedCard> album = veterans();

		TollService.Pick paid = TollService.resolve(WEEK, WEEK, null, album, NO_PENDING, SEED);

		Assert.assertNull("a paid week offers nothing, however full the album is", paid.getUuid());
		Assert.assertFalse("and writes nothing", paid.isRewrite());
	}

	@Test
	public void nothingElseRePicks()
	{
		// A live pick survives everything that is not "the week turned" or "the
		// card is gone": more cards, more service on other cards, more service on
		// the named card itself, and unflushed kills appearing anywhere.
		List<OwnedCard> album = veterans();
		album.add(card("late", 3000, 0));
		Map<String, Integer> banked = new HashMap<>();
		banked.put("late", 5);
		banked.put("vet-3", 12);

		TollService.Pick stands = TollService.resolve(
			WEEK, WEEK, "vet-3", album, pending(banked), SEED);

		Assert.assertEquals("vet-3", stands.getUuid());
		Assert.assertFalse(stands.isRewrite());
	}

	@Test
	public void anEmptyPoolWritesNothingSoTheWeekStaysOpen()
	{
		// Recording the week key with a null uuid here would be indistinguishable
		// from PAID and would suppress the Toll for the whole week — including for
		// the player whose first card earns its first kill on the Tuesday.
		List<OwnedCard> junkOnly = new ArrayList<>(Arrays.asList(
			card("j1", 10, 0), card("j2", 11, 0)));

		TollService.Pick none = TollService.resolve(WEEK, null, null, junkOnly, NO_PENDING, SEED);

		Assert.assertNull(none.getUuid());
		Assert.assertFalse("no eligible card must leave both fields untouched", none.isRewrite());

		// ...and the moment one of them earns a kill, the Toll arrives
		Map<String, Integer> banked = new HashMap<>();
		banked.put("j2", 1);
		TollService.Pick arrived = TollService.resolve(
			WEEK, null, null, junkOnly, pending(banked), SEED);
		Assert.assertEquals("j2", arrived.getUuid());
		Assert.assertTrue(arrived.isRewrite());
	}

	@Test
	public void handlesANullOrEmptyAlbum()
	{
		Assert.assertNull(TollService.resolve(WEEK, null, null, null, NO_PENDING, SEED).getUuid());
		Assert.assertNull(TollService.resolve(
			WEEK, null, null, Collections.emptyList(), NO_PENDING, SEED).getUuid());
	}

	// --- eligibility ---

	@Test
	public void eligibilityCountsUnflushedPendingKills()
	{
		// ServiceRecordService banks kills in memory until flush(), so a card that
		// earned its first kills this session still reads killsServed == 0. Without
		// the pending term the house would call it junk.
		OwnedCard freshlyBlooded = card("u1", 55, 0);

		Assert.assertFalse("no kills at all is junk", TollService.isEligible(freshlyBlooded, 0));
		Assert.assertTrue("one unflushed kill is a Service Record",
			TollService.isEligible(freshlyBlooded, 1));
		Assert.assertTrue("a written record needs no pending kills",
			TollService.isEligible(card("u2", 56, 3), 0));
	}

	@Test
	public void unflushedKillsCanCarryACardIntoThePool()
	{
		List<OwnedCard> album = new ArrayList<>(Arrays.asList(card("only", 77, 0)));
		Map<String, Integer> banked = new HashMap<>();
		banked.put("only", 2);

		List<OwnedCard> pool = TollService.eligible(album, pending(banked));

		Assert.assertEquals(1, pool.size());
		Assert.assertEquals("only", pool.get(0).getUuid());
	}

	@Test
	public void hologramsAreNeverNamed()
	{
		// a hologram represents a whole tier and is the rarest pull in the game;
		// the house does not ask for one, however much service it has seen
		OwnedCard holo = hologram("h1", "dragon", 900);
		Assert.assertFalse(TollService.isEligible(holo, 0));
		Assert.assertFalse(TollService.isEligible(holo, 50));

		List<OwnedCard> album = new ArrayList<>(Arrays.asList(holo, card("plain", 12, 4)));
		Assert.assertEquals(1, TollService.eligible(album, NO_PENDING).size());
		Assert.assertEquals("plain",
			TollService.resolve(WEEK, null, null, album, NO_PENDING, SEED).getUuid());

		// an album of nothing but holograms offers no Toll at all
		Assert.assertNull(TollService.resolve(WEEK, null, null,
			Collections.singletonList(holo), NO_PENDING, SEED).getUuid());
	}

	@Test
	public void aCardAssignedToALoadoutSlotIsStillEligible()
	{
		// The owner's decision: assignment does not enter the eligibility test at
		// all. The player unassigns it first — that refusal happens at purchase
		// time, not by shrinking the pool to whatever they are not wearing.
		OwnedCard worn = card("worn", 99, 120);
		List<OwnedCard> album = new ArrayList<>(Collections.singletonList(worn));
		Map<String, String> loadout = new HashMap<>();
		loadout.put(GearSlot.WEAPON.name(), "worn");

		Assert.assertEquals(1, TollService.eligible(album, NO_PENDING).size());
		Assert.assertEquals("worn",
			TollService.resolve(WEEK, null, null, album, NO_PENDING, SEED).getUuid());
		Assert.assertEquals("and the refusal is the separate concern",
			GearSlot.WEAPON, TollService.assignedSlot(loadout, "worn"));
	}

	@Test
	public void eligibleIsSortedByUuidForDeterminism()
	{
		// the album's own order follows acquisition; a seeded index into an
		// unsorted list would be reproducible only by accident
		List<OwnedCard> album = new ArrayList<>(Arrays.asList(
			card("ccc", 3, 1), card("aaa", 1, 1), card("bbb", 2, 1)));

		List<OwnedCard> pool = TollService.eligible(album, NO_PENDING);

		Assert.assertEquals(Arrays.asList("aaa", "bbb", "ccc"),
			Arrays.asList(pool.get(0).getUuid(), pool.get(1).getUuid(), pool.get(2).getUuid()));
	}

	// --- the assigned-slot refusal ---

	@Test
	public void assignedSlotFindsTheOccupiedSlotOnly()
	{
		Map<String, String> loadout = new HashMap<>();
		loadout.put(GearSlot.WEAPON.name(), "u1");
		loadout.put(GearSlot.BODY.name(), "u2");

		Assert.assertEquals(GearSlot.WEAPON, TollService.assignedSlot(loadout, "u1"));
		Assert.assertEquals(GearSlot.BODY, TollService.assignedSlot(loadout, "u2"));
		Assert.assertNull(TollService.assignedSlot(loadout, "u3"));
		Assert.assertNull(TollService.assignedSlot(null, "u1"));
		Assert.assertNull(TollService.assignedSlot(Collections.emptyMap(), "u1"));
	}

	@Test
	public void theRefusalNamesTheSlotAndIsNotTheUnequipMessage()
	{
		// One intent produces two refusals on two surfaces — unequip, then
		// unassign, then pay. Identical wording would read as one broken button,
		// so this pins the Toll's half of the pair.
		String message = String.format(TollService.ASSIGNED_REFUSAL, GearSlot.WEAPON.getDisplayName());

		Assert.assertEquals("That card is still in your Weapon slot", message);
		Assert.assertFalse("must not duplicate the unassign guard's message",
			message.toLowerCase(Locale.ROOT).contains("take the item off"));
	}

	// --- seeding ---

	@Test
	public void theFirstPickOfAWeekIsDeterministic()
	{
		List<OwnedCard> album = veterans();
		String a = TollService.resolve(WEEK, null, null, album, NO_PENDING,
			TollService.seedFor("profile-a", WEEK)).getUuid();
		String b = TollService.resolve(WEEK, null, null, album, NO_PENDING,
			TollService.seedFor("profile-a", WEEK)).getUuid();

		Assert.assertEquals("same profile, same week, same album -> same card", a, b);
	}

	@Test
	public void theSeedIsSaltedAwayFromTheWeeklyShopsSeed()
	{
		// both mix the same profile key and the same week key; without the salt the
		// two features would walk the same seeded sequence every week
		long shop = WeeklyShopService.splitmix64("profile-a".hashCode() * 31L + WEEK.hashCode());

		Assert.assertNotEquals(shop, TollService.seedFor("profile-a", WEEK));
	}

	@Test
	public void aNullProfileKeyStillSeeds()
	{
		// the profile key is null before login; the Toll must not throw there
		Assert.assertNotEquals(0L, TollService.seedFor(null, WEEK));
	}
}

package com.gachaman.service;

import org.junit.*;

/**
 * Pins the contract KillTracker.emit() now leans on lombok for.
 *
 * emit() used to spell the loot-oracle re-stamp out by hand:
 *
 *   assisted == draft.isAssistedByOther() ? draft : new Kill(...nine args...)
 *
 * and that hand-written form carried two guarantees the rest of the class
 * quietly depends on — (1) an unchanged verdict hands back the SAME instance,
 * so the common case allocates nothing on every kill, and (2) an overturned
 * verdict copies the other eight fields across untouched. Replacing it with
 * field-level {@code @With} moved both guarantees out of our source and into
 * generated code, where a lombok upgrade could change them without any diff
 * appearing in this repository. These assertions are the tripwire for that.
 */
public class KillTrackerWitherTest
{
	private static KillTracker.Kill draft(boolean assisted)
	{
		// deathLocation stays null: LocalPoint's constructor has moved between
		// RuneLite versions, and identity of the carried-over reference is what
		// this test cares about, which assertSame checks just as well on null.
		return new KillTracker.Kill("Goblin", 2, 17, 40, 33, true, 9, assisted, null);
	}

	@Test
	public void unchangedVerdictReturnsSameInstance()
	{
		KillTracker.Kill clean = draft(false);
		Assert.assertSame("clean verdict re-stamped clean must not reallocate",
			clean, clean.withAssistedByOther(false));

		KillTracker.Kill suspected = draft(true);
		Assert.assertSame("suspicion re-stamped suspicious must not reallocate",
			suspected, suspected.withAssistedByOther(true));
	}

	@Test
	public void overturnedVerdictCopiesEveryOtherField()
	{
		KillTracker.Kill suspected = draft(true);
		KillTracker.Kill exonerated = suspected.withAssistedByOther(false);

		Assert.assertNotSame(suspected, exonerated);
		Assert.assertTrue("the draft itself must be untouched", suspected.isAssistedByOther());
		Assert.assertFalse("the oracle's verdict must land", exonerated.isAssistedByOther());

		Assert.assertEquals("Goblin", exonerated.getNpcName());
		Assert.assertEquals(2, exonerated.getNpcCombatLevel());
		Assert.assertEquals(17, exonerated.getNpcIndex());
		Assert.assertEquals(40, exonerated.getTick());
		Assert.assertEquals(33, exonerated.getEngagementStartTick());
		Assert.assertTrue(exonerated.isTookDamageDuringEngagement());
		Assert.assertEquals(9, exonerated.getMaxHitDealt());
		Assert.assertSame(suspected.getDeathLocation(), exonerated.getDeathLocation());
	}
}

package com.gachaman.service;

import org.junit.*;

/**
 * The max-hit curve behind the "land a hit of N+" side bet. The client-reading
 * half of {@link MaxHitService} needs a live client; the arithmetic does not,
 * and the arithmetic is the part that decides whether a bet is winnable.
 *
 * <p>Reference values are the standard OSRS formula
 * {@code floor(0.5 + (level + 8) * (strBonus + 64) / 640)}, unboosted and
 * unprayed — the same steps the Plugin Hub max-hit calculators use, minus the
 * multipliers this deliberately leaves out.
 */
public class MaxHitServiceTest
{
	@Test
	public void bronzeTierAccountMaxesAboutThree()
	{
		// the case that exposed the bug: ~combat 12, bronze sword (str +7)
		// (10 + 8) * (7 + 64) / 640 = 2.0 -> +0.5 -> floor 2
		Assert.assertEquals(2, MaxHitService.gearedMaxHit(10, 7));
		// a few levels and a slightly better weapon still lands in low single digits
		Assert.assertEquals(3, MaxHitService.gearedMaxHit(20, 10));
		// which is why "land a hit of 6+" was unwinnable there
		Assert.assertTrue(MaxHitService.gearedMaxHit(20, 10) < 6);
	}

	@Test
	public void curveRisesWithBothLevelAndGear()
	{
		Assert.assertTrue(MaxHitService.gearedMaxHit(70, 60) > MaxHitService.gearedMaxHit(40, 60));
		Assert.assertTrue(MaxHitService.gearedMaxHit(70, 90) > MaxHitService.gearedMaxHit(70, 30));
		// a maxed melee account sits in the expected 40s, not the hundreds
		int maxed = MaxHitService.gearedMaxHit(99, 120);
		Assert.assertTrue("maxed melee looked wrong: " + maxed, maxed >= 30 && maxed <= 60);
	}

	@Test
	public void neverReturnsZeroOrNegative()
	{
		// an unarmed, level-1 account still has a floor: a threshold of 0 would
		// make the bet auto-win, which is as broken as auto-lose
		Assert.assertTrue(MaxHitService.gearedMaxHit(1, 0) >= 1);
		Assert.assertTrue(MaxHitService.gearedMaxHit(0, -10) >= 1);
		Assert.assertTrue(MaxHitService.magicMaxHit(1, 0) >= 1);
	}

	@Test
	public void spellLadderTracksMagicLevel()
	{
		Assert.assertEquals(2, MaxHitService.spellBaseMaxHit(1));
		Assert.assertEquals(2, MaxHitService.spellBaseMaxHit(12));
		Assert.assertEquals(8, MaxHitService.spellBaseMaxHit(13));   // fire strike
		Assert.assertEquals(12, MaxHitService.spellBaseMaxHit(35));  // fire bolt
		Assert.assertEquals(16, MaxHitService.spellBaseMaxHit(59));  // fire blast
		Assert.assertEquals(24, MaxHitService.spellBaseMaxHit(99));  // fire surge
		int prev = 0;
		for (int lvl = 1; lvl <= 99; lvl++)
		{
			int base = MaxHitService.spellBaseMaxHit(lvl);
			Assert.assertTrue("ladder must never fall at level " + lvl, base >= prev);
			prev = base;
		}
	}

	@Test
	public void magicDamageBonusScalesTheSpell()
	{
		// fire surge at +0% vs +20% magic damage
		Assert.assertEquals(24, MaxHitService.magicMaxHit(99, 0));
		Assert.assertEquals(28, MaxHitService.magicMaxHit(99, 20));
	}

	@Test
	public void everyThresholdItFeedsStaysWinnable()
	{
		// the end-to-end property: whatever the curve says, the bet built from
		// it must be reachable. This is the guard the old combat-level version
		// failed for every account under combat 24.
		for (int level = 1; level <= 99; level++)
		{
			for (int bonus = 0; bonus <= 150; bonus += 10)
			{
				int max = MaxHitService.gearedMaxHit(level, bonus);
				Assert.assertTrue("level " + level + " bonus " + bonus,
					TaskGenerator.bigHitThreshold(max) <= max);
			}
		}
	}
}

package com.gachaman.service;

import com.gachaman.*;
import com.gachaman.data.*;
import com.gachaman.model.*;
import com.gachaman.persist.*;
import java.util.*;
import org.junit.*;

/**
 * The Consignment's spend rules, headless, on real in-memory state and a real
 * StyleService — the only stubs are the two collaborators that would otherwise
 * need a live game client (the card database reads item stats, the chest service
 * rolls from it).
 *
 * <p>The four rows of the spend table are one test each, because they are the
 * subtlest part of the feature and each one fails differently: an over-charged
 * key silently costs the player a day, an under-charged one makes the once-a-day
 * gate meaningless.
 */
public class ConsignmentServiceTest
{
	/**
	 * Fixed so the ORDINARY wheel is predictable. Nothing asserts on the seed
	 * itself — the tests derive what this seed would roll and then arrange the
	 * album so the house names a different style, which is what makes
	 * "accept commits the HOUSE's style" provable rather than lucky.
	 */
	private static final long SEED = 7L;

	private static final int MELEE_CARD = 1001;
	private static final int RANGED_CARD = 2001;
	private static final int MAGIC_CARD = 3001;

	private GachaStateService stateService;
	private StyleService styleService;
	private StubChests chestService;
	private StubCards cardDatabase;
	private HoldingPresenter presenter;
	private ConsignmentService consignment;

	// --- Harness --------------------------------------------------------------

	private static GachaStateService inMemoryStateService()
	{
		StateStore store = new StateStore(null, null, null)
		{
			@Override
			public void save(GachaState state)
			{
			}

			@Override
			public void save(GachaState state, boolean flushDiskNow)
			{
			}

			@Override
			public GachaState load()
			{
				return null; // forces a fresh in-memory state
			}
		};
		GachaStateService service = new GachaStateService(store);
		service.load(3);
		return service;
	}

	/** Card database with hand-written weapon pools; never touches ItemManager. */
	private static class StubCards extends CardDatabase
	{
		private final Map<AttackStyle, Set<Integer>> pools = new EnumMap<>(AttackStyle.class);
		private boolean dbReady = true;

		StubCards()
		{
			super(null, null, null, null, null);
		}

		@Override
		public boolean isReady()
		{
			return dbReady;
		}

		@Override
		public Set<Integer> weaponCardIdsForStyle(AttackStyle style)
		{
			return pools.getOrDefault(style, Collections.emptySet());
		}
	}

	/**
	 * Chest service that only knows how to take the money. The GC round trip is
	 * real — the service under test funds the crate and this spends it back — so
	 * the "a free crate costs the purse nothing" invariant is genuinely exercised
	 * rather than assumed.
	 */
	private static class StubChests extends ChestService
	{
		private final CreditSink sink;
		private Tuning.Chest openedTier;
		private boolean deliverable = true;

		StubChests(GachaStateService stateService, CreditSink sink)
		{
			super(stateService, sink, null, null, null, null, null, null, null);
			this.sink = sink;
		}

		@Override
		public synchronized ChestOpenResult openChest(Tuning.Chest tier)
		{
			if (!deliverable)
			{
				return null;
			}
			long price = Tuning.CHEST_PRICE_GC.get(tier);
			if (!sink.spend(price))
			{
				return null;
			}
			openedTier = tier;
			// trailing null is tollTierKey: this stand-in deals the Consignment's
			// ordinary Gilded crate, which is not a Toll pull and is confined to no
			// tier ladder
			return new ChestOpenResult(tier, tier, false, false, false, null, null,
				Collections.emptyList(), price, false, null);
		}
	}

	/** Claims the offer and then just holds it, so the test decides the answer. */
	private static class HoldingPresenter implements ConsignmentService.Presenter
	{
		private ConsignmentService.Offer shown;
		private int presentCalls;
		private boolean claim = true;

		@Override
		public boolean present(ConsignmentService.Offer offer)
		{
			presentCalls++;
			shown = offer;
			return claim;
		}
	}

	@Before
	public void setUp()
	{
		stateService = inMemoryStateService();
		CreditSink creditSink = new CreditSink(stateService);
		ComplianceService complianceService =
			new ComplianceService(stateService, creditSink, null, null);
		CeremonyBus ceremonyBus = new CeremonyBus();
		styleService = StyleFixture.styleService(stateService, complianceService, ceremonyBus,
			new GachaRng(SEED));
		chestService = new StubChests(stateService, creditSink);
		cardDatabase = new StubCards();
		presenter = new HoldingPresenter();
		consignment = new ConsignmentService(stateService, styleService, chestService,
			cardDatabase, ceremonyBus);
		consignment.setPresenter(presenter);

		cardDatabase.pools.put(AttackStyle.MELEE, new HashSet<>(Arrays.asList(MELEE_CARD)));
		cardDatabase.pools.put(AttackStyle.RANGED, new HashSet<>(Arrays.asList(RANGED_CARD)));
		cardDatabase.pools.put(AttackStyle.MAGIC, new HashSet<>(Arrays.asList(MAGIC_CARD)));
	}

	/** What the ordinary wheel would land on first, from an untouched copy of the seed. */
	private static AttackStyle wheelWouldRollFirst()
	{
		return AttackStyle.values()[new GachaRng(SEED).nextInt(AttackStyle.values().length)];
	}

	private static OwnedCard card(int cardId)
	{
		return new OwnedCard(UUID.randomUUID().toString(), cardId, null, Variant.NORMAL,
			0L, "test", 0);
	}

	/**
	 * An established account, already on a style, whose album is worst dressed
	 * for exactly one style — the one the seeded wheel would NOT have picked, so
	 * "the house named it" and "the wheel happened to land there" cannot be
	 * confused for one another.
	 */
	private AttackStyle seedEstablishedAccount()
	{
		AttackStyle wheel = wheelWouldRollFirst();
		AttackStyle house = null;
		for (AttackStyle style : AttackStyle.values())
		{
			if (style != wheel)
			{
				house = style;
				break;
			}
		}
		// every OTHER style gets a weapon card; the house's style gets none, so it
		// is strictly worst dressed and no tie-break is involved
		final AttackStyle named = house;
		List<OwnedCard> album = new ArrayList<>();
		for (AttackStyle style : AttackStyle.values())
		{
			if (style == named)
			{
				continue;
			}
			for (int id : cardDatabase.pools.get(style))
			{
				album.add(card(id));
			}
		}
		stateService.mutate(s -> s
			.withAllowedStyle(AttackStyle.MELEE.name())
			.withCycleTarget(Tuning.CYCLE_TASKS)
			.withCycleProgress(Tuning.CYCLE_TASKS)
			.withStyleRolledAtMs(1L)
			// wiped deliberately, and it is load-bearing: the delegation pin below
			// re-seeds AFTER taking a control roll, and a value left over from that
			// control would make the pin pass no matter what the accept path did
			.withPreferredWeaponType(null)
			.withOwnedCards(album)
			.withGc(0));
		return named;
	}

	// --- The spend table ------------------------------------------------------

	@Test
	public void acceptingSpendsTheDayKeyAndCommitsTheHouseStyle()
	{
		AttackStyle named = seedEstablishedAccount();

		Assert.assertTrue("the roll must be deferred, not taken", consignment.offerOrRoll(10));
		Assert.assertEquals(1, presenter.presentCalls);
		Assert.assertEquals(named, presenter.shown.getStyle());
		Assert.assertEquals(Tuning.Chest.GILDED, presenter.shown.getChestTier());
		Assert.assertTrue("a deferred roll must be recorded as owed",
			stateService.get().isStyleRollOwed());
		Assert.assertNull("the key is spent on RESOLUTION, never on the offer",
			stateService.get().getConsignmentDayKey());

		Assert.assertTrue(consignment.accept(11));

		GachaState after = stateService.get();
		Assert.assertEquals("the key is spent", consignment.currentDayKey(),
			after.getConsignmentDayKey());
		Assert.assertFalse("the roll has been taken", after.isStyleRollOwed());
		Assert.assertEquals("the HOUSE named the style, not the wheel", named.name(),
			after.getAllowedStyle());
		Assert.assertEquals("the cycle restarts like any other roll", 0.0,
			after.getCycleProgress(), 0.0001);
		Assert.assertEquals(Tuning.Chest.GILDED, chestService.openedTier);
		Assert.assertEquals("a free crate must cost the purse exactly nothing",
			0L, after.getGc());
		Assert.assertNull("the offer is resolved and gone", consignment.pendingOffer());
	}

	/**
	 * The regression pin for the one mistake that would be invisible: committing
	 * the house's style with a hand-written mutate instead of routing it through
	 * StyleService. A duplicated commit still sets the style, the cycle and the
	 * timestamp — so nothing else in this file would notice — but it silently
	 * drops whatever else the wheel names alongside the style (the preferred
	 * weapon type, and anything added after it).
	 *
	 * <p>Written as an agreement between the two paths rather than a bare
	 * non-null assertion, so it stays honest headless: if an ordinary roll cannot
	 * name a weapon type without a game client, neither can this one, and the
	 * test still fails the moment the two paths stop matching.
	 */
	@Test
	public void anAcceptedConsignmentRollsTHROUGHStyleServiceRatherThanAroundIt()
	{
		seedEstablishedAccount();

		// control: what an ordinary roll leaves behind on this same harness
		styleService.roll(1);
		boolean ordinaryNamesAWeaponType = stateService.get().getPreferredWeaponType() != null;
		int ordinaryCycleTarget = stateService.get().getCycleTarget();

		// put the cycle back where it was and run the offer for real
		AttackStyle named = seedEstablishedAccount();
		Assert.assertTrue(consignment.offerOrRoll(10));
		Assert.assertTrue(consignment.accept(11));

		GachaState after = stateService.get();
		Assert.assertEquals(named.name(), after.getAllowedStyle());
		Assert.assertEquals("the house's roll must be the same kind of roll as the wheel's",
			ordinaryCycleTarget, after.getCycleTarget());
		Assert.assertEquals("an accepted Consignment must go THROUGH StyleService.roll —"
				+ " a hand-written commit would drop whatever the wheel names beside the style",
			ordinaryNamesAWeaponType, after.getPreferredWeaponType() != null);
	}

	@Test
	public void decliningAlsoSpendsTheDayKeyAndTakesTheOrdinaryWheel()
	{
		seedEstablishedAccount();
		// a purse with something IN it, so "the refusal moved no money" is a real
		// assertion rather than 0 == 0: a decline that wrongly funded a crate it
		// never deals would be invisible against an empty purse
		stateService.mutate(s -> s.withGc(1234));
		long styleRolledBefore = stateService.get().getStyleRolledAtMs();

		Assert.assertTrue(consignment.offerOrRoll(10));
		Assert.assertTrue(consignment.decline(11));

		GachaState after = stateService.get();
		Assert.assertEquals("being ASKED is what is rationed, so a refusal still pays",
			consignment.currentDayKey(), after.getConsignmentDayKey());
		Assert.assertFalse(after.isStyleRollOwed());
		Assert.assertNotEquals("the wheel must actually have turned", styleRolledBefore,
			after.getStyleRolledAtMs());
		Assert.assertEquals("the cycle restarts", 0.0, after.getCycleProgress(), 0.0001);
		Assert.assertNull("no crate on a refusal", chestService.openedTier);
		Assert.assertEquals("a refusal must not move the purse by a single coin",
			1234L, after.getGc());
	}

	/**
	 * Declining must NOT re-queue the way a deed choice does. A deed that
	 * re-queues costs nothing; an offer that re-queues is re-offerable at will,
	 * which is the whole once-per-day gate gone.
	 */
	@Test
	public void aDeclinedOfferIsNotOfferedAgainTheSameDay()
	{
		seedEstablishedAccount();
		Assert.assertTrue(consignment.offerOrRoll(10));
		Assert.assertTrue(consignment.decline(11));

		// the next contract completion brings another roll due
		stateService.mutate(s -> s.withCycleProgress(s.getCycleTarget()));
		Assert.assertFalse("the day key is spent — this roll goes straight to the wheel",
			consignment.offerOrRoll(20));
		Assert.assertEquals("the player must not be asked twice in one day",
			1, presenter.presentCalls);
	}

	/**
	 * Safe mode pulled the ceremony down when something hit the player. They
	 * never got to answer, so they are not charged — and the roll they were about
	 * to be given is still owed.
	 */
	@Test
	public void anOfferAbortedByCombatSpendsNothingAndLeavesTheRollOwed()
	{
		seedEstablishedAccount();
		Assert.assertTrue(consignment.offerOrRoll(10));
		long styleRolledBefore = stateService.get().getStyleRolledAtMs();

		consignment.abandon();

		GachaState after = stateService.get();
		Assert.assertNull("an offer the player never answered must not be charged",
			after.getConsignmentDayKey());
		Assert.assertTrue("the roll is still owed", after.isStyleRollOwed());
		Assert.assertEquals("no wheel turned", styleRolledBefore, after.getStyleRolledAtMs());
		Assert.assertNull(consignment.pendingOffer());
		Assert.assertNull(chestService.openedTier);
	}

	/**
	 * The client died with the offer on screen. Nothing in memory survives, so
	 * the persisted owed flag is the only witness — and the login drain settles
	 * it by taking the ordinary wheel, never by asking again (a login is an
	 * arbitrary time, and this offer is only ever made in the moment a roll comes
	 * due). The day key stays unspent, so the player can still be asked properly
	 * the next time the cycle turns over today.
	 */
	@Test
	public void loggingOutMidOfferSpendsNothingAndTheLoginDrainTakesTheWheel()
	{
		seedEstablishedAccount();
		Assert.assertTrue(consignment.offerOrRoll(10));
		long styleRolledBefore = stateService.get().getStyleRolledAtMs();

		// the process is gone: a brand-new service sees only what was persisted
		ConsignmentService afterRestart = new ConsignmentService(stateService, styleService,
			chestService, cardDatabase, new CeremonyBus());
		HoldingPresenter freshPresenter = new HoldingPresenter();
		afterRestart.setPresenter(freshPresenter);

		Assert.assertNull("nothing about the question survives the client",
			afterRestart.pendingOffer());
		Assert.assertTrue(stateService.get().isStyleRollOwed());
		Assert.assertNull(stateService.get().getConsignmentDayKey());

		afterRestart.drainOwedRoll(5);

		GachaState after = stateService.get();
		Assert.assertFalse("the drain must settle the owed roll", after.isStyleRollOwed());
		Assert.assertNotEquals("the wheel turned", styleRolledBefore, after.getStyleRolledAtMs());
		Assert.assertNull("an unanswered offer is never charged, not even on recovery",
			after.getConsignmentDayKey());
		Assert.assertEquals("the drain must never re-ask", 0, freshPresenter.presentCalls);
	}

	@Test
	public void theLoginDrainIsANoOpWhenNothingIsOwed()
	{
		seedEstablishedAccount();
		long styleRolledBefore = stateService.get().getStyleRolledAtMs();

		consignment.drainOwedRoll(5);

		Assert.assertEquals("no owed flag means no roll to settle", styleRolledBefore,
			stateService.get().getStyleRolledAtMs());
	}

	// --- Exclusions -----------------------------------------------------------

	/**
	 * An account with no album cannot be "worst dressed" for anything, and the
	 * free First Colours chest already rides the first roll. {@code allowedStyle
	 * == null} is the same firstEver discriminator StyleService uses.
	 */
	@Test
	public void theFirstEverRollIsNeverAConsignment()
	{
		Assert.assertNull("precondition: a fresh profile has no style yet",
			stateService.get().getAllowedStyle());

		Assert.assertFalse("the first roll is taken, never sold",
			consignment.offerOrRoll(1));

		Assert.assertEquals(0, presenter.presentCalls);
		Assert.assertNotNull("the roll still happened", stateService.get().getAllowedStyle());
		Assert.assertNull(stateService.get().getConsignmentDayKey());
		Assert.assertFalse(stateService.get().isStyleRollOwed());
	}

	/**
	 * Nobody can put it on screen (headless, or the overlay is busy). The wheel
	 * spins exactly as it would have without this feature, and the day key is
	 * untouched — an offer that never reached the player is not an offer.
	 */
	@Test
	public void anOfferNobodyCanPresentCostsNothingAndStillRolls()
	{
		seedEstablishedAccount();
		presenter.claim = false;
		long styleRolledBefore = stateService.get().getStyleRolledAtMs();

		Assert.assertFalse(consignment.offerOrRoll(10));

		GachaState after = stateService.get();
		Assert.assertNull(after.getConsignmentDayKey());
		Assert.assertFalse("nothing may be left owed", after.isStyleRollOwed());
		Assert.assertNotEquals("the wheel must still turn", styleRolledBefore,
			after.getStyleRolledAtMs());
	}

	@Test
	public void noOfferUntilTheCardDatabaseCanSayWhoIsWorstDressed()
	{
		seedEstablishedAccount();
		cardDatabase.dbReady = false;

		Assert.assertFalse(consignment.offerOrRoll(10));

		Assert.assertEquals(0, presenter.presentCalls);
		Assert.assertNull(stateService.get().getConsignmentDayKey());
		Assert.assertFalse(stateService.get().isStyleRollOwed());
	}

	// --- Delivery failure -----------------------------------------------------

	/**
	 * The crate could not be dealt after the key was already spent. The funding
	 * stays in the purse: nothing is invented as a consolation prize, we simply
	 * decline to claw back GC the player can now see for a crate we failed to
	 * hand over.
	 */
	@Test
	public void anUndeliverableCrateLeavesItsPriceInThePurse()
	{
		seedEstablishedAccount();
		chestService.deliverable = false;

		Assert.assertTrue(consignment.offerOrRoll(10));
		Assert.assertTrue(consignment.accept(11));

		Assert.assertEquals((long) Tuning.CHEST_PRICE_GC.get(Tuning.Chest.GILDED),
			stateService.get().getGc());
		Assert.assertEquals("the key is still spent — the player was asked and answered",
			consignment.currentDayKey(), stateService.get().getConsignmentDayKey());
	}

	// --- The self-healing property --------------------------------------------

	/**
	 * Why losing the deferred roll is safe rather than lossy: advanceCycle never
	 * resets cycleProgress — only roll() does — so a dropped deferred roll leaves
	 * the state cycle-OVERDUE and the next advanceCycle returns true again.
	 *
	 * <p>This is the load-bearing assumption behind every failure path in
	 * ConsignmentService, so it is pinned here directly against StyleService
	 * rather than inferred.
	 */
	@Test
	public void aDroppedDeferredRollLeavesTheCycleOverdue()
	{
		stateService.mutate(s -> s
			.withAllowedStyle(AttackStyle.MELEE.name())
			.withCycleTarget(2)
			.withCycleProgress(0));

		Assert.assertFalse("one contract in, not due yet", styleService.advanceCycle(null));
		Assert.assertTrue("second contract: the roll comes due", styleService.advanceCycle(null));

		// the offer was armed and then lost — a crash, a kill -9, a profile switch
		stateService.mutate(s -> s.withStyleRollOwed(true));
		stateService.mutate(s -> s.withStyleRollOwed(false)); // dropped without rolling

		Assert.assertTrue("the cycle is still overdue, so the wheel is re-owed automatically",
			styleService.advanceCycle(null));
		Assert.assertTrue("progress kept climbing past the target — only roll() ever resets it",
			stateService.get().getCycleProgress() > stateService.get().getCycleTarget());

		// and the moment a roll actually happens, the cycle finally clears
		styleService.roll(1);
		Assert.assertEquals(0.0, stateService.get().getCycleProgress(), 0.0001);
		Assert.assertFalse(styleService.advanceCycle(null));
	}

	// --- Guards ---------------------------------------------------------------

	@Test
	public void resolvingWithNoOfferLiveDoesNothing()
	{
		seedEstablishedAccount();
		long styleRolledBefore = stateService.get().getStyleRolledAtMs();

		Assert.assertFalse(consignment.accept(1));
		Assert.assertFalse(consignment.decline(1));
		consignment.abandon();

		Assert.assertEquals(styleRolledBefore, stateService.get().getStyleRolledAtMs());
		Assert.assertNull(stateService.get().getConsignmentDayKey());
		Assert.assertNull(chestService.openedTier);
	}

	@Test
	public void anOfferCannotBeAnsweredTwice()
	{
		seedEstablishedAccount();
		Assert.assertTrue(consignment.offerOrRoll(10));
		Assert.assertTrue(consignment.accept(11));

		Assert.assertFalse("a second answer must not deal a second crate",
			consignment.accept(12));
		Assert.assertFalse(consignment.decline(12));
		Assert.assertEquals("a free crate must still have cost the purse nothing",
			0L, stateService.get().getGc());
	}
}

package com.gachaman.service;

import com.gachaman.model.*;
import com.gachaman.persist.*;
import java.util.*;
import org.junit.*;

/**
 * The orphaned-party-offer surface: what a click on a party offer does with no
 * vote session behind it, and that demoting them back to personal offers keeps
 * every contract term intact ("rolls cannot be undone").
 *
 * Headless with a null client: none of hasPendingOffers, hasPendingPartyOffers,
 * demotePartyOffers or acceptOffer/acceptInternal reads the client — only
 * rollOffers does, which is why the offers here are seeded through the state
 * service instead of rolled.
 */
public class TaskServicePartyOfferTest
{
	private GachaStateService stateService;
	private TaskService taskService;

	private static GachaStateService inMemoryStateService()
	{
		StateStore store = new StateStore(null, null, null)
		{
			@Override
			public void save(GachaState state)
			{
			}

			@Override
			public void save(GachaState state, boolean flushDiskNow)
			{
			}

			@Override
			public GachaState load()
			{
				return null; // forces a fresh in-memory state
			}
		};
		GachaStateService service = new GachaStateService(store);
		service.load(3);
		return service;
	}

	@Before
	public void setUp()
	{
		stateService = inMemoryStateService();
		CreditSink creditSink = new CreditSink(stateService);
		ComplianceService complianceService = new ComplianceService(stateService, creditSink, null, null);
		CeremonyBus ceremonyBus = new CeremonyBus();
		StyleService styleService = StyleFixture.styleService(stateService, complianceService, ceremonyBus,
			new GachaRng(1L));
		com.gachaman.data.MonsterTable monsterTable =
			com.gachaman.data.MonsterTable.load(new com.google.gson.Gson());
		taskService = new TaskService(null, stateService, creditSink, complianceService,
			styleService, ceremonyBus, new GachaRng(1L), monsterTable,
			// null Client already means these tests never reach rollOffers()
			null, null,
			// The three collaborators added with the Preferred Weapon and the
			// Consignment are unwired here: no contract in this file pays per kill,
			// so the award branch (the only reader of the weapon pair) is never
			// reached, and no completion here tips the style cycle.
			null, null, null);
	}

	private static List<TaskOffer> fourOffers(boolean partyRoll)
	{
		List<TaskOffer> offers = new ArrayList<>(4);
		offers.add(new TaskOffer(TaskDifficulty.EASY, "Goblin", 2, 15, 7, 400,
			new ArrayList<>(), false, partyRoll));
		offers.add(new TaskOffer(TaskDifficulty.MEDIUM, "Hill Giant", 28, 40, 12, 1100,
			Arrays.asList(new SideBet(SideBet.Kind.BIG_HIT, 30, 0, true, false, 250)),
			false, partyRoll));
		offers.add(new TaskOffer(TaskDifficulty.HARD, "Blue dragon", 111, 25, 30, 3200,
			new ArrayList<>(), true, partyRoll));
		offers.add(new TaskOffer(TaskDifficulty.EASY, "Cow", 2, 20, 5, 300,
			new ArrayList<>(), false, partyRoll));
		return offers;
	}

	private void seedOffers(boolean partyRoll)
	{
		List<TaskOffer> offers = fourOffers(partyRoll);
		stateService.mutate(s -> s.withPendingOffers(offers));
	}

	/** The defect itself: with no vote session the click accepts nothing at all. */
	@Test
	public void orphanedPartyOfferClickAcceptsNothing()
	{
		seedOffers(true);
		final int[] voted = {-1};
		taskService.setPartyVoteHook(i -> voted[0] = i);

		Assert.assertTrue("acceptOffer reports success even though nothing is accepted",
			taskService.acceptOffer(0));

		Assert.assertNull("a party offer must never bind a contract by itself",
			stateService.get().getActiveTask());
		Assert.assertEquals("the offers stay pending, so the roll gate stays shut",
			4, stateService.get().getPendingOffers().size());
		Assert.assertEquals("the click was consumed as a vote", 0, voted[0]);
	}

	/** Rolls cannot be undone: demotion may only flip the party flag. */
	@Test
	public void demotePreservesEveryContractExactly()
	{
		List<TaskOffer> original = fourOffers(true);
		stateService.mutate(s -> s.withPendingOffers(original));

		taskService.demotePartyOffers();

		List<TaskOffer> after = stateService.get().getPendingOffers();
		Assert.assertEquals(original.size(), after.size());
		for (int i = 0; i < original.size(); i++)
		{
			TaskOffer before = original.get(i);
			TaskOffer now = after.get(i);
			Assert.assertEquals(before.getDifficulty(), now.getDifficulty());
			Assert.assertEquals(before.getMonsterName(), now.getMonsterName());
			Assert.assertEquals(before.getMonsterCombatLevel(), now.getMonsterCombatLevel());
			Assert.assertEquals(before.getKillsRequired(), now.getKillsRequired());
			Assert.assertEquals(before.getPerKillGc(), now.getPerKillGc());
			Assert.assertEquals(before.getCompletionGc(), now.getCompletionGc());
			Assert.assertEquals(before.isRedemption(), now.isRedemption());
			Assert.assertEquals(before.getSideBets(), now.getSideBets());
			Assert.assertFalse("only the party flag may change", now.isPartyRoll());
		}
	}

	/** After demotion the same scroll signs a plain solo contract. */
	@Test
	public void demotedOfferAcceptsAsPersonalContract()
	{
		seedOffers(true);
		taskService.demotePartyOffers();

		Assert.assertTrue(taskService.acceptOffer(1));

		Assert.assertNotNull(stateService.get().getActiveTask());
		Assert.assertEquals("Hill Giant", stateService.get().getActiveTask().getMonsterName());
		Assert.assertNull("a demoted offer must never bind a SHARED contract",
			stateService.get().getActiveTask().getPartyLabel());
		Assert.assertFalse(stateService.get().getActiveTask().isParty());
		Assert.assertTrue(stateService.get().getPendingOffers().isEmpty());
	}

	/**
	 * The load-time recovery sweep runs on every single login, so demotion has
	 * to be a no-op on anything that is not a live party set.
	 */
	@Test
	public void demoteIsIdempotentAndIgnoresPersonalOffers()
	{
		seedOffers(true);
		taskService.demotePartyOffers();
		List<TaskOffer> once = stateService.get().getPendingOffers();
		taskService.demotePartyOffers();
		Assert.assertEquals(once, stateService.get().getPendingOffers());

		List<TaskOffer> personal = fourOffers(false);
		stateService.mutate(s -> s.withPendingOffers(personal));
		taskService.demotePartyOffers();
		Assert.assertEquals(personal, stateService.get().getPendingOffers());

		stateService.mutate(s -> s.withPendingOffers(new ArrayList<>()));
		taskService.demotePartyOffers(); // must not throw on an empty board
		Assert.assertTrue(stateService.get().getPendingOffers().isEmpty());
	}

	/** The predicate the recovery sweep gates on, over every board state. */
	@Test
	public void hasPendingPartyOffersPredicate()
	{
		Assert.assertFalse("an untouched board has nothing to recover",
			taskService.hasPendingPartyOffers());

		seedOffers(true);
		Assert.assertTrue(taskService.hasPendingPartyOffers());

		taskService.demotePartyOffers();
		Assert.assertFalse("demotion is what clears the sweep's trigger",
			taskService.hasPendingPartyOffers());
		Assert.assertTrue("...without clearing the offers themselves",
			taskService.hasPendingOffers());

		seedOffers(false);
		Assert.assertFalse(taskService.hasPendingPartyOffers());

		stateService.mutate(s -> s.withPendingOffers(new ArrayList<>()));
		Assert.assertFalse(taskService.hasPendingPartyOffers());
	}
}

package com.gachaman.service;

import com.gachaman.*;
import com.gachaman.model.*;
import org.junit.*;

/**
 * The Ante's two pure rules: what a stake is worth, and which contracts may
 * carry one. Both are arithmetic over a purse and an enum, so they are testable
 * in isolation — the escrow itself needs a state service and lives in
 * {@link TaskServiceAnteTest}.
 */
public class AnteStakeTest
{
	private static TaskOffer offer(TaskDifficulty difficulty)
	{
		return new TaskOffer(difficulty, "Goblin", 2, 10, 8, 250, null, false, false);
	}

	// --- A. eligibility: the hardest contracts only ---

	@Test
	public void onlyInsaneContractsCanCarryTheAnte()
	{
		Assert.assertTrue(TaskService.anteEligible(offer(TaskDifficulty.INSANE)));
		Assert.assertFalse(TaskService.anteEligible(offer(TaskDifficulty.HARD)));
		Assert.assertFalse(TaskService.anteEligible(offer(TaskDifficulty.MEDIUM)));
		Assert.assertFalse(TaskService.anteEligible(offer(TaskDifficulty.EASY)));
	}

	@Test
	public void anAbsentOfferIsNeverEligible()
	{
		// the accept path asks this before pricing anything; a throw here would
		// take the CONTRACT down with the wager
		Assert.assertFalse(TaskService.anteEligible(null));
	}

	@Test
	public void aPartyFlaggedInsaneOfferIsStillEligible()
	{
		// the party path routes through the same predicate, so the party flag
		// must not accidentally disqualify a contract the party voted for
		TaskOffer partyOffer = new TaskOffer(TaskDifficulty.INSANE, "Goblin", 2, 10, 8, 250,
			null, false, true);
		Assert.assertTrue(TaskService.anteEligible(partyOffer));
	}

	// --- B. the purse floor ---

	@Test
	public void aPurseUnderTheFloorIsOfferedNoWager()
	{
		Assert.assertEquals(0, TaskService.anteStakeFor(0, 50));
		Assert.assertEquals(0, TaskService.anteStakeFor(Tuning.ANTE_MIN_PURSE_GC - 1, 50));
		Assert.assertEquals("a broke player must not be taxed for being broke", 0,
			TaskService.anteStakeFor(Tuning.ANTE_MIN_PURSE_GC - 1, Tuning.ANTE_MIN_PERCENT));
	}

	@Test
	public void exactlyTheFloorIsAlreadyEnough()
	{
		Assert.assertEquals(Tuning.ANTE_MIN_PURSE_GC * Tuning.ANTE_MIN_PERCENT / 100,
			TaskService.anteStakeFor(Tuning.ANTE_MIN_PURSE_GC, Tuning.ANTE_MIN_PERCENT));
	}

	@Test
	public void aNegativePurseCannotProduceANegativeStake()
	{
		// a corrupt save must not hand the player GC by "staking" a debt
		Assert.assertEquals(0, TaskService.anteStakeFor(-5000, 50));
	}

	// --- C. the percent band ---

	@Test
	public void theStakeIsThePercentOfThePurse()
	{
		Assert.assertEquals(100, TaskService.anteStakeFor(1000, 10));
		Assert.assertEquals(300, TaskService.anteStakeFor(1000, 30));
		Assert.assertEquals(500, TaskService.anteStakeFor(1000, 50));
	}

	@Test
	public void percentsOutsideTheBandAreClampedIntoIt()
	{
		Assert.assertEquals("below the band reads as the minimum",
			TaskService.anteStakeFor(1000, Tuning.ANTE_MIN_PERCENT),
			TaskService.anteStakeFor(1000, 1));
		Assert.assertEquals("above the band reads as the maximum",
			TaskService.anteStakeFor(1000, Tuning.ANTE_MAX_PERCENT),
			TaskService.anteStakeFor(1000, 9999));
	}

	@Test
	public void zeroPercentIsDisarmedRatherThanClampedUpToTheMinimum()
	{
		// the arming field's "no wager" value is 0, and it travels through this
		// same function on every accept — clamping it up would stake a player
		// who never armed anything
		Assert.assertEquals(0, TaskService.anteStakeFor(1_000_000, 0));
		Assert.assertEquals(0, TaskService.anteStakeFor(1_000_000, -20));
	}

	// --- D. the absolute cap ---

	@Test
	public void aRichPurseIsCappedInAbsoluteGc()
	{
		Assert.assertEquals(Tuning.ANTE_MAX_GC, TaskService.anteStakeFor(10_000_000, 50));
		Assert.assertEquals("one contract must never be an economy-sized swing",
			Tuning.ANTE_MAX_GC, TaskService.anteStakeFor(Long.MAX_VALUE / 100, 50));
	}

	@Test
	public void theCapBitesExactlyAtItsThreshold()
	{
		long atCap = Tuning.ANTE_MAX_GC * 100L / Tuning.ANTE_MAX_PERCENT;
		Assert.assertEquals(Tuning.ANTE_MAX_GC,
			TaskService.anteStakeFor(atCap, Tuning.ANTE_MAX_PERCENT));
		Assert.assertTrue("just under the threshold must still be under the cap",
			TaskService.anteStakeFor(atCap - 100, Tuning.ANTE_MAX_PERCENT) < Tuning.ANTE_MAX_GC);
	}

	// --- E. the invariant the escrow depends on ---

	@Test
	public void theStakeNeverExceedsThePurse()
	{
		// acceptInternal subtracts this straight off the balance inside a mutate;
		// a stake larger than the purse would sign a contract with negative GC
		for (long gc = 0; gc <= 20_000; gc += 137)
		{
			for (int percent = 0; percent <= 60; percent += 5)
			{
				int stake = TaskService.anteStakeFor(gc, percent);
				Assert.assertTrue("stake " + stake + " over purse " + gc, stake <= gc);
				Assert.assertTrue("negative stake at gc " + gc, stake >= 0);
			}
		}
	}

	@Test
	public void aFatterPurseNeverStakesLess()
	{
		int previous = 0;
		for (long gc = 0; gc <= 60_000; gc += 250)
		{
			int stake = TaskService.anteStakeFor(gc, Tuning.ANTE_MAX_PERCENT);
			Assert.assertTrue("stake fell from " + previous + " to " + stake + " at gc " + gc,
				stake >= previous);
			previous = stake;
		}
	}
}

package com.gachaman.service;

import com.gachaman.data.*;
import com.gachaman.model.*;
import com.google.gson.*;
import java.io.*;
import java.nio.charset.*;
import java.util.*;
import org.junit.*;

/**
 * A contract on a monster melee cannot reach is unwinnable for a player the
 * wheel has locked to melee, so those monsters must never be dealt to one.
 *
 * <p>The flag is about REACH, never damage — a monster that merely resists melee
 * stays rollable. The dataset assertions below are the guard on that
 * distinction: they pin both the monsters that carry the flag and the two
 * instructive near-misses that must NOT, because a false positive silently
 * deletes a monster from every melee player's pool.
 */
public class MeleeReachTest
{
	private static List<MonsterTable.Monster> monsters;

	@BeforeClass
	public static void load() throws Exception
	{
		try (InputStreamReader reader = new InputStreamReader(
			MeleeReachTest.class.getResourceAsStream("/com/gachaman/data/monsters.json"),
			StandardCharsets.UTF_8))
		{
			monsters = new Gson().fromJson(reader, Shape.class).monsters;
		}
	}

	private static class Shape
	{
		List<MonsterTable.Monster> monsters;
	}

	private static MonsterTable.Monster named(String name)
	{
		return monsters.stream().filter(m -> m.getName().equals(name)).findFirst()
			.orElseThrow(() -> new AssertionError("not in monsters.json: " + name));
	}

	@Test
	public void theFlaggedSetIsExactlyWhatWasConfirmed()
	{
		Set<String> flagged = new TreeSet<>();
		for (MonsterTable.Monster m : monsters)
		{
			if (m.isMeleeUnreachable())
			{
				flagged.add(m.getName());
			}
		}
		// every one of these was confirmed twice: surveyed, then re-checked by an
		// independent pass told to disagree by default
		Assert.assertEquals(
			new TreeSet<>(Arrays.asList("Cave kraken", "Kraken", "The Leviathan",
				"TzKal-Zuk", "Veiled kraken")),
			flagged);
	}

	@Test
	public void theNearMissesStayRollable()
	{
		// Ducks swim, but they also walk ashore, and melee connects there. This
		// was the first candidate flagged and the check overturned it.
		Assert.assertFalse(named("Duck").isMeleeUnreachable());
		// Zalcano is immune to conventional combat ENTIRELY — ranged and magic
		// fare no better, so calling it melee-unreachable would say something
		// untrue and would hide it from styles that are equally stuck.
		Assert.assertFalse(named("Zalcano").isMeleeUnreachable());
	}

	@Test
	public void aMeleeLockedRollNeverOffersOneOfThem()
	{
		GachaRng rng = new GachaRng(20260814L);
		for (int trial = 0; trial < 400; trial++)
		{
			for (int cb = 60; cb <= 126; cb += 11)
			{
				List<TaskOffer> offers = TaskGenerator.generateOffers(monsters, cb, 99,
					true, null, false, 0, true, rng);
				for (TaskOffer offer : offers)
				{
					Assert.assertFalse("melee-locked roll offered " + offer.getMonsterName(),
						named(offer.getMonsterName()).isMeleeUnreachable());
				}
			}
		}
	}

	/**
	 * Every confirmed monster is ALREADY unrollable for a reason that predates
	 * this flag, so the filter is a guard rather than a fix today.
	 *
	 * <p>This test exists to say that out loud, because the flag reads like it is
	 * doing work and is not: two are slayer-task-only, and the rest sit above the
	 * highest combat cap the generator can produce (combat 126 x the INSANE
	 * fraction of 1.35 = 170). If a future dataset adds a LOW-level monster melee
	 * cannot reach — the case the flag was actually built for — this test starts
	 * failing and should be updated to assert the new monster is gated by the
	 * filter rather than by its level.
	 */
	@Test
	public void everyFlaggedMonsterIsAlreadyGatedWithoutTheFlag()
	{
		int cap = (int) Math.floor(126 * TaskDifficulty.INSANE.getCbCapFraction());
		for (MonsterTable.Monster m : monsters)
		{
			if (!m.isMeleeUnreachable())
			{
				continue;
			}
			Assert.assertTrue(m.getName() + " is now reachable by a roll — the melee"
					+ " filter is doing real work and this test needs rewriting",
				m.isSlayerTaskOnly() || m.getCombatLevel() > cap);
		}
	}

	/**
	 * The filter must gate MELEE specifically, not delete monsters outright — so
	 * it is asserted directly rather than through a roll, which cannot reach any
	 * of them today for the reasons above.
	 */
	@Test
	public void theFilterOnlyBitesWhenSomeoneIsLockedToMelee()
	{
		MonsterTable.Monster unreachable = named("Cave kraken");
		List<MonsterTable.Monster> pool = Collections.singletonList(unreachable);
		// slayer 99 and quest gating off, so the ONLY thing that can exclude it
		// here is the melee flag — slayerTaskOnly is filtered in generateOffers
		Assert.assertTrue(unreachable.isMeleeUnreachable());
		Assert.assertFalse(pool.stream()
			.filter(m -> !m.isMeleeUnreachable())
			.findAny().isPresent());
		Assert.assertTrue(pool.stream()
			.filter(m -> true)
			.findAny().isPresent());
	}
}

package com.gachaman.service;

import com.gachaman.data.*;
import com.gachaman.model.*;
import com.google.gson.*;
import java.io.*;
import java.nio.charset.*;
import java.util.*;
import org.junit.*;

/**
 * A quest lock is a HARD gate: a monster behind an unfinished quest cannot be
 * reached or damaged, and a Gachaman contract cannot be abandoned. So the pool
 * is filtered before the roll, and everything below exists to prove the filter
 * fails in the safe direction — offering LESS on a bad answer, never a contract
 * the player cannot start.
 */
public class QuestGatingTest
{
	private static List<MonsterTable.Monster> monsters;

	@BeforeClass
	public static void load() throws Exception
	{
		try (InputStreamReader reader = new InputStreamReader(
			QuestGatingTest.class.getResourceAsStream("/com/gachaman/data/monsters.json"),
			StandardCharsets.UTF_8))
		{
			monsters = new Gson().fromJson(reader, MonstersShape.class).monsters;
		}
	}

	private static class MonstersShape
	{
		List<MonsterTable.Monster> monsters;
	}

	private static MonsterTable.Monster monster(String name, int cb, String... quests)
	{
		return new MonsterTable.Monster(name, cb, List.of("starter"), false, 0, false, false, false,
			List.of(quests));
	}

	// --- the predicate ------------------------------------------------------

	@Test
	public void anUngatedMonsterIsAlwaysSatisfied()
	{
		MonsterTable.Monster free = monster("Chicken", 1);
		Assert.assertTrue(TaskGenerator.questsSatisfied(free, Set.of()));
		Assert.assertTrue(TaskGenerator.questsSatisfied(free, null));
		Assert.assertTrue(TaskGenerator.questsSatisfied(free, Set.of("PRIEST_IN_PERIL")));
	}

	@Test
	public void nullMeansGatingOffButEmptyMeansAPlayerWhoHasFinishedNothing()
	{
		MonsterTable.Monster gated = monster("Banshee", 23, "PRIEST_IN_PERIL");
		// the two are NOT interchangeable: null is the mixed-version fallback
		Assert.assertTrue(TaskGenerator.questsSatisfied(gated, null));
		Assert.assertFalse(TaskGenerator.questsSatisfied(gated, Set.of()));
	}

	@Test
	public void everyListedQuestIsRequired()
	{
		MonsterTable.Monster nex = monster("Nex", 1001, "THE_FROZEN_DOOR", "TROLL_STRONGHOLD");
		Assert.assertFalse(TaskGenerator.questsSatisfied(nex, Set.of("THE_FROZEN_DOOR")));
		Assert.assertFalse(TaskGenerator.questsSatisfied(nex, Set.of("TROLL_STRONGHOLD")));
		Assert.assertTrue(TaskGenerator.questsSatisfied(nex,
			Set.of("THE_FROZEN_DOOR", "TROLL_STRONGHOLD")));
	}

	@Test
	public void anUnrecognisedNameWithholdsTheMonsterRatherThanOfferingIt()
	{
		// a typo can never be satisfied, so the monster stays locked — the
		// direction a bad dataset should fail in
		MonsterTable.Monster typo = monster("Ghost", 20, "PREIST_IN_PERIL");
		Assert.assertFalse(TaskGenerator.questsSatisfied(typo, Set.of("PRIEST_IN_PERIL")));
	}

	// --- the pool -----------------------------------------------------------

	@Test
	public void aQuestlessAccountIsNeverOfferedAQuestLockedMonster()
	{
		Map<String, MonsterTable.Monster> byName = new HashMap<>();
		for (MonsterTable.Monster m : monsters)
		{
			byName.put(m.getName(), m);
		}
		GachaRng rng = new GachaRng(4242L);
		for (int i = 0; i < 400; i++)
		{
			for (TaskOffer offer : TaskGenerator.generateOffers(monsters, 60 + (i % 60), 99,
				true, Set.of(), false, rng))
			{
				MonsterTable.Monster picked = byName.get(offer.getMonsterName());
				Assert.assertNotNull(offer.getMonsterName(), picked);
				Assert.assertTrue(offer.getMonsterName() + " needs "
					+ picked.getQuests() + " and should not have been offered",
					picked.getQuests() == null || picked.getQuests().isEmpty());
			}
		}
	}

	@Test
	public void finishingTheQuestPutsTheMonsterBackInThePool()
	{
		List<MonsterTable.Monster> pool = List.of(
			monster("Cow", 2),
			monster("Crawling Hand", 8, "PRIEST_IN_PERIL"));
		Assert.assertTrue(seenNames(pool, Set.of()).contains("Cow"));
		Assert.assertFalse(seenNames(pool, Set.of()).contains("Crawling Hand"));
		Assert.assertTrue(seenNames(pool, Set.of("PRIEST_IN_PERIL")).contains("Crawling Hand"));
	}

	private static Set<String> seenNames(List<MonsterTable.Monster> pool, Set<String> completed)
	{
		Set<String> names = new HashSet<>();
		GachaRng rng = new GachaRng(9L);
		for (int i = 0; i < 60; i++)
		{
			for (TaskOffer offer : TaskGenerator.generateOffers(pool, 40, 99, true, completed,
				false, rng))
			{
				names.add(offer.getMonsterName());
			}
		}
		return names;
	}

	/**
	 * The pool decides how many values {@code rng.pick} draws against, and a
	 * different bound consumes a different number of {@code Random.next()}
	 * calls. That is the whole reason quest state is transmitted rather than
	 * read locally, so it is worth pinning that it really does move the board.
	 */
	@Test
	public void adifferentQuestSetDealsADifferentBoard()
	{
		List<String> withNone = names(TaskGenerator.generateOffers(monsters, 90, 99, true,
			Set.of(), false, new GachaRng(77L)));
		List<String> withPip = names(TaskGenerator.generateOffers(monsters, 90, 99, true,
			Set.of("PRIEST_IN_PERIL"), false, new GachaRng(77L)));
		Assert.assertNotEquals(withNone, withPip);
		// and identical inputs still deal identically, or nothing else holds
		Assert.assertEquals(withNone, names(TaskGenerator.generateOffers(monsters, 90, 99, true,
			Set.of(), false, new GachaRng(77L))));
	}

	private static List<String> names(List<TaskOffer> offers)
	{
		List<String> names = new ArrayList<>(offers.size());
		for (TaskOffer offer : offers)
		{
			names.add(offer.getMonsterName());
		}
		return names;
	}

	@Test
	public void theDatasetGatesTheMonstersItClaimsTo()
	{
		int gated = 0;
		for (MonsterTable.Monster m : monsters)
		{
			if (m.getQuests() != null && !m.getQuests().isEmpty())
			{
				gated++;
			}
		}
		Assert.assertTrue("expected the bundled table to carry quest gates", gated >= 100);
	}
}

package com.gachaman.persist;

import com.gachaman.model.*;
import com.google.gson.*;
import java.io.*;
import java.nio.charset.*;
import java.util.*;
import java.util.zip.*;
import org.junit.*;

/**
 * A profile saved by an older build must still load after a feature is removed.
 *
 * <p>Removing Prestige and the Charter Office deleted three PERSISTED fields —
 * {@code prestigeRank}, {@code charterHold}, {@code charterDayKey}. Every
 * existing player's stored blob still contains them, and one of them
 * ({@code charterHold}) is an object whose class no longer exists at all.
 *
 * <p>Nothing else in the suite covers this: every other codec test round-trips
 * a state the CURRENT build wrote, which by construction can never carry a
 * retired field. If this assumption is wrong the failure is silent and total —
 * {@code decode} returns null, the profile reads as a fresh account, and the
 * player's cards and GC are gone on first launch.
 */
public class LegacyStateCompatTest
{
	private final StateCodec codec = new StateCodec(new Gson());

	/** Rebuilds the envelope exactly as an older StateCodec would have written it. */
	private static String legacyBlob(String payload) throws Exception
	{
		JsonObject envelope = new JsonObject();
		envelope.addProperty("version", GachaState.SCHEMA_VERSION);
		envelope.addProperty("sha256", StateCodec.sha256(payload));
		envelope.addProperty("payload", payload);
		ByteArrayOutputStream bytes = new ByteArrayOutputStream();
		try (Writer w = new OutputStreamWriter(new GZIPOutputStream(bytes), StandardCharsets.UTF_8))
		{
			w.write(envelope.toString());
		}
		return Base64.getEncoder().encodeToString(bytes.toByteArray());
	}

	@Test
	public void aProfileCarryingRetiredFieldsStillLoads() throws Exception
	{
		// a state the current build wrote, with the three retired fields spliced
		// back in exactly where an older build would have put them
		String current = new Gson().toJson(
			GachaState.fresh(42).withGc(98765).withTaint(2).withAllowedStyle("RANGED"));
		Assert.assertTrue("expected a JSON object", current.startsWith("{"));
		String legacy = "{"
			+ "\"prestigeRank\":3,"
			+ "\"charterDayKey\":\"2026-D220\","
			+ "\"charterHold\":{\"monsterName\":\"Gargoyle\",\"priceGc\":1500,"
			+ "\"expiresAtMs\":1750000000000},"
			+ current.substring(1);

		GachaState decoded = codec.decode(legacyBlob(legacy));

		Assert.assertNotNull("a pre-removal profile failed to decode — every existing"
			+ " player would lose their save", decoded);
		Assert.assertEquals(98765, decoded.getGc());
		Assert.assertEquals(2, decoded.getTaint());
		Assert.assertEquals("RANGED", decoded.getAllowedStyle());
	}

	@Test
	public void theRetiredFieldsAreGoneFromWhatWeWriteNow() throws Exception
	{
		// the other half: once loaded, the next save must not resurrect them
		String written = new Gson().toJson(GachaState.fresh(1));
		Assert.assertFalse(written.contains("prestigeRank"));
		Assert.assertFalse(written.contains("charterHold"));
		Assert.assertFalse(written.contains("charterDayKey"));
	}
}

package com.gachaman.persist;

import com.gachaman.model.*;
import com.gachaman.service.*;
import com.google.gson.*;
import java.util.*;
import org.junit.*;

public class StateCodecTest
{
	private final StateCodec codec = new StateCodec(new Gson());

	@Test
	public void roundTripPreservesState()
	{
		GachaState state = GachaState.fresh(42);
		List<OwnedCard> cards = new ArrayList<>();
		cards.add(new OwnedCard("u1", 1333, null, Variant.NORMAL, 123L, "chest:BATTERED", 0));
		cards.add(new OwnedCard("u2", -1, "dragon", Variant.HOLOGRAM, 456L, "chest:ORNATE", 7));
		state = state.withOwnedCards(cards).withGc(12345).withTaint(3).withAllowedStyle("MAGIC")
			.withStardust(5).withStardustBlessArmed(true)
			.withFreeCompactors(1).withFreeExtenders(1).withStarterVouchersGranted(true)
			.withDeedFragments(7).withFragmentDeedForged(true);

		GachaState decoded = codec.decode(codec.encode(state));
		Assert.assertNotNull(decoded);
		Assert.assertEquals(12345, decoded.getGc());
		Assert.assertEquals(3, decoded.getTaint());
		Assert.assertEquals("MAGIC", decoded.getAllowedStyle());
		Assert.assertEquals(2, decoded.getOwnedCards().size());
		Assert.assertEquals("dragon", decoded.getOwnedCards().get(1).getTierKey());
		Assert.assertTrue(decoded.getOwnedCards().get(1).isHologram());
		Assert.assertEquals(0, decoded.getOwnedCards().get(0).getKillsServed());
		Assert.assertEquals("the Service Record must survive gzip + SHA-256",
			7, decoded.getOwnedCards().get(1).getKillsServed());
		Assert.assertEquals(3, decoded.getDeededSlots().size()); // weapon + body + ammo
		Assert.assertEquals(5, decoded.getStardust());
		Assert.assertTrue(decoded.isStardustBlessArmed());
		Assert.assertEquals(1, decoded.getFreeCompactors());
		Assert.assertEquals(1, decoded.getFreeExtenders());
		Assert.assertTrue(decoded.isStarterVouchersGranted());
		Assert.assertEquals(7, decoded.getDeedFragments());
		Assert.assertTrue(decoded.isFragmentDeedForged());
	}

	@Test
	public void legacyOwnedCardDefaultsToZeroService()
	{
		// a card acquired before the Service Record existed: Gson leaves the
		// absent primitive at 0, which is the TRUTH for it — no service was ever
		// recorded. normalized() cannot help here (it backfills null COLLECTIONS
		// only, and it never descends into ownedCards), so the safe-default
		// choice is the whole migration story.
		OwnedCard legacy = new Gson().fromJson(
			"{\"uuid\":\"u\",\"cardId\":1333,\"variant\":\"NORMAL\"}", OwnedCard.class);
		Assert.assertEquals(0, legacy.getKillsServed());
	}

	@Test
	public void legacyPayloadNormalizesNewFields()
	{
		// a pre-feature save: none of the early-game fields exist in the JSON
		GachaState legacy = new Gson().fromJson("{\"gc\":5,\"totalTasksCompleted\":2}", GachaState.class);
		Assert.assertNull(legacy.getFirstsClaimed());
		GachaState normalized = legacy.normalized();
		Assert.assertEquals(5, normalized.getGc());
		Assert.assertNotNull(normalized.getFirstsClaimed());
		Assert.assertNotNull(normalized.getSpeciesDiscovered());
		Assert.assertNotNull(normalized.getSlotBestTierRank());
		Assert.assertNotNull(normalized.getTimeline());
		Assert.assertNotNull(normalized.getOwnedCards());
		Assert.assertNotNull(normalized.getDeededSlots());
		Assert.assertNotNull(normalized.getQueuedThemedChests());
		Assert.assertEquals(0, normalized.getStardust());
		Assert.assertFalse(normalized.isStardustBlessArmed());
		Assert.assertEquals(0, normalized.getFreeCompactors());
		Assert.assertEquals(0, normalized.getFreeExtenders());
		Assert.assertFalse("false flag is the migration trigger", normalized.isStarterVouchersGranted());
		Assert.assertEquals(0, normalized.getDeedFragments());
		Assert.assertFalse(normalized.isFragmentDeedForged());
	}

	@Test
	public void legacyPayloadWithoutPatronsNormalizesToEmpty()
	{
		// The Patron's Mark ledger did not exist when this save was written, so
		// zero shared contracts is not a lossy default — it is the only honest
		// one. It is also inert: an empty map means no top patron, no tier and
		// no mark, no Patrons tab, and nothing anywhere gates on the field.
		GachaState legacy = new Gson().fromJson("{\"gc\":5}", GachaState.class);
		Assert.assertNull(legacy.getPatrons());
		GachaState normalized = legacy.normalized();
		Assert.assertNotNull(normalized.getPatrons());
		Assert.assertTrue(normalized.getPatrons().isEmpty());
		Assert.assertNull(PatronMark.topKey(normalized.getPatrons()));
	}

	@Test
	public void aPreRenameLedgerIsDroppedRatherThanFailingTheWholeSave()
	{
		// the field was renamed rather than re-typed on purpose: the old
		// "partnerContracts" held a Map<String,Integer>, and a bare number where
		// Gson now expects an object throws and takes the ENTIRE save with it,
		// not just this one ledger. Under the new name Gson drops the old key as
		// unknown, which costs a cosmetic tally and nothing else.
		GachaState legacy = new Gson().fromJson(
			"{\"gc\":5,\"partnerContracts\":{\"Zezima\":3}}", GachaState.class);
		Assert.assertEquals(5, legacy.getGc());
		Assert.assertNull(legacy.getPatrons());
		Assert.assertTrue(legacy.normalized().getPatrons().isEmpty());
	}

	@Test
	public void patronsSurviveARoundTrip()
	{
		Map<String, PatronRecord> patrons = new LinkedHashMap<>();
		patrons.put("00112233445566aa", new PatronRecord("Zezima", 3, 1_700_000_000_000L));
		patrons.put("00112233445566bb", new PatronRecord("B0aty", 41, 1_700_000_005_000L));
		GachaState state = GachaState.fresh(42).withPatrons(patrons);

		GachaState decoded = codec.decode(codec.encode(state));
		Assert.assertNotNull(decoded);
		Map<String, PatronRecord> back = decoded.getPatrons();
		Assert.assertEquals(2, back.size());
		Assert.assertEquals(3, back.get("00112233445566aa").getCount());
		Assert.assertEquals("the label is persisted, not re-derived — a partner who"
			+ " never joins again still draws with a name",
			"B0aty", back.get("00112233445566bb").getName());
		Assert.assertEquals(1_700_000_005_000L,
			back.get("00112233445566bb").getLastSharedAt());
		// Gson rebuilds this as a LinkedTreeMap, so pin that the reader still
		// answers correctly against whatever map type comes back off disk
		Assert.assertEquals("00112233445566bb", PatronMark.topKey(back));
		Assert.assertEquals("a received key is normalized before lookup",
			41, PatronMark.countFor(back, "00112233445566BB"));
	}

	@Test
	public void legacyPayloadWithoutAContractLogNormalizesToEmpty()
	{
		// the Dossier did not exist when this save was written. An empty log is
		// inert: the totals fold to zero and the tab shows its empty note, so no
		// history is invented for a player who has none.
		GachaState legacy = new Gson().fromJson("{\"gc\":5}", GachaState.class);
		Assert.assertNull(legacy.getContractLog());
		GachaState normalized = legacy.normalized();
		Assert.assertNotNull(normalized.getContractLog());
		Assert.assertTrue(normalized.getContractLog().isEmpty());
		Assert.assertEquals(0, DossierSummary.of(normalized.getContractLog()).getContracts());
	}

	@Test
	public void contractLogSurvivesTheCodec()
	{
		GachaState state = GachaState.fresh(42).withContractLog(Arrays.asList(
			new ContractRecord(1700000000000L, "Goblin", "EASY", 15, 400, 60_000, "MELEE",
				0, null, false, false),
			new ContractRecord(1700000060000L, "Blue dragon", "HARD", 25, 3200, 900_000, "MAGIC",
				2, "Party of 3", true, true)));

		GachaState decoded = codec.decode(codec.encode(state));
		Assert.assertNotNull(decoded);
		List<ContractRecord> log = decoded.getContractLog();
		Assert.assertEquals(2, log.size());
		Assert.assertEquals("Goblin", log.get(0).getMonsterName());
		Assert.assertTrue(log.get(0).isClean());
		ContractRecord second = log.get(1);
		Assert.assertEquals(1700000060000L, second.getAt());
		Assert.assertEquals("HARD", second.getDifficulty());
		Assert.assertEquals(3200, second.getGc());
		Assert.assertEquals("MAGIC", second.getStyle());
		Assert.assertEquals("Party of 3", second.getParty());
		Assert.assertTrue(second.isCarried());
		Assert.assertTrue(second.isRedemption());
		Assert.assertEquals("the clean verdict is derived from a COUNT that must survive",
			2, second.getTaintedKills());
		Assert.assertFalse(second.isClean());
	}

	@Test
	public void aRecordFiledByAFutureBuildStillLoads()
	{
		// difficulty and style are persisted as plain strings, not enums: Gson maps
		// an unknown ENUM constant to null and would silently erase the filed fact,
		// whereas a string keeps it and leaves the renderer to fall back
		GachaState legacy = new Gson().fromJson(
			"{\"contractLog\":[{\"at\":5,\"monsterName\":\"Goblin\",\"difficulty\":\"NIGHTMARE\","
				+ "\"kills\":3,\"gc\":90,\"style\":\"DRAGONFIRE\"}]}", GachaState.class);
		ContractRecord record = legacy.normalized().getContractLog().get(0);
		Assert.assertEquals("NIGHTMARE", record.getDifficulty());
		Assert.assertEquals("DRAGONFIRE", record.getStyle());
		Assert.assertTrue("an absent taintedKills is zero, which reads clean", record.isClean());
	}

	@Test
	public void activeTaskPartyStylesSurviveTheCodec()
	{
		// partyStyles is the first enum collection nested inside activeTask, so
		// no persisted task has ever been round-tripped before this
		GachaState state = GachaState.fresh(42).withActiveTask(ActiveTask.builder()
			.difficulty(TaskDifficulty.EASY)
			.monsterName("Goblin")
			.killsRequired(10)
			.completionGc(1000)
			.partyLabel("Party of 3")
			.partyStyles(Arrays.asList(AttackStyle.MELEE, null, AttackStyle.MAGIC))
			.build());

		GachaState decoded = codec.decode(codec.encode(state));
		Assert.assertNotNull(decoded);
		List<AttackStyle> styles = decoded.getActiveTask().getPartyStyles();
		// Gson writes null ARRAY elements regardless of serializeNulls, so the
		// hole survives the trip — the null skip in distinctStyles is
		// load-bearing on the persistence path, not just the wire
		Assert.assertEquals(Arrays.asList(AttackStyle.MELEE, null, AttackStyle.MAGIC), styles);
	}

	@Test
	public void legacyActiveTaskDecodesNullPartyStyles()
	{
		// a shared contract signed before the snapshot existed
		GachaState legacy = new Gson().fromJson(
			"{\"gc\":5,\"activeTask\":{\"monsterName\":\"Goblin\",\"killsRequired\":10,"
				+ "\"partyLabel\":\"Party of 2\"}}", GachaState.class);
		Assert.assertNull(legacy.getActiveTask().getPartyStyles());
		// normalized() backfills TOP-LEVEL collections only; it never descends
		// into activeTask, so the null must stay a null the readers tolerate
		Assert.assertNull(legacy.normalized().getActiveTask().getPartyStyles());
	}

	@Test
	public void partyProposalIdSurvivesTheCodec()
	{
		// the ONLY handle that can reunite a restarted client with its own contract:
		// member ids are drawn fresh every RuneLite session, so nothing else on the
		// wire still identifies this party after a restart
		GachaState state = GachaState.fresh(42).withActiveTask(ActiveTask.builder()
			.difficulty(TaskDifficulty.EASY)
			.monsterName("Goblin")
			.killsRequired(10)
			.partyLabel("Party of 3")
			.partyProposalId(-8_070_450_532_247_928_833L)
			.build());

		GachaState decoded = codec.decode(codec.encode(state));
		Assert.assertNotNull(decoded);
		Assert.assertEquals("a 64-bit id must not be rebuilt through a double",
			Long.valueOf(-8_070_450_532_247_928_833L),
			decoded.getActiveTask().getPartyProposalId());
	}

	@Test
	public void aProposalIdOfZeroIsNotMistakenForALegacyContract()
	{
		// exactly why the field is BOXED: 0 is a perfectly legal proposal id, and a
		// primitive would make a live party indistinguishable from a save written
		// before the field existed — which is settled by the carry clause on sight
		GachaState state = GachaState.fresh(42).withActiveTask(ActiveTask.builder()
			.monsterName("Goblin")
			.partyLabel("Party of 2")
			.partyProposalId(0L)
			.build());

		GachaState decoded = codec.decode(codec.encode(state));
		Assert.assertNotNull(decoded);
		Assert.assertEquals(Long.valueOf(0L), decoded.getActiveTask().getPartyProposalId());
	}

	@Test
	public void legacyPartyContractDecodesANullProposalId()
	{
		// a shared contract signed before the id was persisted. It cannot be
		// rejoined by anyone, so the null must survive intact for
		// PartyRollService.resurrectPartyContract to spot it and convert — and
		// normalized() must not invent a value, since it backfills null COLLECTIONS
		// only and never descends into activeTask
		GachaState legacy = new Gson().fromJson(
			"{\"gc\":5,\"activeTask\":{\"monsterName\":\"Goblin\",\"killsRequired\":10,"
				+ "\"partyLabel\":\"Party of 2\"}}", GachaState.class);
		Assert.assertTrue(legacy.getActiveTask().isParty());
		Assert.assertNull(legacy.getActiveTask().getPartyProposalId());
		Assert.assertNull(legacy.normalized().getActiveTask().getPartyProposalId());
	}

	@Test
	public void aSoloContractCarriesNoProposalId()
	{
		// the solo accept path signs with null, so a solo task can never be
		// resurrected into a party session by a stray id left on the builder
		GachaState state = GachaState.fresh(42).withActiveTask(ActiveTask.builder()
			.monsterName("Goblin")
			.killsRequired(10)
			.build());

		GachaState decoded = codec.decode(codec.encode(state));
		Assert.assertNotNull(decoded);
		Assert.assertFalse(decoded.getActiveTask().isParty());
		Assert.assertNull(decoded.getActiveTask().getPartyProposalId());
	}

	@Test
	public void unknownStyleNameInAPersistedTaskBecomesNull()
	{
		// Gson's enum adapter maps an unrecognised name to null rather than
		// throwing, so a save from a build with more styles still loads
		GachaState legacy = new Gson().fromJson(
			"{\"activeTask\":{\"monsterName\":\"Goblin\",\"partyLabel\":\"Party of 2\","
				+ "\"partyStyles\":[\"MELEE\",\"DRAGONFIRE\"]}}", GachaState.class);
		Assert.assertEquals(Arrays.asList(AttackStyle.MELEE, null),
			legacy.getActiveTask().getPartyStyles());
	}

	@Test
	public void pendingPartyOffersRoundTrip()
	{
		// The whole party-deadlock defect rests on this asymmetry: the party FLAG
		// survives the save blob while the vote session that gives it meaning is
		// transient. Pin the persisted half so nobody "fixes" the orphan by
		// assuming the flag decays on its own.
		GachaState state = GachaState.fresh(42).withPendingOffers(Arrays.asList(
			new TaskOffer(TaskDifficulty.EASY, "Goblin", 2, 15, 7, 400,
				new ArrayList<>(), false, true),
			new TaskOffer(TaskDifficulty.HARD, "Blue dragon", 111, 25, 30, 3200,
				new ArrayList<>(), true, true)));

		GachaState decoded = codec.decode(codec.encode(state));
		Assert.assertNotNull(decoded);
		Assert.assertEquals(2, decoded.getPendingOffers().size());
		Assert.assertTrue(decoded.getPendingOffers().get(0).isPartyRoll());
		Assert.assertTrue(decoded.getPendingOffers().get(1).isPartyRoll());
		Assert.assertEquals("Blue dragon", decoded.getPendingOffers().get(1).getMonsterName());
	}

	@Test
	public void demotedOffersRoundTripAsPersonal()
	{
		// the recovery sweep's result has to be durable, or the board re-orphans
		// itself on the next login
		GachaState state = GachaState.fresh(42).withPendingOffers(Arrays.asList(
			new TaskOffer(TaskDifficulty.EASY, "Goblin", 2, 15, 7, 400,
				new ArrayList<>(), false, false)));

		GachaState decoded = codec.decode(codec.encode(state));
		Assert.assertNotNull(decoded);
		Assert.assertFalse(decoded.getPendingOffers().get(0).isPartyRoll());
		Assert.assertEquals(15, decoded.getPendingOffers().get(0).getKillsRequired());
	}

	@Test
	public void legacyOfferWithoutPartyFlagLoadsPersonal()
	{
		// a save from before the flag existed: Gson leaves the absent key false,
		// which is the safe side — an old offer must never demand a vote session
		GachaState legacy = new Gson().fromJson(
			"{\"pendingOffers\":[{\"monsterName\":\"Goblin\",\"killsRequired\":15}]}",
			GachaState.class);
		Assert.assertFalse(legacy.getPendingOffers().get(0).isPartyRoll());
		// normalized() only backfills NULL collections; it never inspects offers
		Assert.assertFalse(legacy.normalized().getPendingOffers().get(0).isPartyRoll());
	}

	@Test
	public void tamperedPayloadRefusesToLoad()
	{
		GachaState state = GachaState.fresh(3);
		String blob = codec.encode(state);
		// flip a chunk of the base64 body
		char[] chars = blob.toCharArray();
		int mid = chars.length / 2;
		chars[mid] = chars[mid] == 'A' ? 'B' : 'A';
		GachaState decoded = codec.decode(new String(chars));
		Assert.assertNull(decoded);
	}

	@Test
	public void sha256IsStable()
	{
		Assert.assertEquals(StateCodec.sha256("gachaman"), StateCodec.sha256("gachaman"));
		Assert.assertNotEquals(StateCodec.sha256("a"), StateCodec.sha256("b"));
	}

	@Test
	public void garbageReturnsNullNotThrow()
	{
		Assert.assertNull(codec.decode(null));
		Assert.assertNull(codec.decode(""));
		Assert.assertNull(codec.decode("not-base64!!"));
	}

	@Test
	public void savedAtStampsEveryBlobAndOrdersThem() throws Exception
	{
		// the stamp is what lets StateStore.load prefer the NEWER of the config
		// copy and the disk copy. Without it a client killed before RuneLite
		// flushed its config silently rolled the player back to an older save.
		StateCodec codec = new StateCodec(new com.google.gson.Gson());
		String first = codec.encode(GachaState.fresh(50));
		Thread.sleep(5);
		String second = codec.encode(GachaState.fresh(50));

		Assert.assertTrue("blobs must be stamped", codec.savedAt(first) > 0);
		Assert.assertTrue("later save must stamp later",
			codec.savedAt(second) > codec.savedAt(first));
	}

	@Test
	public void savedAtIsZeroForAnythingItCannotRead()
	{
		// pre-stamp saves and junk both sort oldest, so a stamped copy wins and
		// an unstamped pair falls back to the old config-first behaviour
		StateCodec codec = new StateCodec(new com.google.gson.Gson());
		Assert.assertEquals(0, codec.savedAt(null));
		Assert.assertEquals(0, codec.savedAt(""));
		Assert.assertEquals(0, codec.savedAt("not base64 gzip at all"));
	}
}

package com.gachaman;

import com.gachaman.model.*;
import org.junit.*;

/**
 * The wear stage is a pure function of one number and of nothing else. That is
 * the whole safety argument for this feature: because no state, no clock and no
 * RNG feeds it, "a worn card behaves exactly like a pristine one" is provable
 * here rather than asserted in a design doc.
 */
public class CardWearTest
{
	/**
	 * Every threshold, from both sides. Off-by-one on a milestone is the bug a
	 * player would actually notice — they hit 100 kills, look at the card, and
	 * it has not changed.
	 */
	@Test
	public void everyBoundaryExactly()
	{
		Assert.assertEquals(CardWear.NONE, Tuning.cardWear(99));
		Assert.assertEquals(CardWear.HAIRLINE, Tuning.cardWear(100));
		Assert.assertEquals(CardWear.HAIRLINE, Tuning.cardWear(399));
		Assert.assertEquals(CardWear.CRACKED, Tuning.cardWear(400));
		Assert.assertEquals(CardWear.CRACKED, Tuning.cardWear(999));
		Assert.assertEquals(CardWear.SHATTERED, Tuning.cardWear(1000));
	}

	/** A brand-new card, and a legacy save where killsServed backfilled to zero. */
	@Test
	public void aFreshCardIsPristine()
	{
		Assert.assertEquals(CardWear.NONE, Tuning.cardWear(0));
		Assert.assertEquals(CardWear.NONE, Tuning.cardWear(1));
	}

	/**
	 * killsServed is documented as monotonic, but a corrupted or hand-edited save
	 * must not throw or fall off the bottom of the switch. Negative means "no
	 * service", the same as zero.
	 */
	@Test
	public void nonsenseInputsDegradeToPristine()
	{
		Assert.assertEquals(CardWear.NONE, Tuning.cardWear(-1));
		Assert.assertEquals(CardWear.NONE, Tuning.cardWear(Integer.MIN_VALUE));
	}

	/** Past the top stage it saturates. There is no fifth, worse stage. */
	@Test
	public void theTopStageSaturates()
	{
		Assert.assertEquals(CardWear.SHATTERED, Tuning.cardWear(1001));
		Assert.assertEquals(CardWear.SHATTERED, Tuning.cardWear(1_000_000));
		Assert.assertEquals(CardWear.SHATTERED, Tuning.cardWear(Integer.MAX_VALUE));
	}

	/**
	 * Wear only ever accumulates. Because killsServed is permanent and monotonic,
	 * a card can never visibly heal — sweep the whole reachable ladder and prove
	 * the stage index never steps backwards.
	 */
	@Test
	public void wearNeverGoesBackwards()
	{
		int previous = -1;
		for (int kills = 0; kills <= 1200; kills++)
		{
			int stage = Tuning.cardWear(kills).ordinal();
			Assert.assertTrue("wear regressed at " + kills, stage >= previous);
			previous = stage;
		}
	}

	/**
	 * The thresholds are strictly ordered, so each stage is actually reachable.
	 * Collapsing two of them (say, both at 400) would silently delete a stage
	 * without failing anything else.
	 */
	@Test
	public void everyStageIsReachable()
	{
		Assert.assertTrue(Tuning.WEAR_HAIRLINE_KILLS < Tuning.WEAR_CRACKED_KILLS);
		Assert.assertTrue(Tuning.WEAR_CRACKED_KILLS < Tuning.WEAR_SHATTERED_KILLS);

		Assert.assertEquals(CardWear.HAIRLINE, Tuning.cardWear(Tuning.WEAR_HAIRLINE_KILLS));
		Assert.assertEquals(CardWear.CRACKED, Tuning.cardWear(Tuning.WEAR_CRACKED_KILLS));
		Assert.assertEquals(CardWear.SHATTERED, Tuning.cardWear(Tuning.WEAR_SHATTERED_KILLS));

		Assert.assertEquals(CardWear.NONE, Tuning.cardWear(Tuning.WEAR_HAIRLINE_KILLS - 1));
		Assert.assertEquals(CardWear.HAIRLINE, Tuning.cardWear(Tuning.WEAR_CRACKED_KILLS - 1));
		Assert.assertEquals(CardWear.CRACKED, Tuning.cardWear(Tuning.WEAR_SHATTERED_KILLS - 1));
	}

	/**
	 * The first threshold must stay at or above one. Wear is measured from the
	 * top band that CardRenderer reserves around the service pill, and the pill
	 * is only painted when killsServed &gt; 0 — a zero threshold would ask the
	 * crack router to steer around a badge that was never drawn.
	 */
	@Test
	public void theFirstThresholdImpliesAVisibleServicePill()
	{
		Assert.assertTrue("wear must not appear before the service pill does",
			Tuning.WEAR_HAIRLINE_KILLS >= 1);
	}

	/**
	 * The stage names are player-facing text and go through Java2D, which draws a
	 * tofu box for anything the sans-serif face has no glyph for.
	 */
	@Test
	public void displayNamesArePlainAscii()
	{
		Assert.assertEquals("", CardWear.NONE.getDisplayName());
		for (CardWear wear : CardWear.values())
		{
			Assert.assertTrue("non-ascii in " + wear,
				wear.getDisplayName().matches("[\\x20-\\x7E]*"));
		}
	}

	// --- the inverse, used only by ::gachawear ---

	/**
	 * The round trip, over every stage. wearKills lives in the same file as
	 * cardWear precisely so the two cannot drift, and this is the assertion that
	 * makes that guarantee real rather than a comment: retune a threshold and it
	 * still passes, add a stage and forget the inverse and it does not.
	 */
	@Test
	public void everyStageNamesItsOwnFloor()
	{
		for (CardWear wear : CardWear.values())
		{
			Assert.assertEquals("wearKills(" + wear + ") does not land on " + wear,
				wear, Tuning.cardWear(Tuning.wearKills(wear)));
		}
	}

	/**
	 * The floor is the FLOOR — one kill short of it must be a lower stage. A
	 * wearKills that returned the middle of a band would still pass the round
	 * trip above while making "::gachawear cracked" a lie about the number.
	 */
	@Test
	public void theFloorIsTheFirstKillOfItsStage()
	{
		Assert.assertEquals(0, Tuning.wearKills(CardWear.NONE));
		for (CardWear wear : CardWear.values())
		{
			if (wear != CardWear.NONE)
			{
				Assert.assertTrue(Tuning.cardWear(Tuning.wearKills(wear) - 1).ordinal()
					< wear.ordinal());
			}
		}
	}

	// --- CardWear.parse ---

	@Test
	public void parseTakesEveryStageNameInAnyCase()
	{
		for (CardWear wear : CardWear.values())
		{
			Assert.assertEquals(wear, CardWear.parse(wear.name()));
			Assert.assertEquals(wear, CardWear.parse(wear.name().toLowerCase(java.util.Locale.ROOT)));
			Assert.assertEquals(wear, CardWear.parse("  " + wear.name() + "  "));
		}
	}

	/**
	 * Null, not NONE. The caller's other reading of the argument is a raw kill
	 * count, so a stage default here would turn a typo into a wiped record.
	 */
	@Test
	public void parseRejectsAnythingThatIsNotAStage()
	{
		Assert.assertNull(CardWear.parse(null));
		Assert.assertNull(CardWear.parse(""));
		Assert.assertNull(CardWear.parse("   "));
		Assert.assertNull(CardWear.parse("shatter"));
		Assert.assertNull(CardWear.parse("shatteredd"));
		Assert.assertNull(CardWear.parse("100"));
		// the display name is prose, not an input token
		Assert.assertNull(CardWear.parse(CardWear.SHATTERED.getDisplayName()));
	}
}

package com.gachaman;

import com.gachaman.model.*;
import java.util.*;
import java.util.function.*;
import org.junit.*;

/**
 * The card-DB heal's remap-then-dedupe rule, in BOTH list orders.
 *
 * <p>A cache upgrade can merge two card groups into one, which leaves an owned
 * copy pointing at a card id that no longer exists. That copy is remapped
 * through the item index, and if the remap lands on a card the player already
 * owns in the same variant, the stale copy is dropped.
 *
 * <p>The regression these tests exist for: the drop used to depend on where
 * the stale copy sat in the list. Owned cards are stored in acquisition order
 * and the stale copy — minted under the older card DB — is almost always the
 * OLDER of the two, so in the common case NEITHER copy was dropped and the
 * album showed the duplicate twice. Every ordering assertion below is there to
 * keep that from coming back.
 */
public class HealStaleCardIdsTest
{
	private static final int MERGED = 4708; // the card that survived the merge
	private static final int STALE = 4712;  // an id the merge dissolved

	private static OwnedCard card(String uuid, int cardId, Variant variant, int killsServed)
	{
		return new OwnedCard(uuid, cardId, null, variant, 1L, "chest:GILDED", killsServed);
	}

	private static OwnedCard holo(String uuid, String tierKey)
	{
		return new OwnedCard(uuid, -1, tierKey, Variant.HOLOGRAM, 1L, "chest:ORNATE", 0);
	}

	/** A stand-in for the card DB: only the listed ids are stale. */
	private static IntUnaryOperator merges(int... staleToSurvivor)
	{
		Map<Integer, Integer> map = new HashMap<>();
		for (int i = 0; i < staleToSurvivor.length; i += 2)
		{
			map.put(staleToSurvivor[i], staleToSurvivor[i + 1]);
		}
		return id -> map.getOrDefault(id, -1);
	}

	// --- the ordering bug ---

	@Test
	public void staleCopyIsDroppedWhenItComesFirst()
	{
		// the common case: the stale copy was acquired first, so it leads
		List<OwnedCard> owned = Arrays.asList(
			card("stale", STALE, Variant.NORMAL, 0),
			card("genuine", MERGED, Variant.NORMAL, 0));

		List<OwnedCard> out = GachamanPlugin.healCardIds(owned, merges(STALE, MERGED));

		Assert.assertNotNull(out);
		Assert.assertEquals("the remapped duplicate must not survive alongside its twin",
			1, out.size());
		Assert.assertEquals("genuine", out.get(0).getUuid());
		Assert.assertEquals(MERGED, out.get(0).getCardId());
	}

	@Test
	public void staleCopyIsDroppedWhenItComesSecond()
	{
		// the order that already worked — pinned so a fix cannot trade one for
		// the other
		List<OwnedCard> owned = Arrays.asList(
			card("genuine", MERGED, Variant.NORMAL, 0),
			card("stale", STALE, Variant.NORMAL, 0));

		List<OwnedCard> out = GachamanPlugin.healCardIds(owned, merges(STALE, MERGED));

		Assert.assertNotNull(out);
		Assert.assertEquals(1, out.size());
		Assert.assertEquals("genuine", out.get(0).getUuid());
	}

	@Test
	public void twoStaleCopiesOfTheSameCardCollapseToOne()
	{
		// no healthy copy at all: one remapped survivor, not two
		List<OwnedCard> owned = Arrays.asList(
			card("a", STALE, Variant.NORMAL, 0),
			card("b", 4713, Variant.NORMAL, 0));

		List<OwnedCard> out = GachamanPlugin.healCardIds(
			owned, merges(STALE, MERGED, 4713, MERGED));

		Assert.assertNotNull(out);
		Assert.assertEquals(1, out.size());
		Assert.assertEquals(MERGED, out.get(0).getCardId());
	}

	// --- what the drop must NOT touch ---

	@Test
	public void preExistingHealthyDuplicatesAreLeftAlone()
	{
		// two genuine copies of one card is a legal thing to own — the heal is
		// not a general dedupe pass and must never eat one of them
		List<OwnedCard> owned = Arrays.asList(
			card("dup1", MERGED, Variant.NORMAL, 0),
			card("dup2", MERGED, Variant.NORMAL, 0),
			card("stale", STALE, Variant.NORMAL, 0));

		List<OwnedCard> out = GachamanPlugin.healCardIds(
			owned, merges(STALE, 5000)); // remaps somewhere else entirely

		Assert.assertNotNull(out);
		Assert.assertEquals(3, out.size());
		Assert.assertEquals("dup1", out.get(0).getUuid());
		Assert.assertEquals("dup2", out.get(1).getUuid());
		Assert.assertEquals(5000, out.get(2).getCardId());
	}

	@Test
	public void aDifferentVariantOfTheSameCardIsNotADuplicate()
	{
		// the key is (card, variant): a shiny and a normal are two collectibles
		List<OwnedCard> owned = Arrays.asList(
			card("stale", STALE, Variant.NORMAL, 0),
			card("shiny", MERGED, Variant.SHINY, 0));

		List<OwnedCard> out = GachamanPlugin.healCardIds(owned, merges(STALE, MERGED));

		Assert.assertNotNull(out);
		Assert.assertEquals(2, out.size());
		Assert.assertEquals(MERGED, out.get(0).getCardId());
		Assert.assertEquals(Variant.NORMAL, out.get(0).getVariant());
		Assert.assertEquals(Variant.SHINY, out.get(1).getVariant());
	}

	@Test
	public void hologramsAreNeverRemappedOrDropped()
	{
		// holograms carry cardId -1 and key on their tier; two of a tier is the
		// player's business, not the heal's
		List<OwnedCard> owned = Arrays.asList(
			holo("h1", "dragon"),
			holo("h2", "dragon"),
			card("stale", STALE, Variant.NORMAL, 0));

		List<OwnedCard> out = GachamanPlugin.healCardIds(owned, merges(STALE, MERGED, -1, 99));

		Assert.assertNotNull(out);
		Assert.assertEquals(3, out.size());
		Assert.assertEquals(-1, out.get(0).getCardId());
		Assert.assertEquals(-1, out.get(1).getCardId());
		Assert.assertEquals("dragon", out.get(0).getTierKey());
	}

	// --- what the remap carries ---

	@Test
	public void remapKeepsTheServiceRecordAndEverySoftField()
	{
		List<OwnedCard> owned = Collections.singletonList(
			new OwnedCard("u1", STALE, null, Variant.SHINY, 12345L, "shop:2026-W32", 400));

		List<OwnedCard> out = GachamanPlugin.healCardIds(owned, merges(STALE, MERGED));

		Assert.assertNotNull(out);
		Assert.assertEquals(1, out.size());
		OwnedCard healed = out.get(0);
		Assert.assertEquals(MERGED, healed.getCardId());
		Assert.assertEquals("u1", healed.getUuid()); // loadouts key on the uuid
		Assert.assertEquals(400, healed.getKillsServed()); // the odometer never resets
		Assert.assertEquals(Variant.SHINY, healed.getVariant());
		Assert.assertEquals(12345L, healed.getAcquiredAtMs());
		Assert.assertEquals("shop:2026-W32", healed.getProvenance());
	}

	// --- the null contract ---

	@Test
	public void nullIsReturnedWhenThereIsNothingToHeal()
	{
		// null hands mutate() an unchanged state, so a clean load costs no
		// re-encode of the save at all
		List<OwnedCard> healthy = Arrays.asList(
			card("a", MERGED, Variant.NORMAL, 0),
			card("b", MERGED, Variant.NORMAL, 0));

		Assert.assertNull(GachamanPlugin.healCardIds(healthy, merges()));
		Assert.assertNull(GachamanPlugin.healCardIds(null, merges(STALE, MERGED)));
		Assert.assertNull(GachamanPlugin.healCardIds(
			Collections.emptyList(), merges(STALE, MERGED)));
	}

	@Test
	public void anUnrescuableStaleIdIsKeptAsIs()
	{
		// the id resolves to nothing at all: leave the copy alone rather than
		// silently deleting a card the player owns
		List<OwnedCard> owned = Collections.singletonList(card("u1", STALE, Variant.NORMAL, 0));

		Assert.assertNull(GachamanPlugin.healCardIds(owned, merges()));
	}
}

package com.gachaman;

import org.junit.*;

/**
 * Pins {@link GachamanPlugin#ordinal(int)} against the branch-per-case switch
 * it replaced.
 *
 * <p>The switch spelled the 11/12/13 band out as an early return and the three
 * suffixes as case arms. The current form folds the teens into a sentinel 0 and
 * chains three ternaries, which is much smaller but is exactly the kind of
 * rewrite that can slip a boundary: 11-13 and their multiples of 100 (111,
 * 1013) must be "th" even though they end in 1, 2 and 3, while 21/32/43 must
 * NOT be. Both shapes are reproduced here independently of the implementation,
 * so a future compaction that gets the band wrong fails loudly.
 *
 * <p>This is the whole reason ordinal() is package-private rather than private:
 * the milestone chat line it feeds ("your 12th completion paid x2") only prints
 * from a live client, so the arithmetic could not otherwise be checked.
 */
public class OrdinalSuffixTest
{
	/** The suffix rule written the long way, deliberately NOT the same code. */
	private static String expected(int n)
	{
		int teens = Math.abs(n) % 100;
		if (teens >= 11 && teens <= 13)
		{
			return n + "th";
		}
		switch (Math.abs(n) % 10)
		{
			case 1:
				return n + "st";
			case 2:
				return n + "nd";
			case 3:
				return n + "rd";
			default:
				return n + "th";
		}
	}

	@Test
	public void theFirstFewReadTheWayAPlayerExpects()
	{
		Assert.assertEquals("1st", GachamanPlugin.ordinal(1));
		Assert.assertEquals("2nd", GachamanPlugin.ordinal(2));
		Assert.assertEquals("3rd", GachamanPlugin.ordinal(3));
		Assert.assertEquals("4th", GachamanPlugin.ordinal(4));
	}

	@Test
	public void theTeensAreTheExceptionBand()
	{
		Assert.assertEquals("11th", GachamanPlugin.ordinal(11));
		Assert.assertEquals("12th", GachamanPlugin.ordinal(12));
		Assert.assertEquals("13th", GachamanPlugin.ordinal(13));
		// the band's edges: 10 and 14 are ordinary, and the band repeats every
		// hundred, which is the case a naive n % 10 rule gets wrong
		Assert.assertEquals("10th", GachamanPlugin.ordinal(10));
		Assert.assertEquals("14th", GachamanPlugin.ordinal(14));
		Assert.assertEquals("111th", GachamanPlugin.ordinal(111));
		Assert.assertEquals("112th", GachamanPlugin.ordinal(112));
		Assert.assertEquals("113th", GachamanPlugin.ordinal(113));
	}

	@Test
	public void theSuffixReturnsOutsideTheBand()
	{
		Assert.assertEquals("21st", GachamanPlugin.ordinal(21));
		Assert.assertEquals("22nd", GachamanPlugin.ordinal(22));
		Assert.assertEquals("23rd", GachamanPlugin.ordinal(23));
		Assert.assertEquals("101st", GachamanPlugin.ordinal(101));
		Assert.assertEquals("1002nd", GachamanPlugin.ordinal(1002));
	}

	@Test
	public void everyNonNegativeCompletionNumberAgreesWithTheLongForm()
	{
		// a contract count is a non-negative running total, so this range is the
		// whole reachable domain several times over
		for (int n = 0; n <= 5000; n++)
		{
			Assert.assertEquals("ordinal(" + n + ")", expected(n), GachamanPlugin.ordinal(n));
		}
	}

	@Test
	public void negativesCannotThrowOrProduceAStraySuffix()
	{
		// unreachable through the milestone path, but the old switch fell to
		// "th" on a negative n % 10 and the new sentinel form must too — pinning
		// it stops the next rewrite from "fixing" that into a crash
		for (int n = -1; n >= -200; n--)
		{
			Assert.assertTrue("ordinal(" + n + ") = " + GachamanPlugin.ordinal(n),
				GachamanPlugin.ordinal(n).endsWith("th"));
		}
		Assert.assertEquals(Integer.MIN_VALUE + "th", GachamanPlugin.ordinal(Integer.MIN_VALUE));
	}
}

package com.gachaman.overlay;

import com.gachaman.*;

/**
 * The chest fights before it opens, and how hard it fights is the tell. This is
 * the whole schedule for that fight: a shudder that starts the strain, a hold
 * whose amplitude climbs toward the give, a beat of total stillness, then the
 * give — at which point the existing lid/flash/shatter code takes over
 * untouched.
 * <p>
 * Every input here is the {@link Tuning.Chest} tier the player PAID for and
 * nothing else. No signature in this class can accept a roll result, so the
 * length of the fight physically cannot betray what is inside the box; it
 * reports only what was bought. That is the difference between a tell and a
 * spoiler, and it is enforced by the signatures rather than by care.
 * <p>
 * Pure function of its arguments — no state, no timers; the caller owns the
 * clock, exactly as {@link ChestPainter} does. It depends only on
 * {@link Tuning}, which pulls in nothing from the client, so the schedule is
 * testable without a running RuneLite.
 */
final class ChestStrain {
	/**
	 * Dead stillness immediately before the give. Sustained shaking reads as
	 * noise; shaking that suddenly STOPS reads as a lock about to lose. This
	 * beat is the point of the whole class — if any part of the strain is ever
	 * cut, cut the groans and keep this.
	 */
	static final long HELD_STILL_MS = 220;

	/** How long the extra jolt from a groan takes to bleed off. */
	private static final long KICK_MS = 180;

	// Rusty gets no groans on purpose: the bottom of the ladder has to be
	// conspicuously undramatic or "how hard it fights" tells you nothing.
	private static final long[] BEATS_RUSTY = {};
	private static final long[] BEATS_BATTERED = {300, 900};
	private static final long[] BEATS_GILDED = {600, 1400, 2200};
	private static final long[] BEATS_ORNATE = {4000, 4700, 5400, 6000};

	private ChestStrain() {
	}

	/**
	 * Total intro length. All four numbers are exactly what the ceremony
	 * already shipped with — this feature changes the SHAPE of the intro, never
	 * its duration, because every downstream boundary (the Gilded lid at 3200,
	 * the Ornate blast at 6400) is tuned against them.
	 */
	static long totalMs(Tuning.Chest tier) {
		switch (tier) {
			case RUSTY:
				return 1400;
			case BATTERED:
				return 2000;
			case GILDED:
				return 4000;
			default:
				return 7000;
		}
	}

	/** When the lock first moves. */
	static long shudderMs(Tuning.Chest tier) {
		switch (tier) {
			case RUSTY:
				return 300;
			case BATTERED:
				return 300;
			case GILDED:
				return 600;
			default:
				return 900;
		}
	}

	/** When the lock loses — the instant the existing lid/flash/shatter code owns. */
	static long giveMs(Tuning.Chest tier) {
		switch (tier) {
			case RUSTY:
				return 900;
			case BATTERED:
				return 1400;
			case GILDED:
				return 2800;
			default:
				return 6400;
		}
	}

	/**
	 * Elapsed times at which the lock groans and visibly kicks. The returned
	 * array is the SHARED instance, not a copy: {@link #kick} walks it on every
	 * rendered frame and a defensive clone there would allocate at framerate.
	 * Callers must not write to it (Tuning.CHEST_ODDS hands out shared arrays
	 * the same way).
	 */
	static long[] beats(Tuning.Chest tier) {
		switch (tier) {
			case RUSTY:
				return BEATS_RUSTY;
			case BATTERED:
				return BEATS_BATTERED;
			case GILDED:
				return BEATS_GILDED;
			default:
				return BEATS_ORNATE;
		}
	}

	/** 0..1 build from the first shudder to the give; monotone and clamped. */
	static double load(long el, Tuning.Chest tier) {
		long from = shudderMs(tier);
		long to = giveMs(tier);
		if (to <= from)
			return 0;
		double t = (el - from) / (double) (to - from);
		return t <= 0 ? 0 : (t >= 1 ? 1 : t);
	}

	/**
	 * The lock only moves while it is losing, and goes dead still just before
	 * it gives. Draw code gates on this rather than on {@code load() > 0}
	 * because at {@code el == shudderMs} the load is exactly 0, so a {@code > 0}
	 * gate would silently swallow the first frame of movement.
	 */
	static boolean straining(long el, Tuning.Chest tier) {
		return el >= shudderMs(tier) && el < giveMs(tier) - HELD_STILL_MS;
	}

	/** Extra amplitude right after a groan, decaying over KICK_MS — the visible shudder. */
	static double kick(long el, Tuning.Chest tier) {
		double best = 0;
		for (long b : beats(tier)) {
			long d = el - b;
			if (d >= 0 && d < KICK_MS) {
				double k = 1.0 - d / (double) KICK_MS;
				if (k > best)
					best = k;
			}
		}
		return best;
	}
}

package com.gachaman.overlay;

import java.awt.*;
import java.io.*;
import java.util.*;
import javax.imageio.*;

/**
 * The one PNG cache every ceremony sprite is loaded through: the roulette
 * chrome, the scroll rollers and the parchment texture all name a file under
 * {@code /com/gachaman/art/} and all want the same "decode once, remember the
 * answer" behaviour, so they share this instead of each carrying a map and a
 * copy of the same try-with-resources.
 *
 * <p>Unbounded on purpose. These sprites are small, few, and wanted for as long
 * as the client runs. {@link CeremonyPlayer} deliberately does NOT use this
 * cache: its chest frames are large enough that holding them all costs tens of
 * MB, which is why that class keeps a bounded LRU of its own.
 */
final class ArtCache {
	/**
	 * Sprite name to decoded image, with an explicit null for a sprite that is
	 * not in the jar. Package-visible so the overlay tests can assert on the
	 * caching itself rather than on pixels.
	 */
	static final Map<String, Image> ART = new HashMap<>();

	private ArtCache() {
	}

	/**
	 * The named sprite, or null when it is missing or will not decode.
	 *
	 * <p>containsKey, not computeIfAbsent: a HashMap does not RECORD a null
	 * mapping, so computeIfAbsent treats a missing PNG as "not cached yet" and
	 * re-runs the loader on every single frame. Every sprite ships today, so
	 * this is latent rather than live — but on a partial or stripped jar the
	 * roulette would do four failed classloader lookups per frame for the whole
	 * spin, and each scroll five more per roller. An explicit null value is the
	 * "tried once" sentinel that holds a miss to exactly one lookup.
	 */
	static Image get(String name) {
		if (!ART.containsKey(name)) {
			Image loaded = null;
			try (InputStream in = ArtCache.class.getResourceAsStream(
				"/com/gachaman/art/" + name + ".png")) {
				if (in != null)
					loaded = ImageIO.read(in);
			}
			catch (Exception e) {
				// a truncated or corrupt PNG caches as a miss for the same
				// reason: re-decoding it every frame cannot make it decode
			}
			ART.put(name, loaded);
		}
		return ART.get(name);
	}

	/**
	 * Draws the named sprite stretched into (x, y, w, h); a miss draws nothing.
	 *
	 * <p>The size check comes first so a caller whose arithmetic has collapsed —
	 * a scroll drawn narrower than its own end caps — never reaches the cache at
	 * all, which is the order {@link ScrollPainter} has always used.
	 */
	static void blit(Graphics2D g, String name, int x, int y, int w, int h) {
		Image art = w > 0 && h > 0 ? get(name) : null;
		if (art != null)
			g.drawImage(art, x, y, w, h, null);
	}
}

package com.gachaman.overlay;

import net.runelite.api.Point;
import com.gachaman.ui.Paint;
import com.gachaman.service.*;
import com.gachaman.ui.*;
import java.awt.*;
import javax.inject.*;
import lombok.extern.slf4j.*;
import net.runelite.api.*;
import net.runelite.api.coords.*;
import net.runelite.client.ui.overlay.*;

/**
 * Lightweight non-modal kill feedback: floating "+N GC" texts rising from the
 * NPC death point, a grey "x" for off-task kills, tainted text and a golden
 * burst on the final kill. Task progress itself lives in the movable
 * {@link TaskProgressOverlay} panel. The overlay is the
 * {@link TaskService.Listener} the plugin registers
 * ({@code taskService.addListener(killJuiceOverlay)}).
 *
 * <p>Notes are pinned to the world, not the screen: each one keeps the
 * {@link LocalPoint} the NPC died on and is re-projected every frame, so the
 * number sits over the corpse while the camera turns, zooms and pans. Floating
 * texts live in a preallocated ring buffer and burst particles are pure
 * functions of elapsed time + seed; the only per-frame allocation is the
 * projected Point per ACTIVE note, which is almost always none or one.
 */
@Slf4j
@Singleton
public class KillJuiceOverlay extends Overlay implements TaskService.Listener {
	private static final int POOL_SIZE = 16;
	private static final long FLOAT_MS = 1500;
	private static final long BURST_MS = 1100;
	private static final int RISE_PX = 30;

	private static final int KIND_GC = 0;
	private static final int KIND_OFF_TASK = 1;
	private static final int KIND_TAINTED = 2;
	private static final int KIND_BURST = 3;

	private static final Font FONT_GC = new Font(Font.SANS_SERIF, Font.BOLD, 15);
	private static final Font FONT_SMALL = new Font(Font.SANS_SERIF, Font.PLAIN, 11);

	private static final Color GC_GOLD = new Color(255, 205, 70);
	private static final Color OFF_GREY = new Color(160, 160, 160, 190);
	private static final Color TAINT_RED = new Color(170, 30, 30);

	/** Preallocated floating-text slot; mutated in place, never allocated in render. */
	private static final class Note {
		boolean active;
		int kind;
		long startMs;
		/**
		 * The world spot this note is pinned to, re-projected every frame so the
		 * number stays over the corpse while the camera turns. Null only when the
		 * kill arrived without a death location, in which case the note falls
		 * back to the screen anchor below.
		 */
		LocalPoint world;
		int plane;
		int screenX;
		int screenY;
		String text;
		int seed;
	}

	private final Client client;

	private final Note[] notes = new Note[POOL_SIZE];
	private int noteCursor;

	@Inject
	public KillJuiceOverlay(Client client) {
		this.client = client;
		for (int i = 0; i < notes.length; i++) {
			notes[i] = new Note();
		}
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
		setPriority(Overlay.PRIORITY_MED);
	}

	// --- TaskService.Listener (events arrive on the client thread) ---

	@Override
	public void onKillFeedback(TaskService.KillFeedback feedback) {
		if (feedback == null)
			return;
		// keep the WORLD point, not a canvas point: projecting once at spawn
		// pinned the number to a screen pixel, so it slid off the corpse the
		// moment the camera moved. Projection happens per frame in drawNotes.
		LocalPoint world = feedback.getDeathLocation();
		int plane = client.getTopLevelWorldView().getPlane();
		long now = System.currentTimeMillis();

		if (!feedback.isOnTask()) {
			spawn(KIND_OFF_TASK, world, plane, "x", now);
			return;
		}
		if (feedback.isTainted())
			spawn(KIND_TAINTED, world, plane, "TAINTED +1 taint", now);
		else if (feedback.getGcAwarded() > 0) {
			spawn(KIND_GC, world, plane, "+" + feedback.getGcAwarded() + " GC", now);
		}
		if (feedback.isFinalKill())
			spawn(KIND_BURST, world, plane, null, now);
	}


	@Override
	public void onTaskCompleted(TaskService.TaskCompletionSummary summary) {
		// the docked TaskProgressOverlay tracks progress; completion fanfare
		// is the final-kill burst plus the ceremony pipeline
	}


	private synchronized void spawn(int kind, LocalPoint world, int plane, String text, long now) {
		Note note = notes[noteCursor];
		noteCursor = (noteCursor + 1) % notes.length;
		note.active = true;
		note.kind = kind;
		note.startMs = now;
		note.world = world;
		note.plane = plane;
		// only consulted when there is no world point to project
		note.screenX = client.getCanvasWidth() / 2;
		note.screenY = client.getCanvasHeight() / 2;
		note.text = text;
		note.seed = (int) (now & 0x7FFF) * 31 + (world == null ? 0 : world.getX());
	}

	// --- render (zero allocation) ---

	@Override
	public Dimension render(Graphics2D g) {
		long now = System.currentTimeMillis();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

		drawNotes(g, now);
		return null;
	}

	private void drawNotes(Graphics2D g, long now) {
		for (int i = 0; i < notes.length; i++) {
			Note note = notes[i];
			if (!note.active)
				continue;
			long el = now - note.startMs;
			long life = note.kind == KIND_BURST ? BURST_MS : FLOAT_MS;
			if (el < 0 || el >= life) {
				note.active = false;
				continue;
			}
			// re-project every frame: this is what keeps the number over the
			// spot the NPC died on rather than over a fixed screen pixel
			int anchorX = note.screenX;
			int anchorY = note.screenY;
			if (note.world != null) {
				Point p = null;
				try {
					p = Perspective.localToCanvas(client, note.world, note.plane);
				}
				catch (Exception e) {
					p = null;
				}
				if (p == null) {
					continue; // the spot is off-scene or behind the camera this frame
				}
				anchorX = p.getX();
				anchorY = p.getY();
			}
			if (note.kind == KIND_BURST) {
				drawBurst(g, note, el, anchorX, anchorY);
				continue;
			}
			float u = el / (float) life;
			float alpha = u < 0.6f ? 1f : 1f - (u - 0.6f) / 0.4f;
			int y = anchorY - (int) (RISE_PX * easeOut(u));

			Font font;
			Color color;
			if (note.kind == KIND_GC) {
				font = FONT_GC;
				color = GC_GOLD;
			}
			else if (note.kind == KIND_TAINTED) {
				font = FONT_GC;
				color = TAINT_RED;
			}
			else {
				font = FONT_SMALL;
				color = OFF_GREY;
			}
			g.setFont(font);
			FontMetrics fm = g.getFontMetrics();
			int x = anchorX - fm.stringWidth(note.text) / 2;
			g.setColor(Paint.withAlpha(Color.BLACK, alpha * 0.8f));
			g.drawString(note.text, x + 1, y + 1);
			g.setColor(Paint.withAlpha(color, alpha));
			g.drawString(note.text, x, y);
		}
	}

	private void drawBurst(Graphics2D g, Note note, long el, int anchorX, int anchorY) {
		float u = el / (float) BURST_MS;
		double ts = el / 1000.0;
		for (int p = 0; p < 14; p++) {
			float h1 = Paint.hash01(note.seed + p * 3);
			float h2 = Paint.hash01(note.seed + p * 3 + 1);
			float h3 = Paint.hash01(note.seed + p * 3 + 2);
			double ang = h1 * Math.PI * 2;
			double speed = 40 + h2 * 150;
			int px = anchorX + (int) (Math.cos(ang) * speed * ts);
			int py = anchorY + (int) (Math.sin(ang) * speed * ts * 0.8 + 240 * ts * ts);
			int size = 2 + (int) (h3 * 2);
			g.setColor(Paint.withAlpha(p % 3 == 0 ? Color.WHITE : GC_GOLD, 1f - u));
			g.fillRect(px, py, size, size);
		}
		// small expanding halo
		int r = (int) (10 + 34 * easeOut(u));
		g.setColor(Paint.withAlpha(GC_GOLD, (1f - u) * 0.7f));
		g.setStroke(STROKE_2);
		g.drawOval(anchorX - r, anchorY - r, r * 2, r * 2);
	}

	private static final BasicStroke STROKE_2 = new BasicStroke(2f);

	private static float easeOut(float t) {
		float inv = 1 - Math.max(0f, Math.min(1f, t));
		return 1 - inv * inv;
	}


}

