	private void layoutDeedRects(int cw, int ch) {
		int boxW = Math.min(120, (cw - 120) / 3);
		int boxH = 58;
		int gapX = 16;
		int gapY = 14;
		int totalW = boxW * 3 + gapX * 2;
		int totalH = boxH * 5 + gapY * 4;
		int x0 = (cw - totalW) / 2;
		int y0 = (ch - totalH) / 2 + 16;
		GearSlot[] slots = GearSlot.values();
		for (int i = 0; i < slots.length; i++) {
			int col = DEED_GRID[i][0];
			int row = DEED_GRID[i][1];
			deedRects[i].setBounds(x0 + col * (boxW + gapX), y0 + row * (boxH + gapY), boxW, boxH);
		}
	}

	private boolean isSlotDeeded(GearSlot slot) {
		GachaState state = stateService.get();
		return state != null && state.getDeededSlots().contains(slot.name());
	}

	private void drawDeedChoice(Graphics2D g, int cw, int ch, long now) {
		layoutDeedRects(cw, ch);
		centre(g, "SLOT DEED EARNED", cw / 2, 46, FONT_TITLE, GOLD);
		centre(g, "Choose a locked slot to unlock forever", cw / 2, 70, FONT_BODY,
			Color.WHITE);
		GachaState state = stateService.get();
		int pending = state == null ? 0 : state.getPendingDeeds();
		if (pending > 1) {
			centre(g, "Deeds available: " + pending, cw / 2, 90, FONT_SMALL,
				new Color(200, 200, 200), false);
		}

		GearSlot[] slots = GearSlot.values();
		for (int i = 0; i < slots.length; i++) {
			Rectangle r = deedRects[i];
			boolean deeded = isSlotDeeded(slots[i]);
			boolean chosen = phase == PH_DEED_BURST && slots[i] == chosenDeedSlot;
			boolean hovered = phase == PH_DEED_CHOOSE && !deeded && pointerValid
				&& r.contains(pointerX, pointerY);

			// Every box is the same rounded plate at the same geometry; a slot
			// that is won (or being won right now) differs only in its three
			// colours and a heavier border. `lit` and `hovered` are mutually
			// exclusive by construction — hovered demands PH_DEED_CHOOSE and
			// !deeded — so the border weight is simply "either of them".
			boolean lit = deeded || chosen;
			plate(g, r, lit ? new Color(66, 52, 18, 235)
					: hovered ? new Color(46, 46, 54, 240) : new Color(30, 30, 36, 235),
				lit ? GOLD : hovered ? new Color(200, 200, 210) : new Color(90, 90, 100),
				lit || hovered);
			int mx = r.x + r.width / 2;
			if (lit) {
				// won: the name alone, centred, with nothing left to unlock
				centre(g, slots[i].getDisplayName(), mx, r.y + r.height / 2 + 4,
					FONT_BODY, GOLD);
			}
			else {
				// locked: the padlock takes the middle and the name sits under it
				centre(g, slots[i].getDisplayName(), mx, r.y + r.height - 10, FONT_SMALL,
					hovered ? Color.WHITE : new Color(150, 150, 160), false);
				drawMiniPadlock(g, mx, r.y + r.height / 2 - 8,
					hovered ? new Color(220, 220, 230) : new Color(120, 120, 130));
			}

			if (chosen)
				drawDeedBurst(g, r, now - phaseAt);
		}
	}

	private void drawMiniPadlock(Graphics2D g, int cx, int cy, Color color) {
		g.setColor(color);
		g.setStroke(new BasicStroke(2f));
		g.drawArc(cx - 5, cy - 9, 10, 10, 0, 180);
		g.fillRoundRect(cx - 7, cy - 3, 14, 11, 3, 3);
	}

	private void drawDeedBurst(Graphics2D g, Rectangle r, long t) {
		float u = (float) clamp(t / (double) DEED_BURST_MS);
		float fade = 1 - u;
		int cx = r.x + r.width / 2;
		int cy = r.y + r.height / 2;
		// rays
		Graphics2D g2 = copy(g);
		g2.setStroke(new BasicStroke(3f));
		for (int k = 0; k < 12; k++) {
			double ang = k * Math.PI / 6 + u * 0.9;
			double len = 20 + smoothstep(u) * 110;
			g2.setColor(withAlpha(GOLD, fade * 0.9f));
			g2.drawLine(cx + (int) (Math.cos(ang) * 12), cy + (int) (Math.sin(ang) * 12),
				cx + (int) (Math.cos(ang) * len), cy + (int) (Math.sin(ang) * len));
		}
		// expanding ring + sparks
		double ringR = smoothstep(u) * 90;
		g2.setColor(withAlpha(Color.WHITE, fade * 0.8f));
		g2.setStroke(new BasicStroke(2f + fade * 8f));
		g2.drawOval(cx - (int) ringR, cy - (int) ringR, (int) ringR * 2, (int) ringR * 2);
		double ts = t / 1000.0;
		for (int p = 0; p < 18; p++) {
			float h1 = hash01(p * 71 + 5);
			float h2 = hash01(p * 71 + 6);
			double ang = h1 * Math.PI * 2;
			double speed = 50 + h2 * 190;
			int px = cx + (int) (Math.cos(ang) * speed * ts);
			int py = cy + (int) (Math.sin(ang) * speed * ts + 260 * ts * ts);
			g2.setColor(withAlpha(GOLD, fade));
			g2.fillRect(px, py, 3, 3);
		}
		g2.dispose();
	}

	// =====================================================================
	// THE CONSIGNMENT (a binding choice)
	// =====================================================================

	/**
	 * The two answers, as plates to aim at.
	 *
	 * <p>Identical geometry on purpose: a binding choice must not have a default,
	 * and the house's side of it is exactly the one that would profit from being
	 * the bigger target.
	 *
	 * <p>Static and package-private because it is pure, and because the invariant
	 * worth pinning off-client is a layout one — two plates that overlapped, or
	 * one that ran off the canvas, would take an answer the player never gave.
	 */
	static void consignRect(int i, int cw, int ch, Rectangle out) {
		int bw = Math.min(230, (cw - 90) / 2);
		int gap = 26;
		int x0 = (cw - (bw * 2 + gap)) / 2;
		// centred on a tall canvas, lifted off the bottom edge on a short one, so
		// the crate above keeps its room either way
		out.setBounds(x0 + i * (bw + gap), Math.min(ch - 116, ch / 2 + 118), bw, 52);
	}

	/**
	 * One answer: a title, and the consequence spelled out under it.
	 *
	 * <p>The second line is not decoration. The two answers differ in what they
	 * cost as much as in what they pay, and "TAKE THE DEAL" against "SPIN THE
	 * WHEEL" asks the player to remember which of them hands their style to the
	 * house — at the one moment they are being asked to agree to it.
	 */
	private static void drawChoicePlate(Graphics2D g, Rectangle r, String title, String detail,
		boolean hovered, Color accent) {
		plate(g, r, hovered ? new Color(46, 42, 30, 245) : new Color(28, 26, 20, 235),
			hovered ? accent : withAlpha(accent, 0.6f), hovered);
		int mx = r.x + r.width / 2;
		centre(g, title, mx, r.y + 19, FONT_BODY, accent);
		centre(g, detail, mx, r.y + 37, FONT_SMALL, CAP_DIM, false);
	}

	/**
	 * The rounded plate every aimable target in this file is built on: a slot in
	 * the deed grid and an answer in the Consignment.
	 *
	 * <p>The two screens were drawing the identical five calls — same 10px
	 * corner, same 2.5/1.6 border weights, same fill-then-stroke order — and
	 * differed only in which colours they chose and what they wrote on top. That
	 * is not two plates, it is one plate asked twice, and a target the player has
	 * to aim at is exactly the thing that must not drift between the screen that
	 * unlocks a slot and the screen that signs away a style roll.
	 *
	 * <p>{@code heavy} is passed rather than derived: the deed grid thickens the
	 * border for a slot that is lit OR hovered, the Consignment only for a hover,
	 * and no expression over the arguments here can tell those apart.
	 */
	private static void plate(Graphics2D g, Rectangle r, Color fill, Color edge,
		boolean heavy) {
		g.setColor(fill);
		g.fillRoundRect(r.x, r.y, r.width, r.height, 10, 10);
		g.setColor(edge);
		g.setStroke(new BasicStroke(heavy ? 2.5f : 1.6f));
		g.drawRoundRect(r.x, r.y, r.width, r.height, 10, 10);
	}

	/**
	 * The offer. No clock, no animation, no phase to skip past — see
	 * {@link #PH_CONSIGN_OFFER}. Everything on it is either the deal or the price
	 * of the deal.
	 */
	private void drawConsignment(Graphics2D g, int cw, int ch) {
		ConsignmentService.Offer offer = consignOffer;
		if (offer == null)
			return;
		Tuning.Chest tier = offer.getChestTier();
		// every line, the crate and both answer plates hang off the same axis
		int mx = cw / 2;
		centre(g, "THE CONSIGNMENT", mx, 46, FONT_TITLE, GOLD);
		centre(g, "A free " + tier.name() + " crate, on the house",
			mx, 72, FONT_BODY, Color.WHITE);
		// What the crate is worth, from the same two tables the shop charges from
		// and the roller deals from — so the offer cannot flatter itself, and a
		// retune of either moves this line with it.
		centre(g, "normally " + Tuning.CHEST_PRICE_GC.get(tier) + " GC - "
			+ Tuning.CHEST_CARDS.get(tier) + " cards", mx, 92, FONT_SMALL, CAP_INK, false);

		// the button row owns the vertical anchor; everything above stacks off it
		consignRect(0, cw, ch, rect);
		int btnY = rect.y;
		int headY = btnY - 52;

		int crateW = Math.min(220, cw / 3);
		int crateH = crateW * 3 / 4;
		int crateCy = headY - 30 - crateH / 2;
		// the crate, closed, in its own tier's ceremony art. Skipped rather than
		// squeezed when the canvas cannot hold it under the heading: the words are
		// the offer, the picture is only the box it comes in.
		if (crateCy - crateH / 2 > 104)
			ceremonyPlayer.draw(g, mx, crateCy, crateW, crateH, tier, 0, 1f);

		AttackStyle named = offer.getStyle();
		centre(g, "Its price is your next style roll", mx, headY - 24,
			FONT_SMALL, CAP_DIM);
		centre(g, "THE HOUSE NAMES " + named.getDisplayName().toUpperCase(),
			mx, headY, FONT_TITLE, named.getColor());
		// why THIS style, in the terms the house picked it by. A deal that names a
		// style without saying how it chose reads as rigged; saying it out loud
		// makes it a rule the player can see coming next time.
		int owned = offer.getOwnedWeaponCards();
		centre(g, owned == 0
			? "the one style your album holds no weapon cards for"
			: "the style your album is worst dressed for - " + owned + " weapon card"
				+ (owned == 1 ? "" : "s"),
			mx, btnY - 26, FONT_SMALL, CAP_INK);

		for (int i = 0; i < 2; i++) {
			consignRect(i, cw, ch, rect);
			drawChoicePlate(g, rect, i == 0 ? "TAKE THE DEAL" : "SPIN THE WHEEL",
				i == 0 ? "the crate, and the house's style" : "the wheel decides, as always",
				pointerValid && rect.contains(pointerX, pointerY),
				i == 0 ? GOLD : new Color(200, 200, 210));
		}
		// Said before the click, not after it. Refusing costs the day too, and a
		// player who learned that by pressing Escape and being asked no more today
		// would be right to call it a trick.
		centre(g, "Either answer takes the roll and spends today's offer.",
			mx, ch - 48, FONT_SMALL, CAP_DIM);
		centre(g, "Click an answer - Esc refuses the deal", mx, ch - 30,
			FONT_BODY, HINT);
	}

	// =====================================================================
	// FANFARE (non-modal)
	// =====================================================================

	private static long fanfareDurationMs(CeremonyBus.Fanfare.Size size) {
		switch (size) {
			case SMALL:
				return 2000;
			case MEDIUM:
				return 3200;
			default:
				return 4400;
		}
	}

	private void drawFanfare(Graphics2D g, int cw, int ch, long now, long el) {
		CeremonyBus.Fanfare fan = fanfare;
		CeremonyBus.Fanfare.Size size = fan.getSize();
		long total = fanfareDurationMs(size);
		// The banner's own copy, read once. Both lines were being fetched and
		// null-tested twice over — once to measure the ribbon, once to ink it —
		// and "has a detail line" was spelled out at both ends of the method.
		String title = fan.getTitle() == null ? "" : fan.getTitle();
		String detail = fan.getDetail();
		boolean detailed = detail != null && !detail.isEmpty();

		if (size == CeremonyBus.Fanfare.Size.MEDIUM)
			drawConfetti(g, cw, ch, el);
		else if (size == CeremonyBus.Fanfare.Size.LARGE) {
			drawFireworks(g, cw, ch, el);
		}

		// ribbon banner slides in at the top
		double in = smoothstep(clamp(el / 250.0));
		double out = smoothstep(clamp((total - el) / 250.0));
		double slide = Math.min(in, out);
		int bannerH = detailed ? 56 : 40;
		int y = (int) lerp(-bannerH - 8, 14, slide);

		FontMetrics fmT = metrics(g, FONT_BODY);
		int titleW = fmT.stringWidth(title);
		g.setFont(FONT_SMALL);
		int detailW = detail == null ? 0 : g.getFontMetrics().stringWidth(detail);
		BufferedImage icon = fan.getIconItemId() != null
			? cardImageService.itemImage(fan.getIconItemId(), null) : null;
		int iconW = icon != null ? 40 : 0;
		int w = Math.max(titleW, detailW) + 40 + iconW;
		int x = (cw - w) / 2;

		g.setPaint(new GradientPaint(x, y, new Color(40, 32, 14, 235),
			x, y + bannerH, new Color(24, 18, 8, 235)));
		g.fillRoundRect(x, y, w, bannerH, 12, 12);
		g.setColor(GOLD);
		g.setStroke(new BasicStroke(2f));
		g.drawRoundRect(x, y, w, bannerH, 12, 12);
		// ribbon tails
		g.setColor(new Color(120, 90, 20, 220));
		g.fillRect(x - 12, y + 8, 12, bannerH - 16);
		g.fillRect(x + w, y + 8, 12, bannerH - 16);

		int textX = x + 20 + iconW;
		if (icon != null)
			g.drawImage(icon, x + 10, y + (bannerH - 32) / 2, 32, 32, null);
		g.setFont(FONT_BODY);
		g.setColor(GOLD);
		g.drawString(title, textX, y + 22);
		if (detailed) {
			g.setFont(FONT_SMALL);
			g.setColor(Color.WHITE);
			g.drawString(detail, textX, y + 40);
		}
	}

	private void drawConfetti(Graphics2D g, int cw, int ch, long el) {
		AffineTransform saved = g.getTransform();
		double ts = el / 1000.0;
		for (int p = 0; p < 36; p++) {
			float h1 = hash01(p * 91 + 1);
			float h2 = hash01(p * 91 + 2);
			float h3 = hash01(p * 91 + 3);
			int x = (int) (h1 * cw);
			double speed = 110 + h2 * 190;
			int y = (int) ((h3 * ch + speed * ts) % (ch + 40)) - 20;
			double rot = ts * (2 + h2 * 5) + h1 * 6;
			g.setColor(Color.getHSBColor(h1, 0.75f, 1f));
			g.rotate(rot, x, y);
			g.fillRect(x - 2, y - 5, 4, 10);
			g.setTransform(saved);
		}
	}

	private void drawFireworks(Graphics2D g, int cw, int ch, long el) {
		long[] launches = {250, 1050, 1850};
		double[] xFracs = {0.2, 0.8, 0.5};
		for (int m = 0; m < launches.length; m++) {
			long t = el - launches[m];
			if (t < 0)
				continue;
			int lx = (int) (cw * xFracs[m]);
			int burstY = (int) (ch * (0.30 + 0.06 * m));
			long riseMs = 480;
			if (t < riseMs) {
				// mortar streak
				double u = smoothstep(t / (double) riseMs);
				int y = (int) lerp(ch, burstY, u);
				g.setColor(withAlpha(Color.WHITE, 0.9f));
				g.fillRect(lx - 1, y, 3, 10);
				g.setColor(withAlpha(GOLD, 0.5f));
				g.fillRect(lx - 1, y + 10, 3, 18);
				continue;
			}
			long bt = t - riseMs;
			if (bt > 1000)
				continue;
			float u = bt / 1000f;
			double ts = bt / 1000.0;
			for (int p = 0; p < 26; p++) {
				float h1 = hash01(m * 811 + p * 3);
				float h2 = hash01(m * 811 + p * 3 + 1);
				double ang = h1 * Math.PI * 2;
				double speed = 60 + h2 * 220;
				int px = lx + (int) (Math.cos(ang) * speed * ts);
				int py = burstY + (int) (Math.sin(ang) * speed * ts + 190 * ts * ts);
				g.setColor(withAlpha((p % 3 == 0) ? Color.WHITE : GOLD, 1 - u));
				g.fillRect(px, py, 3, 3);
			}
		}
	}

	// =====================================================================
	// utilities
	// =====================================================================

	/**
	 * A throwaway Graphics2D to transform, clip or restyle without disturbing
	 * the caller's.
	 *
	 * <p>Thirteen ceremonies take one, and {@code (Graphics2D) g.create()} was
	 * spelled out at every one of them — the cast included, because
	 * {@link Graphics#create()} is declared to return the superclass. One name
	 * for it says the same thing and carries the cast once.
	 */
	/**
	 * Set the font and hand back its metrics.
	 *
	 * <p>Nothing in this file ever wants one without the other — every block of
	 * text here is measured before it is placed — and the two lines were written
	 * out together eleven times over. One name for the pair also makes it
	 * impossible to measure against a font other than the one about to be drawn
	 * with, which is the bug the split version invites.
	 */
	private static FontMetrics metrics(Graphics2D g, Font f) {
		g.setFont(f);
		return g.getFontMetrics();
	}

	private static Graphics2D copy(Graphics2D g) {
		return (Graphics2D) g.create();
	}

	private static double clamp(double v) {
		return v <= 0 ? 0 : (v >= 1 ? 1 : v);
	}

	private static double smoothstep(double t) {
		t = clamp(t);
		return t * t * (3 - 2 * t);
	}

	private static double easeOutCubic(double t) {
		t = clamp(t);
		double u = 1 - t;
		return 1 - u * u * u;
	}

	/**
	 * Ease-out with a small overshoot, for the unroll.
	 *
	 * <p>A cubic ease glides to a halt, which is how a menu slides, not how a
	 * sheet of paper behaves: it pays out, overruns, and is pulled taut. The
	 * overshoot is deliberately gentle — 1.1 rather than the usual 1.70158 —
	 * because the rollers travel only a few dozen pixels and a full back-ease at
	 * that distance reads as a bounce rather than tension.
	 */
	private static double easeOutBack(double t) {
		t = clamp(t);
		double u = t - 1;
		final double c = 1.1;
		return 1 + (c + 1) * u * u * u + c * u * u;
	}

	private static double easeInCubic(double t) {
		t = clamp(t);
		return t * t * t;
	}

	private static double lerp(double a, double b, double t) {
		return a + (b - a) * t;
	}



	private static Color mixColor(Color a, Color b, float t) {
		float u = Math.max(0f, Math.min(1f, t));
		return new Color(
			(int) (a.getRed() + (b.getRed() - a.getRed()) * u),
			(int) (a.getGreen() + (b.getGreen() - a.getGreen()) * u),
			(int) (a.getBlue() + (b.getBlue() - a.getBlue()) * u));
	}

	/**
	 * Pull a colour toward its own brightness, keeping the hue but dropping the
	 * chroma. Used before tinting paper: mixing a UI-saturated colour into a
	 * parchment base carries the saturation across with it, and a little of a
	 * very saturated colour still looks like paint rather than staining.
	 *
	 * @param amount 0 = untouched, 1 = fully grey
	 */
	private static Color desaturate(Color c, float amount) {
		int lum = (int) Math.round(0.299 * c.getRed() + 0.587 * c.getGreen()
			+ 0.114 * c.getBlue());
		return mixColor(c, new Color(lum, lum, lum), amount);
	}

	private static String capitalize(String s) {
		if (s == null || s.isEmpty())
			return "";
		return Character.toUpperCase(s.charAt(0)) + s.substring(1);
	}

	private static String clipText(FontMetrics fm, String text, int maxWidth) {
		if (fm.stringWidth(text) <= maxWidth)
			return text;
		String drawn = text;
		while (fm.stringWidth(drawn) > maxWidth && drawn.length() > 3) {
			drawn = drawn.substring(0, drawn.length() - 2);
		}
		return drawn + "...";
	}

	/**
	 * One line of text centred on (cx, cy), with the drop shadow every ceremony
	 * headline carries.
	 *
	 * <p>Shadowed is the overwhelming majority — twenty-six of the thirty-three
	 * call sites — so it is the overload rather than a flag repeated at each of
	 * them. The seven that pass {@code false} are the quiet secondary lines that
	 * sit on their own dark plate and gain nothing from a shadow.
	 */
	private static void centre(Graphics2D g, String text, int cx, int cy, Font font,
		Color color) {
		centre(g, text, cx, cy, font, color, true);
	}

	private static void centre(Graphics2D g, String text, int cx, int cy, Font font,
		Color color, boolean shadow) {
		FontMetrics fm = metrics(g, font);
		int x = cx - fm.stringWidth(text) / 2;
		int y = cy + fm.getAscent() / 2 - 2;
		if (shadow) {
			g.setColor(new Color(0, 0, 0, 200));
			g.drawString(text, x + 2, y + 2);
		}
		g.setColor(color);
		g.drawString(text, x, y);
	}
}

package com.gachaman.overlay;

import net.runelite.client.input.MouseWheelListener;
import net.runelite.client.input.MouseListener;
import net.runelite.client.input.KeyListener;
import java.awt.event.*;
import javax.inject.*;
import lombok.*;
import net.runelite.api.*;
import net.runelite.client.input.*;

/**
 * Consumes ALL input while a MODAL ceremony is showing and routes clicks,
 * hover and keys to {@link RevealOverlay} in canvas coordinates. Fanfares are
 * non-modal: nothing is consumed and gameplay input passes straight through.
 *
 * <p>The gate is deliberately narrow. Every consume site asks for a modal that
 * is being <em>painted</em> ({@code isModalInteractive()}, not
 * {@code isModalActive()}) on a client that is <em>in game</em>. Input the user
 * cannot see a reason for losing is unrecoverable — there is no visible modal to
 * dismiss and, at the login screen, not even a plugin panel in reach.
 */
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class RevealInputListener implements MouseListener, MouseWheelListener, KeyListener {
	private final Client client;
	private final RevealOverlay overlay;

	/** Whether this listener may swallow the event it was just handed. */
	private boolean shouldConsume() {
		return client.getGameState() == GameState.LOGGED_IN && overlay.isModalInteractive();
	}

	private void syncHover(MouseEvent e) {
		if (e == null)
			return;
		if (!shouldConsume()) {
			overlay.setPointer(null);
			return;
		}
		overlay.setPointer(e.getPoint());
	}

	@Override
	public MouseEvent mouseClicked(MouseEvent e) {
		if (e == null || !shouldConsume())
			return e;
		e.consume();
		return e;
	}

	@Override
	public MouseEvent mousePressed(MouseEvent e) {
		if (e == null)
			return e;
		syncHover(e);
		if (!shouldConsume())
			return e;
		if (e.getButton() == MouseEvent.BUTTON1)
			overlay.handleClick(e.getPoint());
		e.consume();
		return e;
	}

	@Override
	public MouseEvent mouseReleased(MouseEvent e) {
		if (e == null || !shouldConsume())
			return e;
		e.consume();
		return e;
	}

	@Override
	public MouseEvent mouseEntered(MouseEvent e) {
		if (e == null || !shouldConsume())
			return e;
		e.consume();
		return e;
	}

	@Override
	public MouseEvent mouseExited(MouseEvent e) {
		if (e == null || !shouldConsume())
			return e;
		e.consume();
		return e;
	}

	@Override
	public MouseEvent mouseDragged(MouseEvent e) {
		if (e == null)
			return e;
		syncHover(e);
		if (!shouldConsume())
			return e;
		e.consume();
		return e;
	}

	@Override
	public MouseEvent mouseMoved(MouseEvent e) {
		if (e == null)
			return e;
		syncHover(e);
		if (!shouldConsume())
			return e;
		e.consume();
		return e;
	}

	@Override
	public MouseWheelEvent mouseWheelMoved(MouseWheelEvent e) {
		if (e == null)
			return e;
		syncHover(e);
		if (!shouldConsume())
			return e;
		e.consume();
		return e;
	}

	@Override
	public void keyTyped(KeyEvent e) {
		if (e == null || !shouldConsume())
			return;
		e.consume();
	}

	@Override
	public void keyPressed(KeyEvent e) {
		if (e == null || !shouldConsume())
			return;
		if (e.getKeyCode() == KeyEvent.VK_ESCAPE)
			overlay.handleEscape();
		else if (e.getKeyCode() == KeyEvent.VK_SPACE) {
			overlay.handleAdvance();
		}
		e.consume();
	}

	@Override
	public void keyReleased(KeyEvent e) {
		if (e == null || !shouldConsume())
			return;
		e.consume();
	}
}

package com.gachaman.overlay;

import java.awt.*;
import java.awt.geom.*;

/**
 * Draws the chrome of the unrolling contract scrolls used by the TASK_OFFERS
 * ceremony in {@link RevealOverlay}: the two wooden rollers (cylinders with
 * end caps) and the tinted parchment sheet stretched between them. Stateless
 * pure drawing - all animation timing and clipping live in the caller.
 */
final class ScrollPainter {
	/** Roller (cylinder) diameter in px. */
	static final int ROLLER_H = 18;
	/**
	 * Horizontal inset of the parchment sheet from the scroll bounds.
	 *
	 * <p>Wide enough that the sheet clearly hangs BETWEEN the rollers rather than
	 * running out to their end caps. At 6 the paper reached almost to the knobs,
	 * so the rods read as trim glued along a card's edges instead of two rods
	 * with a sheet wound on them.
	 */
	static final int PARCH_INSET = 15;
	/** Height of the vertically squashed "curl" band at each unrolling edge. */
	static final int CURL_BAND = 12;

	private static final int CAP_W = 7;
	private static final int EDGE_REACH = 8;

	private static final Color EDGE_SHADE = new Color(60, 42, 20, 90);
	private static final Color EDGE_CLEAR = new Color(60, 42, 20, 0);
	private static final Color VIGNETTE = new Color(120, 96, 60, 70);
	private static final Color VIGNETTE_CLEAR = new Color(120, 96, 60, 0);
	/** Wood fibre running the length of a roller. */
	private static final Color GRAIN = new Color(52, 34, 14, 55);
	/** Handling stain along the sheet's top and bottom edges. */
	private static final Color AGE = new Color(112, 84, 46, 46);
	private static final Color AGE_CLEAR = new Color(112, 84, 46, 0);
	/** Soft shadow: many faint passes rather than a few strong ones. */
	private static final int SHADOW_STEPS = 5;
	private static final int SHADOW_DROP = 5;
	private static final Color SHADOW_STEP = new Color(0, 0, 0, 11);

	private ScrollPainter() {
	}

	/** Center Y of the top roller at unroll progress u (0 = closed, 1 = open). */
	static int topRollerCy(Rectangle r, double u) {
		double closed = r.y + r.height / 2.0 - ROLLER_H / 2.0;
		double open = r.y + ROLLER_H / 2.0;
		return (int) Math.round(closed + (open - closed) * u);
	}

	/** Center Y of the bottom roller at unroll progress u (0 = closed, 1 = open). */
	static int bottomRollerCy(Rectangle r, double u) {
		double closed = r.y + r.height / 2.0 + ROLLER_H / 2.0;
		double open = r.y + r.height - ROLLER_H / 2.0;
		return (int) Math.round(closed + (open - closed) * u);
	}

	/**
	 * A horizontal wooden roller spanning the scroll bounds, centred on cy.
	 *
	 * <p>Nine-sliced rather than drawn: the cylinder's gradient runs purely
	 * vertically, so the middle is uniform along x and one narrow strip
	 * stretches to any scroll width exactly. Only the rounded ends and the end
	 * caps are fixed-width, and they blit unscaled.
	 *
	 * @param spin 0..1 phase of the grain, so a rolling scroll looks like it is
	 *             turning rather than sliding. The fibres stay procedural for
	 *             exactly that reason - they are the only part that moves.
	 */
	static void drawRoller(Graphics2D g, Rectangle r, int cy, Color tier, double spin) {
		int y = cy - ROLLER_H / 2;
		int bodyX = r.x + CAP_W - 2;
		int bodyW = r.width - (CAP_W - 2) * 2;
		String k = String.format("%06x", tier.getRGB() & 0xFFFFFF);
		int end = ROLLER_H / 2;
		ArtCache.blit(g, "roller-" + k + "-l", bodyX, y, end, ROLLER_H);
		ArtCache.blit(g, "roller-" + k + "-m", bodyX + end, y, bodyW - end * 2, ROLLER_H);
		ArtCache.blit(g, "roller-" + k + "-r", bodyX + bodyW - end, y, end, ROLLER_H);

		Shape clip = g.getClip();
		g.clip(new RoundRectangle2D.Float(bodyX, y, bodyW, ROLLER_H, ROLLER_H, ROLLER_H));
		g.setColor(GRAIN);
		for (int i = 0; i < 3; i++) {
			// floorMod, not %: the top roller spins backwards and Java's remainder
			// keeps the sign, which would push the grain off the clip entirely
			double phase = (((spin + i / 3.0) % 1.0) + 1.0) % 1.0;
			int gy = y + 2 + (int) Math.round(phase * (ROLLER_H - 4));
			g.drawLine(bodyX + 3, gy, bodyX + bodyW - 3, gy);
		}
		g.setClip(clip);

		ArtCache.blit(g, "roller-" + k + "-cap", r.x, y - 2, CAP_W, ROLLER_H + 4);
		ArtCache.blit(g, "roller-" + k + "-cap", r.x + r.width - CAP_W, y - 2, CAP_W, ROLLER_H + 4);
	}

	/**
	 * The parchment sheet at its full, final position: vertical paper
	 * gradient, aged vignette down both long edges, and tier-colored hairline
	 * borders. Callers clip this to the revealed window between the rollers.
	 */
	static void drawParchment(Graphics2D g, int x, int y, int w, int h,
		Color top, Color bottom, Color border) {
		g.setPaint(new GradientPaint(x, y, top, x, y + h, bottom));
		g.fillRect(x, y, w, h);

		// bow shading and paper fibre: both are pure fractions of the sheet, so
		// one stretched image (authored by com.gachaman.tools.ScrollArt)
		// reproduces them at any scroll size
		ArtCache.blit(g, "parchment-texture", x, y, w, h);

		// aged edges: the top and bottom of a sheet darken where it has been
		// handled, and it stops the paper reading as a flat swatch of colour
		int age = Math.min(18, h / 5);
		if (age > 2) {
			g.setPaint(new GradientPaint(0, y, AGE, 0, y + age, AGE_CLEAR));
			g.fillRect(x, y, w, age);
			g.setPaint(new GradientPaint(0, y + h, AGE, 0, y + h - age, AGE_CLEAR));
			g.fillRect(x, y + h - age, w, age);
		}

		int vig = Math.min(14, w / 6);
		g.setPaint(new GradientPaint(x, 0, VIGNETTE, x + vig, 0, VIGNETTE_CLEAR));
		g.fillRect(x, y, vig, h);
		g.setPaint(new GradientPaint(x + w, 0, VIGNETTE, x + w - vig, 0, VIGNETTE_CLEAR));
		g.fillRect(x + w - vig, y, vig, h);
		g.setColor(border);
		g.drawLine(x, y, x, y + h - 1);
		g.drawLine(x + w - 1, y, x + w - 1, y + h - 1);
	}

	/**
	 * A soft drop shadow under the whole scroll, so it sits above the scene
	 * rather than being printed on it. Drawn before anything else.
	 */
	static void drawDropShadow(Graphics2D g, Rectangle r, double u) {
		int top = topRollerCy(r, u) - ROLLER_H / 2;
		int bot = bottomRollerCy(r, u) + ROLLER_H / 2;
		int h = bot - top;
		if (h <= 0)
			return;
		// Largest and faintest first, each smaller pass laid over the last, so the
		// alpha ACCUMULATES toward the middle and falls off at the rim.
		//
		// The previous version varied alpha per ring and floored it at 3, which
		// put a visible hard-edged step at the outermost ring and stacked to a
		// near-solid slab behind the scroll — it read as a dark panel the scroll
		// was mounted on rather than as light being blocked.
		for (int i = SHADOW_STEPS; i >= 1; i--) {
			int grow = i * 3;
			g.setColor(SHADOW_STEP);
			g.fillRoundRect(r.x - grow, top - grow + SHADOW_DROP,
				r.width + grow * 2, h + grow * 2, 12 + grow, 12 + grow);
		}
	}

	/**
	 * Contact shading where the sheet disappears behind a roller: darkest at
	 * edgeY, fading over a few px {@code fromTop ? downward : upward}.
	 */
	static void drawEdgeShade(Graphics2D g, int x, int w, int edgeY, boolean fromTop) {
		if (fromTop) {
			g.setPaint(new GradientPaint(0, edgeY, EDGE_SHADE, 0, edgeY + EDGE_REACH, EDGE_CLEAR));
			g.fillRect(x, edgeY, w, EDGE_REACH);
		}
		else {
			g.setPaint(new GradientPaint(0, edgeY, EDGE_SHADE, 0, edgeY - EDGE_REACH, EDGE_CLEAR));
			g.fillRect(x, edgeY - EDGE_REACH, w, EDGE_REACH);
		}
	}

}

package com.gachaman.overlay;

import com.gachaman.model.*;
import com.gachaman.service.*;
import java.awt.*;
import javax.inject.*;
import net.runelite.api.*;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.*;
import net.runelite.client.ui.overlay.*;

/**
 * Crosses out the equipment-tab slots no Deed has opened yet, so the lock is
 * visible where the player actually looks for it rather than only in the
 * loadout board.
 *
 * <p>Drawn over EMPTY slots too, which is why this cannot be a
 * {@link net.runelite.client.ui.overlay.WidgetItemOverlay} like the forbidden-item
 * marker: that renders per item, and an undeeded slot is usually bare.
 */
@Singleton
public class SlotLockOverlay extends Overlay {
	/**
	 * Slot widget per {@link GearSlot}, in declaration order. The ids are NOT
	 * contiguous — the equipment interface skips 6, 8 and 11 — so this is a
	 * table rather than arithmetic on the slot index.
	 */
	private static final int[] SLOT_WIDGETS = {
		InterfaceID.Wornitems.SLOT0,   // HEAD
		InterfaceID.Wornitems.SLOT1,   // CAPE
		InterfaceID.Wornitems.SLOT2,   // AMULET
		InterfaceID.Wornitems.SLOT3,   // WEAPON
		InterfaceID.Wornitems.SLOT4,   // BODY
		InterfaceID.Wornitems.SLOT5,   // SHIELD
		InterfaceID.Wornitems.SLOT7,   // LEGS
		InterfaceID.Wornitems.SLOT9,   // HANDS
		InterfaceID.Wornitems.SLOT10,  // FEET
		InterfaceID.Wornitems.SLOT12,  // RING
		InterfaceID.Wornitems.SLOT13,  // AMMO
	};

	private static final Color SCRIM = new Color(0, 0, 0, 120);
	private static final Color CROSS = new Color(200, 60, 50, 210);
	private static final BasicStroke CROSS_STROKE = new BasicStroke(2f);
	private static final int INSET = 4;

	private final Client client;
	private final PermissionService permissionService;
	private final GachaStateService stateService;

	@Inject
	public SlotLockOverlay(Client client, PermissionService permissionService,
		GachaStateService stateService) {
		this.client = client;
		this.permissionService = permissionService;
		this.stateService = stateService;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPriority(Overlay.PRIORITY_LOW);
	}

	@Override
	public Dimension render(Graphics2D g) {
		// Fail open, exactly as the permission check does: an unloaded save has
		// an EMPTY deeded set, which would read as "every slot is locked" and
		// flash eleven crosses across the tab on every login.
		if (stateService.get() == null)
			return null;
		// The equipment widgets can EXIST with garbage bounds outside the game
		// view, so trust them only when the panel root and the head slot agree —
		// the same guard the loadout button uses, for the same ghosting reason.
		Widget root = client.getWidget(InterfaceID.Wornitems.UNIVERSE);
		if (root == null || root.isHidden())
			return null;
		Rectangle rootBounds = root.getBounds();
		if (rootBounds == null || rootBounds.width < 100 || rootBounds.height < 100)
			return null;
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		for (GearSlot slot : GearSlot.values()) {
			if (permissionService.isSlotDeeded(slot))
				continue;
			Widget widget = client.getWidget(SLOT_WIDGETS[slot.ordinal()]);
			if (widget == null || widget.isHidden())
				continue;
			Rectangle b = widget.getBounds();
			if (b == null || b.width <= 0 || b.height <= 0
				|| !rootBounds.contains(b.x + b.width / 2, b.y + b.height / 2)) {
				continue; // stale or off-panel bounds — draw nothing rather than ghost
			}
			g.setColor(SCRIM);
			g.fillRect(b.x, b.y, b.width, b.height);
			g.setColor(CROSS);
			g.setStroke(CROSS_STROKE);
			int x1 = b.x + INSET;
			int y1 = b.y + INSET;
			int x2 = b.x + b.width - INSET;
			int y2 = b.y + b.height - INSET;
			g.drawLine(x1, y1, x2, y2);
			g.drawLine(x1, y2, x2, y1);
		}
		return null;
	}
}

package com.gachaman.overlay;

import java.util.List;
import java.awt.Point;
import com.gachaman.*;
import com.gachaman.model.*;
import com.gachaman.service.*;
import java.awt.*;
import java.util.*;
import javax.inject.*;
import lombok.*;
import net.runelite.api.*;
import net.runelite.client.ui.overlay.*;
import net.runelite.client.ui.overlay.components.*;

/**
 * Movable/dockable task progress panel: standard RuneLite OverlayPanel the
 * player can drag into any snap corner (alt-drag / overlay manage mode works
 * out of the box). Shows the active task monster, difficulty-colored progress
 * bar and a compact side-bet counter; when only rolled offers are pending it
 * collapses to a one-line reminder. Hidden entirely when there is nothing to
 * show. Steady-state frames build no new strings — labels are cached and only
 * rebuilt when the underlying counts change.
 */
@Singleton
public class TaskProgressOverlay extends OverlayPanel {
	private static final Color GOLD = new Color(255, 205, 70);
	private static final Color MUTED = new Color(170, 170, 170);
	private static final Color BAR_BG = new Color(24, 24, 24, 210);
	private static final Color DONE_GREEN = new Color(120, 220, 120);
	private static final String TITLE = "Gachaman contract";
	private static final String OFFERS_WAITING = "Contracts rolled — view and pick one";
	private static final String NO_TASK = "No contract — roll one in the Gachaman panel";
	private static final String SIDE_BETS_LABEL = "Side bets";
	private static final String DOCKET_LABEL = "Double Docket";
	/** Constant expression, so the steady-state frame still allocates nothing. */
	private static final String DOCKET_VALUE = "x" + Tuning.DOUBLE_DOCKET_MULT;

	private final GachaStateService stateService;
	private final Client client;
	private final TaskService taskService;
	private final KillTracker killTracker;
	private final ProgressBarComponent progressBar = new ProgressBarComponent();
	private final ComboMeterComponent comboMeter = new ComboMeterComponent();

	// caches so unchanged frames allocate no new strings/colors
	private String monsterLine;
	private String monsterLineName;
	private TaskDifficulty monsterLineDifficulty;
	private String progressLabel;
	private int progressKills = -1;
	private int progressRequired = -1;
	private boolean progressHalf;
	private String[] sideBetLines;
	private String[] sideBetStatus;
	private boolean[] sideBetDoneFlags;
	private String sideBetTaskName;
	private int sideBetDone = -1;
	private int sideBetTotal = -1;
	/**
	 * Which CONTRACT the cached lines were built for.
	 *
	 * <p>The other three fields do not identify one: finish a Goblin contract with both
	 * side bets unclaimed and take a second Goblin contract that also carries two, and
	 * (done, total, monsterName) is identical across the boundary — so the HUD went on
	 * listing the first contract's objectives and payouts under the second one, and kept
	 * doing so until a real bet completed. The null gap between contracts does not clear
	 * it either; the {@code task == null} early return leaves every field standing.
	 */
	private long sideBetAcceptedAt = -1;
	private Color barColor;
	private TaskDifficulty barColorDifficulty;

	@Inject
	public TaskProgressOverlay(GachaStateService stateService, Client client,
		TaskService taskService, KillTracker killTracker) {
		this.stateService = stateService;
		this.client = client;
		this.taskService = taskService;
		this.killTracker = killTracker;
		setPosition(OverlayPosition.TOP_LEFT);
		progressBar.setMinimum(0);
		progressBar.setMaximum(100);
		progressBar.setBackgroundColor(BAR_BG);
		progressBar.setFontColor(Color.WHITE);
		progressBar.setLabelDisplayMode(ProgressBarComponent.LabelDisplayMode.TEXT_ONLY);
	}

	@Override
	public Dimension render(Graphics2D graphics) {
		GachaState state = stateService.get();
		if (state == null || TutorialGate.onTutorial(client))
			return null;
		ActiveTask task = state.getActiveTask();
		List<TaskOffer> offers = state.getPendingOffers();

		panelComponent.getChildren().clear();

		if (task == null) {
			// combat is locked without a task — always tell the player what to do
			boolean offersWaiting = offers != null && !offers.isEmpty();
			panelComponent.getChildren().add(LineComponent.builder()
				.left(offersWaiting ? OFFERS_WAITING : NO_TASK)
				.leftColor(offersWaiting ? GOLD : MUTED)
				.build());
			return super.render(graphics);
		}

		TaskDifficulty difficulty = task.getDifficulty();

		panelComponent.getChildren().add(TitleComponent.builder()
			.text(TITLE)
			.color(GOLD)
			.build());

		if (monsterLine == null || difficulty != monsterLineDifficulty
			|| !task.getMonsterName().equals(monsterLineName)) {
			monsterLineName = task.getMonsterName();
			monsterLineDifficulty = difficulty;
			monsterLine = monsterLineName + " (" + difficulty.getDisplayName() + ")";
		}
		panelComponent.getChildren().add(LineComponent.builder()
			.left(monsterLine)
			.leftColor(difficulty.getColor())
			.build());

		// shared (party) contracts pool everyone's kills into the quota
		int pooledKills = task.getKillsDone() + (task.isParty() ? task.getPartyOtherKills() : 0);
		// One left: the same signal the NPC highlighter paints on the targets
		// themselves, mirrored here because that overlay is config-toggled and a
		// player with highlighting off would otherwise get no warning at all.
		boolean lastOne = task.getKillsRequired() - pooledKills == 1;
		if (pooledKills != progressKills || task.getKillsRequired() != progressRequired
			|| task.isHalfKillPending() != progressHalf) {
			progressKills = pooledKills;
			progressRequired = task.getKillsRequired();
			progressHalf = task.isHalfKillPending();
			// a constant when it fires, so the no-allocation-per-frame rule this
			// cache exists for still holds, and the counter resumes after it
			progressLabel = lastOne ? "1 LEFT"
				: progressKills + (progressHalf ? ".5" : "") + "/" + progressRequired;
		}
		if (difficulty != barColorDifficulty) {
			barColorDifficulty = difficulty;
			Color c = difficulty.getColor();
			barColor = new Color(c.getRed(), c.getGreen(), c.getBlue(), 200);
		}
		double pct = task.getKillsRequired() <= 0 ? 0
			: Math.min(100.0, (pooledKills + (task.isHalfKillPending() ? 0.5 : 0))
				* 100.0 / task.getKillsRequired());
		progressBar.setValue(pct);
		progressBar.setCenterLabel(progressLabel);
		// the pulse is recomputed per frame rather than cached, which is the one
		// place the difficulty-keyed barColor cache is deliberately bypassed
		progressBar.setForegroundColor(lastOne
			? TaskNpcHighlightOverlay.finalTargetGold() : barColor);
		panelComponent.getChildren().add(progressBar);

		// rhythm combo meter (transient — lives in TaskService, KillTracker ticks)
		int nowTick = killTracker.currentTick();
		// shown from the first kill, not the first stack: with five kills to a
		// stack the chain would otherwise build invisibly for most of a minute
		int comboIdleLeft = taskService.comboIdleTicksRemaining(nowTick);
		if (comboIdleLeft > 0) {
			comboMeter.set(taskService.comboStacksAt(nowTick),
				taskService.comboProgressAt(nowTick), comboIdleLeft);
			panelComponent.getChildren().add(comboMeter);
		}

		// Latched-only here: the HUD is the terse view, so it states the bonus a
		// player HAS. The sidebar carries the always-visible "not your Slayer
		// task" case and the rule behind it.
		if (task.isSlayerAligned()) {
			panelComponent.getChildren().add(LineComponent.builder()
				.left(DOCKET_LABEL)
				.leftColor(DONE_GREEN)
				.right(DOCKET_VALUE)
				.rightColor(GOLD)
				.build());
		}

		List<SideBet> sideBets = task.getSideBets();
		int total = sideBets == null ? 0 : sideBets.size();
		if (total > 0) {
			int done = 0;
			for (int i = 0; i < total; i++) {
				if (sideBets.get(i).isCompleted())
					done++;
			}
			// rebuild the per-bet lines only when the task or a completion changes
			if (sideBetLines == null || done != sideBetDone || total != sideBetTotal
				|| !task.getMonsterName().equals(sideBetTaskName)
				|| task.getAcceptedAtMs() != sideBetAcceptedAt) {
				sideBetDone = done;
				sideBetTotal = total;
				sideBetTaskName = task.getMonsterName();
				sideBetAcceptedAt = task.getAcceptedAtMs();
				sideBetLines = new String[total];
				sideBetStatus = new String[total];
				sideBetDoneFlags = new boolean[total];
				for (int i = 0; i < total; i++) {
					SideBet bet = sideBets.get(i);
					sideBetLines[i] = TaskService.describeSideBet(bet);
					sideBetDoneFlags[i] = bet.isCompleted();
					// "*" not a check mark: the RuneScape faces have no U+2713. It only
					// looked right in testing because ComboMeterComponent leaves logical
					// SANS_SERIF on the shared Graphics2D while a combo is live — at rest
					// this line paints a tofu box.
					sideBetStatus[i] = bet.isCompleted()
						? "* +" + bet.getPayoutGc()
						: "+" + bet.getPayoutGc();
				}
			}
			panelComponent.getChildren().add(LineComponent.builder()
				.left(SIDE_BETS_LABEL)
				.leftColor(MUTED)
				.build());
			for (int i = 0; i < total; i++) {
				panelComponent.getChildren().add(LineComponent.builder()
					.left(sideBetLines[i])
					.leftColor(sideBetDoneFlags[i] ? DONE_GREEN : Color.WHITE)
					.right(sideBetStatus[i])
					.rightColor(sideBetDoneFlags[i] ? DONE_GREEN : GOLD)
					.build());
			}
		}

		return super.render(graphics);
	}

	/**
	 * Compact kill-tempo meter: bold xN counter, ten stack pips, and the idle
	 * countdown — a seconds label plus an arc draining over the full idle
	 * window, showing how long until the chain cancels. While the (shorter)
	 * growth window is still open the pips glow full; once it closes the pips
	 * dim to telegraph that the next kill maintains but does not build.
	 */
	private static final class ComboMeterComponent
		implements LayoutableRenderableEntity {
		private static final int HEIGHT = 16;

		@Getter
		private final Rectangle bounds = new Rectangle();
		@Setter
		private Point preferredLocation = new Point();
		private Dimension preferredSize = new Dimension(150, HEIGHT);

		private int stacks;
		private double progress;
		private int idleTicksRemaining;
		private String label = "";
		private int labelStacks = -1;
		private String secondsLabel = "";
		private int labelSeconds = -1;

		void set(int stacks, double progress, int idleTicksRemaining) {
			this.stacks = stacks;
			this.progress = progress;
			this.idleTicksRemaining = idleTicksRemaining;
			if (stacks != labelStacks) {
				labelStacks = stacks;
				// the payout, not the pip count — the pips already say that, and
				// the whole point of the flat ladder is being able to read it
				double m = Tuning.comboMultiplier(stacks);
				label = "x" + (m == Math.rint(m) ? String.valueOf((int) m) : String.valueOf(m));
			}
			// 1 game tick = 0.6s; round up so the label never reads 0s early
			int seconds = (int) Math.ceil(idleTicksRemaining * 0.6);
			if (seconds != labelSeconds) {
				labelSeconds = seconds;
				secondsLabel = seconds + "s";
			}
		}

		@Override
		public Dimension render(Graphics2D g) {
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,
				RenderingHints.VALUE_ANTIALIAS_ON);
			int x = preferredLocation.x;
			int y = preferredLocation.y;

			g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 12));
			g.setColor(GOLD);
			g.drawString(label, x, y + 12);
			int textW = g.getFontMetrics().stringWidth(label);

			// stack pips
			int px = x + textW + 8;
			int py = y + 5;
			Color empty = new Color(255, 205, 70, 60);
			// the pip being worked on brightens with each kill banked toward it,
			// so the five-kill climb to the next stack is legible at a glance
			Color filling = new Color(255, 205, 70, 60 + (int) Math.round(progress * 120));
			for (int i = 0; i < Tuning.COMBO_MAX_STACKS; i++) {
				g.setColor(i < stacks ? GOLD : i == stacks ? filling : empty);
				g.fillOval(px + i * 7, py, 5, 5);
			}

			// idle countdown: arc + seconds until the chain cancels; the last
			// ~15s turn red as the combo is about to drop
			double idleFraction = Math.max(0, Math.min(1.0,
				idleTicksRemaining / (double) Tuning.COMBO_IDLE_RESET_TICKS));
			boolean urgent = idleFraction <= 0.25;
			int ax = px + Tuning.COMBO_MAX_STACKS * 7 + 6;
			g.setColor(urgent ? new Color(230, 90, 70, 160) : new Color(255, 205, 70, 90));
			g.setStroke(new BasicStroke(2f));
			g.drawArc(ax, y + 2, 12, 12, 90, -(int) Math.round(360 * idleFraction));
			g.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, 11));
			g.setColor(urgent ? new Color(230, 90, 70) : MUTED);
			int sx = ax + 12 + 5;
			g.drawString(secondsLabel, sx, y + 12);
			int secondsW = g.getFontMetrics().stringWidth(secondsLabel);

			int width = sx + secondsW + 2 - x;
			bounds.setBounds(x, y, width, HEIGHT);
			return new Dimension(width, HEIGHT);
		}


		@Override
		public void setPreferredSize(Dimension size) {
			if (size != null)
				this.preferredSize = size;
		}
	}
}

package com.gachaman.overlay;

import com.gachaman.service.*;
import java.awt.*;
import java.awt.image.*;
import javax.inject.*;
import net.runelite.api.widgets.*;
import net.runelite.client.ui.overlay.*;

/**
 * Draws a crossed-circle icon over forbidden equipment in the inventory and
 * bank so the player can see at a glance what their cards do not permit.
 */
@Singleton
public class ForbiddenItemOverlay extends WidgetItemOverlay {
	private static final int ICON_SIZE = 14;

	private final PermissionService permissionService;
	private BufferedImage icon;

	@Inject
	public ForbiddenItemOverlay(PermissionService permissionService) {
		this.permissionService = permissionService;
		showOnInventory();
		showOnBank();
	}

	@Override
	public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem) {
		if (!permissionService.isForbidden(itemId))
			return;
		Rectangle bounds = widgetItem.getCanvasBounds();
		if (bounds == null)
			return;
		graphics.drawImage(getIcon(), bounds.x + bounds.width - ICON_SIZE, bounds.y, null);
	}

	private BufferedImage getIcon() {
		if (icon != null)
			return icon;
		BufferedImage image = new BufferedImage(ICON_SIZE, ICON_SIZE, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(new Color(0, 0, 0, 160));
		g.fillOval(0, 0, ICON_SIZE - 1, ICON_SIZE - 1);
		g.setColor(new Color(232, 60, 60));
		g.setStroke(new BasicStroke(2f));
		g.drawOval(1, 1, ICON_SIZE - 3, ICON_SIZE - 3);
		int inset = 3;
		g.drawLine(inset, ICON_SIZE - 1 - inset, ICON_SIZE - 1 - inset, inset);
		g.dispose();
		icon = image;
		return image;
	}
}

package com.gachaman.overlay;

import com.gachaman.*;
import com.gachaman.model.*;
import com.gachaman.service.*;
import java.awt.*;
import javax.inject.*;
import net.runelite.api.*;
import net.runelite.client.ui.overlay.*;
import net.runelite.client.util.*;

/** Outlines NPCs matching the active task (config-toggled). */
@Singleton
public class TaskNpcHighlightOverlay extends Overlay {
	private final Client client;
	private final GachaStateService stateService;
	private final GachamanConfig config;

	@Inject
	public TaskNpcHighlightOverlay(Client client, GachaStateService stateService, GachamanConfig config) {
		this.client = client;
		this.stateService = stateService;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics) {
		if (!config.highlightTaskNpc())
			return null;
		GachaState state = stateService.get();
		ActiveTask task = state == null ? null : state.getActiveTask();
		if (task == null)
			return null;
		// One left: the contract's biggest moment used to be a surprise, because
		// the golden burst fires AFTER the final kill lands. Marking the targets
		// that can finish it turns the last stretch into a hunt instead — you see
		// the gold, you pick one, you go. Nothing mechanical changes: these are
		// the same NPCs, already outlined, in the same places.
		int remaining = task.getKillsRequired()
			- (task.getKillsDone() + (task.isParty() ? task.getPartyOtherKills() : 0));
		boolean lastOne = remaining == 1;
		Color color = lastOne ? finalTargetGold() : task.getDifficulty().getColor();
		Color fill = new Color(color.getRed(), color.getGreen(), color.getBlue(), lastOne ? 60 : 30);
		graphics.setStroke(new BasicStroke(2f));
		for (NPC npc : client.getTopLevelWorldView().npcs()) {
			if (npc == null)
				continue;
			String name = npc.getName();
			if (name == null || !Text.removeTags(name).equalsIgnoreCase(task.getMonsterName())
				|| npc.isDead()) {
				continue;
			}
			Shape hull = npc.getConvexHull();
			if (hull != null) {
				graphics.setColor(fill);
				graphics.fill(hull);
				graphics.setColor(color);
				graphics.draw(hull);
			}
		}
		return null;
	}

	/**
	 * Gold, pulsing about three times a second so it reads as urgency rather
	 * than decoration. Derived from wall-clock rather than a tick so it keeps
	 * breathing while the player stands still deciding which one to take.
	 */
	static Color finalTargetGold() {
		double phase = (Math.sin(System.currentTimeMillis() / 160.0) + 1) / 2;
		return new Color(255, 205, 70, (int) (170 + 85 * phase));
	}
}

package com.gachaman.overlay;

import java.util.List;
import com.gachaman.*;
import com.google.gson.*;
import java.awt.*;
import java.io.*;
import java.nio.charset.*;
import java.util.*;
import javax.imageio.*;
import javax.inject.*;
import lombok.extern.slf4j.*;

/**
 * Plays the pre-rendered chest ceremony: body, lid, chains, padlock, strain,
 * seam leak, glow and motes, as one frame sequence per tier.
 *
 * <p>The whole ceremony is a pure function of (tier, elapsed) - the chest and
 * camera shakes are translations the caller applies, and every other input is
 * derived from el - so it bakes exactly. Frames are cropped to their own alpha
 * bounds with the offset carried in the index, which is what keeps a whipping
 * chain or a blasted lid from paying for the empty space around it.
 *
 * <p>Authored by com.gachaman.overlay.CeremonyArt (test scope), which holds the
 * procedural source.
 */
@Slf4j
@Singleton
class CeremonyPlayer {
	/** Frames are authored against a 300x225 chest and scaled from there. */
	private static final int ART_W = 300;
	private static final int ART_H = 225;

	private final Gson gson;
	private Index index;

	@Inject
	CeremonyPlayer(Gson gson) {
		this.gson = gson;
	}

	/**
	 * Bounded frame cache.
	 *
	 * <p>A ceremony walks its frames in order and never looks back, so holding
	 * all of them is pure waste: the ORNATE sequence alone decodes to 55 MB.
	 * Eight is comfortably more than the one frame in flight, absorbs the
	 * upgrade crossfade (which touches two tiers' frame 0 together) and the
	 * deal phase (which parks on the last frame), and caps the player at a few
	 * MB. A miss costs one small PNG decode inside a 50ms frame budget.
	 */
	private static final int CACHE = 8;
	private final Map<String, Image> frames =
		new LinkedHashMap<String, Image>(16, 0.75f, true) {
			@Override
			protected boolean removeEldestEntry(Map.Entry<String, Image> eldest) {
				return size() > CACHE;
			}
		};

	private static final class Index {
		int fps;
		Map<String, List<List<Integer>>> tiers;
	}

	private Index index() {
		if (index == null) {
			Index loaded = null;
			try (InputStream in = CeremonyPlayer.class.getResourceAsStream(
				"/com/gachaman/art/ceremony/chest-ceremony.json")) {
				if (in != null) {
					loaded = gson.fromJson(
						new InputStreamReader(in, StandardCharsets.UTF_8), Index.class);
				}
			}
			catch (Exception e) {
				log.warn("chest ceremony index missing", e);
			}
			if (loaded == null || loaded.tiers == null) {
				loaded = new Index();
				loaded.fps = 20;
				loaded.tiers = new HashMap<>();
			}
			index = loaded;
		}
		return index;
	}

	/** Frame count for a tier, or 0 when the art is unavailable. */
	int frames(Tuning.Chest tier) {
		List<List<Integer>> f = index().tiers.get(tier.name().toLowerCase(Locale.ROOT));
		return f == null ? 0 : f.size();
	}

	/** The frame index this many ms into the ceremony, clamped to the last one. */
	int frameAt(Tuning.Chest tier, long el) {
		int n = frames(tier);
		if (n == 0)
			return -1;
		int i = (int) (el * index().fps / 1000L);
		return Math.max(0, Math.min(n - 1, i));
	}

	int lastFrame(Tuning.Chest tier) {
		return Math.max(0, frames(tier) - 1);
	}

	/**
	 * Blits one ceremony frame with the chest centred on (cx, cy).
	 *
	 * @return false when the art could not be loaded, so the caller can fall
	 *         back rather than draw nothing
	 */
	boolean draw(Graphics2D g, int cx, int cy, int w, int h, Tuning.Chest tier, int frame,
		float alpha) {
		List<List<Integer>> offsets = index().tiers.get(tier.name().toLowerCase(Locale.ROOT));
		if (offsets == null || frame < 0 || frame >= offsets.size())
			return false;
		String key = tier.name() + frame;
		Image art = frames.computeIfAbsent(key, k -> {
			try (InputStream in = CeremonyPlayer.class.getResourceAsStream(
				String.format("/com/gachaman/art/ceremony/chest-%s-%03d.png",
					tier.name().toLowerCase(Locale.ROOT), frame))) {
				return in == null ? null : ImageIO.read(in);
			}
			catch (Exception e) {
				return null;
			}
		});
		if (art == null)
			return false;
		double sx = w / (double) ART_W;
		double sy = h / (double) ART_H;
		List<Integer> at = offsets.get(frame);
		int dx = cx + (int) Math.round(at.get(0) * sx);
		int dy = cy + (int) Math.round(at.get(1) * sy);
		Composite old = null;
		if (alpha < 0.999f) {
			old = g.getComposite();
			g.setComposite(AlphaComposite.getInstance(
				AlphaComposite.SRC_OVER, Math.max(0f, alpha)));
		}
		// index carries the AUTHORED size, which is not the stored size: a frame
		// whose decoded bytes would pass the Plugin Hub's 1 MiB image limit is
		// stored smaller and stretched back here, so the art keeps its extent
		g.drawImage(art, dx, dy,
			(int) Math.round(at.get(2) * sx),
			(int) Math.round(at.get(3) * sy), null);
		if (old != null)
			g.setComposite(old);
		return true;
	}
}

