import net.runelite.client.ui.*;
import net.runelite.client.util.*;

/**
 * The Gachaman sidebar: a tab strip over a CardLayout hosting the tabs.
 * While the card database is still scanning the item cache, every tab shows a
 * centered scan-progress message polled by a Swing timer (only while visible).
 * refresh() is EDT-safe and coalesced; only the selected tab is rebuilt, the
 * rest are marked dirty and rebuilt lazily on selection.
 */
@Slf4j
@Singleton
public class GachamanPanel extends PluginPanel implements GachaStateService.Listener {
	private enum Tab {
		OVERVIEW("Overview"),
		SHOP("Shop"),
		ALBUM("Album"),
		SETS("Sets"),
		JOURNAL("Journal"),
		TIMELINE("Timeline"),
		DOSSIER("Dossier"),
		PARTY("Party"),
		PATRONS("Patrons"),
		LOADOUT("Loadout"),
		HELP("Help");

		private final String label;

		Tab(String label) {
			this.label = label;
		}
	}

	private static final String CARD_LOADING = "LOADING";
	private static final int SCAN_POLL_MS = 400;
	private static final String GITHUB_URL = "https://github.com/BraveH/Gachaman";
	private static final String KOFI_URL = "https://ko-fi.com/amrothabet";


	private final GachaStateService stateService;
	private final CardDatabase cardDatabase;
	// Only the two tabs the plugin later pushes a supplier into keep a field.
	// The other nine became write-only the moment their rebuild() moved into the
	// rebuilders map below: the constructor parameter is enough to build the card
	// and capture the method reference, so a second reference bought nothing.
	private final OverviewTab overviewTab;
	private final PartyTab partyTab;

	private final CardLayout contentLayout = new CardLayout();
	private final JPanel content = new JPanel(contentLayout);
	private final JLabel scanLabel = new JLabel("", SwingConstants.CENTER);
	private final Map<Tab, JButton> tabButtons = new EnumMap<>(Tab.class);
	// One rebuild() per tab, registered next to the card it redraws. This replaces
	// an eleven-arm switch whose every arm was the same statement with a different
	// receiver — a shape that can silently go stale against the enum, where a
	// missing registration here surfaces through the log line rebuildIfDirty
	// already writes.
	private final EnumMap<Tab, Runnable> rebuilders = new EnumMap<>(Tab.class);
	private final EnumSet<Tab> dirty = EnumSet.allOf(Tab.class);
	private final AtomicBoolean refreshQueued = new AtomicBoolean();

	private Tab selected = Tab.OVERVIEW;
	// volatile for the same reason as started/active below: this field is WRITTEN
	// on the EDT (ensureScanTimer, reached from onActivate and refreshNow) but
	// READ from the client thread, because GachamanPlugin.shutDown calls stop() ->
	// stopScanTimer() there. Without it the client thread may read a stale null
	// and skip stopping a live 400ms poll. javax.swing.Timer.stop() is itself
	// thread-safe, so publishing the reference is the whole of what is needed.
	private volatile Timer scanTimer;
	private volatile boolean started;
	private volatile boolean active;

	private final GachamanConfig config;
	private JPanel tabRow;

	@Inject
	public GachamanPanel(
		GachaStateService stateService,
		CardDatabase cardDatabase,
		OverviewTab overviewTab,
		ShopTab shopTab,
		AlbumTab albumTab,
		SetsTab setsTab,
		JournalTab journalTab,
		TimelineTab timelineTab,
		DossierTab dossierTab,
		PartyTab partyTab,
		PatronsTab patronsTab,
		LoadoutTab loadoutTab,
		HelpTab helpTab,
		GachamanConfig config) {
		super(false);
		this.config = config;
		this.stateService = stateService;
		this.cardDatabase = cardDatabase;
		this.overviewTab = overviewTab;
		this.partyTab = partyTab;

		setLayout(new BorderLayout(0, 6));
		setBorder(new EmptyBorder(6, 6, 6, 6));
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		JPanel header = new JPanel(new BorderLayout(0, 6));
		header.setOpaque(false);
		JPanel titleRow = new JPanel(new BorderLayout(6, 0));
		titleRow.setOpaque(false);
		JLabel titleLabel = new JLabel("Gachaman");
		titleLabel.setFont(FontManager.getRunescapeBoldFont().deriveFont(18f));
		titleLabel.setForeground(Color.WHITE);
		titleRow.add(titleLabel, BorderLayout.CENTER);
		JPanel links = new JPanel(new FlowLayout(FlowLayout.RIGHT, 4, 0));
		links.setOpaque(false);
		links.add(linkIcon(icon("link-github"), icon("link-github-hover"), GITHUB_URL,
			"Gachaman on GitHub — source, issues and releases"));
		links.add(linkIcon(icon("link-kofi"), icon("link-kofi-hover"), KOFI_URL,
			"Support Gachaman on Ko-fi"));
		titleRow.add(links, BorderLayout.EAST);
		header.add(titleRow, BorderLayout.NORTH);

		tabRow = new JPanel(new GridLayout(0, 3, 3, 3));
		tabRow.setOpaque(false);
		for (Tab tab : Tab.values()) {
			JButton button = new JButton(tab.label);
			button.setFont(FontManager.getRunescapeSmallFont());
			button.setFocusPainted(false);
			button.setMargin(new Insets(2, 2, 2, 2));
			button.addActionListener(e -> selectTab(tab));
			tabButtons.put(tab, button);
			tabRow.add(button);
		}
		header.add(tabRow, BorderLayout.CENTER);
		add(header, BorderLayout.NORTH);
		updateTabVisibility();

		content.setOpaque(false);
		// the scan card is exactly centeredNote()'s panel with the label handed in
		// rather than created, so the two "nothing to show yet" screens cannot drift
		content.add(centered(scanLabel), CARD_LOADING);
		addCard(Tab.OVERVIEW, wrapScroll(overviewTab), overviewTab::rebuild);
		addCard(Tab.SHOP, wrapScroll(shopTab), shopTab::rebuild);
		addCard(Tab.ALBUM, albumTab, albumTab::rebuild); // album manages its own scroll
		addCard(Tab.SETS, wrapScroll(setsTab), setsTab::rebuild);
		addCard(Tab.JOURNAL, wrapScroll(journalTab), journalTab::rebuild);
		addCard(Tab.TIMELINE, timelineTab, timelineTab::rebuild); // timeline scrolls itself
		addCard(Tab.DOSSIER, dossierTab, dossierTab::rebuild); // dossier pins its totals outside the scroll
		addCard(Tab.PARTY, wrapScroll(partyTab), partyTab::rebuild);
		addCard(Tab.PATRONS, patronsTab, patronsTab::rebuild); // patrons pins its totals outside the scroll
		addCard(Tab.LOADOUT, wrapScroll(loadoutTab), loadoutTab::rebuild);
		addCard(Tab.HELP, wrapScroll(helpTab), helpTab::rebuild);
		add(content, BorderLayout.CENTER);

		updateTabButtonStyles();
		updateScanLabel();
		contentLayout.show(content, CARD_LOADING);
	}

	// --- Lifecycle ---

	public void start() {
		started = true;
		stateService.addListener(this);
		cardDatabase.onReady(this::refresh);
		refresh();
	}

	public void stop() {
		started = false;
		stateService.removeListener(this);
		stopScanTimer();
	}

	@Override
	public void onActivate() {
		active = true;
		ensureScanTimer();
		refresh();
	}

	@Override
	public void onDeactivate() {
		active = false;
		stopScanTimer();
	}

	/** Wired later by the plugin: whether the player is in a party (party offers). */
	public void setInPartySupplier(BooleanSupplier supplier) {
		overviewTab.setInPartySupplier(supplier);
	}

	/**
	 * Wired later by the plugin: the live party vote, or null when none is open.
	 *
	 * <p>Pushed in rather than injected, for the same reason as the supplier
	 * above — the panel is built by Guice and the party layer takes its hooks
	 * from the plugin, so a constructor dependency here would be the one edge
	 * that points backwards.
	 */
	public void setVoteViewSupplier(
		Supplier<PartyRollService.VoteView> supplier) {
		partyTab.setVoteViewSupplier(supplier);
	}

	// --- State listener ---

	@Override
	public void onStateChanged(GachaState newState) {
		refresh();
	}

	/** EDT-safe, coalesced refresh. Cheap to call from any thread, any rate. */
	public void refresh() {
		if (!refreshQueued.compareAndSet(false, true))
			return;
		SwingUtilities.invokeLater(() -> {
			refreshQueued.set(false);
			refreshNow();
		});
	}

	private void refreshNow() {
		if (!started)
			return;
		dirty.addAll(EnumSet.allOf(Tab.class));
		// on every refresh, not just on a config change: the first filed contract
		// and the first shared one are STATE changes, and a tab the player just
		// earned should appear on the refresh that earned it
		updateTabVisibility();
		if (!cardDatabase.isReady()) {
			updateScanLabel();
			contentLayout.show(content, CARD_LOADING);
			ensureScanTimer();
			return;
		}
		stopScanTimer();
		if (active || isShowing())
			rebuildIfDirty(selected);
		contentLayout.show(content, selected.name());
	}

	// --- Tabs ---

	private void selectTab(Tab tab) {
		selected = tab;
		updateTabButtonStyles();
		if (!cardDatabase.isReady()) {
			contentLayout.show(content, CARD_LOADING);
			return;
		}
		rebuildIfDirty(tab);
		contentLayout.show(content, tab.name());
	}

	/**
	 * Register a tab's card and the call that redraws it, in one place so the two
	 * cannot be added independently.
	 *
	 * <p>Every path that can reach {@link #rebuildIfDirty} must run after this —
	 * a tab with a card but no rebuilder would NPE inside the try below and be
	 * logged instead of drawn. The one caller that runs earlier in the
	 * constructor is {@link #updateTabVisibility}, and it only reaches
	 * rebuildIfDirty through its "selected tab went away" fallback, which cannot
	 * fire there: the selected tab is still Overview, Overview takes the
	 * always-visible {@code default} arm of {@link #isTabVisible}, and its button
	 * was put in the map by the loop above.
	 */
	private void addCard(Tab tab, JComponent card, Runnable rebuild) {
		content.add(card, tab.name());
		rebuilders.put(tab, rebuild);
	}

	private void rebuildIfDirty(Tab tab) {
		if (!dirty.remove(tab))
			return;
		try {
			rebuilders.get(tab).run();
		}
		catch (Exception e) {
			log.warn("Gachaman tab rebuild failed: {}", tab, e);
		}
	}

	/**
	 * Rebuild the tab strip from the enum, keeping only the tabs that currently
	 * have something behind them.
	 *
	 * The WHOLE strip is rebuilt rather than one button being spliced back in at
	 * its ordinal. An index-based re-insert is only correct while at most one tab
	 * is hideable and it is the last one before Help — with three hideable tabs
	 * an ordinal is no longer a valid tabRow index (two hidden tabs below it push
	 * every later ordinal past the button count) and the strip would either throw
	 * or silently reorder itself. Removing and re-adding in enum order is O(tabs),
	 * runs only on a refresh, and cannot get the order wrong by construction.
	 *
	 * Safe to call before the constructor finishes wiring: tabRow is the guard.
	 */
	public void updateTabVisibility() {
		if (tabRow == null)
			return;
		GachaState state = stateService.get();
		tabRow.removeAll();
		boolean selectedSurvives = false;
		for (Tab tab : Tab.values()) {
			JButton button = tabButtons.get(tab);
			if (button == null || !isTabVisible(tab, state))
				continue;
			tabRow.add(button);
			selectedSurvives |= tab == selected;
		}
		tabRow.revalidate();
		tabRow.repaint();
		if (!selectedSurvives) {
			// the page the player was reading just went away — land them somewhere
			// that always exists rather than on a card with no button to leave it
			selectTab(Tab.OVERVIEW);
		}
	}

	/**
	 * Whether a tab is worth a button right now.
	 *
	 * Empty pages are HIDDEN rather than shown empty: the strip is a 3-column
	 * grid in a 200px sidebar, so every button that explains nothing costs a row
	 * of the ones that do. Overview is the fallback in
	 * {@link #updateTabVisibility} and so must never be hidden here.
	 */
	private boolean isTabVisible(Tab tab, GachaState state) {
		switch (tab) {
			case DOSSIER:
				return hasContracts(state);
			case PATRONS:
				return PatronMark.partnerCount(state == null ? null : state.getPatrons()) > 0;
			case LOADOUT:
				return config.oneCardPerSlot();
			default:
				return true;
		}
	}

	/** True once one contract has been filed — the Dossier's whole content. */
	private static boolean hasContracts(GachaState state) {
		List<ContractRecord> log = state == null ? null : state.getContractLog();
		if (log == null)
			return false;
		for (ContractRecord record : log) {
			if (record != null) {
				return true; // Gson can hand back a null array element
			}
		}
		return false;
	}

	private void updateTabButtonStyles() {
		for (Map.Entry<Tab, JButton> entry : tabButtons.entrySet()) {
			boolean isSelected = entry.getKey() == selected;
			JButton button = entry.getValue();
			button.setBackground(isSelected ? ColorScheme.BRAND_ORANGE : ColorScheme.DARKER_GRAY_COLOR);
			button.setForeground(isSelected ? Color.BLACK : ColorScheme.LIGHT_GRAY_COLOR);
		}
	}

	// --- Header links ---

	/**
	 * A flat panel icon, authored by com.gachaman.tools.IconArt.
	 *
	 * <p>Package-private, not private: the tabs bake their own fixed-size icons
	 * to PNG through the same authoring tool, and every one of them loads it back
	 * through here rather than re-deriving the loadImageResource path.
	 */
	static ImageIcon icon(String name) {
		return new ImageIcon(ImageUtil.loadImageResource(
			GachamanPanel.class, "/com/gachaman/ui/" + name + ".png"));
	}

	/**
	 * A flat icon that opens a URL.
	 *
	 * A JLabel rather than a JButton on purpose: a button brings a border, a fill
	 * and a focus ring, and three of those stacked immediately above the tab strip
	 * read as two competing rows of controls. The icon IS the control, so hover is
	 * the only affordance it needs — hence the swapped bright variant and the hand
	 * cursor.
	 *
	 * LinkBrowser rather than Desktop.browse(): it is RuneLite's own opener, so it
	 * respects the client's link-confirmation setting and degrades to a
	 * copy-to-clipboard prompt on a machine with no usable browser handler,
	 * instead of throwing onto the EDT.
	 */
	private static JLabel linkIcon(ImageIcon normal, ImageIcon hover, String url, String tooltip) {
		JLabel label = new JLabel(normal);
		label.setToolTipText(tooltip);
		label.setCursor(new Cursor(Cursor.HAND_CURSOR));
		label.addMouseListener(new MouseAdapter() {
			@Override
			public void mousePressed(MouseEvent e) {
				LinkBrowser.browse(url);
			}

			@Override
			public void mouseEntered(MouseEvent e) {
				label.setIcon(hover);
			}

			@Override
			public void mouseExited(MouseEvent e) {
				label.setIcon(normal);
			}
		});
		return label;
	}




	// --- Scan progress polling ---

	private void updateScanLabel() {
		scanLabel.setText("Scanning Gielinor's armoury… " + cardDatabase.getScanProgressPercent() + "%");
	}

	private void ensureScanTimer() {
		if (!active || cardDatabase.isReady())
			return;
		if (scanTimer == null) {
			scanTimer = new Timer(SCAN_POLL_MS, e -> {
				if (cardDatabase.isReady()) {
					stopScanTimer();
					refresh();
				}
				else {
					updateScanLabel();
				}
			});
			// no setRepeats(true) — that IS javax.swing.Timer's documented default,
			// so the call only restated it. The poll still fires every SCAN_POLL_MS.
		}
		if (!scanTimer.isRunning())
			scanTimer.start();
	}

	private void stopScanTimer() {
		if (scanTimer != null && scanTimer.isRunning())
			scanTimer.stop();
	}

	/**
	 * The one scroll pane recipe this plugin's panels use: vertical-as-needed,
	 * horizontal NEVER, no border of its own, a real unit increment and a
	 * viewport painted to match its content, finished with the stone scrollbar.
	 *
	 * <p>Horizontal NEVER is the load-bearing part and the reason the width
	 * constants above exist: a child wider than the viewport is not scrolled to,
	 * it is clipped. Every wrapper in the sidebar wants exactly this, so the two
	 * things they legitimately disagree about — how far one wheel notch travels
	 * and what colour shows through under short content — are the parameters,
	 * and nothing else is.
	 *
	 * <p>LoadoutTab's picker pane is deliberately NOT routed through here, and
	 * its missing setUnitIncrement is the reason rather than an oversight.
	 * JScrollPane's own scrollbar only returns a fixed increment once someone
	 * has SET one; until then, if the view implements Scrollable, it asks the
	 * view instead — and that picker's view is a JList, which answers with its
	 * row height. So the picker already scrolls a whole row per notch, tuned to
	 * whatever its renderer measures. Handing it a flat 16 would break that
	 * alignment, and the viewport background it also does without would repaint
	 * a backdrop it currently lets show through. Both are visible changes.
	 *
	 * <p>The tabs that DO come through here pass an explicit increment, which
	 * sets that flag and wins over any Scrollable view underneath — AlbumTab's
	 * grid is Scrollable too, and its THUMB_H / 3 took precedence before this
	 * helper existed exactly as it does now.
	 */
	static JScrollPane scrollPane(JComponent inner, int unitIncrement, Color viewportBackground) {
		JScrollPane scroll = new JScrollPane(inner,
			ScrollPaneConstants.VERTICAL_SCROLLBAR_AS_NEEDED,
			ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		scroll.setBorder(null);
		scroll.getVerticalScrollBar().setUnitIncrement(unitIncrement);
		scroll.getViewport().setBackground(viewportBackground);
		styleScrollbar(scroll);
		return scroll;
	}

	/**
	 * Configures an HTML list pane and returns it already scroll-wrapped — the
	 * whole BorderLayout.CENTER of the Dossier, Patrons and Timeline tabs, which
	 * carried this as three byte-identical copies.
	 *
	 * <p>The configuring and the wrapping are fused on purpose rather than split
	 * into a "style the pane" half and a "wrap it" half. No caller has ever
	 * wanted one without the other, and splitting them puts the pane's setup
	 * back at the call sites — which is where the ordering constraint below gets
	 * broken, because at a call site it looks like six independent setters.
	 *
	 * <p>HONOR_DISPLAY_PROPERTIES must be set BEFORE setFont. The property is
	 * what makes the pane obey setFont/setForeground at all; a font set while it
	 * is still false is read back by the HTML view as the default serif face,
	 * and the tab renders in black Times instead of the RuneScape small font.
	 */
	static JScrollPane htmlListScroll(JEditorPane list) {
		list.setEditable(false);
		list.setContentType("text/html");
		list.putClientProperty(JEditorPane.HONOR_DISPLAY_PROPERTIES, Boolean.TRUE);
		list.setFont(FontManager.getRunescapeSmallFont());
		list.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		list.setBorder(new EmptyBorder(6, 6, 6, 6));
		return scrollPane(list, 16, ColorScheme.DARKER_GRAY_COLOR);
	}

	private static JScrollPane wrapScroll(JComponent inner) {
		return scrollPane(inner, 16, ColorScheme.DARK_GRAY_COLOR);
	}

	/**
	 * The stone palette the scrollbar thumb and the slider thumb are both cut
	 * from — the two UIs used to carry byte-identical private copies of these
	 * RGBs, which is how they would eventually have drifted apart.
	 *
	 * <p>Deliberately NOT named TRACK/THUMB: {@link MeterBar} has its own TRACK,
	 * a genuinely different dark, and although an inner field legally shadows an
	 * outer one, two same-named different-valued constants in one file is a trap
	 * for whoever next deletes the "redundant" copy.
	 */
	private static final Color STONE_TRACK = new Color(28, 27, 25);
	private static final Color STONE_THUMB = new Color(82, 72, 58);
	private static final Color STONE_EDGE = new Color(115, 102, 82);
	private static final Color STONE_EDGE_DARK = new Color(46, 40, 32);

	/** Slim, dark, game-styled scrollbar (stone thumb, no arrow buttons). */
	public static void styleScrollbar(JScrollPane scroll) {
		JScrollBar bar = scroll.getVerticalScrollBar();
		bar.setUI(new GameScrollBarUI());
		bar.setPreferredSize(new Dimension(9, 0));
		bar.setOpaque(false);
	}

	private static final class GameScrollBarUI extends BasicScrollBarUI {
		@Override
		protected void paintTrack(Graphics g, JComponent c, Rectangle r) {
			g.setColor(STONE_TRACK);
			g.fillRect(r.x, r.y, r.width, r.height);
		}

		@Override
		protected void paintThumb(Graphics g, JComponent c, Rectangle r) {
			if (r.isEmpty() || !scrollbar.isEnabled())
				return;
			g.setColor(STONE_THUMB);
			g.fillRect(r.x + 1, r.y + 1, r.width - 2, r.height - 2);
			g.setColor(STONE_EDGE);
			g.drawLine(r.x + 1, r.y + 1, r.x + r.width - 2, r.y + 1);
			g.drawLine(r.x + 1, r.y + 1, r.x + 1, r.y + r.height - 2);
			g.setColor(STONE_EDGE_DARK);
			g.drawLine(r.x + 1, r.y + r.height - 2, r.x + r.width - 2, r.y + r.height - 2);
			g.drawLine(r.x + r.width - 2, r.y + 1, r.x + r.width - 2, r.y + r.height - 2);
		}

		@Override
		protected JButton createDecreaseButton(int orientation) {
			return zeroButton();
		}

		@Override
		protected JButton createIncreaseButton(int orientation) {
			return zeroButton();
		}

		private static JButton zeroButton() {
			JButton button = new JButton();
			Dimension zero = new Dimension(0, 0);
			button.setPreferredSize(zero);
			button.setMinimumSize(zero);
			button.setMaximumSize(zero);
			return button;
		}
	}

	// --- Shared widget helpers used by the tabs ---

	static JPanel section(String title) {
		JPanel panel = new JPanel();
		panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
		panel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		panel.setBorder(new EmptyBorder(8, 8, 8, 8));
		panel.setAlignmentX(Component.LEFT_ALIGNMENT);
		if (title != null) {
			JLabel label = new JLabel(title);
			label.setForeground(ColorScheme.BRAND_ORANGE);
			label.setFont(FontManager.getRunescapeBoldFont());
			label.setAlignmentX(Component.LEFT_ALIGNMENT);
			panel.add(label);
			panel.add(Box.createVerticalStrut(6));
		}
		return panel;
	}

	static JLabel line(String text, Color color, Font font) {
		JLabel label = new JLabel(text);
		label.setForeground(color);
		label.setFont(font);
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		return label;
	}

	static JLabel smallLine(String text, Color color) {
		return line(text, color, FontManager.getRunescapeSmallFont());
	}

	/**
	 * The viewport a scroll-wrapped tab actually gets.
	 *
	 * <p>{@link PluginPanel#getPreferredSize()} returns 242 for the super(false)
	 * form this panel uses; take off the 6px panel border each side and the 9px
	 * GameScrollBarUI and 221 is left. The scroll panes never scroll sideways,
	 * so a child that wants more than this is not scrolled to — it is clipped.
	 */
	static final int VIEWPORT_WIDTH = PluginPanel.PANEL_WIDTH + PluginPanel.SCROLLBAR_WIDTH
		- 2 * PluginPanel.BORDER_OFFSET - 9;

	/**
	 * The usable column inside a {@link #section}, whose padding is 8px a side.
	 * The gold-bordered variants swap that padding for a 1px line plus 7px,
	 * which is the same 8px, so one number covers every caller.
	 */
	static final int SECTION_WIDTH = VIEWPORT_WIDTH - 16;

	/**
	 * Hard cap on a section's width: the sidebar is fixed-width and no tab's
	 * scroll pane scrolls horizontally, so a child whose preferred width exceeds
	 * the viewport is not scrolled to — it is clipped at the right edge. Capping
	 * both the preferred and the maximum width means no child can push its
	 * section past the cap, whatever it asks for.
	 *
	 * <p>One class for all three callers. Shop, Help and Party each carried a
	 * private copy; Help's and Party's were byte-identical to each other and
	 * Shop's differed only in baking its cap in as a constant instead of taking
	 * it as a field. The two-arg form covers both: Shop hands over the
	 * compile-time {@code CONTENT_WIDTH}, Help and Party hand over the width
	 * they measured from the live viewport, and the arithmetic each one sees is
	 * unchanged.
	 */
	static final class WidthCap extends JPanel {
		private final int cap;

		WidthCap(JComponent inner, int cap) {
			super(new BorderLayout());
			this.cap = cap;
			setOpaque(false);
			setAlignmentX(Component.LEFT_ALIGNMENT);
			add(inner, BorderLayout.CENTER);
		}

		@Override
		public Dimension getPreferredSize() {
			Dimension d = super.getPreferredSize();
			return new Dimension(Math.min(d.width, cap), d.height);
		}

		@Override
		public Dimension getMaximumSize() {
			return new Dimension(cap, getPreferredSize().height);
		}
	}

	/**
	 * The big GC readout, in a section of its own — the balance every page that
	 * shows money at all opens with.
	 *
	 * <p>Shared because the Overview and the Shop are the two halves of one
	 * story: Overview is where the number is earned, Shop is where it is spent,
	 * and a player who sees a different face or a different orange on the two
	 * pages reads them as two different numbers. Overview appends its lifetime
	 * and reroll-token lines to the returned panel; the shop stops here.
	 */
	static JPanel balanceSection(GachaState state) {
		JPanel section = section(null);
		JLabel gc = new JLabel(QuantityFormatter.formatNumber(state.getGc()) + " GC");
		gc.setFont(FontManager.getRunescapeBoldFont().deriveFont(26f));
		gc.setForeground(ColorScheme.BRAND_ORANGE);
		gc.setAlignmentX(Component.LEFT_ALIGNMENT);
		section.add(gc);
		return section;
	}

	/**
	 * A width-constrained, word-wrapping HTML block sized for a direct child of
	 * {@link #section}.
	 *
	 * <p>The text is inserted raw — {@code <b>} in a caller's string is meant to
	 * render. Callers interpolating anything the player or the item cache
	 * supplies must run it through {@link #escape} first.
	 *
	 * <p>Not an HTML JLabel with {@code style='width:205px'}, which is what this
	 * used to be: Swing reads that width as a PREFERRED span, not a cap, so a
	 * line that measures wider simply laid out wider than the column and the
	 * viewport — which has no horizontal scrollbar — sheared the overflow off at
	 * the right edge with no ellipsis. A JEditorPane wraps against the width it
	 * is actually given, and pinning that width makes the column real.
	 */
	static JComponent wrapped(String text, Color color) {
		return wrapped(text, color, FontManager.getRunescapeSmallFont());
	}

	/**
	 * {@link #wrapped} in a caller-chosen font. Same column — the only reason to
	 * pick the font is a HEADING that has to wrap, and the bold face at ~7px/char
	 * runs out of column a third sooner than the small one does.
	 */
	static JComponent wrapped(String text, Color color, Font font) {
		JEditorPane pane = new JEditorPane();
		pane.setContentType("text/html");
		pane.setEditable(false);
		pane.setFocusable(false);
		pane.setOpaque(false);
		pane.setBorder(null);
		pane.setMargin(new Insets(0, 0, 0, 0));
		// without this the pane renders in the HTML default face and colour and
		// ignores setFont/setForeground entirely — the panel would go serif black
		pane.putClientProperty(JEditorPane.HONOR_DISPLAY_PROPERTIES, Boolean.TRUE);
		pane.setFont(font);
		pane.setForeground(color);
		// no CSS width: the wrap comes from the size pinned below, which unlike the
		// CSS hint is a width the layout cannot talk the pane out of
		pane.setText("<html><body>" + text + "</body></html>");
		pane.setAlignmentX(Component.LEFT_ALIGNMENT);
		// size first, then ask: the line count only exists once there is a width
		// to wrap against, and the height is only right for that same width
		pane.setSize(SECTION_WIDTH, Short.MAX_VALUE);
		Dimension fixed = new Dimension(SECTION_WIDTH, pane.getPreferredSize().height);
		pane.setPreferredSize(fixed);
		pane.setMinimumSize(fixed);
		pane.setMaximumSize(fixed);
		return pane;
	}

	/**
	 * The between-facts separator for the HTML panes (Dossier, Patrons,
	 * Timeline), matching the literal {@code "  ·  "} the plain-JLabel panels
	 * use. Non-breaking because HTML collapses a run of spaces to one, so the
	 * literal rendered a third of the intended gap and the segments ran together.
	 */
	static final String DOT = "&nbsp;&nbsp;·&nbsp;&nbsp;";

	/**
	 * Neutralise HTML in a string bound for a Swing HTML label. All three of
	 * {@code & < >} — a lone {@code >} is legal text in HTML5 but Swing's parser
	 * is HTML 3.2 and will happily close a tag it thinks it is inside.
	 */
	static String escape(String text) {
		return text == null ? ""
			: text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

	/**
	 * "a" or "an" for a noun phrase, so generated sentences do not read "a Easy
	 * contract" or "a Ornate Chest". Vowel letter, not vowel sound: every noun
	 * this is used on is a difficulty or a chest name, and none of them is a
	 * "u"-as-in-you or a silent-h word where the two rules disagree.
	 */
	static String article(String noun) {
		if (noun == null || noun.isEmpty())
			return "a";
		return "AEIOUaeiou".indexOf(noun.charAt(0)) >= 0 ? "an" : "a";
	}

	/**
	 * A caller-supplied label alone in the middle of an otherwise empty card.
	 *
	 * <p>Takes the label rather than the text because the scan card in the
	 * constructor centres a label it has to keep a reference to (it retitles it
	 * every 400ms), and that was the only difference between the two.
	 */
	static JPanel centered(JLabel label) {
		JPanel panel = new JPanel(new GridBagLayout());
		panel.setOpaque(false);
		label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		label.setFont(FontManager.getRunescapeSmallFont());
		panel.add(label, new GridBagConstraints());
		panel.setAlignmentX(Component.LEFT_ALIGNMENT);
		return panel;
	}

	static JComponent centeredNote(String text) {
		return centered(new JLabel(text, SwingConstants.CENTER));
	}

	static boolean confirm(Component parent, String titleText, String message) {
		JOptionPane pane = new JOptionPane(dialogBody(message),
			JOptionPane.WARNING_MESSAGE, JOptionPane.YES_NO_OPTION);
		showDialog(pane, parent, titleText);
		// the dialog is modal, so showDialog only returns once JOptionPane has
		// stored the chosen option on the pane
		return Integer.valueOf(JOptionPane.YES_OPTION).equals(pane.getValue());
	}

	static void info(Component parent, String message) {
		showDialog(new JOptionPane(dialogBody(message), JOptionPane.INFORMATION_MESSAGE),
			parent, "Gachaman");
	}

	/** Fixed-width HTML body so the dialog's preferred size is stable on any monitor. */
	private static JComponent dialogBody(String message) {
		String escaped = escape(message).replace("\n", "<br>");
		return new JLabel("<html><body style='width:230px'>" + escaped + "</body></html>");
	}

	/**
	 * Build, size, show and dispose one modal option pane — the whole tail that
	 * {@link #confirm} and {@link #info} used to spell out identically.
	 *
	 * <p>Mixed-DPI multi-monitor fix, and the reason the sizing is not left to
	 * createDialog(): createDialog() packs the dialog with the PRIMARY monitor's
	 * graphics configuration; when the client sits on a monitor with a different
	 * scale factor the dialog opens clipped — message truncated, Yes/No buttons
	 * entirely off the bottom. Move the window onto the target screen FIRST, then
	 * re-pack so layout runs with that monitor's real metrics, pin the packed size
	 * as the minimum, and re-centre because the re-pack changed the size.
	 */
	private static void showDialog(JOptionPane pane, Component parent, String titleText) {
		JDialog dialog = pane.createDialog(parent, titleText);
		dialog.setLocationRelativeTo(parent);
		dialog.pack();
		dialog.setMinimumSize(dialog.getSize());
		dialog.setLocationRelativeTo(parent);
		dialog.setVisible(true);
		dialog.dispose();
	}

	/** A thin horizontal meter with an optional centered label. */
	static final class MeterBar extends JComponent {
		private static final Color TRACK = new Color(28, 28, 28);

		private final double fraction;
		private final Color barColor;
		@Nullable
		private final String label;

		MeterBar(double fraction, Color barColor, String label) {
			this.fraction = Math.max(0, Math.min(1, fraction));
			this.barColor = barColor;
			this.label = label;
			setPreferredSize(new Dimension(100, 15));
			setMaximumSize(new Dimension(Integer.MAX_VALUE, 15));
			setAlignmentX(Component.LEFT_ALIGNMENT);
		}

		@Override
		protected void paintComponent(Graphics g) {
			Graphics2D g2 = (Graphics2D) g.create();
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			int w = getWidth();
			int h = getHeight();
			g2.setColor(TRACK);
			g2.fillRoundRect(0, 0, w, h, 6, 6);
			int fill = (int) Math.round(w * fraction);
			if (fill > 0) {
				g2.setColor(barColor);
				g2.fillRoundRect(0, 0, Math.max(fill, 6), h, 6, 6);
			}
			if (label != null) {
				g2.setFont(FontManager.getRunescapeSmallFont());
				g2.setColor(Color.WHITE);
				int tw = g2.getFontMetrics().stringWidth(label);
				g2.drawString(label, (w - tw) / 2, h / 2 + g2.getFontMetrics().getAscent() / 2 - 1);
			}
			g2.dispose();
		}
	}

	/** A left-aligned row wrapper so BorderLayout rows behave in a BoxLayout. */
	static JPanel row(JComponent left, JComponent right) {
		JPanel panel = new JPanel(new BorderLayout(6, 0));
		panel.setOpaque(false);
		panel.setAlignmentX(Component.LEFT_ALIGNMENT);
		panel.setMaximumSize(new Dimension(Integer.MAX_VALUE, 30));
		panel.add(left, BorderLayout.CENTER);
		if (right != null)
			panel.add(right, BorderLayout.EAST);
		return panel;
	}

	/**
	 * The one step below {@code DARKER_GRAY_COLOR} that every recessed control in
	 * this panel — button face, combo arrow, spinner steppers — is painted with.
	 * Package-private so the other tabs can reach the same instance instead of
	 * calling {@code .darker()} again for an equal colour.
	 */
	static final Color SUNKEN = ColorScheme.DARKER_GRAY_COLOR.darker();

	static JButton button(String text) {
		JButton button = new JButton(text);
		button.setFont(FontManager.getRunescapeSmallFont());
		button.setFocusPainted(false);
		button.setBackground(SUNKEN);
		button.setForeground(Color.WHITE);
		button.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR),
			new EmptyBorder(3, 8, 3, 8)));
		button.setAlignmentX(Component.LEFT_ALIGNMENT);
		return button;
	}

	/** Dark, RuneLite-styled combo box: colors, font, renderer and arrow. */
	static void styleCombo(JComboBox<?> combo) {
		styleCombo(combo, value -> value == null ? "" : String.valueOf(value));
	}

	/**
	 * As {@link #styleCombo(JComboBox)}, but rendering each entry
	 * through {@code labeller} instead of its {@code toString()}.
	 *
	 * A combo box has exactly one renderer, and this method installs it — so a
	 * caller that sets its own renderer first and then styles the box loses it
	 * silently, and the list falls back to raw enum names ("ORNATE" rather than
	 * "Ornate Chest"). Passing the label function in is the only ordering that
	 * cannot be got wrong.
	 */
	static <T> void styleCombo(JComboBox<T> combo,
		Function<T, String> labeller) {
		combo.setFont(FontManager.getRunescapeSmallFont());
		combo.setForeground(Color.WHITE);
		combo.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		combo.setFocusable(false);
		combo.setUI(new BasicComboBoxUI() {
			@Override
			protected JButton createArrowButton() {
				BasicArrowButton arrow = new BasicArrowButton(SwingConstants.SOUTH,
					SUNKEN, SUNKEN, ColorScheme.LIGHT_GRAY_COLOR, SUNKEN);
				arrow.setBorder(BorderFactory.createEmptyBorder());
				return arrow;
			}
		});
		combo.setBorder(BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR));
		DefaultListCellRenderer renderer = new DefaultListCellRenderer() {
			@Override
			@SuppressWarnings("unchecked")
			public Component getListCellRendererComponent(JList<?> list, Object value,
				int index, boolean isSelected, boolean cellHasFocus) {
				super.getListCellRendererComponent(list, value, index, isSelected, cellHasFocus);
				setFont(FontManager.getRunescapeSmallFont());
				setBackground(isSelected ? ColorScheme.DARK_GRAY_HOVER_COLOR : ColorScheme.DARKER_GRAY_COLOR);
				setForeground(isSelected ? Color.WHITE : ColorScheme.LIGHT_GRAY_COLOR);
				setBorder(new EmptyBorder(2, 5, 2, 5));
				// Swing renders a null entry while the popup sizes itself and
				// whenever the model is empty; the labeller never sees one.
				setText(value == null ? "" : labeller.apply((T) value));
				return this;
			}
		};
		combo.setRenderer(renderer);
	}

	/**
	 * Dark, RuneLite-styled spinner (date/number editors alike).
	 *
	 * <p>Takes JSpinner, not JComponent: the parameter used to be widened with an
	 * instanceof guard that quietly returned, which meant a caller passing the
	 * wrong thing got an unstyled spinner and no complaint. Both callers already
	 * hold a JSpinner, so the type does the checking for free and a future
	 * mistake is a compile error instead of a silent white box.
	 */
	static void styleSpinner(JSpinner s) {
		s.setBorder(BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR));
		s.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		JComponent editor = s.getEditor();
		if (editor instanceof JSpinner.DefaultEditor) {
			JFormattedTextField field =
				((JSpinner.DefaultEditor) editor).getTextField();
			field.setFont(FontManager.getRunescapeSmallFont());
			field.setBackground(ColorScheme.DARKER_GRAY_COLOR);
			field.setForeground(Color.WHITE);
			field.setCaretColor(Color.WHITE);
			field.setBorder(new EmptyBorder(2, 5, 2, 5));
		}
		for (Component child : s.getComponents()) {
			if (child instanceof JButton)
				child.setBackground(SUNKEN);
		}
	}

	/** Dark game-styled slider: stone thumb on a slim dark track. */
	static final class GameSliderUI extends BasicSliderUI {
		GameSliderUI(JSlider slider) {
			super(slider);
		}

		@Override
		public void paintTrack(Graphics g) {
			int cy = trackRect.y + trackRect.height / 2;
			g.setColor(STONE_TRACK);
			g.fillRoundRect(trackRect.x, cy - 3, trackRect.width, 6, 6, 6);
			g.setColor(ColorScheme.BRAND_ORANGE);
			int fill = thumbRect.x + thumbRect.width / 2 - trackRect.x;
			if (fill > 0)
				g.fillRoundRect(trackRect.x, cy - 3, Math.min(fill, trackRect.width), 6, 6, 6);
		}

		@Override
		public void paintThumb(Graphics g) {
			g.setColor(STONE_THUMB);
			g.fillRect(thumbRect.x + 2, thumbRect.y + 2, thumbRect.width - 4, thumbRect.height - 4);
			g.setColor(STONE_EDGE);
			g.drawRect(thumbRect.x + 2, thumbRect.y + 2, thumbRect.width - 5, thumbRect.height - 5);
		}

		@Override
		public void paintFocus(Graphics g) {
			// no focus ring
		}
	}

	/**
	 * Pre-realization fallback only: the 242px non-wrapped PluginPanel minus
	 * its 6px borders and a full stock 17px scrollbar — the NARROWEST the
	 * viewport can plausibly be, so nothing clips even before measuring.
	 *
	 * <p>Written out cancelled. The full derivation adds SCROLLBAR_WIDTH to reach
	 * the 242px outer width and then subtracts it again for the scrollbar, so the
	 * two terms annihilate and PANEL_WIDTH less the two borders is all that
	 * survives: 225 + 17 - 12 - 17 == 225 - 12 == 213. The prose above is the
	 * derivation; the expression below only has to reach the same number.
	 */
	static final int FALLBACK_WIDTH = PluginPanel.PANEL_WIDTH - 2 * PluginPanel.BORDER_OFFSET;

	static String htmlWrap(String body) {
		return "<html><body>" + body + "</body></html>";
	}

	static String hex(Color color) {
		return String.format("#%02x%02x%02x", color.getRed(), color.getGreen(), color.getBlue());
	}

	/**
	 * Wrap-to-width body text WITHOUT the HTML renderer: Swing's CSS width is
	 * a preferred span, not a hard cap — stretched labels re-wrap wider than
	 * asked and then clip under the scrollbar. A JTextArea wraps at exactly
	 * the width it is given; sizing it up front makes its preferred height
	 * correct before the BoxLayout ever asks.
	 */
	static JTextArea textBlock(String text, Color color, int width) {
		JTextArea area = new JTextArea(text);
		area.setEditable(false);
		area.setFocusable(false);
		area.setOpaque(false);
		area.setLineWrap(true);
		area.setWrapStyleWord(true);
		area.setBorder(null);
		area.setForeground(color);
		area.setFont(FontManager.getRunescapeSmallFont());
		area.setAlignmentX(Component.LEFT_ALIGNMENT);
		area.setSize(width, Short.MAX_VALUE);
		Dimension pref = area.getPreferredSize();
		area.setPreferredSize(new Dimension(width, pref.height));
		area.setMaximumSize(new Dimension(width, pref.height));
		return area;
	}

	/** The scroll viewport's ACTUAL extent width — the only trustworthy budget. */
	static int measuredWidth(JComponent panel) {
		Container ancestor = SwingUtilities.getAncestorOfClass(JViewport.class, panel);
		if (ancestor instanceof JViewport) {
			int width = ((JViewport) ancestor).getExtentSize().width;
			if (width > 0)
				return width;
		}
		return FALLBACK_WIDTH;
	}
}

package com.gachaman.ui.panel;

import java.util.List;
// A nested-type import, not a static one. The com.gachaman.service.* wildcard
// below reaches that package's top-level types only — never the Unlock class
// nested inside QuestExemptionService, which is the sole reason that qualifier
// used to be spelled out in full eight times over. Unlock is a name unique to
// this repo, so it collides with nothing the other wildcards bring in.
import com.gachaman.service.QuestExemptionService.*;
import com.gachaman.*;
import com.gachaman.model.*;
import com.gachaman.party.*;
import com.gachaman.service.*;
import java.awt.*;
import java.awt.event.*;
import java.util.*;
import java.util.function.*;
import javax.annotation.*;
import javax.inject.*;
import javax.swing.*;
import javax.swing.border.*;
import net.runelite.client.callback.*;
import net.runelite.client.ui.*;
import net.runelite.client.util.*;
// The three types this panel used to name on nearly every line. The rest of the
// package already sanctions the pattern — DossierTab, HelpTab, PartyTab,
// PatronsTab and TimelineTab all static-import GachamanPanel members today —
// and the on-demand form is what CLAUDE.md's wildcard rule asks for.
//
// No ambiguity is introduced: a static-import-on-demand only ever competes with
// another static-import-on-demand, and these three export disjoint simple names
// (GachamanPanel's widget helpers and width constants, ColorScheme's colours,
// QuantityFormatter's formatters). Anything OverviewTab inherits from JPanel
// wins over all of them anyway, since class members shadow imports.
//
// The bare LEFT_ALIGNMENT below comes from neither: it is java.awt.Component's
// public static float, inherited all the way down Component -> Container ->
// JComponent -> JPanel -> OverviewTab, so it is a member of this class and is
// in scope even inside the static helpers. That inheritance is also what makes
// it immune to the GachamanPanel static import, which re-exports the same
// constant through the same ancestor.
import static com.gachaman.ui.panel.GachamanPanel.*;
import static net.runelite.client.ui.ColorScheme.*;
import static net.runelite.client.util.QuantityFormatter.*;
// A fourth, on exactly the argument above: this file named Tuning seventeen
// times — the fragment window, the weapon multiplier, the Double Docket, the
// pity cap and the whole Ante band — and "Tuning." is three tokens every time.
//
// It cannot collide with the three above, which is the same disjointness
// argument: Tuning exports SCREAMING_CASE constants and the nested enum Chest
// (which this file never names), GachamanPanel exports widget helpers and width
// constants, ColorScheme exports colours, QuantityFormatter exports formatters.
// A static-import-on-demand only ever competes with another one, and anything
// OverviewTab declares or inherits from JPanel — LEFT_ALIGNMENT included — wins
// over all four regardless.
import static com.gachaman.Tuning.*;

/**
 * Overview: GC balances, style lock + cycle, the active task (with side bets
 * and abandon), taint warning, pity meter, and the Roll Tasks button.
 */
@Singleton
public class OverviewTab extends JPanel {
	/**
	 * The bold RuneScape face this tab titles with, held rather than asked for
	 * six times over.
	 *
	 * <p>Provably the same object either way, which is the only reason this is
	 * safe to hoist: {@code FontManager.runescapeBoldFont} is a <b>private static
	 * final</b> field assigned once in that class's static initialiser, and the
	 * getter compiles to a bare {@code getstatic} + {@code areturn} with no
	 * derive, no clone and no lazy build. Every call site was already sharing this
	 * instance and only spelling out the lookup to reach it. The one deriveFont
	 * caller still derives its own 16f copy, exactly as before — deriveFont never
	 * mutates its receiver.
	 */
	private static final Font BOLD = FontManager.getRunescapeBoldFont();

	private static final Color TAINT_RED = new Color(190, 60, 55);
	private static final Color SIDEBET_DONE = new Color(110, 200, 110);
	private static final Color DOCKET_GREEN = new Color(120, 220, 120);
	/** The Ante: warm, not festive — it marks money at risk, not a prize. */
	private static final Color ANTE_AMBER = new Color(214, 158, 74);

	// Some of these are shorter than the service they hold, because an identifier
	// is charged to the token budget on every line it appears on and the declared
	// type is right there saying what it is.
	//
	// taskService is NOT shortened and must not be: OverviewTabTest greps this
	// file for the literal text "invokeLater(taskService::presentOffers)" and
	// fails if it reappears — that spelling binds to the BooleanSupplier overload
	// and leaks a per-tick task forever (see viewRolledContracts). Rename the
	// field and the guard silently stops watching for the bug it was written for.
	private final GachaStateService stateService;
	private final TaskService taskService;
	private final ClientThread clientThread;
	private final PartyRollService rollService;
	private final GachamanConfig config;

	private final QuestExemptionService quests;
	/**
	 * Resource-only reads ({@code displayName}), so this tab never has to hop to
	 * the client thread to name the category the wheel picked. Deliberately NOT
	 * used to ask what is in the player's hands right now: that would need a
	 * varbit read, and the bonus is per-kill precisely so it cannot be decided by
	 * a late look at whatever happens to be equipped.
	 */
	private final WeaponTypeService weapons;
	private final ConsignmentService consignment;

	private BooleanSupplier inParty = () -> false;
	/** The live Quest-unlocked section, so a late answer can tell if it is stale. */
	private JPanel unlockBox;

	@Inject
	public OverviewTab(GachaStateService stateService, TaskService taskService,
		ClientThread clientThread,
		PartyRollService rollService,
		GachamanConfig config,
		QuestExemptionService quests,
		WeaponTypeService weapons,
		ConsignmentService consignment) {
		this.weapons = weapons;
		this.consignment = consignment;
		this.stateService = stateService;
		this.taskService = taskService;
		this.clientThread = clientThread;
		this.rollService = rollService;
		this.config = config;
		this.quests = quests;
		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setOpaque(false);
		setBorder(new EmptyBorder(0, 0, 6, 0));
	}

	void setInPartySupplier(BooleanSupplier supplier) {
		if (supplier != null)
			this.inParty = supplier;
	}

	void rebuild() {
		removeAll();
		GachaState state = stateService.get();
		if (state == null) {
			// drop the reference too, or a snapshot still in flight would fill a
			// section that is no longer on screen
			unlockBox = null;
			add(centeredNote("Log in to begin your Gachaman journey."));
			revalidate();
			repaint();
			return;
		}

		addSection(buildBalanceSection(state));
		addSection(buildStyleSection(state));
		addSection(buildTaskSection(state));
		if (!state.isFragmentDeedForged()
			&& state.getTotalTasksCompleted() < FRAGMENT_WINDOW_TASKS) {
			addSection(buildFragmentSection(state));
		}
		if (state.getTaint() > 0)
			addSection(buildTaintSection(state));
		addSection(buildPitySection(state));
		// last on purpose: a player who does not care scrolls past everything
		// that matters first, and it hides itself entirely when empty
		unlockBox = section("Quest-unlocked NPCs");
		unlockBox.setVisible(false);
		addSection(unlockBox);
		requestQuestUnlocks(state);

		revalidate();
		repaint();
	}

	/**
	 * Quest state lives behind a client script and a varp read, so it cannot be
	 * touched from the EDT. Hop to the client thread for the snapshot, hop back
	 * to fill the section in. The section is built empty and hidden, so a rebuild
	 * that finishes before the answer arrives simply shows nothing for a frame.
	 */
	private void requestQuestUnlocks(GachaState state) {
		JPanel target = unlockBox;
		ActiveTask task = state.getActiveTask();
		String taskMonster = task == null ? null : task.getMonsterName();
		// keep this a BLOCK lambda. ClientThread overloads invokeLater on Runnable
		// and on BooleanSupplier, and only a body that cannot yield a value forces
		// the Runnable one; viewRolledContracts below documents what a task bound
		// to the BooleanSupplier overload costs.
		clientThread.invokeLater(() -> {
			List<Unlock> unlocks = quests.currentUnlocks();
			SwingUtilities.invokeLater(() -> fillQuestUnlocks(target, unlocks, taskMonster));
		});
	}

	private void fillQuestUnlocks(JPanel target, List<Unlock> unlocks, String taskMonster) {
		if (target != unlockBox) {
			return; // a later rebuild replaced the section this answer was for
		}
		// the contract's own monster is not news - this section is for what the
		// player can hit BESIDES it
		List<Unlock> shown = new ArrayList<>();
		Set<String> seen = new HashSet<>();
		for (Unlock unlock : unlocks) {
			if (taskMonster != null && taskMonster.equalsIgnoreCase(unlock.getNpcName()))
				continue;
			// NUL joins the two halves of the dedupe key because no NPC or quest
			// name can contain it, so ("a", "b\0c") and ("a\0b", "c") stay
			// distinct. Write it as the escape \0 and NEVER as a raw 0x00 byte in
			// the literal: a raw NUL makes `file` call this source "data" and
			// makes grep/ripgrep treat it as binary and SKIP it, so a repo-wide
			// search silently misses every line of this class. That is not
			// hypothetical — it happened, and it made the live party-roll UI
			// (proposalGroups, PendingProposal, joinProposal, declineProposal)
			// look like dead code to an audit until the greps were re-run with -a.
			if (seen.add(unlock.getNpcName().toLowerCase(Locale.ROOT)
				+ "\0" + unlock.getQuestName())) {
				shown.add(unlock);
			}
		}
		if (shown.isEmpty()) {
			target.setVisible(false);
			return;
		}
		shown.sort(Comparator
			.comparing((Unlock u) -> !u.isManual())
			.thenComparing(u -> u.getQuestName() == null ? "" : u.getQuestName())
			.thenComparing(Unlock::getNpcName));
		// every one of them, never a "+N more": a player checking whether the
		// monster in front of them is unlocked needs to find it in this list
		for (Unlock unlock : shown) {
			target.add(unlockRow(unlock));
		}
		target.setVisible(true);
		target.revalidate();
		target.repaint();
	}

	/**
	 * NPC on the left, what unlocked it on the right, one line each.
	 *
	 * <p>Not {@link GachamanPanel#row}: that puts the left component in CENTER,
	 * so in a 205px column a long quest name squeezes the NPC name until Swing
	 * elides it — losing exactly the word the player is trying to match against
	 * the monster in front of them. Here the NPC holds its width and the quest
	 * gives way first.
	 */
	static JPanel unlockRow(Unlock unlock) {
		JPanel row = new JPanel(new BorderLayout(6, 0));
		row.setOpaque(false);
		row.setAlignmentX(LEFT_ALIGNMENT);
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 16));
		row.add(smallLine(unlock.getNpcName(), Color.WHITE),
			BorderLayout.WEST);
		JLabel why = smallLine(
			unlock.isManual() ? "manual override" : unlock.getQuestName(),
			unlock.isManual() ? ANTE_AMBER : LIGHT_GRAY_COLOR);
		why.setHorizontalAlignment(SwingConstants.RIGHT);
		row.add(why, BorderLayout.CENTER);
		return row;
	}

	private void addSection(JPanel section) {
		add(section);
		gap(this, 6);
	}

	/**
	 * Every vertical gap on this panel goes through here. Twenty-six call sites
	 * spelled {@code panel.add(Box.createVerticalStrut(n))} out in full and the
	 * repetition bought nothing: {@code createVerticalStrut} hands back a fresh
	 * Filler on every call in either spelling, so each gap keeps its exact pixel
	 * height and its exact position in the parent's child order.
	 */
	private static void gap(JComponent panel, int height) {
		panel.add(Box.createVerticalStrut(height));
	}

	/**
	 * A one-line label, added. Seventeen call sites spelled
	 * {@code section.add(smallLine(text, colour))} in full; the eight that keep
	 * the label to hang a tooltip on it still call {@link GachamanPanel#smallLine}
	 * directly, because those want the component and this does not hand it back.
	 *
	 * <p>Folding the add in is order-safe for the same reason {@link #gap} and
	 * {@link #actionButton} are: the label still lands at exactly the same point
	 * in the parent's child order, which is the only order-sensitive step.
	 */
	private static void note(JComponent parent, String text, Color color) {
		parent.add(smallLine(text, color));
	}

	/**
	 * A word-wrapping paragraph, added — {@link #note}'s sibling for the nine
	 * sites that wrapped instead of clipping.
	 *
	 * <p>{@link GachamanPanel#wrapped} is the HTML JEditorPane form and stays
	 * exactly as it is; nothing about the pane, the width it is pinned to or the
	 * markup it accepts changes here. The one caller that keeps the component to
	 * put a tooltip on it (the weapon worth line) still calls wrapped() itself.
	 */
	private static void para(JComponent parent, String text, Color color) {
		parent.add(wrapped(text, color));
	}

	/**
	 * The four-beat button dance — make it, tooltip it, wire it, add it —
	 * collapsed into one call, because most of the buttons on this panel are
	 * purely declarative. The button still lands at exactly the same point in the
	 * parent's child order, which is the only order-sensitive step of the four.
	 *
	 * <p>A null {@code tooltip} skips {@code setToolTipText} rather than passing
	 * null down to it. {@code setToolTipText(null)} would in practice be a no-op
	 * on a component that was never registered with the ToolTipManager, but the
	 * two tooltip-less buttons here are then provably untouched rather than
	 * merely almost-untouched.
	 *
	 * <p>Deliberately NOT named {@code button}. A method declared in this class
	 * shadows a static import of the same NAME regardless of signature, so that
	 * spelling would hide {@link GachamanPanel#button(String)} from the three
	 * call sites that still need the plain form to call setEnabled on.
	 */
	private static void actionButton(JComponent parent, String text, String tooltip,
		ActionListener action) {
		JButton made = button(text);
		if (tooltip != null)
			made.setToolTipText(tooltip);
		made.addActionListener(action);
		parent.add(made);
	}

	/**
	 * The host's "Cancel Party Roll" button, which the Contract section offers
	 * from two different places — beside a board that has already been rolled,
	 * and beside the force-start control before it has — with only the tail of
	 * the tooltip differing between the two.
	 */
	private void addCancelRoll(JPanel section, String tail) {
		gap(section, 3);
		actionButton(section, "Cancel Party Roll",
			"Host only: abort this party roll for every member who joined it" + tail,
			e -> rollService.cancelRoll());
	}

	private JPanel buildBalanceSection(GachaState state) {
		// the GC readout itself is shared with the Shop tab; only the two lines
		// under it are this page's
		JPanel section = balanceSection(state);
		gap(section, 4);
		note(section, 
			"Lifetime earned: " + formatNumber(state.getLifetimeGcEarned()) + " GC",
			LIGHT_GRAY_COLOR);
		note(section, 
			"Reroll tokens: " + state.getRerollTokens(), LIGHT_GRAY_COLOR);
		return section;
	}

	private JPanel buildStyleSection(GachaState state) {
		JPanel section = section("Allowed Style");
		if (state.getAllowedStyle() == null) {
			note(section, "Not yet rolled — fate awaits.", LIGHT_GRAY_COLOR);
			return section;
		}
		AttackStyle style;
		try {
			style = AttackStyle.valueOf(state.getAllowedStyle());
		}
		catch (IllegalArgumentException e) {
			note(section, "Unknown style", LIGHT_GRAY_COLOR);
			return section;
		}
		section.add(line(style.getDisplayName(), style.getColor(),
			BOLD.deriveFont(16f)));
		gap(section, 5);
		int target = Math.max(1, state.getCycleTarget());
		double progress = state.getCycleProgress();
		String barLabel = trimDouble(progress) + " / " + target + " contracts";
		section.add(new MeterBar(progress / target, style.getColor(), barLabel));
		gap(section, 3);
		note(section, "Style re-rolls when the cycle completes.",
			MEDIUM_GRAY_COLOR);
		// Both of these belong to the wheel, so they live under it rather than in
		// sections of their own — and both are deliberately BELOW the two early
		// returns above. A profile that has never rolled has no preferred weapon
		// to name, and the Consignment excludes the first-ever roll outright, so
		// saying "today's offer is still to come" there would be a promise the
		// house has already decided not to keep.
		addWeaponLines(section, state, style);
		addConsignmentLine(section);
		return section;
	}

	/**
	 * The weapon category the wheel named alongside the style, and what it is
	 * actually worth on the contract in hand.
	 *
	 * <p><b>The honesty rule, which is the whole reason this is more than one
	 * line:</b> the multiplier is x1.5 on KILL GC and nothing else, and kill GC
	 * is a small slice of an EASY contract against a large slice of an INSANE
	 * one. Told "x1.5" and no more, a player would reasonably conclude that
	 * fighting with the named category is always the right play — and on an EASY
	 * contract with a slow category it is a pay cut. So the break-even is printed
	 * as a number they can hold their own weapon up against, rather than hinted
	 * at in prose that lets the panel off the hook.
	 *
	 * <p>Always {@link WeaponTypeService#displayName}, never the key. The key for
	 * category 0 is "unarmed" while its name is "No weapon equipped", because the
	 * game reports that same category for every non-weapon item a player might be
	 * holding — calling it "unarmed" would be a claim about their hands that the
	 * varbit cannot support.
	 *
	 * <p>Package-private rather than private so the rendered lines can be pinned
	 * headlessly, the same arrangement {@link #trimDouble} already has. That one
	 * rule — the key never on screen, the name always — is invisible to every
	 * other kind of test, because both spellings compile and only one of them is
	 * a lie.
	 */
	void addWeaponLines(JPanel section, GachaState state, AttackStyle style) {
		gap(section, 6);
		String name = weapons.displayName(state.getPreferredWeaponType());
		if (name == null) {
			// Two causes, one line, and neither is the player's doing: no category
			// was named for this cycle, or one was named under a taxonomy this build
			// no longer carries. The bonus only ever adds to their income, so its
			// absence is not a failure and must not be dressed as one.
			note(section, "Preferred weapon: none — no bonus available.",
				LIGHT_GRAY_COLOR);
			return;
		}
		JLabel named = smallLine("Preferred weapon: " + name, style.getColor());
		named.setToolTipText("The wheel names a weapon category alongside the style. A kill landed in the allowed style with one of those in hand pays x"
			+ trimDouble(WEAPON_BONUS_MULT) + " GC. Per kill only — never on the completion bonus, and never on a kill that broke the style lock.");
		section.add(named);
		ActiveTask task = state.getActiveTask();
		String none = noBonusReason(task);
		if (none != null) {
			note(section, none, MEDIUM_GRAY_COLOR);
			return;
		}
		double share = killShareFraction(task.getPerKillGc(), task.getKillsRequired(),
			task.getCompletionGc());
		long total = (long) task.getPerKillGc() * task.getKillsRequired()
			+ task.getCompletionGc();
		// The break-even, derived rather than guessed. With K the contract's base
		// kill GC (per-kill x quota) and C its completion bonus, a contract run
		// entirely with the named category pays 1.5K + C instead of K + C, over a
		// time of t' per kill instead of t. GC per hour is equal exactly when
		// t'/t == (1.5K + C)/(K + C) — so the weapon may be 0.5K/(K + C) slower and
		// break even, which is the kill share times (WEAPON_BONUS_MULT - 1). On an
		// EASY contract that is about 8% of slack; on an INSANE, about 22%.
		long slack = Math.round(share * (WEAPON_BONUS_MULT - 1.0) * 100);
		// "the preferred weapon", not the name itself: the name for category 0 is
		// "No weapon equipped", and "So No weapon equipped may be up to 8% slower"
		// is a sentence no player should have to parse. The line above has just
		// named it, so the phrase is unambiguous and it reads for every category.
		JComponent worth = wrapped("Kill GC is " + Math.round(share * 100)
			+ "% of this contract's " + formatNumber(total)
			+ " GC — the completion bonus is the rest, and the weapon never touches it. So the preferred weapon may be up to "
			+ slack + "% slower per kill and still pay the same. Slower than that and taking it is a pay cut.", LIGHT_GRAY_COLOR);
		worth.setToolTipText("Computed from this contract's own two figures, so you can check it against the Contract section below."
			+ " The break-even moves during play: the rhythm combo and a level gap scale kill GC up and buy the weapon more slack,"
			+ " while the Double Docket, a milestone and the party co-op bonus scale the completion up and buy it less."
			+ " On a shared contract the quota is pooled, so your own share of the kill GC is smaller than the figure above.");
		section.add(worth);
	}

	/**
	 * Why the preferred weapon is worth nothing on the contract in hand, or null
	 * when it is worth something.
	 *
	 * <p>"No bonus available" in both arms, deliberately, and never a wording that
	 * reads as a fault: a Redemption contract pays nothing per kill by design, and
	 * a player between contracts has done nothing wrong. The two cases are still
	 * told apart because the fix is different — sign a contract, or finish this
	 * one — and a single vague line would leave the player poking at the wrong one.
	 */
	@Nullable
	static String noBonusReason(ActiveTask task) {
		if (task == null)
			return "No contract signed — no bonus available.";
		return task.getPerKillGc() > 0 ? null
			: "This contract pays nothing per kill — no bonus available.";
	}

	/**
	 * What share of a contract's base GC is paid out per kill, as a fraction.
	 *
	 * <p>The Preferred Weapon multiplies kill GC and nothing else, so this single
	 * number is what it is worth. Computed from the two figures the Contract
	 * section already prints — the per-kill rate and the completion bonus — so the
	 * player can check the claim by hand rather than take it. The combo and
	 * level-gap terms are left out for the same reason: they are properties of a
	 * kill, not terms of the contract, and the tooltip says which way each moves
	 * the answer instead of quietly baking in an average.
	 *
	 * <p>Package-private for the test that pins EASY against INSANE with the real
	 * Tuning tables — the two ends of the honesty claim this whole block makes.
	 *
	 * <p><b>The ratio itself now lives in {@link Tuning#killShare(double, double)}
	 * and not here.</b> {@code RevealOverlay.weaponWorthPct} was deriving the same
	 * thing independently for the reveal ceremony's weapon caption, off the same
	 * two Tuning tables, and the two agreed only because both derivations happened
	 * to be right — nothing held them together, so an edit to either would have
	 * moved one number on screen and not the other. This method keeps its name and
	 * its int signature (the contract in hand really does carry three ints, and
	 * the quota clamp below belongs to the panel's own defensiveness about a
	 * migrated save), and hands the division itself to the shared helper.
	 */
	static double killShareFraction(int perKillGc, int killsRequired, int completionGc) {
		return killShare((double) Math.max(0, perKillGc) * Math.max(0, killsRequired), completionGc);
	}

	/**
	 * Whether today's Consignment is still to come.
	 *
	 * <p>Three states rather than two: the day key is spent on an ANSWER, not on
	 * the offer being raised, so an offer standing on screen right now is neither
	 * "made" nor "still to come" and gets its own line.
	 *
	 * <p>"Still to come" is honest rather than a promise, and the tooltip carries
	 * the reason: the house only ever asks in the moment a style roll comes due,
	 * so a day can pass with the key unspent simply because the cycle never turned
	 * over. Saying "available today" would read as a thing the player could go and
	 * collect.
	 */
	private void addConsignmentLine(JPanel section) {
		gap(section, 5);
		boolean live = consignment.pendingOffer() != null;
		boolean spent = consignment.offeredToday();
		JLabel label = smallLine(live
			? "Consignment: the house is making its offer now."
			: spent
				? "Consignment: today's offer has been made."
				: "Consignment: today's offer is still to come.",
			live || !spent ? ANTE_AMBER : MEDIUM_GRAY_COLOR);
		label.setToolTipText("A free Gilded chest whose price is your next style roll: the wheel does not spin, the house names the style,"
			+ " and it names the one your album owns the fewest weapon cards for. At most one a day (the day turns at midnight UTC),"
			+ " and only in the moment a roll comes due — so a day can pass without one if your cycle does not complete."
			+ " Declining spends the day too: being asked is the thing that is rationed.");
		section.add(label);
	}

	/**
	 * One card per party roll on offer, host first.
	 *
	 * <p>Adds nothing at all when there is nothing to answer — including while
	 * this client is committed to a roll or hosting one, which the SERVICE
	 * enforces rather than the panel, so the rule holds for the chat commands
	 * too. A player can be offered several rolls at once and can take exactly
	 * one; joining answers the rest for them.
	 */
	private void addProposalCards(JPanel section) {
		// the enhanced-for evaluates proposalGroups() exactly once, same as the
		// local it replaced
		for (PartyRollService.PendingProposal offer : rollService.proposalGroups()) {
			section.add(buildProposalCard(offer));
			gap(section, 6);
		}
	}

	private JComponent buildProposalCard(PartyRollService.PendingProposal offer) {
		JPanel card = new JPanel();
		card.setLayout(new BoxLayout(card, BoxLayout.Y_AXIS));
		card.setOpaque(false);
		card.setAlignmentX(LEFT_ALIGNMENT);
		card.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(new Color(90, 82, 60)),
			new EmptyBorder(5, 6, 6, 6)));
		card.setMaximumSize(new Dimension(SECTION_WIDTH, Integer.MAX_VALUE));

		String host = offer.getHostName()
			+ (offer.getHostCombatLevel() > 0 ? "  lvl " + offer.getHostCombatLevel() : "");
		card.add(line(host + "'s roll" + (offer.isMine() ? "  (yours)" : ""),
			new Color(230, 190, 80), BOLD));
		gap(card, 2);

		// the rule the roll would ACTUALLY use, and how long the offer stands.
		// Seconds, not ticks: a countdown nobody can convert is not a countdown.
		para(card, "Sizing: " + escape(offer.getSizingLabel()),
			LIGHT_GRAY_COLOR);
		note(card, (offer.isVoting() ? "voting  ·  " : offer.getAgreed() + " in  ·  ")
				+ PartyRollService.ticksToSeconds(offer.getTicksLeft())
				+ "s left",
			MEDIUM_GRAY_COLOR);
		gap(card, 3);

		for (PartyRollService.ProposalMember member : offer.getMembers()) {
			// once voting opens the useful fact about a member is which contract
			// they backed, not that they agreed to roll — everyone here agreed
			// the contract they backed, by name — an index is meaningless next to
			// a player once the board is off screen
			String state = offer.isVoting()
				? (member.getVoteLabel() == null ? "no vote" : member.getVoteLabel())
				: stanceLabel(member.getResponse());
			boolean settled = offer.isVoting()
				? member.getVote() >= 0
				: member.getResponse() == PartyRollResponseMessage.AGREE;
			note(card, 
				"  " + member.getName() + (member.isSelf() ? " (you)" : "")
					+ (member.isHost() ? " — host" : "")
					+ "  ·  " + state,
				settled ? LIGHT_GRAY_COLOR : MUTED_MEMBER);
		}

		if (offer.isMine()) {
			// your own group is a roster, not an offer: there is nothing left to
			// answer, and the host's Start/Cancel controls live below the section
			return card;
		}

		gap(card, 4);
		final long id = offer.getProposalId();
		JButton join = button("Join");
		join.setEnabled(!offer.isBlocked());
		join.setToolTipText(offer.isBlocked()
			? "You cannot join this roll — you have a contract, undecided rolls, or party contracts are off in your settings."
			: "Join this roll. Any other roll you have been offered is answered for you.");
		join.addActionListener(e -> rollService.joinProposal(id));
		card.add(join);
		gap(card, 3);
		actionButton(card, "Decline",
			"Sit this one out. The rest of that party may still take a contract.",
			e -> rollService.declineProposal(id));
		return card;
	}

	private static final Color MUTED_MEMBER = new Color(140, 140, 140);

	/** How one member has answered a proposal, in words. */
	private static String stanceLabel(int response) {
		switch (response) {
			case PartyRollResponseMessage.AGREE:
				return "in";
			case PartyRollResponseMessage.DECLINE:
				return "sitting out";
			case PartyRollResponseMessage.BUSY:
				return "busy";
			default:
				return "no answer";
		}
	}

	/**
	 * Re-show the offers already on the board, from the "View Rolled Contracts"
	 * button. Exists as a named <b>void</b> method for one reason: to decide
	 * which {@code ClientThread.invokeLater} overload the call site binds to.
	 *
	 * <p>The obvious spelling, {@code invokeLater(taskService::presentOffers)},
	 * silently picks {@code invokeLater(BooleanSupplier)} instead of
	 * {@code invokeLater(Runnable)} — ClientThread declares both. For an exact
	 * method reference JLS 15.12.2.5 makes a functional interface with a
	 * non-void return MORE SPECIFIC than one returning void, and
	 * {@code presentOffers()} returns boolean. RuneLite's invoke queue only
	 * removes a BooleanSupplier task once it returns TRUE; a false one is logged
	 * as "Deferring task" and left queued, so it is retried on every game tick
	 * forever.
	 *
	 * <p>{@code presentOffers()} returns false whenever there is nothing to
	 * present. So a click that landed just after the offers were cleared — party
	 * roll cancelled, TTL expired, world hopped, or the offer accepted through
	 * the ceremony overlay itself — leaked a permanent tick task, which then
	 * fired the offer ceremony unprompted the next time ANY offer set existed,
	 * possibly stacked on the fresh roll's own ceremony.
	 *
	 * <p>A zero-arg expression lambda does NOT close this: a lambda with no
	 * parameters counts as explicitly typed, so the same most-specific rule
	 * applies. Only a void-returning target does, and a named method is the one
	 * spelling a test can check. The sibling call two blocks down,
	 * {@code invokeLater(taskService::rollOffers)}, is safe on its own —
	 * rollOffers returns {@code List<TaskOffer>}, which is not assignable to
	 * boolean, so BooleanSupplier is not even applicable there.
	 */
	void viewRolledContracts() {
		taskService.presentOffers();
	}

	private JPanel buildTaskSection(GachaState state) {
		JPanel section = section("Contract");
		ActiveTask task = state.getActiveTask();
		if (task == null) {
			// read once. GachaState is a Lombok @Value, so the three reads this
			// replaces could not have disagreed — they were three trips for one
			// immutable reference, and the null check now guards the local it
			// actually checked.
			List<TaskOffer> offers = state.getPendingOffers();
			boolean offersWaiting = offers != null && !offers.isEmpty();
			if (offersWaiting) {
				boolean partyVote = offers.get(0).isPartyRoll();
				para(section, partyVote
						? "Party contracts rolled — click one to VOTE (a majority accepts)."
						: "Contracts rolled — view them and pick one.",
					LIGHT_GRAY_COLOR);
				gap(section, 4);
				// the group, through the vote: who is in it and how each of them
				// has voted. This branch used to return before the cards were
				// added, so the roster disappeared at the exact moment a majority
				// was being counted — which is when it matters most
				addProposalCards(section);
				// This button has never carried a tooltip, hence the null:
				// actionButton leaves setToolTipText uncalled for it.
				// NOT taskService::presentOffers — see viewRolledContracts above
				actionButton(section, "View Rolled Contracts", null,
					e -> clientThread.invokeLater(this::viewRolledContracts));
				if (partyVote && rollService.canCancelRoll())
					addCancelRoll(section, " (before a contract is accepted).");
				addAnteControls(section, state, partyVote);
				return section;
			}
			note(section, "No active contract.", LIGHT_GRAY_COLOR);
			gap(section, 4);
			// every roll on offer, before the buttons that would start a rival one:
			// the whole point of a card is that answering it is the cheaper move
			addProposalCards(section);
			JButton roll = button("Roll Contracts");
			// canRollOffers() only knows about THIS client's contract state, and a
			// host who declined their own proposal is left in a live party vote
			// holding no offers — which reads here as "nothing going on". Rolling a
			// personal board in that window gets its scrolls force-closed the moment
			// the party vote settles, so the party's claim on this client counts too.
			roll.setEnabled(taskService.canRollOffers() && !rollService.committedSnapshot());
			roll.addActionListener(e -> clientThread.invokeLater(taskService::rollOffers));
			section.add(roll);
			if (inParty.getAsBoolean()) {
				// deliberately OUTSIDE the branches below, exactly where it has always
				// been: when a proposal is live and this client is not the host,
				// nothing follows it, and that bare 4px gap at the foot of the section
				// is what renders today. Flattening the old nested if must not quietly
				// close it — that would be a visible change.
				gap(section, 4);
				// the same truth table as the old `if (live) { if (canForceStart) X } else Y`,
				// one nesting level shallower. Both reads are pure, so the swapped
				// order costs nothing.
				if (!rollService.isProposalLive()) {
					JButton party = button("Propose Party Roll");
					party.setToolTipText("Party members without a contract join with ::gachaparty; the roll starts with whoever agrees (minimum 2),"
						+ " identical offers appear for everyone, and a majority vote picks the shared contract.");
					party.setEnabled(taskService.canRollOffers());
					party.addActionListener(e -> rollService.propose());
					section.add(party);
				}
				else if (rollService.canForceStart()) {
					// no status line in this branch any more: the group card above
					// already carries the host, the roster, the count and the countdown,
					// and two copies of one clock is one copy too many
					gap(section, 3);
					actionButton(section,
						"Start Roll Now (" + rollService.agreedCount() + " agreed)",
						"Host only: start immediately with everyone who has agreed so far instead of waiting out the 60s window.",
						e -> rollService.forceStart());
					addCancelRoll(section, ".");
				}
			}
			return section;
		}

		// Name only. The CENTER cell is ~161px once the Wiki button and the 6px gap
		// are taken out, and bold runs ~7px/char — "General Graardor  (lvl 624)"
		// measures 176px, so Swing ellipsised away the exact thing the suffix was
		// there to show. The level moves down to the difficulty line, which has the
		// full 205px to itself.
		// the name four times over, from an immutable @Value, so one read
		String named = task.getMonsterName();
		JLabel monster = line(named,
			Color.WHITE, BOLD);
		monster.setToolTipText(named + " (level " + task.getMonsterCombatLevel() + ")");
		JButton wiki = new JButton("Wiki");
		wiki.setFont(FontManager.getRunescapeSmallFont());
		wiki.setMargin(new Insets(1, 6, 1, 6));
		wiki.setFocusPainted(false);
		wiki.setBackground(DARKER_GRAY_HOVER_COLOR);
		wiki.setForeground(new Color(240, 200, 90));
		wiki.setToolTipText("Open the OSRS wiki page for " + named);
		final String wikiUrl = "https://oldschool.runescape.wiki/w/"
			+ named.replace(' ', '_');
		wiki.addActionListener(e -> LinkBrowser.browse(wikiUrl));
		// row() is this header field for field: BorderLayout(6, 0), not opaque,
		// left-aligned, left child in CENTER and right child in EAST. The one extra
		// thing it does is pin a 30px maximum height — so the setMaximumSize below
		// MUST stay and MUST run after it, since that is what keeps the row the
		// height of its own tallest child rather than a flat 30.
		JPanel headerRow = row(monster, wiki);
		headerRow.setMaximumSize(new Dimension(Integer.MAX_VALUE,
			Math.max(monster.getPreferredSize().height, wiki.getPreferredSize().height)));
		section.add(headerRow);
		// the difficulty's colour paints three lines and the shared flag decides
		// four things; both come off the same immutable task, so both are read once
		Color rung = task.getDifficulty().getColor();
		boolean shared = task.isParty();
		int quota = task.getKillsRequired();
		boolean half = task.isHalfKillPending();
		note(section, task.getDifficulty().getDisplayName()
				+ "  ·  lvl " + task.getMonsterCombatLevel()
				+ (task.isRedemption() ? " — REDEMPTION" : ""),
			rung);
		if (shared) {
			// Its own line: appended to the difficulty it ran to 237px in a 205px
			// column, and the horizontal scrollbar is disabled, so the party label
			// was simply cut off.
			note(section, "SHARED: " + task.getPartyLabel(), rung);
		}
		gap(section, 5);
		// shared contracts pool every participant's kills into the quota
		int pooled = task.getKillsDone() + (shared ? task.getPartyOtherKills() : 0);
		double killsDone = pooled + (half ? 0.5 : 0);
		double killFrac = quota <= 0 ? 0
			: killsDone / quota;
		section.add(new MeterBar(killFrac, rung,
			pooled + (half ? ".5" : "")
				+ " / " + quota + " kills"
				+ (shared ? " (yours: " + task.getKillsDone() + ")" : "")));
		gap(section, 4);
		note(section, 
			formatNumber(task.getPerKillGc()) + " GC / kill  ·  "
				+ formatNumber(task.getCompletionGc()) + " GC completion",
			LIGHT_GRAY_COLOR);
		if (task.getAppliedCharge() != null) {
			note(section, "Charge applied: " + prettyCharge(task.getAppliedCharge()),
				new Color(150, 190, 240));
		}
		int staked = task.getAnteStake();
		if (staked > 0) {
			// Shown for as long as the stake exists, because it is the player's
			// own GC sitting outside the purse — the balance at the top of this
			// panel is short by exactly this much and needs the explanation.
			JLabel ante = smallLine(
				"Ante: " + formatNumber(staked) + " GC staked",
				ANTE_AMBER);
			ante.setToolTipText("This GC left your purse when you signed. Complete the contract and " + formatNumber(
					(long) staked * ANTE_PAYOUT_MULT)
				+ " GC comes back; die and it is gone. Only your own stake is at risk — a party member dying does not cost you yours.");
			section.add(ante);
		}
		// Shown on EVERY contract, active or not. A bonus that only appears once
		// it is already earned is a bonus nobody goes looking for, and the "not
		// aligned" state is the only place the player can be told why they are
		// not getting it. The tooltip carries the exact when-is-it-fixed rule.
		JLabel docket = smallLine(
			task.isSlayerAligned()
				? "Double Docket: ACTIVE (x" + trimDouble(DOUBLE_DOCKET_MULT) + ")"
				: "Double Docket: not your Slayer task",
			task.isSlayerAligned() ? DOCKET_GREEN : LIGHT_GRAY_COLOR);
		docket.setToolTipText("Kill your Slayer assignment on contract and completion pays x"
			+ trimDouble(DOUBLE_DOCKET_MULT) + ". Checked when you accept AND on every kill, so picking up the matching task mid-contract"
			+ " still counts — and once it locks in it stays, even if you finish the Slayer task first. Contracts are never rolled to"
			+ " match your Slayer task; grouped assignments such as Metal dragons name no single monster and cannot be detected.");
		section.add(docket);

		List<SideBet> bets = task.getSideBets();
		if (bets != null && !bets.isEmpty()) {
			gap(section, 5);
			note(section, "Side bets:", BRAND_ORANGE);
			for (SideBet bet : bets) {
				// The same three-way truth table the if/else/if here used to spell
				// out: a sealed bet hides its terms while it is still running but
				// never its payout, completing one both uncovers the terms and earns
				// the "* " marker, and describeSideBet is still called only on the
				// arm that already called it. The payout tail was written twice
				// because both old arms ended the same way.
				String text = (bet.isCompleted() ? "* " : "")
					+ (bet.isSealed() && !bet.isCompleted()
						? "???" : TaskService.describeSideBet(bet))
					+ " — " + formatNumber(bet.getPayoutGc()) + " GC";
				note(section, text,
					bet.isCompleted() ? SIDEBET_DONE : LIGHT_GRAY_COLOR);
			}
		}

		gap(section, 4);
		para(section, 
			"A contract is a contract — it cannot be abandoned.",
			MEDIUM_GRAY_COLOR);
		return section;
	}

	private static boolean hasInsaneOffer(GachaState state) {
		if (state.getPendingOffers() == null)
			return false;
		for (TaskOffer offer : state.getPendingOffers()) {
			if (TaskService.anteEligible(offer))
				return true;
		}
		return false;
	}

	/**
	 * The Ante's arming controls, shown only while an INSANE contract is
	 * actually on the board — an option to wager on contracts that are not there
	 * is an invitation, and this is meant to be an answer to a question the
	 * player asked.
	 *
	 * Arming is the ONLY route by which GC is ever staked. Nothing here is
	 * preselected, the button is never the obvious next click, and it takes TWO
	 * confirmations: one naming the amount, one naming what losing means.
	 * Disarming takes none — backing out of a wager should never be defended.
	 */
	private void addAnteControls(JPanel section, GachaState state, boolean partyVote) {
		if (!config.anteEnabled() || !hasInsaneOffer(state))
			return;
		gap(section, 6);
		note(section, "The Ante", BRAND_ORANGE);

		int armed = taskService.getArmedAntePercent();
		if (armed > 0) {
			para(section, "ARMED at " + armed + "% — "
				+ formatNumber(taskService.previewAnteStake())
				+ " GC will be staked on the INSANE contract you "
				+ (partyVote
					? "vote for, and only if EVERY member agrees to their own stake."
					: "accept."),
				ANTE_AMBER);
			gap(section, 3);
			actionButton(section, "Disarm the Ante",
				"Take the wager off. Nothing has been staked yet — GC only leaves your purse when a contract is actually signed.",
				e -> {
					taskService.armAnte(0);
					rebuild();
				});
			return;
		}

		if (taskService.previewAnteStake(ANTE_MIN_PERCENT) <= 0) {
			para(section, "Your purse is under "
				+ formatNumber(ANTE_MIN_PURSE_GC)
				+ " GC, so no wager is offered.", MEDIUM_GRAY_COLOR);
			return;
		}

		para(section, 
			"Optional. Stake part of your purse against an INSANE contract before you take it: complete the contract and the stake returns doubled, die and it is gone. Contracts cannot be abandoned.",
			LIGHT_GRAY_COLOR);
		if (partyVote) {
			para(section, 
				"In a party it takes EVERY member. Each stakes from their own purse, and each loses only their own — one member declining means no Ante for anyone, but the contract goes ahead either way.",
				LIGHT_GRAY_COLOR);
		}
		gap(section, 4);

		// The GC figure is baked into each item rather than tracked by a listener:
		// the amount is the whole decision, so it must be readable at the moment
		// of choosing without a second glance elsewhere.
		JComboBox<String> percents = new JComboBox<>();
		// The ten-point stops across the legal band, both ends included. Enumerated
		// rather than materialised into an int[] first, because the progression IS
		// the index: item i is ANTE_MIN_PERCENT + 10*i — 10/20/30/40/50 for today's
		// 10..50 band — which is exactly how the listener below recovers the chosen
		// percent back out of the combo's selected index.
		for (int percent = ANTE_MIN_PERCENT; percent <= ANTE_MAX_PERCENT;
			percent += 10) {
			percents.addItem(percent + "%  —  "
				+ formatNumber(taskService.previewAnteStake(percent)) + " GC");
		}
		percents.setSelectedIndex(0);
		percents.setFont(FontManager.getRunescapeSmallFont());
		percents.setAlignmentX(LEFT_ALIGNMENT);
		percents.setMaximumSize(new Dimension(Integer.MAX_VALUE,
			percents.getPreferredSize().height));
		section.add(percents);
		gap(section, 3);

		actionButton(section, "Arm the Ante",
			"Arms only. The GC leaves your purse when you sign an INSANE contract, and is priced from your purse at that moment (capped at "
				+ formatNumber(ANTE_MAX_GC) + " GC).",
			e -> {
				// The inverse of the loop that filled the combo: index i is the i'th
				// ten-point stop up from the floor. Math.max keeps the no-selection
				// (-1) case pinned to the minimum, exactly as the array lookup did.
				int percent = ANTE_MIN_PERCENT
					+ 10 * Math.max(0, percents.getSelectedIndex());
				int stake = taskService.previewAnteStake(percent);
				if (stake <= 0)
					return;
				String amount = formatNumber(stake);
				if (!confirm(this, "Arm the Ante?",
					"Stake " + amount + " GC (" + percent + "% of your purse) on the next INSANE contract you take? The exact amount is fixed when you sign.")) {
					return;
				}
				if (!confirm(this, "If you die, it is gone",
					"Dying while that contract is active loses the " + amount + " GC outright. The contract itself is still binding and cannot be abandoned. Arm the Ante?")) {
					return;
				}
				taskService.armAnte(percent);
				rebuild();
			});
	}


	private JPanel buildTaintSection(GachaState state) {
		JPanel section = section(null);
		section.setBackground(new Color(56, 26, 24));
		section.add(line("TAINT ACTIVE (" + state.getTaint() + ")",
			TAINT_RED, BOLD));
		gap(section, 3);
		para(section, 
			"Forbidden gear or style has stained your record. All GC income is halved until the taint is worked off with clean kills (or a Redemption contract).",
			new Color(230, 170, 160));
		return section;
	}

	/**
	 * Deed Fragments and the Pity Meter render the same six beats: a titled
	 * section, a MeterBar labelled "&lt;done&gt; / &lt;total&gt; &lt;unit&gt;", a
	 * 3px gap, then a grey footnote. Only the title, the bar colour and the note
	 * ever differ, so those are the arguments and the shape is written once.
	 *
	 * <p>The fraction keeps its {@code (double)} cast, which is load-bearing:
	 * both meters divide an int by an int, so dropping it would floor every bar
	 * to empty-or-full. The same trap sits at the Pity call site, where the 0.8
	 * colour threshold is computed from that same integer pair.
	 *
	 * <p>{@link GachamanPanel#section} already appends the title label AND a 6px
	 * strut of its own when the title is non-null, so nothing is added here
	 * before the bar.
	 */
	private static JPanel meterSection(String title, int done, int total, Color bar,
		String unit, String note) {
		JPanel section = section(title);
		section.add(new MeterBar((double) done / total, bar,
			done + " / " + total + " " + unit));
		gap(section, 3);
		para(section, note, MEDIUM_GRAY_COLOR);
		return section;
	}

	private JPanel buildFragmentSection(GachaState state) {
		int tasksLeft = FRAGMENT_WINDOW_TASKS - state.getTotalTasksCompleted();
		return meterSection("Deed Fragments", state.getDeedFragments(),
			FRAGMENTS_REQUIRED, new Color(230, 190, 80), "fragments",
			"Medium+ contracts drop fragments during your first "
				+ FRAGMENT_WINDOW_TASKS + " contracts (" + tasksLeft + " left). Collect "
				+ FRAGMENTS_REQUIRED + " to forge a bonus Slot Deed.");
	}

	private JPanel buildPitySection(GachaState state) {
		int cap = PITY_HARD_CAP;
		// warms from violet to amber over the last fifth of the run to the cap. The
		// (double) cast is the same one meterSection needs — int/int would only ever
		// clear 0.8 by hitting the cap exactly.
		Color barColor = (double) state.getOpensSinceEpic() / cap >= 0.8
			? new Color(226, 148, 62) : new Color(150, 120, 220);
		return meterSection("Pity Meter", state.getOpensSinceEpic(), cap, barColor, "cards",
			"Cards revealed without an Epic+. At the cap, a Legendary is guaranteed.");
	}

	private static String prettyCharge(String charge) {
		// the constant is the receiver of equals, so a null charge falls all the way
		// through to the identity return exactly as the old if/if/return did
		return "COMPACTOR".equals(charge) ? "Compactor"
			: "EXTENDER".equals(charge) ? "Extender" : charge;
	}

	/**
	 * One decimal place, and only when there is one worth showing.
	 *
	 * <p>{@link Locale#ROOT} is load-bearing, not decoration. Plain
	 * {@code String.format("%.1f", …)} formats in the DEFAULT locale, so a client
	 * running under a comma-decimal locale (de, fr, es, pt-BR — much of the EU)
	 * printed the style cycle as "2,5 / 3 contracts" and the Double Docket as
	 * "x1,5". Every other number in this panel comes from
	 * {@link QuantityFormatter#formatNumber}, which groups thousands with a
	 * comma, so the player saw "1,250 GC" and "x1,5" side by side with the two
	 * commas meaning opposite things. Pinning ROOT gives every player the string
	 * a UK/US player already sees, so nothing changes on the common locales.
	 *
	 * <p>Both live callers really do reach this line: the cycle-progress bar
	 * label (a half-kill leaves progress on x.5) and the Double Docket
	 * multiplier, which is 1.2. Whole values leave early through
	 * {@code String.valueOf((int) value)} and were locale-independent already.
	 *
	 * <p>Package-private rather than private so the locale can be pinned from a
	 * test — the same arrangement {@link ShopTab#pct} already uses.
	 */
	static String trimDouble(double value) {
		if (value == Math.floor(value))
			return String.valueOf((int) value);
		return String.format(Locale.ROOT, "%.1f", value);
	}
}

package com.gachaman.ui.panel;

import java.util.List;
import static com.gachaman.ui.panel.GachamanPanel.measuredWidth;
import static com.gachaman.ui.panel.GachamanPanel.textBlock;
import com.gachaman.model.*;
import com.gachaman.ui.*;
import com.google.gson.*;
import java.awt.*;
import java.awt.event.*;
import java.awt.image.*;
import java.io.*;
import java.nio.charset.*;
import java.util.*;
import javax.inject.*;
import javax.swing.*;
import javax.swing.border.*;
import net.runelite.client.ui.*;

/**
 * How-to-play reference for the gamemode. Content is entirely static text and
 * procedurally drawn illustrations (no assets, no network) — but its WRAP
 * WIDTH is not static: the real viewport width depends on which scrollbar
 * width the look-and-feel actually honors, and assuming it from constants has
 * produced both a right-side gap and scrollbar-covered text. The tab measures
 * the live viewport instead and rebuilds whenever that measurement changes.
 */
@Singleton
public class HelpTab extends JPanel {

	/** Horizontal padding a GachamanPanel.section() adds (8px borders each side). */
	private static final int SECTION_PADDING = 16;
	/** Icon column width inside an iconRow (glyph up to 16px + 6px gap). */
	private static final int ICON_COLUMN = 22;

	private static final Color MELEE = new Color(214, 72, 56);
	private static final Color RANGED = new Color(80, 175, 68);
	private static final Color MAGIC = new Color(72, 118, 214);
	private static final Color BODY = ColorScheme.LIGHT_GRAY_COLOR;
	private static final Color MUTED = ColorScheme.MEDIUM_GRAY_COLOR;

	private static final int CARD_W = 56;
	private static final int CARD_H = 80;

	/** Wrap width the current content was built for; -1 = never built. */
	private int builtWidth = -1;
	private boolean viewportHooked;

	private final Gson gson;

	@Inject
	public HelpTab(Gson gson) {
		this.gson = gson;
		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setOpaque(false);
		setBorder(new EmptyBorder(0, 0, 6, 0));
	}

	/** Rebuilds only when the measured viewport width changed; no-op otherwise. */
	void rebuild() {
		int width = measuredWidth(this);
		if (width == builtWidth)
			return;
		builtWidth = width;
		removeAll();
		buildSections(width);
		revalidate();
		repaint();
	}

@Override
	public void addNotify() {
		super.addNotify();
		Container ancestor = SwingUtilities.getAncestorOfClass(JViewport.class, this);
		if (!viewportHooked && ancestor instanceof JViewport) {
			// the viewport narrows when the scrollbar appears (and would widen
			// if the LAF ever changed its width) — re-measure and rebuild; the
			// equal-width check makes this settle in at most two passes
			viewportHooked = true;
			ancestor.addComponentListener(new ComponentAdapter() {
				@Override
				public void componentResized(ComponentEvent e) {
					SwingUtilities.invokeLater(HelpTab.this::rebuild);
				}
			});
		}
	}

	private void addSection(JPanel section, int width) {
		add(new GachamanPanel.WidthCap(section, width));
		add(Box.createVerticalStrut(6));
	}

	// --- Sections ---

	/**
	 * Builds every section from help.json.
	 *
	 * <p>The copy is data, not code: it is ~11,000 words of prose that changes
	 * whenever the rules do, and prose wedged into string concatenations is
	 * prose nobody wants to edit. The resource carries the text and the ORDER;
	 * this method owns the rendering, and the illustrations stay in Java
	 * because they are drawn, not written.
	 */
	private void buildSections(int width) {
		for (Section section : document().sections) {
			JPanel panel = GachamanPanel.section(section.title);
			for (com.google.gson.JsonElement element : section.body) {
				if (element.isJsonPrimitive()) {
					paragraph(panel, width, element.getAsString());
					continue;
				}
				element(panel, width, element.getAsJsonObject());
			}
			addSection(panel, width);
		}
	}

	/**
	 * One non-paragraph element. The trailing gap is carried by the DATA, not
	 * assumed here: the original hand-written sections spaced these differently
	 * on purpose (the blocked-equipment glyph gets 6px, the padlock 4px), and a
	 * renderer that averaged them would quietly restyle the page.
	 */
	private void element(JPanel panel, int width, com.google.gson.JsonObject el) {
		if (el.has("note"))
			panel.add(GachamanPanel.smallLine(el.get("note").getAsString(), MUTED));
		else if (el.has("muted")) {
			panel.add(textBlock(el.get("muted").getAsString(), MUTED, width - SECTION_PADDING));
		}
		else if (el.has("icon")) {
			ImageIcon icon = "padlock".equals(el.get("icon").getAsString())
				? padlockIcon() : crossedCircleIcon();
			panel.add(iconRow(width, icon, textBlock(el.get("text").getAsString(),
				BODY, width - SECTION_PADDING - ICON_COLUMN)));
		}
		else {
			widget(panel, width, el);
		}
		if (el.has("gap"))
			panel.add(Box.createVerticalStrut(el.get("gap").getAsInt()));
	}

	private void widget(JPanel panel, int width, com.google.gson.JsonObject el) {
		switch (el.get("widget").getAsString()) {
			case "styleRow": {
				JPanel styles = flowRow(width);
				styles.add(styleLabel("Melee", MELEE));
				styles.add(styleLabel("Ranged", RANGED));
				styles.add(styleLabel("Magic", MAGIC));
				panel.add(styles);
				break;
			}
			case "rarityLadder":
				for (Rarity rarity : Rarity.values()) {
					panel.add(GachamanPanel.smallLine(rarity.getDisplayName(), rarity.getColor()));
					panel.add(Box.createVerticalStrut(1));
				}
				break;
			case "cardSamples": {
				JPanel cards = flowRow(width);
				cards.add(new JLabel(cardIcon(sample("Rune scimitar", Rarity.RARE, Variant.NORMAL, null))));
				cards.add(new JLabel(cardIcon(sample("Rune scimitar", Rarity.RARE, Variant.SHINY, null))));
				cards.add(new JLabel(cardIcon(sample("Dragon Hologram", Rarity.EPIC, Variant.HOLOGRAM,
					"Dragon tier"))));
				panel.add(cards);
				break;
			}
			case "pityMeter":
				panel.add(new GachamanPanel.MeterBar(12 / 30.0, ColorScheme.BRAND_ORANGE, "12 / 30"));
				break;
			case "commandList":
				for (com.google.gson.JsonElement command : el.getAsJsonArray("items")) {
					panel.add(GachamanPanel.smallLine(command.getAsString(), BODY));
					panel.add(Box.createVerticalStrut(1));
				}
				break;
			default:
				break;
		}
	}

	private static CardRenderer.CardView sample(String name, Rarity rarity, Variant variant,
		String subtitle) {
		return CardRenderer.CardView.builder()
			.name(name)
			.rarity(rarity)
			.variant(variant)
			.art(null)
			.subtitle(subtitle)
			.build();
	}

	// --- the document ---

	private static final class Doc {
		List<Section> sections;
	}

	private static final class Section {
		String title;
		List<com.google.gson.JsonElement> body;
	}

	private Doc document;

	private Doc document() {
		if (document == null) {
			Doc loaded = null;
			try (InputStream in = HelpTab.class.getResourceAsStream(
				"/com/gachaman/ui/help.json")) {
				if (in != null) {
					loaded = gson.fromJson(new InputStreamReader(
						in, StandardCharsets.UTF_8), Doc.class);
				}
			}
			catch (Exception e) {
				loaded = null;
			}
			if (loaded == null || loaded.sections == null) {
				loaded = new Doc();
				loaded.sections = Collections.emptyList();
			}
			document = loaded;
		}
		return document;
	}


	// --- Layout helpers ---

	private static void paragraph(JPanel section, int w, String text) {
		section.add(textBlock(text, BODY, w - SECTION_PADDING));
		section.add(Box.createVerticalStrut(4));
	}

/**
	 * A left-aligned flow row whose height never stretches in the BoxLayout.
	 *
	 * <p>Takes the SECTION-OUTER width, like {@link #paragraph}, and takes the
	 * padding off itself — both call sites were handing it the unpadded number
	 * while every other child of the same section subtracted first, so the cap
	 * it enforced was 16px wider than the column it sits in.
	 */
	private static JPanel flowRow(int outerWidth) {
		final int w = outerWidth - SECTION_PADDING;
		JPanel panel = new JPanel(new FlowLayout(FlowLayout.LEFT, 6, 0)) {
			@Override
			public Dimension getMaximumSize() {
				return new Dimension(w, getPreferredSize().height);
			}
		};
		panel.setOpaque(false);
		panel.setAlignmentX(Component.LEFT_ALIGNMENT);
		return panel;
	}

	/**
	 * A small glyph beside a wrapped text block, icon pinned to the top. Takes
	 * the SECTION-OUTER width and subtracts the padding itself, for the same
	 * reason {@link #flowRow} does.
	 */
	private static JPanel iconRow(int outerWidth, ImageIcon icon, JComponent text) {
		final int w = outerWidth - SECTION_PADDING;
		JPanel panel = new JPanel(new BorderLayout(6, 0)) {
			@Override
			public Dimension getMaximumSize() {
				return new Dimension(w, getPreferredSize().height);
			}
		};
		panel.setOpaque(false);
		panel.setAlignmentX(Component.LEFT_ALIGNMENT);
		JLabel iconLabel = new JLabel(icon);
		iconLabel.setVerticalAlignment(SwingConstants.TOP);
		panel.add(iconLabel, BorderLayout.WEST);
		panel.add(text, BorderLayout.CENTER);
		return panel;
	}

	private static JLabel styleLabel(String name, Color color) {
		JLabel label = new JLabel(name, squareIcon(color), SwingConstants.LEFT);
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(color);
		label.setIconTextGap(4);
		return label;
	}

	// --- Procedural illustrations ---

	/** A small filled swatch for the attack-style legend. */
	private static ImageIcon squareIcon(Color color) {
		BufferedImage image = new BufferedImage(10, 10, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		g.setColor(color);
		g.fillRect(0, 0, 10, 10);
		g.setColor(color.darker());
		g.drawRect(0, 0, 9, 9);
		g.dispose();
		return new ImageIcon(image);
	}

	/** The 14px crossed-circle glyph, mirroring ForbiddenItemOverlay's icon. */
	private static ImageIcon crossedCircleIcon() {
		int size = 14;
		BufferedImage image = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(new Color(0, 0, 0, 160));
		g.fillOval(0, 0, size - 1, size - 1);
		g.setColor(new Color(232, 60, 60));
		g.setStroke(new BasicStroke(2f));
		g.drawOval(1, 1, size - 3, size - 3);
		int inset = 3;
		g.drawLine(inset, size - 1 - inset, size - 1 - inset, inset);
		g.dispose();
		return new ImageIcon(image);
	}

	/** A small padlock glyph for the locked gear slots. */
	private static ImageIcon padlockIcon() {
		int size = 16;
		BufferedImage image = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(new Color(230, 190, 80));
		g.setStroke(new BasicStroke(2f));
		g.drawArc(4, 1, 7, 10, 0, 180);
		g.setColor(new Color(146, 126, 96));
		g.fillRoundRect(2, 7, 12, 8, 3, 3);
		g.setColor(new Color(230, 190, 80));
		g.drawRoundRect(2, 7, 11, 7, 3, 3);
		g.setColor(new Color(46, 40, 32));
		g.fillOval(7, 9, 3, 3);
		g.dispose();
		return new ImageIcon(image);
	}

	/** A mini card face rendered through the shared CardRenderer. */
	private static ImageIcon cardIcon(CardRenderer.CardView view) {
		BufferedImage image = new BufferedImage(CARD_W, CARD_H, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		CardRenderer.drawFace(g, 1, 1, CARD_W - 2, CARD_H - 2, view, 300L);
		g.dispose();
		return new ImageIcon(image);
	}
}

package com.gachaman.ui.panel;

import java.util.List;
import static com.gachaman.ui.panel.GachamanPanel.hex;
import static com.gachaman.ui.panel.GachamanPanel.htmlWrap;
import com.gachaman.model.*;
import com.gachaman.service.*;
