/**
 * The card album: every card in the database as a lazily rasterized thumbnail
 * grid, sorted rarity-ascending (Common first) then A-Z by default, with a
 * header dropdown offering that, its reverse, name order, and two orders that
 * read the player's own album — newest unlock and best Service Record. Under
 * those last two an unowned card sorts BELOW every owned one rather than
 * leading a block of zeroes; see {@link #acquiredAt} and {@link #serviceOf}.
 * Unowned cards are darkened
 * silhouettes named "???". Thumbnails are built off the EDT in SwingWorker
 * batches (only visible cells are requested) and cached in a small LRU so a
 * multi-thousand-card database stays light. Item sprites load asynchronously,
 * so every raster snapshots a per-cell version and registers a load hook that
 * bumps the version, evicts that one cell and repaints — a raster built from
 * a not-yet-loaded sprite can never stick. The cached raster is static; a
 * live paint pass animates diagonal sheen, prismatic borders and scanlines
 * over visible shiny/hologram/EPIC+ cells, driven by a Swing timer that only
 * runs while such cells are actually on screen.
 */
@Slf4j
@Singleton
public class AlbumTab extends JPanel {
	private static final int THUMB_W = 90;
	private static final int THUMB_H = 120;
	private static final int GAP = 6;
	/**
	 * Fixed time for the base raster. Chosen so CardRenderer's EPIC+ sheen
	 * band (period 3000ms, on-card while t%3000 is roughly 667..2000) sits
	 * fully off-card: the cached thumbnails carry no frozen effect band and
	 * the live paint pass owns all time-varying shimmer.
	 */
	private static final long STATIC_TIME_MS = 300L;
	private static final int CACHE_MAX = 300;
	private static final int BATCH_MAX = 24;
	private static final String UNKNOWN_NAME = "???";
	private static final Color PLACEHOLDER = new Color(38, 36, 32);
	/** Wiki badge in each owned card's top-right corner. */
	private static final int WIKI_BADGE = 13;
	private static final Color WIKI_BADGE_BG = new Color(0, 0, 0, 165);
	private static final Color WIKI_BADGE_FG = new Color(240, 200, 90);
	private static final Font WIKI_BADGE_FONT = new Font(Font.SANS_SERIF, Font.BOLD, 10);

	/** Corner arc of the card face (matches CardRenderer's w/7 round rect). */
	private static final float CELL_ARC = THUMB_W / 7f;
	private static final int EFFECT_TICK_MS = 33;
	private static final int SHEEN_PERIOD_MS = 2600;
	private static final double SHEEN_ANGLE_RAD = Math.toRadians(-25);
	private static final Color SHEEN_CLEAR = new Color(255, 255, 255, 0);
	private static final Color SHEEN_WHITE = new Color(255, 255, 255, 46);
	private static final Color HOLO_SCAN = new Color(140, 230, 255, 34);
	private static final Color HOLO_EDGE = new Color(120, 220, 255);
	private static final BasicStroke BORDER_THICK = new BasicStroke(2.5f);
	private static final BasicStroke BORDER_THIN = new BasicStroke(1.6f);

	private final GachaStateService stateService;
	private final CardDatabase cardDatabase;
	private final CardImageService cardImageService;

	private final JComboBox<String> slotFilter;
	private final JComboBox<String> rarityFilter;
	private final JComboBox<String> variantFilter;
	private final JCheckBox ownedOnlyBox = new JCheckBox("Owned only");
	private final JComboBox<String> sortOrder = new JComboBox<>(SORT_LABELS);
	private final JTextField searchField = new JTextField();
	private final JLabel collectedLabel = new JLabel();
	private final JLabel rarityCountsLabel = new JLabel();
	private final JLabel stardustLabel = new JLabel();
	private final JPanel holoPanel = box(BoxLayout.Y_AXIS);
	private final GridPanel grid = new GridPanel();

	/**
	 * Sort orders, in the dropdown's own order. The INDEX is the mode — see
	 * {@link #ensureSorted()} — so adding one here means adding its arm there,
	 * and reordering these reorders the menu and nothing else.
	 *
	 * <p>The last two read the player's album rather than the card database,
	 * which is what makes them different in kind from the rarity orders: an
	 * unowned card has no unlock time and no Service Record, so it sorts to the
	 * bottom rather than to the top of an ascending run of zeroes.
	 */
	private static final String[] SORT_LABELS = {
		"Common first", "Legendary first", "Name A-Z", "Newest first", "Most kills"
	};
	private static final int SORT_NEWEST = 3;
	private static final int SORT_KILLS = 4;

	private List<CardDefinition> sorted = Collections.emptyList();
	private Map<Integer, CardDefinition> sortedSource;
	/** Index into {@link #SORT_LABELS}. */
	private int sortMode;
	/** Mode {@link #sorted} was built with, to detect a change of order. */
	private int sortedMode = -1;
	private Map<Integer, Variant> ownedVariantByCardId = Collections.emptyMap();
	/** Card id -> best Service Record among the owned copies of that card. */
	private Map<Integer, Integer> serviceByCardId = Collections.emptyMap();
	/** Card id -> the MOST RECENT unlock time among the owned copies. */
	private Map<Integer, Long> acquiredByCardId = Collections.emptyMap();

	@Inject
	public AlbumTab(GachaStateService stateService, CardDatabase cardDatabase,
		CardImageService cardImageService) {
		this.stateService = stateService;
		this.cardDatabase = cardDatabase;
		this.cardImageService = cardImageService;

		setLayout(new BorderLayout(0, 6));
		setOpaque(false);

		// Arrays.stream over values() keeps enum DECLARATION order, which is the
		// order applyFilters depends on when it maps selectedIndex-1 back through
		// GearSlot.values() / Rarity.values(). This replaced two named helpers
		// holding byte-identical index loops; denser to read, but the Plugin Hub
		// token budget is the binding constraint and the helpers bought nothing.
		slotFilter = comboOf("All slots",
			Arrays.stream(GearSlot.values()).map(GearSlot::getDisplayName).toArray(String[]::new));
		rarityFilter = comboOf("All rarities",
			Arrays.stream(Rarity.values()).map(Rarity::getDisplayName).toArray(String[]::new));
		variantFilter = comboOf("All variants", new String[]{"Normal", "Shiny"});

		JPanel north = box(BoxLayout.Y_AXIS);

		collectedLabel.setFont(FontManager.getRunescapeBoldFont());
		collectedLabel.setForeground(Color.WHITE);
		JPanel headerRow = box(BoxLayout.X_AXIS);
		headerRow.add(collectedLabel);
		headerRow.add(Box.createHorizontalGlue());
		stardustLabel.setFont(FontManager.getRunescapeSmallFont());
		stardustLabel.setIcon(icon("stardust"));
		stardustLabel.setIconTextGap(4);
		headerRow.add(stardustLabel);
		north.add(headerRow);
		rarityCountsLabel.setFont(FontManager.getRunescapeSmallFont());
		rarityCountsLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
		north.add(rarityCountsLabel);
		north.add(Box.createVerticalStrut(5));

		JPanel filterGrid = new JPanel(new GridLayout(2, 2, 4, 4));
		filterGrid.setOpaque(false);
		filterGrid.setAlignmentX(Component.LEFT_ALIGNMENT);
		filterGrid.setMaximumSize(new Dimension(Integer.MAX_VALUE, 52));
		filterGrid.add(slotFilter);
		filterGrid.add(rarityFilter);
		filterGrid.add(variantFilter);
		ownedOnlyBox.setOpaque(false);
		ownedOnlyBox.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		ownedOnlyBox.setFont(FontManager.getRunescapeSmallFont());
		ownedOnlyBox.setIcon(icon("checkbox-off"));
		ownedOnlyBox.setSelectedIcon(icon("checkbox-on"));
		filterGrid.add(ownedOnlyBox);
		north.add(filterGrid);
		north.add(Box.createVerticalStrut(4));

		GachamanPanel.styleCombo(sortOrder);
		sortOrder.setToolTipText("Sort order");
		// Still pinned to a fixed width so the search field beside it takes the
		// rest, and still MEASURED rather than guessed — the hardcoded width this
		// replaced was narrower than its own longest caption, so the control
		// ellipsised the moment you changed it. A combo also needs room for the
		// arrow, hence the wider pad than the button wanted.
		FontMetrics sortMetrics =
			sortOrder.getFontMetrics(FontManager.getRunescapeSmallFont());
		int sortWidth = 0;
		for (String label : SORT_LABELS) {
			sortWidth = Math.max(sortWidth, sortMetrics.stringWidth(label));
		}
		Dimension sortSize = new Dimension(sortWidth + 32, 24);
		sortOrder.setPreferredSize(sortSize);
		sortOrder.setMinimumSize(sortSize);
		sortOrder.setMaximumSize(sortSize);

		searchField.setFont(FontManager.getRunescapeSmallFont());
		searchField.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		searchField.setForeground(Color.WHITE);
		searchField.setCaretColor(Color.WHITE);
		searchField.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR),
			new EmptyBorder(2, 5, 2, 5)));
		searchField.setToolTipText("Search by card name");
		JPanel searchRow = box(BoxLayout.X_AXIS);
		searchRow.setMaximumSize(new Dimension(Integer.MAX_VALUE, 24));
		searchRow.add(searchField);
		searchRow.add(Box.createHorizontalStrut(4));
		searchRow.add(sortOrder);
		north.add(searchRow);
		north.add(Box.createVerticalStrut(5));

		north.add(holoPanel);

		add(north, BorderLayout.NORTH);

		// a third of a thumbnail per notch, not the sidebar's flat 16: the grid
		// scrolls in rows of cards, so the increment has to follow the card size
		add(GachamanPanel.scrollPane(grid, THUMB_H / 3, ColorScheme.DARK_GRAY_COLOR),
			BorderLayout.CENTER);

		slotFilter.addActionListener(e -> applyFilters());
		rarityFilter.addActionListener(e -> applyFilters());
		variantFilter.addActionListener(e -> applyFilters());
		ownedOnlyBox.addActionListener(e -> applyFilters());
		sortOrder.addActionListener(e -> {
			sortMode = Math.max(0, sortOrder.getSelectedIndex());
			ensureSorted();
			applyFilters();
		});
		searchField.getDocument().addDocumentListener(new DocumentListener() {
			@Override
			public void insertUpdate(DocumentEvent e) {
				applyFilters();
			}

			@Override
			public void removeUpdate(DocumentEvent e) {
				applyFilters();
			}

			@Override
			public void changedUpdate(DocumentEvent e) {
				applyFilters();
			}
		});
	}

	void rebuild() {
		GachaState state = stateService.get();

		Map<Integer, Variant> ownedVariants = new HashMap<>();
		Map<Integer, Long> acquired = new HashMap<>();
		if (state != null) {
			for (OwnedCard owned : state.getOwnedCards()) {
				if (owned.isHologram())
					continue;
				Variant existing = ownedVariants.get(owned.getCardId());
				if (existing == null || (existing == Variant.NORMAL && owned.getVariant() == Variant.SHINY))
					ownedVariants.put(owned.getCardId(), owned.getVariant());
				// the MOST RECENT copy wins: "Newest first" answers "what have I
				// just pulled", and a duplicate arriving today is news even when
				// the first copy is a year old
				acquired.merge(owned.getCardId(), owned.getAcquiredAtMs(), Math::max);
			}
		}
		ownedVariantByCardId = ownedVariants;
		acquiredByCardId = acquired;
		serviceByCardId = ServiceRecordService.bestByCardId(
			state == null ? null : state.getOwnedCards());

		// AFTER the album maps above, never before: the newest and most-kills
		// orders read them, and sorting first would order this rebuild by the
		// PREVIOUS one's album — invisible on a cold start and wrong on the very
		// rebuild a new pull triggers, which is exactly when someone is looking.
		ensureSorted();

		updateHeader(state);
		rebuildHoloSection(state);
		applyFilters();
	}

	private void ensureSorted() {
		if (!cardDatabase.isReady()) {
			sorted = Collections.emptyList();
			sortedSource = null;
			return;
		}
		Map<Integer, CardDefinition> source = cardDatabase.all();
		int mode = sortMode;
		// The rarity and name orders depend only on the card database, so an
		// unchanged database plus an unchanged mode means the answer cannot have
		// moved. The album orders CANNOT be cached that way — the database is the
		// same object the moment a card is pulled, so caching on it would freeze
		// "Newest first" on the last pull the player saw before choosing it.
		boolean readsAlbum = mode == SORT_NEWEST || mode == SORT_KILLS;
		if (!readsAlbum && source == sortedSource && sortedMode == mode)
			return;
		List<CardDefinition> cards = new ArrayList<>(source.values());
		// Name A-Z is the tie-break under every order, so it is also the whole of
		// its own arm: mode 2 simply contributes nothing and falls through.
		cards.sort((a, b) -> {
			int cmp = mode <= 1
				? (mode == 1 ? -1 : 1)
					* Integer.compare(a.getRarity().ordinal(), b.getRarity().ordinal())
				: mode == SORT_NEWEST ? Long.compare(acquiredAt(b), acquiredAt(a))
				: mode == SORT_KILLS ? Integer.compare(serviceOf(b), serviceOf(a))
				: 0;
			return cmp != 0 ? cmp : a.getName().compareToIgnoreCase(b.getName());
		});
		sorted = cards;
		sortedSource = source;
		sortedMode = mode;
	}

	/**
	 * Unlock time of a card's newest copy, or MIN_VALUE when it is not owned —
	 * so under a newest-first order the whole unowned tail sinks below every
	 * card the player actually has, rather than a run of zeroes floating to the
	 * top of the album the moment the order is chosen.
	 */
	private long acquiredAt(CardDefinition card) {
		Long at = acquiredByCardId.get(card.getCardId());
		return at == null ? Long.MIN_VALUE : at;
	}

	/**
	 * Best Service Record among a card's copies. Unowned is -1 rather than 0,
	 * which keeps it strictly below an owned card that has served no kills yet —
	 * "I have it, it has done nothing" and "I do not have it" are different
	 * answers and the order should not conflate them.
	 */
	private int serviceOf(CardDefinition card) {
		Integer kills = serviceByCardId.get(card.getCardId());
		return kills == null ? -1 : kills;
	}

	/**
	 * Takes the state rather than re-reading it: the only caller is rebuild(),
	 * which already holds the same snapshot and hands it to rebuildHoloSection
	 * two lines later. Nothing between the two runs off the EDT or mutates
	 * state, so this is the same object either way — and the asymmetry of one
	 * sibling taking the state while the other silently re-fetched it is gone.
	 */
	private void updateHeader(GachaState state) {
		int total = sorted.size();
		int ownedCount = 0;
		Map<Rarity, Integer> ownedByRarity = new EnumMap<>(Rarity.class);
		Map<Rarity, Integer> totalByRarity = new EnumMap<>(Rarity.class);
		for (CardDefinition card : sorted) {
			totalByRarity.merge(card.getRarity(), 1, Integer::sum);
			if (ownedVariantByCardId.containsKey(card.getCardId())) {
				ownedCount++;
				ownedByRarity.merge(card.getRarity(), 1, Integer::sum);
			}
		}
		collectedLabel.setText("Collected: " + QuantityFormatter.formatNumber(ownedCount)
			+ " / " + QuantityFormatter.formatNumber(total));

		int dust = state == null ? 0 : state.getStardust();
		boolean armed = state != null && state.isStardustBlessArmed();
		stardustLabel.setText(armed ? "Blessed!" : dust + "/" + Tuning.STARDUST_REQUIRED);
		stardustLabel.setForeground(armed ? new Color(230, 190, 80) : new Color(190, 170, 255));
		stardustLabel.setToolTipText(armed
			? "Stardust blessing armed — the next chest rolls every card's shiny twice"
			: "Stardust " + dust + "/" + Tuning.STARDUST_REQUIRED
				+ " — shiny near-misses bank stardust; a full bank blesses your next chest");

		StringBuilder html = new StringBuilder("<html>");
		boolean first = true;
		for (Rarity rarity : Rarity.values()) {
			if (!first)
				html.append("&nbsp;&nbsp;");
			first = false;
			// #rrggbb and rgb(r,g,b) parse to the same Color in Swing's CSS, and
			// GachamanPanel.hex is what Dossier, Patrons and Timeline already use
			html.append("<span style='color:").append(GachamanPanel.hex(rarity.getColor()))
				.append("'>")
				.append(rarity.getDisplayName().charAt(0)).append(':')
				.append(ownedByRarity.getOrDefault(rarity, 0)).append('/')
				.append(totalByRarity.getOrDefault(rarity, 0)).append("</span>");
		}
		html.append("</html>");
		rarityCountsLabel.setText(html.toString());
	}

	private void rebuildHoloSection(GachaState state) {
		holoPanel.removeAll();
		if (state == null || !cardDatabase.isReady())
			return;
		Set<String> seenTiers = new LinkedHashSet<>();
		List<OwnedCard> holos = new ArrayList<>();
		for (OwnedCard owned : state.getOwnedCards()) {
			if (owned.isHologram() && seenTiers.add(owned.getTierKey()))
				holos.add(owned);
		}
		if (holos.isEmpty())
			return;
		JLabel title = new JLabel("Holograms");
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setForeground(new Color(120, 220, 255));
		title.setAlignmentX(Component.LEFT_ALIGNMENT);
		holoPanel.add(title);
		for (OwnedCard owned : holos) {
			HologramDefinition def = cardDatabase.holograms().get(owned.getTierKey());
			String name = def != null ? def.getName() : "Hologram (" + owned.getTierKey() + ")";
			GearSlot assigned = assignedSlotOf(state, owned);
			int served = owned.getKillsServed();
			// Holograms never enter the grid, so this list is their only album
			// surface for the Service Record — and on one line the whole row ran
			// to ~345px in a 230px column, so the Service Record, the last thing
			// on it, was always the thing that got cut. Name, then the facts
			// indented under it; the tooltip carries the lot.
			String full = name + " — tier " + owned.getTierKey()
				+ (assigned != null ? " — " + assigned.getDisplayName() : "")
				+ (served > 0 ? " — " + servedText(served) : "");
			JLabel label = GachamanPanel.line(name,
				def != null ? def.getRarity().getColor() : ColorScheme.LIGHT_GRAY_COLOR,
				FontManager.getRunescapeSmallFont());
			label.setToolTipText(full);
			holoPanel.add(label);

			JLabel detail = GachamanPanel.smallLine("    tier " + owned.getTierKey()
					+ (assigned != null ? "  ·  " + assigned.getDisplayName() : ""),
				ColorScheme.MEDIUM_GRAY_COLOR);
			detail.setToolTipText(full);
			holoPanel.add(detail);

			if (served > 0) {
				JLabel service = GachamanPanel.smallLine("    " + servedText(served),
					ColorScheme.MEDIUM_GRAY_COLOR);
				service.setToolTipText(full);
				holoPanel.add(service);
			}
		}
		holoPanel.add(Box.createVerticalStrut(4));
	}

	@Nullable
	private static GearSlot assignedSlotOf(GachaState state, OwnedCard owned) {
		for (Map.Entry<String, String> entry : state.getLoadout().entrySet()) {
			if (owned.getUuid().equals(entry.getValue())) {
				try {
					return GearSlot.valueOf(entry.getKey());
				}
				catch (IllegalArgumentException e) {
					return null;
				}
			}
		}
		return null;
	}

	private void applyFilters() {
		GearSlot slotSel = slotFilter.getSelectedIndex() <= 0 ? null
			: GearSlot.values()[slotFilter.getSelectedIndex() - 1];
		Rarity raritySel = rarityFilter.getSelectedIndex() <= 0 ? null
			: Rarity.values()[rarityFilter.getSelectedIndex() - 1];
		// same values()[index - 1] idiom as the two filters above: the combo is
		// ["All variants", "Normal", "Shiny"] and Variant is [NORMAL, SHINY,
		// HOLOGRAM], so index 3 (HOLOGRAM) is unreachable — the combo has three
		// items — and index 0 or -1 falls through to "no variant filter"
		Variant variantSel = variantFilter.getSelectedIndex() <= 0 ? null
			: Variant.values()[variantFilter.getSelectedIndex() - 1];
		boolean ownedOnly = ownedOnlyBox.isSelected();
		String query = searchField.getText() == null ? "" : searchField.getText().trim().toLowerCase();

		List<Entry> entries = new ArrayList<>();
		for (CardDefinition card : sorted) {
			if (slotSel != null && card.getSlot() != slotSel)
				continue;
			if (raritySel != null && card.getRarity() != raritySel)
				continue;
			Variant ownedVariant = ownedVariantByCardId.get(card.getCardId());
			boolean owned = ownedVariant != null;
			if (ownedOnly && !owned)
				continue;
			if (variantSel != null && (!owned || ownedVariant != variantSel))
				continue;
			if (!query.isEmpty() && !card.getName().toLowerCase().contains(query))
				continue;
			entries.add(new Entry(card, owned, owned ? ownedVariant : Variant.NORMAL,
				owned ? serviceByCardId.getOrDefault(card.getCardId(), 0) : 0));
		}
		grid.setEntries(entries);
		revalidate();
		repaint();
	}

	private static JComboBox<String> comboOf(String allLabel, String[] values) {
		String[] items = new String[values.length + 1];
		items[0] = allLabel;
		System.arraycopy(values, 0, items, 1, values.length);
		JComboBox<String> combo = new JComboBox<>(items);
		GachamanPanel.styleCombo(combo);
		return combo;
	}

	/**
	 * The transparent left-aligned BoxLayout panel this file assembled by hand
	 * four times over. LEFT_ALIGNMENT is set unconditionally: every one of these
	 * panels either sits in a BoxLayout parent that honours it, or — in the case
	 * of the north container — is added with BorderLayout.NORTH, which ignores
	 * alignmentX outright, so the one extra call is inert rather than a change.
	 */
	private static JPanel box(int axis) {
		JPanel panel = new JPanel();
		panel.setLayout(new BoxLayout(panel, axis));
		panel.setOpaque(false);
		panel.setAlignmentX(Component.LEFT_ALIGNMENT);
		return panel;
	}

	/**
	 * The Service Record phrase, shared by the hologram tooltip, the hologram
	 * detail line and the grid tooltip. ServiceRecordService's javadoc pins the
	 * wording — "present for N kills", never "killed N", because the record
	 * counts kills the card was ASSIGNED TO THE LOADOUT for, on-task or not —
	 * so one place to say it is also one place to keep saying it correctly.
	 */
	private static String servedText(int kills) {
		return "present for " + QuantityFormatter.formatNumber(kills)
			+ (kills == 1 ? " kill" : " kills");
	}

	// --- Grid entry ---

	@RequiredArgsConstructor
	private static final class Entry {
		private final CardDefinition card;
		private final boolean owned;
		private final Variant variant;
		private final int serviceKills;
	}

	private static String keyOf(Entry entry) {
		// the Service Record is baked into the raster and the LRU is never
		// cleared on rebuild, so it must key the cache or thumbnails go stale.
		// The variant deliberately does NOT: rasterize() hardcodes the NORMAL
		// face and the variant effects are painted live, so keying on it only
		// re-rasterized an identical image when a card upgraded to shiny. The
		// ":o:"/":u:" separator keeps ids and kill counts unambiguous.
		return entry.card.getCardId() + (entry.owned ? ":o:" : ":u:") + entry.serviceKills;
	}

	/** True for cells the live (non-rasterized) effect pass animates. */
	private static boolean hasLiveEffect(Entry entry) {
		return entry.owned
			&& (entry.variant == Variant.SHINY
			|| entry.variant == Variant.HOLOGRAM
			|| entry.card.getRarity().atLeast(Rarity.EPIC));
	}

	/** Cheap scan (item sprites are 36x32) for any non-transparent pixel. */
	private static boolean hasVisiblePixel(BufferedImage img) {
		int w = img.getWidth();
		int h = img.getHeight();
		for (int y = 0; y < h; y++) {
			for (int x = 0; x < w; x++) {
				if ((img.getRGB(x, y) >>> 24) != 0)
					return true;
			}
		}
		return false;
	}

	/**
	 * A flat 13x13 icon authored by com.gachaman.tools.IconArt, in test scope.
	 *
	 * <p>The stardust sparkle and the two "Owned only" checkbox states used to be
	 * hand-painted Icon classes right here. Every one of them is a FIXED drawing
	 * — no animation, no tint that varies with state (the "Blessed!" case
	 * recolours the LABEL, not the sparkle) — so painting them on each panel
	 * build was re-deriving a constant, exactly the case IconArt already exists
	 * for. AlbumIconBakeTest keeps the old paintIcon bodies and renders both ways
	 * onto the same backgrounds: no pixel moved, and the only drift was ±1 on one
	 * channel of eight pixels over the dark panel — the extra rounding step a
	 * composited layer costs, since ARGB is stored non-premultiplied.
	 *
	 * <p>GachamanPanel has a character-identical loader but keeps it private;
	 * duplicating four lines here is deliberate, so this change stays inside one
	 * file. Collapsing the two into one package-private helper is a later pass.
	 */
	private static ImageIcon icon(String name) {
		return new ImageIcon(ImageUtil.loadImageResource(
			AlbumTab.class, "/com/gachaman/ui/" + name + ".png"));
	}

	// --- Grid panel ---

	private final class GridPanel extends JPanel implements Scrollable {
		private List<Entry> entries = Collections.emptyList();
		private final LinkedHashMap<String, BufferedImage> cache =
			new LinkedHashMap<String, BufferedImage>(64, 0.75f, true) {
				@Override
				protected boolean removeEldestEntry(Map.Entry<String, BufferedImage> eldest) {
					return size() > CACHE_MAX;
				}
			};
		private boolean workerRunning;
		private final AtomicBoolean repaintScheduled = new AtomicBoolean();
		/**
		 * Per-cell raster version. A raster snapshots the version before
		 * fetching art; a sprite-load hook firing later bumps it, so the
		 * stale raster is dropped at publish time (or evicted from the
		 * cache if it already landed) and the cell re-rasters.
		 */
		private final Map<String, Integer> rasterVersion = new ConcurrentHashMap<>();
		/** Item ids whose sprite has finished loading (load hook fired). */
		private final Set<Integer> loadedItemIds = ConcurrentHashMap.newKeySet();
		/**
		 * Card id -> item id whose sprite actually drew visible pixels.
		 * Some odd item variants rasterize fully transparent; once a good
		 * sprite in the variant group is found it is remembered here.
		 */
		private final Map<Integer, Integer> resolvedArtIds = new ConcurrentHashMap<>();
		/**
		 * Drives the live shimmer pass; runs only while the album tab is
		 * showing AND at least one effect cell is inside the viewport.
		 */
		private final Timer effectTimer = new Timer(EFFECT_TICK_MS, e -> tickEffects());

		GridPanel() {
			setOpaque(false);
			setToolTipText("");
			addMouseListener(new MouseAdapter() {
				@Override
				public void mouseClicked(MouseEvent e) {
					Entry entry = entryAt(e.getX(), e.getY());
					// owned only: an undiscovered card shows "???" and has no
					// name to look up, so its badge is never drawn either
					if (entry != null && entry.owned && onWikiBadge(e.getX(), e.getY())) {
						LinkBrowser.browse("https://oldschool.runescape.wiki/w/"
							+ entry.card.getName().replace(' ', '_'));
					}
				}
			});
			addMouseMotionListener(new MouseMotionAdapter() {
				@Override
				public void mouseMoved(MouseEvent e) {
					Entry entry = entryAt(e.getX(), e.getY());
					boolean onBadge = entry != null && entry.owned
						&& onWikiBadge(e.getX(), e.getY());
					setCursor(Cursor.getPredefinedCursor(
						onBadge ? Cursor.HAND_CURSOR : Cursor.DEFAULT_CURSOR));
				}
			});
		}

		private void tickEffects() {
			if (!isShowing() || !hasVisibleEffectCells()) {
				effectTimer.stop();
				return;
			}
			Rectangle vis = getVisibleRect();
			repaint(vis.x, vis.y, vis.width, vis.height);
		}

		private boolean hasVisibleEffectCells() {
			Rectangle vis = getVisibleRect();
			if (entries.isEmpty() || vis.isEmpty())
				return false;
			int c = cols();
			int rowH = THUMB_H + GAP;
			int firstRow = Math.max(0, (vis.y - GAP) / rowH);
			// This was a nested row/col walk, but index = row * c + col rises by
			// exactly one every step, so the visible cells are one contiguous run
			// of the flat list. Math.min against entries.size() is the old inner
			// "past the last entry, give up" bail; keeping Math.max(firstRow, ...)
			// preserves the old lastRow clamp for a negative vis.y, which cannot
			// happen through a JViewport but costs nothing to honour.
			int last = Math.min(entries.size(),
				(Math.max(firstRow, (vis.y + vis.height) / rowH) + 1) * c);
			for (int i = firstRow * c; i < last; i++) {
				if (hasLiveEffect(entries.get(i)))
					return true;
			}
			return false;
		}

		void setEntries(List<Entry> next) {
			entries = next == null ? Collections.emptyList() : next;
			revalidate();
			repaint();
		}

		private int cols() {
			int width = Math.max(getWidth(), THUMB_W);
			return Math.max(1, (width + GAP) / (THUMB_W + GAP));
		}

		@Override
		public Dimension getPreferredSize() {
			int c = cols();
			int rows = entries.isEmpty() ? 0 : (entries.size() + c - 1) / c;
			return new Dimension(THUMB_W, Math.max(rows * (THUMB_H + GAP) + GAP, 40));
		}

		@Override
		protected void paintComponent(Graphics g) {
			super.paintComponent(g);
			Graphics2D g2 = (Graphics2D) g.create();
			try {
				if (entries.isEmpty()) {
					g2.setColor(ColorScheme.MEDIUM_GRAY_COLOR);
					g2.setFont(FontManager.getRunescapeSmallFont());
					g2.drawString("No cards match the filters.", 8, 20);
					return;
				}
				long now = System.currentTimeMillis();
				Rectangle clip = g2.getClipBounds();
				if (clip == null)
					clip = new Rectangle(0, 0, getWidth(), getHeight());
				int c = cols();
				int cellW = getWidth() / c;
				int rowH = THUMB_H + GAP;
				int firstRow = Math.max(0, (clip.y - GAP) / rowH);
				int lastRow = Math.max(firstRow, (clip.y + clip.height) / rowH);
				List<Entry> missing = new ArrayList<>();
				for (int row = firstRow; row <= lastRow; row++) {
					for (int col = 0; col < c; col++) {
						int index = row * c + col;
						if (index >= entries.size())
							break;
						Entry entry = entries.get(index);
						int x = col * cellW + (cellW - THUMB_W) / 2;
						int y = GAP + row * rowH;
						BufferedImage thumb = cache.get(keyOf(entry));
						if (thumb != null) {
							g2.drawImage(thumb, x, y, null);
							if (hasLiveEffect(entry))
								paintLiveEffect(g2, x, y, entry, now);
							if (entry.owned)
								paintWikiBadge(g2, x, y);
						}
						else {
							g2.setColor(PLACEHOLDER);
							g2.fillRoundRect(x, y, THUMB_W, THUMB_H, 12, 12);
							if (missing.size() < BATCH_MAX)
								missing.add(entry);
						}
					}
				}
				if (!missing.isEmpty())
					scheduleRaster(missing);
				updateEffectTimer();
			}
			finally {
				g2.dispose();
			}
		}

		private void updateEffectTimer() {
			if (isShowing() && hasVisibleEffectCells()) {
				if (!effectTimer.isRunning())
					effectTimer.start();
			}
			else if (effectTimer.isRunning()) {
				effectTimer.stop();
			}
		}

		/**
		 * Live effect pass painted over the static base thumbnail: a diagonal
		 * sheen band sweeping corner-to-corner (shiny and EPIC+), a cycling
		 * prismatic border (shiny) and drifting scanlines (hologram). Cheap
		 * gradient/line fills clipped to the cell — never re-rasterization.
		 */
		private void paintLiveEffect(Graphics2D g, int x, int y, Entry entry, long now) {
			boolean shiny = entry.variant == Variant.SHINY;
			boolean holo = entry.variant == Variant.HOLOGRAM;
			RoundRectangle2D cell = new RoundRectangle2D.Float(
				x, y, THUMB_W, THUMB_H, CELL_ARC, CELL_ARC);

			if (shiny || entry.card.getRarity().atLeast(Rarity.EPIC)) {
				Graphics2D gs = (Graphics2D) g.create();
				gs.setClip(cell);
				gs.rotate(SHEEN_ANGLE_RAD, x + THUMB_W / 2.0, y + THUMB_H / 2.0);
				float phase = (now % SHEEN_PERIOD_MS) / (float) SHEEN_PERIOD_MS;
				int span = THUMB_W + THUMB_H;
				int bandW = THUMB_W / 2;
				int bx = x - span + (int) (phase * span * 2);
				Color tint = shiny ? shinySheenColor(now) : SHEEN_WHITE;
				gs.setPaint(new GradientPaint(bx, 0, SHEEN_CLEAR, bx + bandW / 2f, 0, tint, true));
				gs.fillRect(bx, y - THUMB_H, bandW, THUMB_H * 3);
				gs.dispose();
			}

			if (holo) {
				Graphics2D gs = (Graphics2D) g.create();
				gs.setClip(cell);
				gs.setColor(HOLO_SCAN);
				int offset = (int) ((now / 90) % 6);
				for (int sy = y + offset; sy < y + THUMB_H; sy += 6) {
					gs.drawLine(x, sy, x + THUMB_W, sy);
				}
				gs.dispose();
			}

			if (shiny || holo) {
				Graphics2D gs = (Graphics2D) g.create();
				gs.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
				gs.setColor(shiny ? CardRenderer.prismaticColor(now, 0) : HOLO_EDGE);
				gs.setStroke(entry.card.getRarity().atLeast(Rarity.RARE) ? BORDER_THICK : BORDER_THIN);
				gs.draw(cell);
				gs.dispose();
			}
		}

		private Color shinySheenColor(long now) {
			Color c = CardRenderer.prismaticColor(now, 60);
			return new Color(c.getRed(), c.getGreen(), c.getBlue(), 64);
		}

		private void scheduleRaster(List<Entry> batch) {
			if (workerRunning)
				return;
			workerRunning = true;
			final List<Entry> copy = new ArrayList<>(batch);
			new SwingWorker<Void, Object[]>() {
				@Override
				protected Void doInBackground() {
					for (Entry entry : copy) {
						try {
							String key = keyOf(entry);
							int version = versionOf(key);
							publish(new Object[]{key, rasterize(entry, key), version});
						}
						catch (Exception e) {
							log.debug("album thumbnail raster failed", e);
						}
					}
					return null;
				}

				@Override
				protected void process(List<Object[]> chunks) {
					for (Object[] chunk : chunks) {
						String key = (String) chunk[0];
						if (versionOf(key) == (Integer) chunk[2])
							cache.put(key, (BufferedImage) chunk[1]);
						// else: a sprite finished loading mid-raster; drop the
						// stale raster and let the repaint re-request the cell
					}
					scheduleRepaint();
				}

				@Override
				protected void done() {
					workerRunning = false;
					// repaint requests the next missing batch, if any
					scheduleRepaint();
				}
			}.execute();
		}

		private void scheduleRepaint() {
			if (!repaintScheduled.compareAndSet(false, true))
				return;
			SwingUtilities.invokeLater(() -> {
				repaintScheduled.set(false);
				repaint();
			});
		}

		private int versionOf(String key) {
			return rasterVersion.getOrDefault(key, 0);
		}

		/**
		 * Load hook attached to every art fetch. AsyncBufferedImage.onLoaded on
		 * an ALREADY-loaded image does not run synchronously — it re-queues via
		 * clientThread.invokeLater — so an in-fetch flag can never suppress it.
		 * The gate is the load-state TRANSITION instead: only the FIRST time we
		 * learn a sprite finished loading may a cell be invalidated. Repeat
		 * fires (every later fetch of the same loaded sprite) are no-ops, which
		 * is what makes the raster pipeline converge instead of evicting its
		 * own output forever.
		 */
		private Runnable artLoadHook(String key, int itemId) {
			return () -> {
				if (!loadedItemIds.add(itemId)) {
					return; // already knew — the raster saw loaded pixels
				}
				rasterVersion.merge(key, 1, Integer::sum);
				SwingUtilities.invokeLater(() -> {
					cache.remove(key);
					scheduleRepaint();
				});
			};
		}

		@Nullable
		private BufferedImage fetchArt(String key, int itemId) {
			return cardImageService.itemImage(itemId, artLoadHook(key, itemId));
		}

		/**
		 * Card art is normally the card's lowest item id, but some odd item
		 * variants rasterize fully transparent. Walk the variant group in id
		 * order until a sprite shows visible pixels (a cheap 36x32 scan),
		 * remembering the winner. A sprite that is merely still loading is
		 * used as-is: its load hook re-rasters the cell once it arrives.
		 */
		@Nullable
		private BufferedImage resolveArt(Entry entry, String key) {
			int cardId = entry.card.getCardId();
			Integer resolved = resolvedArtIds.get(cardId);
			if (resolved != null)
				return fetchArt(key, resolved);
			Set<Integer> ids = entry.card.getItemIds();
			List<Integer> candidates = ids == null ? new ArrayList<>() : new ArrayList<>(ids);
			if (!candidates.contains(cardId))
				candidates.add(cardId);
			Collections.sort(candidates);
			BufferedImage fallback = null;
			for (int itemId : candidates) {
				BufferedImage art = fetchArt(key, itemId);
				if (art == null)
					continue;
				if (hasVisiblePixel(art)) {
					resolvedArtIds.put(cardId, itemId);
					return art;
				}
				if (!loadedItemIds.contains(itemId)) {
					// still loading, so blank is inconclusive; draw with it
					// and let its load hook re-raster this cell
					fallback = art;
					break;
				}
				// loaded but fully transparent: try the next variant id
			}
			return fallback;
		}

		private BufferedImage rasterize(Entry entry, String key) {
			BufferedImage art = resolveArt(entry, key);
			BufferedImage img = new BufferedImage(THUMB_W, THUMB_H, BufferedImage.TYPE_INT_ARGB);
			Graphics2D g2 = img.createGraphics();
			try {
				g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
				// base raster is always the NORMAL face: time-varying variant
				// effects (shiny bands, holo scanlines, prismatic border) are
				// painted live in paintComponent instead of being baked in
				CardRenderer.CardView view = CardRenderer.CardView.builder()
					.name(entry.owned ? entry.card.getName() : UNKNOWN_NAME)
					.rarity(entry.card.getRarity())
					.variant(Variant.NORMAL)
					.art(art)
					.subtitle(entry.owned ? entry.card.getSlot().getDisplayName() : null)
					.killsServed(entry.serviceKills)
					.build();
				CardRenderer.drawFace(g2, 0, 0, THUMB_W, THUMB_H, view, STATIC_TIME_MS);
			}
			finally {
				g2.dispose();
			}
			if (!entry.owned) {
				RescaleOp darken = new RescaleOp(
					new float[]{0.16f, 0.16f, 0.20f, 1f}, new float[4], null);
				img = darken.filter(img, null);
			}
			return img;
		}

		/**
		 * The "w" badge in a card's top-right corner, drawn only on cards the
		 * player owns — an undiscovered card has no name to look up yet.
		 */
		private void paintWikiBadge(Graphics2D g2, int x, int y) {
			int bx = x + THUMB_W - WIKI_BADGE - 3;
			int by = y + 3;
			g2.setColor(WIKI_BADGE_BG);
			g2.fillOval(bx, by, WIKI_BADGE, WIKI_BADGE);
			g2.setColor(WIKI_BADGE_FG);
			g2.setFont(WIKI_BADGE_FONT);
			FontMetrics fm = g2.getFontMetrics();
			String glyph = "w";
			g2.drawString(glyph, bx + (WIKI_BADGE - fm.stringWidth(glyph)) / 2,
				by + (WIKI_BADGE + fm.getAscent()) / 2 - 1);
		}

		/** Cell the point falls in, or null when it is past the last card. */
		private Entry entryAt(int px, int py) {
			if (entries.isEmpty())
				return null;
			int c = cols();
			int cellW = Math.max(1, getWidth() / c);
			int col = px / cellW;
			int row = Math.max(0, (py - GAP) / (THUMB_H + GAP));
			int index = row * c + col;
			if (col >= c || index < 0 || index >= entries.size())
				return null;
			return entries.get(index);
		}

		/** True when the point is inside that cell's wiki badge. */
		private boolean onWikiBadge(int px, int py) {
			int c = cols();
			int cellW = Math.max(1, getWidth() / c);
			int rowH = THUMB_H + GAP;
			// back to the cell's own origin, the same way paintComponent lays it out
			int x = (px / cellW) * cellW + (cellW - THUMB_W) / 2;
			int y = GAP + Math.max(0, (py - GAP) / rowH) * rowH;
			int bx = x + THUMB_W - WIKI_BADGE - 3;
			int by = y + 3;
			return px >= bx && px <= bx + WIKI_BADGE && py >= by && py <= by + WIKI_BADGE;
		}

		@Override
		public String getToolTipText(MouseEvent event) {
			if (event == null || entries.isEmpty())
				return null;
			Entry entry = entryAt(event.getX(), event.getY());
			if (entry == null)
				return null;
			if (entry.owned && onWikiBadge(event.getX(), event.getY()))
				return "Open the OSRS wiki page for " + entry.card.getName();
			if (!entry.owned)
				return "Undiscovered card";
			String variantText = entry.variant == Variant.SHINY ? " — Shiny" : "";
			// "present for", never "killed": the record counts kills the card was
			// ASSIGNED TO THE LOADOUT for, on-task or not, tainted or not
			String service = entry.serviceKills > 0 ? " — " + servedText(entry.serviceKills) : "";
			return entry.card.getName() + " — " + entry.card.getRarity().getDisplayName()
				+ variantText + " — " + entry.card.getSlot().getDisplayName() + service;
		}

		// --- Scrollable ---

		@Override
		public Dimension getPreferredScrollableViewportSize() {
			return getPreferredSize();
		}

		@Override
		public int getScrollableUnitIncrement(Rectangle visibleRect, int orientation, int direction) {
			return THUMB_H / 3;
		}

		@Override
		public int getScrollableBlockIncrement(Rectangle visibleRect, int orientation, int direction) {
			return orientation == SwingConstants.VERTICAL ? visibleRect.height : visibleRect.width;
		}

		@Override
		public boolean getScrollableTracksViewportWidth() {
			return true;
		}

		@Override
		public boolean getScrollableTracksViewportHeight() {
			return false;
		}
	}
}

package com.gachaman.ui.panel;

import java.util.List;
import static com.gachaman.ui.panel.GachamanPanel.measuredWidth;
import static com.gachaman.ui.panel.GachamanPanel.textBlock;
import com.gachaman.*;
import com.gachaman.model.*;
import com.gachaman.party.*;
import com.gachaman.service.*;
import java.awt.*;
import java.awt.event.*;
import java.awt.image.*;
import java.util.*;
import java.util.function.*;
import javax.annotation.*;
import javax.inject.*;
import javax.swing.*;
import javax.swing.border.*;
import net.runelite.client.ui.*;

/**
 * The party page: one line per RuneLite Party member, showing the style they
 * rolled, their combat level and how far along their contract is.
 *
 * Every line is SELF-REPORTED — it is whatever that member's own client chose
 * to broadcast, taken on trust exactly like the rest of the party layer. The
 * tab renders {@link PartyPresenceService.Row}s and touches neither PartyService
 * nor Client itself; the service has already clipped and clamped every remote
 * value, so a hostile client cannot reach the layout through here.
 */
@Singleton
public class PartyTab extends JPanel {

	/** Horizontal padding a GachamanPanel.section() adds (8px borders each side). */
	private static final int SECTION_PADDING = 16;
	/** Side of the drawn style chip. */
	private static final int SWATCH = 10;

	private static final Color MUTED = ColorScheme.MEDIUM_GRAY_COLOR;
	private static final Color TAINT_RED = new Color(190, 60, 55);
	/** Side of the drawn Patron's Mark pip. */
	private static final int PIP = 9;
	/**
	 * The Patron's Mark by tier. Index 0 is drawn too — a partner you have one
	 * contract with is below the first threshold but is still someone you have
	 * a history with, and that is exactly what the pip says. Bronze, silver,
	 * gold — the last is JournalTab's earned colour, so a maxed mark reads the
	 * same as every other earned thing.
	 */
	private static final Color[] PATRON_COLORS = {
		ColorScheme.LIGHT_GRAY_COLOR, new Color(170, 130, 90),
		new Color(200, 200, 210), new Color(230, 190, 80),
	};
	/**
	 * The outline on your TOP patron's pip. Every partner with a history now
	 * wears a pip, so without this the mark would stop having an owner; a
	 * near-white outline separates one pip from its neighbours at 9px in a way
	 * a tier colour cannot, since the top patron is often the top tier as well.
	 */
	private static final Color MARK_OWNER = new Color(245, 245, 245);

	/**
	 * The mark's colour for a count, clamped so a fourth entry in
	 * Tuning.PATRON_TIERS cannot throw. Shared with the Patrons page rather
	 * than copied: a pip beside a name and that name's row on the other tab
	 * describe the same mark, and two palettes would eventually disagree.
	 */
	static Color patronColor(int count) {
		return PATRON_COLORS[Math.min(PatronMark.tierFor(count), PATRON_COLORS.length - 1)];
	}

	private final PartyPresenceService presenceService;
	private final GachaStateService stateService;
	private final GachamanConfig config;

	/** Wrap width the current content was built for; -1 = never built. */
	private int builtWidth = -1;
	private boolean viewportHooked;

	/**
	 * Plugin-wired: the live party vote, or a supplier answering null when none
	 * is open. Nullable rather than a no-op default so an unwired panel shows no
	 * vote column at all instead of an empty one on every row.
	 */
	@Nullable
	private Supplier<PartyRollService.VoteView> voteViewSupplier;

	public void setVoteViewSupplier(
		Supplier<PartyRollService.VoteView> supplier) {
		this.voteViewSupplier = supplier;
	}

	@Inject
	public PartyTab(PartyPresenceService presenceService, GachaStateService stateService,
		GachamanConfig config) {
		this.presenceService = presenceService;
		this.stateService = stateService;
		this.config = config;
		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setOpaque(false);
		setBorder(new EmptyBorder(0, 0, 6, 0));
	}

	/**
	 * ALWAYS rebuilds. HelpTab short-circuits on an unchanged width because its
	 * content is static text; this page's content changes every time someone in
	 * the party kills something, so the same guard would freeze it after the
	 * first paint. The width comparison lives in the resize listener instead,
	 * which is also what stops a resize storm looping.
	 */
	void rebuild() {
		int width = measuredWidth(this);
		builtWidth = width;
		int inner = width - SECTION_PADDING;
		removeAll();

		JPanel section = GachamanPanel.section("Party");
		if (!config.partyRollsEnabled()) {
			section.add(textBlock("Party contracts are turned off in your Gachaman settings,"
				+ " so nothing is broadcast and nothing is shown here.", MUTED, inner));
		}
		else {
			List<PartyPresenceService.Row> rows = presenceService.getRows();
			if (rows.isEmpty()) {
				section.add(textBlock("Join a RuneLite Party to see everyone's style, level"
					+ " and contract progress here.", MUTED, inner));
			}
			else {
				// counted over ROWS, not over a group's members: a group is on
				// contract when its quota is, and saying so about a member whose
				// own line reports nothing would be inventing their state
				int onContract = 0;
				for (PartyPresenceService.Row row : rows) {
					if (row.getKillsRequired() > 0)
						onContract++;
				}
				List<PartyPresenceService.Group> groups = PartyPresenceService.group(rows);
				int shared = 0;
				for (PartyPresenceService.Group group : groups) {
					if (group.isShared())
						shared++;
				}
				// Two lines rather than three facts on one: at double digits the
				// combined string ran past the 205px section and the tail was cut.
				// A party of one is reachable — buildRows always emits a self row.
				section.add(GachamanPanel.smallLine(rows.size()
						+ (rows.size() == 1 ? " member · " : " members · ")
						+ onContract + " on contract",
					ColorScheme.LIGHT_GRAY_COLOR));
				if (shared > 0) {
					section.add(GachamanPanel.smallLine(shared
							+ (shared == 1 ? " shared contract" : " shared contracts"),
						ColorScheme.LIGHT_GRAY_COLOR));
				}
				section.add(Box.createVerticalStrut(6));
				// resolved ONCE per rebuild, not per row: the ledger is one map,
				// read from one state snapshot, so no two pips on the page can
				// disagree about who the mark's owner is
				Marks marks = marks();
				// likewise once per rebuild: every row on the page must be reading
				// the same instant of the tally, or two names could show votes from
				// either side of an incoming ballot
				PartyRollService.VoteView votes =
					voteViewSupplier == null ? null : voteViewSupplier.get();
				for (PartyPresenceService.Group group : groups) {
					section.add(buildGroup(group, inner, marks, votes));
					section.add(Box.createVerticalStrut(8));
				}
				section.add(textBlock("Every line is self-reported by that member's own client"
					+ " and taken on trust.", MUTED, inner));
			}
		}

		add(new GachamanPanel.WidthCap(section, width));
		add(Box.createVerticalStrut(6));
		revalidate();
		repaint();
	}

	/**
	 * One block: every member sharing a contract, then the one pooled meter
	 * they are all filling.
	 *
	 * A shared contract is drawn ONCE, not once per member, because there is
	 * one quota — repeating "Goblin 12/20" under three names reads as three
	 * jobs of twenty and makes a party of four look like eighty kills of work.
	 * The names stack; the meter does not.
	 */
	private JComponent buildGroup(PartyPresenceService.Group group, int w, Marks marks,
		PartyRollService.VoteView votes) {
		JPanel outer = new JPanel() {
			@Override
			public Dimension getMaximumSize() {
				return new Dimension(w, getPreferredSize().height);
			}
		};
		outer.setLayout(new BoxLayout(outer, BoxLayout.Y_AXIS));
		outer.setOpaque(false);
		outer.setAlignmentX(Component.LEFT_ALIGNMENT);

		List<PartyPresenceService.Row> members = group.getMembers();
		boolean live = false;
		for (int i = 0; i < members.size(); i++) {
			PartyPresenceService.Row row = members.get(i);
			if (i > 0)
				outer.add(Box.createVerticalStrut(2));
			outer.add(memberHeader(row, w, marks, votes));
			live |= row.isHeard() && row.isLoggedIn();
			if (!group.isOnContract()) {
				// a group with no quota is a single member by construction —
				// only a contract collapses rows together — but writing it
				// per-member means the page degrades to one line each rather
				// than silently dropping lines if that ever stops holding
				outer.add(statusLine(row));
			}
		}

		if (group.isOnContract()) {
			// a null task name alongside a real quota only reaches us from a
			// malformed or hostile client, and the block still has to lay out
			String quarry = group.getTaskName() == null ? "A contract" : group.getTaskName();
			outer.add(GachamanPanel.smallLine(group.isShared() ? "Shared · " + quarry : quarry,
				live ? ColorScheme.LIGHT_GRAY_COLOR : MUTED));
			outer.add(Box.createVerticalStrut(2));
			GachamanPanel.MeterBar meter = new GachamanPanel.MeterBar(
				PartyPresenceService.progressFraction(group.getKillsDone(), group.getKillsRequired()),
				barColor(group), group.getKillsDone() + " / " + group.getKillsRequired());
			meter.setMaximumSize(new Dimension(w, 15));
			outer.add(meter);
		}
		return outer;
	}

	/**
	 * A shared meter takes the brand colour, never a member's style colour: the
	 * members of one contract can be on three different styles — that is what
	 * the clash bonus pays for — so colouring the pooled bar after whichever
	 * row happened to be first would credit the quota to one of them.
	 */
	private static Color barColor(PartyPresenceService.Group group) {
		if (group.isShared())
			return ColorScheme.BRAND_ORANGE;
		PartyPresenceService.Row only = group.getMembers().get(0);
		return only.getStyle() == null ? ColorScheme.BRAND_ORANGE : only.getStyle().getColor();
	}

	/** One member's line: style chip, name and level, their vote, then their badges. */
	private static JComponent memberHeader(PartyPresenceService.Row row, int w, Marks marks,
		PartyRollService.VoteView votes) {
		boolean live = row.isHeard() && row.isLoggedIn();
		JPanel header = new JPanel(new BorderLayout(6, 0)) {
			@Override
			public Dimension getMaximumSize() {
				return new Dimension(w, getPreferredSize().height);
			}
		};
		header.setOpaque(false);
		header.setAlignmentX(Component.LEFT_ALIGNMENT);
		// style swatch and party face together on the left: the swatch says what
		// they swing, the face says who they are, and neither substitutes for the
		// other in a party where two members can share a style
		JPanel left = new JPanel(new BorderLayout(3, 0));
		left.setOpaque(false);
		left.add(new Swatch(row.getStyle() == null ? MUTED : row.getStyle().getColor()),
			BorderLayout.WEST);
		if (row.getAvatar() != null)
			left.add(new Face(row.getAvatar(), live), BorderLayout.EAST);
		header.add(left, BorderLayout.WEST);
		String label = row.getName() + (row.isSelf() ? " (you)" : "")
			+ (row.getCombatLevel() > 0 ? "  lvl " + row.getCombatLevel() : "")
			+ voteSuffix(row, votes);
		header.add(GachamanPanel.line(label, live ? Color.WHITE : MUTED,
			FontManager.getRunescapeSmallFont()), BorderLayout.CENTER);
		header.add(badges(row, marks), BorderLayout.EAST);
		return header;
	}

	/**
	 * How this member has voted, appended to their name while a vote is open.
	 *
	 * <p>Members who have NOT voted are named as such rather than left blank: a
	 * majority vote stalls on the people who have not answered, and a row that
	 * simply says nothing is indistinguishable from one the panel forgot. Empty
	 * outside a vote, so the line does not carry a dead column the rest of the
	 * time.
	 *
	 * <p>The contract is NAMED, not numbered. "vote 2" is an index into a board
	 * the reader may well have scrolled away from, and this column exists so a
	 * member can see what the party is converging on without reopening it.
	 */
	private static String voteSuffix(PartyPresenceService.Row row,
		PartyRollService.VoteView votes) {
		if (votes == null)
			return "";
		String label = votes.getLabelByMember().get(row.getMemberId());
		return label == null ? "  · no vote" : "  · " + label;
	}

	/**
	 * What a member with no contract is doing. A dealt-but-unsigned board is
	 * called out by name because it is the one state that silently EXCLUDES
	 * someone from a party roll: without this the party proposes, that member
	 * is auto-excused, and nothing on the page ever said why.
	 */
	private static JLabel statusLine(PartyPresenceService.Row row) {
		if (!row.isHeard()) {
			// "- " marker only: the RuneScape TTFs have no bullet glyph
			return GachamanPanel.smallLine("- No signal", MUTED);
		}
		if (row.isUndecidedOffers()) {
			JLabel line = GachamanPanel.smallLine("- Undecided board", TAINT_RED);
			// your own row is on this page too, and third-person copy pointed at
			// yourself reads as a bug rather than as a description of you
			line.setToolTipText(row.isSelf()
				? "You have offers dealt and have signed none of them, so you cannot"
					+ " join a shared roll until you sign one or clear the board."
				: "They have offers dealt and have signed none of them, so they"
					+ " cannot join a shared roll until they sign one or clear the board.");
			return line;
		}
		return GachamanPanel.smallLine("- No contract", MUTED);
	}

	/**
	 * The row's badge strip: one small marker per party feature that decorates
	 * a member. Later party features add their marker HERE (and their bit as a
	 * field on GachaPresenceMessage) rather than adding a column, so every row
	 * keeps one layout however many features land.
	 */
	private static JPanel badges(PartyPresenceService.Row row, Marks marks) {
		JPanel strip = new JPanel(new FlowLayout(FlowLayout.RIGHT, 3, 0));
		strip.setOpaque(false);
		if (row.isTainted()) {
			JLabel taint = GachamanPanel.line("*", TAINT_RED, FontManager.getRunescapeSmallFont());
			taint.setToolTipText(row.isSelf()
				? "Tainted — your income is halved until you work it off."
				: "Tainted — their income is halved until they work it off.");
			strip.add(taint);
		}
		PatronRecord record = marks.recordFor(row);
		if (record != null) {
			int count = record.getCount();
			boolean top = marks.isTop(row);
			Pip pip = new Pip(patronColor(count), top);
			pip.setToolTipText(PatronMark.tierLabel(count) + " — you have finished "
				+ count + " shared contract" + (count == 1 ? "" : "s") + " with them"
				+ (top ? ", more than with anyone else." : ".")
				+ " The mark is cosmetic: it pays nothing and unlocks nothing.");
			strip.add(pip);
		}
		return strip;
	}

	/**
	 * The Patron's Mark ledger as the page needs it, read once per rebuild.
	 *
	 * Both halves come from ONE state snapshot on purpose: re-reading the state
	 * per row would let a shared contract complete mid-rebuild and hand two
	 * rows two different owners of a mark that only has one.
	 */
	private static final class Marks {
		@Nullable
		private final Map<String, PatronRecord> ledger;
		@Nullable
		private final String topKey;

		Marks(Map<String, PatronRecord> ledger) {
			this.ledger = ledger;
			this.topKey = PatronMark.topKey(ledger);
		}

		/**
		 * Matched on ACCOUNT KEY, never on the name: the name a member
		 * broadcasts is a label they can change, and the presence layer's
		 * "A party member" fallback would otherwise let every unnamed row in
		 * the party wear the same person's mark.
		 */
		@Nullable
		PatronRecord recordFor(PartyPresenceService.Row row) {
			return PatronMark.recordFor(ledger, row.getAccountKey());
		}

		/** False whenever either side is unknown — see {@link AccountKey#same}. */
		boolean isTop(PartyPresenceService.Row row) {
			return AccountKey.same(row.getAccountKey(), topKey);
		}
	}

	/** The ledger as of now; empty when the save has not loaded yet. */
	private Marks marks() {
		GachaState state = stateService.get();
		return new Marks(state == null ? null : state.getPatrons());
	}

	// --- Layout plumbing ---

@Override
	public void addNotify() {
		super.addNotify();
		Container ancestor = SwingUtilities.getAncestorOfClass(JViewport.class, this);
		if (!viewportHooked && ancestor instanceof JViewport) {
			// the viewport narrows when the scrollbar appears (and would widen if
			// the LAF ever changed its width) — re-measure and rebuild. rebuild()
			// itself cannot carry the equal-width guard here (it must always
			// rebuild), so the guard sits in the listener or a resize loops.
			viewportHooked = true;
			ancestor.addComponentListener(new ComponentAdapter() {
				@Override
				public void componentResized(ComponentEvent e) {
					SwingUtilities.invokeLater(() -> {
						if (measuredWidth(PartyTab.this) != builtWidth)
							rebuild();
					});
				}
			});
		}
	}

	/** A drawn colour chip: the RuneScape TTFs have no block glyph to type. */
	private static final class Swatch extends JComponent {
		private final Color color;

		Swatch(Color color) {
			this.color = color;
			Dimension d = new Dimension(SWATCH, SWATCH);
			setPreferredSize(d);
			setMinimumSize(d);
			setMaximumSize(d);
		}

		@Override
		protected void paintComponent(Graphics g) {
			g.setColor(color);
			g.fillRect(0, Math.max(0, getHeight() / 2 - SWATCH / 2), SWATCH, SWATCH);
		}
	}

	/** Edge the party avatar is drawn at; matches the swatch's visual weight. */
	private static final int FACE = 14;

	/**
	 * A member's RuneLite party avatar.
	 *
	 * <p>Scaled on paint rather than pre-scaled once: the image arrives from
	 * RuneLite's party layer and can be replaced when a member changes it, so
	 * caching a resized copy here would pin the old face until the next rebuild.
	 * A member who is not currently heard is drawn faded, matching how their text
	 * greys out — the face should not be the one part of a stale row that still
	 * looks live.
	 */
	private static final class Face extends JComponent {
		private final BufferedImage image;
		private final boolean live;

		Face(BufferedImage image, boolean live) {
			this.image = image;
			this.live = live;
			Dimension d = new Dimension(FACE, FACE);
			setPreferredSize(d);
			setMinimumSize(d);
			setMaximumSize(d);
		}

		@Override
		protected void paintComponent(Graphics g) {
			Graphics2D g2 = (Graphics2D) g.create();
			try {
				g2.setRenderingHint(RenderingHints.KEY_INTERPOLATION,
					RenderingHints.VALUE_INTERPOLATION_BILINEAR);
				if (!live) {
					g2.setComposite(AlphaComposite.getInstance(
						AlphaComposite.SRC_OVER, 0.45f));
				}
				int y = Math.max(0, getHeight() / 2 - FACE / 2);
				g2.drawImage(image, 0, y, FACE, FACE, null);
			}
			finally {
				g2.dispose();
			}
		}
	}

	/**
	 * The Patron's Mark, drawn rather than typed for the same reason as
	 * {@link Swatch}: the RuneScape TTFs carry no medal, crown, star or bullet
	 * glyph, and anything outside the plain ASCII markers renders as a tofu
	 * box. A diamond needs no glyph at all, and it cannot be confused with the
	 * taint badge's "*" sitting beside it.
	 */
	private static final class Pip extends JComponent {
		private final Color color;
		/** This is the mark's owner: outline it so one pip still stands out. */
		private final boolean owner;

		Pip(Color color, boolean owner) {
			this.color = color;
			this.owner = owner;
			Dimension d = new Dimension(PIP, PIP);
			setPreferredSize(d);
			setMinimumSize(d);
			setMaximumSize(d);
		}

		@Override
		protected void paintComponent(Graphics g) {
			Graphics2D g2 = (Graphics2D) g.create();
			try {
				g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING,
					RenderingHints.VALUE_ANTIALIAS_ON);
				int top = Math.max(0, getHeight() / 2 - PIP / 2);
				int mid = PIP / 2;
				int[] xs = {mid, PIP - 1, mid, 0};
				int[] ys = {top, top + mid, top + PIP - 1, top + mid};
				g2.setColor(color);
				g2.fillPolygon(xs, ys, 4);
				g2.setColor(owner ? MARK_OWNER : color.darker());
				g2.drawPolygon(xs, ys, 4);
			}
			finally {
				g2.dispose();
			}
		}
	}

}

package com.gachaman.ui.panel;

import java.util.List;
import com.gachaman.data.*;
import com.gachaman.model.*;
import com.gachaman.service.*;
import com.gachaman.ui.*;
import com.google.gson.*;
import java.awt.*;
import java.awt.event.*;
import java.awt.image.*;
import java.util.*;
import javax.annotation.*;
import javax.inject.*;
import javax.swing.*;
import javax.swing.border.*;
import javax.swing.event.*;
import net.runelite.client.ui.*;

/**
 * Loadout: the eleven gear slots arranged like the in-game equipment tab.
 * Deeded slots accept owned cards (holograms fit any slot); locked slots show
 * a padlock and can be unlocked with a pending Slot Deed.
 */
@Singleton
public class LoadoutTab extends JPanel {
	private static final Color GOLD = new Color(230, 190, 80);
	private static final Color HOLO_BORDER = new Color(120, 220, 255);
	private static final Color LOCKED_FILL = new Color(30, 30, 30);
	private static final Color SLOT_FILL = new Color(40, 38, 34);
	private static final int SLOT_W = 64;
	private static final int SLOT_H = 56;

	/**
	 * (gridx, gridy) placement per slot, mirroring the equipment tab shape —
	 * read from loadout-board.json, which is the SAME table the in-game
	 * LoadoutOverlay lays its sockets out from. Two hand-written copies of one
	 * arrangement is one edit away from a board that disagrees with itself about
	 * where the ring goes; see {@link BoardLayout}.
	 *
	 * <p>An instance field loaded in the constructor rather than the static block
	 * this replaces: the Gson is injected, so it does not exist until Guice has
	 * built this panel, and a data table must never load from a static
	 * initialiser.
	 */
	private final Map<String, BoardLayout.Socket> sockets;

	private final GachaStateService stateService;
	private final CardDatabase cardDatabase;
	private final CardImageService cardImageService;
	private final PermissionService permissionService;
	private final ChestService chestService;
	private final LoadoutService loadoutService;

	@Inject
	public LoadoutTab(GachaStateService stateService, CardDatabase cardDatabase,
		CardImageService cardImageService, PermissionService permissionService,
		ChestService chestService, LoadoutService loadoutService, Gson gson) {
		this.sockets = BoardLayout.load(gson);
		this.stateService = stateService;
		this.cardDatabase = cardDatabase;
		this.cardImageService = cardImageService;
		this.permissionService = permissionService;
		this.chestService = chestService;
		this.loadoutService = loadoutService;
		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setOpaque(false);
		setBorder(new EmptyBorder(0, 0, 6, 0));
	}

	void rebuild() {
		removeAll();
		GachaState state = stateService.get();
		if (state == null) {
			add(GachamanPanel.centeredNote("Log in to manage your loadout."));
			revalidate();
			repaint();
			return;
		}

		if (state.getPendingDeeds() > 0) {
			JPanel banner = GachamanPanel.section(null);
			banner.setBorder(BorderFactory.createCompoundBorder(
				BorderFactory.createLineBorder(GOLD, 1),
				new EmptyBorder(7, 7, 7, 7)));
			String plural = state.getPendingDeeds() == 1 ? "a Slot Deed"
				: state.getPendingDeeds() + " Slot Deeds";
			banner.add(GachamanPanel.line("You have " + plural + "!", GOLD,
				FontManager.getRunescapeBoldFont()));
			banner.add(GachamanPanel.wrapped("Click a locked slot to unlock it.", GOLD));
			add(banner);
			add(Box.createVerticalStrut(6));
		}

		JPanel gridSection = GachamanPanel.section("Loadout");
		JPanel grid = new JPanel(new GridBagLayout());
		grid.setOpaque(false);
		grid.setAlignmentX(Component.LEFT_ALIGNMENT);
		GridBagConstraints gbc = new GridBagConstraints();
		// 2px, not 3. A cell is SLOT_W plus its inset each side, and three columns
		// have to fit the 205px inside a section(): at 3 the grid wanted
		// 3 * (64 + 6) = 210 in a scroll pane with no horizontal bar, so the ring,
		// shield and ammo column simply lost its right edge. 3 * (64 + 4) = 204.
		gbc.insets = new Insets(2, 2, 2, 2);
		for (GearSlot slot : GearSlot.values()) {
			BoardLayout.Socket cell = sockets.get(slot.name());
			// a slot the resource does not name is left off the grid rather than
			// stacked at (0,0) on top of another one
			if (cell == null)
				continue;
			gbc.gridx = cell.getCol();
			gbc.gridy = cell.getRow();
			grid.add(buildSlotComponent(state, slot), gbc);
		}
		gridSection.add(grid);
		gridSection.add(Box.createVerticalStrut(5));
		gridSection.add(GachamanPanel.wrapped(
			"Left-click a slot to assign a card. Right-click to unassign.",
			ColorScheme.MEDIUM_GRAY_COLOR));
		add(gridSection);

		revalidate();
		repaint();
	}

	private SlotComponent buildSlotComponent(GachaState state, GearSlot slot) {
		boolean deeded = permissionService.isSlotDeeded(slot)
			|| state.getDeededSlots().contains(slot.name());
		OwnedCard assigned = loadoutService.assigned(slot);

		String name = null;
		Color border = null;
		BufferedImage sprite = null;
		if (assigned != null && cardDatabase.isReady()) {
			if (assigned.isHologram()) {
				HologramDefinition holo = cardDatabase.holograms().get(assigned.getTierKey());
				name = holo != null ? holo.getName() : "Hologram";
				border = HOLO_BORDER;
				if (holo != null)
					sprite = cardImageService.hologramImage(holo, this::repaint);
			}
			else {
				CardDefinition def = cardDatabase.card(assigned.getCardId());
				if (def != null) {
					name = def.getName();
					border = def.getRarity().getColor();
					sprite = cardImageService.cardImage(def, this::repaint);
				}
				else {
					name = "Card #" + assigned.getCardId();
					border = Rarity.COMMON.getColor();
				}
			}
		}

		SlotComponent component = new SlotComponent(slot, deeded, assigned != null,
			state.getPendingDeeds() > 0, name, border, sprite);
		component.addMouseListener(new MouseAdapter() {
			@Override
			public void mousePressed(MouseEvent e) {
				handleSlotPress(component, slot, e);
			}
		});
		return component;
	}

	private void handleSlotPress(SlotComponent component, GearSlot slot, MouseEvent e) {
		GachaState state = stateService.get();
		if (state == null)
			return;
		boolean deeded = permissionService.isSlotDeeded(slot)
			|| state.getDeededSlots().contains(slot.name());
		if (!deeded) {
			if (state.getPendingDeeds() > 0
				&& GachamanPanel.confirm(this, "Slot Deed",
					"Use a Slot Deed to unlock the " + slot.getDisplayName() + " slot?")) {
				chestService.claimDeed(slot);
			}
			return;
		}
		if (SwingUtilities.isRightMouseButton(e)) {
			OwnedCard assigned = loadoutService.assigned(slot);
			if (assigned != null) {
				JPopupMenu menu = new JPopupMenu();
				JMenuItem unassign = new JMenuItem("Unassign " + loadoutService.displayName(assigned));
				unassign.addActionListener(a -> unassignOrExplain(slot));
				menu.add(unassign);
				menu.show(component, e.getX(), e.getY());
			}
			return;
		}
		showAssignMenu(component, slot, e.getX(), e.getY());
	}

	/**
	 * Clear a slot, and put the guard's refusal in front of the player when it
	 * says no. Both unassign routes on this page — the right-click menu item
	 * and the picker's Unassign row — come through here, so neither can be the
	 * one that silently swallows a refusal.
	 *
	 * <p>The chat line has already gone out from LoadoutService; this is the
	 * dialog on top of it, because a click made in the sidebar is answered in
	 * the sidebar. The assign refusal a few lines below sets that expectation.
	 *
	 * <p>No hop to the client thread, deliberately. The guard reads the worn
	 * container, but it is advisory rather than a boundary — the worst a stale
	 * read can do is refuse (or allow) a beat late — and both routes already
	 * mutate and checkpoint state from this thread, so a hop would be new
	 * machinery buying an answer nobody can act on faster than a game tick.
	 */
	private void unassignOrExplain(GearSlot slot) {
		if (!loadoutService.unassign(slot)) {
			GachamanPanel.info(this, "That card is still unlocking what you are wearing."
				+ " Take the item off first.");
		}
	}

	/**
	 * Card picker: a popup hosting a search field + list. Unlike JMenuItems
	 * (which activate on the mouse RELEASE of the click that opened the menu,
	 * causing accidental picks), a list row only reacts to its own complete
	 * click — selection is always a second, deliberate action. Typing in the
	 * field filters live; Enter picks the top match; Esc closes.
	 */
	private void showAssignMenu(SlotComponent component, GearSlot slot, int x, int y) {
		List<OwnedCard> valid = loadoutService.validFor(slot);
		OwnedCard current = loadoutService.assigned(slot);

		JPopupMenu popup = new JPopupMenu();
		popup.setBorder(BorderFactory.createLineBorder(ColorScheme.DARKER_GRAY_HOVER_COLOR));
		JPanel content = new JPanel(new BorderLayout(0, 4));
		content.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		content.setBorder(new EmptyBorder(6, 6, 6, 6));

		JTextField search = new JTextField();
		search.setBackground(ColorScheme.DARK_GRAY_COLOR);
		search.setForeground(Color.WHITE);
		search.setCaretColor(Color.WHITE);
		search.setBorder(new EmptyBorder(4, 6, 4, 6));
		search.setToolTipText("Type to filter");
		content.add(search, BorderLayout.NORTH);

		DefaultListModel<Object> model = new DefaultListModel<>();
		JList<Object> list = new JList<>(model);
		list.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		list.setSelectionBackground(ColorScheme.DARKER_GRAY_HOVER_COLOR);
		list.setSelectionForeground(Color.WHITE);
		list.setCellRenderer(new DefaultListCellRenderer() {
			@Override
			public Component getListCellRendererComponent(JList<?> jList,
				Object value, int index, boolean selected, boolean focused) {
				super.getListCellRendererComponent(jList, value, index, selected, focused);
				if (value instanceof OwnedCard) {
					OwnedCard owned = (OwnedCard) value;
					setText(loadoutService.displayName(owned));
					BufferedImage icon = iconFor(owned);
					setIcon(icon != null ? new ImageIcon(icon) : null);
				}
				else {
					setText(String.valueOf(value));
					setIcon(null);
					setForeground(new Color(240, 140, 130));
				}
				if (!selected) {
					setBackground(ColorScheme.DARKER_GRAY_COLOR);
					if (value instanceof OwnedCard)
						setForeground(Color.WHITE);
				}
				return this;
			}
		});

		Runnable refilter = () -> {
			String typed = search.getText() == null ? "" : search.getText().trim();
			String filter = typed.toLowerCase();
			model.clear();
			if (current != null)
				model.addElement("Unassign " + loadoutService.displayName(current));
			int matches = 0;
			for (OwnedCard owned : valid) {
				if (filter.isEmpty()
					|| loadoutService.displayName(owned).toLowerCase().contains(filter)) {
					model.addElement(owned);
					matches++;
				}
			}
			// Counted, not model.isEmpty(). With a card already in the slot the
			// "Unassign" row is always present, so the model was never empty and
			// the slot that HAS a card was the one slot that could never explain
			// an empty list. And the reason matters: a filter that matches nothing
			// is a typo to fix, not a collection to go and earn.
			if (matches == 0) {
				model.addElement(filter.isEmpty()
					? "No eligible cards for " + slot.getDisplayName()
					: "No card here matches \"" + typed + "\"");
			}
		};
		refilter.run();
		search.getDocument().addDocumentListener(new DocumentListener() {
			@Override
			public void insertUpdate(DocumentEvent e) {
				refilter.run();
			}

			@Override
			public void removeUpdate(DocumentEvent e) {
				refilter.run();
			}

			@Override
			public void changedUpdate(DocumentEvent e) {
				refilter.run();
			}
		});

		Runnable pickSelected = () -> {
			Object value = list.getSelectedValue();
			if (value instanceof OwnedCard) {
				popup.setVisible(false);
				if (!loadoutService.assign(slot, ((OwnedCard) value).getUuid())) {
					GachamanPanel.info(this, "That card cannot go in the "
						+ slot.getDisplayName() + " slot.");
				}
			}
			else if (value instanceof String && ((String) value).startsWith("Unassign")) {
				popup.setVisible(false);
				unassignOrExplain(slot);
			}
		};
		list.addMouseListener(new MouseAdapter() {
			@Override
			public void mouseClicked(MouseEvent e) {
				int index = list.locationToIndex(e.getPoint());
				if (index >= 0) {
					list.setSelectedIndex(index);
					pickSelected.run();
				}
			}
		});
		search.addActionListener(e -> {
			// Enter picks the first real match
			for (int i = 0; i < model.size(); i++) {
				if (model.get(i) instanceof OwnedCard) {
					list.setSelectedIndex(i);
					pickSelected.run();
					return;
				}
			}
		});

		JScrollPane scroll = new JScrollPane(list,
			ScrollPaneConstants.VERTICAL_SCROLLBAR_AS_NEEDED,
			ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		scroll.setBorder(null);
		scroll.setPreferredSize(new Dimension(190,
			Math.min(320, Math.max(60, model.size() * 40))));
		GachamanPanel.styleScrollbar(scroll);
		content.add(scroll, BorderLayout.CENTER);

		popup.add(content);
		popup.show(component, x, y);
		SwingUtilities.invokeLater(search::requestFocusInWindow);
	}

	@Nullable
	private BufferedImage iconFor(OwnedCard owned) {
		if (!cardDatabase.isReady())
			return null;
		if (owned.isHologram()) {
			HologramDefinition holo = cardDatabase.holograms().get(owned.getTierKey());
			return holo == null ? null : cardImageService.hologramImage(holo, null);
		}
		CardDefinition def = cardDatabase.card(owned.getCardId());
		return def == null ? null : cardImageService.cardImage(def, null);
	}

	// --- Slot component ---

	private static final class SlotComponent extends JComponent {
		private final GearSlot slot;
		private final boolean deeded;
		private final boolean assigned;
		private final boolean deedAvailable;
		@Nullable
		private final String cardName;
		@Nullable
		private final Color borderColor;
		@Nullable
		private final BufferedImage sprite;

		SlotComponent(GearSlot slot, boolean deeded, boolean assigned, boolean deedAvailable,
			String cardName, Color borderColor, BufferedImage sprite) {
			this.slot = slot;
			this.deeded = deeded;
			this.assigned = assigned;
			this.deedAvailable = deedAvailable;
			this.cardName = cardName;
			this.borderColor = borderColor;
			this.sprite = sprite;
			setPreferredSize(new Dimension(SLOT_W, SLOT_H));
			setMinimumSize(new Dimension(SLOT_W, SLOT_H));
			// every arm opens with the slot name, so only the tail varies
			setToolTipText(slot.getDisplayName() + (!deeded
				? " — locked" + (deedAvailable ? " (click to use a Slot Deed)" : " (find a Slot Deed)")
				: assigned && cardName != null
					? ": " + cardName
					: " — empty (click to assign)"));
		}

		@Override
		protected void paintComponent(Graphics g) {
			Graphics2D g2 = (Graphics2D) g.create();
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			int w = getWidth();
			int h = getHeight();

			g2.setColor(deeded ? SLOT_FILL : LOCKED_FILL);
			g2.fillRoundRect(0, 0, w - 1, h - 1, 8, 8);

			Color outline = !deeded
				? (deedAvailable ? GOLD : ColorScheme.MEDIUM_GRAY_COLOR.darker())
				: assigned && borderColor != null ? borderColor : ColorScheme.MEDIUM_GRAY_COLOR;
			g2.setColor(outline);
			g2.setStroke(new BasicStroke(assigned ? 2f : 1.2f));
			g2.drawRoundRect(0, 0, w - 1, h - 1, 8, 8);

			if (!deeded) {
				drawPadlock(g2, w / 2, h / 2 - 6, deedAvailable ? GOLD : ColorScheme.MEDIUM_GRAY_COLOR);
				drawSlotName(g2, w, h, ColorScheme.MEDIUM_GRAY_COLOR);
			}
			else if (!assigned) {
				g2.setColor(ColorScheme.MEDIUM_GRAY_COLOR);
				g2.setFont(FontManager.getRunescapeBoldFont().deriveFont(18f));
				centred(g2, "+", w, h / 2 + 2);
				drawSlotName(g2, w, h, ColorScheme.MEDIUM_GRAY_COLOR);
			}
			else {
				if (sprite != null) {
					int sw = Math.min(sprite.getWidth(), w - 8);
					int sh = Math.min(sprite.getHeight(), h - 20);
					g2.drawImage(sprite, (w - sw) / 2, 4, sw, sh, null);
				}
				g2.setFont(FontManager.getRunescapeSmallFont());
				g2.setColor(borderColor != null ? borderColor : Color.WHITE);
				centred(g2, cardName == null ? slot.getDisplayName() : truncate(g2, cardName, w - 6),
					w, h - 5);
			}
			g2.dispose();
		}

		private void drawSlotName(Graphics2D g2, int w, int h, Color color) {
			g2.setFont(FontManager.getRunescapeSmallFont());
			g2.setColor(color);
			centred(g2, truncate(g2, slot.getDisplayName(), w - 6), w, h - 5);
		}

		/**
		 * Draw text horizontally centred in a {@code w}-wide cell on the given
		 * baseline — the measure-then-draw pair every label in this component
		 * repeated verbatim, in the current font and colour so callers keep setting
		 * those themselves.
		 */
		private static void centred(Graphics2D g2, String text, int w, int baselineY) {
			FontMetrics fm = g2.getFontMetrics();
			g2.drawString(text, (w - fm.stringWidth(text)) / 2, baselineY);
		}

		private static void drawPadlock(Graphics2D g2, int cx, int cy, Color color) {
			g2.setColor(color);
			g2.setStroke(new BasicStroke(2f));
			// shackle
			g2.drawArc(cx - 6, cy - 8, 12, 12, 0, 180);
			// body
			g2.fillRoundRect(cx - 8, cy - 2, 16, 12, 3, 3);
			// keyhole
			g2.setColor(LOCKED_FILL);
			g2.fillOval(cx - 2, cy + 1, 4, 4);
			g2.drawLine(cx, cy + 4, cx, cy + 7);
		}

		private static String truncate(Graphics2D g2, String text, int maxWidth) {
			FontMetrics fm = g2.getFontMetrics();
			if (fm.stringWidth(text) <= maxWidth)
				return text;
			String drawn = text;
			while (drawn.length() > 2 && fm.stringWidth(drawn + "…") > maxWidth) {
				drawn = drawn.substring(0, drawn.length() - 1);
			}
			return drawn + "…";
		}
	}
}

package com.gachaman.ui.panel;

import java.util.List;
import static com.gachaman.ui.panel.GachamanPanel.hex;
import static com.gachaman.ui.panel.GachamanPanel.htmlWrap;
import com.gachaman.*;
import com.gachaman.model.*;
import com.gachaman.service.*;
import java.awt.*;
import java.text.*;
import java.util.*;
import javax.annotation.*;
import javax.inject.*;
import javax.swing.*;
import javax.swing.border.*;
import net.runelite.client.ui.*;
import net.runelite.client.util.*;

/**
 * The Contract Dossier: every contract you have filed, newest first, under a
 * pinned totals header.
 *
 * <p>Distinct from the Timeline, which is a chronological audit of ALL fortune
 * events sharing one 500-entry budget that a busy chest session drains in an
 * afternoon; and from the Journal, which aggregates per MONSTER and keeps no
 * chronology. Only this page can answer "what did that job actually pay, and
 * did I run it clean" — and only this layout can pin the totals, because the
 * header lives in BorderLayout.NORTH outside the scroll viewport.
 */
@Singleton
public class DossierTab extends JPanel {
	/**
	 * Year included: the log retains {@link Tuning#DOSSIER_MAX_RECORDS} contracts,
	 * which for a slow player spans well over a year, and a bare "Aug 9" on a
	 * record filed two years ago is a lie. Locale pinned to ENGLISH so the month
	 * abbreviation matches the rest of the panel's copy on a non-English JVM
	 * rather than appearing alone in the system language.
	 */
	private static final SimpleDateFormat LINE_FORMAT =
		new SimpleDateFormat("d MMM yy HH:mm", Locale.ENGLISH);

	private static final Color CLEAN_GREEN = new Color(110, 200, 110);
	private static final Color BAD_RED = new Color(229, 90, 80);
	private static final Color DETAIL_GRAY = new Color(138, 138, 138);
	private static final Color BODY_GRAY = new Color(200, 200, 200);
	private static final Color PARTY_BLUE = new Color(150, 190, 240);

	private final GachaStateService stateService;

	private final JPanel header = new JPanel();
	private final JEditorPane list = new JEditorPane();

	@Inject
	public DossierTab(GachaStateService stateService) {
		this.stateService = stateService;
		setLayout(new BorderLayout(0, 6));
		setOpaque(false);

		header.setLayout(new BoxLayout(header, BoxLayout.Y_AXIS));
		header.setOpaque(false);
		add(header, BorderLayout.NORTH);

		add(GachamanPanel.htmlListScroll(list), BorderLayout.CENTER);
	}

	void rebuild() {
		header.removeAll();
		GachaState state = stateService.get();
		if (state == null) {
			list.setText(htmlWrap("<font color='#909090'>Log in to view your dossier.</font>"));
			header.revalidate();
			header.repaint();
			return;
		}

		List<ContractRecord> log = state.getContractLog();
		DossierSummary summary = DossierSummary.of(log);
		header.add(buildTotals(state, summary));

		list.setText(htmlWrap(buildRows(log)));
		// newest first, so the top of the document is the interesting end
		list.setCaretPosition(0);
		header.revalidate();
		header.repaint();
	}

	private static JPanel buildTotals(GachaState state, DossierSummary summary) {
		JPanel section = GachamanPanel.section(null);
		section.add(GachamanPanel.line("Contracts filed: " + summary.getContracts(),
			Color.WHITE, FontManager.getRunescapeBoldFont()));
		section.add(Box.createVerticalStrut(4));

		if (summary.getContracts() == 0) {
			section.add(GachamanPanel.smallLine("Nothing filed yet — go and sign one.",
				ColorScheme.MEDIUM_GRAY_COLOR));
			section.add(Box.createVerticalStrut(3));
			section.add(GachamanPanel.smallLine(
				"Lifetime earned: " + QuantityFormatter.formatNumber(state.getLifetimeGcEarned()) + " GC",
				ColorScheme.BRAND_ORANGE));
			return section;
		}

		section.add(new GachamanPanel.MeterBar(summary.cleanFraction(), CLEAN_GREEN,
			summary.getCleanContracts() + " / " + summary.getContracts() + " clean"));
		section.add(Box.createVerticalStrut(4));
		// Both GC figures on the pay line and both counts on the next: "best" is a
		// GC number and reading it off a line labelled "Kills:" made it look like a
		// kill count.
		section.add(GachamanPanel.smallLine(
			"Pay: " + QuantityFormatter.formatNumber(summary.getTotalGc()) + " GC  ·  avg "
				+ QuantityFormatter.formatNumber(summary.averageGc()) + " GC",
			ColorScheme.LIGHT_GRAY_COLOR));
		section.add(GachamanPanel.smallLine(
			"Best: " + QuantityFormatter.formatNumber(summary.getBestGc()) + " GC  ·  "
				+ QuantityFormatter.formatNumber(summary.getTotalKills()) + " kills",
			ColorScheme.LIGHT_GRAY_COLOR));
		section.add(GachamanPanel.smallLine(
			"Time: " + formatDuration(summary.getTotalDurationMs()) + "  ·  avg "
				+ formatDuration(summary.averageDurationMs()),
			ColorScheme.LIGHT_GRAY_COLOR));
		section.add(GachamanPanel.smallLine(
			"Clean rate: " + summary.cleanPercent() + "%  ·  shared " + summary.getPartyContracts(),
			ColorScheme.LIGHT_GRAY_COLOR));
		if (summary.getContracts() >= Tuning.DOSSIER_MAX_RECORDS) {
			// totals are a fold over the RETAINED window, so say so rather than
			// letting the header read as a lifetime figure it is not
			section.add(GachamanPanel.smallLine("(last " + Tuning.DOSSIER_MAX_RECORDS + " contracts)",
				ColorScheme.MEDIUM_GRAY_COLOR));
		}
		section.add(Box.createVerticalStrut(3));
		// the one true lifetime number, unbounded by the log's cap
		section.add(GachamanPanel.smallLine(
			"Lifetime earned: " + QuantityFormatter.formatNumber(state.getLifetimeGcEarned()) + " GC",
			ColorScheme.BRAND_ORANGE));
		return section;
	}

	private static String buildRows(List<ContractRecord> log) {
		if (log == null || log.isEmpty())
			return "<font color='#909090'>No contracts filed yet. Complete one and it lands here.</font>";
		StringBuilder html = new StringBuilder();
		int shown = 0;
		// newest first: the log is appended in completion order, so walk it back
		for (int i = log.size() - 1; i >= 0; i--) {
			ContractRecord record = log.get(i);
			if (record == null) {
				continue; // Gson can hand back a null array element
			}
			shown++;
			html.append("<font color='").append(hex(difficultyColor(record.getDifficulty())))
				.append("'>").append(GachamanPanel.escape(nameOf(record.getMonsterName()))).append("</font>")
				.append("<font color='").append(hex(BODY_GRAY)).append("'>").append(GachamanPanel.DOT)
				.append(QuantityFormatter.formatNumber(record.getKills()))
				.append(record.getKills() == 1 ? " kill" : " kills").append(GachamanPanel.DOT)
				.append(QuantityFormatter.formatNumber(record.getGc())).append(" GC</font><br/>");

			html.append("<font color='").append(hex(DETAIL_GRAY)).append("'>")
				.append(LINE_FORMAT.format(new Date(record.getAt())))
				.append(GachamanPanel.DOT).append(formatDuration(record.getDurationMs()));
			Color styleColor = styleColor(record.getStyle());
			if (styleColor != null) {
				html.append(GachamanPanel.DOT).append("<font color='").append(hex(styleColor)).append("'>")
					.append(GachamanPanel.escape(styleName(record.getStyle()))).append("</font>");
			}
			if (record.isParty()) {
				html.append(GachamanPanel.DOT).append("<font color='").append(hex(PARTY_BLUE)).append("'>")
					.append(GachamanPanel.escape(record.getParty())).append("</font>");
			}
			if (record.isCarried())
				html.append(GachamanPanel.DOT).append("carried");
			if (record.isRedemption())
				html.append(GachamanPanel.DOT).append("redemption");
			html.append(GachamanPanel.DOT).append("<font color='")
				.append(hex(record.isClean() ? CLEAN_GREEN : BAD_RED)).append("'>")
				.append(record.isClean() ? "clean"
					: record.getTaintedKills() + (record.getTaintedKills() == 1
						? " off-style kill" : " off-style kills"))
				.append("</font></font><br/><br/>");
		}
		if (shown == 0)
			return "<font color='#909090'>No contracts filed yet. Complete one and it lands here.</font>";
		return html.toString();
	}

	private static String nameOf(String monsterName) {
		return monsterName == null || monsterName.isEmpty() ? "Unknown quarry" : monsterName;
	}

	/** Falls back to neutral for a difficulty name this build does not know. */
	private static Color difficultyColor(String difficulty) {
		if (difficulty == null)
			return ColorScheme.LIGHT_GRAY_COLOR;
		try {
			return TaskDifficulty.valueOf(difficulty).getColor();
		}
		catch (IllegalArgumentException e) {
			return ColorScheme.LIGHT_GRAY_COLOR; // a record filed by a future version
		}
	}

	/** Null when there is no style to show, so the caller can omit the segment. */
	@Nullable
	private static Color styleColor(String style) {
		if (style == null)
			return null;
		try {
			return AttackStyle.valueOf(style).getColor();
		}
		catch (IllegalArgumentException e) {
			return ColorScheme.LIGHT_GRAY_COLOR;
		}
	}

	static String styleName(String style) {
		if (style == null)
			return "";
		try {
			return AttackStyle.valueOf(style).getDisplayName();
		}
		catch (IllegalArgumentException e) {
			return style; // show the raw name rather than dropping the fact
		}
	}

static String formatDuration(long ms) {
		long totalSeconds = Math.max(0, ms) / 1000;
		long minutes = totalSeconds / 60;
		long seconds = totalSeconds % 60;
		if (minutes >= 60)
			return String.format("%d:%02d:%02d", minutes / 60, minutes % 60, seconds);
		return String.format("%d:%02d", minutes, seconds);
	}
}

package com.gachaman.ui;

import java.awt.*;

/**
 * The two paint helpers every animated surface in the plugin needs, in one
 * place instead of three.
 *
 * <p>{@link #hash01} in particular had drifted into CardRenderer, RevealOverlay
 * and KillJuiceOverlay as three byte-identical copies. That is worse than
 * wasteful: card wear, chest motes and kill sparks all seed their scatter from
 * it, and a "harmless" tweak to one copy would have silently re-rolled the
 * pattern on one surface while leaving the others alone.
 */
public final class Paint {
	private Paint() {
	}

	/**
	 * A deterministic 0..1 from an int seed — the same value for the same seed,
	 * forever and on every machine. Effects seeded from a card name or a
	 * particle index are then frame-stable and survive a restart.
	 */
	public static float hash01(int n) {
		int h = n * 0x9E3779B9;
		h ^= h >>> 16;
		h *= 0x85EBCA6B;
		h ^= h >>> 13;
		return (h & 0x7FFFFFFF) / (float) 0x7FFFFFFF;
	}

	/** The same colour at a new alpha, clamped rather than wrapped. */
	public static Color withAlpha(Color c, float alpha) {
		int a = Math.max(0, Math.min(255, Math.round(alpha * 255f)));
		return new Color(c.getRed(), c.getGreen(), c.getBlue(), a);
	}
}

package com.gachaman.ui;

import java.util.List;
import com.gachaman.*;
import com.gachaman.model.*;
import java.awt.*;
import java.awt.geom.*;
import java.awt.image.*;
import java.util.*;
import javax.annotation.*;
import lombok.*;

/**
 * Procedural card face rendering: rarity frames, foil sheen, shiny prismatic
 * cycling, hologram scanlines with chromatic ghosting, deterministic sparkles.
 * Pure drawing — animation state comes in via timeMs so callers control time.
 */
public final class CardRenderer {
	private static final Color CARD_BG_TOP = new Color(48, 42, 32);
	private static final Color CARD_BG_BOTTOM = new Color(28, 24, 18);
	private static final Color NAME_BAND = new Color(20, 17, 12, 230);
	private static final Color CARD_BACK_A = new Color(58, 34, 92);
	private static final Color CARD_BACK_B = new Color(32, 18, 52);
	private static final Color SERVICE_BG = new Color(18, 15, 10, 215);
	private static final Color SERVICE_EDGE = new Color(176, 141, 87, 210);
	private static final Color SERVICE_TEXT = new Color(226, 205, 158);
	/**
	 * Card stock. A printed card is ink over a pale board, so everywhere the print
	 * has worn through — the rim, the corners, the lit ridge of a crease, a
	 * shuffling scratch — what shows is this, slightly warm and never pure white.
	 * That one fact is what makes wear read as wear instead of as drawn-on damage.
	 */
	private static final Color WEAR_STOCK = new Color(216, 208, 192);
	private static final Color WEAR_SHADOW = new Color(10, 8, 5);
	/** Handling dirt: fingers, sleeves, and a decade in a box. */
	private static final Color WEAR_GRIME = new Color(26, 19, 10);
	/**
	 * Steps per crease. A crease is one polyline crossing the whole card, so this
	 * is how finely it bends rather than how many separate marks are drawn — and
	 * because the underlying meander is a smooth curve, MORE steps is smoother,
	 * not busier. Twelve is where the joints stop being visible at 150px.
	 */
	static final int WEAR_STEPS = 12;
	/** Segment kinds returned by {@link #wearSegments}, at index 4. */
	static final int KIND_CREASE = 0;
	static final int KIND_SCRATCH = 1;
	/** How far a scratch bows off its own straight line, as a fraction of half its length. */
	private static final double SCRATCH_BEND = 0.06;
	/**
	 * The bound on that bow once wearSeamPath's grit is included — its wave tops
	 * out at 1.0 and the grit adds another 0.11 — rounded up. Placement adds this
	 * to the plain sin/cos extent, because a scratch sized by trigonometry alone
	 * pokes its tip into the name band and loses the last of itself to the text
	 * check.
	 */
	private static final double WANDER = SCRATCH_BEND * 1.12;

	@Value
	@Builder
	public static class CardView {
		String name;
		Rarity rarity;
		Variant variant;
		@Nullable
		BufferedImage art;
		@Nullable
		String subtitle; // e.g. "Dragon tier — any slot" for holograms
		/**
		 * Service Record — kills this copy was assigned to the loadout for.
		 * 0 hides the badge, which is what @Builder leaves an unset int at, so
		 * every existing builder call site keeps rendering pixel-identically.
		 */
		int killsServed;
	}

	private CardRenderer() {
	}

	/**
	 * A child Graphics2D to draw one layer on, antialiased, optionally clipped —
	 * the preamble nine drawing methods here used to spell out for themselves.
	 *
	 * <p>The null-clip branch is the reason this takes a nullable Shape rather
	 * than always calling setClip: passing null STRAIGHT through would CLEAR the
	 * caller's clip (a RuneLite overlay's, or Swing's paint clip) rather than
	 * leave it alone, and the three top-level entry points rely on inheriting it.
	 *
	 * <p>Setting antialiasing here is a no-op for the clipped callers that used
	 * to omit it — Graphics.create() copies the parent's rendering hints, and
	 * every clipped child in this file descends from drawBack's or drawFace's
	 * graphics, on which antialiasing is already on.
	 */
	private static Graphics2D layer(Graphics2D g, Shape clip) {
		Graphics2D out = (Graphics2D) g.create();
		if (clip != null)
			out.setClip(clip);
		out.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		return out;
	}

	/** Draw a face-down card back. */
	public static void drawBack(Graphics2D g, int x, int y, int w, int h, long timeMs) {
		Graphics2D g2 = layer(g, null);
		RoundRectangle2D shape = new RoundRectangle2D.Float(x, y, w, h, w / 7f, w / 7f);
		g2.setPaint(new GradientPaint(x, y, CARD_BACK_A, x, y + h, CARD_BACK_B));
		g2.fill(shape);
		g2.setColor(new Color(212, 175, 55));
		g2.setStroke(new BasicStroke(2f));
		g2.draw(shape);
		// simple gacha sigil: diamond + circle
		int cx = x + w / 2;
		int cy = y + h / 2;
		int r = Math.min(w, h) / 5;
		g2.setColor(new Color(212, 175, 55, 150));
		g2.drawOval(cx - r, cy - r, r * 2, r * 2);
		// the diamond's half-diagonal, one and a half radii. Four separate lines
		// rather than one drawPolygon on purpose: BasicStroke(2f) defaults to
		// CAP_SQUARE/JOIN_MITER, so a closed mitered path would differ from four
		// square-capped strokes by a pixel or two at every vertex.
		int d = r + r / 2;
		g2.drawLine(cx, cy - d, cx + d, cy);
		g2.drawLine(cx + d, cy, cx, cy + d);
		g2.drawLine(cx, cy + d, cx - d, cy);
		g2.drawLine(cx - d, cy, cx, cy - d);
		// slow sheen sweep so backs feel alive
		drawSheen(g2, shape, x, y, w, h, timeMs, 5200, new Color(255, 255, 255, 26));
		g2.dispose();
	}

	/** Draw a face-up card. */
	public static void drawFace(Graphics2D g, int x, int y, int w, int h, CardView view, long timeMs) {
		Graphics2D g2 = layer(g, null);
		RoundRectangle2D shape = new RoundRectangle2D.Float(x, y, w, h, w / 7f, w / 7f);

		// body
		g2.setPaint(new GradientPaint(x, y, CARD_BG_TOP, x, y + h, CARD_BG_BOTTOM));
		g2.fill(shape);

		// art — cropped to its opaque bounds first: item sprites carry uneven
		// transparent padding, so centering the raw sprite off-centers the art.
		if (view.getArt() != null) {
			int artH = (int) (h * 0.52);
			int artY = y + (int) (h * 0.12);
			BufferedImage art = cropToOpaqueBounds(view.getArt());
			double scale = Math.min((double) (w - 16) / art.getWidth(), (double) artH / art.getHeight());
			int dw = Math.max(1, (int) (art.getWidth() * scale));
			int dh = Math.max(1, (int) (art.getHeight() * scale));
			// Nearest-neighbour so a scaled item sprite stays crisp instead of
			// turning to mush. Set on g2 itself rather than on a throwaway child:
			// g2 is drawFace's own private copy (created above, disposed at the
			// end), so the hint cannot escape to the caller, and KEY_INTERPOLATION
			// only affects drawImage and TexturePaint — neither of which anything
			// drawn after the art here uses.
			g2.setRenderingHint(RenderingHints.KEY_INTERPOLATION,
				RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
			g2.drawImage(art, x + (w - dw) / 2, artY + (artH - dh) / 2, dw, dh, null);
		}

		// Cracked Cards, first of three passes: handling dirt. Deliberately over
		// the art and under every piece of text — a veteran card's PICTURE is the
		// part that goes dull with age, while its printing has to stay readable at
		// 90px. Drawing it under the art instead would read as a dirty background
		// rather than as a dirty card.
		CardWear wear = Tuning.cardWear(view.getKillsServed());
		// seeded from the NAME, not from timeMs and not from a new CardView
		// field: the pattern is then frame-stable (no shimmer on a static
		// card), survives a restart, and is identical between the album
		// thumbnail and the reveal card — one physical object, not two.
		// Hoisted because all three wear passes below want the same number, and
		// String.hashCode is specified and pure, so one read cannot disagree
		// with another.
		int seed = view.getName().hashCode();
		if (wear != CardWear.NONE)
			drawWearGrime(g2, shape, x, y, w, h, wear, seed);

		// name band — the font SHRINKS to fit the name (ellipsis only as a
		// last resort at the minimum size)
		int bandH = Math.max(16, h / 6);
		g2.setColor(NAME_BAND);
		g2.fillRect(x + 2, y + h - bandH - h / 8, w - 4, bandH);
		g2.setColor(view.getRarity().getColor());
		drawFittedString(g2, view.getName(), x + w / 2, y + h - bandH / 2 - h / 8, w - 8,
			new Font(Font.SANS_SERIF, Font.BOLD, Math.max(9, w / 9)), 8);
		if (view.getSubtitle() != null) {
			g2.setColor(new Color(200, 200, 200));
			drawFittedString(g2, view.getSubtitle(), x + w / 2, y + h - h / 16, w - 8,
				new Font(Font.SANS_SERIF, Font.PLAIN, Math.max(8, w / 12)), 7);
		}

		// The service badge shares the top band with the rarity label, so it is
		// measured FIRST and the label is then centred in the span the badge
		// leaves. Reserved on the LEFT only: mirroring the reservation to keep
		// the label centred on the card costs twice the width and chops
		// "LEGENDARY" to "LEGE…" on the 90px album thumbnail, which is the
		// surface this feature exists for.
		String service = view.getKillsServed() > 0 ? serviceText(view.getKillsServed()) : null;
		int badgeTextW = -1;
		int badgeBottom = y;
		if (service != null) {
			g2.setFont(serviceFont(w));
			badgeTextW = g2.getFontMetrics().stringWidth(service);
			badgeBottom = serviceBadgeY(y, h) + g2.getFontMetrics().getHeight();
		}
		int labelLeft = rarityLabelLeft(x, w, badgeTextW);
		int labelRight = x + w - 4;

		// rarity label
		int labelSize = Math.max(8, w / 11);
		g2.setColor(view.getRarity().getColor());
		g2.setFont(new Font(Font.SANS_SERIF, Font.BOLD, labelSize));
		drawCenteredString(g2, view.getRarity().getDisplayName().toUpperCase(),
			(labelLeft + labelRight) / 2, y + h / 14 + 4, labelRight - labelLeft);

		// variant effects
		if (view.getVariant() == Variant.SHINY)
			drawShiny(g2, shape, x, y, w, h, timeMs);
		else if (view.getVariant() == Variant.HOLOGRAM) {
			drawHologram(g2, shape, x, y, w, h, timeMs);
		}
		else if (view.getRarity().atLeast(Rarity.EPIC)) {
			drawSheen(g2, shape, x, y, w, h, timeMs, 3000, new Color(255, 255, 255, 40));
		}

		// after the variant effects so the number is not lost under scanlines;
		// the border block below re-sets both colour and stroke, so nothing leaks
		if (service != null)
			drawServiceBadge(g2, x, y, w, h, service);

		// Second pass: creases and scratches. Drawn BEFORE the border so the
		// rarity frame always paints on top of them, and allowed to run edge to
		// edge straight ACROSS the art — a card creases through the picture, and
		// confining the fold to the margins is what made this read as scribble
		// rather than as damage. What it may never cover is TEXT: the service
		// pill, the rarity label and the name band. A segment that would cross one
		// is dropped, which leaves a clean gap, as if the band were a label stuck
		// on the card and the crease ran underneath it.
		int topBandBottom = Math.max(badgeBottom, y + h / 14 + 4 + labelSize);
		int nameBandTop = y + h - bandH - h / 8;
		if (wear != CardWear.NONE) {
			drawWearLines(g2, shape, w, wear, wearSegments(x, y, w, h, wear,
				seed, wearProtect(x, y, w, h, topBandBottom, nameBandTop)));
		}

		// border (variant-tinted)
		Color border = view.getVariant() == Variant.SHINY
			? prismaticColor(timeMs, 0)
			: view.getVariant() == Variant.HOLOGRAM
			? new Color(120, 220, 255)
			: view.getRarity().getColor();
		g2.setColor(border);
		g2.setStroke(new BasicStroke(view.getRarity().atLeast(Rarity.RARE) ? 2.5f : 1.6f));
		g2.draw(shape);

		// Third pass: the chewed edge, and the only thing drawn AFTER the border —
		// that is the whole point of it. A worn card's frame is interrupted where
		// the gilt has flaked off, so the nicks have to bite the border itself
		// rather than sit politely inside it.
		if (wear != CardWear.NONE)
			drawWearEdge(g2, shape, x, y, w, h, wear, seed);

		g2.dispose();
	}

	/** Rarity-colored glow behind a card (charge-up etc.); intensity 0..1. */
	public static void drawGlow(Graphics2D g, int x, int y, int w, int h, Color color, float intensity) {
		if (intensity <= 0)
			return;
		Graphics2D g2 = layer(g, null);
		int layers = 12;
		for (int i = layers; i >= 1; i--) {
			float t = (float) i / layers;
			int alpha = (int) (intensity * 90 * (1 - t) * (1 - t));
			if (alpha <= 0)
				continue;
			// alpha() clamps to 0..255, which subsumes the Math.min this used to do
			g2.setColor(alpha(color, alpha));
			int pad = (int) (t * Math.min(w, h) * 0.28f);
			g2.fill(new RoundRectangle2D.Float(x - pad, y - pad, w + pad * 2, h + pad * 2,
				w / 6f + pad, w / 6f + pad));
		}
		g2.dispose();
	}

	// --- effect internals ---

	private static void drawShiny(Graphics2D g2, Shape clip, int x, int y, int w, int h, long timeMs) {
		Graphics2D gs = layer(g2, clip);
		// two counter-drifting prismatic bands, swept diagonally
		gs.rotate(Math.toRadians(-25), x + w / 2.0, y + h / 2.0);
		for (int band = 0; band < 2; band++) {
			float phase = ((timeMs + band * 900) % 2600) / 2600f;
			int bx = x - w - h / 2 + (int) (phase * (w * 3 + h));
			Color c = prismaticColor(timeMs, band * 120);
			gs.setPaint(new GradientPaint(bx, y, alpha(c, 0), bx + w / 2f, y + h, alpha(c, 70)));
			gs.fillRect(bx, y - h / 2, w / 2, h * 2);
		}
		gs.rotate(Math.toRadians(25), x + w / 2.0, y + h / 2.0);
		// deterministic sparkles
		for (int i = 0; i < 7; i++) {
			float u = Paint.hash01(i * 733 + 1);
			float v = Paint.hash01(i * 733 + 2);
			float twinkle = (float) (0.5 + 0.5 * Math.sin(timeMs / 260.0 + i * 1.7));
			int alpha = (int) (200 * twinkle);
			gs.setColor(new Color(255, 255, 255, alpha));
			int sx = x + (int) (u * (w - 8)) + 4;
			int sy = y + (int) (v * (h - 8)) + 4;
			int size = 2 + (i % 2);
			gs.drawLine(sx - size, sy, sx + size, sy);
			gs.drawLine(sx, sy - size, sx, sy + size);
		}
		gs.dispose();
	}

	private static void drawHologram(Graphics2D g2, Shape clip, int x, int y, int w, int h, long timeMs) {
		Graphics2D gs = layer(g2, clip);
		// cyan wash
		gs.setColor(new Color(90, 200, 255, 26));
		gs.fillRect(x, y, w, h);
		// scanlines drifting downward
		int offset = (int) ((timeMs / 90) % 6);
		gs.setColor(new Color(140, 230, 255, 34));
		for (int sy = y + offset; sy < y + h; sy += 6) {
			gs.drawLine(x, sy, x + w, sy);
		}
		// chromatic ghost edges
		Composite old = gs.getComposite();
		gs.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, 0.30f));
		gs.setColor(new Color(255, 80, 160));
		gs.drawRoundRect(x - 1, y, w, h, w / 7, w / 7);
		gs.setColor(new Color(80, 255, 220));
		gs.drawRoundRect(x + 1, y, w, h, w / 7, w / 7);
		gs.setComposite(old);
		// occasional flicker band
		float flicker = (timeMs % 2400) / 2400f;
		if (flicker > 0.9f) {
			int fy = y + (int) ((flicker - 0.9f) * 10 * h);
			gs.setColor(new Color(200, 245, 255, 60));
			gs.fillRect(x, fy, w, 4);
		}
		gs.dispose();
	}

	private static void drawSheen(Graphics2D g2, Shape clip, int x, int y, int w, int h,
		long timeMs, int periodMs, Color color) {
		// diagonal sweep: band travels corner-to-corner, tilted ~25 degrees
		Graphics2D gs = layer(g2, clip);
		gs.rotate(Math.toRadians(-25), x + w / 2.0, y + h / 2.0);
		float phase = (timeMs % periodMs) / (float) periodMs;
		int travel = w * 3 + h;
		int sx = x - w - h / 2 + (int) (phase * travel);
		gs.setPaint(new GradientPaint(sx, y, new Color(255, 255, 255, 0),
			sx + w / 3f, y, color, true));
		gs.fillRect(sx, y - h / 2, w / 3, h * 2);
		gs.dispose();
	}

	// --- cosmetic wear (Cracked Cards) ---
	//
	// Modelled on what a played trading card actually looks like, in the order a
	// grader would list it. Edge whitening first — the print layer wears through
	// at the rim and the pale stock core shows, worst at the corners, and it is
	// the single most recognisable "this card has been handled" cue there is. Then
	// creases: a card bends along a LINE, so a crease is near-straight and reads as
	// a shadow with a lit ridge beside it. Then surface scratches from sleeving
	// and shuffling, then general patina.
	//
	// Deliberately none of it is gold. An earlier pass drew kintsugi repair veins,
	// which is a nice idea and looks nothing like a worn card.
	//
	// Every card wears differently; every card in a bracket wears the same AMOUNT.
	// The counts and opacities below are functions of the stage alone, and the
	// per-card seed only ever picks where a crease enters, which way the scratches
	// lean, and where the fringe thins. So a SHATTERED card always reads as
	// SHATTERED at a glance — the weight of the damage is the stage — and no two
	// cards in the album carry it in the same places.

	/** Crease width. Scales with the card so a 90px thumb and a 150px reveal read alike. */
	static float wearStroke(int w) {
		return Math.max(1.6f, w / 55f);
	}

	/**
	 * How far the ink actually reaches from a line's centre line. The crease
	 * shadow is the widest of the passes and is drawn centred, so this is half its
	 * width — drawWearLines strokes with exactly (2 * this), which is what lets a
	 * test assert the painted footprint against the same number the renderer uses
	 * instead of against a copy of it that can drift.
	 */
	static float wearInkReach(int w) {
		return wearStroke(w) * 1.35f;
	}

	/**
	 * Everything the stage decides, as one table: five parallel switch statements
	 * over the same four-constant enum were 900-odd characters of case labels for
	 * twenty numbers, and reading a stage across them meant reading five methods.
	 * One row per {@link CardWear}, indexed by ordinal, so a row IS the recipe for
	 * a stage and the progression down a column is visible at a glance.
	 *
	 * <p>Rows are in enum declaration order: NONE, HAIRLINE, CRACKED, SHATTERED.
	 * NONE is ordinal 0 and its row is all zeroes, which is exactly what every
	 * switch's {@code default:} arm returned. Columns are the five accessors
	 * below, in this order:
	 *
	 * <pre>
	 *   creases  scratches  lineAlpha  grimeAlpha  edgeNicks
	 * </pre>
	 *
	 * <p>The one honest difference from the switches: a fifth constant added to
	 * CardWear would throw here where a switch would have quietly returned the
	 * default. WearTuningTest pins the row order and the row count against the
	 * enum, so that shows up as a red test rather than as a crash in a reveal.
	 */
	private static final int[][] WEAR_TUNING = {
		{0, 0, 0, 0, 0},
		{0, 6, 96, 34, 20},
		{1, 10, 150, 62, 38},
		{2, 16, 200, 92, 60}
	};

	/**
	 * Creases. A crease is the heaviest single thing that can happen to a card
	 * short of a tear, so these numbers are small on purpose: none at all on a
	 * lightly played card, one on a worn one, two on a wreck.
	 */
	static int creaseCount(CardWear wear) {
		return WEAR_TUNING[wear.ordinal()][0];
	}

	/**
	 * Surface scratches from sleeving and shuffling. Unlike creases these start
	 * immediately — a card with a hundred kills of service has been in and out of
	 * a loadout a hundred times, and fine scuffing is the first thing that shows.
	 */
	static int scratchCount(CardWear wear) {
		return WEAR_TUNING[wear.ordinal()][1];
	}

	/** Line opacity for creases and scratches. Strictly increasing, never opaque. */
	static int wearAlpha(CardWear wear) {
		return WEAR_TUNING[wear.ordinal()][2];
	}

	/**
	 * Handling-dirt opacity at the rim, where the vignette is darkest. Kept well
	 * under the line work: patina is the layer you notice last.
	 */
	static int grimeAlpha(CardWear wear) {
		return WEAR_TUNING[wear.ordinal()][3];
	}

	/**
	 * Patches of worn print along the border. High counts on purpose — edge
	 * whitening is a continuous frayed fringe, not a handful of chips, and the
	 * only way to get a fringe out of discrete marks is to use enough of them
	 * that they overlap.
	 */
	static int edgeNicks(CardWear wear) {
		return WEAR_TUNING[wear.ordinal()][4];
	}

	/**
	 * The two regions a line may never touch, and they are both TEXT: the top
	 * band (service pill plus rarity label) and the name band plus the subtitle
	 * strip under it. The art is pointedly NOT protected — a card creases
	 * through the picture, and keeping the fold out of the picture is exactly
	 * what made the old routing read as margin scribble.
	 *
	 * <p>Callers pass the band edges they themselves drew with, so this cannot
	 * drift out of step with drawFace the way a re-derived copy would.
	 */
	static Rectangle[] wearProtect(int x, int y, int w, int h, int topBandBottom,
		int nameBandTop) {
		return new Rectangle[]{
			new Rectangle(x, y, w, Math.max(1, topBandBottom - y)),
			new Rectangle(x, nameBandTop, w, Math.max(1, y + h - nameBandTop))
		};
	}

	/**
	 * The clear vertical window between the two text bands, as {lo, hi}. Derived
	 * from the protected rects the caller already built rather than from a second
	 * copy of drawFace's band arithmetic, so the two cannot disagree.
	 *
	 * <p>A rect touching the top of the card pushes {@code lo} down past it;
	 * anything else pulls {@code hi} up above it. That is exactly the shape of
	 * {@link #wearProtect} and does not care what order it returns them in.
	 * Degenerate input collapses to the whole card, and the per-segment
	 * {@link #blocked} check still keeps the guarantee — it just means a card
	 * whose bands eat the entire face draws no seams at all rather than seams in
	 * the wrong place.
	 */
	static int[] wearOpenBand(Rectangle[] protect, int y, int h) {
		int lo = y;
		int hi = y + h;
		if (protect != null) {
			for (Rectangle r : protect) {
				if (r == null)
					continue;
				if (r.y <= lo)
					lo = Math.max(lo, r.y + r.height);
				else {
					hi = Math.min(hi, r.y);
				}
			}
		}
		return hi - lo < 4 ? new int[]{y, y + h} : new int[]{lo, hi};
	}

	/**
	 * A point on the card's perimeter. {@code edge} is 0=top, 1=right, 2=bottom,
	 * 3=left and {@code t} in 0..1 slides along it, squeezed into the middle 70%
	 * so a seam never starts in a rounded corner where the clip would eat it.
	 *
	 * <p>The left and right edges slide along {@code band} — the clear strip
	 * between the two text bands — rather than the card's full height. A seam
	 * entering at the same height as the name band would be dropped in its
	 * entirety by the text check and paint nothing; entering through the open
	 * middle, it always crosses the face. Top and bottom entries deliberately do
	 * NOT get this treatment: losing their first few segments under the rarity
	 * label is the look, a break running beneath a stuck-on label.
	 *
	 * <p>Inset by {@code pad} rather than sitting exactly on the boundary: the
	 * seam is stroked round-capped, so an endpoint on the line would put half the
	 * relief outside the card, where the clip flattens it into a blunt stub
	 * instead of letting it taper into the frame.
	 */
	static double[] wearEdgePoint(int x, int y, int w, int h, int[] band, int edge, float t,
		float pad) {
		double u = 0.15 + 0.70 * t;
		double v = band[0] + u * (band[1] - band[0]);
		switch (edge & 3) {
			case 0:
				return new double[]{x + u * w, y + pad};
			case 1:
				return new double[]{x + w - pad, v};
			case 2:
				return new double[]{x + u * w, y + h - pad};
			default:
				return new double[]{x + pad, v};
		}
	}

	/**
	 * One seam as a polyline of {@link #WEAR_STEPS}+1 points, running from a to b
	 * with seeded jitter perpendicular to that line.
	 *
	 * <p>The offset is a MEANDER, not a random walk: two slow sine waves at a
	 * seeded frequency and phase, with a little grit on top. Sampling an
	 * independent random number per step is what draws a sawtooth, and a sawtooth
	 * is precisely the "horrible ascii" this rewrite exists to delete. A real
	 * break drifts, then turns; it does not alternate.
	 *
	 * <p>The whole offset is then tapered by {@code sin(pi*t)}, which is zero at
	 * both ends. That is the second half of the trick: the seam wanders freely
	 * across the middle of the card but arrives at each edge exactly where it was
	 * aimed, so it meets the frame cleanly instead of stopping in mid-air.
	 */
	static double[][] wearSeamPath(double ax, double ay, double bx, double by, int seed,
		double amp) {
		double dx = bx - ax;
		double dy = by - ay;
		double len = Math.hypot(dx, dy);
		double nx = len < 1e-6 ? 0 : -dy / len;
		double ny = len < 1e-6 ? 0 : dx / len;
		// one full lobe at the low end, so even the calmest seam bows rather than
		// running straight; the fast wave rides on it as a second, smaller kink
		double slow = 1.0 + Paint.hash01(seed + 1) * 1.4;
		double fast = 2.6 + Paint.hash01(seed + 2) * 2.4;
		double slowPhase = Paint.hash01(seed + 3) * Math.PI * 2;
		double fastPhase = Paint.hash01(seed + 4) * Math.PI * 2;
		double lean = Paint.hash01(seed + 5) < 0.5 ? -1 : 1;
		double[][] pts = new double[WEAR_STEPS + 1][2];
		for (int s = 0; s <= WEAR_STEPS; s++) {
			double t = (double) s / WEAR_STEPS;
			double wave = 0.66 * Math.sin(slow * Math.PI * t + slowPhase)
				+ 0.34 * Math.sin(fast * Math.PI * t + fastPhase);
			// grit is a fifth of the wave at most: enough to roughen the line,
			// never enough to become the line
			double grit = (Paint.hash01(seed + s * 31 + 7) - 0.5) * 0.22;
			double offset = lean * amp * Math.sin(Math.PI * t) * (wave + grit);
			pts[s][0] = ax + dx * t + nx * offset;
			pts[s][1] = ay + dy * t + ny * offset;
		}
		return pts;
	}

	/**
	 * Every line segment to be drawn, as {x1,y1,x2,y2,kind} with kind either
	 * {@link #KIND_CREASE} or {@link #KIND_SCRATCH}. Both kinds share one list so
	 * the text-clearance and stays-inside guarantees are proved once.
	 *
	 * <p>A CREASE is a fold, and a folded card creases from edge to edge in
	 * essentially a straight line — the amplitude here is a third of what a
	 * cracked-glass effect would use, because a crease that wanders is a tear.
	 * A SCRATCH is shorter, sits anywhere on the face, and leans with the rest of
	 * its card: cards get scuffed by sliding in and out of the same sleeve the
	 * same way, so a seeded dominant angle with a little spread per scratch reads
	 * as handling, where independent angles read as confetti.
	 *
	 * <p>Every card wears differently and every card in a bracket wears the same
	 * AMOUNT. The counts and opacities come only from {@code wear}; the seed only
	 * ever chooses where things land and which way they lean. That split is the
	 * whole contract: the stage is legible at a glance because two SHATTERED
	 * cards carry the same weight of damage, and the album does not look
	 * stamped because no two carry it in the same places.
	 *
	 * <p>Segments that would cross protected text are dropped rather than
	 * rerouted. Dropping leaves a gap in a line that carries on afterwards, which
	 * reads correctly — the name band is a printed label and the crease runs
	 * under it. Rerouting would bend the line around the band and put back the
	 * kink this rewrite exists to remove.
	 *
	 * <p>The first crease of every card is forced left-to-right. Top and bottom
	 * entries lose their first or last few segments to the two text bands, so
	 * without this a one-crease card could roll a top-to-bottom fold and show
	 * almost nothing; a horizontal crease always crosses the open middle.
	 *
	 * <p>Pure and deterministic in the seed, which is what lets a test prove the
	 * never-obscure guarantee by sweeping sizes and seeds rather than by eye.
	 */
	static List<int[]> wearSegments(int x, int y, int w, int h, CardWear wear,
		int seed, Rectangle[] protect) {
		List<int[]> out = new ArrayList<>();
		if (wear == null || w <= 0 || h <= 0)
			return out;
		float pad = wearInkReach(w);
		int[] band = wearOpenBand(protect, y, h);

		double creaseAmp = Math.min(w, h) * 0.035;
		for (int k = 0; k < creaseCount(wear); k++) {
			int cs = seed + k * 977;
			int entry;
			int exit;
			if (k == 0) {
				entry = 3;
				exit = 1;
			}
			else {
				entry = (int) (Paint.hash01(cs + 1) * 4) & 3;
				// +1.. so the exit can never land back on the entry edge, which
				// would give a fold that leaves and returns through the same side
				exit = (entry + 1 + (int) (Paint.hash01(cs + 2) * 3)) & 3;
			}
			double[] a = wearEdgePoint(x, y, w, h, band, entry, Paint.hash01(cs + 3), pad);
			double[] b = wearEdgePoint(x, y, w, h, band, exit, Paint.hash01(cs + 4), pad);
			emitSeam(out, clampPath(wearSeamPath(a[0], a[1], b[0], b[1], cs + 5, creaseAmp),
				x, y, w, h, pad), pad, protect, KIND_CREASE);
		}

		// one shuffle direction per card, shared by all of its scratches
		double lean = Paint.hash01(seed + 61) * Math.PI;
		for (int k = 0; k < scratchCount(wear); k++) {
			int ss = seed + 4099 + k * 613;
			double angle = lean + (Paint.hash01(ss + 1) - 0.5) * 0.7;
			// SQUARED, so most scratches are short and the occasional one is long.
			// A uniform draw gave every card several near-full-length lines, and
			// half a dozen long strokes at matched angles reads as straw laid on
			// the card rather than as a surface that has been rubbed.
			double r = Paint.hash01(ss + 2);
			double half = Math.min(w, h) * (0.07 + 0.30 * r * r) / 2;
			// How far the drawn scratch actually reaches from its centre on each
			// axis. WANDER covers the meander wearSeamPath adds perpendicular to
			// the line — small, but it is what a plain sin/cos bound misses, and
			// missing it puts the tip of a scratch under the name band.
			double rise = Math.abs(Math.sin(angle)) + WANDER;
			double run = Math.abs(Math.cos(angle)) + WANDER;
			// Length is chosen first and the centre is then placed only where the
			// whole scratch fits between the two text bands. Not for safety — the
			// per-segment check would drop any overhang anyway — but so the AMOUNT
			// of scuffing is the same for every card in the bracket. A scratch
			// half-eaten by the name band is a scratch this card silently did not
			// get, and the stage would stop reading at a glance.
			double roomY = (band[1] - band[0]) / 2.0 - pad;
			if (half * rise > roomY) {
				// an open band shorter than the scratch: shorten the scratch, since
				// the alternative is to draw it somewhere it will be thrown away
				half = Math.max(1, roomY / rise);
			}
			double loY = band[0] + pad + half * rise;
			double hiY = band[1] - pad - half * rise;
			double cy = loY + Paint.hash01(ss + 4) * Math.max(0, hiY - loY);
			double loX = x + pad + half * run;
			double hiX = x + w - pad - half * run;
			double cx = loX <= hiX
				? loX + Paint.hash01(ss + 3) * (hiX - loX)
				: x + w / 2.0;
			double hx = Math.cos(angle) * half;
			double hy = Math.sin(angle) * half;
			// barely any wander: a scratch is a straight drag, and the curve is
			// only here so it does not look ruled with a straightedge
			emitSeam(out, clampPath(wearSeamPath(cx - hx, cy - hy, cx + hx, cy + hy,
				ss + 5, half * SCRATCH_BEND), x, y, w, h, pad), pad, protect, KIND_SCRATCH);
		}
		return out;
	}

	/**
	 * Pull every point of a seam back inside the card by the ink reach. The
	 * tapered jitter already lands both ENDS exactly where they were aimed, but
	 * the bulge in the middle of a steep seam can swing past a side on a narrow
	 * card. Clamping per point keeps the polyline connected, and it means "wear
	 * never paints outside the card" is arithmetic rather than a job the
	 * rounded-rect clip is quietly doing for us.
	 *
	 * <p>The bounds are rounded OUTWARD to whole pixels — ceil the low edge, floor
	 * the high one — because emitSeam rounds each point to an int afterwards.
	 * Clamping at x+2.4 and then rounding 10.4 down to 10 would put the ink back
	 * over the edge by half a pixel; clamping at 11 cannot, since rounding never
	 * moves a value below its own floor.
	 */
	private static double[][] clampPath(double[][] path, int x, int y, int w, int h, float pad) {
		double loX = Math.ceil(x + pad);
		double hiX = Math.floor(x + w - pad);
		double loY = Math.ceil(y + pad);
		double hiY = Math.floor(y + h - pad);
		if (loX > hiX || loY > hiY) {
			// a card too small to hold even one padded pixel; nothing legal to draw
			return path;
		}
		for (double[] p : path) {
			p[0] = Math.max(loX, Math.min(hiX, p[0]));
			p[1] = Math.max(loY, Math.min(hiY, p[1]));
		}
		return path;
	}

	/**
	 * Round a polyline to integer segments, dropping any that would cross text.
	 *
	 * <p>Rounded FIRST, then tested. Testing the unrounded point and storing the
	 * rounded one lets the rounding move the ink up to half a pixel toward the
	 * band after the check has already passed, which is exactly enough to put the
	 * relief over the top of the rarity label on a small card.
	 */
	private static void emitSeam(List<int[]> out, double[][] path, float pad,
		Rectangle[] protect, int kind) {
		for (int s = 1; s < path.length; s++) {
			int ax = (int) Math.round(path[s - 1][0]);
			int ay = (int) Math.round(path[s - 1][1]);
			int bx = (int) Math.round(path[s][0]);
			int by = (int) Math.round(path[s][1]);
			if (!blocked(protect, ax, ay, bx, by, pad)) {
				out.add(new int[]{ax, ay, bx, by, kind});
			}
		}
	}

	/** True when a stroked segment, padded, would touch anything protected. */
	static boolean blocked(Rectangle[] protect, double ax, double ay,
		double bx, double by, float pad) {
		if (protect == null)
			return false;
		int x0 = (int) Math.floor(Math.min(ax, bx) - pad);
		int y0 = (int) Math.floor(Math.min(ay, by) - pad);
		int x1 = (int) Math.ceil(Math.max(ax, bx) + pad);
		int y1 = (int) Math.ceil(Math.max(ay, by) + pad);
		Rectangle box = new Rectangle(x0, y0, Math.max(1, x1 - x0), Math.max(1, y1 - y0));
		for (Rectangle r : protect) {
			if (r != null && r.intersects(box))
				return true;
		}
		return false;
	}

	/**
	 * Handling dirt: a vignette that darkens toward the rim, plus a few soft
	 * blotches. The vignette is transparent at its centre, which is where the
	 * sprite sits, so the art dulls at its extremities and stays legible in the
	 * middle without anything having to know where the art actually is.
	 */
	private static void drawWearGrime(Graphics2D g2, Shape clip, int x, int y, int w, int h,
		CardWear wear, int seed) {
		int alpha = grimeAlpha(wear);
		if (alpha <= 0 || w <= 0 || h <= 0)
			return;
		Graphics2D gg = layer(g2, clip);
		// centred a little above the middle, on the sprite rather than on the
		// card, so the clear window sits where the thing worth seeing is
		gg.setPaint(new RadialGradientPaint(
			new Point2D.Float(x + w / 2f, y + h * 0.42f),
			Math.max(w, h) * 0.72f,
			new float[]{0f, 0.50f, 1f},
			new Color[]{
				alpha(WEAR_GRIME, 0),
				alpha(WEAR_GRIME, alpha / 3),
				alpha(WEAR_GRIME, alpha)
			}));
		gg.fill(clip);
		// blotches: flat ovals stacked concentrically rather than one gradient
		// each. drawFace runs every frame of a reveal, and a per-blotch
		// RadialGradientPaint costs more than the softness is worth at this size.
		//
		// Six thin rings, not three fat ones. The same total opacity spread over
		// twice as many steps costs nothing extra and is the difference between
		// a soiled patch and a visible grey disc — with three rings the outermost
		// step lands at a fifth of full grime in one jump, and the eye reads that
		// jump as an outline.
		int blotches = Math.max(1, edgeNicks(wear) / 4);
		int rings = 6;
		for (int i = 0; i < blotches; i++) {
			int bs = seed + i * 613;
			int d = (int) (Math.min(w, h) * (0.34f + 0.40f * Paint.hash01(bs + 3)));
			int bx = x + (int) (Paint.hash01(bs + 1) * w) - d / 2;
			int by = y + (int) (Paint.hash01(bs + 2) * h) - d / 2;
			gg.setColor(alpha(WEAR_GRIME, Math.max(1, alpha / (rings * 2))));
			for (int ring = rings; ring >= 1; ring--) {
				int rd = Math.max(1, d * ring / rings);
				gg.fillOval(bx + (d - rd) / 2, by + (d - rd) / 2, rd, rd);
			}
		}
		gg.dispose();
	}

	/**
	 * Creases and scratches. Full passes over every segment of a kind rather than
	 * a full stack per segment: with per-segment stacks the shadow of a later
	 * segment paints over the lit ridge of an earlier one wherever two lines
	 * cross, and a crossing is exactly where the relief matters most.
	 *
	 * <p>A crease is drawn as three things, in the order a fold actually presents
	 * itself: a broad soft valley, a dark line in the bottom of it, and a pale
	 * ridge along ONE side. The ridge is the whole trick. It is the colour of the
	 * card stock because a fold cracks the printed ink and shows the board
	 * underneath, and it is off-centre because relief is a direction — light from
	 * somewhere, shadow on the other side. Centre it and the crease flattens back
	 * into a drawn-on line.
	 *
	 * <p>A scratch gets none of that: one hairline, thin and faint, in the same
	 * stock colour. A scuff is a shallow gouge with no depth to shade.
	 *
	 * <p>Every pass is inside {@link #wearInkReach} of the stored segment — the
	 * broad valley by half its width, the ridge by its offset plus half of its
	 * own — which is what {@link #blocked} reserves, so the paint that lands and
	 * the clearance the tests assert cannot drift apart.
	 */
	private static void drawWearLines(Graphics2D g2, Shape clip, int w, CardWear wear,
		List<int[]> segments) {
		if (segments.isEmpty())
			return;
		Graphics2D gw = layer(g2, clip);
		float line = wearStroke(w);
		int alpha = wearAlpha(wear);
		// Each pass filters the one shared list by kind as it walks it, rather
		// than being handed a pre-split copy. Splitting first meant building two
		// throwaway ArrayLists on every frame of every card, and the filter is a
		// single int compare inside a loop the pass already runs. The z-order is
		// unchanged and is the whole point of passing rather than stacking: all
		// crease valleys, then the crease shadow ridge, then the crease stock
		// ridge, then the two scratch ridges.
		strokePass(gw, segments, KIND_CREASE, roundStroke(wearInkReach(w) * 2f),
			alpha(WEAR_SHADOW, alpha / 4));
		// the dark side and the lit side sit either side of the fold line, half
		// a stroke each way. Stacking both on the centre is what flattened the
		// earlier pass into a drawn-on line: relief is two tones meeting, and
		// they cannot meet if they are on top of each other.
		ridgePass(gw, segments, KIND_CREASE, roundStroke(line * 0.9f),
			alpha(WEAR_SHADOW, alpha), line * -0.5f);
		ridgePass(gw, segments, KIND_CREASE, roundStroke(line * 0.7f),
			alpha(WEAR_STOCK, alpha), line * 0.5f);
		// A scratch is a groove, so it gets the same two-tone treatment as a crease
		// at a tenth of the scale: a dark side and a lit side half a hairline
		// apart. Sub-pixel at these widths, which is exactly right — antialiasing
		// resolves it into a soft channel in the surface, where a single bright
		// line sat on top of the card like a drawn stick.
		float fine = Math.max(1f, line * 0.35f);
		ridgePass(gw, segments, KIND_SCRATCH, roundStroke(fine),
			alpha(WEAR_SHADOW, alpha * 2 / 5), line * -0.45f);
		ridgePass(gw, segments, KIND_SCRATCH, roundStroke(fine),
			alpha(WEAR_STOCK, alpha * 2 / 5), line * 0.45f);
		gw.dispose();
	}

	/**
	 * Every stroke in the wear passes is round-capped and round-joined — a worn
	 * mark has no square ends — so the cap/join pair was spelled out seven times.
	 * Each caller still gets its own instance; BasicStroke is immutable, so that
	 * is a formality rather than a requirement.
	 */
	private static BasicStroke roundStroke(float width) {
		return new BasicStroke(width, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND);
	}

	private static void strokePass(Graphics2D gw, List<int[]> segments, int kind,
		BasicStroke stroke, Color color) {
		gw.setStroke(stroke);
		gw.setColor(color);
		for (int[] seg : segments) {
			if (seg[4] == kind)
				gw.drawLine(seg[0], seg[1], seg[2], seg[3]);
		}
	}

	/**
	 * A pass over every segment of {@code kind}, shifted {@code off} pixels
	 * perpendicular to each. The normal comes from the segment's own direction,
	 * and the polyline is walked in a consistent order, so the shift stays on one
	 * side for the whole length of a crease instead of flipping about and
	 * crosshatching it.
	 *
	 * <p>Drawn through {@link Line2D.Double} rather than the int-coordinate
	 * drawLine. Rounding the shifted endpoint could push it a further half pixel
	 * out, and {@code off} plus half this stroke is already exactly
	 * {@link #wearInkReach} — the budget the text-clearance check reserves. There
	 * is no half pixel spare, so nothing may round.
	 */
	private static void ridgePass(Graphics2D gw, List<int[]> segments, int kind,
		BasicStroke stroke, Color color, float off) {
		gw.setStroke(stroke);
		gw.setColor(color);
		for (int[] seg : segments) {
			double dx = seg[2] - seg[0];
			double dy = seg[3] - seg[1];
			double len = Math.hypot(dx, dy);
			// the wrong kind and a zero-length segment are both "not this pass's
			// business", so they share the one skip
			if (seg[4] != kind || len < 1e-6)
				continue;
			double nx = -dy / len * off;
			double ny = dx / len * off;
			gw.draw(new Line2D.Double(seg[0] + nx, seg[1] + ny, seg[2] + nx, seg[3] + ny));
		}
	}

	/**
	 * Edge whitening — the single most recognisable thing about a played card,
	 * and the reason this pass runs AFTER the border instead of before it.
	 *
	 * <p>The rim of a card is where the ink goes first: it is what rubs on every
	 * other card in the deck, every sleeve, every box wall. What shows through is
	 * the pale core of the board, so the marks here are drawn in
	 * {@link #WEAR_STOCK} and they eat the gilt frame. An earlier pass drew dark
	 * bites instead, which is the mental image of "damage" but the opposite of
	 * what a worn card does — the edge gets LIGHTER, not darker.
	 *
	 * <p>Each mark is a dash lying ALONG the edge, not a dot on it. Dots read as
	 * punched holes; overlapping tangential dashes of varying length and
	 * thickness read as a continuous frayed fringe, which is why the counts in
	 * {@link #edgeNicks} are so high. Two strokes per dash — a wide faint one and
	 * a narrow bright one on the same line — feather it, so no mark has a hard
	 * edge of its own.
	 *
	 * <p>Corners are worst, because a corner takes the whole force of a drop on
	 * one point. Rather than a separate corner routine, every mark's length,
	 * thickness and opacity scale by how close it is to a corner, and each corner
	 * additionally gets a soft pale bloom centred exactly on its point — the clip
	 * keeps only the quarter of that bloom inside the card, which is precisely
	 * the shape of a rubbed-round corner.
	 *
	 * <p>Clipped to the card throughout. Marks straddle the boundary on purpose,
	 * so without the clip a card drawn next to another would fray its neighbour.
	 */
	private static void drawWearEdge(Graphics2D g2, Shape clip, int x, int y, int w, int h,
		CardWear wear, int seed) {
		int marks = edgeNicks(wear);
		if (marks == 0 || w <= 0 || h <= 0)
			return;
		Graphics2D ge = layer(g2, clip);
		int alpha = wearAlpha(wear);
		double perimeter = 2.0 * (w + h);
		// deliberately thin. An earlier pass used w/44 and the marks were so fat
		// they merged into an inner glow — a lit border, which is the opposite
		// read. The fringe has to be finer than the frame it is eating.
		float base = Math.max(1f, w / 70f);
		double cornerSpan = Math.min(w, h) * 0.30;
		for (int i = 0; i < marks; i++) {
			int ns = seed + i * 401;
			// walked round the perimeter in even steps with a jittered offset, so
			// the fringe spreads over all four sides instead of clumping on one
			double at = ((i + Paint.hash01(ns + 1) * 0.85) / marks) * perimeter;
			double px;
			double py;
			double tx;
			double ty;
			if (at < w) {
				px = x + at;
				py = y;
				tx = 1;
				ty = 0;
			}
			else if (at < w + h) {
				px = x + w;
				py = y + (at - w);
				tx = 0;
				ty = 1;
			}
			else if (at < 2 * w + h) {
				px = x + w - (at - w - h);
				py = y + h;
				tx = -1;
				ty = 0;
			}
			else {
				px = x;
				py = y + h - (at - 2 * w - h);
				tx = 0;
				ty = -1;
			}
			// The inward normal is the tangent turned a quarter turn, on every one
			// of the four sides — top (1,0) gives (0,1), right (0,1) gives (-1,0),
			// bottom (-1,0) gives (0,-1), left (0,-1) gives (1,0). It was written
			// out per branch, which is four more chances for a side to disagree
			// with its own tangent, and the walk goes clockwise for all four.
			double inx = -ty;
			double iny = tx;
			double corner = Math.min(Math.min(at, Math.abs(at - w)),
				Math.min(Math.abs(at - (w + h)),
					Math.min(Math.abs(at - (2 * w + h)), perimeter - at)));
			double boost = 1.0 + 1.6 * Math.max(0, 1 - corner / cornerSpan);
			float th = (float) (base * (0.55 + 0.65 * Paint.hash01(ns + 3)) * Math.min(1.5, boost));
			int a = (int) (alpha * (0.6 + 0.4 * Paint.hash01(ns + 5)));
			// Roughly a third of the fringe bites INWARD across the rim instead of
			// lying along it. A rim of pure tangential dashes reads as a drawn
			// outline however ragged the lengths are; the perpendicular ones are
			// what break the frame into teeth, and teeth are what a shelf-worn
			// edge actually has.
			boolean bite = Paint.hash01(ns + 6) < 0.34;
			double len;
			double dx;
			double dy;
			double depth;
			if (bite) {
				len = base * (1.6 + 3.4 * Paint.hash01(ns + 2)) * boost;
				dx = inx;
				dy = iny;
				// anchored just outside the rim so the bite starts in the frame and
				// runs in, rather than floating in the middle of the border
				depth = -base * 0.5;
			}
			else {
				len = base * (2.0 + 5.5 * Paint.hash01(ns + 2)) * boost;
				dx = tx;
				dy = ty;
				// a little in or a little out: the ones sitting proud of the rim get
				// halved by the clip, which is what stops the band looking ruled
				depth = base * (Paint.hash01(ns + 4) * 0.9 - 0.3);
			}
			// How far back along its own direction the mark starts. A tangential
			// dash is centred on its anchor, so it steps back half its length; a
			// bite STARTS at the rim and runs inward, so it steps back none. The
			// old spelling subtracted the half-length and then added it straight
			// back for bites, which is the same thing said twice.
			double back = bite ? 0 : len / 2;
			double ax = px + inx * depth - dx * back;
			double ay = py + iny * depth - dy * back;
			double bx = ax + dx * len;
			double by = ay + dy * len;
			// one line, drawn twice: a wide faint stroke feathered under a narrow
			// bright one, so no mark has a hard edge of its own. Graphics2D.draw
			// does not mutate the shape it is handed, so the two passes can share
			// the instance instead of allocating a second identical Line2D.
			Line2D mark = new Line2D.Double(ax, ay, bx, by);
			ge.setStroke(roundStroke(th * 1.9f));
			ge.setColor(alpha(WEAR_STOCK, a / 4));
			ge.draw(mark);
			ge.setStroke(roundStroke(th));
			ge.setColor(alpha(WEAR_STOCK, a));
			ge.draw(mark);
		}
		// The corner blooms, feathered outward-in so they have no rim of their own.
		// Kept small and faint: this is the last touch, a corner gone soft, not a
		// light source. Scaled by the stage through the mark count so a HAIRLINE
		// card gets a hint of it and a SHATTERED one gets a rounded-off corner.
		int d = Math.max(3, (int) (w * (0.035f + 0.045f * marks / 60f)));
		int steps = 5;
		for (int c = 0; c < 4; c++) {
			int cx = (c & 1) == 0 ? x : x + w;
			int cy = (c & 2) == 0 ? y : y + h;
			ge.setColor(alpha(WEAR_STOCK, Math.max(1, alpha / (steps * 6))));
			for (int s = steps; s >= 1; s--) {
				int rd = Math.max(2, d * s / steps);
				ge.fillOval(cx - rd / 2, cy - rd / 2, rd, rd);
			}
		}
		ge.dispose();
	}

	private static Color alpha(Color base, int a) {
		return new Color(base.getRed(), base.getGreen(), base.getBlue(),
			Math.max(0, Math.min(255, a)));
	}

	public static Color prismaticColor(long timeMs, int offsetDeg) {
		float hue = ((timeMs / 22) % 360 + offsetDeg) % 360 / 360f;
		return Color.getHSBColor(hue, 0.65f, 1f);
	}


	private static Font serviceFont(int w) {
		return new Font(Font.SANS_SERIF, Font.BOLD, Math.max(8, w / 13));
	}

	/** Left edge of the service badge pill. */
	static int serviceBadgeX(int x, int w) {
		return x + Math.max(3, w / 22);
	}

	/**
	 * Top edge of the service badge pill. Extracted from drawServiceBadge rather
	 * than duplicated because the wear pass measures the protected top band from
	 * it — two copies of this expression would drift and let a crack cross the
	 * pill.
	 */
	static int serviceBadgeY(int y, int h) {
		return y + Math.max(3, h / 26);
	}

	/** Horizontal padding inside the pill, one side. */
	static int serviceBadgePadX(int w) {
		return Math.max(3, w / 24);
	}

	/** Full width of the pill for a badge whose text measured badgeTextWidth. */
	static int serviceBadgeWidth(int w, int badgeTextWidth) {
		return badgeTextWidth + serviceBadgePadX(w) * 2;
	}

	/**
	 * Leftmost x the centered rarity label may occupy. Pass badgeTextWidth &lt; 0
	 * for "no badge", which must return the plain inset so a card with no
	 * service record renders exactly as it did before this feature existed.
	 *
	 * <p>Derived from the SAME geometry drawServiceBadge draws with, so the
	 * clearance is guaranteed by construction rather than by measurement luck.
	 */
	static int rarityLabelLeft(int x, int w, int badgeTextWidth) {
		if (badgeTextWidth < 0)
			return x + 4;
		return serviceBadgeX(x, w) + serviceBadgeWidth(w, badgeTextWidth) + Math.max(4, w / 20);
	}

	/**
	 * Compact service count: the corner has room for four characters, not six.
	 * Integer math only — no locale, no rounding drift, and only ASCII digits,
	 * '.', 'k' and 'm' come out, so there is no missing-glyph hazard.
	 */
	static String serviceText(int killsServed) {
		if (killsServed < 1000)
			return Integer.toString(killsServed);
		if (killsServed < 10000)
			return killsServed / 1000 + "." + killsServed % 1000 / 100 + "k";
		if (killsServed < 1000000)
			return killsServed / 1000 + "k";
		return killsServed / 1000000 + "m";
	}

	/** Top-left pill: a worn brass service tag. */
	private static void drawServiceBadge(Graphics2D g2, int x, int y, int w, int h, String text) {
		g2.setFont(serviceFont(w));
		FontMetrics fm = g2.getFontMetrics();
		int padX = serviceBadgePadX(w);
		int bw = serviceBadgeWidth(w, fm.stringWidth(text));
		int bh = fm.getHeight();
		int bx = serviceBadgeX(x, w);
		int by = serviceBadgeY(y, h);
		g2.setColor(SERVICE_BG);
		g2.fillRoundRect(bx, by, bw, bh, bh, bh);
		g2.setColor(SERVICE_EDGE);
		g2.setStroke(new BasicStroke(1f));
		g2.drawRoundRect(bx, by, bw, bh, bh, bh);
		g2.setColor(SERVICE_TEXT);
		g2.drawString(text, bx + padX, by + fm.getAscent() - 1);
	}

	private static void drawCenteredString(Graphics2D g, String text, int cx, int cy, int maxWidth) {
		FontMetrics fm = g.getFontMetrics();
		String drawn = text;
		while (fm.stringWidth(drawn) > maxWidth && drawn.length() > 4) {
			drawn = drawn.substring(0, drawn.length() - 2);
		}
		if (!drawn.equals(text))
			drawn = drawn.substring(0, Math.max(1, drawn.length() - 1)) + "…";
		g.drawString(drawn, cx - fm.stringWidth(drawn) / 2, cy + fm.getAscent() / 2 - 1);
	}

	/**
	 * Draw centered, shrinking the font (down to minSize) until the whole
	 * text fits; only at the floor does it fall back to ellipsizing.
	 */
	private static void drawFittedString(Graphics2D g, String text, int cx, int cy, int maxWidth,
		Font baseFont, int minSize) {
		Font font = baseFont;
		g.setFont(font);
		while (g.getFontMetrics().stringWidth(text) > maxWidth && font.getSize() > minSize) {
			font = font.deriveFont((float) (font.getSize() - 1));
			g.setFont(font);
		}
		drawCenteredString(g, text, cx, cy, maxWidth);
	}

	/**
	 * The smallest subimage containing every non-transparent pixel. Item
	 * sprites pad their content unevenly; cropping first makes centering
	 * center the visible art, not the padding.
	 */
	private static BufferedImage cropToOpaqueBounds(BufferedImage image) {
		int minX = image.getWidth();
		int minY = image.getHeight();
		int maxX = -1;
		int maxY = -1;
		for (int py = 0; py < image.getHeight(); py++) {
			for (int px = 0; px < image.getWidth(); px++) {
				if ((image.getRGB(px, py) >>> 24) > 8) {
					minX = Math.min(minX, px);
					minY = Math.min(minY, py);
					maxX = Math.max(maxX, px);
					maxY = Math.max(maxY, py);
				}
			}
		}
		if (maxX < 0 || (minX == 0 && minY == 0
			&& maxX == image.getWidth() - 1 && maxY == image.getHeight() - 1)) {
			return image; // fully transparent or already tight
		}
		return image.getSubimage(minX, minY, maxX - minX + 1, maxY - minY + 1);
	}
}

package com.gachaman;

import com.gachaman.model.*;
import java.util.*;

/**
 * All economy/RNG constants in one place. Values are deliberate tuning
 * decisions, not config — the gamemode is meant to be consistent.
 */
public final class Tuning {
	private Tuning() {
	}

	/**
	 * An enum-keyed table built POSITIONALLY from {@code values()}: the Nth
	 * value belongs to the Nth constant, and a null value means that constant
	 * is deliberately absent from the table (a Rusty chest rolls no deeds).
	 *
	 * <p>Spelling every key out cost about twenty characters apiece, and the
	 * Plugin Hub's token budget is the binding constraint on this plugin — see
	 * CLAUDE.md. The declaration order IS the mapping. That is safe here and
	 * only here: these enums are closed sets the gamemode defines itself, and
	 * reordering one is already a save-breaking change (the persisted state
	 * stores their NAMES, so a reorder is invisible to Gson but would silently
	 * re-point every table below). Do not use this for anything whose order is
	 * outside this repo's control.
	 *
	 * <p>Too FEW values throws ArrayIndexOutOfBounds at class-init, which is the
	 * right moment and needs no hand-written check to say so. Too many is caught
	 * by TuningTableTest, which is free — tests are not counted.
	 */
	@SafeVarargs
	private static <K extends Enum<K>, V> Map<K, V> table(K[] keys, V... values) {
		Map<K, V> map = new EnumMap<>(keys[0].getDeclaringClass());
		for (int i = 0; i < values.length; i++) {
			if (values[i] != null)
				map.put(keys[i], values[i]);
		}
		return map;
	}

	// --- Task rewards (GC) ---
	/**
	 * Kill income is deliberately a trickle next to {@link #COMPLETION_GC}:
	 * kill COUNT already scales 20 -> 100 across the ladder, so a steep per-kill
	 * ladder on top of that compounds into the runaway this replaced. Finishing
	 * the contract is what pays.
	 */
	public static final Map<TaskDifficulty, Integer> PER_KILL_GC =
		table(TaskDifficulty.values(), 4, 8, 16, 28);

	/**
	 * Per-kill GC scales with the combat-level DIFFERENCE between the slain
	 * NPC and the player (diff = npcCb - playerCb):
	 *  - up to 5 levels below you: the flat 1x base
	 *  - your level or above: starts at 1.1x and accelerates with the gap
	 *  - far beneath you: decays toward a floor (farming trivial mobs pays dust)
	 */
	public static final double KILL_DIFF_FLOOR = 0.1;
	public static final int KILL_DIFF_GRACE = 5;          // levels below you still worth 1x
	public static final double KILL_DIFF_UNDER_RATE = 0.02;  // decay per level beyond grace
	public static final double KILL_DIFF_EQUAL_BONUS = 0.1;  // matching your level pays 1.1x
	/**
	 * Punching up scales by the RATIO npcCb/playerCb, not the absolute gap:
	 * +5 levels at cb 3 is a monster ~2.7x your level (huge payout), while
	 * +5 at cb 70 is a near-peer (small bonus). Growth is linear+quadratic in
	 * (ratio - 1), capped.
	 */
	public static final double KILL_RATIO_LINEAR = 1.5;
	public static final double KILL_RATIO_QUAD = 0.75;
	/**
	 * Was 5.0, then 2.5. A 5x ceiling on punching up was the other half of the
	 * runaway: against the retired low-level bonus it compounded to 12x on the
	 * base before the combo was even counted.
	 *
	 * <p>The drop from 2.5 is a literal no-op for every SOLO kill and always
	 * was — the clamp first bites at ratio 1.693, but a contract sizes its
	 * monster to at most INSANE's 1.35 fraction of the player's combat level,
	 * which tops out at 1.7169. The one live path to the clamp is a PARTY
	 * CARRY: the award reads the LOCAL player's combat level while a party
	 * contract sizes its monster to the party average, so a cb-30 member
	 * carried in a cb-90 party can fight ratio 4.0 and clamp. Left at 2.5 that
	 * path pays the weapon bonus on top of a 4x, on the account least able to
	 * have earned it. See KillDiffCapTest, which pins the no-op claim over
	 * every pair the generator can actually produce.
	 */
	public static final double KILL_DIFF_CAP = 1.75;

	/*
	 * There is deliberately no low-level compensation multiplier here any more.
	 * It paid up to +150% at combat 3 on the theory that low-level kills are
	 * slower — but the contract generator already caps monsters to a fraction
	 * of the player's combat level, so time-to-kill is roughly FLAT across the
	 * whole range (~90s at combat 12 against ~85s at combat 70: a low-level
	 * player kills a 25 HP monster slowly, a high-level one kills a 150 HP
	 * monster fast, and it comes out even). Paying 2.5x for a slowdown the
	 * content scaling already absorbs made the early game the richest part of
	 * the gamemode, which is backwards.
	 */

	/**
	 * Rhythm Combo: every five compliant on-task kills earn a stack, and each
	 * stack multiplies the contract's base per-kill GC by a further quarter —
	 * x1.25 at one stack up to x2.5 at six, so a maxed chain is 30 kills deep.
	 * How long a kill takes is deliberately not a condition; only going idle
	 * breaks the chain, so a slow tanky target still builds a full combo as
	 * long as the player keeps attacking.
	 *
	 * <p>Combat level does not enter into it. The bonus is a flat ladder so a
	 * player can read their own pip count and know exactly what the next kill
	 * pays, which a level-faded percentage could never tell them.
	 *
	 * <p>Every base in {@link #PER_KILL_GC} is a multiple of 4, so a quarter
	 * step always lands on a whole number of GC and the ladder needs no
	 * rounding of its own — EXCEPT when {@link #WEAPON_BONUS_MULT} is live,
	 * which is a deliberate, owner-chosen exception; see that constant.
	 */
	public static final int COMBO_IDLE_RESET_TICKS = 50;   // ~30 seconds
	public static final int COMBO_MAX_STACKS = 6;
	public static final int COMBO_KILLS_PER_STACK = 5;
	public static final double COMBO_STACK_STEP = 0.25;

	/** Kills a chain is worth holding on to; past this the ladder is capped. */
	public static final int COMBO_MAX_KILLS = COMBO_MAX_STACKS * COMBO_KILLS_PER_STACK;

	public static int comboStacks(int chainKills) {
		return Math.min(COMBO_MAX_STACKS, Math.max(0, chainKills) / COMBO_KILLS_PER_STACK);
	}

	public static double comboMultiplier(int stacks) {
		return 1.0 + COMBO_STACK_STEP * Math.max(0, Math.min(COMBO_MAX_STACKS, stacks));
	}

	/**
	 * The Preferred Weapon: the wheel names a weapon CATEGORY alongside the
	 * style, and a compliant kill landed with that category in hand pays this
	 * much more. Multiplicative on the whole per-kill award, deliberately —
	 * folded in additively it would be worth only +31% at the attainable
	 * ceiling, and a bonus the interface calls "1.5x" while the player measures
	 * +31% is a lie. The runaway argument that forced the combat-level bonus
	 * and the combo to ADD does not transfer: those two are the same kind of
	 * term scaling the same base for the same reason, while the weapon is a
	 * different axis — HOW you fight, not who you fight or how steadily — and
	 * it is self-limiting because the named category usually costs DPS.
	 *
	 * <p>Per-kill only, never on completion. The category is sampled at the
	 * killing blow (see StyleTracker's cached judgement), so the bonus is
	 * verifiable against the kill that earned it; a completion bonus would be
	 * decided by whatever happened to be equipped at the end and could be had
	 * by swapping in the preferred weapon for the final kill alone.
	 *
	 * <p>1.5 breaks the whole-GC ladder above, knowingly: it needs base x mult
	 * to stay a multiple of 4, and with the smallest base at 4 that admits only
	 * WHOLE multipliers — 1.25, 1.5 and 1.75 all go lumpy, and only 2.0 and 3.0
	 * do not. The owner chose 1.5 with that named. EASY at an even match
	 * therefore reads 6, 8, 9, 11, 12, 14, 15 up the combo ladder rather than
	 * stepping evenly, and WeaponBonusTest pins exactly that so it stays a
	 * decision rather than becoming a bug report. Any level gap at all already
	 * makes the total fractional, so this is visible only on an even match.
	 */
	public static final double WEAPON_BONUS_MULT = 1.5;

	public static double killCbMultiplier(int playerCb, int npcCb) {
		int diff = npcCb - playerCb;
		if (diff >= 0) {
			double over = (double) npcCb / Math.max(1, playerCb) - 1.0;
			double mult = 1.0 + KILL_DIFF_EQUAL_BONUS
				+ over * KILL_RATIO_LINEAR
				+ over * over * KILL_RATIO_QUAD;
			return Math.min(KILL_DIFF_CAP, mult);
		}
		if (diff >= -KILL_DIFF_GRACE)
			return 1.0;
		return Math.max(KILL_DIFF_FLOOR, 1.0 + (diff + KILL_DIFF_GRACE) * KILL_DIFF_UNDER_RATE);
	}

	public static final Map<TaskDifficulty, Integer> COMPLETION_GC =
		table(TaskDifficulty.values(), 400, 900, 1900, 3600);

	/**
	 * Milestone completions, in the shape Slayer points use: every Nth finished
	 * contract pays a multiple of its completion reward. HIGHEST matching tier
	 * wins — they do not stack, so the 100th contract pays x10 and not
	 * 1.5 + 2.5 + 5 + 10.
	 *
	 * <p>Descending so the scan takes the first match. Kept as a pair of arrays
	 * rather than a map because order IS the rule here.
	 *
	 * <p>Tuned for a ~30% lift on completion income averaged over 100
	 * contracts, not for the raw size of the peaks: across any 100 contracts
	 * 80 pay flat, 10 pay x1.5, 8 pay x2.5, and one each pay x5 and x10. The
	 * peaks are meant to be an event; the average is meant to stay modest, or
	 * the milestone ladder quietly becomes the economy.
	 */
	public static final int[] COMPLETION_MILESTONES = {250, 100, 50, 10, 5};
	public static final double[] COMPLETION_MILESTONE_MULT = {15.0, 10.0, 5.0, 2.5, 1.5};

	/**
	 * Reward multiple for the Nth completed contract, 1.0 when N is not a
	 * milestone. N is the count INCLUDING this completion, so the tenth
	 * contract a player ever finishes is the one that pays x2.5.
	 */
	public static double completionMilestoneMult(int taskNumber) {
		if (taskNumber <= 0)
			return 1.0;
		for (int i = 0; i < COMPLETION_MILESTONES.length; i++) {
			if (taskNumber % COMPLETION_MILESTONES[i] == 0)
				return COMPLETION_MILESTONE_MULT[i];
		}
		return 1.0;
	}

