	public static final int ANTE_MIN_PERCENT = 10;
	public static final int ANTE_MAX_PERCENT = 50;
	public static final int ANTE_MAX_GC = 5000;
	public static final int ANTE_MIN_PURSE_GC = 250;
	/**
