package com.gachaman.service;

import net.runelite.api.*;

/**
 * Tutorial Island exclusion: none of Gachaman's locks apply until the
 * tutorial is complete. Varp 281 tracks tutorial progress; 1000 = done.
 */
public final class TutorialGate {
	public static final int TUTORIAL_PROGRESS_VARP = 281;
	public static final int TUTORIAL_COMPLETE = 1000;

	private TutorialGate() {
	}

	public static boolean onTutorial(Client client) {
		try {
			return client.getVarpValue(TUTORIAL_PROGRESS_VARP) < TUTORIAL_COMPLETE;
		}
		catch (Exception e) {
			return false;
		}
	}
}

package com.gachaman.service;

import java.util.*;
import java.util.function.*;
import javax.annotation.*;
import javax.inject.*;
import lombok.*;
import lombok.extern.slf4j.*;

/**
 * Queue of ceremony/celebration requests emitted by game services and drained
 * by the overlay layer. Services never touch UI directly, so everything works
 * headless (requests fall back to chat lines when no renderer claims them).
 */
@Slf4j
@Singleton
public class CeremonyBus {
	public enum Type {
		CHEST_OPEN,      // payload: ChestOpenResult
		THEMED_CHEST,    // payload: ChestOpenResult (boss KC reward)
		STYLE_ROLL,      // payload: StyleRollResult
		TASK_OFFERS,     // payload: List<TaskOffer>
		TASK_COMPLETE,   // payload: TaskCompletionSummary
		DEED_CHOICE,     // payload: DeedGrant
		/**
		 * payload: {@link ConsignmentService.Offer} — the Consignment, and the
		 * only request on this bus that carries an OBLIGATION rather than a
		 * reward.
		 *
		 * <p>Everything else queued here is something the player has already
		 * been given: dropping a fanfare costs a banner, dropping a chest reveal
		 * still commits the cards. This one is a question with a deadline on it,
		 * and whoever claims it has promised {@code ConsignmentService} that
		 * exactly one of {@code accept} / {@code decline} / {@code abandon} will
		 * follow. Claiming it and then merely forgetting it leaves the style roll
		 * owed until the next login drain settles it.
		 *
		 * <p>Which is why this type must never be handed to a
		 * {@link FallbackHandler}: a chat line cannot answer a binding choice.
		 * Nothing registers a fallback today (see CeremonyBusDeclineTest), so an
		 * unclaimed offer parks in the queue and re-presents when the renderer
		 * frees up — which is exactly what has to happen, because a contract
		 * completion queues TASK_COMPLETE and often DEED_CHOICE ahead of it.
		 */
		CONSIGNMENT,
		FANFARE          // payload: Fanfare (generic icon+text celebration)
	}

	@Value
	public static class Request {
		Type type;
		Object payload;
	}

	@Value
	public static class Fanfare {
		public enum Size {
			SMALL, MEDIUM, LARGE
		}

		Size size;
		String title;
		String detail;
		@Nullable
		Integer iconItemId;
	}

	public interface Renderer {
		/** Return true when the request was claimed for animated presentation. */
		boolean present(Request request);
	}

	public interface FallbackHandler {
		/** Headless presentation (chat message) when no renderer claims it. */
		void presentFallback(Request request);
	}

	private final Deque<Request> queue = new ArrayDeque<>();
	private final List<Renderer> renderers = new ArrayList<>();
	/** Passive observers notified of every submit (audit/timeline). */
	private final List<Consumer<Request>> taps = new ArrayList<>();
	private FallbackHandler fallback;

	public synchronized void addTap(Consumer<Request> tap) {
		if (!taps.contains(tap))
			taps.add(tap);
	}

	public synchronized void removeTap(Consumer<Request> tap) {
		taps.remove(tap);
	}

	public synchronized void setFallback(FallbackHandler handler) {
		this.fallback = handler;
	}

	public synchronized void addRenderer(Renderer renderer) {
		renderers.add(renderer);
	}

	public synchronized void removeRenderer(Renderer renderer) {
		renderers.remove(renderer);
	}

	/** Drop everything still queued (plugin shutdown — renderer is being torn down). */
	public synchronized void clear() {
		queue.clear();
	}

	public void submit(Type type, Object payload) {
		// taps run OUTSIDE the bus monitor: they mutate game state, and holding
		// this lock across a state mutation would nest monitors across threads
		Request request = new Request(type, payload);
		List<Consumer<Request>> tapsCopy;
		synchronized (this) {
			tapsCopy = taps.isEmpty() ? List.of() : new ArrayList<>(taps);
		}
		// the snapshot stays HERE rather than inside Listeners.fire: that helper
		// copies for iteration safety, but this copy also has to happen under the
		// bus monitor, which the helper knows nothing about
		Listeners.fire(tapsCopy, tap -> tap.accept(request), "ceremony tap failed");
		enqueue(type, payload);
	}

	private synchronized void enqueue(Type type, Object payload) {
		// Coalesce SMALL fanfare floods (early game fires many): once two SMALLs
		// are already waiting, further SMALLs merge into the last one instead of
		// stacking seconds of banners. MEDIUM/LARGE are rare and never coalesce.
		if (type == Type.FANFARE && payload instanceof Fanfare
			&& ((Fanfare) payload).getSize() == Fanfare.Size.SMALL) {
			Request lastSmall = null;
			int queuedSmall = 0;
			for (Request queued : queue) {
				if (queued.getType() == Type.FANFARE && queued.getPayload() instanceof Fanfare
					&& ((Fanfare) queued.getPayload()).getSize() == Fanfare.Size.SMALL) {
					queuedSmall++;
					lastSmall = queued;
				}
			}
			if (queuedSmall >= 2 && lastSmall != null) {
				Fanfare last = (Fanfare) lastSmall.getPayload();
				queue.remove(lastSmall);
				queue.add(new Request(Type.FANFARE, new Fanfare(Fanfare.Size.SMALL,
					last.getTitle(), "…and more", null)));
				drain();
				return;
			}
		}
		queue.add(new Request(type, payload));
		drain();
	}

	/** Called by the overlay layer when it becomes free to present the next request. */
	public synchronized void drain() {
		while (!queue.isEmpty()) {
			Request request = queue.peek();
			boolean claimed = false;
			for (Renderer renderer : renderers) {
				try {
					if (renderer.present(request)) {
						claimed = true;
						break;
					}
				}
				catch (Exception e) {
					log.warn("ceremony renderer failed", e);
				}
			}
			if (claimed) {
				queue.poll();
				return; // renderer presents one at a time; it calls drain() when done
			}
			if (fallback != null) {
				queue.poll();
				try {
					fallback.presentFallback(request);
				}
				catch (Exception e) {
					log.warn("ceremony fallback failed", e);
				}
			}
			else {
				return; // nothing can present yet; keep queued
			}
		}
	}
}

package com.gachaman.service;

import com.gachaman.data.*;
import java.util.*;
import javax.inject.*;
import lombok.*;
import net.runelite.api.*;
import net.runelite.api.coords.*;
import net.runelite.api.events.*;
import net.runelite.client.eventbus.*;
import net.runelite.client.events.*;
import net.runelite.client.util.*;

/**
 * Attributes NPC kills to the local player via engagement windows:
 * InteractingChanged + own hitsplats refresh the window; ActorDeath within
 * ENGAGEMENT_TICKS credits the kill.
 *
 * Assist detection (the ironman half-credit rule) combines three signals:
 * (1) any other-player hitsplat on the NPC — including 0-damage splashes,
 *     which still void ironman credit — sticky for the NPC's lifetime;
 * (2) the game's own "might not receive kill-credit" warning at attack time
 *     (server-authoritative, covers damage dealt before the NPC entered the
 *     scene; toggleable in the game's Activities settings);
 * (3) the loot oracle: kills are emitted a couple of ticks AFTER despawn so
 *     the server's loot events can be observed. Loot received = proof of
 *     full credit (overrides any suspicion — rescues thralls, groupmates and
 *     NPC-inflicted damage); loot absent on a monster with a guaranteed drop
 *     = denial, catching fully off-scene assists even with the warning off.
 */
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class KillTracker {
	private static final int ENGAGEMENT_TICKS = 7;
	private static final int SWEEP_INTERVAL = 25;
	/**
	 * The game's ironman warning ("As an Iron Man, you might not receive
	 * kill-credit for this monster.") fires at ATTACK time.
	 */
	private static final String KILL_CREDIT_WARNING = "might not receive kill-credit";
	/** Emit a pending kill this many ticks after its despawn (loot has landed). */
	private static final int LOOT_SETTLE_TICKS = 2;
	/** Hard emission timeout from death (delayed-despawn bosses). */
	private static final int PENDING_TIMEOUT_TICKS = 30;

	@Value
	public static class Kill {
		String npcName;
		int npcCombatLevel;
		int npcIndex;
		int tick;
		int engagementStartTick;
		boolean tookDamageDuringEngagement;
		int maxHitDealt;
		/**
		 * Another player assisted this kill (final, loot-oracle-adjusted).
		 *
		 * Field-level @With so only withAssistedByOther is generated. The kill is
		 * built at death carrying the provisional SUSPICION verdict and re-stamped
		 * when the loot oracle rules a couple of ticks later; lombok's wither hands
		 * back THIS very instance when the verdict is unchanged, which is the
		 * identity short-circuit the hand-written rebuild used to spell out. The
		 * common case (verdict stands) therefore still allocates nothing.
		 */
		@With
		boolean assistedByOther;
		LocalPoint deathLocation;
	}

	public interface KillListener {
		void onKill(Kill kill);

		/**
		 * The LOCAL player died. Default no-op so the many listeners that only
		 * care about kills are untouched.
		 *
		 * This rides on the death subscription rather than the "Oh dear, you are
		 * dead" chat line because a safe death (Castle Wars, Barbarian Assault,
		 * a minigame) prints no such line — an observer that watched for the
		 * message would silently miss exactly the deaths that cost nothing to
		 * arrange.
		 */
		default void onLocalPlayerDeath() {
		}
	}

	private static class Engagement {
		int lastRefreshTick;
		int startTick;
		int maxHit;
		String name;
		int combatLevel;
	}

	/** A credited kill awaiting the server's loot verdict. */
	private static class PendingKill {
		Kill kill;           // built at death with the SUSPICION verdict
		int npcId;
		int deathTick;
		int despawnTick = -1;
		boolean lootSeen;
	}

	private final Client client;
	private final MonsterTable monsterTable;
	private final List<KillListener> listeners = new ArrayList<>();
	private final Map<Integer, Engagement> engagements = new HashMap<>();
	/** npc index -> another player's hitsplat seen (sticky for the NPC's life). */
	private final Set<Integer> otherDamaged = new HashSet<>();
	/** npc index -> flagged by the game's ironman kill-credit warning. */
	private final Set<Integer> warnedAssist = new HashSet<>();
	private final List<PendingKill> pendingKills = new ArrayList<>();
	/** Monster name (lowercase) -> has no guaranteed drop (loot absence proves nothing). */
	private Map<String, Boolean> noGuaranteedDropByName;

	/**
	 * True once ANY loot event was observed this session — the absence-based
	 * denial only activates after the loot pipeline has proven itself alive,
	 * so a dead pipeline can never penalize every kill.
	 */
	private boolean lootPipelineLive;

	private int tick;
	@Getter
	private int lastPlayerDamagedTick = -1;

	public void addListener(KillListener listener) {
		if (!listeners.contains(listener))
			listeners.add(listener);
	}

	public void removeListener(KillListener listener) {
		listeners.remove(listener);
	}

	public int currentTick() {
		return tick;
	}


	@Subscribe
	public void onGameTick(GameTick event) {
		tick++;
		emitReadyKills();
		if (tick % SWEEP_INTERVAL == 0)
			engagements.values().removeIf(e -> tick - e.lastRefreshTick > ENGAGEMENT_TICKS * 4);
	}

	@Subscribe
	public void onInteractingChanged(InteractingChanged event) {
		// instanceof already excludes null, so this covers "stopped interacting"
		if (event.getSource() == client.getLocalPlayer() && event.getTarget() instanceof NPC)
			refresh((NPC) event.getTarget());
	}

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied event) {
		if (event.getActor() == client.getLocalPlayer()) {
			// NPC hits on YOU are *_ME hitsplat types (they involve the local
			// player), so isMine() covers regular incoming damage; DoT types
			// (poison/venom/...) are neither mine nor others and count too.
			// Drains/heals are not HP damage.
			Hitsplat hitsplat = event.getHitsplat();
			int type = hitsplat.getHitsplatType();
			boolean hpDamage = hitsplat.isMine()
				|| type == HitsplatID.POISON
				|| type == HitsplatID.VENOM
				|| type == HitsplatID.DISEASE
				|| type == HitsplatID.BLEED
				|| type == HitsplatID.BURN
				|| type == HitsplatID.DOOM;
			if (hpDamage && hitsplat.getAmount() > 0)
				lastPlayerDamagedTick = tick;
			return;
		}
		if (!(event.getActor() instanceof NPC))
			return;
		NPC npc = (NPC) event.getActor();
		if (event.getHitsplat().isOthers()) {
			// another player attacked this NPC — even a 0-damage splash voids
			// ironman credit, so no amount filter. Sticky until despawn: the
			// game's denial state never expires either.
			otherDamaged.add(npc.getIndex());
			return;
		}
		if (!event.getHitsplat().isMine())
			return;
		Engagement engagement = refresh(npc);
		engagement.maxHit = Math.max(engagement.maxHit, event.getHitsplat().getAmount());
	}

	@Subscribe
	public void onChatMessage(ChatMessage event) {
		// only real game messages — a player could type the phrase in public chat
		if (event.getType() != ChatMessageType.GAMEMESSAGE
			&& event.getType() != ChatMessageType.SPAM
			&& event.getType() != ChatMessageType.ENGINE) {
			return;
		}
		String text = Text.removeTags(event.getMessage()).toLowerCase(Locale.ROOT);
		if (!text.contains(KILL_CREDIT_WARNING))
			return;
		// the warning refers to the monster just attacked: the current target,
		// falling back to the most recently refreshed engagement
		Player local = client.getLocalPlayer();
		if (local != null && local.getInteracting() instanceof NPC) {
			warnedAssist.add(((NPC) local.getInteracting()).getIndex());
			return;
		}
		// Two details make this the same search the hand-rolled loop performed.
		// Ties: the loop used a strict >, so the first entry encountered kept the
		// crown; Stream.max reduces with BinaryOperator.maxBy, which returns the
		// LEFT argument whenever compare(a, b) >= 0 — first-encountered wins there
		// too, over the same entrySet in the same order.
		// Emptiness: the loop's trailing bestIndex >= 0 only asked "did anything
		// match at all", because lastRefreshTick is assigned from tick and so is
		// never below 0, which the -1 seed always loses to on the first entry, and
		// npc indices are never negative. ifPresent asks exactly that question.
		engagements.entrySet().stream()
			.max(Comparator.comparingInt(e -> e.getValue().lastRefreshTick))
			.ifPresent(e -> warnedAssist.add(e.getKey()));
	}

	@Subscribe
	public void onActorDeath(ActorDeath event) {
		if (!(event.getActor() instanceof NPC)) {
			// The one non-NPC death worth reporting: this player's own. Same
			// event, one branch, so death is observed exactly where kills are.
			if (client != null && event.getActor() instanceof Player
				&& event.getActor() == client.getLocalPlayer()) {
				Listeners.fire(listeners, KillListener::onLocalPlayerDeath,
					"death listener failed");
			}
			return;
		}
		NPC npc = (NPC) event.getActor();
		Engagement engagement = engagements.remove(npc.getIndex());
		boolean suspected = otherDamaged.remove(npc.getIndex()) | warnedAssist.remove(npc.getIndex());
		if (engagement == null || tick - engagement.lastRefreshTick > ENGAGEMENT_TICKS)
			return;
		boolean tookDamage = lastPlayerDamagedTick >= engagement.startTick;
		PendingKill pending = new PendingKill();
		pending.kill = new Kill(engagement.name, engagement.combatLevel, npc.getIndex(), tick,
			engagement.startTick, tookDamage, engagement.maxHit, suspected, npc.getLocalLocation());
		pending.npcId = npc.getId();
		pending.deathTick = tick;
		pendingKills.add(pending);
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned event) {
		int index = event.getNpc().getIndex();
		for (PendingKill pending : pendingKills) {
			if (pending.despawnTick < 0 && pending.kill.getNpcIndex() == index) {
				pending.despawnTick = tick;
				break;
			}
		}
		// a despawn (death or walk-off) ends the NPC instance: drop its flags
		// so a reused index can never inherit them
		otherDamaged.remove(index);
		warnedAssist.remove(index);
		engagements.remove(index);
	}

	@Subscribe
	public void onNpcLootReceived(NpcLootReceived event) {
		lootPipelineLive = true;
		int index = event.getNpc().getIndex();
		for (PendingKill pending : pendingKills) {
			if (!pending.lootSeen && pending.kill.getNpcIndex() == index) {
				pending.lootSeen = true;
				return;
			}
		}
	}

	@Subscribe
	public void onServerNpcLoot(ServerNpcLoot event) {
		lootPipelineLive = true;
		if (event.getComposition() == null)
			return;
		int npcId = event.getComposition().getId();
		// Composition, not index — this event carries no index, so several pendings of
		// the same monster are indistinguishable and one of them has to be chosen.
		// FIFO chose the OLDEST, which is the wrong end: loot lands with the death, so
		// the newest unmatched pending is the one it belongs to, while the oldest is
		// typically a delayed-despawn corpse still waiting out PENDING_TIMEOUT_TICKS.
		// Backwards costs TWO verdicts at once — kill an assisted monster, then a clean
		// one of the same type, and the clean kill's loot exonerates the assisted
		// pending while the clean kill is left unproven and convicted on absence. That
		// inversion is precisely what the loot oracle exists to prevent.
		//
		// Ties keep list (death) order, and there is no time window layered on top.
		// Two monsters that die on one tick send two loot events, so taking them
		// first-listed marks both, where refusing to choose would convict a clean kill
		// on the strength of our own ambiguity. And preferring the newest can never
		// refuse a match FIFO would have made — it only changes WHICH pending is
		// credited — so nothing proven today becomes unproven.
		PendingKill best = null;
		for (PendingKill pending : pendingKills) {
			if (!pending.lootSeen && pending.npcId == npcId
				&& (best == null || pending.deathTick > best.deathTick)) {
				best = pending;
			}
		}
		if (best != null)
			best.lootSeen = true;
	}

	/**
	 * The final assist verdict once the loot window closed. Loot received is
	 * server PROOF of full credit and overrides any suspicion; loot absence
	 * convicts only when the pipeline is proven alive AND the monster has a
	 * guaranteed drop.
	 */
	static boolean finalAssisted(boolean lootSeen, boolean suspected, boolean pipelineLive,
		boolean guaranteedDrop) {
		if (lootSeen)
			return false;
		return suspected || (pipelineLive && guaranteedDrop);
	}

	private void emitReadyKills() {
		if (pendingKills.isEmpty())
			return;
		Iterator<PendingKill> it = pendingKills.iterator();
		while (it.hasNext()) {
			PendingKill pending = it.next();
			boolean settled = pending.despawnTick >= 0 && tick - pending.despawnTick >= LOOT_SETTLE_TICKS;
			boolean timedOut = tick - pending.deathTick >= PENDING_TIMEOUT_TICKS;
			if (!settled && !timedOut)
				continue;
			it.remove();
			emit(pending);
		}
	}

	private void emit(PendingKill pending) {
		Kill draft = pending.kill;
		// the wither rebuilds only when the oracle actually overturns the draft
		// verdict, so the eight untouched fields never have to be respelled here
		Kill kill = draft.withAssistedByOther(finalAssisted(pending.lootSeen,
			draft.isAssistedByOther(), lootPipelineLive, hasGuaranteedDrop(draft.getNpcName())));
		Listeners.fire(listeners, l -> l.onKill(kill), "kill listener failed");
	}

	/** Emit everything still pending with current verdicts (logout hygiene). */
	public void flushPending() {
		List<PendingKill> drain = new ArrayList<>(pendingKills);
		pendingKills.clear();
		drain.forEach(this::emit);
		otherDamaged.clear();
		warnedAssist.clear();
		engagements.clear();
	}

	private boolean hasGuaranteedDrop(String npcName) {
		if (noGuaranteedDropByName == null) {
			noGuaranteedDropByName = new HashMap<>();
			for (MonsterTable.Monster monster : monsterTable.getMonsters()) {
				noGuaranteedDropByName.put(monster.getName().toLowerCase(Locale.ROOT),
					monster.isNoGuaranteedDrop());
			}
		}
		Boolean noDrop = noGuaranteedDropByName.get(npcName == null ? ""
			: npcName.toLowerCase(Locale.ROOT));
		// unknown monsters (off-table) default to NOT convicting on absence
		return noDrop != null && !noDrop;
	}

	// No low-HP helper lives here any more: the only clutch-kill check in the
	// plugin is TaskService's own private killTrackerLowHp(), which never called
	// this one. Nothing player-visible changed — the same check still runs, from
	// the same place it always ran.

	private Engagement refresh(NPC npc) {
		Engagement engagement = engagements.get(npc.getIndex());
		if (engagement == null || tick - engagement.lastRefreshTick > ENGAGEMENT_TICKS * 4) {
			engagement = new Engagement();
			engagement.startTick = tick;
			engagements.put(npc.getIndex(), engagement);
		}
		engagement.lastRefreshTick = tick;
		String name = npc.getName();
		if (name != null)
			engagement.name = Text.removeTags(name);
		engagement.combatLevel = npc.getCombatLevel();
		return engagement;
	}
}

package com.gachaman.service;

import com.gachaman.data.*;
import com.google.gson.*;
import java.util.*;
import javax.inject.*;
import net.runelite.api.*;
import net.runelite.api.gameval.*;

/**
 * Ironman armour is account-type identity gear: the game only lets you wear
 * the set matching your own account type. Granting every set to every profile
 * therefore handed a normal account eighteen cards it could never equip, and
 * parked an unwearable Hardcore ironman platebody in its one starter body slot.
 *
 * Varbit 1777 carries the account type. It is read raw rather than through
 * {@code client.getAccountType()} because unranked group ironman (value 6)
 * postdates RuneLite's AccountType enum, which stops at 5.
 */
@Singleton
public final class IronmanGear {
	/** Account type varbit value for a non-ironman account. */
	public static final int NORMAL = 0;

	/**
	 * {helm, platebody, platelegs} indexed by the account type varbit value,
	 * from ironman-gear.json. Index {@link #BODY} of each entry is the piece
	 * the body slot takes.
	 */
	private static class Table {
		List<List<String>> sets = Collections.emptyList();
	}

	private final List<List<String>> sets;

	@Inject
	IronmanGear(Gson gson) {
		this.sets = DataJson.load(gson, "ironman-gear", Table.class, new Table()).sets;
	}

	private static final int BODY = 1;

	/** The account type varbit, or {@link #NORMAL} if it cannot be read. */
	public static int accountType(Client client) {
		if (client == null)
			return NORMAL;
		try {
			return client.getVarbitValue(VarbitID.IRONMAN);
		}
		catch (Exception e) {
			return NORMAL;
		}
	}

	/**
	 * The armour cards this account type may actually wear — empty for a
	 * normal account, and empty for any future account type this build has
	 * never heard of (granting nothing beats granting the wrong set).
	 */
	public List<String> cardNames(int accountType) {
		if (accountType <= NORMAL || accountType >= sets.size())
			return Collections.emptyList();
		return Collections.unmodifiableList(sets.get(accountType));
	}

	/** The platebody of this account's set, or null if there is none to assign. */
	public String bodyCardName(int accountType) {
		List<String> set = cardNames(accountType);
		return set.isEmpty() ? null : set.get(BODY);
	}

	/**
	 * Every ironman armour name across all account types. The reconcile pass
	 * uses this to identify starter cards an account should never have been
	 * given, so it must stay exhaustive.
	 */
	public Set<String> allCardNames() {
		Set<String> all = new LinkedHashSet<>();
		for (List<String> set : sets) {
			all.addAll(set);
		}
		return Collections.unmodifiableSet(all);
	}
}

package com.gachaman.service;

import net.runelite.api.gameval.InventoryID;
import com.gachaman.*;
import com.gachaman.data.*;
import com.gachaman.model.*;
import java.util.*;
import java.util.function.*;
import javax.annotation.*;
import javax.inject.*;
import lombok.*;
import lombok.extern.slf4j.*;
import net.runelite.api.*;
import net.runelite.client.chat.*;

/**
 * Loadout assignment rules, shared by the sidebar panel and the in-game
 * overlay. Equipment cards may only occupy their own gear slot; hologram
 * cards fit any slot but may occupy only ONE slot at a time (re-assigning a
 * hologram moves it).
 */
@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class LoadoutService {
	private final GachaStateService stateService;
	private final CardDatabase cardDatabase;
	private final TierTable tierTable;
	private final RangedMetal.Lookup rangedMetal;
	private final Client client;
	private final GachamanConfig config;
	private final PermissionService permissionService;
	private final ChatMessageManager chatMessageManager;

	/** Optional hook fired after a successful assignment (Firsts + Timeline). */
	@Nullable
	@Setter
	private BiConsumer<GearSlot, OwnedCard> assignHook;

	/** Tick of the last refusal line, so a fumbled double-click says it once. */
	private int lastWarnTick = -1;


	/** Assign an owned card to a loadout slot. Returns false when invalid. */
	public boolean assign(GearSlot slot, String ownedCardUuid) {
		GachaState state = stateService.get();
		if (state == null || slot == null || ownedCardUuid == null)
			return false;
		OwnedCard owned = findByUuid(state, ownedCardUuid);
		if (owned == null)
			return false;
		if (!owned.isHologram()) {
			if (!cardDatabase.isReady())
				return false;
			CardDefinition def = cardDatabase.card(owned.getCardId());
			if (def == null || def.getSlot() != slot)
				return false;
		}
		stateService.mutate(s -> {
			OwnedCard card = findByUuid(s, ownedCardUuid);
			if (card == null)
				return s;
			Map<String, String> loadout = new HashMap<>(s.getLoadout());
			if (card.isHologram()) {
				// a hologram may occupy only one slot: assigning elsewhere moves it
				loadout.values().removeIf(ownedCardUuid::equals);
			}
			loadout.put(slot.name(), ownedCardUuid);
			return s.withLoadout(loadout);
		});
		// Straight to disk, not into the debounce. A loadout change is a
		// deliberate, fiddly decision the player just spent time on — swapping a
		// card between slots, re-equipping around a new pull — and it is the
		// single change they are most likely to notice missing. It is also rare
		// enough that an immediate write costs nothing measurable.
		stateService.checkpoint();
		Listeners.fireHook(assignHook, h -> h.accept(slot, owned), "assign hook failed");
		return true;
	}

	/**
	 * Clear a loadout slot.
	 *
	 * <p>REFUSES while an item this card unlocks is still WORN. Unassigning is
	 * the only way to lose a permission you are in the middle of exercising:
	 * nothing re-reads equipment on a loadout change, so the player would walk
	 * away still wearing gear the album no longer permits, and stay that way
	 * until some unrelated container change happened to force a rebuild. The
	 * plugin may not take the gear off for them — no automated actions, ever —
	 * so refusing and saying why is the only honest answer left.
	 *
	 * <p>Guarded only while {@code oneCardPerSlot} is ON, which is the same
	 * branch {@link PermissionService#rebuild} takes. With it OFF permission
	 * comes from OWNERSHIP alone (rebuildOwnershipOnly), the loadout grants
	 * nothing at all, and clearing a slot therefore takes nothing away — a
	 * guard there would be refusing a click that could not have hurt anyone.
	 *
	 * @return false ONLY when the guard refused and nothing changed. A clear
	 *     that happened, a slot that was already empty and a null slot all
	 *     return true: there is nothing there for a caller to explain.
	 */
	public boolean unassign(GearSlot slot) {
		if (slot == null)
			return true;
		if (stillWorn(slot, assigned(slot))) {
			refuseWornUnassign();
			return false;
		}
		stateService.mutate(s -> {
			if (!s.getLoadout().containsKey(slot.name()))
				return s;
			Map<String, String> loadout = new HashMap<>(s.getLoadout());
			loadout.remove(slot.name());
			return s.withLoadout(loadout);
		});
		// clearing a slot is a loadout change like any other, and a clear that
		// silently came back after a crash would be just as confusing as an
		// assignment that vanished
		stateService.checkpoint();
		return true;
	}

	/**
	 * Is something this card unlocks IN THIS SLOT on the player's back?
	 *
	 * <p>The id set comes from {@link PermissionService#itemIdsFor} — the very
	 * branch the rebuild loop runs per entry — and deliberately not from
	 * isForbidden, which answers false for every one of these ids exactly
	 * because the card is still assigned.
	 *
	 * <p>The worn container is scanned whole instead of being indexed by
	 * GearSlot. The card that named these ids already named the slot they live
	 * in, so an id match IS a slot match, and no GearSlot -> container index
	 * table has to exist or be kept correct.
	 */
	private boolean stillWorn(GearSlot slot, OwnedCard owned) {
		if (owned == null || !config.oneCardPerSlot())
			return false;
		Set<Integer> worn = wornItemIds();
		for (int itemId : permissionService.itemIdsFor(owned, slot)) {
			if (worn.contains(itemId))
				return true;
		}
		return false;
	}

	/**
	 * Item ids on the player's back right now, read the way GraduationService
	 * reads them: the WORN container, skipping the empty-slot sentinels.
	 *
	 * <p>Package-private so a headless test can hand the guard a synthetic set.
	 * RuneLite's Client is far too wide an interface to implement for one
	 * container read, and this repo's suite carries no mocking framework.
	 */
	Set<Integer> wornItemIds() {
		ItemContainer worn = client == null ? null : client.getItemContainer(InventoryID.WORN);
		if (worn == null) {
			return Collections.emptySet(); // logged out: fail open, like every permission read
		}
		Set<Integer> ids = new HashSet<>();
		for (Item item : worn.getItems()) {
			if (item != null && item.getId() > 0)
				ids.add(item.getId());
		}
		return ids;
	}

	/**
	 * The refusal line: CONSOLE, the Gachaman prefix, once per tick — the same
	 * shape EquipBlockService warns in when it blocks an equip. A player meets
	 * both messages in the same breath and they should read as one voice.
	 *
	 * <p>It lives HERE, not at each call site, on purpose. The in-game board
	 * has no text of its own and the chatbox search discards its result
	 * entirely, so a refusal wired per-caller is one forgotten call site away
	 * from a click that does nothing and says nothing. Putting it in the
	 * service means every caller — including ones this file has not met yet —
	 * gets the same sentence for free. The sidebar adds a dialog on top of it,
	 * because that is where a sidebar click is already answered.
	 */
	private void refuseWornUnassign() {
		if (chatMessageManager == null || client == null) {
			return; // headless (tests): the boolean return is the whole contract there
		}
		int tick = client.getTickCount();
		if (tick == lastWarnTick)
			return;
		lastWarnTick = tick;
		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.CONSOLE)
			.runeLiteFormattedMessage("<col=b25be2>Gachaman:</col> That card is still unlocking"
				+ " what you are wearing. Take the item off first.")
			.build());
	}

	/** The owned card currently assigned to a slot, or null. */
	@Nullable
	public OwnedCard assigned(GearSlot slot) {
		GachaState state = stateService.get();
		if (state == null || slot == null)
			return null;
		String uuid = state.getLoadout().get(slot.name());
		return uuid == null ? null : findByUuid(state, uuid);
	}

	/**
	 * Owned cards that could be assigned to this slot right now: unassigned
	 * equipment cards whose card slot matches, plus every owned hologram
	 * (holograms are valid for every slot; assigning one that lives elsewhere
	 * moves it). Duplicate (cardId, variant) copies are collapsed to one.
	 */
	public List<OwnedCard> validFor(GearSlot slot) {
		GachaState state = stateService.get();
		List<OwnedCard> result = new ArrayList<>();
		if (state == null || slot == null || !cardDatabase.isReady())
			return result;
		Set<String> assignedUuids = new HashSet<>(state.getLoadout().values());
		String currentUuid = state.getLoadout().get(slot.name());
		Set<String> seen = new HashSet<>();
		for (OwnedCard owned : state.getOwnedCards()) {
			if (owned.isHologram()) {
				if (owned.getUuid().equals(currentUuid)) {
					continue; // already here
				}
				if (!seen.add("H:" + owned.getTierKey()))
					continue;
				result.add(owned);
				continue;
			}
			CardDefinition def = cardDatabase.card(owned.getCardId());
			if (def == null || def.getSlot() != slot)
				continue;
			if (assignedUuids.contains(owned.getUuid()))
				continue;
			if (!seen.add("C:" + owned.getCardId() + ":" + owned.getVariant()))
				continue;
			result.add(owned);
		}
		// group 1: cards matching the rolled attack style (or style-neutral);
		// group 2: everything else — A-Z within both groups
		AttackStyle allowed = state.getAllowedStyle() == null
			? null : AttackStyle.valueOf(state.getAllowedStyle());
		result.sort(Comparator
			.comparing((OwnedCard owned) -> !matchesStyle(owned, allowed))
			.thenComparing(this::displayName, String.CASE_INSENSITIVE_ORDER));
		return result;
	}

	/** Does this card belong to the rolled style's gear family? Neutral gear always matches. */
	public boolean matchesStyle(OwnedCard owned, AttackStyle allowed) {
		if (allowed == null)
			return true;
		AttackStyle style = styleOf(owned);
		return style == null || style == allowed;
	}

	/** MELEE/RANGED/MAGIC by tier ladder; null = style-neutral or unknown. */
	@Nullable
	public AttackStyle styleOf(OwnedCard owned) {
		String tierKey = null;
		String name = null;
		if (owned.isHologram())
			tierKey = owned.getTierKey();
		else {
			CardDefinition def = cardDatabase.card(owned.getCardId());
			if (def != null) {
				tierKey = def.getTierKey();
				name = def.getName();
			}
		}
		if (tierKey == null)
			return null;
		String ladder = tierTable.ladderOf(tierKey);
		if (ladder == null)
			return null;
		switch (ladder) {
			case "metal":
				// Rune arrows and adamant darts sit on the metal ladder but are Ranged gear.
				// Calling them melee sorted them into the non-matching half of a ranger's own
				// loadout picker. Holograms carry no item name, so they keep the melee default.
				return rangedMetal.of(name) != null
					? AttackStyle.RANGED
					: AttackStyle.MELEE;
			case "dhide":
				return AttackStyle.RANGED;
			case "robes":
				return AttackStyle.MAGIC;
			default:
				return null;
		}
	}

	/** Human-readable name for an owned card (works for holograms too). */
	public String displayName(OwnedCard owned) {
		if (owned == null)
			return "?";
		if (owned.isHologram()) {
			HologramDefinition holo = cardDatabase.holograms().get(owned.getTierKey());
			return holo != null ? holo.getName() : "Hologram (" + owned.getTierKey() + ")";
		}
		CardDefinition def = cardDatabase.card(owned.getCardId());
		String name = def != null ? def.getName() : "Card #" + owned.getCardId();
		return owned.getVariant() == Variant.SHINY ? name + " (Shiny)" : name;
	}

	@Nullable
	private static OwnedCard findByUuid(GachaState state, String uuid) {
		for (OwnedCard card : state.getOwnedCards()) {
			if (card.getUuid().equals(uuid))
				return card;
		}
		return null;
	}
}

package com.gachaman.service;

import java.nio.charset.*;
import java.security.*;
import java.util.*;
import javax.annotation.*;

/**
 * A stable, per-account identifier for the party layer.
 *
 * Jagex gives every account a permanent id and RuneLite exposes it as
 * {@code Client.getAccountHash()}, but SELF-ONLY: a PartyMember carries a
 * member id, a display name, an avatar and a login flag, and nothing in the
 * API maps another player back to an account. So the key has to be sent, and
 * what is sent is what everyone in the party can read.
 *
 * That is why this hashes rather than forwarding the raw value. The account
 * hash is a permanent cross-session correlator and is also the input RuneLite
 * itself derives the RS profile key from; handing it to every member of every
 * party you ever join gives away more than "this is the same person I rolled
 * with last week". Truncating SHA-256 to 8 bytes keeps that one statement and
 * throws the rest away — 16 hex characters is far too wide to collide inside
 * a party, and is not the account hash.
 *
 * SELF-REPORTED AND UNAUTHENTICATED. The value arrives over the party relay
 * from another player's client, so a hostile client can claim any key it
 * likes — exactly the trust level of the display name it replaces. Fine as
 * the key for a cosmetic mark and for grouping rows on a page. Never let it
 * gate anything that pays.
 *
 * Pure statics, so every rule here is testable without a Client.
 */
public final class AccountKey {
	/** 8 bytes of SHA-256, hex-encoded. */
	public static final int KEY_LENGTH = 16;

	/** What getAccountHash() returns when nobody is logged in. */
	public static final long NO_ACCOUNT = -1L;

	private static final char[] HEX = "0123456789abcdef".toCharArray();

	private AccountKey() {
		return;
	}

	/**
	 * The key for an account hash, or null when there is no account.
	 *
	 * Null rather than a constant "logged out" string: a key is an identity
	 * claim, and every logged-out client sharing one would make them all the
	 * same person. Callers must treat null as "unknown", never as a group.
	 */
	@Nullable
	public static String of(long accountHash) {
		if (accountHash == NO_ACCOUNT || accountHash == 0L)
			return null;
		MessageDigest digest;
		try {
			digest = MessageDigest.getInstance("SHA-256");
		}
		catch (NoSuchAlgorithmException e) {
			// SHA-256 is required of every JRE; if it is genuinely absent the
			// right answer is "no identity", not a crash on the game thread
			return null;
		}
		byte[] hash = digest.digest(Long.toString(accountHash).getBytes(StandardCharsets.UTF_8));
		char[] out = new char[KEY_LENGTH];
		for (int i = 0; i < KEY_LENGTH / 2; i++) {
			out[i * 2] = HEX[(hash[i] >> 4) & 0xF];
			out[i * 2 + 1] = HEX[hash[i] & 0xF];
		}
		return new String(out);
	}

	/**
	 * A received key made safe to store and compare, or null if it is not one.
	 *
	 * The trust boundary for everything that arrives over the wire. Length and
	 * alphabet are both checked because this string becomes a KEY in the save
	 * blob: an unbounded remote string keyed into a persisted map is a way to
	 * grow somebody else's save file, and a mixed-case one would key twice.
	 */
	@Nullable
	public static String normalize(String raw) {
		if (raw == null)
			return null;
		String key = raw.trim().toLowerCase(Locale.ROOT);
		if (key.length() != KEY_LENGTH)
			return null;
		for (int i = 0; i < KEY_LENGTH; i++) {
			char c = key.charAt(i);
			if ((c < '0' || c > '9') && (c < 'a' || c > 'f'))
				return null;
		}
		return key;
	}

	/**
	 * Whether two claims name the same account. Two unknowns are NOT the same
	 * account — that is the whole reason this is not {@code Objects.equals}.
	 */
	public static boolean same(String a, String b) {
		String left = normalize(a);
		String right = normalize(b);
		return left != null && left.equals(right);
	}
}

package com.gachaman.service;

import java.util.*;
import javax.annotation.*;
import javax.inject.*;
import lombok.*;
import net.runelite.api.*;
import net.runelite.api.gameval.*;
import net.runelite.client.config.*;
import net.runelite.client.plugins.slayer.*;

/**
 * Double Docket: does a Gachaman contract's target intersect the player's live
 * Slayer assignment?
 *
 * The Slayer plugin's own {@code SlayerPluginService} is bound inside that
 * plugin's CHILD injector ({@code SlayerPlugin implements Module}), so it
 * cannot be injected from here at all — it would fail at injection time. The
 * assignment is therefore read out of the persisted config the Slayer plugin
 * writes, which is a public contract of the client.
 *
 * Everything that touches {@link Client} or {@link ConfigManager} lives in
 * {@link #liveTarget()}; the matching RULE below it is pure static and fully
 * unit tested, because no mocking framework is available in this project.
 */
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class SlayerAlignment {
	private final Client client;
	private final ConfigManager configManager;

	/**
	 * The name of the LIVE Slayer assignment, or null when there is none.
	 *
	 * The remaining-count varp is the authority on liveness, NOT the config.
	 * SlayerPlugin.updateTask() writes setTask("", 0, 0) when the count drops
	 * to zero, so while that plugin is ENABLED the persisted name self-clears —
	 * but with it disabled the config freezes at the last assignment the player
	 * ever had, and a stale name with 0 remaining must never pay the bonus. The
	 * varp is server-written and correct whether or not the Slayer plugin is
	 * installed. The config is still needed for the NAME (the varp holds a
	 * count, not a string), so both are read: varp for "is it live", config for
	 * "what is it".
	 *
	 * SlayerPlugin persists these with setRSProfileConfiguration, so this MUST
	 * read them with getRSProfileConfiguration — getConfiguration("slayer",
	 * "taskName") returns null. That call also returns null when there is no RS
	 * profile key (not logged in), which is exactly the answer we want.
	 */
	@Nullable
	public String liveTarget() {
		if (client == null || configManager == null)
			return null;
		if (client.getVarpValue(VarPlayerID.SLAYER_COUNT) <= 0)
			return null;
		String name = configManager.getRSProfileConfiguration(
			SlayerConfig.GROUP_NAME, SlayerConfig.TASK_NAME_KEY);
		return name == null || name.isEmpty() ? null : name;
	}

	// ------------------------------------------------------------------
	// The rule. Pure statics — no Client, no ConfigManager, no state.
	// ------------------------------------------------------------------

	/**
	 * Does a contract target intersect a Slayer assignment?
	 *
	 * Contract targets are singular NPC names ("Fire giant"); Slayer
	 * assignments are plural category names ("Fire giants"), so the assignment
	 * is singularised and compared against the contract. Either side null or
	 * blank is NO match — no Slayer task means no bonus, never a default-on.
	 *
	 * KNOWN AND DELIBERATE GAP: set-valued assignments ("Metal dragons",
	 * "Bandits", "Fever spiders") name a category no NPC is called, so they
	 * cannot be resolved from the name alone. Slayer's own Task enum, which
	 * holds that mapping, is package-private and unreachable from here, and
	 * shipping a hand-written table would be asserting game data that cannot be
	 * verified against real code. The failure mode is a WITHHELD bonus, never a
	 * wrongly paid one, which is the correct direction to fail; the sidebar
	 * tooltip states the limitation with this exact example.
	 */
	static boolean matches(String contractMonster, String slayerTarget) {
		String contract = normalize(contractMonster);
		String target = normalize(slayerTarget);
		if (contract.isEmpty() || target.isEmpty())
			return false;
		for (String candidate : singularCandidates(target)) {
			if (candidate.isEmpty())
				continue;
			if (contract.equals(candidate))
				return true;
			// One-directional, word-boundary prefix: an assignment BROADER than
			// the contract genuinely covers it ("Kalphites" covers "Kalphite
			// Worker", "Elves" covers "Elf archer"), while the reverse is not a
			// real relationship. The trailing space is LOAD-BEARING — a bare
			// startsWith would make "Rats" match "Ratcatcher".
			if (contract.startsWith(candidate + " "))
				return true;
		}
		return false;
	}

	/** Lowercase, letters/digits/spaces only, whitespace collapsed, no edge spaces. */
	static String normalize(String raw) {
		if (raw == null)
			return "";
		StringBuilder sb = new StringBuilder(raw.length());
		boolean pendingSpace = false;
		for (int i = 0; i < raw.length(); i++) {
			char c = raw.charAt(i);
			if (Character.isLetterOrDigit(c)) {
				if (pendingSpace && sb.length() > 0)
					sb.append(' ');
				pendingSpace = false;
				sb.append(Character.toLowerCase(c));
			}
			else {
				pendingSpace = true;
			}
		}
		return sb.toString();
	}

	/**
	 * Every plausible singular of an already-normalized name, applied to the
	 * LAST word only ("fire giants" -> "fire giant").
	 *
	 * English pluralisation is not a function — the ies->y rule is right for
	 * "jellies" and wrong for "zombies" — so guessing one form guarantees a
	 * class of silent misses. Generating the whole candidate set is safe
	 * because a wrong candidate ("zomby") is a non-word that matches no
	 * monster. The name itself is always a candidate, so an assignment with no
	 * plural form ("Nechryael") still works.
	 */
	static List<String> singularCandidates(String normalized) {
		List<String> out = new ArrayList<>(5);
		out.add(normalized);
		int cut = normalized.lastIndexOf(' ');
		String head = cut < 0 ? "" : normalized.substring(0, cut + 1);
		String last = cut < 0 ? normalized : normalized.substring(cut + 1);
		if (last.length() > 1 && last.endsWith("s")) {
			out.add(head + last.substring(0, last.length() - 1));        // giants -> giant
		}
		if (last.length() > 3 && last.endsWith("ies")) {
			out.add(head + last.substring(0, last.length() - 3) + "y");  // jellies -> jelly
		}
		if (last.length() > 3 && last.endsWith("ves")) {
			out.add(head + last.substring(0, last.length() - 3) + "f");  // elves -> elf
			out.add(head + last.substring(0, last.length() - 3) + "fe"); // knives -> knife
		}
		if (last.length() > 2 && last.endsWith("es")) {
			out.add(head + last.substring(0, last.length() - 2));        // boxes -> box
		}
		return out;
	}
}

package com.gachaman.service;

import com.gachaman.*;
import com.gachaman.model.*;
import javax.inject.*;
import lombok.*;
import lombok.extern.slf4j.*;

/**
 * The style lock. Rolls are uniform 1/3 and may legitimately re-pick the
 * current style; the roulette ceremony is purely cosmetic (outcome committed
 * immediately — nothing here is exploitable by closing the overlay).
 *
 * <p>The wheel names two things: the style, and a preferred weapon CATEGORY
 * inside it. The category is purely a bonus — a compliant on-task kill landed
 * with that category in hand pays {@link Tuning#WEAPON_BONUS_MULT}, and a kill
 * landed without it pays exactly what it always did. See {@link
 * WeaponTypeService} for the taxonomy, and for why a category this build cannot
 * name is silently no bonus rather than a penalty.
 */
@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class StyleService {
	@Value
	public static class StyleRollResult {
		AttackStyle previous; // null on the very first roll
		AttackStyle rolled;
		int cycleTarget;
		/**
		 * The weapon category named alongside the style, or null when none was —
		 * an empty pool, which means the taxonomy resource failed to load.
		 *
		 * <p>The whole VALUE rather than its key, so an announcing caller can reach
		 * {@code getDisplayName()} without injecting WeaponTypeService to translate.
		 * That matters more than it looks: the key for category 0 is "unarmed", and
		 * the owner's rule is that player-facing text says "no weapon equipped",
		 * because the game reports that category for every non-weapon held item
		 * too. Handing callers the key alone would make the easy thing the wrong
		 * thing. Deeply immutable, so the ceremony payload is safe on the EDT.
		 */
		WeaponTypeService.WeaponType weaponType;
	}

	private final GachaStateService stateService;
	private final ComplianceService complianceService;
	private final CeremonyBus ceremonyBus;
	private final GachaRng rng;
	private final WeaponTypeService weaponTypeService;

	public boolean hasRolled() {
		GachaState state = stateService.get();
		return state != null && state.getAllowedStyle() != null;
	}

	/** Roll (or re-roll) the allowed style, commit, and queue the roulette ceremony. */
	public StyleRollResult roll(int currentTick) {
		return roll(currentTick, null);
	}

	/**
	 * As {@link #roll(int)}, but with the style NAMED instead of drawn — the
	 * Consignment's deferred path, where the house picks the style as the price of
	 * a free crate. See {@link ConsignmentService} for why that roll is held back
	 * rather than taken and overwritten.
	 *
	 * <p><b>An overload here rather than a commit written over there.</b> The wheel
	 * names more than the style, and it will name more again: a duplicated mutate
	 * inside the Consignment would set the style, the cycle and the timestamp and
	 * silently drop the preferred weapon type, so an accepted deal would cost the
	 * player the whole cycle's {@link Tuning#WEAPON_BONUS_MULT} with nothing on
	 * screen to explain it. One commit path means whatever the wheel learns to name
	 * next lands in both routes at once, with no sync burden on either.
	 *
	 * <p>Nothing here excludes a forced style from the first-ever roll, and nothing
	 * needs to: {@code ConsignmentService.canOffer} refuses to make an offer at all
	 * while {@code allowedStyle} is null, because an account with no album cannot be
	 * worst dressed for anything. Were a forced roll ever to land first anyway,
	 * {@code firstEver} below still arms the free First Colours chest — the
	 * discriminator is the absent PREVIOUS style, not the presence of a draw.
	 *
	 * @param forced the style to commit, or null to spin the wheel
	 */
	public StyleRollResult roll(int currentTick, AttackStyle forced) {
		GachaState state = stateService.get();
		if (state == null)
			return null;
		AttackStyle previous = state.getAllowedStyle() == null
			? null : AttackStyle.valueOf(state.getAllowedStyle());
		AttackStyle rolled = forced != null
			? forced : AttackStyle.values()[rng.nextInt(AttackStyle.values().length)];
		int target = Tuning.CYCLE_TASKS;
		// A fresh account is exactly the one with no previous style, and that same
		// fact arms the free First Colours chest. Armed inside THIS mutate rather
		// than a second one: a separate write would leave a window where the style
		// is committed but the gift is not owed, and every mutate pays a full
		// gzip + SHA-256 of the whole save.
		final boolean firstEver = previous == null;
		// The weapon category rides the same mutate for the same reason, and the
		// window it closes is nastier than the chest's: two writes would leave a
		// moment in which the NEW style is live and the preference is still the
		// LAST cycle's, so a crash there ships a MAGIC cycle whose preferred
		// category is a scimitar — a bonus the player can never earn and cannot see
		// is wrong. Drawn out here and captured, following the same shape as
		// `rolled` and `target`, so the draw is unambiguously once.
		//
		// AFTER the style draw, deliberately: the style stays the first number off
		// the stream, which is what lets a test predict a seeded wheel with a bare
		// `new GachaRng(seed).nextInt(3)`.
		//
		// And it draws from the INJECTED rng — the singleton, never the party's. A
		// seeded party roll builds its own `new GachaRng(seed)` and passes it down
		// as an argument (PartyRollService), so this stream is not that one, and it
		// must stay that way: an extra draw taken inside a seeded path by one client
		// and not another shifts every later draw and deals two different boards.
		// Tuning's Double Docket comment warns about exactly that failure. The
		// preference is strictly per-player and rides the per-player style roll —
		// party members legitimately hold different styles and different categories,
		// and each earns their own bonus on their own kills against the shared quota.
		final WeaponTypeService.WeaponType weaponType = weaponTypeService.roll(rolled);

		stateService.mutate(s -> {
			GachaState next = s
				.withAllowedStyle(rolled.name())
				.withCycleProgress(0)
				.withCycleTarget(target)
				.withStyleRolledAtMs(System.currentTimeMillis())
				// Written unconditionally, null included. A cycle the taxonomy could
				// not name a category for must CLEAR the last one rather than inherit
				// it — an "only write it when we have one" guard would leave a stale
				// preference live against a style it was never rolled for.
				.withPreferredWeaponType(weaponType == null ? null : weaponType.getKey());
			return firstEver ? next.withFirstColoursChestOwed(true) : next;
		});
		complianceService.noteStyleChanged(currentTick);

		StyleRollResult result = new StyleRollResult(previous, rolled, target, weaponType);
		ceremonyBus.submit(CeremonyBus.Type.STYLE_ROLL, result);
		log.debug("Style rolled: {} (target {} tasks, weapon {})", rolled, target,
			weaponType == null ? "none" : weaponType.getKey());
		return result;
	}

	/** Advance the cycle by a completed task; true when a re-roll is due. */
	public boolean advanceCycle(String appliedCharge) {
		GachaState state = stateService.get();
		if (state == null || state.getAllowedStyle() == null)
			return false;
		double weight = 1.0;
		if ("COMPACTOR".equals(appliedCharge))
			weight = Tuning.COMPACTOR_WEIGHT;
		else if ("EXTENDER".equals(appliedCharge)) {
			weight = Tuning.EXTENDER_WEIGHT;
		}
		final double w = weight;
		GachaState next = stateService.mutate(s -> s.withCycleProgress(s.getCycleProgress() + w));
		return next != null && next.getCycleProgress() >= next.getCycleTarget();
	}
}

package com.gachaman.service;

import com.gachaman.*;
import com.gachaman.data.*;
import com.gachaman.model.*;
import java.util.*;
import javax.inject.*;
import lombok.*;
import lombok.extern.slf4j.*;
import net.runelite.api.*;

/**
 * Computes the allowed item-id set from the loadout:
 *  - equipment card in slot S -> its exact item ids
 *  - SHINY equipment card    -> plus every lower-or-equal tier family member
 *  - HOLOGRAM in slot S      -> every item of that tier whose slot is S
 * All intersected with deeded slots. Fail-open: while the card DB is not
 * ready, nothing is ever blocked (an API hiccup must never punish a player).
 */
@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class PermissionService implements GachaStateService.Listener {
	private final GachaStateService stateService;
	private final CardDatabase cardDatabase;
	private final Client client;
	private final GachamanConfig config;

	private volatile Set<Integer> allowedItemIds = Collections.emptySet();
	private volatile Set<String> deededSlots = Collections.emptySet();

	/** Re-derive permissions from the current state (config toggles etc.). */
	public void refresh() {
		GachaState state = stateService.get();
		if (state != null)
			rebuild(state);
	}

	public void start() {
		stateService.addListener(this);
		cardDatabase.onReady(() -> {
			GachaState state = stateService.get();
			if (state != null)
				rebuild(state);
		});
	}

	public void stop() {
		stateService.removeListener(this);
	}

	@Override
	public void onStateChanged(GachaState state) {
		rebuild(state);
	}

	/** Is equipping this item forbidden by Gachaman rules right now? */
	public boolean isForbidden(int itemId) {
		if (!cardDatabase.isReady() || stateService.get() == null) {
			return false; // fail-open
		}
		if (TutorialGate.onTutorial(client)) {
			return false; // NO Gachaman locks on Tutorial Island — it force-equips items
		}
		CardDefinition card = cardDatabase.cardForItem(itemId);
		if (card == null) {
			return false; // not equipment we track
		}
		if (!deededSlots.contains(card.getSlot().name())) {
			return true; // slot itself locked
		}
		return !allowedItemIds.contains(itemId);
	}

	public boolean isSlotDeeded(GearSlot slot) {
		return deededSlots.contains(slot.name());
	}

	void rebuild(GachaState state) {
		if (!cardDatabase.isReady())
			return;
		if (!config.oneCardPerSlot()) {
			rebuildOwnershipOnly(state);
			return;
		}
		Set<Integer> allowed = new HashSet<>();
		Map<String, OwnedCard> byUuid = new HashMap<>();
		for (OwnedCard card : state.getOwnedCards()) {
			byUuid.put(card.getUuid(), card);
		}
		for (Map.Entry<String, String> entry : state.getLoadout().entrySet()) {
			GearSlot slot;
			try {
				slot = GearSlot.valueOf(entry.getKey());
			}
			catch (IllegalArgumentException e) {
				continue;
			}
			OwnedCard owned = byUuid.get(entry.getValue());
			if (owned == null)
				continue;
			allowed.addAll(itemIdsFor(owned, slot));
		}
		publish(allowed, state);
	}

	/**
	 * Swap in a freshly computed permission set. Both rebuild routes end here so
	 * the two volatiles are always written together and in the same order: a
	 * reader that saw a new allow-set against the previous deed set would, for one
	 * instant, be answering from a pair that never existed.
	 */
	private void publish(Set<Integer> allowed, GachaState state) {
		this.allowedItemIds = allowed;
		this.deededSlots = new HashSet<>(state.getDeededSlots());
	}

	/**
	 * Every item of a hologram's tier, optionally narrowed to one slot — {@code
	 * slot} null means the whole tier in every slot, which is what ownership-only
	 * permission grants.
	 */
	private void addTierIds(Set<Integer> ids, OwnedCard owned, GearSlot slot) {
		for (CardDefinition card : cardDatabase.all().values()) {
			if (owned.getTierKey().equals(card.getTierKey())
				&& (slot == null || card.getSlot() == slot)) {
				ids.addAll(card.getItemIds());
			}
		}
	}

	/**
	 * One equipment card's ids: its own, plus — for a SHINY — every lower-or-equal
	 * tier member of its family.
	 *
	 * <p>Shared by both permission routes, which is the point. The shiny ladder had
	 * this rule written out twice, and two copies of "which family members does a
	 * shiny unlock" is exactly the pair that drifts: the config toggle would then
	 * decide not just WHETHER the loadout gates gear but what a shiny is worth,
	 * and a player flipping it would watch their unlocks change for no stated
	 * reason.
	 */
	private void addCardIds(Set<Integer> ids, OwnedCard owned, CardDefinition card) {
		ids.addAll(card.getItemIds());
		if (owned.getVariant() == Variant.SHINY && card.getFamilyKey() != null) {
			for (CardDefinition member : cardDatabase.family(card.getFamilyKey())) {
				if (member.getTierRank() <= card.getTierRank())
					ids.addAll(member.getItemIds());
			}
		}
	}

	/**
	 * The item ids ONE loadout entry grants: this card, in this slot, and
	 * nothing else. This is the per-entry branch {@link #rebuild} runs in its
	 * loop, lifted out verbatim so it has exactly one definition — the union
	 * over every entry is still the whole allowed set, so nothing about
	 * rebuild's answer changed.
	 *
	 * <p>It exists because {@link #isForbidden} is the WRONG question for the
	 * unassign guard, and wrong in the way that looks right: for every id in
	 * this set isForbidden answers false, precisely BECAUSE the card is still
	 * assigned. A guard built on it would refuse nothing, ever, and pass a
	 * casual read. A dragon hologram in WEAPON with a dragon scimitar worn is
	 * the case that makes the difference visible — isForbidden says fine,
	 * this says "that scimitar is yours only while the hologram stays put".
	 *
	 * <p>Empty when the card does not belong in this slot at all, which makes
	 * "would clearing this slot strand anything?" a plain set intersection.
	 */
	public Set<Integer> itemIdsFor(OwnedCard owned, GearSlot slot) {
		Set<Integer> ids = new HashSet<>();
		if (owned == null || slot == null || !cardDatabase.isReady()) {
			return ids; // fail-open, same as every other read here
		}
		if (owned.isHologram()) {
			// tier-wide permission scoped to this slot
			addTierIds(ids, owned, slot);
			return ids;
		}
		CardDefinition card = cardDatabase.card(owned.getCardId());
		if (card != null && card.getSlot() == slot)
			addCardIds(ids, owned, card);
		return ids;
	}

	/**
	 * "One card per slot" OFF: owning a card is enough — every owned card's
	 * items are permitted with no loadout assignment. Shiny still unlocks the
	 * lower tiers of its family; a hologram unlocks its whole tier in every
	 * slot. Deed gating is unchanged.
	 */
	private void rebuildOwnershipOnly(GachaState state) {
		Set<Integer> allowed = new HashSet<>();
		for (OwnedCard owned : state.getOwnedCards()) {
			if (owned.isHologram()) {
				addTierIds(allowed, owned, null); // null slot: the whole tier, every slot
				continue;
			}
			CardDefinition card = cardDatabase.card(owned.getCardId());
			if (card != null)
				addCardIds(allowed, owned, card);
		}
		publish(allowed, state);
	}
}

package com.gachaman.service;

import com.gachaman.model.*;
import javax.inject.*;
import lombok.*;
import lombok.extern.slf4j.*;
import net.runelite.api.*;
import net.runelite.api.events.*;
import net.runelite.client.chat.*;
import net.runelite.client.eventbus.*;
import net.runelite.client.util.*;

/**
 * Combat gating: attacks are only permitted against the active task's
 * monster. With no task rolled, attacking is blocked entirely. Players are
 * never task targets, so PvP attacks are always blocked. Tutorial Island is
 * exempt. Same remove-plus-consume technique as the equipment block.
 */
@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class CombatBlockService {
	private final Client client;
	private final GachaStateService stateService;
	private final ChatMessageManager chatMessageManager;
	private final QuestExemptionService questExemptionService;

	private int lastWarnTick = -1;

	@Subscribe
	public void onMenuEntryAdded(MenuEntryAdded event) {
		MenuEntry entry = event.getMenuEntry();
		if (!isOffensiveEntry(entry.getOption(), entry.getType()))
			return;
		if (isBlocked(entry))
			client.getMenu().removeMenuEntry(entry);
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event) {
		if (!isOffensiveEntry(event.getMenuOption(), event.getMenuAction()))
			return;
		if (isBlocked(event.getMenuEntry())) {
			event.consume();
			warn();
		}
	}

	private boolean isBlocked(MenuEntry entry) {
		GachaState state = stateService.get();
		if (state == null || TutorialGate.onTutorial(client))
			return false;
		ActiveTask task = state.getActiveTask();
		NPC npc = entry.getNpc();
		if (npc == null) {
			// player (or unknown) target: never a task target
			return true;
		}
		String name = npc.getName();
		if (name != null && questExemptionService.isQuestTarget(Text.removeTags(name))) {
			return false; // an in-progress quest requires fighting this NPC
		}
		if (task == null) {
			return true; // no task rolled -> no combat at all
		}
		return name == null || !Text.removeTags(name).equalsIgnoreCase(task.getMonsterName());
	}

	private void warn() {
		int tick = client.getTickCount();
		if (tick == lastWarnTick)
			return;
		lastWarnTick = tick;
		GachaState state = stateService.get();
		String message = state != null && state.getActiveTask() != null
			? "You may only attack your contract target: "
				+ state.getActiveTask().getMonsterName() + "."
			: "You have no contract — roll one before entering combat.";
		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.CONSOLE)
			.runeLiteFormattedMessage("<col=b25be2>Gachaman:</col> " + message)
			.build());
	}

	/**
	 * Attack options, plus manual spell casts on NPCs/players ("Cast <spell>
	 * -> <target>" arrives as a WIDGET_TARGET_ON_* action — casting High
	 * Alchemy on items is a different action type and stays untouched).
	 */
	static boolean isOffensiveEntry(String option, MenuAction action) {
		if ("Attack".equals(option))
			return true;
		return option != null && option.startsWith("Cast")
			&& (action == MenuAction.WIDGET_TARGET_ON_NPC
			|| action == MenuAction.WIDGET_TARGET_ON_PLAYER);
	}
}

package com.gachaman.service;

import com.gachaman.*;
import com.gachaman.overlay.*;
import javax.inject.*;
import lombok.*;
import lombok.extern.slf4j.*;
import net.runelite.api.*;
import net.runelite.api.events.*;
import net.runelite.client.eventbus.*;

/**
 * Combat safety for modal ceremonies: if the local player takes damage or is
 * targeted while a full-canvas ceremony is consuming input, the ceremony is
 * aborted (a pending chest is still committed and summarized in chat). The
 * plugin registers this on the EventBus; only @Subscribe methods here.
 */
@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class SafeModeService {
	private final Client client;
	private final RevealOverlay revealOverlay;
	private final GachamanConfig config;

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied event) {
		if (event.getActor() != client.getLocalPlayer()
			|| event.getHitsplat() == null
			|| event.getHitsplat().getAmount() <= 0) {
			return;
		}
		abortIfModal("damage taken");
	}

	@Subscribe
	public void onInteractingChanged(InteractingChanged event) {
		if (event.getTarget() != client.getLocalPlayer()
			|| client.getLocalPlayer() == null
			|| !(event.getSource() instanceof NPC)) {
			return;
		}
		abortIfModal("targeted by an NPC");
	}

	private void abortIfModal(String reason) {
		if (!config.safeModeAbort() || !revealOverlay.isModalActive())
			return;
		log.debug("Gachaman safe-mode: aborting ceremony ({})", reason);
		revealOverlay.abortActiveCeremony();
	}
}

package com.gachaman.service;

import com.gachaman.*;
import com.gachaman.data.*;
import com.gachaman.model.*;
import java.util.*;
import javax.inject.*;
import lombok.*;
import lombok.extern.slf4j.*;

/**
 * The fortune timeline: records every roll, pull, equip and notable event as
 * a chronological audit line in state (capped). Feeds off a CeremonyBus tap,
 * the chest commit hooks, compliance events, and small hooks the plugin wires.
 */
@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class TimelineService implements ChestService.ChestListener, ComplianceService.Listener {
	private final GachaStateService stateService;
	private final CardDatabase cardDatabase;

	// --- Core recording ---

	public void record(String kind, String text, String meta) {
		recordAll(List.of(new TimelineEvent(System.currentTimeMillis(), kind, text, meta)));
	}

	public void recordAll(List<TimelineEvent> events) {
		if (events.isEmpty())
			return;
		stateService.mutate(s -> {
			List<TimelineEvent> timeline = s.getTimeline() == null
				? new ArrayList<>() : new ArrayList<>(s.getTimeline());
			timeline.addAll(events);
			while (timeline.size() > Tuning.TIMELINE_MAX_EVENTS) {
				timeline.remove(0);
			}
			return s.withTimeline(timeline);
		});
	}

	// --- CeremonyBus tap (style rolls, offers, completions, fanfares) ---

	public void onCeremony(CeremonyBus.Request request) {
		switch (request.getType()) {
			case STYLE_ROLL: {
				if (!(request.getPayload() instanceof StyleService.StyleRollResult))
					return;
				StyleService.StyleRollResult roll = (StyleService.StyleRollResult) request.getPayload();
				AttackStyle rolled = roll.getRolled();
				String was = roll.getPrevious() == null ? ""
					: " (was " + roll.getPrevious().getDisplayName() + ")";
				record(TimelineEvent.KIND_STYLE,
					"Style rolled: " + rolled.getDisplayName() + was, rolled.name());
				return;
			}
			case TASK_OFFERS: {
				if (!(request.getPayload() instanceof List))
					return;
				StringBuilder sb = new StringBuilder("Contracts rolled: ");
				boolean first = true;
				for (Object o : (List<?>) request.getPayload()) {
					if (!(o instanceof TaskOffer))
						continue;
					TaskOffer offer = (TaskOffer) o;
					if (!first)
						sb.append(", ");
					first = false;
					sb.append(offer.getMonsterName())
						.append(" (").append(offer.getDifficulty().getDisplayName()).append(')');
				}
				record(TimelineEvent.KIND_OFFERS, sb.toString(), null);
				return;
			}
			case TASK_COMPLETE: {
				if (!(request.getPayload() instanceof TaskService.TaskCompletionSummary))
					return;
				TaskService.TaskCompletionSummary sum =
					(TaskService.TaskCompletionSummary) request.getPayload();
				String monster = sum.getTask() == null ? "?" : sum.getTask().getMonsterName();
				String difficulty = sum.getTask() == null ? null : sum.getTask().getDifficulty().name();
				StringBuilder sb = new StringBuilder("Contract complete: ").append(monster)
					.append(" — +").append(sum.getCompletionGcAwarded()).append(" GC");
				if (sum.getFragmentsEarned() > 0) {
					sb.append(", +").append(sum.getFragmentsEarned()).append(" fragment")
						.append(sum.getFragmentsEarned() > 1 ? "s" : "");
				}
				if (sum.isFragmentDeedForged())
					sb.append(" — DEED FORGED");
				if (sum.getDeedMilestoneEarned() > 0)
					sb.append(" — deed milestone ").append(sum.getDeedMilestoneEarned());
				if (sum.isCycleTriggered())
					sb.append(" — style cycle complete");
				record(TimelineEvent.KIND_COMPLETE, sb.toString(), difficulty);
				return;
			}
			case FANFARE: {
				if (!(request.getPayload() instanceof CeremonyBus.Fanfare))
					return;
				CeremonyBus.Fanfare fanfare = (CeremonyBus.Fanfare) request.getPayload();
				String detail = fanfare.getDetail() == null || fanfare.getDetail().isEmpty()
					? "" : " — " + fanfare.getDetail();
				record(TimelineEvent.KIND_LUCK, fanfare.getTitle() + detail, null);
				return;
			}
			case CHEST_OPEN:
			case THEMED_CHEST: {
				// the purchase itself, logged the moment the ceremony starts
				// (cards land separately at commit, post-reroll)
				if (request.getPayload() instanceof ChestService.ChestOpenResult) {
					record(TimelineEvent.KIND_CHEST,
						chestHeader((ChestService.ChestOpenResult) request.getPayload()), null);
				}
				return;
			}
			default:
				// deed choices are recorded via their claim fanfare
		}
	}

	private static String chestHeader(ChestService.ChestOpenResult result) {
		StringBuilder sb = new StringBuilder();
		if (result.getThemedSetTag() != null)
			sb.append("Boss chest opened: ").append(result.getThemedSetTag());
		else if (result.getTargetSlot() != null) {
			sb.append("Slot chest opened: ").append(result.getTargetSlot());
		}
		else {
			sb.append("Chest opened: ").append(pretty(result.getPurchasedTier().name()));
		}
		if (result.getPricePaid() > 0)
			sb.append(" (").append(result.getPricePaid()).append(" GC)");
		if (result.isJackpotUpgraded())
			sb.append(" — JACKPOT to ").append(pretty(result.getEffectiveTier().name()));
		if (result.isPityBreak())
			sb.append(" — PITY BREAK");
		if (result.isStardustBlessed())
			sb.append(" — stardust-blessed");
		if (result.isDeedGranted())
			sb.append(" — SLOT DEED rolled");
		return sb.toString();
	}

	// --- Plugin-wired hooks ---

	public void onOfferAccepted(TaskOffer offer) {
		record(TimelineEvent.KIND_ACCEPT,
			"Contract accepted: " + offer.getKillsRequired() + "x " + offer.getMonsterName()
				+ " (" + offer.getDifficulty().getDisplayName() + ")"
				+ (offer.isPartyRoll() ? " — PARTY (shared)" : ""),
			offer.getDifficulty().name());
	}

	public void onCardAssigned(GearSlot slot, OwnedCard card) {
		record(TimelineEvent.KIND_EQUIP,
			"Equipped: " + cardName(card) + " -> " + slot.getDisplayName() + " slot", null);
	}

	public void onChargePurchased(boolean compactor, boolean voucher) {
		record(TimelineEvent.KIND_CHARGE,
			(compactor ? "Compactor" : "Extender") + " applied to the current contract"
				+ (voucher ? " (free voucher)" : ""), null);
	}

	// --- ChestService.ChestListener ---

	@Override
	public void onChestCommitted(ChestService.ChestOpenResult result, long dupeGc) {
		// the purchase header was logged at open time (ceremony tap); commit
		// logs the final cards — post-reroll, exactly what entered the album
		List<TimelineEvent> events = new ArrayList<>();
		long now = System.currentTimeMillis();
		for (ChestService.RolledSlot slot : result.getSlots()) {
			StringBuilder card = new StringBuilder("Card: ").append(slotName(slot))
				.append(" (").append(pretty(slot.getRarity().name())).append(')');
			if (slot.getVariant() == Variant.SHINY)
				card.append(" — SHINY!");
			else if (slot.getVariant() == Variant.HOLOGRAM) {
				card.append(" — HOLOGRAM!");
			}
			if (slot.isDuplicate()) {
				Integer gc = Tuning.DUPLICATE_GC.get(slot.getRarity());
				card.append(" (dupe, +").append(gc == null ? 0 : gc).append(" GC)");
			}
			events.add(new TimelineEvent(now, TimelineEvent.KIND_CARD, card.toString(),
				slot.getRarity().name()));
		}
		recordAll(events);
	}

	@Override
	public void onDeedClaimed(GearSlot slot) {
		// the claim's LARGE fanfare already lands a LUCK entry via the bus tap
	}

	@Override
	public void onRerollSpent() {
		record(TimelineEvent.KIND_REROLL, "Reroll token spent — one card re-flipped", null);
	}

	// --- ComplianceService.Listener ---

	@Override
	public void onForbiddenAttack(AttackStyle used, AttackStyle allowed, long penaltyGc) {
		record(TimelineEvent.KIND_VIOLATION,
			"Forbidden " + used.getDisplayName() + " attack (" + allowed.getDisplayName()
				+ " allowed) — -" + penaltyGc + " GC", null);
	}

	@Override
	public void onForbiddenPardoned(int tick, long refundedGc) {
		record(TimelineEvent.KIND_CLEANSE,
			"Pardoned: that attack was Magic after all — +" + refundedGc + " GC refunded", null);
	}

	@Override
	public void onTaintAdded(int newTaint) {
		record(TimelineEvent.KIND_TAINT, "Tainted kill — taint x" + newTaint, null);
	}

	@Override
	public void onTaintCleared(int cleared, int remaining) {
		if (remaining == 0)
			record(TimelineEvent.KIND_CLEANSE, "All taint cleansed", null);
	}

	// --- Helpers ---

	private String cardName(OwnedCard card) {
		if (card.isHologram()) {
			HologramDefinition holo = cardDatabase.holograms().get(card.getTierKey());
			return holo != null ? holo.getName() : "Hologram (" + card.getTierKey() + ")";
		}
		CardDefinition def = cardDatabase.card(card.getCardId());
		String name = def != null ? def.getName() : "Card #" + card.getCardId();
		return card.getVariant() == Variant.SHINY ? name + " (Shiny)" : name;
	}

	private String slotName(ChestService.RolledSlot slot) {
		if (slot.getHologramTier() != null) {
			HologramDefinition holo = cardDatabase.holograms().get(slot.getHologramTier());
			return holo != null ? holo.getName() : "Hologram (" + slot.getHologramTier() + ")";
		}
		CardDefinition def = cardDatabase.card(slot.getCardId());
		return def != null ? def.getName() : "Card #" + slot.getCardId();
	}

	/** RUSTY -> Rusty, LEGENDARY -> Legendary. */
	private static String pretty(String constant) {
		if (constant == null || constant.isEmpty())
			return "?";
		return constant.charAt(0) + constant.substring(1).toLowerCase(Locale.ROOT);
	}
}

package com.gachaman.service;

import com.gachaman.data.*;
import java.util.*;
import javax.inject.*;
import lombok.extern.slf4j.*;
import net.runelite.api.*;

/**
 * Which quest-locked monsters this account may actually be sent after.
 *
 * A quest lock is a HARD gate, like a Slayer level and unlike a combat level: a
 * contract on a monster behind an unfinished quest cannot be started at all, and
 * a Gachaman contract cannot be abandoned. So the pool is filtered before the
 * roll rather than the player being left holding it.
 *
 * Only quests that actually lock a monster in the table are ever read. That set
 * is a few dozen entries out of ~195 quests, and it decides both how many quest
 * scripts run here and how much a party roll puts on the wire.
 */
@Slf4j
@Singleton
public class QuestUnlockService {
	/**
	 * Quest state is a client script, not a field read. Recomputing the whole
	 * gating set on every panel repaint would be silly, and the only thing a
	 * stale answer can cost is a monster staying locked for another half minute
	 * after its quest is finished — it can never unlock one early, because the
	 * set only ever grows.
	 */
	private static final int CACHE_TTL_TICKS = 50;

	private final Client client;

	/** Quest names referenced by monsters.json, in a stable order. Resolved once. */
	private final List<Quest> gatingQuests;
	/** Names in gatingQuests, for the fast "is this even worth asking about" test. */
	private final Set<String> gatingNames;

	private Set<String> cached = Collections.emptySet();
	private int cachedAtTick = Integer.MIN_VALUE;

	@Inject
	public QuestUnlockService(Client client, MonsterTable monsterTable) {
		this.client = client;
		Set<String> names = new TreeSet<>();
		for (MonsterTable.Monster monster : monsterTable.getMonsters()) {
			if (monster.getQuests() != null)
				names.addAll(monster.getQuests());
		}
		List<Quest> resolved = new ArrayList<>(names.size());
		Set<String> resolvedNames = new LinkedHashSet<>();
		for (String name : names) {
			try {
				resolved.add(Quest.valueOf(name));
				resolvedNames.add(name);
			}
			catch (IllegalArgumentException e) {
				// Deliberately NOT added: a name Quest cannot resolve can never
				// enter the completed set, so every monster requiring it stays
				// locked forever. That is the safe direction, and the dataset
				// integrity test fails the build before it can ship.
				log.warn("monsters.json gates a monster on unknown quest {} — those monsters"
					+ " will never be offered", name);
			}
		}
		this.gatingQuests = Collections.unmodifiableList(resolved);
		this.gatingNames = Collections.unmodifiableSet(resolvedNames);
		log.debug("Quest gating active on {} quest(s)", resolved.size());
	}

	/**
	 * Client thread only. The gating quests this account has FINISHED.
	 *
	 * Never null: an empty set means "has finished none of them", which gates
	 * every quest-locked monster out. Null is reserved for "gating disabled" and
	 * this method does not produce it.
	 */
	public Set<String> completedQuests() {
		if (gatingQuests.isEmpty())
			return Collections.emptySet();
		int tick = client.getTickCount();
		if (cachedAtTick != Integer.MIN_VALUE && tick - cachedAtTick < CACHE_TTL_TICKS
			&& tick >= cachedAtTick) {
			return cached;
		}
		if (client.getGameState() != GameState.LOGGED_IN) {
			// Quest varbits are not populated yet, so every quest would read as
			// NOT_STARTED. Answer "none finished" — which locks quest monsters
			// rather than unlocking them — and do NOT cache it, so the first
			// call after login reads the real thing.
			return Collections.emptySet();
		}
		Set<String> finished = new HashSet<>();
		for (Quest quest : gatingQuests) {
			try {
				if (quest.getState(client) == QuestState.FINISHED)
					finished.add(quest.name());
			}
			catch (Exception e) {
				// A quest-state script hiccup is not evidence of completion.
				// Leaving it out withholds a contract; putting it in would hand
				// out one the player cannot start.
				log.debug("Quest state unavailable for {}", quest, e);
			}
		}
		cached = Collections.unmodifiableSet(finished);
		cachedAtTick = tick;
		return cached;
	}

	/**
	 * The same set as a sorted list, for the party wire.
	 *
	 * Sorted so two clients that transmit identical progress transmit identical
	 * JSON — the roll intersects these as sets and does not care about order,
	 * but a stable encoding makes a desync report readable instead of a diff of
	 * two shuffled arrays.
	 */
	public List<String> completedQuestsForWire() {
		return Collections.unmodifiableList(new ArrayList<>(new TreeSet<>(completedQuests())));
	}

	/** Quest names that lock at least one monster in the table. */
	public Set<String> gatingQuestNames() {
		return gatingNames;
	}
}

package com.gachaman.service;

import com.gachaman.data.*;
import com.gachaman.model.*;
import com.google.gson.*;
import java.util.*;
import javax.annotation.*;
import javax.inject.*;
import lombok.*;
import lombok.extern.slf4j.*;
import net.runelite.api.*;
import net.runelite.api.gameval.*;

/**
 * The weapon CATEGORY taxonomy: what the wheel may name alongside a style, and
 * whether the weapon in hand at a kill satisfies it.
 *
 * <p>Category level only, deliberately. The varbit reports a category and
 * nothing finer, so a scimitar and a longsword are the same thing to this
 * service and always will be — the wheel cannot tell them apart, so it must
 * never claim to.
 *
 * <h2>The resolution chain</h2>
 *
 * <pre>
 *   VarbitID.COMBAT_WEAPON_CATEGORY (an int, 6 bits, 0..63)
 *     -&gt; the client's own DB table 78, category int -&gt; DBROW ID
 *     -&gt; weapon-types.json, keyed on that dbrow -&gt; a {@link WeaponType}
 * </pre>
 *
 * <p><b>Keyed on dbrow ids, never on the raw varbit int.</b> The legacy
 * WeaponType int table that other plugins copy around is stale from 22 onward,
 * so anything built on it quietly names the wrong category for every weapon
 * added since. The dbrow ids are Jagex's own and are spelled as
 * {@code DBTableID.CombatInterfaceWeaponCategory.Row} constants in
 * {@code com.gachaman.tools.WeaponTypes}, where the compiler still checks every
 * name against the live API — the same arrangement {@code AttackAnims} uses for
 * the animation ids, and for the same reason: numbers in a resource are
 * unchecked, names in code are not.
 *
 * <h2>The safety property</h2>
 *
 * <p>An unrecognised category earns NO BONUS, and that is the whole design.
 * There is no default arm, no array index, no clamp into range, and no remap of
 * an unknown id onto a similar one. Every step of the chain returns null on a
 * miss and the miss propagates: a player holding a category this build has
 * never heard of simply does not get the multiplier that kill. The bonus is
 * additive to the player's fortunes and never subtractive, so failing to pay it
 * is a non-event, while paying it for the wrong weapon would make the
 * preference meaningless.
 *
 * <h2>Which thread</h2>
 *
 * <p>{@link #byCategory(int)} and {@link #satisfies(String, int, int)} touch the
 * client to read the category table, so call them from the CLIENT thread — the
 * kill path already is one. {@link #byKey}, {@link #displayName}, {@link #pool}
 * and {@link #roll} touch nothing but the loaded resource and are safe from
 * anywhere, which covers everything a panel needs; a panel that genuinely wants
 * to name the weapon in hand should read
 * {@code VarbitID.COMBAT_WEAPON_CATEGORY} on the client thread and bring the int
 * here. There is deliberately no convenience method that reads it for you: the
 * bonus is per-kill precisely so it cannot be decided by a late read of whatever
 * happens to be equipped, and a getter named for the present tense is an
 * invitation to make exactly that mistake.
 */
@Slf4j
@Singleton
public class WeaponTypeService {
	/**
	 * The one pseudo-type: casting from the autocast slot. It is not a weapon
	 * category and has no dbrow — it is {@code COM_MODE == 4}, the same signal
	 * {@link StyleTracker#resolve} reads to judge an attack MAGIC regardless of
	 * what is in hand. Modelled as a type anyway so magic's pool is not just the
	 * powered staves, and so a caller asking "does this kill satisfy the
	 * preference" gets one answer from one place.
	 */
	public static final String SPELL_CAST_KEY = "spell_cast";

	/** The dbrow of a type that has none. Real rows start in the 3900s. */
	public static final int NO_DBROW = -1;

	/**
	 * The autocast slot. Powered staves do NOT use it (they fight from com mode
	 * 0/1/3), which is exactly why they are their own category and this is its
	 * own pseudo-type.
	 */
	private static final int AUTOCAST = 4;

	/**
	 * One weapon category.
	 *
	 * <p>{@code offerIn} is the set of styles whose wheel may name this category
	 * — the hybrid staves are in MELEE <b>and</b> MAGIC on purpose, and that is
	 * what rescues magic from a two-item pool. Which mode such a staff is
	 * actually being used in is never resolved and never needs to be: the bonus
	 * pays only on a COMPLIANT kill, and the style lock already guarantees
	 * compliance, because a kill landed in the wrong style is tainted and pays
	 * zero before any multiplier is reached.
	 *
	 * <p>{@code offerable} false means the wheel may never name it, with the
	 * reason recorded in {@code reason} — a category can be excluded for being
	 * unwinnable, ambiguous, or empty of live items, and which one it was is
	 * worth keeping next to the exclusion.
	 */
	@Value
	public static class WeaponType {
		/** Stable internal id, persisted in {@code GachaState.preferredWeaponType}. */
		String key;
		/**
		 * The player-facing name. <b>Render this, never the key</b> — the key for
		 * category 0 is "unarmed", and the owner's rule is that player-facing
		 * text says "no weapon equipped", because the game reports that same
		 * category for every non-weapon held item and calling it "unarmed" would
		 * be a lie about what the player is holding.
		 */
		String displayName;
		/** {@code DBTableID.CombatInterfaceWeaponCategory.Row} id, or {@link #NO_DBROW}. */
		int dbrow;
		Set<AttackStyle> offerIn;
		boolean offerable;
		/** Why the wheel will not name it; null when it will. */
		String reason;
	}

	/**
	 * The shape of weapon-types.json. The file also carries a {@code note} key
	 * explaining how it is authored — deliberately not declared here, since Gson
	 * ignores keys it has no field for, and a resource nobody can leave a
	 * comment in should at least be allowed to carry one.
	 */
	private static class TypesFile {
		List<WeaponType> types;
	}

	private final Client client;
	private final GachaRng rng;
	private final List<WeaponType> types;
	/**
	 * The same types indexed two ways. Short names on purpose: every character
	 * of a private member is charged against the Plugin Hub's token budget at
	 * each use, and the budget is this repo's binding constraint — the type of
	 * each map already says what it is keyed on, and the javadoc says the rest.
	 *
	 * <p>{@code byRow} holds only the entries with a real dbrow, so the
	 * SPELL_CAST pseudo-type is absent from it by construction rather than by a
	 * check at lookup time. {@code keyed} holds every entry, pseudo-type
	 * included, because a persisted preference names it by key.
	 */
	private final Map<Integer, WeaponType> byRow;
	private final Map<String, WeaponType> keyed;

	/**
	 * @param rng the INJECTED singleton, never a seeded instance. The wheel's
	 *            weapon roll must not draw from the party's seeded RNG: the
	 *            party path builds its own {@code new GachaRng(seed)} and passes
	 *            it down as an argument so every client deals the same board
	 *            from one seed, and an extra draw taken from that stream by one
	 *            client and not another shifts every subsequent draw and deals
	 *            two different boards. Taking the RNG by constructor injection
	 *            rather than as a method parameter is what makes that mistake
	 *            impossible rather than merely discouraged — the seeded instance
	 *            has no route in here.
	 */
	@Inject
	WeaponTypeService(Client client, Gson gson, GachaRng rng) {
		this.client = client;
		this.rng = rng;
		TypesFile file = DataJson.load(gson, "weapon-types", TypesFile.class, new TypesFile());
		List<WeaponType> loaded = new ArrayList<>();
		Map<Integer, WeaponType> rows = new HashMap<>();
		Map<String, WeaponType> keys = new HashMap<>();
		for (WeaponType raw : file.types == null ? Collections.<WeaponType>emptyList() : file.types) {
			if (raw == null || raw.key == null)
				continue;
			// Every row is REBUILT rather than used as Gson handed it over, with
			// a non-null, immutable, null-free style set. Gson writes the final
			// fields directly, so an absent offerIn arrives as null and an
			// unrecognised style name arrives as a null ELEMENT — and the null
			// element is the nastier of the two, because contains() on a set
			// holding one still works while every enumeration over it trips.
			//
			// This was a normalised() helper with exactly one caller until the
			// token budget got tight; its signature and call site were the only
			// thing the separation bought. The argument order below is
			// load-bearing and must stay as it is: com.gachaman.tools.WeaponTypes
			// calls the same @Value all-args constructor to author the resource,
			// and WeaponTypeResourceTest compares the two by equals().
			Set<AttackStyle> styles = EnumSet.noneOf(AttackStyle.class);
			if (raw.offerIn != null) {
				for (AttackStyle style : raw.offerIn) {
					if (style != null)
						styles.add(style);
				}
			}
			WeaponType type = new WeaponType(raw.key, raw.displayName, raw.dbrow,
				Collections.unmodifiableSet(styles), raw.offerable, raw.reason);
			loaded.add(type);
			keys.put(type.key, type);
			if (type.dbrow != NO_DBROW)
				rows.put(type.dbrow, type);
		}
		this.types = Collections.unmodifiableList(loaded);
		this.byRow = Collections.unmodifiableMap(rows);
		this.keyed = Collections.unmodifiableMap(keys);
	}

	/**
	 * Category int -&gt; dbrow id, read once from the client's own DB table.
	 * Null until a COMPLETE read succeeds, which is the point: see
	 * {@link #categoryMap()}.
	 *
	 * <p>Volatile because it is published from whichever thread happens to build
	 * it first and read from the other. Today the only builder is the kill path
	 * on the client thread, but the guard is kept rather than relaxed: this field
	 * previously also backed a {@code currentForDisplay()} convenience that was
	 * dropped precisely because DBTable access from the Swing EDT is unverified,
	 * and anything that reintroduces an EDT reader must not have to rediscover
	 * why the publication needs to be safe. The race itself is
	 * benign — both would build the same map and one would win — but publishing a
	 * HashMap through a non-volatile field can hand the other thread a
	 * half-constructed one, and this is the same guard {@code CardDatabase} puts
	 * on the maps it builds once and reads everywhere.
	 */
	private volatile Map<Integer, Integer> cache;

	/** So an incomplete table is reported once, not once per kill. */
	private boolean warned;

	/**
	 * The client's category-to-dbrow table, or an empty map while it cannot be
	 * read at all.
	 *
	 * <p>The read is CACHED only when every row yielded a category int, and USED
	 * either way. Both halves of that matter, and they guard opposite failures:
	 *
	 * <ul>
	 * <li>Caching a partial read would freeze it. At login the cache is still
	 * loading and a row's field can come back null; a partial map cached there
	 * would leave those categories unresolvable for the rest of the session, and
	 * the player would see the bonus pay for some weapons and silently not for
	 * others with nothing to explain it.
	 * <li>DISCARDING a partial read would be worse, because it is total rather
	 * than partial. If some row in table 78 legitimately carries no value in this
	 * column, an exact-match requirement would never be met, the map would never
	 * cache, and the bonus would never pay for anybody — one debug line the only
	 * trace. Nothing here can verify that every row carries one, so this does not
	 * bet the feature on it.
	 * </ul>
	 *
	 * <p>So an incomplete read is returned unmemoised: a transient one heals on
	 * the next call and then caches for good, and a permanent one costs a walk of
	 * three dozen rows per lookup and still pays out for every category that does
	 * resolve. Warned at WARN and once only — debug is off for the player who
	 * would be reporting "the weapon bonus never pays", and a per-kill warning
	 * would drown their log instead of helping it.
	 */
	private Map<Integer, Integer> categoryMap() {
		// Read twice rather than into a local, which is safe here only because the
		// field is MONOTONIC: it is written exactly once, from null to a complete
		// unmodifiable map, and the write happens only on the path where the read
		// above saw null. So a non-null first read cannot be followed by a null
		// second one. Two threads racing can each write, but they write maps of
		// identical content, so which one a reader lands on is not observable.
		// Do not copy this shortening to a field that can ever be reset to null.
		if (cache != null)
			return cache;
		if (client == null)
			return Collections.emptyMap();
		try {
			List<Integer> rows = client.getDBTableRows(DBTableID.CombatInterfaceWeaponCategory.ID);
			if (rows == null || rows.isEmpty()) {
				return Collections.emptyMap(); // cache not loaded yet — normal, try again later
			}
			Map<Integer, Integer> map = new HashMap<>();
			for (Integer row : rows) {
				if (row == null)
					continue;
				Object[] field = client.getDBTableField(row,
					DBTableID.CombatInterfaceWeaponCategory.COL_ID, 0);
				if (field == null || field.length == 0 || !(field[0] instanceof Number))
					continue;
				map.put(((Number) field[0]).intValue(), row);
			}
			if (map.size() != rows.size()) {
				if (!warned) {
					warned = true;
					log.warn("weapon category table incomplete ({} of {} rows readable) —"
						+ " using it without caching; the preferred weapon bonus will not"
						+ " pay for the categories it is missing", map.size(), rows.size());
				}
				return Collections.unmodifiableMap(map);
			}
			cache = Collections.unmodifiableMap(map);
			return cache;
		}
		catch (Exception e) {
			log.debug("weapon category table unreadable", e);
			return Collections.emptyMap();
		}
	}

	/** Every type in the taxonomy, offerable or not, in resource order. */
	public List<WeaponType> all() {
		return types;
	}

	/**
	 * The type a raw {@code COMBAT_WEAPON_CATEGORY} value names, or null when
	 * this build cannot name it — an unmapped int, an unknown dbrow, or a
	 * category table that is not readable yet. Null means no bonus, always.
	 */
	@Nullable
	public WeaponType byCategory(int cat) {
		return byCategory(categoryMap(), cat);
	}

	/**
	 * Pure form, taking the table as an argument.
	 *
	 * <p>Split out for the same reason {@code StyleTracker.resolve} is: the
	 * service around it needs a live Client to read the table at all, so the
	 * behaviour that actually matters — that an unrecognised category resolves
	 * to NOTHING — could not otherwise be tested at all.
	 *
	 * @param table the category-int to dbrow mapping, normally {@link #categoryMap()}
	 * @param cat   a raw {@code COMBAT_WEAPON_CATEGORY} value
	 */
	@Nullable
	WeaponType byCategory(Map<Integer, Integer> table, int cat) {
		Integer dbrow = table.get(cat);
		return dbrow == null ? null : byRow.get(dbrow);
	}

	/**
	 * The type a persisted key names, or null when this build no longer knows it
	 * — a preference saved before the taxonomy changed resolves to nothing,
	 * which is no bonus rather than a wrong one.
	 */
	@Nullable
	public WeaponType byKey(String key) {
		return key == null ? null : keyed.get(key);
	}

	/**
	 * The player-facing name for a persisted key, or null when it no longer
	 * resolves (render nothing rather than a raw key). Always the route to text:
	 * see {@link WeaponType#getDisplayName()} for why the key must never be
	 * shown.
	 */
	@Nullable
	public String displayName(String key) {
		WeaponType type = byKey(key);
		return type == null ? null : type.displayName;
	}

	/**
	 * Does a kill landed with this weapon satisfy the preference?
	 *
	 * <p>The caller passes the category and com mode SAMPLED AT THE KILLING
	 * BLOW, never read fresh here — the bonus is per-kill precisely so it cannot
	 * be earned by swapping the preferred weapon in after the fight.
	 *
	 * @param pref {@code GachaState.preferredWeaponType}; null (no preference
	 *             live) is false, never an error
	 * @param cat  the raw {@code COMBAT_WEAPON_CATEGORY} at the killing blow
	 * @param mode the com mode at the killing blow; 4 is the autocast slot
	 */
	public boolean satisfies(String pref, int cat, int mode) {
		return satisfies(categoryMap(), pref, cat, mode);
	}

	/** Pure form, taking the table as an argument. See {@link #byCategory(Map, int)}. */
	boolean satisfies(Map<Integer, Integer> table, String pref, int cat, int mode) {
		WeaponType preferred = byKey(pref);
		if (preferred == null)
			return false;
		// Both comparisons below read pref where they once read preferred.key.
		// That is the same string, not a shortcut: keyed is populated as
		// put(type.key, type), so a hit means the stored key equalled the lookup
		// key. Compared by equals() rather than by == on the two WeaponType
		// objects on purpose — reference identity would hold only because a test
		// pins keys unique, and that is a behavioural dependency this file should
		// not be leaning on from the outside.
		if (SPELL_CAST_KEY.equals(pref)) {
			// the pseudo-type: the autocast slot and nothing else. A powered
			// staff casting from com mode 0/1/3 is NOT this — it is its own
			// category, and has its own entry to be named by
			return mode == AUTOCAST;
		}
		WeaponType inHand = byCategory(table, cat);
		return inHand != null && inHand.key.equals(pref);
	}

	/**
	 * The categories this style's wheel may name, in resource order.
	 *
	 * <p>Order is the resource's, so a seeded roll is reproducible from the
	 * shipped file alone.
	 */
	public List<WeaponType> pool(AttackStyle style) {
		List<WeaponType> pool = new ArrayList<>();
		for (WeaponType type : types) {
			if (type.offerable && type.offerIn.contains(style))
				pool.add(type);
		}
		return Collections.unmodifiableList(pool);
	}

	/**
	 * Name a preferred category for this style, uniformly from its pool. Null
	 * only if the pool is empty, which means the resource failed to load — and
	 * no preference is the correct degradation, since the bonus is a bonus.
	 */
	@Nullable
	public WeaponType roll(AttackStyle style) {
		List<WeaponType> pool = pool(style);
		return pool.isEmpty() ? null : rng.pick(pool);
	}
}

package com.gachaman.service;

import com.gachaman.model.*;
import com.gachaman.persist.*;
import java.util.*;
import java.util.function.*;
import javax.annotation.*;
import javax.inject.*;
import lombok.*;
import lombok.extern.slf4j.*;

/**
 * Owner of the volatile state snapshot. Every mutation is a synchronized
 * pure-function application that persists the result and notifies listeners.
 */
@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class GachaStateService {
	public interface Listener {
		void onStateChanged(GachaState newState);
	}

	private final StateStore store;
	private final List<Listener> listeners = new ArrayList<>();

	private volatile GachaState state;
	@Getter
	private volatile boolean loaded;

	@Nullable
	public GachaState get() {
		return state;
	}


	/** Load for the current RS profile; creates fresh state when none exists. */
	public synchronized void load(int combatLevel) {
		GachaState s = store.load();
		if (s == null) {
			s = GachaState.fresh(combatLevel);
			log.info("Gachaman: fresh profile state created (cb {})", combatLevel);
		}
		else {
			// older saves: fields added since deserialize as null
			s = s.normalized();
		}
		state = s;
		loaded = true;
		notifyListeners(s);
	}

	public synchronized void unload() {
		if (loaded && state != null)
			store.save(state, true);
		state = null;
		loaded = false;
	}

	/**
	 * Drop the in-memory state WITHOUT saving. Used on RS profile switches:
	 * RuneScapeProfileChanged fires after the profile key has already moved,
	 * so saving here would write the old account's state under the new key.
	 */
	public synchronized void discard() {
		state = null;
		loaded = false;
	}

	/** Apply a pure mutation, persist, notify. No-op when not loaded. */
	public synchronized GachaState mutate(UnaryOperator<GachaState> fn) {
		if (!loaded || state == null)
			return null;
		GachaState next = fn.apply(state);
		if (next == null || next == state)
			return state;
		state = next;
		store.save(next);
		notifyListeners(next);
		return next;
	}

	/** Force a save of the current snapshot (logout/shutdown checkpoints). */
	public synchronized void checkpoint() {
		if (loaded && state != null)
			store.save(state, true);
	}

	public synchronized void addListener(Listener l) {
		listeners.add(l);
	}

	public synchronized void removeListener(Listener l) {
		listeners.remove(l);
	}

	private void notifyListeners(GachaState s) {
		Listeners.fire(listeners, l -> l.onStateChanged(s), "Gachaman state listener failed");
	}
}

package com.gachaman.service;

import com.gachaman.*;
import com.gachaman.model.*;
import java.util.*;
import javax.annotation.*;
import javax.inject.*;
import lombok.*;
import lombok.extern.slf4j.*;
import net.runelite.api.*;

/**
 * The Firsts Journal: listens across the task/chest/compliance layers and
 * claims each {@link FirstStamp} exactly once, paying a small bounty with a
 * fanfare whose detail line teaches the rule that was just touched.
 */
@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class FirstsService implements TaskService.Listener, ComplianceService.Listener,
	ChestService.ChestListener {
	private final GachaStateService stateService;
	private final CreditSink creditSink;
	private final CeremonyBus ceremonyBus;
	@Nullable
	private final Client client;

	/** Claim-once core. Returns true when newly claimed. */
	public synchronized boolean claim(FirstStamp stamp) {
		GachaState state = stateService.get();
		if (state == null || alreadyClaimed(state.getFirstsClaimed(), stamp))
			return false;
		// stamp + bounty land in ONE mutate: an unload/profile switch can
		// never mark the once-ever stamp claimed while swallowing its GC
		CreditSink.AwardResult result = creditSink.awardWith(Tuning.FIRSTS_GC.get(stamp),
			new CreditSink.GcContext(CreditSink.Source.FIRST, null, null),
			s -> {
				Set<String> next = s.getFirstsClaimed() == null
					? new HashSet<>() : new HashSet<>(s.getFirstsClaimed());
				return next.add(stamp.name()) ? s.withFirstsClaimed(next) : s;
			});
		if (result.getState() == null || result.getState().getFirstsClaimed() == null
			|| !result.getState().getFirstsClaimed().contains(stamp.name())) {
			return false;
		}
		ceremonyBus.submit(CeremonyBus.Type.FANFARE, new CeremonyBus.Fanfare(
			CeremonyBus.Fanfare.Size.SMALL, "First: " + stamp.getDisplayName(),
			stamp.getExplainer() + "  +" + result.getAmount() + " GC", null));
		return true;
	}

	static boolean alreadyClaimed(Set<String> claimed, FirstStamp stamp) {
		return claimed != null && claimed.contains(stamp.name());
	}

	/**
	 * Pure mapper for chest commits: which stamps do these revealed slots
	 * touch? EPIC matches Epic-or-better (the pity-reset rule its explainer
	 * teaches); holograms count for rarity and dupes but never shiny.
	 */
	static List<FirstStamp> stampsForSlots(List<ChestService.RolledSlot> slots) {
		List<FirstStamp> stamps = new ArrayList<>();
		for (ChestService.RolledSlot slot : slots) {
			if (slot.getRarity() == Rarity.UNCOMMON && !stamps.contains(FirstStamp.FIRST_UNCOMMON))
				stamps.add(FirstStamp.FIRST_UNCOMMON);
			if (slot.getRarity() == Rarity.RARE && !stamps.contains(FirstStamp.FIRST_RARE))
				stamps.add(FirstStamp.FIRST_RARE);
			if (slot.getRarity().atLeast(Rarity.EPIC) && !stamps.contains(FirstStamp.FIRST_EPIC))
				stamps.add(FirstStamp.FIRST_EPIC);
			if (slot.getVariant() == Variant.SHINY && !stamps.contains(FirstStamp.FIRST_SHINY))
				stamps.add(FirstStamp.FIRST_SHINY);
			if (slot.isDuplicate() && !stamps.contains(FirstStamp.FIRST_DUPE))
				stamps.add(FirstStamp.FIRST_DUPE);
		}
		return stamps;
	}

	// --- TaskService.Listener ---

	@Override
	public void onKillFeedback(TaskService.KillFeedback feedback) {
		if (client != null && TutorialGate.onTutorial(client))
			return;
		claim(FirstStamp.FIRST_KILL);
	}

	@Override
	public void onSideBetHit(SideBet bet, String monsterName) {
		claim(FirstStamp.FIRST_SIDE_BET);
	}

	@Override
	public void onTaskCompleted(TaskService.TaskCompletionSummary summary) {
		claim(FirstStamp.FIRST_TASK);
		if (summary.isNewFastestPb() || summary.isNewHaulPb())
			claim(FirstStamp.FIRST_RECORD);
		if (summary.isCycleTriggered())
			claim(FirstStamp.FIRST_CYCLE);
	}


	// --- ComplianceService.Listener ---

	@Override
	public void onForbiddenAttack(AttackStyle used, AttackStyle allowed, long penaltyGc) {
	}


	@Override
	public void onTaintCleared(int cleared, int remaining) {
		claim(FirstStamp.FIRST_TAINT_CLEARED);
	}

	// --- ChestService.ChestListener ---

	@Override
	public void onChestCommitted(ChestService.ChestOpenResult result, long dupeGc) {
		claim(FirstStamp.FIRST_CHEST);
		for (FirstStamp stamp : stampsForSlots(result.getSlots())) {
			claim(stamp);
		}
	}

	@Override
	public void onDeedClaimed(GearSlot slot) {
		claim(FirstStamp.FIRST_DEED);
	}

	@Override
	public void onRerollSpent() {
		claim(FirstStamp.FIRST_REROLL_SPENT);
	}

	// --- Loadout hook (wired by the plugin) ---

	public void onCardAssigned(OwnedCard card) {
		// starter gear is auto-assigned on fresh load — never stamp without
		// an actual player action
		if (!"starter".equals(card.getProvenance()))
			claim(FirstStamp.FIRST_ASSIGN);
	}
}

package com.gachaman.service;

import net.runelite.api.gameval.InventoryID;
import com.gachaman.*;
import com.gachaman.data.*;
import com.gachaman.model.*;
import java.util.*;
import javax.inject.*;
import lombok.*;
import lombok.extern.slf4j.*;
import net.runelite.api.*;
import net.runelite.api.events.*;
import net.runelite.api.gameval.*;
import net.runelite.client.callback.*;
import net.runelite.client.eventbus.*;

/**
 * Graduation Ceremony: the first time each gear slot's WORN tier rank climbs
 * (bronze to iron, iron to steel...) a fanfare fires with a small GC grant —
 * but only while the new rank stays within the early band. The first rank
 * ever recorded for a slot is a silent baseline, so equipping starter bronze
 * (or logging in on an endgame account) celebrates nothing.
 */
@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class GraduationService {
	private final Client client;
	private final ClientThread clientThread;
	private final GachaStateService stateService;
	private final CardDatabase cardDatabase;
	private final CreditSink creditSink;
	private final CeremonyBus ceremonyBus;

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event) {
		if (event.getContainerId() != InventoryID.WORN)
			return;
		process(event.getItemContainer());
	}

	/**
	 * Post-load catch-up: equipment worn at login may never fire a container
	 * change, so the plugin calls this once the card DB is ready to seed the
	 * baseline (silently, when a slot has no recorded rank yet).
	 */
	public void refresh() {
		clientThread.invokeLater(() -> process(client.getItemContainer(InventoryID.WORN)));
	}

	private void process(ItemContainer container) {
		GachaState state = stateService.get();
		if (container == null || state == null || state.getSlotBestTierRank() == null
			|| !cardDatabase.isReady()) {
			return;
		}
		Map<String, Integer> best = state.getSlotBestTierRank();
		Map<String, Integer> updates = new HashMap<>();
		// slot name -> the card that caused a CELEBRATED rank-up (not baselines)
		Map<String, CardDefinition> graduations = new HashMap<>();
		for (Item item : container.getItems()) {
			if (item == null || item.getId() <= 0)
				continue;
			CardDefinition def = cardDatabase.cardForItem(item.getId());
			if (def == null || def.getSlot() == null || def.getTierKey() == null
				|| def.getTierRank() <= 0) {
				continue; // untiered gear never graduates
			}
			String slotKey = def.getSlot().name();
			Integer prev = updates.containsKey(slotKey) ? updates.get(slotKey) : best.get(slotKey);
			if (prev == null) {
				updates.put(slotKey, def.getTierRank()); // silent baseline
				continue;
			}
			if (def.getTierRank() > prev) {
				updates.put(slotKey, def.getTierRank());
				if (def.getTierRank() <= Tuning.GRADUATION_MAX_RANK)
					graduations.put(slotKey, def);
			}
		}
		if (updates.isEmpty())
			return;
		stateService.mutate(s -> {
			if (s.getSlotBestTierRank() == null)
				return s;
			Map<String, Integer> map = new HashMap<>(s.getSlotBestTierRank());
			for (Map.Entry<String, Integer> entry : updates.entrySet()) {
				Integer existing = map.get(entry.getKey());
				if (existing == null || entry.getValue() > existing)
					map.put(entry.getKey(), entry.getValue());
			}
			return s.withSlotBestTierRank(map);
		});
		for (Map.Entry<String, CardDefinition> entry : graduations.entrySet()) {
			CardDefinition def = entry.getValue();
			creditSink.award(Tuning.GRADUATION_GC,
				new CreditSink.GcContext(CreditSink.Source.GRADUATION, null, null));
			ceremonyBus.submit(CeremonyBus.Type.FANFARE, new CeremonyBus.Fanfare(
				CeremonyBus.Fanfare.Size.MEDIUM, "Tier up: " + def.getName(),
				"Your " + def.getSlot().getDisplayName().toLowerCase()
					+ " gear graduates to " + def.getTierKey() + " — +" + Tuning.GRADUATION_GC + " GC",
				def.getCardId()));
		}
	}
}

package com.gachaman.service;

// COLLISION RESOLVER, do not "tidy" into the java.util.* wildcard below: RuneLite
// ships its own net.runelite.api.Deque (the client's linked-list container), which
// the net.runelite.api.* wildcard also drags in, and the two make the bare name
// ambiguous. The single-class import outranks both wildcards and picks java.util's.
import java.util.Deque;
import com.gachaman.*;
import com.gachaman.data.*;
import com.gachaman.model.*;
import java.util.*;
import java.util.function.*;
import javax.annotation.*;
import javax.inject.*;
import lombok.*;
import lombok.extern.slf4j.*;
import net.runelite.api.*;
import net.runelite.api.coords.*;
import net.runelite.api.gameval.*;

/**
 * The kill-task engine: offer rolls, acceptance, per-kill crediting with
 * taint rules, side bets, completion rewards, journal/PBs, style-cycle
 * advancement and deed milestones.
 */
@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class TaskService implements KillTracker.KillListener, ComplianceService.Listener,
	StyleTracker.AttackListener {
	@Value
	public static class TaskCompletionSummary {
		ActiveTask task;
		long completionGcAwarded;
		int sideBetsHit;
		long taskDurationMs;
		boolean newFastestPb;
		boolean newHaulPb;
		boolean redemptionCleared;
		boolean cycleTriggered;
		int deedMilestoneEarned; // 0 = none, else the milestone task count
		int fragmentsEarned;     // Deed Fragments granted by THIS completion
		int fragmentsTotal;      // running fragment count after this completion
		boolean fragmentDeedForged; // this completion forged the fragment deed
		/** Lifetime contract number this completion was, counting from 1. */
		int taskNumber;
		/** Slayer-style milestone multiple this completion paid; 1.0 = ordinary. */
		double completionMilestoneMult;
	}

	@Value
	public static class KillFeedback {
		String monsterName;
		long gcAwarded;      // 0 for tainted / off-task
		boolean onTask;
		boolean tainted;
		boolean finalKill;
		int killsDone;
		int killsRequired;
		/** The ironman assisted-kill penalty applied (half count, half GC). */
		boolean assistedHalfCredit;
		LocalPoint deathLocation;
	}

	/**
	 * Pure kill-count advance rule: a Compactor doubles the count, the ironman
	 * assisted-kill penalty halves it — an assisted normal kill banks/redeems
	 * a pending half (two assisted kills = one count), an assisted Compactor
	 * kill lands back on exactly 1.
	 */
	@Value
	public static class KcAdvance {
		int increment;
		boolean halfPending;
	}

	static KcAdvance kcAdvance(boolean compactor, boolean assistedPenalty, boolean pendingHalf) {
		if (!assistedPenalty)
			return new KcAdvance(compactor ? 2 : 1, pendingHalf);
		if (compactor) {
			return new KcAdvance(1, pendingHalf); // 2 x 0.5
		}
		return pendingHalf ? new KcAdvance(1, false) : new KcAdvance(0, true);
	}

	/**
	 * The ironman honor rule halves assisted kills — but on a shared party
	 * contract teammates are EXPECTED to pile onto the same monsters, so
	 * their "assists" are just the party playing together (hitsplats cannot
	 * be attributed to a specific player, so the whole rule stands down while
	 * the contract is shared). It re-arms the moment the carry clause
	 * converts the contract back to solo.
	 */
	static boolean assistedPenaltyApplies(boolean ironman, boolean assistedByOther, ActiveTask task) {
		return ironman && assistedByOther && (task == null || !task.isParty());
	}

	/**
	 * The Ante's stake: a percent of the purse, clamped to the legal band and to
	 * the absolute cap, floored to whole GC.
	 *
	 * Returns 0 — meaning "no wager is offered" — for a purse under the floor.
	 * That is not a rounding accident: at 200 GC the minimum stake is 20, which
	 * is not a risk worth a confirmation dialog, and a player who is that broke
	 * is the one least able to absorb it.
	 */
	public static int anteStakeFor(long gc, int percent) {
		if (gc < Tuning.ANTE_MIN_PURSE_GC || percent <= 0)
			return 0;
		int pct = Math.max(Tuning.ANTE_MIN_PERCENT, Math.min(Tuning.ANTE_MAX_PERCENT, percent));
		long stake = Math.min(gc * pct / 100, Tuning.ANTE_MAX_GC);
		// can only ever bind by the cap, never by the purse (pct <= 50), but the
		// clamp is kept so a future band change cannot overdraw the account
		return (int) Math.max(0, Math.min(stake, gc));
	}

	/**
	 * The Ante rides on the hardest contracts ONLY. A wager the player can take
	 * on an easy contract is a wager with no downside worth speaking of, and the
	 * point of this one is that INSANE contracts are where dying is plausible.
	 */
	public static boolean anteEligible(TaskOffer offer) {
		return offer != null && offer.getDifficulty() == TaskDifficulty.INSANE;
	}

	/**
	 * Optional hooks default to no-ops: most listeners care about exactly one
	 * of them, and four empty bodies per implementor is noise that hides which
	 * ones a class actually acts on.
	 *
	 * <p>{@link #onTaskCompleted} is deliberately NOT defaulted. It is the hook
	 * that books rewards and records service, so a new listener that forgets it
	 * should fail to compile rather than silently drop them.
	 */
	public interface Listener {
		default void onKillFeedback(KillFeedback feedback) {
		}

		default void onSideBetHit(SideBet bet, String monsterName) {
		}

		void onTaskCompleted(TaskCompletionSummary summary);

		default void onOffersRolled(List<TaskOffer> offers) {
		}

		/** Party hook: local player progressed a shared party contract. */
		default void onPartyProgress(ActiveTask task) {
		}
	}

	private final Client client;
	private final GachaStateService stateService;
	private final CreditSink creditSink;
	private final ComplianceService complianceService;
	private final StyleService styleService;
	private final CeremonyBus ceremonyBus;
	private final GachaRng rng;
	private final MonsterTable monsterTable;
	private final QuestUnlockService questUnlockService;
	private final MaxHitService maxHitService;
	/**
	 * The Preferred Weapon pair. StyleTracker is asked what was in hand at the
	 * killing blow (never what is in hand now — see {@link #weaponMultFor}), and
	 * WeaponTypeService decides whether that satisfies the wheel's named category.
	 *
	 * <p>Declared LAST on purpose: Lombok builds the constructor in field order,
	 * so appending here leaves every existing positional call site — all of them
	 * headless tests — able to say what it always said plus the new arguments.
	 */
	private final StyleTracker styleTracker;
	private final WeaponTypeService weaponTypeService;
	/**
	 * The Consignment, which owns the moment a style roll comes due. Injected
	 * rather than hooked (the four @Setter hooks above exist so the payout path
	 * stays testable without a Client) because this one is not optional: a
	 * completion that silently skipped it would drop the deferred roll AND the
	 * feature, and Guice refusing to build the service is a far better failure
	 * than a wheel that quietly never offers.
	 */
	private final ConsignmentService consignmentService;

	private final List<Listener> listeners = new ArrayList<>();
	/** Optional hook the plugin wires for the party layer. */
	@Setter
	private Consumer<TaskOffer> offerAcceptedHook;
	/** Party layer: clicking a party-roll offer casts a VOTE instead of accepting. */
	@Setter
	private IntConsumer partyVoteHook;
	/**
	 * Double Docket: supplies the live Slayer assignment name, or null. A hook
	 * rather than an injected dependency so the whole payout path stays testable
	 * without a Client — every unit test leaves it unwired and gets no bonus.
	 */
	@Setter
	private Supplier<String> slayerTargetHook;
	/** Double Docket: fired once, the moment a contract latches on to the bonus. */
	@Setter
	private Runnable slayerLatchHook;
	/** Recent credited kill ticks for SPEED_KILLS side bets. */
	private final Deque<Integer> recentKillTicks = new ArrayDeque<>();
	/** Tick of the most recent kill; completeTask runs inside onKill so this is "now". */
	private int lastKillTick;
	/** Monster name -> tags, built lazily from the table. */
	private Map<String, List<String>> tagsByMonster;

	// Rhythm Combo (transient, never persisted): consecutive on-task kills
	// within the window build stacks; a forbidden attack breaks it, and it
	// cancels only after the idle window passes with NO attacks at all —
	// fighting a tanky monster keeps the chain alive even between kills.
	/** Compliant kills banked on the running chain; stacks are earned from these. */
	private int comboKills;
	/**
	 * Last activity (kill OR attack) keeping the chain alive, or -1 for no
	 * chain. Only a kill starts one; attacks merely hold an existing chain
	 * open, which is why this doubles as the "is a chain running" sentinel.
	 */
	private int comboIdleAnchorTick = -1;

	/**
	 * The Ante: the percent the player armed for the contract in front of them,
	 * or 0 for "no wager". Deliberately TRANSIENT and deliberately cleared the
	 * moment a contract is signed or a fresh set of offers arrives — arming is a
	 * decision about one specific board, and a stake that survived a logout or a
	 * re-roll would be a wager the player does not remember making.
	 *
	 * volatile: the panel arms it on the Swing thread, the accept path reads it
	 * on the client thread.
	 */
	private volatile int antePercentArmed;

	public void addListener(Listener listener) {
		if (!listeners.contains(listener))
			listeners.add(listener);
	}

	public void removeListener(Listener listener) {
		listeners.remove(listener);
	}

	/**
	 * The contract in force, or null. Deliberately conflates "no state loaded"
	 * with "no contract": every caller of this already treated the two the same
	 * way, and one read of the snapshot means the thing tested and the thing
	 * used are the same object by construction.
	 *
	 * NOT usable where the two cases must be told apart — canRollOffers must say
	 * "no" while the state is still loading, and onKill must not journal a kill
	 * against a state that does not exist yet.
	 */
	@Nullable
	private ActiveTask activeTask() {
		GachaState state = stateService.get();
		return state == null ? null : state.getActiveTask();
	}

	/**
	 * The offers sitting on the board, never null. A missing state and a missing
	 * list both mean "the board is empty", which is exactly what each caller's
	 * old null test spelled out by hand. The state's OWN list comes back
	 * unchanged when there is one, so a caller that hands it to the ceremony bus
	 * still passes the same instance it always did.
	 */
	private List<TaskOffer> pending() {
		GachaState state = stateService.get();
		List<TaskOffer> offers = state == null ? null : state.getPendingOffers();
		return offers == null ? List.of() : offers;
	}

	/**
	 * The live Slayer assignment, or null. Swallows hook failures: a broken
	 * Slayer read must cost the player a bonus, never a kill credit.
	 */
	@Nullable
	private String liveSlayerTarget() {
		if (slayerTargetHook == null)
			return null;
		try {
			return slayerTargetHook.get();
		}
		catch (Exception e) {
			log.warn("slayer target hook failed", e);
			return null;
		}
	}

	// --- The Ante ---

	/**
	 * Arm (or, with 0, disarm) the wager for the offers currently on the board.
	 * Arming alone stakes nothing: the GC only leaves the purse when a contract
	 * is actually signed, and only if the contract turns out to be eligible.
	 */
	public void armAnte(int percent) {
		antePercentArmed = percent <= 0 ? 0
			: Math.max(Tuning.ANTE_MIN_PERCENT, Math.min(Tuning.ANTE_MAX_PERCENT, percent));
	}

	public int getArmedAntePercent() {
		return antePercentArmed;
	}

	public boolean anteArmed() {
		return antePercentArmed > 0;
	}

	/** What the armed percent would stake against the purse right now, or 0. */
	public int previewAnteStake() {
		return previewAnteStake(antePercentArmed);
	}

	/** What a percent WOULD stake right now. Arms nothing — a preview only. */
	public int previewAnteStake(int percent) {
		GachaState state = stateService.get();
		return state == null ? 0 : anteStakeFor(state.getGc(), percent);
	}

	/** GC currently escrowed on the active contract, or 0. */
	public int getActiveAnteStake() {
		ActiveTask task = activeTask();
		return task == null ? 0 : task.getAnteStake();
	}

	/**
	 * The local player died. The stake is already out of the purse (escrowed at
	 * accept), so losing it is simply never giving it back: zero the escrow and
	 * the completion path has nothing to return.
	 *
	 * Guarded inside the mutate rather than around it, so a contract completing
	 * on the same tick cannot be charged twice — and a death with nothing staked
	 * returns the identical state instance, which costs no re-encode.
	 */
	@Override
	public void onLocalPlayerDeath() {
		final int[] lost = {0};
		stateService.mutate(s -> {
			ActiveTask task = s.getActiveTask();
			if (task == null || task.getAnteStake() <= 0)
				return s;
			lost[0] = task.getAnteStake();
			return s.withActiveTask(task.withAnteStake(0));
		});
		if (lost[0] > 0) {
			fanfare(CeremonyBus.Fanfare.Size.MEDIUM, "The Ante is lost",
				lost[0] + " GC staked on this contract is gone. The contract stands.");
		}
	}

	// --- Offers ---

	public boolean canRollOffers() {
		GachaState state = stateService.get();
		return state != null && state.getActiveTask() == null
			&& (state.getPendingOffers() == null || state.getPendingOffers().isEmpty());
	}

	/** Are rolled-but-undecided offers waiting? */
	public boolean hasPendingOffers() {
		return !pending().isEmpty();
	}

	/**
	 * Are the waiting offers party-flagged (clicking VOTES rather than accepts)?
	 * Deliberately the SAME first-element convention demotePartyOffers uses, so
	 * the predicate and the demotion can never disagree about a given offer set.
	 */
	public boolean hasPendingPartyOffers() {
		List<TaskOffer> offers = pending();
		return !offers.isEmpty() && offers.get(0).isPartyRoll();
	}

	/** Re-present the already-rolled offers (Esc'd earlier) — never re-rolls. */
	public boolean presentOffers() {
		List<TaskOffer> offers = pending();
		if (offers.isEmpty())
			return false;
		ceremonyBus.submit(CeremonyBus.Type.TASK_OFFERS, offers);
		return true;
	}

	/**
	 * Put a freshly decided offer set on the board: disarm the wager, persist the
	 * offers, present them and tell the listeners. Shared by the personal roll and
	 * by the party layer's installer so the two can never drift — a board that
	 * kept a stale arming, or one the panel never heard about, would be a bug
	 * visible only on whichever of the two paths forgot a line.
	 */
	private void installOffers(List<TaskOffer> offers) {
		antePercentArmed = 0; // a new board is a new decision
		stateService.mutate(s -> s.withPendingOffers(offers));
		ceremonyBus.submit(CeremonyBus.Type.TASK_OFFERS, offers);
		for (Listener listener : listeners) {
			listener.onOffersRolled(offers);
		}
	}

	/** Personal roll (party rolls go through the party layer's agreement flow). */
	@Nullable
	public List<TaskOffer> rollOffers() {
		GachaState state = stateService.get();
		if (state == null || state.getActiveTask() != null || hasPendingOffers()) {
			// existing offers must be decided (or viewed again) — no free rerolls
			return null;
		}
		List<TaskOffer> offers = TaskGenerator.generateOffers(
			monsterTable.getMonsters(), playerCombatLevel(), lvl(Skill.SLAYER),
			localIsMembers(), questUnlockService.completedQuests(), state.getTaint() > 0,
			maxHitService.estimateFor(state.getAllowedStyle()),
			// solo: the wheel has locked THIS player, and their style is always
			// known, so a melee-unreachable contract can never be dealt here
			AttackStyle.MELEE.name().equals(state.getAllowedStyle()), rng);
		installOffers(offers);
		return offers;
	}

	/**
	 * Members world AND an actual membership on the account (ACCOUNT_CREDIT =
	 * membership days remaining) — free accounts never see members tasks. The
	 * party layer shares this in its roll handshake.
	 */
	public boolean localIsMembers() {
		return client != null && client.getWorldType().contains(WorldType.MEMBERS)
			&& client.getVarpValue(VarPlayerID.ACCOUNT_CREDIT) > 0;
	}

	/**
	 * Party layer: install an externally generated (seed-shared, identical on
	 * every participant's client) offer set as the pending offers.
	 */
	public boolean presentPartyOffers(List<TaskOffer> offers) {
		GachaState state = stateService.get();
		if (state == null || state.getActiveTask() != null || hasPendingOffers()
			|| offers == null || offers.isEmpty()) {
			return false;
		}
		installOffers(offers);
		return true;
	}

	/**
	 * Party layer: the vote died before it bound this player (the party
	 * dissolved, the host went quiet, or a minority settled it without their
	 * vote), but rolls cannot be undone — the SAME offers remain, demoted to
	 * personal ones (clicking now accepts for this player alone).
	 */
	public void demotePartyOffers() {
		stateService.mutate(s -> {
			List<TaskOffer> pending = s.getPendingOffers();
			if (pending == null || pending.isEmpty() || !pending.get(0).isPartyRoll())
				return s;
			List<TaskOffer> personal = new ArrayList<>(pending.size());
			for (TaskOffer offer : pending) {
				personal.add(new TaskOffer(offer.getDifficulty(), offer.getMonsterName(),
					offer.getMonsterCombatLevel(), offer.getKillsRequired(), offer.getPerKillGc(),
					offer.getCompletionGc(), offer.getSideBets(), offer.isRedemption(), false));
			}
			return s.withPendingOffers(personal);
		});
	}

	/**
	 * The offer at a board position, or null when there is nothing there to
	 * accept — no state, a contract already in force, an empty board, or an index
	 * past the end.
	 *
	 * Deliberately reads the state itself instead of composing pending(): the
	 * guard order here (null list tested BEFORE the bounds test) is the one both
	 * accept paths have always had, and routing it through a never-null list
	 * would quietly turn a negative index from today's throw into a false.
	 */
	@Nullable
	private TaskOffer offerAt(int index) {
		GachaState state = stateService.get();
		if (state == null || state.getActiveTask() != null
			|| state.getPendingOffers() == null || index >= state.getPendingOffers().size()) {
			return null;
		}
		return state.getPendingOffers().get(index);
	}

	public boolean acceptOffer(int index) {
		TaskOffer offer = offerAt(index);
		if (offer == null)
			return false;
		if (offer.isPartyRoll()) {
			// a party offer is not accepted — it is VOTED for; the host's
			// settlement accepts it on every member's client via acceptPartyOffer
			Listeners.fireHook(partyVoteHook, h -> h.accept(index), "party vote hook failed");
			return true;
		}
		// solo: the arming IS the consent, taken through the panel's confirmation
		acceptInternal(offer, null, null, true, null);
		return true;
	}

	/**
	 * Party layer: the vote is settled — every bound member's client accepts
	 * the same offer as a SHARED contract (kills from all of them count).
	 */
	public boolean acceptPartyOffer(int index, String partyLabel,
		List<AttackStyle> partyStyles) {
		return acceptPartyOffer(index, partyLabel, partyStyles, false, null);
	}

	/**
	 * Party layer with the Ante verdict. The wager is a SEPARATE decision from
	 * the contract: {@code anteRequested} false signs exactly the same contract,
	 * so a party that could not agree on the wager still hunts together.
	 */
	public boolean acceptPartyOffer(int index, String partyLabel,
		List<AttackStyle> partyStyles, boolean anteRequested) {
		return acceptPartyOffer(index, partyLabel, partyStyles, anteRequested, null);
	}

	/**
	 * As above, recording the roll's proposal id on the contract. That id is what
	 * lets a client that restarts mid-contract be recognised by the rest of the
	 * party again — see ActiveTask.partyProposalId. Null signs a contract that can
	 * never be rejoined, which is right for the solo path and for tests.
	 */
	public boolean acceptPartyOffer(int index, String partyLabel,
		List<AttackStyle> partyStyles, boolean anteRequested,
		Long proposalId) {
		TaskOffer offer = offerAt(index);
		if (offer == null)
			return false;
		acceptInternal(offer, partyLabel, partyStyles, anteRequested, proposalId);
		return true;
	}

	/**
	 * Signs the contract. There is no partyAnchorId parameter: every caller ever
	 * passed 0, because RuneLite regenerates party member ids each client session
	 * and the id is therefore worthless for recognising anyone — partyProposalId
	 * is what actually reunites a restarted client with its contract. The
	 * persisted ActiveTask.partyAnchorId field stays (removing it would change
	 * the save format) and simply keeps its 0 default, exactly as before.
	 */
	private void acceptInternal(TaskOffer offer, String partyLabel,
		List<AttackStyle> partyStyles, boolean anteRequested,
		Long partyProposalId) {
		ActiveTask task = ActiveTask.builder()
			.difficulty(offer.getDifficulty())
			.monsterName(offer.getMonsterName())
			.monsterCombatLevel(offer.getMonsterCombatLevel())
			.killsRequired(offer.getKillsRequired())
			.killsDone(0)
			.perKillGc(offer.getPerKillGc())
			.completionGc(offer.getCompletionGc())
			.sideBets(offer.getSideBets())
			.redemption(offer.isRedemption())
			.acceptedAtMs(System.currentTimeMillis())
			.appliedCharge(null) // charges are bought DURING a task, slayer-bracelet style
			.partyLabel(partyLabel) // non-null = shared contract (party)
			// partyAnchorId is not set: the builder leaves it 0, which is the value
			// every accept has written since the field existed (see above)
			.partyProposalId(partyProposalId) // the only handle that survives a restart
			.partyStyles(partyStyles) // snapshot: the clash bonus is priced at signing
			.slayerAligned(SlayerAlignment.matches(offer.getMonsterName(), liveSlayerTarget()))
			.build();
		// The Ante is priced and escrowed INSIDE the mutate that signs the
		// contract, off the balance read there rather than the one read here: a
		// purchase landing in between would otherwise let the stake exceed the
		// purse, and the deduction would silently clamp to less than the contract
		// says is at risk. An ineligible offer, an unarmed player or a purse
		// under the floor all price to 0 and sign the identical contract — the
		// wager can never block or alter the contract itself.
		final int percent = anteRequested && anteEligible(offer) ? antePercentArmed : 0;
		final int[] staked = {0};
		stateService.mutate(s -> {
			int stake = anteStakeFor(s.getGc(), percent);
			staked[0] = stake;
			return s
				.withActiveTask(stake > 0 ? task.withAnteStake(stake) : task)
				.withGc(s.getGc() - stake)
				.withPendingOffers(new ArrayList<>());
		});
		antePercentArmed = 0; // one arming, one contract
		if (staked[0] > 0) {
			fanfare(CeremonyBus.Fanfare.Size.MEDIUM, "The Ante is staked",
				staked[0] + " GC is held against this contract — finish it for "
					+ (long) staked[0] * Tuning.ANTE_PAYOUT_MULT + " GC back, die and it is gone.");
		}
		recentKillTicks.clear();
		resetCombo(); // each contract starts its own rhythm
		Listeners.fireHook(offerAcceptedHook, h -> h.accept(offer), "offer accepted hook failed");
	}

	/**
	 * Buy a Style Compactor/Extender for the CURRENT task. Requires an active
	 * task with no charge applied yet; one purchase locks both until the task
	 * ends and a new one is assigned. A free starter voucher, when held, is
	 * consumed INSTEAD of GC — never both. The whole purchase (guards, payment
	 * and charge application) is ONE atomic mutate, so a task completing
	 * concurrently can never burn the voucher/GC without applying the charge.
	 */
	public boolean purchaseCharge(boolean compactor) {
		String charge = compactor ? "COMPACTOR" : "EXTENDER";
		int price = compactor ? Tuning.COMPACTOR_PRICE_GC : Tuning.EXTENDER_PRICE_GC;
		final boolean[] applied = {false};
		stateService.mutate(s -> {
			if (s.getActiveTask() == null || s.getActiveTask().getAppliedCharge() != null)
				return s;
			GachaState next;
			if (compactor ? s.getFreeCompactors() > 0 : s.getFreeExtenders() > 0) {
				next = compactor
					? s.withFreeCompactors(s.getFreeCompactors() - 1)
					: s.withFreeExtenders(s.getFreeExtenders() - 1);
			}
			else if (s.getGc() >= price) {
				next = s.withGc(s.getGc() - price);
			}
			else {
				return s;
			}
			applied[0] = true;
			return next.withActiveTask(next.getActiveTask().withAppliedCharge(charge));
		});
		return applied[0];
	}

	/**
	 * Party layer: total kills contributed by the OTHER participants (summed
	 * from their broadcasts). Completion triggers when own + others reaches
	 * the shared quota.
	 */
	public void syncPartyKills(int othersTotal) {
		ActiveTask task = activeTask();
		if (task == null || !task.isParty() || othersTotal <= task.getPartyOtherKills())
			return;
		stateService.mutate(s -> s.getActiveTask() == null ? s
			: s.withActiveTask(s.getActiveTask().withPartyOtherKills(othersTotal)));
		completeSharedIfReached();
	}

	/** Complete the shared contract when the pooled quota is reached. */
	public void completeSharedIfReached() {
		ActiveTask task = activeTask();
		if (task != null && task.isParty()
			&& task.getKillsDone() + task.getPartyOtherKills() >= task.getKillsRequired()) {
			completeTask();
		}
	}

	/** A participant's client reported the shared contract complete (sync backstop). */
	public void forcePartyComplete() {
		ActiveTask task = activeTask();
		if (task == null || !task.isParty())
			return;
		// the mutate re-reads the contract off its OWN snapshot (s), not the one
		// guarded above, so a completion landing in between cannot be overwritten
		stateService.mutate(s -> {
			ActiveTask live = s.getActiveTask();
			return live == null ? s : s.withActiveTask(live.withPartyOtherKills(Math.max(
				live.getPartyOtherKills(), live.getKillsRequired() - live.getKillsDone())));
		});
		completeSharedIfReached();
	}

	// A contract is a contract: there is deliberately NO abandonTask(). Once a
	// task is accepted the only way out is completing it.

	// --- Rhythm Combo ---

	/** Whether a chain is still running at the given tick. */
	private boolean comboAlive(int nowTick) {
		return comboIdleAnchorTick >= 0
			&& nowTick - comboIdleAnchorTick <= Tuning.COMBO_IDLE_RESET_TICKS;
	}

	/** Stacks the chain is worth at the given tick (0 once the idle cutoff passes). */
	public int comboStacksAt(int nowTick) {
		return comboAlive(nowTick) ? Tuning.comboStacks(comboKills) : 0;
	}

	/**
	 * How far the chain has come toward its next stack, 0-1. Flat 0 on a dead
	 * or already-maxed chain, so the meter has nothing left to promise.
	 */
	public double comboProgressAt(int nowTick) {
		if (!comboAlive(nowTick) || comboKills >= Tuning.COMBO_MAX_KILLS)
			return 0;
		return (comboKills % Tuning.COMBO_KILLS_PER_STACK) / (double) Tuning.COMBO_KILLS_PER_STACK;
	}

	/** Ticks left before an alive chain cancels from idling (0 when no chain). */
	public int comboIdleTicksRemaining(int nowTick) {
		if (comboIdleAnchorTick < 0)
			return 0;
		return Math.max(0, Tuning.COMBO_IDLE_RESET_TICKS - (nowTick - comboIdleAnchorTick));
	}

	private void resetCombo() {
		comboKills = 0;
		comboIdleAnchorTick = -1;
	}

	/**
	 * Logout/profile-switch hygiene: transient combat state must never leak
	 * across characters or let a logout park a combo past its idle window.
	 */
	public void resetTransientCombat() {
		resetCombo();
		recentKillTicks.clear();
	}

	/** Advance the chain for an on-task compliant kill; returns the new stack count. */
	int advanceCombo(int killTick) {
		if (!comboAlive(killTick)) {
			comboKills = 1; // fresh chain (dead chains stay dead — attacks after
			// the idle cutoff cannot revive them, they start this new one)
		}
		else {
			// every kill on a live chain banks, however long it took to land;
			// held at the cap so a long chain cannot bank credit it can't spend
			comboKills = Math.min(Tuning.COMBO_MAX_KILLS, comboKills + 1);
		}
		comboIdleAnchorTick = killTick;
		return Tuning.comboStacks(comboKills);
	}

	// StyleTracker.AttackListener: any judged attack keeps a LIVE chain alive —
	// the idle countdown only runs while no attack commands are being issued
	@Override
	public void onAttack(AttackStyle style, int tick) {
		if (comboAlive(tick)) {
			// max, not assignment: this tick comes from StyleTracker's counter
			// while kills anchor with KillTracker's, and the meter reads back
			// with KillTracker's again. Those three agree today only because
			// both services increment on the same GameTick and are registered
			// together — a coincidence, not a guarantee. Taking the later of the
			// two means a swing can only ever EXTEND a chain, never cut it short,
			// so any future skew degrades to a slightly generous timer instead
			// of a chain that stops resetting while the player is still fighting.
			comboIdleAnchorTick = Math.max(comboIdleAnchorTick, tick);
		}
	}

	// ComplianceService.Listener: a forbidden-style attack breaks the rhythm
	@Override
	public void onForbiddenAttack(AttackStyle used, AttackStyle allowed, long penaltyGc) {
		resetCombo();
	}


	// --- Kill handling ---

	@Override
	public void onKill(KillTracker.Kill kill) {
		GachaState state = stateService.get();
		if (state == null)
			return;
		lastKillTick = kill.getTick();
		ActiveTask task = state.getActiveTask();
		boolean onTask = task != null && task.getMonsterName().equalsIgnoreCase(kill.getNpcName());
		if (!onTask) {
			journalKill(kill.getNpcName(), 0);
			fireKillFeedback(new KillFeedback(kill.getNpcName(), 0, false, false, false,
				task == null ? 0 : task.getKillsDone(), task == null ? 0 : task.getKillsRequired(),
				false, kill.getDeathLocation()));
			return;
		}

		// ironman honor rule: a kill another player damaged is only half yours
		boolean assistedPenalty = assistedPenaltyApplies(isIronman(), kill.isAssistedByOther(), task);

		// bounded by the DEATH tick: kills are emitted a few ticks late (loot
		// oracle), and a forbidden attack on the NEXT target inside that gap
		// must never taint this finished kill
		int convictingTick = complianceService.convictingAttackTick(
			kill.getEngagementStartTick(), kill.getTick());
		boolean tainted = convictingTick >= 0;
		long awarded = 0;
		if (tainted) {
			// name the conviction: the pardon that retracts that verdict a few
			// ticks later must be able to reverse this exact point
			complianceService.addTaint(convictingTick);
			resetCombo(); // a forbidden-style kill has no rhythm
		}
		else {
			// rhythm advances on every compliant on-task kill, even when the
			// contract pays nothing per kill (redemption tasks have perKillGc 0)
			int stacks = advanceCombo(kill.getTick());
			// award BEFORE working off taint: with taint > 0 this kill's income
			// (and its side bets) must still be halved — the debt clears after
			if (task.getPerKillGc() > 0) {
				// The rhythm combo and the combat-level scaling ADD their
				// bonuses rather than compounding. Multiplied, a low-level
				// player punching up stacked 2.5 x 5.0 x 2.5 into a 31x kill and
				// the early game paid better per hour than the late game. Added,
				// and with KILL_DIFF_CAP now 1.75, the pair tops out at 3.25x and
				// the ladder stays legible: six stacks is "+150%", the level-gap
				// term is at most "+75%", together +225%.
				int playerCb = playerCombatLevel();
				double bonus = (Tuning.killCbMultiplier(playerCb, kill.getNpcCombatLevel()) - 1.0)
					+ (Tuning.comboMultiplier(stacks) - 1.0);
				// The Preferred Weapon multiplies the WHOLE award rather than joining
				// that additive term. Folded in additively a "1.5x" bonus would be
				// worth about +31% at the top of the ladder, and an interface that says
				// 1.5x while the player measures +31% is a lie; Tuning.WEAPON_BONUS_MULT
				// carries the rest of that argument. The real attainable ceiling on one
				// kill is therefore 3.25 x 1.5 = 4.875x, reached with six stacks and the
				// level-gap term sitting on its cap.
				double weaponMult = weaponMultFor(state, kill);
				// the assist penalty stays multiplicative: it is a halving of
				// whatever was earned, not a bonus competing with the others
				double mult = (1.0 + bonus) * weaponMult
					* (assistedPenalty ? Tuning.ASSISTED_KILL_MULT : 1.0);
				long scaled = Math.round(task.getPerKillGc() * mult);
				awarded = creditSink.award(scaled, new CreditSink.GcContext(
					CreditSink.Source.KILL, kill.getNpcName(), tagsFor(kill.getNpcName())));
			}
			recordDiscovery(kill.getNpcName());
			checkSideBets(kill);
			complianceService.workOffTaint();
		}
		journalKill(kill.getNpcName(), awarded);

		// Compactor doubles the count (expeditious-bracelet fast-forward; the
		// skipped count pays no GC); the assisted penalty halves it, banking a
		// pending half when needed. Clamped so the counter never overshoots.
		KcAdvance advance = kcAdvance("COMPACTOR".equals(task.getAppliedCharge()),
			assistedPenalty, task.isHalfKillPending());
		int newKills = Math.min(task.getKillsRequired(), task.getKillsDone() + advance.getIncrement());
		// shared (party) contracts pool everyone's kills toward the quota
		boolean finalKill = newKills + (task.isParty() ? task.getPartyOtherKills() : 0)
			>= task.getKillsRequired();
		// Double Docket re-checks per kill, so a contract signed before the
		// player picked up the matching assignment still latches on. Skipped
		// once latched: the flag is sticky, so there is nothing further to learn
		// and no reason to keep reading the Slayer config. It rides the kill-count
		// mutate rather than taking one of its own — a second mutate here would
		// re-encode and re-hash the entire save on every kill.
		boolean docketNow = !task.isSlayerAligned()
			&& SlayerAlignment.matches(task.getMonsterName(), liveSlayerTarget());
		// The Dossier's clean flag rides this same mutate for the same reason the
		// docket latch does: a mutate of its own would re-gzip and re-hash the
		// entire save on every out-of-style kill, on the very path that is
		// already the hottest in the plugin.
		stateService.mutate(s -> s.getActiveTask() == null ? s
			: s.withActiveTask(s.getActiveTask()
				.withKillsDone(newKills)
				.withHalfKillPending(advance.isHalfPending())
				.withSlayerAligned(s.getActiveTask().isSlayerAligned() || docketNow)
				.withTaintedKills(s.getActiveTask().getTaintedKills() + (tainted ? 1 : 0))));

		fireKillFeedback(new KillFeedback(kill.getNpcName(), awarded, true, tainted, finalKill,
			newKills, task.getKillsRequired(), assistedPenalty, kill.getDeathLocation()));

		if (docketNow)
			Listeners.fireHook(slayerLatchHook, Runnable::run, "slayer latch hook failed");

		// The re-read stays INSIDE the loop deliberately: a listener is allowed to
		// end the contract, and the listeners queued behind it must then observe
		// that and stay silent. Hoisting the check above the loop would be a real
		// behaviour change, not a cleanup.
		//
		// What changed is that one iteration now makes ONE observation instead of
		// four. The old form re-read the volatile snapshot for each null test, for
		// isParty(), and a fourth time to build the argument — so the value that
		// reached the listener was never the value the three guards had approved.
		// Nothing pins the four reads to each other: a snapshot swap landing
		// between the last guard and the argument hands the listener a different
		// task, or a null, on a callback whose whole contract is "here is the live
		// shared contract". One local makes the thing tested and the thing passed
		// the same object by construction. It also takes the hottest path in the
		// plugin from four state reads per listener per credited kill down to one.
		for (Listener listener : listeners) {
			GachaState live = stateService.get();
			ActiveTask shared = live == null ? null : live.getActiveTask();
			if (shared != null && shared.isParty())
				listener.onPartyProgress(shared);
		}

		if (finalKill)
			completeTask();
	}

	/**
	 * The Preferred Weapon factor for one kill: {@link Tuning#WEAPON_BONUS_MULT}
	 * when the wheel's named category was in the player's hands at the killing
	 * blow, 1.0 otherwise.
	 *
	 * <p><b>The category is not read here, and that is the whole feature.</b>
	 * onKill runs several ticks after the death — KillTracker holds every kill
	 * back for the loot oracle — so a varbit read at this moment would report
	 * what is equipped NOW, and swapping the named weapon in during that window
	 * would collect a bonus the fight never earned. StyleTracker stamps every
	 * judged attack with what it was made with, and only a stamp inside this
	 * kill's own engagement window counts; a kill with no judged attack in that
	 * window (a thrall's kill, damage dealt off-screen) pays nothing rather than
	 * inheriting the previous fight's weapon.
	 *
	 * <p>Called from inside the NON-TAINTED branch above, which is what makes
	 * "a tainted kill pays no weapon bonus" structural rather than a rule
	 * somebody has to remember: a tainted kill never reaches the award at all.
	 * WeaponBonusTest pins that so a later refactor of that branch cannot
	 * quietly change it.
	 *
	 * <p>Neither collaborator is null-guarded, unlike the Client reads elsewhere
	 * in this file. Both are constructor-injected, so Guice cannot leave either
	 * null in the live plugin — it would refuse to build the service at all — and
	 * a guard here would exist purely for headless harnesses, which the token
	 * budget does not have room to spend on. A test that reaches this line wires
	 * a real StyleTracker and a real WeaponTypeService; both are safe with a null
	 * Client (nothing is ever sampled, so nothing is ever satisfied) and cost a
	 * line each.
	 */
	private double weaponMultFor(GachaState state, KillTracker.Kill kill) {
		StyleTracker.WeaponSample sample = styleTracker.weaponAt(
			kill.getEngagementStartTick(), kill.getTick());
		return sample != null && weaponTypeService.satisfies(state.getPreferredWeaponType(),
			sample.getCategory(), sample.getComMode())
			? Tuning.WEAPON_BONUS_MULT : 1.0;
	}

	private void checkSideBets(KillTracker.Kill kill) {
		// one read, taken before the tick bookkeeping: nothing between here and
		// the old second read touched the state, so this is the same contract
		ActiveTask task = activeTask();
		if (task == null)
			return;
		recentKillTicks.add(kill.getTick());
		while (recentKillTicks.size() > 10) {
			recentKillTicks.poll();
		}
		List<SideBet> bets = task.getSideBets();
		if (bets == null || bets.isEmpty())
			return;
		List<SideBet> updated = new ArrayList<>(bets.size());
		boolean changed = false;
		for (SideBet bet : bets) {
			if (bet.isCompleted()) {
				updated.add(bet);
				continue;
			}
			boolean hit = false;
			switch (bet.getKind()) {
				case BIG_HIT:
					hit = kill.getMaxHitDealt() >= bet.getThreshold();
					break;
				case DAMAGELESS_KILL:
					hit = !kill.isTookDamageDuringEngagement();
					break;
				case SPEED_KILLS:
					hit = countKillsWithin(bet.getWindowTicks(), kill.getTick()) >= bet.getThreshold();
					break;
				case CLUTCH_KILL:
					hit = killTrackerLowHp();
					break;
			}
			if (hit) {
				SideBet done = bet.withCompleted(true);
				updated.add(done);
				changed = true;
				creditSink.award(bet.getPayoutGc(), new CreditSink.GcContext(
					CreditSink.Source.SIDE_BET, kill.getNpcName(), tagsFor(kill.getNpcName())));
				for (Listener listener : listeners) {
					listener.onSideBetHit(done, kill.getNpcName());
				}
				fanfare(CeremonyBus.Fanfare.Size.SMALL,
					bet.isSealed() ? "Sealed bet revealed!" : "Side bet hit!",
					describeSideBet(done) + " +" + bet.getPayoutGc() + " GC");
			}
			else {
				updated.add(bet);
			}
		}
		if (changed) {
			stateService.mutate(s -> s.getActiveTask() == null ? s
				: s.withActiveTask(s.getActiveTask().withSideBets(updated)));
		}
	}

	/**
	 * Bestiary: the first on-task compliant kill of a new species stamps the
	 * codex and pays a discovery bonus; crossing a codex milestone pays more.
	 */
	private void recordDiscovery(String monsterName) {
		GachaState state = stateService.get();
		if (state == null || state.getSpeciesDiscovered() == null)
			return;
		// Locale.ROOT: persisted keys must not vary with the JVM locale
		String key = monsterName.toLowerCase(Locale.ROOT);
		if (state.getSpeciesDiscovered().contains(key))
			return;
		GachaState next = stateService.mutate(s -> {
			Set<String> discovered = new HashSet<>(s.getSpeciesDiscovered());
			discovered.add(key);
			return s.withSpeciesDiscovered(discovered);
		});
		creditSink.award(Tuning.DISCOVERY_GC, new CreditSink.GcContext(
			CreditSink.Source.DISCOVERY, monsterName, tagsFor(monsterName)));
		int count = next == null ? 0 : next.getSpeciesDiscovered().size();
		// only the first ten discoveries get a banner (early-game flood control);
		// after that the codex meter and milestone fanfares carry the feedback
		if (count <= 10) {
			fanfare(CeremonyBus.Fanfare.Size.SMALL, "New species: " + monsterName,
				"Codex entry " + count + " — +" + Tuning.DISCOVERY_GC + " GC");
		}
		for (int i = 0; i < Tuning.BESTIARY_MILESTONES.length; i++) {
			if (count == Tuning.BESTIARY_MILESTONES[i]) {
				int bonus = Tuning.BESTIARY_MILESTONE_GC[i];
				creditSink.award(bonus, new CreditSink.GcContext(
					CreditSink.Source.DISCOVERY, null, null));
				fanfare(CeremonyBus.Fanfare.Size.MEDIUM, count + " species discovered!",
					"The codex swells — +" + bonus + " GC");
			}
		}
	}

	private boolean killTrackerLowHp() {
		int boosted = client.getBoostedSkillLevel(Skill.HITPOINTS);
		int real = lvl(Skill.HITPOINTS);
		return real > 0 && boosted * 4 <= real;
	}

	private int countKillsWithin(int windowTicks, int nowTick) {
		int count = 0;
		for (int t : recentKillTicks) {
			if (nowTick - t <= windowTicks)
				count++;
		}
		return count;
	}

	public static String describeSideBet(SideBet bet) {
		switch (bet.getKind()) {
			case BIG_HIT:
				return "Land a hit of " + bet.getThreshold() + "+";
			case DAMAGELESS_KILL:
				return "A kill without taking damage";
			case SPEED_KILLS:
				return bet.getThreshold() + " kills within " + (bet.getWindowTicks() * 3 / 5) + "s";
			case CLUTCH_KILL:
				return "Finish a kill under 25% HP";
			default:
				return "?";
		}
	}

	// --- Completion ---

	/**
	 * How many DISTINCT styles a shared contract was signed with. Null is the
	 * legacy case (a save written before the snapshot existed, or a solo task)
	 * and null ENTRIES are real too — a participant on an older client sends
	 * no style, and Gson keeps null array elements across a save/load — so
	 * both must count as no contribution rather than throw.
	 */
	static int distinctStyles(List<AttackStyle> styles) {
		if (styles == null || styles.isEmpty())
			return 0;
		EnumSet<AttackStyle> seen = EnumSet.noneOf(AttackStyle.class);
		for (AttackStyle style : styles) {
			if (style != null)
				seen.add(style);
		}
		return seen.size();
	}

	private void completeTask() {
		GachaState state = stateService.get();
		if (state == null || state.getActiveTask() == null)
			return;
		ActiveTask task = state.getActiveTask();
		// one clock read shared by the personal best and by the Dossier record, so
		// the filed timestamp and the filed duration cannot disagree
		long completedAtMs = System.currentTimeMillis();
		long duration = completedAtMs - task.getAcceptedAtMs();

		double completionMult = 1.0;
		if (task.isParty()) {
			// Shared contract: the co-op bonus applies party-wide, plus a FLAT
			// clash bonus if the party covers 2+ distinct styles. Flat, not per
			// extra style — a trio running all three styles pays exactly what a
			// pair running two pays. Computed over the accept-time snapshot
			// (self included), so every client pays the same and a mid-contract
			// style re-roll cannot reprice a signed contract.
			completionMult = Tuning.PARTY_REWARD_MULT;
			if (distinctStyles(task.getPartyStyles()) > 1)
				completionMult += Tuning.PARTY_STYLE_CLASH_BONUS;
		}
		else if (task.isPartyConvertedToSolo()) {
			completionMult = Tuning.PARTY_CARRY_MULT;
		}

		// Double Docket stacks MULTIPLICATIVELY on whatever the party chain came
		// to, so it is worth the same proportion of a shared contract as of a
		// solo one. The taint halving still lands after all of this, inside the
		// sink, exactly as it does for every other completion modifier.
		if (task.isSlayerAligned())
			completionMult *= Tuning.DOUBLE_DOCKET_MULT;

		// Milestone contracts (every 5th/10th/50th/100th/250th) multiply the
		// completion reward, Slayer-point style. Stacks multiplicatively with
		// the party and Double Docket chain above for the same reason the
		// docket does: a milestone should be worth the same PROPORTION of a
		// shared or aligned contract as of a plain one.
		//
		// This completion's lifetime contract number — and, being one past the old
		// total, also the new total the mutate below files. Deed milestones, the
		// fragment window and the milestone multiple are all read off this single
		// value so they cannot disagree about which contract this was.
		int taskNumber = state.getTotalTasksCompleted() + 1;
		double milestoneMult = Tuning.completionMilestoneMult(taskNumber);
		completionMult *= milestoneMult;

		// Redemption clears taint BEFORE the award so its own completion
		// reward is not halved by the debt it just paid off.
		boolean redemptionCleared = false;
		if (task.isRedemption()) {
			complianceService.clearAllTaint();
			redemptionCleared = true;
		}

		long completionAwarded = creditSink.award(Math.round(task.getCompletionGc() * completionMult),
			new CreditSink.GcContext(CreditSink.Source.TASK_COMPLETION, task.getMonsterName(),
				tagsFor(task.getMonsterName())));

		int sideBetsHit = 0;
		long sideBetGc = 0;
		if (task.getSideBets() != null) {
			for (SideBet bet : task.getSideBets()) {
				if (bet.isCompleted()) {
					sideBetsHit++;
					sideBetGc += bet.getPayoutGc();
				}
			}
		}
		long haul = completionAwarded + sideBetGc + (long) task.getPerKillGc() * task.getKillsRequired();

		// journal + PBs
		boolean newFastest = false;
		boolean newHaul = false;
		String pbKey = task.getDifficulty().name();
		PersonalBest pb = state.getPersonalBests().get(pbKey);
		if (pb == null)
			pb = new PersonalBest(0, null, 0, null);
		PersonalBest updatedPb = pb;
		if (pb.getFastestTaskMs() == 0 || duration < pb.getFastestTaskMs()) {
			updatedPb = updatedPb.withFastestTaskMs(duration).withFastestMonster(task.getMonsterName());
			newFastest = pb.getFastestTaskMs() != 0;
		}
		if (haul > pb.getBiggestHaulGc()) {
			updatedPb = updatedPb.withBiggestHaulGc((int) haul).withBiggestHaulMonster(task.getMonsterName());
			newHaul = pb.getBiggestHaulGc() != 0;
		}
		if (newFastest || newHaul) {
			creditSink.award(Tuning.PB_RECORD_GC, new CreditSink.GcContext(
				CreditSink.Source.RECORD, null, null));
		}

		final PersonalBest pbFinal = updatedPb;
		final String monsterName = task.getMonsterName();

		// deed milestone?
		int milestone = 0;
		int claimed = state.getDeedMilestonesClaimed();
		if (claimed < Tuning.DEED_TASK_MILESTONES.length
			&& taskNumber >= Tuning.DEED_TASK_MILESTONES[claimed]
			&& state.getDeededSlots().size() < GearSlot.values().length) {
			milestone = Tuning.DEED_TASK_MILESTONES[claimed];
		}
		final int milestoneFinal = milestone;

		// Deed Fragments: harder contracts during the first ten tasks pay
		// fragments; ten forge the one-per-account bonus deed
		int fragmentsEarned = 0;
		if (!state.isFragmentDeedForged() && taskNumber <= Tuning.FRAGMENT_WINDOW_TASKS)
			fragmentsEarned = Tuning.fragmentsFor(task.getDifficulty());
		final int fragmentsEarnedFinal = fragmentsEarned;

		// the applied charge is read INSIDE the clearing mutate so a purchase
		// landing after this method's task snapshot still reaches advanceCycle
		final String[] chargeApplied = {task.getAppliedCharge()};
		// ...and so is the stake, for the same reason in reverse: a death landing
		// after the snapshot has already zeroed the escrow, and returning the
		// stale figure would refund a wager that was lost.
		final int[] anteStake = {task.getAnteStake()};
		// ...and the violation count, so a final kill convicted between this
		// method's snapshot and the mutate still files the contract as dirty
		final int[] taintedKills = {task.getTaintedKills()};
		GachaState afterMutate = stateService.mutate(s -> {
			if (s.getActiveTask() != null) {
				chargeApplied[0] = s.getActiveTask().getAppliedCharge();
				anteStake[0] = s.getActiveTask().getAnteStake();
				taintedKills[0] = s.getActiveTask().getTaintedKills();
			}
			Map<String, PersonalBest> pbs = new HashMap<>(s.getPersonalBests());
			pbs.put(pbKey, pbFinal);
			Map<String, Integer> byDiff = new HashMap<>(s.getTasksCompletedByDifficulty());
			byDiff.merge(task.getDifficulty().name(), 1, Integer::sum);
			Map<String, MonsterStats> stats = new HashMap<>(s.getMonsterStats());
			MonsterStats ms = stats.getOrDefault(monsterName, new MonsterStats(0, 0, 0));
			stats.put(monsterName, ms.withTasksCompleted(ms.getTasksCompleted() + 1));
			GachaState next = s
				.withActiveTask(null)
				.withPersonalBests(pbs)
				.withTasksCompletedByDifficulty(byDiff)
				.withMonsterStats(stats)
				.withTotalTasksCompleted(taskNumber);
			if (anteStake[0] > 0) {
				// The principal comes back RAW, in the same mutate that retires
				// the contract, because it was never income — it is the player's
				// own GC coming out of escrow. Through the sink it would be
				// halved by taint and would inflate lifetime earnings by money
				// the player merely got back. Only the PROFIT is awarded, below.
				next = next.withGc(next.getGc() + anteStake[0]);
			}
			if (milestoneFinal > 0) {
				next = next.withDeedMilestonesClaimed(s.getDeedMilestonesClaimed() + 1)
					.withPendingDeeds(s.getPendingDeeds() + 1);
			}
			if (fragmentsEarnedFinal > 0 && !s.isFragmentDeedForged()) {
				int frags = s.getDeedFragments() + fragmentsEarnedFinal;
				if (frags >= Tuning.FRAGMENTS_REQUIRED) {
					next = next.withDeedFragments(Tuning.FRAGMENTS_REQUIRED)
						.withFragmentDeedForged(true)
						.withPendingDeeds(next.getPendingDeeds() + 1);
				}
				else {
					next = next.withDeedFragments(frags);
				}
			}
			// File the contract. This rides the completion mutate rather than
			// taking one of its own, and the style is read off s HERE — before
			// styleService.advanceCycle() runs below — so the Dossier files the
			// style the contract was RUN under, not the one rolled as its reward.
			// getKillsRequired() is the quota the pay was computed against; on a
			// shared contract those kills were pooled, which the row's party tag
			// makes plain.
			next = next.withContractLog(ContractRecord.appendCapped(s.getContractLog(),
				new ContractRecord(completedAtMs, monsterName, task.getDifficulty().name(),
					task.getKillsRequired(), haul, duration, s.getAllowedStyle(), taintedKills[0],
					task.getPartyLabel(), task.isPartyConvertedToSolo(), task.isRedemption()),
				Tuning.DOSSIER_MAX_RECORDS));
			return next;
		});

		if (anteStake[0] > 0) {
			// Only the winnings are income. SIDE_BET is the honest source: the
			// Ante is the same kind of thing as the contract's own side bets,
			// and taint halving the PROFIT (never the principal) is exactly the
			// treatment every other bet on this contract gets.
			long profit = creditSink.award((long) anteStake[0] * (Tuning.ANTE_PAYOUT_MULT - 1),
				new CreditSink.GcContext(CreditSink.Source.SIDE_BET, task.getMonsterName(),
					tagsFor(task.getMonsterName())));
			fanfare(CeremonyBus.Fanfare.Size.MEDIUM, "The Ante pays",
				anteStake[0] + " GC staked returns with " + profit + " GC won.");
		}

		boolean forgedNow = fragmentsEarned > 0 && !state.isFragmentDeedForged()
			&& afterMutate != null && afterMutate.isFragmentDeedForged();
		int fragmentsTotal = afterMutate == null
			? state.getDeedFragments() : afterMutate.getDeedFragments();

		boolean cycleTriggered = styleService.advanceCycle(chargeApplied[0]);

		TaskCompletionSummary summary = new TaskCompletionSummary(task, completionAwarded,
			sideBetsHit, duration, newFastest, newHaul, redemptionCleared, cycleTriggered, milestone,
			fragmentsEarned, fragmentsTotal, forgedNow, taskNumber, milestoneMult);
		ceremonyBus.submit(CeremonyBus.Type.TASK_COMPLETE, summary);
		for (Listener listener : listeners) {
			listener.onTaskCompleted(summary);
		}
		if (milestone > 0)
			ceremonyBus.submit(CeremonyBus.Type.DEED_CHOICE, milestone);
		if (forgedNow) {
			fanfare(CeremonyBus.Fanfare.Size.LARGE, "Deed forged from fragments!",
				Tuning.FRAGMENTS_REQUIRED + " fragments fuse into a bonus Slot Deed — choose a slot.");
			ceremonyBus.submit(CeremonyBus.Type.DEED_CHOICE, 0);
		}
		if (cycleTriggered) {
			// NOT styleService.roll(): a roll coming due is the only moment the
			// Consignment may be offered, so this is the one call site allowed to
			// put it up. offerOrRoll always leaves the roll either taken or owed,
			// which is why nothing is read back — and with no presenter wired it
			// takes the ordinary wheel, exactly as this line did before.
			consignmentService.offerOrRoll(lastKillTick);
		}
		resetCombo(); // rhythm does not carry across contracts
		// A completion banks the reward, the deed, the fragments and the style
		// roll in one moment. Losing that to a crash in the debounce window is
		// the single worst thing this save can drop, and completions are rare
		// enough that an immediate write costs nothing.
		stateService.checkpoint();
	}

	// --- Party carry clause ---

	/**
	 * The Ante deliberately survives this. A stake is personal and the contract
	 * is binding, so a partner leaving does not release this player's wager: the
	 * carry clause already prices the extra difficulty (PARTY_CARRY_MULT), and
	 * refunding here would make "partner logs out" the cheap way out of a losing
	 * bet. Finish it alone and it still pays double.
	 */
	public void convertPartyToSolo() {
		stateService.mutate(s -> s.getActiveTask() == null || !s.getActiveTask().isParty() ? s
			: s.withActiveTask(s.getActiveTask().withPartyConvertedToSolo(true)));
	}

	// --- Helpers ---

	/**
	 * Raise a banner. Every celebration this service submits is the same shape —
	 * a size, a title, one line of detail and no item icon — so the constructor
	 * ceremony is written once here instead of at seven call sites. It still goes
	 * through submit(), so the taps fire and the SMALL-banner coalescing inside
	 * enqueue() behaves exactly as it did.
	 */
	private void fanfare(CeremonyBus.Fanfare.Size size, String title, String detail) {
		ceremonyBus.submit(CeremonyBus.Type.FANFARE, new CeremonyBus.Fanfare(size, title, detail, null));
	}

	/**
	 * Base (unboosted) level shorthand. Nine sites read levels off the client,
	 * seven of them inside one combat-level computation; the delegation is exact,
	 * so the arguments still reach Experience.getCombatLevel in the same order.
	 */
	private int lvl(Skill skill) {
		return client.getRealSkillLevel(skill);
	}

	private void journalKill(String monsterName, long gcAwarded) {
		stateService.mutate(s -> {
			Map<String, MonsterStats> stats = new HashMap<>(s.getMonsterStats());
			MonsterStats ms = stats.getOrDefault(monsterName, new MonsterStats(0, 0, 0));
			stats.put(monsterName, ms.withKills(ms.getKills() + 1).withGcEarned(ms.getGcEarned() + gcAwarded));
			return s.withMonsterStats(stats);
		});
	}

	private void fireKillFeedback(KillFeedback feedback) {
		Listeners.fire(listeners, l -> l.onKillFeedback(feedback), "kill feedback listener failed");
	}

	@Nullable
	private List<String> tagsFor(String monsterName) {
		if (tagsByMonster == null) {
			tagsByMonster = new HashMap<>();
			for (MonsterTable.Monster monster : monsterTable.getMonsters()) {
				tagsByMonster.put(monster.getName().toLowerCase(), monster.getTags());
			}
		}
		return tagsByMonster.get(monsterName.toLowerCase());
	}

	/** Any ironman variant (varbit 1777 nonzero: IM/UIM/HCIM/GIM...). */
	private boolean isIronman() {
		return client != null
			&& client.getVarbitValue(VarbitID.IRONMAN) > 0;
	}

	public int playerCombatLevel() {
		return Experience.getCombatLevel(
			lvl(Skill.ATTACK), lvl(Skill.STRENGTH), lvl(Skill.DEFENCE), lvl(Skill.HITPOINTS),
			lvl(Skill.MAGIC), lvl(Skill.RANGED), lvl(Skill.PRAYER));
	}
}

package com.gachaman.service;

import com.gachaman.model.*;
import java.util.*;
import javax.inject.*;
import lombok.*;
import net.runelite.api.*;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.game.*;

/**
 * What this player could hit at the very best, right now, in one style.
 *
 * <p>Exists for the "land a hit of N+" side bet, which used to size itself off
 * combat level and so dealt bets a bronze-armed account could not physically
 * win. The maths is the standard OSRS one, transcribed from the same steps the
 * Plugin Hub's max-hit-calc uses: effective level from the skill, then
 * {@code floor(0.5 + effective * (strengthBonus + 64) / 640)}.
 *
 * <p>Deliberately the UNBOOSTED, unprayed, no-void figure. Every one of those
 * would raise the estimate, and an estimate that lands above what the player
 * can actually manage recreates the exact bug this replaced. Reading low costs
 * nothing — the bet asks for a fraction of this number, not the number itself.
 */
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class MaxHitService {
	/**
	 * Standard-book combat spells by the Magic level that unlocks them, paired
	 * with their base max hit. The fire variant of each tier — the strongest of
	 * the four elements — because the player picks their own spell and this is
	 * a ceiling, not a prediction. Ascending, so the scan takes the last match.
	 */
	private static final int[] SPELL_LEVELS = {1, 13, 35, 59, 75, 95};
	private static final int[] SPELL_MAX_HITS = {2, 8, 12, 16, 20, 24};

	private final Client client;
	private final ItemManager itemManager;

	/** Base max hit for a spell the player's Magic level allows. */
	static int spellBaseMaxHit(int magicLevel) {
		int base = SPELL_MAX_HITS[0];
		for (int i = 0; i < SPELL_LEVELS.length; i++) {
			if (magicLevel >= SPELL_LEVELS[i])
				base = SPELL_MAX_HITS[i];
		}
		return base;
	}

	/**
	 * The melee/ranged max-hit curve. Pure so it can be tested without a client:
	 * both styles share it, differing only in which level and which equipment
	 * strength bonus they read.
	 */
	static int gearedMaxHit(int level, int strengthBonus) {
		double effective = Math.max(1, level) + 8;
		return Math.max(1, (int) Math.floor(0.5 + effective * (strengthBonus + 64) / 640.0));
	}

	/** Magic ignores the curve entirely: spell base, scaled by damage percent. */
	static int magicMaxHit(int magicLevel, float magicDamagePercent) {
		return Math.max(1,
			(int) Math.floor(spellBaseMaxHit(magicLevel) * (1.0 + magicDamagePercent / 100.0)));
	}

	/**
	 * Best hit the player could land in the style named by the persisted state,
	 * or 0 when there is no style rolled yet or the name is unrecognised.
	 */
	public int estimateFor(String styleName) {
		if (styleName == null)
			return 0;
		try {
			return estimate(AttackStyle.valueOf(styleName));
		}
		catch (IllegalArgumentException e) {
			return 0; // a style name from a newer save than this build knows
		}
	}

	/** Best hit the player could land in this style, or 0 when it cannot be read. */
	public int estimate(AttackStyle style) {
		if (style == null)
			return 0;
		try {
			switch (style) {
				case RANGED:
					return gearedMaxHit(client.getRealSkillLevel(Skill.RANGED), rangedStrength());
				case MAGIC:
					return magicMaxHit(client.getRealSkillLevel(Skill.MAGIC), magicDamage());
				default:
					return gearedMaxHit(client.getRealSkillLevel(Skill.STRENGTH), meleeStrength());
			}
		}
		catch (Exception e) {
			return 0; // no container, no stats, not logged in — the bet falls to its floor
		}
	}

	private int meleeStrength() {
		int total = 0;
		for (ItemEquipmentStats stats : wornStats()) {
			total += stats.getStr();
		}
		return total;
	}

	private int rangedStrength() {
		int total = 0;
		for (ItemEquipmentStats stats : wornStats()) {
			total += stats.getRstr();
		}
		return total;
	}

	private float magicDamage() {
		float total = 0;
		for (ItemEquipmentStats stats : wornStats()) {
			total += stats.getMdmg();
		}
		return total;
	}

	private List<ItemEquipmentStats> wornStats() {
		List<ItemEquipmentStats> out = new ArrayList<>();
		ItemContainer worn = client.getItemContainer(InventoryID.WORN);
		if (worn == null)
			return out;
		for (Item item : worn.getItems()) {
			if (item == null || item.getId() <= 0)
				continue;
			ItemStats stats = itemManager.getItemStats(item.getId());
			if (stats != null && stats.getEquipment() != null)
				out.add(stats.getEquipment());
		}
		return out;
	}
}

package com.gachaman.service;

import com.gachaman.*;
import com.gachaman.data.*;
import com.gachaman.model.*;
import java.util.*;
import java.util.function.*;
import java.util.stream.*;
import javax.annotation.*;
import javax.inject.*;
import lombok.*;
import lombok.extern.slf4j.*;
import net.runelite.api.*;

/**
 * Chest purchasing and roll math: rarity odds with pity, jackpot upgrades,
 * shiny/hologram variants, deed rolls, duplicate conversion. Outcomes are
 * rolled up-front and committed only when the reveal closes (deferred commit),
 * so in-reveal rerolls and aborted ceremonies are safe.
 */
@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class ChestService {
	@Value
	@With
	public static class RolledSlot {
		Rarity rarity;
		int cardId;             // -1 for hologram slots
		@Nullable
		String hologramTier;    // non-null for hologram slots
		Variant variant;
		boolean duplicate;      // NORMAL dupe -> converts to GC at commit
		boolean pityLocked;     // the guaranteed pity slot; reroll-locked
		boolean nearMiss;       // shiny roll landed just outside the band -> stardust
	}

	/**
	 * {@code @With} is here for rerollSlot, which changes exactly one field
	 * (the slot list) and would otherwise have to hand-copy all ten — a list that
	 * silently rots the next time a field is added. The generated withSlots()
	 * expands to the very constructor call it replaces, and Gson binds by field,
	 * so the persisted blob shape is untouched.
	 */
	@Value
	@With
	public static class ChestOpenResult {
		Tuning.Chest purchasedTier;
		Tuning.Chest effectiveTier;
		boolean jackpotUpgraded;
		boolean pityBreak;
		boolean deedGranted;
		@Nullable
		String themedSetTag;
		/** GearSlot name for slot-targeted chests, else null. */
		@Nullable
		String targetSlot;
		List<RolledSlot> slots;
		long pricePaid;
		/** Every card in this open rolled shiny twice (8 stardust consumed). */
		boolean stardustBlessed;
		/**
		 * The tier ladder a Toll pull is confined to ({@link RollOdds#UNTIERED} for
		 * the untiered band), else null for every ordinary chest.
		 *
		 * <p>Carried on the RESULT, not just passed to the roll, because the
		 * in-reveal reroll rebuilds its pool from this object rather than from the
		 * call that created it. Without the field a rerolled Toll pull would fall
		 * through to the all-cards pool and quietly hand back a card from outside
		 * the ladder the player paid for — the one thing the Toll promises.
		 *
		 * <p>Gson binds by field, so a pending blob written before this existed
		 * deserializes it as null and behaves exactly as it did.
		 */
		@Nullable
		String tollTierKey;
	}

	/**
	 * The exact candidate list a roll of this rarity would draw from, plus whether the
	 * house lean applies to it. Shared by pickCardOfRarity and oddsFor so the
	 * disclosure can never drift from the roll.
	 */
	@Value
	public static class RollBucket {
		List<CardDefinition> cards;
		/** True when the proximity gate ran, which is exactly when the lean applies. */
		boolean leaned;
	}

	/** One disclosure row: a tier ladder in one reach band, with its real odds. */
	@Value
	public static class TierOdds {
		/** tierKey, or RollOdds.UNTIERED. */
		String tierKey;
		String displayName;
		boolean wieldableNow;
		/** Probability 0..1 for one ordinary card out of this chest. */
		double probability;
		/**
		 * The cards counted in this row, sorted and de-duplicated.
		 *
		 * <p>Carried because a tier ladder legitimately appears in BOTH bands — the
		 * Defence gate lands on the body only, and metal-prefixed ranged gear is
		 * measured against Ranged — so "Hardleather" showing up twice reads as a bug
		 * unless the panel can say which pieces are the ones still out of reach.
		 */
		List<String> cardNames;
	}

	/** Everything the Chest Odds panel prints, computed from the roll's own code. */
	@Value
	public static class OddsDisclosure {
		Tuning.Chest tier;
		/** Post-pity rarity split, percent, order C/U/R/E/L. */
		double[] rarityPercent;
		/** All non-zero rows, probability-descending. */
		List<TierOdds> rows;
		double wieldableTotal;
		double headroomTotal;
		double untieredTotal;
		double pityBonusPercent;
		int opensSinceEpic;
		int pityHardCap;
		boolean pityBreakNext;
	}

	private final GachaStateService stateService;
	private final CreditSink creditSink;
	private final CardDatabase cardDatabase;
	private final CeremonyBus ceremonyBus;
	private final GachaRng rng;
	private final com.google.gson.Gson gson;
	private final RangedMetal.Lookup rangedMetal;
	@Nullable
	private final Client client;
	@Nullable
	private final TierTable tierTable;

	/** Commit-time hooks (Firsts Journal stamps chest events through this). */
	public interface ChestListener {
		void onChestCommitted(ChestOpenResult result, long dupeGc);

		void onDeedClaimed(GearSlot slot);

		void onRerollSpent();
	}

	private final List<ChestListener> chestListeners = new ArrayList<>();

	/**
	 * The single pending (uncommitted) open, if any.
	 *
	 * <p>Volatile because the writers and some of the readers are different
	 * threads. Every write happens under this object's monitor — recoverPending,
	 * openFirstColoursChest, rerollSlot and commitPending are all synchronized, and
	 * the one remaining write lives in deal(), which is deliberately NOT
	 * synchronized because its only callers (openChest, openSlotChest,
	 * openThemedChest) are, and already hold this monitor when they call it. Grep
	 * for `pending =` and you will land in deal() rather than in the openers; that
	 * is the reason, not a lock that went missing. The Lombok getter takes
	 * no lock, and the Swing EDT reads through it (ShopTab:205 and :652) while the
	 * client thread is the one doing the writing. With no lock and no volatile
	 * there is no happens-before edge to the EDT at all, so it is free to keep
	 * observing a stale reference indefinitely: a shop tile stuck on "a reveal is
	 * in progress" after the reveal has already closed, or an Open button that
	 * stays disabled. Publishing the reference safely is the whole fix — the
	 * object behind it is a deeply immutable Lombok value type, so a reader that
	 * sees the reference necessarily sees a fully built result.
	 *
	 * <p>Deliberately volatile rather than a synchronized getter: the getter would
	 * put the EDT behind the same monitor commitPending() holds while it rewrites
	 * state, awards GC and fans out to every listener, which is a UI stall bought
	 * for nothing. Every reader does a single read into a local and never a
	 * compound check, so a plain volatile read is all the atomicity they need.
	 *
	 * <p>rerollUsedThisReveal below needs no such treatment: its only reader is
	 * canReroll(), which is itself synchronized, so every read of it already
	 * takes the lock that its writes are made under.
	 */
	@Nullable
	@Getter
	private volatile ChestOpenResult pending;
	private boolean rerollUsedThisReveal;

	public void addChestListener(ChestListener listener) {
		if (!chestListeners.contains(listener))
			chestListeners.add(listener);
	}

	public void removeChestListener(ChestListener listener) {
		chestListeners.remove(listener);
	}

	/**
	 * Crash recovery: a client that died mid-reveal left the paid-for outcome
	 * serialized in state. Auto-commit it on the next load so the purchase is
	 * never lost.
	 */
	public synchronized void recoverPending() {
		var state = stateService.get();
		if (pending != null || state == null || state.getPendingChestBlob() == null)
			return;
		try {
			pending = gson.fromJson(state.getPendingChestBlob(), ChestOpenResult.class);
		}
		catch (Exception e) {
			log.warn("Failed to recover pending chest; discarding", e);
			stateService.mutate(s -> s.withPendingChestBlob(null));
			return;
		}
		if (pending != null) {
			log.info("Recovering interrupted chest open ({})", pending.getEffectiveTier());
			commitPending();
		}
	}

	private void persistPending() {
		String blob = pending == null ? null : gson.toJson(pending);
		stateService.mutate(s -> s.withPendingChestBlob(blob));
	}

	// --- Opening ---

	public boolean canAfford(Tuning.Chest tier) {
		GachaState state = stateService.get();
		return state != null && state.getGc() >= Tuning.CHEST_PRICE_GC.get(tier);
	}

	/** Lifetime Rusty opens so far (the starter tier retires after the cap). */
	public int rustyChestsOpened() {
		GachaState state = stateService.get();
		if (state == null || state.getChestsOpenedByTier() == null)
			return 0;
		return state.getChestsOpenedByTier().getOrDefault(Tuning.Chest.RUSTY.name(), 0);
	}

	public boolean rustyAvailable() {
		return rustyChestsOpened() < Tuning.RUSTY_LIFETIME_CAP;
	}

	/** Buy and roll a chest; queues the ceremony. Null when unaffordable/busy/DB not ready. */
	@Nullable
	public synchronized ChestOpenResult openChest(Tuning.Chest tier) {
		if (pending != null || !cardDatabase.isReady())
			return null;
		if (tier == Tuning.Chest.RUSTY && !rustyAvailable())
			return null;
		long price = Tuning.CHEST_PRICE_GC.get(tier);
		if (!creditSink.spend(price))
			return null;
		return deal(roll(tier, null, null, price, null, null, null), CeremonyBus.Type.CHEST_OPEN);
	}

	/**
	 * The tail every PURCHASED open shares: publish the outcome, arm a fresh
	 * reroll, get the blob on disk, and only then hand the result to the ceremony
	 * queue. That order is the crash contract — a client that dies during the
	 * ceremony must find the paid-for outcome in state, so persistPending() has to
	 * run before the reveal can possibly start.
	 *
	 * <p>Called only from synchronized openers, so it inherits their monitor (see
	 * the note on `pending`). openFirstColoursChest deliberately does NOT route
	 * through here: it folds the blob write and the owed-flag clear into ONE
	 * mutate, for the crash-window reason its own javadoc gives.
	 */
	private ChestOpenResult deal(ChestOpenResult result, CeremonyBus.Type type) {
		pending = result;
		rerollUsedThisReveal = false;
		persistPending();
		ceremonyBus.submit(type, result);
		return result;
	}

	/**
	 * Slot-targeted chest: Gilded price, ONE card, rolled only from the chosen
	 * gear slot's pool (Gilded odds; pity applies; no jackpot upgrade).
	 */
	@Nullable
	public synchronized ChestOpenResult openSlotChest(GearSlot slot) {
		if (pending != null || !cardDatabase.isReady() || slot == null)
			return null;
		long price = Tuning.CHEST_PRICE_GC.get(Tuning.Chest.GILDED);
		if (!creditSink.spend(price))
			return null;
		return deal(roll(Tuning.Chest.GILDED, null, slot, price, null, null, null),
			CeremonyBus.Type.CHEST_OPEN);
	}

	/** Open a queued boss-themed chest (free). */
	@Nullable
	public synchronized ChestOpenResult openThemedChest(String setTag) {
		GachaState state = stateService.get();
		if (pending != null || state == null || !cardDatabase.isReady()
			|| !state.getQueuedThemedChests().contains(setTag)) {
			return null;
		}
		stateService.mutate(s -> {
			List<String> queued = new ArrayList<>(s.getQueuedThemedChests());
			queued.remove(setTag);
			return s.withQueuedThemedChests(queued);
		});
		return deal(roll(Tuning.Chest.GILDED, setTag, null, 0, null, null, null),
			CeremonyBus.Type.THEMED_CHEST);
	}

	/**
	 * The Toll's pull: ONE card drawn from a single tier ladder, Gilded odds, no
	 * GC price — the player has already paid in a card. See {@link TollService}
	 * for what is being surrendered and why.
	 *
	 * <p>Modelled on {@link #openSlotChest} rather than {@link #openThemedChest}
	 * because the Toll is PAID, just not in coin. It therefore keeps pity, shiny
	 * and hologram rolls exactly as a bought chest has them: a player handing over
	 * a veteran card is taking a real gamble, and a pull that could never come back
	 * shiny would make the Toll strictly a downgrade machine. The one thing it
	 * drops is the jackpot upgrade, which is meaningless when the pool is one
	 * ladder deep.
	 *
	 * @param tierKey        the ladder to draw from, or null for the untiered band.
	 *                       Null is mapped to {@link RollOdds#UNTIERED} on the way
	 *                       in so that a non-null value can mean "this is a Toll
	 *                       pull" all the way down without a second flag.
	 * @param spentCardUuid  the card being handed over, still owned at this instant.
	 *                       Excluded from the duplicate test for this roll only —
	 *                       see {@link #ownedKeys(GachaState, String)}.
	 * @return the dealt open, or null when nothing was taken (a reveal already in
	 *         flight, or the card database not ready). TollService treats null as
	 *         "nothing happened" and leaves the week unspent, so this must never
	 *         return null after having changed anything.
	 */
	@Nullable
	public synchronized ChestOpenResult openTollChest(String tierKey, String spentCardUuid) {
		if (pending != null || !cardDatabase.isReady())
			return null;
		return deal(roll(Tuning.Chest.GILDED, null, null, 0, null,
			tierKey == null ? RollOdds.UNTIERED : tierKey, spentCardUuid),
			CeremonyBus.Type.CHEST_OPEN);
	}

	/**
	 * Is the free First Colours chest due to be dealt right now?
	 *
	 * <p>Every term is a way the gift could go wrong. The owed flag on its own
	 * would re-deal the chest on every login until a reveal happened to close; an
	 * unfinished reveal — live in memory OR still serialized by a client that
	 * died mid-ceremony — has to be committed first, because writing this chest's
	 * blob over it would silently destroy one the player paid for; and rolling
	 * before the card database is ready would draw from an empty pool.
	 */
	static boolean firstColoursDue(GachaState state, boolean revealPending, boolean dbReady) {
		return state != null
			&& state.isFirstColoursChestOwed()
			&& !revealPending
			&& state.getPendingChestBlob() == null
			&& dbReady;
	}

	/**
	 * The free chest that rides behind an account's very first style roll.
	 * Deliberately NOT gated on rustyAvailable(): the lifetime cap limits what
	 * the shop will sell, and withholding a gift because the player already
	 * bought their three would punish exactly the wrong account.
	 *
	 * <p>{@code preferredCardIds} steers the first card only, and only when the
	 * rarity band it lands in actually holds one of them — see constrained(). A
	 * preference, never a guarantee, so a sparse card database still deals.
	 *
	 * <p>The owed flag clears in the SAME mutate that persists the blob rather
	 * than via persistPending(): two writes leave a crash window that either
	 * re-gifts the chest or eats it, and the blob alone is enough for
	 * recoverPending() to finish the job.
	 */
	@Nullable
	public synchronized ChestOpenResult openFirstColoursChest(Set<Integer> preferredCardIds) {
		GachaState state = stateService.get();
		if (!firstColoursDue(state, pending != null, cardDatabase.isReady()))
			return null;
		Predicate<CardDefinition> require =
			preferredCardIds == null || preferredCardIds.isEmpty()
				? null
				: c -> preferredCardIds.contains(c.getCardId());
		ChestOpenResult result = roll(Tuning.Chest.RUSTY, null, null, 0, require, null, null);
		pending = result;
		rerollUsedThisReveal = false;
		final String blob = gson.toJson(result);
		stateService.mutate(s -> s.withPendingChestBlob(blob).withFirstColoursChestOwed(false));
		ceremonyBus.submit(CeremonyBus.Type.CHEST_OPEN, result);
		log.debug("First Colours chest dealt ({} preferred cards)",
			preferredCardIds == null ? 0 : preferredCardIds.size());
		return result;
	}

	/**
	 * {@code require} steers the FIRST card only, and only as a preference. A
	 * chest that promised the player something usable must keep that promise in
	 * the card they see first, while the rest of the box stays honest gacha.
	 * Every caller that has nothing to steer passes an explicit null; the
	 * convenience overload that used to hide it was pure budget.
	 */
	ChestOpenResult roll(Tuning.Chest tier, String themedSetTag,
		GearSlot targetSlot, long price,
		Predicate<CardDefinition> require,
		String tollTierKey, String excludeCardUuid) {
		GachaState state = stateService.get();
		int opensSinceEpic = state == null ? 0 : state.getOpensSinceEpic();
		boolean rusty = tier == Tuning.Chest.RUSTY;

		// stardust blessing: consumed by the next chest that can actually roll
		// shiny — themed chests roll no variants, so they pass the blessing
		// through untouched. The flag clears at roll time (persisted
		// immediately) so a crash cannot re-arm.
		boolean blessed = themedSetTag == null && state != null && state.isStardustBlessArmed();
		if (blessed)
			stateService.mutate(s -> s.withStardustBlessArmed(false));

		// jackpot upgrade (regular untargeted chests only; the starter tier
		// never upgrades — it must stay the humblest box in the shop).
		//
		// rng.chance is the LAST && term deliberately: && short-circuits, so a
		// themed, slot-targeted or Rusty chest still consumes no RNG here, exactly
		// as the nested ifs this replaces did. Move it earlier and every fixed-seed
		// test shifts.
		// tollTierKey joins the exclusions for the same reason targetSlot is here:
		// a pull that must come from ONE tier ladder has nothing to upgrade INTO,
		// and the && short-circuit keeps it consuming no RNG, so no fixed-seed
		// test moves.
		boolean jackpot = themedSetTag == null && targetSlot == null && tollTierKey == null && !rusty
			&& rng.chance(Tuning.JACKPOT_CHANCE);
		// Chest is declared RUSTY, BATTERED, GILDED, ORNATE, so ordinal + 1 IS the
		// one-tier promotion: BATTERED -> GILDED, GILDED -> ORNATE, the only two
		// steps the ladder has. ORNATE is excluded because it is the top of the shop
		// — its jackpot pays a fourth card below instead — and RUSTY can never get
		// here at all because !rusty gates the roll. That is a real dependency on
		// the enum's declaration order, which ChestJackpotLadderTest pins.
		Tuning.Chest effective = jackpot && tier != Tuning.Chest.ORNATE
			? Tuning.Chest.values()[tier.ordinal() + 1]
			: tier;
		int cardCount = targetSlot != null || tollTierKey != null
			? 1
			: Tuning.CHEST_CARDS.get(effective);
		if (jackpot && tier == Tuning.Chest.ORNATE) {
			cardCount++; // ornate jackpot: 4th card
		}

		// pity (themed chests are free rewards and sit outside pity; Rusty can
		// never pay Epic+ so it neither benefits from nor advances pity)
		boolean pityEligible = themedSetTag == null && !rusty;
		boolean pityBreak = pityEligible && opensSinceEpic + 1 >= Tuning.PITY_HARD_CAP;
		double pityBonus = pityEligible
			? Math.max(0, opensSinceEpic - Tuning.PITY_SOFT_START) * Tuning.PITY_BONUS_PER_OPEN
			: 0;

		List<CardDefinition> pool = poolFor(targetSlot == null ? null : targetSlot.name(),
			themedSetTag, rusty, state, tollTierKey);

		// themed chests roll no variants at all (unchanged); Rusty rolls no
		// holograms (too grand for the starter box) but shiny at a juiced rate
		boolean hologramsAllowed = themedSetTag == null && !rusty;
		double shinyChance = themedSetTag != null ? 0
			: (rusty ? Tuning.RUSTY_SHINY_CHANCE : Tuning.SHINY_CHANCE);
		int shinyAttempts = blessed ? 2 : 1;
		Set<String> ownedKeys = ownedKeys(state, excludeCardUuid);
		List<RolledSlot> slots = new ArrayList<>(cardCount);
		for (int i = 0; i < cardCount; i++) {
			// The ternary on `rarity` is load-bearing, not cosmetic: it
			// short-circuits, so the guaranteed pity card still consumes NO
			// rollRarity draw. Turn it into an unconditional call whose result is
			// then discarded and every fixed-seed test in the suite moves.
			boolean locked = i == 0 && pityBreak;
			Rarity rarity = locked
				? Rarity.LEGENDARY
				: rollRarity(Tuning.CHEST_ODDS.get(effective), pityBonus);
			RolledSlot slot = rollSlot(pool, rarity, hologramsAllowed, shinyChance,
				shinyAttempts, ownedKeys, i == 0 ? require : null);
			slots.add(locked ? slot.withPityLocked(true) : slot);
		}

		// themed chests never grant deeds; the null check stays FIRST so it still
		// gates whether the deed roll is drawn at all
		boolean deed = themedSetTag == null
			&& rng.chance(Tuning.DEED_CHANCE.getOrDefault(tier, 0.0));

		return new ChestOpenResult(tier, effective, jackpot, pityBreak, deed, themedSetTag,
			targetSlot == null ? null : targetSlot.name(), slots, price, blessed, tollTierKey);
	}

	Rarity rollRarity(double[] odds, double pityBonusPercent) {
		// shift pity bonus into EPIC+LEGENDARY mass, taken from COMMON. Shared with
		// the odds disclosure so the panel cannot quote a different pity curve than
		// the one the roll runs; the cumulative walk below stays here on purpose,
		// because pickHologram's near-identical walk falls back to the LAST element
		// while this one falls back to index 0 (EarlyGameMathTest.rustyRollsCommonOnly
		// depends on exactly that).
		double[] adjusted = RollOdds.adjustOdds(odds, pityBonusPercent);
		double total = 0;
		for (double odd : adjusted) {
			total += odd;
		}
		double roll = rng.nextDouble() * total;
		double cumulative = 0;
		for (int i = 0; i < adjusted.length; i++) {
			cumulative += adjusted[i];
			if (roll < cumulative)
				return Rarity.values()[i];
		}
		return Rarity.COMMON;
	}

	RolledSlot rollSlot(List<CardDefinition> pool, Rarity rarity, boolean hologramsAllowed,
		double shinyChance, int shinyAttempts, Set<String> ownedKeys) {
		return rollSlot(pool, rarity, hologramsAllowed, shinyChance, shinyAttempts, ownedKeys, null);
	}

	RolledSlot rollSlot(List<CardDefinition> pool, Rarity rarity, boolean hologramsAllowed,
		double shinyChance, int shinyAttempts, Set<String> ownedKeys,
		Predicate<CardDefinition> require) {
		// hologram replaces the card entirely
		if (hologramsAllowed && !cardDatabase.holograms().isEmpty() && rng.chance(Tuning.HOLOGRAM_CHANCE)) {
			HologramDefinition holo = pickHologram();
			boolean dupe = ownedKeys.contains("H:" + holo.getTierKey());
			return new RolledSlot(holo.getRarity(), -1, holo.getTierKey(), Variant.HOLOGRAM, dupe, false, false);
		}
		CardDefinition card = pickCardOfRarity(pool, rarity, require);
		Variant variant = Variant.NORMAL;
		boolean nearMiss = false;
		if (shinyChance > 0 && card.isShinyEligible()) {
			// the raw roll is captured (not chance()) so the near-miss band is
			// observable; draw count is unchanged except for blessed retries
			double band = shinyChance * Tuning.STARDUST_NEAR_MISS_MULT;
			for (int attempt = 0; attempt < Math.max(1, shinyAttempts); attempt++) {
				double r = rng.nextDouble();
				if (r < shinyChance) {
					variant = Variant.SHINY;
					nearMiss = false;
					break;
				}
				if (r < band)
					nearMiss = true;
			}
		}
		boolean duplicate = variant == Variant.NORMAL && ownedKeys.contains("C:" + card.getCardId());
		return new RolledSlot(card.getRarity(), card.getCardId(), null, variant, duplicate, false, nearMiss);
	}

	/**
	 * {@code require} narrows the candidate list BEFORE the draw instead of
	 * rejecting after it, so a constrained pick still costs exactly one
	 * rng.pick. With require == null the candidate lists — and therefore every
	 * nextInt bound — are identical to the unconstrained build, so no existing
	 * seed moves.
	 */
	CardDefinition pickCardOfRarity(List<CardDefinition> pool, Rarity rarity,
		Predicate<CardDefinition> require) {
		RollBucket bucket = bucketFor(pool, rarity, require);
		return bucket.isLeaned() ? pickLeaned(bucket.getCards()) : rng.pick(bucket.getCards());
	}

	/**
	 * The exact candidate list a roll of this rarity would draw from — everything
	 * pickCardOfRarity used to do except the draw itself. Split out because it
	 * consumes NO RNG, which is what lets oddsFor() quote the roll's own numbers
	 * instead of a parallel transcription that would drift.
	 *
	 * <p>Two passes rather than two near-identical loops. Pass 0 is the real draw:
	 * Epic+ may land anywhere, below that stay near what the player's levels can
	 * actually wield (see isReachable for the headroom). Pass 1 is the fallback for
	 * when the gate excluded every card of every rarity, and drops BOTH the gate
	 * and the preference — dropping the preference is free rather than a change,
	 * because constrained(list, null) hands back the very same list instance, so
	 * pass 1 builds exactly the list the old unconstrained loop built and no
	 * rng.pick bound moves.
	 *
	 * <p>Each pass walks r DOWN the Rarity declaration order: a rarity with no
	 * candidates falls back to the next one below it, never above.
	 */
	RollBucket bucketFor(List<CardDefinition> pool, Rarity rarity,
		Predicate<CardDefinition> require) {
		for (int pass = 0; pass < 2; pass++) {
			final boolean gate = pass == 0 && !rarity.atLeast(Rarity.EPIC);
			for (int r = rarity.ordinal(); r >= 0; r--) {
				final Rarity target = Rarity.values()[r];
				List<CardDefinition> candidates = constrained(pool.stream()
					.filter(c -> c.getRarity() == target)
					.filter(c -> !gate || isReachable(c, true))
					.collect(Collectors.toList()), pass == 0 ? require : null);
				if (!candidates.isEmpty()) {
					// `gate` doubles as the leaned flag on purpose: the house lean
					// applies exactly when the proximity gate ran, so one variable
					// cannot let the two drift apart.
					return new RollBucket(candidates, gate);
				}
			}
		}
		return new RollBucket(pool, false);
	}

	/**
	 * The house lean: inside a proximity-gated bucket, gear the player can wield
	 * today outweighs gear that only got in through the headroom. Weighted rather
	 * than filtered so the headroom band stays reachable — it is deliberate
	 * aspirational slack, not an accident, and leanWeight() is asserted never to
	 * return zero.
	 *
	 * <p>When every candidate sits in the same band the weight vector is flat, and a
	 * flat weight vector IS a uniform draw, so this takes rng.pick() instead: same
	 * distribution, same single next() call. That branch is what keeps every
	 * fixed-seed test byte-identical, because isReachable is uniformly true when
	 * client is null — which is every headless test.
	 */
	private CardDefinition pickLeaned(List<CardDefinition> candidates) {
		double[] weights = new double[candidates.size()];
		double total = 0;
		int wieldable = 0;
		for (int i = 0; i < candidates.size(); i++) {
			boolean now = isReachable(candidates.get(i), false);
			if (now)
				wieldable++;
			// total is accumulated from the very values the walk below reads, so the
			// two can never disagree in the last bit and drop off the end
			weights[i] = RollOdds.leanWeight(now);
			total += weights[i];
		}
		if (wieldable == 0 || wieldable == candidates.size())
			return rng.pick(candidates);
		return candidates.get(RollOdds.weightedIndex(rng.nextDouble() * total, weights));
	}

	/**
	 * The constraint is a PREFERENCE, not a filter: narrowing to nothing hands
	 * back the full list, so a chest can never fail to deal a card. Returning the
	 * very same list instance on the null path is the point — every rng.pick
	 * bound must stay bit-identical to the unconstrained build.
	 */
	static List<CardDefinition> constrained(List<CardDefinition> candidates,
		Predicate<CardDefinition> require) {
		if (require == null || candidates.isEmpty())
			return candidates;
		List<CardDefinition> narrowed = candidates.stream()
			.filter(require)
			.collect(Collectors.toList());
		return narrowed.isEmpty() ? candidates : narrowed;
	}

	/**
	 * The Rusty starter pool: only slots the player has unlocked, and tiered gear
	 * only up to what is wieldable today (no headroom). Untiered gear is not
	 * level-filtered at all — isReachable exempts it by design — so this is a
	 * clamp on the tier ladders, not a hard wieldability guarantee. Shared by
	 * roll() and rerollSlot() so the two can never drift.
	 */
	private List<CardDefinition> rustyPool(GachaState state) {
		Set<String> deeded = state == null || state.getDeededSlots() == null
			? Set.of() : state.getDeededSlots();
		return cardDatabase.all().values().stream()
			.filter(c -> c.getSlot() != null && deeded.contains(c.getSlot().name()))
			.filter(c -> isReachable(c, false))
			.collect(Collectors.toList());
	}

	/**
	 * The card pool a chest of this shape draws from, plus the empty-pool fallback.
	 * Shared by roll() and rerollSlot() so a reroll can never draw from a different
	 * pool than the open it is re-flipping.
	 *
	 * <p>Keyed on the gear slot's NAME rather than the enum because that is how
	 * ChestOpenResult carries it (it has to survive Gson), and GearSlot.name() /
	 * valueOf() round-trip exactly, so the filtered pool is unchanged.
	 *
	 * <p>An empty pool has two causes, only one of which is a defect: bosses.json
	 * naming a set sets.json does not define (a dataset bug, integrity-tested) —
	 * and, perfectly legitimately, a Rusty pool on an account whose deeded slots
	 * hold nothing wieldable yet. Both fall back to the whole card list so a chest
	 * always deals, and both log, because the first case is worth shouting about
	 * and the second is rare enough that the noise is cheap. Note this makes the
	 * reroll path log where it used to fall back silently, and turns a reroll of an
	 * empty themed/slot-targeted pool from an rng.pick crash into the same fallback
	 * the open itself would have taken.
	 */
	private List<CardDefinition> poolFor(String targetSlot, String themedSetTag,
		boolean rusty, GachaState state, String tollTierKey) {
		List<CardDefinition> pool;
		if (tollTierKey != null) {
			// The Toll's tier ladder. RollOdds.UNTIERED ("") is the band for cards
			// whose definition carries no tier at all, matching the convention
			// RollOdds.bandKeyOf already uses — which is why the empty string can
			// stand in for null here without a second flag saying "this is a toll".
			//
			// Routing this through openThemedChest(tierKey) instead would look
			// equivalent and silently is not: setMembers() knows set tags, not tier
			// keys, so it returns empty, the guard below "falls back to all cards",
			// and the player who surrendered a veteran card gets an ordinary chest
			// with no sign anything went wrong.
			boolean untiered = RollOdds.UNTIERED.equals(tollTierKey);
			pool = cardDatabase.all().values().stream()
				.filter(c -> untiered
					? c.getTierKey() == null
					: tollTierKey.equals(c.getTierKey()))
				.collect(Collectors.toList());
		}
		else if (targetSlot != null) {
			GearSlot slot = GearSlot.valueOf(targetSlot);
			pool = cardDatabase.all().values().stream()
				.filter(c -> c.getSlot() == slot)
				.collect(Collectors.toList());
		}
		else if (themedSetTag != null) {
			pool = cardDatabase.setMembers(themedSetTag);
		}
		else if (rusty) {
			pool = rustyPool(state);
		}
		else {
			pool = new ArrayList<>(cardDatabase.all().values());
		}
		if (pool.isEmpty()) {
			log.warn("empty chest pool (themedSetTag={}, targetSlot={}) — falling back to all cards",
				themedSetTag, targetSlot);
			pool = new ArrayList<>(cardDatabase.all().values());
		}
		return pool;
	}

	/**
	 * Is this card's tier within reach of the player's levels? With
	 * {@code allowHeadroom} it also admits the aspirational band just above them.
	 *
	 * <p>Headroom is a flag rather than a number because the two branches below
	 * measure it in different units — metal in tier ranks, dhide/robes in skill
	 * levels. Callers pass it explicitly (the one-argument convenience overload was
	 * deleted as pure budget); true is the roll's proximity gate, false is "can
	 * wield today", which is what the lean and the Rusty pool ask for.
	 */
	boolean isReachable(CardDefinition card, boolean allowHeadroom) {
		if (card.getTierKey() == null || client == null || tierTable == null) {
			return true; // untiered gear (or headless tests) is never proximity-gated
		}
		String ladder = tierTable.ladderOf(card.getTierKey());
		if (ladder == null)
			return true;
		switch (ladder) {
			case "metal":
				RangedMetal ranged = rangedMetal.of(card.getName());
				if (ranged != null) {
					// Arrows, bolts, javelins, crossbows, darts, knives and thrownaxes wear a
					// metal prefix but are Ranged gear, and mostly not on the ladder's numbers
					// (a rune crossbow is 61, not 40). Measured in levels like dhide/robes, so
					// the level headroom; no ranged weapon or ammunition carries a Defence gate.
					return Tuning.withinReach(
						client.getRealSkillLevel(Skill.RANGED),
						client.getRealSkillLevel(Skill.DEFENCE),
						rangedMetal.reqRangedLevel(ranged, card.getTierKey(),
							tierTable.reqLevelOf(card.getTierKey())),
						1,
						allowHeadroom ? Tuning.ROLL_LEVEL_HEADROOM : 0);
				}
				// Melee metal is left rank-wise on purpose: TIER_RANK_LEVELS transcribes the
				// metal ladder exactly, so this is already correct. The max() is load-bearing
				// too — metal weapons gate on Attack and metal armour on Defence, never both,
				// so a second Defence term here would lock an Attack pure out of rune weapons
				// it can wield today.
				int metalLevel = Math.max(client.getRealSkillLevel(Skill.ATTACK),
					client.getRealSkillLevel(Skill.DEFENCE));
				return card.getTierRank() <= Tuning.maxRankForLevel(metalLevel)
					+ (allowHeadroom ? Tuning.ROLL_TIER_HEADROOM : 0);
			case "dhide":
				return ladderWithinReach(card,
					client.getRealSkillLevel(Skill.RANGED), allowHeadroom);
			case "robes":
				return ladderWithinReach(card,
					client.getRealSkillLevel(Skill.MAGIC), allowHeadroom);
			default:
				return true;
		}
	}

	/**
	 * Dhide/robes ranks are power ordinals on their own ladder, not levels, so these
	 * two read explicit requirements out of tiers.json rather than borrowing metal's
	 * rank table (which understated them by 15-40 levels). Defence is applied to BODY
	 * only: the body is the piece that carries a Defence gate on every tier of both
	 * ladders, while d'hide chaps and vambraces carry none and would otherwise be
	 * over-gated for a low-Defence ranger.
	 */
	private boolean ladderWithinReach(CardDefinition card, int primaryLevel, boolean allowHeadroom) {
		int reqDefence = card.getSlot() == GearSlot.BODY
			? tierTable.reqDefenceOf(card.getTierKey())
			: 1;
		return Tuning.withinReach(primaryLevel,
			client.getRealSkillLevel(Skill.DEFENCE),
			tierTable.reqLevelOf(card.getTierKey()), reqDefence,
			allowHeadroom ? Tuning.ROLL_LEVEL_HEADROOM : 0);
	}

	HologramDefinition pickHologram() {
		List<HologramDefinition> holos = new ArrayList<>(cardDatabase.holograms().values());
		int maxRank = 1;
		for (HologramDefinition holo : holos) {
			maxRank = Math.max(maxRank, rankOf(holo));
		}
		double[] weights = new double[holos.size()];
		double total = 0;
		for (int i = 0; i < holos.size(); i++) {
			weights[i] = Math.pow(maxRank - rankOf(holos.get(i)) + 1, 2);
			total += weights[i];
		}
		// the same cumulative walk this used to open-code, including the landing
		// spot when a rounding crumb pushes the roll past the total: weightedIndex
		// returns the LAST index, which is what holos.get(holos.size() - 1) did.
		// One rng.nextDouble(), in the same position, so no seeded test moves.
		return holos.get(RollOdds.weightedIndex(rng.nextDouble() * total, weights));
	}

	private int rankOf(HologramDefinition holo) {
		return holo.getRarity().ordinal() * 2 + 1; // proxy: rarity encodes rank band
	}

	// --- Odds disclosure ---

	/**
	 * The true post-lean odds for ONE ORDINARY card out of this chest, derived from
	 * the same bucketFor()/adjustOdds()/leanWeight() the roll uses, so the panel
	 * cannot drift from reality.
	 *
	 * <p>Scoped to one ordinary card on purpose: the jackpot tier upgrade, the
	 * hologram that replaces a card outright and the pity hard-cap Legendary are
	 * NAMED in the panel rather than blended in, so every number shown is one a
	 * player can actually check against their own opens.
	 *
	 * <p>Reads live skill levels through isReachable — CLIENT THREAD ONLY.
	 * Deliberately NOT synchronized, unlike openChest/rerollSlot: both they and this
	 * run on the client thread and so cannot interleave, and this touches neither
	 * `pending` nor state, so the lock would buy nothing but contention with a reveal
	 * in flight.
	 */
	public OddsDisclosure oddsFor(Tuning.Chest tier) {
		GachaState state = stateService.get();
		// these five mirror roll() exactly — keep them adjacent so a reviewer can
		// diff the two blocks by eye
		boolean rusty = tier == Tuning.Chest.RUSTY;
		int opensSinceEpic = state == null ? 0 : state.getOpensSinceEpic();
		int hardCap = Tuning.PITY_HARD_CAP;
		double pityBonus = rusty
			? 0
			: Math.max(0, opensSinceEpic - Tuning.PITY_SOFT_START) * Tuning.PITY_BONUS_PER_OPEN;
		boolean pityBreakNext = !rusty && opensSinceEpic + 1 >= hardCap;

		List<CardDefinition> pool = rusty
			? rustyPool(state)
			: new ArrayList<>(cardDatabase.all().values());
		if (pool.isEmpty())
			pool = new ArrayList<>(cardDatabase.all().values());

		// one pass, not five: the rarity buckets walk down and revisit cards, and
		// cardId is the key of cardDatabase.all() so it is unique per definition
		Map<Integer, Boolean> wieldableByCardId = new HashMap<>();
		for (CardDefinition card : pool) {
			wieldableByCardId.put(card.getCardId(), isReachable(card, false));
		}

		double[] adjusted = RollOdds.adjustOdds(Tuning.CHEST_ODDS.get(tier), pityBonus);
		double[] rarityShare = RollOdds.normalize(adjusted);
		Map<RollOdds.TierBand, Double> totals = new LinkedHashMap<>();
		// names per row, for the tooltip that has to name the pieces a split tier
		// leaves out of reach. Sorted and de-duplicated: a card can be revisited
		// across rarity buckets, and an arbitrary order would reshuffle every rebuild.
		Map<RollOdds.TierBand, SortedSet<String>> namesByBand = new HashMap<>();
		for (Rarity rarity : Rarity.values()) {
			double share = rarityShare[rarity.ordinal()];
			if (share <= 0)
				continue;
			RollBucket bucket = bucketFor(pool, rarity, null);
			List<CardDefinition> cards = bucket.getCards();
			boolean[] flags = new boolean[cards.size()];
			// one pass fills flags[] and files the name, because the name only ever
			// needs its OWN index's flag — nothing here reads a later one
			for (int i = 0; i < cards.size(); i++) {
				CardDefinition card = cards.get(i);
				flags[i] = wieldableByCardId.getOrDefault(card.getCardId(), true);
				namesByBand
					.computeIfAbsent(RollOdds.bandOf(card, flags[i]),
						k -> new TreeSet<>(String.CASE_INSENSITIVE_ORDER))
					.add(card.getName());
			}
			for (Map.Entry<RollOdds.TierBand, Double> entry
				: RollOdds.tierShares(cards, flags, bucket.isLeaned()).entrySet()) {
				totals.merge(entry.getKey(), entry.getValue() * share, Double::sum);
			}
		}

		List<TierOdds> rows = new ArrayList<>(totals.size());
		double wieldableTotal = 0;
		double headroomTotal = 0;
		double untieredTotal = 0;
		for (Map.Entry<RollOdds.TierBand, Double> entry : totals.entrySet()) {
			double probability = entry.getValue();
			if (probability <= 0)
				continue;
			RollOdds.TierBand band = entry.getKey();
			boolean untiered = RollOdds.UNTIERED.equals(band.getTierKey());
			if (untiered)
				untieredTotal += probability;
			else if (band.isWieldableNow()) {
				wieldableTotal += probability;
			}
			else {
				headroomTotal += probability;
			}
			String display = untiered || tierTable == null
				? band.getTierKey()
				: tierTable.displayNameOf(band.getTierKey());
			SortedSet<String> names = namesByBand.get(band);
			rows.add(new TierOdds(band.getTierKey(), display, band.isWieldableNow(), probability,
				names == null ? Collections.emptyList() : new ArrayList<>(names)));
		}
		rows.sort(Comparator.comparingDouble(TierOdds::getProbability).reversed());

		double[] rarityPercent = new double[rarityShare.length];
		for (int i = 0; i < rarityShare.length; i++) {
			rarityPercent[i] = rarityShare[i] * 100;
		}
		return new OddsDisclosure(tier, rarityPercent, rows, wieldableTotal, headroomTotal,
			untieredTotal, pityBonus, opensSinceEpic, hardCap, pityBreakNext);
	}

	// --- In-reveal reroll ---

	public synchronized boolean canReroll(int slotIndex) {
		GachaState state = stateService.get();
		return pending != null && !rerollUsedThisReveal
			&& state != null && state.getRerollTokens() > 0
			&& slotIndex >= 0 && slotIndex < pending.getSlots().size()
			&& !pending.getSlots().get(slotIndex).isPityLocked();
	}

	/** Spend a reroll token to re-flip one slot; returns the new slot or null. */
	@Nullable
	public synchronized RolledSlot rerollSlot(int slotIndex) {
		if (!canReroll(slotIndex))
			return null;
		GachaState state = stateService.get();
		stateService.mutate(s -> s.withRerollTokens(s.getRerollTokens() - 1));
		rerollUsedThisReveal = true;

		boolean rusty = pending.getPurchasedTier() == Tuning.Chest.RUSTY;
		// A Toll pull rerolls back into its OWN ladder — the tier is what the
		// player surrendered a card for, so a reroll that escaped it would be a
		// second chest rather than a second draw.
		List<CardDefinition> pool = poolFor(pending.getTargetSlot(), pending.getThemedSetTag(),
			rusty, state, pending.getTollTierKey());
		boolean hologramsAllowed = pending.getThemedSetTag() == null && !rusty;
		double shinyChance = pending.getThemedSetTag() != null ? 0
			: (rusty ? Tuning.RUSTY_SHINY_CHANCE : Tuning.SHINY_CHANCE);
		int shinyAttempts = pending.isStardustBlessed() ? 2 : 1;
		Rarity rarity = rollRarity(Tuning.CHEST_ODDS.get(pending.getEffectiveTier()), 0);
		RolledSlot fresh = rollSlot(pool, rarity, hologramsAllowed, shinyChance, shinyAttempts,
			ownedKeys(state, null));

		List<RolledSlot> slots = new ArrayList<>(pending.getSlots());
		slots.set(slotIndex, fresh);
		// withSlots() is the generated copy of every OTHER field verbatim; the list
		// is freshly built so it is never == and a real copy always happens
		pending = pending.withSlots(slots);
		persistPending();
		notifyListeners(ChestListener::onRerollSpent);
		return fresh;
	}

	/**
	 * Fan one event out to every listener — the three call sites (reroll spent,
	 * chest committed, deed claimed) had this loop copied out verbatim.
	 *
	 * <p>The defensive copy is what lets a listener add or drop another one from
	 * inside its own callback without a ConcurrentModificationException, and the
	 * per-listener catch is what stops a single broken listener from stranding a
	 * chest half-committed: by the time this runs the state write and the GC award
	 * have already happened, so an exception escaping here would lose the
	 * notification AND the return value with nothing rolled back. Both now live in
	 * {@link Listeners#fire} — this wrapper stays because the three call sites
	 * would otherwise each have to repeat the collection and the warning text.
	 */
	private void notifyListeners(Consumer<ChestListener> event) {
		Listeners.fire(chestListeners, event, "chest listener failed");
	}

	// --- Commit (reveal closed or aborted) ---

	/** Apply the pending open to state. Returns GC gained from duplicates. */
	public synchronized long commitPending() {
		if (pending == null)
			return 0;
		ChestOpenResult result = pending;
		pending = null;

		long dupeGc = 0;
		List<OwnedCard> newCards = new ArrayList<>();
		for (RolledSlot slot : result.getSlots()) {
			if (slot.isDuplicate()) {
				dupeGc += Tuning.DUPLICATE_GC.get(slot.getRarity());
				continue;
			}
			String provenance = (result.getThemedSetTag() == null ? "chest:" : "kc-chest:")
				+ result.getEffectiveTier();
			newCards.add(new OwnedCard(UUID.randomUUID().toString(),
				slot.getCardId(), slot.getHologramTier(), slot.getVariant(),
				System.currentTimeMillis(), provenance, 0));
		}

		final long dupeGcFinal = dupeGc;
		GachaState beforeCommit = stateService.get();
		stateService.mutate(s -> {
			List<OwnedCard> owned = new ArrayList<>(s.getOwnedCards());
			owned.addAll(newCards);
			Map<String, Integer> byTier = new HashMap<>(s.getChestsOpenedByTier());
			byTier.merge(result.getPurchasedTier().name(), 1, Integer::sum);
			// One walk, two tallies. Pity counts CARDS since the last Epic+ card, in
			// reveal order; stardust counts near-misses, which bank at commit
			// (rerolls replaced their slot, so this can never double-count) and arm
			// the next chest once 8 are held. The pity counter is computed even for
			// chests that sit outside pity and then thrown away — both reads are
			// pure, so the wasted arithmetic simply buys one less pass over the list.
			int counter = s.getOpensSinceEpic();
			int nearMisses = 0;
			for (RolledSlot slot : result.getSlots()) {
				counter = slot.getRarity().atLeast(Rarity.EPIC) ? 0 : counter + 1;
				if (slot.isNearMiss())
					nearMisses++;
			}
			GachaState next = s.withOwnedCards(owned).withChestsOpenedByTier(byTier)
				.withPendingChestBlob(null);
			if (result.getThemedSetTag() == null
				&& result.getPurchasedTier() != Tuning.Chest.RUSTY) {
				next = next.withOpensSinceEpic(counter);
			}
			if (nearMisses > 0) {
				int dust = s.getStardust() + nearMisses;
				boolean armed = s.isStardustBlessArmed();
				if (!armed && dust >= Tuning.STARDUST_REQUIRED) {
					dust -= Tuning.STARDUST_REQUIRED;
					armed = true;
				}
				next = next.withStardust(dust).withStardustBlessArmed(armed);
			}
			if (result.isDeedGranted()) {
				boolean saturated = s.getDeededSlots().size() >= GearSlot.values().length;
				if (!saturated)
					next = next.withPendingDeeds(s.getPendingDeeds() + 1);
			}
			return next;
		});

		GachaState afterCommit = stateService.get();
		if (afterCommit != null && afterCommit.isStardustBlessArmed()
			&& (beforeCommit == null || !beforeCommit.isStardustBlessArmed())) {
			ceremonyBus.submit(CeremonyBus.Type.FANFARE, new CeremonyBus.Fanfare(
				CeremonyBus.Fanfare.Size.SMALL, "Stardust blessing!",
				Tuning.STARDUST_REQUIRED + " stardust consumed — your next chest rolls shiny twice per card.",
				null));
		}

		if (dupeGc > 0)
			creditSink.award(dupeGcFinal, new CreditSink.GcContext(CreditSink.Source.DUPLICATE, null, null));
		if (result.isDeedGranted()) {
			GachaState state = stateService.get();
			if (state != null && state.getDeededSlots().size() >= GearSlot.values().length) {
				creditSink.award(Tuning.DEED_SATURATED_GC,
					new CreditSink.GcContext(CreditSink.Source.DEED_SATURATED, null, null));
			}
			else {
				ceremonyBus.submit(CeremonyBus.Type.DEED_CHOICE, 0);
			}
		}
		notifyListeners(l -> l.onChestCommitted(result, dupeGcFinal));
		return dupeGc;
	}

	// --- Deed choice ---

	public boolean claimDeed(GearSlot slot) {
		GachaState state = stateService.get();
		if (state == null || state.getPendingDeeds() <= 0
			|| state.getDeededSlots().contains(slot.name())) {
			return false;
		}
		stateService.mutate(s -> {
			Set<String> deeded = new HashSet<>(s.getDeededSlots());
			deeded.add(slot.name());
			return s.withDeededSlots(deeded).withPendingDeeds(s.getPendingDeeds() - 1);
		});
		ceremonyBus.submit(CeremonyBus.Type.FANFARE, new CeremonyBus.Fanfare(
			CeremonyBus.Fanfare.Size.LARGE, "Slot Deed: " + slot.getDisplayName(),
			"The " + slot.getDisplayName() + " slot is now unlocked!", null));
		notifyListeners(l -> l.onDeedClaimed(slot));
		return true;
	}

	/** Milestone deed from task completion (already counted in TaskService). */
	public void grantMilestoneDeed() {
		stateService.mutate(s -> s.withPendingDeeds(s.getPendingDeeds() + 1));
	}

	// --- Helpers ---

	/**
	 * The duplicate-test keys for everything the player owns, optionally blind to
	 * ONE card by uuid. Callers with nothing to exclude pass an explicit null; the
	 * one-argument convenience overload that used to hide it had a single caller
	 * and was pure budget.
	 *
	 * <p>The exclusion exists for the Toll (see {@link #openTollChest}), which
	 * deals its pull while the surrendered card is still in the album — that
	 * ordering is deliberate, so a client that dies mid-purchase cannot take the
	 * card and hand back nothing. Without the exclusion the surrendered card would
	 * count as a duplicate of itself, and since the pull is drawn from that card's
	 * OWN tier ladder the collision is common rather than a tail case.
	 *
	 * <p>Skipping by UUID rather than by key is what keeps a second copy honest: a
	 * player holding two of the same card who pays one of them still has the other
	 * in this set, so the pull correctly reads as a duplicate. Removing the KEY
	 * instead would quietly hand them a free non-dupe.
	 */
	static Set<String> ownedKeys(GachaState state, String excludeUuid) {
		Set<String> keys = new HashSet<>();
		if (state == null)
			return keys;
		for (OwnedCard card : state.getOwnedCards()) {
			if (excludeUuid != null && excludeUuid.equals(card.getUuid()))
				continue;
			if (card.isHologram())
				keys.add("H:" + card.getTierKey());
			else if (card.getVariant() == Variant.NORMAL) {
				keys.add("C:" + card.getCardId());
			}
		}
		return keys;
	}
}

package com.gachaman.service;

import com.gachaman.*;
import java.io.*;
import java.util.concurrent.*;
import javax.inject.*;
import lombok.*;
import lombok.extern.slf4j.*;
import net.runelite.api.*;
import net.runelite.client.callback.*;
import net.runelite.client.chat.*;
import net.runelite.client.config.*;
import net.runelite.client.externalplugins.*;
import net.runelite.client.util.*;

/**
 * Update plumbing, which is two different jobs because the client already does
 * the one people expect.
 *
 * <p>RuneLite force-updates every Plugin Hub plugin at client start:
 * ExternalPluginManager.loadExternalPlugins downloads the hub manifest and
 * re-fetches any installed jar whose hash no longer matches. So the code
 * running here is ALWAYS the newest build for this client — there is nothing
 * for a plugin to force, and calling ExternalPluginManager.update() from
 * inside the plugin would ask the client to unload Gachaman while Gachaman is
 * the thing running. What is left is the two gaps that auto-update leaves:
 *
 * <ol>
 * <li>the player is never told they were updated, or what changed — announced
 * on login, keyed on the version the hub actually shipped;
 * <li>a client left open across a hub release keeps running the old jar until
 * it restarts — detected by comparing our jar hash against the manifest's.
 * </ol>
 *
 * <p>Both read their identity through the hub classloader, which only exists
 * for an installed hub build. Under an IDE both come back null and the whole
 * service goes quiet, which is what you want while developing.
 */
@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class UpdateService {
	/** Config key holding the last version we announced. */
	private static final String SEEN_VERSION_KEY = "lastSeenVersion";

	/**
	 * What this release added, in RuneLite chat markup. Rewritten by hand each
	 * release; the version number in front of it is not, so the two can never
	 * drift out of step the way a hardcoded version string does.
	 *
	 * <p>Unread on 1.0.0 by design — a first install announces nothing, so this
	 * line is first seen by players updating from 1.0.0 to whatever follows.
	 * Rewrite it in the same commit that bumps the version.
	 */
	private static final String CHANGELOG = "See the plugin's GitHub for what changed.";

	private static final int CHECK_INITIAL_MINUTES = 10;
	private static final int CHECK_PERIOD_MINUTES = 180;

	private final Client client;
	private final ClientThread clientThread;
	private final ChatMessageManager chatMessageManager;
	private final ConfigManager configManager;
	/**
	 * Deliberately a Provider: ExternalPluginClient is client-internal, with a
	 * private constructor and two @Named bindings. Resolving it eagerly would
	 * make a binding change upstream stop Gachaman from loading at all, over a
	 * courtesy notice. Resolved inside the check instead, where failing just
	 * means no notice.
	 */
	private final Provider<ExternalPluginClient> externalPluginClient;
	private final ScheduledExecutorService executor;

	/** Hub hash we have already nagged about, so a poll cannot repeat itself. */
	private String announcedHash;
	private ScheduledFuture<?> checkTask;

	public void start() {
		if (checkTask == null) {
			// same cadence the client uses for its own hub traffic
			checkTask = executor.scheduleWithFixedDelay(this::checkHub,
				CHECK_INITIAL_MINUTES, CHECK_PERIOD_MINUTES, TimeUnit.MINUTES);
		}
	}

	public void stop() {
		if (checkTask != null) {
			checkTask.cancel(false);
			checkTask = null;
		}
	}

	/**
	 * Announce a version change once. Idempotent through the stored key, so
	 * firing it on every login costs nothing after the first.
	 */
	public void onLoggedIn() {
		PluginHubManifest.DisplayData data =
			ExternalPluginManager.getDisplayData(GachamanPlugin.class);
		if (data == null || data.getVersion() == null) {
			return; // not a hub build
		}
		String version = data.getVersion();
		String seen = configManager.getConfiguration(GachamanConfig.GROUP, SEEN_VERSION_KEY);
		if (version.equals(seen))
			return;
		configManager.setConfiguration(GachamanConfig.GROUP, SEEN_VERSION_KEY, version);
		if (seen == null) {
			return; // a first install is not an update, and has no changelog to read
		}
		chat("<col=ff9040>Gachaman</col> updated to <col=ff9040>v" + version + "</col>. "
			+ CHANGELOG);
	}

	/**
	 * Compare the jar we are running against what the hub is serving. Runs off
	 * the client thread, and stays silent on any failure — a CDN blip is not
	 * worth a chat line, and the next poll retries anyway.
	 */
	private void checkHub() {
		PluginHubManifest.JarData mine = ExternalPluginManager.getJarData(GachamanPlugin.class);
		String internalName = ExternalPluginManager.getInternalName(GachamanPlugin.class);
		if (mine == null || internalName == null) {
			return; // not a hub build
		}
		try {
			for (PluginHubManifest.JarData jar : externalPluginClient.get().downloadManifestLite().getJars()) {
				if (!internalName.equals(jar.getInternalName()))
					continue;
				String hubHash = jar.getJarHash();
				if (hubHash == null || hubHash.equals(mine.getJarHash())) {
					return; // already running it
				}
				// hold the nag until they can actually read it; leaving
				// announcedHash unset means a logged-out player gets it next poll
				if (hubHash.equals(announcedHash) || client.getGameState() != GameState.LOGGED_IN)
					return;
				announcedHash = hubHash;
				chat("A new version of <col=ff9040>Gachaman</col> is on the Plugin Hub."
					+ " Restart your client to update.");
				return;
			}
		}
		// RuntimeException too: this runs on a shared executor, so an unchecked
		// throw here would kill the repeating task and take the notice with it
		catch (IOException | VerificationException | RuntimeException e) {
			log.debug("plugin hub version check failed", e);
		}
	}

	private void chat(String message) {
		clientThread.invokeLater(() -> chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.GAMEMESSAGE)
			.runeLiteFormattedMessage(message)
			.build()));
	}
}

package com.gachaman.service;

import com.gachaman.data.*;
import com.gachaman.model.*;
import java.util.*;
import java.util.function.*;
import java.util.stream.*;
import javax.inject.*;
import lombok.*;
import lombok.extern.slf4j.*;
import net.runelite.client.config.*;

/**
 * The Toll: a weekly chest priced in a CARD rather than in GC.
 *
 * <p>The house names one card out of the player's own album — never junk, never
 * a hologram — and the chest opens only for that card, dealing a blind pull of
 * the tier the card belongs to. Hand over a veteran rune scimitar, get an
 * unknown rune-tier card back.
 *
 * <h2>Why the pick is PERSISTED and not recomputed</h2>
 *
 * <p>{@link WeeklyShopService} recomputes its three offers from a seed on every
 * call and stores nothing at all. That is safe there for one reason only: its
 * pool is the immutable card database, so the same seed indexes the same list
 * forever.
 *
 * <p>The Toll's pool is the player's ALBUM, and an album GROWS during the week.
 * Every chest opened, every shop card bought, and every card that crosses its
 * first kill of service changes the length and the contents of the eligible
 * list — so the same seed would index a DIFFERENT card on Tuesday than it did
 * on Monday, and the Toll would silently rename itself mid-week under a player
 * who was saving up for it. A naive port of the weekly shop's zero-state trick
 * produces exactly that bug, which is what
 * {@code TollServiceTest.pickIsStableAsTheAlbumGrows} exists to catch.
 *
 * <p>So the pick lands in {@link GachaState#getTollWeekKey()} +
 * {@link GachaState#getTollCardUuid()} and is recomputed only when the week key
 * moves or the named uuid is no longer owned. The deterministic seed therefore
 * chooses only the FIRST pick of each week — which is what "stable across a
 * week" actually means. It is not decoration: it keeps the choice reproducible
 * (and so debuggable) without making it re-derivable.
 *
 * <h2>The three states those two fields encode</h2>
 *
 * <ul>
 * <li>week key does not match — re-pick. Fresh state has a null week key, so a
 * new profile lands here too.</li>
 * <li>week key matches, uuid null — PAID. Terminal for the rest of the week.
 * This is the state {@link #purchase()} writes, and it is why consuming the
 * card cannot re-arm the Toll: the "uuid no longer owned" re-pick trigger is
 * never reached, because the null uuid is checked first.</li>
 * <li>week key matches, uuid names an owned card — the live offer. If that uuid
 * is not owned (burned, spent elsewhere), re-pick.</li>
 * </ul>
 *
 * <p>Nothing else re-picks. In particular a re-pick that finds NO eligible card
 * deliberately writes nothing at all — see {@link #resolve}.
 *
 * <h2>A note on the shape of this file</h2>
 *
 * <p>It has been through a compression pass against the Plugin Hub's 200k token
 * ceiling, which counts this source with comments and blank lines stripped. No
 * behaviour moved and nothing player-visible changed: the savings are one-line
 * guards, {@code var} on locals whose type the initialiser already spells out,
 * annotations sharing the line they annotate, and values read once into a local
 * instead of re-derived. In particular the three-state encoding above, and the
 * order in which {@link #resolve} tests it, are exactly as they were — that
 * order is the anti-re-arm guard and no amount of budget buys it.
 */
@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class TollService {
	/**
	 * The refusal the player sees when the Toll names a card they still have
	 * assigned to a loadout slot. Deliberately distinct wording from the unassign
	 * guard's "Take the item off first": one intent (pay the Toll with a card
	 * that is both slotted AND worn) produces two refusals on two surfaces —
	 * unequip, then unassign, then pay — and two identical messages would read as
	 * one button that is simply broken.
	 *
	 * <p>Load-bearing rather than cosmetic: {@link #purchase()} consumes the
	 * card, and consuming a card that is still in the loadout map would leave a
	 * dangling uuid behind in it.
	 */
	public static final String ASSIGNED_REFUSAL = "That card is still in your %s slot";

	/**
	 * Salt that keeps the Toll's draw from correlating with the weekly shop's.
	 * Both mix the same profile key and the same week key, so without a salt the
	 * two would walk the same seeded sequence every week. "Toll" in ASCII.
	 */
	private static final long SEED_SALT = 0x546F6C6CL;

	/**
	 * The seam ChestService fills: deal the blind pull, through the very machinery
	 * every other chest uses (roll -> publish pending -> persist the blob ->
	 * queue the ceremony), so the Toll inherits the deferred commit, the
	 * mid-reveal reroll and the crash recovery instead of reimplementing any of
	 * them badly.
	 *
	 * <p>Declared here as a settable hook — the same shape as
	 * {@link LoadoutService#setAssignHook} — rather than by injecting ChestService
	 * directly, for two reasons. ChestService currently has no tier-scoped opener
	 * and no public way to publish a rolled result ({@code pending},
	 * {@code deal()} and {@code persistPending()} are all private), so the method
	 * this calls has to be added there by whoever owns that file; and until it is,
	 * an unwired hook leaves this class compiling and every other feature green.
	 * An unwired hook refuses the purchase and takes nothing.
	 */
	public interface TollPullDealer {
		/**
		 * @param tierKey        the tier ladder the pull must draw from, or null for
		 *                       the untiered band ({@link RollOdds#UNTIERED}) — see
		 *                       {@link TollOffer#getTierKey()}
		 * @param spentCardUuid  the card being handed over. It is still owned at
		 *                       this instant (see the ordering note on
		 *                       {@link #purchase()}), so it MUST be excluded from
		 *                       the roll's duplicate test — drop it from
		 *                       {@code ownedKeys(state)} for this roll only.
		 *                       <p>Not a tail case: the pull is drawn from the
		 *                       surrendered card's OWN tier ladder, so its cardId is
		 *                       one of a small pool and comes up often. Without the
		 *                       exclusion, paying a 300-kill veteran and pulling its
		 *                       own cardId reads as a duplicate and pays a handful of
		 *                       GC instead of dealing the card back — the player has
		 *                       destroyed a veteran card for pocket change.
		 * @return the dealt open, or null when nothing could be dealt (a reveal
		 *         already in flight, database not ready). A null return MUST mean
		 *         nothing was taken.
		 */
		ChestService.ChestOpenResult dealTollPull(String tierKey, String spentCardUuid);
	}

	/** Everything the shop panel needs to render the offer, so it re-derives none of it. */
	@Value
	public static class TollOffer {
		/** The card the house is asking for. Never a hologram. */
		OwnedCard card;
		/** Album-style name, including the "(Shiny)" suffix when it applies. */
		String displayName;
		/**
		 * The tier ladder the pull will draw from — null when the named card is
		 * untiered (or its definition has gone missing), which draws the untiered
		 * band rather than nothing. Untiered cards are eligible because the owner
		 * settled the eligibility test as exactly {@code !hologram && served > 0},
		 * and narrowing it here would be re-deciding that.
		 */
		String tierKey;
		/** The loadout slot the card still occupies, or null when it is free to hand over. */
		GearSlot assignedSlot;
		/** Why the Toll cannot be paid right now; null when it can. */
		String refusal;
	}

	/** The outcome of {@link #resolve}: which uuid to offer, and whether it must be written. */
	@Value
	static class Pick {
		String uuid;
		boolean rewrite;
	}

	private final GachaStateService stateService;
	private final WeeklyShopService weeklyShop;
	private final ServiceRecordService serviceRecords;
	private final LoadoutService loadoutService;
	private final CardDatabase cardDatabase;
	private final ConfigManager configManager;

	@Setter private TollPullDealer dealer;

	/**
	 * Borrowed from the weekly shop rather than re-derived so there is ONE ISO
	 * week boundary in the plugin. Two transcriptions of the same calendar rule
	 * would eventually disagree at a year edge, and the two features would roll
	 * over on different days for the same player.
	 */
	public String currentWeekKey() { return weeklyShop.currentWeekKey(); }

	/**
	 * True once this week's Toll has been paid — terminal until the week turns.
	 *
	 * <p>Read together with {@link #currentOffer()} this is a THREE-way state, not
	 * a boolean, and a panel needs all three to write the right line:
	 *
	 * <table>
	 * <caption>What the pair means</caption>
	 * <tr><th>currentOffer()</th><th>paidThisWeek()</th><th>the player is told</th></tr>
	 * <tr><td>non-null</td><td>false</td><td>the live offer — render the card and the
	 * button, disabled with {@link TollOffer#getRefusal()} when that is non-null</td></tr>
	 * <tr><td>null</td><td>true</td><td>"paid" — comes back next week</td></tr>
	 * <tr><td>null</td><td>false</td><td>no card in the album has a Service Record
	 * yet, so the house has nothing to ask for. This one arrives on its own the
	 * moment a card earns its first kill; it is not an error and not a wait for
	 * the week to turn.</td></tr>
	 * </table>
	 *
	 * <p>(non-null + true cannot happen: a paid week offers nothing.) The third row
	 * is the reason this method exists at all — without it the panel would have to
	 * infer "nothing eligible" from a null offer, which is exactly the re-derivation
	 * {@link TollOffer} is shaped to spare it.
	 */
	public boolean paidThisWeek() {
		var state = stateService.get();
		return state != null && currentWeekKey().equals(state.getTollWeekKey()) && state.getTollCardUuid() == null;
	}

	/**
	 * This week's offer, or null when there is none (already paid, or the album
	 * holds nothing with a Service Record yet).
	 *
	 * <p>A read that can write: the first call of a new week persists the pick it
	 * just made, because a pick that lived only in memory would be re-drawn from a
	 * grown album after any restart — the exact drift this whole class exists to
	 * prevent. Every later call in the same week finds the stored uuid owned and
	 * writes nothing, so the panel may poll this freely.
	 *
	 * <p>Deliberately NOT synchronized, unlike {@link #purchase()}, for the reason
	 * ChestService gives for exposing {@code pending} through a volatile field
	 * rather than a synchronized getter: this is what the shop panel calls on every
	 * repaint, and putting the EDT behind the monitor a purchase holds while it
	 * rolls a chest, rewrites state and fans out to every listener is a UI stall
	 * bought for nothing. It also removes the only lock-ordering hazard this class
	 * could have had — a state listener firing under GachaStateService's monitor
	 * can reach this method, and if it blocked here while purchase() held this
	 * monitor and waited for that one, the two would deadlock.
	 *
	 * <p>The atomicity given up is nil: the state snapshot is read ONCE into a
	 * local and GachaState is deeply immutable, so there is no compound read to
	 * tear. Two callers racing on the very first call of a week can both re-pick,
	 * and the loser's write is overwritten by an identical one — the seed is
	 * deterministic and the album has not moved between them.
	 */
	public TollOffer currentOffer() {
		var state = stateService.get();
		if (state == null || !cardDatabase.isReady()) { return null; }
		final String weekKey = currentWeekKey();
		// the album is read ONCE out of the snapshot and handed to both the pick and
		// the lookup below, which is what the "read out of the snapshot" note used to
		// say twice: the mutate in between touches only the two Toll fields, so the
		// card list under it is still the one the pick was made from
		var owned = state.getOwnedCards();
		var pick = resolve(weekKey, state.getTollWeekKey(), state.getTollCardUuid(), owned, serviceRecords::pendingFor,
			seedFor(configManager.getRSProfileKey(), weekKey));
		// one read of the picked uuid, which also gives the mutate below the
		// effectively-final capture it needs without a second local for it
		var uuid = pick.getUuid();
		if (uuid == null) { return null; }
		if (pick.isRewrite()) { stateService.mutate(s -> s.withTollWeekKey(weekKey).withTollCardUuid(uuid)); }
		var card = findByUuid(owned, uuid);
		if (card == null) { return null; }
		var def = cardDatabase.card(card.getCardId());
		// uuid rather than card.getUuid(): findByUuid matched on it, so they are the
		// same string and the second call was a re-derivation of a value in hand
		var slot = assignedSlot(state.getLoadout(), uuid);
		return new TollOffer(card, loadoutService.displayName(card), def == null ? null : def.getTierKey(),
			slot, slot == null ? null : String.format(ASSIGNED_REFUSAL, slot.getDisplayName()));
	}

	/**
	 * Pay the Toll: hand over the named card, take a blind pull of its tier.
	 * Returns null and takes NOTHING when there is no offer, when the card is
	 * still assigned, or when the pull could not be dealt.
	 *
	 * <p>Order is deliberate — deal FIRST, consume SECOND. The two writes cannot
	 * be folded into one (the blob write lives inside ChestService), so one of
	 * them has to be exposed to a crash, and this order picks the direction that
	 * favours the player: a client that dies in the gap finds the paid-for pull in
	 * the pending blob and commits it on the next login, while the card was never
	 * taken and the Toll is still live. The reverse order would take the card and
	 * hand back nothing. Consuming the card and marking the week paid ARE one
	 * mutate, so no crash can leave the card gone with the Toll still armed.
	 *
	 * <p>Synchronized because it reads the offer and then acts on it; two clicks
	 * landing together must not both pay. This is the ONLY method that takes this
	 * monitor — see the note on {@link #currentOffer()} — so nothing else can be
	 * blocked behind a purchase, and the locks it then takes (ChestService's, then
	 * GachaStateService's) are only ever acquired in that order: neither of those
	 * services knows the Toll exists, so no path runs the sequence backwards.
	 */
	public synchronized ChestService.ChestOpenResult purchase() {
		var offer = currentOffer();
		if (offer == null || offer.getRefusal() != null) { return null; }
		// one read of the hook field, so a setDealer landing mid-purchase cannot
		// leave this method half-wired to two different dealers
		var pull = dealer;
		if (pull == null) { log.warn("Toll purchase attempted with no pull dealer wired; nothing taken"); return null; }
		final String uuid = offer.getCard().getUuid();
		var result = pull.dealTollPull(offer.getTierKey(), uuid);
		if (result == null) { return null; }
		final String weekKey = currentWeekKey();
		stateService.mutate(s -> {
			var owned = new ArrayList<>(s.getOwnedCards());
			owned.removeIf(c -> uuid.equals(c.getUuid()));
			// the null uuid under the CURRENT week key is what marks the Toll paid;
			// the week key is rewritten alongside it so a purchase that somehow
			// straddles midnight on Sunday cannot mark the wrong week
			return s.withOwnedCards(owned).withTollWeekKey(weekKey).withTollCardUuid(null);
		});
		// a card surrendered and a chest earned is precisely the kind of event a
		// player would resent losing to a client that dies before the 1s debounce
		stateService.checkpoint();
		return result;
	}

	// --- pure rules ---

	/**
	 * Which uuid the Toll should name, and whether the caller must persist it.
	 *
	 * <p>The order of the two same-week checks is the whole anti-re-arm rule: a
	 * null uuid means PAID and returns before the ownership test, so consuming the
	 * card cannot be mistaken for "the named card is gone, pick another" and hand
	 * out a second free Toll in the same week.
	 *
	 * <p>An empty eligible pool writes NOTHING and offers nothing. Recording the
	 * week key with a null uuid would be indistinguishable from PAID and would
	 * suppress the Toll for the rest of the week — including for a player whose
	 * first card earns its first kill on the Tuesday. Leaving the stale fields
	 * untouched costs one retry per call and is always self-correcting.
	 */
	static Pick resolve(String weekKey, String storedWeekKey, String storedUuid,
		List<OwnedCard> owned, ToIntFunction<String> pendingFor, long seed) {
		if (weekKey.equals(storedWeekKey)) {
			if (storedUuid == null) { return new Pick(null, false); }
			if (findByUuid(owned, storedUuid) != null) { return new Pick(storedUuid, false); }
		}
		var pool = eligible(owned, pendingFor);
		if (pool.isEmpty()) { return new Pick(null, false); }
		return new Pick(pool.get(new Random(seed).nextInt(pool.size())).getUuid(), true);
	}

	/**
	 * Every card the Toll may name, in a stable order.
	 *
	 * <p>Sorted by uuid for the same reason the weekly shop sorts by cardId: the
	 * album's own list order follows acquisition and a seeded index into an
	 * unsorted list would be reproducible only by accident.
	 *
	 * <p>Assignment to a loadout slot is deliberately NOT part of this test. An
	 * assigned card is fully eligible — the player unassigns it first — and
	 * filtering assigned cards out here would quietly shrink the pool to whatever
	 * the player happens not to be wearing.
	 */
	static List<OwnedCard> eligible(List<OwnedCard> owned, ToIntFunction<String> pendingFor) {
		if (owned == null) { return new ArrayList<>(); }
		// the filter-then-sort the loop did by hand. sorted() on an ordered stream is
		// stable, exactly as List.sort was, so equal uuids keep album order — and the
		// sort still happens AFTER the filter, which is what keeps the seeded index
		// pointing at the same card the loop form would have handed back
		return owned.stream().filter(c -> isEligible(c, pendingFor.applyAsInt(c.getUuid())))
			.sorted(Comparator.comparing(OwnedCard::getUuid)).collect(Collectors.toList());
	}

	/**
	 * A card with a Service Record on it, and not a hologram. Holograms represent
	 * a whole tier and are the rarest pull in the game; the house does not ask for
	 * one.
	 *
	 * <p>{@code pendingKills} is {@link ServiceRecordService#pendingFor} — the
	 * kills banked since the last flush. Without it a card that earned its very
	 * first kills this session would still read as junk, because the record does
	 * not reach {@code killsServed} until a contract completes or the client shuts
	 * down cleanly.
	 *
	 * <p>That tally is transient, and the consequence is deliberate: a hard crash
	 * loses it, so a pick made on pending kills alone can survive into a week where
	 * the named card reads {@code killsServed == 0}. The Toll does NOT re-pick on
	 * that — the only re-pick triggers are the week turning and the card being
	 * gone. A pick that re-rolled because a number moved underneath it would be
	 * the very instability this class is built to prevent, and the player is owed
	 * the card they were shown.
	 */
	static boolean isEligible(OwnedCard card, int pendingKills) { return !card.isHologram() && (card.getKillsServed() + pendingKills) > 0; }

	/**
	 * Personal and week-stable, mixed the same way {@link WeeklyShopService} mixes
	 * its own seed — same splitmix64, one shared implementation — but salted so
	 * the two features cannot draw in lockstep.
	 */
	static long seedFor(String profileKey, String weekKey) {
		return WeeklyShopService.splitmix64((profileKey == null ? 0 : profileKey.hashCode()) * 31L + weekKey.hashCode() + SEED_SALT);
	}

	/**
	 * The loadout slot holding this uuid, or null. Walks the enum rather than the
	 * map so the answer is deterministic; only holograms can occupy two slots at
	 * once and they are never named by the Toll.
	 */
	static GearSlot assignedSlot(Map<String, String> loadout, String uuid) {
		if (loadout == null) { return null; }
		for (GearSlot slot : GearSlot.values()) { if (uuid.equals(loadout.get(slot.name()))) { return slot; } }
		return null;
	}

	/**
	 * The named card out of an album that may be null. Null-tolerant on both the
	 * list and its contents, unlike {@code LoadoutService}'s same-named private
	 * helper, which dereferences the card first — the two cannot be merged without
	 * changing one of the two null contracts, so they stay apart deliberately.
	 */
	private static OwnedCard findByUuid(List<OwnedCard> owned, String uuid) {
		if (owned == null) { return null; }
		for (OwnedCard card : owned) { if (uuid.equals(card.getUuid())) { return card; } }
		return null;
	}
}

package com.gachaman.service;

import com.gachaman.*;
import com.gachaman.model.*;
import java.util.*;
import java.util.function.*;
import javax.inject.*;
import lombok.*;
import lombok.extern.slf4j.*;

/**
 * The single funnel every GC award flows through. Modifiers (set perks, party
 * bonus, prestige, taint) register once and compose multiplicatively.
 */
@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class CreditSink {
	public enum Source {
		KILL, TASK_COMPLETION, SIDE_BET, DUPLICATE, DEED_SATURATED, RECORD,
		DISCOVERY, GRADUATION, FIRST, OTHER
	}

	@Value
	public static class GcContext {
		Source source;
		String monsterName;   // null when not kill-scoped
		List<String> monsterTags; // null when unknown
	}

	public interface Modifier {
		/** Multiplicative factor for this award; return 1.0 when not applicable. */
		double factor(GcContext context);
	}

	public interface Listener {
		void onGcAwarded(long amount, GcContext context, long newBalance);
	}

	private final GachaStateService stateService;
	private final List<Modifier> modifiers = new ArrayList<>();
	private final List<Listener> listeners = new ArrayList<>();

	public synchronized void registerModifier(Modifier modifier) {
		if (!modifiers.contains(modifier))
			modifiers.add(modifier);
	}

	public synchronized void unregisterModifier(Modifier modifier) {
		modifiers.remove(modifier);
	}

	public synchronized void addListener(Listener listener) {
		listeners.add(listener);
	}

	public synchronized void removeListener(Listener listener) {
		listeners.remove(listener);
	}

	@Value
	public static class AwardResult {
		long amount;
		/** Post-mutate snapshot; null when state was not loaded. */
		GachaState state;
	}

	/**
	 * Atomic variant: applies extraMutation AND the GC award in ONE state
	 * mutation, so an unload/profile-switch can never separate a one-shot
	 * marker (e.g. a Firsts stamp) from its bounty. The award lands only when
	 * extraMutation actually changed the state.
	 */
	public synchronized AwardResult awardWith(long baseAmount, GcContext context,
		UnaryOperator<GachaState> extraMutation) {
		if (stateService.get() == null)
			return new AwardResult(0, null);
		double factor = 1.0;
		for (Modifier modifier : modifiers) {
			try {
				factor *= modifier.factor(context);
			}
			catch (Exception e) {
				log.warn("GC modifier failed", e);
			}
		}
		if (stateService.get().getTaint() > 0)
			factor *= Tuning.TAINT_INCOME_MULT;
		long amount = baseAmount <= 0 ? 0 : Math.max(0, Math.round(baseAmount * factor));
		final boolean[] applied = {false};
		var next = stateService.mutate(s -> {
			GachaState mutated = extraMutation.apply(s);
			if (mutated == null || mutated == s) {
				return s; // marker did not land — no award either
			}
			applied[0] = true;
			if (amount > 0) {
				mutated = mutated.withGc(mutated.getGc() + amount)
					.withLifetimeGcEarned(mutated.getLifetimeGcEarned() + amount);
			}
			return mutated;
		});
		if (next == null || !applied[0])
			return new AwardResult(0, next);
		if (amount > 0) {
			Listeners.fire(listeners, l -> l.onGcAwarded(amount, context, next.getGc()),
				"GC listener failed");
		}
		return new AwardResult(amount, next);
	}

	/** Award GC (may be reduced by taint / boosted by perks). Returns the net amount. */
	public synchronized long award(long baseAmount, GcContext context) {
		if (baseAmount <= 0 || stateService.get() == null)
			return 0;
		double factor = 1.0;
		for (Modifier modifier : modifiers) {
			try {
				factor *= modifier.factor(context);
			}
			catch (Exception e) {
				log.warn("GC modifier failed", e);
			}
		}
		if (stateService.get().getTaint() > 0)
			factor *= Tuning.TAINT_INCOME_MULT;
		long amount = Math.max(0, Math.round(baseAmount * factor));
		if (amount == 0)
			return 0;
		var newState = stateService.mutate(s -> s
			.withGc(s.getGc() + amount)
			.withLifetimeGcEarned(s.getLifetimeGcEarned() + amount));
		long balance = newState == null ? 0 : newState.getGc();
		Listeners.fire(listeners, l -> l.onGcAwarded(amount, context, balance), "GC listener failed");
		return amount;
	}

	/**
	 * Restore GC that was deducted in error (style pardons). Raw restitution:
	 * bypasses modifiers, taint halving and lifetime earnings — it is not
	 * income, it is undoing a wrongful deduction.
	 */
	public synchronized long refund(long amount) {
		if (amount <= 0 || stateService.get() == null)
			return 0;
		stateService.mutate(s -> s.withGc(s.getGc() + amount));
		return amount;
	}

	/** Deduct GC (violation penalties, purchases). Returns amount actually deducted. */
	public synchronized long deduct(long amount) {
		if (amount <= 0 || stateService.get() == null)
			return 0;
		long current = stateService.get().getGc();
		long actual = Math.min(current, amount);
		stateService.mutate(s -> s.withGc(s.getGc() - actual));
		return actual;
	}

	/** Try to spend exactly amount; false (and no change) when unaffordable. */
	public synchronized boolean spend(long amount) {
		if (stateService.get() == null || stateService.get().getGc() < amount)
			return false;
		stateService.mutate(s -> s.withGc(s.getGc() - amount));
		return true;
	}
}

package com.gachaman.service;

import com.gachaman.*;
import com.gachaman.model.*;
import java.util.*;
import javax.inject.*;
import lombok.*;
import net.runelite.api.*;
import net.runelite.client.util.*;

/**
 * Style-rule enforcement. On a re-roll the player is only WARNED; a violation
 * begins when an attack is actually made with a forbidden style. Each
 * forbidden attack costs GC; kills finished while violating pay zero and add
 * taint (halving all income until worked off).
 */
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class ComplianceService implements StyleTracker.AttackListener {
	private static final int VIOLATING_DISPLAY_TICKS = 8;

	public interface Listener {
		void onForbiddenAttack(AttackStyle used, AttackStyle allowed, long penaltyGc);

		default void onTaintAdded(int newTaint) {
		}

		default void onTaintCleared(int cleared, int remaining) {
		}

		/**
		 * A forbidden-attack verdict was retracted (the delayed Magic XP
		 * proved the attack was actually a compliant cast); its penalty has
		 * been refunded.
		 */
		default void onForbiddenPardoned(int tick, long refundedGc) {
		}

		/**
		 * A pardon reversed the taint its own conviction had caused. NOT a
		 * cleanse: nothing was worked off, so this must never be confused with
		 * {@link #onTaintCleared} (which pays the first-cleanse bounty).
		 */
		default void onTaintRolledBack(int lifted, int remaining) {
		}
	}

	/** One convicted forbidden attack: when, and what it cost (for pardon refunds). */
	@RequiredArgsConstructor
	private static final class ForbiddenAttack {
		final int tick;
		final long deductedGc;
		/**
		 * Taint this conviction is still answerable for. A kill tainted by this
		 * attack adds a point here, so a later pardon can reverse exactly its
		 * own taint and never someone else's.
		 */
		int taintPoints;
	}

	private final GachaStateService stateService;
	private final CreditSink creditSink;
	private final Client client;
	private final QuestExemptionService questExemptionService;

	@Getter
	private int lastForbiddenAttackTick = -1;
	@Getter
	private int lastCompliantAttackTick = -1;
	/**
	 * Recent forbidden attacks (kills are judged a few ticks after death, and
	 * pardons arrive a few ticks after the attack).
	 */
	private final ArrayDeque<ForbiddenAttack> recentForbiddenAttacks = new ArrayDeque<>();
	/** Tick of the most recent style re-roll (drives the "switch gear" warning chip). */
	@Getter
	private int styleChangedTick = -1;

	/**
	 * The six fan-outs below used to iterate this list directly, without the
	 * defensive copy every other service in the package takes; routing them
	 * through {@link Listeners#fire} gives them one.
	 *
	 * <p>That widens what is legal rather than changing what happens. Registering
	 * or dropping a listener from inside a compliance callback used to throw
	 * ConcurrentModificationException straight out of onAttack; now it does not.
	 * Nothing did it: the only callers of addListener/removeListener in the whole
	 * of src/main are GachamanPlugin's startUp and shutDown, which is a fact
	 * about call sites and so cannot be invalidated by a change inside any
	 * listener.
	 */
	private final List<Listener> listeners = new ArrayList<>();
	private int currentTick;

	public void addListener(Listener listener) {
		if (!listeners.contains(listener))
			listeners.add(listener);
	}

	public void removeListener(Listener listener) {
		listeners.remove(listener);
	}

	public void noteStyleChanged(int tick) {
		styleChangedTick = tick;
	}

	/** True while the "in violation" chip should show. */
	public boolean isViolating(int tick) {
		return lastForbiddenAttackTick >= 0 && tick - lastForbiddenAttackTick <= VIOLATING_DISPLAY_TICKS
			&& lastCompliantAttackTick < lastForbiddenAttackTick;
	}

	/**
	 * Was a forbidden attack made inside [fromTick, toTick]? Kill processing
	 * is deferred past death for the loot oracle, so the judgement must be
	 * bounded by the DEATH tick — an attack on the next target during the
	 * settle window must never taint the finished kill.
	 */
	public boolean forbiddenAttackBetween(int fromTick, int toTick) {
		return convictingAttackTick(fromTick, toTick) >= 0;
	}

	/**
	 * Which forbidden attack convicts a kill spanning [fromTick, toTick], or -1
	 * for none. Same window as {@link #forbiddenAttackBetween}, but it keeps the
	 * convicting attack's identity so the taint it causes can be attributed to
	 * it and reversed if that verdict is later pardoned. Returns the OLDEST
	 * match: with two convictions in one window the taint stays pinned to the
	 * first, so pardoning only the second correctly lifts nothing.
	 */
	public int convictingAttackTick(int fromTick, int toTick) {
		for (ForbiddenAttack attack : recentForbiddenAttacks) {
			if (attack.tick >= fromTick && attack.tick <= toTick)
				return attack.tick;
		}
		return -1;
	}

	@Override
	public void onAttack(AttackStyle style, int tick) {
		currentTick = tick;
		GachaState state = stateService.get();
		if (state == null || state.getAllowedStyle() == null
			|| (client != null && TutorialGate.onTutorial(client))) {
			return;
		}
		AttackStyle allowed = AttackStyle.valueOf(state.getAllowedStyle());
		if (style == allowed) {
			lastCompliantAttackTick = tick;
			return;
		}
		// quest fights are style-exempt: some quest bosses require a specific
		// style and a lock would soft-lock the quest
		if (client != null) {
			Actor target = client.getLocalPlayer() == null
				? null : client.getLocalPlayer().getInteracting();
			if (target instanceof NPC && target.getName() != null
				&& questExemptionService.isQuestTarget(
					Text.removeTags(target.getName()))) {
				lastCompliantAttackTick = tick;
				return;
			}
		}
		lastForbiddenAttackTick = tick;
		long penalty = penaltyFor(state.getActiveTask());
		long deducted = creditSink.deduct(penalty);
		recentForbiddenAttacks.addLast(new ForbiddenAttack(tick, deducted));
		while (recentForbiddenAttacks.size() > 32) {
			recentForbiddenAttacks.removeFirst();
		}
		Listeners.fire(listeners, l -> l.onForbiddenAttack(style, allowed, deducted),
			"compliance listener failed");
	}

	/**
	 * The StyleTracker retracted a stance verdict: the delayed Magic XP proved
	 * the "forbidden melee/ranged attack" at judgedTick was actually a spell
	 * cast. Undo everything the conviction did — remove it from the taint
	 * window, refund the penalty, reverse any taint it already caused, and count
	 * the attack as compliant. The kill that taint came from stays unpaid: its
	 * combo, side bets and KC were already scored and cannot be replayed.
	 */
	@Override
	public void onAttackPardoned(int judgedTick) {
		ForbiddenAttack pardoned = null;
		for (ForbiddenAttack attack : recentForbiddenAttacks) {
			if (attack.tick == judgedTick) {
				pardoned = attack;
				break;
			}
		}
		if (pardoned == null) {
			return; // that verdict was compliant anyway — nothing to undo
		}
		recentForbiddenAttacks.remove(pardoned);
		long refunded = creditSink.refund(pardoned.deductedGc);
		// the verdict was wrong, so the taint it caused was wrong too — but only
		// reverse taint that is still STANDING. A work-off, a cleanse or a
		// profile switch may already have burned it, and lifting more than that
		// would hand back taint the player genuinely earned elsewhere.
		GachaState beforeRollback = stateService.get();
		int standingTaint = beforeRollback == null ? 0 : beforeRollback.getTaint();
		int lifted = Math.min(pardoned.taintPoints, standingTaint);
		GachaState afterRollback = lifted > 0
			? stateService.mutate(s -> s.withTaint(s.getTaint() - lifted))
			: null;
		int latestRemaining = -1;
		for (ForbiddenAttack attack : recentForbiddenAttacks) {
			latestRemaining = Math.max(latestRemaining, attack.tick);
		}
		lastForbiddenAttackTick = latestRemaining;
		lastCompliantAttackTick = Math.max(lastCompliantAttackTick, judgedTick);
		Listeners.fire(listeners, l -> l.onForbiddenPardoned(judgedTick, refunded),
			"compliance listener failed");
		// value-based, not null-based: @With returns the same instance when the
		// value is unchanged and mutate hands that straight back, so a non-null
		// state is no proof that any taint actually came off
		if (afterRollback != null && afterRollback.getTaint() < standingTaint) {
			// a second fan-out takes a second copy, so a listener registered by the
			// pardon notice above is seen here exactly as it was when hand-written
			Listeners.fire(listeners, l -> l.onTaintRolledBack(lifted, afterRollback.getTaint()),
				"compliance listener failed");
		}
	}

	static long penaltyFor(ActiveTask task) {
		if (task == null)
			return Tuning.VIOLATION_ATTACK_PENALTY_NO_TASK;
		return Math.max(Tuning.VIOLATION_ATTACK_PENALTY_FLOOR,
			(long) task.getPerKillGc() * Tuning.VIOLATION_ATTACK_PENALTY_MULT);
	}

	/**
	 * Called by the task engine when a kill was tainted, naming the conviction
	 * that tainted it (see {@link #convictingAttackTick}) so a pardon of that
	 * attack can reverse this point. An unknown tick still taints — it is just
	 * unattributable, and therefore permanent until worked off.
	 */
	public void addTaint(int convictionTick) {
		var state = stateService.mutate(s -> s.withTaint(s.getTaint() + 1));
		if (state != null) {
			for (ForbiddenAttack attack : recentForbiddenAttacks) {
				if (attack.tick == convictionTick) {
					attack.taintPoints++;
					break;
				}
			}
			Listeners.fire(listeners, l -> l.onTaintAdded(state.getTaint()),
				"compliance listener failed");
		}
	}

	/** Called on each compliant credited kill; works one taint off. */
	public void workOffTaint() {
		GachaState state = stateService.get();
		if (state == null || state.getTaint() <= 0)
			return;
		var next = stateService.mutate(s -> s.withTaint(Math.max(0, s.getTaint() - 1)));
		if (next != null) {
			// taint points are fungible against the global counter, so retire the
			// OLDEST attributed point first — that keeps the ledger's total from
			// running AHEAD of the counter, which is what stops a pardon from
			// lifting taint that was already worked off. It cannot keep the two
			// EQUAL: this deque is bounded, so an evicted attack takes its
			// unretired points with it while the counter keeps them. The ledger
			// is therefore only ever <= the counter, and the pardon path still
			// needs its own Math.min against the standing taint.
			for (ForbiddenAttack attack : recentForbiddenAttacks) {
				if (attack.taintPoints > 0) {
					attack.taintPoints--;
					break;
				}
			}
			Listeners.fire(listeners, l -> l.onTaintCleared(1, next.getTaint()),
				"compliance listener failed");
		}
	}

	/** Redemption task completion clears everything. */
	public void clearAllTaint() {
		GachaState state = stateService.get();
		if (state == null || state.getTaint() <= 0)
			return;
		int cleared = state.getTaint();
		stateService.mutate(s -> s.withTaint(0));
		// the counter is empty, so no conviction is answerable for anything any
		// more — a later pardon must not "refund" taint redemption already wiped
		for (ForbiddenAttack attack : recentForbiddenAttacks) {
			attack.taintPoints = 0;
		}
		Listeners.fire(listeners, l -> l.onTaintCleared(cleared, 0),
			"compliance listener failed");
	}

	/**
	 * Logout/profile-switch hygiene: the conviction ledger is in-memory while
	 * the taint it accounts for is persisted per-profile. A conviction that
	 * outlived its own save would let a pardon reverse the NEXT character's
	 * taint, so the convictions die with the profile.
	 */
	public void resetTransient() {
		recentForbiddenAttacks.clear();
		lastForbiddenAttackTick = -1;
		lastCompliantAttackTick = -1;
		// the "switch your gear" chip is about a re-roll the PREVIOUS profile
		// saw; left set, it warns the next character about nothing
		styleChangedTick = -1;
	}
}

package com.gachaman.service;

import javax.annotation.*;
import javax.inject.*;
import lombok.*;
import net.runelite.api.*;

/**
 * The local player's {@link AccountKey}, cached and self-invalidating.
 *
 * <p>The hash itself is the cache key, so a profile switch, a logout or a
 * hop onto a different account is picked up by the next call with no event
 * subscription at all. Subscribing to AccountHashChanged instead would put
 * this service's correctness at the mercy of eventbus ORDERING — a party
 * broadcast handled before our listener ran would send the previous
 * account's key — and there is no ordering guarantee to lean on. Comparing
 * the value we were given is the version that cannot be raced.
 *
 * <p>Deliberately NOT persisted anywhere. The key is derived, not stored: a
 * cached copy in the save blob could outlive the account it names and would
 * then have to be reconciled with the live one, which is a whole class of bug
 * bought for the price of one SHA-256 per login.
 */
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class AccountKeyService {
	private final Client client;

	/**
	 * Both fields are written together and only from the accessor below.
	 * Volatile because the party layer reads this from the client thread while
	 * the sidebar reads it from the EDT.
	 */
	private volatile long cachedHash = AccountKey.NO_ACCOUNT;
	@Nullable
	private volatile String cachedKey;

	/**
	 * The local account's key, or null when nobody is logged in.
	 *
	 * <p>Null is a real and frequent answer — getAccountHash() returns -1 on
	 * the login screen, and the party layer can broadcast before the first
	 * login completes. Callers must send null through as "unknown" rather than
	 * substituting a placeholder, or every logged-out client in the party
	 * becomes the same person.
	 */
	@Nullable
	public String key() {
		long hash;
		try {
			hash = client.getAccountHash();
		}
		catch (Exception e) {
			// the API can be called before the client is fully constructed
			return null;
		}
		if (hash != cachedHash) {
			// key FIRST, then the hash that publishes it: a thread that sees the
			// new hash is guaranteed by the volatile write to see the matching
			// key, so a concurrent reader can never pair a fresh hash with the
			// previous account's key. Recomputing twice on a race is harmless —
			// AccountKey.of is a pure function of the hash.
			cachedKey = AccountKey.of(hash);
			cachedHash = hash;
		}
		return cachedKey;
	}
}

package com.gachaman.service;

import com.gachaman.data.*;
import com.gachaman.model.*;
import java.util.*;
import java.util.stream.*;
import javax.inject.*;
import lombok.*;
import lombok.extern.slf4j.*;

/**
 * Detects set completion on collection changes and applies permanent perks as
 * a CreditSink modifier. Hologram cards count as every member card of their
 * tier for completion purposes (wildcard rule for tier sets).
 */
@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class SetPerkService implements GachaStateService.Listener {
	private final GachaStateService stateService;
	private final CreditSink creditSink;
	private final CardDatabase cardDatabase;
	private final SetTable setTable;
	private final CeremonyBus ceremonyBus;

	private final CreditSink.Modifier perkModifier = this::perkFactor;

	public void start() {
		stateService.addListener(this);
		creditSink.registerModifier(perkModifier);
	}

	public void stop() {
		stateService.removeListener(this);
		creditSink.unregisterModifier(perkModifier);
	}

	@Override
	public void onStateChanged(GachaState state) {
		if (!cardDatabase.isReady())
			return;
		Set<Integer> ownedIds = state.getOwnedCards().stream()
			.filter(c -> !c.isHologram())
			.map(OwnedCard::getCardId)
			.collect(Collectors.toSet());
		Set<String> ownedHoloTiers = state.getOwnedCards().stream()
			.filter(OwnedCard::isHologram)
			.map(OwnedCard::getTierKey)
			.collect(Collectors.toSet());

		// Everything found in ONE pass, banked in ONE mutate.
		//
		// Mutating inside the loop re-enters this method — mutate() notifies its
		// listeners synchronously and this class is one of them — and the nested pass
		// walks the WHOLE table again against the new state, banking any later set it
		// finds. The outer loop then reaches that same set still holding its stale
		// `state` snapshot, which does not know the set is done, and completes it a
		// second time: a second LARGE modal, and a second save (withCompletedSets
		// returns a new object even when the key is already in it, so mutate's
		// identity check does not catch it). It takes two sets finishing on one card,
		// which is precisely what a mega-set is built to do.
		Set<String> newKeys = new HashSet<>();
		List<CeremonyBus.Fanfare> fanfares = new ArrayList<>();
		for (SetTable.CardSet set : setTable.getSets()) {
			if (state.getCompletedSets().contains(set.getSetKey()))
				continue;
			List<CardDefinition> members = cardDatabase.setMembers(set.getSetKey());
			if (members.isEmpty() || members.size() < set.getCardNames().size()) {
				continue; // some names failed to resolve; never complete a partial mapping
			}
			boolean complete = members.stream().allMatch(m ->
				ownedIds.contains(m.getCardId())
					|| (m.getTierKey() != null && ownedHoloTiers.contains(m.getTierKey())));
			if (complete) {
				newKeys.add(set.getSetKey());
				fanfares.add(new CeremonyBus.Fanfare(
					CeremonyBus.Fanfare.Size.LARGE, "Set complete: " + set.getName(),
					perkDescription(set.getPerk()), members.get(0).getCardId()));
				log.debug("Set completed: {}", set.getSetKey());
			}
		}
		if (newKeys.isEmpty())
			return;
		// This one still re-enters, and is meant to: the nested pass sees every key
		// already banked and finds nothing, which is the fixed point we want.
		stateService.mutate(s -> {
			Set<String> done = new HashSet<>(s.getCompletedSets());
			done.addAll(newKeys);
			return s.withCompletedSets(done);
		});
		for (CeremonyBus.Fanfare fanfare : fanfares) {
			ceremonyBus.submit(CeremonyBus.Type.FANFARE, fanfare);
		}
	}

	double perkFactor(CreditSink.GcContext context) {
		GachaState state = stateService.get();
		if (state == null || state.getCompletedSets().isEmpty())
			return 1.0;
		double factor = 1.0;
		for (SetTable.CardSet set : setTable.getSets()) {
			if (!state.getCompletedSets().contains(set.getSetKey()))
				continue;
			SetTable.Perk perk = set.getPerk();
			if (perk == null || !typeMatches(perk.getType(), context.getSource()))
				continue;
			if (scopeMatches(perk, context))
				factor *= 1.0 + perk.getMagnitudePercent() / 100.0;
		}
		return factor;
	}

	private static boolean typeMatches(SetTable.PerkType type, CreditSink.Source source) {
		switch (type) {
			case KILL_GC_PERCENT:
				return source == CreditSink.Source.KILL;
			case COMPLETION_GC_PERCENT:
				return source == CreditSink.Source.TASK_COMPLETION;
			case SIDEBET_GC_PERCENT:
				return source == CreditSink.Source.SIDE_BET;
			default:
				return false;
		}
	}

	private static boolean scopeMatches(SetTable.Perk perk, CreditSink.GcContext context) {
		switch (perk.getScope()) {
			case GLOBAL:
				return true;
			case MONSTER_NAME_SET:
				return context.getMonsterName() != null && perk.getScopeValues() != null
					&& perk.getScopeValues().stream()
						.anyMatch(n -> n.equalsIgnoreCase(context.getMonsterName()));
			case CATEGORY_TAG:
				return context.getMonsterTags() != null && perk.getScopeValues() != null
					&& perk.getScopeValues().stream().anyMatch(context.getMonsterTags()::contains);
			default:
				return false;
		}
	}

	public static String perkDescription(SetTable.Perk perk) {
		if (perk == null)
			return "";
		String what;
		switch (perk.getType()) {
			case KILL_GC_PERCENT:
				what = "kill GC";
				break;
			case COMPLETION_GC_PERCENT:
				what = "contract completion GC";
				break;
			default:
				what = "side bet GC";
		}
		String scope = perk.getScope() == SetTable.PerkScope.GLOBAL ? "" : " (scoped)";
		return "+" + perk.getMagnitudePercent() + "% " + what + scope + ", permanently";
	}
}

package com.gachaman.service;

import java.security.*;
import java.util.*;
import javax.inject.*;

/** Central RNG. Tests construct with a fixed seed; production uses SecureRandom seeding. */
@Singleton
public class GachaRng {
	private final Random random;

	public GachaRng() {
		this.random = new Random(new SecureRandom().nextLong());
	}

	public GachaRng(long seed) {
		this.random = new Random(seed);
	}

	public int nextInt(int bound) {
		return random.nextInt(bound);
	}

	public int between(int minInclusive, int maxInclusive) {
		return minInclusive + random.nextInt(maxInclusive - minInclusive + 1);
	}

	public double nextDouble() {
		return random.nextDouble();
	}

	public boolean chance(double probability) {
		return random.nextDouble() < probability;
	}

	public <T> T pick(List<T> list) {
		return list.get(random.nextInt(list.size()));
	}
}

package com.gachaman.service;

import com.gachaman.*;
import com.gachaman.data.*;
import com.gachaman.model.*;
import java.util.*;
import java.util.stream.*;
import net.runelite.api.*;

/**
 * Pure task-offer generation: 4 difficulty offers scaled to combat level
 * (never impossible) and an optional Redemption 5th offer while tainted.
 * Fully deterministic for a given RNG seed and pool — party rolls rely on
 * this to produce identical offers on every participant's client.
 */
public final class TaskGenerator {
	private TaskGenerator() {
	}

	public static List<TaskOffer> generateOffers(List<MonsterTable.Monster> pool, int playerCb,
		boolean membersWorld, boolean tainted, GachaRng rng) {
		return generateOffers(pool, playerCb, 99, membersWorld, tainted, rng);
	}

	/** Quest gating disabled — see the {@code completedQuests} overload. */
	public static List<TaskOffer> generateOffers(List<MonsterTable.Monster> pool, int playerCb,
		int playerSlayerLevel, boolean membersWorld, boolean tainted, GachaRng rng) {
		return generateOffers(pool, playerCb, playerSlayerLevel, membersWorld, null, tainted, 0, false, rng);
	}

	/** Quest-gated roll with no max-hit estimate: BIG_HIT falls to its floor. */
	public static List<TaskOffer> generateOffers(List<MonsterTable.Monster> pool, int playerCb,
		int playerSlayerLevel, boolean membersWorld,
		Set<String> completedQuests, boolean tainted, GachaRng rng) {
		return generateOffers(pool, playerCb, playerSlayerLevel, membersWorld,
			completedQuests, tainted, 0, false, rng);
	}

	/**
	 * @param completedQuests {@link Quest} names the player has
	 *                        FINISHED. Null disables quest gating entirely — the
	 *                        pre-quest-gate behaviour, which a mixed-version party
	 *                        falls back to so every client still deals one board.
	 *                        An EMPTY set is not the same thing: it means a player
	 *                        who has finished nothing, and gates accordingly.
	 * @param maxHit          the player's calculated max hit in their locked
	 *                        style, sizing the BIG_HIT side bet. 0 = unknown.
	 * @param anyoneLockedToMelee true when the local player — or, in a party, ANY
	 *                        agreed member — is locked to melee, which removes
	 *                        every melee-unreachable monster from the pool.
	 */
	public static List<TaskOffer> generateOffers(List<MonsterTable.Monster> pool, int playerCb,
		int playerSlayerLevel, boolean membersWorld,
		Set<String> completedQuests, boolean tainted,
		int maxHit, boolean anyoneLockedToMelee, GachaRng rng) {
		// slayer-task-only monsters are unfulfillable contracts (a Gachaman
		// task is not a slayer task); slayer-level-gated ones need the level;
		// quest-locked ones cannot be reached or damaged at all
		pool = pool.stream()
			.filter(m -> !m.isSlayerTaskOnly())
			.filter(m -> m.getSlayerLevel() <= playerSlayerLevel)
			.filter(m -> questsSatisfied(m, completedQuests))
			// A monster melee cannot reach is an UNWINNABLE contract for a player
			// the wheel has locked to melee, so it is gated exactly like the slayer
			// level and the quest locks above rather than merely discouraged.
			//
			// In a party this is ANY agreed member, not the local player: a shared
			// contract pools everyone's kills, so one melee member who cannot touch
			// the target is a member who cannot help and cannot build a combo. It
			// costs the party some variety, which is the trade the owner chose.
			.filter(m -> !anyoneLockedToMelee || !m.isMeleeUnreachable())
			.collect(Collectors.toList());
		List<TaskOffer> offers = new ArrayList<>(5);
		// no monster may appear on more than one offer in the same roll
		Set<String> usedMonsters = new HashSet<>();
		for (TaskDifficulty difficulty : TaskDifficulty.values()) {
			TaskOffer offer = generate(pool, playerCb, membersWorld, difficulty, false, usedMonsters, maxHit, rng);
			usedMonsters.add(offer.getMonsterName());
			offers.add(offer);
		}
		if (tainted) {
			TaskOffer redemption = generate(pool, playerCb, membersWorld, TaskDifficulty.MEDIUM,
				true, usedMonsters, maxHit, rng);
			offers.add(redemption);
		}
		return offers;
	}

	/**
	 * True when every quest this monster is locked behind has been finished.
	 *
	 * Order-independent by construction — a Set membership test, never a list
	 * comparison — because in a party this runs against an INTERSECTION built
	 * from several members' answers, and two clients that walked the roster in
	 * different orders must still agree monster for monster.
	 */
	static boolean questsSatisfied(MonsterTable.Monster monster,
		Set<String> completedQuests) {
		List<String> required = monster.getQuests();
		if (required == null || required.isEmpty())
			return true;
		// null = gating off; empty = a player who has finished nothing
		return completedQuests == null || completedQuests.containsAll(required);
	}

	static TaskOffer generate(List<MonsterTable.Monster> pool, int playerCb, boolean membersWorld,
		TaskDifficulty difficulty, boolean redemption,
		Set<String> excludeMonsters, int maxHit, GachaRng rng) {
		List<MonsterTable.Monster> eligible = eligibleMonsters(pool, playerCb, membersWorld, difficulty);
		List<MonsterTable.Monster> distinct = eligible.stream()
			.filter(m -> !excludeMonsters.contains(m.getName()))
			.collect(Collectors.toList());
		// only repeat a monster when the band genuinely has no alternative
		MonsterTable.Monster monster = rng.pick(distinct.isEmpty() ? eligible : distinct);

		int kills = rng.between(difficulty.getMinKills(), difficulty.getMaxKills());
		if (redemption)
			kills = (int) Math.ceil(kills * Tuning.REDEMPTION_KILL_MULT);
		int perKill = redemption ? 0 : Tuning.PER_KILL_GC.get(difficulty);
		int completion = Tuning.COMPLETION_GC.get(difficulty);

		List<SideBet> sideBets = redemption ? List.of() : rollSideBets(maxHit, completion, rng);
		return new TaskOffer(difficulty, monster.getName(), monster.getCombatLevel(),
			kills, perKill, completion, sideBets, redemption, false);
	}

	/**
	 * Monsters at or below the difficulty's CB cap. Always non-empty: when the
	 * cap excludes everything, the lowest-level monsters are used instead.
	 */
	static List<MonsterTable.Monster> eligibleMonsters(List<MonsterTable.Monster> pool, int playerCb,
		boolean membersWorld, TaskDifficulty difficulty) {
		int cap = (int) Math.max(2, Math.floor(playerCb * difficulty.getCbCapFraction()));
		List<MonsterTable.Monster> available = pool.stream()
			.filter(m -> membersWorld || !m.isMembers())
			.collect(Collectors.toList());
		List<MonsterTable.Monster> eligible = available.stream()
			.filter(m -> m.getCombatLevel() <= cap)
			.collect(Collectors.toList());
		if (!eligible.isEmpty()) {
			// bias toward the top of the band so harder difficulties feel harder
			int floor = (int) Math.floor(cap * (difficulty == TaskDifficulty.EASY ? 0.0 : 0.35));
			List<MonsterTable.Monster> banded = eligible.stream()
				.filter(m -> m.getCombatLevel() >= floor)
				.collect(Collectors.toList());
			return banded.isEmpty() ? eligible : banded;
		}
		// degenerate low-level case: hand back the weakest few monsters
		return available.stream()
			.sorted(Comparator.comparingInt(MonsterTable.Monster::getCombatLevel))
			.limit(8)
			.collect(Collectors.toList());
	}

	/**
	 * "Land a hit of N+", sized to the max hit this player could actually land
	 * in the style they are locked into — see {@link MaxHitService}.
	 *
	 * <p>Combat level was the wrong basis and produced impossible bets: the old
	 * {@code max(5, 5 + cb/8)} floored every player under combat 24 at 5, while
	 * a bronze-armed account around combat 12 maxes about 3. The bet could not
	 * be won at all in the band it was most likely to be dealt in.
	 *
	 * <p>Asks for {@value #BIG_HIT_FRACTION_PCT}% of that ceiling rather than
	 * the ceiling itself: a max hit is the rarest single roll on the damage
	 * curve, so a bet demanding it exactly would be technically possible and
	 * practically dead. The estimate is already conservative (no prayer, no
	 * boosts, no void), so the two margins compound in the player's favour.
	 *
	 * <p>Zero means the ceiling could not be read — logged out, no style rolled
	 * yet, an unreadable equipment container — and yields the floor.
	 */
	static final int BIG_HIT_FRACTION_PCT = 70;

	static int bigHitThreshold(int maxHit) {
		if (maxHit <= 0) {
			return 2; // unknown — a guess, and deliberately a low one
		}
		// never above what the player can physically hit: a floor that can
		// outrun the real ceiling is the same bug in smaller print
		return Math.max(1, Math.min(40, maxHit * BIG_HIT_FRACTION_PCT / 100));
	}

	static List<SideBet> rollSideBets(int maxHit, int completionGc, GachaRng rng) {
		int count = rng.chance(0.5) ? 2 : 1;
		List<SideBet> bets = new ArrayList<>(count);
		for (int i = 0; i < count; i++) {
			SideBet.Kind kind = SideBet.Kind.values()[rng.nextInt(SideBet.Kind.values().length)];
			int threshold = 0;
			int window = 0;
			switch (kind) {
				case BIG_HIT:
					threshold = bigHitThreshold(maxHit);
					break;
				case SPEED_KILLS:
					threshold = 3;
					window = 100;
					break;
				case DAMAGELESS_KILL:
				case CLUTCH_KILL:
					break;
			}
			double frac = Tuning.SIDEBET_MIN_PAYOUT_FRAC
				+ rng.nextDouble() * (Tuning.SIDEBET_MAX_PAYOUT_FRAC - Tuning.SIDEBET_MIN_PAYOUT_FRAC);
			int payout = (int) Math.round(completionGc * frac);
			// side bets are always visible — sealed bets were cut by design review
			bets.add(new SideBet(kind, threshold, window, false, false, payout));
		}
		return bets;
	}

}

package com.gachaman.service;

import java.util.*;
import javax.inject.*;
import lombok.*;
import lombok.extern.slf4j.*;
import net.runelite.api.*;
import net.runelite.api.events.*;
import net.runelite.client.chat.*;
import net.runelite.client.eventbus.*;

/**
 * The hard click-block for forbidden equipment. Menu entries are removed on
 * every MenuEntryAdded (the menu rebuilds each frame — no caching), and
 * MenuOptionClicked.consume() is the backstop that actually guarantees the
 * block if any path re-adds an entry.
 */
@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class EquipBlockService {
	private static final Set<String> EQUIP_OPTIONS = Set.of("Wield", "Wear", "Equip", "Hold");

	private final Client client;
	private final PermissionService permissionService;
	private final ChatMessageManager chatMessageManager;

	private int lastWarnTick = -1;

	@Subscribe
	public void onMenuEntryAdded(MenuEntryAdded event) {
		MenuEntry entry = event.getMenuEntry();
		if (!isEquipOption(entry.getOption()))
			return;
		int itemId = entry.getItemId();
		if (itemId > 0 && permissionService.isForbidden(itemId))
			client.getMenu().removeMenuEntry(entry);
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event) {
		if (!isEquipOption(event.getMenuOption()))
			return;
		int itemId = event.getItemId();
		if (itemId > 0 && permissionService.isForbidden(itemId)) {
			event.consume();
			int tick = client.getTickCount();
			if (tick != lastWarnTick) {
				lastWarnTick = tick;
				chatMessageManager.queue(QueuedMessage.builder()
					.type(ChatMessageType.CONSOLE)
					.runeLiteFormattedMessage(
						"<col=b25be2>Gachaman:</col> That equipment is card-locked. Pull its card and equip it in your loadout first.")
					.build());
			}
		}
	}

	static boolean isEquipOption(String option) {
		return option != null && EQUIP_OPTIONS.contains(option);
	}
}

package com.gachaman.service;

import java.util.*;
import java.util.function.*;
import lombok.extern.slf4j.*;

/**
 * The one listener fan-out loop, shared by every service that has listeners.
 *
 * <p>Sixteen sites used to spell this out by hand — copy the list, loop, try,
 * catch, warn — and every one of them had to get all three of the following
 * right independently. They are the reason this class exists, so none of them
 * may be "simplified" away:
 *
 * <ul>
 * <li><b>The defensive copy</b> is what lets a listener add or drop another one
 * from inside its own callback without a ConcurrentModificationException. It is
 * cheap insurance: these lists hold a handful of entries and the fan-out is not
 * on any hot loop.</li>
 * <li><b>The per-listener catch</b> is what stops one broken listener from
 * stranding the caller half-done. By the time a fan-out runs, the state write
 * and the GC award have usually already happened, so an exception escaping here
 * would lose every remaining notification AND the caller's return value with
 * nothing rolled back.</li>
 * <li><b>Catching Exception, not Throwable</b>, so an Error still propagates.</li>
 * </ul>
 *
 * <p>The label is the caller's own warning text, passed through verbatim rather
 * than derived, because it is the only thing in the log line that says WHICH
 * fan-out failed — this class is the logger for all of them. Labels must stay
 * free of SLF4J {@code {}} placeholders: the label is the message pattern, and
 * the exception is bound to the throwable overload, not to a placeholder.
 */
@Slf4j
final class Listeners {
	private Listeners() {
	}

	/**
	 * Hand {@code action} to every listener, in order, surviving throwers.
	 *
	 * <p>{@code Consumer<? super T>} rather than {@code Consumer<T>} so a
	 * handler written against a supertype (or a bare {@code Runnable::run}
	 * style reference) still binds without a cast at the call site.
	 */
	static <T> void fire(Collection<T> listeners, Consumer<? super T> action, String label) {
		for (T listener : new ArrayList<>(listeners)) {
			try {
				action.accept(listener);
			}
			catch (Exception e) {
				log.warn(label, e);
			}
		}
	}

	/**
	 * The same contract for a single OPTIONAL hook — the {@code @Setter} fields
	 * the plugin wires and the tests deliberately leave null.
	 *
	 * <p>Named differently rather than overloaded: a {@code List<T>} argument
	 * satisfies BOTH signatures (T binds to the list itself), so an overload
	 * here makes every collection call site ambiguous and the compiler refuses
	 * the whole package.
	 *
	 * <p>Separate from the collection overload rather than wrapping the hook in
	 * a singleton list: that would allocate on every call, and these fire on the
	 * kill and contract paths. The null check belongs here because every one of
	 * the five call sites had to remember it, and a forgotten one is an NPE on
	 * the hottest path in the plugin rather than a quiet no-op.
	 */
	static <T> void fireHook(T hook, Consumer<? super T> action, String label) {
		if (hook == null)
			return;
		try {
			action.accept(hook);
		}
		catch (Exception e) {
			log.warn(label, e);
		}
	}
}

package com.gachaman.service;

import com.gachaman.model.*;
import java.util.*;
import javax.annotation.*;
import javax.inject.*;
import lombok.*;
import lombok.extern.slf4j.*;

/**
 * The Service Record: every card counts the kills it was present for, and the
 * number is permanent.
 *
 * <p>"Present for" = the owned card's uuid was assigned to a loadout slot at
 * the moment the kill was credited. Consequences, all deliberate:
 *
 * <ul>
 * <li>It counts EVERY kill {@link KillTracker} emits — off-task and tainted
 * kills included. The record measures how much fighting the card was carried
 * through, not how well the player obeyed a contract. This is why the tally
 * listens to KillTracker directly and never sits behind TaskService's off-task
 * early return.</li>
 * <li>It counts REAL kills, not contract credit. A Compactor doubles
 * killsDone but buys no extra service; an ironman's assisted half-credit still
 * bought the card a whole kill of wear.</li>
 * <li>It counts each assigned card ONCE per kill, distinct by uuid. A hologram
 * occupies exactly one slot today, but the set-based credit makes that
 * assumption non-load-bearing.</li>
 * <li>The loadout is read at EMIT time, not death time. Kills are emitted a few
 * ticks late (the loot oracle settles first) and there is no historical loadout
 * record; a deliberate reassignment inside that gap is rare enough to accept.
 * Do not build a loadout-snapshot ring buffer to close it.</li>
 * </ul>
 *
 * <p>The album says "present for N kills" — never "killed N" — so the wording
 * matches the rule.
 *
 * <p>Kills bank in a transient map and are written through
 * {@link GachaStateService#mutate} only at contract completion and at the
 * boundaries where the tally would otherwise die with the client. mutate()
 * saves on every call and save() gzips + SHA-256s the whole state
 * synchronously before the disk debounce, so a per-kill write is a genuine
 * hot-path hazard.
 */
@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class ServiceRecordService implements KillTracker.KillListener, TaskService.Listener {
	private final GachaStateService stateService;

	/** owned-card uuid -> kills tallied since the last flush. Never persisted. */
	private final Map<String, Integer> pending = new HashMap<>();

	// --- KillTracker.KillListener ---

	@Override
	public synchronized void onKill(KillTracker.Kill kill) {
		GachaState state = stateService.get();
		if (state != null)
			creditKill(pending, state.getLoadout());
	}

	// --- TaskService.Listener ---

	@Override
	public void onTaskCompleted(TaskService.TaskCompletionSummary summary) {
		flush();
	}


	// --- flush boundaries ---

	/**
	 * Write the banked tally into the persisted records. Runs only at contract
	 * completion and at the exit boundaries (logout, plugin shutdown, client
	 * shutdown), never per kill.
	 */
	public synchronized void flush() {
		if (pending.isEmpty())
			return;
		Map<String, Integer> tally = new HashMap<>(pending);
		// cleared BEFORE the write: a failed write costs a handful of kills, a
		// re-runnable tally would over-count them permanently. For a cosmetic
		// odometer, under-counting is the correct failure direction.
		pending.clear();
		stateService.mutate(s -> {
			List<OwnedCard> updated = applyTally(s.getOwnedCards(), tally);
			return updated == null ? s : s.withOwnedCards(updated);
		});
	}

	/**
	 * Throw the tally away unwritten. RuneScapeProfileChanged fires AFTER the
	 * profile key has moved, so these kills can no longer be attributed to the
	 * account that earned them; writing them would credit another character's
	 * cards. The LOGIN_SCREEN handler already flushed under the right key.
	 */
	public synchronized void drop() {
		pending.clear();
	}

	/** Kills tallied for an owned card but not yet written. */
	public synchronized int pendingFor(String ownedCardUuid) {
		return pending.getOrDefault(ownedCardUuid, 0);
	}

	/**
	 * Debug only (::gachawear), for staging a screenshot of a worn card face
	 * without grinding a thousand kills. Flushes first: a banked tally left
	 * unwritten would land on top of the number afterwards and the card would
	 * quietly drift off the stage the player set.
	 */
	public synchronized void debugSetServed(Set<String> uuids, int killsServed) {
		flush();
		stateService.mutate(s -> {
			List<OwnedCard> updated = setServed(s.getOwnedCards(), uuids, killsServed);
			return updated == null ? s : s.withOwnedCards(updated);
		});
	}

	// --- pure rules ---

	/**
	 * +1 kill of service for every card assigned to a loadout slot, distinct by
	 * uuid: a card that somehow occupied two slots still served one kill.
	 */
	static void creditKill(Map<String, Integer> tally, Map<String, String> loadout) {
		if (loadout == null || loadout.isEmpty())
			return;
		for (String uuid : new HashSet<>(loadout.values())) {
			if (uuid != null)
				tally.merge(uuid, 1, Integer::sum);
		}
	}

	/**
	 * Apply a tally, preserving list order. Returns null when nothing matched so
	 * the caller hands mutate() an unchanged state and skips the encode
	 * entirely. Tallied uuids no longer owned (burned, prestiged away) are
	 * dropped — their service died with them.
	 */
	@Nullable
	static List<OwnedCard> applyTally(List<OwnedCard> cards, Map<String, Integer> tally) {
		if (cards == null || cards.isEmpty() || tally.isEmpty())
			return null;
		List<OwnedCard> out = new ArrayList<>(cards.size());
		boolean changed = false;
		for (OwnedCard card : cards) {
			int add = tally.getOrDefault(card.getUuid(), 0);
			if (add > 0) {
				out.add(card.withKillsServed(card.getKillsServed() + add));
				changed = true;
			}
			else {
				out.add(card);
			}
		}
		return changed ? out : null;
	}

	/**
	 * Overwrite the record on an exact set of copies, preserving list order.
	 * Returns null when nothing changed, on the same contract as
	 * {@link #applyTally}.
	 *
	 * <p>SET, not add, and it is the only thing in the plugin that can make a
	 * service record go DOWN — which is why nothing but the ::gachawear debug
	 * command may call it. The record is documented as permanent and monotonic
	 * and every other path honours that.
	 *
	 * <p>Takes uuids rather than a predicate so the selection is made once,
	 * against the snapshot the player was shown, and cannot silently re-run
	 * against a different list inside mutate().
	 */
	@Nullable
	static List<OwnedCard> setServed(List<OwnedCard> cards, Set<String> uuids,
		int killsServed) {
		if (cards == null || cards.isEmpty() || uuids.isEmpty())
			return null;
		List<OwnedCard> out = new ArrayList<>(cards.size());
		boolean changed = false;
		for (OwnedCard card : cards) {
			if (uuids.contains(card.getUuid()) && card.getKillsServed() != killsServed) {
				out.add(card.withKillsServed(killsServed));
				changed = true;
			}
			else {
				out.add(card);
			}
		}
		return changed ? out : null;
	}

	/**
	 * Card id -> highest service record among the owned copies. The album is a
	 * catalogue of card DEFINITIONS while the record is per copy; the veteran
	 * copy is the one the player means. MAX, not SUM: a summed number would not
	 * match any single card and would inflate a figure the player checks
	 * against their own kill count. Holograms are excluded — they carry cardId
	 * -1 and never enter the grid.
	 */
	public static Map<Integer, Integer> bestByCardId(List<OwnedCard> cards) {
		Map<Integer, Integer> best = new HashMap<>();
		if (cards != null) {
			for (OwnedCard card : cards) {
				if (!card.isHologram())
					best.merge(card.getCardId(), card.getKillsServed(), Math::max);
			}
		}
		return best;
	}
}

package com.gachaman.service;

import com.gachaman.data.*;
import java.util.*;
import java.util.regex.*;
import javax.inject.*;
import lombok.*;
import lombok.extern.slf4j.*;
import net.runelite.api.*;
import net.runelite.api.events.*;
import net.runelite.client.eventbus.*;
import net.runelite.client.util.*;

/**
 * Parses boss kill-count chat lines and queues a themed chest when a
 * configured milestone is crossed and unclaimed.
 */
@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class BossKcService {
	// The counter noun varies by activity ("kill count", "chest count", ...) and is NOT
	// part of the captured name — Barrows' "Your Barrows chest count is: 5" captures
	// "Barrows", so bosses.json chatName must exclude the noun.
	static final Pattern KC_PATTERN =
		Pattern.compile("Your (.+?) (?:kill|chest|harvest|completion) count is:? ([\\d,]+)");

	private final GachaStateService stateService;
	private final BossTable bossTable;
	private final CeremonyBus ceremonyBus;

	@Subscribe
	public void onChatMessage(ChatMessage event) {
		if (event.getType() != ChatMessageType.GAMEMESSAGE && event.getType() != ChatMessageType.SPAM)
			return;
		String message = Text.removeTags(event.getMessage());
		Matcher matcher = KC_PATTERN.matcher(message);
		if (!matcher.find())
			return;
		String chatName = matcher.group(1);
		int kc;
		try {
			kc = Integer.parseInt(matcher.group(2).replace(",", ""));
		}
		catch (NumberFormatException e) {
			return;
		}
		handleKc(chatName, kc);
	}

	void handleKc(String chatName, int kc) {
		if (stateService.get() == null)
			return;
		for (BossTable.Boss boss : bossTable.getBosses()) {
			if (!boss.getChatName().equalsIgnoreCase(chatName))
				continue;
			for (int milestone : boss.getKcMilestones()) {
				if (kc >= milestone)
					awardMilestone(boss, milestone);
			}
			return;
		}
	}

	/**
	 * Claims are keyed by boss NAME. They used to be keyed by set tag, but many
	 * bosses share a tag — all three Dagannoth Kings are "dagannoth" — so Rex
	 * crossing 25 KC silently consumed Prime's and Supreme's milestone chests too.
	 */
	private void awardMilestone(BossTable.Boss boss, int milestone) {
		String claimKey = boss.getBossName() + ":" + milestone;
		String legacyKey = boss.getSetTag() + ":" + milestone;
		var state = stateService.get();
		if (state == null || state.getBossKcClaims().contains(claimKey))
			return;
		if (state.getBossKcClaims().contains(legacyKey)) {
			// A save written before the rekey holds one tag-keyed claim standing in
			// for what may be several bosses. Let this boss absorb it — silently,
			// because that chest was already paid out — so its tag-mates can still
			// earn their own instead of being locked out forever.
			stateService.mutate(s -> {
				Set<String> claims = new HashSet<>(s.getBossKcClaims());
				claims.remove(legacyKey);
				claims.add(claimKey);
				return s.withBossKcClaims(claims);
			});
			return;
		}
		stateService.mutate(s -> {
			Set<String> claims = new HashSet<>(s.getBossKcClaims());
			claims.add(claimKey);
			var queued = new ArrayList<>(s.getQueuedThemedChests());
			queued.add(boss.getSetTag());
			return s.withBossKcClaims(claims).withQueuedThemedChests(queued);
		});
		ceremonyBus.submit(CeremonyBus.Type.FANFARE, new CeremonyBus.Fanfare(
			CeremonyBus.Fanfare.Size.MEDIUM,
			boss.getBossName() + " " + milestone + " KC!",
			"A themed chest has been added to your shop.", null));
		log.debug("Boss KC milestone: {} {}", boss.getBossName(), milestone);
	}
}

package com.gachaman.service;

import com.gachaman.data.*;
import java.util.*;
import javax.inject.*;
import lombok.*;
import net.runelite.api.*;

/**
 * Quest combat exemptions: an NPC required by an IN_PROGRESS quest may be
 * attacked (and fought with any style) regardless of the task/style locks.
 * Kills stay economy-neutral — this service only answers "is this NPC an
 * active quest target?".
 *
 * <p>One source, and it is the game's own: the bundled quest-&gt;monster table
 * cross-checked against {@link Quest#getState}. This used to have a second,
 * best-effort source that reflected into Quest Helper's selected step for bonus
 * coverage. Reflection is not permitted in Plugin Hub plugins, and there is no
 * supported way for one plugin to read another's state, so that source is gone
 * rather than reworked. The table is the contract now: an NPC that should be
 * exempt has to be IN it.
 */
@Singleton
public class QuestExemptionService {
	private final Client client;
	private final QuestMonsterTable questMonsterTable;

	/** Per-tick memo: quest-state scripts are not free. */
	private final Map<String, Boolean> tickMemo = new HashMap<>();
	private int memoTick = -1;

	/**
	 * Manually unlocked NPCs, lowercased. The escape hatch for the case this
	 * whole table cannot avoid: a quest genuinely needs a monster the curated
	 * data does not list, and the player is locked out of their own quest with
	 * no way forward until the table is fixed and shipped.
	 *
	 * <p>Deliberately NOT persisted. It survives a hop, not a client restart —
	 * a bypass that outlives the bug it worked around is a bypass nobody
	 * remembers turning on. Client thread only, like everything else here.
	 */
	private final Set<String> manualUnlocks = new LinkedHashSet<>();

	/** One reason the player may currently attack something off-task. */
	@Getter
	@RequiredArgsConstructor
	public static final class Unlock {
		private final String npcName;
		/** The quest that opened it, or null when it is a manual override. */
		private final String questName;

		public boolean isManual() {
			return questName == null;
		}
	}

	@Inject
	public QuestExemptionService(Client client, QuestMonsterTable questMonsterTable) {
		this.client = client;
		this.questMonsterTable = questMonsterTable;
	}

	/** Client thread only. True when the NPC is a target of an in-progress quest. */
	public boolean isQuestTarget(String npcName) {
		if (npcName == null)
			return false;
		int tick = client.getTickCount();
		if (tick != memoTick) {
			memoTick = tick;
			tickMemo.clear();
		}
		return tickMemo.computeIfAbsent(npcName.toLowerCase(), this::compute);
	}

	// --- manual overrides ---

	/** True when this newly unlocked it; false when it was already unlocked. */
	public boolean unlock(String npcName) {
		tickMemo.clear();
		return manualUnlocks.add(npcName.toLowerCase(Locale.ROOT));
	}

	/** Drops one override, or every one of them when {@code npcName} is null. */
	public int relock(String npcName) {
		tickMemo.clear();
		if (npcName == null) {
			int had = manualUnlocks.size();
			manualUnlocks.clear();
			return had;
		}
		return manualUnlocks.remove(npcName.toLowerCase(Locale.ROOT)) ? 1 : 0;
	}

	/**
	 * Client thread only. Every NPC the player may currently attack regardless
	 * of their contract, and why. Walks the whole table rather than answering
	 * one name, so quest state is resolved once per quest and not once per NPC.
	 */
	public List<Unlock> currentUnlocks() {
		List<Unlock> out = new ArrayList<>();
		for (String name : manualUnlocks) {
			out.add(new Unlock(name, null));
		}
		Map<Quest, Boolean> inProgress = new HashMap<>();
		for (QuestMonsterTable.Gate gate : questMonsterTable.allGates()) {
			try {
				if (!inProgress.computeIfAbsent(gate.getQuest(),
					q -> q.getState(client) == QuestState.IN_PROGRESS)) {
					continue;
				}
				if (gate.hasWindow() && !gate.contains(readVar(gate)))
					continue;
				out.add(new Unlock(gate.getNpcName(), gate.getQuest().getName()));
			}
			catch (Exception e) {
				// one quest's state script misbehaving must not empty the list
			}
		}
		return out;
	}

	private int readVar(QuestMonsterTable.Gate gate) {
		// the same variable the quest itself tracks its progress in, read through
		// the ordinary client API - this is how Quest Helper knows which step you
		// are on, and it needs no privileged access
		return gate.isVarbit()
			? client.getVarbitValue(gate.getVarId())
			: client.getVarpValue(gate.getVarId());
	}

	private boolean compute(String lowerName) {
		if (manualUnlocks.contains(lowerName))
			return true;
		for (QuestMonsterTable.Gate gate : questMonsterTable.gatesFor(lowerName)) {
			try {
				if (gate.getQuest().getState(client) != QuestState.IN_PROGRESS)
					continue;
				if (!gate.hasWindow())
					return true;
				if (gate.contains(readVar(gate)))
					return true;
			}
			catch (Exception e) {
				// a quest-state script hiccup fails CLOSED: the combat block
				// only ever relaxes on positive proof that the quest is running
			}
		}
		return false;
	}
}

package com.gachaman.service;

import com.gachaman.*;
import com.gachaman.data.*;
import com.gachaman.model.*;
import java.time.*;
import java.time.temporal.*;
import java.util.*;
import java.util.stream.*;
import javax.annotation.*;
import javax.inject.*;
import lombok.*;
import net.runelite.client.config.*;

/**
 * Deterministic weekly 3-card direct-buy shop: seed = profile key + ISO week,
 * so the rotation is personal and stable with zero stored state. Slot 3 is
 * biased toward unowned cards from sets the player has started.
 */
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class WeeklyShopService {
	@Value
	public static class ShopSlot {
		int slotIndex;
		CardDefinition card;
		int priceGc;
		boolean purchased;
		boolean owned;
	}

	private final GachaStateService stateService;
	private final CreditSink creditSink;
	private final CardDatabase cardDatabase;
	private final SetTable setTable;
	private final ConfigManager configManager;

	public String currentWeekKey() {
		LocalDate now = LocalDate.now(ZoneOffset.UTC);
		return now.get(IsoFields.WEEK_BASED_YEAR) + "-W" + now.get(IsoFields.WEEK_OF_WEEK_BASED_YEAR);
	}

	/**
	 * Purely seeded rotation: seed = f(profile key, ISO week). Every
	 * recomputation — before or after purchases, across restarts — returns the
	 * exact same 3 cards. No stored state.
	 */
	public List<ShopSlot> currentOffers() {
		GachaState state = stateService.get();
		if (state == null || !cardDatabase.isReady())
			return Collections.emptyList();
		String weekKey = currentWeekKey();
		Set<Integer> ownedIds = state.getOwnedCards().stream()
			.filter(c -> !c.isHologram())
			.map(OwnedCard::getCardId)
			.collect(Collectors.toSet());

		String profile = configManager.getRSProfileKey();
		long seed = splitmix64((profile == null ? 0 : profile.hashCode()) * 31L + weekKey.hashCode());
		Random weekRng = new Random(seed);
		List<CardDefinition> all = new ArrayList<>(cardDatabase.all().values());
		all.sort((a, b) -> Integer.compare(a.getCardId(), b.getCardId())); // determinism

		List<CardDefinition> offers = new ArrayList<>(3);
		Set<Integer> pickedIds = new HashSet<>();
		while (offers.size() < 3 && offers.size() < all.size()) {
			CardDefinition pick = all.get(weekRng.nextInt(all.size()));
			if (pickedIds.add(pick.getCardId()))
				offers.add(pick);
		}

		Set<Integer> purchased = state.getWeeklyShopPurchases()
			.getOrDefault(weekKey, Collections.emptySet());
		List<ShopSlot> slots = new ArrayList<>(3);
		for (int i = 0; i < offers.size(); i++) {
			CardDefinition card = offers.get(i);
			slots.add(new ShopSlot(i, card, Tuning.SHOP_PRICE_GC.get(card.getRarity()),
				purchased.contains(i), ownedIds.contains(card.getCardId())));
		}
		return slots;
	}

	@Nullable
	public OwnedCard purchase(int slotIndex) {
		List<ShopSlot> offers = currentOffers();
		if (slotIndex < 0 || slotIndex >= offers.size())
			return null;
		ShopSlot slot = offers.get(slotIndex);
		if (slot.isPurchased() || !creditSink.spend(slot.getPriceGc()))
			return null;
		String weekKey = currentWeekKey();
		OwnedCard card = new OwnedCard(UUID.randomUUID().toString(), slot.getCard().getCardId(),
			null, Variant.NORMAL, System.currentTimeMillis(), "shop:" + weekKey, 0);
		stateService.mutate(s -> {
			List<OwnedCard> owned = new ArrayList<>(s.getOwnedCards());
			owned.add(card);
			Map<String, Set<Integer>> purchases = new HashMap<>(s.getWeeklyShopPurchases());
			Set<Integer> week = new HashSet<>(purchases.getOrDefault(weekKey, Collections.emptySet()));
			week.add(slotIndex);
			purchases.put(weekKey, week);
			return s.withOwnedCards(owned).withWeeklyShopPurchases(purchases);
		});
		return card;
	}

	static long splitmix64(long seed) {
		long z = seed + 0x9E3779B97F4A7C15L;
		z = (z ^ (z >>> 30)) * 0xBF58476D1CE4E5B9L;
		z = (z ^ (z >>> 27)) * 0x94D049BB133111EBL;
		return z ^ (z >>> 31);
	}
}

package com.gachaman.service;

import com.gachaman.*;
import com.gachaman.data.*;
import com.gachaman.model.*;
import java.time.*;
import java.util.*;
import java.util.stream.*;
import javax.inject.*;
import lombok.*;
import lombok.extern.slf4j.*;

/**
 * The Consignment: a free Gilded chest whose price is your next style roll.
 *
 * <p>The house does not spin the wheel — it names the style, and it names the
 * one your album is worst dressed for. Take the deal and you get the crate and
 * the style the house picked; refuse it and the wheel spins as normal. Either
 * answer costs the roll, because the roll was the price of being asked.
 *
 * <h2>Why the roll is DEFERRED rather than undone</h2>
 *
 * This cannot be a ceremony that runs after {@link StyleService#roll}. Read that
 * class's comment: the roll commits immediately and the roulette is purely
 * cosmetic, so by the time a wheel is on screen the style is already in state.
 * An offer made there would be pricing something the player has already been
 * sold — "your next style roll" would name a roll that already happened, and
 * accepting could only overwrite it, which is a second roll, not a price.
 *
 * <p>So the roll is held back. When the cycle comes due the caller hands the
 * roll to {@link #offerOrRoll}, which arms {@link GachaState#isStyleRollOwed()}
 * and puts the offer to the player instead. The roll is taken on resolution —
 * with the house's style on accept, on the ordinary wheel on decline. This is
 * the {@code firstColoursChestOwed} idiom from StyleService: a flag that says
 * something is OWED, never that something is DONE, so a save written before the
 * field existed deserializes false and false means "nothing owed".
 *
 * <p><b>Losing the flag is safe, and that is by design.</b> {@code advanceCycle}
 * never resets {@code cycleProgress} — only {@code roll()} does — so a deferred
 * roll that gets dropped (crash, kill -9, a profile switch mid-offer) leaves the
 * state cycle-OVERDUE, and the very next {@code advanceCycle} returns true
 * again. The wheel is re-owed automatically. Every failure path in this file
 * leans on that: nothing here has to be transactional with StyleService, because
 * the worst case is one contract's delay, not a lost roll.
 *
 * <h2>What spends the day key</h2>
 *
 * At most one Consignment per UTC day, tracked by
 * {@link GachaState#getConsignmentDayKey()}. The rule is that an offer the
 * player never got to answer must not be charged:
 *
 * <table>
 *   <tr><td>accepted</td><td>SPENT — roll taken now, house's style</td></tr>
 *   <tr><td>declined (Escape)</td><td>SPENT — roll taken now, ordinary wheel</td></tr>
 *   <tr><td>aborted by safe mode (incoming damage)</td><td>UNSPENT, still owed</td></tr>
 *   <tr><td>logged out mid-offer</td><td>UNSPENT, still owed</td></tr>
 * </table>
 *
 * <p>Decline SPENDS deliberately, and unlike {@code DEED_CHOICE} this offer must
 * NOT re-queue on decline. A deed that re-queues costs nothing — the deed is
 * still owed either way. A Consignment that re-queues is re-offerable at will:
 * Escape, finish another contract, get asked again, and the once-per-day gate is
 * worth nothing. Being asked is the thing that is rationed, not being crated.
 *
 * <h2>A note on the shape of this file</h2>
 *
 * <p>It has been through a compression pass against the Plugin Hub's 200k token
 * ceiling, which counts this source with comments and blank lines stripped.
 * Nothing player-visible changed and no behaviour moved: the savings are all
 * one-line guards, {@code var} on locals whose type the initialiser already
 * names, Lombok standing in for hand-written accessors, and single-caller
 * helpers folded into their caller with their javadoc carried along. Where a
 * fold is not obvious the comment at the site says what was folded and why.
 * Comments cost nothing here, so none were shortened to pay for any of it.
 */
@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class ConsignmentService {
	/** The deal as it is put to the player. Immutable; safe to hand to the EDT. */
	@Value
	public static class Offer {
		/** The style the house names — the one the album is worst dressed for. */
		AttackStyle style;
		/** How few weapon cards that style has; the reason it was picked. */
		int ownedWeaponCards;
		/** Always GILDED. Carried rather than assumed so the crate art can read it. */
		Tuning.Chest chestTier;
	}

	/**
	 * Whoever puts the offer on screen. One presenter at a time (the overlay).
	 *
	 * <p><b>The contract, in full, because the presenter lives in another file:</b>
	 * returning true means "I am showing this AND I will eventually call exactly
	 * one of {@link #accept}, {@link #decline} or {@link #abandon}". Returning
	 * false means "I cannot show this right now" — the roll is then taken on the
	 * ordinary wheel immediately and the day key is NOT spent, because an offer
	 * that never reached the player is not an offer.
	 *
	 * <p>The obligation to call {@link #abandon} on teardown sits with the
	 * presenter, not with safe mode. {@code SafeModeService.abortIfModal} only
	 * fires while the overlay reports itself modal, so a ceremony torn down by a
	 * logout, a plugin shutdown or a profile switch never reaches it. A presenter
	 * that drops an offer without calling anything is not a disaster — the owed
	 * flag is still on disk and the login drain settles it — but it does cost the
	 * player a wheel they were mid-way through answering.
	 */
	public interface Presenter {
		/** Return true when the offer was claimed for presentation. */
		boolean present(Offer offer);
	}

	private final GachaStateService stateService;
	private final StyleService styleService;
	private final ChestService chestService;
	private final CardDatabase cardDatabase;
	private final CeremonyBus ceremonyBus;

	/**
	 * Lombok writes {@code setPresenter} rather than this file: same public
	 * signature, same assignment, and the hand-written body was pure budget.
	 */
	@Setter private volatile Presenter presenter;
	/**
	 * The offer currently in front of the player, or null.
	 *
	 * <p>Deliberately NOT persisted, unlike the owed flag. A live offer is a
	 * question being asked, and a question does not survive the client that was
	 * asking it: the state that has to outlive a crash is "a roll is owed", which
	 * the flag carries, and the login drain settles that by rolling rather than by
	 * re-asking. Re-asking on login would be an offer at an arbitrary time, which
	 * is exactly what the once-per-day gate exists to prevent.
	 *
	 * <p>Volatile because the panel may read it off the EDT while the client
	 * thread writes it. Every reader takes one read into a local — Offer is a
	 * deeply immutable value type, so seeing the reference is seeing the whole
	 * thing.
	 */
	private volatile Offer live;
	/**
	 * Guards the claim of {@link #live} and NOTHING else — never a state mutation
	 * and never a presenter call.
	 *
	 * <p>Reading the offer and clearing it is a check-then-act, and both halves
	 * have to be one step or a double-click deals two crates. Making the whole
	 * resolution synchronized would have done it too, but that would hold this
	 * monitor across {@code stateService.mutate}, which notifies every state
	 * listener from inside its own monitor — the exact nested-monitor-across-
	 * threads shape CeremonyBus.submit documents avoiding. A lock this small
	 * cannot participate in a cycle.
	 *
	 * <p>{@link #pendingOffer()} deliberately reads {@link #live} WITHOUT taking
	 * this lock, and that is not an oversight. A single read has nothing to make
	 * atomic — the volatile is the whole of what it needs — and keeping the
	 * panel's read lock-free is what guarantees the EDT can never end up waiting
	 * on the client thread to finish resolving an offer.
	 */
	private final Object offerLock = new Object();

	/** Take the live offer, if there is one, leaving nothing behind for a second answer. */
	private Offer claim() {
		synchronized (offerLock) { Offer c = live; live = null; return c; }
	}

	// --- Pure rules -----------------------------------------------------------

	/**
	 * The day key, shaped exactly like the weekly shop's week key and derived the
	 * same way: UTC, from the client's own clock, with no server and nothing
	 * stored but the last one used. Comparing two derived strings is what makes
	 * "once a day" work offline, across restarts, and across world hops.
	 *
	 * <p>Lifted verbatim from the removed Charter Office, which is the point: two
	 * daily gates in one plugin that disagreed about when a day turns over would
	 * be a bug nobody could reproduce without waiting for midnight.
	 */
	public static String dayKey(LocalDate date) { return date.getYear() + "-D" + date.getDayOfYear(); }

	/**
	 * The UTC day key for an instant. The UTC pin lives HERE rather than at the
	 * call site so there is exactly one place that can get the zone wrong: a
	 * player's local midnight is not the gate, and two players on the same world
	 * in different timezones roll over together.
	 */
	public static String dayKeyAt(long epochMs) { return dayKey(LocalDate.ofInstant(Instant.ofEpochMilli(epochMs), ZoneOffset.UTC)); }

	/** A Consignment was already put to the player on this day key. */
	public static boolean usedOn(String lastDayKey, String today) { return lastDayKey != null && lastDayKey.equals(today); }

	/**
	 * How many DISTINCT weapon cards in this pool the album holds.
	 *
	 * <p>Distinct by card id, not by copy: a second Rune scimitar card does not
	 * make anybody better dressed, and counting copies would let a run of dupes
	 * quietly move a style out of last place. Holograms are skipped because they
	 * carry card id -1 and a tier key instead — they genuinely do dress a slot,
	 * but they name a whole tier rather than a weapon, and this measure is
	 * "how many weapons has this style been given", not "what can you equip".
	 */
	public static int ownedFrom(Set<Integer> pool, List<OwnedCard> owned) {
		if (pool == null || pool.isEmpty() || owned == null) { return 0; }
		// distinct() over the boxed ids is the HashSet this used to build by hand:
		// same equals/hashCode, same count, and the set no longer needs a name
		return (int) owned.stream().filter(c -> c != null && !c.isHologram() && pool.contains(c.getCardId()))
			.map(OwnedCard::getCardId).distinct().count();
	}

	/**
	 * The worst-dressed style: fewest owned weapon cards, ties broken by
	 * declaration order (MELEE, then RANGED, then MAGIC).
	 *
	 * <p><b>The tie-break is the main path, not a corner case.</b> The pools come
	 * from {@code weaponCardIdsForStyle}, which returns COMMON weapons only, so a
	 * young album sits at 0/0/0 and every early Consignment is decided by the
	 * break alone. That makes "first declared wins" a rule the player can learn
	 * and predict, which a coin flip could never be — and a seeded flip would be
	 * worse still, since the seed would have to be persisted to survive the
	 * offer being re-computed for the panel.
	 *
	 * <p>Nothing excludes the style the player is already locked into. The wheel
	 * has always been allowed to land on the same style twice in a row, and the
	 * house naming a style it happens to already be is the same kind of luck.
	 */
	public static AttackStyle worstDressed(Map<AttackStyle, Set<Integer>> pools, List<OwnedCard> owned) {
		AttackStyle worst = null;
		int fewest = Integer.MAX_VALUE;
		for (AttackStyle style : AttackStyle.values()) {
			int count = ownedFrom(pools == null ? null : pools.get(style), owned);
			// strictly-less-than is what makes the tie-break declaration order:
			// a later style has to actually beat the incumbent to displace it
			if (count < fewest) { fewest = count; worst = style; }
		}
		return worst;
	}

	// --- Live state -----------------------------------------------------------

	public String currentDayKey() { return dayKeyAt(System.currentTimeMillis()); }

	/** The Consignment has already been put to this player today. */
	public boolean offeredToday() {
		var state = stateService.get();
		return state != null && usedOn(state.getConsignmentDayKey(), currentDayKey());
	}

	/** The offer currently in front of the player, or null. */
	public Offer pendingOffer() { return live; }

	// --- The offer ------------------------------------------------------------

	/**
	 * A style roll has come due. Either put the Consignment to the player —
	 * deferring the roll until they answer — or take the roll right now.
	 *
	 * <p>This is the ONLY entry point for a due roll, and it always leaves a roll
	 * either taken or owed. Callers replace a bare {@code styleService.roll(tick)}
	 * with this and read nothing back but the boolean.
	 *
	 * <p><b>Not the debug command.</b> {@code ::gachastyle} must keep calling
	 * {@link StyleService#roll} directly. Routing it through here for consistency
	 * would let a developer spend a real player's once-per-day Consignment from a
	 * chat box, and would make the offer appear at an arbitrary time, which is the
	 * one thing the design forbids.
	 *
	 * @return true when the roll was DEFERRED and an offer is now live.
	 */
	public boolean offerOrRoll(int tick) {
		var state = stateService.get();
		// not loaded: there is no cycle to advance and nothing to roll
		if (state == null) { return false; }
		if (!canOffer(state)) { rollNow(tick); return false; }
		// One scan of the card database for all three styles, reused for both the
		// pick and the count it is justified by. weaponCardIdsForStyle walks every
		// card and reads item stats live, so asking it a fourth time to re-count
		// the style it just named would double the cost of the whole offer.
		//
		// This scan was a private weaponPools() helper with one caller, which is
		// pure budget, so it was folded in here and brought its javadoc with it:
		// CLIENT THREAD ONLY, inherited from weaponCardIdsForStyle — it reads item
		// stats live rather than off the card. The only caller is the offer, which
		// is raised from the contract-completion path, already on that thread.
		Map<AttackStyle, Set<Integer>> pools = new EnumMap<>(AttackStyle.class);
		for (AttackStyle style : AttackStyle.values()) { pools.put(style, cardDatabase.weaponCardIdsForStyle(style)); }
		// one read of the album, shared by the pick and the count that justifies it
		var owned = state.getOwnedCards();
		var named = worstDressed(pools, owned);
		var offer = new Offer(named, ownedFrom(pools.get(named), owned), Tuning.Chest.GILDED);

		// Armed BEFORE the offer goes on screen, never after. The flag is the only
		// record that a roll is outstanding, and the window it closes is the whole
		// point of the feature: a client that dies with the offer up must find the
		// roll still owed, not silently swallowed. Ordering it the other way would
		// make the crash cost a wheel instead of a question.
		stateService.mutate(s -> s.withStyleRollOwed(true));
		synchronized (offerLock) { live = offer; }

		// the presenter's true/false is read straight out of the call rather than
		// through a `claimed` flag; a throw lands in the catch and falls through to
		// the unclaimed path exactly as the flag's initial false used to
		var p = presenter;
		if (p != null) {
			try { if (p.present(offer)) { return true; } }
			catch (Exception e) { log.warn("Consignment presenter failed", e); }
		}
		// A presenter is allowed to resolve inline (a headless one does exactly
		// that) and then report false because it never put pixels up. It has
		// already taken the roll, so taking another here would hand out a free
		// re-roll — claiming the offer back is what tells the two cases apart:
		// getting nothing means somebody already answered.
		if (claim() == null) { return false; }
		// Nobody could show it, so nobody was asked: the day key stays unspent and
		// the wheel spins as it would have without this feature at all.
		rollNow(tick);
		return false;
	}

	/**
	 * Every way the offer can be off the table. Each term is a way the deal would
	 * be dishonest rather than merely unavailable:
	 *
	 * <ul>
	 * <li>no style yet — the first-ever roll. An account with no album cannot be
	 *     "worst dressed" for anything, and the free First Colours chest already
	 *     rides that roll; a second free crate on top of it would make the opening
	 *     minute the richest in the game. {@code allowedStyle == null} is the same
	 *     {@code firstEver} discriminator StyleService uses.</li>
	 * <li>a roll is already owed — an offer is live, or one was dropped and the
	 *     login drain has not run yet. Either way, one question at a time.</li>
	 * <li>the day key is spent — at most one per UTC day.</li>
	 * <li>the card database is not ready — worst-dressed cannot be computed from
	 *     an empty pool, and the crate could not be rolled either.</li>
	 * <li>a chest reveal is in flight, in memory or serialized by a client that
	 *     died mid-ceremony — the Gilded crate could not be dealt on accept, and
	 *     offering something undeliverable is worse than not offering.</li>
	 * </ul>
	 */
	private boolean canOffer(GachaState state) {
		return state.getAllowedStyle() != null && !state.isStyleRollOwed()
			&& !usedOn(state.getConsignmentDayKey(), currentDayKey())
			&& cardDatabase.isReady() && chestService.getPending() == null
			&& state.getPendingChestBlob() == null;
	}

	// --- Resolution -----------------------------------------------------------

	/**
	 * The half of {@link #accept} and {@link #decline} that is the same on both
	 * sides of the deal: refuse the answer if there is nothing owed, and spend the
	 * day key in ONE write. False means there was nothing to answer.
	 *
	 * <p>The offer is claimed by the CALLER and handed in already claimed, which
	 * keeps the original order: the claim happens before the state read, so a
	 * claim that then fails the owed test still drops the offer and a second click
	 * arriving behind it finds nothing rather than re-running the answer. It also
	 * lets accept read the price off the offer's own tier rather than assuming
	 * GILDED — the tier is carried on the Offer precisely so nothing assumes it.
	 *
	 * <p>{@code price} is the funding accept needs and decline does not; decline
	 * passes zero, and {@code withGc} on an unchanged value returns the same
	 * instance, so the decline write is byte-for-byte the two-field write it was
	 * before this method existed.
	 *
	 * <p>The write order is the crash contract, and it is deliberately the same
	 * side of the trade {@code openFirstColoursChest} picked. That method's
	 * javadoc says two writes leave a window that either re-gifts the chest or
	 * eats it, and it folded them into one to never re-gift. This path cannot
	 * fold — the crate's blob is written inside ChestService's own mutate, which
	 * is not ours to join — so it takes the same side by ordering: the day key is
	 * spent FIRST, and a crash in the window costs a crate rather than handing out
	 * a second free Gilded.
	 *
	 * <p>The owed flag clears in that same first write, before the roll is taken.
	 * A crash there leaves the state cycle-overdue with nothing owed, and the next
	 * completed contract re-fires the roll — one contract late, never lost. Clearing
	 * it after the roll would be the worse order: a crash between the two would
	 * leave a roll owed that had already happened, and the login drain would roll
	 * a second time.
	 */
	private boolean settle(Offer offer, long price) {
		var state = stateService.get();
		if (offer == null || state == null || !state.isStyleRollOwed()) { return false; }
		final String today = currentDayKey();
		stateService.mutate(s -> s.withConsignmentDayKey(today).withStyleRollOwed(false).withGc(s.getGc() + price));
		return true;
	}

	/**
	 * The player takes the deal: the house's style, and the Gilded crate free.
	 *
	 * <p>The crate is funded in the same write that spends the key (see
	 * {@link #settle}), then bought back out of the purse by the ordinary purchase
	 * path below. The round trip is exactly GC-neutral and it is what keeps the
	 * crate honest: pity, the lifetime tier counts and the pending-blob crash
	 * contract all come free, where a second kind of "free chest" inside
	 * ChestService would have to re-implement every one of them. lifetimeGcEarned
	 * is untouched on purpose — this is not income, it is the price of a thing
	 * being handed straight back.
	 *
	 * <p>The price is read off the claimed offer's own tier before the settle,
	 * which is a pure constant-map lookup with no side effect: moving it ahead of
	 * the owed test changes nothing but saves carrying the offer back out again.
	 */
	public boolean accept(int tick) {
		var offer = claim();
		final long price = offer == null ? 0 : Tuning.CHEST_PRICE_GC.get(offer.getChestTier());
		if (!settle(offer, price)) { return false; }

		// Roll first, crate second, so the two ceremonies queue in the order the
		// player reads them: the house names the style, then the box arrives.
		styleService.roll(tick, offer.getStyle());
		if (chestService.openChest(offer.getChestTier()) == null) {
			// Undeliverable after all (the reveal or the database moved under us).
			// The funding stays in the purse: nothing is being invented as a
			// consolation prize, we are simply declining to claw back GC the player
			// can now see, for a crate we failed to hand over.
			//
			// Submitted straight to the bus rather than through a fanfare() helper:
			// there was exactly one call, so the helper cost more than it saved.
			ceremonyBus.submit(CeremonyBus.Type.FANFARE, new CeremonyBus.Fanfare(CeremonyBus.Fanfare.Size.MEDIUM,
				"The consignment could not be crated", "Its price is in your purse instead: " + price + " GC.", null));
		}
		// The free crate, the named style and the spent day key all land in one
		// moment, and it is a moment the player would be furious to replay.
		stateService.checkpoint();
		log.debug("Consignment accepted: {} named, {} crate", offer.getStyle(), offer.getChestTier());
		return true;
	}

	/**
	 * The player refuses (Escape). The wheel spins as normal — and the day key is
	 * spent anyway, because being asked was the thing that was rationed. See the
	 * class comment for why this must not re-queue the way a deed choice does.
	 */
	public boolean decline(int tick) {
		if (!settle(claim(), 0)) { return false; }
		styleService.roll(tick);
		// A resolution, exactly like accept: the key is spent and the wheel has
		// turned. A player who declines and crashes must not be asked again today.
		stateService.checkpoint();
		return true;
	}

	/**
	 * The offer went away without an answer — safe mode aborted it on incoming
	 * damage, or the client is being torn down.
	 *
	 * <p>Mutates nothing at all, and that is the whole feature: the day key stays
	 * unspent because the player never answered, and the owed flag stays armed
	 * because the roll has not been taken. A pure read, so no checkpoint — there
	 * is nothing new on disk to flush.
	 */
	public void abandon() {
		if (claim() == null) { return; }
		log.debug("Consignment abandoned unanswered; day key unspent, roll still owed");
	}

	/**
	 * Login drain: settle a roll left owed by a client that died mid-offer.
	 *
	 * <p>Without this the wheel would sit owed until the player's NEXT contract
	 * completed, which on a bad night is hours of playing a style the game already
	 * decided to change. The cycle self-heals — see the class comment — but it
	 * heals slowly, and the player cannot see why.
	 *
	 * <p>It takes the ordinary wheel and never re-offers. The Consignment is only
	 * ever put up in the moment a roll comes due; a login is an arbitrary time,
	 * and an offer at an arbitrary time is what the once-per-day gate exists to
	 * stop. The day key is untouched, so a player who crashed mid-offer can still
	 * be asked properly the next time the cycle turns over today.
	 */
	public void drainOwedRoll(int tick) {
		var state = stateService.get();
		if (state == null || !state.isStyleRollOwed()) { return; }
		claim();
		rollNow(tick);
		stateService.checkpoint();
		log.debug("Drained a style roll left owed by an unanswered Consignment");
	}

	/**
	 * Take the roll on the ordinary wheel, making sure nothing is left owed.
	 *
	 * <p>The flag clears BEFORE the roll for the same reason accept clears it
	 * early: a crash between the two must leave the state cycle-overdue with
	 * nothing owed (one contract's delay) rather than owed-and-already-rolled (a
	 * free second wheel from the next login drain).
	 */
	private void rollNow(int tick) {
		var state = stateService.get();
		if (state != null && state.isStyleRollOwed()) { stateService.mutate(s -> s.withStyleRollOwed(false)); }
		styleService.roll(tick);
	}
}

package com.gachaman.service;

import com.gachaman.*;
import com.gachaman.model.*;
import java.util.*;
import javax.annotation.*;

/**
 * The Patron's Mark: a private, cosmetic tally of how many shared party
 * contracts each partner has finished alongside you.
 *
 * STRICTLY COSMETIC, deliberately. It pays no GC, feeds no CreditSink
 * modifier, multiplies nothing and gates nothing. A patron count that is
 * worth something makes farming a friend the correct play, and the mark stops
 * meaning what it says. Do not add an economic hook here.
 *
 * Keyed by ACCOUNT KEY — {@link AccountKey}, the hashed account hash the party
 * layer broadcasts — with the display name demoted to a label inside the
 * {@link PatronRecord}. Two identifiers were rejected first and it is worth
 * saying why. A party memberId is drawn from a fresh Random when PartyService
 * is constructed and drawn AGAIN inside changeParty(), so an id-keyed count
 * would reset on every login and the higher tiers would be unreachable by
 * construction. A display name survives a login but not a rename: a partner
 * who changes theirs forks into two rows, each with half a history, and
 * neither one is right. The account key survives both.
 *
 * The key is SELF-REPORTED and unauthenticated — it arrives over the party
 * relay from another player's client, exactly like the name it replaces. A
 * hostile client can claim any key it likes and inflate a count in a ledger
 * only its owner will ever see. That is the whole reason this stays cosmetic.
 *
 * Every rule lives here as a pure static so all of it is testable — the
 * service-side caller is reduced to reading a roster and calling these.
 */
public final class PatronMark {
	/**
	 * OSRS display names are at most 12 characters. Anything longer did not
	 * come from a real name — the string arrives over the party relay from
	 * another player's client, so it is not trusted.
	 */
	private static final int MAX_NAME = 12;

	/** One longer than Tuning.PATRON_TIERS: index 0 is "counted, no tier yet". */
	private static final String[] TIER_LABELS =
		{"Patron", "Patron I", "Patron II", "Patron III"};

	/**
	 * Display order, and the SINGLE definition of it: most contracts first,
	 * then name, then key. Used by both {@link #ranked} and {@link #topKey} so
	 * the Patrons page's first row and the party page's top-patron mark can
	 * never disagree about who the mark belongs to.
	 *
	 * The key is the final tiebreak precisely because it is always present and
	 * always canonical. Without it two nameless one-contract partners would tie
	 * completely, and Gson hands the map back in JSON order, so the ordering
	 * would differ between a fresh ledger and a reloaded one and the page would
	 * reshuffle on its own.
	 */
	private static final Comparator<Map.Entry<String, PatronRecord>> DISPLAY_ORDER =
		Comparator.<Map.Entry<String, PatronRecord>>comparingInt(e -> -e.getValue().getCount())
			.thenComparing(e -> nameOf(e.getValue()), PatronMark::nameOrder)
			.thenComparing(Map.Entry::getKey);

	private PatronMark() {
		return;
	}

	/**
	 * A partner name fit to persist and to draw, or null when there is nothing
	 * drawable.
	 *
	 * RuneLite already ran toJagexName and removeTags over anything that
	 * reached PartyMember.setDisplayName, so this only has to trim and refuse
	 * the placeholders. "&lt;unknown&gt;" is PartyMember's CONSTRUCTOR DEFAULT and
	 * is what every member reads as while the built-in Party plugin is off —
	 * storing it would put a placeholder on the Patrons page as though it were
	 * somebody's name, and the angle brackets would additionally be eaten by
	 * the sidebar's HTML renderer.
	 *
	 * Unlike the old name-keyed ledger, a null here is no longer fatal: the
	 * account key still identifies the partner, so the contract is credited
	 * either way and only the label is missing.
	 */
	@Nullable
	public static String normalizeName(String raw) {
		if (raw == null)
			return null;
		// U+00A0. Jagex names use it as the word separator, and it reads as a
		// normal space but would key separately — written as a code point
		// because a literal one in source is invisible and one editor pass
		// or encoding round-trip would silently eat it
		String name = raw.replace((char) 0xA0, ' ').trim();
		if (name.isEmpty() || name.length() > MAX_NAME
			|| name.indexOf('<') >= 0 || name.indexOf('>') >= 0) {
			return null;
		}
		return name;
	}

	/** The partner's record, or null when they are not in the ledger. */
	@Nullable
	public static PatronRecord recordFor(Map<String, PatronRecord> ledger,
		String accountKey) {
		String key = AccountKey.normalize(accountKey);
		if (ledger == null || ledger.isEmpty() || key == null)
			return null;
		PatronRecord record = ledger.get(key);
		return record == null || record.getCount() <= 0 ? null : record;
	}

	/** Shared contracts finished with one partner; 0 for anyone uncounted. */
	public static int countFor(Map<String, PatronRecord> ledger,
		String accountKey) {
		PatronRecord record = recordFor(ledger, accountKey);
		return record == null ? 0 : record.getCount();
	}

	/**
	 * Every counted partner in display order — what the Patrons page draws.
	 *
	 * Junk is dropped rather than rendered: a record with no count is not a
	 * partner, and a key that is not a key came from a hand-edited save.
	 */
	public static List<PatronRecord> ranked(Map<String, PatronRecord> ledger) {
		List<Map.Entry<String, PatronRecord>> entries = sortedEntries(ledger);
		List<PatronRecord> out = new ArrayList<>(entries.size());
		for (Map.Entry<String, PatronRecord> entry : entries) {
			out.add(entry.getValue());
		}
		return Collections.unmodifiableList(out);
	}

	/**
	 * The account key of the partner who has finished the most contracts with
	 * you, or null when nobody has. Always {@link #ranked}'s first entry.
	 */
	@Nullable
	public static String topKey(Map<String, PatronRecord> ledger) {
		List<Map.Entry<String, PatronRecord>> entries = sortedEntries(ledger);
		return entries.isEmpty() ? null : entries.get(0).getKey();
	}

	/** Distinct counted partners — the Patrons page's headline, and its gate. */
	public static int partnerCount(Map<String, PatronRecord> ledger) {
		return sortedEntries(ledger).size();
	}

	/** Shared contracts across every partner. Not a contract count: a shared
	 * contract with three partners is three marks and reads as three here. */
	public static int totalMarks(Map<String, PatronRecord> ledger) {
		int total = 0;
		for (Map.Entry<String, PatronRecord> entry : sortedEntries(ledger)) {
			total += entry.getValue().getCount();
		}
		return total;
	}

	/**
	 * One mark per distinct partner on a finished contract.
	 *
	 * {@code partners} maps account key to the partner's display name at the
	 * moment of completion; a null or unusable name still credits the mark and
	 * simply leaves the previous label alone. Passing a Map is what makes the
	 * "one mark per partner" rule structural rather than a dedupe pass — the
	 * same account sitting in the party from two clients under two member ids
	 * collapses to one entry before this is ever called.
	 *
	 * Returns the CALLER'S OWN instance when nothing is creditable, so
	 * GachaStateService.mutate short-circuits on {@code next == state} and the
	 * completion skips the gzip + SHA-256 encode of the whole save entirely.
	 * Never writes into the map it was handed: the state object it came from
	 * is shared and immutable by contract.
	 */
	public static Map<String, PatronRecord> credit(Map<String, PatronRecord> current,
		Map<String, String> partners, int cap, long nowMs) {
		if (partners == null || partners.isEmpty())
			return current;
		Map<String, PatronRecord> next = current == null
			? new LinkedHashMap<>() : new LinkedHashMap<>(current);
		// two raw keys can normalize to ONE partner (they differ only in case),
		// and the loop below would then credit that partner twice off a single
		// contract. The caller normalizes before it builds the map, so this only
		// backstops a future one — but "one mark per partner" is the rule the
		// whole feature rests on, and a rule that holds by convention is not one
		Set<String> credited = new HashSet<>();
		boolean changed = false;
		for (Map.Entry<String, String> partner : partners.entrySet()) {
			String key = AccountKey.normalize(partner.getKey());
			if (key == null || !credited.add(key)) {
				continue; // not an identity, or an identity already counted
			}
			String name = normalizeName(partner.getValue());
			PatronRecord existing = next.get(key);
			if (existing != null && existing.getCount() > 0) {
				// keep the last name we could read rather than blanking a drawn
				// row because this one completion happened while they were
				// logged out of the roster
				next.put(key, new PatronRecord(name != null ? name : existing.getName(),
					existing.getCount() + 1, nowMs));
				changed = true;
				continue;
			}
			if (cap > 0 && next.size() >= cap && !evictOneOff(next)) {
				// at the cap with nobody to displace: drop the newcomer rather
				// than a partner you actually have a history with
				continue;
			}
			next.put(key, new PatronRecord(name, 1, nowMs));
			changed = true;
		}
		// a full-cap contract where every partner was turned away changed
		// nothing, and handing back an equal-but-distinct map here would defeat
		// the identity short-circuit and buy a whole-save encode for no edit
		return changed ? next : current;
	}

	/** 0 = below the first threshold, up to Tuning.PATRON_TIERS.length. */
	public static int tierFor(int count) {
		int tier = 0;
		for (int threshold : Tuning.PATRON_TIERS) {
			if (count >= threshold)
				tier++;
		}
		return tier;
	}

	/** True only on the completion that pushes a partner up a tier. */
	public static boolean crossedTier(int before, int after) {
		return tierFor(after) > tierFor(before);
	}

	/** Clamped, so adding a fourth threshold to PATRON_TIERS cannot throw. */
	public static String tierLabel(int count) {
		return TIER_LABELS[Math.min(tierFor(count), TIER_LABELS.length - 1)];
	}

	/** What to draw for a partner whose client never told us their name. */
	public static String displayName(PatronRecord record) {
		String name = record == null ? null : normalizeName(record.getName());
		return name == null ? "An unnamed patron" : name;
	}

	/** Package-private for the test that pins the labels to the thresholds. */
	static int labelCount() {
		return TIER_LABELS.length;
	}

	// --- internals ---

	/** Counted, key-valid entries in {@link #DISPLAY_ORDER}. */
	private static List<Map.Entry<String, PatronRecord>> sortedEntries(
		Map<String, PatronRecord> ledger) {
		if (ledger == null || ledger.isEmpty())
			return Collections.emptyList();
		List<Map.Entry<String, PatronRecord>> entries = new ArrayList<>(ledger.size());
		for (Map.Entry<String, PatronRecord> entry : ledger.entrySet()) {
			// a null VALUE is reachable: Gson deserializes {"abc…":null} happily
			if (entry.getValue() == null || entry.getValue().getCount() <= 0)
				continue;
			// CANONICAL, not merely normalizable. recordFor looks the partner up
			// with the normalized key, so a stored "…AA" would be listed here and
			// found by nothing — the Patrons page would name a top patron the
			// party page could not draw a pip for. credit() only ever writes
			// canonical keys, so a non-canonical one came from a hand-edited save
			// and the honest reading of it is "not one of ours"
			if (!entry.getKey().equals(AccountKey.normalize(entry.getKey())))
				continue;
			entries.add(entry);
		}
		entries.sort(DISPLAY_ORDER);
		return entries;
	}

	/**
	 * Drop the least valuable partner, but ONLY when that partner has a single
	 * contract, so the bound cannot be weaponised: a stranger can never push
	 * out a history of two or more. Among one-offs the one you shared with
	 * longest ago goes first, and the key breaks any remaining tie so eviction
	 * is deterministic across a reload.
	 */
	private static boolean evictOneOff(Map<String, PatronRecord> ledger) {
		String victim = null;
		int lowest = Integer.MAX_VALUE;
		long oldest = Long.MAX_VALUE;
		for (Map.Entry<String, PatronRecord> entry : ledger.entrySet()) {
			PatronRecord record = entry.getValue();
			// a junk row is the ideal victim: it occupies a slot and draws nothing
			int count = record == null ? 0 : record.getCount();
			long at = record == null ? 0 : record.getLastSharedAt();
			if (count < lowest
				|| (count == lowest && at < oldest)
				|| (count == lowest && at == oldest && keyOrder(entry.getKey(), victim) < 0)) {
				lowest = count;
				oldest = at;
				victim = entry.getKey();
			}
		}
		if (victim == null || lowest > 1)
			return false;
		ledger.remove(victim);
		return true;
	}

	/** Nulls last, then case-insensitive, then case-sensitive, so no two tie. */
	private static int nameOrder(String a, String b) {
		if (a == null || b == null)
			return a == b ? 0 : (a == null ? 1 : -1);
		int cmp = a.compareToIgnoreCase(b);
		return cmp != 0 ? cmp : a.compareTo(b);
	}

	private static int keyOrder(String a, String b) {
		return b == null ? -1 : a.compareTo(b);
	}

	@Nullable
	private static String nameOf(PatronRecord record) {
		return normalizeName(record.getName());
	}
}

package com.gachaman.service;

import com.gachaman.*;
import com.gachaman.model.*;
import javax.inject.*;
import lombok.*;
import lombok.extern.slf4j.*;
import net.runelite.api.*;
import net.runelite.api.events.*;
import net.runelite.client.eventbus.*;

/** Awards one in-reveal reroll token per full +10 combat levels gained. */
@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class MilestoneService {
	private final Client client;
	private final GachaStateService stateService;
	private final CeremonyBus ceremonyBus;

	@Subscribe
	public void onStatChanged(StatChanged event) {
		GachaState state = stateService.get();
		if (state == null)
			return;
		int cb = combatLevel();
		int last = state.getLastTokenCombatLevel();
		if (cb >= last + Tuning.TOKEN_CB_INTERVAL) {
			int tokens = (cb - last) / Tuning.TOKEN_CB_INTERVAL;
			int newLast = last + tokens * Tuning.TOKEN_CB_INTERVAL;
			stateService.mutate(s -> s
				.withRerollTokens(s.getRerollTokens() + tokens)
				.withLastTokenCombatLevel(newLast));
			ceremonyBus.submit(CeremonyBus.Type.FANFARE, new CeremonyBus.Fanfare(
				CeremonyBus.Fanfare.Size.MEDIUM, "Combat level " + cb + "!",
				"+" + tokens + " card reroll token" + (tokens > 1 ? "s" : ""), null));
		}
	}

	public int combatLevel() {
		return Experience.getCombatLevel(
			client.getRealSkillLevel(Skill.ATTACK),
			client.getRealSkillLevel(Skill.STRENGTH),
			client.getRealSkillLevel(Skill.DEFENCE),
			client.getRealSkillLevel(Skill.HITPOINTS),
			client.getRealSkillLevel(Skill.MAGIC),
			client.getRealSkillLevel(Skill.RANGED),
			client.getRealSkillLevel(Skill.PRAYER));
	}
}

package com.gachaman.service;

import java.util.Deque;
import com.gachaman.data.*;
import com.gachaman.model.*;
import com.google.gson.*;
import com.google.gson.reflect.*;
import java.util.*;
import javax.annotation.*;
import javax.inject.*;
import lombok.*;
import lombok.extern.slf4j.*;
import net.runelite.api.*;
import net.runelite.api.events.*;
import net.runelite.api.gameval.*;
import net.runelite.client.eventbus.*;

/**
 * Judges the attack style of every offensive action, IMMEDIATELY at the
 * attack's own tick (kill tainting depends on the verdict existing before the
 * death event is processed — deferred judgement provably breaks it).
 *
 * Four signals, strongest first:
 *
 * 1. Spell-cast ANIMATIONS are unambiguous: a cast animation is magic no
 *    matter what the stance varps say. Utility animations (alch, teleport,
 *    eat, block) are equally unambiguously NOT attacks and are never judged.
 * 2. The "Cast <spell> -> <target>" menu click marks the upcoming attack on
 *    THAT target as magic — covering casts whose animation the client missed.
 *    The mark is bound to the clicked target, survives long pathing walks,
 *    and dies when the player clicks something else instead.
 * 3. The weapon-stance varps (COMBAT_WEAPON_CATEGORY + COM_MODE + autocast)
 *    judge everything else instantly on the attack animation.
 * 4. XP drops are ground truth for the style actually used — and the ONLY
 *    signal that can also RETRACT: a Magic XP drop arriving a few ticks after
 *    a stance-sourced melee/ranged verdict (spell XP is delayed by distance;
 *    melee XP is same-tick) proves the verdict wrong and pardons it.
 *    (Defence and Hitpoints are never used: Defence is shared by melee
 *    defensive, ranged longrange AND defensive casting.)
 *
 * Unresolvable styles are never judged — an API hiccup must never fine a
 * compliant player.
 */
@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class StyleTracker {
	private static final int LOGIN_SETTLE_TICKS = 5;
	/** Weapon categories whose WEAPON_STYLES enum entry is -1 (client special cases). */
	private static final int CAT_BLUE_MOON_SPEAR = 22;
	private static final int CAT_PARTISAN = 30;
	/**
	 * Absolute lifetime of a Cast-click mark. Target-binding makes a long cap
	 * safe: the old 6-tick TTL expired mid-path on long walks to the target,
	 * letting the eventual cast be judged from a melee stance instead.
	 */
	private static final int CAST_MARK_CAP_TICKS = 25;
	/** Fallback TTL for a mark whose target could not be resolved at click time. */
	private static final int CAST_MARK_UNBOUND_TTL_TICKS = 6;
	/** XP fallback only fires when no judgement happened this recently. */
	private static final int XP_FALLBACK_QUIET_TICKS = 2;
	/**
	 * How far back a Magic XP drop may retract a stance verdict. Spell XP
	 * lands 2-5 ticks after the cast (1 + (1+distance)/3 hit delay, +1
	 * processing); melee XP is same-tick, which is what makes the
	 * contradiction provable.
	 */
	private static final int PARDON_WINDOW_TICKS = 5;
	/**
	 * How long a weapon sample is kept.
	 *
	 * <p>Sized against the KILL path, not the pardon window, because that is who
	 * reads it: KillTracker holds every kill back for the loot oracle and emits it
	 * up to PENDING_TIMEOUT_TICKS (30) after the death. A sample has to outlive
	 * that whole window or the award would find nothing and quietly pay no bonus
	 * for a kill that genuinely earned one — and "quietly" is the problem, since a
	 * missing bonus looks exactly like a bonus the player never qualified for.
	 */
	private static final int WEAPON_SAMPLE_TTL_TICKS = 40;
	/**
	 * Hard cap, the same belt-and-braces {@link #MAX_RECENT_VERDICTS} is. At most
	 * one judgement lands per tick (the anim path refuses a second, and the XP
	 * fallback waits out XP_FALLBACK_QUIET_TICKS), so the TTL above already bounds
	 * this to TTL + 1 and the cap can only bite if that invariant ever breaks.
	 */
	private static final int MAX_WEAPON_SAMPLES = WEAPON_SAMPLE_TTL_TICKS + 1;

	/** What evidence produced a judgement. Pardons only ever touch STANCE. */
	enum JudgementSource {
		MARK, ANIM, STANCE, XP
	}

	/**
	 * What was in the player's hands at one judged attack, stamped with the tick
	 * it was read on.
	 *
	 * <p>The stamp is the whole value of this. A kill reaches the award code
	 * several ticks after the killing blow, so a varbit read there reports what is
	 * equipped NOW — and a player who swapped the preferred weapon in during the
	 * loot-oracle window would collect a bonus the fight never earned. Sampling at
	 * the attack and carrying the tick with it lets the award insist the sample
	 * belongs to the kill it is paying for.
	 *
	 * <p>comMode rides along because the taxonomy's one pseudo-type — casting from
	 * the autocast slot — is not a weapon category at all; see
	 * {@link WeaponTypeService#SPELL_CAST_KEY}. Read at the same instant as the
	 * category so the pair can never describe two different moments.
	 *
	 * <p>One known imprecision, accepted rather than papered over: the category
	 * varbit updates a tick BEHIND an equip (the same lag that makes the first
	 * cast after swapping to a staff read as melee, which is what the pardon
	 * machinery above exists to absorb), so a sample taken on the very tick of a
	 * swap can name the weapon just put away. It is one attack wide, it can only
	 * ever hand out a bonus rather than withhold one, and closing it would mean
	 * deferring the sample — which is exactly the late read this whole mechanism
	 * exists to avoid.
	 */
	@Value
	public static class WeaponSample {
		int tick;
		int category;
		int comMode;
	}

	/**
	 * How StyleTracker classifies an animation, loaded from attack-anims.json.
	 *
	 * <p>The ids are authored as {@link net.runelite.api.gameval.AnimationID}
	 * constants by com.gachaman.tools.AttackAnims, so the compiler still checks
	 * every name against the live API, and AttackAnimResourceTest pins the
	 * shipped resource to those lists. Data in a resource, names checked in
	 * code, and a test between them.
	 *
	 * <p>offensiveMagic: unambiguous spell casts — judge MAGIC whatever the
	 * stance says. neverJudge: provably not attacks (utility, consumables,
	 * blocks); these also do NOT consume a pending Cast mark. magicUtility: the
	 * neverJudge subset that pays Magic XP, whose drop must never grant a
	 * pardon.
	 */
	private Map<String, Set<Integer>> animGroups;

	/**
	 * Loaded on first judgement rather than at class-init: the Gson is
	 * injected, so it does not exist until Guice has built this service.
	 */
	private Set<Integer> anims(String group) {
		if (animGroups == null) {
			animGroups = DataJson.load(gson, "attack-anims",
				new TypeToken<Map<String, Set<Integer>>>() {
				}.getType(), Collections.emptyMap());
		}
		return animGroups.getOrDefault(group, Collections.emptySet());
	}

	public interface AttackListener {
		/** One offensive action, judged at its own tick. */
		void onAttack(AttackStyle style, int tick);

		/**
		 * A stance-sourced verdict at judgedTick was retracted: the delayed
		 * Magic XP drop proved the attack was actually a spell cast.
		 */
		default void onAttackPardoned(int judgedTick) {
		}
	}

	private final Client client;
	private final Gson gson;
	private final List<AttackListener> listeners = new ArrayList<>();

	private int tick;
	private int settleUntilTick;
	/**
	 * Tick of the most recent judgement, for the two places that only need
	 * "was anything judged just now": the one-verdict-per-tick guard and the
	 * XP fallback's quiet period. Pardons read {@link #recentVerdicts} instead.
	 */
	private int lastJudgedTick = -1;

	/** One judged attack, kept until it falls out of the pardon window. */
	@RequiredArgsConstructor
	static final class Verdict {
		final int tick;
		final AttackStyle style;
		final JudgementSource source;
		boolean pardoned;
	}

	/**
	 * Recent verdicts, oldest first.
	 *
	 * <p>This was a single slot, and a single slot cannot survive its own pardon
	 * window. Spell XP lands 2-5 ticks after the cast, and across a gap that wide
	 * the player has attacked again — every attack overwrote the slot. So the
	 * verdict the Magic XP was coming to retract had already been replaced, and the
	 * pardon either found a MAGIC verdict and declined (source is not STANCE) or
	 * retracted a later, innocent stance verdict in its place.
	 *
	 * <p>The first case is the "cast a spell and still get a tainted kill" report:
	 * COMBAT_WEAPON_CATEGORY updates a tick behind the equip, so the first cast
	 * after swapping to a staff is judged MELEE from the weapon just put away, and
	 * the Magic XP that would have cleared it arrives to find the SECOND cast — a
	 * clean ANIM MAGIC verdict — sitting in the slot. Nothing is pardoned, the
	 * melee verdict stands, and the kill is tainted by a spell.
	 *
	 * <p>Bounded twice: pruned past PARDON_WINDOW_TICKS on every push, and
	 * hard-capped, so a long fight cannot grow it.
	 */
	private final Deque<Verdict> recentVerdicts = new ArrayDeque<>();
	private static final int MAX_RECENT_VERDICTS = 8;
	/**
	 * Weapon samples, oldest first — a deque for exactly the reason
	 * {@link #recentVerdicts} is one, and it is worth spelling out because a
	 * single slot looks sufficient here and is not.
	 *
	 * <p>The reader is the kill award, which arrives 2-30 ticks after the death.
	 * By then the player has almost always started on the next monster, and every
	 * one of those attacks would have overwritten a single slot with a tick past
	 * the end of the finished kill's window. The bonus would then fail to pay on
	 * the ordinary case — fighting continuously — and pay only when the player
	 * stopped attacking after the kill, which is backwards.
	 */
	private final Deque<WeaponSample> weaponSamples = new ArrayDeque<>();
	/** Cast-click mark: when it was set and the actor it was aimed at. */
	private int castMarkTick = -1;
	private Actor castMarkTarget;
	/**
	 * Tick the local player last took a hitsplat. Incoming hits play a BLOCK
	 * animation on the player — indistinguishable from an attack by animation
	 * alone — which must never be judged (it both fined casters under fire
	 * and consumed the Cast-click magic mark before the real cast animated).
	 */
	private int lastDamagedTick = -1;
	/** Tick a Magic-XP-granting utility animation (alch etc.) last played. */
	private int lastUtilityMagicTick = -100;
	/** Tick of the last Attack/Strength/Ranged XP gain (confirms melee/ranged verdicts). */
	private int lastMeleeRangedXpTick = -1;

	// XP baselines so only GAINS count (login floods are settled separately)
	private long lastAttackXp = -1;
	private long lastStrengthXp = -1;
	private long lastRangedXp = -1;
	private long lastMagicXp = -1;

	public void addListener(AttackListener listener) {
		if (!listeners.contains(listener))
			listeners.add(listener);
	}

	public void removeListener(AttackListener listener) {
		listeners.remove(listener);
	}

	public int currentTick() {
		return tick;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event) {
		if (event.getGameState() == GameState.LOGGED_IN) {
			settleUntilTick = tick + LOGIN_SETTLE_TICKS;
			lastAttackXp = -1;
			lastStrengthXp = -1;
			lastRangedXp = -1;
			lastMagicXp = -1;
			clearCastMark();
			// a verdict from before the hop belongs to a fight that is over; the
			// login XP flood must not be able to pardon it
			recentVerdicts.clear();
			// same reasoning, and it keeps the invariant local rather than resting
			// on "the tick counter never resets, so old samples fall out of every
			// future window anyway" — true today, and a trap for whoever changes it
			weaponSamples.clear();
		}
	}

	@Subscribe
	public void onGameTick(GameTick event) {
		tick++;
	}

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied event) {
		if (event.getActor() == client.getLocalPlayer())
			lastDamagedTick = tick;
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event) {
		MenuAction action = event.getMenuAction();
		if ((action == MenuAction.WIDGET_TARGET_ON_NPC || action == MenuAction.WIDGET_TARGET_ON_PLAYER)
			&& event.getMenuOption() != null && event.getMenuOption().startsWith("Cast")) {
			// a manual spell cast was just clicked — the upcoming attack on
			// THIS target is magic (a newer Cast click simply re-marks)
			castMarkTick = tick;
			castMarkTarget = event.getMenuEntry() == null ? null : event.getMenuEntry().getActor();
			return;
		}
		if (castMarkTick >= 0 && supersedesCast(action)) {
			// the player changed their mind — walked away, attacked something
			// the normal way, picked something up — the pending cast is dead
			clearCastMark();
		}
	}

	/** Clicks that abandon a pending manual cast (widget clicks — eat, spellbook — do not). */
	private static boolean supersedesCast(MenuAction action) {
		if (action == null)
			return false;
		if (action == MenuAction.WALK)
			return true;
		String name = action.name();
		return name.startsWith("NPC_") || name.startsWith("PLAYER_") || name.startsWith("GROUND_ITEM_");
	}

	private boolean castMarkActiveOn(Actor interacting) {
		if (castMarkTick < 0 || tick - castMarkTick > CAST_MARK_CAP_TICKS)
			return false;
		if (castMarkTarget == null) {
			// target unresolvable at click time — fall back to the old short
			// TTL against whatever we are now interacting with
			return interacting != null && tick - castMarkTick <= CAST_MARK_UNBOUND_TTL_TICKS;
		}
		return castMarkTarget == interacting;
	}

	private void clearCastMark() {
		castMarkTick = -1;
		castMarkTarget = null;
	}

	/**
	 * Signals 1-3: the attack animation, judged instantly. Unambiguous cast
	 * animations beat everything; the target-bound Cast mark beats the stance
	 * varps. Judging here — not at end of tick — is what lets a final blow
	 * taint its own kill.
	 */
	@Subscribe
	public void onAnimationChanged(AnimationChanged event) {
		if (event.getActor() != client.getLocalPlayer() || tick < settleUntilTick || tick == lastJudgedTick)
			return;
		int animation = client.getLocalPlayer().getAnimation();
		Actor interacting = client.getLocalPlayer().getInteracting();
		if (animation == -1 || interacting == null)
			return;
		if (anims("neverJudge").contains(animation)) {
			// utility cast / consumable / block pose — not an attack, and the
			// pending Cast mark (if any) survives untouched
			if (anims("magicUtility").contains(animation))
				lastUtilityMagicTick = tick;
			return;
		}
		boolean markMatch = castMarkActiveOn(interacting);
		if (anims("offensiveMagic").contains(animation)) {
			// unambiguous spell cast: magic no matter the stance, and provably
			// not a block animation — so it is judged even inside the damage
			// window below
			logVerdict(animation, AttackStyle.MAGIC, JudgementSource.ANIM, markMatch);
			clearCastMark();
			judge(AttackStyle.MAGIC, JudgementSource.ANIM);
			return;
		}
		if (tick - lastDamagedTick <= 1) {
			// almost certainly the BLOCK animation from the hit we just took —
			// never judge it (the XP path still catches a real wrong-style
			// attack that lands damage on the same tick)
			return;
		}
		if (markMatch) {
			logVerdict(animation, AttackStyle.MAGIC, JudgementSource.MARK, true);
			clearCastMark();
			judge(AttackStyle.MAGIC, JudgementSource.MARK);
			return;
		}
		AttackStyle style = predictStyle();
		if (style != null) {
			logVerdict(animation, style, JudgementSource.STANCE, false);
			judge(style, JudgementSource.STANCE);
		}
	}

	/**
	 * Signal 4: XP is ground truth for the style actually used. It fires as a
	 * fallback judgement only when nothing was judged in the last
	 * {@link #XP_FALLBACK_QUIET_TICKS} ticks (so it can never double-judge an
	 * attack the animation path already handled) — but a Magic XP drop also
	 * checks whether it CONTRADICTS a recent stance verdict and pardons it.
	 */
	@Subscribe
	public void onStatChanged(StatChanged event) {
		AttackStyle xpStyle;
		long previous;
		long current = event.getXp();
		switch (event.getSkill()) {
			case ATTACK:
				previous = lastAttackXp;
				lastAttackXp = current;
				xpStyle = AttackStyle.MELEE;
				break;
			case STRENGTH:
				previous = lastStrengthXp;
				lastStrengthXp = current;
				xpStyle = AttackStyle.MELEE;
				break;
			case RANGED:
				previous = lastRangedXp;
				lastRangedXp = current;
				xpStyle = AttackStyle.RANGED;
				break;
			case MAGIC:
				previous = lastMagicXp;
				lastMagicXp = current;
				xpStyle = AttackStyle.MAGIC;
				break;
			default:
				return; // Defence/HP are shared across styles — never evidence
		}
		if (previous < 0 || current <= previous || tick < settleUntilTick) {
			return; // baseline settle or no gain
		}
		if (xpStyle == AttackStyle.MAGIC)
			maybePardonStanceVerdict();
		else {
			lastMeleeRangedXpTick = tick;
		}
		if (lastJudgedTick >= 0 && tick - lastJudgedTick <= XP_FALLBACK_QUIET_TICKS) {
			return; // the animation path already judged this attack
		}
		log.debug("style verdict: tick={} skill={} verdict={} source=XP", tick, event.getSkill(), xpStyle);
		judge(xpStyle, JudgementSource.XP);
	}

	/**
	 * A Magic XP gain just landed: if the last verdict was a stance-sourced
	 * melee/ranged within the pardon window, unconfirmed by any melee/ranged
	 * XP, and not explained by a utility cast, that verdict was wrong — the
	 * "attack" was a manual cast judged from a stale melee stance. Retract it.
	 */
	private void maybePardonStanceVerdict() {
		Verdict verdict = pardonTarget(recentVerdicts, tick, lastMeleeRangedXpTick,
			lastUtilityMagicTick);
		if (verdict == null)
			return;
		verdict.pardoned = true;
		log.debug("style pardon: retracting {} verdict from tick {} (magic xp at tick {})",
			verdict.style, verdict.tick, tick);
		Listeners.fire(listeners, l -> l.onAttackPardoned(verdict.tick), "attack listener failed");
	}

	/**
	 * Which of the recent verdicts a Magic XP drop retracts, or null for none.
	 *
	 * <p>Oldest candidate first, {@code recent} being in judgement order. Magic XP
	 * is the DELAYED signal, so among the verdicts still inside the window the
	 * earliest is the one the cast produced; taking them in order also means two
	 * casts in quick succession pardon two verdicts in the order they were judged
	 * rather than both reaching for the newest. One XP drop retracts at most one.
	 *
	 * <p>Pure and static for the same reason {@link #shouldPardon} is: the tracker
	 * around it needs a live Client, so choosing ACROSS verdicts could not otherwise
	 * be tested — and choosing across verdicts is the whole of the fix.
	 */
	@Nullable
	static Verdict pardonTarget(Iterable<Verdict> recent, int tick, int lastMeleeRangedXpTick,
		int lastUtilityMagicTick) {
		for (Verdict verdict : recent) {
			if (shouldPardon(verdict.source, verdict.style, verdict.pardoned, verdict.tick,
				tick, lastMeleeRangedXpTick, lastUtilityMagicTick)) {
				return verdict;
			}
		}
		return null;
	}

	/**
	 * Pure pardon decision (unit-testable). Only STANCE verdicts are ever
	 * pardonable: MARK/ANIM verdicts are already magic and XP verdicts are
	 * ground truth. Melee/ranged XP at or after the verdict confirms it as
	 * genuine (melee XP is same-tick — an auto-retaliate staff bash that lands
	 * is a REAL melee attack and stays convicted), and Magic XP right after a
	 * utility cast proves nothing about combat.
	 */
	static boolean shouldPardon(JudgementSource source, AttackStyle style, boolean alreadyPardoned,
		int judgedTick, int tick, int lastMeleeRangedXpTick, int lastUtilityMagicTick) {
		return source == JudgementSource.STANCE
			&& (style == AttackStyle.MELEE || style == AttackStyle.RANGED)
			&& !alreadyPardoned
			&& judgedTick >= 0
			&& tick - judgedTick <= PARDON_WINDOW_TICKS
			&& lastMeleeRangedXpTick < judgedTick
			&& tick - lastUtilityMagicTick > 1;
	}

	private void judge(AttackStyle style, JudgementSource source) {
		lastJudgedTick = tick;
		sampleWeapon();
		// prune first, so the cap can only ever discard verdicts that are still
		// young enough to matter — and at one judgement per tick over a 5-tick
		// window it never reaches the cap in the first place
		while (!recentVerdicts.isEmpty()
			&& tick - recentVerdicts.peekFirst().tick > PARDON_WINDOW_TICKS) {
			recentVerdicts.pollFirst();
		}
		recentVerdicts.addLast(new Verdict(tick, style, source));
		while (recentVerdicts.size() > MAX_RECENT_VERDICTS) {
			recentVerdicts.pollFirst();
		}
		fire(style, tick);
	}

	private void fire(AttackStyle style, int judgedTick) {
		Listeners.fire(listeners, l -> l.onAttack(style, judgedTick), "attack listener failed");
	}

	/**
	 * Record what the attack judged this tick was made with.
	 *
	 * <p>Called from {@link #judge} and deliberately NOT from
	 * {@link #predictStyle}: the ANIM and MARK branches of
	 * {@link #onAnimationChanged} both judge and return before predictStyle is
	 * ever reached, so a spell-cast kill — the one whose entire verdict comes from
	 * the animation — would never sample its own weapon and could never earn the
	 * preference it was fought with.
	 *
	 * <p>On the XP-fallback path the judged tick is the tick the XP LANDED, which
	 * for a spell is a few ticks after the cast. That is still the right evidence
	 * to keep — it is what the player was holding while that attack resolved, and
	 * it is the only reading available for an attack the animation path never saw.
	 *
	 * <p>A read that throws records NOTHING rather than a placeholder, and both
	 * reads have to succeed before anything is pushed (the arguments are evaluated
	 * before the call). That is the same direction every other unresolvable case
	 * in this file takes: an unsampled attack simply pays no weapon bonus, and the
	 * bonus is only ever additive to the player's fortunes, so failing to pay it
	 * is a non-event where paying it for a weapon nobody can prove was in hand
	 * would make the preference meaningless.
	 */
	private void sampleWeapon() {
		try {
			recordWeapon(tick, client.getVarbitValue(VarbitID.COMBAT_WEAPON_CATEGORY),
				client.getVarpValue(VarPlayerID.COM_MODE));
		}
		catch (Exception ignored) {
			// no client, or the varbit is unreadable — this attack goes unsampled
		}
	}

	/**
	 * Push one sample, pruning by age first and capping second — the same order
	 * {@link #judge} prunes its verdicts in, and for the same reason: the cap can
	 * then only ever discard entries that are already too old to matter.
	 *
	 * <p>Package-private, and separated from the client read above, so the
	 * retention rule that kills actually depend on can be exercised without a live
	 * Client — exactly why {@link #resolve} and {@link #shouldPardon} are pure
	 * statics.
	 */
	void recordWeapon(int atTick, int category, int comMode) {
		while (!weaponSamples.isEmpty()
			&& atTick - weaponSamples.peekFirst().getTick() > WEAPON_SAMPLE_TTL_TICKS) {
			weaponSamples.pollFirst();
		}
		weaponSamples.addLast(new WeaponSample(atTick, category, comMode));
		while (weaponSamples.size() > MAX_WEAPON_SAMPLES) {
			weaponSamples.pollFirst();
		}
	}

	/**
	 * What was in hand at the last judged attack inside [fromTick, toTick], or
	 * null when no attack this tracker judged falls in that window.
	 *
	 * <p>Callers pass a kill's own [engagementStartTick, deathTick]. The NEWEST
	 * match is returned because that is the killing blow — a player who swings
	 * their preferred weapon for the last hit has genuinely landed the kill with
	 * it, while one who swaps it in after the death lands outside the window and
	 * gets nothing.
	 *
	 * <p>Null for a kill with no judged attack inside its own engagement — a
	 * thrall's kill, damage dealt off-screen, a monster something else finished —
	 * rather than the category from whatever fight came before it. That is what
	 * makes the rule airtight instead of merely usually right.
	 */
	@Nullable
	public WeaponSample weaponAt(int fromTick, int toTick) {
		WeaponSample best = null;
		for (WeaponSample sample : weaponSamples) {
			if (sample.getTick() >= fromTick && sample.getTick() <= toTick) {
				best = sample; // pushed oldest-first, so the last match is the newest
			}
		}
		return best;
	}

	private void logVerdict(int animation, AttackStyle verdict, JudgementSource source, boolean markMatch) {
		if (!log.isDebugEnabled())
			return;
		int category = -1;
		int comMode = -1;
		try {
			category = client.getVarbitValue(VarbitID.COMBAT_WEAPON_CATEGORY);
			comMode = client.getVarpValue(VarPlayerID.COM_MODE);
		}
		catch (Exception ignored) {
		}
		log.debug("style verdict: tick={} anim={} category={} comMode={} verdict={} source={}"
				+ " markTick={} markMatch={} lastDamagedTick={}",
			tick, animation, category, comMode, verdict, source, castMarkTick, markMatch, lastDamagedTick);
	}

	/** The style the next attack would use, or null when unresolvable. */
	@Nullable
	public AttackStyle predictStyle() {
		try {
			int category = client.getVarbitValue(VarbitID.COMBAT_WEAPON_CATEGORY);
			int comMode = client.getVarpValue(VarPlayerID.COM_MODE);
			boolean defensiveAutocast = client.getVarbitValue(VarbitID.AUTOCAST_DEFMODE) == 1;
			return resolve(category, comMode, defensiveAutocast, this::styleNameFor);
		}
		catch (Exception e) {
			return null;
		}
	}

	/** Lookup of the style-name param for (category, styleIndex); null when absent. */
	@Nullable
	private String styleNameFor(int category, int styleIndex) {
		EnumComposition weaponStyles = client.getEnum(EnumID.WEAPON_STYLES);
		int structsEnumId = weaponStyles.getIntValue(category);
		if (structsEnumId == -1)
			return null;
		EnumComposition structs = client.getEnum(structsEnumId);
		int[] structIds = structs.getIntVals();
		if (styleIndex < 0 || styleIndex >= structIds.length)
			return null;
		StructComposition struct = client.getStructComposition(structIds[styleIndex]);
		return struct == null ? null : struct.getStringValue(ParamID.ATTACK_STYLE_NAME);
	}

	interface StyleNameLookup {
		@Nullable
		String get(int category, int styleIndex);
	}

	/**
	 * Pure resolution function (unit-testable). comMode 4 = the autocast SLOT
	 * (an explicitly selected autocast spell). Powered staves (trident,
	 * sanguinesti, warped sceptre...) do NOT use it — they fight from comMode
	 * 0/1/3 — so they are identified by probing style 0: a category whose
	 * first style is "Casting" is all-magic in every mode.
	 */
	@Nullable
	static AttackStyle resolve(int category, int comMode, boolean defensiveAutocast, StyleNameLookup lookup) {
		if (comMode == 4) {
			// the autocast slot; defensiveAutocast irrelevant to style
			return AttackStyle.MAGIC;
		}
		if (category == CAT_BLUE_MOON_SPEAR || category == CAT_PARTISAN) {
			// client special-cases these; their non-autocast styles are melee
			return AttackStyle.MELEE;
		}
		if ("Casting".equals(lookup.get(category, 0))) {
			// powered stave: every combat mode of this category is a cast
			return AttackStyle.MAGIC;
		}
		String name = lookup.get(category, comMode);
		return name == null ? null : mapStyleName(name);
	}

	@Nullable
	static AttackStyle mapStyleName(String name) {
		switch (name) {
			case "Accurate":
			case "Aggressive":
			case "Defensive":
			case "Controlled":
				return AttackStyle.MELEE;
			case "Ranging":
			case "Longrange":
				return AttackStyle.RANGED;
			case "Casting":
			case "Defensive Casting":
				return AttackStyle.MAGIC;
			default:
				return null;
		}
	}
}

package com.gachaman.service;

import com.gachaman.*;
import com.gachaman.data.*;
import java.util.*;
import lombok.*;

/**
 * The roll's own arithmetic, lifted out of ChestService so the odds disclosure can
 * quote the numbers the roll actually uses instead of a parallel transcription that
 * would drift the first time either side is retuned. Pure and static throughout:
 * nothing here reads a Client, a GachaState or the RNG, which is also what makes it
 * the testable half of the feature (ChestService.isReachable dereferences Client).
 */
public final class RollOdds {
	/**
	 * Bucket key for cards the proximity gate never level-checks at all. Deliberately
	 * the empty string rather than null so it can be a map key and compared with
	 * equals() without a null branch at every use site.
	 */
	public static final String UNTIERED = "";

	/** One disclosure row: a tier ladder in one reach band. */
	@Value
	public static class TierBand {
		/** tierKey, or UNTIERED. */
		String tierKey;
		/**
		 * True when the cards behind this row pass isReachable(card, false). A tier can
		 * legitimately appear in BOTH bands: ChestService.ladderWithinReach applies
		 * reqDefence to BODY only, so hardleather chaps can be wieldable while the
		 * hardleather body is not.
		 */
		boolean wieldableNow;
	}

	/**
	 * The row one card falls in. Public so the disclosure can collect the card
	 * names behind each row from the same key {@link #tierShares} counts them
	 * under — two independent derivations of "which row is this?" would be free
	 * to disagree, and the tooltip would then name cards from the wrong band.
	 */
	public static TierBand bandOf(CardDefinition card, boolean wieldableNow) {
		String key = card.getTierKey() == null ? UNTIERED : card.getTierKey();
		return new TierBand(key, wieldableNow);
	}

	private RollOdds() {
	}

	/**
	 * Verbatim lift of the block that used to sit inline in ChestService.rollRarity:
	 * shift the pity bonus into EPIC+LEGENDARY mass, taken from COMMON. Clones on
	 * purpose — the caller passes Tuning.CHEST_ODDS's shared array and must never see
	 * it move.
	 */
	public static double[] adjustOdds(double[] odds, double pityBonusPercent) {
		double[] adjusted = odds.clone();
		if (pityBonusPercent > 0) {
			double shift = Math.min(adjusted[0] - 1, pityBonusPercent);
			adjusted[0] -= shift;
			adjusted[3] += shift * 0.7;
			adjusted[4] += shift * 0.3;
		}
		return adjusted;
	}

	/** Never returns 0: headroom gear stays possible, just rarer. */
	public static double leanWeight(boolean wieldableNow) {
		return wieldableNow ? 1.0 : Tuning.HOUSE_LEAN_HEADROOM_WEIGHT;
	}

	/**
	 * The weighted draw itself: walk the cumulative weights until {@code roll} is
	 * passed. {@code roll} must already be scaled to the weight total, and the total
	 * must have been accumulated from these very values so the two cannot disagree in
	 * the last bit; the final index is returned if it does anyway, so a rounding crumb
	 * costs one skewed pick rather than an exception.
	 *
	 * <p>Static and RNG-free because the alternative — a private walk inside
	 * ChestService — could only be tested through isReachable, which dereferences
	 * Client and is therefore untestable headless.
	 */
	public static int weightedIndex(double roll, double[] weights) {
		double cumulative = 0;
		for (int i = 0; i < weights.length; i++) {
			cumulative += weights[i];
			if (roll < cumulative)
				return i;
		}
		return weights.length - 1;
	}

	/** Weights to probabilities. An empty or all-zero vector returns all zeroes. */
	public static double[] normalize(double[] weights) {
		double total = 0;
		for (double w : weights) {
			total += w;
		}
		double[] out = new double[weights.length];
		if (total <= 0)
			return out;
		for (int i = 0; i < weights.length; i++) {
			out[i] = weights[i] / total;
		}
		return out;
	}

	/**
	 * How one pick from this candidate list distributes over (tier, band) rows.
	 *
	 * <p>{@code leaned} is false for Epic+ and for the unfiltered fallback, which both
	 * draw uniformly, so passing it through keeps the disclosure honest about those
	 * branches instead of quietly reporting a lean that never ran.
	 */
	public static Map<TierBand, Double> tierShares(List<CardDefinition> candidates,
		boolean[] wieldableNow, boolean leaned) {
		Map<TierBand, Double> shares = new LinkedHashMap<>();
		if (candidates.isEmpty())
			return shares;
		double[] weights = new double[candidates.size()];
		double total = 0;
		for (int i = 0; i < candidates.size(); i++) {
			weights[i] = leaned ? leanWeight(wieldableNow[i]) : 1.0;
			total += weights[i];
		}
		if (total <= 0)
			return shares;
		for (int i = 0; i < candidates.size(); i++) {
			shares.merge(bandOf(candidates.get(i), wieldableNow[i]), weights[i] / total,
				Double::sum);
		}
		return shares;
	}
}

package com.gachaman.persist;

import com.gachaman.*;
import com.gachaman.model.*;
import java.io.*;
import java.nio.charset.*;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import javax.inject.*;
import lombok.*;
import lombok.extern.slf4j.*;
import net.runelite.client.*;
import net.runelite.client.config.*;

/**
 * Dual-layer persistence: RSProfile config key (in-memory, batched flush by
 * RuneLite — synchronous and cheap) plus a disk file with one .bak rotation.
 * Disk writes are debounced onto the executor so file I/O never runs on the
 * client thread; checkpoints flush immediately.
 */
@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class StateStore {
	private static final String KEY_STATE = "state";
	private static final File BASE_DIR = new File(RuneLite.RUNELITE_DIR, "gachaman");
	/**
	 * Was 10s. A debounce is still wanted — a kill, a card and a GC award can
	 * all land in the same instant and there is no sense writing three times —
	 * but ten seconds is ten seconds of progress a crash can take with it, and
	 * a lost contract kill count is exactly the kind of loss a player notices
	 * and resents. At one second the coalescing still works and the worst case
	 * is a single event. The write is off-thread and the state is ~6 KB gzipped,
	 * so the cost of the shorter window is not worth measuring.
	 */
	private static final long DISK_FLUSH_DELAY_MS = 1_000;

	private final ConfigManager configManager;
	private final StateCodec codec;
	private final ScheduledExecutorService executor;

	/** blob + profile key captured at save time (profile may switch before the flush runs). */
	private final AtomicReference<String[]> pendingDisk = new AtomicReference<>();
	private volatile boolean flushScheduled;

	/** Regular save: config now, disk debounced. */
	public void save(GachaState state) {
		save(state, false);
	}

	/** Checkpoint save: config now, disk now (still off-thread, but immediate). */
	public void save(GachaState state, boolean flushDiskNow) {
		String blob = codec.encode(state);
		configManager.setRSProfileConfiguration(GachamanConfig.GROUP, KEY_STATE, blob);
		String profile = configManager.getRSProfileKey();
		if (profile == null)
			return;
		pendingDisk.set(new String[]{profile, blob});
		if (flushDiskNow)
			executor.execute(this::flushDisk);
		else if (!flushScheduled) {
			flushScheduled = true;
			executor.schedule(this::flushDisk, DISK_FLUSH_DELAY_MS, TimeUnit.MILLISECONDS);
		}
	}

	private void flushDisk() {
		flushScheduled = false;
		String[] pending = pendingDisk.getAndSet(null);
		if (pending == null)
			return;
		writeDisk(pending[0], pending[1]);
	}

	/** @return loaded state or null when nothing valid exists (fresh profile). */
	/**
	 * Loads the NEWEST surviving copy, not simply the config one.
	 *
	 * <p>Config used to win outright and disk was consulted only when config was
	 * missing or corrupt. That loses data whenever the client dies without a
	 * clean shutdown: the plugin's own disk write is debounced and lands, but
	 * RuneLite never flushes its in-memory config, so the next launch reads a
	 * config blob OLDER than state.dat, decodes it fine, and quietly rolls the
	 * player back — a reassigned loadout or a contract's kill count simply gone.
	 * Comparing the stamps makes the disk copy the safety net it was meant to be.
	 */
	public GachaState load() {
		String blob = configManager.getRSProfileConfiguration(GachamanConfig.GROUP, KEY_STATE);
		String best = blob;
		long bestAt = codec.savedAt(blob);
		for (String name : new String[]{"state.dat", "state.dat.bak"}) {
			File f = diskFile(configManager.getRSProfileKey(), name);
			if (f == null || !f.exists())
				continue;
			try {
				String disk = new String(Files.readAllBytes(f.toPath()), StandardCharsets.UTF_8);
				long diskAt = codec.savedAt(disk);
				// strictly newer only: on a tie config wins, which keeps the old
				// behaviour for saves written before the stamp existed
				if (diskAt > bestAt) {
					best = disk;
					bestAt = diskAt;
					log.info("Gachaman state: {} is newer than config, preferring it", name);
				}
			}
			catch (IOException e) {
				log.warn("Failed reading {}", f, e);
			}
		}
		GachaState state = codec.decode(best);
		if (state != null)
			return state;
		// the newest copy did not survive verification — fall back through the
		// rest, newest first, rather than starting the player from nothing
		for (String candidate : candidatesOldestLast(blob)) {
			state = codec.decode(candidate);
			if (state != null) {
				log.info("Gachaman state recovered from a fallback copy");
				return state;
			}
		}
		return null;
	}

	/** Every surviving blob except the one already tried, newest first. */
	private List<String> candidatesOldestLast(String configBlob) {
		List<String> out = new ArrayList<>();
		out.add(configBlob);
		for (String name : new String[]{"state.dat", "state.dat.bak"}) {
			File f = diskFile(configManager.getRSProfileKey(), name);
			if (f == null || !f.exists())
				continue;
			try {
				out.add(new String(Files.readAllBytes(f.toPath()), StandardCharsets.UTF_8));
			}
			catch (IOException e) {
				log.warn("Failed reading {}", f, e);
			}
		}
		out.sort((a, b) -> Long.compare(codec.savedAt(b), codec.savedAt(a)));
		return out;
	}

	private void writeDisk(String profileKey, String blob) {
		File f = diskFile(profileKey, "state.dat");
		if (f == null)
			return;
		try {
			File dir = f.getParentFile();
			if (!dir.exists() && !dir.mkdirs())
				return;
			Path path = f.toPath();
			if (f.exists()) {
				Files.copy(path, diskFile(profileKey, "state.dat.bak").toPath(),
					StandardCopyOption.REPLACE_EXISTING);
			}
			Path tmp = path.resolveSibling("state.dat.tmp");
			Files.write(tmp, blob.getBytes(StandardCharsets.UTF_8));
			try {
				Files.move(tmp, path, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
			}
			catch (AtomicMoveNotSupportedException e) {
				Files.move(tmp, path, StandardCopyOption.REPLACE_EXISTING);
			}
		}
		catch (IOException e) {
			log.warn("Failed to write Gachaman disk state", e);
		}
	}

	private File diskFile(String profileKey, String name) {
		if (profileKey == null)
			return null;
		return new File(new File(BASE_DIR, profileKey.replaceAll("[^A-Za-z0-9_.-]", "_")), name);
	}
}

package com.gachaman.persist;

import com.gachaman.model.*;
import com.google.gson.*;
import java.io.*;
import java.nio.charset.*;
import java.security.*;
import java.util.*;
import java.util.zip.*;
import javax.inject.*;
import lombok.*;
import lombok.extern.slf4j.*;

/**
 * Serializes GachaState to a versioned, hash-stamped, gzip+base64 envelope
 * suitable for both RSProfile config storage and disk files.
 */
@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class StateCodec {
	private final Gson gson;

	public String encode(GachaState state) {
		String payload = gson.toJson(state);
		JsonObject envelope = new JsonObject();
		envelope.addProperty("version", GachaState.SCHEMA_VERSION);
		envelope.addProperty("sha256", sha256(payload));
		// stamped so a loader can tell two surviving copies apart; see savedAt
		envelope.addProperty("savedAtMs", System.currentTimeMillis());
		envelope.addProperty("payload", payload);
		return base64Gzip(envelope.toString());
	}

	/**
	 * When this blob was written, or 0 if it predates the stamp or cannot be
	 * read. Lets {@code StateStore} pick the NEWER of the config copy and the
	 * disk copy instead of always trusting config — a client that dies without
	 * a clean shutdown leaves config behind whatever the plugin last wrote to
	 * disk, and blindly preferring config silently rolls the player back.
	 *
	 * <p>Deliberately does not verify the hash: this only orders two candidates,
	 * and whichever wins is still decoded (and so still verified) properly.
	 */
	public long savedAt(String blob) {
		if (blob == null || blob.isEmpty())
			return 0;
		try {
			JsonObject envelope = gson.fromJson(gunzipBase64(blob), JsonObject.class);
			return envelope.has("savedAtMs") ? envelope.get("savedAtMs").getAsLong() : 0;
		}
		catch (Exception e) {
			return 0;
		}
	}

	/** @return decoded state, or null if the blob is missing/corrupt/tampered. */
	public GachaState decode(String blob) {
		if (blob == null || blob.isEmpty())
			return null;
		try {
			String json = gunzipBase64(blob);
			JsonObject envelope = gson.fromJson(json, JsonObject.class);
			int version = envelope.get("version").getAsInt();
			if (version > GachaState.SCHEMA_VERSION) {
				log.warn("Gachaman state schema {} is newer than supported {}", version, GachaState.SCHEMA_VERSION);
				return null;
			}
			String payload = envelope.get("payload").getAsString();
			String expected = envelope.get("sha256").getAsString();
			if (!expected.equals(sha256(payload))) {
				log.warn("Gachaman state hash mismatch — refusing to load");
				return null;
			}
			return gson.fromJson(payload, GachaState.class);
		}
		catch (Exception e) {
			log.warn("Failed to decode Gachaman state", e);
			return null;
		}
	}

	static String sha256(String s) {
		try {
			MessageDigest digest = MessageDigest.getInstance("SHA-256");
			byte[] hash = digest.digest(s.getBytes(StandardCharsets.UTF_8));
			StringBuilder sb = new StringBuilder(hash.length * 2);
			for (byte b : hash) {
				sb.append(Character.forDigit((b >> 4) & 0xF, 16)).append(Character.forDigit(b & 0xF, 16));
			}
			return sb.toString();
		}
		catch (NoSuchAlgorithmException e) {
			throw new IllegalStateException(e);
		}
	}

	private static String base64Gzip(String s) {
		try {
			ByteArrayOutputStream bos = new ByteArrayOutputStream();
			try (Writer w = new OutputStreamWriter(new GZIPOutputStream(bos), StandardCharsets.UTF_8)) {
				w.write(s);
			}
			return Base64.getEncoder().encodeToString(bos.toByteArray());
		}
		catch (IOException e) {
			throw new IllegalStateException(e);
		}
	}

	private static String gunzipBase64(String s) throws IOException {
		byte[] compressed = Base64.getDecoder().decode(s);
		try (InputStreamReader r = new InputStreamReader(
			new GZIPInputStream(new ByteArrayInputStream(compressed)), StandardCharsets.UTF_8)) {
			StringBuilder sb = new StringBuilder();
			char[] buf = new char[8192];
			int n;
			while ((n = r.read(buf)) != -1) {
				sb.append(buf, 0, n);
			}
			return sb.toString();
		}
	}
}
